import React from 'react';
import { useParams } from 'react-router-dom';
import { TenantProvider } from '@/contexts/TenantContext';

/**
 * Wrapper que extrai o slug da rota (se disponível) e passa para o TenantProvider.
 * Funciona tanto para caminhos com slug (ex: /:slug/cliente-login)
 * quanto para acessos diretos via domínio próprio (ex: portal.empresa.com/cliente-login).
 */
export default function TenantSlugResolver({ children }) {
    const { slug } = useParams();

    return (
        <TenantProvider slug={slug}>
            {children}
        </TenantProvider>
    );
}

import React, { useState, useEffect, useRef } from "react";
import { base44 } from "@/api/base44Client";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Loader2, Plus, Trash2, Upload, X, FileText, Image, HardHat, Search } from "lucide-react";
import { Checkbox } from "@/components/ui/checkbox";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { toast } from "sonner";
import { AlertCircle } from "lucide-react";
import DevolucaoModal from "../devolucoes/DevolucaoModal";

const TIPOS_ASSISTENCIA = [
    { value: "Devolução", label: "Devolução", color: "bg-red-100 text-red-800" },
    { value: "Troca", label: "Troca", color: "bg-orange-100 text-orange-800" },
    { value: "Peça Faltante", label: "Peça Faltante", color: "bg-yellow-100 text-yellow-800" },
    { value: "Conserto", label: "Conserto", color: "bg-blue-100 text-blue-800" },
    { value: "Visita Técnica", label: "Visita Técnica", color: "bg-purple-100 text-purple-800" },
    { value: "Outros", label: "Outros", color: "bg-gray-100 text-gray-800" }
];

const STATUS_OPTIONS = [
    { value: "Aberta", label: "Aberta", color: "bg-blue-100 text-blue-800" },
    { value: "Em Andamento", label: "Em Andamento", color: "bg-yellow-100 text-yellow-800" },
    { value: "Aguardando Peça", label: "Aguardando Peça", color: "bg-orange-100 text-orange-800" },
    { value: "Aguardando Cliente", label: "Aguardando Cliente", color: "bg-purple-100 text-purple-800" },
    { value: "Concluída", label: "Concluída", color: "bg-green-100 text-green-800" },
    { value: "Cancelada", label: "Cancelada", color: "bg-red-100 text-red-800" }
];

const PRIORIDADE_OPTIONS = [
    { value: "Baixa", label: "Baixa", color: "bg-gray-100 text-gray-600" },
    { value: "Normal", label: "Normal", color: "bg-blue-100 text-blue-700" },
    { value: "Alta", label: "Alta", color: "bg-orange-100 text-orange-700" },
    { value: "Urgente", label: "Urgente", color: "bg-red-100 text-red-700" }
];

function SeletorProdutoTroca({ value, initialLabel, onSelect }) {
    const [searchTerm, setSearchTerm] = useState(initialLabel || "");
    const [results, setResults] = useState([]);
    const [loading, setLoading] = useState(false);
    const [isOpen, setIsOpen] = useState(false);
    const containerRef = useRef(null);

    // Fetch products on search term change
    useEffect(() => {
        if (!searchTerm || value) {
            setResults([]);
            return;
        }

        const delayDebounce = setTimeout(async () => {
            setLoading(true);
            try {
                const { data } = await base44.entities.Produto.search({
                    search: searchTerm,
                    limit: 10
                });
                setResults(data || []);
                setIsOpen(true);
            } catch (err) {
                console.error("Erro ao buscar produtos:", err);
            } finally {
                setLoading(false);
            }
        }, 300);

        return () => clearTimeout(delayDebounce);
    }, [searchTerm, value]);

    // Close results when clicking outside
    useEffect(() => {
        const handleClickOutside = (e) => {
            if (containerRef.current && !containerRef.current.contains(e.target)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const handleClear = () => {
        setSearchTerm("");
        setResults([]);
        onSelect(null);
        setIsOpen(false);
    };

    return (
        <div ref={containerRef} className="relative w-full">
            {value ? (
                <div className="flex items-center justify-between border rounded px-3 py-1.5 bg-gray-50 text-xs">
                    <span className="font-medium truncate flex-1">{searchTerm}</span>
                    <Button
                        type="button"
                        variant="ghost"
                        size="icon"
                        className="h-5 w-5 ml-2 text-red-500 hover:text-red-700 hover:bg-red-50"
                        onClick={handleClear}
                    >
                        <X className="w-3.5 h-3.5" />
                    </Button>
                </div>
            ) : (
                <div className="relative">
                    <Search className="absolute left-2.5 top-1/2 transform -translate-y-1/2 w-3.5 h-3.5 text-gray-400" />
                    <Input
                        placeholder="Digite nome, código ou referência do produto..."
                        value={searchTerm}
                        onChange={(e) => {
                            setSearchTerm(e.target.value);
                            setIsOpen(true);
                        }}
                        className="pl-8 text-xs h-8"
                    />
                    {loading && (
                        <Loader2 className="absolute right-2.5 top-1/2 transform -translate-y-1/2 w-3.5 h-3.5 animate-spin text-gray-400" />
                    )}
                </div>
            )}

            {isOpen && !value && searchTerm && (
                <div className="absolute left-0 right-0 z-50 mt-1 max-h-60 overflow-y-auto bg-white border border-gray-200 rounded-md shadow-lg">
                    {loading && results.length === 0 && (
                        <div className="p-3 text-center text-xs text-gray-500">Buscando...</div>
                    )}
                    {!loading && results.length === 0 && (
                        <div className="p-3 text-center text-xs text-gray-500">Nenhum produto encontrado</div>
                    )}
                    {results.map((p) => (
                        <div
                            key={p.id}
                            className="p-2 hover:bg-gray-100 cursor-pointer flex justify-between items-center text-xs border-b border-gray-50 last:border-b-0"
                            onClick={() => {
                                onSelect(p);
                                setSearchTerm(p.nome);
                                setIsOpen(false);
                            }}
                        >
                            <div className="flex-1 min-w-0 pr-2">
                                <p className="font-semibold text-gray-800 truncate">{p.nome}</p>
                                <p className="text-[10px] text-gray-500 truncate">
                                    Ref: {p.modelo_referencia || 'N/A'} | Categoria: {p.categoria || 'Outra'}
                                </p>
                            </div>
                            <div className="text-right shrink-0">
                                <p className="font-bold text-green-700">
                                    R$ {p.preco_venda?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                                </p>
                                <p className="text-[10px] text-gray-500">
                                    Estoque: {p.quantidade_estoque || 0} un
                                </p>
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}

export default function AssistenciaTecnicaModal({
    isOpen,
    onClose,
    onSave,
    assistencia,
    initialValues,
    vendas = [],
    produtos = [],
    fornecedores = [],
    isLoading,
    devolucoes = [],
    onSaveDevolucao,
    savingDevolucao
}) {
    const getDefaultFormData = () => ({
        venda_id: "",
        numero_pedido: "",
        cliente_nome: "",
        cliente_telefone: "",
        tipo: "Conserto",
        data_abertura: new Date().toISOString().split('T')[0],
        data_resolucao: "",
        descricao_problema: "",
        solucao_aplicada: "",
        itens_envolvidos: [],
        valor_devolvido: 0,
        valor_cobrado: 0,
        status: "Aberta",
        prioridade: "Normal",
        arquivos: [],
        observacoes: "",
        responsabilidade_montador: false,
        montador_usuario_id: null
    });

    const [formData, setFormData] = useState({
        ...getDefaultFormData()
    });

    const [vendaSelecionada, setVendaSelecionada] = useState(null);
    const [entregue, setEntregue] = useState(false);
    const [verificandoEntrega, setVerificandoEntrega] = useState(false);
    const [searchVenda, setSearchVenda] = useState("");
    const [uploadingFile, setUploadingFile] = useState(false);

    useEffect(() => {
        if (assistencia) {
            setFormData({
                ...assistencia,
                itens_envolvidos: (assistencia.itens_envolvidos || []).map(i => ({
                    ...i,
                    produto_sai_id: i.produto_sai_id || i.produto_id,
                    produto_sai_nome: i.produto_sai_nome || i.produto_nome,
                    produto_sai_quantidade: i.produto_sai_quantidade || i.quantidade
                })),
                arquivos: assistencia.arquivos || []
            });
            const venda = vendas.find(v => v.id === assistencia.venda_id);
            setVendaSelecionada(venda);
            setEntregue(true); // Se já existe assistência, assumimos que a entrega foi verificada ou já passou pelo filtro
        } else {
            const prefill = initialValues || {};
            // Se veio do painel de montagem com montador_usuario_id, auto-marcar como responsabilidade do montador
            const autoResponsabilidade = !!prefill.montador_usuario_id;
            setFormData({
                ...getDefaultFormData(),
                ...prefill,
                itens_envolvidos: (prefill.itens_envolvidos || []).map(i => ({
                    ...i,
                    produto_sai_id: i.produto_sai_id || i.produto_id,
                    produto_sai_nome: i.produto_sai_nome || i.produto_nome,
                    produto_sai_quantidade: i.produto_sai_quantidade || i.quantidade
                })),
                arquivos: prefill.arquivos || [],
                responsabilidade_montador: autoResponsabilidade || prefill.responsabilidade_montador || false,
                montador_usuario_id: prefill.montador_usuario_id || null
            });

            if (prefill.venda_id) {
                const venda = vendas.find(v => String(v.id) === String(prefill.venda_id));
                setVendaSelecionada(venda || null);
                setEntregue(true);
            } else {
                setVendaSelecionada(null);
                setEntregue(false);
            }
        }
    }, [assistencia, vendas, isOpen, initialValues]);

    const handleVendaChange = async (vendaId) => {
        const venda = vendas.find(v => v.id === vendaId);
        if (!venda) return;

        setVendaSelecionada(venda);
        setVerificandoEntrega(true);
        setEntregue(false);

        try {
            // Verificar se há entrega concluída no Supabase para esta venda
            const { data: entregas, error } = await base44.supabase
                .from('entregas')
                .select('id')
                .eq('venda_id', vendaId)
                .eq('status', 'Entregue');

            if (error) throw error;

            // Se houver pelo menos uma entrega concluída, permite
            setEntregue(entregas && entregas.length > 0);
        } catch (err) {
            toast.error("Erro ao verificar status de entrega. Permitindo abertura por precaução.");
            setEntregue(true);
        } finally {
            setVerificandoEntrega(false);
        }

        setFormData({
            ...formData,
            venda_id: vendaId,
            numero_pedido: venda.numero_pedido,
            cliente_nome: venda.cliente_nome,
            cliente_telefone: venda.cliente_telefone || "",
            itens_envolvidos: []
        });
    };

    const adicionarItem = (item) => {
        const jaAdicionado = formData.itens_envolvidos.find(i => i.produto_id === item.produto_id);
        if (jaAdicionado) return;

        setFormData({
            ...formData,
            itens_envolvidos: [...formData.itens_envolvidos, {
                produto_id: item.produto_id,
                produto_nome: item.produto_nome,
                quantidade: item.quantidade,
                problema: "",
                produto_sai_id: item.produto_id,
                produto_sai_nome: item.produto_nome,
                produto_sai_quantidade: item.quantidade
            }]
        });
    };

    const removerItem = (index) => {
        setFormData({
            ...formData,
            itens_envolvidos: formData.itens_envolvidos.filter((_, i) => i !== index)
        });
    };

    const handleFileUpload = async (e) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setUploadingFile(true);
        try {
            const result = await base44.integrations.Core.UploadFile({ file });
            setFormData({
                ...formData,
                arquivos: [...formData.arquivos, {
                    nome: file.name,
                    url: result.file_url,
                    tipo: file.type,
                    data: new Date().toISOString()
                }]
            });
        } catch (error) {
            toast.error("Erro ao fazer upload do arquivo. Verifique o tamanho e formato.");
        } finally {
            setUploadingFile(false);
        }
    };

    const removerArquivo = (index) => {
        setFormData({
            ...formData,
            arquivos: formData.arquivos.filter((_, i) => i !== index)
        });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();

        if (!formData.venda_id) {
            alert("Selecione um pedido");
            return;
        }

        if (!formData.descricao_problema.trim()) {
            alert("Descreva o problema");
            return;
        }

        // Sanitize date fields - convert empty strings to null for PostgreSQL
        const sanitizedData = {
            ...formData,
            data_abertura: formData.data_abertura || null,
            data_resolucao: formData.data_resolucao || null
        };

        onSave(sanitizedData);
    };

    const filteredVendas = vendas.filter(v => {
        if (!searchVenda) return true;
        const termo = searchVenda.toLowerCase();
        return (
            v.numero_pedido?.toString().includes(termo) ||
            v.cliente_nome?.toLowerCase().includes(termo)
        );
    });

    return (
        <Dialog open={isOpen} onOpenChange={onClose}>
            <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
                {formData.tipo === 'Devolução' || formData.tipo === 'Troca' ? (
                    <DevolucaoModal
                        noDialog={true}
                        isOpen={isOpen}
                        onClose={onClose}
                        onSave={onSaveDevolucao}
                        devolucao={assistencia && assistencia.itemType === 'devolucao' ? assistencia : { tipo: formData.tipo, status: "Pendente" }}
                        devolucoes={devolucoes}
                        vendas={vendas}
                        produtos={produtos}
                        fornecedores={fornecedores}
                        isLoading={savingDevolucao}
                    />
                ) : (
                    <>
                        <DialogHeader>
                            <DialogTitle style={{ color: '#07593f' }}>
                                {assistencia ? "Editar Assistência Técnica" : "Nova Assistência Técnica"}
                            </DialogTitle>
                        </DialogHeader>

                        <form onSubmit={handleSubmit}>
                    <div className="space-y-6">
                        {/* Seleção do Pedido */}
                        <div className="grid md:grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <Label>Buscar Pedido *</Label>
                                <Input
                                    placeholder="Digite número do pedido ou nome do cliente..."
                                    value={searchVenda}
                                    onChange={e => setSearchVenda(e.target.value)}
                                    disabled={!!assistencia}
                                />
                                {!assistencia && searchVenda && (
                                    <div className="max-h-40 overflow-y-auto border rounded-lg">
                                        {filteredVendas.slice(0, 10).map(venda => (
                                            <div
                                                key={venda.id}
                                                className="p-2 hover:bg-gray-100 cursor-pointer flex justify-between items-center"
                                                onClick={() => {
                                                    handleVendaChange(venda.id);
                                                    setSearchVenda("");
                                                }}
                                            >
                                                <div>
                                                    <span className="font-medium">#{venda.numero_pedido}</span>
                                                    <span className="text-gray-500 ml-2">{venda.cliente_nome}</span>
                                                </div>
                                                <Badge variant="outline">
                                                    R$ {venda.valor_total?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                                                </Badge>
                                            </div>
                                        ))}
                                        {filteredVendas.length === 0 && (
                                            <div className="p-2 text-gray-500 text-center">Nenhum pedido encontrado</div>
                                        )}
                                    </div>
                                )}
                            </div>

                            <div className="space-y-2">
                                <Label>Tipo de Assistência *</Label>
                                <Select
                                    value={formData.tipo}
                                    onValueChange={(value) => {
                                        setFormData({ ...formData, tipo: value });
                                    }}
                                >
                                    <SelectTrigger>
                                        <SelectValue />
                                    </SelectTrigger>
                                    <SelectContent>
                                        {TIPOS_ASSISTENCIA.map(tipo => (
                                            <SelectItem key={tipo.value} value={tipo.value}>
                                                {tipo.label}
                                            </SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                            </div>
                        </div>

                        {/* Info do Pedido Selecionado */}
                        {vendaSelecionada && (
                            <>
                                <Alert className={`border-2 ${entregue ? 'bg-green-50 border-green-200' : 'bg-red-50 border-red-300'}`}>
                                    <AlertDescription>
                                        <div className="flex flex-wrap gap-4 items-center">
                                            <div>
                                                <strong>Pedido:</strong> #{vendaSelecionada.numero_pedido}
                                            </div>
                                            <div>
                                                <strong>Cliente:</strong> {vendaSelecionada.cliente_nome}
                                            </div>
                                            <div>
                                                <strong>Status Entrega:</strong> {verificandoEntrega ? <Loader2 className="w-3 h-3 animate-spin inline ml-1" /> : (entregue ? <Badge className="bg-green-600 ml-1">Entregue</Badge> : <Badge variant="destructive" className="ml-1">Não Entregue</Badge>)}
                                            </div>
                                            {!entregue && !verificandoEntrega && (
                                                <div className="w-full mt-2 text-red-700 font-bold flex items-center gap-2">
                                                    <AlertCircle className="w-4 h-4" />
                                                    Trocas/Defeitos só podem ser registrados após a entrega concluída.
                                                </div>
                                            )}
                                        </div>
                                    </AlertDescription>
                                </Alert>
                            </>
                        )}

                        {/* Status e Prioridade */}
                        <div className="grid md:grid-cols-3 gap-4">
                            <div>
                                <Label>Data de Abertura *</Label>
                                <Input
                                    type="date" lang="pt-BR"
                                    value={formData.data_abertura}
                                    onChange={(e) => setFormData({ ...formData, data_abertura: e.target.value })}
                                    required
                                />
                            </div>
                            <div>
                                <Label>Status</Label>
                                <Select
                                    value={formData.status}
                                    onValueChange={(value) => setFormData({ ...formData, status: value })}
                                >
                                    <SelectTrigger>
                                        <SelectValue />
                                    </SelectTrigger>
                                    <SelectContent>
                                        {STATUS_OPTIONS.map(status => (
                                            <SelectItem key={status.value} value={status.value}>
                                                {status.label}
                                            </SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                            </div>
                            <div>
                                <Label>Prioridade</Label>
                                <Select
                                    value={formData.prioridade}
                                    onValueChange={(value) => setFormData({ ...formData, prioridade: value })}
                                >
                                    <SelectTrigger>
                                        <SelectValue />
                                    </SelectTrigger>
                                    <SelectContent>
                                        {PRIORIDADE_OPTIONS.map(p => (
                                            <SelectItem key={p.value} value={p.value}>
                                                {p.label}
                                            </SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                            </div>
                        </div>

                        {/* Responsabilidade do Montador — exibido apenas no painel admin/portal cliente (não quando auto-set pelo painel de montagem) */}
                        {!assistencia && !initialValues?.montador_usuario_id && (
                            <div className="flex items-start gap-3 p-4 bg-amber-50 border border-amber-200 rounded-lg">
                                <Checkbox
                                    id="responsabilidade_montador"
                                    checked={formData.responsabilidade_montador}
                                    onCheckedChange={(checked) =>
                                        setFormData({ ...formData, responsabilidade_montador: !!checked })
                                    }
                                    className="mt-0.5"
                                />
                                <div className="flex-1">
                                    <label
                                        htmlFor="responsabilidade_montador"
                                        className="flex items-center gap-2 font-medium text-amber-900 cursor-pointer"
                                    >
                                        <HardHat className="w-4 h-4" />
                                        Responsabilidade do Montador?
                                    </label>
                                    <p className="text-xs text-amber-700 mt-0.5">
                                        Marque caso o problema seja decorrente da montagem realizada. A assistência aparecerá no portal do montador responsável.
                                    </p>
                                </div>
                            </div>
                        )}

                        {/* Indicador quando auto-vinculado pelo painel de montagem */}
                        {!assistencia && !!initialValues?.montador_usuario_id && (
                            <div className="flex items-center gap-3 p-3 bg-amber-50 border border-amber-200 rounded-lg">
                                <HardHat className="w-4 h-4 text-amber-700" />
                                <p className="text-sm text-amber-800">
                                    Esta assistência será vinculada ao montador responsável e aparecerá no portal dele.
                                </p>
                            </div>
                        )}

                        {/* Descrição do Problema */}
                        <div>
                            <Label>Descrição do Problema *</Label>
                            <Textarea
                                value={formData.descricao_problema}
                                onChange={(e) => setFormData({ ...formData, descricao_problema: e.target.value })}
                                placeholder="Descreva detalhadamente o problema relatado pelo cliente..."
                                rows={3}
                                required
                            />
                        </div>

                        {/* Solução Aplicada */}
                        <div>
                            <Label>Solução Aplicada</Label>
                            <Textarea
                                value={formData.solucao_aplicada}
                                onChange={(e) => setFormData({ ...formData, solucao_aplicada: e.target.value })}
                                placeholder="Descreva a solução aplicada para resolver o problema..."
                                rows={3}
                            />
                        </div>

                        {/* Itens Envolvidos */}
                        {vendaSelecionada && vendaSelecionada.itens && (
                            <div className="border rounded-lg p-4" style={{ borderColor: '#E5E0D8' }}>
                                <h4 className="font-semibold mb-3" style={{ color: '#07593f' }}>
                                    Itens do Pedido (selecione os envolvidos)
                                </h4>
                                <div className="space-y-2">
                                    {vendaSelecionada.itens.map((item, index) => (
                                        <div key={index} className="flex items-center justify-between p-3 bg-gray-50 rounded">
                                            <div>
                                                <p className="font-medium">{item.produto_nome}</p>
                                                <p className="text-sm text-gray-500">
                                                    Quantidade: {item.quantidade}
                                                </p>
                                            </div>
                                            <Button
                                                type="button"
                                                size="sm"
                                                onClick={() => adicionarItem(item)}
                                                disabled={formData.itens_envolvidos.some(i => i.produto_id === item.produto_id)}
                                                className={formData.itens_envolvidos.some(i => i.produto_id === item.produto_id)
                                                    ? "bg-gray-300"
                                                    : "bg-orange-500 hover:bg-orange-600"}
                                            >
                                                <Plus className="w-4 h-4 mr-1" />
                                                {formData.itens_envolvidos.some(i => i.produto_id === item.produto_id) ? "Adicionado" : "Adicionar"}
                                            </Button>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        {/* Itens Selecionados */}
                        {formData.itens_envolvidos.length > 0 && (
                            <div className="border rounded-lg p-4" style={{ borderColor: '#07593f' }}>
                                <h4 className="font-semibold mb-3" style={{ color: '#07593f' }}>
                                    Itens Selecionados ({formData.itens_envolvidos.length})
                                </h4>
                                <div className="space-y-3">
                                    {formData.itens_envolvidos.map((item, index) => (
                                        <div key={index} className="flex flex-col gap-3 p-3 bg-green-50 rounded border border-green-200">
                                            <div className="flex items-start justify-between gap-3">
                                                <div className="flex-1">
                                                    <p className="font-medium text-green-950">{item.produto_nome}</p>
                                                    <Input
                                                        placeholder="Descreva o problema específico deste item..."
                                                        value={item.problema}
                                                        onChange={(e) => {
                                                            const novosItens = [...formData.itens_envolvidos];
                                                            novosItens[index].problema = e.target.value;
                                                            setFormData({ ...formData, itens_envolvidos: novosItens });
                                                        }}
                                                        className="mt-2"
                                                    />
                                                </div>
                                                <Button
                                                    type="button"
                                                    variant="ghost"
                                                    size="sm"
                                                    onClick={() => removerItem(index)}
                                                    className="text-red-600 hover:text-red-800 hover:bg-red-50 flex-shrink-0"
                                                >
                                                    <Trash2 className="w-4 h-4" />
                                                </Button>
                                            </div>

                                            {/* Se for troca, selecionar o item que sai */}
                                            {formData.tipo === 'Troca' && (
                                                <div className="p-3 bg-white border border-dashed border-green-200 rounded-lg space-y-2">
                                                    <Label className="text-[10px] font-bold text-gray-500 uppercase tracking-wider block">
                                                        Item que Sai (Novo Produto entregue ao Cliente)
                                                    </Label>
                                                    <div className="flex flex-col sm:flex-row gap-2">
                                                        <div className="flex-1">
                                                                                           <SeletorProdutoTroca
                                                                value={item.produto_sai_id}
                                                                initialLabel={item.produto_sai_nome}
                                                                onSelect={(prod) => {
                                                                    const novosItens = [...formData.itens_envolvidos];
                                                                    if (prod) {
                                                                        novosItens[index].produto_sai_id = prod.id;
                                                                        novosItens[index].produto_sai_nome = prod.nome;
                                                                    } else {
                                                                        novosItens[index].produto_sai_id = null;
                                                                        novosItens[index].produto_sai_nome = "";
                                                                    }
                                                                    setFormData({ ...formData, itens_envolvidos: novosItens });
                                                                }}
                                                            />
                                                        </div>
                                                        <div className="w-full sm:w-24">
                                                            <Input
                                                                type="number"
                                                                min="1"
                                                                value={item.produto_sai_quantidade || item.quantidade}
                                                                onChange={(e) => {
                                                                    const novosItens = [...formData.itens_envolvidos];
                                                                    novosItens[index].produto_sai_quantidade = Math.max(1, parseInt(e.target.value) || 1);
                                                                    setFormData({ ...formData, itens_envolvidos: novosItens });
                                                                }}
                                                                placeholder="Qtd"
                                                                className="w-full text-xs"
                                                            />
                                                        </div>
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        {/* Arquivos */}
                        <div className="border rounded-lg p-4" style={{ borderColor: '#E5E0D8' }}>
                            <h4 className="font-semibold mb-3 flex items-center gap-2" style={{ color: '#07593f' }}>
                                <Upload className="w-4 h-4" />
                                Arquivos Anexos
                            </h4>

                            <div className="flex flex-wrap gap-2 mb-3">
                                {formData.arquivos.map((arquivo, index) => (
                                    <div key={index} className="flex items-center gap-2 bg-gray-100 px-3 py-2 rounded-lg">
                                        {arquivo.tipo?.startsWith('image') ? (
                                            <Image className="w-4 h-4 text-blue-600" />
                                        ) : (
                                            <FileText className="w-4 h-4 text-gray-600" />
                                        )}
                                        <a
                                            href={arquivo.url}
                                            target="_blank"
                                            rel="noopener noreferrer"
                                            className="text-sm text-blue-600 hover:underline max-w-[150px] truncate"
                                        >
                                            {arquivo.nome}
                                        </a>
                                        <button
                                            type="button"
                                            onClick={() => removerArquivo(index)}
                                            className="text-red-500 hover:text-red-700"
                                        >
                                            <X className="w-4 h-4" />
                                        </button>
                                    </div>
                                ))}
                            </div>

                            <label className="flex items-center justify-center gap-2 p-4 border-2 border-dashed rounded-lg cursor-pointer hover:bg-gray-50 transition-colors">
                                {uploadingFile ? (
                                    <Loader2 className="w-5 h-5 animate-spin" />
                                ) : (
                                    <>
                                        <Upload className="w-5 h-5 text-gray-400" />
                                        <span className="text-gray-500">Clique para anexar arquivo (foto, documento...)</span>
                                    </>
                                )}
                                <input
                                    type="file"
                                    className="hidden"
                                    onChange={handleFileUpload}
                                    disabled={uploadingFile}
                                    accept="image/*,.pdf,.doc,.docx"
                                />
                            </label>
                        </div>

                        {/* Valores */}
                        <div className="grid md:grid-cols-2 gap-4">
                            <div>
                                <Label>Valor Devolvido (R$)</Label>
                                <Input
                                    type="number"
                                    step="0.01"
                                    min="0"
                                    value={formData.valor_devolvido}
                                    onChange={(e) => setFormData({ ...formData, valor_devolvido: parseFloat(e.target.value) || 0 })}
                                    placeholder="0,00"
                                />
                            </div>
                            <div>
                                <Label>Valor Cobrado (R$)</Label>
                                <Input
                                    type="number"
                                    step="0.01"
                                    min="0"
                                    value={formData.valor_cobrado}
                                    onChange={(e) => setFormData({ ...formData, valor_cobrado: parseFloat(e.target.value) || 0 })}
                                    placeholder="0,00"
                                />
                            </div>
                        </div>


                        {/* Data de Resolução */}
                        {formData.status === "Concluída" && (
                            <div>
                                <Label>Data de Resolução</Label>
                                <Input
                                    type="date" lang="pt-BR"
                                    value={formData.data_resolucao}
                                    onChange={(e) => setFormData({ ...formData, data_resolucao: e.target.value })}
                                />
                            </div>
                        )}

                        {/* Observações */}
                        <div>
                            <Label>Observações Internas</Label>
                            <Textarea
                                value={formData.observacoes}
                                onChange={(e) => setFormData({ ...formData, observacoes: e.target.value })}
                                placeholder="Notas internas (não serão mostradas ao cliente)..."
                                rows={2}
                            />
                        </div>
                    </div>

                    <DialogFooter className="mt-6">
                        <Button type="button" variant="outline" onClick={onClose}>
                            Cancelar
                        </Button>
                        <Button
                            type="submit"
                            disabled={isLoading || !formData.venda_id || !formData.descricao_problema || (!entregue && !assistencia)}
                            style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
                        >
                            {isLoading ? (
                                <>
                                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                                    Salvando...
                                </>
                            ) : (
                                assistencia ? "Atualizar" : "Criar Assistência"
                            )}
                        </Button>
                    </DialogFooter>
                        </form>
                    </>
                )}
            </DialogContent>
        </Dialog>
    );
}

import React, { useState, useEffect } from "react";
import { supabase } from "@/lib/supabase";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Loader2, Package, AlertTriangle } from "lucide-react";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Label } from "@/components/ui/label";

/**
 * Modal de seleção de unidade (loja) de onde descontar o estoque
 * ao concluir uma assistência de tipo Troca ou Peça Faltante.
 *
 * Props:
 *  - isOpen: boolean
 *  - onClose: () => void
 *  - onConfirm: (selecao: { [produto_id]: { loja_id, loja_nome, estoque_disponivel } }) => void
 *  - itens: Array<{ produto_id, produto_nome, quantidade }>
 *  - lojas: Array<{ id, nome, codigo }>
 */
export default function SelecionarLojaReposicaoModal({ isOpen, onClose, onConfirm, itens = [], lojas = [] }) {
    const [estoquePorLojaEProduto, setEstoquePorLojaEProduto] = useState({});
    const [selecao, setSelecao] = useState({});
    const [carregando, setCarregando] = useState(false);

    // Buscar estoque de cada produto em cada loja ao abrir o modal
    useEffect(() => {
        if (!isOpen || itens.length === 0 || lojas.length === 0) return;

        const buscarEstoques = async () => {
            setCarregando(true);
            try {
                const produtoIds = [...new Set(itens.map(i => i.produto_id).filter(Boolean))];
                const lojaIds = lojas.map(l => l.id);

                const { data, error } = await supabase
                    .from('estoque_loja')
                    .select('produto_id, loja_id, quantidade, quantidade_disponivel')
                    .in('produto_id', produtoIds)
                    .in('loja_id', lojaIds);

                if (error) throw error;

                // Montar mapa: { [produto_id]: { [loja_id]: quantidade } }
                const mapa = {};
                for (const row of data || []) {
                    if (!mapa[row.produto_id]) mapa[row.produto_id] = {};
                    mapa[row.produto_id][row.loja_id] = row.quantidade_disponivel ?? row.quantidade ?? 0;
                }
                setEstoquePorLojaEProduto(mapa);

                // Pré-selecionar automaticamente a loja com mais estoque para cada item
                const selecaoInicial = {};
                for (const item of itens) {
                    const estoqueDoItem = mapa[item.produto_id] || {};
                    let melhorLoja = null;
                    let melhorQtd = -1;
                    for (const loja of lojas) {
                        const qtd = estoqueDoItem[loja.id] ?? 0;
                        if (qtd > melhorQtd) {
                            melhorQtd = qtd;
                            melhorLoja = loja;
                        }
                    }
                    if (melhorLoja) {
                        selecaoInicial[item.produto_id] = {
                            loja_id: melhorLoja.id,
                            loja_nome: melhorLoja.nome,
                            estoque_disponivel: melhorQtd,
                        };
                    }
                }
                setSelecao(selecaoInicial);
            } catch (err) {
                console.error("Erro ao buscar estoques por loja:", err);
            } finally {
                setCarregando(false);
            }
        };

        buscarEstoques();
    }, [isOpen, itens, lojas]);

    const handleSelecaoLoja = (produtoId, loja) => {
        const qtd = estoquePorLojaEProduto[produtoId]?.[loja.id] ?? 0;
        setSelecao(prev => ({
            ...prev,
            [produtoId]: {
                loja_id: loja.id,
                loja_nome: loja.nome,
                estoque_disponivel: qtd,
            },
        }));
    };

    const todosSelecionados = itens.every(item => selecao[item.produto_id]);

    const handleConfirmar = () => {
        onConfirm(selecao);
    };

    return (
        <Dialog open={isOpen} onOpenChange={open => !open && onClose()}>
            <DialogContent className="max-w-2xl max-h-[80vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle className="flex items-center gap-2">
                        <Package className="w-5 h-5 text-orange-600" />
                        Selecionar Unidade para Desconto de Estoque
                    </DialogTitle>
                    <p className="text-sm text-gray-500 mt-1">
                        Selecione de qual unidade cada item será descontado. O estoque será reduzido e uma solicitação de reposição será enviada para Compras.
                    </p>
                </DialogHeader>

                {carregando ? (
                    <div className="flex justify-center items-center py-10">
                        <Loader2 className="w-6 h-6 animate-spin text-gray-400" />
                        <span className="ml-2 text-sm text-gray-500">Consultando estoques...</span>
                    </div>
                ) : (
                    <div className="space-y-6 py-2">
                        {itens.map(item => {
                            const estoqueItem = estoquePorLojaEProduto[item.produto_id] || {};
                            const selecaoItem = selecao[item.produto_id];
                            const totalEstoque = Object.values(estoqueItem).reduce((s, q) => s + q, 0);

                            return (
                                <div key={item.produto_id} className="border border-gray-200 rounded-lg p-4 space-y-3">
                                    <div className="flex items-start justify-between gap-2">
                                        <div>
                                            <p className="font-medium text-gray-900">{item.produto_nome}</p>
                                            <p className="text-xs text-gray-500">
                                                Quantidade a descontar: <span className="font-semibold text-red-600">-{item.quantidade}</span>
                                            </p>
                                        </div>
                                        <Badge
                                            className={
                                                totalEstoque === 0
                                                    ? "bg-red-100 text-red-700 border-red-200"
                                                    : totalEstoque < item.quantidade
                                                    ? "bg-yellow-100 text-yellow-700 border-yellow-200"
                                                    : "bg-green-100 text-green-700 border-green-200"
                                            }
                                        >
                                            Total: {totalEstoque} unid.
                                        </Badge>
                                    </div>

                                    {totalEstoque === 0 && (
                                        <div className="flex items-center gap-2 text-xs text-amber-700 bg-amber-50 border border-amber-200 rounded p-2">
                                            <AlertTriangle className="w-4 h-4 flex-shrink-0" />
                                            Estoque zerado em todas as unidades. A reposição será enviada para compras mesmo assim.
                                        </div>
                                    )}

                                    <RadioGroup
                                        value={selecaoItem?.loja_id || ''}
                                        onValueChange={lojaId => {
                                            const loja = lojas.find(l => l.id === lojaId);
                                            if (loja) handleSelecaoLoja(item.produto_id, loja);
                                        }}
                                        className="grid grid-cols-1 sm:grid-cols-2 gap-2"
                                    >
                                        {lojas.map(loja => {
                                            const qtd = estoqueItem[loja.id] ?? 0;
                                            const semEstoque = qtd < item.quantidade;
                                            return (
                                                <div
                                                    key={loja.id}
                                                    className={`flex items-center space-x-2 border rounded-lg p-3 cursor-pointer transition-colors ${
                                                        selecaoItem?.loja_id === loja.id
                                                            ? "border-green-600 bg-green-50"
                                                            : "border-gray-200 hover:border-gray-300"
                                                    }`}
                                                    onClick={() => handleSelecaoLoja(item.produto_id, loja)}
                                                >
                                                    <RadioGroupItem value={loja.id} id={`${item.produto_id}-${loja.id}`} />
                                                    <Label
                                                        htmlFor={`${item.produto_id}-${loja.id}`}
                                                        className="flex-1 cursor-pointer"
                                                    >
                                                        <span className="block font-medium text-sm">{loja.nome}</span>
                                                        <span className={`text-xs ${semEstoque ? "text-amber-600 font-medium" : "text-gray-500"}`}>
                                                            {qtd} unid. disponíveis
                                                            {semEstoque && qtd > 0 && " (insuficiente)"}
                                                            {qtd === 0 && " (sem estoque)"}
                                                        </span>
                                                    </Label>
                                                </div>
                                            );
                                        })}
                                    </RadioGroup>
                                </div>
                            );
                        })}
                    </div>
                )}

                <DialogFooter className="gap-2">
                    <Button variant="outline" onClick={onClose} disabled={carregando}>
                        Cancelar
                    </Button>
                    <Button
                        onClick={handleConfirmar}
                        disabled={carregando || !todosSelecionados}
                        className="bg-green-700 hover:bg-green-800 text-white"
                    >
                        {carregando ? (
                            <Loader2 className="w-4 h-4 animate-spin mr-2" />
                        ) : (
                            <Package className="w-4 h-4 mr-2" />
                        )}
                        Confirmar Desconto e Enviar para Compras
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useQuery } from "@tanstack/react-query";
import { base44 } from "@/api/base44Client";
import { useAuth } from "@/hooks/useAuth";
import { Search, X, ShoppingCart, Users, Package, FileText, Receipt, Truck, Calendar } from "lucide-react";
import { useNavigate } from "react-router-dom";
import FiltrosAvancados from "./FiltrosAvancados";
import ResultadosBusca from "./ResultadosBusca";

export default function BuscaGlobal({ open, onClose }) {
  const [termoBusca, setTermoBusca] = useState("");
  const [filtros, setFiltros] = useState({
    dataInicio: "",
    dataFim: "",
    status: "todos",
    valorMin: "",
    valorMax: "",
    loja: "todas"
  });
  const [secaoAtiva, setSecaoAtiva] = useState("todos");
  const { user, can, filterData } = useAuth();
  const navigate = useNavigate();

  // Debounce para busca
  const [termoDebounced, setTermoDebounced] = useState("");
  useEffect(() => {
    const timer = setTimeout(() => setTermoDebounced(termoBusca), 300);
    return () => clearTimeout(timer);
  }, [termoBusca]);

  // Buscar dados apenas quando há termo de busca
  const habilitarBusca = termoDebounced.length >= 2 && open;

  // Vendas
  const { data: vendas = [] } = useQuery({
    queryKey: ['busca-vendas', termoDebounced, filtros],
    queryFn: async () => {
      const data = await base44.entities.Venda.list();
      return filterData(data);
    },
    enabled: habilitarBusca && can('view_vendas')
  });

  // Clientes
  const { data: clientes = [] } = useQuery({
    queryKey: ['busca-clientes', termoDebounced],
    queryFn: () => base44.entities.Cliente.list(),
    enabled: habilitarBusca && can('view_clientes')
  });

  // Produtos
  const { data: produtos = [] } = useQuery({
    queryKey: ['busca-produtos', termoDebounced],
    queryFn: () => base44.entities.Produto.list(),
    enabled: habilitarBusca && can('view_produtos')
  });

  // Orçamentos
  const { data: orcamentos = [] } = useQuery({
    queryKey: ['busca-orcamentos', termoDebounced],
    queryFn: async () => {
      const data = await base44.entities.Orcamento.list();
      return filterData(data);
    },
    enabled: habilitarBusca && can('view_orcamentos')
  });

  // Entregas
  const { data: entregas = [] } = useQuery({
    queryKey: ['busca-entregas', termoDebounced],
    queryFn: () => base44.entities.Entrega.list(),
    enabled: habilitarBusca && can('view_entregas')
  });



  // Filtrar resultados
  const filtrarResultados = (dados, tipo) => {
    if (!termoDebounced) return [];

    let resultado = dados.filter(item => {
      const termo = termoDebounced.toLowerCase();

      switch (tipo) {
        case 'vendas':
          return item.numero_pedido?.toLowerCase().includes(termo) ||
            item.cliente_nome?.toLowerCase().includes(termo);
        case 'clientes':
          return item.nome_completo?.toLowerCase().includes(termo) ||
            item.telefone?.includes(termo) ||
            item.cpf?.includes(termo) ||
            item.email?.toLowerCase().includes(termo);
        case 'produtos':
          return item.nome?.toLowerCase().includes(termo) ||
            item.sku?.toLowerCase().includes(termo) ||
            item.codigo_barras?.includes(termo) ||
            item.modelo_referencia?.toLowerCase().includes(termo) ||
            item.categoria?.toLowerCase().includes(termo);
        case 'orcamentos':
          return item.numero_orcamento?.toLowerCase().includes(termo) ||
            item.cliente_nome?.toLowerCase().includes(termo);
        case 'entregas':
          return item.numero_pedido?.toLowerCase().includes(termo) ||
            item.cliente_nome?.toLowerCase().includes(termo) ||
            item.endereco_entrega?.toLowerCase().includes(termo);
        default:
          return false;
      }
    });

    // Aplicar filtros avançados
    if (filtros.dataInicio && tipo === 'vendas') {
      resultado = resultado.filter(item => item.data_venda >= filtros.dataInicio);
    }
    if (filtros.dataFim && tipo === 'vendas') {
      resultado = resultado.filter(item => item.data_venda <= filtros.dataFim);
    }
    if (filtros.status !== 'todos' && (tipo === 'vendas' || tipo === 'orcamentos')) {
      resultado = resultado.filter(item => item.status === filtros.status);
    }
    if (filtros.valorMin && tipo === 'vendas') {
      resultado = resultado.filter(item => item.valor_total >= parseFloat(filtros.valorMin));
    }
    if (filtros.valorMax && tipo === 'vendas') {
      resultado = resultado.filter(item => item.valor_total <= parseFloat(filtros.valorMax));
    }
    if (filtros.loja !== 'todas' && tipo === 'vendas') {
      resultado = resultado.filter(item => item.loja === filtros.loja);
    }

    return resultado;
  };

  const vendasFiltradas = filtrarResultados(vendas, 'vendas');
  const clientesFiltrados = filtrarResultados(clientes, 'clientes');
  const produtosFiltrados = filtrarResultados(produtos, 'produtos');
  const orcamentosFiltrados = filtrarResultados(orcamentos, 'orcamentos');
  const entregasFiltradas = filtrarResultados(entregas, 'entregas');

  const totalResultados = vendasFiltradas.length + clientesFiltrados.length +
    produtosFiltrados.length + orcamentosFiltrados.length +
    entregasFiltradas.length;

  const navegarPara = (tipo, item) => {
    switch (tipo) {
      case 'vendas':
        navigate('/admin/Pedidos');
        break;
      case 'clientes':
        navigate('/Clientes');
        break;
      case 'produtos':
        navigate('/Estoque');
        break;
      case 'orcamentos':
        navigate('/Orcamentos');
        break;
      case 'entregas':
        navigate('/Entregas');
        break;
    }
    onClose();
  };

  const limparBusca = () => {
    setTermoBusca("");
    setFiltros({
      dataInicio: "",
      dataFim: "",
      status: "todos",
      valorMin: "",
      valorMax: "",
      loja: "todas"
    });
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-hidden flex flex-col p-0">
        <DialogHeader className="p-6 pb-4 border-b">
          <div className="flex items-center gap-3">
            <Search className="w-5 h-5 text-gray-400" />
            <Input
              placeholder="Buscar em pedidos, clientes, produtos, orçamentos..."
              value={termoBusca}
              onChange={(e) => setTermoBusca(e.target.value)}
              className="flex-1 border-0 focus-visible:ring-0 text-lg"
              autoFocus
            />
            {termoBusca && (
              <Button variant="ghost" size="sm" onClick={limparBusca}>
                <X className="w-4 h-4" />
              </Button>
            )}
          </div>
          {termoDebounced.length >= 2 && (
            <div className="flex items-center justify-between mt-2">
              <p className="text-sm text-gray-500">
                {totalResultados} {totalResultados === 1 ? 'resultado encontrado' : 'resultados encontrados'}
              </p>
              <FiltrosAvancados filtros={filtros} onChange={setFiltros} />
            </div>
          )}
        </DialogHeader>

        <div className="flex-1 overflow-auto p-6">
          {termoDebounced.length < 2 ? (
            <div className="text-center py-12">
              <Search className="w-12 h-12 text-gray-300 mx-auto mb-4" />
              <p className="text-gray-500">Digite pelo menos 2 caracteres para buscar</p>
              <div className="mt-6 flex flex-wrap gap-2 justify-center">
                <Badge variant="outline">Pedidos</Badge>
                <Badge variant="outline">Clientes</Badge>
                <Badge variant="outline">Produtos</Badge>
                <Badge variant="outline">Orçamentos</Badge>
                <Badge variant="outline">Entregas</Badge>
              </div>
            </div>
          ) : totalResultados === 0 ? (
            <div className="text-center py-12">
              <div className="w-12 h-12 rounded-full bg-gray-100 flex items-center justify-center mx-auto mb-4">
                <Search className="w-6 h-6 text-gray-400" />
              </div>
              <p className="text-gray-500 font-medium">Nenhum resultado encontrado</p>
              <p className="text-sm text-gray-400 mt-1">Tente usar outros termos de busca</p>
            </div>
          ) : (
            <Tabs value={secaoAtiva} onValueChange={setSecaoAtiva}>
              <TabsList className="mb-4">
                <TabsTrigger value="todos">
                  Todos ({totalResultados})
                </TabsTrigger>
                {vendasFiltradas.length > 0 && (
                  <TabsTrigger value="vendas">
                    <ShoppingCart className="w-4 h-4 mr-1" />
                    Pedidos ({vendasFiltradas.length})
                  </TabsTrigger>
                )}
                {clientesFiltrados.length > 0 && (
                  <TabsTrigger value="clientes">
                    <Users className="w-4 h-4 mr-1" />
                    Clientes ({clientesFiltrados.length})
                  </TabsTrigger>
                )}
                {produtosFiltrados.length > 0 && (
                  <TabsTrigger value="produtos">
                    <Package className="w-4 h-4 mr-1" />
                    Produtos ({produtosFiltrados.length})
                  </TabsTrigger>
                )}
                {orcamentosFiltrados.length > 0 && (
                  <TabsTrigger value="orcamentos">
                    <FileText className="w-4 h-4 mr-1" />
                    Orçamentos ({orcamentosFiltrados.length})
                  </TabsTrigger>
                )}
                {entregasFiltradas.length > 0 && (
                  <TabsTrigger value="entregas">
                    <Truck className="w-4 h-4 mr-1" />
                    Entregas ({entregasFiltradas.length})
                  </TabsTrigger>
                )}
              </TabsList>

              <TabsContent value="todos" className="space-y-4">
                {vendasFiltradas.length > 0 && (
                  <ResultadosBusca
                    titulo="Pedidos"
                    icon={ShoppingCart}
                    dados={vendasFiltradas.slice(0, 5)}
                    tipo="vendas"
                    onClicar={navegarPara}
                    termo={termoDebounced}
                  />
                )}
                {clientesFiltrados.length > 0 && (
                  <ResultadosBusca
                    titulo="Clientes"
                    icon={Users}
                    dados={clientesFiltrados.slice(0, 5)}
                    tipo="clientes"
                    onClicar={navegarPara}
                    termo={termoDebounced}
                  />
                )}
                {produtosFiltrados.length > 0 && (
                  <ResultadosBusca
                    titulo="Produtos"
                    icon={Package}
                    dados={produtosFiltrados.slice(0, 5)}
                    tipo="produtos"
                    onClicar={navegarPara}
                    termo={termoDebounced}
                  />
                )}
                {orcamentosFiltrados.length > 0 && (
                  <ResultadosBusca
                    titulo="Orçamentos"
                    icon={FileText}
                    dados={orcamentosFiltrados.slice(0, 5)}
                    tipo="orcamentos"
                    onClicar={navegarPara}
                    termo={termoDebounced}
                  />
                )}
                {entregasFiltradas.length > 0 && (
                  <ResultadosBusca
                    titulo="Entregas"
                    icon={Truck}
                    dados={entregasFiltradas.slice(0, 5)}
                    tipo="entregas"
                    onClicar={navegarPara}
                    termo={termoDebounced}
                  />
                )}
              </TabsContent>

              <TabsContent value="vendas">
                <ResultadosBusca
                  titulo="Pedidos"
                  icon={ShoppingCart}
                  dados={vendasFiltradas}
                  tipo="vendas"
                  onClicar={navegarPara}
                  termo={termoDebounced}
                />
              </TabsContent>

              <TabsContent value="clientes">
                <ResultadosBusca
                  titulo="Clientes"
                  icon={Users}
                  dados={clientesFiltrados}
                  tipo="clientes"
                  onClicar={navegarPara}
                  termo={termoDebounced}
                />
              </TabsContent>

              <TabsContent value="produtos">
                <ResultadosBusca
                  titulo="Produtos"
                  icon={Package}
                  dados={produtosFiltrados}
                  tipo="produtos"
                  onClicar={navegarPara}
                  termo={termoDebounced}
                />
              </TabsContent>

              <TabsContent value="orcamentos">
                <ResultadosBusca
                  titulo="Orçamentos"
                  icon={FileText}
                  dados={orcamentosFiltrados}
                  tipo="orcamentos"
                  onClicar={navegarPara}
                  termo={termoDebounced}
                />
              </TabsContent>

              <TabsContent value="entregas">
                <ResultadosBusca
                  titulo="Entregas"
                  icon={Truck}
                  dados={entregasFiltradas}
                  tipo="entregas"
                  onClicar={navegarPara}
                  termo={termoDebounced}
                />
              </TabsContent>
            </Tabs>
          )}
        </div>

        <div className="border-t p-4 bg-gray-50 dark:bg-neutral-900 text-xs text-gray-500 flex items-center justify-between">
          <div className="flex gap-4">
            <kbd className="px-2 py-1 bg-white dark:bg-neutral-800 border rounded">↑↓</kbd>
