          <div>
            <kbd className="px-2 py-1 bg-white dark:bg-neutral-800 border rounded">Esc</kbd>
            <span className="ml-2">Fechar</span>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from "react";
import { useLojas } from "@/hooks/useLojas";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Filter, X } from "lucide-react";
import { Badge } from "@/components/ui/badge";

export default function FiltrosAvancados({ filtros, onChange }) {
  const [aberto, setAberto] = useState(false);
  const { data: lojas = [] } = useLojas();

  const contarFiltrosAtivos = () => {
    let count = 0;
    if (filtros.dataInicio) count++;
    if (filtros.dataFim) count++;
    if (filtros.status !== 'todos') count++;
    if (filtros.valorMin) count++;
    if (filtros.valorMax) count++;
    if (filtros.loja !== 'todas') count++;
    return count;
  };

  const limparFiltros = () => {
    onChange({
      dataInicio: "",
      dataFim: "",
      status: "todos",
      valorMin: "",
      valorMax: "",
      loja: "todas"
    });
  };

  const filtrosAtivos = contarFiltrosAtivos();

  return (
    <Popover open={aberto} onOpenChange={setAberto}>
      <PopoverTrigger asChild>
        <Button variant="outline" size="sm" className="gap-2">
          <Filter className="w-4 h-4" />
          Filtros
          {filtrosAtivos > 0 && (
            <Badge variant="default" className="ml-1 h-5 w-5 flex items-center justify-center p-0">
              {filtrosAtivos}
            </Badge>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-80" align="end">
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <h4 className="font-semibold text-sm">Filtros Avançados</h4>
            {filtrosAtivos > 0 && (
              <Button variant="ghost" size="sm" onClick={limparFiltros}>
                <X className="w-4 h-4 mr-1" />
                Limpar
              </Button>
            )}
          </div>

          <div className="space-y-3">
            <div>
              <Label className="text-xs">Data Início</Label>
              <Input
                type="date" lang="pt-BR"
                value={filtros.dataInicio}
                onChange={(e) => onChange({ ...filtros, dataInicio: e.target.value })}
              />
            </div>

            <div>
              <Label className="text-xs">Data Fim</Label>
              <Input
                type="date" lang="pt-BR"
                value={filtros.dataFim}
                onChange={(e) => onChange({ ...filtros, dataFim: e.target.value })}
              />
            </div>

            <div>
              <Label className="text-xs">Status</Label>
              <Select value={filtros.status} onValueChange={(val) => onChange({ ...filtros, status: val })}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="todos">Todos</SelectItem>
                  <SelectItem value="Pendente">Pendente</SelectItem>
                  <SelectItem value="Pago">Pago</SelectItem>
                  <SelectItem value="Cancelado">Cancelado</SelectItem>
                  <SelectItem value="Aprovado">Aprovado</SelectItem>
                  <SelectItem value="Entregue">Entregue</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="grid grid-cols-2 gap-2">
              <div>
                <Label className="text-xs">Valor Mín.</Label>
                <Input
                  type="number"
                  placeholder="R$ 0"
                  value={filtros.valorMin}
                  onChange={(e) => onChange({ ...filtros, valorMin: e.target.value })}
                />
              </div>
              <div>
                <Label className="text-xs">Valor Máx.</Label>
                <Input
                  type="number"
                  placeholder="R$ 9999"
                  value={filtros.valorMax}
                  onChange={(e) => onChange({ ...filtros, valorMax: e.target.value })}
                />
              </div>
            </div>

            <div>
              <Label className="text-xs">Loja</Label>
              <Select value={filtros.loja} onValueChange={(val) => onChange({ ...filtros, loja: val })}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="todas">Todas</SelectItem>
                  {lojas.map(loja => (
                    <SelectItem key={loja.id} value={loja.nome}>{loja.nome}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        </div>
      </PopoverContent>
    </Popover>
  );
}

import React from "react";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { ChevronRight } from "lucide-react";
import { formatarDataExibicao } from "@/utils/dateUtils";

export default function ResultadosBusca({ titulo, icon: Icon, dados, tipo, onClicar, termo }) {
  const destacarTexto = (texto, termo) => {
    if (!texto || !termo) return texto;
    const textoStr = String(texto);
    const regex = new RegExp(`(${termo})`, 'gi');
    const partes = textoStr.split(regex);
    
    return partes.map((parte, i) => 
      regex.test(parte) ? 
        <mark key={i} className="bg-yellow-200 dark:bg-yellow-900 font-semibold">{parte}</mark> : 
        parte
    );
  };

  const renderizarItem = (item) => {
    switch(tipo) {
      case 'vendas':
        return (
          <div
            key={item.id}
            onClick={() => onClicar(tipo, item)}
            className="p-4 hover:bg-gray-50 dark:hover:bg-neutral-800 cursor-pointer border-b last:border-b-0 transition-colors"
          >
            <div className="flex items-center justify-between">
              <div className="flex-1">
                <div className="flex items-center gap-2 mb-1">
                  <span className="font-semibold text-gray-900 dark:text-white">
                    {destacarTexto(item.numero_pedido, termo)}
                  </span>
                  <Badge variant={
                    item.status === 'Pago' ? 'default' : 
                    item.status === 'Cancelado' ? 'destructive' : 
                    'secondary'
                  }>
                    {item.status}
                  </Badge>
                </div>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  Cliente: {destacarTexto(item.cliente_nome, termo)}
                </p>
                <div className="flex items-center gap-4 mt-1 text-xs text-gray-500">
                  <span>📅 {formatarDataExibicao(item.data_venda)}</span>
                  <span>💰 R$ {item.valor_total?.toFixed(2)}</span>
                  <span>🏪 {item.loja}</span>
                </div>
              </div>
              <ChevronRight className="w-5 h-5 text-gray-400" />
            </div>
          </div>
        );

      case 'clientes':
        return (
          <div
            key={item.id}
            onClick={() => onClicar(tipo, item)}
            className="p-4 hover:bg-gray-50 dark:hover:bg-neutral-800 cursor-pointer border-b last:border-b-0 transition-colors"
          >
            <div className="flex items-center justify-between">
              <div className="flex-1">
                <div className="font-semibold text-gray-900 dark:text-white mb-1">
                  {destacarTexto(item.nome_completo, termo)}
                </div>
                <div className="flex gap-3 text-sm text-gray-600 dark:text-gray-400">
                  <span>📱 {destacarTexto(item.telefone, termo)}</span>
                  {item.email && <span>📧 {destacarTexto(item.email, termo)}</span>}
                </div>
                {item.cidade && (
                  <p className="text-xs text-gray-500 mt-1">
                    📍 {item.cidade} - {item.estado}
                  </p>
                )}
              </div>
              <ChevronRight className="w-5 h-5 text-gray-400" />
            </div>
          </div>
        );

      case 'produtos':
        return (
          <div
            key={item.id}
            onClick={() => onClicar(tipo, item)}
            className="p-4 hover:bg-gray-50 dark:hover:bg-neutral-800 cursor-pointer border-b last:border-b-0 transition-colors"
          >
            <div className="flex items-center justify-between">
              <div className="flex-1">
                <div className="font-semibold text-gray-900 dark:text-white mb-1">
                  {destacarTexto(item.nome, termo)}
                </div>
                <div className="flex flex-wrap items-center gap-2 text-sm text-gray-600 dark:text-gray-400">
                  <Badge variant="outline">{item.categoria}</Badge>
                  {item.sku && (
                    <span className="text-xs font-mono font-medium text-gray-800 dark:text-gray-200">SKU: {destacarTexto(item.sku, termo)}</span>
                  )}
                  {item.codigo_barras && (
                    <span className="text-xs font-mono text-gray-600 dark:text-gray-400">EAN: {destacarTexto(item.codigo_barras, termo)}</span>
                  )}
                  {item.modelo_referencia && (
                    <span className="text-xs text-gray-500">Ref: {destacarTexto(item.modelo_referencia, termo)}</span>
                  )}
                </div>
                <div className="flex gap-4 mt-2 text-xs">
                  <span className="text-green-600 font-semibold">R$ {item.preco_venda?.toFixed(2)}</span>
                  <span className="text-gray-500">
                    Estoque: {item.quantidade_estoque || 0} un.
                  </span>
                </div>
              </div>
              <ChevronRight className="w-5 h-5 text-gray-400" />
            </div>
          </div>
        );

      case 'orcamentos':
        return (
          <div
            key={item.id}
            onClick={() => onClicar(tipo, item)}
            className="p-4 hover:bg-gray-50 dark:hover:bg-neutral-800 cursor-pointer border-b last:border-b-0 transition-colors"
          >
            <div className="flex items-center justify-between">
              <div className="flex-1">
                <div className="flex items-center gap-2 mb-1">
                  <span className="font-semibold text-gray-900 dark:text-white">
                    {destacarTexto(item.numero_orcamento, termo)}
                  </span>
                  <Badge variant={
                    item.status === 'Aprovado' ? 'default' :
                    item.status === 'Convertido' ? 'default' :
                    item.status === 'Rejeitado' ? 'destructive' :
                    'secondary'
                  }>
                    {item.status}
                  </Badge>
                </div>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  Cliente: {destacarTexto(item.cliente_nome, termo)}
                </p>
                <div className="flex items-center gap-4 mt-1 text-xs text-gray-500">
                  <span>📅 {formatarDataExibicao(item.data_orcamento)}</span>
                  <span>💰 R$ {item.valor_total?.toFixed(2)}</span>
                  <span>⏰ Validade: {formatarDataExibicao(item.validade)}</span>
                </div>
              </div>
              <ChevronRight className="w-5 h-5 text-gray-400" />
            </div>
          </div>
        );

      case 'entregas':
        return (
          <div
            key={item.id}
            onClick={() => onClicar(tipo, item)}
            className="p-4 hover:bg-gray-50 dark:hover:bg-neutral-800 cursor-pointer border-b last:border-b-0 transition-colors"
          >
            <div className="flex items-center justify-between">
              <div className="flex-1">
                <div className="flex items-center gap-2 mb-1">
                  <span className="font-semibold text-gray-900 dark:text-white">
                    {destacarTexto(item.numero_pedido, termo)}
                  </span>
                  <Badge variant={
                    item.status === 'Entregue' ? 'default' :
                    item.status === 'Em Rota' ? 'secondary' :
                    item.status === 'Cancelada' ? 'destructive' :
                    'outline'
                  }>
                    {item.status}
                  </Badge>
                </div>
                <p className="text-sm text-gray-600 dark:text-gray-400 mb-1">
                  Cliente: {destacarTexto(item.cliente_nome, termo)}
                </p>
                <p className="text-xs text-gray-500 line-clamp-1">
                  📍 {destacarTexto(item.endereco_entrega, termo)}
                </p>
                {item.data_agendada && (
                  <p className="text-xs text-gray-500 mt-1">
                    📅 Agendada: {formatarDataExibicao(item.data_agendada)} - {item.turno}
                  </p>
                )}
              </div>
              <ChevronRight className="w-5 h-5 text-gray-400" />
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="mb-6">
      <div className="flex items-center gap-2 mb-3 px-4">
        <Icon className="w-5 h-5 text-gray-500" />
        <h3 className="font-semibold text-gray-900 dark:text-white">{titulo}</h3>
        <Badge variant="secondary">{dados.length}</Badge>
      </div>
      <Card className="divide-y overflow-hidden">
        {dados.map(renderizarItem)}
      </Card>
    </div>
  );
}

import React, { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription
} from "@/components/ui/dialog";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
    ShoppingBag,
    User,
    Star,
    Calendar,
    TrendingUp,
    Package,
    Clock,
    Phone,
    Mail,
    FileText,
    Cake,
    MapPin,
    Truck,
    Ban
} from 'lucide-react';
import { base44 } from '@/lib/supabase';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { formatarCPFCNPJ, formatarTelefone } from '@/utils/formatters';

const normalizarTexto = (value) => (value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
const somenteDigitos = (value) => (value || '').replace(/\D/g, '');

export function ClienteCRMModal({ cliente, isOpen, onClose }) {
    // Busca o histórico de vendas do cliente
    // Usa base44.entities.Venda.list() (método comprovado pelo app) e filtra em memória.
    // Queries diretas via supabase.from() retornam 400 por exigência do header Range.
    const { data: vendas, isLoading } = useQuery({
        queryKey: ['vendas-crm-v2', cliente?.id],
        queryFn: async () => {
            if (!cliente?.id) return [];

            const nomeCliente = normalizarTexto(cliente?.nome_completo || '');
            const telefoneCliente = somenteDigitos(cliente?.telefone);

            const todasVendas = await base44.entities.Venda.list('-data_venda');

            const idsVistos = new Set();
            return (todasVendas || []).filter((venda) => {
                // Deduplicação por id (garante contra cache antigo ou registros duplicados no DB)
                if (idsVistos.has(venda.id)) return false;

                // 1. Match por cliente_id (BIGINT ou UUID)
                if (venda?.cliente_id != null && String(venda.cliente_id) === String(cliente.id)) {
                    idsVistos.add(venda.id);
                    return true;
                }
                // 2. Match por nome normalizado
                const nomeVenda = normalizarTexto(venda?.cliente_nome);
                if (nomeCliente && nomeVenda &&
                    (nomeVenda.includes(nomeCliente) || nomeCliente.includes(nomeVenda))) {
                    idsVistos.add(venda.id);
                    return true;
                }
                // 3. Match por telefone (últimos 8 dígitos)
                const telefoneVenda = somenteDigitos(venda?.cliente_telefone);
                if (telefoneCliente.length >= 8 && telefoneVenda.length >= 8 &&
                    (telefoneVenda.endsWith(telefoneCliente.slice(-8)) ||
                        telefoneCliente.endsWith(telefoneVenda.slice(-8)))) {
                    idsVistos.add(venda.id);
                    return true;
                }
                return false;
            });
        },
        enabled: !!cliente?.id && isOpen,
    });

    // Busca todos os produtos para ter acesso às categorias (fallback para vendas antigas)
    const { data: produtos } = useQuery({
        queryKey: ['produtos-crm'],
        queryFn: async () => {
            const { data, error } = await base44.entities.Produto.list();
            if (error) throw error;
            return data || [];
        },
        enabled: isOpen,
    });

    // Calcula categorias de interesse
    const interesses = useMemo(() => {
        if (!vendas) return [];
        const catCounts = {};

        // Cria um mapa de produto_id -> categoria
        const produtoMap = (produtos || []).reduce((acc, p) => {
            acc[p.id] = p.categoria || "Geral";
            return acc;
        }, {});

        vendas.forEach(venda => {
            const itens = Array.isArray(venda.itens) ? venda.itens : [];
            itens.forEach(item => {
                // Tenta pegar do item (novas vendas) ou do mapa de produtos (vendas antigas)
                const categoria = item.produto_categoria || produtoMap[item.produto_id] || "Outros";
                catCounts[categoria] = (catCounts[categoria] || 0) + (item.quantidade || 1);
            });
        });

        return Object.entries(catCounts)
            .sort((a, b) => b[1] - a[1])
            .slice(0, 5)
            .map(([nome, qtde]) => ({ nome, qtde }));
    }, [vendas, produtos]);

    // Função para pegar a badge de tier (coroas)
    const getTierBadge = (coroas = 0) => {
        if (coroas >= 500) return { label: 'Ouro', color: 'bg-amber-500 text-white' };
        if (coroas >= 100) return { label: 'Prata', color: 'bg-slate-400 text-white' };
        return { label: 'Bronze', color: 'bg-amber-700 text-white' };
    };

    const tier = getTierBadge(cliente?.coroas);

    if (!cliente) return null;

    return (
        <Dialog open={isOpen} onOpenChange={onClose}>
            <DialogContent className="max-w-4xl max-h-[90vh] flex flex-col p-6">
