        endereco_entrega_complemento: cliente.endereco_entrega_complemento || "",
        endereco_entrega_ponto_referencia: cliente.endereco_entrega_ponto_referencia || "",
        endereco_entrega_bairro: cliente.endereco_entrega_bairro || "",
        endereco_entrega_cidade: cliente.endereco_entrega_cidade || "",
        endereco_entrega_estado: cliente.endereco_entrega_estado || "",
        // Outros
        contatos: cliente.contatos || [],
        observacoes: cliente.observacoes || "",
        data_nascimento: cliente.data_nascimento || "",
        // Preferências de Entrega
        // Preferências de Entrega (Garante que sejam números)
        dias_bloqueados_entrega: cliente.dias_bloqueados_entrega?.map(d => Number(d)) || [],
        turno_bloqueado_entrega: cliente.turno_bloqueado_entrega || "",
      });
    } else {
      setFormData({
        nome_completo: "",
        tipo_pessoa: "Física",
        cpf: "",
        cnpj: "",
        razao_social: "",
        telefone: "",
        email: "",
        cep: "",
        endereco: "",
        numero: "",
        complemento: "",
        ponto_referencia: "",
        bairro: "",
        cidade: "",
        estado: "",
        usar_mesmo_endereco: true,
        endereco_entrega_cep: "",
        endereco_entrega_rua: "",
        endereco_entrega_numero: "",
        endereco_entrega_complemento: "",
        endereco_entrega_ponto_referencia: "",
        endereco_entrega_bairro: "",
        endereco_entrega_cidade: "",
        endereco_entrega_estado: "",
        contatos: [],
        observacoes: "",
        data_nascimento: "",
        dias_bloqueados_entrega: [],
        turno_bloqueado_entrega: "",
      });
    }
  }, [cliente, isOpen]);


  // Função auxiliar para buscar com timeout
  const fetchWithTimeout = async (resource, options = {}) => {
    const { timeout = 5000 } = options;
    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), timeout);
    const response = await fetch(resource, {
      ...options,
      signal: controller.signal
    });
    clearTimeout(id);
    return response;
  };

  const buscarCEP = async (cep, isEntrega = false) => {
    const cepLimpo = cep.replace(/\D/g, '');
    if (cepLimpo.length !== 8) return;

    if (isEntrega) {
      setBuscandoCepEntrega(true);
    } else {
      setBuscandoCep(true);
    }

    const preencherDados = (dados) => {
      if (isEntrega) {
        setFormData(prev => ({
          ...prev,
          endereco_entrega_rua: formatarEndereco(dados.logradouro || dados.street || ""),
          endereco_entrega_bairro: formatarEndereco(dados.bairro || dados.neighborhood || ""),
          endereco_entrega_cidade: formatarEndereco(dados.localidade || dados.city || ""),
          endereco_entrega_estado: dados.uf || dados.state || "",
        }));
      } else {
        setFormData(prev => ({
          ...prev,
          endereco: formatarEndereco(dados.logradouro || dados.street || ""),
          bairro: formatarEndereco(dados.bairro || dados.neighborhood || ""),
          cidade: formatarEndereco(dados.localidade || dados.city || ""),
          estado: dados.uf || dados.state || "",
        }));
      }
    };

    try {
      // Tentativa 1: ViaCEP
      console.log(`🔍 Buscando CEP ${cepLimpo} via ViaCEP...`);
      const response = await fetchWithTimeout(`https://viacep.com.br/ws/${cepLimpo}/json/`, { timeout: 3000 });
      if (!response.ok) throw new Error("ViaCEP indisponível");

      const data = await response.json();
      if (data.erro) {
        // Se o ViaCEP retornar { erro: true }, o CEP não existe, não adianta tentar outro serviço
        console.warn("⚠️ CEP não encontrado no ViaCEP.");
        // Opcional: tentar BrasilAPI mesmo assim caso seja um CEP muito novo
        throw new Error("CEP não encontrado");
      }

      preencherDados(data);
      console.log("✅ CEP encontrado via ViaCEP");

    } catch (errorViaCep) {
      console.warn(`⚠️ Falha no ViaCEP (${errorViaCep.message}). Tentando BrasilAPI...`);

      try {
        // Tentativa 2: BrasilAPI
        const responseBrasil = await fetchWithTimeout(`https://brasilapi.com.br/api/cep/v1/${cepLimpo}`, { timeout: 3000 });
        if (!responseBrasil.ok) throw new Error("BrasilAPI indisponível");

        const dataBrasil = await responseBrasil.json();
        preencherDados(dataBrasil);
        console.log("✅ CEP encontrado via BrasilAPI");

      } catch (errorBrasil) {
        console.error("❌ Erro em todos os serviços de CEP:", errorBrasil);
        if (isEntrega) {
          // Opcional: mostrar erro visual
        }
      }
    } finally {
      if (isEntrega) {
        setBuscandoCepEntrega(false);
      } else {
        setBuscandoCep(false);
      }
    }
  };

  const buscarCNPJ = async (cnpj) => {
    const cnpjLimpo = cnpj.replace(/\D/g, '');
    if (cnpjLimpo.length !== 14) return;

    setBuscandoCnpj(true);
    try {
      const response = await fetch(`https://brasilapi.com.br/api/cnpj/v1/${cnpjLimpo}`);
      const data = await response.json();

      setFormData(prev => ({
        ...prev,
        razao_social: formatarNome(data.razao_social || ""),
        nome_completo: formatarNome(data.nome_fantasia || data.razao_social || prev.nome_completo),
        telefone: formatarTelefone(data.ddd_telefone_1 ? data.ddd_telefone_1 + (data.telefone_1 || "") : prev.telefone),
        email: data.email || prev.email,
        cep: data.cep?.replace(/\D/g, '') || "",
        endereco: formatarEndereco(data.logradouro || ""),
        numero: data.numero || "",
        complemento: formatarEndereco(data.complemento || ""),
        bairro: formatarEndereco(data.bairro || ""),
        cidade: formatarEndereco(data.municipio || ""),
        estado: data.uf || "",
      }));
    } catch (error) {
      console.error("Erro ao buscar CNPJ:", error);
    } finally {
      setBuscandoCnpj(false);
    }
  };

  const adicionarContato = () => {
    setFormData({
      ...formData,
      contatos: [...formData.contatos, { nome: "", telefone: "", email: "", tipo: "Principal" }]
    });
  };

  const removerContato = (index) => {
    setFormData({
      ...formData,
      contatos: formData.contatos.filter((_, i) => i !== index)
    });
  };

  const atualizarContato = (index, campo, valor) => {
    const novosContatos = [...formData.contatos];
    if (campo === 'nome') {
      novosContatos[index][campo] = formatarNome(valor);
    } else if (campo === 'telefone') {
      novosContatos[index][campo] = formatarTelefone(valor);
    } else {
      novosContatos[index][campo] = valor;
    }
    setFormData({ ...formData, contatos: novosContatos });
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!formData.nome_completo || !formData.telefone) {
      alert("Preencha nome e telefone do cliente");
      return;
    }

    if (!formData.cidade || !formData.estado) {
      alert("Preencha a cidade e o estado do cliente");
      return;
    }

    if (!formData.usar_mesmo_endereco && (!formData.endereco_entrega_cidade || !formData.endereco_entrega_estado)) {
      alert("Preencha a cidade e o estado do endereço de entrega");
      return;
    }

    // Validação de duplicidade
    const cpfLimpo = formData.cpf?.replace(/\D/g, '') || '';
    const telefoneLimpo = formData.telefone?.replace(/\D/g, '') || '';
    const emailLimpo = formData.email?.toLowerCase().trim() || '';

    const duplicatas = clientes.filter(c => {
      if (cliente && c.id === cliente.id) return false;

      const cCpf = c.cpf?.replace(/\D/g, '') || '';
      const cTelefone = c.telefone?.replace(/\D/g, '') || '';
      const cEmail = c.email?.toLowerCase().trim() || '';

      return (
        (cpfLimpo && cCpf && cpfLimpo === cCpf) ||
        (telefoneLimpo && cTelefone && telefoneLimpo === cTelefone) ||
        (emailLimpo && cEmail && emailLimpo === cEmail)
      );
    });

    if (duplicatas.length > 0) {
      const mensagens = [];
      duplicatas.forEach(dup => {
        if (cpfLimpo && dup.cpf?.replace(/\D/g, '') === cpfLimpo) {
          mensagens.push(`CPF já cadastrado para: ${dup.nome_completo}`);
        }
        if (telefoneLimpo && dup.telefone?.replace(/\D/g, '') === telefoneLimpo) {
          mensagens.push(`Telefone já cadastrado para: ${dup.nome_completo}`);
        }
        if (emailLimpo && dup.email?.toLowerCase().trim() === emailLimpo) {
          mensagens.push(`Email já cadastrado para: ${dup.nome_completo}`);
        }
      });

      alert(`Cliente com dados duplicados encontrado:\n\n${mensagens.join('\n')}\n\nVerifique os dados ou edite o cliente existente.`);
      return;
    }

    onSave(formData);
  };

  // Render function reutilizável de campos de endereço (convertido de componente para evitar remount)
  const renderCamposEndereco = (prefix = "", disabled = false) => {
    const getField = (field) => prefix ? `${prefix}_${field}` : field;
    const getValue = (field) => formData[getField(field)] || "";
    const setValue = (field, value) => setFormData(prev => ({ ...prev, [getField(field)]: value }));

    const isEntrega = prefix === "endereco_entrega";

    // Simplificando lógica de busca
    const handleBuscaCEP = () => buscarCEP(getValue(isEntrega ? "cep" : "cep"), isEntrega);

    return (
      <div className="space-y-4">
        <div className="grid md:grid-cols-3 gap-4">
          <div>
            <Label>CEP</Label>
            <div className="flex gap-2">
              <Input
                value={getValue(isEntrega ? "cep" : "cep")}
                onChange={(e) => setValue(isEntrega ? "cep" : "cep", e.target.value)}
                onBlur={() => !disabled && handleBuscaCEP()}
                placeholder="00000-000"
                disabled={disabled}
              />
              <Button
                type="button"
                variant="outline"
                onClick={handleBuscaCEP}
                disabled={disabled || (isEntrega ? buscandoCepEntrega : buscandoCep)}
              >
                {(isEntrega ? buscandoCepEntrega : buscandoCep) ? <Loader2 className="w-4 h-4 animate-spin" /> : <Search className="w-4 h-4" />}
              </Button>
            </div>
          </div>
          <div className="md:col-span-2">
            <Label>Rua/Logradouro</Label>
            <Input
              value={getValue(isEntrega ? "rua" : "endereco")}
              onChange={(e) => setValue(isEntrega ? "rua" : "endereco", e.target.value)}
              disabled={disabled}
            />
          </div>
        </div>

        <div className="grid md:grid-cols-4 gap-4">
          <div>
            <Label>Número</Label>
            <Input
              value={getValue("numero")}
              onChange={(e) => setValue("numero", e.target.value)}
              placeholder="123"
              disabled={disabled}
            />
          </div>
          <div className="md:col-span-3">
            <Label>Complemento</Label>
            <Input
              value={getValue("complemento")}
              onChange={(e) => setValue("complemento", e.target.value)}
              placeholder="Apt 101, Bloco A..."
              disabled={disabled}
            />
          </div>
        </div>

        <div>
          <Label className="flex items-center gap-1">
            <MapPin className="w-3 h-3" style={{ color: '#07593f' }} />
            Ponto de Referência
          </Label>
          <Input
            value={getValue("ponto_referencia")}
            onChange={(e) => setValue("ponto_referencia", e.target.value)}
            placeholder="Próximo ao mercado, em frente à farmácia..."
            disabled={disabled}
          />
        </div>

        <div className="grid md:grid-cols-2 gap-4">
          <div>
            <Label>Bairro</Label>
            <Input
              value={getValue("bairro")}
              onChange={(e) => setValue("bairro", e.target.value)}
              disabled={disabled}
            />
          </div>
          <EstadoCidadeFields
            estado={getValue("estado")}
            cidade={getValue("cidade")}
            onChangeEstado={(uf) => {
              console.log('Estado selecionado:', uf);
              setValue("estado", uf);
            }}
            onChangeCidade={(nomeCidade) => setValue("cidade", nomeCidade)}
            disabled={disabled}
          />
        </div>
      </div>
    );
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle style={{ color: '#07593f' }}>
            {cliente ? "Editar Cliente" : "Novo Cliente"}
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit}>
          <Tabs defaultValue="basico" className="w-full">
            <TabsList className="grid w-full grid-cols-2">
              <TabsTrigger value="basico">Dados e Endereços</TabsTrigger>
              <TabsTrigger value="contatos">Contatos Adicionais</TabsTrigger>
            </TabsList>

            <TabsContent value="basico" className="space-y-4 mt-4">
              {/* Tipo de Pessoa */}
              <div>
                <Label htmlFor="tipo_pessoa">Tipo de Pessoa *</Label>
                <Select
                  value={formData.tipo_pessoa}
                  onValueChange={(value) => setFormData({ ...formData, tipo_pessoa: value })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="Física">Pessoa Física</SelectItem>
                    <SelectItem value="Jurídica">Pessoa Jurídica</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              {formData.tipo_pessoa === "Física" ? (
                <div className="grid md:grid-cols-2 gap-4">
                  <div>
                    <Label htmlFor="nome_completo">Nome Completo *</Label>
                    <Input
                      id="nome_completo"
                      value={formData.nome_completo}
                      onChange={(e) => setFormData({ ...formData, nome_completo: formatarNome(e.target.value) })}
                      required
                    />
                  </div>
                  <div>
                    <Label htmlFor="cpf">CPF</Label>
                    <Input
                      id="cpf"
                      value={formData.cpf}
                      onChange={(e) => setFormData({ ...formData, cpf: formatarCPF(e.target.value) })}
                      placeholder="000.000.000-00"
                      maxLength={14}
                    />
                  </div>
                </div>
              ) : (
                <>
                  <div className="grid md:grid-cols-2 gap-4">
                    <div>
                      <Label htmlFor="cnpj">CNPJ</Label>
                      <div className="flex gap-2">
                        <Input
                          id="cnpj"
                          value={formData.cnpj}
                          onChange={(e) => setFormData({ ...formData, cnpj: formatarCNPJ(e.target.value) })}
                          placeholder="00.000.000/0000-00"
                          maxLength={18}
                        />
                        <Button
                          type="button"
                          variant="outline"
                          onClick={() => buscarCNPJ(formData.cnpj)}
                          disabled={buscandoCnpj}
                        >
                          {buscandoCnpj ? <Loader2 className="w-4 h-4 animate-spin" /> : <Search className="w-4 h-4" />}
                        </Button>
                      </div>
                    </div>
                    <div>
                      <Label htmlFor="razao_social">Razão Social</Label>
                      <Input
                        id="razao_social"
                        value={formData.razao_social}
                        onChange={(e) => setFormData({ ...formData, razao_social: formatarNome(e.target.value) })}
                      />
                    </div>
                  </div>
                  <div>
                    <Label htmlFor="nome_completo">Nome Fantasia *</Label>
                    <Input
                      id="nome_completo"
                      value={formData.nome_completo}
                      onChange={(e) => setFormData({ ...formData, nome_completo: formatarNome(e.target.value) })}
                      required
                    />
                  </div>
                </>
              )}

              <div className="grid md:grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="telefone">WhatsApp *</Label>
                  <Input
                    id="telefone"
                    value={formData.telefone}
                    onChange={(e) => setFormData({ ...formData, telefone: formatarTelefone(e.target.value) })}
                    placeholder="(00) 00000-0000"
                    required
                  />
                  <p className="text-xs text-gray-500 mt-1">Este numero e usado pelo bot para envio de mensagens no WhatsApp.</p>
                </div>
                <div>
                  <Label htmlFor="email">E-mail</Label>
                  <Input
                    id="email"
                    type="email"
                    value={formData.email}
                    onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  />
                </div>
              </div>

              <div className="grid md:grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="data_nascimento" className="flex items-center gap-1">
                    <Cake className="w-4 h-4" style={{ color: '#07593f' }} />
                    Data de Nascimento
                  </Label>
                  <Input
                    id="data_nascimento"
                    type="date" lang="pt-BR"
                    value={formData.data_nascimento || ""}
                    onChange={(e) => setFormData({ ...formData, data_nascimento: e.target.value })}
                    className="mt-1"
                  />
                </div>
              </div>

              {/* Endereço do Cliente */}
              <div className="border-t pt-4 mt-4">
                <h4 className="font-semibold mb-3 flex items-center gap-2" style={{ color: '#07593f' }}>
                  <MapPin className="w-4 h-4" />
                  Endereço do Cliente
                </h4>
                {renderCamposEndereco()}
              </div>

              {/* Endereço de Entrega */}
              <div className="border-t pt-4 mt-4">
                <div className="flex items-center justify-between mb-3">
                  <h4 className="font-semibold flex items-center gap-2" style={{ color: '#07593f' }}>
                    <Truck className="w-4 h-4" />
                    Endereço de Entrega
                  </h4>
                  <div className="flex items-center gap-2">
                    <Checkbox
                      id="usar_mesmo_endereco"
                      checked={formData.usar_mesmo_endereco}
                      onCheckedChange={(checked) => {
                        setFormData(prev => ({
                          ...prev,
                          usar_mesmo_endereco: checked,
                          // Copiar dados se marcado
                          ...(checked ? {
                            endereco_entrega_cep: prev.cep,
                            endereco_entrega_rua: prev.endereco,
                            endereco_entrega_numero: prev.numero,
                            endereco_entrega_complemento: prev.complemento,
                            endereco_entrega_ponto_referencia: prev.ponto_referencia,
                            endereco_entrega_bairro: prev.bairro,
                            endereco_entrega_cidade: prev.cidade,
                            endereco_entrega_estado: prev.estado,
                          } : {})
                        }));
                      }}
                    />
                    <Label htmlFor="usar_mesmo_endereco" className="text-sm font-normal cursor-pointer">
                      Usar mesmo endereço do cliente
                    </Label>
                  </div>
                </div>

                {formData.usar_mesmo_endereco ? (
                  <div className="bg-gray-50 dark:bg-neutral-800 rounded-lg p-4 text-sm text-gray-600 dark:text-gray-400">
                    <p className="flex items-center gap-2">
                      <MapPin className="w-4 h-4 text-green-600" />
                      {formData.endereco ? (
                        <>
                          {formData.endereco}, {formData.numero}
                          {formData.complemento && ` - ${formData.complemento}`}
                          {formData.bairro && ` - ${formData.bairro}`}
                          {formData.cidade && `, ${formData.cidade}`}
                          {formData.estado && `/${formData.estado}`}
                          {formData.ponto_referencia && (
                            <span className="text-xs text-orange-600 ml-2">(Ref: {formData.ponto_referencia})</span>
                          )}
                        </>
                      ) : (
                        <span className="italic">Preencha o endereço do cliente acima</span>
                      )}
                    </p>
                  </div>
                ) : (
                  renderCamposEndereco("endereco_entrega")
                )}
              </div>

              {/* Preferências de Entrega */}
              <div className="border-t pt-4 mt-4">
                <h4 className="font-semibold mb-3 flex items-center gap-2" style={{ color: '#07593f' }}>
                  <Ban className="w-4 h-4" />
                  Restrições de Entrega
                </h4>
                <p className="text-xs text-gray-500 mb-3">
                  Marque os dias em que o cliente <strong>NÃO PODE</strong> receber entregas:
                </p>

                <div className="grid grid-cols-4 sm:grid-cols-7 gap-2 mb-4">
                  {[
                    { dia: 0, nome: 'Dom' },
                    { dia: 1, nome: 'Seg' },
                    { dia: 2, nome: 'Ter' },
                    { dia: 3, nome: 'Qua' },
                    { dia: 4, nome: 'Qui' },
                    { dia: 5, nome: 'Sex' },
                    { dia: 6, nome: 'Sáb' }
                  ].map(({ dia, nome }) => {
                    const bloqueado = formData.dias_bloqueados_entrega?.includes(dia);
                    return (
                      <RestricaoCheckbox
                        key={dia}
                        label={nome}
                        checked={bloqueado}
                        isBlockedMode={true}
                        onCheckedChange={(checked) => {
                          const atual = formData.dias_bloqueados_entrega || [];
                          const novo = checked
                            ? [...atual, dia]
                            : atual.filter(d => d !== dia);
                          setFormData({ ...formData, dias_bloqueados_entrega: novo });
                        }}
                      />
                    );
                  })}
                </div>

                <div className="flex flex-wrap items-center gap-4">
                  <Label className="text-sm text-red-700 font-bold">Turno que NÃO pode receber (Bloqueado):</Label>
                  <div className="flex gap-4">
                    {['Manhã', 'Tarde'].map((turno) => {
                      const value = turno === 'Manhã' ? 'manha' : 'tarde';
                      const bloqueado = formData.turno_bloqueado_entrega === value;
                      return (
                        <RestricaoCheckbox
                          key={turno}
                          label={turno}
                          checked={bloqueado}
                          isBlockedMode={true}
                          onCheckedChange={(checked) => {
                            setFormData({
                              ...formData,
                              turno_bloqueado_entrega: checked ? value : ""
                            });
                          }}
                        />
                      );
                    })}
                  </div>
                </div>

                {(formData.dias_bloqueados_entrega?.length > 0 || formData.turno_bloqueado_entrega) && (
                  <div className="mt-3 flex items-center gap-2 text-xs text-red-600 font-medium animate-pulse">
                    <Ban className="w-3 h-3" />
                    <span>Restrições ativas para este cliente.</span>
                  </div>
                )}
              </div>

              <div>
                <Label htmlFor="observacoes">Observações</Label>
                <Textarea
                  id="observacoes"
                  value={formData.observacoes}
                  onChange={(e) => setFormData({ ...formData, observacoes: e.target.value })}
                  rows={3}
                />
              </div>
            </TabsContent>

            <TabsContent value="contatos" className="space-y-4 mt-4">
              <div className="flex justify-between items-center">
                <h4 className="font-semibold" style={{ color: '#07593f' }}>Contatos Adicionais</h4>
                <Button type="button" onClick={adicionarContato} size="sm">
                  <Plus className="w-4 h-4 mr-1" />
                  Adicionar
                </Button>
              </div>

              {formData.contatos.length === 0 ? (
                <p className="text-center py-8" style={{ color: '#8B8B8B' }}>
                  Nenhum contato adicional cadastrado
                </p>
              ) : (
                <div className="space-y-4">
                  {formData.contatos.map((contato, index) => (
                    <div key={index} className="border rounded-lg p-4" style={{ borderColor: '#E5E0D8' }}>
                      <div className="flex justify-between items-center mb-3">
                        <Badge>Contato {index + 1}</Badge>
                        <Button
                          type="button"
                          variant="ghost"
                          size="sm"
                          onClick={() => removerContato(index)}
                          className="text-red-600"
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      </div>
                      <div className="grid md:grid-cols-2 gap-3">
                        <Input
                          placeholder="Nome"
                          value={contato.nome}
                          onChange={(e) => atualizarContato(index, 'nome', e.target.value)}
                        />
                        <Input
                          placeholder="Telefone"
                          value={contato.telefone}
                          onChange={(e) => atualizarContato(index, 'telefone', e.target.value)}
                        />
                        <Input
                          placeholder="E-mail"
                          value={contato.email}
                          onChange={(e) => atualizarContato(index, 'email', e.target.value)}
                        />
                        <Input
                          placeholder="Tipo (ex: Trabalho, Pessoal)"
                          value={contato.tipo}
                          onChange={(e) => atualizarContato(index, 'tipo', e.target.value)}
                        />
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </TabsContent>
          </Tabs>

          <DialogFooter className="mt-6">
            <Button type="button" variant="outline" onClick={onClose}>
              Cancelar
            </Button>
            <Button
              type="submit"
              disabled={isLoading}
              style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
            >
              {isLoading ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Salvando...
                </>
              ) : (
                cliente ? "Atualizar" : "Cadastrar"
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { base44 } from "@/api/base44Client";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Plus, Trash2, Target, AlertCircle } from "lucide-react";
import { calcularComissaoTiered } from "@/services/comissaoTiersService";

const EMPTY_FAIXA = () => ({
  _key: crypto.randomUUID(),
  percentual_meta_min: "",
  percentual_comissao: "",
  base_calculo: "liquido",
});

export function ModalNiveisComissao({
  vendedor,
  organizationId,
  niveisComissao,
  niveisComissaoFaixas,
  onClose,
  onSaved,
}) {
  const queryClient = useQueryClient();

  const nivelExistente = niveisComissao.find(
    (n) => n.vendedor_id === vendedor.id && n.ativo !== false
  );

  const [meta, setMeta] = useState(
    nivelExistente?.meta_mensal ?? vendedor.meta_mensal ?? ""
  );
  const [faixas, setFaixas] = useState(() => {
    if (nivelExistente) {
      const rows = niveisComissaoFaixas
        .filter((f) => f.nivel_comissao_id === nivelExistente.id)
        .sort((a, b) => (a.ordem ?? 0) - (b.ordem ?? 0));
      return rows.length > 0
        ? rows.map((f) => ({ ...f, _key: f.id }))
        : [EMPTY_FAIXA()];
    }
    return [EMPTY_FAIXA()];
  });
  const [saving, setSaving] = useState(false);
  const [erro, setErro] = useState("");

  function addFaixa() {
    setFaixas((prev) => [...prev, EMPTY_FAIXA()]);
  }

  function removeFaixa(key) {
    setFaixas((prev) => prev.filter((f) => f._key !== key));
  }

  function updateFaixa(key, field, value) {
    setFaixas((prev) =>
      prev.map((f) => (f._key === key ? { ...f, [field]: value } : f))
    );
  }

  // Preview de exemplo a 110% da meta
  const faixasValidas = faixas.filter(
    (f) => f.percentual_meta_min !== "" && f.percentual_comissao !== ""
  );
  const previewMeta = Number(meta) || 0;
  const previewBruto = previewMeta > 0 ? previewMeta * 1.1 : 0;
  const preview = previewMeta > 0 && faixasValidas.length > 0
    ? calcularComissaoTiered({
        vendasBrutas: previewBruto,
        vendasLiquidas: previewBruto * 0.96,
        meta: previewMeta,
        faixas: faixasValidas.map((f) => ({
          ...f,
          percentual_meta_min: Number(f.percentual_meta_min),
          percentual_comissao: Number(f.percentual_comissao),
        })),
      })
    : null;

  async function handleSave() {
    setErro("");
    const metaNum = Number(meta);
    if (!metaNum || metaNum <= 0) {
      setErro("Informe uma meta válida (maior que zero).");
      return;
    }
    for (const f of faixas) {
      if (f.percentual_meta_min === "" || f.percentual_comissao === "") {
        setErro("Preencha todos os campos de cada faixa.");
        return;
      }
      if (Number(f.percentual_meta_min) < 0 || Number(f.percentual_comissao) < 0) {
        setErro("Percentuais não podem ser negativos.");
        return;
      }
    }

    setSaving(true);
    try {
      let nivelId;

      if (nivelExistente) {
        await base44.entities.NivelComissao.update(nivelExistente.id, {
          meta_mensal: metaNum,
          updated_at: new Date().toISOString(),
        });
        nivelId = nivelExistente.id;
      } else {
        const novo = await base44.entities.NivelComissao.create({
          organization_id: organizationId,
          vendedor_id: vendedor.id,
          nome: `Comissão — ${vendedor.nome}`,
          meta_mensal: metaNum,
          ativo: true,
        });
        nivelId = novo.id;
      }

      // Deletar faixas antigas e recriar
      const faixasAntigas = niveisComissaoFaixas.filter(
        (f) => f.nivel_comissao_id === nivelId
      );
      await Promise.all(
        faixasAntigas.map((f) => base44.entities.NivelComissaoFaixa.delete(f.id))
      );
      await Promise.all(
        faixas.map((f, idx) =>
          base44.entities.NivelComissaoFaixa.create({
            nivel_comissao_id: nivelId,
            percentual_meta_min: Number(f.percentual_meta_min),
            percentual_comissao: Number(f.percentual_comissao),
            base_calculo: f.base_calculo || "liquido",
            ordem: idx,
          })
        )
      );

      // Sync meta no registro do vendedor
      if (vendedor.meta_mensal !== metaNum) {
        await base44.entities.Vendedor.update(vendedor.id, {
          meta_mensal: metaNum,
        });
      }

      queryClient.invalidateQueries({ queryKey: ["niveis-comissao"] });
      queryClient.invalidateQueries({ queryKey: ["niveis-comissao-faixas"] });
      queryClient.invalidateQueries({ queryKey: ["vendedores"] });
      onSaved?.();
      onClose();
    } catch (e) {
      setErro("Erro ao salvar: " + (e.message || String(e)));
    } finally {
      setSaving(false);
    }
  }

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Target className="w-5 h-5 text-green-700" />
            Configurar Comissão por Faixas — {vendedor.nome}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-5 py-2">
          {/* Aviso de política */}
          <div className="flex items-start gap-2 p-3 rounded-lg bg-amber-50 border border-amber-200">
            <AlertCircle className="w-4 h-4 text-amber-600 mt-0.5 shrink-0" />
            <p className="text-sm text-amber-800">
              Apenas gerentes e administradores podem configurar metas. A meta
              pode ser alterada para o mês atual ou futuro — não é possível
              alterar comissões de meses já fechados.
            </p>
          </div>

          {/* Meta mensal */}
          <div className="space-y-1">
            <Label htmlFor="meta-input">Meta Mensal (R$)</Label>
            <Input
              id="meta-input"
              type="number"
              min="0"
              step="100"
              placeholder="Ex.: 50000"
              value={meta}
              onChange={(e) => setMeta(e.target.value)}
            />
          </div>

          {/* Faixas */}
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <Label>Faixas de Comissão</Label>
              <Button
                type="button"
                size="sm"
                variant="outline"
                onClick={addFaixa}
                className="flex items-center gap-1"
              >
                <Plus className="w-3 h-3" />
                Adicionar Faixa
              </Button>
            </div>

            {/* Cabeçalho */}
            <div className="grid grid-cols-[1fr_1fr_1fr_auto] gap-2 px-1">
              <span className="text-xs text-gray-500">Meta atingida (%)</span>
              <span className="text-xs text-gray-500">Comissão (%)</span>
              <span className="text-xs text-gray-500">Base de cálculo</span>
              <span />
            </div>

            {faixas.map((faixa) => (
              <div
                key={faixa._key}
                className="grid grid-cols-[1fr_1fr_1fr_auto] gap-2 items-center"
              >
                <div className="relative">
                  <Input
                    type="number"
                    min="0"
                    max="999"
                    step="1"
                    placeholder="Ex.: 80"
                    value={faixa.percentual_meta_min}
                    onChange={(e) =>
                      updateFaixa(faixa._key, "percentual_meta_min", e.target.value)
                    }
                  />
                  <span className="absolute right-3 top-2 text-gray-400 text-sm pointer-events-none">
                    %
                  </span>
                </div>
                <div className="relative">
                  <Input
                    type="number"
                    min="0"
                    max="100"
                    step="0.1"
                    placeholder="Ex.: 3"
                    value={faixa.percentual_comissao}
                    onChange={(e) =>
                      updateFaixa(faixa._key, "percentual_comissao", e.target.value)
                    }
                  />
                  <span className="absolute right-3 top-2 text-gray-400 text-sm pointer-events-none">
                    %
                  </span>
                </div>
                <Select
                  value={faixa.base_calculo}
                  onValueChange={(v) => updateFaixa(faixa._key, "base_calculo", v)}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="liquido">Líquido</SelectItem>
                    <SelectItem value="bruto">Bruto</SelectItem>
                  </SelectContent>
                </Select>
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  onClick={() => removeFaixa(faixa._key)}
                  disabled={faixas.length === 1}
                  className="text-red-400 hover:text-red-600"
                >
                  <Trash2 className="w-4 h-4" />
                </Button>
              </div>
            ))}

            <p className="text-xs text-gray-500 mt-1">
              A faixa ativa é a de maior "Meta atingida %" que o vendedor ainda
              alcançou. Ex.: se atingiu 105%, aplica a faixa de 100% (não a
              de 80%).
            </p>
          </div>

          {/* Preview */}
          {preview && previewMeta > 0 && (
            <div className="p-4 rounded-lg border border-green-200 bg-green-50 space-y-1">
              <p className="text-sm font-semibold text-green-800">
                Exemplo: vendas a 110% da meta (R${" "}
                {previewBruto.toLocaleString("pt-BR", {
                  minimumFractionDigits: 2,
                })}
                )
              </p>
              {preview.faixaAplicada ? (
                <div className="flex items-center gap-3 flex-wrap">
                  <Badge className="bg-green-100 text-green-700">
                    Faixa {">"}= {preview.faixaAplicada.percentual_meta_min}%
                  </Badge>
                  <Badge className="bg-green-100 text-green-700">
                    {preview.percentualComissao}%{" "}
                    {preview.faixaAplicada.base_calculo === "bruto"
                      ? "bruto"
                      : "líquido"}
                  </Badge>
                  <span className="font-bold text-green-700">
                    Comissão:{" "}
                    R${" "}
                    {preview.valorComissao.toLocaleString("pt-BR", {
                      minimumFractionDigits: 2,
                    })}
                  </span>
                </div>
              ) : (
                <p className="text-sm text-gray-500">
                  Nenhuma faixa se aplica a este exemplo.
                </p>
              )}
            </div>
          )}

          {/* Erro */}
          {erro && (
            <p className="text-sm text-red-600 flex items-center gap-1">
              <AlertCircle className="w-4 h-4" />
              {erro}
            </p>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={onClose} disabled={saving}>
            Cancelar
          </Button>
          <Button
            onClick={handleSave}
            disabled={saving}
            style={{ backgroundColor: "#07593f" }}
            className="text-white hover:opacity-90"
          >
            {saving ? "Salvando..." : "Salvar Configuração"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Store, Loader2 } from "lucide-react";
import { useAuth } from "@/hooks/useAuth";
import { useLojas } from "@/hooks/useLojas";

export default function StoreSelectorModal() {
    const { user, selectedStore, setSelectedStore, loading } = useAuth();
    const { data: lojas = [], isLoading: fetching } = useLojas();

    // Derived state: Modal MUST be open if user is admin/manager (no fixed loja) and hasn't selected a store yet.
    // Roles that require a store context:
    const ROLES_REQUIRING_STORE = ['Administrador', 'Gerente Geral', 'Gerente', 'Vendedor'];
    const isOpen = !loading && !!user && !user.loja && !selectedStore && ROLES_REQUIRING_STORE.includes(user.cargo);

    useEffect(() => {
        // Mantido para preservar comportamento de abertura controlada.
    }, [isOpen]);

    const handleSelect = (lojaNome) => {
        setSelectedStore(lojaNome);
    };

    const handleOpenChange = (newOpen) => {
        // Prevent closing if we are in the "forced selection" state
        if (!newOpen && isOpen) {
            return;
        }
    };

    return (
        <Dialog open={isOpen} onOpenChange={handleOpenChange}>
            <DialogContent className="sm:max-w-md" onPointerDownOutside={(e) => e.preventDefault()} onEscapeKeyDown={(e) => e.preventDefault()}>
                <DialogHeader>
                    <DialogTitle className="flex items-center gap-2">
                        <Store className="w-5 h-5" /> Selecione a Loja de Operação
                    </DialogTitle>
                </DialogHeader>

                <div className="py-4">
                    <p className="text-sm text-gray-500 mb-4">
                        Você está logado como Administrador/Gerente sem loja fixa.
                        Por favor, selecione em qual unidade deseja operar agora.
                    </p>

                    {fetching ? (
                        <div className="flex justify-center py-8">
                            <Loader2 className="w-8 h-8 animate-spin text-gray-400" />
                        </div>
                    ) : lojas.length === 0 ? (
                        <div className="py-6 text-sm text-gray-500">
                            Nenhuma loja cadastrada ativa em Configurações.
                        </div>
                    ) : (
                        <div className="grid grid-cols-2 gap-3">
                            {lojas.map(loja => (
                                <Button
                                    key={loja.id}
                                    variant="outline"
                                    className="h-24 flex flex-col items-center justify-center gap-2 border-2 hover:border-green-500 hover:bg-green-50 text-wrap transition-all"
                                    onClick={() => handleSelect(loja.nome)}
                                >
                                    <Store className="w-6 h-6 text-gray-500" />
                                    <span className="font-semibold">{loja.nome}</span>
                                </Button>
                            ))}
                        </div>
                    )}
                </div>
            </DialogContent>
        </Dialog>
    );
}

import React, { useState } from 'react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Loader2, CheckCircle, XCircle } from 'lucide-react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';
import { comprasService } from '@/services/comprasService';
import { useAuth } from '@/hooks/useAuth';

/**
 * Modal para Aprovação de OCs
 * Permite aprovar ou rejeitar uma OC com comentários
 */
export default function ApprovalModal({
  isOpen,
  onClose,
  oc = null,
  onSuccess,
}) {
  const queryClient = useQueryClient();
  const { user } = useAuth();
  const [action, setAction] = useState(null); // 'approve' or 'reject'
  const [comentarios, setComentarios] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleActionChange = (newAction) => {
    setAction(newAction);
    setComentarios('');
  };

  // Mutation: Aprovar OC
  const approveMutation = useMutation({
    mutationFn: async () => {
      setIsLoading(true);
      try {
        await comprasService.approveOc(oc.id, {
          comments: comentarios || 'Aprovado',
          approved_by: user?.id
        });
        toast.success(`OC ${oc.numero_pedido} aprovada com sucesso`);
        return true;
      } finally {
        setIsLoading(false);
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['compras'] });
      setAction(null);
      setComentarios('');
      onSuccess?.();
      onClose();
    },
    onError: (error) => {
      toast.error(`Erro ao aprovar OC: ${error.message}`);
    },
  });

  // Mutation: Rejeitar OC
  const rejectMutation = useMutation({
    mutationFn: async () => {
      setIsLoading(true);
      try {
        await comprasService.rejectOc(oc.id, {
          comments: comentarios || 'Rejeitado',
          rejected_by: user?.id
        });
        toast.success(`OC ${oc.numero_pedido} rejeitada`);
        return true;
      } finally {
        setIsLoading(false);
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['compras'] });
      setAction(null);
      setComentarios('');
      onSuccess?.();
      onClose();
    },
    onError: (error) => {
      toast.error(`Erro ao rejeitar OC: ${error.message}`);
    },
  });

  const handleApprove = async () => {
    if (!comentarios.trim()) {
      toast.warning('Por favor, adicione um comentário');
      return;
    }
    await approveMutation.mutateAsync();
  };

  const handleReject = async () => {
    if (!comentarios.trim()) {
      toast.warning('Por favor, adicione um motivo da rejeição');
      return;
    }
    await rejectMutation.mutateAsync();
  };

  const isProcessing = isLoading || approveMutation.isPending || rejectMutation.isPending;

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-xl">
        <DialogHeader>
          <DialogTitle className="text-lg">
            Aprovação de Ordem de Compra
          </DialogTitle>
          <DialogDescription>
            OC #{oc?.numero_pedido} - Fornecedor: {oc?.fornecedor_nome}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-6">
          {/* Detalhes da OC */}
          <div className="bg-slate-50 rounded-lg p-4 space-y-2 text-sm">
            <div className="flex justify-between">
              <span className="text-slate-600">Valor Total:</span>
              <span className="font-semibold">R$ {(oc?.valor_total || 0).toFixed(2)}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-slate-600">Data Previsão:</span>
              <span>{oc?.data_previsao_entrega ? new Date(oc.data_previsao_entrega).toLocaleDateString('pt-BR') : '-'}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-slate-600">Itens:</span>
              <span>{oc?.itens?.length || 0} produto(s)</span>
            </div>
          </div>

          {/* Seleção de Ação */}
          <div className="space-y-3">
            <label className="block text-sm font-semibold">O que você deseja fazer?</label>
            <div className="grid grid-cols-2 gap-3">
              <button
                onClick={() => handleActionChange('approve')}
                className={`flex items-center justify-center gap-2 p-3 rounded-lg border-2 transition-all ${
                  action === 'approve'
                    ? 'border-green-500 bg-green-50'
                    : 'border-slate-200 hover:border-green-300'
                }`}
              >
                <CheckCircle className="w-5 h-5 text-green-600" />
                <span className="font-medium">Aprovar</span>
              </button>

              <button
                onClick={() => handleActionChange('reject')}
                className={`flex items-center justify-center gap-2 p-3 rounded-lg border-2 transition-all ${
                  action === 'reject'
                    ? 'border-red-500 bg-red-50'
                    : 'border-slate-200 hover:border-red-300'
                }`}
              >
                <XCircle className="w-5 h-5 text-red-600" />
                <span className="font-medium">Rejeitar</span>
              </button>
            </div>
          </div>

          {/* Comentários */}
          {action && (
            <div className="space-y-2">
              <label className="block text-sm font-semibold">
                {action === 'approve' ? 'Comentários de Aprovação' : 'Motivo da Rejeição'}
              </label>
              <Textarea
                placeholder={action === 'approve' 
                  ? 'Ex: Verificado orçamento, confere com requisição...' 
                  : 'Ex: Valor fora do orçamento, prazo inadequado...'}
                value={comentarios}
                onChange={(e) => setComentarios(e.target.value)}
                className="min-h-24 text-sm"
              />
              <p className="text-xs text-slate-500">
                {comentarios.length}/500 caracteres
              </p>
            </div>
          )}
        </div>

        <DialogFooter className="flex gap-2 justify-end">
          <Button variant="outline" onClick={onClose} disabled={isProcessing}>
            Cancelar
          </Button>

          {action === 'approve' && (
            <Button 
              onClick={handleApprove} 
              disabled={isProcessing || !comentarios.trim()}
              className="bg-green-600 hover:bg-green-700"
            >
              {isProcessing ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Aprovando...
                </>
              ) : (
                'Aprovar'
              )}
            </Button>
          )}

          {action === 'reject' && (
            <Button 
              onClick={handleReject} 
              disabled={isProcessing || !comentarios.trim()}
              variant="destructive"
            >
              {isProcessing ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Rejeitando...
                </>
              ) : (
                'Rejeitar'
              )}
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { useEffect, useRef, useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectTrigger, SelectContent, SelectItem, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { base44 } from "@/lib/supabase";
import { Paperclip, CheckCircle, Loader2, Send } from "lucide-react";
import { toast } from "sonner";

export default function CriarLancamentoFromOcModal({ oc, open, onClose, categorias }) {
  const ocAtual = oc || null;
  const [form, setForm] = useState({
    categoria_id: "",
    descricao: `Compra OC #${ocAtual?.numero_pedido || ""}`,
    data_vencimento: "",
    forma_pagamento: ocAtual?.forma_pagamento_oc || "",
    observacao: "",
    detalhe_devolucao: "",
    anexo_url: "",
  });
  const [uploading, setUploading] = useState(false);
  const [anexoNome, setAnexoNome] = useState("");
  const [error, setError] = useState("");
  const fileInputRef = useRef(null);
  const queryClient = useQueryClient();

  useEffect(() => {
    if (!open || !ocAtual) return;
    setForm({
      categoria_id: "",
      descricao: `Compra OC #${ocAtual.numero_pedido || ""}`,
      data_vencimento: "",
      forma_pagamento: ocAtual.forma_pagamento_oc || "",
      observacao: "",
      detalhe_devolucao: "",
      anexo_url: "",
    });
    setUploading(false);
    setAnexoNome("");
    setError("");
  }, [open, ocAtual]);

  const mutation = useMutation({
    mutationFn: async () => {
      const solicitacao = {
        categoria_id: form.categoria_id,
        categoria_nome: categorias.find(c => c.id === form.categoria_id)?.nome || "",
        descricao: form.descricao,
        valor: ocAtual.valor_total,
        data_vencimento: form.data_vencimento,
        forma_pagamento: form.forma_pagamento,
        observacao: form.observacao,
        detalhe_devolucao: form.detalhe_devolucao,
        anexo_url: form.anexo_url,
        anexo_nome: anexoNome,
        solicitado_em: new Date().toISOString(),
      };
      const anexosAtuais = Array.isArray(ocAtual.anexos_financeiro) ? ocAtual.anexos_financeiro : [];
      await base44.entities.ComprasOrden.update(ocAtual.id, {
        pagamento_status: "pendente_aprovacao",
        observacoes_aprovacao: form.detalhe_devolucao || form.observacao || null,
        anexos_financeiro: [...anexosAtuais, { url: form.anexo_url, nome: anexoNome, data: new Date().toISOString() }],
        metadata: {
          ...(ocAtual.metadata || {}),
          solicitacao_financeiro: solicitacao,
        },
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["compras"] });
      toast.success("Solicitação enviada para aprovação do setor financeiro.");
      onClose();
    },
    onError: (err) => setError(err?.message || "Erro ao enviar solicitação."),
  });

  const handleFileUpload = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    setError("");
    try {
      const { file_url } = await base44.integrations.Core.UploadFile({ file });
      setForm(f => ({ ...f, anexo_url: file_url }));
      setAnexoNome(file.name);
    } catch {
      setError("Erro ao enviar o arquivo. Tente novamente.");
    } finally {
      setUploading(false);
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setError("");
    if (!ocAtual) return setError("Nenhuma ordem de compra foi selecionada.");
    if (!form.anexo_url) return setError("Anexe o comprovante de devolução do fabricante antes de continuar.");
    mutation.mutate();
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Solicitar Aprovação Financeira</DialogTitle>
          <DialogDescription>
            Anexe o comprovante de devolução do fabricante e informe os detalhes. A solicitação será enviada ao setor financeiro para aprovação e geração do lançamento.
          </DialogDescription>
        </DialogHeader>
        {!ocAtual ? (
          <div className="rounded-md border border-dashed p-4 text-sm text-muted-foreground">
            Selecione uma ordem de compra para criar a solicitação.
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-3">
            <div>
              <label className="block text-xs font-medium">Ordem de Compra</label>
              <Input value={ocAtual.numero_pedido} readOnly className="bg-gray-100" />
            </div>
            <div>
              <label className="block text-xs font-medium">Fornecedor</label>
              <Input value={ocAtual.fornecedor_nome} readOnly className="bg-gray-100" />
            </div>
            <div>
              <label className="block text-xs font-medium">Valor Total</label>
              <Input
                value={Number(ocAtual.valor_total || 0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" })}
                readOnly
                className="bg-gray-100"
              />
            </div>

            {/* Anexo de devolução — obrigatório */}
            <div className="rounded-md border border-dashed p-3 space-y-2">
              <label className="block text-xs font-semibold text-gray-700">
                Comprovante de Devolução do Fabricante <span className="text-red-500">*</span>
              </label>
              <p className="text-xs text-muted-foreground">
                A solicitação só poderá ser enviada após o envio do comprovante.
              </p>
              <input
                ref={fileInputRef}
                type="file"
                accept="image/*,.pdf,.doc,.docx,.xls,.xlsx"
                className="hidden"
                onChange={handleFileUpload}
              />
              {form.anexo_url ? (
                <div className="flex items-center gap-2 text-sm text-green-700 font-medium">
                  <CheckCircle className="w-4 h-4 shrink-0" />
                  <span className="truncate">{anexoNome || "Arquivo enviado"}</span>
                  <button
                    type="button"
                    className="ml-auto text-xs text-muted-foreground underline hover:text-gray-700"
                    onClick={() => { setForm(f => ({ ...f, anexo_url: "" })); setAnexoNome(""); if (fileInputRef.current) fileInputRef.current.value = ""; }}
                  >
                    Trocar
                  </button>
                </div>
              ) : (
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  disabled={uploading}
                  onClick={() => fileInputRef.current?.click()}
                  className="w-full"
                >
                  {uploading ? (
                    <><Loader2 className="w-4 h-4 mr-2 animate-spin" />Enviando...</>
                  ) : (
                    <><Paperclip className="w-4 h-4 mr-2" />Selecionar arquivo</>
                  )}
                </Button>
              )}
            </div>

            <div>
              <label className="block text-xs font-medium">Detalhe da Devolução</label>
              <Textarea
                placeholder="Descreva o motivo e os detalhes da devolução..."
                value={form.detalhe_devolucao}
                onChange={e => setForm(f => ({ ...f, detalhe_devolucao: e.target.value }))}
                rows={3}
              />
            </div>

            <div>
              <label className="block text-xs font-medium">Categoria sugerida</label>
              <Select value={form.categoria_id} onValueChange={v => setForm(f => ({ ...f, categoria_id: v }))}>
                <SelectTrigger>
                  <SelectValue placeholder="Selecione (opcional)" />
                </SelectTrigger>
                <SelectContent>
                  {categorias.map(cat => (
                    <SelectItem key={cat.id} value={cat.id}>{cat.nome}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div>
              <label className="block text-xs font-medium">Descrição do lançamento</label>
              <Input value={form.descricao} onChange={e => setForm(f => ({ ...f, descricao: e.target.value }))} />
            </div>

            <div>
              <label className="block text-xs font-medium">Data de vencimento sugerida</label>
              <Input
                type="date"
                lang="pt-BR"
                value={form.data_vencimento}
                onChange={e => setForm(f => ({ ...f, data_vencimento: e.target.value }))}
              />
            </div>

            <div>
              <label className="block text-xs font-medium">Forma de Pagamento</label>
              <Input
                value={form.forma_pagamento}
                onChange={e => setForm(f => ({ ...f, forma_pagamento: e.target.value }))}
              />
            </div>

            <div>
              <label className="block text-xs font-medium">Observação</label>
              <Textarea
                value={form.observacao}
                onChange={e => setForm(f => ({ ...f, observacao: e.target.value }))}
              />
            </div>

            {error && <div className="text-red-600 text-xs">{error}</div>}

            <div className="flex justify-end">
              <Button
                type="submit"
                disabled={mutation.isPending || uploading || !form.anexo_url}
                title={!form.anexo_url ? "Anexe o comprovante de devolução para continuar" : undefined}
              >
                {mutation.isPending ? (
                  <><Loader2 className="w-4 h-4 mr-2 animate-spin" />Enviando...</>
                ) : (
                  <><Send className="w-4 h-4 mr-2" />Enviar para Aprovação</>
                )}
              </Button>
            </div>
          </form>
        )}
      </DialogContent>
    </Dialog>
  );
}

import { useState } from 'react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Loader2, Paperclip, Plus, Trash2, CheckCircle, Lock } from 'lucide-react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';
import { comprasService } from '@/services/comprasService';
import { useAuth } from '@/hooks/useAuth';

const FORMAS_PAGAMENTO = [
  { value: 'a_vista', label: 'A Vista' },
  { value: 'pix', label: 'PIX' },
  { value: 'boleto', label: 'Boleto' },
  { value: 'parcelado', label: 'Parcelado' },
  { value: 'cartao_debito', label: 'Cartão Débito' },
  { value: 'cartao_credito', label: 'Cartão Crédito' },
  { value: 'transferencia', label: 'Transferência Bancária' },
  { value: 'cheque', label: 'Cheque' },
  { value: 'multiplo', label: 'Múltiplas Formas' },
  { value: 'outro', label: 'Outro' },
];

function FormaPagamentoLabel({ value }) {
  const found = FORMAS_PAGAMENTO.find(f => f.value === value);
  return found ? found.label : value || 'Não informado';
}

/**
 * Modal exclusivo do master para aprovar e registrar pagamento de OC
 */
export default function PaymentApprovalModal({ isOpen, onClose, oc }) {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  const [formaMultipla, setFormaMultipla] = useState(false);
  const [formasMultiplas, setFormasMultiplas] = useState([
    { metodo: '', valor: '', parcelas: '', observacao: '' },
  ]);
  const [formData, setFormData] = useState({
    pagamento_forma_final: '',
    pagamento_parcelas: '',
    pagamento_valor_pago: '',
    pagamento_data_pagamento: '',
    pagamento_observacoes: '',
  });

  const valorTotalOc = oc?.valor_total || 0;

  const handleAddForma = () => {
    setFormasMultiplas(prev => [...prev, { metodo: '', valor: '', parcelas: '', observacao: '' }]);
  };

  const handleRemoveForma = (idx) => {
    setFormasMultiplas(prev => prev.filter((_, i) => i !== idx));
  };

  const handleFormaChange = (idx, field, value) => {
    setFormasMultiplas(prev => prev.map((item, i) => i === idx ? { ...item, [field]: value } : item));
  };

  const precisaParcelas = (forma) =>
    ['parcelado', 'cartao_credito'].includes(forma);

  const approveMutation = useMutation({
    mutationFn: async () => {
      if (!formaMultipla && !formData.pagamento_forma_final) {
        throw new Error('Selecione a forma de pagamento');
      }
      if (formaMultipla && formasMultiplas.some(f => !f.metodo || !f.valor)) {
        throw new Error('Preencha método e valor em todas as formas de pagamento');
      }

      const payload = {
        aprovado_por: user?.id || null,
        pagamento_observacoes: formData.pagamento_observacoes || null,
        pagamento_data_pagamento: formData.pagamento_data_pagamento || null,
        pagamento_valor_pago: formData.pagamento_valor_pago ? parseFloat(formData.pagamento_valor_pago) : null,
      };

      if (formaMultipla) {
        payload.pagamento_forma_final = 'multiplo';
        payload.pagamento_formas_multiplas = formasMultiplas.map(f => ({
          metodo: f.metodo,
          valor: parseFloat(f.valor) || 0,
          parcelas: f.parcelas ? parseInt(f.parcelas) : null,
          observacao: f.observacao || null,
        }));
      } else {
        payload.pagamento_forma_final = formData.pagamento_forma_final;
        payload.pagamento_parcelas = formData.pagamento_parcelas ? parseInt(formData.pagamento_parcelas) : null;
        payload.pagamento_formas_multiplas = [];
      }

      return await comprasService.approvePayment(oc.id, payload);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['compras'] });
      toast.success(`Pagamento da OC ${oc?.numero_pedido} registrado com sucesso`);
      onClose();
    },
    onError: (error) => {
      toast.error(`Erro ao registrar pagamento: ${error.message}`);
    },
  });

  if (!oc) return null;

  const anexosAprovacao = oc.anexos_aprovacao || [];
  const observacoesAprovacao = oc.observacoes_aprovacao;

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <CheckCircle className="w-5 h-5 text-green-600" />
            Aprovar Pagamento — {oc.numero_pedido}
          </DialogTitle>
          <DialogDescription>
            {oc.fornecedor_nome} · R$ {(valorTotalOc).toLocaleString('pt-BR', { minimumFractionDigits: 2 })} · Forma solicitada:{' '}
            <strong><FormaPagamentoLabel value={oc.forma_pagamento_oc} /></strong>
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-5">
          {/* Seção: Observações do comprador (somente leitura) */}
          {(observacoesAprovacao || anexosAprovacao.length > 0) && (
            <div className="rounded-lg border border-amber-200 bg-amber-50/60 p-4 space-y-3">
              <div className="flex items-center gap-2">
                <Lock className="w-4 h-4 text-amber-600" />
                <span className="text-xs font-bold uppercase tracking-widest text-amber-700">
                  Informações enviadas pelo comprador
                </span>
              </div>
              {observacoesAprovacao && (
                <p className="text-sm text-gray-700 whitespace-pre-wrap">{observacoesAprovacao}</p>
              )}
              {anexosAprovacao.length > 0 && (
                <div className="flex flex-wrap gap-2">
                  {anexosAprovacao.map((anexo, idx) => (
                    <a
                      key={idx}
                      href={anexo.url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="flex items-center gap-1 bg-white border rounded px-2 py-1 text-xs text-blue-600 hover:underline"
                    >
                      <Paperclip className="w-3 h-3" />
                      {anexo.nome || `Anexo ${idx + 1}`}
                    </a>
                  ))}
                </div>
              )}
            </div>
          )}

          {/* Toggle: múltiplas formas */}
          <div className="flex items-center gap-3">
            <input
              type="checkbox"
              id="formaMultipla"
              checked={formaMultipla}
              onChange={(e) => setFormaMultipla(e.target.checked)}
              className="w-4 h-4 accent-green-600"
            />
            <Label htmlFor="formaMultipla" className="cursor-pointer">
              Pagamento em múltiplas formas
            </Label>
          </div>

          {/* Forma única */}
          {!formaMultipla && (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <Label>Forma de Pagamento Final *</Label>
                <Select
                  value={formData.pagamento_forma_final}
                  onValueChange={(v) => setFormData(prev => ({ ...prev, pagamento_forma_final: v }))}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Selecione..." />
                  </SelectTrigger>
                  <SelectContent>
                    {FORMAS_PAGAMENTO.filter(f => f.value !== 'multiplo').map(f => (
                      <SelectItem key={f.value} value={f.value}>{f.label}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              {precisaParcelas(formData.pagamento_forma_final) && (
                <div>
                  <Label>Número de Parcelas</Label>
                  <Input
                    type="number"
                    min="1"
                    placeholder="Ex: 3"
                    value={formData.pagamento_parcelas}
                    onChange={(e) => setFormData(prev => ({ ...prev, pagamento_parcelas: e.target.value }))}
                  />
                </div>
              )}
            </div>
          )}

          {/* Múltiplas formas */}
          {formaMultipla && (
            <div className="space-y-3">
              <Label className="text-sm font-semibold">Formas de Pagamento</Label>
              {formasMultiplas.map((f, idx) => (
                <div key={idx} className="grid grid-cols-12 gap-2 items-start border rounded-lg p-3 bg-gray-50">
                  <div className="col-span-4">
                    <Label className="text-xs">Método</Label>
                    <Select
                      value={f.metodo}
                      onValueChange={(v) => handleFormaChange(idx, 'metodo', v)}
                    >
                      <SelectTrigger className="h-8 text-sm">
                        <SelectValue placeholder="Selecione..." />
                      </SelectTrigger>
                      <SelectContent>
                        {FORMAS_PAGAMENTO.filter(fp => fp.value !== 'multiplo').map(fp => (
                          <SelectItem key={fp.value} value={fp.value}>{fp.label}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="col-span-3">
                    <Label className="text-xs">Valor (R$)</Label>
                    <Input
                      type="number"
                      step="0.01"
                      min="0"
                      placeholder="0,00"
                      className="h-8 text-sm"
                      value={f.valor}
                      onChange={(e) => handleFormaChange(idx, 'valor', e.target.value)}
                    />
                  </div>
                  {precisaParcelas(f.metodo) && (
                    <div className="col-span-2">
                      <Label className="text-xs">Parcelas</Label>
                      <Input
                        type="number"
                        min="1"
                        placeholder="1"
                        className="h-8 text-sm"
                        value={f.parcelas}
                        onChange={(e) => handleFormaChange(idx, 'parcelas', e.target.value)}
                      />
                    </div>
                  )}
                  <div className={precisaParcelas(f.metodo) ? 'col-span-2' : 'col-span-4'}>
                    <Label className="text-xs">Observação</Label>
                    <Input
                      placeholder="Opcional"
                      className="h-8 text-sm"
                      value={f.observacao}
                      onChange={(e) => handleFormaChange(idx, 'observacao', e.target.value)}
                    />
                  </div>
                  <div className="col-span-1 flex items-end pb-1">
                    {formasMultiplas.length > 1 && (
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        onClick={() => handleRemoveForma(idx)}
                        className="h-8 w-8 p-0 text-red-500 hover:text-red-700"
                      >
                        <Trash2 className="w-3 h-3" />
                      </Button>
                    )}
                  </div>
                </div>
              ))}
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={handleAddForma}
                className="gap-1"
              >
                <Plus className="w-3 h-3" />
                Adicionar forma
              </Button>
              {/* Total das formas múltiplas */}
              <div className="flex justify-between text-sm font-semibold border-t pt-2">
                <span>Total informado:</span>
                <span className={
                  Math.abs(formasMultiplas.reduce((sum, f) => sum + (parseFloat(f.valor) || 0), 0) - valorTotalOc) < 0.01
                    ? 'text-green-600'
                    : 'text-red-600'
                }>
                  R$ {formasMultiplas.reduce((sum, f) => sum + (parseFloat(f.valor) || 0), 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                  {' '}/ R$ {valorTotalOc.toLocaleString('pt-BR', { minimumFractionDigits: 2 })} (total OC)
                </span>
              </div>
            </div>
          )}

          {/* Campos comuns */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <Label>Valor Pago (R$)</Label>
              <Input
                type="number"
                step="0.01"
                min="0"
                placeholder={valorTotalOc.toFixed(2)}
                value={formData.pagamento_valor_pago}
                onChange={(e) => setFormData(prev => ({ ...prev, pagamento_valor_pago: e.target.value }))}
              />
            </div>
            <div>
              <Label>Data do Pagamento</Label>
              <Input
                type="date" lang="pt-BR"
                value={formData.pagamento_data_pagamento}
                onChange={(e) => setFormData(prev => ({ ...prev, pagamento_data_pagamento: e.target.value }))}
              />
            </div>
          </div>

          <div>
            <Label>Observações do Master</Label>
            <Textarea
              placeholder="Notas internas sobre este pagamento..."
              value={formData.pagamento_observacoes}
              onChange={(e) => setFormData(prev => ({ ...prev, pagamento_observacoes: e.target.value }))}
              rows={3}
            />
          </div>

          {/* Resumo */}
          <div className="rounded-lg bg-green-50 border border-green-200 p-3 flex items-center justify-between">
            <div>
              <p className="text-xs font-semibold text-green-700 uppercase tracking-widest">Pedido de Compra</p>
              <p className="font-mono font-bold text-gray-900">{oc.numero_pedido}</p>
            </div>
            <div className="text-right">
              <p className="text-xs text-gray-500">Valor Total</p>
              <p className="text-xl font-black text-gray-900">
                R$ {valorTotalOc.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
              </p>
            </div>
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={onClose}>
            Cancelar
          </Button>
          <Button
            onClick={() => approveMutation.mutate()}
            disabled={approveMutation.isPending}
            className="bg-green-600 hover:bg-green-700 gap-2"
          >
            {approveMutation.isPending ? (
              <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
              <CheckCircle className="w-4 h-4" />
            )}
            Marcar como Pago
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { base44 } from "@/api/base44Client";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Search, MoreVertical, Package, CheckCircle, ShoppingCart, XCircle, Loader2 } from "lucide-react";
import { toast } from "sonner";

const STATUS_CONFIG = {
    Pendente:   { label: "Pendente",   color: "bg-yellow-100 text-yellow-800 border-yellow-200" },
    "Em Compra":{ label: "Em Compra",  color: "bg-blue-100 text-blue-800 border-blue-200" },
    Resolvida:  { label: "Resolvida",  color: "bg-green-100 text-green-800 border-green-200" },
    Cancelada:  { label: "Cancelada",  color: "bg-red-100 text-red-800 border-red-200" },
};

/**
 * Tab de Solicitações de Reposição dentro da página de Compras.
 * Exibe todas as solicitações geradas por assistências técnicas concluídas.
 */
export default function SolicitacoesReposicaoTab() {
    const queryClient = useQueryClient();
    const [searchTerm, setSearchTerm] = useState("");
    const [statusFiltro, setStatusFiltro] = useState("todos");

    const { data: solicitacoes = [], isLoading } = useQuery({
        queryKey: ["solicitacoes-reposicao"],
        queryFn: () => base44.entities.SolicitacaoReposicao.list("-created_at"),
        staleTime: 30000,
    });

    const atualizarStatusMutation = useMutation({
        mutationFn: ({ id, status }) =>
            base44.entities.SolicitacaoReposicao.update(id, { status }),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["solicitacoes-reposicao"] });
            toast.success("Status atualizado!");
        },
        onError: () => toast.error("Erro ao atualizar status"),
    });

    const handleAtualizarStatus = (id, novoStatus) => {
        atualizarStatusMutation.mutate({ id, status: novoStatus });
    };

    const filtradas = solicitacoes.filter(s => {
        const matchSearch =
            s.produto_nome?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            s.numero_assistencia?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            s.loja_nome?.toLowerCase().includes(searchTerm.toLowerCase());
        const matchStatus = statusFiltro === "todos" || s.status === statusFiltro;
        return matchSearch && matchStatus;
    });

    const contadores = {
        Pendente: solicitacoes.filter(s => s.status === "Pendente").length,
        "Em Compra": solicitacoes.filter(s => s.status === "Em Compra").length,
        Resolvida: solicitacoes.filter(s => s.status === "Resolvida").length,
        Cancelada: solicitacoes.filter(s => s.status === "Cancelada").length,
    };

    return (
        <div className="space-y-4">
            {/* Cards de resumo */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                <Card className="border-l-4 border-l-yellow-400">
                    <CardContent className="p-3">
                        <p className="text-2xl font-bold text-yellow-600">{contadores.Pendente}</p>
                        <p className="text-xs text-gray-500">Pendentes</p>
                    </CardContent>
                </Card>
                <Card className="border-l-4 border-l-blue-400">
                    <CardContent className="p-3">
                        <p className="text-2xl font-bold text-blue-600">{contadores["Em Compra"]}</p>
                        <p className="text-xs text-gray-500">Em Compra</p>
                    </CardContent>
                </Card>
                <Card className="border-l-4 border-l-green-400">
                    <CardContent className="p-3">
                        <p className="text-2xl font-bold text-green-600">{contadores.Resolvida}</p>
                        <p className="text-xs text-gray-500">Resolvidas</p>
                    </CardContent>
                </Card>
                <Card className="border-l-4 border-l-red-400">
                    <CardContent className="p-3">
                        <p className="text-2xl font-bold text-red-500">{contadores.Cancelada}</p>
                        <p className="text-xs text-gray-500">Canceladas</p>
                    </CardContent>
                </Card>
            </div>

            <Card>
                <CardHeader className="pb-3">
                    <CardTitle className="text-base flex items-center gap-2">
                        <Package className="w-4 h-4 text-orange-600" />
                        Solicitações de Reposição
                    </CardTitle>
                    <div className="flex flex-wrap gap-3 items-center mt-2">
                        <div className="relative flex-1 min-w-[200px]">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                            <Input
                                placeholder="Buscar por produto, assistência ou unidade..."
                                className="pl-9"
                                value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)}
                            />
                        </div>
                        <Select value={statusFiltro} onValueChange={setStatusFiltro}>
                            <SelectTrigger className="w-[150px]">
                                <SelectValue placeholder="Status" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="todos">Todos</SelectItem>
                                <SelectItem value="Pendente">Pendente</SelectItem>
                                <SelectItem value="Em Compra">Em Compra</SelectItem>
                                <SelectItem value="Resolvida">Resolvida</SelectItem>
                                <SelectItem value="Cancelada">Cancelada</SelectItem>
                            </SelectContent>
                        </Select>
                    </div>
                </CardHeader>
                <CardContent className="p-0">
                    {isLoading ? (
                        <div className="flex justify-center items-center py-10">
                            <Loader2 className="w-5 h-5 animate-spin text-gray-400" />
                        </div>
                    ) : filtradas.length === 0 ? (
                        <div className="text-center py-10 text-gray-500">
                            <Package className="w-10 h-10 mx-auto mb-2 text-gray-300" />
                            <p className="text-sm">Nenhuma solicitação encontrada.</p>
                        </div>
                    ) : (
                        <Table>
                            <TableHeader className="bg-gray-50">
                                <TableRow>
                                    <TableHead>Produto</TableHead>
                                    <TableHead className="text-center">Qtd</TableHead>
                                    <TableHead>Unidade de Origem</TableHead>
                                    <TableHead>Assistência</TableHead>
                                    <TableHead>Status</TableHead>
                                    <TableHead>Data</TableHead>
                                    <TableHead className="text-right">Ações</TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {filtradas.map(sol => {
                                    const statusCfg = STATUS_CONFIG[sol.status] || STATUS_CONFIG.Pendente;
                                    return (
                                        <TableRow key={sol.id}>
                                            <TableCell className="font-medium">{sol.produto_nome || "—"}</TableCell>
                                            <TableCell className="text-center font-mono font-semibold text-red-600">
                                                -{sol.quantidade}
                                            </TableCell>
                                            <TableCell className="text-sm text-gray-600">{sol.loja_nome || "—"}</TableCell>
                                            <TableCell className="text-sm">
                                                {sol.numero_assistencia ? `#${sol.numero_assistencia}` : "—"}
                                            </TableCell>
                                            <TableCell>
                                                <Badge className={`${statusCfg.color} border text-[10px] uppercase tracking-wide px-2`}>
                                                    {statusCfg.label}
                                                </Badge>
                                            </TableCell>
                                            <TableCell className="text-sm text-gray-500">
                                                {sol.created_at
                                                    ? new Date(sol.created_at).toLocaleDateString("pt-BR")
                                                    : "—"}
                                            </TableCell>
                                            <TableCell className="text-right">
                                                {atualizarStatusMutation.isPending &&
                                                atualizarStatusMutation.variables?.id === sol.id ? (
                                                    <Loader2 className="w-4 h-4 animate-spin ml-auto text-gray-400" />
                                                ) : (
                                                    <DropdownMenu>
                                                        <DropdownMenuTrigger asChild>
                                                            <Button variant="ghost" size="icon">
                                                                <MoreVertical className="w-4 h-4" />
                                                            </Button>
                                                        </DropdownMenuTrigger>
                                                        <DropdownMenuContent align="end">
                                                            {sol.status !== "Em Compra" && (
                                                                <DropdownMenuItem
                                                                    onClick={() => handleAtualizarStatus(sol.id, "Em Compra")}
                                                                >
                                                                    <ShoppingCart className="w-4 h-4 mr-2 text-blue-600" />
                                                                    Marcar Em Compra
                                                                </DropdownMenuItem>
                                                            )}
                                                            {sol.status !== "Resolvida" && (
                                                                <DropdownMenuItem
                                                                    onClick={() => handleAtualizarStatus(sol.id, "Resolvida")}
                                                                >
                                                                    <CheckCircle className="w-4 h-4 mr-2 text-green-600" />
                                                                    Marcar Resolvida
                                                                </DropdownMenuItem>
                                                            )}
                                                            {sol.status !== "Cancelada" && (
                                                                <DropdownMenuItem
                                                                    onClick={() => handleAtualizarStatus(sol.id, "Cancelada")}
                                                                    className="text-red-600"
                                                                >
                                                                    <XCircle className="w-4 h-4 mr-2" />
                                                                    Cancelar
                                                                </DropdownMenuItem>
                                                            )}
                                                            {sol.status === "Cancelada" && (
                                                                <DropdownMenuItem
                                                                    onClick={() => handleAtualizarStatus(sol.id, "Pendente")}
                                                                >
                                                                    <Package className="w-4 h-4 mr-2 text-yellow-600" />
                                                                    Reabrir
                                                                </DropdownMenuItem>
                                                            )}
                                                        </DropdownMenuContent>
                                                    </DropdownMenu>
                                                )}
                                            </TableCell>
                                        </TableRow>
                                    );
                                })}
                            </TableBody>
                        </Table>
                    )}
                </CardContent>
            </Card>
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { ScrollArea } from '@/components/ui/scroll-area';
import {
  ShieldCheck,
  CreditCard,
  Package,
  User,
  Plus,
  Trash2,
  AlertTriangle,
  Check,
  Loader2,
  ArrowLeft,
  MessageSquare,
} from 'lucide-react';
import { toast } from 'sonner';
import { toMoneyNumber } from '@/utils/deliveryPayment';
import { buildProductDisplayName } from '@/utils/productReference';
import { formatarNome } from '@/utils/formatters';

const FORMAS_PAGAMENTO = [
  'Dinheiro',
  'PIX',
  'Cartão de Débito',
  'Cartão de Crédito',
  'Boleto',
  'Transferência',
  'Cheque',
];

const createEmptyPagamento = (defaults = {}) => ({
  forma_pagamento: defaults.forma_pagamento || 'PIX',
  valor: defaults.valor || '',
  parcelas: 1,
});

const formatCurrency = (val) =>
  new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val || 0);

const formatarValorInput = (value) => {
  const digitsOnly = String(value ?? '').replace(/\D/g, '');
  if (!digitsOnly) return '';
  return (Number(digitsOnly) / 100).toLocaleString('pt-BR', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
};

export default function ConferenciaCaixaModal({
  open,
  onClose,
  venda,
  onAprovar,
  onDevolver,
  isLoading = false,
}) {
  const [pagamentos, setPagamentos] = useState([]);
  const [novoPagamento, setNovoPagamento] = useState(createEmptyPagamento({ forma_pagamento: 'PIX' }));
  const [observacao, setObservacao] = useState('');
  const [motivoDevolucao, setMotivoDevolucao] = useState('');
  const [modo, setModo] = useState('conferir'); // 'conferir' | 'devolver'
  const [isProcessing, setIsProcessing] = useState(false);

  useEffect(() => {
    if (!venda || !open) return;
    // Inicializar com os pagamentos originais da venda
    const pags = Array.isArray(venda.pagamentos) && venda.pagamentos.length > 0
      ? venda.pagamentos.map((p) => ({
          forma_pagamento: p.forma_pagamento || 'PIX',
          valor: p.valor || 0,
          parcelas: p.parcelas || 1,
        }))
      : [createEmptyPagamento({ forma_pagamento: venda.forma_pagamento || 'PIX', valor: venda.valor_total || 0 })];

    setPagamentos(pags);
    setNovoPagamento(createEmptyPagamento({ forma_pagamento: 'PIX' }));
    setObservacao('');
    setMotivoDevolucao('');
    setModo('conferir');
  }, [venda, open]);

  if (!venda) return null;

  const totalPagamentos = pagamentos.reduce((sum, p) => sum + toMoneyNumber(p.valor), 0);
  const totalVenda = venda.valor_total || 0;
  const diferenca = totalVenda - totalPagamentos;
  const totalOk = Math.abs(diferenca) < 0.02;

  const adicionarPagamento = () => {
    const valorNum = toMoneyNumber(novoPagamento.valor);
    if (!novoPagamento.forma_pagamento) {
      toast.error('Selecione uma forma de pagamento.');
      return;
    }
    if (valorNum <= 0) {
      toast.error('Informe um valor maior que zero.');
      return;
    }
    setPagamentos((prev) => [...prev, { ...novoPagamento, valor: valorNum }]);
    setNovoPagamento(createEmptyPagamento({ forma_pagamento: novoPagamento.forma_pagamento }));
  };

  const removerPagamento = (idx) => {
    setPagamentos((prev) => prev.filter((_, i) => i !== idx));
  };

  const handleAprovar = async () => {
    if (pagamentos.length === 0) {
      toast.error('Informe pelo menos uma forma de pagamento.');
      return;
    }
    if (!totalOk && Math.abs(diferenca) > 0.02) {
      const confirmMsg =
        diferenca > 0
          ? `O total informado está R$ ${Math.abs(diferenca).toFixed(2)} abaixo do valor da venda. Confirmar assim mesmo?`
          : `O total informado está R$ ${Math.abs(diferenca).toFixed(2)} acima do valor da venda. Confirmar assim mesmo?`;
      if (!window.confirm(confirmMsg)) return;
    }
    setIsProcessing(true);
    try {
      await onAprovar({ pagamentos, observacao });
    } finally {
      setIsProcessing(false);
    }
  };

  const handleDevolver = async () => {
    if (!motivoDevolucao.trim()) {
      toast.error('Informe o motivo para devolver o pedido ao vendedor.');
      return;
    }
    setIsProcessing(true);
    try {
      await onDevolver({ motivo: motivoDevolucao });
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[92vh] flex flex-col">
        <DialogHeader className="border-b pb-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-amber-100 flex items-center justify-center">
              <ShieldCheck className="w-5 h-5 text-amber-600" />
            </div>
            <div>
              <DialogTitle className="text-lg font-bold">
                Conferência de Caixa — Pedido #{venda.numero_pedido}
              </DialogTitle>
              <DialogDescription className="text-sm text-gray-500 mt-0.5">
                Confirme o recebimento e a forma de pagamento antes de liberar o pedido.
              </DialogDescription>
            </div>
          </div>
        </DialogHeader>

        <ScrollArea className="flex-1 pr-1">
          <div className="space-y-5 py-4 pr-2">
            {/* Cliente e Resumo */}
            <div className="grid grid-cols-2 gap-3">
              <div className="rounded-xl border bg-gray-50 p-3 space-y-1">
                <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide flex items-center gap-1">
                  <User className="w-3 h-3" /> Cliente
                </p>
                <p className="font-semibold text-sm">{formatarNome(venda.cliente_nome)}</p>
                {venda.cliente_telefone && (
                  <p className="text-xs text-gray-500">{venda.cliente_telefone}</p>
                )}
              </div>
              <div className="rounded-xl border bg-gray-50 p-3 space-y-1">
                <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide flex items-center gap-1">
                  <CreditCard className="w-3 h-3" /> Valor Total
                </p>
                <p className="font-bold text-2xl text-green-700">{formatCurrency(totalVenda)}</p>
                <p className="text-xs text-gray-500">
                  Pagamento registrado: {venda.forma_pagamento || 'Não informado'}
                </p>
              </div>
            </div>

            {/* Itens do Pedido */}
            <div>
              <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide flex items-center gap-1 mb-2">
                <Package className="w-3 h-3" /> Itens do Pedido
              </p>
              <div className="rounded-xl border overflow-hidden">
                {(venda.itens || []).map((item, idx) => (
                  <div
                    key={idx}
                    className="flex items-center justify-between px-3 py-2 text-sm border-b last:border-0 bg-white"
                  >
                    <span className="flex-1 text-gray-800">
                      {item.quantidade}× {buildProductDisplayName(item.produto_nome, item.modelo_referencia)}
                      {item.variacao_nome && (
                        <span className="text-xs text-gray-400 ml-1">({item.variacao_nome})</span>
                      )}
                    </span>
                    <span className="font-semibold text-gray-900 ml-4">
                      {formatCurrency(item.subtotal || item.preco_unitario * item.quantidade)}
                    </span>
                  </div>
                ))}
              </div>
            </div>

            {/* Observação do vendedor retorno */}
            {venda.conferencia_caixa_status === 'devolvido' && venda.conferencia_caixa_observacao && (
              <div className="flex items-start gap-2 rounded-xl border border-orange-200 bg-orange-50 p-3 text-sm text-orange-800">
                <AlertTriangle className="w-4 h-4 mt-0.5 shrink-0" />
                <div>
                  <p className="font-semibold">Devolvido anteriormente</p>
                  <p className="text-xs mt-1">{venda.conferencia_caixa_observacao}</p>
                </div>
              </div>
            )}

            {/* Modo: Conferir ou Devolver */}
            {modo === 'conferir' ? (
              <>
                {/* Pagamentos */}
                <div>
                  <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide flex items-center gap-1 mb-3">
                    <CreditCard className="w-3 h-3" /> Formas de Pagamento Recebidas
                  </p>

                  {/* Lista atual */}
                  <div className="space-y-2 mb-3">
                    {pagamentos.map((pag, idx) => (
                      <div
                        key={idx}
                        className="flex items-center gap-2 rounded-lg border bg-white px-3 py-2"
                      >
                        <span className="flex-1 text-sm font-medium">{pag.forma_pagamento}</span>
                        {pag.parcelas > 1 && (
                          <span className="text-xs text-gray-400">{pag.parcelas}×</span>
                        )}
                        <span className="font-semibold text-sm text-green-700">
                          {formatCurrency(pag.valor)}
                        </span>
                        <button
                          type="button"
                          onClick={() => removerPagamento(idx)}
                          className="text-gray-400 hover:text-red-500 transition-colors ml-1"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    ))}
                    {pagamentos.length === 0 && (
                      <p className="text-xs text-gray-400 text-center py-2">
                        Nenhuma forma de pagamento adicionada
                      </p>
                    )}
                  </div>

                  {/* Adicionar nova forma */}
                  <div className="rounded-xl border border-dashed border-gray-200 bg-gray-50/50 p-3 space-y-3">
                    <p className="text-xs font-medium text-gray-500">Adicionar forma de pagamento</p>
                    <div className="grid grid-cols-[1fr_auto_auto] gap-2 items-end">
                      <div className="space-y-1">
                        <Label className="text-xs text-gray-500">Forma</Label>
                        <Select
                          value={novoPagamento.forma_pagamento}
                          onValueChange={(v) => setNovoPagamento((p) => ({ ...p, forma_pagamento: v }))}
                        >
                          <SelectTrigger className="h-9">
                            <SelectValue placeholder="Selecionar" />
                          </SelectTrigger>
                          <SelectContent>
                            {FORMAS_PAGAMENTO.map((f) => (
                              <SelectItem key={f} value={f}>{f}</SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </div>
                      <div className="space-y-1 w-36">
                        <Label className="text-xs text-gray-500">Valor (R$)</Label>
                        <Input
                          className="h-9 text-right"
                          placeholder="0,00"
                          value={novoPagamento.valor}
                          onChange={(e) =>
                            setNovoPagamento((p) => ({
                              ...p,
                              valor: formatarValorInput(e.target.value),
                            }))
                          }
                          onKeyDown={(e) => e.key === 'Enter' && adicionarPagamento()}
                        />
                      </div>
                      <Button
                        type="button"
                        size="icon"
                        className="h-9 w-9 bg-green-600 hover:bg-green-700"
                        onClick={adicionarPagamento}
                      >
                        <Plus className="w-4 h-4" />
                      </Button>
                    </div>
                  </div>
                </div>

                {/* Totalizador */}
                <div
                  className={`rounded-xl border p-3 space-y-2 ${
                    totalOk
                      ? 'border-green-200 bg-green-50'
                      : 'border-amber-200 bg-amber-50'
                  }`}
                >
                  <div className="flex justify-between text-sm">
                    <span className="text-gray-600">Total da venda</span>
                    <span className="font-semibold">{formatCurrency(totalVenda)}</span>
                  </div>
                  <div className="flex justify-between text-sm">
                    <span className="text-gray-600">Total informado</span>
                    <span className={`font-semibold ${totalOk ? 'text-green-700' : 'text-amber-700'}`}>
                      {formatCurrency(totalPagamentos)}
                    </span>
                  </div>
                  {!totalOk && (
                    <div className="flex justify-between text-sm border-t pt-2">
                      <span className="text-amber-700 font-medium">
                        {diferenca > 0 ? 'Faltando' : 'Excesso'}
                      </span>
                      <span className="font-bold text-amber-700">
                        {formatCurrency(Math.abs(diferenca))}
                      </span>
                    </div>
                  )}
                  {totalOk && (
                    <div className="flex items-center gap-1 text-xs text-green-700 font-medium pt-1 border-t">
                      <Check className="w-3.5 h-3.5" /> Pagamento confere com o valor da venda
                    </div>
                  )}
                </div>

                {/* Observação */}
                <div className="space-y-1">
                  <Label className="text-xs text-gray-500 flex items-center gap-1">
                    <MessageSquare className="w-3 h-3" /> Observação (opcional)
                  </Label>
                  <Textarea
                    placeholder="Alguma observação sobre o recebimento..."
                    value={observacao}
                    onChange={(e) => setObservacao(e.target.value)}
                    className="resize-none text-sm"
                    rows={2}
                  />
                </div>
              </>
            ) : (
              /* Modo devolução */
              <div className="space-y-3">
                <div className="flex items-start gap-2 rounded-xl border border-orange-200 bg-orange-50 p-3 text-sm text-orange-800">
                  <AlertTriangle className="w-4 h-4 mt-0.5 shrink-0" />
                  <p>
                    O pedido será devolvido ao vendedor para correção. Informe o motivo para que
                    o vendedor saiba o que ajustar.
                  </p>
                </div>
                <div className="space-y-1">
                  <Label className="text-sm font-medium">Motivo da devolução *</Label>
                  <Textarea
                    placeholder="Ex: Pagamento informado não corresponde ao recebido, cliente pagou com PIX mas foi lançado como dinheiro..."
                    value={motivoDevolucao}
                    onChange={(e) => setMotivoDevolucao(e.target.value)}
                    className="resize-none text-sm"
                    rows={4}
                  />
                </div>
              </div>
            )}
          </div>
        </ScrollArea>

        <DialogFooter className="border-t pt-4 gap-2 flex-wrap">
          {modo === 'conferir' ? (
            <>
              <Button
                type="button"
                variant="outline"
                className="text-orange-600 border-orange-200 hover:bg-orange-50"
                onClick={() => setModo('devolver')}
                disabled={isProcessing || isLoading}
              >
                <AlertTriangle className="w-4 h-4 mr-2" />
                Devolver ao Vendedor
              </Button>
              <Button
                type="button"
                onClick={handleAprovar}
                disabled={isProcessing || isLoading || pagamentos.length === 0}
                className="bg-green-600 hover:bg-green-700 text-white"
              >
                {isProcessing || isLoading ? (
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                ) : (
                  <Check className="w-4 h-4 mr-2" />
                )}
                Aprovar e Liberar Pedido
              </Button>
            </>
          ) : (
            <>
              <Button
                type="button"
                variant="ghost"
                onClick={() => setModo('conferir')}
                disabled={isProcessing}
              >
                <ArrowLeft className="w-4 h-4 mr-2" />
                Voltar
              </Button>
              <Button
                type="button"
                onClick={handleDevolver}
                disabled={isProcessing || !motivoDevolucao.trim()}
                variant="destructive"
              >
                {isProcessing ? (
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                ) : (
                  <AlertTriangle className="w-4 h-4 mr-2" />
                )}
                Confirmar Devolução
              </Button>
            </>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { ScrollArea } from '@/components/ui/scroll-area';
import {
  Package,
  CreditCard,
  Trash2,
  Plus,
  Loader2,
  Save,
  AlertTriangle,
  Minus,
} from 'lucide-react';
import { toast } from 'sonner';
import { base44 } from '@/api/base44Client';
import { toMoneyNumber } from '@/utils/deliveryPayment';
import { buildProductDisplayName } from '@/utils/productReference';
import { validatePaymentSplit } from '@/services/paymentOrchestrator';
import { supabase } from '@/lib/supabase';
import { resolveStockField, getProductTotalStock, getVarianteEstoque, atualizarEstoqueVariante } from '@/utils/stockUtils';

const FORMAS_PAGAMENTO = [
  'Dinheiro',
  'PIX',
  'Cartão de Débito',
  'Cartão de Crédito',
  'Boleto',
  'Transferência',
  'Cheque',
];

const formatCurrency = (val) =>
  new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val || 0);

const formatarValorInput = (value) => {
  const digitsOnly = String(value ?? '').replace(/\D/g, '');
  if (!digitsOnly) return '';
  return (Number(digitsOnly) / 100).toLocaleString('pt-BR', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
};

export default function EdicaoPedidoModal({ open, onClose, venda, onSalvar }) {
  const [itens, setItens] = useState([]);
  const [pagamentos, setPagamentos] = useState([]);
  const [novoPagamento, setNovoPagamento] = useState({ forma_pagamento: 'PIX', valor: '', parcelas: 1 });
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!venda || !open) return;
    setItens(
      (venda.itens || []).map((item) => ({ ...item }))
    );
    setPagamentos(
      Array.isArray(venda.pagamentos) && venda.pagamentos.length > 0
        ? venda.pagamentos.map((p) => ({ ...p }))
        : [{ forma_pagamento: venda.forma_pagamento || 'PIX', valor: venda.valor_total || 0, parcelas: 1 }]
    );
    setNovoPagamento({ forma_pagamento: 'PIX', valor: '', parcelas: 1 });
  }, [venda, open]);

  if (!venda) return null;

  // Recalcular totais
  const subtotal = itens.reduce(
    (sum, item) => sum + (toMoneyNumber(item.preco_unitario) * (item.quantidade || 1)),
    0
  );
  const desconto = venda.desconto || 0;
  const valorTotal = Math.max(subtotal - desconto, 0);
  const totalPagamentos = pagamentos.reduce((sum, p) => sum + toMoneyNumber(p.valor), 0);
  const diferenca = valorTotal - totalPagamentos;

  const atualizarQtd = (idx, delta) => {
    setItens((prev) =>
      prev.map((item, i) => {
        if (i !== idx) return item;
        const novaQtd = Math.max(1, (item.quantidade || 1) + delta);
        return { ...item, quantidade: novaQtd, subtotal: item.preco_unitario * novaQtd };
      })
    );
  };

  const removerItem = (idx) => {
    if (itens.length <= 1) {
      toast.error('A venda precisa ter pelo menos 1 item.');
      return;
    }
    setItens((prev) => prev.filter((_, i) => i !== idx));
  };

  const adicionarPagamento = () => {
    const valorNum = toMoneyNumber(novoPagamento.valor);
    if (!novoPagamento.forma_pagamento) {
      toast.error('Selecione uma forma de pagamento.');
      return;
    }
    if (valorNum <= 0) {
      toast.error('Informe um valor maior que zero.');
      return;
    }
    setPagamentos((prev) => [...prev, { ...novoPagamento, valor: valorNum }]);
    setNovoPagamento({ forma_pagamento: novoPagamento.forma_pagamento, valor: '', parcelas: 1 });
  };

  const removerPagamento = (idx) => {
    setPagamentos((prev) => prev.filter((_, i) => i !== idx));
  };

  const handleSalvar = async () => {
    if (itens.length === 0) {
      toast.error('A venda precisa ter pelo menos 1 item.');
      return;
    }
    if (pagamentos.length === 0) {
      toast.error('Informe pelo menos uma forma de pagamento.');
      return;
    }

    setSaving(true);
    try {
      const novoSubtotal = itens.reduce(
        (sum, item) => sum + (toMoneyNumber(item.preco_unitario) * (item.quantidade || 1)),
        0
      );
      const novoTotal = Math.max(novoSubtotal - desconto, 0);
      const novoPago = pagamentos.reduce((sum, p) => sum + toMoneyNumber(p.valor), 0);
      const novoRestante = Math.max(novoTotal - novoPago, 0);
      const novoStatus = novoRestante <= 0.01 ? 'Pago' : 'Pagamento Pendente';

      const formaPrincipal =
        pagamentos.length === 1
          ? pagamentos[0].forma_pagamento
          : pagamentos.length > 1
            ? 'Múltiplos'
            : venda.forma_pagamento || 'Diversos';

      const payload = {
        itens,
        valor_total: novoTotal,
        valor_pago: novoPago,
        valor_restante: novoRestante,
        status: novoStatus,
        pagamentos,
        forma_pagamento: formaPrincipal,
        // Ao salvar edições, se o pedido estava devolvido, retorna para aguardando a conferência
        ...(venda.conferencia_caixa_status === 'devolvido' ? {
          conferencia_caixa_status: 'aguardando',
          conferencia_caixa_observacao: null,
          conferencia_caixa_at: null,
          conferencia_caixa_por: null,
          conferencia_caixa_por_id: null,
        } : {}),
      };

      // 1. Reconciliar estoque com base na diferença de quantidade de itens
      const itensAntigos = venda.itens || [];
      const itensNovos = itens;
      const obterChaveItem = (it) => `${it.produto_id}_${it.variante_id || ''}`;
      
      const qtdsAntigas = {};
      itensAntigos.forEach(it => {
        const key = obterChaveItem(it);
        qtdsAntigas[key] = (qtdsAntigas[key] || 0) + Number(it.quantidade || 0);
      });

      const qtdsNovas = {};
      itensNovos.forEach(it => {
        const key = obterChaveItem(it);
        qtdsNovas[key] = (qtdsNovas[key] || 0) + Number(it.quantidade || 0);
      });

      const todasChaves = Array.from(new Set([...Object.keys(qtdsAntigas), ...Object.keys(qtdsNovas)]));
      const lojaNome = venda.loja;
      
      // Buscar lojas para encontrar o lojaId
      const { data: lojas } = await supabase.from('lojas').select('id, nome');
      const lojaId = lojas?.find(l => String(l.nome).trim().toLowerCase() === String(lojaNome).trim().toLowerCase())?.id;

      for (const key of todasChaves) {
        const [produtoId, varianteId] = key.split('_');
        const qtdAntiga = qtdsAntigas[key] || 0;
        const qtdNova = qtdsNovas[key] || 0;
        const diff = qtdNova - qtdAntiga; // se > 0 reduziu estoque (vendeu mais), se < 0 devolveu estoque (vendeu menos)

        if (diff !== 0) {
          if (varianteId && lojaId) {
            const estoqueAtual = await getVarianteEstoque(supabase, varianteId, lojaId);
            const novaQtd = estoqueAtual - diff;
            await atualizarEstoqueVariante(supabase, varianteId, lojaId, novaQtd);
          } else if (produtoId) {
            const prod = await base44.entities.Produto.getById(produtoId);
            if (prod) {
              const itemOriginal = itensAntigos.find(it => obterChaveItem(it) === key) || 
                                   itensNovos.find(it => obterChaveItem(it) === key);
              const campoOrigem = itemOriginal?.origem_estoque_campo || resolveStockField(lojaNome);
              if (campoOrigem) {
                const estoqueOrigemAtual = Number(prod[campoOrigem] || 0);
                const estoqueLocalAposVenda = estoqueOrigemAtual - diff;
                
                const produtoAtualizado = {
                  ...prod,
                  [campoOrigem]: Math.max(0, estoqueLocalAposVenda)
                };
                const updates = {
                  [campoOrigem]: produtoAtualizado[campoOrigem],
                  quantidade_estoque: getProductTotalStock(produtoAtualizado)
                };
                await base44.entities.Produto.update(prod.id, updates);
              }
            }
          }
        }
      }

      await base44.entities.Venda.update(venda.id, payload);
      toast.success('Pedido atualizado! Aguardando conferência de caixa.');
      onSalvar?.(payload);
      onClose?.();
    } catch (err) {
      console.error('Erro ao atualizar pedido:', err);
      toast.error(err?.message || 'Não foi possível salvar as alterações.');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[92vh] flex flex-col">
        <DialogHeader className="border-b pb-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-blue-100 flex items-center justify-center">
              <Package className="w-5 h-5 text-blue-600" />
            </div>
            <div>
              <DialogTitle className="text-lg font-bold">
                Editar Pedido #{venda.numero_pedido}
              </DialogTitle>
              <DialogDescription className="text-sm text-gray-500 mt-0.5">
                O pedido ainda não foi conferido — você pode editar itens e pagamentos livremente.
              </DialogDescription>
            </div>
          </div>
        </DialogHeader>

        <ScrollArea className="flex-1 pr-1">
          <div className="space-y-5 py-4 pr-2">
            {/* Aviso devolução */}
            {venda.conferencia_caixa_status === 'devolvido' && venda.conferencia_caixa_observacao && (
              <div className="flex items-start gap-2 rounded-xl border border-orange-200 bg-orange-50 p-3 text-sm text-orange-800">
                <AlertTriangle className="w-4 h-4 mt-0.5 shrink-0" />
                <div>
                  <p className="font-semibold">Pedido devolvido pelo caixa</p>
                  <p className="text-xs mt-1">{venda.conferencia_caixa_observacao}</p>
                </div>
              </div>
            )}

            {/* Itens */}
            <div>
              <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide flex items-center gap-1 mb-3">
                <Package className="w-3 h-3" /> Itens do Pedido
              </p>
              <div className="space-y-2">
                {itens.map((item, idx) => (
                  <div
                    key={idx}
                    className="flex items-center gap-3 rounded-xl border bg-white px-3 py-2.5"
                  >
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-medium truncate">
                        {buildProductDisplayName(item.produto_nome, item.modelo_referencia)}
                      </p>
                      {item.variacao_nome && (
                        <p className="text-xs text-gray-400">{item.variacao_nome}</p>
                      )}
                      <p className="text-xs text-gray-500 mt-0.5">
                        Unitário: {formatCurrency(item.preco_unitario)}
                      </p>
                    </div>

                    {/* Controle de quantidade */}
                    <div className="flex items-center gap-1.5">
                      <button
                        type="button"
                        onClick={() => atualizarQtd(idx, -1)}
                        className="w-7 h-7 rounded-lg border flex items-center justify-center hover:bg-gray-100 transition-colors"
                      >
                        <Minus className="w-3.5 h-3.5" />
                      </button>
                      <span className="w-8 text-center font-semibold text-sm">
                        {item.quantidade || 1}
                      </span>
                      <button
                        type="button"
                        onClick={() => atualizarQtd(idx, 1)}
                        className="w-7 h-7 rounded-lg border flex items-center justify-center hover:bg-gray-100 transition-colors"
                      >
                        <Plus className="w-3.5 h-3.5" />
                      </button>
                    </div>

                    <span className="font-bold text-sm text-gray-900 w-24 text-right">
                      {formatCurrency(item.preco_unitario * (item.quantidade || 1))}
                    </span>

                    <button
                      type="button"
                      onClick={() => removerItem(idx)}
                      className="text-gray-300 hover:text-red-500 transition-colors ml-1"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                ))}
              </div>
            </div>

            {/* Resumo de Valores */}
            <div className="rounded-xl border bg-gray-50 p-3 space-y-1.5 text-sm">
              <div className="flex justify-between">
                <span className="text-gray-500">Subtotal</span>
                <span>{formatCurrency(subtotal)}</span>
              </div>
              {desconto > 0 && (
                <div className="flex justify-between text-emerald-600">
                  <span>Desconto</span>
                  <span>- {formatCurrency(desconto)}</span>
                </div>
              )}
              <div className="flex justify-between font-bold text-base border-t pt-2 mt-1">
                <span>Total</span>
                <span className="text-green-700">{formatCurrency(valorTotal)}</span>
              </div>
            </div>

            {/* Pagamentos */}
            <div>
              <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide flex items-center gap-1 mb-3">
                <CreditCard className="w-3 h-3" /> Formas de Pagamento
              </p>

              <div className="space-y-2 mb-3">
                {pagamentos.map((pag, idx) => (
                  <div
                    key={idx}
                    className="flex items-center gap-2 rounded-lg border bg-white px-3 py-2"
                  >
                    <span className="flex-1 text-sm font-medium">{pag.forma_pagamento}</span>
                    {pag.parcelas > 1 && (
                      <span className="text-xs text-gray-400">{pag.parcelas}×</span>
                    )}
                    <span className="font-semibold text-sm text-green-700">
                      {formatCurrency(pag.valor)}
                    </span>
                    <button
                      type="button"
                      onClick={() => removerPagamento(idx)}
                      className="text-gray-300 hover:text-red-500 transition-colors"
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                  </div>
                ))}
                {pagamentos.length === 0 && (
                  <p className="text-xs text-center text-gray-400 py-2">
                    Nenhuma forma de pagamento
                  </p>
                )}
              </div>

              {/* Adicionar */}
              <div className="rounded-xl border border-dashed bg-gray-50/50 p-3 space-y-2">
                <p className="text-xs font-medium text-gray-500">Adicionar pagamento</p>
                <div className="grid grid-cols-[1fr_auto_auto] gap-2 items-end">
                  <div className="space-y-1">
                    <Label className="text-xs text-gray-500">Forma</Label>
                    <Select
                      value={novoPagamento.forma_pagamento}
                      onValueChange={(v) => setNovoPagamento((p) => ({ ...p, forma_pagamento: v }))}
                    >
                      <SelectTrigger className="h-9">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {FORMAS_PAGAMENTO.map((f) => (
                          <SelectItem key={f} value={f}>{f}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-1 w-32">
                    <Label className="text-xs text-gray-500">Valor (R$)</Label>
                    <Input
                      className="h-9 text-right"
                      placeholder="0,00"
                      value={novoPagamento.valor}
                      onChange={(e) =>
                        setNovoPagamento((p) => ({ ...p, valor: formatarValorInput(e.target.value) }))
                      }
                      onKeyDown={(e) => e.key === 'Enter' && adicionarPagamento()}
                    />
                  </div>
                  <Button
                    type="button"
                    size="icon"
                    className="h-9 w-9 bg-green-600 hover:bg-green-700"
                    onClick={adicionarPagamento}
                  >
                    <Plus className="w-4 h-4" />
                  </Button>
                </div>
              </div>

              {/* Conferência de total */}
              {pagamentos.length > 0 && (
                <div
                  className={`mt-2 rounded-lg border px-3 py-2 text-xs flex justify-between ${
                    Math.abs(diferenca) < 0.02
                      ? 'border-green-200 bg-green-50 text-green-700'
                      : 'border-amber-200 bg-amber-50 text-amber-700'
                  }`}
                >
                  <span>
                    {Math.abs(diferenca) < 0.02
                      ? '✅ Pagamento confere com o total'
                      : diferenca > 0
                        ? `⚠ Faltam ${formatCurrency(diferenca)}`
                        : `⚠ Excesso de ${formatCurrency(Math.abs(diferenca))}`}
                  </span>
                  <span className="font-semibold">{formatCurrency(totalPagamentos)} / {formatCurrency(valorTotal)}</span>
                </div>
              )}
            </div>
          </div>
        </ScrollArea>

        <DialogFooter className="border-t pt-4 gap-2">
          <Button type="button" variant="outline" onClick={onClose} disabled={saving}>
            Cancelar
          </Button>
          <Button
            type="button"
            onClick={handleSalvar}
            disabled={saving || itens.length === 0}
            className="bg-green-600 hover:bg-green-700 text-white"
          >
            {saving ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Save className="w-4 h-4 mr-2" />}
            Salvar Alterações
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import { supabase } from '@/lib/supabase';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import {
  ShieldCheck,
  Search,
  Clock,
  RefreshCw,
  AlertTriangle,
  Check,
  Loader2,
  User,
  CreditCard,
} from 'lucide-react';
import { toast } from 'sonner';
import { useAuth } from '@/hooks/useAuth';
import { useTenant } from '@/contexts/TenantContext';
import { isAguardandoConferencia, aprovarConferencia, devolverParaVendedor } from '@/services/conferenciaCaixaService';
import ConferenciaCaixaModal from '@/components/conferencia/ConferenciaCaixaModal';
import { formatarNome } from '@/utils/formatters';
import { formatarDataExibicao } from '@/utils/dateUtils';

const formatCurrency = (val) =>
  new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val || 0);

export default function PainelConferenciaCaixa() {
  const { user } = useAuth();
  const { conferenciaCaixaEnabled } = useTenant();
  const queryClient = useQueryClient();

  const [searchTerm, setSearchTerm] = useState('');
  const [vendaParaConferencia, setVendaParaConferencia] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);

  // Query de vendas pendentes de conferência
  const { data: todasVendas = [], isLoading, refetch } = useQuery({
    queryKey: ['vendas-conferencia'],
    queryFn: () => base44.entities.Venda.list('-data_venda'),
    enabled: !!user && conferenciaCaixaEnabled,
    refetchInterval: 15000, // atualizar a cada 15s
  });

  // Query de configurações auxiliares para o serviço de aprovação
  const { data: taxas = [] } = useQuery({
    queryKey: ['configuracao_taxas'],
    queryFn: () => base44.entities.ConfiguracaoTaxa.list(),
    enabled: !!user,
  });

  const { data: categoriasFinanceiras = [] } = useQuery({
    queryKey: ['categorias-financeiras'],
    queryFn: () => base44.entities.CategoriaFinanceira?.list?.() || Promise.resolve([]),
    enabled: !!user,
  });

  const { data: prazosConfig = [] } = useQuery({
    queryKey: ['prazos-entrega'],
    queryFn: async () => {
      const { data, error } = await supabase.from('prazos_entrega').select('*');
      if (error) throw error;
      return data || [];
    },
    enabled: !!user,
  });

  // Filtrar vendas aguardando conferência
  const vendasPendentes = todasVendas.filter(v => isAguardandoConferencia(v));

  const vendasFiltradas = vendasPendentes.filter(v => {
    if (!searchTerm.trim()) return true;
    const termo = searchTerm.toLowerCase();
    return (
      v.cliente_nome?.toLowerCase().includes(termo) ||
      v.numero_pedido?.includes(termo)
    );
  });

  const handleAprovar = async ({ pagamentos, observacao }) => {
    if (!vendaParaConferencia) return;
    setIsProcessing(true);
    try {
      await aprovarConferencia({
        venda: vendaParaConferencia,
        gerente: { id: user?.id, nome: user?.full_name || user?.email },
        pagamentosConferidos: pagamentos,
        observacao,
        taxas,
        categoriasFinanceiras,
        prazosConfig,
      });

      toast.success(`Pedido #${vendaParaConferencia.numero_pedido} aprovado! Entrega e lançamentos criados.`);
      setIsModalOpen(false);
      setVendaParaConferencia(null);
      queryClient.invalidateQueries({ queryKey: ['vendas-conferencia'] });
      queryClient.invalidateQueries({ queryKey: ['vendas-gerente'] });
      queryClient.invalidateQueries({ queryKey: ['vendas'] });
      queryClient.invalidateQueries({ queryKey: ['entregas'] });
      queryClient.invalidateQueries({ queryKey: ['lancamentos-financeiros'] });
    } catch (err) {
      console.error('Erro ao aprovar conferência:', err);
      toast.error(err?.message || 'Não foi possível aprovar o pedido.');
    } finally {
      setIsProcessing(false);
    }
  };

  const handleDevolver = async ({ motivo }) => {
    if (!vendaParaConferencia) return;
    setIsProcessing(true);
    try {
      await devolverParaVendedor({
        venda: vendaParaConferencia,
        gerente: { id: user?.id, nome: user?.full_name || user?.email },
        motivo,
      });

      toast.success(`Pedido #${vendaParaConferencia.numero_pedido} devolvido ao vendedor para correção.`);
      setIsModalOpen(false);
      setVendaParaConferencia(null);
      queryClient.invalidateQueries({ queryKey: ['vendas-conferencia'] });
      queryClient.invalidateQueries({ queryKey: ['vendas'] });
    } catch (err) {
      console.error('Erro ao devolver pedido:', err);
      toast.error(err?.message || 'Não foi possível devolver o pedido.');
    } finally {
      setIsProcessing(false);
    }
  };

  if (!conferenciaCaixaEnabled) {
    return (
      <Card className="border-dashed border-2 border-gray-200">
        <CardContent className="py-10 text-center">
          <ShieldCheck className="w-10 h-10 mx-auto text-gray-300 mb-3" />
          <p className="text-sm text-gray-500 font-medium">Módulo de Conferência de Caixa inativo</p>
          <p className="text-xs text-gray-400 mt-1">
            Ative em Configurações → Compras e Pagamentos.
          </p>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-amber-100 flex items-center justify-center">
            <ShieldCheck className="w-5 h-5 text-amber-600" />
          </div>
          <div>
            <h2 className="text-lg font-bold text-gray-900 dark:text-white">Conferência de Caixa</h2>
            <p className="text-sm text-gray-500">
              {vendasPendentes.length > 0
                ? `${vendasPendentes.length} pedido(s) aguardando conferência`
                : 'Nenhum pedido aguardando conferência'}
            </p>
          </div>
        </div>
        <Button variant="outline" size="icon" onClick={() => refetch()} disabled={isLoading}>
          <RefreshCw className={`w-4 h-4 ${isLoading ? 'animate-spin' : ''}`} />
        </Button>
      </div>

      {/* Busca */}
      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
        <Input
          className="pl-9"
          placeholder="Buscar por cliente ou nº do pedido..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      {/* Tabela */}
      <Card>
        <CardContent className="p-0">
          <Table>
            <TableHeader className="bg-amber-50">
              <TableRow>
                <TableHead className="w-[100px]">Pedido</TableHead>
                <TableHead>Cliente</TableHead>
                <TableHead>Data</TableHead>
                <TableHead>Total</TableHead>
                <TableHead>Forma Pagamento</TableHead>
                <TableHead>Status</TableHead>
                <TableHead className="text-right">Ação</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {isLoading ? (
                <TableRow>
                  <TableCell colSpan={7} className="text-center py-10">
                    <Loader2 className="w-6 h-6 animate-spin mx-auto mb-2 text-amber-500" />
                    <p className="text-sm text-gray-500">Carregando...</p>
                  </TableCell>
                </TableRow>
              ) : vendasFiltradas.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={7} className="text-center py-14">
                    <Check className="w-10 h-10 mx-auto text-green-300 mb-3" />
                    <p className="font-medium text-gray-500">
                      {searchTerm
                        ? 'Nenhum pedido encontrado para esta busca.'
                        : 'Todos os pedidos foram conferidos! ✅'}
                    </p>
                    <p className="text-sm text-gray-400 mt-1">
                      Novas vendas aparecerão aqui automaticamente.
                    </p>
                  </TableCell>
                </TableRow>
              ) : (
                vendasFiltradas.map((venda) => (
                  <TableRow
                    key={venda.id}
                    className="hover:bg-amber-50/50 transition-colors cursor-pointer"
                    onClick={() => {
                      setVendaParaConferencia(venda);
                      setIsModalOpen(true);
                    }}
                  >
                    <TableCell className="font-bold text-amber-700">
                      #{venda.numero_pedido}
                    </TableCell>
                    <TableCell>
                      <div className="flex flex-col">
                        <span className="font-medium text-sm">{formatarNome(venda.cliente_nome)}</span>
                        {venda.cliente_telefone && (
                          <span className="text-xs text-gray-400">{venda.cliente_telefone}</span>
                        )}
                      </div>
                    </TableCell>
                    <TableCell className="text-sm text-gray-600">
                      {formatarDataExibicao(venda.data_venda)}
                    </TableCell>
                    <TableCell className="font-semibold text-green-700">
                      {formatCurrency(venda.valor_total)}
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-1.5 text-sm text-gray-600">
                        <CreditCard className="w-3.5 h-3.5 text-gray-400" />
                        {venda.forma_pagamento || 'Não informado'}
                      </div>
                    </TableCell>
                    <TableCell>
                      {venda.conferencia_caixa_status === 'devolvido' ? (
                        <Badge className="bg-orange-100 text-orange-700 border-orange-200 text-xs">
                          <AlertTriangle className="w-3 h-3 mr-1" />
                          Devolvido
                        </Badge>
                      ) : (
                        <Badge className="bg-amber-100 text-amber-700 border-amber-200 text-xs">
                          <Clock className="w-3 h-3 mr-1" />
                          Aguardando
                        </Badge>
                      )}
                    </TableCell>
                    <TableCell className="text-right" onClick={(e) => e.stopPropagation()}>
                      <Button
                        size="sm"
                        className="bg-amber-500 hover:bg-amber-600 text-white"
                        onClick={() => {
                          setVendaParaConferencia(venda);
                          setIsModalOpen(true);
                        }}
                      >
                        <ShieldCheck className="w-3.5 h-3.5 mr-1.5" />
                        Conferir
                      </Button>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      {/* Modal de Conferência */}
      <ConferenciaCaixaModal
        open={isModalOpen}
        onClose={() => {
          if (!isProcessing) {
            setIsModalOpen(false);
            setVendaParaConferencia(null);
          }
        }}
        venda={vendaParaConferencia}
        onAprovar={handleAprovar}
        onDevolver={handleDevolver}
        isLoading={isProcessing}
      />
    </div>
  );
}

import React, { useEffect, useMemo, useState } from "react";
import { base44 } from "@/lib/supabase";
import { useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/hooks/useAuth";
import { useConfirm } from "@/hooks/useConfirm";
import {
    Dialog,
    DialogContent,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import {
    TrendingUp,
    TrendingDown,
    Loader2,
    CheckCircle,
    ShieldAlert,
    RotateCcw,
    Percent,
    DollarSign,
    ChevronLeft,
    ChevronRight,
} from "lucide-react";
import { toast } from "sonner";
import {
    BULK_PRICE_CONSTANTS,
    applyExceptionMode,
    buildSimulation,
    filterProductsByCriteria,
} from "@/utils/bulkPriceAdjustment";

const UNDO_KEY = "bulk_price_last_batch_v1";
const UNDO_WINDOW_MS = 15 * 60 * 1000;

const defaultCriteria = {
    fabricantes: "",
    categorias: "",
    searchTerm: "",
    precoMin: "",
    precoMax: "",
    status: BULK_PRICE_CONSTANTS.STATUS_OPTIONS.TODOS,
    estoqueMin: "",
    estoqueMax: "",
    createdFrom: "",
    createdTo: "",
    updatedFrom: "",
    updatedTo: "",
};

const PREVIEW_PAGE_SIZE = 100;

export default function AjustePrecoModal({ isOpen, onClose, produtos = [] }) {
    const [targetField, setTargetField] = useState("preco_venda");
    const [tipoAjuste, setTipoAjuste] = useState("porcentagem");
    const [operacao, setOperacao] = useState("aumentar");
    const [percentual, setPercentual] = useState("");
    const [valorFixo, setValorFixo] = useState("");
    const [criteria, setCriteria] = useState(defaultCriteria);
    const [exceptionMode, setExceptionMode] = useState(BULK_PRICE_CONSTANTS.EXCEPTION_MODES.INCLUDE_FILTER_EXCLUDE_ITEMS);
    const [exceptionSearch, setExceptionSearch] = useState("");
    const [exceptionIds, setExceptionIds] = useState([]);
    const [simulation, setSimulation] = useState(null);
    const [lastBatch, setLastBatch] = useState(null);
    const [aplicando, setAplicando] = useState(false);
    const [previewPage, setPreviewPage] = useState(1);
    const [selectedExecutionIds, setSelectedExecutionIds] = useState([]);
    const [editCadastroOpen, setEditCadastroOpen] = useState(false);
    const [editCadastroItem, setEditCadastroItem] = useState(null);
    const [editPrecoCusto, setEditPrecoCusto] = useState("");
    const [editPrecoVenda, setEditPrecoVenda] = useState("");
    const [salvandoEdicaoCadastro, setSalvandoEdicaoCadastro] = useState(false);

    const { user, can } = useAuth();
    const confirm = useConfirm();
    const queryClient = useQueryClient();

    const adjustmentValue = tipoAjuste === "porcentagem" ? percentual : valorFixo;

    const uniqueManufacturers = useMemo(() => {
        return [...new Set(
            produtos
                .map((produto) => produto.fornecedor_nome || produto.marca)
                .filter(Boolean)
                .map((value) => String(value).trim())
        )].sort((a, b) => a.localeCompare(b, "pt-BR", { sensitivity: "base" }));
    }, [produtos]);

    const uniqueCategories = useMemo(() => {
        return [...new Set(
            produtos
                .map((produto) => produto.categoria)
                .filter(Boolean)
                .map((value) => String(value).trim())
        )].sort((a, b) => a.localeCompare(b, "pt-BR", { sensitivity: "base" }));
    }, [produtos]);

    const filteredProducts = useMemo(() => {
        return filterProductsByCriteria(produtos, criteria, targetField);
    }, [produtos, criteria, targetField]);

    const eligibleProducts = useMemo(() => {
        return applyExceptionMode({
            produtos,
            filteredProducts,
            exceptionMode,
            exceptionIds,
        });
    }, [produtos, filteredProducts, exceptionMode, exceptionIds]);

    const exceptionSuggestions = useMemo(() => {
        const normalized = String(exceptionSearch || "").trim().toLowerCase();
        if (!normalized) return [];

        return produtos
            .filter((produto) => {
                const blob = [
                    produto.nome,
                    produto.id,
                    produto.codigo_barras,
                    produto.modelo_referencia,
                ].join(" ").toLowerCase();
                return blob.includes(normalized);
            })
            .slice(0, 8);
    }, [produtos, exceptionSearch]);

    const exceptionProducts = useMemo(() => {
        const selected = new Set(exceptionIds);
        return produtos.filter((produto) => selected.has(produto.id));
    }, [exceptionIds, produtos]);

    const executionRows = simulation?.executableRows || [];
    const blockedRows = simulation?.blockedRows || [];
    const selectedExecutableRows = useMemo(() => {
        if (!simulation) return [];
        const selectedSet = new Set(selectedExecutionIds);
        return executionRows.filter((row) => selectedSet.has(row.id));
    }, [simulation, executionRows, selectedExecutionIds]);

    const formatMoney = (value) => {
        if (!value && value !== 0) return "R$ 0,00";
        return `R$ ${value.toLocaleString("pt-BR", { minimumFractionDigits: 2 })}`;
    };

    const toggleException = (produtoId) => {
        setExceptionIds((prev) =>
            prev.includes(produtoId)
                ? prev.filter((id) => id !== produtoId)
                : [...prev, produtoId]
        );
    };

    const removeException = (produtoId) => {
        setExceptionIds((prev) => prev.filter((id) => id !== produtoId));
    };

    useEffect(() => {
        setSimulation(null);
        setSelectedExecutionIds([]);
    }, [criteria, exceptionMode, exceptionIds, tipoAjuste, operacao, percentual, valorFixo, targetField]);

    useEffect(() => {
        setPreviewPage(1);
    }, [simulation, criteria, exceptionMode, exceptionIds, tipoAjuste, operacao, percentual, valorFixo, targetField]);

    useEffect(() => {
        if (!isOpen) return;

        const raw = localStorage.getItem(UNDO_KEY);
        if (!raw) {
            setLastBatch(null);
            return;
        }

        try {
            const parsed = JSON.parse(raw);
            const elapsed = Date.now() - new Date(parsed.timestamp).getTime();
            if (elapsed > UNDO_WINDOW_MS) {
                localStorage.removeItem(UNDO_KEY);
                setLastBatch(null);
                return;
            }
            setLastBatch(parsed);
        } catch (_error) {
            localStorage.removeItem(UNDO_KEY);
            setLastBatch(null);
        }
    }, [isOpen]);

    const minutosRestantesDesfazer = useMemo(() => {
        if (!lastBatch?.timestamp) return 0;
        const elapsed = Date.now() - new Date(lastBatch.timestamp).getTime();
        return Math.max(0, Math.ceil((UNDO_WINDOW_MS - elapsed) / 60000));
    }, [lastBatch]);

    const gerarSimulacao = () => {
        const numericValue = parseFloat(adjustmentValue);
        if (!numericValue || numericValue <= 0) {
            toast.error("Informe um valor de reajuste válido");
            return;
        }

        if (tipoAjuste === "porcentagem" && numericValue > BULK_PRICE_CONSTANTS.MAX_ADJUSTMENT_PERCENT) {
            toast.error(`Limite máximo por operação: ${BULK_PRICE_CONSTANTS.MAX_ADJUSTMENT_PERCENT}%`);
            return;
        }

        if (tipoAjuste === "multiplicador" && numericValue === 1) {
            toast.error("Informe um multiplicador diferente de 1");
            return;
        }

        const result = buildSimulation({
            produtos: eligibleProducts,
            targetField,
            adjustmentType: tipoAjuste,
            operation: operacao,
            adjustmentValue,
        });

        setSimulation(result);
        setSelectedExecutionIds(result.executableRows.map((row) => row.id));
        toast.success(`Simulação gerada: ${result.summary.totalExecutaveis} item(ns) executáveis`);
    };

    const selecionarTodosElegiveis = () => {
        if (!simulation) return;
        setSelectedExecutionIds(executionRows.map((row) => row.id));
    };

    const limparSelecaoElegiveis = () => {
        setSelectedExecutionIds([]);
    };

    const toggleExecucaoSelecionada = (produtoId) => {
        setSelectedExecutionIds((prev) =>
            prev.includes(produtoId)
                ? prev.filter((id) => id !== produtoId)
                : [...prev, produtoId]
        );
    };

    const abrirEditarCadastro = (produto) => {
        setEditCadastroItem(produto);
        setEditPrecoCusto(String(produto?.preco_custo_tabela ?? produto?.preco_custo ?? 0));
        setEditPrecoVenda(String(produto?.preco_venda ?? 0));
        setEditCadastroOpen(true);
    };

    const salvarEdicaoCadastro = async () => {
        if (!editCadastroItem?.id) return;

        const custo = Number(editPrecoCusto);
        const venda = Number(editPrecoVenda);

        if (!(custo >= 0) || !(venda >= 0)) {
            toast.error("Informe valores válidos de custo e venda");
            return;
        }

        setSalvandoEdicaoCadastro(true);
        try {
            await base44.entities.Produto.update(editCadastroItem.id, {
                preco_custo_tabela: custo,
                preco_custo: custo,
                preco_venda: venda,
            });

            queryClient.invalidateQueries({ queryKey: ["produtos"] });
            setSimulation(null);
            setSelectedExecutionIds([]);
            setEditCadastroOpen(false);
            toast.success("Cadastro do item atualizado. Gere nova simulação.");
        } catch (error) {
            toast.error("Erro ao atualizar cadastro: " + error.message);
        } finally {
            setSalvandoEdicaoCadastro(false);
        }
    };

    const salvarSnapshotDesfazer = (snapshot) => {
        const payload = {
            targetField,
            rows: snapshot,
            timestamp: new Date().toISOString(),
            userName: user?.nome || user?.full_name || user?.email || "Sistema",
        };
        localStorage.setItem(UNDO_KEY, JSON.stringify(payload));
        setLastBatch(payload);
    };

    const desfazerUltimoLote = async () => {
        if (!lastBatch?.rows?.length) {
            toast.error("Nenhum lote disponível para desfazer");
            return;
        }

        if (minutosRestantesDesfazer <= 0) {
            toast.error("Janela de desfazer expirada");
            localStorage.removeItem(UNDO_KEY);
            setLastBatch(null);
            return;
        }

        const confirmed = await confirm({
            title: "Desfazer último lote",
            message: `Isso irá restaurar ${lastBatch.rows.length} item(ns) para o valor anterior em ${lastBatch.targetField}.`,
            confirmText: "Desfazer",
            variant: "destructive",
        });

        if (!confirmed) return;

        setAplicando(true);
        let restored = 0;
        const errors = [];

        for (const row of lastBatch.rows) {
            try {
                await base44.entities.Produto.update(row.id, {
                    [lastBatch.targetField]: row.oldValue,
                });

                await base44.entities.HistoricoPrecos?.create?.({
                    organization_id: row.organizationId || "00000000-0000-0000-0000-000000000001",
                    produto_id: row.id,
                    preco_antigo: row.newValue,
                    preco_novo: row.oldValue,
                    tipo: lastBatch.targetField === "preco_venda" ? "venda" : "custo",
                    motivo: "Desfazer reajuste em massa",
                    usuario_nome: user?.nome || user?.full_name || user?.email || "Sistema",
                });

                restored += 1;
            } catch (error) {
                errors.push(`${row.id}: ${error.message}`);
            }
        }

        try {
            await base44.entities.AuditLog.create({
                user_email: user?.email,
                user_name: user?.full_name || user?.nome,
                user_cargo: user?.cargo,
                action: "BULK_PRICE_UNDO",
                entity_type: "Produto",
                entity_id: `${restored}`,
                entity_description: `Desfazer reajuste em massa (${restored} restaurados, ${errors.length} erros)`,
                changes: {
                    targetField: lastBatch.targetField,
                    restored,
                    errors,
                },
                timestamp: new Date().toISOString(),
            });
        } catch (_error) {
            // Nao bloquear fluxo por erro de auditoria
        }

        localStorage.removeItem(UNDO_KEY);
        setLastBatch(null);
        queryClient.invalidateQueries({ queryKey: ["produtos"] });
        setAplicando(false);

        if (errors.length) {
            toast.warning(`Desfazer parcial: ${restored} restaurados, ${errors.length} com erro`);
            return;
        }

        toast.success(`Desfazer concluído: ${restored} item(ns)`);
    };

    const aplicarAjuste = async () => {
        if (!can("manage_bulk_price_adjustment")) {
            toast.error("Você não possui permissão para reajuste em massa");
            return;
        }

        if (!simulation) {
            toast.error("Gere a simulação antes de executar");
            return;
        }

        if (!selectedExecutableRows.length) {
            toast.error("Nenhum item executável na simulação");
            return;
        }

        const firstConfirm = await confirm({
            title: "Confirmar reajuste",
            message: `Executar reajuste em ${selectedExecutableRows.length} item(ns) no campo ${targetField}?\nItens bloqueados: ${blockedRows.length}`,
            confirmText: "Continuar",
            variant: "destructive",
        });
        if (!firstConfirm) return;

        if (selectedExecutableRows.length > 100) {
            const secondConfirm = await confirm({
                title: "Lote grande detectado",
                message: "Esta operação afeta mais de 100 itens. Confirme novamente para executar.",
                confirmText: "Executar lote",
                variant: "destructive",
            });
            if (!secondConfirm) return;
        }

        setAplicando(true);
        const snapshot = [];
        const errors = [];

        try {
            const batchSize = 25;
            for (let i = 0; i < selectedExecutableRows.length; i += batchSize) {
                const batch = selectedExecutableRows.slice(i, i + batchSize);

                await Promise.all(batch.map(async (row) => {
                    try {
                        await base44.entities.Produto.update(row.id, {
                            [targetField]: row.adjusted,
                        });

                        await base44.entities.HistoricoPrecos?.create?.({
                            organization_id: row.produto.organization_id || "00000000-0000-0000-0000-000000000001",
                            produto_id: row.id,
                            preco_antigo: row.current,
                            preco_novo: row.adjusted,
                            tipo: targetField === "preco_venda" ? "venda" : "custo",
                            motivo: "Reajuste em massa flexível",
                            usuario_nome: user?.nome || user?.full_name || user?.email || "Sistema",
                        });

                        snapshot.push({
                            id: row.id,
                            oldValue: row.current,
                            newValue: row.adjusted,
                            organizationId: row.produto.organization_id || "00000000-0000-0000-0000-000000000001",
                        });
                    } catch (error) {
                        errors.push(`${row.produto.nome || row.id}: ${error.message}`);
                    }
                }));
            }

            await base44.entities.AuditLog.create({
                user_email: user?.email,
                user_name: user?.full_name || user?.nome,
                user_cargo: user?.cargo,
                action: "BULK_PRICE_ADJUSTMENT",
                entity_type: "Produto",
                entity_id: `${snapshot.length}`,
                entity_description: `Reajuste em massa (${snapshot.length} sucesso, ${errors.length} erro)`,
                changes: {
                    targetField,
                    tipoAjuste,
                    operacao,
                    adjustmentValue,
                    criteria,
                    exceptionMode,
                    exceptionIds,
                    blockedCount: blockedRows.length,
                    selectedCount: selectedExecutableRows.length,
                    successCount: snapshot.length,
                    errorCount: errors.length,
                },
                timestamp: new Date().toISOString(),
            });

            if (snapshot.length) {
                salvarSnapshotDesfazer(snapshot);
            }

            queryClient.invalidateQueries({ queryKey: ["produtos"] });

            if (errors.length) {
                toast.warning(`Execução parcial: ${snapshot.length} sucesso, ${errors.length} erro`);
            } else {
                toast.success(`${snapshot.length} produto(s) atualizados com sucesso`);
            }

            setSimulation(null);
            if (!errors.length) {
                onClose();
            }
        } catch (error) {
            toast.error("Erro ao executar reajuste: " + error.message);
        } finally {
            setAplicando(false);
        }
    };

    const nomeCampoAlvo = targetField === "preco_venda" ? "Preço de Venda" : "Preço de Custo Tabela";

    const previewRowsSource = simulation?.rows || eligibleProducts;
    const totalPreviewRows = previewRowsSource.length;
    const totalPreviewPages = Math.max(1, Math.ceil(totalPreviewRows / PREVIEW_PAGE_SIZE));
    const currentPreviewPage = Math.min(previewPage, totalPreviewPages);
    const previewStartIndex = (currentPreviewPage - 1) * PREVIEW_PAGE_SIZE;

    const previewRowsSlice = useMemo(() => {
        return previewRowsSource.slice(previewStartIndex, previewStartIndex + PREVIEW_PAGE_SIZE);
    }, [previewRowsSource, previewStartIndex]);

    const previewRows = useMemo(() => {
        if (simulation) return previewRowsSlice;

        return previewRowsSlice.map((produto) => {
            const current = Number(produto[targetField] || 0);
            const adjusted = tipoAjuste === "porcentagem"
                ? (operacao === "aumentar"
                    ? current * (1 + (parseFloat(percentual || 0) / 100))
                    : current * (1 - (parseFloat(percentual || 0) / 100)))
                : tipoAjuste === "multiplicador"
                    ? current * parseFloat(valorFixo || 0)
                    : (operacao === "aumentar"
                        ? current + parseFloat(valorFixo || 0)
                        : Math.max(0, current - parseFloat(valorFixo || 0)));
            const deltaPercent = current > 0 ? ((adjusted - current) / current) * 100 : 0;

            return {
                id: produto.id,
                produto,
                current,
                adjusted: Math.round(adjusted * 100) / 100,
                deltaPercent,
                blocked: false,
                reasons: [],
            };
        });
    }, [simulation, previewRowsSlice, targetField, tipoAjuste, operacao, percentual, valorFixo]);

    return (
        <>
        <Dialog open={isOpen} onOpenChange={onClose}>
            <DialogContent className="max-w-6xl max-h-[90vh] overflow-hidden flex flex-col">
                <DialogHeader className="pb-4 border-b">
                    <DialogTitle className="text-xl font-semibold" style={{ color: "#07593f" }}>
                        Reajuste Flexível em Massa
                    </DialogTitle>
                </DialogHeader>

                <div className="flex-1 overflow-y-auto space-y-5 py-4">
                    {!can("manage_bulk_price_adjustment") && (
                        <div className="p-3 rounded-lg border border-red-200 bg-red-50 text-red-700 text-sm">
                            Você não possui permissão para executar reajuste em massa.
                        </div>
                    )}

                    {lastBatch?.rows?.length > 0 && minutosRestantesDesfazer > 0 && (
                        <div className="p-3 rounded-lg border border-amber-200 bg-amber-50 flex items-center justify-between gap-3">
                            <div className="text-sm text-amber-800">
                                Último lote disponível para desfazer: {lastBatch.rows.length} item(ns), janela restante {minutosRestantesDesfazer} min.
                            </div>
                            <Button
                                variant="outline"
                                className="border-amber-300 text-amber-800 hover:bg-amber-100"
                                onClick={desfazerUltimoLote}
                                disabled={aplicando}
                            >
                                <RotateCcw className="w-4 h-4 mr-2" />
                                Desfazer Último Lote
                            </Button>
                        </div>
                    )}

                    <div className="space-y-2">
                        <h3 className="text-sm font-semibold text-gray-900">1. Regra do reajuste</h3>
                        <p className="text-xs text-gray-600">Escolha o campo de preço e o comportamento das exceções para a simulação.</p>
                    </div>

                    <div className="grid md:grid-cols-2 gap-4 p-4 bg-gray-50 rounded-xl">
                        <div>
                            <Label className="text-sm font-medium text-gray-700 mb-2 block">Campo de preço</Label>
                            <Select value={targetField} onValueChange={setTargetField}>
                                <SelectTrigger>
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="preco_venda">Preço de Venda</SelectItem>
                                    <SelectItem value="preco_custo_tabela">Preço de Custo Tabela</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>

                        <div>
                            <Label className="text-sm font-medium text-gray-700 mb-2 block">Modo das exceções</Label>
                            <Select value={exceptionMode} onValueChange={setExceptionMode}>
                                <SelectTrigger>
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value={BULK_PRICE_CONSTANTS.EXCEPTION_MODES.INCLUDE_FILTER_EXCLUDE_ITEMS}>
                                        Excluir itens selecionados manualmente
                                    </SelectItem>
                                    <SelectItem value={BULK_PRICE_CONSTANTS.EXCEPTION_MODES.EXCLUDE_FILTER_INCLUDE_ITEMS}>
                                        Incluir apenas itens selecionados manualmente
                                    </SelectItem>
                                </SelectContent>
                            </Select>
                        </div>
                    </div>

                    <div className="space-y-2">
                        <h3 className="text-sm font-semibold text-gray-900">2. Itens alvo</h3>
                        <p className="text-xs text-gray-600">Defina os candidatos usando filtros de fabricante, categoria, status e faixa de preço.</p>
                    </div>

                    <div className="grid md:grid-cols-4 gap-3 p-4 border rounded-xl">
                        <div>
                            <Label className="text-xs text-gray-600">Fabricante</Label>
                            <Select
                                value={criteria.fabricantes || "todos"}
                                onValueChange={(value) => setCriteria((prev) => ({ ...prev, fabricantes: value === "todos" ? "" : value }))}
                            >
                                <SelectTrigger><SelectValue /></SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="todos">Todos os fabricantes</SelectItem>
                                    {uniqueManufacturers.map((fabricante) => (
                                        <SelectItem key={fabricante} value={fabricante}>{fabricante}</SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                        <div>
                            <Label className="text-xs text-gray-600">Categoria</Label>
                            <Select
                                value={criteria.categorias || "todas"}
                                onValueChange={(value) => setCriteria((prev) => ({ ...prev, categorias: value === "todas" ? "" : value }))}
                            >
                                <SelectTrigger><SelectValue /></SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="todas">Todas as categorias</SelectItem>
                                    {uniqueCategories.map((categoria) => (
                                        <SelectItem key={categoria} value={categoria}>{categoria}</SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                        <div>
                            <Label className="text-xs text-gray-600">Produto específico</Label>
                            <Input
                                value={criteria.searchTerm}
                                onChange={(e) => setCriteria((prev) => ({ ...prev, searchTerm: e.target.value }))}
                                placeholder="Nome, SKU, ID"
                            />
                        </div>
                        <div>
                            <Label className="text-xs text-gray-600">Status</Label>
                            <Select
                                value={criteria.status}
                                onValueChange={(value) => setCriteria((prev) => ({ ...prev, status: value }))}
                            >
                                <SelectTrigger><SelectValue /></SelectTrigger>
                                <SelectContent>
                                    <SelectItem value={BULK_PRICE_CONSTANTS.STATUS_OPTIONS.TODOS}>Todos</SelectItem>
                                    <SelectItem value={BULK_PRICE_CONSTANTS.STATUS_OPTIONS.ATIVO}>Somente ativos</SelectItem>
                                    <SelectItem value={BULK_PRICE_CONSTANTS.STATUS_OPTIONS.INATIVO}>Inativo</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>

                        <div>
                            <Label className="text-xs text-gray-600">Faixa de preço (mín.)</Label>
                            <Input type="number" value={criteria.precoMin} onChange={(e) => setCriteria((prev) => ({ ...prev, precoMin: e.target.value }))} />
                        </div>
                        <div>
                            <Label className="text-xs text-gray-600">Faixa de preço (máx.)</Label>
                            <Input type="number" value={criteria.precoMax} onChange={(e) => setCriteria((prev) => ({ ...prev, precoMax: e.target.value }))} />
                        </div>
                        <div>
                            <Label className="text-xs text-gray-600">Estoque (mín.)</Label>
                            <Input type="number" value={criteria.estoqueMin} onChange={(e) => setCriteria((prev) => ({ ...prev, estoqueMin: e.target.value }))} />
                        </div>
                        <div>
                            <Label className="text-xs text-gray-600">Estoque (máx.)</Label>
                            <Input type="number" value={criteria.estoqueMax} onChange={(e) => setCriteria((prev) => ({ ...prev, estoqueMax: e.target.value }))} />
                        </div>

                        <div>
                            <Label className="text-xs text-gray-600">Cadastro (de)</Label>
                            <Input type="date" lang="pt-BR" value={criteria.createdFrom} onChange={(e) => setCriteria((prev) => ({ ...prev, createdFrom: e.target.value }))} />
                        </div>
                        <div>
                            <Label className="text-xs text-gray-600">Cadastro (até)</Label>
                            <Input type="date" lang="pt-BR" value={criteria.createdTo} onChange={(e) => setCriteria((prev) => ({ ...prev, createdTo: e.target.value }))} />
                        </div>

                        <div>
                            <Label className="text-xs text-gray-600">Atualização (de)</Label>
                            <Input type="date" lang="pt-BR" value={criteria.updatedFrom} onChange={(e) => setCriteria((prev) => ({ ...prev, updatedFrom: e.target.value }))} />
                        </div>
                        <div>
                            <Label className="text-xs text-gray-600">Atualização (até)</Label>
                            <Input type="date" lang="pt-BR" value={criteria.updatedTo} onChange={(e) => setCriteria((prev) => ({ ...prev, updatedTo: e.target.value }))} />
                        </div>
                    </div>

                    <div className="space-y-2">
                        <h3 className="text-sm font-semibold text-gray-900">3. Forma de cálculo</h3>
                        <p className="text-xs text-gray-600">Defina tipo, direção e valor do reajuste.</p>
                    </div>

                    <div className="space-y-2">
                        <h3 className="text-sm font-semibold text-gray-900">4. Ajustes manuais (exceções)</h3>
                        <p className="text-xs text-gray-600">Inclua ou exclua itens pontuais sem alterar os filtros principais.</p>
                    </div>

                    <div className="grid md:grid-cols-2 gap-4 p-4 border rounded-xl">
                        <div className="space-y-3">
                            <div className="flex gap-2">
                                <Button
                                    type="button"
                                    variant={tipoAjuste === "porcentagem" ? "default" : "outline"}
                                    onClick={() => setTipoAjuste("porcentagem")}
                                    className={tipoAjuste === "porcentagem" ? "bg-green-600 hover:bg-green-700" : ""}
                                >
                                    <Percent className="w-4 h-4 mr-2" />
                                    Porcentagem
                                </Button>
                                <Button
                                    type="button"
                                    variant={tipoAjuste === "fixo" ? "default" : "outline"}
                                    onClick={() => setTipoAjuste("fixo")}
                                    className={tipoAjuste === "fixo" ? "bg-blue-600 hover:bg-blue-700" : ""}
                                >
                                    <DollarSign className="w-4 h-4 mr-2" />
                                    Valor Fixo
                                </Button>
                                <Button
                                    type="button"
                                    variant={tipoAjuste === "multiplicador" ? "default" : "outline"}
                                    onClick={() => setTipoAjuste("multiplicador")}
                                    className={tipoAjuste === "multiplicador" ? "bg-violet-600 hover:bg-violet-700" : ""}
                                >
                                    Multiplicador
                                </Button>
                            </div>

                            {tipoAjuste !== "multiplicador" && (
                                <div className="flex gap-2">
                                    <Button
                                        type="button"
                                        variant={operacao === "aumentar" ? "default" : "outline"}
                                        onClick={() => setOperacao("aumentar")}
                                        className={operacao === "aumentar" ? "bg-green-600 hover:bg-green-700" : ""}
                                    >
                                        <TrendingUp className="w-4 h-4 mr-2" />
                                        Aumentar
                                    </Button>
                                    <Button
                                        type="button"
                                        variant={operacao === "diminuir" ? "default" : "outline"}
                                        onClick={() => setOperacao("diminuir")}
                                        className={operacao === "diminuir" ? "bg-red-600 hover:bg-red-700" : ""}
                                    >
                                        <TrendingDown className="w-4 h-4 mr-2" />
                                        Diminuir
                                    </Button>
                                </div>
                            )}
                        </div>

                        <div>
                            <Label className="text-xs text-gray-600">Valor do reajuste</Label>
                            <Input
                                type="number"
                                min="0"
                                max={tipoAjuste === "porcentagem" ? "20" : "999999"}
                                step={tipoAjuste === "porcentagem" ? "0.5" : tipoAjuste === "multiplicador" ? "0.01" : "0.01"}
                                value={adjustmentValue}
                                onChange={(e) => tipoAjuste === "porcentagem" ? setPercentual(e.target.value) : setValorFixo(e.target.value)}
                                placeholder={tipoAjuste === "porcentagem" ? "Ex: 5" : tipoAjuste === "multiplicador" ? "Ex: 1.08" : "Ex: 50"}
                            />
                            <p className="text-xs text-gray-500 mt-1">
                                {tipoAjuste === "multiplicador"
                                    ? "Use fator direto. Ex.: 1.05 aumenta 5%, 0.95 reduz 5%."
                                    : "Limite de segurança: 20% por item."}
                            </p>
                        </div>
                    </div>

                    <div className="grid md:grid-cols-2 gap-4 p-4 border rounded-xl">
                        <div>
                            <Label className="text-xs text-gray-600">Buscar exceções</Label>
                            <Input
                                value={exceptionSearch}
                                onChange={(e) => setExceptionSearch(e.target.value)}
                                placeholder="Digite nome, SKU ou ID"
                            />
                            <div className="mt-2 space-y-1 max-h-28 overflow-auto">
                                {exceptionSuggestions.map((produto) => {
                                    const selected = exceptionIds.includes(produto.id);
                                    return (
                                        <button
                                            key={produto.id}
                                            type="button"
                                            className={`w-full text-left px-2 py-1 rounded text-xs border ${selected ? "bg-blue-50 border-blue-300" : "bg-white hover:bg-gray-50"}`}
                                            onClick={() => toggleException(produto.id)}
                                        >
                                            {produto.nome} ({produto.codigo_barras || produto.id})
                                        </button>
                                    );
                                })}
                            </div>
                        </div>

                        <div>
                            <Label className="text-xs text-gray-600">Exceções ativas ({exceptionProducts.length})</Label>
                            <div className="max-h-32 overflow-auto border rounded p-2 text-xs space-y-1">
                                {exceptionProducts.length === 0 && (
                                    <div className="text-gray-500">Nenhuma exceção selecionada.</div>
                                )}
                                {exceptionProducts.map((produto) => (
                                    <div key={produto.id} className="flex items-center justify-between gap-2">
                                        <span className="truncate">{produto.nome}</span>
                                        <Button size="sm" variant="ghost" onClick={() => removeException(produto.id)}>Remover</Button>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>

                    <div className="p-3 rounded-lg border bg-gray-50 text-sm text-gray-700 grid md:grid-cols-3 gap-3">
                        <div>Base pelos filtros: <span className="font-semibold">{filteredProducts.length}</span></div>
                        <div>Elegíveis após exceções: <span className="font-semibold">{eligibleProducts.length}</span></div>
                        <div>Campo de preço: <span className="font-semibold">{nomeCampoAlvo}</span></div>
                    </div>

                    <div className="space-y-2">
                        <h3 className="text-sm font-semibold text-gray-900">5. Simulação e validação</h3>
                        <p className="text-xs text-gray-600">Simule antes de executar e verifique os itens que requerem ajuste.</p>
                    </div>

                    <div className="flex items-center gap-3">
                        <Button onClick={gerarSimulacao} disabled={!can("manage_bulk_price_adjustment") || aplicando}>
                            Simular reajuste
                        </Button>
                        {simulation && (
                            <>
                                <Button variant="outline" onClick={selecionarTodosElegiveis} disabled={aplicando || !executionRows.length}>
                                    Selecionar todos elegíveis
                                </Button>
                                <Button variant="outline" onClick={limparSelecaoElegiveis} disabled={aplicando || !selectedExecutionIds.length}>
                                    Limpar seleção
                                </Button>
                            </>
                        )}
                        {simulation && (
                            <div className="text-sm text-gray-600">
                                Prontos para aplicar: <span className="font-semibold text-green-700">{simulation.summary.totalExecutaveis}</span> | Selecionados: <span className="font-semibold text-blue-700">{selectedExecutableRows.length}</span> | Requer ajuste: <span className="font-semibold text-red-700">{simulation.summary.totalBloqueados}</span>
                            </div>
                        )}
                    </div>

                    {simulation && (
                        <div className="p-3 rounded-lg border border-blue-200 bg-blue-50 text-sm">
                            <div className="font-medium text-blue-900 mb-2">Resumo da simulação</div>
                            <div className="grid md:grid-cols-4 gap-2 text-blue-900">
                                <div>Total elegíveis: {simulation.summary.totalElegiveis}</div>
                                <div>Prontos para aplicar: {simulation.summary.totalExecutaveis}</div>
                                <div>Soma atual: {formatMoney(simulation.summary.somaAtual)}</div>
                                <div>Soma nova: {formatMoney(simulation.summary.somaNova)}</div>
                            </div>
                            <div className="mt-2">Impacto total: <span className={simulation.summary.impactoTotal >= 0 ? "text-green-700 font-semibold" : "text-red-700 font-semibold"}>{formatMoney(simulation.summary.impactoTotal)}</span></div>
                        </div>
                    )}

                    <div className="border rounded-xl overflow-hidden">
                        <div className="px-3 py-2 border-b bg-gray-50 flex items-center justify-between text-xs text-gray-600">
                            <span>
                                Mostrando {Math.min(totalPreviewRows, previewStartIndex + 1)}-{Math.min(totalPreviewRows, previewStartIndex + previewRows.length)} de {totalPreviewRows} item(ns)
                            </span>
                            <div className="flex items-center gap-2">
                                <Button
                                    type="button"
                                    variant="outline"
                                    size="sm"
                                    onClick={() => setPreviewPage((prev) => Math.max(1, prev - 1))}
                                    disabled={currentPreviewPage <= 1}
                                >
                                    <ChevronLeft className="w-4 h-4" />
                                </Button>
                                <span>Página {currentPreviewPage} de {totalPreviewPages}</span>
                                <Button
                                    type="button"
                                    variant="outline"
                                    size="sm"
                                    onClick={() => setPreviewPage((prev) => Math.min(totalPreviewPages, prev + 1))}
                                    disabled={currentPreviewPage >= totalPreviewPages}
                                >
                                    <ChevronRight className="w-4 h-4" />
                                </Button>
                            </div>
                        </div>
                        <div className="max-h-[280px] overflow-y-auto">
                            <Table>
                                <TableHeader className="bg-gray-50 sticky top-0">
                                    <TableRow>
                                        <TableHead className="w-16">Aplicar?</TableHead>
                                        <TableHead>Produto</TableHead>
                                        <TableHead className="text-right">Atual</TableHead>
                                        <TableHead className="text-right">Novo</TableHead>
                                        <TableHead className="text-right">Var. %</TableHead>
                                        <TableHead>Status</TableHead>
                                    </TableRow>
                                </TableHeader>
                                <TableBody>
                                    {previewRows.map((row) => {
                                        const selectedExecution = selectedExecutionIds.includes(row.id);
                                        return (
                                            <TableRow key={row.id} className={row.blocked ? "bg-red-50" : ""}>
                                                <TableCell>
                                                    <Checkbox
                                                        checked={selectedExecution}
                                                        disabled={row.blocked}
                                                        onCheckedChange={() => toggleExecucaoSelecionada(row.id)}
                                                    />
                                                </TableCell>
                                                <TableCell>
                                                    <p className="font-medium text-sm truncate max-w-[280px]">{row.produto.nome}</p>
                                                    <p className="text-xs text-gray-500">{row.produto.categoria || "Sem categoria"}</p>
                                                </TableCell>
                                                <TableCell className="text-right font-mono text-sm">{formatMoney(row.current)}</TableCell>
                                                <TableCell className="text-right font-mono text-sm">{formatMoney(row.adjusted)}</TableCell>
                                                <TableCell className={`text-right text-sm ${row.deltaPercent >= 0 ? "text-green-700" : "text-red-700"}`}>
                                                    {row.deltaPercent.toFixed(2)}%
                                                </TableCell>
                                                <TableCell className="text-xs">
                                                    {row.blocked ? (
                                                        <div className="text-red-700 flex items-center gap-1">
                                                            <ShieldAlert className="w-3 h-3" />
                                                            <span>{row.reasons.join("; ")}</span>
                                                            {row.reasons.some((reason) => String(reason).toLowerCase().includes("menor ou igual a zero")) && (
                                                                <Button
                                                                    type="button"
                                                                    variant="link"
                                                                    size="sm"
                                                                    className="h-auto p-0 text-red-800 underline"
                                                                    onClick={() => abrirEditarCadastro(row.produto)}
                                                                >
                                                                    corrigir cadastro
                                                                </Button>
                                                            )}
                                                        </div>
                                                    ) : (
                                                        <span className="text-green-700">Pronto para aplicar</span>
                                                    )}
                                                </TableCell>
                                            </TableRow>
                                        );
                                    })}
                                </TableBody>
                            </Table>
                        </div>
                    </div>
                </div>

                <div className="pt-4 border-t space-y-2">
                    <h3 className="text-sm font-semibold text-gray-900">6. Execução</h3>
                    <div className="flex items-center justify-between">
                    <div className="text-sm text-gray-600">
                        {simulation
                            ? `${selectedExecutableRows.length} item(ns) selecionados para execução em ${nomeCampoAlvo}`
                            : "Simule o reajuste para liberar a execução"}
                    </div>

                    <div className="flex gap-3">
                        <Button variant="outline" onClick={onClose}>
                            Cancelar
                        </Button>
                        <Button
                            onClick={aplicarAjuste}
                            disabled={
                                aplicando ||
                                !simulation ||
                                !selectedExecutableRows.length ||
                                !can("manage_bulk_price_adjustment")
                            }
                            className="min-w-[180px] bg-green-700 hover:bg-green-800"
                        >
                            {aplicando ? (
                                <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                            ) : (
                                <CheckCircle className="w-4 h-4 mr-2" />
                            )}
                            Executar Reajuste
                        </Button>
                    </div>
                    </div>
                </div>
            </DialogContent>

        </Dialog>

        <Dialog open={editCadastroOpen} onOpenChange={setEditCadastroOpen}>
            <DialogContent className="max-w-md">
                <DialogHeader>
                    <DialogTitle>Editar Cadastro do Item</DialogTitle>
                </DialogHeader>

                <div className="space-y-4 py-2">
                    <div className="text-sm text-gray-700 font-medium">
                        {editCadastroItem?.nome || "Produto"}
                    </div>
                    <div>
                        <Label>Preço de Custo</Label>
                        <Input
                            type="number"
                            min="0"
                            step="0.01"
                            value={editPrecoCusto}
                            onChange={(e) => setEditPrecoCusto(e.target.value)}
                        />
                    </div>
                    <div>
                        <Label>Preço de Venda</Label>
                        <Input
                            type="number"
                            min="0"
                            step="0.01"
                            value={editPrecoVenda}
                            onChange={(e) => setEditPrecoVenda(e.target.value)}
                        />
                    </div>
                </div>

                <DialogFooter>
                    <Button variant="outline" onClick={() => setEditCadastroOpen(false)}>
                        Cancelar
                    </Button>
                    <Button onClick={salvarEdicaoCadastro} disabled={salvandoEdicaoCadastro}>
                        {salvandoEdicaoCadastro && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
                        Salvar Cadastro
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
        </>
    );
}

import React, { useState, useEffect } from 'react';
import { useTenant } from '@/contexts/TenantContext';
import { useAuth } from '@/hooks/useAuth';
import { supabase } from '@/lib/supabase';
import { toast } from 'sonner';
import EscolhaPlano from './EscolhaPlano';
import {
  CreditCard, QrCode, FileText, Loader2, LogOut,
  AlertTriangle, CheckCircle, Clock, Copy, ExternalLink, RefreshCw
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle, CardDescription, CardFooter } from '@/components/ui/card';

export default function BlockedSubscriptionScreen() {
  const { organization, refreshTenant } = useTenant();
  const { logout } = useAuth();
  const [loadingPending, setLoadingPending] = useState(false);
  const [pendingPayment, setPendingPayment] = useState(null);
  const [checkingStatus, setCheckingStatus] = useState(false);
  const [showPlanSelection, setShowPlanSelection] = useState(false);

  const fetchPendingPaymentDetails = async () => {
    if (!organization?.asaas_subscription_id) return;
    
    try {
      setLoadingPending(true);
      const { data, error } = await supabase.functions.invoke("criar-assinatura", {
        body: { action: "get-pending-payment" }
      });

      if (error) {
        let msg = error.message || 'Erro ao buscar cobrança pendente.';
        if (error.context && typeof error.context.json === 'function') {
          try {
            const body = await error.context.json();
            if (body?.error) msg = body.error;
          } catch (_) {}
        }
        throw new Error(msg);
      }
      
      if (data && data.paymentId) {
        if (['CONFIRMED', 'RECEIVED', 'RECEIVED_IN_CASH'].includes(data.status)) {
          toast.success("Pagamento confirmado! Seu acesso foi liberado.");
          await refreshTenant();
          return;
        }
        setPendingPayment(data);
      } else {
        setPendingPayment(null);
      }
    } catch (err) {
      console.error("Erro ao buscar cobrança pendente:", err);
    } finally {
      setLoadingPending(false);
    }
  };

  useEffect(() => {
    fetchPendingPaymentDetails();
  }, [organization?.asaas_subscription_id]);

  const handleRefreshStatus = async () => {
    try {
      setCheckingStatus(true);
      await refreshTenant();
      toast.success("Status atualizado!");
    } catch (err) {
      toast.error("Erro ao atualizar o status.");
    } finally {
      setCheckingStatus(false);
    }
  };

  const [isCanceling, setIsCanceling] = useState(false);
  
  const handleCancelPending = async () => {
    if (!confirm("Tem certeza que deseja cancelar esta fatura? Você poderá escolher o plano e a forma de pagamento novamente.")) return;
    
    try {
      setIsCanceling(true);
      const { data, error } = await supabase.functions.invoke("criar-assinatura", {
        body: { action: "cancel-and-restart" }
      });
      
      if (error) throw error;
      
      toast.success("Fatura cancelada com sucesso. Escolha seu plano novamente.");
      await refreshTenant();
      setShowPlanSelection(true);
    } catch (err) {
      console.error(err);
      toast.error("Erro ao cancelar a fatura.");
    } finally {
      setIsCanceling(false);
    }
  };

  const copyToClipboard = (text) => {
    navigator.clipboard.writeText(text);
    toast.success("Código copiado com sucesso!");
  };

  const formatCurrency = (val) => {
    return new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(val);
  };

  // Obter detalhes de layout com base no status real da assinatura
  const getStatusInfo = () => {
    switch (organization?.status_assinatura) {
      case 'processando':
        return {
          title: "Assinatura Pendente de Pagamento",
          description: "O pagamento da sua assinatura ainda não foi confirmado pelo Asaas.",
          icon: <Clock className="w-12 h-12 text-amber-500" />,
          bgColor: "bg-amber-50 dark:bg-amber-950/20",
          textColor: "text-amber-800 dark:text-amber-400",
          borderColor: "border-amber-200 dark:border-amber-900/30"
        };
      case 'atrasada':
        return {
          title: "Assinatura Vencida / Atrasada",
          description: "Detectamos atraso no pagamento da sua assinatura e o acesso ao painel foi suspenso.",
          icon: <AlertTriangle className="w-12 h-12 text-rose-500" />,
          bgColor: "bg-rose-50 dark:bg-rose-950/20",
          textColor: "text-rose-800 dark:text-rose-400",
          borderColor: "border-rose-200 dark:border-rose-900/30"
        };
      case 'cancelada':
        return {
          title: "Assinatura Cancelada",
          description: "A assinatura da sua empresa foi cancelada. Entre em contato com o suporte para reativar.",
          icon: <AlertTriangle className="w-12 h-12 text-gray-500" />,
          bgColor: "bg-gray-50 dark:bg-gray-800/20",
          textColor: "text-gray-800 dark:text-gray-400",
          borderColor: "border-gray-200 dark:border-gray-700/30"
        };
      default:
        return {
          title: "Acesso Bloqueado",
          description: "Não identificamos uma assinatura ativa para esta organização.",
          icon: <AlertTriangle className="w-12 h-12 text-amber-500" />,
          bgColor: "bg-amber-50 dark:bg-amber-950/20",
          textColor: "text-amber-800 dark:text-amber-400",
          borderColor: "border-amber-200 dark:border-amber-900/30"
        };
    }
  };

  const statusInfo = getStatusInfo();

  if (showPlanSelection) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-neutral-950 p-4">
        <div className="w-full max-w-4xl bg-white dark:bg-neutral-900 p-6 rounded-2xl border shadow-lg">
          <EscolhaPlano onCancel={() => setShowPlanSelection(false)} />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-neutral-950 p-4">
      <div className="w-full max-w-2xl space-y-6">
        <Card className={`border shadow-lg ${statusInfo.borderColor}`}>
          <CardHeader className={`flex flex-col items-center text-center p-6 rounded-t-xl ${statusInfo.bgColor}`}>
            <div className="mb-4">
              {statusInfo.icon}
            </div>
            <CardTitle className={`text-2xl font-bold ${statusInfo.textColor}`}>
              {statusInfo.title}
            </CardTitle>
            <CardDescription className="text-gray-600 dark:text-gray-300 max-w-md mt-2">
              {statusInfo.description}
            </CardDescription>
          </CardHeader>
          
          <CardContent className="p-6 space-y-6">
            <div className="text-sm border rounded-xl p-4 bg-white dark:bg-neutral-900 space-y-2">
              <div className="flex justify-between">
                <span className="text-gray-500">Organização:</span>
                <span className="font-semibold text-gray-800 dark:text-gray-200">{organization?.name}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-500">CNPJ:</span>
                <span className="font-mono text-gray-800 dark:text-gray-200">{organization?.cnpj || 'Não cadastrado'}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-500">Status atual:</span>
                <span className="capitalize font-semibold text-gray-800 dark:text-gray-200">
                  {organization?.status_assinatura?.replace('_', ' ') || 'Pendente'}
                </span>
              </div>
            </div>

            {loadingPending ? (
              <div className="flex flex-col items-center justify-center py-8">
                <Loader2 className="w-8 h-8 animate-spin text-green-700 mb-2" />
                <p className="text-sm text-gray-500">Carregando detalhes do pagamento...</p>
              </div>
            ) : pendingPayment ? (
              <Card className="border-green-100 dark:border-green-900/30 shadow-inner">
                <CardHeader className="p-4 bg-green-50/50 dark:bg-green-900/10">
                  <CardTitle className="text-sm font-semibold flex items-center gap-2 text-green-800 dark:text-green-400">
                    <QrCode className="w-4 h-4" /> Dados para Pagamento
                  </CardTitle>
                </CardHeader>
                <CardContent className="p-4 space-y-6">
                  {pendingPayment.status && !['PENDING', 'OVERDUE'].includes(pendingPayment.status) && (
                    <div className="bg-red-50 dark:bg-red-900/20 text-red-800 dark:text-red-400 p-3 rounded-lg text-sm flex items-start gap-2 border border-red-200 dark:border-red-800">
                      <AlertTriangle className="w-5 h-5 shrink-0 mt-0.5" />
                      <p>
                        Atenção: O status atual do pagamento é <strong>{pendingPayment.status}</strong>. 
                        Isso pode indicar que o pagamento foi recusado ou falhou. Considere cancelar a fatura atual e tentar novamente.
                      </p>
                    </div>
                  )}
                  <div className="flex flex-col md:flex-row gap-6 items-center">
                    {pendingPayment.pixQrCode && (
                      <div className="flex flex-col items-center p-3 bg-white border rounded-xl shadow-inner shrink-0">
                        <img 
                          src={`data:image/png;base64,${pendingPayment.pixQrCode}`} 
                          alt="QR Code Pix"
                          className="w-36 h-36 object-contain"
                        />
                        <span className="text-[10px] text-gray-400 mt-1">Escaneie no App do banco</span>
                      </div>
                    )}
                    
                    <div className="flex-1 w-full space-y-4">
                      <div className="grid grid-cols-2 gap-4 text-sm">
                        <div>
                          <span className="text-xs text-gray-400 font-semibold block">Valor da Fatura</span>
                          <span className="text-lg font-bold text-gray-800 dark:text-gray-200">{formatCurrency(pendingPayment.value)}</span>
                        </div>
                        <div>
                          <span className="text-xs text-gray-400 font-semibold block">Vencimento</span>
                          <span className="text-lg font-bold text-gray-800 dark:text-gray-200">
                            {new Date(pendingPayment.dueDate + "T12:00:00").toLocaleDateString("pt-BR")}
                          </span>
                        </div>
                      </div>

                      <div className="flex flex-wrap gap-2 pt-2">
                        {pendingPayment.pixCopiaCola && (
                          <Button 
                            variant="outline"
                            size="sm"
                            onClick={() => copyToClipboard(pendingPayment.pixCopiaCola)}
                            className="text-gray-700 hover:bg-gray-100"
                          >
                            <Copy className="w-3.5 h-3.5 mr-1.5" />
                            Copia e Cola
                          </Button>
                        )}

                        {pendingPayment.bankSlipUrl && (
                          <Button 
                            variant="outline"
                            size="sm"
                            onClick={() => window.open(pendingPayment.bankSlipUrl, "_blank")}
                            className="text-gray-700 hover:bg-gray-100"
                          >
                            <FileText className="w-3.5 h-3.5 mr-1.5" />
                            Ver Boleto
                          </Button>
                        )}

                        {pendingPayment.invoiceUrl && (
                          <Button 
                            variant="outline"
                            size="sm"
                            onClick={() => window.open(pendingPayment.invoiceUrl, "_blank")}
                            className="text-gray-700 hover:bg-gray-100"
                          >
                            <ExternalLink className="w-3.5 h-3.5 mr-1.5" />
                            Abrir Fatura
                          </Button>
                        )}

                        <Button 
                          variant="outline"
                          size="sm"
                          onClick={() => setShowPlanSelection(true)}
                          className="text-amber-700 border-amber-200 hover:bg-amber-50 hover:text-amber-800"
                        >
                          <RefreshCw className="w-3.5 h-3.5 mr-1.5" />
                          Alterar Plano
                        </Button>

                        <Button 
                          variant="outline"
                          size="sm"
                          onClick={handleCancelPending}
                          disabled={isCanceling}
                          className="text-red-700 border-red-200 hover:bg-red-50 hover:text-red-800"
                        >
                          {isCanceling ? <Loader2 className="w-3.5 h-3.5 mr-1.5 animate-spin" /> : <LogOut className="w-3.5 h-3.5 mr-1.5" />}
                          Cancelar Fatura Atual
                        </Button>
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ) : (
              organization?.status_assinatura !== 'cancelada' && (
                <div className="text-center py-6 px-4 space-y-4 text-gray-500 text-sm border border-dashed rounded-xl bg-gray-50/50">
                  <div className="space-y-1">
                    <p className="font-medium text-gray-700 dark:text-gray-300">Nenhuma cobrança ativa pendente encontrada no Asaas.</p>
                    <p className="text-xs text-gray-400">Isso pode ocorrer se os dados de faturamento (como CNPJ/CPF) estiverem incorretos ou se a assinatura não pôde ser gerada no Asaas.</p>
                  </div>
                  <Button 
                    variant="outline" 
                    onClick={() => setShowPlanSelection(true)}
                    className="border-green-700 text-green-700 hover:bg-green-50 hover:text-green-800"
                  >
                    Configurar Assinatura / Corrigir CNPJ
                  </Button>
                </div>
              )
            )}
          </CardContent>

          <CardFooter className="flex flex-col sm:flex-row gap-3 border-t p-6 bg-gray-50/50 dark:bg-neutral-900/50 rounded-b-xl">
            <Button
              onClick={handleRefreshStatus}
              disabled={checkingStatus}
              className="w-full sm:flex-1 bg-green-700 hover:bg-green-800 text-white font-medium shadow"
            >
              {checkingStatus ? (
                <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Verificando...</>
              ) : (
                <><RefreshCw className="w-4 h-4 mr-2" /> Já efetuei o pagamento / Atualizar</>
              )}
            </Button>
            
            <Button
              variant="outline"
              onClick={logout}
              className="w-full sm:w-auto border-red-200 text-red-700 hover:bg-red-50 hover:text-red-800"
            >
              <LogOut className="w-4 h-4 mr-2" />
              Sair da Conta
            </Button>
          </CardFooter>
        </Card>
      </div>
    </div>
  );
}

import React, { useMemo, createElement } from "react";
import { Badge } from "@/components/ui/badge";
import { Shield, X, ChevronUp, ChevronDown } from "lucide-react";
import { CARGOS } from "@/config/cargos";

/**
 * Seletor de múltiplos cargos com checkboxes.
 *
 * Props:
 *   value         — array de strings com cargos selecionados (ex: ["Vendedor", "Financeiro"])
 *   onChange      — callback(novoArray: string[])
 *   extraCargos   — array de cargos adicionais (cargos custom do banco), formato { value, label, color, icon? }
 *   disabled      — boolean
 */
export default function CargosMultiSelect({ value = [], onChange, extraCargos = [], disabled = false }) {
    // Todos os cargos disponíveis: estáticos + custom do banco
    const allCargos = useMemo(() => {
        const staticValues = new Set(CARGOS.map(c => c.value));
        const customList = extraCargos
            .filter(c => !staticValues.has(c.value))
            .map(c => ({
                value:       c.value,
                label:       c.label || c.value,
                color:       c.color || '#6b7280',
                bgColor:     `${c.color || '#6b7280'}18`,
                icon:        Shield,
                isCustom:    true,
            }));
        return [...CARGOS, ...customList];
    }, [extraCargos]);

    const toggle = (cargoValue) => {
        if (disabled) return;
        if (value.includes(cargoValue)) {
            onChange(value.filter(v => v !== cargoValue));
        } else {
            onChange([...value, cargoValue]);
        }
    };

    const moveUp = (index) => {
        if (index === 0 || disabled) return;
        const next = [...value];
        [next[index - 1], next[index]] = [next[index], next[index - 1]];
        onChange(next);
    };

    const moveDown = (index) => {
        if (index === value.length - 1 || disabled) return;
        const next = [...value];
        [next[index], next[index + 1]] = [next[index + 1], next[index]];
        onChange(next);
    };

    const remove = (cargoValue) => {
        if (disabled) return;
        onChange(value.filter(v => v !== cargoValue));
    };

    return (
        <div className="space-y-3">
            {/* Chips dos cargos selecionados com ordem */}
            {value.length > 0 && (
                <div className="space-y-1">
                    <p className="text-xs text-gray-500 font-medium">Cargos selecionados (o primeiro é o principal):</p>
                    <div className="space-y-1">
                        {value.map((cargoValue, idx) => {
                            const cfg = allCargos.find(c => c.value === cargoValue);
                            const color = cfg?.color || '#6b7280';
                            return (
                                <div
                                    key={cargoValue}
                                    className="flex items-center gap-2 p-2 rounded-lg border"
                                    style={{
                                        backgroundColor: `${color}10`,
                                        borderColor: `${color}40`,
                                    }}
                                >
                                    {/* Ordem */}
                                    <span
                                        className="w-5 h-5 rounded-full flex items-center justify-center text-xs font-bold flex-shrink-0"
                                        style={{ backgroundColor: color, color: '#fff' }}
                                    >
                                        {idx + 1}
                                    </span>

                                    {/* Ícone + label */}
                                    {cfg?.icon && createElement(cfg.icon, {
                                        className: "w-3.5 h-3.5 flex-shrink-0",
                                        style: { color }
                                    })}
                                    <span className="text-sm font-medium flex-1" style={{ color }}>
                                        {cfg?.label || cargoValue}
                                        {idx === 0 && (
                                            <span className="ml-2 text-xs font-normal text-gray-400">(principal)</span>
                                        )}
                                    </span>

                                    {/* Botões de reordenação */}
                                    {!disabled && (
                                        <div className="flex gap-0.5">
                                            <button
                                                type="button"
                                                onClick={() => moveUp(idx)}
                                                disabled={idx === 0}
                                                className="p-0.5 rounded hover:bg-gray-200 disabled:opacity-30 disabled:cursor-not-allowed"
                                                title="Mover para cima"
                                            >
                                                <ChevronUp className="w-3.5 h-3.5 text-gray-500" />
                                            </button>
                                            <button
                                                type="button"
                                                onClick={() => moveDown(idx)}
                                                disabled={idx === value.length - 1}
                                                className="p-0.5 rounded hover:bg-gray-200 disabled:opacity-30 disabled:cursor-not-allowed"
                                                title="Mover para baixo"
                                            >
                                                <ChevronDown className="w-3.5 h-3.5 text-gray-500" />
                                            </button>
                                            <button
                                                type="button"
                                                onClick={() => remove(cargoValue)}
                                                className="p-0.5 rounded hover:bg-red-100 ml-1"
                                                title="Remover cargo"
                                            >
                                                <X className="w-3.5 h-3.5 text-red-500" />
                                            </button>
                                        </div>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* Grade de cargos disponíveis */}
            <div className="space-y-1">
                <p className="text-xs text-gray-500 font-medium">Cargos disponíveis:</p>
                <div className="grid grid-cols-2 gap-1.5 max-h-56 overflow-y-auto pr-1">
                    {allCargos.map(cargo => {
                        const selected = value.includes(cargo.value);
                        return (
                            <button
                                key={cargo.value}
                                type="button"
                                onClick={() => toggle(cargo.value)}
                                disabled={disabled}
                                className={`
                                    w-full text-left px-3 py-2 rounded-lg border-2 transition-all text-sm
                                    ${selected
                                        ? 'shadow-sm scale-[1.01]'
                                        : 'border-gray-200 bg-gray-50 opacity-60 hover:opacity-100 hover:border-gray-300'
                                    }
                                    disabled:cursor-not-allowed
                                `}
                                style={selected ? {
                                    backgroundColor: `${cargo.color}12`,
                                    borderColor: cargo.color,
                                } : {}}
                            >
                                <div className="flex items-center gap-2">
                                    {/* Checkbox visual */}
                                    <div
                                        className={`w-4 h-4 rounded border-2 flex items-center justify-center flex-shrink-0 transition-colors ${
                                            selected ? 'border-current' : 'border-gray-300 bg-white'
                                        }`}
                                        style={selected ? { borderColor: cargo.color, backgroundColor: cargo.color } : {}}
                                    >
                                        {selected && (
                                            <svg className="w-2.5 h-2.5 text-white" fill="none" viewBox="0 0 12 12">
                                                <path d="M2 6l3 3 5-5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                                            </svg>
                                        )}
                                    </div>

                                    {createElement(cargo.icon || Shield, {
                                        className: "w-3.5 h-3.5 flex-shrink-0",
                                        style: { color: cargo.color }
                                    })}

                                    <span
                                        className="font-medium truncate"
                                        style={{ color: selected ? cargo.color : '#374151' }}
                                    >
                                        {cargo.label}
                                    </span>

                                    {cargo.isCustom && (
                                        <Badge className="bg-purple-100 text-purple-700 text-xs px-1 ml-auto flex-shrink-0">
                                            Custom
                                        </Badge>
                                    )}
                                </div>
                            </button>
                        );
                    })}
                </div>
            </div>
        </div>
    );
}

import React, { useState, useEffect } from "react";
import { supabase } from "@/lib/supabase";
import { useTenant } from "@/contexts/TenantContext";
import { toast } from "sonner";
import { 
  Check, 
  Loader2, 
  AlertTriangle, 
  FileText, 
  Sparkles, 
  Trash2, 
  ExternalLink, 
  ShieldCheck,
  RefreshCw,
  Copy,
  Info
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";

import EscolhaPlano from "./EscolhaPlano";
import PlanModulesDisplay from "@/components/planos/PlanModulesDisplay";


export default function ConfiguracaoAssinatura() {
  const { organization, refreshTenant } = useTenant();
  const [planos, setPlanos] = useState([]);
  const [loadingPlanos, setLoadingPlanos] = useState(true);
  const [loadingSubmit, setLoadingSubmit] = useState(false);
  const [pendingPayment, setPendingPayment] = useState(null);
  const [loadingPending, setLoadingPending] = useState(false);
  const [showPlanSelection, setShowPlanSelection] = useState(false);
  const [showCancelModal, setShowCancelModal] = useState(false);

  // Load available plans from DB
  useEffect(() => {
    async function loadPlanos() {
      try {
        setLoadingPlanos(true);
        const { data, error } = await supabase
          .from("planos")
          .select("*")
          .eq("ativo", true)
          .order("preco_mensal", { ascending: true });

        if (error) throw error;
        setPlanos(data || []);
      } catch (err) {
        console.error("Erro ao carregar planos:", err);
        toast.error("Erro ao carregar os planos do sistema.");
      } finally {
        setLoadingPlanos(false);
      }
    }

    loadPlanos();
  }, []);

  // Fetch pending invoice details if subscription status is 'processando' or 'atrasada'
  useEffect(() => {
    if (organization?.status_assinatura === "processando" || organization?.status_assinatura === "atrasada") {
      fetchPendingPaymentDetails();
    } else {
      setPendingPayment(null);
    }
  }, [organization?.status_assinatura, organization?.asaas_subscription_id]);

  const fetchPendingPaymentDetails = async () => {
    if (!organization?.asaas_subscription_id) return;
    
    try {
      setLoadingPending(true);
      const { data, error } = await supabase.functions.invoke("criar-assinatura", {
        body: { action: "get-pending-payment" }
      });

      if (error) {
        let msg = error.message || 'Erro ao buscar cobrança pendente.';
        if (error.context && typeof error.context.json === 'function') {
          try {
            const body = await error.context.json();
            if (body?.error) msg = body.error;
          } catch (_) {}
        }
        throw new Error(msg);
      }
      if (data && data.paymentId) {
        setPendingPayment(data);
      } else {
        setPendingPayment(null);
      }
    } catch (err) {
      console.error("Erro ao buscar cobrança pendente:", err);
    } finally {
      setLoadingPending(false);
    }
  };



  const handleCancelSubscription = async () => {
    try {
      setLoadingSubmit(true);
      const { data, error } = await supabase.functions.invoke("criar-assinatura", {
        body: { action: "cancel" }
      });

      if (error) {
        let msg = error.message || 'Erro ao solicitar o cancelamento.';
        if (error.context && typeof error.context.json === 'function') {
          try {
            const body = await error.context.json();
            if (body?.error) msg = body.error;
          } catch (_) {}
        }
        throw new Error(msg);
      }

      if (data?.success) {
        toast.success("Assinatura cancelada com sucesso.");
        setShowCancelModal(false);
        await refreshTenant();
      }
    } catch (err) {
      console.error("Erro ao cancelar assinatura:", err);
      toast.error(err.message || "Erro ao solicitar o cancelamento.");
    } finally {
      setLoadingSubmit(false);
    }
  };

  const [isCancelingPending, setIsCancelingPending] = useState(false);
  const handleCancelPending = async () => {
    if (!confirm("Tem certeza que deseja cancelar esta fatura? Você poderá escolher o plano e a forma de pagamento novamente.")) return;
    
    try {
      setIsCancelingPending(true);
      const { data, error } = await supabase.functions.invoke("criar-assinatura", {
        body: { action: "cancel-and-restart" }
      });
      
      if (error) throw error;
      
      toast.success("Fatura cancelada com sucesso. Escolha seu plano novamente.");
      await refreshTenant();
      setShowPlanSelection(true);
    } catch (err) {
      console.error(err);
      toast.error("Erro ao cancelar a fatura.");
    } finally {
      setIsCancelingPending(false);
    }
  };

  const copyToClipboard = (text) => {
    navigator.clipboard.writeText(text);
    toast.success("Copiado para a área de transferência!");
  };

  // Helper to format currency
  const formatCurrency = (val) => {
    return new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(val);
  };

  // Helper to translate status
  const getStatusBadge = (status) => {
    switch (status) {
      case "ativa":
        return <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold bg-emerald-100 text-emerald-800"><ShieldCheck className="w-3.5 h-3.5" /> Ativa</span>;
      case "atrasada":
        return <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold bg-rose-100 text-rose-800"><AlertTriangle className="w-3.5 h-3.5" /> Em Atraso</span>;
      case "processando":
        return <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold bg-amber-100 text-amber-800 animate-pulse"><Loader2 className="w-3.5 h-3.5 animate-spin" /> Processando Pagamento</span>;
      case "cancelada":
        return <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold bg-gray-100 text-gray-800">Cancelada</span>;
      default:
        return <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold bg-slate-100 text-slate-800">Sem Assinatura</span>;
    }
  };

  const isSubscribed = organization?.status_assinatura && organization.status_assinatura !== "sem_assinatura" && organization.status_assinatura !== "cancelada";
  const currentPlan = planos.find(p => p.id === organization?.plano_id);

  const isDefaultOrg = organization?.id === '00000000-0000-0000-0000-000000000001' || organization?.slug === 'moveis-pedro-ii';

  if (isDefaultOrg) {
    return (
      <Card className="border-green-100 shadow-sm max-w-2xl mx-auto">
        <CardHeader className="bg-green-50/50 text-center">
          <CardTitle className="text-xl flex items-center justify-center gap-2" style={{ color: "#07593f" }}>
            <ShieldCheck className="w-6 h-6 text-green-700" />
            Organização Matriz
          </CardTitle>
          <CardDescription className="text-green-800 font-medium">
            Esta organização ({organization?.name || "Matriz"}) possui licença corporativa vitalícia.
          </CardDescription>
        </CardHeader>
        <CardContent className="pt-6 text-center space-y-4">
          <p className="text-gray-600 text-sm">
            Como esta é a conta mestre do sistema, o faturamento e cobranças recorrentes são gerenciados diretamente pelo time operacional do ERP. Não há ações financeiras pendentes para o seu domínio.
          </p>
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full text-xs font-semibold bg-green-100 text-green-800">
            Acesso Ilimitado & Isento
          </div>
        </CardContent>
      </Card>
    );
  }

  if (loadingPlanos) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <Loader2 className="w-8 h-8 animate-spin text-green-700 mb-2" />
        <p className="text-sm text-gray-500">Carregando planos e informações de assinatura...</p>
      </div>
    );
  }
  if (!isSubscribed || showPlanSelection) {
    return <EscolhaPlano onCancel={isSubscribed ? () => setShowPlanSelection(false) : null} />;
  }

  return (
    <div className="space-y-6">
      
      {/* 1. SE ASSINATURA ESTÁ EM ATRASO OU PROCESSANDO */}
      {isSubscribed && organization?.status_assinatura === "atrasada" && (
        <Alert className="border-2 border-red-200 bg-red-50 text-red-900">
          <AlertTriangle className="h-5 w-5 text-red-600" />
          <AlertTitle className="font-bold text-red-800">Sua fatura recorrente está vencida!</AlertTitle>
          <AlertDescription className="mt-1">
            Detectamos que o pagamento da sua última mensalidade está atrasado. 
            Você possui um período de <strong>carência de 3 dias</strong> para regularizar o pagamento antes que os módulos pagos (WhatsApp Bot e Fotos de Entrega) sejam suspensos temporariamente.
          </AlertDescription>
        </Alert>
      )}

      {/* 2. PORTAL DE FATURAMENTO (SE JÁ TEM ASSINATURA) */}
      {isSubscribed ? (
        <div className="space-y-6">
          <Card className="border-green-100 shadow-sm">
            <CardHeader className="bg-green-50/50">
              <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
                <div>
                  <CardTitle className="text-xl flex items-center gap-2" style={{ color: "#07593f" }}>
                    <Sparkles className="w-5 h-5 text-green-600" />
                    Plano de Assinatura Ativo
                  </CardTitle>
                  <CardDescription>
                    Gerencie seu plano atual, formas de pagamento e cancelamento.
                  </CardDescription>
                </div>
                <div>
                  {getStatusBadge(organization?.status_assinatura)}
                </div>
              </div>
            </CardHeader>
            <CardContent className="pt-6">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="space-y-1">
                  <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Plano Contratado</span>
                  <p className="text-lg font-bold text-gray-800">{currentPlan?.nome || "Carregando..."}</p>
                  <p className="text-2xl font-extrabold text-green-800 mt-1">
                    {currentPlan ? formatCurrency(currentPlan.preco_mensal) : "R$ --"}
                    <span className="text-xs font-normal text-gray-500"> / mês</span>
                  </p>
                </div>
                <div className="space-y-1">
                  <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Próxima Cobrança</span>
                  <p className="text-lg font-semibold text-gray-800">
                    {organization?.proxima_cobranca 
                      ? new Date(organization.proxima_cobranca + "T12:00:00").toLocaleDateString("pt-BR")
                      : "Sem data agendada"
                    }
                  </p>
                  <p className="text-xs text-gray-500 mt-1">Cobrança processada automaticamente via Asaas.</p>
                </div>
                <div className="space-y-1">
                  <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider">ID da Assinatura</span>
                  <p className="text-sm font-mono text-gray-600 bg-gray-100 px-2 py-1 rounded select-all max-w-max">
                    {organization?.asaas_subscription_id}
                  </p>
                  <button 
                    onClick={fetchPendingPaymentDetails}
                    className="text-xs text-green-700 hover:text-green-800 flex items-center gap-1 font-semibold mt-2 transition-all"
                  >
                    <RefreshCw className={`w-3.5 h-3.5 ${loadingPending ? "animate-spin" : ""}`} />
                    Atualizar Status
                  </button>
                </div>
              </div>

              {/* Módulos Habilitados no Plano Atual */}
              {currentPlan?.recursos && (
                <div className="mt-8 border-t pt-6">
                  <h4 className="text-sm font-semibold text-gray-700 mb-3">Módulos Habilitados por este Plano:</h4>
                  <PlanModulesDisplay recursos={currentPlan.recursos} variant="card" />
                </div>
              )}

            </CardContent>
            
            <CardFooter className="bg-gray-50/50 border-t py-4 px-6 flex flex-wrap justify-between gap-4">
              <Button 
                variant="outline"
                className="text-rose-700 border-rose-200 hover:bg-rose-50 hover:text-rose-800 transition-colors"
                onClick={() => setShowCancelModal(true)}
              >
                <Trash2 className="w-4 h-4 mr-2" />
                Cancelar Assinatura
              </Button>
              
              <Button 
                onClick={() => {
                  // Upgrade / Downgrade is just selecting another plan
                  setPendingPayment(null);
                  setShowPlanSelection(true);
                }}
                className="bg-green-700 hover:bg-green-800 transition-colors"
              >
                <Sparkles className="w-4 h-4 mr-2" />
                Trocar de Plano (Upgrade/Downgrade)
              </Button>
            </CardFooter>
          </Card>

          {/* MOSTRAR QR CODE / BOLETO SE HOUVER COBRANÇA PENDENTE */}
          {(organization?.status_assinatura === "processando" || organization?.status_assinatura === "atrasada") && (
            <Card className="border-amber-200 shadow-sm overflow-hidden">
              <CardHeader className="bg-amber-50">
                <CardTitle className="text-base text-amber-800 flex items-center gap-2">
                  <Info className="w-4 h-4" />
                  Instruções para Pagamento da Fatura
                </CardTitle>
                <CardDescription className="text-amber-700">
                  Efetue o pagamento abaixo para liberar ou manter o acesso aos seus módulos do plano {currentPlan?.nome}.
                </CardDescription>
              </CardHeader>
              <CardContent className="pt-6">
                {loadingPending ? (
                  <div className="flex items-center justify-center py-6">
                    <Loader2 className="w-6 h-6 animate-spin text-amber-600 mr-2" />
                    <p className="text-sm text-gray-500">Buscando faturas geradas no Asaas...</p>
                  </div>
                ) : pendingPayment ? (
                  <div className="space-y-6">
                    <div className="flex flex-col md:flex-row gap-6 items-center">
                      
                      {/* PIX QR CODE SHOWING */}
                      {pendingPayment.pixQrCode && (
                        <div className="flex flex-col items-center p-4 bg-white border rounded-xl shadow-inner shrink-0">
                          <img 
                            src={`data:image/png;base64,${pendingPayment.pixQrCode}`} 
                            alt="QR Code Pix"
                            className="w-40 h-40 object-contain"
                          />
                          <span className="text-xs text-gray-400 mt-2">Escaneie com o app do banco</span>
                        </div>
                      )}

                      {/* PAYMENT DETAILS COLUMN */}
                      <div className="flex-1 space-y-4 w-full">
                        <div className="grid grid-cols-2 gap-4 text-sm">
                          <div>
                            <span className="text-xs text-gray-400 font-semibold block">Valor do Pagamento</span>
                            <span className="text-lg font-bold text-gray-800">{formatCurrency(pendingPayment.value)}</span>
                          </div>
                          <div>
                            <span className="text-xs text-gray-400 font-semibold block">Data de Vencimento</span>
                            <span className="text-lg font-bold text-gray-800">
                              {new Date(pendingPayment.dueDate + "T12:00:00").toLocaleDateString("pt-BR")}
                            </span>
                          </div>
                        </div>

                        {/* ACTION BUTTONS */}
                        <div className="flex flex-wrap gap-3 pt-2">
                          {pendingPayment.pixCopiaCola && (
                            <Button 
                              variant="outline"
                              onClick={() => copyToClipboard(pendingPayment.pixCopiaCola)}
                              className="text-gray-700"
                            >
                              <Copy className="w-4 h-4 mr-2" />
                              Copiar Pix Copia e Cola
                            </Button>
                          )}

                          {pendingPayment.bankSlipUrl && (
                            <Button 
                              variant="outline"
                              onClick={() => window.open(pendingPayment.bankSlipUrl, "_blank")}
                              className="text-gray-700"
                            >
                              <FileText className="w-4 h-4 mr-2" />
                              Visualizar Boleto (PDF)
                            </Button>
                          )}

                          {pendingPayment.invoiceUrl && (
                            <Button 
                              variant="outline"
                              onClick={() => window.open(pendingPayment.invoiceUrl, "_blank")}
                              className="text-gray-700"
                            >
                              <ExternalLink className="w-4 h-4 mr-2" />
                              Abrir Fatura Asaas
                            </Button>
                          )}

                          <Button 
                            variant="outline"
                            onClick={() => {
                              setPendingPayment(null);
                              setShowPlanSelection(true);
                            }}
                            className="text-amber-700 border-amber-200 hover:bg-amber-50 hover:text-amber-800"
                          >
                            <RefreshCw className="w-4 h-4 mr-2" />
                            Alterar Plano
                          </Button>

                          <Button 
                            variant="outline"
                            onClick={handleCancelPending}
                            disabled={isCancelingPending}
                            className="text-red-700 border-red-200 hover:bg-red-50 hover:text-red-800"
                          >
                            {isCancelingPending ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Trash2 className="w-4 h-4 mr-2" />}
                            Cancelar Fatura Atual
                          </Button>
                        </div>
                      </div>

                    </div>
                  </div>
                ) : (
                  <div className="text-center py-6 text-gray-500 text-sm">
                    Nenhuma fatura em aberto foi localizada no painel do Asaas. 
                    A assinatura está sendo processada, se já realizou o pagamento o acesso será liberado em breve.
                  </div>
                )}
              </CardContent>
            </Card>
          )}
        </div>
      ) : null}



      {/* 5. MODAL DE CANCELAMENTO */}
      <Dialog open={showCancelModal} onOpenChange={setShowCancelModal}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle className="text-rose-800 flex items-center gap-2">
              <AlertTriangle className="w-5 h-5" />
              Cancelar sua Assinatura?
            </DialogTitle>
            <DialogDescription className="text-gray-600 mt-2">
              Tem certeza que deseja cancelar sua assinatura recorrente? Ao cancelar, as cobranças do Asaas serão encerradas.
              <br /><br />
              <strong className="text-red-700">Atenção:</strong> O acesso aos módulos <strong>WhatsApp Bot</strong> e <strong>Fotos de Entrega</strong> será bloqueado permanentemente assim que a exclusão for efetuada no Asaas.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter className="gap-2 mt-4">
            <Button
              type="button"
              variant="outline"
              onClick={() => setShowCancelModal(false)}
              disabled={loadingSubmit}
            >
              Manter Assinatura
            </Button>
            <Button
              onClick={handleCancelSubscription}
              disabled={loadingSubmit}
              className="bg-rose-700 hover:bg-rose-800 hover:text-white"
            >
              {loadingSubmit ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin mr-2" />
                  Processando...
                </>
              ) : (
                "Sim, Cancelar Plano"
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

    </div>
  );
}

import React, { useState, useMemo, useEffect } from "react";
import { base44 } from "@/api/base44Client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { TrendingDown, Save, Loader2, AlertCircle, Settings, Target, ShieldAlert, Award, Store, User } from "lucide-react";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { toast } from "sonner";
import { useTenant } from "@/contexts/TenantContext";
import { supabase } from "@/lib/supabase";

const isMissingDescontoVendedorColumnError = (err) => {
  const message = String(err?.message || '').toLowerCase();
  return message.includes('desconto_vendedor') && message.includes('schema cache');
};

export default function ConfiguracaoComissoes() {
  const queryClient = useQueryClient();
  const { settings, refreshTenant } = useTenant();
  const [editando, setEditando] = useState({});

  // Configurações do modelo de cálculo
  const [modeloCalculo, setModeloCalculo] = useState('regra_venda');
  const [faixaReferencia, setFaixaReferencia] = useState('vendedor');
  const [pisoLoja, setPisoLoja] = useState(0);
  const [salvandoSettings, setSalvandoSettings] = useState(false);

  useEffect(() => {
    if (settings) {
      setModeloCalculo(settings.comissao_modelo_calculo || 'regra_venda');
      setFaixaReferencia(settings.comissao_faixa_referencia || 'vendedor');
      setPisoLoja(settings.comissao_meta_minima_loja_percentual || 0);
    }
  }, [settings]);

  const { data: taxas = [], isLoading } = useQuery({
    queryKey: ['configuracao_taxas'],
    queryFn: () => base44.entities.ConfiguracaoTaxa.list(),
  });

  const taxasOrdenadas = useMemo(() => {
    return [...taxas].sort((a, b) =>
      a.forma_pagamento.localeCompare(b.forma_pagamento, 'pt-BR')
    );
  }, [taxas]);

  const updateMutation = useMutation({
    mutationFn: ({ id, desconto_vendedor }) =>
      base44.entities.ConfiguracaoTaxa.update(id, { desconto_vendedor }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['configuracao_taxas'] });
      toast.success("Configuração salva com sucesso!");
    },
    onError: (err) => {
      if (isMissingDescontoVendedorColumnError(err)) {
        toast.error("Seu banco ainda não possui a coluna desconto_vendedor em configuracao_taxas. Aplique a migração pendente para habilitar esta configuração.");
        return;
      }
      toast.error("Erro ao salvar: " + err.message);
    },
  });

  const handleSaveSettings = async () => {
    setSalvandoSettings(true);
    try {
      const tenantId = settings?.organization_id || "00000000-0000-0000-0000-000000000001";
      const { error } = await supabase
        .from('organization_settings')
        .update({
          comissao_modelo_calculo: modeloCalculo,
          comissao_faixa_referencia: faixaReferencia,
          comissao_meta_minima_loja_percentual: Number(pisoLoja) || 0,
        })
        .eq('organization_id', tenantId);

      if (error) throw error;
      await refreshTenant();
      toast.success("Configurações gerais de comissão atualizadas com sucesso!");
    } catch (err) {
      toast.error("Erro ao salvar configurações gerais: " + err.message);
    } finally {
      setSalvandoSettings(false);
    }
  };

  const handleChange = (taxaId, valor) => {
    setEditando(prev => ({ ...prev, [taxaId]: valor }));
  };

  const handleSave = (taxa) => {
    const novoValor = editando[taxa.id];
    if (novoValor === undefined) return;
    updateMutation.mutate({
      id: taxa.id,
      desconto_vendedor: parseFloat(novoValor) || 0,
    });
    setEditando(prev => {
      const novo = { ...prev };
      delete novo[taxa.id];
      return novo;
    });
  };

  if (isLoading) {
    return (
      <Card className="border-0 shadow-lg">
        <CardContent className="flex items-center justify-center py-12">
          <Loader2 className="w-8 h-8 animate-spin" style={{ color: '#07593f' }} />
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      {/* Card 1: Configuração do Modelo Geral */}
      <Card className="border-0 shadow-lg overflow-hidden">
        <CardHeader className="bg-gray-50/50 border-b">
          <CardTitle className="flex items-center gap-2" style={{ color: '#07593f' }}>
            <Settings className="w-5 h-5" />
            Parâmetros de Cálculo de Comissão da Loja
          </CardTitle>
        </CardHeader>
        <CardContent className="p-6 space-y-6">
          <div className="space-y-4">
            <Label className="text-base font-semibold text-gray-800">Selecione o Modelo de Comissão Ativo</Label>
            
            <div className="grid md:grid-cols-2 gap-4">
              {/* Modelo por Venda */}
              <div
                onClick={() => setModeloCalculo('regra_venda')}
                className={`p-5 rounded-xl border-2 cursor-pointer transition-all duration-200 flex flex-col justify-between ${
                  modeloCalculo === 'regra_venda'
                    ? 'border-green-600 bg-green-50/30'
                    : 'border-gray-200 hover:border-gray-300 hover:bg-gray-50/50'
                }`}
              >
                <div>
                  <div className="flex items-center gap-2 mb-2">
                    <Award className={`w-5 h-5 ${modeloCalculo === 'regra_venda' ? 'text-green-700' : 'text-gray-500'}`} />
                    <h3 className="font-bold text-gray-800">Por Venda (Regras Individuais)</h3>
                  </div>
                  <p className="text-xs text-gray-500 leading-relaxed">
                    A comissão é acumulada a cada venda efetuada pelo vendedor, aplicando o percentual correspondente à forma de pagamento ou regra de comissão específica.
                  </p>
                </div>
                {modeloCalculo === 'regra_venda' && (
                  <span className="text-[10px] bg-green-100 text-green-700 font-bold px-2 py-0.5 rounded-full w-max mt-4">Ativo</span>
                )}
              </div>

              {/* Modelo por Faixas de Meta */}
              <div
                onClick={() => setModeloCalculo('faixas_meta')}
                className={`p-5 rounded-xl border-2 cursor-pointer transition-all duration-200 flex flex-col justify-between ${
                  modeloCalculo === 'faixas_meta'
                    ? 'border-green-600 bg-green-50/30'
                    : 'border-gray-200 hover:border-gray-300 hover:bg-gray-50/50'
                }`}
              >
                <div>
                  <div className="flex items-center gap-2 mb-2">
                    <Target className={`w-5 h-5 ${modeloCalculo === 'faixas_meta' ? 'text-green-700' : 'text-gray-500'}`} />
                    <h3 className="font-bold text-gray-800">Por Faixas de Meta Mensal</h3>
                  </div>
                  <p className="text-xs text-gray-500 leading-relaxed">
                    A comissão é calculada mensalmente com base no faturamento acumulado do vendedor vs. sua meta, aplicando percentuais progressivos escalonados (tiers).
                  </p>
                </div>
                {modeloCalculo === 'faixas_meta' && (
                  <span className="text-[10px] bg-green-100 text-green-700 font-bold px-2 py-0.5 rounded-full w-max mt-4">Ativo</span>
                )}
              </div>
            </div>
          </div>

          {/* Opções de Faixa de Meta (somente se selecionado) */}
          {modeloCalculo === 'faixas_meta' && (
            <div className="p-5 rounded-xl bg-gray-50/50 border-2 border-dashed space-y-5 animate-in fade-in slide-in-from-top-2 duration-300">
              <div className="space-y-3">
                <Label className="text-sm font-semibold text-gray-700">Referência para o Atingimento da Meta</Label>
                <div className="grid md:grid-cols-3 gap-3">
                  {/* Vendedor */}
                  <div
                    onClick={() => setFaixaReferencia('vendedor')}
                    className={`p-4 rounded-lg border-2 cursor-pointer transition-all flex items-center gap-3 bg-white ${
                      faixaReferencia === 'vendedor'
                        ? 'border-green-600 bg-green-50/10'
                        : 'border-gray-200 hover:border-gray-300'
                    }`}
                  >
                    <User className="w-4 h-4 text-gray-500" />
                    <div>
                      <h4 className="text-xs font-bold text-gray-800">Vendedor</h4>
                      <p className="text-[10px] text-gray-400">Meta e faturamento individual</p>
                    </div>
                  </div>

                  {/* Loja */}
                  <div
                    onClick={() => setFaixaReferencia('loja')}
                    className={`p-4 rounded-lg border-2 cursor-pointer transition-all flex items-center gap-3 bg-white ${
                      faixaReferencia === 'loja'
                        ? 'border-green-600 bg-green-50/10'
                        : 'border-gray-200 hover:border-gray-300'
                    }`}
                  >
                    <Store className="w-4 h-4 text-gray-500" />
                    <div>
                      <h4 className="text-xs font-bold text-gray-800">Apenas Loja</h4>
                      <p className="text-[10px] text-gray-400">Faturamento da filial vs meta da filial</p>
                    </div>
                  </div>

                  {/* Misto */}
                  <div
                    onClick={() => setFaixaReferencia('ambos')}
                    className={`p-4 rounded-lg border-2 cursor-pointer transition-all flex items-center gap-3 bg-white ${
                      faixaReferencia === 'ambos'
                        ? 'border-green-600 bg-green-50/10'
                        : 'border-gray-200 hover:border-gray-300'
                    }`}
                  >
                    <ShieldAlert className="w-4 h-4 text-gray-500" />
                    <div>
                      <h4 className="text-xs font-bold text-gray-800">Misto (Com Piso)</h4>
                      <p className="text-[10px] text-gray-400">Meta individual + piso da filial</p>
                    </div>
                  </div>
                </div>
              </div>

              {/* Piso da Loja (se Ambos) */}
              {faixaReferencia === 'ambos' && (
                <div className="space-y-2 max-w-md animate-in fade-in duration-200">
                  <Label htmlFor="piso-loja-input" className="text-xs text-gray-700 font-semibold">
                    Piso de Faturamento da Loja (% Mínimo Atingido)
                  </Label>
                  <div className="relative w-36">
                    <Input
                      id="piso-loja-input"
                      type="number"
                      min="0"
                      max="100"
                      step="5"
                      value={pisoLoja}
                      onChange={(e) => setPisoLoja(e.target.value)}
                      className="pr-8 text-right font-medium"
                    />
                    <span className="absolute right-3 top-2.5 text-gray-400 text-sm font-semibold pointer-events-none">%</span>
                  </div>
                  <p className="text-[11px] text-gray-400 leading-normal">
                    O vendedor só qualifica para a comissão por faixas se a sua filial atingir pelo menos este percentual da meta geral da loja no mês. Caso contrário, aplica-se a comissão por regras normais.
                  </p>
                </div>
              )}
            </div>
          )}

          <div className="flex justify-end pt-2 border-t">
            <Button
              onClick={handleSaveSettings}
              disabled={salvandoSettings}
              className="bg-green-700 hover:bg-green-800 text-white font-semibold flex items-center gap-2"
              style={{ backgroundColor: '#07593f' }}
            >
              {salvandoSettings ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" />
                  Salvando...
                </>
              ) : (
                <>
                  <Save className="w-4 h-4" />
                  Salvar Parâmetros Gerais
                </>
              )}
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Card 2: Configuração de Desconto de Forma de Pagamento */}
      <Card className="border-0 shadow-lg">
        <CardHeader>
          <CardTitle className="flex items-center gap-2" style={{ color: '#07593f' }}>
            <TrendingDown className="w-6 h-6" />
            Desconto no Líquido do Vendedor por Forma de Pagamento
          </CardTitle>
        </CardHeader>
        <CardContent>
          <Alert className="mb-6 bg-orange-50/60 border-orange-200">
            <AlertCircle className="w-4 h-4 text-orange-600" />
            <AlertDescription className="text-orange-800 text-sm space-y-1">
              <p>
                {modeloCalculo === 'regra_venda' ? (
                  <>
                    <strong>O sistema calcula comissões automaticamente.</strong> O percentual de desconto abaixo é subtraído do valor da venda para obter o <strong>valor líquido do vendedor</strong> — que é a base usada para o cálculo de regras.
                  </>
                ) : (
                  <>
                    <strong>Cálculo mensal por faixas ativo.</strong> O percentual de desconto configurado abaixo só afetará o cálculo se a faixa configurada para o vendedor utilizar a base de cálculo <strong>Líquido</strong>.
                  </>
                )}
              </p>
              <p className="text-xs text-orange-700">
                Exemplo: Venda de R$ 1.000 no Crédito 1x com 10% de desconto → Líquido do vendedor = R$ 900
              </p>
            </AlertDescription>
          </Alert>

          {taxas.length === 0 ? (
            <Alert className="bg-yellow-50 border-yellow-200">
              <AlertCircle className="w-4 h-4 text-yellow-600" />
              <AlertDescription className="text-yellow-800">
                Nenhuma forma de pagamento configurada. Acesse a aba <strong>Taxas</strong> para
                configurar as formas de pagamento.
              </AlertDescription>
            </Alert>
          ) : (
            <div className="space-y-3">
              {taxasOrdenadas.map(taxa => {
                const isEditing = taxa.id in editando;
                const valorAtual = isEditing ? editando[taxa.id] : (taxa.desconto_vendedor ?? 0);
                return (
                  <div
                    key={taxa.id}
                    className="flex items-center gap-4 p-4 rounded-lg border-2 hover:shadow-md transition-all duration-200"
                    style={{ borderColor: '#E5E0D8' }}
                  >
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-semibold text-gray-800">{taxa.forma_pagamento}</p>
                      {taxa.descricao && (
                        <p className="text-xs text-gray-500 truncate">{taxa.descricao}</p>
                      )}
                    </div>
                    <div className="flex items-center gap-2">
                      <Input
                        type="number"
                        step="0.01"
                        min="0"
                        max="100"
                        value={valorAtual}
                        onChange={(e) => handleChange(taxa.id, e.target.value)}
                        className="w-24 text-right"
                        placeholder="0.00"
                      />
                      <span className="text-sm font-semibold text-orange-600">%</span>
                    </div>
                    {isEditing && (
                      <Button
                        size="sm"
                        className="bg-green-600 hover:bg-green-700 shrink-0 text-white"
                        onClick={() => handleSave(taxa)}
                        disabled={updateMutation.isPending}
                      >
                        {updateMutation.isPending
                          ? <Loader2 className="w-3 h-3 animate-spin" />
                          : <><Save className="w-3 h-3 mr-1" />Salvar</>
                        }
                      </Button>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>

      <Alert className="bg-blue-50 border-blue-200">
        <AlertCircle className="w-4 h-4 text-blue-600" />
        <AlertDescription className="text-blue-800 text-sm">
          <strong>Fórmula do Líquido:</strong>{" "}
          <code className="bg-white px-1 rounded border border-blue-100">
            Líquido Vendedor = Valor da Venda × (1 − Desconto%)
          </code>
          . Configure as taxas da loja e os acréscimos ao cliente na aba <strong>Taxas</strong>.
        </AlertDescription>
      </Alert>
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Checkbox } from '@/components/ui/checkbox';
import { Label } from '@/components/ui/label';
import { Button } from '@/components/ui/button';
import { Switch } from '@/components/ui/switch';
import { Loader2, CreditCard, ShieldCheck, AlertTriangle } from 'lucide-react';
import { toast } from 'sonner';
import { supabase } from '@/lib/supabase';
import { useTenant } from '@/contexts/TenantContext';

const FORMAS_PAGAMENTO = [
  { value: 'a_vista', label: 'A Vista' },
  { value: 'pix', label: 'PIX' },
  { value: 'boleto', label: 'Boleto' },
  { value: 'parcelado', label: 'Parcelado' },
  { value: 'cartao_debito', label: 'Cartao Debito' },
  { value: 'cartao_credito', label: 'Cartao Credito' },
  { value: 'transferencia', label: 'Transferencia Bancaria' },
  { value: 'cheque', label: 'Cheque' },
  { value: 'a_definir', label: 'A Definir' },
];

export default function ConfiguracaoComprasPagamento() {
  const { organization, settings, refreshTenant } = useTenant();
  const [formasSelecionadas, setFormasSelecionadas] = useState(['a_vista']);
  const [conferenciaCaixaEnabled, setConferenciaCaixaEnabled] = useState(false);
  const [saving, setSaving] = useState(false);
  const [savingConferencia, setSavingConferencia] = useState(false);

  useEffect(() => {
    const atuais = settings?.compras_aprovacao_automatica;
    if (Array.isArray(atuais)) {
      setFormasSelecionadas(atuais);
    }
    setConferenciaCaixaEnabled(settings?.conferencia_caixa_enabled === true);
  }, [settings?.compras_aprovacao_automatica, settings?.conferencia_caixa_enabled]);

  const toggleForma = (forma) => {
    setFormasSelecionadas((prev) => {
      if (prev.includes(forma)) {
        return prev.filter((f) => f !== forma);
      }
      return [...prev, forma];
    });
  };

  const handleSalvar = async () => {
    try {
      setSaving(true);

      const orgId = organization?.id || '00000000-0000-0000-0000-000000000001';
      const payload = {
        organization_id: orgId,
        compras_aprovacao_automatica: formasSelecionadas,
        updated_at: new Date().toISOString(),
      };

      const { error } = await supabase
        .from('organization_settings')
        .upsert(payload, { onConflict: 'organization_id' });

      if (error) throw error;

      await refreshTenant();
      toast.success('Configuracoes de aprovacao automatica atualizadas');
    } catch (error) {
      console.error('Erro ao salvar configuracao de compras:', error);
      toast.error(`Erro ao salvar: ${error.message}`);
    } finally {
      setSaving(false);
    }
  };

  const handleSalvarConferencia = async (novoValor) => {
    try {
      setSavingConferencia(true);
      const orgId = organization?.id || '00000000-0000-0000-0000-000000000001';

      const { error } = await supabase
        .from('organization_settings')
        .upsert(
          {
            organization_id: orgId,
            conferencia_caixa_enabled: novoValor,
            updated_at: new Date().toISOString(),
          },
          { onConflict: 'organization_id' }
        );

      if (error) throw error;

      setConferenciaCaixaEnabled(novoValor);
      await refreshTenant();
      toast.success(
        novoValor
          ? 'Conferência de Caixa ativada! As vendas agora aguardarão aprovação antes de prosseguir.'
          : 'Conferência de Caixa desativada. Vendas seguirão o fluxo normal.'
      );
    } catch (error) {
      console.error('Erro ao salvar conferência de caixa:', error);
      toast.error(`Erro ao salvar: ${error.message}`);
      // Reverter o switch visualmente em caso de erro
      setConferenciaCaixaEnabled(!novoValor);
    } finally {
      setSavingConferencia(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* ── Conferência de Caixa ── */}
      <Card className="border-2 border-amber-100">
        <CardHeader>
          <div className="flex items-center gap-2">
            <ShieldCheck className="w-5 h-5 text-amber-600" />
            <CardTitle>Conferência de Caixa</CardTitle>
          </div>
          <CardDescription>
            Quando ativado, toda venda precisará ser conferida pelo gerente antes de gerar entrega,
            montagem e lançamentos financeiros. Permite detectar divergências de pagamento logo após
            a venda.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center justify-between p-4 rounded-xl border bg-amber-50/50">
            <div className="space-y-1">
              <p className="font-semibold text-sm text-gray-800">
                {conferenciaCaixaEnabled ? '✅ Módulo Ativo' : '⬜ Módulo Inativo'}
              </p>
              <p className="text-xs text-gray-500 max-w-sm">
                {conferenciaCaixaEnabled
                  ? 'Vendas ficam bloqueadas aguardando aprovação do caixa/gerente. Vendas "Pagar na Entrega" são isentas.'
                  : 'As vendas seguem o fluxo normal (entrega e lançamentos criados automaticamente).'}
              </p>
            </div>
            <div className="flex items-center gap-2">
              {savingConferencia && <Loader2 className="w-4 h-4 animate-spin text-amber-600" />}
              <Switch
                id="conferencia-caixa-toggle"
                checked={conferenciaCaixaEnabled}
                onCheckedChange={(val) => handleSalvarConferencia(val)}
                disabled={savingConferencia}
                className="data-[state=checked]:bg-amber-500"
              />
            </div>
          </div>

          {conferenciaCaixaEnabled && (
            <div className="flex items-start gap-2 rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-xs text-amber-800">
              <AlertTriangle className="w-3.5 h-3.5 mt-0.5 shrink-0" />
              <span>
                <strong>Atenção:</strong> Com este módulo ativo, o gerente verá as vendas pendentes
                no <strong>Painel Gerencial → Conferência de Caixa</strong>. Vendas não conferidas
                ficam editáveis pelo vendedor na listagem de vendas.
              </span>
            </div>
          )}
        </CardContent>
      </Card>

      {/* ── Aprovação Automática de Compras ── */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <CreditCard className="w-5 h-5 text-green-700" />
            <CardTitle>Aprovação Automática de Vendas por Forma de Pagamento</CardTitle>
          </div>
          <CardDescription>
            Selecione quais formas de pagamento NÃO precisam passar pela aprovação manual do gerente/master nas vendas.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid gap-3 md:grid-cols-2">
            {FORMAS_PAGAMENTO.map((forma) => (
              <div key={forma.value} className="flex items-center space-x-2 rounded-md border p-3">
                <Checkbox
                  id={`forma-${forma.value}`}
                  checked={formasSelecionadas.includes(forma.value)}
                  onCheckedChange={() => toggleForma(forma.value)}
                />
                <Label htmlFor={`forma-${forma.value}`} className="cursor-pointer text-sm font-medium">
                  {forma.label}
                </Label>
              </div>
            ))}
          </div>

          <div className="rounded-md border border-amber-200 bg-amber-50 px-3 py-2 text-xs text-amber-800">
            Formas desmarcadas exigirao envio para aprovacao de pagamento.
          </div>

          <div className="flex justify-end">
            <Button onClick={handleSalvar} disabled={saving} className="gap-2">
              {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : null}
              Salvar
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { base44 } from "@/api/base44Client";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import {
    Table, TableBody, TableCell, TableHead, TableHeader, TableRow
} from "@/components/ui/table";
import {
    Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle
} from "@/components/ui/dialog";
import { Alert, AlertDescription } from "@/components/ui/alert";
import {
    Search, KeyRound, UserCheck, UserX, RotateCcw, Shield,
    Clock, CheckCircle2, AlertCircle, Loader2, Copy, Eye, EyeOff,
    MessageCircle, Users
} from "lucide-react";
import { toast } from "sonner";
import { getZapApiUrl } from '../../utils/zapApiUrl';
import { CARGOS, getCargoConfig } from "@/config/cargos";

const API_URL = getZapApiUrl();

export default function ConfiguracaoCredenciais() {
    const [searchTerm, setSearchTerm] = useState("");
    const [filterStatus, setFilterStatus] = useState("all");
    const [selectedUser, setSelectedUser] = useState(null);
    const [modalType, setModalType] = useState(null); // 'create' | 'reset' | 'toggle'
    const [showPassword, setShowPassword] = useState(false);
    const [generatedPassword, setGeneratedPassword] = useState(null);
    const [generatedMatricula, setGeneratedMatricula] = useState(null);

    const queryClient = useQueryClient();

    // Buscar usuários aprovados (funcionários)
    const { data: users = [], isLoading } = useQuery({
        queryKey: ['users-credentials'],
        queryFn: async () => {
            const allUsers = await base44.entities.User.list('-created_date');
            // Filtrar apenas usuários aprovados que são funcionários (não clientes)
            return allUsers.filter(u =>
                u.status_aprovacao === 'Aprovado' &&
                u.cargo &&
                !['Cliente'].includes(u.cargo)
            );
        }
    });

    // Mutation para criar credenciais
    const createCredentialsMutation = useMutation({
        mutationFn: async (userId) => {
            const response = await fetch(`${API_URL}/api/auth/employee/create`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ user_id: userId })
            });
            if (!response.ok) {
                const error = await response.json();
                throw new Error(error.error || 'Erro ao criar credenciais');
            }
            return response.json();
        },
        onSuccess: (data) => {
            setGeneratedMatricula(data.matricula);
            setGeneratedPassword(data.senha_temporaria);
            queryClient.invalidateQueries({ queryKey: ['users-credentials'] });
            toast.success("Credenciais criadas com sucesso!");
        },
        onError: (error) => {
            toast.error(error.message);
            setModalType(null);
            setSelectedUser(null);
        }
    });

    // Mutation para resetar senha
    const resetPasswordMutation = useMutation({
        mutationFn: async (userId) => {
            const response = await fetch(`${API_URL}/api/auth/employee/reset-password`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ user_id: userId })
            });
            if (!response.ok) {
                const error = await response.json();
                throw new Error(error.error || 'Erro ao resetar senha');
            }
            return response.json();
        },
        onSuccess: (data) => {
            setGeneratedPassword(data.senha_temporaria);
            setGeneratedMatricula(selectedUser?.matricula);
            queryClient.invalidateQueries({ queryKey: ['users-credentials'] });
            toast.success(data.whatsapp_enviado
                ? "Senha resetada e enviada via WhatsApp!"
                : "Senha resetada! (WhatsApp não disponível)");
        },
        onError: (error) => {
            toast.error(error.message);
            setModalType(null);
            setSelectedUser(null);
        }
    });

    // Mutation para ativar/desativar conta
    const toggleAccountMutation = useMutation({
        mutationFn: async ({ userId, ativo }) => {
            // Atualizar diretamente no Supabase
            await base44.entities.User.update(userId, { ativo });
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['users-credentials'] });
            toast.success(selectedUser?.ativo ? "Conta desativada!" : "Conta ativada!");
            setModalType(null);
            setSelectedUser(null);
        },
        onError: (error) => {
            toast.error("Erro ao alterar status: " + error.message);
        }
    });

    // Filtrar usuários
    const filteredUsers = users.filter(user => {
        const matchesSearch =
            user.full_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            user.email?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            user.matricula?.toLowerCase().includes(searchTerm.toLowerCase());

        let matchesStatus = true;
        if (filterStatus === 'with') matchesStatus = !!user.matricula;
        if (filterStatus === 'without') matchesStatus = !user.matricula;
        if (filterStatus === 'active') matchesStatus = user.matricula && user.ativo !== false;
        if (filterStatus === 'inactive') matchesStatus = user.matricula && user.ativo === false;

        return matchesSearch && matchesStatus;
    });

    // Estatísticas
    const stats = {
        total: users.length,
        withCredentials: users.filter(u => u.matricula).length,
        active: users.filter(u => u.matricula && u.ativo !== false).length,
        pendingFirstAccess: users.filter(u => u.matricula && u.primeiro_acesso).length
    };

    const handleOpenModal = (user, type) => {
        setSelectedUser(user);
        setModalType(type);
        setGeneratedPassword(null);
        setGeneratedMatricula(null);
        setShowPassword(false);
    };

    const handleCloseModal = () => {
        setModalType(null);
        setSelectedUser(null);
        setGeneratedPassword(null);
        setGeneratedMatricula(null);
        setShowPassword(false);
    };

    const handleCreateCredentials = () => {
        if (selectedUser) {
            createCredentialsMutation.mutate(selectedUser.id);
        }
    };

    const handleResetPassword = () => {
        if (selectedUser) {
            resetPasswordMutation.mutate(selectedUser.id);
        }
    };

    const handleToggleAccount = () => {
        if (selectedUser) {
            toggleAccountMutation.mutate({
                userId: selectedUser.id,
                ativo: !selectedUser.ativo
            });
        }
    };

    const copyToClipboard = (text, label) => {
        navigator.clipboard.writeText(text);
        toast.success(`${label} copiado!`);
    };

    const getStatusBadge = (user) => {
        if (!user.matricula) {
            return (
                <Badge variant="outline" className="bg-gray-50 text-gray-600">
                    <AlertCircle className="w-3 h-3 mr-1" />
                    Sem Credencial
                </Badge>
            );
        }
        if (user.ativo === false) {
            return (
                <Badge className="bg-red-100 text-red-700">
                    <UserX className="w-3 h-3 mr-1" />
                    Desativado
                </Badge>
            );
        }
        if (user.primeiro_acesso) {
            return (
                <Badge className="bg-yellow-100 text-yellow-700">
                    <Clock className="w-3 h-3 mr-1" />
                    Primeiro Acesso
                </Badge>
            );
        }
        return (
            <Badge className="bg-green-100 text-green-700">
                <CheckCircle2 className="w-3 h-3 mr-1" />
                Ativo
            </Badge>
        );
    };

    return (
        <div className="space-y-6">
            {/* Header */}
            <div>
                <h2 className="text-xl font-bold text-gray-900 flex items-center gap-2">
                    <KeyRound className="w-5 h-5 text-green-600" />
                    Credenciais de Acesso
                </h2>
                <p className="text-gray-500 text-sm mt-1">
                    Gerencie as matrículas e senhas de acesso dos funcionários ao sistema
                </p>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-4 gap-4">
                <Card className="border-0 shadow-sm">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-sm text-gray-500">Total</p>
                                <p className="text-2xl font-bold" style={{ color: '#07593f' }}>{stats.total}</p>
                            </div>
                            <Users className="w-8 h-8 text-gray-200" />
                        </div>
                    </CardContent>
                </Card>
                <Card className="border-0 shadow-sm">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-sm text-gray-500">Com Credencial</p>
                                <p className="text-2xl font-bold text-blue-600">{stats.withCredentials}</p>
                            </div>
                            <KeyRound className="w-8 h-8 text-blue-100" />
                        </div>
                    </CardContent>
                </Card>
                <Card className="border-0 shadow-sm">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-sm text-gray-500">Ativos</p>
                                <p className="text-2xl font-bold text-green-600">{stats.active}</p>
                            </div>
                            <UserCheck className="w-8 h-8 text-green-100" />
                        </div>
                    </CardContent>
                </Card>
                <Card className="border-0 shadow-sm">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-sm text-gray-500">Primeiro Acesso</p>
                                <p className="text-2xl font-bold text-yellow-600">{stats.pendingFirstAccess}</p>
                            </div>
                            <Clock className="w-8 h-8 text-yellow-100" />
                        </div>
                    </CardContent>
                </Card>
            </div>

            {/* Filters */}
            <Card className="border-0 shadow-lg">
                <CardContent className="p-4">
                    <div className="flex gap-4">
                        <div className="flex-1 relative">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                            <Input
                                placeholder="Buscar por nome, email ou matrícula..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="pl-10"
                            />
                        </div>
                        <select
                            value={filterStatus}
                            onChange={(e) => setFilterStatus(e.target.value)}
                            className="px-3 py-2 border rounded-md text-sm"
                        >
                            <option value="all">Todos</option>
                            <option value="with">Com Credencial</option>
                            <option value="without">Sem Credencial</option>
                            <option value="active">Ativos</option>
                            <option value="inactive">Desativados</option>
                        </select>
                    </div>
                </CardContent>
            </Card>

            {/* Table */}
            {isLoading ? (
                <div className="flex justify-center py-12">
                    <Loader2 className="w-8 h-8 animate-spin text-green-700" />
                </div>
            ) : (
                <Card className="border-0 shadow-lg">
                    <CardHeader className="pb-0">
                        <CardTitle className="text-lg">Funcionários ({filteredUsers.length})</CardTitle>
                    </CardHeader>
                    <CardContent>
                        <Table>
                            <TableHeader>
                                <TableRow>
                                    <TableHead>Funcionário</TableHead>
                                    <TableHead>Cargo</TableHead>
                                    <TableHead>Matrícula</TableHead>
                                    <TableHead>Status</TableHead>
                                    <TableHead>Último Login</TableHead>
                                    <TableHead className="text-right">Ações</TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {filteredUsers.map((user) => {
                                    const cargoConfig = getCargoConfig(user.cargo);
                                    return (
                                        <TableRow key={user.id}>
                                            <TableCell>
                                                <div className="flex items-center gap-3">
                                                    <div
                                                        className="w-10 h-10 rounded-full flex items-center justify-center font-semibold"
                                                        style={{
                                                            backgroundColor: cargoConfig?.bgColor || '#f3f4f6',
                                                            color: cargoConfig?.color || '#6b7280'
                                                        }}
                                                    >
                                                        {user.full_name?.charAt(0).toUpperCase() || 'U'}
                                                    </div>
                                                    <div>
                                                        <p className="font-semibold text-sm">{user.full_name || 'Sem nome'}</p>
                                                        <p className="text-xs text-gray-500">{user.email}</p>
                                                    </div>
                                                </div>
                                            </TableCell>
                                            <TableCell>
                                                {cargoConfig ? (
                                                    <Badge
                                                        style={{
                                                            backgroundColor: `${cargoConfig.color}15`,
                                                            color: cargoConfig.color,
                                                            border: `1px solid ${cargoConfig.color}40`
                                                        }}
                                                    >
                                                        {cargoConfig.label}
                                                    </Badge>
                                                ) : (
                                                    <Badge variant="outline">{user.cargo || 'N/A'}</Badge>
                                                )}
                                            </TableCell>
                                            <TableCell>
                                                {user.matricula ? (
                                                    <code className="px-2 py-1 bg-gray-100 rounded text-sm font-mono">
                                                        {user.matricula}
                                                    </code>
                                                ) : (
                                                    <span className="text-gray-400 text-sm">—</span>
                                                )}
                                            </TableCell>
                                            <TableCell>{getStatusBadge(user)}</TableCell>
                                            <TableCell>
                                                {user.ultimo_login ? (
                                                    <span className="text-sm text-gray-600">
                                                        {new Date(user.ultimo_login).toLocaleDateString('pt-BR', {
                                                            day: '2-digit',
                                                            month: '2-digit',
                                                            year: '2-digit',
                                                            hour: '2-digit',
                                                            minute: '2-digit'
                                                        })}
                                                    </span>
                                                ) : (
                                                    <span className="text-gray-400 text-sm">Nunca</span>
                                                )}
                                            </TableCell>
                                            <TableCell>
                                                <div className="flex justify-end gap-1">
                                                    {!user.matricula ? (
                                                        <Button
                                                            size="sm"
                                                            className="h-8 bg-green-600 hover:bg-green-700"
                                                            onClick={() => handleOpenModal(user, 'create')}
                                                        >
                                                            <KeyRound className="w-4 h-4 mr-1" />
                                                            Ativar Acesso
                                                        </Button>
                                                    ) : (
                                                        <>
                                                            <Button
                                                                size="sm"
                                                                variant="outline"
                                                                className="h-8"
                                                                onClick={() => handleOpenModal(user, 'reset')}
                                                            >
                                                                <RotateCcw className="w-4 h-4" />
                                                            </Button>
                                                            <Button
                                                                size="sm"
                                                                variant={user.ativo === false ? "default" : "destructive"}
                                                                className={`h-8 ${user.ativo === false ? 'bg-green-600 hover:bg-green-700' : ''}`}
                                                                onClick={() => handleOpenModal(user, 'toggle')}
                                                            >
                                                                {user.ativo === false ? (
                                                                    <UserCheck className="w-4 h-4" />
                                                                ) : (
                                                                    <UserX className="w-4 h-4" />
                                                                )}
                                                            </Button>
                                                        </>
                                                    )}
                                                </div>
                                            </TableCell>
                                        </TableRow>
                                    );
                                })}
                            </TableBody>
                        </Table>
                        {filteredUsers.length === 0 && (
                            <div className="text-center py-12 text-gray-500">
                                <Users className="w-12 h-12 mx-auto mb-3 opacity-20" />
                                <p>Nenhum funcionário encontrado</p>
                            </div>
                        )}
                    </CardContent>
                </Card>
            )}

            {/* Modal: Criar Credenciais */}
            <Dialog open={modalType === 'create'} onOpenChange={() => !generatedPassword && handleCloseModal()}>
                <DialogContent className="max-w-md">
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-2">
                            <KeyRound className="w-5 h-5 text-green-600" />
                            Ativar Acesso ao Sistema
                        </DialogTitle>
                        <DialogDescription>
                            Criar credenciais para {selectedUser?.full_name}
                        </DialogDescription>
                    </DialogHeader>

                    {!generatedPassword ? (
                        <>
                            <div className="py-4 space-y-4">
                                <Alert className="bg-blue-50 border-blue-200">
                                    <AlertCircle className="w-4 h-4 text-blue-600" />
                                    <AlertDescription className="text-blue-800">
                                        Será gerada uma <strong>matrícula única</strong> e uma <strong>senha temporária</strong>.
                                        O funcionário deverá trocar a senha no primeiro acesso.
                                    </AlertDescription>
                                </Alert>

                                <div className="p-4 bg-gray-50 rounded-lg">
                                    <p className="text-sm text-gray-600">Funcionário:</p>
                                    <p className="font-semibold">{selectedUser?.full_name}</p>
                                    <p className="text-sm text-gray-500">{selectedUser?.cargo} - {selectedUser?.loja || 'Sem loja'}</p>
                                </div>
                            </div>

                            <DialogFooter>
                                <Button variant="outline" onClick={handleCloseModal}>Cancelar</Button>
                                <Button
                                    onClick={handleCreateCredentials}
                                    disabled={createCredentialsMutation.isPending}
                                    className="bg-green-600 hover:bg-green-700"
                                >
                                    {createCredentialsMutation.isPending && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
                                    Criar Credenciais
                                </Button>
                            </DialogFooter>
                        </>
                    ) : (
                        <>
                            <div className="py-4 space-y-4">
                                <Alert className="bg-green-50 border-green-200">
                                    <CheckCircle2 className="w-4 h-4 text-green-600" />
                                    <AlertDescription className="text-green-800">
                                        Credenciais criadas com sucesso! Anote os dados abaixo:
                                    </AlertDescription>
                                </Alert>

                                <div className="space-y-3">
                                    <div className="p-3 bg-gray-50 rounded-lg">
                                        <p className="text-xs text-gray-500 mb-1">Matrícula</p>
                                        <div className="flex items-center justify-between">
                                            <code className="text-lg font-mono font-bold">{generatedMatricula}</code>
                                            <Button
                                                size="sm"
                                                variant="ghost"
                                                onClick={() => copyToClipboard(generatedMatricula, 'Matrícula')}
                                            >
                                                <Copy className="w-4 h-4" />
                                            </Button>
                                        </div>
                                    </div>

                                    <div className="p-3 bg-gray-50 rounded-lg">
                                        <p className="text-xs text-gray-500 mb-1">Senha Temporária</p>
                                        <div className="flex items-center justify-between">
                                            <code className="text-lg font-mono font-bold">
                                                {showPassword ? generatedPassword : '••••••••'}
                                            </code>
                                            <div className="flex gap-1">
                                                <Button
                                                    size="sm"
                                                    variant="ghost"
                                                    onClick={() => setShowPassword(!showPassword)}
                                                >
                                                    {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                                                </Button>
                                                <Button
                                                    size="sm"
                                                    variant="ghost"
                                                    onClick={() => copyToClipboard(generatedPassword, 'Senha')}
                                                >
                                                    <Copy className="w-4 h-4" />
                                                </Button>
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                <Alert className="bg-yellow-50 border-yellow-200">
                                    <AlertCircle className="w-4 h-4 text-yellow-600" />
                                    <AlertDescription className="text-yellow-800 text-sm">
                                        <strong>Importante:</strong> Anote esses dados! A senha não poderá ser visualizada novamente.
                                    </AlertDescription>
                                </Alert>
                            </div>

                            <DialogFooter>
                                <Button onClick={handleCloseModal} className="bg-green-600 hover:bg-green-700">
                                    Fechar
                                </Button>
                            </DialogFooter>
                        </>
                    )}
                </DialogContent>
            </Dialog>

            {/* Modal: Resetar Senha */}
            <Dialog open={modalType === 'reset'} onOpenChange={() => !generatedPassword && handleCloseModal()}>
                <DialogContent className="max-w-md">
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-2">
                            <RotateCcw className="w-5 h-5 text-orange-600" />
                            Resetar Senha
                        </DialogTitle>
                        <DialogDescription>
                            Resetar senha de {selectedUser?.full_name}
                        </DialogDescription>
                    </DialogHeader>

                    {!generatedPassword ? (
                        <>
                            <div className="py-4 space-y-4">
                                <Alert className="bg-orange-50 border-orange-200">
                                    <AlertCircle className="w-4 h-4 text-orange-600" />
                                    <AlertDescription className="text-orange-800">
                                        Será gerada uma nova <strong>senha temporária</strong>.
                                        Se o funcionário tiver telefone cadastrado e o WhatsApp estiver conectado,
                                        a nova senha será enviada automaticamente.
                                    </AlertDescription>
                                </Alert>

                                <div className="p-4 bg-gray-50 rounded-lg">
                                    <p className="text-sm text-gray-600">Funcionário:</p>
                                    <p className="font-semibold">{selectedUser?.full_name}</p>
                                    <p className="text-sm text-gray-500">Matrícula: {selectedUser?.matricula}</p>
                                </div>
                            </div>

                            <DialogFooter>
                                <Button variant="outline" onClick={handleCloseModal}>Cancelar</Button>
                                <Button
                                    onClick={handleResetPassword}
                                    disabled={resetPasswordMutation.isPending}
                                    className="bg-orange-600 hover:bg-orange-700"
                                >
                                    {resetPasswordMutation.isPending && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
                                    Resetar Senha
                                </Button>
                            </DialogFooter>
                        </>
                    ) : (
                        <>
                            <div className="py-4 space-y-4">
                                <Alert className="bg-green-50 border-green-200">
                                    <CheckCircle2 className="w-4 h-4 text-green-600" />
                                    <AlertDescription className="text-green-800">
                                        Senha resetada com sucesso!
                                    </AlertDescription>
                                </Alert>

                                <div className="space-y-3">
                                    <div className="p-3 bg-gray-50 rounded-lg">
                                        <p className="text-xs text-gray-500 mb-1">Matrícula</p>
                                        <code className="text-lg font-mono font-bold">{generatedMatricula}</code>
                                    </div>

                                    <div className="p-3 bg-gray-50 rounded-lg">
                                        <p className="text-xs text-gray-500 mb-1">Nova Senha Temporária</p>
                                        <div className="flex items-center justify-between">
                                            <code className="text-lg font-mono font-bold">
                                                {showPassword ? generatedPassword : '••••••••'}
                                            </code>
                                            <div className="flex gap-1">
                                                <Button
                                                    size="sm"
                                                    variant="ghost"
                                                    onClick={() => setShowPassword(!showPassword)}
                                                >
                                                    {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                                                </Button>
                                                <Button
                                                    size="sm"
                                                    variant="ghost"
                                                    onClick={() => copyToClipboard(generatedPassword, 'Senha')}
                                                >
                                                    <Copy className="w-4 h-4" />
                                                </Button>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <DialogFooter>
                                <Button onClick={handleCloseModal} className="bg-green-600 hover:bg-green-700">
                                    Fechar
                                </Button>
                            </DialogFooter>
                        </>
                    )}
                </DialogContent>
            </Dialog>

            {/* Modal: Ativar/Desativar */}
            <Dialog open={modalType === 'toggle'} onOpenChange={handleCloseModal}>
                <DialogContent className="max-w-md">
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-2">
                            {selectedUser?.ativo === false ? (
                                <>
                                    <UserCheck className="w-5 h-5 text-green-600" />
                                    Ativar Conta
                                </>
                            ) : (
                                <>
                                    <UserX className="w-5 h-5 text-red-600" />
                                    Desativar Conta
                                </>
                            )}
                        </DialogTitle>
                        <DialogDescription>
                            {selectedUser?.ativo === false
                                ? `Reativar o acesso de ${selectedUser?.full_name}?`
                                : `Desativar o acesso de ${selectedUser?.full_name}?`
                            }
                        </DialogDescription>
                    </DialogHeader>

                    <div className="py-4 space-y-4">
                        {selectedUser?.ativo === false ? (
                            <Alert className="bg-green-50 border-green-200">
                                <CheckCircle2 className="w-4 h-4 text-green-600" />
                                <AlertDescription className="text-green-800">
                                    Ao ativar, o funcionário poderá fazer login novamente com sua matrícula.
                                </AlertDescription>
                            </Alert>
                        ) : (
                            <Alert className="bg-red-50 border-red-200">
                                <AlertCircle className="w-4 h-4 text-red-600" />
                                <AlertDescription className="text-red-800">
                                    Ao desativar, o funcionário <strong>não poderá mais fazer login</strong>.
                                    A matrícula e senha serão mantidas para possível reativação futura.
                                </AlertDescription>
                            </Alert>
                        )}

                        <div className="p-4 bg-gray-50 rounded-lg">
                            <p className="text-sm text-gray-600">Funcionário:</p>
                            <p className="font-semibold">{selectedUser?.full_name}</p>
                            <p className="text-sm text-gray-500">Matrícula: {selectedUser?.matricula}</p>
                        </div>
                    </div>

                    <DialogFooter>
                        <Button variant="outline" onClick={handleCloseModal}>Cancelar</Button>
                        <Button
                            onClick={handleToggleAccount}
                            disabled={toggleAccountMutation.isPending}
                            className={selectedUser?.ativo === false
                                ? "bg-green-600 hover:bg-green-700"
                                : "bg-red-600 hover:bg-red-700"
                            }
                        >
                            {toggleAccountMutation.isPending && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
                            {selectedUser?.ativo === false ? 'Ativar' : 'Desativar'}
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
}

import React, { useState } from "react";
import { base44 } from "@/api/base44Client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Truck, Plus, Pencil, Trash2, Loader2 } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";

export default function ConfiguracaoFrota() {
  const [modalAberto, setModalAberto] = useState(false);
  const [editando, setEditando] = useState(null);
  const [formData, setFormData] = useState({
    nome: "",
    placa: "",
    capacidade_volume_m3: 0,
    capacidade_peso_kg: 0,
    ativo: true,
    motorista_padrao: "",
    telefone_motorista: "",
    observacoes: ""
  });

  const queryClient = useQueryClient();

  const { data: caminhoes = [], isLoading } = useQuery({
    queryKey: ['caminhoes'],
    queryFn: () => base44.entities.Caminhao.list(),
  });

  const criarMutation = useMutation({
    mutationFn: (data) => base44.entities.Caminhao.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['caminhoes'] });
      fecharModal();
    }
  });

  const atualizarMutation = useMutation({
    mutationFn: ({ id, data }) => base44.entities.Caminhao.update(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['caminhoes'] });
      fecharModal();
    }
  });

  const deletarMutation = useMutation({
    mutationFn: (id) => base44.entities.Caminhao.delete(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['caminhoes'] });
    }
  });

  const abrirModal = (caminhao = null) => {
    if (caminhao) {
      setEditando(caminhao);
      setFormData(caminhao);
    } else {
      setEditando(null);
      setFormData({
        nome: "",
        placa: "",
        capacidade_volume_m3: 0,
        capacidade_peso_kg: 0,
        ativo: true,
        motorista_padrao: "",
        telefone_motorista: "",
        observacoes: ""
      });
    }
    setModalAberto(true);
  };

  const fecharModal = () => {
    setModalAberto(false);
    setEditando(null);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (editando) {
      atualizarMutation.mutate({ id: editando.id, data: formData });
    } else {
      criarMutation.mutate(formData);
    }
  };

  const handleDelete = (id) => {
    if (confirm("Tem certeza que deseja remover este caminhão?")) {
      deletarMutation.mutate(id);
    }
  };

  if (isLoading) {
    return (
      <Card className="border-0 shadow-lg">
        <CardContent className="flex items-center justify-center py-12">
          <Loader2 className="w-8 h-8 animate-spin" style={{ color: '#07593f' }} />
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      <Card className="border-0 shadow-lg">
        <CardHeader>
          <div className="flex justify-between items-center">
            <CardTitle className="flex items-center gap-2">
              <Truck className="w-6 h-6" style={{ color: '#07593f' }} />
              Frota de Caminhões
            </CardTitle>
            <Button
              onClick={() => abrirModal()}
              style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
            >
              <Plus className="w-4 h-4 mr-2" />
              Adicionar Caminhão
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          {caminhoes.length === 0 ? (
            <div className="text-center py-12">
              <Truck className="w-16 h-16 mx-auto mb-4 opacity-20" style={{ color: '#07593f' }} />
              <p className="text-lg font-medium mb-2" style={{ color: '#07593f' }}>
                Nenhum caminhão cadastrado
              </p>
              <p className="text-sm" style={{ color: '#8B8B8B' }}>
                Cadastre caminhões para otimizar o cálculo de rotas de entrega
              </p>
            </div>
          ) : (
            <div className="grid md:grid-cols-2 gap-4">
              {caminhoes.map((caminhao) => (
                <Card key={caminhao.id} className="border-2" style={{ borderColor: '#E5E0D8' }}>
                  <CardContent className="p-4">
                    <div className="flex justify-between items-start mb-3">
                      <div>
                        <h3 className="font-bold text-lg" style={{ color: '#07593f' }}>
                          {caminhao.nome}
                        </h3>
                        {caminhao.placa && (
                          <p className="text-sm" style={{ color: '#8B8B8B' }}>
                            Placa: {caminhao.placa}
                          </p>
                        )}
                      </div>
                      <Badge
                        style={{
                          backgroundColor: caminhao.ativo ? '#D1FAE5' : '#FEE2E2',
                          color: caminhao.ativo ? '#065f46' : '#991B1B'
                        }}
                      >
                        {caminhao.ativo ? 'Ativo' : 'Inativo'}
                      </Badge>
                    </div>

                    <div className="space-y-2 mb-4">
                      <div className="flex items-center justify-between text-sm">
                        <span style={{ color: '#8B8B8B' }}>Volume:</span>
                        <span className="font-bold" style={{ color: '#07593f' }}>
                          {caminhao.capacidade_volume_m3} m³
                        </span>
                      </div>
                      {caminhao.capacidade_peso_kg > 0 && (
                        <div className="flex items-center justify-between text-sm">
                          <span style={{ color: '#8B8B8B' }}>Peso:</span>
                          <span className="font-bold" style={{ color: '#07593f' }}>
                            {caminhao.capacidade_peso_kg} kg
                          </span>
                        </div>
                      )}
                      {caminhao.motorista_padrao && (
                        <div className="flex items-center justify-between text-sm">
                          <span style={{ color: '#8B8B8B' }}>Motorista:</span>
                          <span style={{ color: '#07593f' }}>
                            {caminhao.motorista_padrao}
                          </span>
                        </div>
                      )}
                    </div>

                    <div className="flex gap-2">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => abrirModal(caminhao)}
                        className="flex-1"
                      >
                        <Pencil className="w-4 h-4 mr-1" />
                        Editar
                      </Button>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleDelete(caminhao.id)}
                        className="text-red-600 hover:text-red-700"
                      >
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      <Dialog open={modalAberto} onOpenChange={setModalAberto}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle style={{ color: '#07593f' }}>
              {editando ? "Editar Caminhão" : "Novo Caminhão"}
            </DialogTitle>
          </DialogHeader>

          <form onSubmit={handleSubmit}>
            <div className="space-y-4 py-4">
              <div className="grid md:grid-cols-2 gap-4">
                <div>
                  <Label>Nome/Identificação *</Label>
                  <Input
                    value={formData.nome}
                    onChange={(e) => setFormData({ ...formData, nome: e.target.value })}
                    placeholder="Ex: Caminhão 1, HR Branco"
                    required
                  />
                </div>
                <div>
                  <Label>Placa</Label>
                  <Input
                    value={formData.placa}
                    onChange={(e) => setFormData({ ...formData, placa: e.target.value.toUpperCase() })}
                    placeholder="ABC-1234"
                    maxLength={8}
                  />
                </div>
              </div>

              <div className="grid md:grid-cols-2 gap-4">
                <div>
                  <Label>Capacidade Volumétrica (m³) *</Label>
                  <Input
                    type="number"
                    step="0.1"
                    min="0"
                    value={formData.capacidade_volume_m3}
                    onChange={(e) => setFormData({ ...formData, capacidade_volume_m3: parseFloat(e.target.value) || 0 })}
                    required
                  />
                </div>
                <div>
                  <Label>Capacidade de Peso (kg)</Label>
                  <Input
                    type="number"
                    step="1"
                    min="0"
                    value={formData.capacidade_peso_kg}
                    onChange={(e) => setFormData({ ...formData, capacidade_peso_kg: parseFloat(e.target.value) || 0 })}
                  />
                </div>
              </div>

              <div className="grid md:grid-cols-2 gap-4">
                <div>
                  <Label>Motorista Padrão</Label>
                  <Input
                    value={formData.motorista_padrao}
                    onChange={(e) => setFormData({ ...formData, motorista_padrao: e.target.value })}
                    placeholder="Nome do motorista"
                  />
                </div>
                <div>
                  <Label>Telefone do Motorista</Label>
                  <Input
                    value={formData.telefone_motorista}
                    onChange={(e) => setFormData({ ...formData, telefone_motorista: e.target.value })}
                    placeholder="(00) 00000-0000"
                  />
                </div>
              </div>

              <div>
                <Label>Observações</Label>
                <Textarea
                  value={formData.observacoes}
                  onChange={(e) => setFormData({ ...formData, observacoes: e.target.value })}
                  rows={3}
                  placeholder="Informações adicionais sobre o caminhão"
                />
              </div>

              <div className="flex items-center gap-2">
                <input
                  type="checkbox"
                  id="ativo"
                  checked={formData.ativo}
                  onChange={(e) => setFormData({ ...formData, ativo: e.target.checked })}
                  className="w-4 h-4"
                />
                <Label htmlFor="ativo" className="cursor-pointer">
                  Caminhão ativo para entregas
                </Label>
              </div>
            </div>

            <DialogFooter>
              <Button type="button" variant="outline" onClick={fecharModal}>
                Cancelar
              </Button>
              <Button
                type="submit"
                disabled={criarMutation.isPending || atualizarMutation.isPending}
                style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
              >
                {(criarMutation.isPending || atualizarMutation.isPending) ? (
                  <>
                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                    Salvando...
                  </>
                ) : (
                  editando ? "Atualizar" : "Cadastrar"
                )}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { base44 } from "@/api/base44Client";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Alert, AlertDescription } from "@/components/ui/alert";
import {
    Key,
    Eye,
    EyeOff,
    Save,
    Loader2,
    Search,
    Sparkles,
    ExternalLink,
    Brain
} from "lucide-react";
import { toast } from "sonner";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";

export default function ConfiguracaoIntegracoes() {
    const queryClient = useQueryClient();
    const [showKey, setShowKey] = useState({}); // { google: false, gemini: false }

    const toggleShowKey = (key) => {
        setShowKey(prev => ({ ...prev, [key]: !prev[key] }));
    };

    const [formData, setFormData] = useState({
        google_api_key: "",
        google_cse_id: "",
        gemini_api_key: ""
    });

    // Buscar configuração existente
    const { data: config, isLoading } = useQuery({
        queryKey: ['config-integracoes'],
        queryFn: async () => {
            const configs = await base44.entities.ConfiguracaoSistema.list();
            return configs.find(c => c.tipo === 'integracoes') || null;
        }
    });

    // Preencher campos
    useEffect(() => {
        if (config?.dados) {
            setFormData({
                google_api_key: config.dados.google_api_key || "",
                google_cse_id: config.dados.google_cse_id || "",
                gemini_api_key: config.dados.gemini_api_key || ""
            });
        }
    }, [config]);

    const handleChange = (field, value) => {
        setFormData(prev => ({ ...prev, [field]: value }));
    };

    // Mutation para salvar
    const saveMutation = useMutation({
        mutationFn: async (dados) => {
            if (config?.id) {
                return base44.entities.ConfiguracaoSistema.update(config.id, { dados });
            } else {
                return base44.entities.ConfiguracaoSistema.create({
                    tipo: 'integracoes',
                    nome: 'Configurações de Integrações',
                    dados
                });
            }
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['config-integracoes'] });
            toast.success("Configurações atualizadas com sucesso!");
        },
        onError: (error) => {
            console.error("Erro ao salvar:", error);
            toast.error("Erro ao salvar configurações");
        }
    });

    if (isLoading) {
        return (
            <div className="flex items-center justify-center h-64">
                <Loader2 className="w-8 h-8 animate-spin text-green-600" />
            </div>
        );
    }

    return (
        <div className="max-w-4xl mx-auto space-y-8">
            <div>
                <h2 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
                    <Brain className="w-8 h-8 text-purple-600" />
                    Central de Inteligência e Integrações
                </h2>
                <p className="text-gray-500 mt-1">Conecte seu sistema aos serviços de IA e busca do Google Cloud.</p>
            </div>

            {/* Google Ecosystem Card */}
            <Card className="border-t-4 border-t-blue-500 shadow-sm">
                <CardHeader>
                    <div className="flex items-center justify-between">
                        <div>
                            <CardTitle className="text-xl flex items-center gap-2">
                                Google Cloud Services
                            </CardTitle>
                            <CardDescription>
                                Configure acesso unificado para Busca Customizada (Imagens) e Gemini AI.
                            </CardDescription>
                        </div>
                        <div className="flex gap-2">
                            {formData.google_api_key && <Badge variant="outline" className="bg-blue-50 text-blue-700 border-blue-200">Search Ativo</Badge>}
                            {formData.gemini_api_key && <Badge variant="outline" className="bg-purple-50 text-purple-700 border-purple-200">Gemini AI Ativo</Badge>}
                        </div>
                    </div>
                </CardHeader>
                <CardContent className="space-y-6">

                    {/* Seção 1: Busca e Imagens */}
                    <div className="grid md:grid-cols-2 gap-6 p-4 bg-gray-50 rounded-lg border border-gray-100">
                        <div className="col-span-2">
                            <h3 className="font-semibold text-gray-900 flex items-center gap-2 mb-4">
                                <Search className="w-4 h-4 text-blue-600" />
                                Motor de Busca (Custom Search)
                            </h3>
                        </div>

                        <div className="space-y-2">
                            <Label htmlFor="google_key">Google API Key (Search)</Label>
                            <div className="relative">
                                <Input
                                    id="google_key"
                                    type={showKey.google ? "text" : "password"}
                                    value={formData.google_api_key}
                                    onChange={(e) => handleChange('google_api_key', e.target.value)}
                                    placeholder="AIza..."
                                    className="pr-10 bg-white"
                                />
                                <button
                                    type="button"
                                    onClick={() => toggleShowKey('google')}
                                    className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                                >
                                    {showKey.google ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                                </button>
                            </div>
                            <p className="text-xs text-gray-500">Usada para buscar imagens de produtos automaticamente.</p>
                        </div>

                        <div className="space-y-2">
                            <Label htmlFor="cse_id">Search Engine ID (CSE)</Label>
                            <Input
                                id="cse_id"
                                value={formData.google_cse_id}
                                onChange={(e) => handleChange('google_cse_id', e.target.value)}
                                placeholder="01757666...:aaaaa"
                                className="bg-white"
                            />
                            <p className="text-xs text-gray-500">ID do mecanismo de busca programável.</p>
                        </div>
                    </div>

                    {/* Seção 2: Inteligência Artificial */}
                    <div className="p-4 bg-purple-50 rounded-lg border border-purple-100">
                        <h3 className="font-semibold text-gray-900 flex items-center gap-2 mb-4">
                            <Sparkles className="w-4 h-4 text-purple-600" />
                            Inteligência Artificial (Gemini AI)
                        </h3>

                        <div className="space-y-2">
                            <Label htmlFor="gemini_key">Gemini API Key</Label>
                            <div className="relative">
                                <Input
                                    id="gemini_key"
                                    type={showKey.gemini ? "text" : "password"}
                                    value={formData.gemini_api_key}
                                    onChange={(e) => handleChange('gemini_api_key', e.target.value)}
                                    placeholder="Cole sua chave do Google AI Studio..."
                                    className="pr-10 bg-white border-purple-200 focus:border-purple-400 focus:ring-purple-200"
                                />
                                <button
                                    type="button"
                                    onClick={() => toggleShowKey('gemini')}
                                    className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                                >
                                    {showKey.gemini ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                                </button>
                            </div>
                            <div className="flex justify-between items-center mt-1">
                                <p className="text-xs text-purple-700">
                                    Habilita sugestão de NCM, descrições automáticas e mais.
                                </p>
                                <a
                                    href="https://aistudio.google.com/app/apikey"
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    className="text-xs text-purple-600 hover:underline flex items-center gap-1"
                                >
                                    Gerar Chave <ExternalLink className="w-3 h-3" />
                                </a>
                            </div>
                        </div>
                    </div>

                </CardContent>
            </Card>

            {/* Barra de Ação Fixa ou no Fluxo */}
            <div className="flex justify-end pt-4 border-t">
                <Button
                    onClick={() => saveMutation.mutate(formData)}
                    disabled={saveMutation.isPending}
                    className="bg-green-600 hover:bg-green-700 min-w-[150px]"
                >
                    {saveMutation.isPending ? (
                        <>
                            <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                            Salvando...
                        </>
                    ) : (
                        <>
                            <Save className="w-4 h-4 mr-2" />
                            Salvar Alterações
                        </>
                    )}
                </Button>
            </div>
        </div>
    );
}

import React, { useState, useEffect } from "react";
import { base44 } from "@/api/base44Client";
import { supabase } from "@/lib/supabase";
import { useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Image as ImageIcon, Upload, Loader2, CheckCircle, X, Trash2, Palette, Save } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useOrganization } from "@/contexts/TenantContext";

export default function ConfiguracaoLogo({ user }) {
  const [uploading, setUploading] = useState(false);
  const [message, setMessage] = useState(null);
  const queryClient = useQueryClient();

  const { organization, refreshTenant } = useOrganization();
  const [nomeEmpresa, setNomeEmpresa] = useState("");
  const [savingName, setSavingName] = useState(false);
  const [nameMessage, setNameMessage] = useState(null);

  useEffect(() => {
    if (organization?.name) {
      setNomeEmpresa(organization.name);
    }
  }, [organization]);

  const handleSaveName = async () => {
    if (!nomeEmpresa.trim()) {
      setNameMessage({ type: 'error', text: 'O nome da empresa não pode ser vazio.' });
      return;
    }

    setSavingName(true);
    setNameMessage(null);
    try {
      const { error } = await supabase
        .from('organizations')
        .update({ name: nomeEmpresa })
        .eq('id', organization.id);

      if (error) throw error;

      setNameMessage({ type: 'success', text: 'Nome da empresa atualizado com sucesso!' });
      if (refreshTenant) refreshTenant();

      setTimeout(() => window.location.reload(), 1500);
    } catch (error) {
      console.error('Erro ao salvar nome:', error);
      setNameMessage({ type: 'error', text: 'Falha ao salvar o nome. Tente novamente.' });
    } finally {
      setSavingName(false);
    }
  };

  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    // Validar tipo de arquivo
    if (!file.type.startsWith('image/')) {
      setMessage({ type: 'error', text: 'Por favor, selecione um arquivo de imagem válido (PNG, JPG).' });
      return;
    }

    // Validar tamanho (max 2MB)
    if (file.size > 2 * 1024 * 1024) {
      setMessage({ type: 'error', text: 'A imagem é muito grande. O limite máximo é 2MB.' });
      return;
    }

    setUploading(true);
    setMessage(null);

    try {
      // Upload do arquivo
      const { file_url } = await base44.integrations.Core.UploadFile({ file });

      // Atualizar o usuário
      await base44.auth.updateMe({ logo_url: file_url });

      // Atualizar a logo da organização (Tenant)
      if (organization?.id) {
        const { error: orgError } = await supabase
          .from('organizations')
          .update({ logo_url: file_url })
          .eq('id', organization.id);

        if (orgError) throw orgError;
      }

      // Recarregar caches
      queryClient.invalidateQueries({ queryKey: ['users'] });

      setMessage({ type: 'success', text: 'Identidade visual atualizada com sucesso!' });

      // Reload sutil para atualizar sidebar e headers globais
      setTimeout(() => window.location.reload(), 1500);

    } catch (error) {
      console.error('Erro ao fazer upload:', error);
      setMessage({ type: 'error', text: 'Falha ao processar o upload. Tente novamente.' });
    } finally {
      setUploading(false);
    }
  };

  const handleRemoveLogo = async () => {
    if (!confirm('Isso removerá a logo de todo o sistema. Deseja continuar?')) return;

    setUploading(true);
    try {
      await base44.auth.updateMe({ logo_url: null });

      // Remover logo da organização (Tenant)
      if (organization?.id) {
        await supabase
          .from('organizations')
          .update({ logo_url: null })
          .eq('id', organization.id);
      }

      queryClient.invalidateQueries({ queryKey: ['users'] });
      setMessage({ type: 'success', text: 'Logo removida.' });
      setTimeout(() => window.location.reload(), 1000);
    } catch (error) {
      console.error('Erro ao remover logo:', error);
      setMessage({ type: 'error', text: 'Erro ao remover a logo.' });
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8">
      <div>
        <h2 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
          <Palette className="w-8 h-8 text-green-600" />
          Identidade Visual
        </h2>
        <p className="text-gray-500 mt-1">Personalize a aparência do sistema com a marca da sua empresa.</p>
      </div>

      <Card className="border-t-4 border-t-green-600 shadow-sm">
        <CardHeader>
          <CardTitle>Logo da Empresa</CardTitle>
          <CardDescription>
            Esta logo será exibida no menu lateral, relatórios impressos e tela de login.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-8">

          <div className="flex flex-col md:flex-row gap-8 items-start">
            {/* Preview Area */}
            <div className="flex-1 w-full">
              <div className="bg-gray-100 rounded-xl p-8 border-2 border-dashed border-gray-200 flex flex-col items-center justify-center min-h-[300px] relative overflow-hidden group">

                {/* Checkered Background Pattern for Transparency Check */}
                <div className="absolute inset-0 opacity-[0.03]"
                  style={{ backgroundImage: 'radial-gradient(#000 1px, transparent 1px)', backgroundSize: '20px 20px' }}
                />

                {user?.logo_url ? (
                  <div className="relative z-10 text-center">
                    <img
                      src={user.logo_url}
                      alt="Logo Atual"
                      className="max-w-[240px] max-h-[160px] object-contain drop-shadow-sm mb-6 transition-transform hover:scale-105 duration-300"
                    />
                    <div className="flex justify-center">
                      <Button
                        variant="destructive"
                        size="sm"
                        onClick={handleRemoveLogo}
                        disabled={uploading}
                        className="opacity-0 group-hover:opacity-100 transition-opacity"
                      >
                        <Trash2 className="w-4 h-4 mr-2" /> Remover Logo
                      </Button>
                    </div>
                  </div>
                ) : (
                  <div className="text-center z-10">
                    <div className="w-20 h-20 bg-gray-200 rounded-full flex items-center justify-center mx-auto mb-4 text-gray-400">
                      <ImageIcon className="w-10 h-10" />
                    </div>
                    <p className="text-gray-500 font-medium">Nenhuma logo definida</p>
                    <p className="text-xs text-gray-400 mt-1">O sistema usará o nome da empresa em texto.</p>
                  </div>
                )}
              </div>
            </div>

            {/* Config & Upload Area */}
            <div className="w-full md:w-80 flex-shrink-0 space-y-6">
              <div>
                <h3 className="font-semibold text-gray-900 mb-2">Alterar Imagem</h3>
                <label className="block w-full">
                  <input
                    type="file"
                    accept="image/png, image/jpeg, image/webp"
                    onChange={handleFileUpload}
                    className="hidden"
                    disabled={uploading}
                  />
                  <div className={`
                    w-full flex items-center justify-center gap-2 px-4 py-3 
                    border border-gray-300 rounded-lg shadow-sm 
                    text-sm font-medium text-gray-700 bg-white
                    hover:bg-gray-50 cursor-pointer transition-colors
                    ${uploading ? 'opacity-50 cursor-not-allowed' : ''}
                  `}>
                    {uploading ? (
                      <>
                        <Loader2 className="w-4 h-4 animate-spin text-green-600" />
                        Enviando...
                      </>
                    ) : (
                      <>
                        <Upload className="w-4 h-4 text-gray-500" />
                        Escolher Arquivo
                      </>
                    )}
                  </div>
                </label>
              </div>

              <div className="bg-blue-50 border border-blue-100 rounded-lg p-4 text-sm text-blue-800">
                <h4 className="font-medium mb-1 flex items-center gap-2">
                  <CheckCircle className="w-4 h-4" /> Recomendações
                </h4>
                <ul className="list-disc list-inside space-y-1 text-blue-700/80 text-xs ml-1">
                  <li>Formato: <strong>PNG (Fundo Transparente)</strong></li>
                  <li>Dimensões ideais: <strong>200x200px</strong> ou retangular horizontal</li>
                  <li>Evite textos muito pequenos</li>
                </ul>
              </div>

              {message && (
                <Alert className={`
                  ${message.type === 'error' ? 'border-red-200 bg-red-50 text-red-800' : 'border-green-200 bg-green-50 text-green-800'}
                `}>
                  <AlertDescription className="flex items-center gap-2">
                    {message.type === 'error' ? <X className="w-4 h-4" /> : <CheckCircle className="w-4 h-4" />}
                    {message.text}
                  </AlertDescription>
                </Alert>
              )}
            </div>
          </div>

        </CardContent>
      </Card>

      {/* Configuração do Nome da Empresa */}
      <Card className="border-t-4 border-t-green-600 shadow-sm">
        <CardHeader>
          <CardTitle>Informações da Empresa</CardTitle>
          <CardDescription>
            Este nome representará a sua marca em todo o sistema e nas etiquetas impressas.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="space-y-2 max-w-md">
            <Label htmlFor="nomeEmpresa">Nome da Empresa</Label>
            <Input
              id="nomeEmpresa"
              value={nomeEmpresa}
              onChange={(e) => setNomeEmpresa(e.target.value)}
              placeholder="Ex: Minha Empresa"
              disabled={savingName}
            />
          </div>

          <Button
            onClick={handleSaveName}
            disabled={savingName}
            className="bg-green-700 hover:bg-green-800"
          >
            {savingName ? (
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
            ) : (
              <Save className="w-4 h-4 mr-2" />
            )}
            Salvar Nome
          </Button>

          {nameMessage && (
            <Alert className={`max-w-md
              ${nameMessage.type === 'error' ? 'border-red-200 bg-red-50 text-red-800' : 'border-green-200 bg-green-50 text-green-800'}
            `}>
              <AlertDescription className="flex items-center gap-2">
                {nameMessage.type === 'error' ? <X className="w-4 h-4" /> : <CheckCircle className="w-4 h-4" />}
                {nameMessage.text}
              </AlertDescription>
            </Alert>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { base44 } from "@/api/base44Client";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useTenant } from "@/contexts/TenantContext";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import {
    Calculator, ArrowRight, Info, TrendingUp, Settings, HandCoins, Loader2, Save
} from "lucide-react";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { useAuth } from "@/hooks/useAuth";

// Categorias padrão do sistema
const CATEGORIAS = [
    "Sofa", "Cama", "Mesa", "Cadeira", "Armario", "Estante", "Rack",
    "Poltrona", "Escrivaninha", "Criado-mudo", "Buffet", "Aparador",
    "Banco", "Colchao", "Guarda-roupa", "Comoda", "Painel", "Travesseiro",
    "Almofada", "Decoracao", "Utensilios", "Outros"
];

const TAXA_PADRAO_IMPOSTO = 18; // 18% padrão se não configurado

export default function ConfiguracaoMarkup() {
    const { user } = useAuth();
    const isAdmin = user?.cargo === 'Administrador';

    const { settings, updateSettings, isLoading: loadingSettings } = useTenant();
    const [margens, setMargens] = useState({});
    const [salvando, setSalvando] = useState(false);
    const [recalculando, setRecalculando] = useState(false);
    const [impostoEstimado, setImpostoEstimado] = useState(TAXA_PADRAO_IMPOSTO);

    const queryClient = useQueryClient();

    // Carregar configurações do tenant quando disponíveis
    useEffect(() => {
        if (settings?.markup_categorias) {
            setMargens(settings.markup_categorias);
        } else {
            // Inicializa com padrão se vazio
            const padroes = {};
            CATEGORIAS.forEach(cat => padroes[cat] = 45); // 45% default
            setMargens(padroes);
        }

        if (settings?.imposto_padrao) {
            setImpostoEstimado(settings.imposto_padrao);
        }
    }, [settings]);

    const { data: produtos = [], isLoading: loadingProdutos } = useQuery({
        queryKey: ['produtos_markup'],
        queryFn: () => base44.entities.Produto.list('nome'),
        staleTime: 1000 * 60 * 5 // 5 minutos cache
    });

    const handleMargemChange = (categoria, valor) => {
        const numValue = Math.max(0, Math.min(500, parseInt(valor) || 0));
        setMargens(prev => ({ ...prev, [categoria]: numValue }));
    };

    const salvarConfiguracoes = async () => {
        setSalvando(true);
        try {
            await updateSettings({
                markup_categorias: margens,
                imposto_padrao: impostoEstimado
            });
            toast.success("Configurações de markup salvas com sucesso!");
        } catch (error) {
            console.error(error);
            toast.error("Erro ao salvar configurações");
        } finally {
            setSalvando(false);
        }
    };

    const recalcularTodosProdutos = async () => {
        if (produtos.length === 0) {
            toast.error("Nenhum produto encontrado para recalcular");
            return;
        }

        const produtosComCusto = produtos.filter(p => p.preco_custo_tabela > 0 && p.categoria);
        if (produtosComCusto.length === 0) {
            toast.error("Nenhum produto com custo de tabela e categoria definidos");
            return;
        }

        // Confirmação antes de processar
        if (!window.confirm(`Isso irá atualizar o preço de VENDA de ${produtosComCusto.length} produtos baseado no CUSTO TABELA. Deseja continuar?`)) {
            return;
        }

        setRecalculando(true);
        let atualizados = 0;
        let erros = 0;

        try {
            // Processamento em lotes para não travar a UI
            const batchSize = 10;
            for (let i = 0; i < produtosComCusto.length; i += batchSize) {
                const batch = produtosComCusto.slice(i, i + batchSize);
                await Promise.all(batch.map(async (produto) => {
                    try {
                        const margemConfigurada = (margens[produto.categoria] || 45) / 100;
                        const custo = parseFloat(produto.preco_custo_tabela);

                        // Fórmula: Custo * (1 + Margem) * (1 + Imposto)
                        // Ex: 100 * 1.45 * 1.18 = 171.10
                        let novoPreco = custo * (1 + margemConfigurada);
                        novoPreco *= (1 + (impostoEstimado / 100));
                        novoPreco = Math.ceil(novoPreco); // Arredondar para cima (estratégia comercial)

                        // Só atualiza se mudar (reduz chamadas)
                        if (parseFloat(produto.preco_venda) !== novoPreco) {
                            await base44.entities.Produto.update(produto.id, {
                                preco_venda: novoPreco
                            });
                            atualizados++;
                        }
                    } catch (err) {
                        console.error(`Erro ao atualizar ${produto.nome}:`, err);
                        erros++;
                    }
                }));
            }

            queryClient.invalidateQueries({ queryKey: ['produtos_markup'] });
            queryClient.invalidateQueries({ queryKey: ['produtos'] }); // Atualiza lista geral

            if (erros === 0) {
                toast.success(`${atualizados} preços atualizados com sucesso!`);
            } else {
                toast.warning(`${atualizados} atualizados, ${erros} com erro`);
            }
        } catch (error) {
            toast.error("Erro ao processar: " + error.message);
        } finally {
            setRecalculando(false);
        }
    };

    const produtosPorCategoria = CATEGORIAS.reduce((acc, cat) => {
        acc[cat] = produtos.filter(p => p.categoria === cat).length;
        return acc;
    }, {});

    if (!isAdmin) {
        return (
            <div className="flex items-center justify-center p-12">
                <Alert className="max-w-md border-red-200 bg-red-50">
                    <AlertTitle className="text-red-800">Acesso Restrito</AlertTitle>
                    <AlertDescription className="text-red-700">
                        Você não tem permissão para acessar esta configuração.
                    </AlertDescription>
                </Alert>
            </div>
        );
    }

    if (loadingSettings) {
        return (
            <div className="flex items-center justify-center p-12">
                <Loader2 className="w-8 h-8 animate-spin text-green-600" />
            </div>
        );
    }

    return (
        <div className="max-w-4xl mx-auto space-y-8">
            {/* Header */}
            <div>
                <h2 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
                    <HandCoins className="w-8 h-8 text-green-600" />
                    Precificação Automática
                </h2>
                <p className="text-gray-500 mt-1">
                    Defina as margens de lucro padrão para cada categoria de produto.
                </p>
            </div>

            {/* Configuração Global */}
            <Card className="border-t-4 border-t-yellow-500 shadow-sm">
                <CardHeader>
                    <CardTitle className="text-lg flex items-center gap-2">
                        <Settings className="w-5 h-5 text-gray-500" />
                        Parâmetros Globais
                    </CardTitle>
                </CardHeader>
                <CardContent>
                    <div className="flex items-end gap-4 p-4 bg-yellow-50 rounded-lg border border-yellow-100">
                        <div className="space-y-2">
                            <Label>Imposto Médio Estimado (%)</Label>
                            <div className="flex items-center gap-2">
                                <Input
                                    type="number"
                                    value={impostoEstimado}
                                    onChange={(e) => setImpostoEstimado(e.target.value)}
                                    className="w-24 bg-white"
                                />
                                <span className="text-gray-500">%</span>
                            </div>
                            <p className="text-xs text-gray-500">Adicionado ao preço final para cobrir impostos.</p>
                        </div>
                        <div className="flex-1 text-sm text-yellow-800">
                            <strong>Fórmula de Precificação:</strong><br />
                            <code className="bg-white px-2 py-1 rounded border border-yellow-200 mt-1 block w-fit">
                                Preço = Custo Tabela × (1 + Margem%) × (1 + Imposto%)
                            </code>
                        </div>
                    </div>
                </CardContent>
            </Card>

            {/* Tabela de Markup */}
            <Card className="border-t-4 border-t-green-600 shadow-sm">
                <CardHeader className="flex flex-row items-center justify-between">
                    <div>
                        <CardTitle className="text-lg flex items-center gap-2">
                            <TrendingUp className="w-5 h-5 text-gray-500" />
                            Margens por Categoria
                        </CardTitle>
                        <CardDescription>
                            Ajuste o markup aplicado sobre o custo de tabela.
                        </CardDescription>
                    </div>
                    <Button
                        onClick={recalcularTodosProdutos}
                        disabled={recalculando || loadingProdutos}
                        variant="outline"
                        size="sm"
                        className="text-blue-600 border-blue-200 hover:bg-blue-50"
                    >
                        {recalculando ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Calculator className="w-4 h-4 mr-2" />}
                        Recalcular Tabela Atual
                    </Button>
                </CardHeader>
                <CardContent>
                    <div className="border rounded-xl overflow-hidden shadow-sm">
                        <Table>
                            <TableHeader className="bg-gray-50">
                                <TableRow>
                                    <TableHead className="w-[200px] font-semibold">Categoria</TableHead>
                                    <TableHead className="w-[150px] text-center font-semibold">Margem Lucro</TableHead>
                                    <TableHead className="w-[150px] text-right font-semibold">Produtos Ativos</TableHead>
                                    <TableHead className="text-right font-semibold">Simulação (Custo R$ 100)</TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {CATEGORIAS.map(categoria => {
                                    const margem = margens[categoria] || 45;
                                    // Simulação: 100 * (1+margem) * (1+imposto)
                                    const precoExemplo = 100 * (1 + margem / 100) * (1 + (parseFloat(impostoEstimado) || 0) / 100);

                                    return (
                                        <TableRow key={categoria} className="hover:bg-gray-50 transition-colors">
                                            <TableCell className="font-medium">
                                                <Badge variant="outline" className="font-normal text-sm px-3 py-1 bg-white">
                                                    {categoria}
                                                </Badge>
                                            </TableCell>
                                            <TableCell>
                                                <div className="relative flex items-center justify-center">
                                                    <Input
                                                        type="number"
                                                        min="0"
                                                        max="500"
                                                        value={margem}
                                                        onChange={(e) => handleMargemChange(categoria, e.target.value)}
                                                        className="w-20 pr-8 text-center font-bold text-green-700 bg-green-50/50 border-green-200 focus:border-green-500 focus:ring-green-200"
                                                    />
                                                    <span className="absolute right-8 top-1/2 -translate-y-1/2 text-green-600 text-xs font-bold">%</span>
                                                </div>
                                            </TableCell>
                                            <TableCell className="text-right text-gray-500">
                                                {produtosPorCategoria[categoria] || "-"}
                                            </TableCell>
                                            <TableCell className="text-right">
                                                <div className="flex items-center justify-end gap-2 text-gray-600">
                                                    <span className="text-xs">R$ 100 ➔</span>
                                                    <span className="font-mono font-bold text-green-700 bg-green-100 px-2 py-0.5 rounded">
                                                        R$ {Math.ceil(precoExemplo).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                                                    </span>
                                                </div>
                                            </TableCell>
                                        </TableRow>
                                    );
                                })}
                            </TableBody>
                        </Table>
                    </div>
                </CardContent>
            </Card>

            {/* Footer Fixo */}
            <div className="flex justify-end pt-4 bg-white/50 backdrop-blur-sm sticky bottom-0 pb-4 border-t">
                <Button
                    onClick={salvarConfiguracoes}
                    disabled={salvando}
                    className="bg-green-700 hover:bg-green-800 text-white shadow-lg min-w-[200px]"
                >
                    {salvando ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Save className="w-4 h-4 mr-2" />}
                    Salvar Alterações
                </Button>
            </div>
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { useTenant } from '@/contexts/TenantContext';
import { supabase } from '@/lib/supabase';
import { SYSTEM_MODULES, MODULE_CATEGORIES } from '@/config/modules';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';
import { Button } from '@/components/ui/button';
import { toast } from 'sonner';
import { Sliders, Save, Loader2, PackageCheck, AlertCircle, CheckCircle2, XCircle } from 'lucide-react';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';

export default function ConfiguracaoModulosOperacionais() {
    const { organization, settings, plano, isModuleAllowedByPlan, refreshTenant } = useTenant();
    const [modulosState, setModulosState] = useState({});
    const [saving, setSaving] = useState(false);


    useEffect(() => {
        const initialMap = {};
        const activeFromSettings = settings?.modulos_ativos || {};

        SYSTEM_MODULES.forEach(mod => {
            if (Object.prototype.hasOwnProperty.call(activeFromSettings, mod.key)) {
                initialMap[mod.key] = activeFromSettings[mod.key] !== false;
            } else {
                initialMap[mod.key] = mod.defaultActive;
            }
        });

        setModulosState(initialMap);
    }, [settings]);

    const handleToggle = (key, value) => {
        setModulosState(prev => ({
            ...prev,
            [key]: value
        }));
    };

    const handleSave = async () => {
        try {
            setSaving(true);
            const orgId = organization?.id || '00000000-0000-0000-0000-000000000001';

            const modulosAtuais = settings?.modulos_ativos || {};
            const novosModulos = {
                ...modulosAtuais,
                ...modulosState
            };

            const { error } = await supabase
                .from('organization_settings')
                .upsert(
                    {
                        organization_id: orgId,
                        modulos_ativos: novosModulos,
                        updated_at: new Date().toISOString()
                    },
                    { onConflict: 'organization_id' }
                );

            if (error) throw error;

            await refreshTenant();
            toast.success('Módulos e recursos atualizados com sucesso!');
        } catch (error) {
            console.error('Erro ao salvar módulos da organização:', error);
            toast.error(`Erro ao salvar: ${error.message || error}`);
        } finally {
            setSaving(false);
        }
    };

    return (
        <div className="space-y-6">
            <Card>
                <CardHeader>
                    <CardTitle className="flex items-center gap-2">
                        <Sliders className="h-5 w-5 text-slate-700" />
                        Módulos & Recursos do Sistema
                    </CardTitle>
                    <CardDescription>
                        Ative ou desative as funcionalidades do sistema de acordo com a estrutura da sua empresa. Recursos desativados serão ocultados dos menus para manter o sistema simples.
                    </CardDescription>
                </CardHeader>
                <CardContent className="space-y-8">
                    {MODULE_CATEGORIES.map(cat => {
                        const modulesInCategory = SYSTEM_MODULES.filter(m => m.category === cat.key);
                        return (
                            <div key={cat.key} className="space-y-4">
                                <div className="border-b pb-2">
                                    <h3 className="text-lg font-semibold text-slate-900">{cat.label}</h3>
                                </div>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    {modulesInCategory.map(mod => {
                                        const isAllowedByPlan = isModuleAllowedByPlan ? isModuleAllowedByPlan(mod.key) : true;
                                        const isChecked = isAllowedByPlan && modulosState[mod.key] !== false;
                                        return (
                                            <div
                                                key={mod.key}
                                                className={`flex items-start justify-between p-4 rounded-xl border transition-all ${
                                                    !isAllowedByPlan
                                                        ? 'border-slate-200 bg-slate-100/80 opacity-60'
                                                        : isChecked
                                                            ? 'border-slate-200 bg-white shadow-sm'
                                                            : 'border-slate-100 bg-slate-50/80'
                                                }`}
                                            >
                                                <div className="space-y-1 pr-4">
                                                    <div className="flex items-center gap-2">
                                                        <Label
                                                            htmlFor={`toggle-${mod.key}`}
                                                            className={`text-sm font-semibold text-slate-900 ${!isAllowedByPlan ? 'cursor-not-allowed text-slate-500' : 'cursor-pointer'}`}
                                                        >
                                                            {mod.label}
                                                        </Label>
                                                        {!isAllowedByPlan ? (
                                                            <span className="inline-flex items-center text-[10px] font-medium text-amber-800 bg-amber-100 px-2 py-0.5 rounded-full border border-amber-300">
                                                                🔒 Requer Upgrade
                                                            </span>
                                                        ) : isChecked ? (
                                                            <span className="inline-flex items-center text-[10px] font-medium text-emerald-700 bg-emerald-50 px-2 py-0.5 rounded-full border border-emerald-200">
                                                                Ativo
                                                            </span>
                                                        ) : (
                                                            <span className="inline-flex items-center text-[10px] font-medium text-slate-500 bg-slate-100 px-2 py-0.5 rounded-full border border-slate-200">
                                                                Desativado
                                                            </span>
                                                        )}
                                                    </div>
                                                    <p className="text-xs text-slate-500 leading-relaxed">
                                                        {!isAllowedByPlan
                                                            ? 'Este recurso não está incluso no plano de assinatura atual da sua empresa.'
                                                            : mod.description}
                                                    </p>
                                                </div>
                                                <Switch
                                                    id={`toggle-${mod.key}`}
                                                    checked={isChecked}
                                                    disabled={!isAllowedByPlan}
                                                    onCheckedChange={(val) => handleToggle(mod.key, val)}
                                                />
                                            </div>
                                        );
                                    })}

                                </div>
                            </div>
                        );
                    })}

                    <div className="flex items-center justify-between border-t pt-4">
                        <p className="text-xs text-slate-500">
                            As alterações afetam os menus e permissões de acesso da empresa imediatamente após salvar.
                        </p>
                        <Button onClick={handleSave} disabled={saving} className="bg-slate-900 hover:bg-slate-800 text-white">
                            {saving ? (
                                <>
                                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                                    Salvando...
                                </>
                            ) : (
                                <>
                                    <Save className="mr-2 h-4 w-4" />
                                    Salvar Módulos
                                </>
                            )}
                        </Button>
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

import React, { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Alert, AlertDescription } from "@/components/ui/alert";
import {
    Building2, Save, Edit, AlertCircle, Search, Loader2
} from "lucide-react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from "@/components/ui/dialog";
import { toast } from "sonner";
import { supabase } from "@/lib/supabase";
import { useTenant } from "@/contexts/TenantContext";

const DEFAULT_ORG_ID = "00000000-0000-0000-0000-000000000001";

// Formatação de CNPJ para exibição
const formatarCnpj = (cnpj) => {
    if (!cnpj) return '';
    const digits = cnpj.replace(/\D/g, '');
    if (digits.length !== 14) return cnpj;
    return `${digits.slice(0,2)}.${digits.slice(2,5)}.${digits.slice(5,8)}/${digits.slice(8,12)}-${digits.slice(12,14)}`;
};

const REGIMES_TRIBUTARIOS = [
    { value: "1", label: "Simples Nacional" },
    { value: "2", label: "Simples Nacional - Excesso de sublimite" },
    { value: "3", label: "Regime Normal (Lucro Presumido/Real)" },
];

// Lê do localStorage como fallback (dados legados)
const carregarDadosFiscaisLocal = () => {
    try {
        const dados = localStorage.getItem("nfe_empresas_fiscais");
        return dados ? JSON.parse(dados) : {};
    } catch {
        return {};
    }
};

// Mapeia config do banco → objeto empresa para exibição
const dbConfigParaEmpresa = (config) => ({
    cnpj: (config.emitente_cnpj || '').replace(/\D/g, ''),
    nome: config.emitente_nome || 'Empresa não configurada',
    cnpjFormatado: formatarCnpj(config.emitente_cnpj),
    email: config.emitente_email || '',
});

// Mapeia colunas do banco → objeto formEmpresa
const dbConfigParaForm = (config) => ({
    ie: config.emitente_ie || "",
    regimeTributario: String(config.emitente_crt || "1"),
    logradouro: config.emitente_logradouro || "",
    numero: config.emitente_numero || "",
    complemento: config.emitente_complemento || "",
    bairro: config.emitente_bairro || "",
    municipio: config.emitente_municipio || "",
    codigoMunicipio: config.emitente_codigo_municipio || "",
    uf: config.emitente_uf || "ES",
    cep: config.emitente_cep || "",
});

export default function ConfiguracaoNfe() {
    const { organization } = useTenant();
    const orgId = organization?.id || DEFAULT_ORG_ID;

    // Empresa emissora carregada do banco para este tenant
    const [empresaEmissora, setEmpresaEmissora] = useState(null);
    const [empresaPadrao, setEmpresaPadrao] = useState(() => {
        return localStorage.getItem("nfe_empresa_padrao") || '';
    });

    const [dadosFiscais, setDadosFiscais] = useState(carregarDadosFiscaisLocal);
    const [editandoEmpresa, setEditandoEmpresa] = useState(null);
    const [formEmpresa, setFormEmpresa] = useState({});
    const [highlightEmitente, setHighlightEmitente] = useState(false);
    const [savingDb, setSavingDb] = useState(false);
    const [acbrCredentials, setAcbrCredentials] = useState({ client_id: '', client_secret: '' });
    const [savingCredentials, setSavingCredentials] = useState(false);
    const [certDialogOpen, setCertDialogOpen] = useState(false);
    const [savingCert, setSavingCert] = useState(false);
    const [certFile, setCertFile] = useState(null);
    const [certPassword, setCertPassword] = useState('');
    const [certStatus, setCertStatus] = useState({
        empresaRegistrada: false,
        validade: null,
        thumbprint: null,
    });
    const [certForm, setCertForm] = useState({
        cnpj: '',
        nome_razao_social: '',
        email: '',
        logradouro: '',
        numero: '',
        complemento: '',
        bairro: '',
        cidade: '',
        uf: 'ES',
        cep: '',
        codigo_municipio: '',
    });

    // ─── Padrões Fiscais (org-level defaults) ────────────────────────────────
    const [fiscalDefaults, setFiscalDefaults] = useState({
        csosn_padrao: '102',
        cst_icms_padrao: '00',
        cst_pis_padrao: '49',
        cst_cofins_padrao: '49',
        aliquota_icms_padrao: '17.00',
        aliquota_icms_interestadual_padrao: '12.00',
        aliquota_pis_padrao: '0.65',
        aliquota_cofins_padrao: '3.00',
        percentual_tributos_padrao: '17.00',
        mod_frete_padrao: '9',
    });
    const [savingFiscal, setSavingFiscal] = useState(false);
    const [fiscalLoaded, setFiscalLoaded] = useState(false);

    // Check for highlight signal from EmitirNFeModal
    useEffect(() => {
        const signal = localStorage.getItem('nfe_highlight_emitente');
        if (signal === '1') {
            localStorage.removeItem('nfe_highlight_emitente');
            setHighlightEmitente(true);
        }
    }, []);

    // ─── Carregar emitente ativo do banco ────────────────────────────────────
    useEffect(() => {
        async function carregarDoDb() {
            const { data, error } = await supabase
                .from('organization_nfe_configs')
                .select('emitente_cnpj, emitente_nome, emitente_ie, emitente_uf, emitente_crt, emitente_logradouro, emitente_numero, emitente_complemento, emitente_bairro, emitente_municipio, emitente_cep, emitente_codigo_municipio, emitente_email, acbr_client_id, acbr_client_secret, acbr_empresa_registrada, acbr_certificado_validade, acbr_certificado_thumbprint, csosn_padrao, cst_icms_padrao, cst_pis_padrao, cst_cofins_padrao, aliquota_icms_padrao, aliquota_icms_interestadual_padrao, aliquota_pis_padrao, aliquota_cofins_padrao, percentual_tributos_padrao, mod_frete_padrao')
                .eq('organization_id', orgId)
                .maybeSingle();

            if (error || !data) return;

            // Credenciais ACBR
            if (data.acbr_client_id || data.acbr_client_secret) {
                setAcbrCredentials({
                    client_id: data.acbr_client_id || '',
                    client_secret: data.acbr_client_secret || '',
                });
            }

            setCertStatus({
                empresaRegistrada: !!data.acbr_empresa_registrada,
                validade: data.acbr_certificado_validade || null,
                thumbprint: data.acbr_certificado_thumbprint || null,
            });

            // Padrões Fiscais
            setFiscalDefaults(prev => ({
                csosn_padrao: data.csosn_padrao || prev.csosn_padrao,
                cst_icms_padrao: data.cst_icms_padrao || prev.cst_icms_padrao,
                cst_pis_padrao: data.cst_pis_padrao || prev.cst_pis_padrao,
                cst_cofins_padrao: data.cst_cofins_padrao || prev.cst_cofins_padrao,
                aliquota_icms_padrao: data.aliquota_icms_padrao != null ? String(data.aliquota_icms_padrao) : prev.aliquota_icms_padrao,
                aliquota_icms_interestadual_padrao: data.aliquota_icms_interestadual_padrao != null ? String(data.aliquota_icms_interestadual_padrao) : prev.aliquota_icms_interestadual_padrao,
                aliquota_pis_padrao: data.aliquota_pis_padrao != null ? String(data.aliquota_pis_padrao) : prev.aliquota_pis_padrao,
                aliquota_cofins_padrao: data.aliquota_cofins_padrao != null ? String(data.aliquota_cofins_padrao) : prev.aliquota_cofins_padrao,
                percentual_tributos_padrao: data.percentual_tributos_padrao != null ? String(data.percentual_tributos_padrao) : prev.percentual_tributos_padrao,
                mod_frete_padrao: data.mod_frete_padrao != null ? String(data.mod_frete_padrao) : prev.mod_frete_padrao,
            }));
            setFiscalLoaded(true);

            // Montar objeto empresa emissora a partir do banco
            const empresa = dbConfigParaEmpresa(data);
            setEmpresaEmissora(empresa);

            const { emitente_cnpj } = data;
            if (!emitente_cnpj) return;

            // Empresa padrão vem do banco
            const cnpjLimpo = emitente_cnpj.replace(/\D/g, '');
            setEmpresaPadrao(cnpjLimpo);
            localStorage.setItem("nfe_empresa_padrao", cnpjLimpo);

            // Dados fiscais come do banco (sobrescreve localStorage para esta empresa)
            setDadosFiscais(prev => ({
                ...prev,
                [cnpjLimpo]: dbConfigParaForm(data),
            }));
        }

        carregarDoDb();
    }, [orgId]);

    // Helper: upsert emitente no banco
    const salvarEmitenteNoBanco = async (empresa, form) => {
        const cnpjLimpo = empresa.cnpj.replace(/\D/g, '');
        const upsertData = {
            emitente_cnpj: cnpjLimpo,
            emitente_nome: empresa.nome,
            emitente_ie: form.ie || null,
            emitente_uf: form.uf || 'ES',
            emitente_crt: parseInt(form.regimeTributario || '1'),
            emitente_logradouro: form.logradouro || null,
            emitente_numero: form.numero || null,
            emitente_bairro: form.bairro || null,
            emitente_municipio: form.municipio || null,
            emitente_cep: (form.cep || '').replace(/\D/g, '') || null,
            emitente_codigo_municipio: form.codigoMunicipio || null,
        };

        // Atualiza todos os rows da org (homologação + produção)
        const { error } = await supabase
            .from('organization_nfe_configs')
            .update(upsertData)
            .eq('organization_id', orgId);

        return error;
    };

    const abrirEdicaoEmpresa = (empresa) => {
        const cnpj = empresa?.cnpj || empresaPadrao;
        const dados = dadosFiscais[cnpj] || {};
        setFormEmpresa({
            ie: dados.ie || "",
            regimeTributario: dados.regimeTributario || "1",
            logradouro: dados.logradouro || "",
            numero: dados.numero || "",
            complemento: dados.complemento || "",
            bairro: dados.bairro || "",
            municipio: dados.municipio || "",
            codigoMunicipio: dados.codigoMunicipio || "",
            uf: dados.uf || "ES",
            cep: dados.cep || "",
        });
        setEditandoEmpresa(empresa || empresaEmissora);
    };

    const formatarTexto = (valor) => {
        if (!valor) return "";
        return valor.toLowerCase().replace(/(?:^|\s|["'([{])+\S/g, match => match.toUpperCase());
    };

    const buscarCEP = async (cep) => {
        if (!cep) return;
        const cepLimpo = cep.replace(/\D/g, '');
        if (cepLimpo.length !== 8) return;

        const toastId = toast.loading("Buscando CEP...");

        try {
            const response = await fetch(`https://viacep.com.br/ws/${cepLimpo}/json/`);
            const data = await response.json();

            if (!data.erro) {
                const novoEndereco = {
                    logradouro: formatarTexto(data.logradouro || ""),
                    bairro: formatarTexto(data.bairro || ""),
                    municipio: formatarTexto(data.localidade || ""),
                    uf: data.uf || "",
                    codigoMunicipio: data.ibge || ""
                };

                setFormEmpresa(prev => ({
                    ...prev,
                    ...novoEndereco
                }));

                toast.success("Endereço encontrado e preenchido!", { id: toastId });
            } else {
                toast.error("CEP não encontrado.", { id: toastId });
            }
        } catch (error) {
            toast.error("Erro ao buscar CEP.", { id: toastId });
        }
    };

    const buscarCNPJ = async (cnpj) => {
        const cnpjLimpo = cnpj.replace(/\D/g, '');
        if (cnpjLimpo.length !== 14) return;

        try {
            const response = await fetch(`https://brasilapi.com.br/api/cnpj/v1/${cnpjLimpo}`);
            const data = await response.json();

            let regime = "1";
            if (data.opcao_pelo_simples === false) {
                regime = "3";
            }

            setFormEmpresa(prev => ({
                ...prev,
                municipio: formatarTexto(data.municipio || ""),
                codigoMunicipio: data.codigo_municipio_ibge || "",
                uf: data.uf || "",
                logradouro: formatarTexto(data.logradouro || ""),
                numero: data.numero || "",
                complemento: formatarTexto(data.complemento || ""),
                bairro: formatarTexto(data.bairro || ""),
                cep: data.cep?.replace(/\D/g, '') || "",
                regimeTributario: regime
            }));
            toast.success("Dados carregados!");
        } catch (error) {
            toast.error("Erro ao buscar CNPJ.");
        }
    };

    const salvarDadosEmpresa = async () => {
        if (!editandoEmpresa) return;

        // 1. Atualiza state local + localStorage (backward compat)
        const novosDados = { ...dadosFiscais, [editandoEmpresa.cnpj]: formEmpresa };
        setDadosFiscais(novosDados);
        localStorage.setItem("nfe_empresas_fiscais", JSON.stringify(novosDados));

        // 2. Se for a empresa padrão, persiste no banco
        if (editandoEmpresa.cnpj === empresaPadrao) {
            setSavingDb(true);
            try {
                const err = await salvarEmitenteNoBanco(editandoEmpresa, formEmpresa);
                if (err) {
                    console.error('[ConfiguracaoNfe] Erro ao salvar no banco:', err);
                    toast.warning(`Dados salvos localmente, mas não foi possível salvar no banco: ${err.message}`);
                } else {
                    toast.success(`Dados de ${editandoEmpresa.nome} salvos!`);
                }
            } finally {
                setSavingDb(false);
            }
        } else {
            toast.success(`Dados de ${editandoEmpresa.nome} salvos!`);
        }

        setEditandoEmpresa(null);
    };

    const getStatusEmpresa = (cnpj) => {
        const dados = dadosFiscais[cnpj];
        if (!dados?.ie || !dados?.logradouro) {
            return { ok: false, msg: "Incompleto" };
        }
        return { ok: true, msg: "Configurado" };
    };

    // ─── Salvar Padrões Fiscais ─────────────────────────────────────────────
    const handleSalvarFiscalDefaults = async () => {
        setSavingFiscal(true);
        try {
            const updateData = {
                csosn_padrao: fiscalDefaults.csosn_padrao || null,
                cst_icms_padrao: fiscalDefaults.cst_icms_padrao || null,
                cst_pis_padrao: fiscalDefaults.cst_pis_padrao || null,
                cst_cofins_padrao: fiscalDefaults.cst_cofins_padrao || null,
                aliquota_icms_padrao: fiscalDefaults.aliquota_icms_padrao ? parseFloat(fiscalDefaults.aliquota_icms_padrao) : null,
                aliquota_icms_interestadual_padrao: fiscalDefaults.aliquota_icms_interestadual_padrao ? parseFloat(fiscalDefaults.aliquota_icms_interestadual_padrao) : null,
                aliquota_pis_padrao: fiscalDefaults.aliquota_pis_padrao ? parseFloat(fiscalDefaults.aliquota_pis_padrao) : null,
                aliquota_cofins_padrao: fiscalDefaults.aliquota_cofins_padrao ? parseFloat(fiscalDefaults.aliquota_cofins_padrao) : null,
                percentual_tributos_padrao: fiscalDefaults.percentual_tributos_padrao ? parseFloat(fiscalDefaults.percentual_tributos_padrao) : null,
                mod_frete_padrao: fiscalDefaults.mod_frete_padrao != null ? parseInt(fiscalDefaults.mod_frete_padrao) : null,
            };

            const { error } = await supabase
                .from('organization_nfe_configs')
                .update(updateData)
                .eq('organization_id', orgId);

            if (error) throw error;
            toast.success('Padrões fiscais salvos com sucesso!');
        } catch (err) {
            toast.error('Erro ao salvar padrões fiscais: ' + err.message);
        } finally {
            setSavingFiscal(false);
        }
    };

    const handleSalvarCredentials = async () => {
        if (!acbrCredentials.client_id.trim() || !acbrCredentials.client_secret.trim()) {
            toast.error('Preencha Client ID e Client Secret.');
            return;
        }
        setSavingCredentials(true);
        try {
            const { error } = await supabase
                .from('organization_nfe_configs')
                .update({
                    acbr_client_id: acbrCredentials.client_id.trim(),
                    acbr_client_secret: acbrCredentials.client_secret.trim(),
                    acbr_access_token: null,
                    acbr_token_expires_at: null,
                })
                .eq('organization_id', orgId);

            if (error) throw error;
            toast.success('Credenciais da ACBR API salvas com sucesso!');
        } catch (err) {
            toast.error('Erro ao salvar credenciais: ' + err.message);
        } finally {
            setSavingCredentials(false);
        }
    };

    const validarCnpj = (cnpj) => {
        const cleaned = (cnpj || '').replace(/\D/g, '');
        if (cleaned.length !== 14) return false;
        if (/^(\d)\1{13}$/.test(cleaned)) return false;

        let length = cleaned.length - 2;
        let numbers = cleaned.substring(0, length);
        const digits = cleaned.substring(length);
        let sum = 0;
        let pos = length - 7;

        for (let i = length; i >= 1; i--) {
            sum += parseInt(numbers.charAt(length - i), 10) * pos--;
            if (pos < 2) pos = 9;
        }

        let result = sum % 11 < 2 ? 0 : 11 - (sum % 11);
        if (result !== parseInt(digits.charAt(0), 10)) return false;

        length += 1;
        numbers = cleaned.substring(0, length);
        sum = 0;
        pos = length - 7;

        for (let i = length; i >= 1; i--) {
            sum += parseInt(numbers.charAt(length - i), 10) * pos--;
            if (pos < 2) pos = 9;
        }

        result = sum % 11 < 2 ? 0 : 11 - (sum % 11);
        return result === parseInt(digits.charAt(1), 10);
    };

    const fileToBase64 = async (file) => {
        const buffer = await file.arrayBuffer();
        const bytes = new Uint8Array(buffer);
        let binary = '';
        const chunkSize = 0x8000;
        for (let i = 0; i < bytes.length; i += chunkSize) {
            const chunk = bytes.subarray(i, i + chunkSize);
            binary += String.fromCharCode(...chunk);
        }
        return btoa(binary);
    };

    const abrirDialogCertificado = () => {
        const dados = dadosFiscais[empresaPadrao] || {};

        setCertForm({
            cnpj: (empresaPadrao || '').replace(/\D/g, ''),
            nome_razao_social: empresaEmissora?.nome || organization?.name || '',
            email: empresaEmissora?.email || '',
            logradouro: dados.logradouro || '',
            numero: dados.numero || '',
            complemento: dados.complemento || '',
            bairro: dados.bairro || '',
            cidade: dados.municipio || '',
            uf: dados.uf || 'ES',
            cep: (dados.cep || '').replace(/\D/g, ''),
            codigo_municipio: dados.codigoMunicipio || '',
        });

        setCertFile(null);
        setCertPassword('');
        setCertDialogOpen(true);
    };

    const handleRegistrarCertificado = async () => {
        if (!validarCnpj(certForm.cnpj)) {
            toast.error('CNPJ inválido.');
            return;
        }
        if (!certForm.nome_razao_social?.trim()) {
            toast.error('Razão social é obrigatória.');
            return;
        }
        if (!certForm.email?.trim()) {
            toast.error('Email é obrigatório.');
            return;
        }
        if (!certFile) {
            toast.error('Selecione o certificado A1 (.pfx ou .p12).');
            return;
        }
        if (!certPassword.trim()) {
            toast.error('Senha do certificado é obrigatória.');
            return;
        }

        setSavingCert(true);
        try {
            const certificado_base64 = await fileToBase64(certFile);

            const { data, error } = await supabase.functions.invoke('registrar-empresa-acbr', {
                body: {
                    organization_id: orgId,
                    cnpj: certForm.cnpj,
                    nome_razao_social: certForm.nome_razao_social,
                    email: certForm.email,
                    endereco: {
                        logradouro: certForm.logradouro,
                        numero: certForm.numero,
                        complemento: certForm.complemento,
                        bairro: certForm.bairro,
                        cidade: certForm.cidade,
                        uf: certForm.uf,
                        cep: certForm.cep,
                        codigo_municipio: certForm.codigo_municipio,
                    },
                    certificado_base64,
                    certificado_senha: certPassword,
                },
            });

            if (error) {
                throw new Error(error.message || 'Erro ao registrar certificado');
            }
            if (!data?.success) {
                throw new Error(data?.error || 'Falha ao registrar certificado');
            }

            setCertStatus({
                empresaRegistrada: true,
                validade: data.data?.certificado_validade || null,
                thumbprint: data.data?.thumbprint || null,
            });

            toast.success('Certificado registrado com sucesso na ACBR API.');
            setCertDialogOpen(false);
        } catch (err) {
            toast.error('Erro ao registrar certificado: ' + err.message);
        } finally {
            setSavingCert(false);
        }
    };

    return (
        <div className="max-w-4xl mx-auto space-y-6">
            <div>
                <h2 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
                    <Building2 className="w-8 h-8 text-green-600" />
                    Dados Fiscais das Empresas
                </h2>
                <p className="text-gray-500 mt-1">Gerencie os dados fiscais obrigatórios para cada CNPJ emissor.</p>
            </div>

            {/* ─── Credenciais ACBR API ─────────────────────────────────── */}
            <Card className="border-t-4 border-t-blue-600 shadow-sm">
                <CardHeader>
                    <CardTitle className="text-lg flex items-center gap-2">
                        <AlertCircle className="w-5 h-5 text-blue-600" />
                        Credenciais da ACBR API
                    </CardTitle>
                    <CardDescription>
                        Client ID e Client Secret do painel da ACBR API. Obrigatório para emissão via API.
                    </CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                    <div className="grid md:grid-cols-2 gap-4">
                        <div>
                            <Label>Client ID</Label>
                            <Input
                                value={acbrCredentials.client_id}
                                onChange={(e) => setAcbrCredentials(prev => ({ ...prev, client_id: e.target.value }))}
                                placeholder="Obtido em acbr.api.br"
                                className="font-mono text-sm"
                            />
                        </div>
                        <div>
                            <Label>Client Secret</Label>
                            <Input
                                type="password"
                                value={acbrCredentials.client_secret}
                                onChange={(e) => setAcbrCredentials(prev => ({ ...prev, client_secret: e.target.value }))}
                                placeholder="Obtido em acbr.api.br"
                                className="font-mono text-sm"
                            />
                        </div>
                    </div>
                    <div className="flex items-center gap-3">
                        <Button onClick={handleSalvarCredentials} disabled={savingCredentials} className="bg-blue-700 hover:bg-blue-800">
                            {savingCredentials ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Save className="w-4 h-4 mr-2" />}
                            Salvar Credenciais
                        </Button>
                        {acbrCredentials.client_id && acbrCredentials.client_secret && (
                            <Badge className="bg-green-100 text-green-800 border-green-200">Configurado</Badge>
                        )}
                        {(!acbrCredentials.client_id || !acbrCredentials.client_secret) && (
                            <Badge variant="outline" className="text-red-600 bg-red-50 border-red-100">Pendente</Badge>
                        )}
                    </div>
                </CardContent>
            </Card>

            <Card className="border-t-4 border-t-indigo-600 shadow-sm">
                <CardHeader>
                    <CardTitle className="text-lg flex items-center gap-2">
                        <AlertCircle className="w-5 h-5 text-indigo-600" />
                        Certificado Digital (A1)
                    </CardTitle>
                    <CardDescription>
                        Cadastre ou renove o certificado A1 (.pfx/.p12) da empresa emissora para habilitar emissão na ACBR API.
                    </CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                    <div className="flex flex-wrap items-center gap-3">
                        {certStatus.empresaRegistrada ? (
                            <Badge className="bg-green-100 text-green-800 border-green-200">Empresa registrada na ACBR</Badge>
                        ) : (
                            <Badge variant="outline" className="text-red-600 bg-red-50 border-red-100">Empresa não registrada</Badge>
                        )}

                        {certStatus.validade ? (
                            <Badge variant="outline" className="text-blue-700 bg-blue-50 border-blue-200">
                                Validade: {new Date(certStatus.validade).toLocaleDateString('pt-BR')}
                            </Badge>
                        ) : (
                            <Badge variant="outline" className="text-amber-700 bg-amber-50 border-amber-200">Sem validade registrada</Badge>
                        )}
                    </div>

                    {certStatus.thumbprint && (
                        <p className="text-xs text-gray-600 font-mono break-all">
                            Thumbprint: {certStatus.thumbprint}
                        </p>
                    )}

                    <Button onClick={abrirDialogCertificado} className="bg-indigo-700 hover:bg-indigo-800">
                        Cadastrar / Renovar Certificado
                    </Button>
                </CardContent>
            </Card>

            {/* ─── Padrões Fiscais para Emissão de NF-e ───────────────── */}
            <Card className="border-t-4 border-t-amber-500 shadow-sm">
                <CardHeader>
                    <CardTitle className="text-lg flex items-center gap-2">
                        <AlertCircle className="w-5 h-5 text-amber-600" />
                        Padrões Fiscais para Emissão de NF-e
                    </CardTitle>
                    <CardDescription>
                        Valores padrão de CSOSN/CST, alíquotas e tributação usados na emissão. Produtos com valores próprios terão prioridade.
                    </CardDescription>
                </CardHeader>
                <CardContent className="space-y-6">
                    {(() => {
                        const crtAtual = dadosFiscais[empresaPadrao]?.regimeTributario || '1';
                        const isSimplesNacional = crtAtual === '1' || crtAtual === '2';

                        return (
                            <>
                                {/* CSOSN ou CST ICMS dependendo do regime */}
                                <div>
                                    <h4 className="font-medium text-gray-700 mb-3">
                                        {isSimplesNacional ? 'ICMS - Simples Nacional' : 'ICMS - Regime Normal'}
                                    </h4>
                                    <div className="grid md:grid-cols-3 gap-4">
                                        {isSimplesNacional ? (
                                            <div>
                                                <Label>CSOSN Padrão</Label>
                                                <Select
                                                    value={fiscalDefaults.csosn_padrao}
                                                    onValueChange={(v) => setFiscalDefaults(prev => ({ ...prev, csosn_padrao: v }))}
                                                >
                                                    <SelectTrigger><SelectValue /></SelectTrigger>
                                                    <SelectContent>
                                                        <SelectItem value="102">102 - Tributada sem permissão de crédito</SelectItem>
                                                        <SelectItem value="103">103 - Isenção do ICMS (faixa SN)</SelectItem>
                                                        <SelectItem value="300">300 - Imune</SelectItem>
                                                        <SelectItem value="400">400 - Não tributada</SelectItem>
                                                        <SelectItem value="500">500 - ICMS cobrado por ST</SelectItem>
                                                        <SelectItem value="900">900 - Outros</SelectItem>
                                                    </SelectContent>
                                                </Select>
                                            </div>
                                        ) : (
                                            <>
                                                <div>
                                                    <Label>CST ICMS Padrão</Label>
                                                    <Select
                                                        value={fiscalDefaults.cst_icms_padrao}
                                                        onValueChange={(v) => setFiscalDefaults(prev => ({ ...prev, cst_icms_padrao: v }))}
                                                    >
                                                        <SelectTrigger><SelectValue /></SelectTrigger>
                                                        <SelectContent>
                                                            <SelectItem value="00">00 - Tributada integralmente</SelectItem>
                                                            <SelectItem value="10">10 - Tributada com ST</SelectItem>
                                                            <SelectItem value="20">20 - Com redução de base</SelectItem>
                                                            <SelectItem value="40">40 - Isenta</SelectItem>
                                                            <SelectItem value="41">41 - Não tributada</SelectItem>
                                                            <SelectItem value="60">60 - ICMS cobrado por ST</SelectItem>
                                                            <SelectItem value="90">90 - Outros</SelectItem>
                                                        </SelectContent>
                                                    </Select>
                                                </div>
                                                <div>
                                                    <Label>Alíquota ICMS (%)</Label>
                                                    <Input
                                                        type="number"
                                                        step="0.01"
                                                        value={fiscalDefaults.aliquota_icms_padrao}
                                                        onChange={(e) => setFiscalDefaults(prev => ({ ...prev, aliquota_icms_padrao: e.target.value }))}
                                                        placeholder="17.00"
                                                    />
                                                </div>
                                                <div>
                                                    <Label>Alíquota Interestadual (%)</Label>
                                                    <Input
                                                        type="number"
                                                        step="0.01"
                                                        value={fiscalDefaults.aliquota_icms_interestadual_padrao}
                                                        onChange={(e) => setFiscalDefaults(prev => ({ ...prev, aliquota_icms_interestadual_padrao: e.target.value }))}
                                                        placeholder="12.00"
                                                    />
                                                </div>
                                            </>
                                        )}
                                    </div>
                                </div>

                                {/* PIS / COFINS */}
                                <div className="border-t pt-4">
                                    <h4 className="font-medium text-gray-700 mb-3">PIS / COFINS</h4>
                                    <div className="grid md:grid-cols-2 gap-4">
                                        <div>
                                            <Label>CST PIS Padrão</Label>
                                            <Select
                                                value={fiscalDefaults.cst_pis_padrao}
                                                onValueChange={(v) => setFiscalDefaults(prev => ({ ...prev, cst_pis_padrao: v }))}
                                            >
                                                <SelectTrigger><SelectValue /></SelectTrigger>
                                                <SelectContent>
                                                    {isSimplesNacional ? (
                                                        <>
                                                            <SelectItem value="49">49 - Outras saídas (SN)</SelectItem>
                                                            <SelectItem value="99">99 - Outras operações</SelectItem>
                                                        </>
                                                    ) : (
                                                        <>
                                                            <SelectItem value="01">01 - Tributável (alíquota normal)</SelectItem>
                                                            <SelectItem value="04">04 - Monofásica (alíquota zero)</SelectItem>
                                                            <SelectItem value="06">06 - Alíquota zero</SelectItem>
                                                            <SelectItem value="07">07 - Isenta</SelectItem>
                                                            <SelectItem value="08">08 - Sem incidência</SelectItem>
                                                            <SelectItem value="09">09 - Com suspensão</SelectItem>
                                                            <SelectItem value="49">49 - Outras saídas</SelectItem>
                                                            <SelectItem value="99">99 - Outras operações</SelectItem>
                                                        </>
                                                    )}
                                                </SelectContent>
                                            </Select>
                                        </div>
                                        <div>
                                            <Label>CST COFINS Padrão</Label>
                                            <Select
                                                value={fiscalDefaults.cst_cofins_padrao}
                                                onValueChange={(v) => setFiscalDefaults(prev => ({ ...prev, cst_cofins_padrao: v }))}
                                            >
                                                <SelectTrigger><SelectValue /></SelectTrigger>
                                                <SelectContent>
                                                    {isSimplesNacional ? (
                                                        <>
                                                            <SelectItem value="49">49 - Outras saídas (SN)</SelectItem>
                                                            <SelectItem value="99">99 - Outras operações</SelectItem>
                                                        </>
                                                    ) : (
                                                        <>
                                                            <SelectItem value="01">01 - Tributável (alíquota normal)</SelectItem>
                                                            <SelectItem value="04">04 - Monofásica (alíquota zero)</SelectItem>
                                                            <SelectItem value="06">06 - Alíquota zero</SelectItem>
                                                            <SelectItem value="07">07 - Isenta</SelectItem>
                                                            <SelectItem value="08">08 - Sem incidência</SelectItem>
                                                            <SelectItem value="09">09 - Com suspensão</SelectItem>
                                                            <SelectItem value="49">49 - Outras saídas</SelectItem>
                                                            <SelectItem value="99">99 - Outras operações</SelectItem>
                                                        </>
                                                    )}
                                                </SelectContent>
                                            </Select>
                                        </div>
                                    </div>
                                    {!isSimplesNacional && (
                                        <div className="grid md:grid-cols-2 gap-4 mt-4">
                                            <div>
                                                <Label>Alíquota PIS (%)</Label>
                                                <Input
                                                    type="number"
                                                    step="0.01"
                                                    value={fiscalDefaults.aliquota_pis_padrao}
                                                    onChange={(e) => setFiscalDefaults(prev => ({ ...prev, aliquota_pis_padrao: e.target.value }))}
                                                    placeholder="0.65"
                                                />
                                            </div>
                                            <div>
                                                <Label>Alíquota COFINS (%)</Label>
                                                <Input
                                                    type="number"
                                                    step="0.01"
                                                    value={fiscalDefaults.aliquota_cofins_padrao}
                                                    onChange={(e) => setFiscalDefaults(prev => ({ ...prev, aliquota_cofins_padrao: e.target.value }))}
                                                    placeholder="3.00"
                                                />
                                            </div>
                                        </div>
                                    )}
                                </div>

                                {/* Tributos Aproximados + Frete */}
                                <div className="border-t pt-4">
                                    <h4 className="font-medium text-gray-700 mb-3">Outros Padrões</h4>
                                    <div className="grid md:grid-cols-2 gap-4">
                                        <div>
                                            <Label>Percentual Tributos Aprox. (%)</Label>
                                            <Input
                                                type="number"
                                                step="0.01"
                                                value={fiscalDefaults.percentual_tributos_padrao}
                                                onChange={(e) => setFiscalDefaults(prev => ({ ...prev, percentual_tributos_padrao: e.target.value }))}
                                                placeholder="17.00"
                                            />
                                            <p className="text-xs text-gray-500 mt-1">Lei da Transparência (12.741/2012) - valor informado ao consumidor</p>
                                        </div>
                                        <div>
                                            <Label>Modalidade de Frete Padrão</Label>
                                            <Select
                                                value={fiscalDefaults.mod_frete_padrao}
                                                onValueChange={(v) => setFiscalDefaults(prev => ({ ...prev, mod_frete_padrao: v }))}
                                            >
                                                <SelectTrigger><SelectValue /></SelectTrigger>
                                                <SelectContent>
                                                    <SelectItem value="0">0 - CIF (emitente)</SelectItem>
                                                    <SelectItem value="1">1 - FOB (destinatário)</SelectItem>
                                                    <SelectItem value="2">2 - Terceiros</SelectItem>
                                                    <SelectItem value="3">3 - Próprio por conta do remetente</SelectItem>
                                                    <SelectItem value="4">4 - Próprio por conta do destinatário</SelectItem>
                                                    <SelectItem value="9">9 - Sem frete</SelectItem>
                                                </SelectContent>
                                            </Select>
                                        </div>
                                    </div>
                                </div>

                                {/* Botão Salvar */}
                                <div className="flex items-center gap-3 pt-2">
                                    <Button onClick={handleSalvarFiscalDefaults} disabled={savingFiscal} className="bg-amber-600 hover:bg-amber-700">
                                        {savingFiscal ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Save className="w-4 h-4 mr-2" />}
                                        Salvar Padrões Fiscais
                                    </Button>
                                    {fiscalLoaded && (
                                        <Badge className="bg-green-100 text-green-800 border-green-200">Carregado do banco</Badge>
                                    )}
                                </div>
                            </>
                        );
                    })()}
                </CardContent>
            </Card>

            <Card className="border-t-4 border-t-green-600 shadow-sm">
                <CardHeader>
                    <CardTitle className="text-lg flex items-center gap-2">
                        <Building2 className="w-5 h-5 text-gray-500" />
                        Empresa Emissora
                    </CardTitle>
                    <CardDescription>Dados fiscais da empresa emissora de NF-e desta organização</CardDescription>
                </CardHeader>
                <CardContent>
                    {highlightEmitente && (
                        <Alert className="mb-6 bg-red-50 border-red-200">
                            <AlertCircle className="h-4 w-4 text-red-600" />
                            <AlertDescription className="text-red-700">
                                <strong>Atenção:</strong> Dados fiscais obrigatórios estão faltando para emissão de notas.
                            </AlertDescription>
                        </Alert>
                    )}

                    {(() => {
                        const empresa = empresaEmissora;
                        const cnpj = empresa?.cnpj || empresaPadrao;
                        const dados = dadosFiscais[cnpj] || {};
                        const status = getStatusEmpresa(cnpj);

                        if (!cnpj) {
                            return (
                                <div className="text-center py-8">
                                    <Building2 className="w-12 h-12 text-gray-300 mx-auto mb-3" />
                                    <p className="text-gray-500 mb-4">Nenhuma empresa emissora configurada para esta organização.</p>
                                    <p className="text-sm text-gray-400 mb-4">Configure as credenciais ACBR acima e cadastre o certificado digital para começar.</p>
                                </div>
                            );
                        }

                        return (
                            <div className="p-5 rounded-xl border-2 border-green-500 bg-green-50/50">
                                <div className="flex items-start justify-between mb-4">
                                    <div>
                                        <h4 className="font-bold text-gray-900">{empresa?.nome || organization?.name || 'Empresa'}</h4>
                                        <p className="text-xs text-gray-500 font-mono mt-0.5">{formatarCnpj(cnpj)}</p>
                                    </div>
                                    <div className="flex flex-col items-end gap-1">
                                        <Badge className="bg-green-100 text-green-800 border-green-200">Emissora Ativa</Badge>
                                        <Badge variant="outline" className={status.ok ? "text-blue-600 bg-blue-50 border-blue-100" : "text-red-600 bg-red-50 border-red-100"}>
                                            {status.msg}
                                        </Badge>
                                    </div>
                                </div>

                                <div className="space-y-2 mb-5">
                                    <div className="flex justify-between text-sm py-1 border-b border-dashed border-gray-200">
                                        <span className="text-gray-500">Inscrição Estadual</span>
                                        <span className="font-mono">{dados.ie || "-"}</span>
                                    </div>
                                    <div className="flex justify-between text-sm py-1 border-b border-dashed border-gray-200">
                                        <span className="text-gray-500">Regime</span>
                                        <span>{REGIMES_TRIBUTARIOS.find(r => r.value === dados.regimeTributario)?.label.split(" - ")[0] || "-"}</span>
                                    </div>
                                    <div className="text-sm py-1">
                                        <span className="text-gray-500 block text-xs mb-0.5">Endereço Fiscal</span>
                                        <span className="line-clamp-1 text-gray-700">
                                            {dados.logradouro ? `${dados.logradouro}, ${dados.numero} - ${dados.municipio}/${dados.uf}` : "-"}
                                        </span>
                                    </div>
                                </div>

                                <Button
                                    size="sm"
                                    variant="outline"
                                    className="w-full"
                                    onClick={() => abrirEdicaoEmpresa(empresa)}
                                >
                                    <Edit className="w-3.5 h-3.5 mr-2" />
                                    Editar Dados Fiscais
                                </Button>
                            </div>
                        );
                    })()}
                </CardContent>
            </Card>

            <Dialog open={!!editandoEmpresa} onOpenChange={() => setEditandoEmpresa(null)}>
                <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-2">
                            <Building2 className="w-5 h-5 text-green-600" />
                            Dados Fiscais - {editandoEmpresa?.nome}
                        </DialogTitle>
                        <DialogDescription>
                            Edite as informações fiscais (IE, Regime) e endereço da empresa.
                        </DialogDescription>
                    </DialogHeader>

                    <div className="space-y-4 py-4">
                        <div className="bg-blue-50 border border-blue-100 rounded-md p-3 mb-4 flex gap-4 text-sm text-blue-800">
                            <div className="flex items-center gap-2">
                                <Search className="w-4 h-4" />
                                <span className="font-semibold">Preencher via CNPJ:</span>
                                <Button variant="link" className="p-0 h-auto font-normal text-blue-700 underline" onClick={() => buscarCNPJ(editandoEmpresa.cnpj)}>
                                    Buscar dados de {editandoEmpresa?.cnpjFormatado || editandoEmpresa?.cnpj}
                                </Button>
                            </div>
                        </div>

                        <div className="grid md:grid-cols-2 gap-4">
                            <div>
                                <Label>Inscrição Estadual (IE)</Label>
                                <Input
                                    value={formEmpresa.ie || ""}
                                    onChange={(e) => setFormEmpresa({ ...formEmpresa, ie: e.target.value })}
                                />
                            </div>
                            <div>
                                <Label>Regime Tributário</Label>
                                <Select
                                    value={formEmpresa.regimeTributario || "1"}
                                    onValueChange={(v) => setFormEmpresa({ ...formEmpresa, regimeTributario: v })}
                                >
                                    <SelectTrigger><SelectValue /></SelectTrigger>
                                    <SelectContent>
                                        <SelectItem value="1">Simples Nacional</SelectItem>
                                        <SelectItem value="3">Regime Normal</SelectItem>
                                    </SelectContent>
                                </Select>
                            </div>
                        </div>

                        <div className="border-t pt-4">
                            <h4 className="font-medium mb-3 text-gray-700">Endereço Fiscal</h4>
                            <div className="grid md:grid-cols-3 gap-4 mb-4">
                                <div className="md:col-span-1">
                                    <Label>CEP</Label>
                                    <Input
                                        value={formEmpresa.cep || ""}
                                        onChange={(e) => setFormEmpresa({ ...formEmpresa, cep: e.target.value })}
                                        onBlur={(e) => buscarCEP(e.target.value)}
                                        placeholder="00000-000"
                                    />
                                </div>
                                <div className="md:col-span-2">
                                    <Label>Logradouro</Label>
                                    <Input
                                        value={formEmpresa.logradouro || ""}
                                        onChange={(e) => setFormEmpresa({ ...formEmpresa, logradouro: e.target.value })}
                                    />
                                </div>
                            </div>

                            <div className="grid md:grid-cols-3 gap-4 mb-4">
                                <div><Label>Número</Label><Input value={formEmpresa.numero || ""} onChange={(e) => setFormEmpresa({ ...formEmpresa, numero: e.target.value })} /></div>
                                <div className="md:col-span-2"><Label>Complemento</Label><Input value={formEmpresa.complemento || ""} onChange={(e) => setFormEmpresa({ ...formEmpresa, complemento: e.target.value })} /></div>
                            </div>

                            <div className="grid md:grid-cols-3 gap-4">
                                <div><Label>Bairro</Label><Input value={formEmpresa.bairro || ""} onChange={(e) => setFormEmpresa({ ...formEmpresa, bairro: e.target.value })} /></div>
                                <div><Label>Município *</Label><Input value={formEmpresa.municipio || ""} onChange={(e) => setFormEmpresa({ ...formEmpresa, municipio: e.target.value })} /></div>
                                <div>
                                    <Label>UF *</Label>
                                    <Select value={formEmpresa.uf || "ES"} onValueChange={(v) => setFormEmpresa({ ...formEmpresa, uf: v })}>
                                        <SelectTrigger><SelectValue /></SelectTrigger>
                                        <SelectContent>
                                            {["AC", "AL", "AP", "AM", "BA", "CE", "DF", "ES", "GO", "MA", "MT", "MS", "MG", "PA", "PB", "PR", "PE", "PI", "RJ", "RN", "RS", "RO", "RR", "SC", "SP", "SE", "TO"].map(uf => (
                                                <SelectItem key={uf} value={uf}>{uf}</SelectItem>
                                            ))}
                                        </SelectContent>
                                    </Select>
                                </div>
                            </div>
                        </div>
                    </div>

                    <DialogFooter className="border-t pt-4">
                        <Button variant="ghost" onClick={() => setEditandoEmpresa(null)}>Cancelar</Button>
                        <Button onClick={salvarDadosEmpresa} disabled={savingDb} className="bg-green-700 hover:bg-green-800">
                            {savingDb ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Save className="w-4 h-4 mr-2" />}
                            Salvar Dados Fiscais
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            <Dialog open={certDialogOpen} onOpenChange={setCertDialogOpen}>
                <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
                    <DialogHeader>
                        <DialogTitle>Cadastro de Certificado A1 (ACBR API)</DialogTitle>
                        <DialogDescription>
                            Revise os dados da empresa, anexe o arquivo .pfx/.p12 e informe a senha do certificado.
                        </DialogDescription>
                    </DialogHeader>

                    <div className="space-y-4 py-2">
                        <Alert className="bg-amber-50 border-amber-200">
                            <AlertCircle className="h-4 w-4 text-amber-600" />
                            <AlertDescription className="text-amber-800">
                                Apenas certificados A1 (.pfx ou .p12) são suportados.
                            </AlertDescription>
                        </Alert>

                        <div className="grid md:grid-cols-2 gap-4">
                            <div>
                                <Label>CNPJ *</Label>
                                <Input value={certForm.cnpj} onChange={(e) => setCertForm(prev => ({ ...prev, cnpj: e.target.value }))} placeholder="Somente números" />
                            </div>
                            <div>
                                <Label>Razão Social *</Label>
                                <Input value={certForm.nome_razao_social} onChange={(e) => setCertForm(prev => ({ ...prev, nome_razao_social: e.target.value }))} />
                            </div>
                        </div>

                        <div>
                            <Label>Email *</Label>
                            <Input type="email" value={certForm.email} onChange={(e) => setCertForm(prev => ({ ...prev, email: e.target.value }))} />
                        </div>

                        <div className="grid md:grid-cols-3 gap-4">
                            <div><Label>CEP *</Label><Input value={certForm.cep} onChange={(e) => setCertForm(prev => ({ ...prev, cep: e.target.value }))} /></div>
                            <div className="md:col-span-2"><Label>Logradouro *</Label><Input value={certForm.logradouro} onChange={(e) => setCertForm(prev => ({ ...prev, logradouro: e.target.value }))} /></div>
                        </div>

                        <div className="grid md:grid-cols-3 gap-4">
                            <div><Label>Número *</Label><Input value={certForm.numero} onChange={(e) => setCertForm(prev => ({ ...prev, numero: e.target.value }))} /></div>
                            <div><Label>Complemento</Label><Input value={certForm.complemento} onChange={(e) => setCertForm(prev => ({ ...prev, complemento: e.target.value }))} /></div>
                            <div><Label>Bairro *</Label><Input value={certForm.bairro} onChange={(e) => setCertForm(prev => ({ ...prev, bairro: e.target.value }))} /></div>
                        </div>

                        <div className="grid md:grid-cols-3 gap-4">
                            <div><Label>Cidade *</Label><Input value={certForm.cidade} onChange={(e) => setCertForm(prev => ({ ...prev, cidade: e.target.value }))} /></div>
                            <div>
                                <Label>UF *</Label>
                                <Select value={certForm.uf} onValueChange={(v) => setCertForm(prev => ({ ...prev, uf: v }))}>
                                    <SelectTrigger><SelectValue /></SelectTrigger>
                                    <SelectContent>
                                        {["AC", "AL", "AP", "AM", "BA", "CE", "DF", "ES", "GO", "MA", "MT", "MS", "MG", "PA", "PB", "PR", "PE", "PI", "RJ", "RN", "RS", "RO", "RR", "SC", "SP", "SE", "TO"].map(uf => (
                                            <SelectItem key={uf} value={uf}>{uf}</SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                            </div>
                            <div><Label>Código Município IBGE *</Label><Input value={certForm.codigo_municipio} onChange={(e) => setCertForm(prev => ({ ...prev, codigo_municipio: e.target.value }))} /></div>
                        </div>

                        <div>
                            <Label>Certificado A1 (.pfx/.p12) *</Label>
                            <Input type="file" accept=".pfx,.p12" onChange={(e) => setCertFile(e.target.files?.[0] || null)} />
                        </div>

                        <div>
                            <Label>Senha do Certificado *</Label>
                            <Input type="password" value={certPassword} onChange={(e) => setCertPassword(e.target.value)} />
                        </div>
                    </div>

                    <DialogFooter>
                        <Button variant="ghost" onClick={() => setCertDialogOpen(false)}>Cancelar</Button>
                        <Button onClick={handleRegistrarCertificado} disabled={savingCert} className="bg-indigo-700 hover:bg-indigo-800">
                            {savingCert ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Save className="w-4 h-4 mr-2" />}
                            Registrar Certificado
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
}

import React, { useState, useEffect } from "react";
import { base44 } from "@/api/base44Client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { CreditCard, Save, Loader2, CheckCircle, AlertCircle, Eye, EyeOff, ExternalLink } from "lucide-react";
import { toast } from "sonner";

export default function ConfiguracaoPagSeguro() {
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [showToken, setShowToken] = useState(false);
    const [config, setConfig] = useState({
        pagseguro_token: "",
        pagseguro_email: "",
        pagseguro_ambiente: "sandbox"
    });
    const [originalConfig, setOriginalConfig] = useState(null);

    useEffect(() => {
        loadConfig();
    }, []);

    const loadConfig = async () => {
        try {
            const configs = await base44.entities.ConfiguracaoSistema.list();
            const configMap = {};
            configs.forEach(c => {
                if (c?.chave?.startsWith('pagseguro_')) {
                    configMap[c.chave] = c.valor || "";
                }
            });
            setConfig(prev => ({ ...prev, ...configMap }));
            setOriginalConfig(configMap);
        } catch (error) {
            console.error("Erro ao carregar configurações:", error);
            toast.error("Erro ao carregar configurações do PagSeguro");
        } finally {
            setLoading(false);
        }
    };

    const handleSave = async () => {
        setSaving(true);
        try {
            // Get existing configs to know their IDs
            const existingConfigs = await base44.entities.ConfiguracaoSistema.list();

            for (const [chave, valor] of Object.entries(config)) {
                const existing = existingConfigs.find(c => c.chave === chave);
                if (existing) {
                    await base44.entities.ConfiguracaoSistema.update(existing.id, { valor, updated_at: new Date().toISOString() });
                } else {
                    await base44.entities.ConfiguracaoSistema.create({ chave, valor });
                }
            }

            setOriginalConfig({ ...config });
            toast.success("Configurações salvas com sucesso!");
        } catch (error) {
            console.error("Erro ao salvar:", error);
            toast.error("Erro ao salvar configurações");
        } finally {
            setSaving(false);
        }
    };

    const hasChanges = JSON.stringify(config) !== JSON.stringify(originalConfig);
    const isConfigured = config.pagseguro_token && config.pagseguro_email;

    if (loading) {
        return (
            <div className="flex items-center justify-center py-12">
                <Loader2 className="w-8 h-8 animate-spin text-green-600" />
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-xl font-bold text-gray-900">PagSeguro / PagBank</h2>
                    <p className="text-sm text-gray-500 mt-1">
                        Configure suas credenciais para gerar links de pagamento
                    </p>
                </div>
                <Badge variant={isConfigured ? "default" : "secondary"} className={isConfigured ? "bg-green-100 text-green-800" : ""}>
                    {isConfigured ? (
                        <><CheckCircle className="w-3 h-3 mr-1" /> Configurado</>
                    ) : (
                        <><AlertCircle className="w-3 h-3 mr-1" /> Não Configurado</>
                    )}
                </Badge>
            </div>

            <Card>
                <CardHeader>
                    <CardTitle className="text-base flex items-center gap-2">
                        <CreditCard className="w-5 h-5 text-orange-500" />
                        Credenciais da API
                    </CardTitle>
                    <CardDescription>
                        Obtenha suas credenciais no painel do PagBank Developers
                    </CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                    <div className="space-y-2">
                        <Label htmlFor="ambiente">Ambiente</Label>
                        <Select
                            value={config.pagseguro_ambiente}
                            onValueChange={(v) => setConfig({ ...config, pagseguro_ambiente: v })}
                        >
                            <SelectTrigger>
                                <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="sandbox">
                                    <div className="flex items-center gap-2">
                                        <span className="w-2 h-2 rounded-full bg-yellow-500" />
                                        Sandbox (Testes)
                                    </div>
                                </SelectItem>
                                <SelectItem value="production">
                                    <div className="flex items-center gap-2">
                                        <span className="w-2 h-2 rounded-full bg-green-500" />
                                        Produção (Real)
                                    </div>
                                </SelectItem>
                            </SelectContent>
                        </Select>
                        <p className="text-xs text-amber-600">
                            {config.pagseguro_ambiente === 'sandbox'
                                ? "⚠️ Modo de testes - pagamentos não são reais"
                                : "✅ Modo produção - pagamentos reais serão processados"
                            }
                        </p>
                    </div>

                    <div className="space-y-2">
                        <Label htmlFor="email">Email da Conta PagBank</Label>
                        <Input
                            id="email"
                            type="email"
                            placeholder="seu-email@empresa.com"
                            value={config.pagseguro_email}
                            onChange={(e) => setConfig({ ...config, pagseguro_email: e.target.value })}
                        />
                    </div>

                    <div className="space-y-2">
                        <Label htmlFor="token">Token de Acesso (Bearer Token)</Label>
                        <div className="relative">
                            <Input
                                id="token"
                                type={showToken ? "text" : "password"}
                                placeholder="Seu token de autenticação"
                                value={config.pagseguro_token}
                                onChange={(e) => setConfig({ ...config, pagseguro_token: e.target.value })}
                                className="pr-10 font-mono text-sm"
                            />
                            <button
                                type="button"
                                onClick={() => setShowToken(!showToken)}
                                className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                            >
                                {showToken ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                            </button>
                        </div>
                        <p className="text-xs text-gray-500">
                            O token é armazenado de forma segura e só é acessado pelo servidor
                        </p>
                    </div>

                    <Alert className="border-blue-200 bg-blue-50">
                        <ExternalLink className="w-4 h-4 text-blue-600" />
                        <AlertDescription className="text-blue-800">
                            <strong>Como obter suas credenciais:</strong>
                            <ol className="list-decimal ml-4 mt-1 text-sm space-y-1">
                                <li>Acesse <a href="https://dev.pagbank.uol.com.br" target="_blank" rel="noopener noreferrer" className="underline">dev.pagbank.uol.com.br</a></li>
                                <li>Faça login com sua conta PagBank</li>
                                <li>Vá em &quot;Credenciais&quot; no menu</li>
                                <li>Copie o Token de Sandbox ou Produção</li>
                            </ol>
                        </AlertDescription>
                    </Alert>

                    <div className="flex justify-end pt-4 border-t">
                        <Button
                            onClick={handleSave}
                            disabled={saving || !hasChanges}
                            className="bg-green-600 hover:bg-green-700"
                        >
                            {saving ? (
                                <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Salvando...</>
                            ) : (
                                <><Save className="w-4 h-4 mr-2" /> Salvar Configurações</>
                            )}
                        </Button>
                    </div>
                </CardContent>
            </Card>

            {isConfigured && (
                <Card className="border-green-200 bg-green-50">
                    <CardContent className="pt-6">
                        <div className="flex items-start gap-3">
                            <CheckCircle className="w-5 h-5 text-green-600 mt-0.5" />
                            <div>
                                <p className="font-medium text-green-800">Integração Configurada</p>
                                <p className="text-sm text-green-700 mt-1">
                                    Você pode gerar links de pagamento diretamente do PDV após finalizar uma venda.
                                </p>
                            </div>
                        </div>
                    </CardContent>
                </Card>
            )}
        </div>
    );
}

import React, { useState, useEffect } from "react";
import { supabase } from "@/lib/supabase";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { toast } from "sonner";
import { Loader2, Save, Truck, Plus, Trash2 } from "lucide-react";

export default function ConfiguracaoPrazos() {
    const [prazos, setPrazos] = useState([]);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [novoPrazoModalOpen, setNovoPrazoModalOpen] = useState(false);
    const [novoPrazoData, setNovoPrazoData] = useState({
        titulo: "",
        quantidade_dias: "",
        tipo_dias: "uteis"
    });
    const [creating, setCreating] = useState(false);

    useEffect(() => {
        fetchPrazos();
    }, []);

    const fetchPrazos = async () => {
        try {
            setLoading(true);
            const { data, error } = await supabase
                .from("prazos_entrega")
                .select("*")
                .order("identificador");

            if (error) throw error;
            setPrazos(data || []);
        } catch (err) {
            console.error("Erro ao carregar prazos:", err);
            toast.error("Erro ao carregar configurações de prazos");
        } finally {
            setLoading(false);
        }
    };

    const handleUpdatePrazo = (id, field, value) => {
        setPrazos(prev => prev.map(p =>
            p.id === id ? { ...p, [field]: value } : p
        ));
    };

    const handleSave = async (prazo) => {
        try {
            setSaving(prazo.id);
            const { error } = await supabase
                .from("prazos_entrega")
                .update({
                    titulo: prazo.titulo,
                    quantidade_dias: parseInt(prazo.quantidade_dias),
                    tipo_dias: prazo.tipo_dias,
                    updated_at: new Date().toISOString()
                })
                .eq("id", prazo.id);

            if (error) throw error;
            toast.success(`${prazo.titulo} atualizado com sucesso!`);
        } catch (err) {
            console.error("Erro ao salvar prazo:", err);
            toast.error("Erro ao salvar configurações");
        } finally {
            setSaving(false);
        }
    };

    const handleCreatePrazo = async () => {
        if (!novoPrazoData.titulo.trim()) {
            toast.error("O título é obrigatório");
            return;
        }
        if (!novoPrazoData.quantidade_dias || parseInt(novoPrazoData.quantidade_dias) <= 0) {
            toast.error("A quantidade de dias deve ser maior que 0");
            return;
        }

        try {
            setCreating(true);
            const slug = novoPrazoData.titulo
                .toLowerCase()
                .normalize("NFD")
                .replace(/[\u0300-\u036f]/g, "")
                .replace(/[^a-z0-9]+/g, "_")
                .replace(/(^_+|_+$)/g, "");
            
            const identificador = `${slug}_${Math.random().toString(36).substring(2, 7)}`;

            const { error } = await supabase
                .from("prazos_entrega")
                .insert({
                    identificador,
                    titulo: novoPrazoData.titulo,
                    quantidade_dias: parseInt(novoPrazoData.quantidade_dias),
                    tipo_dias: novoPrazoData.tipo_dias
                });

            if (error) throw error;

            toast.success("Novo prazo de entrega criado com sucesso!");
            setNovoPrazoModalOpen(false);
            setNovoPrazoData({ titulo: "", quantidade_dias: "", tipo_dias: "uteis" });
            fetchPrazos();
        } catch (err) {
            console.error("Erro ao criar prazo:", err);
            toast.error("Erro ao criar prazo de entrega");
        } finally {
            setCreating(false);
        }
    };

    const handleDelete = async (id, titulo) => {
        if (!window.confirm(`Tem certeza que deseja excluir o prazo "${titulo}"?`)) {
            return;
        }

        try {
            const { error } = await supabase
                .from("prazos_entrega")
                .delete()
                .eq("id", id);
            if (error) throw error;
            toast.success(`Prazo "${titulo}" excluído com sucesso!`);
            fetchPrazos();
        } catch (err) {
            console.error("Erro ao excluir prazo:", err);
            toast.error("Erro ao excluir o prazo");
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center p-12">
                <Loader2 className="w-8 h-8 animate-spin text-green-600" />
            </div>
        );
    }
    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-2xl font-bold tracking-tight">Prazos de Entrega</h2>
                    <p className="text-muted-foreground">
                        Configure os prazos que aparecem no PDV e como eles são calculados.
                    </p>
                </div>
                <Button onClick={() => setNovoPrazoModalOpen(true)} className="bg-green-600 hover:bg-green-700">
                    <Plus className="w-4 h-4 mr-2" />
                    Novo Prazo
                </Button>
            </div>

            <div className="grid gap-6 md:grid-cols-2">
                {prazos.map((prazo) => (
                    <Card key={prazo.id}>
                        <CardHeader>
                            <div className="flex items-center justify-between">
                                <div className="flex items-center gap-2">
                                    <Truck className="w-5 h-5 text-green-600" />
                                    <CardTitle>{prazo.titulo}</CardTitle>
                                </div>
                                {prazo.identificador !== "pronta_entrega" && prazo.identificador !== "encomenda" && (
                                    <Button
                                        variant="ghost"
                                        size="icon"
                                        className="text-red-500 hover:text-red-700 hover:bg-red-50 h-8 w-8"
                                        onClick={() => handleDelete(prazo.id, prazo.titulo)}
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </Button>
                                )}
                            </div>
                            <CardDescription>
                                Configuração para o identificador: {prazo.identificador}
                            </CardDescription>
                        </CardHeader>
                        <CardContent className="space-y-4">
                            <div className="space-y-2">
                                <Label>Título Exibido no PDV</Label>
                                <Input
                                    value={prazo.titulo}
                                    onChange={(e) => handleUpdatePrazo(prazo.id, 'titulo', e.target.value)}
                                />
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <Label>Quantidade de Dias</Label>
                                    <Input
                                        type="number"
                                        value={prazo.quantidade_dias}
                                        onChange={(e) => handleUpdatePrazo(prazo.id, 'quantidade_dias', e.target.value)}
                                    />
                                </div>
                                <div className="space-y-2">
                                    <Label>Tipo de Dias</Label>
                                    <Select
                                        value={prazo.tipo_dias}
                                        onValueChange={(v) => handleUpdatePrazo(prazo.id, 'tipo_dias', v)}
                                    >
                                        <SelectTrigger>
                                            <SelectValue />
                                        </SelectTrigger>
                                        <SelectContent>
                                            <SelectItem value="uteis">Dias Úteis</SelectItem>
                                            <SelectItem value="corridos">Dias Corridos</SelectItem>
                                        </SelectContent>
                                    </Select>
                                </div>
                            </div>

                            <Button
                                className="w-full bg-green-600 hover:bg-green-700"
                                onClick={() => handleSave(prazo)}
                                disabled={saving === prazo.id}
                            >
                                {saving === prazo.id ? (
                                    <Loader2 className="w-4 h-4 animate-spin mr-2" />
                                ) : (
                                    <Save className="w-4 h-4 mr-2" />
                                )}
                                Salvar Alterações
                            </Button>
                        </CardContent>
                    </Card>
                ))}
            </div>

            <Dialog open={novoPrazoModalOpen} onOpenChange={setNovoPrazoModalOpen}>
                <DialogContent>
                    <DialogHeader>
                        <DialogTitle>Adicionar Novo Prazo de Entrega</DialogTitle>
                        <DialogDescription>
                            Cadastre um novo prazo para ser utilizado nas vendas e entregas.
                        </DialogDescription>
                    </DialogHeader>
                    <div className="space-y-4 py-4">
                        <div className="space-y-2">
                            <Label htmlFor="novo-titulo">Título Exibido no PDV</Label>
                            <Input
                                id="novo-titulo"
                                placeholder="Ex: Prazo Especial, 30 dias úteis"
                                value={novoPrazoData.titulo}
                                onChange={(e) => setNovoPrazoData({ ...novoPrazoData, titulo: e.target.value })}
                            />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <Label htmlFor="novo-dias">Quantidade de Dias</Label>
                                <Input
                                    id="novo-dias"
                                    type="number"
                                    placeholder="Ex: 30"
                                    value={novoPrazoData.quantidade_dias}
                                    onChange={(e) => setNovoPrazoData({ ...novoPrazoData, quantidade_dias: e.target.value })}
                                />
                            </div>
                            <div className="space-y-2">
                                <Label htmlFor="novo-tipo">Tipo de Dias</Label>
                                <Select
                                    value={novoPrazoData.tipo_dias}
                                    onValueChange={(v) => setNovoPrazoData({ ...novoPrazoData, tipo_dias: v })}
                                >
                                    <SelectTrigger id="novo-tipo">
                                        <SelectValue placeholder="Selecione..." />
                                    </SelectTrigger>
                                    <SelectContent>
                                        <SelectItem value="uteis">Dias Úteis</SelectItem>
                                        <SelectItem value="corridos">Dias Corridos</SelectItem>
                                    </SelectContent>
                                </Select>
                            </div>
                        </div>
                    </div>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setNovoPrazoModalOpen(false)}>
                            Cancelar
                        </Button>
                        <Button
                            className="bg-green-600 hover:bg-green-700"
                            onClick={handleCreatePrazo}
                            disabled={creating}
                        >
                            {creating ? (
                                <Loader2 className="w-4 h-4 animate-spin mr-2" />
                            ) : (
                                <Plus className="w-4 h-4 mr-2" />
                            )}
                            Criar Prazo
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
}

import React, { useState } from "react";
import { base44 } from "@/lib/supabase";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { DollarSign, Package, TrendingUp, Loader2 } from "lucide-react";
import AjustePrecoModal from "./AjustePrecoModal";
import { useAuth } from "@/hooks/useAuth";

export default function ConfiguracaoPrecificacao() {
    const [isModalOpen, setIsModalOpen] = useState(false);
    const { can } = useAuth();

    const canManageBulkPrice = can('manage_bulk_price_adjustment');

    const { data: produtos = [], isLoading } = useQuery({
        queryKey: ['produtos'],
        queryFn: () => base44.entities.Produto.list('nome'),
    });

    const totalProdutos = produtos.length;
    const precoMedio = produtos.length > 0
        ? produtos.reduce((acc, p) => acc + (p.preco_venda || 0), 0) / produtos.length
        : 0;

    return (
        <div className="space-y-6">
            {/* Header */}
            <Card className="border-0 shadow-lg">
                <CardHeader className="pb-3">
                    <CardTitle className="flex items-center gap-2" style={{ color: '#07593f' }}>
                        <DollarSign className="w-6 h-6" />
                        Precificação
                    </CardTitle>
                </CardHeader>
                <CardContent>
                    <p className="text-gray-500 mb-6">
                        Ajuste preço de venda ou custo tabela com filtros avançados, exceções e simulação obrigatória.
                    </p>

                    {/* Stats */}
                    <div className="grid md:grid-cols-2 gap-4 mb-6">
                        <div className="flex items-center gap-4 p-4 bg-gray-50 rounded-xl">
                            <div className="p-3 rounded-lg bg-green-100">
                                <Package className="w-6 h-6 text-green-700" />
                            </div>
                            <div>
                                <p className="text-2xl font-bold" style={{ color: '#07593f' }}>
                                    {isLoading ? <Loader2 className="w-5 h-5 animate-spin" /> : totalProdutos}
                                </p>
                                <p className="text-sm text-gray-500">Produtos cadastrados</p>
                            </div>
                        </div>

                        <div className="flex items-center gap-4 p-4 bg-gray-50 rounded-xl">
                            <div className="p-3 rounded-lg bg-blue-100">
                                <TrendingUp className="w-6 h-6 text-blue-700" />
                            </div>
                            <div>
                                <p className="text-2xl font-bold text-blue-600">
                                    {isLoading ? <Loader2 className="w-5 h-5 animate-spin" /> : `R$ ${precoMedio.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`}
                                </p>
                                <p className="text-sm text-gray-500">Preço médio de venda</p>
                            </div>
                        </div>
                    </div>

                    {/* Botao */}
                    <Button
                        onClick={() => setIsModalOpen(true)}
                        size="lg"
                        disabled={!canManageBulkPrice}
                        className="w-full h-14 bg-green-700 hover:bg-green-800 text-lg"
                    >
                        <DollarSign className="w-5 h-5 mr-2" />
                        Ajustar Preços em Massa
                    </Button>
                    {!canManageBulkPrice && (
                        <p className="text-xs text-amber-700 mt-2">
                            Apenas Administrador e Gerente Geral podem executar reajuste em massa.
                        </p>
                    )}
                </CardContent>
            </Card>

            {/* Modal */}
            <AjustePrecoModal
                isOpen={isModalOpen}
                onClose={() => setIsModalOpen(false)}
                produtos={produtos}
            />
        </div>
    );
}

import React, { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
    CreditCard, Save, Loader2, CheckCircle, AlertCircle,
    Eye, EyeOff, Key, Link2, Copy, RefreshCw, Webhook,
    TestTube, Building2, Shield, ExternalLink
} from "lucide-react";
import { toast } from "sonner";
import { supabase } from "@/api/base44Client";
import { supabaseUrl } from "@/lib/supabase";

export default function ConfiguracaoStone() {
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [testing, setTesting] = useState(false);
    const [showClientSecret, setShowClientSecret] = useState(false);
    const [showWebhookSecret, setShowWebhookSecret] = useState(false);

    const [config, setConfig] = useState({
        environment: 'sandbox',
        client_id: '',
        client_secret: '',
        account_id: '',
        webhook_secret: '',
        is_active: true
    });
    const [originalConfig, setOriginalConfig] = useState(null);
    const [connectionStatus, setConnectionStatus] = useState(null); // null | 'success' | 'error'
    const [connectionMessage, setConnectionMessage] = useState('');

    // URLs baseadas no ambiente
    const getApiBaseUrl = () => {
        return config.environment === 'production'
            ? 'https://api.openbank.stone.com.br'
            : 'https://sandbox-api.openbank.stone.com.br';
    };

    const getAuthUrl = () => {
        return config.environment === 'production'
            ? 'https://login.stone.com.br'
            : 'https://login.sandbox.stone.com.br';
    };

    // Webhook URL para configurar na Stone (Supabase Edge Function)
    const webhookUrl = `${supabaseUrl}/functions/v1/stone-payment-link/webhook`;

    useEffect(() => {
        loadConfig();
    }, []);

    const loadConfig = async () => {
        try {
            const { data, error } = await supabase
                .from('stone_config')
                .select('*')
                .order('created_at', { ascending: false })
                .limit(1)
                .single();

            if (data) {
                setConfig({
                    environment: data.environment || 'sandbox',
                    client_id: data.client_id || '',
                    client_secret: data.client_secret || '',
                    account_id: data.account_id || '',
                    webhook_secret: data.webhook_secret || '',
                    is_active: data.is_active ?? true
                });
                setOriginalConfig(data);
            }
        } catch (error) {
            // Tabela vazia ou não existe ainda - usar valores padrão
            console.log('Configuração Stone não encontrada, usando padrões');
        } finally {
            setLoading(false);
        }
    };

    const handleSave = async () => {
        if (!config.client_id || !config.client_secret) {
            toast.error("Client ID e Client Secret são obrigatórios");
            return;
        }

        setSaving(true);
        try {
            const payload = {
                environment: config.environment,
                client_id: config.client_id,
                client_secret: config.client_secret,
                account_id: config.account_id || null,
                webhook_secret: config.webhook_secret || null,
                is_active: config.is_active,
                updated_at: new Date().toISOString()
            };

            // Upsert baseado no ambiente
            const { data, error } = await supabase
                .from('stone_config')
                .upsert(payload, {
                    onConflict: 'environment',
                    ignoreDuplicates: false
                })
                .select()
                .single();

            if (error) throw error;

            setOriginalConfig(data);
            toast.success("Configurações da Stone salvas!");
        } catch (error) {
            console.error('Erro ao salvar:', error);
            toast.error("Erro ao salvar configurações");
        } finally {
            setSaving(false);
        }
    };

    const handleTestConnection = async () => {
        if (!config.client_id || !config.client_secret) {
            toast.error("Preencha Client ID e Client Secret primeiro");
            return;
        }

        setTesting(true);
        setConnectionStatus(null);
        setConnectionMessage('');

        try {
            // Tentar obter token OAuth
            const authUrl = `${getAuthUrl()}/auth/realms/stone_bank/protocol/openid-connect/token`;

            const response = await fetch(authUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                body: new URLSearchParams({
                    grant_type: 'client_credentials',
                    client_id: config.client_id,
                    client_secret: config.client_secret
                })
            });

            if (response.ok) {
                const data = await response.json();
                setConnectionStatus('success');
                setConnectionMessage(`Token obtido! Expira em ${data.expires_in}s`);
                toast.success("Conexão com a Stone bem-sucedida!");
            } else {
                const errorData = await response.json();
                setConnectionStatus('error');
                setConnectionMessage(errorData.error_description || errorData.error || 'Credenciais inválidas');
                toast.error("Falha na autenticação");
            }
        } catch (error) {
            setConnectionStatus('error');
            setConnectionMessage(error.message || 'Erro de conexão');
            toast.error("Erro ao conectar com a Stone");
        } finally {
            setTesting(false);
        }
    };

    const copyToClipboard = (text) => {
        navigator.clipboard.writeText(text);
        toast.success("Copiado para área de transferência!");
    };

    const hasChanges = JSON.stringify(config) !== JSON.stringify(originalConfig);

    if (loading) {
        return (
            <div className="flex items-center justify-center py-12">
                <Loader2 className="w-8 h-8 animate-spin text-green-600" />
            </div>
        );
    }

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-xl font-bold text-gray-900 flex items-center gap-2">
                        <CreditCard className="w-6 h-6 text-green-600" />
                        Stone Pagamentos
                    </h2>
                    <p className="text-sm text-gray-500 mt-1">
                        Configure a integração com a Stone OpenBank para gerar links de pagamento
                    </p>
                </div>
                <Badge className={config.is_active ? "bg-green-100 text-green-800" : "bg-gray-100 text-gray-800"}>
                    {config.is_active ? "Ativo" : "Inativo"}
                </Badge>
            </div>

            {/* Ambiente */}
            <Card>
                <CardHeader>
                    <CardTitle className="text-base flex items-center gap-2">
                        <Building2 className="w-5 h-5" />
                        Ambiente
                    </CardTitle>
                    <CardDescription>
                        Selecione o ambiente de integração
                    </CardDescription>
                </CardHeader>
                <CardContent>
                    <Tabs value={config.environment} onValueChange={(v) => setConfig({ ...config, environment: v })}>
                        <TabsList className="grid w-full grid-cols-2">
                            <TabsTrigger value="sandbox" className="gap-2">
                                <TestTube className="w-4 h-4" />
                                Sandbox (Testes)
                            </TabsTrigger>
                            <TabsTrigger value="production" className="gap-2">
                                <Shield className="w-4 h-4" />
                                Produção
                            </TabsTrigger>
                        </TabsList>
                    </Tabs>

                    {config.environment === 'sandbox' && (
                        <Alert className="mt-4 border-blue-200 bg-blue-50">
                            <TestTube className="w-4 h-4 text-blue-600" />
                            <AlertDescription className="text-blue-800">
                                <strong>Ambiente de Testes</strong> - Nenhuma transação real será processada.
                                <a
                                    href="https://docs.openbank.stone.com.br/docs/referencia-da-api/"
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    className="ml-2 text-blue-600 hover:underline inline-flex items-center gap-1"
                                >
                                    Ver documentação <ExternalLink className="w-3 h-3" />
                                </a>
                            </AlertDescription>
                        </Alert>
                    )}

                    {config.environment === 'production' && (
                        <Alert className="mt-4 border-orange-200 bg-orange-50">
                            <Shield className="w-4 h-4 text-orange-600" />
                            <AlertDescription className="text-orange-800">
                                <strong>Ambiente de Produção</strong> - Transações reais serão processadas. Tenha cuidado!
                            </AlertDescription>
                        </Alert>
                    )}
                </CardContent>
            </Card>

            {/* Credenciais */}
            <Card>
                <CardHeader>
                    <CardTitle className="text-base flex items-center gap-2">
                        <Key className="w-5 h-5" />
                        Credenciais OAuth
                    </CardTitle>
                    <CardDescription>
                        Obtenha suas credenciais no painel da Stone OpenBank
                    </CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                    <div className="space-y-2">
                        <Label>Client ID</Label>
                        <Input
                            value={config.client_id}
                            onChange={(e) => setConfig({ ...config, client_id: e.target.value })}
                            placeholder="Seu Client ID da Stone"
                            className="font-mono text-sm"
                        />
                    </div>

                    <div className="space-y-2">
                        <Label>Client Secret</Label>
                        <div className="relative">
                            <Input
                                type={showClientSecret ? "text" : "password"}
                                value={config.client_secret}
                                onChange={(e) => setConfig({ ...config, client_secret: e.target.value })}
                                placeholder="Seu Client Secret da Stone"
                                className="pr-10 font-mono text-sm"
                            />
                            <button
                                type="button"
                                onClick={() => setShowClientSecret(!showClientSecret)}
                                className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                            >
                                {showClientSecret ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                            </button>
                        </div>
                    </div>

                    <div className="space-y-2">
                        <Label>Account ID (Opcional)</Label>
                        <Input
                            value={config.account_id}
                            onChange={(e) => setConfig({ ...config, account_id: e.target.value })}
                            placeholder="ID da conta Stone"
                            className="font-mono text-sm"
                        />
                        <p className="text-xs text-gray-500">Necessário para algumas operações avançadas</p>
                    </div>

                    {/* Testar Conexão */}
                    <div className="pt-4 border-t">
                        <Button
                            onClick={handleTestConnection}
                            disabled={testing || !config.client_id || !config.client_secret}
                            variant="outline"
                            className="w-full"
                        >
                            {testing ? (
                                <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Testando conexão...</>
                            ) : (
                                <><RefreshCw className="w-4 h-4 mr-2" /> Testar Conexão</>
                            )}
                        </Button>

                        {connectionStatus && (
                            <Alert className={`mt-3 ${connectionStatus === 'success' ? 'border-green-200 bg-green-50' : 'border-red-200 bg-red-50'}`}>
                                {connectionStatus === 'success' ? (
                                    <CheckCircle className="w-4 h-4 text-green-600" />
                                ) : (
                                    <AlertCircle className="w-4 h-4 text-red-600" />
                                )}
                                <AlertDescription className={connectionStatus === 'success' ? 'text-green-800' : 'text-red-800'}>
                                    {connectionMessage}
                                </AlertDescription>
                            </Alert>
                        )}
                    </div>
                </CardContent>
            </Card>

            {/* Webhook */}
            <Card>
                <CardHeader>
                    <CardTitle className="text-base flex items-center gap-2">
                        <Webhook className="w-5 h-5" />
                        Webhook de Notificações
                    </CardTitle>
                    <CardDescription>
                        Configure este URL na Stone para receber notificações de pagamento
                    </CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                    <div className="space-y-2">
                        <Label>URL do Webhook</Label>
                        <div className="flex gap-2">
                            <Input
                                value={webhookUrl}
                                readOnly
                                className="font-mono text-sm bg-gray-50"
                            />
                            <Button variant="outline" onClick={() => copyToClipboard(webhookUrl)}>
                                <Copy className="w-4 h-4" />
                            </Button>
                        </div>
                        <p className="text-xs text-gray-500">
                            Copie este URL e configure nas configurações de webhook do seu aplicativo Stone
                        </p>
                    </div>

                    <div className="space-y-2">
                        <Label>Webhook Secret (Opcional)</Label>
                        <div className="relative">
                            <Input
                                type={showWebhookSecret ? "text" : "password"}
                                value={config.webhook_secret}
                                onChange={(e) => setConfig({ ...config, webhook_secret: e.target.value })}
                                placeholder="Secret para validar webhooks"
                                className="pr-10 font-mono text-sm"
                            />
                            <button
                                type="button"
                                onClick={() => setShowWebhookSecret(!showWebhookSecret)}
                                className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                            >
                                {showWebhookSecret ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                            </button>
                        </div>
                        <p className="text-xs text-gray-500">
                            Usado para validar que as notificações vieram da Stone
                        </p>
                    </div>
                </CardContent>
            </Card>

            {/* Status e Salvar */}
            <Card>
                <CardContent className="pt-6">
                    <div className="flex items-center justify-between mb-4">
                        <div className="flex items-center gap-3">
                            <Switch
                                checked={config.is_active}
                                onCheckedChange={(v) => setConfig({ ...config, is_active: v })}
                            />
                            <div>
                                <Label className="font-medium">Integração Ativa</Label>
                                <p className="text-xs text-gray-500">
                                    Quando desativada, links de pagamento não serão gerados
                                </p>
                            </div>
                        </div>
                    </div>

                    <Button
                        onClick={handleSave}
                        disabled={saving || !hasChanges}
                        className="w-full bg-green-600 hover:bg-green-700"
                    >
                        {saving ? (
                            <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Salvando...</>
                        ) : (
                            <><Save className="w-4 h-4 mr-2" /> Salvar Configurações</>
                        )}
                    </Button>
                </CardContent>
            </Card>

            {/* Links úteis */}
            <div className="text-center text-sm text-gray-500">
                <a
                    href="https://docs.openbank.stone.com.br"
                    target="_blank"
                    rel="noopener noreferrer"
                    className="text-green-600 hover:underline inline-flex items-center gap-1"
                >
                    Documentação Stone OpenBank <ExternalLink className="w-3 h-3" />
                </a>
            </div>
        </div>
    );
}

import React, { useState, useMemo } from "react";
import { base44 } from "@/api/base44Client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Loader2, Percent, DollarSign, CreditCard, Save, AlertCircle, Banknote, Smartphone, FileText, TrendingDown, Plus, Link } from "lucide-react";
import { toast } from "sonner";

// Formas do sistema (nunca removíveis, sempre presentes na lista base do PDV)
const FORMAS_SISTEMA = new Set([
    "AFESP", "Boleto", "Crediário", "Crédito 1x", "Crédito Parcelado",
    "Débito", "Dinheiro", "Financiamento", "Link - Crédito", "Link - Débito",
    "Link - Pix", "Multicrédito", "Pix", "Transferência",
]);

// Cores fixas por forma de pagamento (case-insensitive matching)
const CORES_PAGAMENTO = {
    "dinheiro": { bg: "bg-green-50", border: "border-green-300", icon: "bg-green-100 text-green-700" },
    "pix": { bg: "bg-cyan-50", border: "border-cyan-300", icon: "bg-cyan-100 text-cyan-700" },
    "crédito 1x": { bg: "bg-purple-50", border: "border-purple-300", icon: "bg-purple-100 text-purple-700" },
    "crédito parcelado": { bg: "bg-violet-50", border: "border-violet-300", icon: "bg-violet-100 text-violet-700" },
    "débito": { bg: "bg-blue-50", border: "border-blue-300", icon: "bg-blue-100 text-blue-700" },
    "boleto": { bg: "bg-orange-50", border: "border-orange-300", icon: "bg-orange-100 text-orange-700" },
    "multicrédito": { bg: "bg-pink-50", border: "border-pink-300", icon: "bg-pink-100 text-pink-700" },
    "afesp": { bg: "bg-amber-50", border: "border-amber-300", icon: "bg-amber-100 text-amber-700" },
    "crediário": { bg: "bg-yellow-50", border: "border-yellow-300", icon: "bg-yellow-100 text-yellow-700" },
    "financiamento": { bg: "bg-indigo-50", border: "border-indigo-300", icon: "bg-indigo-100 text-indigo-700" },
    "transferência": { bg: "bg-teal-50", border: "border-teal-300", icon: "bg-teal-100 text-teal-700" },
    "cheque": { bg: "bg-slate-50", border: "border-slate-300", icon: "bg-slate-100 text-slate-700" },
};

const getCor = (forma) => {
    const formaLower = forma.toLowerCase().trim();
    // Match exato
    if (CORES_PAGAMENTO[formaLower]) return CORES_PAGAMENTO[formaLower];
    // Match parcial
    for (const [key, value] of Object.entries(CORES_PAGAMENTO)) {
        if (formaLower.includes(key) || key.includes(formaLower)) return value;
    }
    return { bg: "bg-gray-50", border: "border-gray-300", icon: "bg-gray-100 text-gray-600" };
};

const getIcone = (forma) => {
    const f = forma.toLowerCase();
    if (f.includes('crédito') || f.includes('credito')) return <CreditCard className="w-4 h-4" />;
    if (f.includes('débito') || f.includes('debito')) return <CreditCard className="w-4 h-4" />;
    if (f.includes('pix')) return <Smartphone className="w-4 h-4" />;
    if (f.includes('dinheiro')) return <Banknote className="w-4 h-4" />;
    if (f.includes('boleto')) return <FileText className="w-4 h-4" />;
    return <DollarSign className="w-4 h-4" />;
};

const isMissingDescontoVendedorColumnError = (err) => {
    const message = String(err?.message || '').toLowerCase();
    return message.includes('desconto_vendedor') && message.includes('schema cache');
};

export default function ConfiguracaoTaxas() {
    const queryClient = useQueryClient();
    const [editando, setEditando] = useState({});
    const [novaFormaAberta, setNovaFormaAberta] = useState(false);
    const [novaFormaData, setNovaFormaData] = useState({ forma_pagamento: "", descricao: "" });

    const { data: taxas = [], isLoading } = useQuery({
        queryKey: ['configuracao_taxas'],
        queryFn: () => base44.entities.ConfiguracaoTaxa.list()
    });

    // Ordenar alfabeticamente e manter posição fixa
    const taxasOrdenadas = useMemo(() => {
        return [...taxas].sort((a, b) => a.forma_pagamento.localeCompare(b.forma_pagamento, 'pt-BR'));
    }, [taxas]);

    const updateMutation = useMutation({
        mutationFn: async ({ id, data }) => {
            try {
                return await base44.entities.ConfiguracaoTaxa.update(id, data);
            } catch (err) {
                if (!isMissingDescontoVendedorColumnError(err)) throw err;

                const { desconto_vendedor, ...fallbackData } = data;
                return base44.entities.ConfiguracaoTaxa.update(id, fallbackData);
            }
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['configuracao_taxas'] });
            toast.success("Taxa atualizada com sucesso!");
        },
        onError: (err) => toast.error("Erro ao atualizar: " + err.message)
    });

    const createMutation = useMutation({
        mutationFn: (data) => base44.entities.ConfiguracaoTaxa.create(data),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['configuracao_taxas'] });
            toast.success("Forma de pagamento criada!");
            setNovaFormaAberta(false);
            setNovaFormaData({ forma_pagamento: "", descricao: "" });
        },
        onError: (err) => toast.error("Erro ao criar: " + err.message)
    });

    const handleCreateNovaForma = () => {
        const nome = novaFormaData.forma_pagamento.trim();
        if (!nome) { toast.error("Informe o nome da forma de pagamento."); return; }
        if (taxas.some(t => t.forma_pagamento.toLowerCase() === nome.toLowerCase())) {
            toast.error("Já existe uma forma com esse nome."); return;
        }
        createMutation.mutate({
            forma_pagamento: nome,
            descricao: novaFormaData.descricao.trim() || nome,
            tipo_taxa: "porcentagem",
            valor: 0,
            acrescimo: 0,
            acrescimo_tipo: "porcentagem",
            ativa: true,
        });
    };

    const handleEdit = (taxa) => {
        setEditando({
            ...editando,
            [taxa.id]: {
                tipo_taxa: taxa.tipo_taxa,
                valor: taxa.valor,
                ativa: taxa.ativa,
                acrescimo: taxa.acrescimo || 0,
                acrescimo_tipo: taxa.acrescimo_tipo || 'porcentagem',
                desconto_vendedor: taxa.desconto_vendedor ?? 0,
            }
        });
    };

    const handleSave = (taxa) => {
        const dados = editando[taxa.id];
        if (!dados) return;

        updateMutation.mutate({
            id: taxa.id,
            data: {
                tipo_taxa: dados.tipo_taxa,
                valor: parseFloat(dados.valor),
                ativa: dados.ativa,
                acrescimo: parseFloat(dados.acrescimo) || 0,
                acrescimo_tipo: dados.acrescimo_tipo || 'porcentagem',
                desconto_vendedor: parseFloat(dados.desconto_vendedor) || 0,
            }
        });

        setEditando(prev => {
            const novo = { ...prev };
            delete novo[taxa.id];
            return novo;
        });
    };

    const handleChange = (taxaId, campo, valor) => {
        setEditando(prev => ({
            ...prev,
            [taxaId]: {
                ...prev[taxaId],
                [campo]: valor
            }
        }));
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center py-12">
                <Loader2 className="w-6 h-6 animate-spin text-green-700" />
            </div>
        );
    }

    if (taxas.length === 0) {
        return (
            <Alert className="bg-yellow-50 border-yellow-200">
                <AlertCircle className="w-4 h-4 text-yellow-600" />
                <AlertDescription className="text-yellow-800">
                    Nenhuma taxa configurada. Execute o SQL de setup no Supabase para criar as taxas padrão.
                </AlertDescription>
            </Alert>
        );
    }

    return (
        <div className="space-y-4">
            <Card className="border-0 shadow-lg">
                <CardHeader className="pb-3">
                    <CardTitle className="flex items-center gap-2" style={{ color: '#07593f' }}>
                        <Percent className="w-6 h-6" />
                        Taxas por Forma de Pagamento
                    </CardTitle>
                </CardHeader>
                <CardContent>
                    <p className="text-gray-500 mb-2">
                        Configure as taxas de cada forma de pagamento.
                    </p>
                    <div className="flex flex-wrap gap-3 mb-6 text-xs">
                        <div className="flex items-center gap-2 bg-red-50 px-3 py-1.5 rounded-lg border border-red-100">
                            <DollarSign className="w-3.5 h-3.5 text-red-600" />
                            <span className="text-red-700"><strong>Taxa da Loja:</strong> Custo da loja por transação (lançado no financeiro)</span>
                        </div>
                        <div className="flex items-center gap-2 bg-blue-50 px-3 py-1.5 rounded-lg border border-blue-100">
                            <Percent className="w-3.5 h-3.5 text-blue-600" />
                            <span className="text-blue-700"><strong>Acréscimo ao Cliente:</strong> Valor extra cobrado do cliente no PDV</span>
                        </div>
                        <div className="flex items-center gap-2 bg-orange-50 px-3 py-1.5 rounded-lg border border-orange-100">
                            <TrendingDown className="w-3.5 h-3.5 text-orange-600" />
                            <span className="text-orange-700"><strong>Liq. Vendedor:</strong> Desconto na base de cálculo da comissão do vendedor</span>
                        </div>
                    </div>

                    <div className="flex justify-end mb-2">
                        <Button
                            variant="outline"
                            size="sm"
                            className="border-green-600 text-green-700 hover:bg-green-50"
                            onClick={() => setNovaFormaAberta(v => !v)}
                        >
                            <Plus className="w-4 h-4 mr-1" />
                            Nova Forma de Pagamento
                        </Button>
                    </div>

                    {novaFormaAberta && (
                        <Card className="border-2 border-dashed border-green-400 bg-green-50 mb-4">
                            <CardHeader className="pb-2">
                                <CardTitle className="text-sm font-bold text-green-700 flex items-center gap-2">
                                    <Plus className="w-4 h-4" /> Nova Forma de Pagamento
                                </CardTitle>
                                <p className="text-xs text-green-600">Formas criadas aqui aparecem automaticamente no PDV.</p>
                            </CardHeader>
                            <CardContent className="space-y-3">
                                <div>
                                    <Label className="text-xs font-semibold">Nome *</Label>
                                    <Input
                                        className="h-8 text-sm bg-white mt-1"
                                        placeholder="Ex: Vale Presente, Permuta..."
                                        value={novaFormaData.forma_pagamento}
                                        onChange={e => setNovaFormaData(d => ({ ...d, forma_pagamento: e.target.value }))}
                                    />
                                </div>
                                <div>
                                    <Label className="text-xs font-semibold">Descrição</Label>
                                    <Input
                                        className="h-8 text-sm bg-white mt-1"
                                        placeholder="Descrição curta (opcional)"
                                        value={novaFormaData.descricao}
                                        onChange={e => setNovaFormaData(d => ({ ...d, descricao: e.target.value }))}
                                    />
                                </div>
                                <div className="flex gap-2 pt-1">
                                    <Button
                                        size="sm"
                                        className="h-8 bg-green-600 hover:bg-green-700"
                                        onClick={handleCreateNovaForma}
                                        disabled={createMutation.isPending}
                                    >
                                        {createMutation.isPending ? <Loader2 className="w-3 h-3 animate-spin" /> : <Save className="w-3 h-3 mr-1" />}
                                        Criar
                                    </Button>
                                    <Button
                                        size="sm"
                                        variant="ghost"
                                        className="h-8"
                                        onClick={() => { setNovaFormaAberta(false); setNovaFormaData({ forma_pagamento: "", descricao: "" }); }}
                                    >
                                        Cancelar
                                    </Button>
                                </div>
                            </CardContent>
                        </Card>
                    )}

                    <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                        {taxasOrdenadas.map(taxa => {
                            const isEditing = editando[taxa.id];
                            const dados = isEditing || taxa;
                            const cores = getCor(taxa.forma_pagamento);

                            return (
                                <Card
                                    key={taxa.id}
                                    className={`${cores.bg} ${cores.border} border-2 transition-all ${!dados.ativa ? 'opacity-50 grayscale' : ''}`}
                                >
                                    <CardHeader className="pb-2">
                                        <div className="flex items-center justify-between">
                                            <div className="flex items-center gap-3">
                                                <div className={`w-10 h-10 rounded-xl ${cores.icon} flex items-center justify-center`}>
                                                    {getIcone(taxa.forma_pagamento)}
                                                </div>
                                                <div>
                                                    <CardTitle className="text-sm font-bold">{taxa.forma_pagamento}</CardTitle>
                                                    <p className="text-xs text-gray-500">{taxa.descricao}</p>
                                                </div>
                                            </div>
                                        </div>
                                    </CardHeader>
                                    <CardContent className="pt-0">
                                        {isEditing ? (
                                            <div className="space-y-3 pt-2">
                                                {/* Taxa Interna */}
                                                <div className="bg-red-50/50 p-2 rounded-lg border border-red-100">
                                                    <Label className="text-[10px] font-bold uppercase text-red-600 flex items-center gap-1">
                                                        <DollarSign className="w-3 h-3" /> Taxa Interna
                                                    </Label>
                                                    <div className="flex gap-2 mt-1">
                                                        <div className="flex-1">
                                                            <Select
                                                                value={dados.tipo_taxa}
                                                                onValueChange={(v) => handleChange(taxa.id, 'tipo_taxa', v)}
                                                            >
                                                                <SelectTrigger className="h-8 text-xs bg-white">
                                                                    <SelectValue />
                                                                </SelectTrigger>
                                                                <SelectContent>
                                                                    <SelectItem value="porcentagem">%</SelectItem>
                                                                    <SelectItem value="fixo">R$</SelectItem>
                                                                </SelectContent>
                                                            </Select>
                                                        </div>
                                                        <div className="w-20">
                                                            <Input
                                                                type="number"
                                                                step="0.01"
                                                                className="h-8 text-xs bg-white"
                                                                value={dados.valor}
                                                                onChange={(e) => handleChange(taxa.id, 'valor', e.target.value)}
                                                            />
                                                        </div>
                                                    </div>
                                                </div>

                                                {/* Acréscimo ao Cliente */}
                                                <div className="bg-blue-50/50 p-2 rounded-lg border border-blue-100">
                                                    <Label className="text-[10px] font-bold uppercase text-blue-600 flex items-center gap-1">
                                                        <Percent className="w-3 h-3" /> Acréscimo ao Cliente
                                                    </Label>
                                                    <div className="flex gap-2 mt-1">
                                                        <div className="flex-1">
                                                            <Select
                                                                value={dados.acrescimo_tipo || 'porcentagem'}
                                                                onValueChange={(v) => handleChange(taxa.id, 'acrescimo_tipo', v)}
                                                            >
                                                                <SelectTrigger className="h-8 text-xs bg-white">
                                                                    <SelectValue />
                                                                </SelectTrigger>
                                                                <SelectContent>
                                                                    <SelectItem value="porcentagem">%</SelectItem>
                                                                    <SelectItem value="fixo">R$</SelectItem>
                                                                </SelectContent>
                                                            </Select>
                                                        </div>
                                                        <div className="w-20">
                                                            <Input
                                                                type="number"
                                                                step="0.01"
                                                                className="h-8 text-xs bg-white"
                                                                value={dados.acrescimo || 0}
                                                                onChange={(e) => handleChange(taxa.id, 'acrescimo', e.target.value)}
                                                            />
                                                        </div>
                                                    </div>
                                                </div>

                                                {/* Desconto Líquido Vendedor */}
                                                <div className="bg-orange-50/50 p-2 rounded-lg border border-orange-100">
                                                    <Label className="text-[10px] font-bold uppercase text-orange-600 flex items-center gap-1">
                                                        <TrendingDown className="w-3 h-3" /> Desc. Líquido Vendedor
                                                    </Label>
                                                    <div className="flex gap-2 mt-1 items-center">
                                                        <div className="w-20">
                                                            <Input
                                                                type="number"
                                                                step="0.01"
                                                                min="0"
                                                                max="100"
                                                                className="h-8 text-xs bg-white"
                                                                value={dados.desconto_vendedor ?? 0}
                                                                onChange={(e) => handleChange(taxa.id, 'desconto_vendedor', e.target.value)}
                                                            />
                                                        </div>
                                                        <span className="text-xs text-orange-600 font-bold">%</span>
                                                    </div>
                                                </div>

                                                <div className="flex items-center justify-between pt-1">
                                                    <div className="flex items-center gap-2">
                                                        <Switch
                                                            checked={dados.ativa}
                                                            onCheckedChange={(v) => handleChange(taxa.id, 'ativa', v)}
                                                        />
                                                        <span className="text-xs font-medium">Ativa</span>
                                                    </div>
                                                    <Button
                                                        size="sm"
                                                        className="h-8 bg-green-600 hover:bg-green-700"
                                                        onClick={() => handleSave(taxa)}
                                                        disabled={updateMutation.isPending}
                                                    >
                                                        {updateMutation.isPending ? <Loader2 className="w-3 h-3 animate-spin" /> : <Save className="w-3 h-3 mr-1" />}
                                                        Salvar
                                                    </Button>
                                                </div>
                                            </div>
                                        ) : (
                                            <div className="pt-2 space-y-2">
                                                <div className="flex items-center justify-between">
                                                    <div className="flex items-center gap-3">
                                                        {/* Taxa */}
                                                        <div className="text-center">
                                                            <p className="text-[10px] uppercase text-red-500 font-medium">Taxa</p>
                                                            <span className="font-bold text-lg text-red-600">
                                                                {dados.tipo_taxa === 'porcentagem' ? `${dados.valor}%` : `R$ ${parseFloat(dados.valor).toFixed(2)}`}
                                                            </span>
                                                        </div>
                                                        <div className="h-8 w-px bg-gray-200" />
                                                        {/* Acréscimo */}
                                                        <div className="text-center">
                                                            <p className="text-[10px] uppercase text-blue-500 font-medium">Acréscimo</p>
                                                            <span className="font-bold text-lg text-blue-600">
                                                                {(dados.acrescimo_tipo || 'porcentagem') === 'porcentagem'
                                                                    ? `+${dados.acrescimo || 0}%`
                                                                    : `+R$ ${parseFloat(dados.acrescimo || 0).toFixed(2)}`}
                                                            </span>
                                                        </div>
                                                        <div className="h-8 w-px bg-gray-200" />
                                                        {/* Desconto Vendedor */}
                                                        <div className="text-center">
                                                            <p className="text-[10px] uppercase text-orange-500 font-medium">Liq. Vendedor</p>
                                                            <span className="font-bold text-lg text-orange-600">
                                                                -{dados.desconto_vendedor ?? 0}%
                                                            </span>
                                                        </div>
                                                    </div>
                                                    <div className="flex items-center gap-2">
                                                        {!dados.ativa && (
                                                            <Badge variant="secondary" className="text-xs">Inativa</Badge>
                                                        )}
                                                        <Button variant="outline" size="sm" className="h-8 bg-white" onClick={() => handleEdit(taxa)}>
                                                            Editar
                                                        </Button>
                                                    </div>
                                                </div>
                                            </div>
                                        )}
                                    </CardContent>
                                </Card>
                            );
                        })}
                    </div>
                </CardContent>
            </Card>

            <Alert className="bg-blue-50 border-blue-200">
                <AlertCircle className="w-4 h-4 text-blue-600" />
                <AlertDescription className="text-blue-800 text-sm">
                    <strong>Como funciona:</strong> Quando uma venda é finalizada, o sistema lança a <strong>Taxa da Loja</strong> no financeiro. O <strong>Acréscimo ao Cliente</strong> é aplicado no PDV ao valor cobrado. O <strong>Liq. Vendedor</strong> é configurado na aba Comissões e define a base de cálculo da comissão manual.
                </AlertDescription>
            </Alert>
        </div>
    );
}

