export default function ConfiguracaoWhatsAppBot() {
    const { brandName, organization } = useTenant();
    const currentOrgId = organization?.id || '00000000-0000-0000-0000-000000000001';

    const getBotHeaders = useCallback((extra = {}) => ({
        ...extra,
        ...(BOT_API_KEY ? { 'x-bot-api-key': BOT_API_KEY } : {}),
        'x-organization-id': currentOrgId,
    }), [currentOrgId]);

    const MESSAGE_TEMPLATES = useMemo(() => getMessageTemplates(brandName || "Nossa Empresa"), [brandName]);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [reconnecting, setReconnecting] = useState(false);
    const [disconnecting, setDisconnecting] = useState(false);
    const [activeTab, setActiveTab] = useState("conexao");

    // Estado da conexão WhatsApp
    const [connectionStatus, setConnectionStatus] = useState('initializing');
    const [qrCode, setQrCode] = useState(null);
    const [qrCodeImage, setQrCodeImage] = useState(null);
    const [connectionInfo, setConnectionInfo] = useState(null);

    // Templates de mensagens
    const [messageSettings, setMessageSettings] = useState({});
    const [originalMessageSettings, setOriginalMessageSettings] = useState({});

    // Modal de edição
    const [editingMessage, setEditingMessage] = useState(null);
    const [editingTemplate, setEditingTemplate] = useState("");
    const [editingEnabled, setEditingEnabled] = useState(true);

    // Expandidos (acordeões)
    const [expandedCategories, setExpandedCategories] = useState({});

    // Fila Offline & Modal de Pendências ao Conectar
    const [offlineQueue, setOfflineQueue] = useState([]);
    const [loadingQueue, setLoadingQueue] = useState(false);
    const [pendingModalOpen, setPendingModalOpen] = useState(false);
    const [pendingInfo, setPendingInfo] = useState({ totalCount: 0, localCount: 0, backendCount: 0, localItems: [], backendItems: [] });
    const [processingQueueAction, setProcessingQueueAction] = useState(false); // 'sending' | 'clearing' | false
    const prevStatusRef = useRef(null);
    const lastQrRef = useRef(null);

    const fetchOfflineQueue = useCallback(async () => {
        setLoadingQueue(true);
        try {
            const queue = await getOfflineQueue();
            setOfflineQueue(queue || []);
        } catch (e) {
            console.error("Erro ao carregar fila offline:", e);
        } finally {
            setLoadingQueue(false);
        }
    }, []);

    const handleRemoveQueueItem = async (id) => {
        await removeOfflineQueueItem(id);
        fetchOfflineQueue();
        toast.success("Ação cancelada e removida da fila");
    };

    const handleSendPendingNotifications = async () => {
        setProcessingQueueAction('sending');
        try {
            const result = await whatsappService.processAllPendingQueues();
            toast.success(`Disparo iniciado! ${result.sucessosLocal} notificações locais enviadas e processamento do servidor em andamento.`);
            setPendingModalOpen(false);
            fetchOfflineQueue();
        } catch (err) {
            console.error("Erro ao enviar pendências:", err);
            toast.error("Erro ao enviar notificações acumuladas.");
        } finally {
            setProcessingQueueAction(false);
        }
    };

    const handleClearPendingNotifications = async () => {
        setProcessingQueueAction('clearing');
        try {
            const result = await whatsappService.clearAllPendingQueues();
            const total = (pendingInfo.localCount || 0) + (result.backendCancelledCount || 0);
            toast.success(`${total} notificações acumuladas foram descartadas e não serão enviadas.`);
            setPendingModalOpen(false);
            fetchOfflineQueue();
        } catch (err) {
            console.error("Erro ao descartar pendências:", err);
            toast.error("Erro ao descartar notificações.");
        } finally {
            setProcessingQueueAction(false);
        }
    };

    // Polling de status do WhatsApp
    const fetchStatus = useCallback(async () => {
        try {
            const res = await fetch(`${WHATSAPP_BOT_URL}/whatsapp/status`, {
                headers: getBotHeaders(),
            });
            if (res.ok) {
                const data = await res.json();
                const prevStatus = prevStatusRef.current;
                prevStatusRef.current = data.status;

                setConnectionStatus(data.status);
                setQrCode(data.qr);
                setConnectionInfo(data.info);

                // 🔔 DETECÇÃO: WhatsApp acabou de conectar (após leitura de QR ou reconexão)
                if (data.status === 'connected' && prevStatus && prevStatus !== 'connected') {
                    console.log("📱 WhatsApp conectou! Verificando pendências acumuladas...");
                    whatsappService.getPendingQueueInfo().then(info => {
                        if (info.totalCount > 0) {
                            setPendingInfo(info);
                            setPendingModalOpen(true);
                        } else {
                            toast.success("WhatsApp conectado com sucesso!");
                        }
                    }).catch(() => {});
                }

                if (data.qr && data.qr !== lastQrRef.current) {
                    lastQrRef.current = data.qr;
                    const qrImg = await QRCode.toDataURL(data.qr, {
                        width: 280,
                        margin: 2,
                        color: { dark: '#000000', light: '#ffffff' }
                    });
                    setQrCodeImage(qrImg);
                } else if (!data.qr) {
                    lastQrRef.current = null;
                    setQrCodeImage(null);
                }
            }
        } catch (error) {
            prevStatusRef.current = 'offline';
            setConnectionStatus('offline');
        }
    }, [getBotHeaders]);

    // Carregar configurações de mensagens
    const loadSettings = useCallback(async () => {
        const templates = getMessageTemplates(brandName || "Nossa Empresa");
        try {
            const res = await fetch(`${WHATSAPP_BOT_URL}/whatsapp/ai-settings`, {
                headers: getBotHeaders(),
            });
            if (res.ok) {
                const data = await res.json();

                // Configurações de mensagens
                const msgSettings = {};
                Object.values(templates).forEach(category => {
                    category.messages.forEach(msg => {
                        msgSettings[msg.key] = {
                            enabled: data[`msg_${msg.key}_enabled`] ?? true,
                            template: data[`msg_${msg.key}_template`] ?? msg.defaultTemplate
                        };
                    });
                });
                setMessageSettings(msgSettings);
                setOriginalMessageSettings(JSON.parse(JSON.stringify(msgSettings)));
            }
        } catch (error) {
            console.error("Erro ao carregar configurações:", error);
            // Usar valores padrão
            const msgSettings = {};
            Object.values(templates).forEach(category => {
                category.messages.forEach(msg => {
                    msgSettings[msg.key] = {
                        enabled: true,
                        template: msg.defaultTemplate
                    };
                });
            });
            setMessageSettings(msgSettings);
            setOriginalMessageSettings(JSON.parse(JSON.stringify(msgSettings)));
        } finally {
            setLoading(false);
        }
    }, [brandName, getBotHeaders]);

    useEffect(() => {
        fetchStatus();
        loadSettings();
        fetchOfflineQueue();

        const handleOfflineQueueUpdated = () => {
            fetchOfflineQueue();
        };
        window.addEventListener('offline-queue-updated', handleOfflineQueueUpdated);

        const interval = setInterval(fetchStatus, 3000);
        return () => {
            clearInterval(interval);
            window.removeEventListener('offline-queue-updated', handleOfflineQueueUpdated);
        };
    }, [currentOrgId, fetchStatus, loadSettings, fetchOfflineQueue]);



    const handleSaveMessages = async () => {
        setSaving(true);
        try {
            // Converter messageSettings para formato do banco
            const payload = {};
            Object.entries(messageSettings).forEach(([key, value]) => {
                payload[`msg_${key}_enabled`] = value.enabled;
                payload[`msg_${key}_template`] = value.template;
            });

            const res = await fetch(`${WHATSAPP_BOT_URL}/whatsapp/ai-settings`, {
                method: 'POST',
                headers: getBotHeaders({ 'Content-Type': 'application/json' }),
                body: JSON.stringify(payload)
            });

            if (!res.ok) throw new Error('Falha ao salvar');

            setOriginalMessageSettings(JSON.parse(JSON.stringify(messageSettings)));
            toast.success("Templates de mensagens salvos!");
        } catch (error) {
            toast.error("Erro ao salvar mensagens");
        } finally {
            setSaving(false);
        }
    };

    const handleReconnect = async () => {
        setReconnecting(true);
        try {
            const res = await fetch(`${WHATSAPP_BOT_URL}/whatsapp/reconnect`, { method: 'POST', headers: getBotHeaders() });
            if (res.ok) {
                toast.success("Reconexão iniciada!");
                setTimeout(fetchStatus, 1000);
            }
        } catch (error) {
            toast.error("Erro ao reconectar");
        } finally {
            setReconnecting(false);
        }
    };

    const handleDisconnect = async () => {
        setDisconnecting(true);
        try {
            const res = await fetch(`${WHATSAPP_BOT_URL}/whatsapp/disconnect`, { method: 'POST', headers: getBotHeaders() });
            if (res.ok) {
                toast.success("Desconectado!");
                setTimeout(fetchStatus, 1000);
            }
        } catch (error) {
            toast.error("Erro ao desconectar");
        } finally {
            setDisconnecting(false);
        }
    };

    const openMessageEditor = (msg) => {
        setEditingMessage(msg);
        setEditingTemplate(messageSettings[msg.key]?.template || msg.defaultTemplate);
        setEditingEnabled(messageSettings[msg.key]?.enabled ?? true);
    };

    const saveMessageEdit = () => {
        setMessageSettings(prev => ({
            ...prev,
            [editingMessage.key]: {
                enabled: editingEnabled,
                template: editingTemplate
            }
        }));
        setEditingMessage(null);
        toast.success("Alterações aplicadas! Clique em 'Salvar Todas as Mensagens' para persistir.");
    };

    const insertVariable = (variable) => {
        setEditingTemplate(prev => prev + variable);
    };

    const toggleCategory = (cat) => {
        setExpandedCategories(prev => ({
            ...prev,
            [cat]: !prev[cat]
        }));
    };


    const hasMessageChanges = JSON.stringify(messageSettings) !== JSON.stringify(originalMessageSettings);

    const getStatusBadge = () => {
        const badges = {
            connected: { class: "bg-green-100 text-green-800", icon: Wifi, text: "Conectado Online" },
            waiting_qr: { class: "bg-yellow-100 text-yellow-800", icon: QrCode, text: "Escaneie o QR" },
            initializing: { class: "bg-blue-100 text-blue-800", icon: Loader2, text: "Iniciando..." },
            offline: { class: "bg-red-100 text-red-800", icon: WifiOff, text: "Servidor Offline" },
            disconnected: { class: "bg-gray-100 text-gray-800", icon: WifiOff, text: "Desconectado" }
        };
        const b = badges[connectionStatus] || badges.disconnected;
        const Icon = b.icon;
        return (
            <div className={`flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-medium border ${b.class} border-opacity-20`}>
                <Icon className={`w-3.5 h-3.5 ${connectionStatus === 'initializing' ? 'animate-spin' : ''}`} />
                {b.text}
            </div>
        );
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center py-12">
                <Loader2 className="w-8 h-8 animate-spin text-green-600" />
            </div>
        );
    }

    return (
        <div className="max-w-5xl mx-auto space-y-8">
            <div className="flex items-start justify-between">
                <div>
                    <h2 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
                        <Rocket className="w-8 h-8 text-green-600" />
                        Automação WhatsApp
                    </h2>
                    <p className="text-gray-500 mt-1">Configure o bot de atendimento, notificações automáticas e IA.</p>
                </div>
                {getStatusBadge()}
            </div>

            <Card className="border-t-4 border-t-green-600 shadow-sm overflow-hidden">
                <div className="border-b bg-gray-50/50 px-6 py-2">
                    <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
                        <TabsList className="bg-transparent h-auto p-0 gap-6 w-full justify-start">
                            <TabsTrigger
                                value="conexao"
                                className="data-[state=active]:bg-transparent data-[state=active]:shadow-none data-[state=active]:border-b-2 data-[state=active]:border-green-600 rounded-none px-2 py-3 text-gray-500 hover:text-green-700 data-[state=active]:text-green-700 font-medium transition-all"
                            >
                                <Wifi className="w-4 h-4 mr-2" /> Conexão
                            </TabsTrigger>
                            <TabsTrigger
                                value="mensagens"
                                className="data-[state=active]:bg-transparent data-[state=active]:shadow-none data-[state=active]:border-b-2 data-[state=active]:border-green-600 rounded-none px-2 py-3 text-gray-500 hover:text-green-700 data-[state=active]:text-green-700 font-medium transition-all"
                            >
                                <MessageCircle className="w-4 h-4 mr-2" /> Mensagens Automáticas
                            </TabsTrigger>


                            <TabsTrigger
                                value="fila_offline"
                                className="data-[state=active]:bg-transparent data-[state=active]:shadow-none data-[state=active]:border-b-2 data-[state=active]:border-green-600 rounded-none px-2 py-3 text-gray-500 hover:text-green-700 data-[state=active]:text-green-700 font-medium transition-all"
                            >
                                <CloudOff className="w-4 h-4 mr-2" /> Fila Offline
                            </TabsTrigger>
                        </TabsList>
                    </Tabs>
                </div>

                <CardContent className="p-6">
                    <Tabs value={activeTab} className="w-full">
                        {/* Tab Conexão */}
                        <TabsContent value="conexao" className="mt-0 space-y-6">
                            <div className="grid md:grid-cols-2 gap-8 items-start">
                                <div>
                                    <h3 className="text-lg font-semibold mb-2">Status do Dispositivo</h3>
                                    <p className="text-gray-500 text-sm mb-6">Escaneie o QR Code para conectar seu WhatsApp Business e começar a enviar mensagens automáticas.</p>

                                    {connectionStatus === 'connected' ? (
                                        <div className="bg-green-50 border border-green-100 rounded-xl p-6 mb-6">
                                            <div className="flex items-center gap-4">
                                                <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center shadow-sm text-green-600 border border-green-200">
                                                    <Smartphone className="w-8 h-8" />
                                                </div>
                                                <div>
                                                    <p className="text-sm font-medium text-green-600 uppercase tracking-wider">Dispositivo Conectado</p>
                                                    <p className="text-xl font-bold text-gray-900">{connectionInfo?.pushname || 'WhatsApp Bot'}</p>
                                                    <p className="text-sm text-gray-600 font-mono">+{connectionInfo?.wid?.split('@')[0] || 'Conectado'}</p>
                                                </div>
                                            </div>
                                            <div className="mt-6 flex gap-3">
                                                <Button onClick={handleDisconnect} disabled={disconnecting} variant="outline" className="w-full border-red-200 text-red-700 hover:bg-red-50 hover:border-red-300">
                                                    {disconnecting ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <PowerOff className="w-4 h-4 mr-2" />}
                                                    Desconectar Sessão
                                                </Button>
                                            </div>
                                        </div>
                                    ) : (
                                        <div className="space-y-4">
                                            {connectionStatus === 'offline' && (
                                                <Alert variant="destructive">
                                                    <AlertCircle className="w-4 h-4" />
                                                    <AlertDescription>O servidor do bot parece estar offline. Verifique o terminal.</AlertDescription>
                                                </Alert>
                                            )}

                                            <Button
                                                onClick={handleReconnect}
                                                disabled={reconnecting || connectionStatus === 'offline'}
                                                className="w-full bg-green-600 hover:bg-green-700"
                                            >
                                                {reconnecting ? <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Gerando novo QR Code...</> : <><RefreshCw className="w-4 h-4 mr-2" /> Iniciar Conexão / Novo QR</>}
                                            </Button>
                                        </div>
                                    )}
                                </div>

                                {/* QR Code Area */}
                                <div className="flex flex-col items-center justify-center bg-gray-50 rounded-xl border-2 border-dashed border-gray-200 min-h-[300px] p-6">
                                    {connectionStatus === 'waiting_qr' && qrCodeImage ? (
                                        <div className="bg-white p-4 rounded-lg shadow-lg animate-in fade-in zoom-in duration-300">
                                            <img src={qrCodeImage} alt="QR Code" className="w-56 h-56" />
                                            <p className="text-center text-xs text-gray-400 mt-2">Atualiza a cada 30s</p>
                                        </div>
                                    ) : connectionStatus === 'connected' ? (
                                        <div className="text-center">
                                            <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-4">
                                                <CheckCircle className="w-10 h-10" />
                                            </div>
                                            <h4 className="text-lg font-medium text-gray-900">Tudo pronto!</h4>
                                            <p className="text-gray-500">Seu bot está operando normalmente.</p>
                                        </div>
                                    ) : (
                                        <div className="text-center text-gray-400">
                                            {connectionStatus === 'initializing' || connectionStatus === 'authenticating' ? (
                                                <>
                                                    <Loader2 className="w-10 h-10 mx-auto mb-3 animate-spin text-blue-500" />
                                                    <p className="text-blue-600 font-medium">Iniciando WhatsApp...</p>
                                                    <p className="text-xs mt-1">Isso pode levar alguns segundos.</p>
                                                </>
                                            ) : connectionStatus === 'disconnected' ? (
                                                <>
                                                    <WifiOff className="w-10 h-10 mx-auto mb-3 text-red-400" />
                                                    <p className="text-red-600 font-medium">Desconectado</p>
                                                    <p className="text-xs mt-1">Tentando reconectar automaticamente...</p>
                                                </>
                                            ) : connectionStatus === 'offline' ? (
                                                <>
                                                    <AlertTriangle className="w-10 h-10 mx-auto mb-3 text-orange-400" />
                                                    <p className="text-orange-600 font-medium">Servidor Offline</p>
                                                    <p className="text-xs mt-1">Verifique se o container está rodando.</p>
                                                </>
                                            ) : (
                                                <>
                                                    <Loader2 className="w-10 h-10 mx-auto mb-3 animate-spin opacity-50" />
                                                    <p>Aguardando resposta do servidor...</p>
                                                </>
                                            )}
                                        </div>
                                    )}
                                </div>
                            </div>
                        </TabsContent>

                        {/* Tab Mensagens */}
                        <TabsContent value="mensagens" className="mt-0 space-y-4">
                            <div className="flex justify-between items-center mb-6">
                                <div>
                                    <h3 className="text-lg font-semibold">Templates</h3>
                                    <p className="text-sm text-gray-500">Personalize o que o bot envia para seus clientes.</p>
                                </div>
                                <Button onClick={handleSaveMessages} disabled={saving || !hasMessageChanges} className="bg-green-600 hover:bg-green-700">
                                    {saving ? <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Salvando...</> : <><Save className="w-4 h-4 mr-2" /> Salvar Alterações</>}
                                </Button>
                            </div>

                            <div className="grid gap-4">
                                {Object.entries(MESSAGE_TEMPLATES).map(([catKey, category]) => {
                                    const CatIcon = category.icon;
                                    const isExpanded = expandedCategories[catKey];

                                    return (
                                        <Collapsible key={catKey} open={isExpanded} onOpenChange={() => toggleCategory(catKey)} className="border rounded-xl bg-white overflow-hidden shadow-sm">
                                            <CollapsibleTrigger className={`w-full flex items-center justify-between p-4 ${category.bgColor} hover:brightness-95 transition-all`}>
                                                <div className="flex items-center gap-3">
                                                    <div className={`p-2 bg-white/50 rounded-lg ${category.color}`}>
                                                        <CatIcon className="w-5 h-5" />
                                                    </div>
                                                    <div className="text-left">
                                                        <span className={`block font-semibold ${category.color} brightness-75`}>{category.label}</span>
                                                        <span className="text-xs text-gray-500">{category.messages.filter(m => messageSettings[m.key]?.enabled).length} ativas</span>
                                                    </div>
                                                </div>
                                                {isExpanded ? <ChevronDown className="w-5 h-5 text-gray-400" /> : <ChevronRight className="w-5 h-5 text-gray-400" />}
                                            </CollapsibleTrigger>
                                            <CollapsibleContent className="divide-y border-t">
                                                {category.messages.map(msg => {
                                                    const MsgIcon = msg.icon;
                                                    const isEnabled = messageSettings[msg.key]?.enabled ?? true;

                                                    return (
                                                        <div key={msg.key} className="flex items-center justify-between p-4 hover:bg-gray-50 transition-colors group">
                                                            <div className="flex items-start gap-3 max-w-[70%]">
                                                                <MsgIcon className={`w-4 h-4 mt-1 ${isEnabled ? category.color : 'text-gray-300'}`} />
                                                                <div>
                                                                    <p className={`font-medium text-sm ${isEnabled ? 'text-gray-900' : 'text-gray-400 line-through'}`}>
                                                                        {msg.label}
                                                                    </p>
                                                                    <p className="text-xs text-gray-500 line-clamp-1">{msg.description}</p>
                                                                </div>
                                                            </div>
                                                            <div className="flex items-center gap-2">
                                                                <Button size="sm" variant="ghost" onClick={() => openMessageEditor(msg)} className="opacity-0 group-hover:opacity-100 transition-opacity">
                                                                    <Edit2 className="w-4 h-4 text-gray-500" />
                                                                </Button>
                                                                <Switch
                                                                    checked={isEnabled}
                                                                    onCheckedChange={(v) => setMessageSettings(prev => ({
                                                                        ...prev,
                                                                        [msg.key]: { ...prev[msg.key], enabled: v }
                                                                    }))}
                                                                />
                                                            </div>
                                                        </div>
                                                    );
                                                })}
                                            </CollapsibleContent>
                                        </Collapsible>
                                    );
                                })}
                            </div>
                        </TabsContent>


                        {/* Tab Fila Offline */}
                        <TabsContent value="fila_offline" className="mt-0 space-y-4">
                            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
                                <div>
                                    <h3 className="text-lg font-semibold">Fila de Ações Offline</h3>
                                    <p className="text-sm text-gray-500">Ações que estão aguardando o envio porque o bot estava offline ou processando.</p>
                                </div>
                                <div className="flex items-center gap-2 flex-wrap">
                                    {offlineQueue.length > 0 && (
                                        <>
                                            <Button
                                                onClick={async () => {
                                                    const ok = window.confirm("Deseja apagar toda a fila offline sem enviar?");
                                                    if (!ok) return;
                                                    await whatsappService.clearAllPendingQueues();
                                                    fetchOfflineQueue();
                                                    toast.success("Fila offline apagada!");
                                                }}
                                                variant="outline"
                                                className="border-red-200 text-red-600 hover:bg-red-50 text-xs"
                                            >
                                                <Trash2 className="w-3.5 h-3.5 mr-1.5" /> Limpar Toda a Fila
                                            </Button>

                                            <Button
                                                onClick={async () => {
                                                    setLoadingQueue(true);
                                                    await whatsappService.processAllPendingQueues();
                                                    fetchOfflineQueue();
                                                    setLoadingQueue(false);
                                                    toast.success("Processamento da fila iniciado!");
                                                }}
                                                className="bg-green-600 hover:bg-green-700 text-white text-xs"
                                            >
                                                <Send className="w-3.5 h-3.5 mr-1.5" /> Enviar Toda a Fila
                                            </Button>
                                        </>
                                    )}
                                    <Button onClick={fetchOfflineQueue} disabled={loadingQueue} variant="outline" className="border-gray-200 text-xs">
                                        <RefreshCw className={`w-3.5 h-3.5 mr-1.5 ${loadingQueue ? 'animate-spin' : ''}`} /> Atualizar
                                    </Button>
                                </div>
                            </div>

                            <div className="space-y-4">
                                {offlineQueue.length === 0 ? (
                                    <div className="text-center py-12 bg-gray-50 rounded-xl border border-dashed border-gray-200">
                                        <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center shadow-sm text-gray-400 mx-auto mb-4 border border-gray-100">
                                            <CloudOff className="w-8 h-8" />
                                        </div>
                                        <h4 className="text-lg font-medium text-gray-900">Fila Vazia</h4>
                                        <p className="text-gray-500 mt-1">Não há nenhuma ação pendente no momento.</p>
                                    </div>
                                ) : (
                                    <div className="grid gap-4">
                                        {offlineQueue.map(item => (
                                            <div key={item.id} className="flex flex-col md:flex-row md:items-center justify-between p-5 border rounded-xl bg-white shadow-sm hover:shadow-md transition-shadow gap-4">
                                                <div className="flex-1">
                                                    <div className="flex items-center gap-3 mb-2">
                                                        <Badge variant="outline" className="bg-orange-50 text-orange-700 border-orange-200 uppercase tracking-wider text-[10px] font-bold">
                                                            Pendente
                                                        </Badge>
                                                        <span className="font-semibold text-gray-900 border-b border-gray-100 pb-0.5">{item.action}</span>
                                                    </div>

                                                    <div className="ml-1 pl-3 border-l-2 border-gray-200 space-y-1">
                                                        {item.payload && item.payload.map((arg, idx) => (
                                                            <div key={idx} className="text-xs text-gray-600 font-mono bg-gray-50 p-1.5 rounded truncate max-w-xl">
                                                                {typeof arg === 'object' ? JSON.stringify(arg) : String(arg)}
                                                            </div>
                                                        ))}
                                                    </div>

                                                    <p className="text-xs text-gray-400 mt-3 flex items-center gap-1.5">
                                                        <Clock className="w-3.5 h-3.5" />
                                                        Adicionado em: {new Date(item.timestamp).toLocaleString()}
                                                    </p>
                                                </div>
                                                <div className="flex items-center gap-3 shrink-0 self-end md:self-auto border-t md:border-t-0 pt-4 md:pt-0 w-full md:w-auto">
                                                    <Button size="sm" variant="outline" className="text-red-600 border-red-200 hover:bg-red-50 hover:border-red-300 ml-auto w-full md:w-auto" onClick={() => handleRemoveQueueItem(item.id)}>
                                                        <Trash2 className="w-4 h-4 mr-2" /> Cancelar Ação
                                                    </Button>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        </TabsContent>
                    </Tabs>
                </CardContent>
            </Card>

            {/* Modal de Edição de Mensagem */}
            <Dialog open={!!editingMessage} onOpenChange={() => setEditingMessage(null)}>
                <DialogContent className="max-w-4xl h-[85vh] flex flex-col p-0 overflow-hidden rounded-2xl">
                    <DialogHeader className="px-6 py-4 border-b bg-gray-50">
                        <DialogTitle className="flex items-center gap-2">
                            <Edit2 className="w-5 h-5 text-gray-500" />
                            Editar Template: <span className="text-green-700">{editingMessage?.label}</span>
                        </DialogTitle>
                        <DialogDescription>
                            {editingMessage?.description}
                        </DialogDescription>
                    </DialogHeader>

                    <div className="flex-1 flex overflow-hidden">
                        {/* Editor Sidebar */}
                        <div className="w-1/2 p-6 overflow-y-auto border-r space-y-6 bg-white">
                            <div className="flex items-center justify-between p-4 bg-gray-50 border rounded-xl">
                                <Label className="cursor-pointer" htmlFor="msg-active">Mensagem Ativa</Label>
                                <Switch id="msg-active" checked={editingEnabled} onCheckedChange={setEditingEnabled} className="data-[state=checked]:bg-green-600" />
                            </div>

                            <div className="space-y-3">
                                <Label className="text-xs font-bold text-gray-500 uppercase tracking-wider">Variáveis Disponíveis</Label>
                                <div className="flex flex-wrap gap-2">
                                    {editingMessage?.variables.map(v => (
                                        <button
                                            key={v.key}
                                            onClick={() => insertVariable(v.key)}
                                            className="px-3 py-1.5 bg-blue-50 text-blue-700 border border-blue-100 rounded-md text-xs font-mono hover:bg-blue-100 hover:border-blue-200 transition-all active:scale-95 flex items-center gap-1.5"
                                            title={`${v.label}: ${v.example}`}
                                        >
                                            <Copy className="w-3 h-3" />
                                            {v.key}
                                        </button>
                                    ))}
                                </div>
                                <p className="text-[10px] text-gray-400">Clique para inserir no texto. Elas serão substituídas pelos dados reais.</p>
                            </div>

                            <div className="space-y-3 h-full">
                                <Label>Conteúdo da Mensagem</Label>
                                <Textarea
                                    value={editingTemplate}
                                    onChange={(e) => setEditingTemplate(e.target.value)}
                                    className="min-h-[300px] font-mono text-sm leading-relaxed p-4 bg-gray-50 focus:bg-white transition-colors resize-none"
                                />
                            </div>
                        </div>

                        {/* Preview Area */}
                        <div className="w-1/2 bg-[#efeae2] p-8 flex flex-col items-center justify-center relative bg-opacity-80">
                            <div className="absolute inset-0 opacity-10 bg-[url('https://user-images.githubusercontent.com/15075759/28719144-86dc0f70-73b1-11e7-911d-60d70fcded21.png')]"></div>

                            <div className="w-[320px] relative z-10">
                                <div className="bg-[#dcf8c6] rounded-lg p-3 shadow-sm relative after:content-[''] after:absolute after:top-0 after:-right-2 after:w-0 after:h-0 after:border-[8px] after:border-t-[#dcf8c6] after:border-r-transparent after:border-b-transparent after:border-l-transparent">
                                    <p className="text-sm text-gray-800 whitespace-pre-wrap leading-snug">
                                        {editingMessage?.variables.reduce((text, v) => {
                                            return text.replace(new RegExp(v.key.replace(/[{}]/g, '\\$&'), 'g'), v.example);
                                        }, editingTemplate || "")}
                                    </p>
                                    <div className="flex justify-end mt-1">
                                        <span className="text-[10px] text-gray-500">14:30</span>
                                        <span className="ml-1 text-blue-400">✓✓</span>
                                    </div>
                                </div>
                            </div>

                            <p className="mt-8 text-xs text-gray-500 font-medium bg-white/50 px-3 py-1 rounded-full backdrop-blur-sm">
                                Visualização Aproximada
                            </p>
                        </div>
                    </div>

                    <DialogHeader className="px-6 py-4 border-t bg-gray-50 flex flex-row justify-end gap-3 rounded-b-2xl h-auto">
                        <Button variant="ghost" onClick={() => setEditingMessage(null)}>Cancelar</Button>
                        <Button onClick={saveMessageEdit} className="bg-green-600 hover:bg-green-700">
                            <Save className="w-4 h-4 mr-2" /> Salvar Alterações
                        </Button>
                    </DialogHeader>
                </DialogContent>
            </Dialog>

            {/* 🔔 Modal de Confirmação de Notificações Pendentes ao Ler QR Code */}
            <Dialog open={pendingModalOpen} onOpenChange={(open) => {
                if (!processingQueueAction) setPendingModalOpen(open);
            }}>
                <DialogContent className="max-w-xl p-0 overflow-hidden rounded-2xl border-amber-200 shadow-2xl">
                    <DialogHeader className="px-6 pt-6 pb-4 bg-gradient-to-r from-amber-50 to-orange-50 border-b border-amber-100">
                        <div className="flex items-center gap-3">
                            <div className="w-12 h-12 rounded-full bg-amber-100 text-amber-700 flex items-center justify-center shrink-0 border border-amber-200 shadow-sm">
                                <Inbox className="w-6 h-6" />
                            </div>
                            <div>
                                <DialogTitle className="text-xl font-bold text-gray-900">
                                    WhatsApp Conectado!
                                </DialogTitle>
                                <DialogDescription className="text-amber-800 font-medium text-sm mt-0.5">
                                    Notificações pendentes identificadas durante o período desconectado.
                                </DialogDescription>
                            </div>
                        </div>
                    </DialogHeader>

                    <div className="p-6 space-y-4 bg-white">
                        <div className="bg-amber-50/70 border border-amber-200/80 rounded-xl p-4 text-sm text-gray-700 space-y-2">
                            <p className="font-semibold text-amber-950 flex items-center gap-2">
                                <AlertTriangle className="w-4 h-4 text-amber-600 shrink-0" />
                                O que você deseja fazer com as notificações acumuladas?
                            </p>
                            <p className="text-xs text-gray-600 leading-relaxed">
                                Identificamos <strong>{pendingInfo.totalCount} notificação(ões)</strong> acumuladas enquanto o WhatsApp esteve desconectado. Você pode optar por enviá-las agora para os clientes ou descartá-las para evitar mensagens retroativas.
                            </p>
                        </div>

                        {/* Prévia das mensagens */}
                        {pendingInfo.totalCount > 0 && (
                            <div className="space-y-2">
                                <p className="text-xs font-bold text-gray-500 uppercase tracking-wider flex items-center justify-between">
                                    <span>Mensagens na Fila</span>
                                    <Badge variant="outline" className="bg-amber-50 text-amber-800 border-amber-200 text-[10px]">
                                        {pendingInfo.totalCount} pendente(s)
                                    </Badge>
                                </p>
                                <div className="max-h-48 overflow-y-auto space-y-2 border rounded-xl p-3 bg-gray-50/60">
                                    {pendingInfo.localItems.map((item, idx) => (
                                        <div key={item.id || idx} className="text-xs bg-white p-2.5 rounded-lg border border-gray-200 shadow-2xs space-y-1">
                                            <div className="flex items-center justify-between text-[11px] font-semibold text-gray-700">
                                                <span className="text-blue-700 font-mono">{item.action}</span>
                                                <span className="text-gray-400 font-normal">{new Date(item.timestamp).toLocaleString()}</span>
                                            </div>
                                            <p className="text-gray-600 font-mono text-[10px] truncate">
                                                {item.payload ? JSON.stringify(item.payload[0] || item.payload) : ''}
                                            </p>
                                        </div>
                                    ))}
                                    {pendingInfo.backendItems.map((item, idx) => (
                                        <div key={item.id || idx} className="text-xs bg-white p-2.5 rounded-lg border border-gray-200 shadow-2xs space-y-1">
                                            <div className="flex items-center justify-between text-[11px] font-semibold text-gray-700">
                                                <span className="text-green-700">Para: {item.phone}</span>
                                                <span className="text-gray-400 font-normal">{new Date(item.created_at).toLocaleString()}</span>
                                            </div>
                                            <p className="text-gray-600 text-[11px] truncate">
                                                {item.message}
                                            </p>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}
                    </div>

                    <div className="px-6 py-4 bg-gray-50 border-t flex flex-col sm:flex-row items-center justify-end gap-3 rounded-b-2xl">
                        <Button
                            variant="outline"
                            disabled={!!processingQueueAction}
                            onClick={handleClearPendingNotifications}
                            className="w-full sm:w-auto border-red-200 text-red-700 hover:bg-red-50 hover:border-red-300 font-medium text-xs sm:text-sm"
                        >
                            {processingQueueAction === 'clearing' ? (
                                <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Descartando...</>
                            ) : (
                                <><Trash2 className="w-4 h-4 mr-2" /> Apagar / Descartar Todas</>
                            )}
                        </Button>

                        <Button
                            disabled={!!processingQueueAction}
                            onClick={handleSendPendingNotifications}
                            className="w-full sm:w-auto bg-green-600 hover:bg-green-700 text-white font-semibold shadow-md shadow-green-600/20 text-xs sm:text-sm"
                        >
                            {processingQueueAction === 'sending' ? (
                                <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Enviando...</>
                            ) : (
                                <><Send className="w-4 h-4 mr-2" /> Enviar Todas as Notificações ({pendingInfo.totalCount})</>
                            )}
                        </Button>
                    </div>
                </DialogContent>
            </Dialog>
        </div>
    );
}

// Nota para o futuro:
// Para centralizar totalmente as chaves, o backend (server.js) deve ser atualizado para ler
// a gemini_api_key diretamente da tabela 'configuracao_sistema' do Supabase se não for enviada aqui.

import React, { useState, useEffect } from "react";
import { supabase } from "@/lib/supabase";
import { useTenant } from "@/contexts/TenantContext";
import { toast } from "sonner";
import { 
  Check, 
  Loader2, 
  CreditCard, 
  QrCode, 
  FileText, 
  Sparkles, 
  ChevronRight,
  Info
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import PlanModulesDisplay from "@/components/planos/PlanModulesDisplay";


export default function EscolhaPlano({ onCancel }) {
  const { organization, refreshTenant } = useTenant();
  const [planos, setPlanos] = useState([]);
  const [loadingPlanos, setLoadingPlanos] = useState(true);
  const [loadingSubmit, setLoadingSubmit] = useState(false);
  
  // Checkout flow state
  const [selectedPlan, setSelectedPlan] = useState(null);
  const [paymentMethod, setPaymentMethod] = useState("PIX"); // PIX, BOLETO, CREDIT_CARD
  const [showPaymentModal, setShowPaymentModal] = useState(false);

  // Credit Card Form fields
  const [cardHolderName, setCardHolderName] = useState("");
  const [cardNumber, setCardNumber] = useState("");
  const [cardExpiryMonth, setCardExpiryMonth] = useState("");
  const [cardExpiryYear, setCardExpiryYear] = useState("");
  const [cardCvv, setCardCvv] = useState("");
  
  // Additional Cardholder Billing details
  const [holderCpfCnpj, setHolderCpfCnpj] = useState(organization?.cnpj || "");
  const [holderEmail, setHolderEmail] = useState(organization?.email_suporte || "");
  const [holderPhone, setHolderPhone] = useState(organization?.whatsapp_suporte || "");
  const [holderPostalCode, setHolderPostalCode] = useState("");
  const [holderAddressNumber, setHolderAddressNumber] = useState("1");

  const isSubscribed = organization?.status_assinatura && organization.status_assinatura !== "sem_assinatura" && organization.status_assinatura !== "cancelada";

  useEffect(() => {
    async function loadPlanos() {
      try {
        setLoadingPlanos(true);
        const { data, error } = await supabase
          .from("planos")
          .select("*")
          .eq("ativo", true)
          .order("preco_mensal", { ascending: true });

        if (error) throw error;
        setPlanos(data || []);
      } catch (err) {
        console.error("Erro ao carregar planos:", err);
        toast.error("Erro ao carregar os planos do sistema.");
      } finally {
        setLoadingPlanos(false);
      }
    }

    loadPlanos();
  }, []);

  const handleSelectPlan = (plano) => {
    setSelectedPlan(plano);
    setHolderCpfCnpj(organization?.cnpj || "");
    setHolderEmail(organization?.email_suporte || "");
    setHolderPhone(organization?.whatsapp_suporte || "");
    setShowPaymentModal(true);
  };

  const handleConfirmSubscription = async (e) => {
    e.preventDefault();
    if (!selectedPlan) return;

    // Validar dados de faturamento para todas as formas de pagamento
    const cleanCpfCnpj = holderCpfCnpj.replace(/\D/g, "");
    if (cleanCpfCnpj.length !== 11 && cleanCpfCnpj.length !== 14) {
      toast.error("CPF deve ter 11 dígitos e CNPJ deve ter 14 dígitos.");
      return;
    }
    if (!holderEmail || !holderEmail.includes("@")) {
      toast.error("E-mail de faturamento inválido.");
      return;
    }
    if (!holderPhone || holderPhone.replace(/\D/g, "").length < 10) {
      toast.error("WhatsApp / Telefone inválido (mínimo 10 dígitos).");
      return;
    }

    if (paymentMethod === "CREDIT_CARD") {
      if (!cardHolderName || !cardNumber || !cardExpiryMonth || !cardExpiryYear || !cardCvv) {
        toast.error("Preencha todos os campos do cartão de crédito.");
        return;
      }
      if (!holderPostalCode) {
        toast.error("CEP é obrigatório para pagamento com cartão.");
        return;
      }
    }

    try {
      setLoadingSubmit(true);
      
      const payload = {
        planoId: selectedPlan.id,
        paymentMethod,
        billingInfo: {
          cnpj: cleanCpfCnpj,
          email: holderEmail.trim(),
          phone: holderPhone.replace(/\D/g, "")
        },
        cardDetails: paymentMethod === "CREDIT_CARD" ? {
          holderName: cardHolderName,
          number: cardNumber,
          expiryMonth: cardExpiryMonth,
          expiryYear: cardExpiryYear,
          ccv: cardCvv,
          email: holderEmail,
          cpfCnpj: holderCpfCnpj,
          postalCode: holderPostalCode,
          addressNumber: holderAddressNumber,
          phone: holderPhone
        } : null
      };

      const { data, error } = await supabase.functions.invoke("criar-assinatura", {
        body: payload
      });

      if (error) {
        let msg = error.message || 'Ocorreu um erro ao processar a assinatura.';
        if (error.context && typeof error.context.json === 'function') {
          try {
            const body = await error.context.json();
            if (body?.error) msg = body.error;
          } catch (_) {}
        }
        throw new Error(msg);
      }

      if (data?.success) {
        toast.success("Solicitação de assinatura registrada!");
        setShowPaymentModal(false);
        await refreshTenant(); 
        if (onCancel) onCancel();
      }
    } catch (err) {
      console.error("Erro ao assinar plano:", err);
      toast.error(err.message || "Ocorreu um erro ao processar a assinatura no Asaas.");
    } finally {
      setLoadingSubmit(false);
    }
  };

  const formatCurrency = (val) => {
    return new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(val);
  };

  if (loadingPlanos) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <Loader2 className="w-8 h-8 animate-spin text-green-700 mb-2" />
        <p className="text-sm text-gray-500">Carregando planos disponíveis...</p>
      </div>
    );
  }

  return (
    <div id="planos-selection-section" className="space-y-6 pt-4 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="border-t pt-6 flex justify-between items-end">
        <div>
          <h3 className="text-lg font-bold text-gray-800" style={{ color: "#07593f" }}>
            Nossos Planos Disponíveis
          </h3>
          <p className="text-sm text-gray-500 mt-1">
            Selecione um plano diferente abaixo para realizar o upgrade ou downgrade da sua assinatura atual.
          </p>
        </div>
        {onCancel && (
          <Button variant="outline" onClick={onCancel} className="mb-1">
            Voltar
          </Button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 lg:max-w-4xl mx-auto">
        {planos.map((plano) => {
          const isCurrent = plano.id === organization?.plano_id && organization?.status_assinatura === 'ativa';
          const isCustom = !plano.preco_mensal || Number(plano.preco_mensal) === 0 || plano.recursos?.customizado || plano.recursos?.sob_consulta;
          
          return (
            <Card 
              key={plano.id} 
              className={`flex flex-col h-full transition-all relative ${
                isCurrent 
                  ? "border-2 border-green-700 shadow-md ring-1 ring-green-700/20" 
                  : "hover:shadow-md border-gray-200"
              }`}
            >
              {plano.slug === "profissional" && (
                <div className="absolute top-0 right-1/2 translate-x-1/2 -translate-y-1/2 bg-green-700 text-white text-xs font-bold px-3 py-1 rounded-full uppercase tracking-wider shadow">
                  Mais Popular
                </div>
              )}
              
              <CardHeader className="text-center pb-4">
                <CardTitle className="text-xl text-gray-800">{plano.nome}</CardTitle>
                <CardDescription className="text-xs mt-1">
                  {isCustom ? "Atendimento e escopo customizado" : "Recorrência mensal automática"}
                </CardDescription>
                <div className="mt-4">
                  {isCustom ? (
                    <span className="text-2xl font-extrabold text-gray-900">Sob Consulta</span>
                  ) : (
                    <>
                      <span className="text-3xl font-extrabold text-gray-900">{formatCurrency(plano.preco_mensal)}</span>
                      <span className="text-sm text-gray-400"> / mês</span>
                    </>
                  )}
                </div>
              </CardHeader>
              
              <CardContent className="flex-grow pt-2">
                <div className="space-y-3.5">
                  <div className="flex items-center gap-2 text-sm font-semibold text-gray-700 border-b pb-2">
                    <Sparkles className="w-4 h-4 text-green-700" /> Módulos Habilitados:
                  </div>
                  <PlanModulesDisplay recursos={plano.recursos} variant="card" />

                  <div className="flex items-start gap-2 text-sm text-gray-500 pt-2 border-t text-xs">
                    <Info className="w-3.5 h-3.5 text-gray-400 shrink-0 mt-0.5" />
                    <span>Inclui suporte técnico e atualizações do MPII Hub.</span>
                  </div>
                </div>
              </CardContent>
              
              <CardFooter className="pt-6">
                {isCurrent ? (
                  <Button className="w-full bg-green-50 text-green-800 border border-green-200 cursor-default hover:bg-green-50" disabled>
                    Plano Atual Contratado
                  </Button>
                ) : isCustom ? (
                  <a 
                    href={`https://wa.me/5521999999999?text=${encodeURIComponent(`Olá! Gostaria de uma proposta personalizada para o Plano ${plano.nome} no GestApp.`)}`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="w-full block"
                  >
                    <Button className="w-full bg-slate-900 hover:bg-slate-800 text-white transition-colors">
                      Falar com Suporte / Contate-nos
                      <ChevronRight className="w-4 h-4 ml-1" />
                    </Button>
                  </a>
                ) : (
                  <Button 
                    onClick={() => handleSelectPlan(plano)}
                    className="w-full bg-green-700 hover:bg-green-800 transition-colors"
                  >
                    {plano.id === organization?.plano_id 
                      ? "Confirmar e Gerar Cobrança" 
                      : (isSubscribed ? "Alterar para este Plano" : "Assinar este Plano")}
                    <ChevronRight className="w-4 h-4 ml-1" />
                  </Button>
                )}
              </CardFooter>
            </Card>
          );
        })}
      </div>

      {/* MODAL DE CONFIRMAÇÃO E PAGAMENTO (PIX/BOLETO/CARD) */}
      <Dialog open={showPaymentModal} onOpenChange={setShowPaymentModal}>
        <DialogContent className="max-w-xl max-h-[90vh] overflow-y-auto">
          <form onSubmit={handleConfirmSubscription} className="space-y-6">
            <DialogHeader>
              <DialogTitle className="text-lg font-bold" style={{ color: "#07593f" }}>
                Confirmar Assinatura — {selectedPlan?.nome}
              </DialogTitle>
              <DialogDescription>
                Selecione a forma de pagamento recorrente. A primeira cobrança será gerada hoje e as mensalidades serão automáticas.
              </DialogDescription>
            </DialogHeader>

            <div className="space-y-3">
              <Label className="font-semibold text-gray-700">Forma de Pagamento Recorrente</Label>
              <div className="grid grid-cols-3 gap-3">
                <button
                  type="button"
                  onClick={() => setPaymentMethod("PIX")}
                  className={`flex flex-col items-center justify-center p-3 rounded-lg border text-sm font-medium transition-all ${
                    paymentMethod === "PIX" 
                      ? "border-green-700 bg-green-50 text-green-800 ring-2 ring-green-700/20" 
                      : "border-gray-200 text-gray-600 hover:bg-gray-50"
                  }`}
                >
                  <QrCode className="w-5 h-5 mb-1.5" />
                  PIX
                </button>
                <button
                  type="button"
                  onClick={() => setPaymentMethod("BOLETO")}
                  className={`flex flex-col items-center justify-center p-3 rounded-lg border text-sm font-medium transition-all ${
                    paymentMethod === "BOLETO" 
                      ? "border-green-700 bg-green-50 text-green-800 ring-2 ring-green-700/20" 
                      : "border-gray-200 text-gray-600 hover:bg-gray-50"
                  }`}
                >
                  <FileText className="w-5 h-5 mb-1.5" />
                  Boleto
                </button>
                <button
                  type="button"
                  onClick={() => setPaymentMethod("CREDIT_CARD")}
                  className={`flex flex-col items-center justify-center p-3 rounded-lg border text-sm font-medium transition-all ${
                    paymentMethod === "CREDIT_CARD" 
                      ? "border-green-700 bg-green-50 text-green-800 ring-2 ring-green-700/20" 
                      : "border-gray-200 text-gray-600 hover:bg-gray-50"
                  }`}
                >
                  <CreditCard className="w-5 h-5 mb-1.5" />
                  Cartão
                </button>
              </div>
            </div>

            {paymentMethod === "CREDIT_CARD" && (
              <div className="space-y-4 border-t pt-4">
                <h4 className="text-sm font-bold text-gray-700 flex items-center gap-1.5">
                  <CreditCard className="w-4 h-4 text-green-700" />
                  Dados do Cartão de Crédito
                </h4>
                
                <div className="space-y-3">
                  <div>
                    <Label htmlFor="card-name" className="text-xs font-semibold text-gray-500">Nome Impresso no Cartão</Label>
                    <Input 
                      id="card-name"
                      placeholder="NOME DO TITULAR"
                      value={cardHolderName}
                      onChange={(e) => setCardHolderName(e.target.value.toUpperCase())}
                      className="mt-1"
                      required
                    />
                  </div>
                  <div>
                    <Label htmlFor="card-number" className="text-xs font-semibold text-gray-500">Número do Cartão</Label>
                    <Input 
                      id="card-number"
                      placeholder="0000 0000 0000 0000"
                      value={cardNumber}
                      onChange={(e) => setCardNumber(e.target.value.replace(/\D/g, "").substring(0, 16))}
                      className="mt-1"
                      required
                    />
                  </div>
                  <div className="grid grid-cols-3 gap-3">
                    <div>
                      <Label htmlFor="card-month" className="text-xs font-semibold text-gray-500">Mês Exp.</Label>
                      <Input 
                        id="card-month"
                        placeholder="MM"
                        value={cardExpiryMonth}
                        onChange={(e) => setCardExpiryMonth(e.target.value.replace(/\D/g, "").substring(0, 2))}
                        className="mt-1"
                        required
                      />
                    </div>
                    <div>
                      <Label htmlFor="card-year" className="text-xs font-semibold text-gray-500">Ano Exp.</Label>
                      <Input 
                        id="card-year"
                        placeholder="AAAA"
                        value={cardExpiryYear}
                        onChange={(e) => setCardExpiryYear(e.target.value.replace(/\D/g, "").substring(0, 4))}
                        className="mt-1"
                        required
                      />
                    </div>
                    <div>
                      <Label htmlFor="card-cvv" className="text-xs font-semibold text-gray-500">CVV</Label>
                      <Input 
                        id="card-cvv"
                        placeholder="123"
                        value={cardCvv}
                        onChange={(e) => setCardCvv(e.target.value.replace(/\D/g, "").substring(0, 4))}
                        className="mt-1"
                        required
                      />
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* Dados de Faturamento (Sempre Visíveis) */}
            <div className="space-y-4 border-t pt-4">
              <h4 className="text-sm font-bold text-gray-700">Dados de Faturamento</h4>
              
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <Label htmlFor="billing-cnpj" className="text-xs font-semibold text-gray-500">CPF ou CNPJ</Label>
                  <Input 
                    id="billing-cnpj"
                    placeholder="Apenas números"
                    value={holderCpfCnpj}
                    onChange={(e) => setHolderCpfCnpj(e.target.value.replace(/\D/g, ""))}
                    className="mt-1"
                    required
                  />
                </div>
                <div>
                  <Label htmlFor="billing-email" className="text-xs font-semibold text-gray-500">E-mail para Recibo / Faturas</Label>
                  <Input 
                    id="billing-email"
                    type="email"
                    placeholder="email@provedor.com"
                    value={holderEmail}
                    onChange={(e) => setHolderEmail(e.target.value)}
                    className="mt-1"
                    required
                  />
                </div>
                <div className={paymentMethod === "CREDIT_CARD" ? "" : "col-span-2"}>
                  <Label htmlFor="billing-phone" className="text-xs font-semibold text-gray-500">WhatsApp / Telefone</Label>
                  <Input 
                    id="billing-phone"
                    placeholder="Ex: 24999999999"
                    value={holderPhone}
                    onChange={(e) => setHolderPhone(e.target.value.replace(/\D/g, ""))}
                    className="mt-1"
                    required
                  />
                </div>
                {paymentMethod === "CREDIT_CARD" && (
                  <>
                    <div>
                      <Label htmlFor="billing-cep" className="text-xs font-semibold text-gray-500">CEP Residencial</Label>
                      <Input 
                        id="billing-cep"
                        placeholder="00000-000"
                        value={holderPostalCode}
                        onChange={(e) => setHolderPostalCode(e.target.value.replace(/\D/g, "").substring(0, 8))}
                        className="mt-1"
                        required
                      />
                    </div>
                    <div>
                      <Label htmlFor="billing-num" className="text-xs font-semibold text-gray-500">Número Residência</Label>
                      <Input 
                        id="billing-num"
                        placeholder="Ex: 123"
                        value={holderAddressNumber}
                        onChange={(e) => setHolderAddressNumber(e.target.value)}
                        className="mt-1"
                        required
                      />
                    </div>
                  </>
                )}
              </div>
            </div>

            <DialogFooter className="gap-2">
              <Button
                type="button"
                variant="outline"
                onClick={() => setShowPaymentModal(false)}
                disabled={loadingSubmit}
              >
                Cancelar
              </Button>
              <Button
                type="submit"
                disabled={loadingSubmit}
                className="bg-green-700 hover:bg-green-800 transition-colors"
              >
                {loadingSubmit ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin mr-2" />
                    Processando...
                  </>
                ) : (
                  "Confirmar e Pagar"
                )}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useState, useMemo } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Shield, Info, Key, Plus, Trash2, Loader2 } from "lucide-react";
import { CARGOS } from "@/config/cargos";
import { ROLE_RULES, SCOPES } from "@/config/permissions";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { base44 } from "@/api/base44Client";
import { toast } from "sonner";
import RolePermissionEditorModal from "./RolePermissionEditorModal";

const SCOPE_COLORS = {
    [SCOPES.ALL]:   '#dc2626',
    [SCOPES.STORE]: '#f97316',
    [SCOPES.OWN]:   '#3b82f6',
};

const SCOPE_LABELS = {
    [SCOPES.ALL]:   'Escopo: Todos',
    [SCOPES.STORE]: 'Escopo: Loja',
    [SCOPES.OWN]:   'Escopo: Próprio',
};

const SCOPE_SELECT_OPTIONS = [
    { value: SCOPES.ALL,   label: 'Todos os dados (toda a empresa)' },
    { value: SCOPES.STORE, label: 'Dados da loja do usuário' },
    { value: SCOPES.OWN,   label: 'Apenas dados próprios' },
];

export default function GestaoCargos() {
    const [editingCargo, setEditingCargo]         = useState(null);
    const [criarCargoOpen, setCriarCargoOpen]     = useState(false);
    const [novoCargo, setNovoCargo]               = useState({ nome: '', cor: '#6b7280', escopo: SCOPES.OWN, descricao: '' });
    const [confirmarExcluir, setConfirmarExcluir] = useState(null);
    const queryClient = useQueryClient();

    const { data: rolePermissions = [] } = useQuery({
        queryKey: ['role_permissions'],
        queryFn: () => base44.entities.RolePermission.list()
    });

    // Merge static CARGOS (config) + custom cargos created via UI (is_custom = true in DB)
    const allCargos = useMemo(() => {
        const staticList = CARGOS.map(c => {
            const dbRow = rolePermissions.find(r => r.cargo === c.value);
            return {
                value:       c.value,
                label:       c.label,
                color:       c.color,
                bgColor:     c.bgColor,
                description: c.description,
                icon:        c.icon,
                isCustom:    false,
                dbRow,
                scope: dbRow?.scope || ROLE_RULES[c.value]?.scope || SCOPES.OWN,
            };
        });

        const customList = rolePermissions
            .filter(r => r.is_custom && !CARGOS.find(c => c.value === r.cargo))
            .map(r => ({
                value:       r.cargo,
                label:       r.label || r.cargo,
                color:       r.color || '#6b7280',
                bgColor:     `${r.color || '#6b7280'}22`,
                description: r.description || '',
                icon:        Shield,
                isCustom:    true,
                dbRow:       r,
                scope:       r.scope || SCOPES.OWN,
            }));

        return [...staticList, ...customList];
    }, [rolePermissions]);

    // Save permissions (additions + denials) and scope for a cargo
    const savePermissionsMutation = useMutation({
        mutationFn: async ({ cargo, permissions, deniedPermissions, scope }) => {
            const existing = rolePermissions.find(r => r.cargo === cargo);
            const payload = {
                permissions:        permissions        || [],
                denied_permissions: deniedPermissions  || [],
                scope:              scope              || SCOPES.OWN,
                updated_at:         new Date().toISOString(),
            };
            if (existing) {
                await base44.entities.RolePermission.update(existing.id, payload);
            } else {
                await base44.entities.RolePermission.create({ cargo, ...payload });
            }
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['role_permissions'] });
            setEditingCargo(null);
            toast.success('Permissões do cargo atualizadas!');
        },
        onError: (e) => toast.error('Erro: ' + e.message)
    });

    // Create a new custom cargo in DB
    const createCargoMutation = useMutation({
        mutationFn: async ({ nome, cor, escopo, descricao }) => {
            const nomeNorm = nome.trim();
            if (!nomeNorm) throw new Error('Nome do cargo é obrigatório.');
            const existe = rolePermissions.find(r => r.cargo === nomeNorm) || CARGOS.find(c => c.value === nomeNorm);
            if (existe) throw new Error(`Cargo "${nomeNorm}" já existe.`);
            await base44.entities.RolePermission.create({
                cargo:              nomeNorm,
                permissions:        [],
                denied_permissions: [],
                scope:              escopo      || SCOPES.OWN,
                label:              nomeNorm,
                color:              cor         || '#6b7280',
                description:        descricao   || '',
                is_custom:          true,
                updated_at:         new Date().toISOString(),
            });
        },
        onSuccess: (_, { nome }) => {
            queryClient.invalidateQueries({ queryKey: ['role_permissions'] });
            setCriarCargoOpen(false);
            setNovoCargo({ nome: '', cor: '#6b7280', escopo: SCOPES.OWN, descricao: '' });
            toast.success(`Cargo "${nome.trim()}" criado! Configure as permissões clicando em "Editar Permissões".`);
        },
        onError: (e) => toast.error('Erro: ' + e.message)
    });

    // Delete a custom cargo from DB
    const deleteCargoMutation = useMutation({
        mutationFn: async (cargo) => {
            const row = rolePermissions.find(r => r.cargo === cargo && r.is_custom);
            if (!row) throw new Error('Apenas cargos personalizados podem ser excluídos.');
            await base44.entities.RolePermission.delete(row.id);
        },
        onSuccess: (_, cargo) => {
            queryClient.invalidateQueries({ queryKey: ['role_permissions'] });
            setConfirmarExcluir(null);
            toast.success(`Cargo "${cargo}" excluído.`);
        },
        onError: (e) => toast.error('Erro: ' + e.message)
    });

    const getCargoPermissions = (cargoValue) =>
        rolePermissions.find(r => r.cargo === cargoValue)?.permissions || [];

    const getCargoDenied = (cargoValue) =>
        rolePermissions.find(r => r.cargo === cargoValue)?.denied_permissions || [];

    const handleSavePermissions = ({ permissions, deniedPermissions, scope }) => {
        if (!editingCargo) return;
        savePermissionsMutation.mutate({
            cargo: editingCargo.value,
            permissions,
            deniedPermissions,
            scope,
        });
    };

    return (
        <div className="space-y-6">
            <Card className="border-0 shadow-lg">
                <CardHeader className="pb-3">
                    <div className="flex items-center justify-between">
                        <CardTitle className="flex items-center gap-2" style={{ color: '#07593f' }}>
                            <Shield className="w-6 h-6" />
                            Cargos do Sistema
                        </CardTitle>
                        <Button
                            onClick={() => setCriarCargoOpen(true)}
                            style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
                        >
                            <Plus className="w-4 h-4 mr-2" />
                            Criar Cargo
                        </Button>
                    </div>
                </CardHeader>
                <CardContent>
                    <p className="text-gray-500 mb-6 text-sm">
                        Gerencie cargos e suas permissões. Cargos personalizados podem ser criados e excluídos.
                        Clique em &quot;Editar Permissões&quot; para ajustar o acesso de qualquer cargo.
                    </p>

                    <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-4">
                        {allCargos.map((cargo) => {
                            const Icon = cargo.icon;
                            const hasCustomPerms =
                                getCargoPermissions(cargo.value).length > 0 ||
                                getCargoDenied(cargo.value).length > 0;
                            const scopeValue = cargo.scope;

                            return (
                                <div
                                    key={cargo.value}
                                    className="p-4 rounded-xl border-2 transition-all hover:shadow-md"
                                    style={{ backgroundColor: cargo.bgColor, borderColor: cargo.color }}
                                >
                                    <div className="flex items-start gap-3">
                                        <div
                                            className="w-12 h-12 rounded-xl flex items-center justify-center flex-shrink-0"
                                            style={{ backgroundColor: `${cargo.color}20` }}
                                        >
                                            <Icon className="w-6 h-6" style={{ color: cargo.color }} />
                                        </div>
                                        <div className="flex-1 min-w-0">
                                            <div className="flex items-center justify-between gap-1 flex-wrap">
                                                <h3 className="font-bold truncate" style={{ color: cargo.color }}>
                                                    {cargo.label}
                                                </h3>
                                                <div className="flex gap-1 flex-shrink-0">
                                                    {hasCustomPerms && (
                                                        <Badge className="bg-blue-100 text-blue-700 text-xs">
                                                            <Key className="w-3 h-3 mr-1" />
                                                            Editado
                                                        </Badge>
                                                    )}
                                                    {cargo.isCustom && (
                                                        <Badge className="bg-purple-100 text-purple-700 text-xs">
                                                            Custom
                                                        </Badge>
                                                    )}
                                                </div>
                                            </div>

                                            <p className="text-xs text-gray-500 mt-1 line-clamp-2">
                                                {cargo.description}
                                            </p>

                                            <div className="mt-2">
                                                <Badge
                                                    className="text-xs"
                                                    style={{
                                                        backgroundColor: `${SCOPE_COLORS[scopeValue] || '#6b7280'}15`,
                                                        color:           SCOPE_COLORS[scopeValue] || '#6b7280',
                                                        border:          `1px solid ${SCOPE_COLORS[scopeValue] || '#6b7280'}40`,
                                                    }}
                                                >
                                                    {SCOPE_LABELS[scopeValue] || 'Escopo: Próprio'}
                                                </Badge>
                                            </div>

                                            <div className="flex gap-2 mt-3">
                                                <Button
                                                    size="sm"
                                                    variant="outline"
                                                    className="flex-1 text-xs"
                                                    onClick={() => setEditingCargo(cargo)}
                                                    style={{ borderColor: cargo.color, color: cargo.color }}
                                                >
                                                    <Key className="w-3 h-3 mr-1" />
                                                    Editar Permissões
                                                </Button>
                                                {cargo.isCustom && (
                                                    <Button
                                                        size="sm"
                                                        variant="outline"
                                                        className="text-red-600 hover:text-red-700 border-red-200"
                                                        onClick={() => setConfirmarExcluir(cargo.value)}
                                                    >
                                                        <Trash2 className="w-3 h-3" />
                                                    </Button>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </CardContent>
            </Card>

            <Alert className="bg-blue-50 border-blue-200">
                <Info className="w-4 h-4 text-blue-600" />
                <AlertDescription className="text-blue-800">
                    <strong>Escopo de dados:</strong> Controla quais registros o usuário enxerga — todos da empresa, apenas da loja dele, ou somente os próprios.
                    As permissões definem quais ações e telas estão disponíveis.
                </AlertDescription>
            </Alert>

            {/* ── Modal: Criar Cargo ── */}
            <Dialog open={criarCargoOpen} onOpenChange={setCriarCargoOpen}>
                <DialogContent className="max-w-md">
                    <DialogHeader>
                        <DialogTitle>Criar Novo Cargo</DialogTitle>
                        <DialogDescription>
                            Crie um cargo personalizado e depois configure suas permissões.
                        </DialogDescription>
                    </DialogHeader>
                    <div className="space-y-4">
                        <div>
                            <Label htmlFor="nome-cargo">Nome do Cargo *</Label>
                            <Input
                                id="nome-cargo"
                                value={novoCargo.nome}
                                onChange={(e) => setNovoCargo(prev => ({ ...prev, nome: e.target.value }))}
                                placeholder="Ex: Supervisor, Analista, Caixa..."
                                maxLength={50}
                            />
                        </div>
                        <div>
                            <Label>Escopo de Dados *</Label>
                            <Select
                                value={novoCargo.escopo}
                                onValueChange={(v) => setNovoCargo(prev => ({ ...prev, escopo: v }))}
                            >
                                <SelectTrigger className="mt-1">
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    {SCOPE_SELECT_OPTIONS.map(opt => (
                                        <SelectItem key={opt.value} value={opt.value}>{opt.label}</SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                        <div>
                            <Label>Cor de identificação</Label>
                            <div className="flex gap-2 items-center mt-1">
                                <input
                                    type="color"
                                    value={novoCargo.cor}
                                    onChange={(e) => setNovoCargo(prev => ({ ...prev, cor: e.target.value }))}
                                    className="w-10 h-10 rounded cursor-pointer border"
                                />
                                <span className="text-sm text-gray-500">Cor exibida no card do cargo</span>
                            </div>
                        </div>
                        <div>
                            <Label htmlFor="descricao-cargo">Descrição (opcional)</Label>
                            <Input
                                id="descricao-cargo"
                                value={novoCargo.descricao}
                                onChange={(e) => setNovoCargo(prev => ({ ...prev, descricao: e.target.value }))}
                                placeholder="Responsabilidades principais..."
                                maxLength={120}
                            />
                        </div>
                    </div>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setCriarCargoOpen(false)}>
                            Cancelar
                        </Button>
                        <Button
                            onClick={() => createCargoMutation.mutate(novoCargo)}
                            disabled={!novoCargo.nome.trim() || createCargoMutation.isPending}
                            style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
                        >
                            {createCargoMutation.isPending && (
                                <Loader2 className="w-4 h-4 animate-spin mr-2" />
                            )}
                            Criar Cargo
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* ── Modal: Confirmar Exclusão ── */}
            <Dialog open={!!confirmarExcluir} onOpenChange={() => setConfirmarExcluir(null)}>
                <DialogContent className="max-w-sm">
                    <DialogHeader>
                        <DialogTitle>Excluir Cargo</DialogTitle>
                        <DialogDescription>
                            Tem certeza que deseja excluir o cargo{' '}
                            <strong>&quot;{confirmarExcluir}&quot;</strong>?
                            Usuários com este cargo perderão as permissões associadas.
                        </DialogDescription>
                    </DialogHeader>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setConfirmarExcluir(null)}>
                            Cancelar
                        </Button>
                        <Button
                            variant="destructive"
                            onClick={() => deleteCargoMutation.mutate(confirmarExcluir)}
                            disabled={deleteCargoMutation.isPending}
                        >
                            {deleteCargoMutation.isPending && (
                                <Loader2 className="w-4 h-4 animate-spin mr-2" />
                            )}
                            Excluir
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* ── Modal: Editar Permissões do Cargo ── */}
            {editingCargo && (
                <RolePermissionEditorModal
                    cargo={editingCargo.value}
                    cargoLabel={editingCargo.label}
                    cargoColor={editingCargo.color}
                    currentPermissions={getCargoPermissions(editingCargo.value)}
                    currentDenied={getCargoDenied(editingCargo.value)}
                    currentScope={editingCargo.scope}
                    isCustomCargo={editingCargo.isCustom}
                    onClose={() => setEditingCargo(null)}
                    onSave={handleSavePermissions}
                    isSaving={savePermissionsMutation.isPending}
                />
            )}
        </div>
    );
}

import React, { useMemo, useState, createElement } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { base44 } from "@/api/base44Client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import {
    Table, TableBody, TableCell, TableHead, TableHeader, TableRow
} from "@/components/ui/table";
import {
    Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle
} from "@/components/ui/dialog";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Checkbox } from "@/components/ui/checkbox";
import {
    Search, KeyRound, UserCheck, UserX, RotateCcw, Shield,
    Clock, CheckCircle2, AlertCircle, Loader2, Copy, Eye, EyeOff,
    Users, Edit, Store, TrendingUp, Trash2, Lock, Unlock
} from "lucide-react";
import { getZapApiUrl } from '../../utils/zapApiUrl';
import { CARGOS, getCargoConfig } from "@/config/cargos";
import { useLojas } from "@/hooks/useLojas";
import { toast } from "sonner";
import CargosMultiSelect from "./CargosMultiSelect";

import { supabase, supabaseUrl, supabaseKey } from "@/lib/supabase";

const API_URL = getZapApiUrl();

export default function GestaoFuncionarios({ currentUser }) {
    const [searchTerm, setSearchTerm] = useState("");
    const [filterStatus, setFilterStatus] = useState("all");
    const [filterCargo, setFilterCargo] = useState("all");

    // Estados dos modais
    const [selectedUser, setSelectedUser] = useState(null);
    const [modalType, setModalType] = useState(null); // 'create' | 'reset' | 'toggle' | 'edit' | 'cargo'
    const [showPassword, setShowPassword] = useState(false);
    const [generatedPassword, setGeneratedPassword] = useState(null);
    const [generatedMatricula, setGeneratedMatricula] = useState(null);
    const [linkColaboradorId, setLinkColaboradorId] = useState("none");

    // Estado de edição
    const [editData, setEditData] = useState(null);

    const queryClient = useQueryClient();
    const { data: lojasReal = [] } = useLojas();
    const { data: users = [], isLoading } = useQuery({
        queryKey: ['funcionarios-gestao'],
        queryFn: async () => {
            const allUsers = await base44.entities.User.list('-ultimo_login');
            // Funcionários: tem cargo legado OU tem cargos[], excluindo clientes puros
            return allUsers.filter(u => {
                if (u.status_aprovacao !== 'Aprovado') return false;
                const hasCargos = Array.isArray(u.cargos) && u.cargos.length > 0;
                const hasLegacyCargo = u.cargo && !['Cliente'].includes(u.cargo);
                return hasCargos || hasLegacyCargo;
            });
        }
    });

    const { data: colaboradores = [] } = useQuery({
        queryKey: ['colaboradores'],
        queryFn: () => base44.entities.Colaborador.list('-created_at')
    });

    // Cargos customizados do banco (para exibir no CargosMultiSelect)
    const { data: rolePermissions = [] } = useQuery({
        queryKey: ['role_permissions'],
        queryFn: () => base44.entities.RolePermission.list()
    });
    const customCargos = useMemo(() =>
        rolePermissions
            .filter(r => r.is_custom)
            .map(r => ({ value: r.cargo, label: r.label || r.cargo, color: r.color || '#6b7280' })),
        [rolePermissions]
    );

    // [FEATURE] Real-time updates
    React.useEffect(() => {
        const channel = supabase
            .channel('public_users_gestao')
            .on(
                'postgres_changes',
                { event: '*', schema: 'public', table: 'public_users' },
                (payload) => {
                    console.log('Realtime update:', payload);
                    queryClient.invalidateQueries({ queryKey: ['funcionarios-gestao'] });
                }
            )
            .subscribe();

        return () => {
            supabase.removeChannel(channel);
        };
    }, [queryClient]);

    // Helper: garantir token fresco (força refresh para evitar token expirado no cache)
    const getFreshAccessToken = async () => {
        // Sempre tenta refresh primeiro para garantir token válido
        const { data: refreshData, error: refreshError } = await supabase.auth.refreshSession();
        if (refreshData?.session) {
            return refreshData.session.access_token;
        }
        // Se refresh falhar, tenta getSession como fallback
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.access_token) {
            return session.access_token;
        }
        throw new Error('Sessão expirada. Faça login novamente.');
    };

    // Mutation para criar credenciais
    const createCredentialsMutation = useMutation({
        mutationFn: async (userId) => {
            const accessToken = await getFreshAccessToken();

            // Chamar Edge Function via fetch direto (garante Authorization header correto)
            const fnUrl = `${supabaseUrl}/functions/v1/admin-actions`;
            const response = await fetch(fnUrl, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${accessToken}`,
                    'apikey': supabaseKey
                },
                body: JSON.stringify({ action: 'create_credentials', user_id: userId })
            });

            const data = await response.json();
            if (data?.error) throw new Error(data.error);

            return data;
        },
        onSuccess: (data) => {
            setGeneratedMatricula(data.matricula);
            setGeneratedPassword(data.senha_temporaria);
            queryClient.invalidateQueries({ queryKey: ['funcionarios-gestao'] });
            toast.success("Acesso ativado com sucesso!");
        },
        onError: (error) => {
            console.error("Erro Criação Credenciais:", error); // DEBUG
            toast.error(error.message);
            handleCloseModal();
        }
    });

    // Mutation para resetar senha
    const resetPasswordMutation = useMutation({
        mutationFn: async (userId) => {
            const accessToken = await getFreshAccessToken();

            // Chamar Edge Function via fetch direto (garante Authorization header correto)
            const fnUrl = `${supabaseUrl}/functions/v1/admin-actions`;
            const response = await fetch(fnUrl, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${accessToken}`,
                    'apikey': supabaseKey
                },
                body: JSON.stringify({ action: 'reset_password', user_id: userId })
            });

            const data = await response.json();
            if (data?.error) throw new Error(data.error);

            return data;
        },
        onSuccess: (data) => {
            setGeneratedPassword(data.senha_temporaria);
            setGeneratedMatricula(selectedUser?.matricula);
            queryClient.invalidateQueries({ queryKey: ['funcionarios-gestao'] });

            toast.success(data.whatsapp_enviado
                ? "Senha resetada e enviada via WhatsApp!"
                : "Senha resetada! (WhatsApp não disponível)");
        },
        onError: (error) => {
            console.error("Erro Reset Senha:", error); // DEBUG
            toast.error(error.message);
            handleCloseModal();
        }
    });

    // Mutation para ativar/desativar conta
    const toggleAccountMutation = useMutation({
        mutationFn: async ({ userId, ativo }) => {
            await base44.entities.User.update(userId, { ativo });
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['funcionarios-gestao'] });
            toast.success(selectedUser?.ativo === false ? "Acesso desbloqueado!" : "Acesso bloqueado!");
            handleCloseModal();
        },
        onError: (error) => {
            toast.error("Erro ao alterar status: " + error.message);
        }
    });


    // Mutation para editar funcionário
    const updateUserMutation = useMutation({
        mutationFn: async ({ userId, updates }) => {
            // 1. Update User record
            await base44.entities.User.update(userId, updates);

            // 2. Sync with Colaborador if exists
            if (updates.cargo || updates.cargos || updates.full_name) {
                try {
                    const cols = await base44.entities.Colaborador.list();
                    const colab = cols.find(c => c.user_id === userId);
                    if (colab) {
                        await base44.entities.Colaborador.update(colab.id, {
                            cargo: updates.cargo || colab.cargo,
                            cargos: updates.cargos || colab.cargos,
                            nome_completo: updates.full_name || colab.nome_completo
                        });
                    }
                } catch (syncError) {
                    console.error("Erro ao sincronizar com Colaborador:", syncError);
                }
            }
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['funcionarios-gestao'] });
            queryClient.invalidateQueries({ queryKey: ['colaboradores'] }); // Invalidate colabs too
            toast.success("Funcionário atualizado!");
            handleCloseModal();
        },
        onError: (error) => {
            toast.error("Erro: " + error.message);
        }
    });

    // Mutation para deletar usuário
    const deleteUserMutation = useMutation({
        mutationFn: async (userId) => {
            const { error } = await supabase.rpc('delete_user_from_auth', { user_id: userId });
            if (error) throw error;
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['funcionarios-gestao'] });
            toast.success("Funcionário removido!");
        },
        onError: (error) => toast.error("Erro ao remover funcionário: " + error.message)
    });

    const linkColaboradorMutation = useMutation({
        mutationFn: async ({ userId, colaboradorId }) => {
            const colaboradorAtual = colaboradores.find((c) => c.user_id === userId);

            if (colaboradorId === 'none') {
                if (colaboradorAtual) {
                    await base44.entities.Colaborador.update(colaboradorAtual.id, { user_id: null });
                }
                return;
            }

            const colaboradorDestino = colaboradores.find((c) => c.id === colaboradorId);
            if (!colaboradorDestino) {
                throw new Error('Colaborador não encontrado para vínculo.');
            }

            if (colaboradorDestino.user_id && colaboradorDestino.user_id !== userId) {
                throw new Error('Este colaborador já está vinculado a outro usuário.');
            }

            if (colaboradorAtual && colaboradorAtual.id !== colaboradorDestino.id) {
                await base44.entities.Colaborador.update(colaboradorAtual.id, { user_id: null });
            }

            await base44.entities.Colaborador.update(colaboradorDestino.id, { user_id: userId });
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['funcionarios-gestao'] });
            queryClient.invalidateQueries({ queryKey: ['colaboradores'] });
            queryClient.invalidateQueries({ queryKey: ['usuarios'] });
            toast.success('Vínculo de funcionário atualizado com sucesso.');
            handleCloseModal();
        },
        onError: (error) => {
            toast.error(error.message || 'Erro ao atualizar vínculo do funcionário.');
        }
    });

    const getLinkedColaborador = (userId) => colaboradores.find((c) => c.user_id === userId);

    const colaboradoresDisponiveisParaUsuario = useMemo(() => {
        if (!selectedUser) return [];

        return colaboradores.filter((c) => !c.user_id || c.user_id === selectedUser.id);
    }, [colaboradores, selectedUser]);

    // Filtrar usuários
    const filteredUsers = users.filter(user => {
        const matchesSearch =
            user.full_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            user.email?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            user.matricula?.toLowerCase().includes(searchTerm.toLowerCase());

        let matchesStatus = true;
        if (filterStatus === 'with') matchesStatus = !!user.matricula && user.ativo !== false;
        if (filterStatus === 'without') matchesStatus = !user.matricula;
        if (filterStatus === 'inactive') matchesStatus = user.ativo === false;

        let matchesCargo = true;
        if (filterCargo !== 'all') {
            const userCargos = Array.isArray(user.cargos) && user.cargos.length > 0
                ? user.cargos
                : (user.cargo ? [user.cargo] : []);
            matchesCargo = userCargos.includes(filterCargo);
        }

        return matchesSearch && matchesStatus && matchesCargo;
    });

    // Estatísticas
    const stats = {
        total: users.length,
        withAccess: users.filter(u => u.matricula && u.ativo !== false).length,
        withoutAccess: users.filter(u => !u.matricula).length,
        inactive: users.filter(u => u.ativo === false).length
    };

    const handleOpenModal = (user, type) => {
        setSelectedUser(user);
        setModalType(type);
        setGeneratedPassword(null);
        setGeneratedMatricula(null);
        setShowPassword(false);
        if (type === 'edit' || type === 'cargo') {
            // Normaliza cargos[]: usa array existente ou converte cargo legado
            const cargosNorm = Array.isArray(user.cargos) && user.cargos.length > 0
                ? user.cargos
                : (user.cargo ? [user.cargo] : []);
            setEditData({
                full_name: user.full_name || '',
                cargos: cargosNorm,
                cargo: user.cargo || '',        // mantido para compatibilidade no editCargoConfig
                loja: user.loja || '',
                is_vendedor: user.is_vendedor || false,
                meta_mensal: user.meta_mensal || 0
            });
        }
        if (type === 'link') {
            const colaboradorVinculado = colaboradores.find((c) => c.user_id === user.id);
            setLinkColaboradorId(colaboradorVinculado?.id || 'none');
        }
    };

    // Config do cargo principal (primeiro do array) para exibição de info no modal
    const editCargoConfig = editData?.cargos?.length > 0 ? getCargoConfig(editData.cargos[0]) : null;

    const handleCloseModal = () => {
        setModalType(null);
        setSelectedUser(null);
        setGeneratedPassword(null);
        setGeneratedMatricula(null);
        setShowPassword(false);
        setEditData(null);
        setLinkColaboradorId('none');
    };

    const handleSaveEdit = () => {
        if (!selectedUser || !editData) return;
        const cargos = editData.cargos || [];
        const primaryCargo = cargos[0] || '';
        const primaryCargoConfig = primaryCargo ? getCargoConfig(primaryCargo) : null;
        // Qualquer cargo no array que exige loja?
        const anyRequiresStore = cargos.some(c => getCargoConfig(c)?.requiresStore);
        updateUserMutation.mutate({
            userId: selectedUser.id,
            updates: {
                full_name:   editData.full_name,
                cargos:      cargos,
                cargo:       primaryCargo,          // campo legado = primeiro cargo
                loja:        anyRequiresStore ? editData.loja : null,
                is_vendedor: editData.is_vendedor,
                meta_mensal: editData.is_vendedor ? parseFloat(editData.meta_mensal) || 0 : 0
            }
        });
    };

    const handleDeleteUser = (user) => {
        if (user.id === currentUser?.id) {
            toast.error("Você não pode remover sua própria conta");
            return;
        }
        if (confirm(`⚠️ REMOVER "${user.full_name}" permanentemente?\n\nEsta ação não pode ser desfeita!`)) {
            deleteUserMutation.mutate(user.id);
        }
    };

    const copyToClipboard = (text, label) => {
        navigator.clipboard.writeText(text);
        toast.success(`${label} copiado!`);
    };

    const getStatusBadge = (user) => {
        if (!user.matricula) {
            return (
                <Badge variant="outline" className="bg-gray-50 text-gray-600">
                    <AlertCircle className="w-3 h-3 mr-1" />
                    Sem Acesso
                </Badge>
            );
        }
        if (user.ativo === false) {
            return (
                <Badge className="bg-red-100 text-red-700">
                    <Lock className="w-3 h-3 mr-1" />
                    Bloqueado
                </Badge>
            );
        }
        if (user.primeiro_acesso) {
            return (
                <Badge className="bg-yellow-100 text-yellow-700">
                    <Clock className="w-3 h-3 mr-1" />
                    Aguardando 1º Acesso
                </Badge>
            );
        }
        return (
            <Badge className="bg-green-100 text-green-700">
                <CheckCircle2 className="w-3 h-3 mr-1" />
                Ativo
            </Badge>
        );
    };

    return (
        <div className="space-y-6">
            {/* Header */}
            <div>
                <h2 className="text-xl font-bold text-gray-900 flex items-center gap-2">
                    <Users className="w-5 h-5 text-green-600" />
                    Gestão de Funcionários
                </h2>
                <p className="text-gray-500 text-sm mt-1">
                    Gerencie os acessos, cargos e permissões dos funcionários do sistema
                </p>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-4 gap-4">
                <Card className="border-0 shadow-sm">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-sm text-gray-500">Total</p>
                                <p className="text-2xl font-bold" style={{ color: '#07593f' }}>{stats.total}</p>
                            </div>
                            <Users className="w-8 h-8 text-gray-200" />
                        </div>
                    </CardContent>
                </Card>
                <Card className="border-0 shadow-sm">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-sm text-gray-500">Com Acesso</p>
                                <p className="text-2xl font-bold text-green-600">{stats.withAccess}</p>
                            </div>
                            <UserCheck className="w-8 h-8 text-green-100" />
                        </div>
                    </CardContent>
                </Card>
                <Card className="border-0 shadow-sm">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-sm text-gray-500">Sem Acesso</p>
                                <p className="text-2xl font-bold text-gray-600">{stats.withoutAccess}</p>
                            </div>
                            <AlertCircle className="w-8 h-8 text-gray-100" />
                        </div>
                    </CardContent>
                </Card>
                <Card className="border-0 shadow-sm">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-sm text-gray-500">Desativados</p>
                                <p className="text-2xl font-bold text-red-600">{stats.inactive}</p>
                            </div>
                            <UserX className="w-8 h-8 text-red-100" />
                        </div>
                    </CardContent>
                </Card>
            </div>

            {/* Filters */}
            <Card className="border-0 shadow-lg">
                <CardContent className="p-4">
                    <div className="flex gap-4">
                        <div className="flex-1 relative">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                            <Input
                                placeholder="Buscar por nome, email ou matrícula..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="pl-10"
                            />
                        </div>
                        <Select value={filterStatus} onValueChange={setFilterStatus}>
                            <SelectTrigger className="w-40">
                                <SelectValue placeholder="Status" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="all">Todos</SelectItem>
                                <SelectItem value="with">Com Acesso</SelectItem>
                                <SelectItem value="without">Sem Acesso</SelectItem>
                                <SelectItem value="inactive">Desativados</SelectItem>
                            </SelectContent>
                        </Select>
                        <Select value={filterCargo} onValueChange={setFilterCargo}>
                            <SelectTrigger className="w-40">
                                <SelectValue placeholder="Cargo" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="all">Todos Cargos</SelectItem>
                                {CARGOS.filter(c => c.value !== 'Pendente Definição').map(c => (
                                    <SelectItem key={c.value} value={c.value}>{c.label}</SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </div>
                </CardContent>
            </Card>

            {/* Table */}
            {isLoading ? (
                <div className="flex justify-center py-12">
                    <Loader2 className="w-8 h-8 animate-spin text-green-700" />
                </div>
            ) : (
                <Card className="border-0 shadow-lg">
                    <CardHeader className="pb-0">
                        <CardTitle className="text-lg">Funcionários ({filteredUsers.length})</CardTitle>
                    </CardHeader>
                    <CardContent>
                        <Table>
                            <TableHeader>
                                <TableRow>
                                    <TableHead>Funcionário</TableHead>
                                    <TableHead>Cargo / Loja</TableHead>
                                    <TableHead>Matrícula</TableHead>
                                    <TableHead>Status</TableHead>
                                    <TableHead>Último Login</TableHead>
                                    <TableHead className="text-right">Ações</TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {filteredUsers.map((user) => {
                                    // Normaliza cargos para exibição
                                    const userCargos = Array.isArray(user.cargos) && user.cargos.length > 0
                                        ? user.cargos
                                        : (user.cargo ? [user.cargo] : []);
                                    const primaryCargo = userCargos[0];
                                    const primaryCargoConfig = primaryCargo ? getCargoConfig(primaryCargo) : null;
                                    const colaboradorVinculado = getLinkedColaborador(user.id);
                                    return (
                                        <TableRow key={user.id}>
                                            <TableCell>
                                                <div className="flex items-center gap-3">
                                                    <div
                                                        className="w-10 h-10 rounded-full flex items-center justify-center font-semibold"
                                                        style={{
                                                            backgroundColor: primaryCargoConfig?.bgColor || '#f3f4f6',
                                                            color: primaryCargoConfig?.color || '#6b7280'
                                                        }}
                                                    >
                                                        {user.full_name?.charAt(0).toUpperCase() || 'U'}
                                                    </div>
                                                    <div>
                                                        <p className="font-semibold text-sm">{user.full_name || 'Sem nome'}</p>
                                                        <p className="text-xs text-gray-500">{user.email}</p>
                                                        <p className="text-xs text-gray-400">
                                                            Funcionário RH: {colaboradorVinculado?.nome_completo || 'Não vinculado'}
                                                        </p>
                                                    </div>
                                                </div>
                                            </TableCell>
                                            <TableCell>
                                                <div className="space-y-1">
                                                    {/* Exibe até 2 badges de cargo + "..." se tiver mais */}
                                                    <div className="flex flex-wrap gap-1">
                                                        {userCargos.slice(0, 2).map(cargoVal => {
                                                            const cfg = getCargoConfig(cargoVal);
                                                            return cfg ? (
                                                                <Badge
                                                                    key={cargoVal}
                                                                    className="text-xs"
                                                                    style={{
                                                                        backgroundColor: `${cfg.color}15`,
                                                                        color: cfg.color,
                                                                        border: `1px solid ${cfg.color}40`
                                                                    }}
                                                                >
                                                                    {createElement(cfg.icon, { className: "w-3 h-3 mr-1" })}
                                                                    {cfg.label}
                                                                </Badge>
                                                            ) : (
                                                                <Badge key={cargoVal} variant="outline" className="text-xs">{cargoVal}</Badge>
                                                            );
                                                        })}
                                                        {userCargos.length > 2 && (
                                                            <Badge variant="outline" className="text-xs text-gray-500">
                                                                +{userCargos.length - 2}
                                                            </Badge>
                                                        )}
                                                    </div>
                                                    {user.loja && (
                                                        <div className="flex items-center gap-1 text-xs text-gray-500">
                                                            <Store className="w-3 h-3" />
                                                            {user.loja}
                                                        </div>
                                                    )}
                                                </div>
                                            </TableCell>
                                            <TableCell>
                                                {user.matricula ? (
                                                    <code className="px-2 py-1 bg-gray-100 rounded text-sm font-mono">
                                                        {user.matricula}
                                                    </code>
                                                ) : (
                                                    <span className="text-gray-400 text-sm">—</span>
                                                )}
                                            </TableCell>
                                            <TableCell>{getStatusBadge(user)}</TableCell>
                                            <TableCell>
                                                {user.ultimo_login ? (
                                                    <span className="text-xs text-gray-600">
                                                        {new Date(user.ultimo_login).toLocaleDateString('pt-BR', {
                                                            day: '2-digit',
                                                            month: '2-digit',
                                                            hour: '2-digit',
                                                            minute: '2-digit'
                                                        })}
                                                    </span>
                                                ) : (
                                                    <span className="text-gray-400 text-xs">Nunca</span>
                                                )}
                                            </TableCell>
                                            <TableCell>
                                                <div className="flex justify-end gap-1">
                                                    {!user.matricula ? (
                                                        <Button
                                                            size="sm"
                                                            className="h-8 bg-green-600 hover:bg-green-700"
                                                            onClick={() => handleOpenModal(user, 'create')}
                                                        >
                                                            <KeyRound className="w-4 h-4 mr-1" />
                                                            Ativar Acesso
                                                        </Button>
                                                    ) : (
                                                        <>
                                                            <Button
                                                                size="sm"
                                                                variant="outline"
                                                                className="h-8"
                                                                onClick={() => handleOpenModal(user, 'reset')}
                                                                title="Resetar / Exigir Troca de Senha"
                                                            >
                                                                <RotateCcw className="w-4 h-4" />
                                                            </Button>
                                                            <Button
                                                                size="sm"
                                                                variant={user.ativo === false ? "default" : "destructive"}
                                                                className={`h-8 ${user.ativo === false ? 'bg-green-600 hover:bg-green-700' : ''}`}
                                                                onClick={() => handleOpenModal(user, 'toggle')}
                                                                title={user.ativo === false ? "Desbloquear Acesso" : "Bloquear Acesso"}
                                                            >
                                                                {user.ativo === false ? (
                                                                    <Unlock className="w-4 h-4" />
                                                                ) : (
                                                                    <Lock className="w-4 h-4" />
                                                                )}
                                                            </Button>
                                                        </>
                                                    )}
                                                    <Button
                                                        size="sm"
                                                        variant="outline"
                                                        className="h-8"
                                                        onClick={() => handleOpenModal(user, 'link')}
                                                        title="Vincular Funcionário RH"
                                                    >
                                                        <Users className="w-4 h-4" />
                                                    </Button>
                                                    <Button
                                                        size="sm"
                                                        variant="outline"
                                                        className="h-8"
                                                        onClick={() => handleOpenModal(user, 'cargo')}
                                                        title="Alterar Cargo"
                                                    >
                                                        <Shield className="w-4 h-4" />
                                                    </Button>
                                                    <Button
                                                        size="sm"
                                                        variant="outline"
                                                        className="h-8"
                                                        onClick={() => handleOpenModal(user, 'edit')}
                                                        title="Editar"
                                                    >
                                                        <Edit className="w-4 h-4" />
                                                    </Button>
                                                    {currentUser?.cargo === 'Administrador' && user.id !== currentUser?.id && (
                                                        <Button
                                                            size="sm"
                                                            variant="ghost"
                                                            className="h-8 text-red-600 hover:text-red-700 hover:bg-red-50"
                                                            onClick={() => handleDeleteUser(user)}
                                                            title="Remover"
                                                        >
                                                            <Trash2 className="w-4 h-4" />
                                                        </Button>
                                                    )}
                                                </div>
                                            </TableCell>
                                        </TableRow>
                                    );
                                })}
                            </TableBody>
                        </Table>
                        {filteredUsers.length === 0 && (
                            <div className="text-center py-12 text-gray-500">
                                <Users className="w-12 h-12 mx-auto mb-3 opacity-20" />
                                <p>Nenhum funcionário encontrado</p>
                            </div>
                        )}
                    </CardContent>
                </Card>
            )}

            {/* Modal: Ativar Acesso */}
            <Dialog open={modalType === 'link'} onOpenChange={handleCloseModal}>
                <DialogContent className="max-w-md">
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-2">
                            <Users className="w-5 h-5 text-blue-600" />
                            Vincular Funcionário RH
                        </DialogTitle>
                        <DialogDescription>
                            Selecione o funcionário de RH correspondente a {selectedUser?.full_name}.
                        </DialogDescription>
                    </DialogHeader>

                    <div className="py-4 space-y-4">
                        <Alert className="bg-blue-50 border-blue-200">
                            <AlertCircle className="w-4 h-4 text-blue-600" />
                            <AlertDescription className="text-blue-800">
                                Este vínculo conecta o cadastro de acesso ao cadastro de colaborador do RH.
                            </AlertDescription>
                        </Alert>

                        <div className="space-y-2">
                            <Label>Funcionário RH</Label>
                            <Select value={linkColaboradorId} onValueChange={setLinkColaboradorId}>
                                <SelectTrigger>
                                    <SelectValue placeholder="Selecione um funcionário" />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="none">Sem vínculo</SelectItem>
                                    {colaboradoresDisponiveisParaUsuario.map((colaborador) => (
                                        <SelectItem key={colaborador.id} value={colaborador.id}>
                                            {colaborador.nome_completo} {colaborador.cargo ? `- ${colaborador.cargo}` : ''}
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                    </div>

                    <DialogFooter>
                        <Button variant="outline" onClick={handleCloseModal}>Cancelar</Button>
                        <Button
                            onClick={() => linkColaboradorMutation.mutate({ userId: selectedUser?.id, colaboradorId: linkColaboradorId })}
                            disabled={linkColaboradorMutation.isPending}
                            className="bg-blue-600 hover:bg-blue-700"
                        >
                            {linkColaboradorMutation.isPending && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
                            Salvar Vínculo
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* Modal: Ativar Acesso */}
            <Dialog open={modalType === 'create'} onOpenChange={() => !generatedPassword && handleCloseModal()}>
                <DialogContent className="max-w-md">
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-2">
                            <KeyRound className="w-5 h-5 text-green-600" />
                            Ativar Acesso ao Sistema
                        </DialogTitle>
                        <DialogDescription>
                            Criar credenciais para {selectedUser?.full_name}
                        </DialogDescription>
                    </DialogHeader>

                    {!generatedPassword ? (
                        <>
                            <div className="py-4 space-y-4">
                                <Alert className="bg-blue-50 border-blue-200">
                                    <AlertCircle className="w-4 h-4 text-blue-600" />
                                    <AlertDescription className="text-blue-800">
                                        Será gerada uma <strong>matrícula única</strong> e uma <strong>senha temporária</strong>.
                                        O funcionário deverá trocar a senha no primeiro acesso.
                                    </AlertDescription>
                                </Alert>

                                <div className="p-4 bg-gray-50 rounded-lg">
                                    <p className="text-sm text-gray-600">Funcionário:</p>
                                    <p className="font-semibold">{selectedUser?.full_name}</p>
                                    <p className="text-sm text-gray-500">{selectedUser?.cargo} {selectedUser?.loja ? `- ${selectedUser.loja}` : ''}</p>
                                </div>
                            </div>

                            <DialogFooter>
                                <Button variant="outline" onClick={handleCloseModal}>Cancelar</Button>
                                <Button
                                    onClick={() => createCredentialsMutation.mutate(selectedUser?.id)}
                                    disabled={createCredentialsMutation.isPending}
                                    className="bg-green-600 hover:bg-green-700"
                                >
                                    {createCredentialsMutation.isPending && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
                                    Ativar Acesso
                                </Button>
                            </DialogFooter>
                        </>
                    ) : (
                        <>
                            <div className="py-4 space-y-4">
                                <Alert className="bg-green-50 border-green-200">
                                    <CheckCircle2 className="w-4 h-4 text-green-600" />
                                    <AlertDescription className="text-green-800">
                                        Acesso ativado com sucesso! Anote os dados abaixo:
                                    </AlertDescription>
                                </Alert>

                                <div className="space-y-3">
                                    <div className="p-3 bg-gray-50 rounded-lg">
                                        <p className="text-xs text-gray-500 mb-1">Matrícula</p>
                                        <div className="flex items-center justify-between">
                                            <code className="text-lg font-mono font-bold">{generatedMatricula}</code>
                                            <Button size="sm" variant="ghost" onClick={() => copyToClipboard(generatedMatricula, 'Matrícula')}>
                                                <Copy className="w-4 h-4" />
                                            </Button>
                                        </div>
                                    </div>

                                    <div className="p-3 bg-gray-50 rounded-lg">
                                        <p className="text-xs text-gray-500 mb-1">Senha Temporária</p>
                                        <div className="flex items-center justify-between">
                                            <code className="text-lg font-mono font-bold">
                                                {showPassword ? generatedPassword : '••••••••'}
                                            </code>
                                            <div className="flex gap-1">
                                                <Button size="sm" variant="ghost" onClick={() => setShowPassword(!showPassword)}>
                                                    {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                                                </Button>
                                                <Button size="sm" variant="ghost" onClick={() => copyToClipboard(generatedPassword, 'Senha')}>
                                                    <Copy className="w-4 h-4" />
                                                </Button>
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                <Alert className="bg-yellow-50 border-yellow-200">
                                    <AlertCircle className="w-4 h-4 text-yellow-600" />
                                    <AlertDescription className="text-yellow-800 text-sm">
                                        <strong>Importante:</strong> Anote esses dados! A senha não poderá ser visualizada novamente.
                                    </AlertDescription>
                                </Alert>
                            </div>

                            <DialogFooter>
                                <Button onClick={handleCloseModal} className="bg-green-600 hover:bg-green-700">Fechar</Button>
                            </DialogFooter>
                        </>
                    )}
                </DialogContent>
            </Dialog>

            {/* Modal: Resetar Senha */}
            <Dialog open={modalType === 'reset'} onOpenChange={() => !generatedPassword && handleCloseModal()}>
                <DialogContent className="max-w-md">
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-2">
                            <RotateCcw className="w-5 h-5 text-orange-600" />
                            Resetar Senha
                        </DialogTitle>
                        <DialogDescription>
                            Resetar senha de {selectedUser?.full_name}
                        </DialogDescription>
                    </DialogHeader>

                    {!generatedPassword ? (
                        <>
                            <div className="py-4 space-y-4">
                                <Alert className="bg-orange-50 border-orange-200">
                                    <AlertCircle className="w-4 h-4 text-orange-600" />
                                    <AlertDescription className="text-orange-800">
                                        Será gerada uma nova <strong>senha temporária</strong>.
                                        Se o funcionário tiver telefone cadastrado, a nova senha será enviada via WhatsApp.
                                    </AlertDescription>
                                </Alert>

                                <div className="p-4 bg-gray-50 rounded-lg">
                                    <p className="text-sm text-gray-600">Funcionário:</p>
                                    <p className="font-semibold">{selectedUser?.full_name}</p>
                                    <p className="text-sm text-gray-500">Matrícula: {selectedUser?.matricula}</p>
                                </div>
                            </div>

                            <DialogFooter>
                                <Button variant="outline" onClick={handleCloseModal}>Cancelar</Button>
                                <Button
                                    onClick={() => resetPasswordMutation.mutate(selectedUser?.id)}
                                    disabled={resetPasswordMutation.isPending}
                                    className="bg-orange-600 hover:bg-orange-700"
                                >
                                    {resetPasswordMutation.isPending && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
                                    Resetar Senha
                                </Button>
                            </DialogFooter>
                        </>
                    ) : (
                        <>
                            <div className="py-4 space-y-4">
                                <Alert className="bg-green-50 border-green-200">
                                    <CheckCircle2 className="w-4 h-4 text-green-600" />
                                    <AlertDescription className="text-green-800">Senha resetada com sucesso!</AlertDescription>
                                </Alert>

                                <div className="space-y-3">
                                    <div className="p-3 bg-gray-50 rounded-lg">
                                        <p className="text-xs text-gray-500 mb-1">Matrícula</p>
                                        <code className="text-lg font-mono font-bold">{generatedMatricula}</code>
                                    </div>

                                    <div className="p-3 bg-gray-50 rounded-lg">
                                        <p className="text-xs text-gray-500 mb-1">Nova Senha Temporária</p>
                                        <div className="flex items-center justify-between">
                                            <code className="text-lg font-mono font-bold">
                                                {showPassword ? generatedPassword : '••••••••'}
                                            </code>
                                            <div className="flex gap-1">
                                                <Button size="sm" variant="ghost" onClick={() => setShowPassword(!showPassword)}>
                                                    {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                                                </Button>
                                                <Button size="sm" variant="ghost" onClick={() => copyToClipboard(generatedPassword, 'Senha')}>
                                                    <Copy className="w-4 h-4" />
                                                </Button>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <DialogFooter>
                                <Button onClick={handleCloseModal} className="bg-green-600 hover:bg-green-700">Fechar</Button>
                            </DialogFooter>
                        </>
                    )}
                </DialogContent>
            </Dialog>

            {/* Modal: Ativar/Desativar */}
            <Dialog open={modalType === 'toggle'} onOpenChange={handleCloseModal}>
                <DialogContent className="max-w-md">
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-2">
                            {selectedUser?.ativo === false ? (
                                <><Unlock className="w-5 h-5 text-green-600" /> Desbloquear Acesso</>
                            ) : (
                                <><Lock className="w-5 h-5 text-red-600" /> Bloquear Acesso</>
                            )}
                        </DialogTitle>
                    </DialogHeader>

                    <div className="py-4 space-y-4">
                        {selectedUser?.ativo === false ? (
                            <Alert className="bg-green-50 border-green-200">
                                <CheckCircle2 className="w-4 h-4 text-green-600" />
                                <AlertDescription className="text-green-800">
                                    Ao desbloquear, o funcionário poderá fazer login normalmente.
                                </AlertDescription>
                            </Alert>
                        ) : (
                            <Alert className="bg-red-50 border-red-200">
                                <AlertCircle className="w-4 h-4 text-red-600" />
                                <AlertDescription className="text-red-800">
                                    Ao bloquear, o funcionário <strong>não poderá mais fazer login</strong> no sistema.
                                </AlertDescription>
                            </Alert>
                        )}

                        <div className="p-4 bg-gray-50 rounded-lg">
                            <p className="font-semibold">{selectedUser?.full_name}</p>
                            <p className="text-sm text-gray-500">Matrícula: {selectedUser?.matricula}</p>
                        </div>
                    </div>

                    <DialogFooter>
                        <Button variant="outline" onClick={handleCloseModal}>Cancelar</Button>
                        <Button
                            onClick={() => toggleAccountMutation.mutate({ userId: selectedUser?.id, ativo: selectedUser?.ativo === false })}
                            disabled={toggleAccountMutation.isPending}
                            className={selectedUser?.ativo === false ? "bg-green-600 hover:bg-green-700" : "bg-red-600 hover:bg-red-700"}
                        >
                            {toggleAccountMutation.isPending && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
                            {selectedUser?.ativo === false ? 'Desbloquear' : 'Bloquear'}
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>


            {/* Modal: Alterar Cargo (múltiplos cargos) */}
            <Dialog open={modalType === 'cargo'} onOpenChange={handleCloseModal}>
                <DialogContent className="max-w-lg">
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-2">
                            <Shield className="w-5 h-5 text-green-700" />
                            Alterar Cargos
                        </DialogTitle>
                        <DialogDescription>
                            Selecione um ou mais cargos para {selectedUser?.full_name}.
                            O primeiro cargo da lista será o principal.
                        </DialogDescription>
                    </DialogHeader>

                    <div className="py-2 space-y-4">
                        <CargosMultiSelect
                            value={editData?.cargos || []}
                            onChange={(cargos) => setEditData(prev => ({ ...prev, cargos }))}
                            extraCargos={customCargos}
                        />

                        {/* Loja: exibe se qualquer cargo selecionado exigir loja */}
                        {editData?.cargos?.some(c => getCargoConfig(c)?.requiresStore) && (
                            <div className="space-y-2">
                                <Label>Loja</Label>
                                <Select
                                    value={editData?.loja}
                                    onValueChange={(val) => setEditData({ ...editData, loja: val })}
                                >
                                    <SelectTrigger>
                                        <SelectValue placeholder="Selecione a loja" />
                                    </SelectTrigger>
                                    <SelectContent>
                                        {lojasReal.map(loja => (
                                            <SelectItem key={loja.id} value={loja.nome}>{loja.nome}</SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                            </div>
                        )}

                        <div className="flex items-center space-x-2 p-2 bg-gray-50 rounded-lg">
                            <Checkbox
                                id="is_vendedor_quick"
                                checked={editData?.is_vendedor}
                                onCheckedChange={(val) => setEditData({ ...editData, is_vendedor: val })}
                            />
                            <Label htmlFor="is_vendedor_quick" className="text-sm cursor-pointer">Atua como Vendedor (comissões)</Label>
                        </div>
                    </div>

                    <DialogFooter>
                        <Button variant="outline" onClick={handleCloseModal}>Cancelar</Button>
                        <Button
                            onClick={handleSaveEdit}
                            disabled={updateUserMutation.isPending || !editData?.cargos?.length}
                            className="bg-green-700 hover:bg-green-800"
                        >
                            {updateUserMutation.isPending && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
                            Salvar Cargos
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* Modal: Editar Funcionário */}
            <Dialog open={modalType === 'edit'} onOpenChange={handleCloseModal}>
                <DialogContent className="max-w-lg">
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-2">
                            <Edit className="w-5 h-5 text-blue-600" />
                            Editar Funcionário
                        </DialogTitle>
                    </DialogHeader>

                    {editData && (
                        <div className="space-y-4 py-4 overflow-y-auto max-h-[70vh] pr-1">
                            <div>
                                <Label>Nome Completo</Label>
                                <Input
                                    value={editData.full_name}
                                    onChange={(e) => setEditData({ ...editData, full_name: e.target.value })}
                                />
                            </div>

                            <div>
                                <Label>E-mail</Label>
                                <Input value={selectedUser?.email || ''} disabled className="bg-gray-50" />
                            </div>

                            <div>
                                <Label className="mb-2 block">Cargos</Label>
                                <CargosMultiSelect
                                    value={editData.cargos || []}
                                    onChange={(cargos) => setEditData(prev => ({
                                        ...prev,
                                        cargos,
                                        is_vendedor: cargos.includes('Vendedor') ? true : prev.is_vendedor
                                    }))}
                                    extraCargos={customCargos}
                                />
                            </div>

                            {/* Loja: exibe se qualquer cargo selecionado exigir loja */}
                            {editData.cargos?.some(c => getCargoConfig(c)?.requiresStore) && (
                                <div>
                                    <Label>Loja</Label>
                                    <Select
                                        value={editData.loja}
                                        onValueChange={(v) => setEditData({ ...editData, loja: v })}
                                    >
                                        <SelectTrigger><SelectValue placeholder="Selecione a loja" /></SelectTrigger>
                                        <SelectContent>
                                            {lojasReal.map(l => (
                                                <SelectItem key={l.id} value={l.nome}>{l.nome}</SelectItem>
                                            ))}
                                        </SelectContent>
                                    </Select>
                                </div>
                            )}

                            <div className="p-4 rounded-xl bg-blue-50 border-2 border-blue-200">
                                <div className="flex items-start gap-3">
                                    <Checkbox
                                        checked={editData.is_vendedor}
                                        onCheckedChange={(v) => setEditData({ ...editData, is_vendedor: v })}
                                    />
                                    <div>
                                        <Label className="cursor-pointer font-semibold text-blue-700">Atua como Vendedor</Label>
                                        <p className="text-xs text-gray-500 mt-1">Incluído no cálculo de comissões</p>
                                    </div>
                                </div>
                                {editData.is_vendedor && (
                                    <div className="mt-3">
                                        <Label>Meta Mensal (R$)</Label>
                                        <Input
                                            type="number"
                                            value={editData.meta_mensal}
                                            onChange={(e) => setEditData({ ...editData, meta_mensal: parseFloat(e.target.value) || 0 })}
                                        />
                                    </div>
                                )}
                            </div>
                        </div>
                    )}

                    <DialogFooter>
                        <Button variant="outline" onClick={handleCloseModal}>Cancelar</Button>
                        <Button
                            onClick={handleSaveEdit}
                            disabled={updateUserMutation.isPending || !editData?.cargos?.length}
                            className="bg-blue-600 hover:bg-blue-700"
                        >
                            {updateUserMutation.isPending && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
                            Salvar
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
}

import React, { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { base44 } from "@/api/base44Client";
import { useTenant } from "@/contexts/TenantContext";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Store, Plus, Pencil, Trash2, MapPin, Loader2, Building2, Search, Phone, Mail, FileText } from "lucide-react";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";

const INITIAL_FORM_DATA = {
    nome: "",
    cnpj: "",
    endereco: "",
    cidade: "",
    estado: "",
    cep: "",
    telefone: ""
};

export default function GestaoLojas() {
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingLoja, setEditingLoja] = useState(null);
    const [formData, setFormData] = useState(INITIAL_FORM_DATA);
    const [error, setError] = useState("");
    const [searchTerm, setSearchTerm] = useState("");

    const queryClient = useQueryClient();
    const { refreshTenant } = useTenant();

    const { data: lojas = [], isLoading } = useQuery({
        queryKey: ['lojas'],
        queryFn: () => base44.entities.Loja.list('nome'),
    });

    const createMutation = useMutation({
        mutationFn: (data) => base44.entities.Loja.create(data),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['lojas'] });
            if (refreshTenant) refreshTenant();
            handleCloseModal();
        },
        onError: (err) => setError(err.message || "Erro ao criar loja"),
    });

    const updateMutation = useMutation({
        mutationFn: ({ id, data }) => base44.entities.Loja.update(id, data),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['lojas'] });
            if (refreshTenant) refreshTenant();
            handleCloseModal();
        },
        onError: (err) => setError(err.message || "Erro ao atualizar loja"),
    });

    const deleteMutation = useMutation({
        mutationFn: (id) => base44.entities.Loja.delete(id),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['lojas'] });
            if (refreshTenant) refreshTenant();
        },
    });

    const handleOpenModal = (loja = null) => {
        setEditingLoja(loja);
        if (loja) {
            setFormData({
                nome: loja.nome || "",
                cnpj: loja.cnpj || "",
                endereco: loja.endereco || "",
                cidade: loja.cidade || "",
                estado: loja.estado || "",
                cep: loja.cep || "",
                telefone: loja.telefone || ""
            });
        } else {
            setFormData(INITIAL_FORM_DATA);
        }
        setError("");
        setIsModalOpen(true);
    };

    const handleCloseModal = () => {
        setIsModalOpen(false);
        setEditingLoja(null);
        setFormData(INITIAL_FORM_DATA);
        setError("");
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        if (!formData.nome.trim()) {
            setError("O nome da loja é obrigatório");
            return;
        }
        if (editingLoja) {
            updateMutation.mutate({ id: editingLoja.id, data: formData });
        } else {
            createMutation.mutate({ ...formData, ativa: true, is_active: true });
        }
    };

    const handleToggleAtiva = (loja) => {
        updateMutation.mutate({ id: loja.id, data: { ativa: !loja.ativa, is_active: !loja.ativa } });
    };

    const handleDelete = (id) => {
        if (window.confirm("Tem certeza que deseja excluir esta loja? Isso pode afetar estoques vinculados.")) {
            deleteMutation.mutate(id);
        }
    };

    const handleChange = (field, value) => {
        setFormData(prev => ({ ...prev, [field]: value }));
    };

    // Format CNPJ as user types
    const formatCNPJ = (value) => {
        const digits = value.replace(/\D/g, '').slice(0, 14);
        if (digits.length <= 2) return digits;
        if (digits.length <= 5) return `${digits.slice(0, 2)}.${digits.slice(2)}`;
        if (digits.length <= 8) return `${digits.slice(0, 2)}.${digits.slice(2, 5)}.${digits.slice(5)}`;
        if (digits.length <= 12) return `${digits.slice(0, 2)}.${digits.slice(2, 5)}.${digits.slice(5, 8)}/${digits.slice(8)}`;
        return `${digits.slice(0, 2)}.${digits.slice(2, 5)}.${digits.slice(5, 8)}/${digits.slice(8, 12)}-${digits.slice(12)}`;
    };

    // Format phone as user types
    const formatPhone = (value) => {
        const digits = value.replace(/\D/g, '').slice(0, 11);
        if (digits.length <= 2) return digits;
        if (digits.length <= 6) return `(${digits.slice(0, 2)}) ${digits.slice(2)}`;
        if (digits.length <= 10) return `(${digits.slice(0, 2)}) ${digits.slice(2, 6)}-${digits.slice(6)}`;
        return `(${digits.slice(0, 2)}) ${digits.slice(2, 7)}-${digits.slice(7)}`;
    };

    // Format CEP as user types
    const formatCEP = (value) => {
        const digits = value.replace(/\D/g, '').slice(0, 8);
        if (digits.length <= 5) return digits;
        return `${digits.slice(0, 5)}-${digits.slice(5)}`;
    };

    const filteredLojas = lojas.filter(l =>
        l.nome.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (l.endereco && l.endereco.toLowerCase().includes(searchTerm.toLowerCase())) ||
        (l.cidade && l.cidade.toLowerCase().includes(searchTerm.toLowerCase()))
    );

    if (isLoading) {
        return (
            <div className="flex items-center justify-center h-64">
                <Loader2 className="w-8 h-8 animate-spin text-green-600" />
            </div>
        );
    }

    return (
        <div className="max-w-5xl mx-auto space-y-8">
            <div>
                <h2 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
                    <Building2 className="w-8 h-8 text-green-600" />
                    Gestão de Filiais e Estoques
                </h2>
                <p className="text-gray-500 mt-1">Configure as lojas físicas e centros de distribuição para controle de estoque multi-local.</p>
            </div>

            <Card className="border-t-4 border-t-green-600 shadow-sm">
                <CardHeader>
                    <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                        <div>
                            <CardTitle>Lojas Cadastradas</CardTitle>
                            <CardDescription>Gerencie suas unidades de negócio</CardDescription>
                        </div>
                        <div className="flex items-center gap-2">
                            <div className="relative">
                                <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                                <Input
                                    placeholder="Buscar loja..."
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                    className="pl-9 h-9 w-[200px] bg-gray-50"
                                />
                            </div>
                            <Button
                                onClick={() => handleOpenModal()}
                                className="bg-green-600 hover:bg-green-700 h-9"
                            >
                                <Plus className="w-4 h-4 mr-2" />
                                Nova Loja
                            </Button>
                        </div>
                    </div>
                </CardHeader>
                <CardContent>
                    {filteredLojas.length === 0 ? (
                        <div className="text-center py-16 bg-gray-50 rounded-lg border border-dashed border-gray-200">
                            <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4">
                                <Store className="w-8 h-8 text-green-600 opacity-80" />
                            </div>
                            <h3 className="text-lg font-semibold text-gray-900">Nenhuma loja encontrada</h3>
                            <p className="text-gray-500 max-w-sm mx-auto mt-1">
                                {searchTerm ? "Nenhum resultado para sua busca." : "Comece cadastrando sua primeira loja ou centro de distribuição."}
                            </p>
                            {!searchTerm && (
                                <Button onClick={() => handleOpenModal()} variant="outline" className="mt-4 border-green-200 text-green-700 hover:bg-green-50">
                                    Cadastrar Primeira Loja
                                </Button>
                            )}
                        </div>
                    ) : (
                        <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
                            {filteredLojas.map((loja) => (
                                <div
                                    key={loja.id}
                                    className={`relative group bg-white rounded-xl border transition-all duration-200 hover:shadow-md ${loja.ativa
                                        ? 'border-gray-200'
                                        : 'border-gray-200 bg-gray-50 opacity-75'
                                        }`}
                                >
                                    {/* Status Badge */}
                                    <div className="absolute top-4 right-4 z-10">
                                        <Badge variant={loja.ativa ? "default" : "secondary"} className={loja.ativa ? "bg-green-100 text-green-700 hover:bg-green-200" : ""}>
                                            {loja.ativa ? 'Ativa' : 'Inativa'}
                                        </Badge>
                                    </div>

                                    <div className="p-5">
                                        <div className="flex items-center gap-3 mb-4">
                                            <div className={`p-2.5 rounded-lg ${loja.ativa ? 'bg-green-50' : 'bg-gray-100'}`}>
                                                <Store className={`w-6 h-6 ${loja.ativa ? 'text-green-600' : 'text-gray-400'}`} />
                                            </div>
                                            <div>
                                                <h3 className="font-semibold text-gray-900 leading-tight">{loja.nome}</h3>
                                                {loja.cidade && loja.estado && (
                                                    <p className="text-xs text-gray-500 mt-0.5">{loja.cidade} - {loja.estado}</p>
                                                )}
                                            </div>
                                        </div>

                                        <div className="space-y-2 mb-6 min-h-[60px]">
                                            {loja.endereco ? (
                                                <div className="flex items-start gap-2 text-sm text-gray-600">
                                                    <MapPin className="w-4 h-4 mt-0.5 text-gray-400 shrink-0" />
                                                    <span className="line-clamp-2">{loja.endereco}</span>
                                                </div>
                                            ) : (
                                                <div className="flex items-center gap-2 text-sm text-gray-400 italic">
                                                    <MapPin className="w-4 h-4" /> Sem endereço
                                                </div>
                                            )}
                                            {loja.telefone && (
                                                <div className="flex items-center gap-2 text-sm text-gray-600">
                                                    <Phone className="w-4 h-4 text-gray-400 shrink-0" />
                                                    <span>{loja.telefone}</span>
                                                </div>
                                            )}
                                            {loja.cnpj && (
                                                <div className="flex items-center gap-2 text-sm text-gray-600">
                                                    <FileText className="w-4 h-4 text-gray-400 shrink-0" />
                                                    <span className="font-mono text-xs">{loja.cnpj}</span>
                                                </div>
                                            )}
                                        </div>

                                        <div className="pt-4 border-t flex items-center justify-between">
                                            <div className="flex items-center gap-2">
                                                <Switch
                                                    checked={loja.ativa}
                                                    onCheckedChange={() => handleToggleAtiva(loja)}
                                                    className="data-[state=checked]:bg-green-600"
                                                />
                                                <span className="text-xs font-medium text-gray-600">
                                                    {loja.ativa ? 'Loja Aberta' : 'Loja Fechada'}
                                                </span>
                                            </div>

                                            <div className="flex items-center gap-1 opacity-100 sm:opacity-0 group-hover:opacity-100 transition-opacity">
                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    onClick={() => handleOpenModal(loja)}
                                                    className="h-8 w-8 text-gray-500 hover:text-blue-600 hover:bg-blue-50"
                                                >
                                                    <Pencil className="w-4 h-4" />
                                                </Button>
                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    onClick={() => handleDelete(loja.id)}
                                                    className="h-8 w-8 text-gray-500 hover:text-red-600 hover:bg-red-50"
                                                >
                                                    <Trash2 className="w-4 h-4" />
                                                </Button>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </CardContent>
            </Card>

            <Dialog open={isModalOpen} onOpenChange={handleCloseModal}>
                <DialogContent className="sm:max-w-[550px] max-h-[90vh] overflow-y-auto">
                    <DialogHeader>
                        <DialogTitle className="text-xl font-bold flex items-center gap-2 text-gray-900">
                            <Store className="w-5 h-5 text-green-600" />
                            {editingLoja ? 'Editar Loja' : 'Nova Loja'}
                        </DialogTitle>
                        <DialogDescription>
                            Preencha as informações da unidade abaixo.
                        </DialogDescription>
                    </DialogHeader>

                    <form onSubmit={handleSubmit} className="space-y-4 py-2">
                        {error && (
                            <Alert variant="destructive" className="bg-red-50 border-red-200">
                                <AlertDescription className="text-red-700">{error}</AlertDescription>
                            </Alert>
                        )}

                        {/* Dados Básicos */}
                        <div className="space-y-4">
                            <h4 className="text-sm font-semibold text-gray-700 flex items-center gap-2">
                                <Building2 className="w-4 h-4" />
                                Dados Básicos
                            </h4>

                            <div className="grid grid-cols-2 gap-4">
                                <div className="col-span-2">
                                    <Label htmlFor="nome">Nome da Loja *</Label>
                                    <Input
                                        id="nome"
                                        value={formData.nome}
                                        onChange={(e) => handleChange("nome", e.target.value)}
                                        placeholder="Ex: Matriz, Shopping Sul, Centro"
                                        className="bg-gray-50 mt-1"
                                    />
                                </div>

                                <div>
                                    <Label htmlFor="cnpj">CNPJ</Label>
                                    <Input
                                        id="cnpj"
                                        value={formData.cnpj}
                                        onChange={(e) => handleChange("cnpj", formatCNPJ(e.target.value))}
                                        placeholder="00.000.000/0000-00"
                                        className="bg-gray-50 mt-1 font-mono"
                                        maxLength={18}
                                    />
                                </div>

                                <div>
                                    <Label htmlFor="telefone">Telefone</Label>
                                    <Input
                                        id="telefone"
                                        value={formData.telefone}
                                        onChange={(e) => handleChange("telefone", formatPhone(e.target.value))}
                                        placeholder="(00) 00000-0000"
                                        className="bg-gray-50 mt-1"
                                    />
                                </div>
                            </div>
                        </div>
                        {/* Endereço */}
                        <div className="space-y-4 pt-4 border-t">
                            <h4 className="text-sm font-semibold text-gray-700 flex items-center gap-2">
                                <MapPin className="w-4 h-4" />
                                Endereço
                            </h4>

                            <div className="grid grid-cols-3 gap-4">
                                <div className="col-span-3">
                                    <Label htmlFor="endereco">Endereço Completo</Label>
                                    <Input
                                        id="endereco"
                                        value={formData.endereco}
                                        onChange={(e) => handleChange("endereco", e.target.value)}
                                        placeholder="Rua, Número, Bairro"
                                        className="bg-gray-50 mt-1"
                                    />
                                </div>

                                <div className="col-span-2">
                                    <Label htmlFor="cidade">Cidade</Label>
                                    <Input
                                        id="cidade"
                                        value={formData.cidade}
                                        onChange={(e) => handleChange("cidade", e.target.value)}
                                        placeholder="Ex: São Paulo"
                                        className="bg-gray-50 mt-1"
                                    />
                                </div>

                                <div>
                                    <Label htmlFor="estado">UF</Label>
                                    <Input
                                        id="estado"
                                        value={formData.estado}
                                        onChange={(e) => handleChange("estado", e.target.value.toUpperCase().slice(0, 2))}
                                        placeholder="SP"
                                        maxLength={2}
                                        className="bg-gray-50 mt-1 uppercase"
                                    />
                                </div>

                                <div className="col-span-3">
                                    <Label htmlFor="cep">CEP</Label>
                                    <Input
                                        id="cep"
                                        value={formData.cep}
                                        onChange={(e) => handleChange("cep", formatCEP(e.target.value))}
                                        placeholder="00000-000"
                                        className="bg-gray-50 mt-1 w-40"
                                    />
                                </div>
                            </div>
                        </div>

                        <DialogFooter className="pt-4">
                            <Button type="button" variant="ghost" onClick={handleCloseModal}>
                                Cancelar
                            </Button>
                            <Button
                                type="submit"
                                disabled={createMutation.isPending || updateMutation.isPending}
                                className="bg-green-600 hover:bg-green-700 min-w-[120px]"
                            >
                                {(createMutation.isPending || updateMutation.isPending) ? (
                                    <Loader2 className="w-4 h-4 animate-spin mr-2" />
                                ) : null}
                                {editingLoja ? 'Salvar Alterações' : 'Criar Loja'}
                            </Button>
                        </DialogFooter>
                    </form >
                </DialogContent >
            </Dialog >
        </div >
    );
}

import React, { useState } from "react";
import { base44 } from "@/api/base44Client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Plus, Pencil, Trash2, UserCheck, UserX, MapPin, Loader2 } from "lucide-react";
import VendedorModal from "./VendedorModal";
import { useLojas } from "@/hooks/useLojas";

export default function GestaoVendedores() {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingVendedor, setEditingVendedor] = useState(null);
  const queryClient = useQueryClient();

  const { data: vendedores = [], isLoading: loadingVendedores } = useQuery({
    queryKey: ['vendedores'],
    queryFn: () => base44.entities.Vendedor.list('-created_date'),
  });

  const { data: lojas = [], isLoading: loadingLojas } = useLojas();

  const createMutation = useMutation({
    mutationFn: (data) => base44.entities.Vendedor.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['vendedores'] });
      setIsModalOpen(false);
      setEditingVendedor(null);
    },
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, data }) => base44.entities.Vendedor.update(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['vendedores'] });
      setIsModalOpen(false);
      setEditingVendedor(null);
    },
  });

  const deleteMutation = useMutation({
    mutationFn: (id) => base44.entities.Vendedor.delete(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['vendedores'] });
    },
  });

  const handleSave = (data) => {
    if (editingVendedor) {
      updateMutation.mutate({ id: editingVendedor.id, data });
    } else {
      createMutation.mutate(data);
    }
  };

  const handleEdit = (vendedor) => {
    setEditingVendedor(vendedor);
    setIsModalOpen(true);
  };

  const handleDelete = (id) => {
    if (confirm('Tem certeza que deseja excluir este vendedor?')) {
      deleteMutation.mutate(id);
    }
  };

  const toggleAtivo = (vendedor) => {
    updateMutation.mutate({
      id: vendedor.id,
      data: { ...vendedor, ativo: !vendedor.ativo }
    });
  };

  const vendedoresPorLoja = lojas.reduce((acc, loja) => {
    acc[loja.nome] = vendedores.filter(v => v.loja === loja.nome);
    return acc;
  }, {});

  // Vendedores sem loja ou em lojas inativas/não listadas (opcional, mas bom para debug)
  const vendedoresSemLoja = vendedores.filter(v => !lojas.some(l => l.nome === v.loja));
  if (vendedoresSemLoja.length > 0) {
    vendedoresPorLoja["Outros/Sem Loja"] = vendedoresSemLoja;
  }

  if (loadingVendedores || loadingLojas) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="w-8 h-8 animate-spin" style={{ color: '#07593f' }} />
      </div>
    );
  }

  return (
    <>
      <div className="flex justify-end mb-6">
        <Button
          onClick={() => {
            setEditingVendedor(null);
            setIsModalOpen(true);
          }}
          className="shadow-lg"
          style={{ background: 'linear-gradient(135deg, #f38a4c 0%, #f5a164 100%)' }}
        >
          <Plus className="w-4 h-4 mr-2" />
          Adicionar Vendedor
        </Button>
      </div>

      <div className="space-y-6">
        {Object.entries(vendedoresPorLoja).map(([loja, vendedoresLoja]) => (
          <Card key={loja} className="border-0 shadow-lg">
            <CardHeader style={{ backgroundColor: '#f0f9ff' }}>
              <CardTitle className="flex items-center gap-2" style={{ color: '#07593f' }}>
                <MapPin className="w-5 h-5" />
                Loja {loja} ({vendedoresLoja.length})
              </CardTitle>
            </CardHeader>
            <CardContent className="p-6">
              {vendedoresLoja.length === 0 ? (
                <p className="text-center py-8" style={{ color: '#8B8B8B' }}>
                  Nenhum vendedor cadastrado nesta loja
                </p>
              ) : (
                <div className="grid md:grid-cols-2 gap-4">
                  {vendedoresLoja.map((vendedor) => (
                    <div
                      key={vendedor.id}
                      className="p-4 rounded-lg border-2 hover:shadow-md transition-all"
                      style={{
                        borderColor: vendedor.ativo ? '#07593f' : '#E5E0D8',
                        backgroundColor: vendedor.ativo ? '#ffffff' : '#f9fafb'
                      }}
                    >
                      <div className="flex items-start justify-between mb-3">
                        <div className="flex items-center gap-2">
                          <div
                            className="w-10 h-10 rounded-full flex items-center justify-center"
                            style={{
                              backgroundColor: vendedor.ativo ? '#07593f' : '#9ca3af',
                              color: 'white'
                            }}
                          >
                            {vendedor.nome?.charAt(0).toUpperCase()}
                          </div>
                          <div>
                            <p className="font-semibold" style={{ color: '#07593f' }}>
                              {vendedor.nome}
                            </p>
                            <p className="text-xs" style={{ color: '#8B8B8B' }}>
                              {vendedor.cpf || 'CPF não informado'}
                            </p>
                          </div>
                        </div>
                        <Badge
                          variant={vendedor.ativo ? "default" : "secondary"}
                          style={vendedor.ativo ? { backgroundColor: '#D1FAE5', color: '#065F46' } : {}}
                        >
                          {vendedor.ativo ? 'Ativo' : 'Inativo'}
                        </Badge>
                      </div>

                      {vendedor.telefone && (
                        <p className="text-sm mb-1" style={{ color: '#8B8B8B' }}>
                          📱 {vendedor.telefone}
                        </p>
                      )}
                      {vendedor.email && (
                        <p className="text-sm mb-3" style={{ color: '#8B8B8B' }}>
                          ✉️ {vendedor.email}
                        </p>
                      )}

                      <div className="flex gap-2 pt-3 border-t" style={{ borderColor: '#E5E0D8' }}>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => toggleAtivo(vendedor)}
                          className="flex-1"
                        >
                          {vendedor.ativo ? (
                            <>
                              <UserX className="w-4 h-4 mr-1" />
                              Desativar
                            </>
                          ) : (
                            <>
                              <UserCheck className="w-4 h-4 mr-1" />
                              Ativar
                            </>
                          )}
                        </Button>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => handleEdit(vendedor)}
                        >
                          <Pencil className="w-4 h-4" />
                        </Button>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => handleDelete(vendedor.id)}
                          className="text-red-600 hover:text-red-700"
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        ))}
      </div>

      <VendedorModal
        isOpen={isModalOpen}
        onClose={() => {
          setIsModalOpen(false);
          setEditingVendedor(null);
        }}
        onSave={handleSave}
        vendedor={editingVendedor}
        isLoading={createMutation.isPending || updateMutation.isPending}
      />
    </>
  );
}

import React, { useState, useMemo } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Loader2, Shield, Search, ChevronDown, ChevronRight, Check, X } from "lucide-react";
import { ROLE_RULES, SCOPES, PERMISSION_CATALOG, PERMISSION_CATEGORIES } from "@/config/permissions";

const SCOPE_OPTIONS = [
    { value: SCOPES.ALL,   label: 'Todos os dados (toda a empresa)' },
    { value: SCOPES.STORE, label: 'Dados da loja do usuário' },
    { value: SCOPES.OWN,   label: 'Apenas dados próprios' },
];

/**
 * Editor visual de permissões por cargo.
 * - Cargos estáticos: mostra permissões do ROLE_RULES como base (verde),
 *   permite adicionar extras (azul) ou remover do base (vermelho).
 * - Cargos personalizados: lista limpa; cada item marcado = permissão concedida.
 * Props: cargo, cargoLabel, cargoColor, currentPermissions, currentDenied,
 *        currentScope, isCustomCargo, onSave({permissions, deniedPermissions, scope}),
 *        onClose, isSaving
 */
export default function RolePermissionEditorModal({
    cargo,
    cargoLabel,
    cargoColor,
    currentPermissions = [],
    currentDenied      = [],
    currentScope,
    isCustomCargo      = false,
    onSave,
    onClose,
    isSaving           = false,
}) {
    const isAdmin    = cargo === 'Administrador';
    const roleRules  = ROLE_RULES[cargo] || null;
    // Base permissions from ROLE_RULES (for static cargos). Wildcard (*) means all.
    const basePerms  = roleRules?.can?.includes('*') ? [] : (roleRules?.can || []);

    const [scope,              setScope]              = useState(currentScope || ROLE_RULES[cargo]?.scope || SCOPES.OWN);
    // added: permissions explicitly added (extra beyond base, or full list for custom cargo)
    const [added,              setAdded]              = useState(currentPermissions);
    // denied: permissions explicitly removed from base (only relevant for static cargos)
    const [denied,             setDenied]             = useState(currentDenied);
    const [search,             setSearch]             = useState('');
    const [expandedCategories, setExpandedCategories] = useState({});

    // Derive display state for every permission in the catalog
    const permState = useMemo(() => {
        const states = {};
        PERMISSION_CATALOG.forEach(({ code }) => {
            const inBase    = basePerms.includes(code);
            const inAdded   = added.includes(code);
            const inDenied  = denied.includes(code);

            let active = false;
            let source = 'none'; // 'role' | 'added' | 'denied' | 'none'

            if (isCustomCargo) {
                // Custom cargo: no implicit base — added list IS the full permission set
                active = inAdded;
                source = inAdded ? 'added' : 'none';
            } else if (inDenied) {
                active = false;
                source = 'denied';
            } else if (inBase) {
                active = true;
                source = inAdded ? 'added' : 'role';
            } else if (inAdded) {
                active = true;
                source = 'added';
            }

            states[code] = { active, source, inBase };
        });
        return states;
    }, [added, denied, basePerms, isCustomCargo]);

    const togglePerm = (code) => {
        if (isAdmin) return;
        const state = permState[code];
        if (!state) return;

        if (isCustomCargo) {
            // Simple toggle on the added set
            setAdded(prev => prev.includes(code) ? prev.filter(p => p !== code) : [...prev, code]);
        } else if (state.inBase) {
            if (state.source === 'denied') {
                // Restore: remove from denied
                setDenied(prev => prev.filter(p => p !== code));
            } else {
                // Deny: add to denied, remove from added (in case it was there)
                setDenied(prev => [...prev, code]);
                setAdded(prev => prev.filter(p => p !== code));
            }
        } else {
            if (state.source === 'added') {
                // Remove extra
                setAdded(prev => prev.filter(p => p !== code));
            } else {
                // Add extra, ensure not in denied
                setAdded(prev => [...prev, code]);
                setDenied(prev => prev.filter(p => p !== code));
            }
        }
    };

    const handleSave = () => {
        onSave({
            // For static cargos: only store extras that are not already in base
            permissions:        isCustomCargo ? added : added.filter(p => !basePerms.includes(p)),
            deniedPermissions:  isCustomCargo ? []   : denied,
            scope,
        });
    };

    // Group catalog by category, applying search filter
    const catalogByCategory = useMemo(() => {
        const q = search.toLowerCase().trim();
        const result = {};
        PERMISSION_CATALOG.forEach(item => {
            if (
                q &&
                !item.label.toLowerCase().includes(q) &&
                !item.code.toLowerCase().includes(q) &&
                !item.description.toLowerCase().includes(q)
            ) return;
            if (!result[item.category]) result[item.category] = [];
            result[item.category].push(item);
        });
        return result;
    }, [search]);

    const toggleCategory = (cat) =>
        setExpandedCategories(prev => ({ ...prev, [cat]: !prev[cat] }));

    // Default: all categories expanded
    const isCategoryExpanded = (cat) => expandedCategories[cat] !== false;

    const getPermStyle = (code) => {
        const s = permState[code];
        if (!s || s.source === 'none') return { bg: 'bg-gray-50', border: 'border-gray-200', opacity: 'opacity-50' };
        if (s.source === 'denied')     return { bg: 'bg-red-50',   border: 'border-red-300',  opacity: '' };
        if (s.source === 'added')      return { bg: 'bg-blue-50',  border: 'border-blue-300', opacity: '' };
        if (s.active)                  return { bg: 'bg-green-50', border: 'border-green-300', opacity: '' };
        return { bg: 'bg-gray-50', border: 'border-gray-200', opacity: 'opacity-50' };
    };

    const activeCount = Object.values(permState).filter(s => s.active).length;
    const customCount = added.length + denied.length;

    if (!cargo) return null;

    return (
        <Dialog open onOpenChange={onClose}>
            <DialogContent className="max-w-3xl max-h-[92vh] flex flex-col gap-3">
                <DialogHeader className="flex-shrink-0">
                    <DialogTitle className="flex items-center gap-2">
                        <div
                            className="w-8 h-8 rounded-lg flex items-center justify-center"
                            style={{ backgroundColor: `${cargoColor || '#07593f'}25` }}
                        >
                            <Shield className="w-4 h-4" style={{ color: cargoColor || '#07593f' }} />
                        </div>
                        Permissões: {cargoLabel || cargo}
                    </DialogTitle>
                    <DialogDescription>
                        {isAdmin
                            ? 'Administrador possui acesso irrestrito ao sistema e não pode ser editado.'
                            : 'Verde = do cargo, Azul = adicionado, Vermelho = removido. Clique para alternar.'}
                    </DialogDescription>
                </DialogHeader>

                {isAdmin ? (
                    <div className="p-4 bg-amber-50 rounded-lg border border-amber-200">
                        <div className="flex items-center gap-2 text-amber-700">
                            <Shield className="w-5 h-5" />
                            <span className="font-medium">
                                Administrador tem acesso total ao sistema e não pode ser editado.
                            </span>
                        </div>
                    </div>
                ) : (
                    <>
                        {/* Scope selector */}
                        <div className="flex-shrink-0">
                            <Label className="text-sm font-medium">Escopo de dados</Label>
                            <Select value={scope} onValueChange={setScope}>
                                <SelectTrigger className="mt-1">
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    {SCOPE_OPTIONS.map(opt => (
                                        <SelectItem key={opt.value} value={opt.value}>{opt.label}</SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>

                        {/* Legend + search + counters */}
                        <div className="flex-shrink-0 space-y-2">
                            <div className="flex items-center gap-3 flex-wrap">
                                <div className="flex gap-3 text-xs text-gray-600">
                                    <span className="flex items-center gap-1">
                                        <span className="w-3 h-3 rounded bg-green-100 border border-green-400 inline-block" />
                                        Do cargo
                                    </span>
                                    <span className="flex items-center gap-1">
                                        <span className="w-3 h-3 rounded bg-blue-100 border border-blue-400 inline-block" />
                                        Adicionado
                                    </span>
                                    <span className="flex items-center gap-1">
                                        <span className="w-3 h-3 rounded bg-red-100 border border-red-400 inline-block" />
                                        Removido
                                    </span>
                                    <span className="flex items-center gap-1">
                                        <span className="w-3 h-3 rounded bg-gray-100 border border-gray-300 inline-block opacity-50" />
                                        Sem acesso
                                    </span>
                                </div>
                                <div className="flex-1 min-w-40 relative">
                                    <Search className="absolute left-2 top-1/2 -translate-y-1/2 w-3 h-3 text-gray-400" />
                                    <Input
                                        value={search}
                                        onChange={e => setSearch(e.target.value)}
                                        placeholder="Filtrar permissões..."
                                        className="pl-7 h-8 text-sm"
                                    />
                                </div>
                            </div>
                            <p className="text-xs text-gray-500">
                                {activeCount} ativa(s) &nbsp;|&nbsp; {customCount} customização(ões)
                            </p>
                        </div>

                        {/* Permissions grouped by category */}
                        <div className="flex-1 min-h-0 overflow-y-auto pr-2">
                            <div className="space-y-3">
                                {Object.entries(catalogByCategory).map(([category, items]) => {
                                    const catConfig   = PERMISSION_CATEGORIES.find(c => c.key === category);
                                    const expanded    = isCategoryExpanded(category);
                                    const activeInCat = items.filter(i => permState[i.code]?.active).length;

                                    return (
                                        <div key={category} className="border rounded-lg overflow-hidden">
                                            <button
                                                type="button"
                                                className="w-full flex items-center justify-between p-3 bg-gray-50 hover:bg-gray-100 transition-colors"
                                                onClick={() => toggleCategory(category)}
                                            >
                                                <div className="flex items-center gap-2">
                                                    {expanded
                                                        ? <ChevronDown  className="w-4 h-4 text-gray-500" />
                                                        : <ChevronRight className="w-4 h-4 text-gray-500" />
                                                    }
                                                    <span
                                                        className="font-medium text-sm"
                                                        style={{ color: catConfig?.color || '#374151' }}
                                                    >
                                                        {catConfig?.label || category}
                                                    </span>
                                                </div>
                                                <Badge
                                                    className="text-xs"
                                                    style={{
                                                        backgroundColor: `${catConfig?.color || '#6b7280'}20`,
                                                        color:           catConfig?.color || '#6b7280',
                                                    }}
                                                >
                                                    {activeInCat}/{items.length}
                                                </Badge>
                                            </button>

                                            {expanded && (
                                                <div className="p-2 grid sm:grid-cols-2 gap-1">
                                                    {items.map(item => {
                                                        const style = getPermStyle(item.code);
                                                        const state = permState[item.code];
                                                        return (
                                                            <button
                                                                key={item.code}
                                                                type="button"
                                                                onClick={() => togglePerm(item.code)}
                                                                className={`w-full text-left p-2 rounded-lg border transition-all hover:scale-[1.01] ${style.bg} ${style.border} ${style.opacity}`}
                                                            >
                                                                <div className="flex items-start gap-2">
                                                                    <div className={`w-4 h-4 rounded flex items-center justify-center flex-shrink-0 mt-0.5 ${
                                                                        state?.source === 'denied' ? 'bg-red-200'  :
                                                                        state?.active              ? 'bg-green-200' :
                                                                        'bg-gray-200'
                                                                    }`}>
                                                                        {state?.source === 'denied'              && <X     className="w-3 h-3 text-red-600"   />}
                                                                        {state?.active && state?.source !== 'denied' && <Check className="w-3 h-3 text-green-600" />}
                                                                    </div>
                                                                    <div className="min-w-0 flex-1">
                                                                        <p className="text-xs font-medium leading-tight">{item.label}</p>
                                                                        <p className="text-xs text-gray-500 leading-tight">{item.description}</p>
                                                                    </div>
                                                                    {state?.source === 'added' && (
                                                                        <Badge className="bg-blue-100 text-blue-700 text-xs px-1 flex-shrink-0">+</Badge>
                                                                    )}
                                                                    {state?.source === 'denied' && (
                                                                        <Badge className="bg-red-100 text-red-700 text-xs px-1 flex-shrink-0">-</Badge>
                                                                    )}
                                                                </div>
                                                            </button>
                                                        );
                                                    })}
                                                </div>
                                            )}
                                        </div>
                                    );
                                })}
                                {Object.keys(catalogByCategory).length === 0 && (
                                    <p className="text-center text-gray-400 py-8 text-sm">
                                        Nenhuma permissão encontrada para este filtro.
                                    </p>
                                )}
                            </div>
                        </div>
                    </>
                )}

                <DialogFooter className="flex-shrink-0">
                    <Button variant="outline" onClick={onClose}>
                        {isAdmin ? 'Fechar' : 'Cancelar'}
                    </Button>
                    {!isAdmin && (
                        <Button
                            onClick={handleSave}
                            disabled={isSaving}
                            style={{
                                background: `linear-gradient(135deg, ${cargoColor || '#07593f'} 0%, ${cargoColor || '#07593f'}cc 100%)`,
                            }}
                        >
                            {isSaving && <Loader2 className="w-4 h-4 animate-spin mr-2" />}
                            Salvar Permissões
                        </Button>
                    )}
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

import React, { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Loader2 } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { useLojas } from "@/hooks/useLojas";



export default function VendedorModal({ isOpen, onClose, onSave, vendedor, isLoading }) {
  const [formData, setFormData] = useState({
    nome: "",
    loja: "",
    cpf: "",
    telefone: "",
    email: "",
    meta_mensal: 0,
    data_admissao: new Date().toISOString().split('T')[0],
    ativo: true,
    observacoes: "",
  });

  const { data: lojas = [] } = useLojas();

  useEffect(() => {
    // Se for um novo vendedor e temos lojas carregadas, define a primeira como padrão se o campo estiver vazio
    if (!vendedor && lojas.length > 0 && !formData.loja) {
      setFormData(prev => ({ ...prev, loja: lojas[0].nome }));
    }
  }, [lojas, vendedor]);

  useEffect(() => {
    if (vendedor) {
      setFormData(vendedor);
    } else {
      setFormData({
        nome: "",
        loja: lojas.length > 0 ? lojas[0].nome : "",
        cpf: "",
        telefone: "",
        email: "",
        meta_mensal: 0,
        data_admissao: new Date().toISOString().split('T')[0],
        ativo: true,
        observacoes: "",
      });
    }
  }, [vendedor, isOpen]);

  const handleSubmit = (e) => {
    e.preventDefault();
    onSave({
      ...formData,
      meta_mensal: parseFloat(formData.meta_mensal) || 0 // Ensure meta_mensal is a number
    });
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle style={{ color: '#07593f' }}>
            {vendedor ? "Editar Vendedor" : "Novo Vendedor"}
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit}>
          <div className="space-y-4">
            <div className="grid md:grid-cols-2 gap-4">
              <div>
                <Label htmlFor="nome">Nome Completo *</Label>
                <Input
                  id="nome"
                  value={formData.nome}
                  onChange={(e) => setFormData({ ...formData, nome: e.target.value })}
                  required
                />
              </div>
              <div>
                <Label htmlFor="loja">Loja *</Label>
                <Select
                  value={formData.loja}
                  onValueChange={(value) => setFormData({ ...formData, loja: value })}
                  required
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {lojas.length === 0 ? (
                      <SelectItem value="Centro" disabled>Carregando...</SelectItem>
                    ) : (
                      lojas.map(loja => (
                        <SelectItem key={loja.id} value={loja.nome}>{loja.nome}</SelectItem>
                      ))
                    )}
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="grid md:grid-cols-2 gap-4">
              <div>
                <Label htmlFor="cpf">CPF</Label>
                <Input
                  id="cpf"
                  value={formData.cpf}
                  onChange={(e) => setFormData({ ...formData, cpf: e.target.value })}
                  placeholder="000.000.000-00"
                />
              </div>
              <div>
                <Label htmlFor="telefone">Telefone</Label>
                <Input
                  id="telefone"
                  value={formData.telefone}
                  onChange={(e) => setFormData({ ...formData, telefone: e.target.value })}
                  placeholder="(00) 00000-0000"
                />
              </div>
            </div>

            <div className="grid md:grid-cols-2 gap-4">
              <div>
                <Label htmlFor="email">E-mail</Label>
                <Input
                  id="email"
                  type="email"
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                />
              </div>
              <div>
                <Label htmlFor="data_admissao">Data de Admissão</Label>
                <Input
                  id="data_admissao"
                  type="date" lang="pt-BR"
                  value={formData.data_admissao}
                  onChange={(e) => setFormData({ ...formData, data_admissao: e.target.value })}
                />
              </div>
            </div>

            <div>
              <Label htmlFor="meta_mensal">Meta Mensal de Vendas (R$)</Label>
              <Input
                id="meta_mensal"
                type="number"
                step="0.01"
                min="0"
                value={formData.meta_mensal}
                onChange={(e) => setFormData({ ...formData, meta_mensal: parseFloat(e.target.value) || 0 })}
                placeholder="Ex: 50000.00"
              />
              <p className="text-xs mt-1" style={{ color: '#8B8B8B' }}>
                Meta mensal em reais para acompanhamento de performance
              </p>
            </div>

            <div>
              <Label htmlFor="observacoes">Observações</Label>
              <Textarea
                id="observacoes"
                value={formData.observacoes}
                onChange={(e) => setFormData({ ...formData, observacoes: e.target.value })}
                rows={3}
              />
            </div>
          </div>

          <DialogFooter className="mt-6">
            <Button type="button" variant="outline" onClick={onClose}>
              Cancelar
            </Button>
            <Button
              type="submit"
              disabled={isLoading}
              style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
            >
              {isLoading ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Salvando...
                </>
              ) : (
                vendedor ? "Atualizar" : "Cadastrar"
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useQuery } from "@tanstack/react-query";
import { base44 } from "@/api/base44Client";
import { supabase } from "@/lib/supabase";
import { useAuth } from "@/hooks/useAuth";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Eye, Clock, User, Package, Edit, Trash, Plus, ShieldCheck } from "lucide-react";
import { format, parseISO } from "date-fns";
import { ptBR } from "date-fns/locale";

const ACTION_ICONS = {
    'UPDATE': <Edit className="w-4 h-4 text-orange-500" />,
    'CREATE': <Plus className="w-4 h-4 text-green-500" />,
    'DELETE': <Trash className="w-4 h-4 text-red-500" />,
    'DEFAULT': <ShieldCheck className="w-4 h-4 text-blue-500" />
};

export default function AcoesVendedoresWidget() {
    const { user, getUserLoja } = useAuth();

    const { data: rawLogs = [], isLoading, isError } = useQuery({
        queryKey: ['acoes-vendedores'],
        queryFn: () => base44.entities.AuditLog.list('-created_at'),
        refetchInterval: 15000,
            staleTime: 30000,
            retry: false,
    });

    const { data: storeUsers = [] } = useQuery({
        queryKey: ['store-users', user?.loja],
        queryFn: async () => {
            const lojaAtual = getUserLoja();
            if (!lojaAtual) return [];
            const { data, error } = await supabase
                .from('public_users')
                .select('id, email, full_name, cargo')
                .eq('loja', lojaAtual);
            if (error) throw error;
            return data || [];
        },
        enabled: !!getUserLoja()
    });

    const normalizedLogs = rawLogs.map((log) => {
        const resolvedUser = storeUsers.find((u) =>
            (log.user_id && String(u.id) === String(log.user_id)) ||
            (log.user_email && u.email === log.user_email)
        );

        return {
            ...log,
            action: log.acao || log.action || 'UPDATE',
            user_name: log.usuario || log.user_name || resolvedUser?.full_name || '',
            user_email: log.user_email || resolvedUser?.email || '',
            user_cargo: log.user_cargo || resolvedUser?.cargo || '',
            entity_type: log.tabela || log.entity_type || log.table_name || '',
            entity_description: log.entity_description || log.detalhes?.description || '',
            timestamp: log.created_at || log.timestamp,
        };
    });

    const storeUserEmails = storeUsers.map(u => u.email).filter(Boolean);
    const storeUserNames = storeUsers.map(u => u.full_name).filter(Boolean);

    // Filtrar apenas vendedores da mesma loja
    const vendedorLogs = normalizedLogs.filter(log => {
        const cargoLog = (log.user_cargo || log.cargo || '').toLowerCase();
        const isVendedor = cargoLog.includes('vendedor');

        const email = log.user_email || log.email || '';
        const nome = log.user_name || log.usuario || '';

        const isFromStore = storeUserEmails.includes(email) || storeUserNames.includes(nome);

        const lojaAtual = getUserLoja();
        const isGlobalManager = !lojaAtual || lojaAtual === 'todas';

        return isVendedor && (isGlobalManager || isFromStore);
    });

    if (isLoading) {
        return (
            <Card className="col-span-1 lg:col-span-2 shadow-sm border border-gray-100 flex flex-col h-[400px]">
                <CardHeader className="bg-gray-50/50 pb-3 border-b border-gray-100 shrink-0">
                    <CardTitle className="text-sm font-semibold text-gray-800 flex items-center gap-2">
                        <Eye className="w-4 h-4 text-orange-600" />
                        Ações de Vendedores
                    </CardTitle>
                    <CardDescription className="text-xs">
                        Monitorando atividades recentes
                    </CardDescription>
                </CardHeader>
                <CardContent className="p-6 flex-1 flex items-center justify-center">
                    <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-orange-600" />
                </CardContent>
            </Card>
        );
    }

    if (isError) {
        return (
            <Card className="col-span-1 lg:col-span-2 shadow-sm border border-gray-100 flex flex-col h-[400px]">
                <CardHeader className="bg-gray-50/50 pb-3 border-b border-gray-100 shrink-0">
                    <CardTitle className="text-sm font-semibold text-gray-800 flex items-center gap-2">
                        <Eye className="w-4 h-4 text-orange-600" />
                        Ações de Vendedores
                    </CardTitle>
                </CardHeader>
                <CardContent className="p-6 flex-1 flex items-center justify-center">
                    <p className="text-sm text-gray-500">Erro ao carregar os logs.</p>
                </CardContent>
            </Card>
        );
    }

    return (
        <Card className="col-span-1 lg:col-span-2 shadow-sm border-orange-100 flex flex-col h-[400px]">
            <CardHeader className="bg-orange-50/50 pb-3 border-b border-orange-100 shrink-0">
                <div className="flex items-center justify-between">
                    <div>
                        <CardTitle className="text-sm font-semibold text-gray-800 flex items-center gap-2">
                            <Eye className="w-4 h-4 text-orange-600" />
                            Ações de Vendedores
                        </CardTitle>
                        <CardDescription className="text-xs mt-1">
                            Atividades recentes de produtos e vendas
                        </CardDescription>
                    </div>
                    <div className="text-xs text-orange-600 bg-orange-100 px-2 py-1 flex items-center gap-1 rounded font-medium">
                        <Clock className="w-3 h-3" /> Tempo Real
                    </div>
                </div>
            </CardHeader>
            <CardContent className="p-0 flex-1 h-[330px]">
                <ScrollArea className="h-full">
                    {vendedorLogs.length === 0 ? (
                        <div className="p-8 text-center flex flex-col items-center justify-center text-gray-500">
                            <User className="w-8 h-8 opacity-20 mb-2" />
                            <p className="text-sm">Nenhuma ação recente registrada.</p>
                        </div>
                    ) : (
                        <div className="divide-y divide-gray-100">
                            {vendedorLogs.map((log) => {
                                const parsedDate = new Date(log.created_at || log.timestamp);
                                const dataFormatada = format(parsedDate, "dd/MM 'às' HH:mm", { locale: ptBR });
                                const actionIcon = ACTION_ICONS[log.action] || ACTION_ICONS['DEFAULT'];

                                return (
                                    <div key={log.id} className="p-4 hover:bg-orange-50/30 transition-colors">
                                        <div className="flex justify-between items-start gap-3">
                                            <div className="mt-0.5 bg-white p-1.5 rounded-full border shadow-sm shrink-0">
                                                {actionIcon}
                                            </div>
                                            <div className="flex-1 min-w-0">
                                                <div className="flex items-center justify-between gap-2 mb-1">
                                                    <p className="font-semibold text-sm text-gray-800 truncate">
                                                        {log.user_name || log.usuario}
                                                    </p>
                                                    <span className="text-xs text-gray-500 whitespace-nowrap">
                                                        {dataFormatada}
                                                    </span>
                                                </div>
                                                <div className="text-xs bg-gray-50 p-2 rounded text-gray-700 leading-relaxed border line-clamp-2">
                                                    {log.entity_description || log.detalhes?.description || "Ação sem descrição."}
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                )
                            })}
                        </div>
                    )}
                </ScrollArea>
            </CardContent>
        </Card>
    );
}

import React, { useState, useMemo } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useQuery } from "@tanstack/react-query";
import { base44 } from "@/api/base44Client";
import {
    Wrench, Calendar, User, Clock, MapPin, Phone,
    CheckCircle, AlertCircle, CalendarDays, RotateCcw,
    DollarSign, FileText, TrendingUp
} from "lucide-react";
import { format, startOfMonth, endOfMonth, isWithinInterval } from "date-fns";
import { ptBR } from "date-fns/locale";

export default function ControleMontadoresWidget() {
    const [mesRelatorio, setMesRelatorio] = useState(() => {
        const hoje = new Date();
        return `${hoje.getFullYear()}-${String(hoje.getMonth() + 1).padStart(2, '0')}`;
    });
    const [abaAtiva, setAbaAtiva] = useState('visao-geral');

    // Buscar todas as montagens terceirizadas
    const { data: montagens = [], isLoading } = useQuery({
        queryKey: ['montagens-externas-gestao'],
        queryFn: async () => {
            const todas = await base44.entities.MontagemItem.list('-created_at');
            return todas.filter(m => m.tipo_montagem === 'terceirizada');
        },
        refetchInterval: 60000
    });

    // Buscar montadores
    const { data: montadores = [] } = useQuery({
        queryKey: ['montadores-lista'],
        queryFn: () => base44.entities.Montador.list()
    });

    // Filtrar montagens do mês selecionado
    const montagensMes = useMemo(() => {
        if (!mesRelatorio) return montagens;
        const [ano, mes] = mesRelatorio.split('-').map(Number);
        const inicio = startOfMonth(new Date(ano, mes - 1));
        const fim = endOfMonth(new Date(ano, mes - 1));

        return montagens.filter(m => {
            if (!m.data_agendada && !m.created_at) return false;
            const data = new Date(m.data_agendada || m.created_at);
            return isWithinInterval(data, { start: inicio, end: fim });
        });
    }, [montagens, mesRelatorio]);

    // KPIs
    const kpis = useMemo(() => {
        const pendentes = montagens.filter(m => m.status === 'pendente');
        const agendadas = montagens.filter(m => m.status === 'agendada' || m.status === 'confirmada');
        const emAndamento = montagens.filter(m => m.status === 'em_andamento');
        const concluidasMes = montagensMes.filter(m => m.status === 'concluida');
        const valorTotalMes = concluidasMes.reduce((sum, m) => sum + (m.valor_montagem || 0), 0);

        // Reagendadas (se tiver campo de reagendamento ou lógica)
        const reagendadas = montagens.filter(m => m.reagendada === true);

        return {
            pendentes: pendentes.length,
            agendadas: agendadas.length,
            emAndamento: emAndamento.length,
            concluidas: concluidasMes.length,
            reagendadas: reagendadas.length,
            valorTotalMes
        };
    }, [montagens, montagensMes]);

    // Relatório por montador
    const relatorioPorMontador = useMemo(() => {
        const agrupado = {};

        montagensMes.filter(m => m.status === 'concluida').forEach(m => {
            const montadorId = m.montador_id || 'sem_montador';
            const montadorNome = m.montador_nome || 'Não atribuído';

            if (!agrupado[montadorId]) {
                agrupado[montadorId] = {
                    id: montadorId,
                    nome: montadorNome,
                    qtdMontagens: 0,
                    valorTotal: 0,
                    montagens: []
                };
            }
            agrupado[montadorId].qtdMontagens += 1;
            agrupado[montadorId].valorTotal += m.valor_montagem || 0;
            agrupado[montadorId].montagens.push(m);
        });

        return Object.values(agrupado).sort((a, b) => b.valorTotal - a.valorTotal);
    }, [montagensMes]);

    const valorTotalRelatorio = relatorioPorMontador.reduce((sum, m) => sum + m.valorTotal, 0);

    const getStatusConfig = (status) => {
        const config = {
            pendente: { label: 'Pendente', color: 'bg-yellow-100 text-yellow-800', icon: Clock },
            agendada: { label: 'Agendada', color: 'bg-blue-100 text-blue-800', icon: Calendar },
            confirmada: { label: 'Confirmada', color: 'bg-green-100 text-green-800', icon: CheckCircle },
            em_andamento: { label: 'Em Andamento', color: 'bg-purple-100 text-purple-800', icon: Wrench },
            concluida: { label: 'Concluída', color: 'bg-gray-100 text-gray-600', icon: CheckCircle }
        };
        return config[status] || { label: status, color: 'bg-gray-100 text-gray-600', icon: AlertCircle };
    };

    const formatarMoeda = (valor) => {
        return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(valor || 0);
    };

    const formatarData = (dataStr) => {
        if (!dataStr) return '-';
        return format(new Date(dataStr), 'dd/MM/yyyy', { locale: ptBR });
    };

    // Montagens ativas (não concluídas)
    const montagensAtivas = montagens.filter(m => m.status !== 'concluida');

    return (
        <Card className="col-span-full border-orange-200 bg-orange-50/30">
            <CardHeader className="pb-3">
                <div className="flex justify-between items-center">
                    <div>
                        <CardTitle className="text-orange-800 flex items-center gap-2">
                            <Wrench className="w-5 h-5" />
                            Controle de Montadores Externos
                        </CardTitle>
                        <CardDescription>
                            Visão gerencial de montagens terceirizadas
                        </CardDescription>
                    </div>
                    <div className="flex items-center gap-2">
                        <Select value={mesRelatorio} onValueChange={setMesRelatorio}>
                            <SelectTrigger className="w-[140px]">
                                <CalendarDays className="w-4 h-4 mr-2" />
                                <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
                                {Array.from({ length: 6 }, (_, i) => {
                                    const d = new Date();
                                    d.setMonth(d.getMonth() - i);
                                    const val = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
                                    const label = format(d, 'MMMM yyyy', { locale: ptBR });
                                    return <SelectItem key={val} value={val}>{label}</SelectItem>;
                                })}
                            </SelectContent>
                        </Select>
                    </div>
                </div>
            </CardHeader>
            <CardContent>
                {/* KPIs */}
                <div className="grid grid-cols-2 md:grid-cols-5 gap-3 mb-4">
                    <div className="bg-yellow-50 rounded-lg p-3 border border-yellow-200">
                        <p className="text-xs text-yellow-600 font-medium">Pendentes</p>
                        <p className="text-2xl font-bold text-yellow-700">{kpis.pendentes}</p>
                    </div>
                    <div className="bg-blue-50 rounded-lg p-3 border border-blue-200">
                        <p className="text-xs text-blue-600 font-medium">Agendadas</p>
                        <p className="text-2xl font-bold text-blue-700">{kpis.agendadas}</p>
                    </div>
                    <div className="bg-purple-50 rounded-lg p-3 border border-purple-200">
                        <p className="text-xs text-purple-600 font-medium">Em Andamento</p>
                        <p className="text-2xl font-bold text-purple-700">{kpis.emAndamento}</p>
                    </div>
                    <div className="bg-green-50 rounded-lg p-3 border border-green-200">
                        <p className="text-xs text-green-600 font-medium">Concluídas (mês)</p>
                        <p className="text-2xl font-bold text-green-700">{kpis.concluidas}</p>
                    </div>
                    <div className="bg-orange-50 rounded-lg p-3 border border-orange-200">
                        <p className="text-xs text-orange-600 font-medium">Valor Total (mês)</p>
                        <p className="text-xl font-bold text-orange-700">{formatarMoeda(kpis.valorTotalMes)}</p>
                    </div>
                </div>

                <Tabs value={abaAtiva} onValueChange={setAbaAtiva}>
                    <TabsList className="grid grid-cols-3 mb-4">
                        <TabsTrigger value="visao-geral">
                            <Clock className="w-4 h-4 mr-1" />
                            Ativas
                        </TabsTrigger>
                        <TabsTrigger value="agenda">
                            <Calendar className="w-4 h-4 mr-1" />
                            Agenda
                        </TabsTrigger>
                        <TabsTrigger value="relatorio">
                            <FileText className="w-4 h-4 mr-1" />
                            Relatório
                        </TabsTrigger>
                    </TabsList>

                    {/* Aba Visão Geral - Montagens Ativas */}
                    <TabsContent value="visao-geral" className="mt-0">
                        <div className="max-h-[400px] overflow-y-auto">
                            {montagensAtivas.length === 0 ? (
                                <div className="text-center py-8 text-gray-500">
                                    <CheckCircle className="w-12 h-12 mx-auto mb-2 text-green-400" />
                                    <p>Todas as montagens foram concluídas!</p>
                                </div>
                            ) : (
                                <Table>
                                    <TableHeader>
                                        <TableRow>
                                            <TableHead>Pedido</TableHead>
                                            <TableHead>Cliente</TableHead>
                                            <TableHead>Montador</TableHead>
                                            <TableHead>Data Agendada</TableHead>
                                            <TableHead>Status</TableHead>
                                            <TableHead className="text-right">Valor</TableHead>
                                        </TableRow>
                                    </TableHeader>
                                    <TableBody>
                                        {montagensAtivas.map(m => {
                                            const statusConfig = getStatusConfig(m.status);
                                            return (
                                                <TableRow key={m.id}>
                                                    <TableCell className="font-medium">#{m.numero_pedido}</TableCell>
                                                    <TableCell>
                                                        <div>
                                                            <p className="text-sm">{m.cliente_nome}</p>
                                                            <p className="text-xs text-gray-500 truncate max-w-[150px]">{m.produto_nome}</p>
                                                        </div>
                                                    </TableCell>
                                                    <TableCell>
                                                        {m.montador_nome || (
                                                            <span className="text-orange-600 text-xs">Não atribuído</span>
                                                        )}
                                                    </TableCell>
                                                    <TableCell>
                                                        {m.data_agendada ? (
                                                            <div className="flex items-center gap-1">
                                                                <Calendar className="w-3 h-3" />
                                                                {formatarData(m.data_agendada)}
                                                                {m.horario_agendado && (
                                                                    <span className="text-xs text-gray-500">({m.horario_agendado})</span>
                                                                )}
                                                            </div>
                                                        ) : (
                                                            <span className="text-gray-400 text-xs">A definir</span>
                                                        )}
                                                    </TableCell>
                                                    <TableCell>
                                                        <Badge className={statusConfig.color}>
                                                            {statusConfig.label}
                                                        </Badge>
                                                    </TableCell>
                                                    <TableCell className="text-right font-medium">
                                                        {formatarMoeda(m.valor_montagem)}
                                                    </TableCell>
                                                </TableRow>
                                            );
                                        })}
                                    </TableBody>
                                </Table>
                            )}
                        </div>
                    </TabsContent>

                    {/* Aba Agenda */}
                    <TabsContent value="agenda" className="mt-0">
                        <div className="max-h-[400px] overflow-y-auto space-y-2">
                            {montagens
                                .filter(m => m.data_agendada && m.status !== 'concluida')
                                .sort((a, b) => new Date(a.data_agendada) - new Date(b.data_agendada))
                                .map(m => {
                                    const dataAgendada = new Date(m.data_agendada);
                                    const isHoje = dataAgendada.toDateString() === new Date().toDateString();
                                    const statusConfig = getStatusConfig(m.status);

                                    return (
                                        <div key={m.id} className={`flex items-center gap-4 p-3 rounded-lg border ${isHoje ? 'bg-orange-50 border-orange-300' : 'bg-white border-gray-200'}`}>
                                            <div className={`text-center p-2 rounded-lg min-w-[50px] ${isHoje ? 'bg-orange-500 text-white' : 'bg-gray-100'}`}>
                                                <p className="text-xs font-medium">
                                                    {format(dataAgendada, 'EEE', { locale: ptBR })}
                                                </p>
                                                <p className="text-lg font-bold">{format(dataAgendada, 'dd')}</p>
                                            </div>
                                            <div className="flex-1 min-w-0">
                                                <p className="font-medium text-gray-900">#{m.numero_pedido} - {m.produto_nome}</p>
                                                <p className="text-sm text-gray-600">{m.cliente_nome}</p>
                                                <div className="flex items-center gap-2 mt-1">
                                                    <User className="w-3 h-3 text-orange-500" />
                                                    <span className="text-xs text-gray-500">{m.montador_nome || 'Sem montador'}</span>
                                                    {m.horario_agendado && (
                                                        <>
                                                            <Clock className="w-3 h-3 text-gray-400" />
                                                            <span className="text-xs text-gray-500">{m.horario_agendado}</span>
                                                        </>
                                                    )}
                                                </div>
                                            </div>
                                            <Badge className={statusConfig.color}>{statusConfig.label}</Badge>
                                        </div>
                                    );
                                })}
                            {montagens.filter(m => m.data_agendada && m.status !== 'concluida').length === 0 && (
                                <div className="text-center py-8 text-gray-500">
                                    <Calendar className="w-12 h-12 mx-auto mb-2 opacity-20" />
                                    <p>Nenhuma montagem agendada</p>
                                </div>
                            )}
                        </div>
                    </TabsContent>

                    {/* Aba Relatório Mensal */}
                    <TabsContent value="relatorio" className="mt-0">
                        <div className="space-y-4">
                            {/* Resumo */}
                            <div className="bg-gradient-to-r from-orange-100 to-orange-50 rounded-lg p-4 border border-orange-200">
                                <div className="flex justify-between items-center">
                                    <div>
                                        <p className="text-sm text-orange-600 font-medium">Total de Montagens Concluídas</p>
                                        <p className="text-3xl font-bold text-orange-800">{kpis.concluidas}</p>
                                    </div>
                                    <div className="text-right">
                                        <p className="text-sm text-orange-600 font-medium">Valor Total a Pagar</p>
                                        <p className="text-3xl font-bold text-orange-800">{formatarMoeda(valorTotalRelatorio)}</p>
                                    </div>
                                </div>
                            </div>

                            {/* Detalhamento por Montador */}
                            <div className="max-h-[300px] overflow-y-auto">
                                {relatorioPorMontador.length === 0 ? (
                                    <div className="text-center py-8 text-gray-500">
                                        <FileText className="w-12 h-12 mx-auto mb-2 opacity-20" />
                                        <p>Nenhuma montagem concluída neste mês</p>
                                    </div>
                                ) : (
                                    <Table>
                                        <TableHeader>
                                            <TableRow>
                                                <TableHead>Montador</TableHead>
                                                <TableHead className="text-center">Qtd. Montagens</TableHead>
                                                <TableHead className="text-right">Valor Total</TableHead>
                                            </TableRow>
                                        </TableHeader>
                                        <TableBody>
                                            {relatorioPorMontador.map(montador => (
                                                <TableRow key={montador.id}>
                                                    <TableCell className="font-medium">
                                                        <div className="flex items-center gap-2">
                                                            <div className="w-8 h-8 bg-orange-100 rounded-full flex items-center justify-center">
                                                                <User className="w-4 h-4 text-orange-600" />
                                                            </div>
                                                            {montador.nome}
                                                        </div>
                                                    </TableCell>
                                                    <TableCell className="text-center">
                                                        <Badge variant="secondary">{montador.qtdMontagens}</Badge>
                                                    </TableCell>
                                                    <TableCell className="text-right font-bold text-green-600">
                                                        {formatarMoeda(montador.valorTotal)}
                                                    </TableCell>
                                                </TableRow>
                                            ))}
                                        </TableBody>
                                    </Table>
                                )}
                            </div>
                        </div>
                    </TabsContent>
                </Tabs>
            </CardContent>
        </Card>
    );
}

import React from "react";
