import { format, addDays } from "date-fns";

export default function AgendarEntregaModal({ isOpen, onClose, entrega, entregasSelecionadas }) {
  const [formData, setFormData] = useState({
    data_agendada: "",
    turno: "Manhã",
    caminhao_id: "",
    responsavel: "",
    observacoes: ""
  });

  const queryClient = useQueryClient();
  const selecionadas = entregasSelecionadas || [];
  const isMultiple = selecionadas.length > 0;
  const totalEntregas = isMultiple ? selecionadas.length : 1;

  const { data: caminhoes = [] } = useQuery({
    queryKey: ['caminhoes'],
    queryFn: () => base44.entities.Caminhao.list()
  });

  const updateMutation = useMutation({
    mutationFn: async (data) => {
      if (isMultiple) {
        // Atualizar múltiplas entregas
        for (const ent of selecionadas) {
          await base44.entities.Entrega.update(ent.id, data);
        }
      } else {
        await base44.entities.Entrega.update(entrega.id, data);
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['entregas'] });
      onClose();
    }
  });

  useEffect(() => {
    if (!isOpen) return;
    if (entrega && !isMultiple) {
      setFormData({
        data_agendada: entrega.data_agendada || "",
        turno: entrega.turno || "Manhã",
        caminhao_id: entrega.caminhao_id || "",
        responsavel: entrega.responsavel || "",
        observacoes: entrega.observacoes || ""
      });
    } else {
      setFormData({
        data_agendada: "",
        turno: "Manhã",
        caminhao_id: "",
        responsavel: "",
        observacoes: ""
      });
    }
  }, [entrega?.id, isMultiple, isOpen]);

  const handleSave = () => {
    updateMutation.mutate(formData);
  };

  // Sugestões de datas rápidas
  const hoje = new Date();
  const sugestoes = [
    { label: "Amanhã", date: format(addDays(hoje, 1), 'yyyy-MM-dd') },
    { label: "2 dias", date: format(addDays(hoje, 2), 'yyyy-MM-dd') },
    { label: "3 dias", date: format(addDays(hoje, 3), 'yyyy-MM-dd') },
    { label: "1 semana", date: format(addDays(hoje, 7), 'yyyy-MM-dd') }
  ];

  const caminhoesAtivos = caminhoes.filter(c => c.ativo);

  if (!entrega && !isMultiple) return null;

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Calendar className="w-5 h-5 text-blue-600" />
            {isMultiple
              ? `Agendar ${totalEntregas} Entregas`
              : `Agendar Entrega #${entrega?.numero_pedido}`
            }
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-5 py-4">
          {/* Info do Cliente (só para uma entrega) */}
          {!isMultiple && entrega && (
            <div className="bg-gray-50 dark:bg-neutral-800 p-3 rounded-lg text-sm">
              <p className="font-semibold text-gray-900 dark:text-white">{entrega.cliente_nome}</p>
              <p className="text-gray-500 text-xs mt-1">{entrega.endereco_entrega || 'Sem endereço'}</p>
              {entrega.data_limite && (
                <p className="text-orange-600 text-xs mt-1">
                  Limite: {format(new Date(entrega.data_limite + 'T12:00:00'), 'dd/MM/yyyy')}
                </p>
              )}
            </div>
          )}

          {/* Info múltiplas entregas */}
          {isMultiple && (
            <div className="bg-blue-50 dark:bg-blue-900/20 p-3 rounded-lg text-sm border border-blue-200 dark:border-blue-800">
              <p className="font-semibold text-blue-800 dark:text-blue-300">
                📦 {totalEntregas} pedidos selecionados
              </p>
              <p className="text-blue-600 dark:text-blue-400 text-xs mt-1">
                Todos serão agendados com as mesmas configurações
              </p>
            </div>
          )}

          {/* Sugestões Rápidas de Data */}
          <div>
            <Label className="text-xs text-gray-500 mb-2 block">Data rápida</Label>
            <div className="flex flex-wrap gap-2">
              {sugestoes.map(s => (
                <Button
                  key={s.label}
                  type="button"
                  size="sm"
                  variant={formData.data_agendada === s.date ? "default" : "outline"}
                  onClick={() => setFormData({ ...formData, data_agendada: s.date })}
                  className={`text-xs ${formData.data_agendada === s.date ? 'bg-blue-600 text-white' : ''}`}
                >
                  {s.label}
                </Button>
              ))}
            </div>
          </div>

          {/* Data Manual */}
          <div>
            <Label className="flex items-center gap-2 mb-2">
              <Calendar className="w-4 h-4" />
              Data da Entrega
            </Label>
            <Input
              type="date" lang="pt-BR"
              value={formData.data_agendada}
              onChange={e => setFormData({ ...formData, data_agendada: e.target.value })}
              min={format(hoje, 'yyyy-MM-dd')}
            />
          </div>

          {/* Turno - Botões lado a lado */}
          <div>
            <Label className="flex items-center gap-2 mb-2">
              <Clock className="w-4 h-4" />
              Turno
            </Label>
            <div className="grid grid-cols-2 gap-3">
              <Button
                type="button"
                variant={formData.turno === "Manhã" ? "default" : "outline"}
                onClick={() => setFormData({ ...formData, turno: "Manhã" })}
                className={`h-14 flex flex-col items-center justify-center gap-1 ${formData.turno === "Manhã"
                  ? 'bg-amber-500 hover:bg-amber-600 text-white border-amber-500'
                  : 'hover:border-amber-400 hover:text-amber-600'
                  }`}
              >
                <Sun className="w-5 h-5" />
                <span className="text-sm font-medium">Manhã</span>
                <span className="text-xs opacity-70">8h - 12h</span>
              </Button>
              <Button
                type="button"
                variant={formData.turno === "Tarde" ? "default" : "outline"}
                onClick={() => setFormData({ ...formData, turno: "Tarde" })}
                className={`h-14 flex flex-col items-center justify-center gap-1 ${formData.turno === "Tarde"
                  ? 'bg-orange-600 hover:bg-orange-700 text-white border-orange-600'
                  : 'hover:border-orange-400 hover:text-orange-600'
                  }`}
              >
                <Sunset className="w-5 h-5" />
                <span className="text-sm font-medium">Tarde</span>
                <span className="text-xs opacity-70">13h - 18h</span>
              </Button>
            </div>
          </div>

          {/* Caminhão - Botões lado a lado */}
          <div>
            <Label className="flex items-center gap-2 mb-2">
              <Truck className="w-4 h-4" />
              Caminhão
            </Label>
            <div className="grid grid-cols-2 gap-3">
              {caminhoesAtivos.map(c => (
                <Button
                  key={c.id}
                  type="button"
                  variant={formData.caminhao_id === c.id ? "default" : "outline"}
                  onClick={() => setFormData({ ...formData, caminhao_id: c.id })}
                  className={`h-14 flex flex-col items-center justify-center gap-1 ${formData.caminhao_id === c.id
                    ? 'bg-green-700 hover:bg-green-800 text-white border-green-700'
                    : 'hover:border-green-500 hover:text-green-700'
                    }`}
                >
                  <Truck className="w-5 h-5" />
                  <span className="text-sm font-bold">{c.nome}</span>
                  {c.placa && <span className="text-xs opacity-70">{c.placa}</span>}
                </Button>
              ))}
              {caminhoesAtivos.length === 0 && (
                <p className="col-span-2 text-center text-gray-400 text-sm py-4">
                  Nenhum caminhão cadastrado
                </p>
              )}
            </div>
          </div>

          {/* Responsável */}
          <div>
            <Label className="mb-2 block">Responsável (opcional)</Label>
            <Input
              value={formData.responsavel}
              onChange={e => setFormData({ ...formData, responsavel: e.target.value })}
              placeholder="Nome do entregador"
            />
          </div>

          {/* Observações */}
          <div>
            <Label className="mb-2 block">Observações</Label>
            <Textarea
              value={formData.observacoes}
              onChange={e => setFormData({ ...formData, observacoes: e.target.value })}
              placeholder="Instruções especiais..."
              rows={2}
            />
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={onClose}>Cancelar</Button>
          <Button
            onClick={handleSave}
            disabled={!formData.data_agendada || updateMutation.isPending}
            className="bg-blue-600 hover:bg-blue-700"
          >
            <Save className="w-4 h-4 mr-2" />
            {updateMutation.isPending ? 'Salvando...' : `Agendar ${isMultiple ? totalEntregas + ' Entregas' : ''}`}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Printer, Calendar, MapPin, User, Phone, CheckCircle, Clock, AlertTriangle, Edit2 } from "lucide-react";
import { format, differenceInDays, addDays } from "date-fns";
import { base44 } from "@/api/base44Client";
import { EMPRESA } from "@/config/empresa";
import { supabase } from "@/lib/supabase";
import { useMutation, useQueryClient, useQuery } from "@tanstack/react-query";
import { useAuth } from "@/hooks/useAuth";
import { useTenant } from "@/contexts/TenantContext";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import AgendarEntregaModal from "./AgendarEntregaModal";

export default function EntregasPendentes({ entregas, vendas, clientes }) {
  const { brandName, brandLogo } = useTenant();
  const [selecionados, setSelecionados] = useState([]);
  const [imprimindo, setImprimindo] = useState(false);
  const { user, can } = useAuth();
  const [modalAgendar, setModalAgendar] = useState({ open: false, entrega: null, multiplos: [] });
  const [modalPrazo, setModalPrazo] = useState({ open: false, entrega: null });
  const [novoPrazo, setNovoPrazo] = useState("");
  const [novaDataLimite, setNovaDataLimite] = useState("");

  const queryClient = useQueryClient();

  const { data: prazosConfig = [] } = useQuery({
    queryKey: ['prazos_entrega'],
    queryFn: async () => {
      const { data, error } = await supabase.from('prazos_entrega').select('*');
      if (error) throw error;
      return data || [];
    }
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, data }) => base44.entities.Entrega.update(id, data),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['entregas'] })
  });

  const updatePrazoMutation = useMutation({
    mutationFn: async ({ entregaId, vendaId, prazo, dataLimite }) => {
      // 1. Atualizar Entrega
      await base44.entities.Entrega.update(entregaId, {
        prazo_entrega: prazo,
        data_limite: dataLimite
      });

      // 2. Atualizar Venda se existir vendaId
      if (vendaId) {
        await base44.entities.Venda.update(vendaId, {
          prazo_entrega: prazo
        });
      }
      return true;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['entregas'] });
      queryClient.invalidateQueries({ queryKey: ['vendas'] });
      toast.success("Prazo de entrega atualizado com sucesso!");
      setModalPrazo({ open: false, entrega: null });
    },
    onError: (err) => {
      console.error("Erro ao atualizar prazo:", err);
      toast.error("Erro ao atualizar prazo de entrega.");
    }
  });

  const isAdmin = user?.cargo === 'Administrador' || can('manage_vendas');

  // Separar impressos e não impressos
  const naoImpressos = entregas.filter(e => !e.impresso);

  const toggleSelecao = (id) => {
    setSelecionados(prev =>
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  const selecionarTodos = () => {
    const ids = entregas.map(e => e.id);
    const allSelected = ids.every(id => selecionados.includes(id));
    setSelecionados(allSelected ? [] : ids);
  };

  const gerarFichaInternaHTML = (entrega, venda, cliente) => {
    const enderecoCompleto = cliente?.endereco ?
      `${cliente.endereco}, ${cliente.numero || 's/n'}${cliente.complemento ? ` - ${cliente.complemento}` : ''}, ${cliente.bairro || ''}, ${cliente.cidade || ''} - ${cliente.estado || ''}` :
      entrega.endereco_entrega || 'SEM ENDEREÇO';

    const itensHTML = venda?.itens?.map(item =>
      `<tr><td style="padding:8px;border-bottom:1px solid #ddd;">${item.produto_nome}</td><td style="padding:8px;border-bottom:1px solid #ddd;text-align:center;font-weight:bold;">${item.quantidade}</td></tr>`
    ).join('') || '<tr><td colspan="2" style="padding:8px;color:#999;">Sem itens</td></tr>';

    return `
      <div class="ficha" style="page-break-after: always; padding: 20px; font-family: Arial, sans-serif; font-size: 12px; border: 2px solid #333; margin-bottom: 20px; min-height: 90vh; display: flex; flex-direction: column;">
        <!-- Cabeçalho -->
        <div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 3px solid #07593f; padding-bottom: 10px; margin-bottom: 15px;">
          <div style="display: flex; align-items: center; gap: 10px;">
            {brandLogo || EMPRESA.logo_url ? (
              <img src={brandLogo || EMPRESA.logo_url} alt="Logo" style="width: 40px; height: auto;" />
            ) : null}
            <div>
              <div style="font-size: 14px; font-weight: bold; color: #07593f;">${brandName || EMPRESA.nome}</div>
              <div style="font-size: 9px; color: #666;">FICHA DE EXPEDIÇÃO</div>
            </div>
          </div>
          <div style="text-align: right;">
            <div style="font-size: 24px; font-weight: bold; color: #07593f;">#${entrega.numero_pedido}</div>
            <div style="font-size: 10px; color: #666;">Limite: ${entrega.data_limite ? format(new Date(entrega.data_limite + 'T12:00:00'), 'dd/MM/yyyy') : '-'}</div>
          </div>
        </div>

        <!-- Informações do Cliente -->
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 15px; margin-bottom: 15px;">
          <div style="background: #f5f5f5; padding: 12px; border-radius: 6px;">
            <div style="font-size: 10px; color: #666; text-transform: uppercase; margin-bottom: 5px;">Cliente</div>
            <div style="font-size: 14px; font-weight: bold; color: #333;">${cliente?.nome_completo || entrega.cliente_nome}</div>
            <div style="font-size: 11px; color: #666; margin-top: 4px;">Tel: ${cliente?.telefone || entrega.cliente_telefone || '-'}</div>
          </div>
          <div style="background: #f5f5f5; padding: 12px; border-radius: 6px;">
            <div style="font-size: 10px; color: #666; text-transform: uppercase; margin-bottom: 5px;">Endereço de Entrega</div>
            <div style="font-size: 12px; font-weight: bold; color: #333;">${enderecoCompleto}</div>
          </div>
        </div>

        <!-- Tabela de Produtos -->
        <table style="width: 100%; border-collapse: collapse; margin-bottom: 15px;">
          <thead>
            <tr style="background: #333; color: white;">
              <th style="padding: 8px; text-align: left;">Produto</th>
              <th style="padding: 8px; text-align: center; width: 80px;">Qtd</th>
            </tr>
          </thead>
          <tbody>${itensHTML}</tbody>
        </table>

        <!-- Alerta de Pagamento -->
        ${venda?.pagamento_na_entrega ? `
          <div style="border: 4px dashed #dc2626; background: #fef2f2; padding: 20px; border-radius: 10px; text-align: center; margin-bottom: 15px;">
            <div style="color: #991b1b; font-size: 16px; font-weight: bold; margin-bottom: 10px;">⚠️ RECEBER NA ENTREGA</div>
            <div style="font-size: 28px; font-weight: bold; color: #dc2626;">R$ ${venda.valor_pagamento_entrega?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</div>
            <div style="color: #991b1b; margin-top: 12px; font-size: 18px; padding: 8px 16px; background: #fee2e2; border-radius: 6px; display: inline-block;">
              Receber em: <strong>${venda.forma_pagamento_entrega || 'A COMBINAR'}</strong>
            </div>
          </div>
        ` : `
          <div style="padding: 15px; background: #d1fae5; border-radius: 8px; text-align: center; font-weight: bold; color: #065f46; margin-bottom: 15px;">
            ✅ PAGAMENTO JÁ REALIZADO - SEM COBRANÇA
          </div>
        `}

        ${entrega.observacoes ? `
          <div style="background: #fff7ed; padding: 10px; border-radius: 4px; border-left: 3px solid #f97316; margin-bottom: 15px;">
            <strong style="color: #9a3412;">Obs:</strong> <span style="color: #9a3412;">${entrega.observacoes}</span>
          </div>
        ` : ''}

        <!-- Espaçador flexível -->
        <div style="flex: 1;"></div>

        <!-- Área de Observações do Cliente (fixo no fim) -->
        <div style="border: 1px solid #ccc; border-radius: 6px; padding: 10px; margin-bottom: 15px;">
          <div style="font-size: 10px; color: #666; text-transform: uppercase; margin-bottom: 8px;">Observações do Cliente na Entrega:</div>
          <div style="border-bottom: 1px solid #ddd; height: 20px; margin-bottom: 8px;"></div>
          <div style="border-bottom: 1px solid #ddd; height: 20px; margin-bottom: 8px;"></div>
          <div style="border-bottom: 1px solid #ddd; height: 20px;"></div>
        </div>

        <!-- Assinaturas (fixo no fim) -->
        <div style="display: flex; justify-content: space-between; border-top: 1px dashed #ccc; padding-top: 15px;">
          <div style="flex: 1; text-align: center; border-right: 1px dashed #ccc; padding-right: 20px;">
            <div style="border-top: 1px solid #333; margin-top: 50px; padding-top: 5px; font-size: 10px; color: #666;">Assinatura do Cliente</div>
            <div style="font-size: 9px; color: #999; margin-top: 2px;">${cliente?.nome_completo || entrega.cliente_nome}</div>
          </div>
          <div style="flex: 1; text-align: center; padding-left: 20px;">
            <div style="border-top: 1px solid #333; margin-top: 50px; padding-top: 5px; font-size: 10px; color: #666;">Assinatura do Entregador</div>
            <div style="font-size: 9px; color: #999; margin-top: 2px;">Data: ___/___/______</div>
          </div>
        </div>

        <div style="text-align: right; font-size: 9px; color: #999; margin-top: 10px;">
          Impresso em: ${new Date().toLocaleString('pt-BR')}
        </div>
      </div>
    `;
  };

  const imprimirFichas = async (entregasParaImprimir) => {
    setImprimindo(true);

    const fichasHTML = entregasParaImprimir.map(entrega => {
      const venda = vendas.find(v => v.id === entrega.venda_id);
      const cliente = clientes.find(c => c.id === venda?.cliente_id);
      return gerarFichaInternaHTML(entrega, venda, cliente);
    }).join('');

    const htmlCompleto = `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <title>Fichas de Expedição</title>
        <style>
          @page { size: A4; margin: 10mm; }
          @media print { 
            body { padding: 0; margin: 0; }
            .ficha:last-child { page-break-after: avoid; }
          }
        </style>
      </head>
      <body>${fichasHTML}</body>
      </html>
    `;

    const printWindow = window.open('', '_blank');
    printWindow.document.write(htmlCompleto);
    printWindow.document.close();
    printWindow.focus();

    setTimeout(async () => {
      printWindow.print();

      // Marcar como impressos
      for (const entrega of entregasParaImprimir) {
        await updateMutation.mutateAsync({
          id: entrega.id,
          data: { impresso: true, data_impressao: new Date().toISOString() }
        });
      }

      setSelecionados([]);
      setImprimindo(false);
    }, 500);
  };

  const imprimirSelecionados = () => {
    const entregasParaImprimir = entregas.filter(e => selecionados.includes(e.id));
    if (entregasParaImprimir.length > 0) {
      imprimirFichas(entregasParaImprimir);
    }
  };

  const imprimirNovos = () => {
    if (naoImpressos.length > 0) {
      imprimirFichas(naoImpressos);
    }
  };

  const imprimirUm = (entrega) => {
    imprimirFichas([entrega]);
  };

  const agendarSelecionados = () => {
    const entregasParaAgendar = entregas.filter(e => selecionados.includes(e.id));
    if (entregasParaAgendar.length > 0) {
      setModalAgendar({ open: true, entrega: null, multiplos: entregasParaAgendar });
    }
  };

  const getDiasRestantes = (dataLimite) => {
    if (!dataLimite) return null;
    const dias = differenceInDays(new Date(dataLimite + 'T12:00:00'), new Date());
    return dias;
  };

  const getUrgenciaBadge = (dataLimite) => {
    const dias = getDiasRestantes(dataLimite);
    if (dias === null) return null;
    if (dias < 0) return <Badge className="bg-red-600 text-white"><AlertTriangle className="w-3 h-3 mr-1" />Atrasado</Badge>;
    if (dias <= 3) return <Badge className="bg-orange-500 text-white"><Clock className="w-3 h-3 mr-1" />{dias}d</Badge>;
    if (dias <= 7) return <Badge className="bg-yellow-500 text-white">{dias}d</Badge>;
    return <Badge className="bg-green-600 text-white">{dias}d</Badge>;
  };

  if (entregas.length === 0) {
    return (
      <Card className="border-0 shadow-lg">
        <CardContent className="text-center py-16">
          <CheckCircle className="w-16 h-16 mx-auto mb-4 text-green-500 opacity-50" />
          <p className="text-xl font-semibold text-green-700 mb-2">Tudo em dia!</p>
          <p className="text-gray-500">Nenhuma entrega pendente no momento.</p>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      {/* Barra de Ações */}
      <Card className="border-0 shadow-md bg-gradient-to-r from-green-50 to-blue-50 dark:from-green-900/20 dark:to-blue-900/20">
        <CardContent className="p-4">
          <div className="flex flex-wrap items-center justify-between gap-4">
            <div className="flex items-center gap-4">
              <Button
                variant="outline"
                size="sm"
                onClick={selecionarTodos}
                className="text-xs"
              >
                {selecionados.length === entregas.length ? 'Desmarcar Todos' : 'Selecionar Todos'}
              </Button>
              <div className="text-sm">
                <span className="text-gray-500">Total:</span>{" "}
                <span className="font-bold text-gray-900 dark:text-white">{entregas.length}</span>
                {naoImpressos.length > 0 && (
                  <span className="ml-2 text-orange-600 font-medium">
                    ({naoImpressos.length} novos)
                  </span>
                )}
              </div>
              {selecionados.length > 0 && (
                <Badge variant="secondary" className="bg-blue-100 text-blue-800">
                  {selecionados.length} selecionados
                </Badge>
              )}
            </div>
            <div className="flex gap-2 flex-wrap">
              {selecionados.length > 0 && (
                <>
                  <Button
                    onClick={agendarSelecionados}
                    className="bg-blue-600 hover:bg-blue-700 text-white"
                  >
                    <Calendar className="w-4 h-4 mr-2" />
                    Agendar ({selecionados.length})
                  </Button>
                  <Button
                    onClick={imprimirSelecionados}
                    disabled={imprimindo}
                    variant="outline"
                    className="border-green-600 text-green-700 hover:bg-green-50"
                  >
                    <Printer className="w-4 h-4 mr-2" />
                    Imprimir ({selecionados.length})
                  </Button>
                </>
              )}
              {naoImpressos.length > 0 && (
                <Button
                  onClick={imprimirNovos}
                  disabled={imprimindo}
                  className="bg-orange-600 hover:bg-orange-700 text-white"
                >
                  <Printer className="w-4 h-4 mr-2" />
                  Imprimir Novos ({naoImpressos.length})
                </Button>
              )}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Lista de Entregas */}
      <div className="space-y-3">
        {entregas.map((entrega) => {
          const venda = vendas.find(v => v.id === entrega.venda_id);

          return (
            <Card
              key={entrega.id}
              className={`border shadow-sm hover:shadow-md transition-all ${selecionados.includes(entrega.id)
                ? 'border-blue-400 bg-blue-50/50 dark:bg-blue-900/10'
                : entrega.impresso
                  ? 'bg-gray-50 dark:bg-neutral-800/50 border-gray-200'
                  : 'bg-white dark:bg-neutral-900 border-orange-200'
                }`}
            >
              <CardContent className="p-4">
                <div className="flex items-start gap-4">
                  {/* Checkbox */}
                  <div className="pt-1">
                    <Checkbox
                      checked={selecionados.includes(entrega.id)}
                      onCheckedChange={() => toggleSelecao(entrega.id)}
                    />
                  </div>

                  {/* Conteúdo Principal */}
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-3 mb-2">
                      <span className="font-bold text-lg text-green-800 dark:text-green-400">
                        #{entrega.numero_pedido}
                      </span>
                      <div className="flex items-center gap-1">
                        {getUrgenciaBadge(entrega.data_limite)}
                        {isAdmin && (
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-6 w-6 text-gray-400 hover:text-blue-600"
                            onClick={(e) => {
                              e.stopPropagation();
                              setModalPrazo({ open: true, entrega });
                              setNovoPrazo(entrega.prazo_entrega || "");
                              setNovaDataLimite(entrega.data_limite || "");
                            }}
                          >
                            <Edit2 className="w-3 h-3" />
                          </Button>
                        )}
                      </div>
                      {entrega.impresso && (
                        <Badge variant="outline" className="border-green-500 text-green-600">
                          <CheckCircle className="w-3 h-3 mr-1" />
                          Impresso
                        </Badge>
                      )}
                      {venda?.pagamento_na_entrega && (
                        <Badge className="bg-red-100 text-red-700 border border-red-300">
                          💰 Receber R$ {venda.valor_pagamento_entrega?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                        </Badge>
                      )}
                    </div>

                    <div className="grid md:grid-cols-2 gap-3 text-sm">
                      <div className="flex items-center gap-2 text-gray-700 dark:text-gray-300">
                        <User className="w-4 h-4 text-green-600" />
                        <span className="font-medium">{entrega.cliente_nome}</span>
                      </div>
                      {entrega.cliente_telefone && (
                        <div className="flex items-center gap-2 text-gray-500">
                          <Phone className="w-4 h-4" />
                          {entrega.cliente_telefone}
                        </div>
                      )}
                      {entrega.endereco_entrega && (
                        <div className="flex items-start gap-2 text-gray-500 md:col-span-2">
                          <MapPin className="w-4 h-4 mt-0.5 flex-shrink-0 text-orange-500" />
                          <span className="line-clamp-1">{entrega.endereco_entrega}</span>
                        </div>
                      )}
                    </div>

                    {entrega.observacoes && (
                      <div className="mt-2 text-sm text-orange-700 bg-orange-50 dark:bg-orange-900/20 dark:text-orange-400 px-3 py-1.5 rounded">
                        <strong>Obs:</strong> {entrega.observacoes}
                      </div>
                    )}
                  </div>

                  {/* Ações */}
                  <div className="flex flex-col gap-2">
                    <Button
                      size="sm"
                      onClick={() => setModalAgendar({ open: true, entrega, multiplos: [] })}
                      className="bg-blue-600 hover:bg-blue-700 text-white text-xs"
                    >
                      <Calendar className="w-3 h-3 mr-1" />
                      Agendar
                    </Button>
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => imprimirUm(entrega)}
                      disabled={imprimindo}
                      className="text-xs"
                    >
                      <Printer className="w-3 h-3 mr-1" />
                      Imprimir
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>

      {/* Modal de Agendamento */}
      <AgendarEntregaModal
        isOpen={modalAgendar.open}
        onClose={() => setModalAgendar({ open: false, entrega: null, multiplos: [] })}
        entrega={modalAgendar.entrega}
        entregasSelecionadas={modalAgendar.multiplos}
      />

      {/* Modal de Troca de Prazo (Admin) */}
      <Dialog open={modalPrazo.open} onOpenChange={(open) => !open && setModalPrazo({ open: false, entrega: null })}>
        <DialogContent className="sm:max-w-[425px]">
          <DialogHeader>
            <DialogTitle>Alterar Prazo de Entrega</DialogTitle>
            <DialogDescription>
              Ajuste o prazo de entrega para o pedido #{modalPrazo.entrega?.numero_pedido}.
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="space-y-2">
              <Label>Prazo Padrão</Label>
              <Select
                value={novoPrazo}
                onValueChange={(v) => {
                  setNovoPrazo(v);
                  const diasStr = v.match(/\d+/);
                  if (diasStr) {
                    const dias = parseInt(diasStr[0]);
                    setNovaDataLimite(format(addDays(new Date(), dias), 'yyyy-MM-dd'));
                  }
                }}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Selecione um prazo..." />
                </SelectTrigger>
                <SelectContent>
                  {prazosConfig.length === 0 ? (
                    <SelectItem value="15 dias úteis" disabled>Carregando...</SelectItem>
                  ) : (
                    prazosConfig.map(p => {
                      const label = `${p.quantidade_dias} dias ${p.tipo_dias === 'uteis' ? 'úteis' : 'corridos'}`;
                      return (
                        <SelectItem key={p.id} value={label}>
                          {label}
                        </SelectItem>
                      );
                    })
                  )}
                  {novoPrazo === "Retirado na loja" && (
                    <SelectItem value="Retirado na loja" disabled>Retirado na loja</SelectItem>
                  )}
                  <SelectItem value="Customizado">Customizado</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label>Data Limite Sugerida/Final</Label>
              <Input
                type="date" lang="pt-BR"
                value={novaDataLimite}
                onChange={(e) => setNovaDataLimite(e.target.value)}
              />
              <p className="text-[10px] text-gray-500">
                Esta data define a prioridade no funil logístico.
              </p>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setModalPrazo({ open: false, entrega: null })}>
              Cancelar
            </Button>
            <Button
              onClick={() => updatePrazoMutation.mutate({
                entregaId: modalPrazo.entrega?.id,
                vendaId: modalPrazo.entrega?.venda_id,
                prazo: novoPrazo,
                dataLimite: novaDataLimite
              })}
              disabled={updatePrazoMutation.isPending}
              className="bg-green-600 hover:bg-green-700"
            >
              {updatePrazoMutation.isPending ? "Salvando..." : "Salvar Alteração"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useState, useMemo } from "react";
import { base44 } from "@/api/base44Client";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Checkbox } from "@/components/ui/checkbox";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useConfirm } from "@/hooks/useConfirm";
import { useAuth } from "@/hooks/useAuth";
import { formatBrazilDate } from "@/lib/dateBrazil";
import {
  Search,
  CheckSquare,
  X,
  CheckCircle2,
  AlertCircle,
  TrendingUp,
  TrendingDown,
  Loader2,
  Filter,
  ArrowRight,
  RefreshCw
} from "lucide-react";

export default function AlteracaoEmMassaModal({ open, onOpenChange, lancamentos = [], categorias = [] }) {
  const queryClient = useQueryClient();
  const confirm = useConfirm();
  const { user } = useAuth();

  // Estados locais do modal
  const [busca, setBusca] = useState("");
  const [tipoFiltro, setTipoFiltro] = useState("todos"); // todos, entrada, saida
  const [statusFiltro, setStatusFiltro] = useState("pendente"); // todos, pendente, pago, cancelado (padrão pendente)
  const [categoriaFiltro, setCategoriaFiltro] = useState("todos");

  const [selectedIds, setSelectedIds] = useState(new Set());
  const [novoStatus, setNovoStatus] = useState("Pago"); // Pago ou Pendente ou Cancelado
  const [etapa, setEtapa] = useState("selecao"); // selecao | confirmacao
  const [isExecuting, setIsExecuting] = useState(false);
  const [executionResult, setExecutionResult] = useState(null);

  // Resetar ao fechar ou abrir
  const handleClose = (isOpen) => {
    onOpenChange(isOpen);
    if (!isOpen) {
      setEtapa("selecao");
      setSelectedIds(new Set());
      setBusca("");
      setExecutionResult(null);
      setIsExecuting(false);
    }
  };

  // Filtragem dos lançamentos
  const lancamentosFiltrados = useMemo(() => {
    return lancamentos.filter((lanc) => {
      // Busca por texto (descrição, categoria, valor, data)
      if (busca.trim()) {
        const termo = busca.toLowerCase().trim();
        const matchDesc = lanc.descricao?.toLowerCase().includes(termo);
        const matchCat = lanc.categoria_nome?.toLowerCase().includes(termo);
        const matchValor = String(lanc.valor || "").includes(termo);
        const matchForma = lanc.forma_pagamento?.toLowerCase().includes(termo);
        const matchData = (lanc.data_vencimento || lanc.data_lancamento || "").includes(termo);

        if (!matchDesc && !matchCat && !matchValor && !matchForma && !matchData) {
          return false;
        }
      }

      // Filtro de Tipo
      if (tipoFiltro !== "todos") {
        const isEntrada = lanc.tipo === "Entrada" || lanc.tipo === "receita";
        if (tipoFiltro === "entrada" && !isEntrada) return false;
        if (tipoFiltro === "saida" && isEntrada) return false;
      }

      // Filtro de Status
      if (statusFiltro !== "todos") {
        const statusAtual = lanc.status || "Pendente";
        if (statusFiltro === "pendente" && statusAtual !== "Pendente") return false;
        if (statusFiltro === "pago" && statusAtual !== "Pago") return false;
        if (statusFiltro === "cancelado" && statusAtual !== "Cancelado") return false;
      }

      // Filtro de Categoria
      if (categoriaFiltro !== "todos") {
        if (String(lanc.categoria_id) !== String(categoriaFiltro) && lanc.categoria_nome !== categoriaFiltro) {
          return false;
        }
      }

      return true;
    });
  }, [lancamentos, busca, tipoFiltro, statusFiltro, categoriaFiltro]);

  // Lista de lançamentos selecionados (objetos completos)
  const lancamentosSelecionados = useMemo(() => {
    return lancamentos.filter((l) => selectedIds.has(l.id));
  }, [lancamentos, selectedIds]);

  // Valor total selecionado
  const totalValorSelecionado = useMemo(() => {
    return lancamentosSelecionados.reduce((sum, l) => sum + Number(l.valor || 0), 0);
  }, [lancamentosSelecionados]);

  // Handlers de seleção
  const toggleSelect = (id) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  };

  const selecionarTodosFiltrados = () => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      lancamentosFiltrados.forEach((l) => next.add(l.id));
      return next;
    });
  };

  const limparSelecao = () => {
    setSelectedIds(new Set());
  };

  const removerToken = (id) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      next.delete(id);
      return next;
    });
  };

  // Executar alteração em massa
  const executarAlteracaoEmMassa = async () => {
    if (selectedIds.size === 0) return;

    setIsExecuting(true);
    setExecutionResult(null);

    let sucessos = 0;
    let falhas = 0;
    const erros = [];

    try {
      for (const lanc of lancamentosSelecionados) {
        try {
          const previousStatus = lanc.status || "Pendente";
          await base44.entities.LancamentoFinanceiro.update(lanc.id, { status: novoStatus });

          // Se marcou como Pago, adiciona Log de Auditoria
          if (novoStatus === "Pago" && previousStatus !== "Pago") {
            try {
              await base44.entities.AuditLog.create({
                acao: "MARK_PAID",
                usuario: user?.full_name || user?.nome || user?.email || "Usuário desconhecido",
                user_id: user?.id || null,
                tabela: "lancamentos_financeiros",
                detalhes: {
                  record_id: lanc.id,
                  descricao: lanc.descricao || null,
                  categoria: lanc.categoria_nome || null,
                  valor: lanc.valor ?? null,
                  data_vencimento: lanc.data_vencimento || null,
                  from_status: previousStatus,
                  to_status: novoStatus,
                  origem: "alteracao_em_massa"
                },
              });
            } catch (err) {
              console.error("Erro audit log:", err);
            }
          }

          sucessos++;
        } catch (err) {
          falhas++;
          erros.push(`${lanc.descricao}: ${err.message || "Erro de atualização"}`);
        }
      }

      queryClient.invalidateQueries({ queryKey: ["lancamentos-financeiros"] });
      queryClient.invalidateQueries({ queryKey: ["audit-mark-paid"] });

      setExecutionResult({
        sucessos,
        falhas,
        erros,
      });

    } catch (err) {
      setExecutionResult({
        sucessos,
        falhas: selectedIds.size - sucessos,
        erros: [err.message || "Erro ao processar alteração em massa."]
      });
    } finally {
      setIsExecuting(false);
    }
  };

  const formatMoney = (val) =>
    `R$ ${Math.abs(val || 0).toLocaleString("pt-BR", { minimumFractionDigits: 2 })}`;

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="max-w-4xl max-h-[92vh] overflow-hidden flex flex-col p-0">
        <DialogHeader className="p-5 pb-3 border-b bg-gray-50/50 dark:bg-neutral-900/50">
          <div className="flex items-center justify-between">
            <div>
              <DialogTitle className="text-xl font-bold flex items-center gap-2 text-emerald-800 dark:text-emerald-400">
                <CheckSquare className="w-5 h-5 text-emerald-600" />
                Alteração em Massa de Lançamentos
              </DialogTitle>
              <DialogDescription className="text-sm text-gray-500 mt-1">
                Pesquise, selecione múltiplos lançamentos e altere o status de pagamento de uma só vez.
              </DialogDescription>
            </div>
          </div>
        </DialogHeader>

        {/* Conteúdo principal */}
        <div className="flex-1 overflow-y-auto p-5 space-y-4">
          {executionResult ? (
            /* Tela de Resultado da Operação */
            <div className="space-y-4 py-4">
              <div className="p-4 rounded-lg bg-green-50 border border-green-200 flex items-start gap-3">
                <CheckCircle2 className="w-6 h-6 text-green-600 shrink-0 mt-0.5" />
                <div className="flex-1">
                  <h4 className="font-bold text-green-900">Operação concluída com sucesso!</h4>
                  <p className="text-sm text-green-700 mt-1">
                    {executionResult.sucessos} lançamento(s) alterado(s) para o status <strong>{novoStatus}</strong>.
                  </p>
                  {executionResult.falhas > 0 && (
                    <p className="text-sm text-red-600 mt-1">
                      {executionResult.falhas} lançamento(s) apresentaram erro na alteração.
                    </p>
                  )}
                </div>
              </div>

              <div className="flex justify-end gap-3 pt-4">
                <Button
                  onClick={() => {
                    setExecutionResult(null);
                    setEtapa("selecao");
                    setSelectedIds(new Set());
                  }}
                  variant="outline"
                >
                  <RefreshCw className="w-4 h-4 mr-2" />
                  Realizar outra alteração
                </Button>
                <Button onClick={() => handleClose(false)}>
                  Concluir
                </Button>
              </div>
            </div>
          ) : etapa === "selecao" ? (
            /* ETAPA 1: Seleção de Lançamentos & Tokens */
            <div className="space-y-4">
              {/* Painel de Controle de Status de Destino */}
              <div className="p-4 rounded-xl border bg-gradient-to-r from-emerald-50/50 to-teal-50/50 dark:from-emerald-950/20 dark:to-teal-950/20 border-emerald-200 dark:border-emerald-900/50 flex flex-wrap items-center justify-between gap-4">
                <div className="space-y-1">
                  <Label className="text-xs font-semibold uppercase tracking-wider text-emerald-900 dark:text-emerald-300">
                    Definir Novo Status Desejado:
                  </Label>
                  <div className="flex items-center gap-2">
                    <Select value={novoStatus} onValueChange={setNovoStatus}>
                      <SelectTrigger className="w-[180px] bg-white dark:bg-neutral-800 font-semibold border-emerald-300">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="Pago">
                          <span className="flex items-center gap-2">
                            <Badge className="bg-green-100 text-green-800">Pago</Badge>
                          </span>
                        </SelectItem>
                        <SelectItem value="Pendente">
                          <span className="flex items-center gap-2">
                            <Badge className="bg-yellow-100 text-yellow-800">Pendente</Badge>
                          </span>
                        </SelectItem>
                        <SelectItem value="Cancelado">
                          <span className="flex items-center gap-2">
                            <Badge className="bg-gray-100 text-gray-600">Cancelado</Badge>
                          </span>
                        </SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                </div>

                {/* Resumo de Seleção */}
                <div className="flex items-center gap-4 text-right">
                  <div>
                    <p className="text-xs text-gray-500 font-medium">Lançamentos Selecionados</p>
                    <p className="text-lg font-bold text-emerald-800 dark:text-emerald-400">
                      {selectedIds.size} item(s)
                    </p>
                  </div>
                  <div className="h-8 w-px bg-emerald-200 dark:bg-emerald-800" />
                  <div>
                    <p className="text-xs text-gray-500 font-medium">Valor Total Acumulado</p>
                    <p className="text-lg font-bold text-gray-900 dark:text-white">
                      {formatMoney(totalValorSelecionado)}
                    </p>
                  </div>
                </div>
              </div>

              {/* Barra de Busca Tokenizada & Filtros */}
              <div className="space-y-2">
                <div className="flex flex-wrap gap-2">
                  <div className="relative flex-1 min-w-[240px]">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                    <Input
                      placeholder="Pesquisar por descrição, categoria, valor, data ou forma de pagamento..."
                      value={busca}
                      onChange={(e) => setBusca(e.target.value)}
                      className="pl-9"
                    />
                    {busca && (
                      <button
                        onClick={() => setBusca("")}
                        className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                      >
                        <X className="w-4 h-4" />
                      </button>
                    )}
                  </div>

                  <Select value={statusFiltro} onValueChange={setStatusFiltro}>
                    <SelectTrigger className="w-[140px]">
                      <SelectValue placeholder="Status" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="todos">Todos Status</SelectItem>
                      <SelectItem value="pendente">Apenas Pendentes</SelectItem>
                      <SelectItem value="pago">Apenas Pagos</SelectItem>
                      <SelectItem value="cancelado">Apenas Cancelados</SelectItem>
                    </SelectContent>
                  </Select>

                  <Select value={tipoFiltro} onValueChange={setTipoFiltro}>
                    <SelectTrigger className="w-[130px]">
                      <SelectValue placeholder="Tipo" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="todos">Todos Tipos</SelectItem>
                      <SelectItem value="saida">Saídas</SelectItem>
                      <SelectItem value="entrada">Entradas</SelectItem>
                    </SelectContent>
                  </Select>

                  {categorias.length > 0 && (
                    <Select value={categoriaFiltro} onValueChange={setCategoriaFiltro}>
                      <SelectTrigger className="w-[160px]">
                        <SelectValue placeholder="Categoria" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="todos">Todas Categorias</SelectItem>
                        {categorias.map((cat) => (
                          <SelectItem key={cat.id} value={String(cat.id)}>
                            {cat.nome}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  )}
                </div>

                {/* Tokens de Lançamentos Selecionados (Chips) */}
                {selectedIds.size > 0 && (
                  <div className="p-3 rounded-lg border bg-gray-50 dark:bg-neutral-900/40 space-y-2">
                    <div className="flex items-center justify-between">
                      <span className="text-xs font-semibold uppercase tracking-wider text-gray-500">
                        Tokens Selecionados ({selectedIds.size}):
                      </span>
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        className="h-6 text-xs text-red-600 hover:bg-red-50"
                        onClick={limparSelecao}
                      >
                        Limpar Seleção
                      </Button>
                    </div>

                    <div className="flex flex-wrap gap-1.5 max-h-28 overflow-y-auto pr-1">
                      {lancamentosSelecionados.map((item) => (
                        <Badge
                          key={item.id}
                          variant="secondary"
                          className="pl-2 pr-1 py-1 flex items-center gap-1.5 bg-white dark:bg-neutral-800 border shadow-sm text-xs"
                        >
                          <span className="font-semibold text-gray-900 dark:text-white truncate max-w-[200px]">
                            {item.descricao}
                          </span>
                          <span className="text-gray-400">·</span>
                          <span className="text-emerald-700 dark:text-emerald-400 font-bold">
                            {formatMoney(item.valor)}
                          </span>
                          <button
                            type="button"
                            onClick={() => removerToken(item.id)}
                            className="ml-1 rounded-full p-0.5 hover:bg-gray-200 dark:hover:bg-neutral-700 text-gray-400 hover:text-red-600 transition-colors"
                          >
                            <X className="w-3 h-3" />
                          </button>
                        </Badge>
                      ))}
                    </div>
                  </div>
                )}
              </div>

              {/* Ações Rápidas de Seleção da Lista */}
              <div className="flex items-center justify-between text-xs text-gray-500 pt-1">
                <span>
                  Exibindo <strong>{lancamentosFiltrados.length}</strong> de {lancamentos.length} lançamentos
                </span>
                <div className="flex items-center gap-2">
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    className="h-7 text-xs"
                    onClick={selecionarTodosFiltrados}
                    disabled={lancamentosFiltrados.length === 0}
                  >
                    Selecionar Todos da Busca ({lancamentosFiltrados.length})
                  </Button>
                </div>
              </div>

              {/* Tabela / Lista Candidata de Seleção */}
              <div className="border rounded-xl overflow-hidden divide-y max-h-[340px] overflow-y-auto">
                {lancamentosFiltrados.length === 0 ? (
                  <div className="text-center py-12 text-gray-500">
                    <Search className="w-8 h-8 mx-auto mb-2 opacity-30" />
                    <p className="text-sm font-medium">Nenhum lançamento encontrado para os filtros</p>
                  </div>
                ) : (
                  lancamentosFiltrados.map((lanc) => {
                    const isSelected = selectedIds.has(lanc.id);
                    const isEntrada = lanc.tipo === "Entrada" || lanc.tipo === "receita";

                    return (
                      <div
                        key={lanc.id}
                        onClick={() => toggleSelect(lanc.id)}
                        className={`flex items-center justify-between p-3 cursor-pointer transition-colors ${
                          isSelected
                            ? "bg-emerald-50/70 dark:bg-emerald-950/40 border-l-4 border-l-emerald-600"
                            : "hover:bg-gray-50 dark:hover:bg-neutral-800/50"
                        }`}
                      >
                        <div className="flex items-center gap-3 min-w-0 flex-1 mr-3">
                          <Checkbox
                            checked={isSelected}
                            onCheckedChange={() => toggleSelect(lanc.id)}
                            onClick={(e) => e.stopPropagation()}
                          />
                          <div className={`w-7 h-7 rounded-full flex items-center justify-center shrink-0 ${isEntrada ? "bg-green-100 text-green-700" : "bg-red-100 text-red-700"}`}>
                            {isEntrada ? <TrendingUp className="w-3.5 h-3.5" /> : <TrendingDown className="w-3.5 h-3.5" />}
                          </div>
                          <div className="min-w-0 flex-1">
                            <p className="font-semibold text-sm truncate text-gray-900 dark:text-white">
                              {lanc.descricao || "Sem descrição"}
                            </p>
                            <p className="text-xs text-gray-500 truncate">
                              {lanc.categoria_nome || "Sem categoria"} · Vence {formatBrazilDate(lanc.data_vencimento || lanc.data_lancamento)} · {lanc.forma_pagamento || "Dinheiro"}
                            </p>
                          </div>
                        </div>

                        <div className="flex items-center gap-3 shrink-0">
                          <span className={`text-sm font-bold ${isEntrada ? "text-green-600" : "text-red-600"}`}>
                            {formatMoney(lanc.valor)}
                          </span>
                          <Badge className={
                            lanc.status === "Pago"
                              ? "bg-green-100 text-green-800"
                              : lanc.status === "Cancelado"
                              ? "bg-gray-100 text-gray-600"
                              : "bg-yellow-100 text-yellow-800"
                          }>
                            {lanc.status || "Pendente"}
                          </Badge>
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            </div>
          ) : (
            /* ETAPA 2: Confirmação Detalhada */
            <div className="space-y-4 py-2">
              <div className="p-4 rounded-xl border border-amber-200 bg-amber-50/70 dark:bg-amber-950/30 flex items-start gap-3">
                <AlertCircle className="w-6 h-6 text-amber-600 shrink-0 mt-0.5" />
                <div className="flex-1">
                  <h4 className="font-bold text-amber-900 dark:text-amber-300">
                    Confirmar Alteração em Massa
                  </h4>
                  <p className="text-sm text-amber-800 dark:text-amber-400 mt-1">
                    Você está prestes a alterar o status de <strong>{selectedIds.size} lançamento(s)</strong> para{" "}
                    <Badge className="bg-emerald-700 text-white font-bold ml-1">{novoStatus}</Badge>.
                    O valor total acumulado nesta operação é de <strong>{formatMoney(totalValorSelecionado)}</strong>.
                  </p>
                </div>
              </div>

              <div className="space-y-2">
                <h4 className="font-semibold text-sm text-gray-700 dark:text-gray-300">
                  Lançamentos a serem alterados:
                </h4>
                <div className="border rounded-xl overflow-hidden divide-y max-h-[340px] overflow-y-auto">
                  {lancamentosSelecionados.map((lanc) => {
                    const isEntrada = lanc.tipo === "Entrada" || lanc.tipo === "receita";
                    return (
                      <div key={lanc.id} className="flex items-center justify-between p-3 bg-white dark:bg-neutral-800">
                        <div className="min-w-0 flex-1 mr-3">
                          <p className="font-semibold text-sm text-gray-900 dark:text-white truncate">
                            {lanc.descricao}
                          </p>
                          <p className="text-xs text-gray-500 truncate">
                            {lanc.categoria_nome || "Sem categoria"} · Vence {formatBrazilDate(lanc.data_vencimento || lanc.data_lancamento)} · {lanc.forma_pagamento || "Dinheiro"}
                          </p>
                        </div>
                        <div className="flex items-center gap-3 text-right">
                          <span className={`text-sm font-bold ${isEntrada ? "text-green-600" : "text-red-600"}`}>
                            {formatMoney(lanc.valor)}
                          </span>
                          <div className="flex items-center gap-1.5 text-xs font-semibold">
                            <Badge variant="outline" className="opacity-70">{lanc.status || "Pendente"}</Badge>
                            <ArrowRight className="w-3.5 h-3.5 text-gray-400" />
                            <Badge className="bg-emerald-600 text-white">{novoStatus}</Badge>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Rodapé de Ações */}
        {!executionResult && (
          <div className="p-4 border-t bg-gray-50/50 dark:bg-neutral-900/50 flex items-center justify-between">
            <Button
              type="button"
              variant="outline"
              onClick={() => {
                if (etapa === "confirmacao") {
                  setEtapa("selecao");
                } else {
                  handleClose(false);
                }
              }}
              disabled={isExecuting}
            >
              {etapa === "confirmacao" ? "Voltar à seleção" : "Cancelar"}
            </Button>

            {etapa === "selecao" ? (
              <Button
                type="button"
                onClick={() => setEtapa("confirmacao")}
                disabled={selectedIds.size === 0}
                className="bg-emerald-700 hover:bg-emerald-800 text-white"
              >
                Avançar ({selectedIds.size} selecionados)
                <ArrowRight className="w-4 h-4 ml-2" />
              </Button>
            ) : (
              <Button
                type="button"
                onClick={executarAlteracaoEmMassa}
                disabled={isExecuting}
                className="bg-emerald-700 hover:bg-emerald-800 text-white font-bold"
              >
                {isExecuting ? (
                  <>
                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                    Aplicando alterações...
                  </>
                ) : (
                  <>
                    <CheckCircle2 className="w-4 h-4 mr-2" />
                    Confirmar e Alterar ({selectedIds.size} lançamentos)
                  </>
                )}
              </Button>
            )}
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { base44 } from "@/lib/supabase";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Select, SelectTrigger, SelectContent, SelectItem, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Loader2, CheckCircle2, XCircle, ExternalLink,
  FileText, Building2, CalendarDays, Banknote
} from "lucide-react";
import { toast } from "sonner";
import { useConfirm } from "@/hooks/useConfirm";

function OcApprovalCard({ oc, categorias, currentUser }) {
  const solicitacao = oc.metadata?.solicitacao_financeiro || {};
  const [form, setForm] = useState({
    categoria_id: solicitacao.categoria_id || "",
    data_vencimento: solicitacao.data_vencimento || "",
    forma_pagamento: solicitacao.forma_pagamento || "",
    ja_pago: false,
    data_pagamento: "",
  });
  const [formError, setFormError] = useState("");
  const queryClient = useQueryClient();
  const confirm = useConfirm();

  const aprovaMutation = useMutation({
    mutationFn: async () => {
      const statusLancamento = form.ja_pago ? "Pago" : "Pendente";
      const categoriaObj = categorias.find(c => c.id === form.categoria_id);
      const ultimoAnexo = oc.anexos_financeiro?.[oc.anexos_financeiro.length - 1];
      const anexoUrl = ultimoAnexo?.url || solicitacao.anexo_url || "";

      await base44.entities.LancamentoFinanceiro.create({
        tipo: "Saída",
        categoria_id: form.categoria_id,
        categoria_nome: categoriaObj?.nome || solicitacao.categoria_nome || "",
        descricao: solicitacao.descricao || `Compra OC #${oc.numero_pedido}`,
        valor: Number(oc.valor_total || 0),
        status: statusLancamento,
        data_vencimento: form.data_vencimento,
        data_pagamento: form.ja_pago ? (form.data_pagamento || new Date().toISOString().slice(0, 10)) : null,
        forma_pagamento: form.forma_pagamento,
        observacao: solicitacao.observacao || "",
        detalhe_devolucao: solicitacao.detalhe_devolucao || "",
        anexo_url: anexoUrl,
        numero_pedido: oc.numero_pedido,
        fornecedor_nome: oc.fornecedor_nome,
        origem: `OC#${oc.numero_pedido}`,
      });

      await base44.entities.ComprasOrden.update(oc.id, {
        pagamento_status: "pago",
        pagamento_aprovado_por: currentUser?.full_name || currentUser?.email || currentUser?.nome || "Financeiro",
        pagamento_aprovado_em: new Date().toISOString(),
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["compras"] });
      queryClient.invalidateQueries({ queryKey: ["compras-pendentes-aprovacao"] });
      queryClient.invalidateQueries({ queryKey: ["lancamentos-financeiros"] });
      toast.success(`OC #${oc.numero_pedido} aprovada e lançamento gerado.`);
    },
    onError: (err) => {
      toast.error(err?.message || "Erro ao aprovar pedido.");
    },
  });

  const cancelaMutation = useMutation({
    mutationFn: async () => {
      await base44.entities.ComprasOrden.update(oc.id, {
        status: "Cancelada",
        pagamento_status: "nao_aplicavel",
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["compras"] });
      queryClient.invalidateQueries({ queryKey: ["compras-pendentes-aprovacao"] });
      toast.success(`Pedido OC #${oc.numero_pedido} cancelado.`);
    },
    onError: (err) => {
      toast.error(err?.message || "Erro ao cancelar pedido.");
    },
  });

  const handleAprovar = () => {
    setFormError("");
    if (!form.categoria_id) return setFormError("Selecione uma categoria para o lançamento.");
    if (!form.data_vencimento) return setFormError("Informe a data de vencimento.");
    aprovaMutation.mutate();
  };

  const handleCancelar = async () => {
    const ok = await confirm({
      title: "Cancelar e Excluir Pedido",
      message: `Confirma o cancelamento da OC #${oc.numero_pedido} de ${oc.fornecedor_nome}? Esta ação não poderá ser desfeita.`,
      confirmText: "Cancelar Pedido",
      cancelText: "Voltar",
    });
    if (ok) cancelaMutation.mutate();
  };

  const ultimoAnexo = oc.anexos_financeiro?.[oc.anexos_financeiro.length - 1];
  const anexo = ultimoAnexo || (solicitacao.anexo_url ? { url: solicitacao.anexo_url, nome: solicitacao.anexo_nome } : null);

  return (
    <Card className="border border-amber-200 bg-amber-50 dark:bg-amber-900/10 dark:border-amber-800">
      <CardHeader className="pb-3">
        <div className="flex items-start justify-between gap-2 flex-wrap">
          <div>
            <div className="flex items-center gap-2 flex-wrap">
              <span className="font-bold text-base font-mono">{oc.numero_pedido}</span>
              <Badge variant="outline" className="text-amber-700 border-amber-400 bg-amber-100">
                Aguardando Aprovação
              </Badge>
              <Badge variant="outline" className="text-gray-600">
                {oc.status}
              </Badge>
            </div>
            <div className="flex items-center gap-1 mt-1 text-sm text-gray-600">
              <Building2 className="w-3.5 h-3.5" />
              <span>{oc.fornecedor_nome}</span>
            </div>
          </div>
          <div className="text-right">
            <div className="text-xl font-bold text-gray-900 dark:text-white">
              {Number(oc.valor_total || 0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" })}
            </div>
            <div className="text-xs text-gray-500 flex items-center justify-end gap-1 mt-0.5">
              <CalendarDays className="w-3 h-3" />
              {oc.data_pedido ? new Date(oc.data_pedido + "T12:00:00").toLocaleDateString("pt-BR") : "—"}
            </div>
          </div>
        </div>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* Comprovante */}
        {anexo ? (
          <div className="flex items-center gap-2 rounded-md border border-green-200 bg-green-50 px-3 py-2">
            <FileText className="w-4 h-4 text-green-700 shrink-0" />
            <span className="text-sm text-green-800 truncate flex-1">{anexo.nome || "Comprovante de devolução"}</span>
            <a
              href={anexo.url}
              target="_blank"
              rel="noopener noreferrer"
              className="text-green-700 hover:text-green-900 shrink-0"
            >
              <ExternalLink className="w-4 h-4" />
            </a>
          </div>
        ) : (
          <div className="rounded-md border border-dashed border-gray-300 px-3 py-2 text-xs text-muted-foreground">
            Nenhum comprovante anexado
          </div>
        )}

        {/* Detalhe da devolução */}
        {solicitacao.detalhe_devolucao && (
          <div className="rounded-md bg-white dark:bg-neutral-900 border px-3 py-2 text-sm">
            <p className="text-xs font-semibold text-gray-500 mb-1">Detalhe da Devolução</p>
            <p className="text-gray-800 dark:text-gray-200">{solicitacao.detalhe_devolucao}</p>
          </div>
        )}

        {/* Observação */}
        {solicitacao.observacao && (
          <div className="rounded-md bg-white dark:bg-neutral-900 border px-3 py-2 text-sm">
            <p className="text-xs font-semibold text-gray-500 mb-1">Observação</p>
            <p className="text-gray-800 dark:text-gray-200">{solicitacao.observacao}</p>
          </div>
        )}

        {/* Formulário de aprovação */}
        <div className="rounded-md bg-white dark:bg-neutral-900 border p-3 space-y-3">
          <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide">Dados do Lançamento</p>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium mb-1">
                Categoria <span className="text-red-500">*</span>
              </label>
              <Select value={form.categoria_id} onValueChange={v => setForm(f => ({ ...f, categoria_id: v }))}>
                <SelectTrigger className="h-8 text-sm">
                  <SelectValue placeholder="Selecione" />
                </SelectTrigger>
                <SelectContent>
                  {categorias.map(cat => (
                    <SelectItem key={cat.id} value={cat.id}>{cat.nome}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div>
              <label className="block text-xs font-medium mb-1">
                Vencimento <span className="text-red-500">*</span>
              </label>
              <Input
                type="date"
                lang="pt-BR"
                className="h-8 text-sm"
                value={form.data_vencimento}
                onChange={e => setForm(f => ({ ...f, data_vencimento: e.target.value }))}
              />
            </div>

            <div>
              <label className="block text-xs font-medium mb-1">Forma de Pagamento</label>
              <Input
                className="h-8 text-sm"
                value={form.forma_pagamento}
                onChange={e => setForm(f => ({ ...f, forma_pagamento: e.target.value }))}
              />
            </div>

            <div className="flex flex-col justify-end">
              <div className="flex items-center gap-2 h-8">
                <Checkbox
                  id={`pago-${oc.id}`}
                  checked={form.ja_pago}
                  onCheckedChange={v => setForm(f => ({ ...f, ja_pago: !!v }))}
                />
                <label
                  htmlFor={`pago-${oc.id}`}
                  className="text-sm cursor-pointer select-none flex items-center gap-1"
                >
                  <Banknote className="w-3.5 h-3.5 text-green-600" />
                  Já foi pago?
                </label>
              </div>
            </div>
          </div>

          {form.ja_pago && (
            <div>
              <label className="block text-xs font-medium mb-1">Data do Pagamento</label>
              <Input
                type="date"
                lang="pt-BR"
                className="h-8 text-sm max-w-[180px]"
                value={form.data_pagamento}
                onChange={e => setForm(f => ({ ...f, data_pagamento: e.target.value }))}
              />
            </div>
          )}

          {formError && <p className="text-red-600 text-xs">{formError}</p>}
        </div>

        {/* Ações */}
        <div className="flex items-center justify-between gap-2 pt-1">
          <Button
            variant="outline"
            size="sm"
            className="text-red-600 border-red-200 hover:bg-red-50 hover:border-red-400"
            disabled={cancelaMutation.isPending || aprovaMutation.isPending}
            onClick={handleCancelar}
          >
            {cancelaMutation.isPending ? (
              <Loader2 className="w-4 h-4 mr-1.5 animate-spin" />
            ) : (
              <XCircle className="w-4 h-4 mr-1.5" />
            )}
            Cancelar e Excluir Pedido
          </Button>

          <Button
            size="sm"
            className="bg-green-700 hover:bg-green-800 text-white"
            disabled={aprovaMutation.isPending || cancelaMutation.isPending}
            onClick={handleAprovar}
          >
            {aprovaMutation.isPending ? (
              <Loader2 className="w-4 h-4 mr-1.5 animate-spin" />
            ) : (
              <CheckCircle2 className="w-4 h-4 mr-1.5" />
            )}
            {form.ja_pago ? "Aprovar (Pago)" : "Aprovar (Pendente)"}
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

export default function AprovacaoComprasTab({ ocs, categorias, isLoading, currentUser }) {
  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-16">
        <Loader2 className="w-6 h-6 animate-spin text-gray-400" />
      </div>
    );
  }

  if (!ocs || ocs.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-16 text-center text-gray-400">
        <CheckCircle2 className="w-12 h-12 mb-3 opacity-20" />
        <p className="text-base font-medium">Nenhuma solicitação pendente</p>
        <p className="text-sm">Quando o setor de compras enviar uma solicitação, ela aparecerá aqui.</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <p className="text-sm text-gray-500">
        {ocs.length} {ocs.length === 1 ? "solicitação aguardando" : "solicitações aguardando"} aprovação
      </p>
      {ocs.map(oc => (
        <OcApprovalCard
          key={oc.id}
          oc={oc}
          categorias={categorias}
          currentUser={currentUser}
        />
      ))}
    </div>
  );
}

import React, { useState } from "react";
import { base44 } from "@/api/base44Client";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Plus, Edit, Trash2, Tag } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

export default function CategoriasManager({ categorias }) {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingCategoria, setEditingCategoria] = useState(null);
  const [formData, setFormData] = useState({
    nome: "",
    tipo: "Ambos",
    cor: "#07593f",
    ativa: true
  });

  const queryClient = useQueryClient();

  const createMutation = useMutation({
    mutationFn: (data) => base44.entities.CategoriaFinanceira.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['categorias-financeiras'] });
      setIsModalOpen(false);
      resetForm();
    }
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, data }) => base44.entities.CategoriaFinanceira.update(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['categorias-financeiras'] });
      setIsModalOpen(false);
      resetForm();
    }
  });

  const deleteMutation = useMutation({
    mutationFn: (id) => base44.entities.CategoriaFinanceira.delete(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['categorias-financeiras'] });
    }
  });

  const resetForm = () => {
    setFormData({
      nome: "",
      tipo: "Ambos",
      cor: "#07593f",
      ativa: true
    });
    setEditingCategoria(null);
  };

  const handleEdit = (categoria) => {
    setEditingCategoria(categoria);
    setFormData({
      nome: categoria.nome,
      tipo: categoria.tipo,
      cor: categoria.cor || "#07593f",
      ativa: categoria.ativa !== false
    });
    setIsModalOpen(true);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    
    if (editingCategoria) {
      updateMutation.mutate({
        id: editingCategoria.id,
        data: formData
      });
    } else {
      createMutation.mutate(formData);
    }
  };

  const handleDelete = (id) => {
    if (confirm('Tem certeza que deseja excluir esta categoria?')) {
      deleteMutation.mutate(id);
    }
  };

  const getTipoBadge = (tipo) => {
    const styles = {
      'Entrada': 'bg-green-100 text-green-800',
      'Saída': 'bg-red-100 text-red-800',
      'Ambos': 'bg-blue-100 text-blue-800'
    };
    
    return <Badge className={styles[tipo]}>{tipo}</Badge>;
  };

  const coresDisponiveis = [
    { nome: "Verde Escuro", valor: "#07593f" },
    { nome: "Laranja", valor: "#f38a4c" },
    { nome: "Azul", valor: "#3b82f6" },
    { nome: "Vermelho", valor: "#dc2626" },
    { nome: "Roxo", valor: "#8b5cf6" },
    { nome: "Verde", valor: "#10b981" },
    { nome: "Amarelo", valor: "#f59e0b" },
    { nome: "Rosa", valor: "#ec4899" }
  ];

  return (
    <div className="space-y-6">
      <Card className="border-0 shadow-lg">
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="flex items-center gap-2">
              <Tag className="w-5 h-5" />
              Gerenciar Categorias
            </CardTitle>
            <Button
              onClick={() => {
                resetForm();
                setIsModalOpen(true);
              }}
              style={{ background: 'linear-gradient(135deg, #f38a4c 0%, #f5a164 100%)' }}
            >
              <Plus className="w-4 h-4 mr-2" />
              Nova Categoria
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-4">
            {categorias.map((cat) => (
              <Card key={cat.id} className="border" style={{ borderColor: cat.cor || '#E5E0D8' }}>
                <CardContent className="p-4">
                  <div className="flex items-start justify-between mb-3">
                    <div className="flex items-center gap-2">
                      <div 
                        className="w-8 h-8 rounded-full"
                        style={{ backgroundColor: cat.cor || '#07593f' }}
                      />
                      <div>
                        <h3 className="font-semibold" style={{ color: '#07593f' }}>
                          {cat.nome}
                        </h3>
                        {getTipoBadge(cat.tipo)}
                      </div>
                    </div>
                  </div>
                  
                  {!cat.ativa && (
                    <Badge variant="outline" className="mb-2">
                      Inativa
                    </Badge>
                  )}
                  
                  <div className="flex gap-2">
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => handleEdit(cat)}
                      className="flex-1"
                    >
                      <Edit className="w-4 h-4 mr-1" />
                      Editar
                    </Button>
                    <Button
                      size="sm"
                      variant="destructive"
                      onClick={() => handleDelete(cat.id)}
                      disabled={deleteMutation.isPending}
                    >
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>

          {categorias.length === 0 && (
            <div className="text-center py-12">
              <Tag className="w-16 h-16 mx-auto mb-4 opacity-20" style={{ color: '#07593f' }} />
              <p className="text-xl" style={{ color: '#8B8B8B' }}>
                Nenhuma categoria cadastrada
              </p>
            </div>
          )}
        </CardContent>
      </Card>

      <Dialog open={isModalOpen} onOpenChange={setIsModalOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>
              {editingCategoria ? 'Editar Categoria' : 'Nova Categoria'}
            </DialogTitle>
            <DialogDescription>
              Configure as informações da categoria financeira
            </DialogDescription>
          </DialogHeader>

          <form onSubmit={handleSubmit}>
            <div className="space-y-4 py-4">
              <div>
                <Label htmlFor="nome">Nome da Categoria *</Label>
                <Input
                  id="nome"
                  value={formData.nome}
                  onChange={(e) => setFormData({ ...formData, nome: e.target.value })}
                  placeholder="Ex: Vendas, Aluguel, Salários..."
                  required
                />
              </div>

              <div>
                <Label htmlFor="tipo">Tipo *</Label>
                <Select
                  value={formData.tipo}
                  onValueChange={(value) => setFormData({ ...formData, tipo: value })}
                  required
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="Entrada">Apenas Entradas</SelectItem>
                    <SelectItem value="Saída">Apenas Saídas</SelectItem>
                    <SelectItem value="Ambos">Ambos (Entrada e Saída)</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div>
                <Label htmlFor="cor">Cor da Categoria</Label>
                <div className="grid grid-cols-4 gap-2 mt-2">
                  {coresDisponiveis.map((cor) => (
                    <button
                      key={cor.valor}
                      type="button"
                      onClick={() => setFormData({ ...formData, cor: cor.valor })}
                      className={`w-full h-12 rounded-lg transition-all ${
                        formData.cor === cor.valor ? 'ring-2 ring-offset-2 ring-blue-500 scale-110' : ''
                      }`}
                      style={{ backgroundColor: cor.valor }}
                      title={cor.nome}
                    />
                  ))}
                </div>
              </div>

              <div className="flex items-center space-x-2">
                <input
                  type="checkbox"
                  id="ativa"
                  checked={formData.ativa}
                  onChange={(e) => setFormData({ ...formData, ativa: e.target.checked })}
                  className="rounded"
                />
                <Label htmlFor="ativa" className="cursor-pointer">
                  Categoria Ativa
                </Label>
              </div>
            </div>

            <DialogFooter>
              <Button 
                type="button" 
                variant="outline" 
                onClick={() => {
                  setIsModalOpen(false);
                  resetForm();
                }}
              >
                Cancelar
              </Button>
              <Button 
                type="submit"
                disabled={createMutation.isPending || updateMutation.isPending}
                style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
              >
                {(createMutation.isPending || updateMutation.isPending) ? 'Salvando...' : 'Salvar'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { AlertTriangle } from "lucide-react";

const fmt = (v) =>
  `R$ ${Math.abs(v || 0).toLocaleString("pt-BR", { minimumFractionDigits: 2 })}`;

const fmtDate = (d) => {
  if (!d) return "—";
  return new Date(d + "T00:00:00").toLocaleDateString("pt-BR");
};

/**
 * Modal de alerta de conciliação inteligente.
 * Exibe lançamentos existentes com valor similar ao que está sendo criado,
 * pedindo confirmação se o usuário realmente quer criar um novo lançamento.
 *
 * Props:
 *   open: boolean
 *   duplicatas: LancamentoFinanceiro[]
 *   novoValor: number
 *   novoDescricao: string
 *   onConfirm: () => void   — prosseguir mesmo assim
 *   onCancel: () => void    — cancelar criação
 */
export default function ConciliacaoAlertModal({
  open,
  duplicatas = [],
  novoValor,
  novoDescricao,
  onConfirm,
  onCancel,
}) {
  return (
    <Dialog open={open} onOpenChange={(o) => { if (!o) onCancel(); }}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-amber-700">
            <AlertTriangle className="w-5 h-5" />
            Possível duplicidade detectada
          </DialogTitle>
          <DialogDescription>
            Foram encontrados lançamentos existentes com valor semelhante a{" "}
            <strong>{fmt(novoValor)}</strong> ({novoDescricao}). Verifique abaixo se
            este lançamento já foi registrado pelo setor de Compras ou Financeiro antes de
            prosseguir.
          </DialogDescription>
        </DialogHeader>

        <div className="rounded-lg border divide-y overflow-hidden mb-2">
          {duplicatas.map((l) => (
            <div key={l.id} className="flex items-start justify-between gap-3 px-4 py-3">
              <div className="min-w-0 flex-1">
                <p className="text-sm font-medium text-gray-900 truncate">
                  {l.descricao || "—"}
                </p>
                <p className="text-xs text-gray-500 mt-0.5">
                  {l.categoria_nome || "Sem categoria"} ·{" "}
                  {l.forma_pagamento || "—"} · vence {fmtDate(l.data_vencimento)}
                </p>
                {l.fornecedor_nome && (
                  <p className="text-xs text-gray-400">Fornecedor: {l.fornecedor_nome}</p>
                )}
              </div>
              <div className="flex flex-col items-end gap-1 flex-shrink-0">
                <span className="text-sm font-bold text-red-600">{fmt(l.valor)}</span>
                <Badge
                  className={
                    l.status === "Pago"
                      ? "bg-green-100 text-green-800 text-[10px]"
                      : l.status === "Cancelado" || l.status === "Cancelada"
                      ? "bg-gray-100 text-gray-600 text-[10px]"
                      : "bg-yellow-100 text-yellow-800 text-[10px]"
                  }
                >
                  {l.status || "Pendente"}
                </Badge>
              </div>
            </div>
          ))}
        </div>

        <p className="text-xs text-amber-700 bg-amber-50 border border-amber-200 rounded-md px-3 py-2">
          Se este boleto ou compra já foi registrado pelo setor de Compras (ao receber a OC),
          criar um novo lançamento aqui resultará em <strong>contabilização dupla</strong> da
          despesa. Prossiga apenas se tiver certeza de que são lançamentos diferentes.
        </p>

        <div className="flex justify-end gap-2 mt-2">
          <Button variant="outline" onClick={onCancel}>
            Cancelar — não criar
          </Button>
          <Button
            variant="destructive"
            onClick={onConfirm}
          >
            Criar mesmo assim
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useMemo } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Search, Users, ShoppingCart, TrendingUp, CheckCircle2, CheckSquare } from "lucide-react";
import { filtrarFolhasPorMes, normalizeTipo } from "@/services/financeiroAggregation";
import { calcularFolhaCompleta } from "@/utils/calculosTrabalhistas";
import AlteracaoEmMassaModal from "@/components/financeiro/AlteracaoEmMassaModal";

const fmt = (v) =>
  Number(v || 0).toLocaleString("pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const FOLHA_STATUS = {
  Gerado:    { bg: "bg-yellow-100 dark:bg-yellow-900/30", text: "text-yellow-700 dark:text-yellow-400" },
  Pago:      { bg: "bg-green-100 dark:bg-green-900/30",  text: "text-green-700 dark:text-green-400" },
  Cancelado: { bg: "bg-gray-100 dark:bg-neutral-700",    text: "text-gray-500" },
  Estimativa: { bg: "bg-amber-100 dark:bg-amber-900/30", text: "text-amber-700 dark:text-amber-400" },
};

const COMISSAO_STATUS = {
  Calculada: { bg: "bg-blue-100 dark:bg-blue-900/30",   text: "text-blue-700 dark:text-blue-400" },
  Paga:      { bg: "bg-green-100 dark:bg-green-900/30", text: "text-green-700 dark:text-green-400" },
  Pendente:  { bg: "bg-yellow-100 dark:bg-yellow-900/30", text: "text-yellow-700 dark:text-yellow-400" },
  Cancelada: { bg: "bg-gray-100 dark:bg-neutral-700",   text: "text-gray-500" },
};

function StatusBadge({ status, mapa }) {
  const c = mapa?.[status] || { bg: "bg-gray-100", text: "text-gray-500" };
  return (
    <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium ${c.bg} ${c.text}`}>
      {status || "—"}
    </span>
  );
}

function isDespesaPendente(lancamento) {
  const status = String(lancamento?.status || "").trim().toLowerCase();
  if (lancamento?.pago === true) return false;
  if (status === "pago" || status === "cancelado") return false;
  return normalizeTipo(lancamento?.tipo) === "saida";
}

// ─── Aba: Folha de Pagamento ─────────────────────────────────────────────────
function FolhaTab({ folhas, mesAno, isLoading, colaboradores = [] }) {
  const [busca, setBusca] = useState("");

  const folhasMes = useMemo(
    () => filtrarFolhasPorMes(folhas, mesAno),
    [folhas, mesAno]
  );

  // Estimativa a partir dos colaboradores quando não há folhas geradas
  const folhasEstimadas = useMemo(() => {
    if (folhasMes.length > 0) return [];
    const colabAtivos = colaboradores.filter(c => c.status === 'Ativo' && Number(c.salario_base) > 0);
    return colabAtivos.map(c => {
      const calc = calcularFolhaCompleta(c);
      return {
        id: `est-${c.id}`,
        colaborador_nome: c.nome_completo,
        salario_bruto: calc.salario_bruto,
        inss: calc.inss,
        irrf: calc.irrf,
        fgts: calc.fgts,
        vale_transporte: calc.vale_transporte,
        outros_descontos: calc.outros_descontos,
        salario_liquido: calc.salario_liquido,
        status: 'Estimativa',
        data_pagamento: null,
      };
    });
  }, [folhasMes, colaboradores]);

  const dadosExibir = folhasMes.length > 0 ? folhasMes : folhasEstimadas;
  const isEstimativa = folhasMes.length === 0 && folhasEstimadas.length > 0;

  const filtradas = useMemo(() => {
    if (!busca) return dadosExibir;
    const t = busca.toLowerCase();
    return dadosExibir.filter((f) => f.colaborador_nome?.toLowerCase().includes(t));
  }, [dadosExibir, busca]);

  const totalBruto = dadosExibir.reduce((s, f) => s + (f.salario_bruto || 0), 0);
  const totalFGTS = dadosExibir.reduce((s, f) => s + (f.fgts || 0), 0);

  const totalLiquidoPendente = useMemo(() => {
    return dadosExibir.reduce((s, f) => {
      if (f.status === 'Pago' || f.status === 'Cancelado') return s;
      if (f.status === 'Estimativa') return s + (f.salario_liquido || 0);

      const colab = colaboradores.find(c => c.nome_completo === f.colaborador_nome || c.id === f.colaborador_id);
      const recebeVale = colab?.recebe_vale === true;
      const valorDiaPagamento = Number(colab?.valor_dia_pagamento) || 0;
      const valorDiaVale = Number(colab?.valor_dia_vale) || 0;
      const temDistribuicao = recebeVale && (valorDiaPagamento + valorDiaVale) > 0;

      if (temDistribuicao) {
        const salPendente = f.salario_pago === true ? 0 : valorDiaPagamento;
        const valePendente = f.vale_pago === true ? 0 : valorDiaVale;
        return s + salPendente + valePendente;
      } else {
        return s + (f.salario_pago === true ? 0 : (f.salario_liquido || 0));
      }
    }, 0);
  }, [dadosExibir, colaboradores]);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-32">
        <div className="animate-spin rounded-full h-7 w-7 border-b-2 border-green-600" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-3 gap-4">
        <Card className="border-0 shadow-md">
          <CardContent className="pt-4 pb-3">
            <p className="text-xs text-gray-500 uppercase tracking-wide">Salário Bruto</p>
            <p className="text-xl font-bold text-gray-800 dark:text-gray-200">R$ {fmt(totalBruto)}</p>
            <p className="text-xs text-gray-400">{dadosExibir.length} colaborador(es){isEstimativa ? " (estimativa)" : ""}</p>
          </CardContent>
        </Card>
        <Card className="border-0 shadow-md">
          <CardContent className="pt-4 pb-3">
            <p className="text-xs text-gray-500 uppercase tracking-wide">Salário Líquido (A pagar)</p>
            <p className="text-xl font-bold text-red-600">R$ {fmt(totalLiquidoPendente)}</p>
            <p className="text-xs text-gray-400">Total pendente no mês</p>
          </CardContent>
        </Card>
        <Card className="border-0 shadow-md">
          <CardContent className="pt-4 pb-3">
            <p className="text-xs text-gray-500 uppercase tracking-wide">FGTS</p>
            <p className="text-xl font-bold text-orange-600">R$ {fmt(totalFGTS)}</p>
            <p className="text-xs text-gray-400">Encargo patronal</p>
          </CardContent>
        </Card>
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-2.5 w-4 h-4 text-gray-400" />
        <Input
          placeholder="Buscar colaborador..."
          value={busca}
          onChange={(e) => setBusca(e.target.value)}
          className="pl-9 text-sm"
        />
      </div>

      {isEstimativa && (
        <div className="bg-amber-50 border border-amber-200 rounded-lg px-4 py-3 text-sm text-amber-800">
          <strong>Valores estimados.</strong> A folha deste mês ainda não foi gerada no módulo de RH. Os valores abaixo são calculados automaticamente com base no salário dos colaboradores ativos.
        </div>
      )}

      {filtradas.length === 0 ? (
        <div className="text-center py-8 text-gray-400">
          <Users className="w-10 h-10 mx-auto mb-2 opacity-30" />
          {busca
            ? "Nenhum resultado para a busca."
            : "Nenhuma folha gerada e nenhum colaborador com salário cadastrado."}
        </div>
      ) : (
        <Card className="border-0 shadow-md">
          <CardContent className="pt-4">
            <Table>
              <TableHeader>
                <TableRow className="text-xs text-gray-400 uppercase">
                  <TableHead>Colaborador</TableHead>
                  <TableHead>Bruto</TableHead>
                  <TableHead>Descontos</TableHead>
                  <TableHead>Líquido</TableHead>
                  <TableHead>FGTS</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Pagamento</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filtradas.map((f) => {
                  const descontos = (f.inss || 0) + (f.irrf || 0) + (f.vale_transporte || 0) + (f.outros_descontos || 0);

                  // Determinar se o pagamento é parcelado
                  const colab = colaboradores.find(c => c.nome_completo === f.colaborador_nome || c.id === f.colaborador_id);
                  const recebeVale = colab?.recebe_vale === true;
                  const valorDiaPagamento = Number(colab?.valor_dia_pagamento) || 0;
                  const valorDiaVale = Number(colab?.valor_dia_vale) || 0;
                  const temDistribuicao = recebeVale && (valorDiaPagamento + valorDiaVale) > 0;

                  let valorPendente = 0;
                  let statusLabel = f.status;

                  if (f.status === 'Pago') {
                    valorPendente = 0;
                  } else if (f.status === 'Cancelado') {
                    valorPendente = 0;
                  } else if (f.status === 'Estimativa') {
                    valorPendente = f.salario_liquido;
                  } else { // 'Gerado'
                    if (temDistribuicao) {
                      const salPendente = f.salario_pago === true ? 0 : valorDiaPagamento;
                      const valePendente = f.vale_pago === true ? 0 : valorDiaVale;
                      valorPendente = salPendente + valePendente;
                      
                      if (f.salario_pago === true && f.vale_pago === true) {
                        statusLabel = "Pago";
                      } else if (f.salario_pago === true || f.vale_pago === true) {
                        statusLabel = "Parcial";
                      }
                    } else {
                      valorPendente = f.salario_pago === true ? 0 : f.salario_liquido;
                      if (f.salario_pago === true) {
                        statusLabel = "Pago";
                      }
                    }
                  }

                  return (
                    <TableRow key={f.id} className="text-sm hover:bg-gray-50 dark:hover:bg-neutral-800">
                      <TableCell className="font-medium">
                        <p className="font-medium text-gray-800 dark:text-gray-200">{f.colaborador_nome || "—"}</p>
                        {temDistribuicao && (
                          <span className="text-[10px] text-gray-400 block mt-0.5">
                            Divisão: Dia {colab.dia_pagamento || 5} (R$ {fmt(valorDiaPagamento)}) / Dia {colab.dia_vale || 20} (R$ {fmt(valorDiaVale)})
                          </span>
                        )}
                      </TableCell>
                      <TableCell>R$ {fmt(f.salario_bruto)}</TableCell>
                      <TableCell className="text-red-500">– R$ {fmt(descontos)}</TableCell>
                      <TableCell>
                        <p className="font-semibold text-gray-700 dark:text-gray-300">R$ {fmt(f.salario_liquido)}</p>
                        {valorPendente < f.salario_liquido && valorPendente > 0 && (
                          <span className="text-[10px] text-orange-500 font-medium block">
                            Pendente: R$ {fmt(valorPendente)}
                          </span>
                        )}
                        {valorPendente === 0 && f.status !== 'Estimativa' && (
                          <span className="text-[10px] text-green-600 font-medium block">
                            Totalmente Pago
                          </span>
                        )}
                      </TableCell>
                      <TableCell className="text-orange-500">R$ {fmt(f.fgts)}</TableCell>
                      <TableCell>
                        <StatusBadge status={statusLabel} mapa={{ ...FOLHA_STATUS, Parcial: { bg: "bg-indigo-100 dark:bg-indigo-900/30", text: "text-indigo-700 dark:text-indigo-400" } }} />
                      </TableCell>
                      <TableCell className="text-gray-400 text-xs">
                        {f.status === 'Pago' && f.data_pagamento ? (
                          new Date(f.data_pagamento + "T00:00:00").toLocaleDateString("pt-BR")
                        ) : temDistribuicao ? (
                          <div className="space-y-0.5 text-[10px]">
                            <p className={f.salario_pago ? "text-green-600" : "text-gray-400"}>
                              Salário: {f.salario_pago ? `Pago em ${f.data_pagamento_salario ? new Date(f.data_pagamento_salario + "T00:00:00").toLocaleDateString("pt-BR") : '—'}` : 'Pendente'}
                            </p>
                            <p className={f.vale_pago ? "text-green-600" : "text-gray-400"}>
                              Vale: {f.vale_pago ? `Pago em ${f.data_pagamento_vale ? new Date(f.data_pagamento_vale + "T00:00:00").toLocaleDateString("pt-BR") : '—'}` : 'Pendente'}
                            </p>
                          </div>
                        ) : f.salario_pago ? (
                          `Pago em ${f.data_pagamento_salario ? new Date(f.data_pagamento_salario + "T00:00:00").toLocaleDateString("pt-BR") : '—'}`
                        ) : (
                          "Pendente"
                        )}
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

// ─── Aba: Comissões ──────────────────────────────────────────────────────────
function ComissoesTab({ comissoes, mesAno, isLoading }) {
  const [filtroStatus, setFiltroStatus] = useState("pendentes");

  const comissoesMes = useMemo(() => {
    if (!Array.isArray(comissoes)) return [];
    return comissoes.filter((c) => c.data_calculo?.slice(0, 7) === mesAno);
  }, [comissoes, mesAno]);

  const filtradas = useMemo(() => {
    if (filtroStatus === "pendentes") {
      return comissoesMes.filter((c) => c.status === "Calculada" || c.status === "Pendente");
    }
    if (filtroStatus === "pagas") {
      return comissoesMes.filter((c) => c.status === "Paga");
    }
    return comissoesMes;
  }, [comissoesMes, filtroStatus]);

  const totalPendente = comissoesMes
    .filter((c) => c.status === "Calculada" || c.status === "Pendente")
    .reduce((s, c) => s + (c.valor_comissao || 0), 0);
  const totalPago = comissoesMes
    .filter((c) => c.status === "Paga")
    .reduce((s, c) => s + (c.valor_comissao || 0), 0);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-32">
        <div className="animate-spin rounded-full h-7 w-7 border-b-2 border-green-600" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 gap-4">
        <Card className="border-0 shadow-md">
          <CardContent className="pt-4 pb-3">
            <p className="text-xs text-gray-500 uppercase tracking-wide">A Pagar</p>
            <p className="text-xl font-bold text-orange-600">R$ {fmt(totalPendente)}</p>
            <p className="text-xs text-gray-400">
              {comissoesMes.filter((c) => c.status === "Calculada" || c.status === "Pendente").length} comissão(ões)
            </p>
          </CardContent>
        </Card>
        <Card className="border-0 shadow-md">
          <CardContent className="pt-4 pb-3">
            <p className="text-xs text-gray-500 uppercase tracking-wide">Já Pagas</p>
            <p className="text-xl font-bold text-green-600">R$ {fmt(totalPago)}</p>
            <p className="text-xs text-gray-400">
              {comissoesMes.filter((c) => c.status === "Paga").length} comissão(ões)
            </p>
          </CardContent>
        </Card>
      </div>

      <div className="flex gap-2">
        {[
          { value: "pendentes", label: "A pagar" },
          { value: "pagas",     label: "Pagas" },
          { value: "todas",     label: "Todas" },
        ].map((op) => (
          <button
            key={op.value}
            onClick={() => setFiltroStatus(op.value)}
            className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${
              filtroStatus === op.value
                ? "bg-green-600 text-white"
                : "bg-gray-100 dark:bg-neutral-700 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-neutral-600"
            }`}
          >
            {op.label}
          </button>
        ))}
      </div>

      {filtradas.length === 0 ? (
        <div className="text-center py-8 text-gray-400">
          <TrendingUp className="w-10 h-10 mx-auto mb-2 opacity-30" />
          {comissoesMes.length === 0
            ? "Sem comissões calculadas neste mês."
            : "Nenhuma comissão com este status."}
        </div>
      ) : (
        <Card className="border-0 shadow-md">
          <CardContent className="pt-4">
            <Table>
              <TableHeader>
                <TableRow className="text-xs text-gray-400 uppercase">
                  <TableHead>Data Cálculo</TableHead>
                  <TableHead>Forma Pagto.</TableHead>
                  <TableHead>Base</TableHead>
                  <TableHead>%</TableHead>
                  <TableHead>Comissão</TableHead>
                  <TableHead>Status</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filtradas.map((c) => (
                  <TableRow key={c.id} className="text-sm hover:bg-gray-50 dark:hover:bg-neutral-800">
                    <TableCell className="text-gray-500 text-xs">
                      {c.data_calculo ? new Date(c.data_calculo).toLocaleDateString("pt-BR") : "—"}
                    </TableCell>
                    <TableCell>{c.forma_pagamento || "—"}</TableCell>
                    <TableCell>R$ {fmt(c.valor_base)}</TableCell>
                    <TableCell>{c.percentual_aplicado ? `${c.percentual_aplicado}%` : "—"}</TableCell>
                    <TableCell className="font-semibold text-orange-600">
                      R$ {fmt(c.valor_comissao)}
                    </TableCell>
                    <TableCell><StatusBadge status={c.status} mapa={COMISSAO_STATUS} /></TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

