}

export default function VisaoGeral({
  vendas = [],
  lancamentos = [],
  folhas = [],
  comissoes = [],
  contasPagarCompras = [],
  metas = [],
  colaboradores = [],
  mesAno,
  dreModo = "mensal",
  dreDataInicio,
  dreDataFim,
}) {
  const [modalPagamentosAberto, setModalPagamentosAberto] = useState(false);

  const periodoDre = useMemo(
    () => (dreModo === "intervalo"
      ? { modo: "intervalo", dataInicio: dreDataInicio, dataFim: dreDataFim }
      : { modo: "mensal", mesAno }),
    [dreModo, dreDataInicio, dreDataFim, mesAno]
  );

  const dre = useMemo(
    () => calcularDREPorPeriodo({ vendas, lancamentos, folhas, comissoes, periodo: periodoDre }),
    [vendas, lancamentos, folhas, comissoes, periodoDre]
  );

  const receitaRecebida = useMemo(
    () => calcularReceitaRecebidaPorPeriodo(vendas, periodoDre),
    [vendas, periodoDre]
  );

  const { total: totalReceber, itens: itensReceber } = useMemo(
    () => calcularContasReceber(vendas),
    [vendas]
  );

  const totalEntradasLancamentos = useMemo(
    () => calcularTotalEntradasPorPeriodo(lancamentos, periodoDre),
    [lancamentos, periodoDre]
  );

  const totalSaidasLancamentos = useMemo(
    () => calcularTotalSaidasPorPeriodo(lancamentos, periodoDre),
    [lancamentos, periodoDre]
  );

  const saldoCaixa = totalEntradasLancamentos - totalSaidasLancamentos;
  const totalFolhaDRE = dre.totalFolha;
  const totalComissoesMes = dre.totalComissoes;

  // Estimativa de folha a partir dos colaboradores ativos (fallback quando nenhuma folha foi gerada)
  const folhaEstimada = useMemo(() => {
    const colabAtivos = colaboradores.filter(c => c.status === 'Ativo' && Number(c.salario_base) > 0);
    if (colabAtivos.length === 0) return { total: 0, count: 0 };
    const total = colabAtivos.reduce((sum, c) => {
      const folha = calcularFolhaCompleta(c);
      return sum + (folha.salario_liquido || 0);
    }, 0);
    return { total, count: colabAtivos.length };
  }, [colaboradores]);

  // Folhas geradas no período
  const folhasNoPeriodo = useMemo(() => {
    const [a, m2] = mesAno.split("-").map(Number);
    return folhas.filter(f => f.ano_referencia === a && f.mes_referencia === m2);
  }, [folhas, mesAno]);

  const temFolhaGerada = folhasNoPeriodo.length > 0;
  const totalFolhaMes = temFolhaGerada ? totalFolhaDRE : folhaEstimada.total;
  const folhaLabel = temFolhaGerada
    ? `${folhasNoPeriodo.length} colaborador(es)`
    : folhaEstimada.count > 0
      ? `${folhaEstimada.count} colaborador(es) · estimativa`
      : "Sem dados";

  const totalFolhaMesPendente = useMemo(() => {
    if (!temFolhaGerada) return folhaEstimada.total;
    return folhasNoPeriodo.reduce((s, f) => {
      if (f.status === 'Pago' || f.status === 'Cancelado') return s;

      const colab = colaboradores.find(c => c.nome_completo === f.colaborador_nome || c.id === f.colaborador_id);
      const recebeVale = colab?.recebe_vale === true;
      const valorDiaPagamento = Number(colab?.valor_dia_pagamento) || 0;
      const valorDiaVale = Number(colab?.valor_dia_vale) || 0;
      const temDistribuicao = recebeVale && (valorDiaPagamento + valorDiaVale) > 0;

      if (temDistribuicao) {
        const salPendente = f.salario_pago === true ? 0 : valorDiaPagamento;
        const valePendente = f.vale_pago === true ? 0 : valorDiaVale;
        return s + salPendente + valePendente;
      } else {
        return s + (f.salario_pago === true ? 0 : (f.salario_liquido || 0));
      }
    }, 0);
  }, [folhasNoPeriodo, colaboradores, temFolhaGerada, folhaEstimada.total]);

  const MESES = [
    "Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho",
    "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"
  ];

  const formatMesAno = (mesAnoStr) => {
    if (!mesAnoStr) return "";
    const [ano, mes] = mesAnoStr.split("-").map(Number);
    if (!mes || !ano) return mesAnoStr;
    return `${MESES[mes - 1]} de ${ano}`;
  };

  const pagamentosAgrupados = useMemo(() => {
    const listaPagamentos = [];

    if (temFolhaGerada) {
      folhasNoPeriodo.forEach((folha) => {
        const colab = colaboradores.find((c) => c.id === folha.colaborador_id);
        const recebeVale = colab?.recebe_vale === true;
        const valorDiaPagamento = Number(colab?.valor_dia_pagamento) || 0;
        const valorDiaVale = Number(colab?.valor_dia_vale) || 0;
        const temDistribuicao = recebeVale && (valorDiaPagamento + valorDiaVale) > 0;

        if (temDistribuicao) {
          if (valorDiaVale > 0) {
            listaPagamentos.push({
              colaborador_nome: folha.colaborador_nome || colab?.nome_completo || "Colaborador",
              tipo: "Vale",
              valor: valorDiaVale,
              dia: colab.dia_vale || 20,
              tipo_dia: colab.tipo_dia_vale || "fixo",
              pago: folha.vale_pago === true || folha.status === 'Pago',
            });
          }
          if (valorDiaPagamento > 0) {
            listaPagamentos.push({
              colaborador_nome: folha.colaborador_nome || colab?.nome_completo || "Colaborador",
              tipo: "Salário",
              valor: valorDiaPagamento,
              dia: colab.dia_pagamento || 5,
              tipo_dia: colab.tipo_dia_pagamento || "fixo",
              pago: folha.salario_pago === true || folha.status === 'Pago',
            });
          }
        } else {
          listaPagamentos.push({
            colaborador_nome: folha.colaborador_nome || colab?.nome_completo || "Colaborador",
            tipo: "Salário",
            valor: Number(folha.salario_liquido) || 0,
            dia: colab?.dia_pagamento || 5,
            tipo_dia: colab?.tipo_dia_pagamento || "fixo",
            pago: folha.salario_pago === true || folha.status === 'Pago',
          });
        }
      });
    } else {
      // Usar colaboradores ativos como estimativa
      const colabAtivos = colaboradores.filter(
        (c) => c.status === "Ativo" && Number(c.salario_base) > 0
      );

      colabAtivos.forEach((colab) => {
        const folha = calcularFolhaCompleta(colab);
        const recebeVale = colab.recebe_vale === true;
        const valorDiaPagamento = Number(colab.valor_dia_pagamento) || 0;
        const valorDiaVale = Number(colab.valor_dia_vale) || 0;
        const temDistribuicao = recebeVale && (valorDiaPagamento + valorDiaVale) > 0;

        if (temDistribuicao) {
          if (valorDiaVale > 0) {
            listaPagamentos.push({
              colaborador_nome: colab.nome_completo || "Colaborador",
              tipo: "Vale",
              valor: valorDiaVale,
              dia: colab.dia_vale || 20,
              tipo_dia: colab.tipo_dia_vale || "fixo",
              pago: false,
            });
          }
          if (valorDiaPagamento > 0) {
            listaPagamentos.push({
              colaborador_nome: colab.nome_completo || "Colaborador",
              tipo: "Salário",
              valor: valorDiaPagamento,
              dia: colab.dia_pagamento || 5,
              tipo_dia: colab.tipo_dia_pagamento || "fixo",
              pago: false,
            });
          }
        } else {
          listaPagamentos.push({
            colaborador_nome: colab.nome_completo || "Colaborador",
            tipo: "Salário",
            valor: folha.salario_liquido || 0,
            dia: colab.dia_pagamento || 5,
            tipo_dia: colab.tipo_dia_pagamento || "fixo",
            pago: false,
          });
        }
      });
    }

    // Agrupar por dia de pagamento
    const grupos = {};
    listaPagamentos.forEach((pag) => {
      const key = pag.dia;
      if (!grupos[key]) {
        grupos[key] = {
          dia: pag.dia,
          tipo_dia: pag.tipo_dia,
          total: 0,
          pagamentos: [],
        };
      }
      grupos[key].total += pag.valor;
      grupos[key].pagamentos.push(pag);
    });

    const arrayGrupos = Object.values(grupos).sort((a, b) => a.dia - b.dia);
    return arrayGrupos;
  }, [folhasNoPeriodo, colaboradores, temFolhaGerada]);

  // Contas a pagar de compras: apenas pendentes/vencidas
  const totalContasPagarCompras = useMemo(() => {
    if (!Array.isArray(contasPagarCompras)) return 0;
    return contasPagarCompras
      .filter((c) => c.status === "Pendente" || c.status === "Em aberto" || c.status === "Vencida")
      .reduce((s, c) => s + (c.valor_total || c.valor || 0), 0);
  }, [contasPagarCompras]);

  // Meta do mês
  const [ano, mes] = mesAno.split("-").map(Number);
  const metaMes = useMemo(() => {
    if (!Array.isArray(metas)) return null;
    return metas.find((m) => m.mes === mes && m.ano === ano);
  }, [metas, mes, ano]);

  const percentualMeta = metaMes?.valor_meta > 0
    ? Math.round((dre.receitaBruta / metaMes.valor_meta) * 100)
    : null;

  const vendasNoPeriodo = useMemo(() => {
    if (dreModo !== "intervalo") {
      return vendas.filter((v) => v.data_venda?.slice(0, 7) === mesAno && !isVendaCancelada(v));
    }

    const inicio = dreDataInicio ? new Date(dreDataInicio) : null;
    const fim = dreDataFim ? new Date(dreDataFim) : null;
    if (!inicio || !fim) return [];
    fim.setHours(23, 59, 59, 999);

    return vendas.filter((v) => {
      if (isVendaCancelada(v)) return false;
      const dataVenda = new Date(v.data_venda);
      if (Number.isNaN(dataVenda.getTime())) return false;
      return dataVenda >= inicio && dataVenda <= fim;
    });
  }, [vendas, dreModo, mesAno, dreDataInicio, dreDataFim]);

  const mesAnoFinalTendencia = useMemo(() => {
    if (dreModo === "mensal") return mesAno;
    if (dreDataFim?.length >= 7) return dreDataFim.slice(0, 7);
    return new Date().toISOString().slice(0, 7);
  }, [dreModo, mesAno, dreDataFim]);

  const dreTendencia = useMemo(
    () => calcularDRESerieMensal12Meses({ vendas, lancamentos, mesAnoFinal: mesAnoFinalTendencia }),
    [vendas, lancamentos, mesAnoFinalTendencia]
  );

  const maxLucroAbsoluto = useMemo(() => {
    const valores = dreTendencia.map((m) => Math.abs(m.lucroOperacional || 0));
    return Math.max(1, ...valores);
  }, [dreTendencia]);

  const descricaoPeriodoDre = dreModo === "mensal"
    ? mesAno
    : `${dreDataInicio || "--"} até ${dreDataFim || "--"}`;

  // Qtd de vendas atrasadas A/R
  const hoje = new Date(); hoje.setHours(0, 0, 0, 0);
  const receiverVencidas = itensReceber.filter((v) => {
    if (!v.prazo_entrega) return false;
    return new Date(v.prazo_entrega + "T00:00:00") < hoje;
  }).length;

  return (
    <div className="space-y-6">
      {/* KPI Row */}
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
        <KPICard
          titulo="Receita Bruta"
          valor={dre.receitaBruta}
          subtitulo={`${vendasNoPeriodo.length} pedido(s)`}
          icon={ShoppingCart}
          cor="green"
        />
        <KPICard
          titulo="Recebido"
          valor={receitaRecebida}
          subtitulo={`${Math.round(dre.receitaBruta > 0 ? (receitaRecebida / dre.receitaBruta) * 100 : 0)}% da receita`}
          icon={TrendingUp}
          cor="blue"
        />
        <KPICard
          titulo="A Receber"
          valor={totalReceber}
          subtitulo={receiverVencidas > 0 ? `${receiverVencidas} vencido(s)` : `${itensReceber.length} pedido(s)`}
          icon={AlertCircle}
          cor={receiverVencidas > 0 ? "red" : "orange"}
        />
        <KPICard
          titulo="Saldo de Caixa"
          valor={saldoCaixa}
          subtitulo={saldoCaixa >= 0 ? "Positivo no mês" : "Negativo no mês"}
          icon={DollarSign}
          cor={saldoCaixa >= 0 ? "green" : "red"}
        />
        <KPICard
          titulo={temFolhaGerada ? "Folha do Mês" : "Folha do Mês (est.)"}
          valor={totalFolhaMes}
          subtitulo={folhaLabel}
          icon={Users}
          cor="gray"
          onClick={() => setModalPagamentosAberto(true)}
        />
        <KPICard
          titulo="Comissões"
          valor={totalComissoesMes}
          subtitulo="A pagar no mês"
          icon={Target}
          cor="orange"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* DRE Simplificado */}
        <Card className="border-0 shadow-md">
          <CardHeader className="pb-3">
            <CardTitle className="text-base font-semibold text-gray-800 dark:text-white flex items-center gap-2">
              <TrendingUp className="w-4 h-4 text-green-600" />
              DRE Simplificado — {descricaoPeriodoDre}
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            <DRELinha label="(+) Receita Bruta de Vendas" valor={dre.receitaBruta} />
            {dre.descontos > 0 && (
              <DRELinha label="(–) Descontos Concedidos" valor={dre.descontos} negativo nivel={1} />
            )}
            <DRELinha label="(=) Receita Líquida" valor={dre.receitaLiquida} destaque />
            {dre.despesasLancadas > 0 && (
              <DRELinha label="(–) Despesas Operacionais" valor={dre.despesasLancadas} negativo nivel={1} />
            )}
            {totalFolhaMes > 0 && (
              <DRELinha label={temFolhaGerada ? "(–) Folha de Pagamento" : "(–) Folha de Pagamento (est.)"} valor={totalFolhaMes} negativo nivel={1} />
            )}
            {totalComissoesMes > 0 && (
              <DRELinha label="(–) Comissões de Vendas" valor={totalComissoesMes} negativo nivel={1} />
            )}
            <DRELinha label="(=) Resultado Operacional" valor={temFolhaGerada ? dre.resultadoOperacional : dre.resultadoOperacional - folhaEstimada.total + totalFolhaDRE} destaque />

            <div className="pt-3 border-t border-gray-200 dark:border-neutral-700">
              <p className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide mb-2">
                Tendência de Resultado Operacional (12 meses)
              </p>
              <div className="space-y-1.5">
                {dreTendencia.map((item) => {
                  const valor = item.lucroOperacional || 0;
                  const percentual = (Math.abs(valor) / maxLucroAbsoluto) * 100;
                  const positivo = valor >= 0;
                  return (
                    <div key={item.mesAno} className="grid grid-cols-[56px_1fr_112px] items-center gap-2 text-xs">
                      <span className="text-gray-500 dark:text-gray-400">{item.label}</span>
                      <div className="w-full h-2 rounded-full bg-gray-100 dark:bg-neutral-800 overflow-hidden">
                        <div
                          className={`h-full rounded-full ${positivo ? "bg-emerald-500" : "bg-red-500"}`}
                          style={{ width: `${Math.min(100, percentual)}%` }}
                        />
                      </div>
                      <span className={`text-right tabular-nums font-medium ${positivo ? "text-emerald-600" : "text-red-600"}`}>
                        R$ {fmt(valor)}
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Meta + Alertas */}
        <div className="space-y-4">
          {/* Meta de Vendas */}
          <Card className="border-0 shadow-md">
            <CardHeader className="pb-2">
              <CardTitle className="text-base font-semibold text-gray-800 dark:text-white flex items-center gap-2">
                <Target className="w-4 h-4 text-orange-500" />
                Meta do Mês
              </CardTitle>
            </CardHeader>
            <CardContent>
              {metaMes ? (
                <div className="space-y-2">
                  <div className="flex justify-between text-sm">
                    <span className="text-gray-500">Meta:</span>
                    <span className="font-semibold">R$ {fmt(metaMes.valor_meta)}</span>
                  </div>
                  <div className="flex justify-between text-sm">
                    <span className="text-gray-500">Realizado:</span>
                    <span className={`font-semibold ${dre.receitaBruta >= metaMes.valor_meta ? "text-green-600" : "text-orange-600"}`}>
                      R$ {fmt(dre.receitaBruta)}
                    </span>
                  </div>
                  <div className="w-full bg-gray-100 dark:bg-neutral-700 rounded-full h-2 mt-2">
                    <div
                      className={`h-2 rounded-full transition-all ${percentualMeta >= 100 ? "bg-green-500" : percentualMeta >= 70 ? "bg-orange-400" : "bg-red-400"}`}
                      style={{ width: `${Math.min(percentualMeta, 100)}%` }}
                    />
                  </div>
                  <p className="text-xs text-gray-400 text-right">{percentualMeta}% atingido</p>
                </div>
              ) : (
                <p className="text-sm text-gray-400 py-2">Nenhuma meta cadastrada para este mês.</p>
              )}
            </CardContent>
          </Card>

          {/* Resumo de Pendências */}
          <Card className="border-0 shadow-md">
            <CardHeader className="pb-2">
              <CardTitle className="text-base font-semibold text-gray-800 dark:text-white flex items-center gap-2">
                <AlertCircle className="w-4 h-4 text-red-500" />
                Pendências Financeiras
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-2">
              <div className="flex justify-between items-center text-sm">
                <div className="flex items-center gap-2">
                  <ArrowDown className="w-3.5 h-3.5 text-orange-500" />
                  <span className="text-gray-600 dark:text-gray-400">A Receber (vendas)</span>
                </div>
                <span className="font-semibold text-orange-600">R$ {fmt(totalReceber)}</span>
              </div>
              {totalContasPagarCompras > 0 && (
                <div className="flex justify-between items-center text-sm">
                  <div className="flex items-center gap-2">
                    <ArrowUp className="w-3.5 h-3.5 text-red-500" />
                    <span className="text-gray-600 dark:text-gray-400">A Pagar (compras)</span>
                  </div>
                  <span className="font-semibold text-red-600">R$ {fmt(totalContasPagarCompras)}</span>
                </div>
              )}
              {totalFolhaMesPendente > 0 && (
                <div className="flex justify-between items-center text-sm">
                  <div className="flex items-center gap-2">
                    <ArrowUp className="w-3.5 h-3.5 text-red-500" />
                    <span className="text-gray-600 dark:text-gray-400">Folha de Pagamento</span>
                  </div>
                  <span className="font-semibold text-red-600">R$ {fmt(totalFolhaMesPendente)}</span>
                </div>
              )}
              {totalComissoesMes > 0 && (
                <div className="flex justify-between items-center text-sm">
                  <div className="flex items-center gap-2">
                    <ArrowUp className="w-3.5 h-3.5 text-red-500" />
                    <span className="text-gray-600 dark:text-gray-400">Comissões a Pagar</span>
                  </div>
                  <span className="font-semibold text-red-600">R$ {fmt(totalComissoesMes)}</span>
                </div>
              )}
              {totalReceber === 0 && totalContasPagarCompras === 0 && totalFolhaMesPendente === 0 && totalComissoesMes === 0 && (
                <p className="text-sm text-gray-400 py-1">Sem pendências no período.</p>
              )}
            </CardContent>
          </Card>
        </div>
      </div>

      {/* Próximas vendas com saldo em aberto (top 5) */}
      {itensReceber.length > 0 && (
        <Card className="border-0 shadow-md">
          <CardHeader className="pb-2">
            <CardTitle className="text-base font-semibold text-gray-800 dark:text-white flex items-center justify-between">
              <div className="flex items-center gap-2">
                <AlertCircle className="w-4 h-4 text-orange-500" />
                Saldo Pendente por Pedido
              </div>
              <Badge variant="outline" className="text-xs font-normal">
                {itensReceber.length} pedido(s) • R$ {fmt(totalReceber)}
              </Badge>
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {itensReceber
                .sort((a, b) => (b.valor_restante || 0) - (a.valor_restante || 0))
                .slice(0, 5)
                .map((v) => {
                  const vencida = v.prazo_entrega && new Date(v.prazo_entrega) < hoje;
                  return (
                    <div
                      key={v.id}
                      className="flex items-center justify-between p-3 rounded-lg bg-gray-50 dark:bg-neutral-800 gap-4"
                    >
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium text-gray-800 dark:text-gray-200 truncate">
                          {v.cliente_nome || "—"}
                        </p>
                        <p className="text-xs text-gray-400">
                          Pedido #{v.numero_pedido}
                          {v.prazo_entrega ? ` • prazo ${new Date(v.prazo_entrega).toLocaleDateString("pt-BR")}` : ""}
                        </p>
                      </div>
                      <div className="text-right shrink-0">
                        <p className={`text-sm font-semibold ${vencida ? "text-red-600" : "text-orange-600"}`}>
                          R$ {fmt(v.valor_restante)}
                        </p>
                        {vencida && (
                          <Badge className="text-xs bg-red-100 text-red-700 border-0">Vencido</Badge>
                        )}
                      </div>
                    </div>
                  );
                })}
              {itensReceber.length > 5 && (
                <p className="text-xs text-center text-gray-400 pt-1">
                  + {itensReceber.length - 5} pedido(s) - veja tudo em &quot;Contas a Receber&quot;
                </p>
              )}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Modal de Detalhamento da Folha */}
      <Dialog open={modalPagamentosAberto} onOpenChange={setModalPagamentosAberto}>
        <DialogContent className="sm:max-w-[600px] border-0 shadow-xl bg-white dark:bg-neutral-900 rounded-xl overflow-hidden p-0">
          <DialogHeader className="p-6 pb-4 border-b border-gray-100 dark:border-neutral-800 bg-gray-50/50 dark:bg-neutral-900/50">
            <DialogTitle className="text-lg font-bold text-gray-800 dark:text-white flex items-center gap-2">
              <Users className="w-5 h-5 text-indigo-600 dark:text-indigo-400" />
              Detalhamento de Pagamentos — {formatMesAno(mesAno)}
            </DialogTitle>
            <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
              {temFolhaGerada 
                ? "Demonstrativo dos pagamentos baseados na folha fechada do mês." 
                : "Estimativa baseada nos colaboradores ativos e suas configurações de contrato."}
            </p>
          </DialogHeader>

          <div className="p-6 max-h-[60vh] overflow-y-auto space-y-6">
            {!temFolhaGerada && (
              <div className="p-3.5 rounded-xl bg-amber-50 dark:bg-amber-950/20 border border-amber-200/60 dark:border-amber-900/30 flex items-start gap-3">
                <AlertCircle className="w-4 h-4 text-amber-600 dark:text-amber-500 mt-0.5 flex-shrink-0" />
                <div className="text-xs text-amber-800 dark:text-amber-300">
                  <span className="font-semibold block mb-0.5">Valores Estimados</span>
                  A folha deste mês ainda não foi gerada no módulo de RH. Exibindo estimativa com base nos salários e vales contratuais dos colaboradores ativos.
                </div>
              </div>
            )}

            {pagamentosAgrupados.length === 0 ? (
              <div className="text-center py-10 text-gray-500 dark:text-gray-400">
                <Users className="w-10 h-10 mx-auto text-gray-300 dark:text-neutral-700 mb-2" />
                <p className="text-sm font-medium">Nenhum pagamento previsto para este período.</p>
              </div>
            ) : (
              <div className="space-y-6">
                {pagamentosAgrupados.map((grupo) => (
                  <div key={grupo.dia} className="border border-gray-100 dark:border-neutral-800 rounded-xl overflow-hidden shadow-sm">
                    {/* Header do Grupo por Data */}
                    <div className="bg-gray-50 dark:bg-neutral-800/40 px-4 py-3 border-b border-gray-100 dark:border-neutral-800 flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <Calendar className="w-4 h-4 text-gray-500 dark:text-gray-400" />
                        <span className="text-sm font-bold text-gray-700 dark:text-gray-300">
                          Dia {grupo.dia} {grupo.tipo_dia === "util" ? "(Dia Útil)" : ""}
                        </span>
                      </div>
                      <div className="text-right">
                        <span className="text-xs text-gray-400 dark:text-gray-500 mr-1.5 uppercase font-medium tracking-wider">Total do Dia:</span>
                        <span className="text-sm font-extrabold text-gray-900 dark:text-white">
                          R$ {fmt(grupo.total)}
                        </span>
                      </div>
                    </div>

                    {/* Lista de Pagamentos do Grupo */}
                    <div className="divide-y divide-gray-100 dark:divide-neutral-800">
                      {grupo.pagamentos.map((pag, idx) => (
                        <div key={idx} className="px-4 py-3 flex items-center justify-between hover:bg-gray-50/50 dark:hover:bg-neutral-800/10 transition-colors">
                          <div className="flex-1 min-w-0">
                            <p className="text-sm font-semibold text-gray-800 dark:text-gray-200 truncate">
                              {pag.colaborador_nome}
                            </p>
                            <div className="flex items-center gap-2 mt-1">
                              <Badge 
                                variant="outline" 
                                className={`text-[10px] py-0 px-2 font-semibold ${
                                  pag.tipo === "Vale"
                                    ? "bg-purple-50 text-purple-700 border-purple-200/50 dark:bg-purple-950/20 dark:text-purple-400 dark:border-purple-900/30"
                                    : "bg-blue-50 text-blue-700 border-blue-200/50 dark:bg-blue-950/20 dark:text-blue-400 dark:border-blue-900/30"
                                }`}
                              >
                                {pag.tipo}
                              </Badge>
                              <span className="text-xs text-gray-400 dark:text-gray-500">
                                {pag.tipo_dia === "util" ? `${pag.dia}º dia útil` : `todo dia ${pag.dia}`}
                              </span>
                            </div>
                          </div>
                          <div className="flex items-center gap-3 shrink-0">
                            <span className="text-sm font-bold text-gray-800 dark:text-gray-200 tabular-nums">
                              R$ {fmt(pag.valor)}
                            </span>
                            {temFolhaGerada ? (
                              <Badge 
                                className={`text-[10px] py-0.5 px-2 font-semibold border-0 ${
                                  pag.pago
                                    ? "bg-green-100 text-green-700 dark:bg-green-950/30 dark:text-green-400"
                                    : "bg-yellow-100 text-yellow-700 dark:bg-yellow-950/30 dark:text-yellow-400"
                                }`}
                              >
                                {pag.pago ? "Pago" : "Pendente"}
                              </Badge>
                            ) : (
                              <Badge className="text-[10px] py-0.5 px-2 font-semibold bg-amber-100 text-amber-700 dark:bg-amber-950/30 dark:text-amber-400 border-0">
                                Previsto
                              </Badge>
                            )}
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Footer com o Somatório Geral */}
          <div className="p-6 bg-gray-50 dark:bg-neutral-800/20 border-t border-gray-100 dark:border-neutral-800">
            {temFolhaGerada ? (
              <div className="grid grid-cols-3 gap-4 text-center">
                <div className="bg-gray-100/50 dark:bg-neutral-800/20 p-2.5 rounded-lg">
                  <span className="text-[10px] text-gray-400 dark:text-gray-500 uppercase font-bold tracking-wider block">
                    Total da Folha
                  </span>
                  <span className="text-base font-extrabold text-gray-800 dark:text-gray-250 tabular-nums block mt-1">
                    R$ {fmt(totalFolhaMes)}
                  </span>
                </div>
                <div className="bg-green-50/50 dark:bg-green-950/10 p-2.5 rounded-lg">
                  <span className="text-[10px] text-green-600 dark:text-green-500 uppercase font-bold tracking-wider block">
                    Total Pago
                  </span>
                  <span className="text-base font-extrabold text-green-600 dark:text-green-400 tabular-nums block mt-1">
                    R$ {fmt(totalFolhaMes - totalFolhaMesPendente)}
                  </span>
                </div>
                <div className="bg-red-50/50 dark:bg-red-950/10 p-2.5 rounded-lg">
                  <span className="text-[10px] text-red-600 dark:text-red-500 uppercase font-bold tracking-wider block">
                    A Pagar
                  </span>
                  <span className="text-base font-extrabold text-red-600 dark:text-red-400 tabular-nums block mt-1">
                    R$ {fmt(totalFolhaMesPendente)}
                  </span>
                </div>
              </div>
            ) : (
              <div className="flex items-center justify-between">
                <div>
                  <span className="text-xs text-gray-400 dark:text-gray-500 uppercase font-semibold tracking-wider block">
                    Total Geral da Folha (est.)
                  </span>
                  <span className="text-xs text-gray-500 dark:text-gray-400 mt-0.5 block">
                    Valor total estimado
                  </span>
                </div>
                <div className="text-right">
                  <span className="text-2xl font-black text-indigo-600 dark:text-indigo-400 tabular-nums">
                    R$ {fmt(totalFolhaMes)}
                  </span>
                </div>
              </div>
            )}
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { useAuth } from '@/hooks/useAuth';
import { useScanListener } from '@/hooks/useScanListener';
import { eanService } from '@/services/eanService';
import { supabase } from '@/lib/supabase';
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import {
    Package, CheckCircle, AlertTriangle, Search, Link as LinkIcon,
    Plus, Minus, ArrowRight, RotateCcw, Loader2, ImageIcon,
    Layers, Ruler, RefreshCw
} from 'lucide-react';
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import ProdutoCadastroCompleto from '@/components/produtos/ProdutoCadastroCompleto';
import { getColorHex } from '@/components/produtos/FurnitureColorPicker';
import { toast } from 'sonner';
import { isValidGTIN, normalizeGTIN, generateSafeSKU } from '@/utils/gtinValidator';

// ─── Audio ────────────────────────────────────────────────────────
let audioCtx = null;
const playSound = (type) => {
    try {
        if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        if (audioCtx.state === 'suspended') audioCtx.resume();
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc.connect(gain);
        gain.connect(audioCtx.destination);
        if (type === 'success') {
            osc.frequency.setValueAtTime(660, audioCtx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(880, audioCtx.currentTime + 0.1);
            gain.gain.setValueAtTime(0.1, audioCtx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.1);
            osc.start(); osc.stop(audioCtx.currentTime + 0.1);
        } else if (type === 'error') {
            osc.frequency.setValueAtTime(220, audioCtx.currentTime);
            osc.type = 'sawtooth';
            gain.gain.setValueAtTime(0.2, audioCtx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.3);
            osc.start(); osc.stop(audioCtx.currentTime + 0.3);
        } else if (type === 'wait') {
            osc.frequency.setValueAtTime(440, audioCtx.currentTime);
            gain.gain.setValueAtTime(0.1, audioCtx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.2);
            osc.start(); osc.stop(audioCtx.currentTime + 0.2);
        }
    } catch (e) { /* silently ignore */ }
};

// ─── Helper: compare names loosely ───────────────────────────────
function namesMatch(a, b) {
    if (!a || !b) return false;
    const normalize = s => s.toLowerCase().replace(/[^a-záàâãéèêíïóôõúç0-9]/gi, '').trim();
    return normalize(a) === normalize(b);
}

// ─── Multi-token search (same logic as EstoqueTab / supabase.js) ─
async function searchProdutosMultiToken(term) {
    if (!term || term.trim().length < 2) return [];
    const keywords = term.trim().split(/\s+/).filter(Boolean);

    let query = supabase.from('produtos').select('*');

    keywords.forEach(kw => {
        const escaped = kw.replace(/[%_]/g, '');
        query = query.or(
            `nome.ilike.%${escaped}%,` +
            `sku.ilike.%${escaped}%,` +
            `codigo_barras.ilike.%${escaped}%,` +
            `categoria.ilike.%${escaped}%,` +
            `modelo_referencia.ilike.%${escaped}%,` +
            `cor.ilike.%${escaped}%,` +
            `material.ilike.%${escaped}%,` +
            `ambiente.ilike.%${escaped}%,` +
            `fornecedor_nome.ilike.%${escaped}%,` +
            `descricao.ilike.%${escaped}%`
        );
    });

    const { data, error } = await query.order('nome').limit(15);
    if (error) { console.error('Search error:', error); return []; }
    return data || [];
}

// ═══════════════════════════════════════════════════════════════════
// STEPS: idle → loading → search → update → quantity → done
// ═══════════════════════════════════════════════════════════════════

export default function BipagemTab() {
    const { user } = useAuth();

    // ─── Wizard state ───────────────────────────────────────────
    const [step, setStep] = useState('idle');          // idle | loading | search | update | quantity | done
    const [pendingGtin, setPendingGtin] = useState(null);
    const [apiData, setApiData] = useState(null);      // normalized API result
    const [matchedProduct, setMatchedProduct] = useState(null); // selected internal product
    const [quantity, setQuantity] = useState(1);

    // ─── Search state ───────────────────────────────────────────
    const [searchTerm, setSearchTerm] = useState('');
    const [searchResults, setSearchResults] = useState([]);
    const [searching, setSearching] = useState(false);
    const debounceRef = useRef(null);

    // ─── Product creation modal ─────────────────────────────────
    const [showProdutoModal, setShowProdutoModal] = useState(false);
    const [savingProduct, setSavingProduct] = useState(false);

    // ─── History & feedback ─────────────────────────────────────
    const [scannedItems, setScannedItems] = useState([]);
    const [currentCard, setCurrentCard] = useState(null);
    const [manualCode, setManualCode] = useState('');

    // refs for auto-focus
    const searchInputRef = useRef(null);
    const quantityInputRef = useRef(null);

    // ─── Auto-focus when step changes ───────────────────────────
    useEffect(() => {
        if (step === 'search') {
            setTimeout(() => searchInputRef.current?.focus(), 100);
        } else if (step === 'quantity') {
            setTimeout(() => {
                quantityInputRef.current?.focus();
                quantityInputRef.current?.select();
            }, 100);
        }
    }, [step]);

    // ─── Debounced search ───────────────────────────────────────
    const runSearch = useCallback((term) => {
        if (debounceRef.current) clearTimeout(debounceRef.current);
        if (!term || term.trim().length < 2) {
            setSearchResults([]);
            return;
        }
        setSearching(true);
        debounceRef.current = setTimeout(async () => {
            const results = await searchProdutosMultiToken(term);
            setSearchResults(results);
            setSearching(false);
        }, 350);
    }, []);

    // ─── Reset wizard ───────────────────────────────────────────
    const resetWizard = useCallback(() => {
        setStep('idle');
        setPendingGtin(null);
        setApiData(null);
        setMatchedProduct(null);
        setQuantity(1);
        setSearchTerm('');
        setSearchResults([]);
        setShowProdutoModal(false);
    }, []);

    // ═════════════════════════════════════════════════════════════
    // CORE: Handle a barcode scan
    // ═════════════════════════════════════════════════════════════
    const handleScan = useCallback(async (gtin) => {
        if (!gtin || step === 'loading') return;
        resetWizard();
        setStep('loading');
        setPendingGtin(gtin);
        setManualCode('');

        try {
            const result = await eanService.lookup(gtin);
            setApiData(result.apiData);

            if (result.source === 'internal') {
                const product = result.product;
                // Check if API data matches → skip to quantity or show update
                if (result.apiData && result.apiData.nome && !namesMatch(product.nome, result.apiData.nome)) {
                    // Internal product exists but name differs from universal registry
                    playSound('wait');
                    setMatchedProduct(product);
                    setStep('update');
                } else {
                    // Already correctly registered → go straight to quantity
                    playSound('wait');
                    setMatchedProduct(product);
                    setStep('quantity');
                }
            } else if (result.source === 'api') {
                // Found in API but not in internal DB → show search to find or create
                playSound('wait');
                setStep('search');
            } else {
                // Not found anywhere → show search to find or create
                playSound('error');
                setStep('search');
            }
        } catch (error) {
            console.error(error);
            playSound('error');
            setCurrentCard({ status: 'error', message: 'Erro ao processar: ' + error.message });
            setStep('idle');
        }
    }, [step, resetWizard]);

    // ═════════════════════════════════════════════════════════════
    // Select existing product from search results
    // ═════════════════════════════════════════════════════════════
    const handleSelectProduct = useCallback(async (product) => {
        if (!isValidGTIN(pendingGtin)) {
            toast.error('O código bipado não é um código de barras GTIN oficial válido (8, 12, 13 ou 14 dígitos).');
            return;
        }

        const validBarcode = normalizeGTIN(pendingGtin, true);

        // Link barcode to this product
        const { error } = await supabase
            .from('produtos')
            .update({ codigo_barras: validBarcode })
            .eq('id', product.id);

        if (error) {
            toast.error('Erro ao vincular código de barras: ' + error.message);
            return;
        }

        const updatedProduct = { ...product, codigo_barras: validBarcode };

        // Check if API has a better name
        if (apiData && apiData.nome && !namesMatch(product.nome, apiData.nome)) {
            setMatchedProduct(updatedProduct);
            setStep('update');
        } else {
            // Update NCM/foto if missing from API
            if (apiData) {
                const patch = {};
                if (!product.ncm && apiData.ncm) patch.ncm = apiData.ncm;
                if ((!product.fotos || !product.fotos.length) && apiData.foto_url) patch.fotos = [apiData.foto_url];
                if (Object.keys(patch).length > 0) {
                    await supabase.from('produtos').update(patch).eq('id', product.id);
                    Object.assign(updatedProduct, patch);
                }
            }
            setMatchedProduct(updatedProduct);
            setStep('quantity');
        }
    }, [pendingGtin, apiData]);

    const handleSkipUpdate = useCallback(() => {
        setStep('quantity');
    }, []);

    // ═════════════════════════════════════════════════════════════
    // Update product from API data
    // ═════════════════════════════════════════════════════════════
    const handleUpdateFromApi = useCallback(async () => {
        if (!matchedProduct || !apiData) return;

        const updates = { nome: apiData.nome };
        if (apiData.ncm && !matchedProduct.ncm) updates.ncm = apiData.ncm;
        if (apiData.foto_url && (!matchedProduct.fotos || matchedProduct.fotos.length === 0)) {
            updates.fotos = [apiData.foto_url];
        }

        const { error } = await supabase.from('produtos').update(updates).eq('id', matchedProduct.id);
        if (error) {
            toast.error('Erro ao atualizar: ' + error.message);
            return;
        }

        setMatchedProduct(prev => ({ ...prev, ...updates }));
        toast.success('Cadastro atualizado com informações do registro universal');
        setStep('quantity');
    }, [matchedProduct, apiData]);

    // ═════════════════════════════════════════════════════════════
    // Create new product flow (via ProdutoModal)
    // ═════════════════════════════════════════════════════════════
    const handleCreateProduct = useCallback(async (formData) => {
        setSavingProduct(true);
        try {
            const validGtin = (pendingGtin && isValidGTIN(pendingGtin))
                ? normalizeGTIN(pendingGtin, true)
                : (formData.codigo_barras && isValidGTIN(formData.codigo_barras) ? normalizeGTIN(formData.codigo_barras, true) : null);

            const { data, error } = await supabase.from('produtos').insert({
                ...formData,
                sku: formData.sku || generateSafeSKU('BIP'),
                codigo_barras: validGtin,
                ativo: true,
            }).select().single();

            if (error) throw error;

            setShowProdutoModal(false);
            setMatchedProduct(data);
            toast.success('Produto cadastrado');
            setStep('quantity');
        } catch (error) {
            toast.error('Erro ao cadastrar: ' + error.message);
        } finally {
            setSavingProduct(false);
        }
    }, [pendingGtin]);

    // ═════════════════════════════════════════════════════════════
    // Confirm quantity and update stock
    // ═════════════════════════════════════════════════════════════
    const handleConfirmQuantity = useCallback(async () => {
        if (!matchedProduct || quantity < 1) return;
        const tenantId = user?.loja || 'CD';
        const gtin = matchedProduct.codigo_barras || pendingGtin;

        try {
            const { error } = await supabase.from('estoque_loja').insert({
                gtin,
                tenant_id: tenantId,
                quantidade: quantity,
                data_movimento: new Date().toISOString()
            });
            if (error) throw error;

            await supabase.rpc('increment_estoque_global', { p_id: matchedProduct.id, p_qtd: quantity });

            playSound('success');
            setCurrentCard({
                status: 'success',
                message: `Estoque +${quantity}`,
                product: matchedProduct
            });
            setScannedItems(prev => [{
                ...matchedProduct,
                quantidade_adicionada: quantity,
                time: new Date().toLocaleTimeString(),
                status: 'success'
            }, ...prev.slice(0, 9)]);
            setStep('done');
        } catch (error) {
            playSound('error');
            toast.error('Erro ao atualizar estoque: ' + error.message);
        }
    }, [matchedProduct, quantity, pendingGtin, user]);

    // ─── Scan listener (disabled during active input steps) ─────
    const scanActive = step === 'idle' || step === 'done';
    useScanListener(scanActive ? handleScan : () => {});

    // ═════════════════════════════════════════════════════════════
    // RENDER
    // ═════════════════════════════════════════════════════════════
    return (
        <div className="flex flex-col h-full">
            <h1 className="text-3xl font-bold mb-6 flex items-center gap-2 text-slate-800">
                <Package className="h-8 w-8 text-primary" />
                Bipagem de Estoque
            </h1>

            {/* Manual input - always visible */}
            <div className="flex gap-4 mb-6">
                <Input
                    value={manualCode}
                    onChange={e => setManualCode(e.target.value)}
                    placeholder="Digitar ou bipar código de barras..."
                    className="text-lg py-6"
                    onKeyDown={e => {
                        if (e.key === 'Enter') {
                            e.preventDefault();
                            handleScan(manualCode);
                        }
                    }}
                    disabled={step === 'loading'}
                />
                <Button
                    size="lg"
                    onClick={() => handleScan(manualCode)}
                    disabled={step === 'loading' || !manualCode}
                >
                    {step === 'loading' ? <Loader2 className="h-5 w-5 animate-spin" /> : 'PROCESSAR'}
                </Button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 flex-1 min-h-0">
                {/* ─── Main Panel (2 cols) ─────────────────────── */}
                <div className="lg:col-span-2 flex flex-col">
                    {/* IDLE */}
                    {step === 'idle' && !currentCard && (
                        <div className="flex-1 flex items-center justify-center text-gray-400 border-2 border-dashed border-gray-300 rounded-xl p-12">
                            <div className="text-center">
                                <Package className="w-16 h-16 mx-auto mb-4 opacity-30" />
                                <p className="text-xl">Aguardando leitura de código de barras...</p>
                                <p className="text-sm mt-2">Bipe um produto ou digite o código manualmente</p>
                            </div>
                        </div>
                    )}

                    {/* LOADING */}
                    {step === 'loading' && (
                        <div className="flex-1 flex items-center justify-center">
                            <div className="text-center">
                                <Loader2 className="w-16 h-16 mx-auto mb-4 animate-spin text-primary" />
                                <p className="text-xl text-gray-600">Consultando código {pendingGtin}...</p>
                            </div>
                        </div>
                    )}

                    {/* SEARCH STEP: find or create product */}
                    {step === 'search' && (
                        <Card className="flex-1 flex flex-col">
                            <CardContent className="p-6 flex flex-col flex-1">
                                {/* API info header */}
                                <div className="bg-blue-50 p-4 rounded-lg border border-blue-200 mb-4">
                                    <p className="text-sm text-blue-600 font-medium">Código: {pendingGtin}</p>
                                    {apiData?.nome ? (
                                        <div className="mt-1">
                                            <p className="text-xs text-blue-500">Identificado no cadastro universal como:</p>
                                            <p className="font-bold text-lg text-blue-800">{apiData.nome}</p>
                                            {apiData.marca && <p className="text-sm text-blue-600">Marca: {apiData.marca}</p>}
                                        </div>
                                    ) : (
                                        <p className="text-sm text-blue-500 mt-1">Nenhuma informação encontrada nas bases externas.</p>
                                    )}
                                </div>

                                <h3 className="font-semibold text-gray-800 mb-2">Este produto já está cadastrado no sistema?</h3>
                                <p className="text-sm text-gray-500 mb-3">Pesquise por nome, cor, material, categoria, fornecedor — em qualquer ordem.</p>

                                {/* Search input */}
                                <div className="relative mb-3">
                                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                                    <Input
                                        ref={searchInputRef}
                                        placeholder="Ex: guarda roupa henn branco"
                                        value={searchTerm}
                                        onChange={e => {
                                            setSearchTerm(e.target.value);
                                            runSearch(e.target.value);
                                        }}
                                        className="pl-10 h-11 border-2 border-primary/40 focus:border-primary"
                                        onKeyDown={e => {
                                            if (e.key === 'Enter') e.preventDefault();
                                        }}
                                    />
                                    {searching && <Loader2 className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 animate-spin text-gray-400" />}
                                </div>

                                {/* Search results */}
                                <ScrollArea className="flex-1 border rounded-lg min-h-0">
                                    {searchResults.length > 0 ? (
                                        <div className="divide-y">
                                            {searchResults.map(prod => {
                                                const qtd = (prod.quantidade_estoque || 0) - (prod.quantidade_reservada || 0);
                                                return (
                                                    <button
                                                        key={prod.id}
                                                        type="button"
                                                        onClick={() => handleSelectProduct(prod)}
                                                        className="w-full text-left px-4 py-3 hover:bg-green-50 transition-colors flex flex-col gap-1"
                                                    >
                                                        <div className="flex items-center gap-3">
                                                            <div className="w-10 h-10 shrink-0 border rounded overflow-hidden bg-gray-50 flex items-center justify-center">
                                                                {prod.fotos?.[0] ? (
                                                                    <img src={prod.fotos[0]} alt="" className="w-full h-full object-cover" />
                                                                ) : (
                                                                    <ImageIcon className="w-5 h-5 text-gray-300" />
                                                                )}
                                                            </div>
                                                            <span className="flex-1 text-sm font-medium text-gray-800 truncate">
                                                                {prod.nome}
                                                                {prod.modelo_referencia && <span className="text-gray-400 ml-1">- {prod.modelo_referencia}</span>}
                                                            </span>
                                                            <span className={`text-xs font-medium ${qtd > 0 ? 'text-green-600' : 'text-orange-500'}`}>
                                                                {qtd}un
                                                            </span>
                                                        </div>
                                                        <div className="flex items-center flex-wrap gap-1.5 ml-13 pl-13">
                                                            {prod.cor && (
                                                                <span className="text-[10px] px-1.5 py-0.5 rounded bg-gray-50 border border-gray-200 text-gray-700 font-medium flex items-center gap-1">
                                                                    {(() => {
                                                                        const colors = prod.cor.split('/').map(c => c.trim());
                                                                        const hex1 = getColorHex(colors[0]);
                                                                        const hex2 = colors.length > 1 ? getColorHex(colors[1]) : null;
                                                                        return (
                                                                            <>
                                                                                <div
                                                                                    className="w-3 h-3 rounded-full border border-gray-300"
                                                                                    style={{ background: hex2 ? `linear-gradient(135deg, ${hex1} 50%, ${hex2} 50%)` : hex1 }}
                                                                                />
                                                                                {prod.cor}
                                                                            </>
                                                                        );
                                                                    })()}
                                                                </span>
                                                            )}
                                                            {prod.material && (
                                                                <span className="text-[10px] px-1.5 py-0.5 rounded bg-blue-50 text-blue-700 font-medium flex items-center">
                                                                    <Layers className="w-3 h-3 mr-0.5" /> {prod.material}
                                                                </span>
                                                            )}
                                                            {(prod.largura || prod.altura) && (
                                                                <span className="text-[10px] px-1.5 py-0.5 rounded bg-amber-50 text-amber-700 font-medium flex items-center">
                                                                    <Ruler className="w-3 h-3 mr-0.5" />
                                                                    {prod.largura || '?'}x{prod.altura || '?'}{prod.profundidade ? `x${prod.profundidade}` : ''} cm
                                                                </span>
                                                            )}
                                                            {prod.fornecedor_nome && (
                                                                <span className="text-[10px] px-1.5 py-0.5 rounded bg-gray-100 text-gray-600 border border-gray-200">
                                                                    {prod.fornecedor_nome}
                                                                </span>
                                                            )}
                                                            {prod.categoria && (
                                                                <span className="text-[10px] px-1.5 py-0.5 rounded bg-gray-100 text-gray-500">
                                                                    {prod.categoria}
                                                                </span>
                                                            )}
                                                        </div>
                                                    </button>
                                                );
                                            })}
                                        </div>
                                    ) : searchTerm.length >= 2 && !searching ? (
                                        <div className="p-6 text-center text-gray-500">
                                            <Package className="w-8 h-8 mx-auto mb-2 text-gray-300" />
                                            <p className="text-sm">Nenhum produto encontrado para "{searchTerm}"</p>
                                        </div>
                                    ) : (
                                        <div className="p-6 text-center text-gray-400">
                                            <Search className="w-8 h-8 mx-auto mb-2 opacity-30" />
                                            <p className="text-sm">Digite para buscar produtos cadastrados</p>
                                        </div>
                                    )}
                                </ScrollArea>

                                {/* Actions */}
                                <div className="flex gap-2 mt-4 pt-4 border-t">
                                    <Button variant="outline" onClick={resetWizard}>Cancelar</Button>
                                    <Button
                                        className="ml-auto"
                                        onClick={() => setShowProdutoModal(true)}
                                    >
                                        <Plus className="w-4 h-4 mr-2" />
                                        Cadastrar Novo Produto
                                    </Button>
                                </div>
                            </CardContent>
                        </Card>
                    )}

                    {/* UPDATE STEP: API name differs from internal */}
                    {step === 'update' && matchedProduct && apiData && (
                        <Card className="flex-1 flex flex-col">
                            <CardContent className="p-6 flex flex-col gap-4">
                                <h3 className="font-semibold text-gray-800 flex items-center gap-2">
                                    <RefreshCw className="w-5 h-5 text-amber-500" />
                                    Atualizar cadastro do produto?
                                </h3>
                                <p className="text-sm text-gray-500">
                                    O cadastro universal possui informações diferentes do cadastro interno. Deseja atualizar?
                                </p>

                                <div className="grid grid-cols-2 gap-4">
                                    {/* Current */}
                                    <div className="p-4 border rounded-lg bg-gray-50">
                                        <p className="text-xs font-medium text-gray-400 uppercase mb-2">Cadastro Atual</p>
                                        <p className="font-semibold text-gray-800">{matchedProduct.nome}</p>
                                        {matchedProduct.cor && <Badge variant="outline" className="mt-1 text-xs">{matchedProduct.cor}</Badge>}
                                    </div>
                                    {/* API */}
                                    <div className="p-4 border-2 border-primary/30 rounded-lg bg-green-50">
                                        <p className="text-xs font-medium text-primary uppercase mb-2">Cadastro Universal</p>
                                        <p className="font-semibold text-gray-800">{apiData.nome}</p>
                                        {apiData.marca && <p className="text-xs text-gray-500 mt-1">Marca: {apiData.marca}</p>}
                                    </div>
                                </div>

                                <div className="flex gap-2 justify-end pt-2">
                                    <Button variant="outline" onClick={handleSkipUpdate}>
                                        Manter atual
                                    </Button>
                                    <Button onClick={handleUpdateFromApi}>
                                        <RefreshCw className="w-4 h-4 mr-2" />
                                        Atualizar cadastro
                                    </Button>
                                </div>
                            </CardContent>
                        </Card>
                    )}

                    {/* QUANTITY STEP */}
                    {step === 'quantity' && matchedProduct && (
                        <Card className="flex-1 flex items-center justify-center">
                            <CardContent className="p-8 text-center w-full max-w-md">
                                {/* Product info */}
                                <div className="flex items-center gap-3 mb-6 text-left bg-gray-50 p-3 rounded-lg">
                                    <div className="w-12 h-12 shrink-0 border rounded overflow-hidden bg-white flex items-center justify-center">
                                        {matchedProduct.fotos?.[0] ? (
                                            <img src={matchedProduct.fotos[0]} alt="" className="w-full h-full object-cover" />
                                        ) : (
                                            <ImageIcon className="w-6 h-6 text-gray-300" />
                                        )}
                                    </div>
                                    <div className="min-w-0 flex-1">
                                        <p className="font-semibold text-gray-800 truncate">{matchedProduct.nome}</p>
                                        <div className="flex gap-2 mt-0.5">
                                            {matchedProduct.cor && <Badge variant="secondary" className="text-xs">{matchedProduct.cor}</Badge>}
                                            {matchedProduct.modelo_referencia && <span className="text-xs text-gray-500">{matchedProduct.modelo_referencia}</span>}
                                        </div>
                                    </div>
                                </div>

                                <p className="text-sm text-gray-500 mb-4">Informe a quantidade a adicionar ao estoque:</p>

                                {/* Quantity controls */}
                                <div className="flex items-center justify-center gap-4 mb-6">
                                    <Button
                                        size="lg"
                                        variant="outline"
                                        className="h-14 w-14 text-xl"
                                        onClick={() => setQuantity(q => Math.max(1, q - 1))}
                                        disabled={quantity <= 1}
                                    >
                                        <Minus className="w-5 h-5" />
                                    </Button>
                                    <Input
                                        ref={quantityInputRef}
                                        type="number"
                                        min="1"
                                        value={quantity}
                                        onChange={e => {
                                            const val = parseInt(e.target.value);
                                            if (!isNaN(val) && val >= 1) setQuantity(val);
                                        }}
                                        className="w-24 h-14 text-center text-3xl font-bold border-2 border-primary/40"
                                    />
                                    <Button
                                        size="lg"
                                        variant="outline"
                                        className="h-14 w-14 text-xl"
                                        onClick={() => setQuantity(q => q + 1)}
                                    >
                                        <Plus className="w-5 h-5" />
                                    </Button>
                                </div>

                                <div className="flex gap-2 justify-center">
                                    <Button variant="outline" onClick={resetWizard}>Cancelar</Button>
                                    <Button
                                        size="lg"
                                        onClick={handleConfirmQuantity}
                                        className="px-8"
                                    >
                                        <CheckCircle className="w-5 h-5 mr-2" />
                                        Confirmar +{quantity}
                                    </Button>
                                </div>
                            </CardContent>
                        </Card>
                    )}

                    {/* DONE / SUCCESS/ERROR CARD */}
                    {(step === 'done' || (step === 'idle' && currentCard)) && currentCard && (
                        <Card className={`flex-1 flex items-center justify-center border-4 shadow-xl ${currentCard.status === 'success' ? 'border-green-500 bg-green-50' : 'border-red-500 bg-red-50'}`}>
                            <CardContent className="p-8 text-center">
                                {currentCard.status === 'success'
                                    ? <CheckCircle className="w-20 h-20 text-green-500 mx-auto mb-4" />
                                    : <AlertTriangle className="w-20 h-20 text-red-500 mx-auto mb-4" />
                                }
                                <h2 className="text-3xl font-bold mb-2">{currentCard.message}</h2>
                                {currentCard.product && (
                                    <div className="mt-4">
                                        <p className="text-xl font-medium">{currentCard.product.nome}</p>
                                        {currentCard.product.cor && <Badge variant="outline" className="mt-2 text-lg">{currentCard.product.cor}</Badge>}
                                    </div>
                                )}
                                <Button variant="outline" className="mt-6" onClick={resetWizard}>
                                    <RotateCcw className="w-4 h-4 mr-2" />
                                    Nova Bipagem
                                </Button>
                            </CardContent>
                        </Card>
                    )}
                </div>

                {/* ─── History Panel (1 col) ──────────────────── */}
                <Card className="flex flex-col min-h-0">
                    <CardContent className="p-4 flex-1 flex flex-col min-h-0">
                        <h3 className="font-semibold mb-3 text-gray-700">Histórico Recente</h3>
                        <ScrollArea className="flex-1 min-h-0">
                            <div className="space-y-2">
                                {scannedItems.length === 0 && (
                                    <p className="text-center text-sm text-gray-400 py-8">Nenhum item bipado ainda</p>
                                )}
                                {scannedItems.map((item, i) => (
                                    <div key={i} className="flex justify-between items-center p-3 bg-white border rounded shadow-sm">
                                        <div className="min-w-0 flex-1">
                                            <p className="font-medium text-sm truncate">{item.nome}</p>
                                            <div className="flex items-center gap-2 mt-0.5">
                                                <span className="text-xs text-gray-500">{item.codigo_barras || item.gtin}</span>
                                                <Badge variant="secondary" className="text-xs">+{item.quantidade_adicionada || 1}</Badge>
                                            </div>
                                        </div>
                                        <span className="text-xs text-gray-400 ml-2 shrink-0">{item.time}</span>
                                    </div>
                                ))}
                            </div>
                        </ScrollArea>
                    </CardContent>
                </Card>
            </div>

            {/* ─── Cadastro completo para novos produtos ── */}
            <ProdutoCadastroCompleto
                isOpen={showProdutoModal}
                onClose={() => setShowProdutoModal(false)}
                onSave={handleCreateProduct}
                isLoading={savingProduct}
                produto={apiData ? {
                    nome: apiData.nome || '',
                    codigo_barras: pendingGtin || '',
                    ncm: apiData.ncm || '',
                    fotos: apiData.foto_url ? [apiData.foto_url] : [],
                } : {
                    codigo_barras: pendingGtin || '',
                }}
            />
        </div>
    );
}

import React, { useState } from "react";
import { base44 } from "@/api/base44Client";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Plus, CheckCircle } from "lucide-react";
import ProdutoForm from "../produtos/ProdutoForm";

export default function CadastroRapido() {
  const [mensagem, setMensagem] = useState(null);

  const queryClient = useQueryClient();

  const createMutation = useMutation({
    mutationFn: (data) => base44.entities.Produto.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['produtos'] });
      setMensagem({
        tipo: 'sucesso',
        texto: 'Produto cadastrado com sucesso!'
      });
      setTimeout(() => {
        setMensagem(null);
      }, 3000);
    },
    onError: () => {
      setMensagem({
        tipo: 'erro',
        texto: 'Erro ao cadastrar produto'
      });
    }
  });

  const handleSave = (produtoData) => {
    createMutation.mutate(produtoData);
  };

  return (
    <Card className="border-0 shadow-lg">
      <CardHeader>
        <CardTitle className="flex items-center gap-2" style={{ color: '#07593f' }}>
          <Plus className="w-6 h-6" />
          Cadastro de Produto
        </CardTitle>
      </CardHeader>
      <CardContent>
        {mensagem && (
          <Alert className="border-2 bg-green-50 mb-6" style={{ borderColor: '#07593f' }}>
            <CheckCircle className="h-5 w-5" style={{ color: '#07593f' }} />
            <AlertDescription className="ml-2" style={{ color: '#07593f' }}>
              {mensagem.texto}
            </AlertDescription>
          </Alert>
        )}

        <ProdutoForm
          onSave={handleSave}
          isLoading={createMutation.isPending}
        />
      </CardContent>
    </Card>
  );
}

import React, { useState, useRef, useMemo } from "react";
import { normSearch } from "@/lib/utils";
import { base44 } from "@/api/base44Client";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Progress } from "@/components/ui/progress";
import {
    ArrowLeft, ScanBarcode, Search, Save, CheckCircle2,
    Filter, Package, Loader2, Warehouse
} from "lucide-react";
import { toast } from "sonner";
import { obterCampoEstoqueDaLoja, calcularEstoqueTotal } from "@/constants/productConstants";

export default function CargaInicialEstoque({ onVoltar }) {
    const queryClient = useQueryClient();

    // --- State ---
    const [lojaId, setLojaId] = useState("");
    const [quantidades, setQuantidades] = useState({}); // { [produto_id]: number }
    const [searchTerm, setSearchTerm] = useState("");
    const [categoriaFiltro, setCategoriaFiltro] = useState("todas");
    const [filtroPreenchimento, setFiltroPreenchimento] = useState("todos");
    const [isSaving, setIsSaving] = useState(false);
    const [saveProgress, setSaveProgress] = useState({ current: 0, total: 0 });
    const [visibleCount, setVisibleCount] = useState(50);

    const inputRefs = useRef({});

    // --- Queries ---
    const { data: produtos = [], isLoading: loadingProdutos } = useQuery({
        queryKey: ['produtos-carga-inicial'],
        queryFn: () => base44.entities.Produto.list(),
    });

    const { data: lojasData = [], isLoading: loadingLojas } = useQuery({
        queryKey: ['lojas'],
        queryFn: () => base44.entities.Loja.list('nome'),
    });

    const lojasAtivas = useMemo(() => lojasData.filter(l => l.ativa), [lojasData]);

    const getLojaDisplayName = (id) => {
        const loja = lojasData.find(l => l.id === id);
        return loja ? loja.nome : id;
    };

    const getLojaField = (id) => {
        const loja = lojasData.find(l => l.id === id);
        return obterCampoEstoqueDaLoja(loja);
    };

    // --- Derived data ---
    const campoEstoque = getLojaField(lojaId);

    const categorias = useMemo(() => {
        const cats = [...new Set(produtos.map(p => p.categoria).filter(Boolean))].sort();
        return cats;
    }, [produtos]);

    const produtosFiltrados = useMemo(() => {
        let result = [...produtos];

        if (categoriaFiltro !== "todas") {
            result = result.filter(p => p.categoria === categoriaFiltro);
        }

        if (searchTerm.trim()) {
            const terms = normSearch(searchTerm).split(/\s+/).filter(Boolean);
            result = result.filter(p => {
                const searchString = [p.nome, p.codigo_barras, p.modelo_referencia].filter(Boolean).map(normSearch).join(' ');
                return terms.every(term => searchString.includes(term));
            });
        }

        if (filtroPreenchimento === "preenchidos") {
            result = result.filter(p => quantidades[p.id] !== undefined && quantidades[p.id] !== null && quantidades[p.id] !== "");
        } else if (filtroPreenchimento === "vazios") {
            result = result.filter(p => quantidades[p.id] === undefined || quantidades[p.id] === null || quantidades[p.id] === "");
        }

        // Sort: by category, then name
        result.sort((a, b) => {
            const catA = a.categoria || "ZZZ";
            const catB = b.categoria || "ZZZ";
            if (catA !== catB) return catA.localeCompare(catB);
            return (a.nome || "").localeCompare(b.nome || "");
        });

        return result;
    }, [produtos, categoriaFiltro, searchTerm, filtroPreenchimento, quantidades]);

    // Reset pagination when filters change
    React.useEffect(() => {
        setVisibleCount(50);
    }, [categoriaFiltro, searchTerm, filtroPreenchimento]);

    const produtosVisiveis = produtosFiltrados.slice(0, visibleCount);

    // Stats
    const totalPreenchidos = produtos.filter(p =>
        quantidades[p.id] !== undefined && quantidades[p.id] !== null && quantidades[p.id] !== ""
    ).length;
    const totalProdutos = produtos.length;
    const progresso = totalProdutos > 0 ? Math.round((totalPreenchidos / totalProdutos) * 100) : 0;

    // --- Handlers ---
    const handleQtdChange = (produtoId, value) => {
        if (value === "") {
            setQuantidades(prev => ({ ...prev, [produtoId]: "" }));
        } else {
            const num = parseInt(value);
            if (!isNaN(num) && num >= 0) {
                setQuantidades(prev => ({ ...prev, [produtoId]: num }));
            }
        }
    };

    const handleBarcodeSubmit = (e) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            const code = e.target.value.trim();
            if (!code) return;

            const produto = produtos.find(p => p.codigo_barras === code);
            if (produto) {
                const inputEl = inputRefs.current[produto.id];
                if (inputEl) {
                    inputEl.focus();
                    inputEl.select();
                    toast.success(`📦 ${produto.nome}`);
                } else {
                    toast.info(`Produto "${produto.nome}" encontrado. Ajuste os filtros para vê-lo.`);
                }
            } else {
                toast.error("Produto não encontrado com este código de barras.");
            }
            e.target.value = "";
        }
    };

    const handleSalvar = async () => {
        const produtosParaSalvar = Object.entries(quantidades)
            .filter(([_, qtd]) => qtd !== undefined && qtd !== null && qtd !== "")
            .map(([id, qtd]) => ({ id: parseInt(id), qtd: parseInt(qtd) }));

        if (produtosParaSalvar.length === 0) {
            toast.error("Nenhuma quantidade preenchida para salvar.");
            return;
        }

        const confirmMsg = `Salvar estoque de ${produtosParaSalvar.length} produto(s) em "${getLojaDisplayName(lojaId)}"?\n\nIsso vai SUBSTITUIR o estoque atual desses produtos nesta unidade.`;
        if (!confirm(confirmMsg)) return;

        setIsSaving(true);
        setSaveProgress({ current: 0, total: produtosParaSalvar.length });

        let saved = 0;
        let errors = 0;

        // Save in batches of 5 to avoid overwhelming the API
        const batchSize = 5;
        for (let i = 0; i < produtosParaSalvar.length; i += batchSize) {
            const batch = produtosParaSalvar.slice(i, i + batchSize);
            const promises = batch.map(async ({ id, qtd }) => {
                try {
                    const p = produtos.find(item => item.id === id);
                    const itemComQtdAtualizada = {
                        ...p,
                        [campoEstoque]: qtd
                    };
                    const novoTotal = calcularEstoqueTotal(itemComQtdAtualizada, lojasAtivas);

                    await base44.entities.Produto.update(id, { 
                        [campoEstoque]: qtd,
                        quantidade_estoque: novoTotal
                    });
                    saved++;
                } catch (err) {
                    console.error(`Erro ao salvar produto ${id}:`, err);
                    errors++;
                }
            });
            await Promise.all(promises);
            setSaveProgress({ current: Math.min(i + batchSize, produtosParaSalvar.length), total: produtosParaSalvar.length });
        }

        setIsSaving(false);

        if (errors > 0) {
            toast.warning(`Salvo ${saved} produto(s), ${errors} erro(s). Verifique o console.`);
        } else {
            toast.success(`✅ Estoque atualizado para ${saved} produto(s) em "${getLojaDisplayName(lojaId)}"!`);
        }

        // Invalidate queries so the rest of the app sees the new stock (TanStack Query v5 syntax)
        queryClient.invalidateQueries({ queryKey: ['produtos'] });
        queryClient.invalidateQueries({ queryKey: ['produtos-carga-inicial'] });
        queryClient.invalidateQueries({ queryKey: ['produtos-inventario'] });
    };

    // Pre-fill with existing stock values when selecting a store
    const handleSelectLoja = (id) => {
        setLojaId(id);
        const campo = getLojaField(id);
        if (campo && produtos.length > 0) {
            const existing = {};
            produtos.forEach(p => {
                const val = p[campo];
                if (val !== undefined && val !== null && val > 0) {
                    existing[p.id] = val;
                }
            });
            setQuantidades(existing);
        } else {
            setQuantidades({});
        }
    };

    // --- Phase 1: Store selection ---
    if (!lojaId) {
        return (
            <div className="space-y-6">
                <div className="flex items-center gap-3">
                    <Button variant="ghost" size="icon" onClick={onVoltar}>
                        <ArrowLeft className="w-5 h-5" />
                    </Button>
                    <div>
                        <h2 className="text-xl font-bold" style={{ color: '#07593f' }}>
                            Carga Inicial de Estoque
                        </h2>
                        <p className="text-sm" style={{ color: '#8B8B8B' }}>
                            Selecione a unidade para cadastrar as quantidades em estoque
                        </p>
                    </div>
                </div>

                <div className="p-4 rounded-lg border" style={{ backgroundColor: '#FFFBEB', borderColor: '#FDE68A' }}>
                    <p className="text-sm" style={{ color: '#92400E' }}>
                        <strong>⚠️ Use esta tela apenas para a carga inicial.</strong> Ela grava as quantidades diretamente no cadastro dos produtos.
                        Depois que o estoque estiver alimentado, use o <strong>Inventário</strong> para auditorias periódicas.
                    </p>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 max-w-4xl">
                    {loadingLojas ? (
                        <div className="col-span-full text-center py-8 text-gray-500">
                            <Loader2 className="w-8 h-8 animate-spin mx-auto mb-2" />
                            Carregando lojas...
                        </div>
                    ) : lojasAtivas.length === 0 ? (
                        <div className="col-span-full text-center py-8 text-gray-500 bg-white border rounded-lg">
                            <p>Nenhuma loja ativa cadastrada.</p>
                            <p className="text-sm mt-1">Acesse as Configurações para adicionar lojas.</p>
                        </div>
                    ) : lojasAtivas.map(loja => {
                        const field = obterCampoEstoqueDaLoja(loja);
                        const qtdComEstoque = produtos.filter(p => (p[field] || 0) > 0).length;
                        return (
                            <Card
                                key={loja.id}
                                className="border-2 cursor-pointer transition-all hover:shadow-lg hover:border-green-400 active:scale-[0.98]"
                                style={{ borderColor: '#E5E0D8' }}
                                onClick={() => handleSelectLoja(loja.id)}
                            >
                                <CardContent className="p-6 text-center">
                                    <div
                                        className="w-14 h-14 rounded-full mx-auto mb-3 flex items-center justify-center"
                                        style={{ backgroundColor: '#D1FAE5' }}
                                    >
                                        <Warehouse className="w-7 h-7" style={{ color: '#065F46' }} />
                                    </div>
                                    <h3 className="font-bold text-lg mb-1" style={{ color: '#07593f' }}>{loja.nome}</h3>
                                    <p className="text-sm" style={{ color: '#8B8B8B' }}>
                                        {loadingProdutos ? '...' : qtdComEstoque > 0
                                            ? `${qtdComEstoque} produtos já com estoque`
                                            : 'Nenhum estoque cadastrado'}
                                    </p>
                                    <Badge className="mt-2" variant={qtdComEstoque > 0 ? "default" : "secondary"}>
                                        {qtdComEstoque > 0 ? 'Já tem dados' : 'Vazio'}
                                    </Badge>
                                </CardContent>
                            </Card>
                        );
                    })}
                </div>
            </div>
        );
    }

    // --- Phase 2: Quantity entry screen ---
    return (
        <div className="space-y-4">
            {/* Header */}
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
                <div className="flex items-center gap-3">
                    <Button variant="ghost" size="icon" onClick={() => { setLojaId(""); setQuantidades({}); }}>
                        <ArrowLeft className="w-5 h-5" />
                    </Button>
                    <div>
                        <h2 className="text-xl font-bold" style={{ color: '#07593f' }}>
                            Carga Inicial — {getLojaDisplayName(lojaId)}
                        </h2>
                        <p className="text-sm" style={{ color: '#8B8B8B' }}>
                            Campo: <code className="bg-gray-100 px-1 rounded text-xs">{campoEstoque}</code>
                        </p>
                    </div>
                </div>
                <Button
                    onClick={handleSalvar}
                    disabled={isSaving || totalPreenchidos === 0}
                    style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
                    className="min-w-[180px]"
                >
                    {isSaving ? (
                        <>
                            <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                            Salvando {saveProgress.current}/{saveProgress.total}...
                        </>
                    ) : (
                        <>
                            <Save className="w-4 h-4 mr-2" />
                            Salvar Estoque ({totalPreenchidos} itens)
                        </>
                    )}
                </Button>
            </div>

            {/* Warning */}
            <div className="p-3 rounded-lg border" style={{ backgroundColor: '#FEF3C7', borderColor: '#FDE68A' }}>
                <p className="text-xs" style={{ color: '#92400E' }}>
                    💡 <strong>Dica:</strong> Preencha apenas o que tem na loja. Produtos deixados em branco ficarão com estoque 0.
                    Você pode voltar e editar depois. Use o leitor de código de barras para agilizar.
                </p>
            </div>

            {/* Progress bar */}
            <Card className="border-0 shadow-sm" style={{ backgroundColor: '#f0f9ff' }}>
                <CardContent className="p-4">
                    <div className="flex justify-between items-center mb-2">
                        <span className="text-sm font-medium" style={{ color: '#07593f' }}>
                            Progresso do Preenchimento
                        </span>
                        <span className="text-sm font-bold" style={{ color: '#07593f' }}>
                            {totalPreenchidos} / {totalProdutos} produtos ({progresso}%)
                        </span>
                    </div>
                    <Progress value={progresso} className="h-3" />
                </CardContent>
            </Card>

            {/* Barcode + Search + Filters */}
            <div className="flex flex-col sm:flex-row gap-3">
                <div className="relative flex-1 sm:max-w-xs">
                    <ScanBarcode className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4" style={{ color: '#8B8B8B' }} />
                    <Input
                        className="pl-10"
                        placeholder="Bipar código de barras..."
                        onKeyDown={handleBarcodeSubmit}
                    />
                </div>

                <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4" style={{ color: '#8B8B8B' }} />
                    <Input
                        className="pl-10"
                        placeholder="Buscar por nome, código ou referência..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                </div>

                <Select value={categoriaFiltro} onValueChange={setCategoriaFiltro}>
                    <SelectTrigger className="w-full sm:w-48">
                        <Filter className="w-4 h-4 mr-2" style={{ color: '#8B8B8B' }} />
                        <SelectValue placeholder="Categoria" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="todas">Todas Categorias</SelectItem>
                        {categorias.map(cat => (
                            <SelectItem key={cat} value={cat}>{cat}</SelectItem>
                        ))}
                    </SelectContent>
                </Select>

                <Select value={filtroPreenchimento} onValueChange={setFiltroPreenchimento}>
                    <SelectTrigger className="w-full sm:w-44">
                        <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="todos">Todos</SelectItem>
                        <SelectItem value="preenchidos">Preenchidos</SelectItem>
                        <SelectItem value="vazios">Não Preenchidos</SelectItem>
                    </SelectContent>
                </Select>
            </div>

            {/* Products Table */}
            {loadingProdutos ? (
                <div className="text-center py-16">
                    <Loader2 className="w-10 h-10 animate-spin mx-auto mb-3" style={{ color: '#07593f' }} />
                    <p style={{ color: '#8B8B8B' }}>Carregando produtos...</p>
                </div>
            ) : produtosFiltrados.length === 0 ? (
                <div className="text-center py-16">
                    <Package className="w-12 h-12 mx-auto mb-3" style={{ color: '#C0C0C0' }} />
                    <p style={{ color: '#8B8B8B' }}>
                        {totalProdutos === 0
                            ? "Nenhum produto cadastrado no sistema."
                            : "Nenhum produto corresponde aos filtros."
                        }
                    </p>
                </div>
            ) : (
                <div className="border rounded-xl overflow-hidden" style={{ borderColor: '#E5E0D8' }}>
                    {/* Table header */}
                    <div
                        className="grid grid-cols-12 gap-2 px-4 py-3 text-xs font-semibold uppercase tracking-wider"
                        style={{ backgroundColor: '#FAF8F5', color: '#8B8B8B' }}
                    >
                        <div className="col-span-5 sm:col-span-5">Produto</div>
                        <div className="col-span-3 hidden sm:block">Categoria</div>
                        <div className="col-span-4 sm:col-span-2 text-center">Estoque Atual</div>
                        <div className="col-span-3 sm:col-span-2 text-center">Nova Qtd.</div>
                    </div>

                    {/* Table body */}
                    <div className="divide-y" style={{ borderColor: '#F0EDE8' }}>
                        {produtosVisiveis.map(produto => {
                            const estoqueAtual = produto[campoEstoque] || 0;
                            const novaQtd = quantidades[produto.id];
                            const isPreenchido = novaQtd !== undefined && novaQtd !== null && novaQtd !== "";

                            return (
                                <div
                                    key={produto.id}
                                    className="grid grid-cols-12 gap-2 px-4 py-3 items-center transition-colors"
                                    style={{
                                        backgroundColor: isPreenchido ? '#F0FDF4' : '#FFFFFF',
                                    }}
                                >
                                    {/* Product info */}
                                    <div className="col-span-5 sm:col-span-5">
                                        <p className="font-medium text-sm leading-tight" style={{ color: '#1a1a1a' }}>
                                            {produto.nome}
                                        </p>
                                        <p className="text-xs mt-0.5" style={{ color: '#8B8B8B' }}>
                                            {produto.modelo_referencia && <span>{produto.modelo_referencia} • </span>}
                                            {produto.codigo_barras && <span>COD: {produto.codigo_barras}</span>}
                                        </p>
                                    </div>

                                    {/* Category */}
                                    <div className="col-span-3 hidden sm:block">
                                        <Badge variant="secondary" className="text-xs font-normal">
                                            {produto.categoria || '-'}
                                        </Badge>
                                    </div>

                                    {/* Current stock */}
                                    <div className="col-span-4 sm:col-span-2 text-center">
                                        <span className="text-sm font-mono" style={{ color: estoqueAtual > 0 ? '#07593f' : '#C0C0C0' }}>
                                            {estoqueAtual}
                                        </span>
                                    </div>

                                    {/* New quantity input */}
                                    <div className="col-span-3 sm:col-span-2 flex justify-center">
                                        <Input
                                            ref={el => { if (el) inputRefs.current[produto.id] = el; }}
                                            type="number"
                                            min="0"
                                            className="w-20 text-center font-bold text-lg h-10"
                                            style={{
                                                borderColor: isPreenchido ? '#10B981' : '#E5E0D8',
                                                backgroundColor: isPreenchido ? '#FFFFFF' : '#F9FAFB',
                                            }}
                                            value={novaQtd ?? ""}
                                            onChange={(e) => handleQtdChange(produto.id, e.target.value)}
                                            onFocus={(e) => e.target.select()}
                                            placeholder="—"
                                        />
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* Load More Button */}
            {produtosFiltrados.length > visibleCount && (
                <div className="flex justify-center py-4">
                    <Button
                        variant="outline"
                        onClick={() => setVisibleCount(prev => prev + 50)}
                        className="w-full sm:w-auto"
                    >
                        Carregar mais produtos ({produtosFiltrados.length - visibleCount} restantes)
                    </Button>
                </div>
            )}

            {/* Sticky footer */}
            <div
                className="sticky bottom-0 p-4 rounded-xl shadow-lg border flex flex-col sm:flex-row items-center justify-between gap-3"
                style={{ backgroundColor: '#FFFFFF', borderColor: '#E5E0D8' }}
            >
                <div className="flex gap-6 text-sm">
                    <span>
                        <strong style={{ color: '#07593f' }}>{totalPreenchidos}</strong>
                        <span style={{ color: '#8B8B8B' }}> / {totalProdutos} preenchidos</span>
                    </span>
                    <span style={{ color: '#8B8B8B' }}>
                        Loja: <strong>{getLojaDisplayName(lojaId)}</strong>
                    </span>
                </div>
                <Button
                    onClick={handleSalvar}
                    disabled={isSaving || totalPreenchidos === 0}
                    style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
                    className="min-w-[180px]"
                >
                    {isSaving ? (
                        <>
                            <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                            Salvando...
                        </>
                    ) : (
                        <>
                            <CheckCircle2 className="w-4 h-4 mr-2" />
                            Salvar Estoque ({totalPreenchidos})
                        </>
                    )}
                </Button>
            </div>
        </div>
    );
}

import React, { useState, useEffect, useMemo } from "react";
import { normSearch } from "@/lib/utils";
import { base44, supabase } from "@/api/base44Client";
import { useQuery, useMutation, useQueryClient, useInfiniteQuery } from "@tanstack/react-query";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Search, MoreHorizontal, Trash2, Edit, ArrowRightLeft, Filter, Loader2, PackageOpen, Plus, AlertCircle, Ruler, Layers, Printer } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger, DropdownMenuSeparator } from "@/components/ui/dropdown-menu";
import ProdutoCadastroCompleto from "../produtos/ProdutoCadastroCompleto";
import ProdutoConferenciaModal from "./ProdutoConferenciaModal";
import ProductIncompleteIndicator from "../produtos/ProductIncompleteIndicator";
import { getColorHex } from "../produtos/FurnitureColorPicker";
import MovimentacaoModal from "./MovimentacaoModal";
import { useConfirm } from "@/hooks/useConfirm";
import { toast } from "sonner";
import GeradorEtiquetasModal from "./GeradorEtiquetasModal";
import { useLojas } from "@/hooks/useLojas";
import { obterCampoEstoqueDaLoja } from "@/constants/productConstants";
import { useAuth } from "@/hooks/useAuth";

const EditableStockCell = ({ produto, campo, valorOriginal, onSave, canEdit }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [value, setValue] = useState(valorOriginal);

  const handleKeyDown = (e) => {
    if (e.key === 'Enter') {
      const numValue = Number(value);
      if (numValue !== valorOriginal && !isNaN(numValue)) {
        onSave(produto, campo, numValue);
      }
      setIsEditing(false);
    } else if (e.key === 'Escape') {
      setValue(valorOriginal);
      setIsEditing(false);
    }
  };

  const handleBlur = () => {
    setValue(valorOriginal);
    setIsEditing(false);
  };

  if (!canEdit) {
    return <span className={`font-medium ${valorOriginal === 0 ? 'text-red-500' : 'text-gray-900 dark:text-white'}`}>{valorOriginal}</span>;
  }

  if (isEditing) {
    return (
      <input
        type="number"
        value={value}
        onChange={(e) => setValue(e.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={handleBlur}
        autoFocus
        onWheel={(e) => e.target.blur()}
        className="w-14 h-6 text-center text-xs border border-green-500 rounded outline-none shadow-sm [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
        style={{ MozAppearance: 'textfield' }}
      />
    );
  }

  return (
    <span 
      className={`font-medium cursor-pointer hover:text-green-600 hover:underline px-1 py-0.5 rounded transition-colors ${valorOriginal === 0 ? 'text-red-500' : 'text-gray-900 dark:text-white'}`}
      onClick={() => setIsEditing(true)}
      title="Clique para editar"
    >
      {valorOriginal}
    </span>
  );
};

export default function EstoqueTab({ user }) {
  const { data: lojasAtivas = [] } = useLojas();
  const lojasComCd = useMemo(() => {
    const hasCd = lojasAtivas.some((loja) => obterCampoEstoqueDaLoja(loja) === 'estoque_cd');
    if (hasCd) return lojasAtivas;
    return [{ id: 'cd-fallback', nome: 'Depósito / CD' }, ...lojasAtivas];
  }, [lojasAtivas]);
  const [searchTerm, setSearchTerm] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  const [selectedCategoria, setSelectedCategoria] = useState("todas");
  const [selectedFabricante, setSelectedFabricante] = useState("todos");
  const [selectedOrdenacao, setSelectedOrdenacao] = useState("alfabetica");
  const [selectedDirecao, setSelectedDirecao] = useState("asc");
  const [filtroAtencao, setFiltroAtencao] = useState(false);
  const [editingProduto, setEditingProduto] = useState(null);
  const [cadastroProduto, setCadastroProduto] = useState(null);
  const [focusField, setFocusField] = useState(null);
  const [movingProduto, setMovingProduto] = useState(null);
  const [isCadastroModalOpen, setIsCadastroModalOpen] = useState(false);
  const [isConferenciaModalOpen, setIsConferenciaModalOpen] = useState(false);
  const [isMoveModalOpen, setIsMoveModalOpen] = useState(false);
  const [isGeradorEtiquetasOpen, setIsGeradorEtiquetasOpen] = useState(false);
  const [produtosParaEtiqueta, setProdutosParaEtiqueta] = useState([]);

  // Debounce search
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(searchTerm);
    }, 500);
    return () => clearTimeout(timer);
  }, [searchTerm]);

  // Listen for header action event
  useEffect(() => {
    const handleAction = (e) => {
      if (e.detail === 'estoque') {
        setCadastroProduto(null);
        setFocusField(null);
        setIsCadastroModalOpen(true);
      }
    };
    window.addEventListener('estoque-header-action', handleAction);
    return () => window.removeEventListener('estoque-header-action', handleAction);
  }, []);

  const queryClient = useQueryClient();
  const confirm = useConfirm();

  // Mantem a aba de estoque sincronizada entre operadores em tempo real.
  useEffect(() => {
    const channel = supabase
      .channel('estoque-tab-produtos-realtime')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'produtos' },
        () => {
          queryClient.invalidateQueries({ queryKey: ['produtos-paginated'] });
          queryClient.invalidateQueries({ queryKey: ['produtos-atencao-count'] });
          queryClient.invalidateQueries({ queryKey: ['categorias-produtos'] });
          queryClient.invalidateQueries({ queryKey: ['fabricantes-produtos'] });
          queryClient.invalidateQueries({ queryKey: ['fabricantes-e-map'] });
          queryClient.invalidateQueries({ queryKey: ['produtos'] });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [queryClient]);

  // 1. Categories Query (Distinct)
  const { data: categorias = [] } = useQuery({
    queryKey: ['categorias-produtos'],
    queryFn: async () => {
      const { data, error } = await supabase.from('produtos').select('categoria').not('categoria', 'is', null);
      if (error) throw error;
      const cats = [...new Set(data?.map(p => p.categoria))].filter(Boolean).sort();
      return cats;
    },
    staleTime: 1000 * 60 * 5 // Cache for 5 mins
  });

  const { data: fabricantesInfo = { items: [], fornecedoresById: {} } } = useQuery({
    queryKey: ['fabricantes-e-map'],
    queryFn: async () => {
      const { data: produtos, error } = await supabase
        .from('produtos')
        .select('fornecedor_id, fornecedor_nome');

      if (error) throw error;

      const idsFornecedor = [...new Set(
        (produtos || [])
          .map((produto) => produto.fornecedor_id)
          .filter(Boolean)
      )];

      let fornecedoresById = {};
      if (idsFornecedor.length > 0) {
        try {
          const { data: fornecedores, error: fornecedoresError } = await supabase
            .from('fornecedores')
            .select('id, nome_empresa')
            .in('id', idsFornecedor);

          if (!fornecedoresError && fornecedores) {
            fornecedoresById = fornecedores.reduce((acc, fornecedor) => {
              const id = String(fornecedor.id || '');
              const nome = String(fornecedor.nome_empresa || '').trim();
              if (id && nome) acc[id] = nome;
              return acc;
            }, {});
          }
        } catch (_) {
          // Falha silenciosa: usa apenas fornecedor_nome texto como fallback
        }
      }

      const items = [...new Set(
        (produtos || [])
          .map((produto) => {
            const id = String(produto.fornecedor_id || '');
            const nomeDoId = id ? fornecedoresById[id] : '';
            return (nomeDoId || produto.fornecedor_nome || '').trim();
          })
          .filter(Boolean)
      )].sort((a, b) => a.localeCompare(b, 'pt-BR', { sensitivity: 'base' }));

      return { items, fornecedoresById };
    },
    staleTime: 1000 * 60 * 5
  });

  const fabricantes = fabricantesInfo.items || [];
  const fornecedoresById = fabricantesInfo.fornecedoresById || {};

  // 2. Attention Count Query
  // Note: This matches the filter logic used in the main query
  const { data: produtosComAtencao = 0 } = useQuery({
    queryKey: ['produtos-atencao-count'],
    queryFn: async () => {
      const { count, error } = await supabase
        .from('produtos')
        .select('*', { count: 'exact', head: true })
        .eq('requer_atencao', true);
      if (error) throw error;
      return count || 0;
    }
  });

  // 3. Main Infinite Query
  const {
    data,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
    isLoading,
    isError,
    error
  } = useInfiniteQuery({
    queryKey: ['produtos-paginated', debouncedSearch, selectedCategoria, filtroAtencao, selectedFabricante],
    queryFn: async ({ pageParam = 1 }) => {
      const filters = {};

      if (selectedCategoria !== 'todas') filters.categoria = selectedCategoria;
      if (filtroAtencao) filters.requer_atencao = 'true'; // converted to string due to object entry
      // Filtro de fabricante no servidor — evita o problema de paginação client-side
      // que deixava produtos de fornecedores alfabeticamente tardios (TOZZETO etc.) fora da tela
      if (selectedFabricante !== 'todos') filters.fornecedor_nome = selectedFabricante;

      return await base44.entities.Produto.search({
        page: pageParam,
        limit: 100,
        filters,
        search: debouncedSearch,
        orderBy: 'nome'
      });
    },
    getNextPageParam: (lastPage, allPages) => {
      // lastPage is { data, count }
      const currentCount = allPages.flatMap(p => p.data).length;
      if (currentCount < lastPage.count) {
        return allPages.length + 1;
      }
      return undefined;
    },
    keepPreviousData: true
  });

  const deleteMutation = useMutation({
    mutationFn: (id) => base44.entities.Produto.delete(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['produtos-paginated'] });
      queryClient.invalidateQueries({ queryKey: ['produtos-atencao-count'] });
      toast.success("Produto excluido com sucesso");
    }
  });

  const { can } = useAuth();
  const isAdmin = user?.cargo === 'Administrador';
  const isManager = user?.cargo === 'Gerente';
  const isWarehouse = user?.cargo === 'Estoque';
  const isGerenteGeral = user?.cargo === 'Gerente Geral';
  const canEdit = isAdmin || isManager || isWarehouse || isGerenteGeral || can('manage_estoque');

  // Flatten pages to get all loaded products
  const flatProdutos = useMemo(
    () => data?.pages.flatMap(page => page.data) || [],
    [data]
  );
  const { produtosExibidos, isFuzzy } = useMemo(() => {
    let lista = [...flatProdutos];

    if (selectedFabricante !== 'todos') {
      lista = lista.filter((produto) => {
        const idFornecedor = String(produto.fornecedor_id || '');
        const fabricantePorId = idFornecedor ? fornecedoresById[idFornecedor] : '';
        const fabricante = (fabricantePorId || produto.fornecedor_nome || produto.marca || '').trim();
        return fabricante === selectedFabricante;
      });
    }

    // Quando há busca ativa, pontua os resultados do servidor por relevância
    if (debouncedSearch) {
      const termos = normSearch(debouncedSearch).split(/\s+/).filter(Boolean);
      if (termos.length > 0) {
        const scored = lista.map(p => {
          const texto = [p.nome, p.modelo_referencia, p.categoria, p.codigo_barras, p.sku, p.fornecedor_nome, p.cor]
            .filter(Boolean).map(normSearch).join(' ');
          const matches = termos.filter(t => texto.includes(t)).length;
          return { p, score: matches };
        });
        const exact = scored.filter(({ score }) => score === termos.length);
        const partials = scored.filter(({ score }) => score > 0 && score < termos.length);
        const fuzzy = exact.length === 0 && partials.length > 0;
        if (fuzzy) {
          return {
            produtosExibidos: partials.sort((a, b) => b.score - a.score).map(({ p }) => p),
            isFuzzy: true,
          };
        }
        lista = exact.map(({ p }) => p);
      }
    }

    switch (selectedOrdenacao) {
      case 'quantidade':
        lista.sort((a, b) => {
          const aQtd = a.quantidade_estoque || 0;
          const bQtd = b.quantidade_estoque || 0;
          return selectedDirecao === 'asc' ? aQtd - bQtd : bQtd - aQtd;
        });
        break;
      case 'preco':
        lista.sort((a, b) => {
          const aPreco = a.preco_venda || 0;
          const bPreco = b.preco_venda || 0;
          return selectedDirecao === 'asc' ? aPreco - bPreco : bPreco - aPreco;
        });
        break;
      case 'alfabetica':
      default:
        lista.sort((a, b) => {
          const comparacao = (a.nome || '').localeCompare((b.nome || ''), 'pt-BR', { sensitivity: 'base' });
          return selectedDirecao === 'asc' ? comparacao : comparacao * -1;
        });
        break;
    }

    return { produtosExibidos: lista, isFuzzy: false };
  }, [flatProdutos, fornecedoresById, debouncedSearch, selectedFabricante, selectedOrdenacao, selectedDirecao]);
  const totalCount = data?.pages[0]?.count || 0;

  const handleDelete = async (id) => {
    const confirmed = await confirm({
      title: "Excluir Produto",
      message: "Tem certeza que deseja excluir este produto?",
      confirmText: "Excluir",
      variant: "destructive"
    });
    if (confirmed) {
      deleteMutation.mutate(id);
    }
  };

  const handleQuickStockSave = async (produto, campo, novoValor) => {
    try {
      // Optimistic update
      const updateData = (old) => {
        if (!old) return old;
        return {
          ...old,
          pages: old.pages.map(page => ({
            ...page,
            data: page.data.map(p => p.id === produto.id ? { ...p, [campo]: novoValor } : p)
          }))
        };
      };
      queryClient.setQueryData(['produtos-paginated', debouncedSearch, selectedCategoria, filtroAtencao, selectedFabricante], updateData);
      
      await base44.entities.Produto.update(produto.id, { [campo]: novoValor });
      queryClient.invalidateQueries({ queryKey: ['produtos-paginated'] });
      queryClient.invalidateQueries({ queryKey: ['produtos'] });
      toast.success("Estoque atualizado!");
    } catch (error) {
      toast.error("Erro ao atualizar estoque: " + error.message);
    }
  };

  const handleOpenProdutoEditor = (produto, nextFocusField = null) => {
    if (!produto) {
      setCadastroProduto(null);
      setFocusField(null);
      setIsCadastroModalOpen(true);
      return;
    }

    // Quando o clique vier do indicador de incompletude, mantemos o cadastro completo
    // para permitir corrigir todos os campos de produto.
    if (nextFocusField) {
      setCadastroProduto(produto);
      setFocusField(nextFocusField);
      setIsCadastroModalOpen(true);
      return;
    }

    // Fluxo principal da aba de estoque: conferencia + ajuste rapido.
    setEditingProduto(produto);
    setIsConferenciaModalOpen(true);
  };

  return (
    <div className="space-y-4">
      {/* Filters */}
      <div className="bg-white dark:bg-neutral-900 rounded-xl shadow-sm border border-gray-100 dark:border-neutral-800">
        <div className="p-4 border-b border-gray-100 dark:border-neutral-800 space-y-3">
          {/* Linha 1: Campo de busca full-width */}
          <div className="relative w-full">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
            <Input
              placeholder="Buscar por palavras-chave: nome, cor, material, categoria, ambiente..."
              className="pl-10 h-11 text-base border-gray-200 dark:border-neutral-700"
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>
          {/* Linha 2: Filtros e ações */}
          <div className="flex flex-wrap items-center gap-3">
              <Select value={selectedCategoria} onValueChange={setSelectedCategoria}>
                <SelectTrigger className="w-48 border-gray-200 dark:border-neutral-700">
                  <SelectValue placeholder="Filtrar por categoria" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="todas">Todas as Categorias</SelectItem>
                  {categorias.map(cat => (
                    <SelectItem key={cat} value={cat}>{cat}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Select value={selectedFabricante} onValueChange={setSelectedFabricante}>
                <SelectTrigger className="w-48 border-gray-200 dark:border-neutral-700">
                  <SelectValue placeholder="Filtrar por fabricante" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="todos">Todos os Fabricantes</SelectItem>
                  {fabricantes.map(fabricante => (
                    <SelectItem key={fabricante} value={fabricante}>{fabricante}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Select value={selectedOrdenacao} onValueChange={setSelectedOrdenacao}>
                <SelectTrigger className="w-48 border-gray-200 dark:border-neutral-700">
                  <SelectValue placeholder="Ordenar por" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="alfabetica">Ordem alfabetica (A-Z)</SelectItem>
                  <SelectItem value="quantidade">Quantidade</SelectItem>
                  <SelectItem value="preco">Preço</SelectItem>
                </SelectContent>
              </Select>
              <Select value={selectedDirecao} onValueChange={setSelectedDirecao}>
                <SelectTrigger className="w-44 border-gray-200 dark:border-neutral-700">
                  <SelectValue placeholder="Direcao" />
                </SelectTrigger>
                <SelectContent>
                  {selectedOrdenacao === 'alfabetica' ? (
                    <>
                      <SelectItem value="asc">A-Z</SelectItem>
                      <SelectItem value="desc">Z-A</SelectItem>
                    </>
                  ) : (
                    <>
                      <SelectItem value="desc">Maior para menor</SelectItem>
                      <SelectItem value="asc">Menor para maior</SelectItem>
                    </>
                  )}
                </SelectContent>
              </Select>
              {produtosComAtencao > 0 && (
                <Button
                  variant={filtroAtencao ? "default" : "outline"}
                  size="sm"
                  onClick={() => setFiltroAtencao(!filtroAtencao)}
                  className={filtroAtencao ? "bg-yellow-600 hover:bg-yellow-700" : "border-yellow-400 text-yellow-700 hover:bg-yellow-50"}
                >
                  <AlertCircle className="w-4 h-4 mr-1" />
                  Requer Atencao
                  <Badge variant="secondary" className="ml-2 bg-yellow-100 text-yellow-800">{produtosComAtencao}</Badge>
                </Button>
              )}
              {canEdit && (
                <>
                  <Button
                    onClick={() => { setProdutosParaEtiqueta([]); setIsGeradorEtiquetasOpen(true); }}
                    variant="outline"
                    className="border-green-200 text-green-700 hover:bg-green-50"
                  >
                    <Printer className="w-4 h-4 mr-2" />
                    Gerar Etiquetas
                  </Button>
                  <Button
                    onClick={() => handleOpenProdutoEditor(null)}
                    className="bg-green-700 hover:bg-green-800"
                  >
                    <Plus className="w-4 h-4 mr-2" />
                    Novo Produto
                  </Button>
                </>
              )}
            </div>
        </div>

        {/* Table */}
        <Table>
          <TableHeader className="bg-gray-50 dark:bg-neutral-950">
            <TableRow>
              <TableHead className="w-[300px]">Produto</TableHead>
              <TableHead>Categoria</TableHead>
              <TableHead className="text-center">Estoque</TableHead>
              <TableHead className="text-right">Preco</TableHead>
              <TableHead className="w-[50px]"></TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {isLoading && produtosExibidos.length === 0 ? (
              <TableRow>
                <TableCell colSpan={5} className="text-center py-16">
                  <div className="flex flex-col items-center gap-3">
                    <Loader2 className="w-8 h-8 animate-spin text-green-600" />
                    <p className="text-gray-500">Carregando estoque...</p>
                  </div>
                </TableCell>
              </TableRow>
            ) : produtosExibidos.length === 0 ? (
              <TableRow>
                <TableCell colSpan={5} className="text-center py-16">
                  <div className="flex flex-col items-center gap-4">
                    <div className="w-16 h-16 rounded-full bg-gray-100 dark:bg-neutral-800 flex items-center justify-center">
                      <PackageOpen className="w-8 h-8 text-gray-400" />
                    </div>
                    <div>
                      <p className="font-medium text-gray-900 dark:text-white mb-1">
                        {searchTerm ? "Nenhum produto encontrado" : "Estoque vazio"}
                      </p>
                      <p className="text-sm text-gray-500">
                        {searchTerm ? `Nenhum resultado para "${searchTerm}"` : "Comece adicionando seu primeiro produto"}
                      </p>
                    </div>
                    {!searchTerm && canEdit && (
                      <Button
                        onClick={() => handleOpenProdutoEditor(null)}
                        className="mt-2 bg-green-600 hover:bg-green-700"
                      >
                        <Plus className="w-4 h-4 mr-2" />
                        Adicionar Produto
                      </Button>
                    )}
                  </div>
                </TableCell>
              </TableRow>
            ) : (
              produtosExibidos.map(produto => {
                const quantidadeAtual = lojasComCd.reduce((acc, loja) => acc + Number(produto[obterCampoEstoqueDaLoja(loja)] || 0), 0);
                const estoqueMinimo = Number(produto.estoque_minimo || 0);
                const isOutOfStock = quantidadeAtual === 0;
                const isLowStock = quantidadeAtual > 0 && estoqueMinimo > 0 && quantidadeAtual <= estoqueMinimo;

                return (
                  <TableRow key={produto.id} className="hover:bg-gray-50 dark:hover:bg-neutral-800/50">
                    <TableCell>
                      <div className="flex items-center gap-3">
                        {produto.fotos?.[0] && (
                          <img
                            src={produto.fotos[0]}
                            alt={produto.nome}
                            className="w-10 h-10 rounded object-cover border"
                          />
                        )}
                        <div>
                          <div className="flex items-center gap-2">
                            <p className="font-medium text-gray-900 dark:text-white">
                              {produto.nome}{produto.modelo_referencia ? ` ${produto.modelo_referencia}` : ''}
                            </p>
                            <ProductIncompleteIndicator
                              produto={produto}
                              canEdit={canEdit}
                              onSelectMissing={(missingItem) => handleOpenProdutoEditor(produto, missingItem.focusField)}
                            />
                          </div>
                          <div className="flex items-center gap-2 text-xs text-gray-500 flex-wrap">
                            {produto.codigo_barras && <span>COD: {produto.codigo_barras}</span>}
                            {!produto.ativo && <Badge variant="outline" className="text-red-600 border-red-200">Inativo</Badge>}
                            {produto.requer_atencao && (
                              <div className="flex flex-wrap gap-1">
                                {!produto.preco_venda && (
                                  <Badge variant="outline" className="text-yellow-600 border-yellow-300 bg-yellow-50 text-[10px]">
                                    Sem preco
                                  </Badge>
                                )}
                                {!produto.fotos?.length && (
                                  <Badge variant="outline" className="text-yellow-600 border-yellow-300 bg-yellow-50 text-[10px]">
                                    Sem foto
                                  </Badge>
                                )}
                                {!produto.ncm && (
                                  <Badge variant="outline" className="text-yellow-600 border-yellow-300 bg-yellow-50 text-[10px]">
                                    Sem NCM
                                  </Badge>
                                )}
                                {!produto.categoria && (
                                  <Badge variant="outline" className="text-yellow-600 border-yellow-300 bg-yellow-50 text-[10px]">
                                    Sem categoria
                                  </Badge>
                                )}
                                {produto.origem_nfe && (
                                  <Badge variant="outline" className="text-blue-600 border-blue-200 text-[10px]">
                                    Importado NFe
                                  </Badge>
                                )}
                              </div>
                            )}
                            {produto.origem_nfe && !produto.requer_atencao && (
                              <Badge variant="outline" className="text-blue-600 border-blue-200">NFe</Badge>
                            )}
                          </div>

                          {/* Detalhes do Produto (Dimensões, Material, Cor, Tamanho) */}
                          <div className="flex flex-wrap gap-1 mt-1">
                            <span className="text-[10px] px-1.5 py-0.5 rounded bg-amber-50 text-amber-700 border border-amber-100 flex items-center" title="Dimensões (LxAxP)">
                              <Ruler className="w-3 h-3 mr-1 opacity-50" />
                              {(produto.largura || produto.altura || produto.profundidade)
                                ? `${produto.largura || '?'}x${produto.altura || '?'}x${produto.profundidade || '?'}`
                                : 'Dim: N/A'}
                            </span>
                            <span className="text-[10px] px-1.5 py-0.5 rounded bg-blue-50 text-blue-700 border border-blue-100 flex items-center" title="Material">
                              <Layers className="w-3 h-3 mr-1 opacity-50" /> {produto.material || 'Mat: N/A'}
                            </span>
                            {produto.cor && (
                              <span className="text-[10px] px-1.5 py-0.5 rounded bg-gray-50 text-gray-700 border border-gray-100 flex items-center gap-1" title="Cor">
                                <div className="w-2 h-2 rounded-full border border-gray-300" style={{ background: getColorHex(produto.cor) }} />
                                {produto.cor}
                              </span>
                            )}
                            {produto.tamanho && (
                              <span className="text-[10px] px-1.5 py-0.5 rounded bg-gray-50 text-gray-700 border border-gray-100 flex items-center gap-1" title="Tamanho">
                                <Ruler className="w-3 h-3 mr-1 opacity-50" />
                                {produto.tamanho}
                              </span>
                            )}
                          </div>
                        </div>
                      </div>
                    </TableCell>
                    <TableCell>
                      <Badge variant="secondary" className="font-normal bg-gray-100 dark:bg-neutral-800 text-gray-600 dark:text-gray-400">
                        {produto.categoria}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-center align-top pt-4">
                      <div className="flex flex-col gap-2 w-full max-w-[140px] mx-auto">
                        <div className="flex justify-between items-center bg-gray-50 dark:bg-neutral-800/50 p-1.5 rounded-md border border-gray-100 dark:border-neutral-800">
                          <span className="text-xs font-semibold text-gray-500 dark:text-gray-400">TOTAL</span>
                          <div className="flex items-center gap-1.5">
                            <span className={`font-bold text-sm ${(isLowStock || isOutOfStock) ? 'text-red-600' : 'text-gray-900 dark:text-white'}`}>
                              {quantidadeAtual}
                            </span>
                            {isOutOfStock ? (
                              <Badge variant="destructive" className="h-4 px-1 text-[9px] leading-none">Zerado</Badge>
                            ) : isLowStock && (
                              <Badge variant="destructive" className="h-4 px-1 text-[9px] leading-none">Baixo</Badge>
                            )}
                          </div>
                        </div>
                        
                        <div className="flex flex-col gap-1.5">
                          {lojasComCd.map(loja => {
                            const campo = obterCampoEstoqueDaLoja(loja);
                            const qtd = Number(produto[campo] || 0);
                            const sigla = loja.nome === "Depósito / CD" ? "CD" : 
                                          loja.nome === "Centro" ? "Centro" :
                                          loja.nome === "Ponte Branca" ? "P.Branca" :
                                          loja.nome === "Mega Store" ? "Mega" :
                                          loja.nome.substring(0, 8);
                            return (
                              <div key={loja.id} className="flex justify-between items-center text-xs px-1 hover:bg-gray-50/50 dark:hover:bg-neutral-800/30 rounded">
                                <span className="text-gray-500 dark:text-gray-400" title={loja.nome}>{sigla}:</span>
                                <EditableStockCell 
                                  produto={produto}
                                  campo={campo}
                                  valorOriginal={qtd}
                                  onSave={handleQuickStockSave}
                                  canEdit={canEdit}
                                />
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    </TableCell>
                    <TableCell className="text-right font-medium text-gray-900 dark:text-white">
                      R$ {produto.preco_venda?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                    </TableCell>
                    <TableCell>
                      {canEdit && (
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" className="h-8 w-8 p-0">
                              <MoreHorizontal className="h-4 w-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem onClick={() => { setProdutosParaEtiqueta([produto]); setIsGeradorEtiquetasOpen(true); }}>
                              <Printer className="mr-2 h-4 w-4" /> Imprimir Etiqueta
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => { setMovingProduto(produto); setIsMoveModalOpen(true); }}>
                              <ArrowRightLeft className="mr-2 h-4 w-4 text-blue-600" /> Movimentar
                            </DropdownMenuItem>
                            <DropdownMenuSeparator />
                            <DropdownMenuItem onClick={() => handleOpenProdutoEditor(produto)}>
                              <Edit className="mr-2 h-4 w-4" /> Editar
                            </DropdownMenuItem>
                            <DropdownMenuItem className="text-red-600" onClick={() => handleDelete(produto.id)}>
                              <Trash2 className="mr-2 h-4 w-4" /> Excluir
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      )}
                    </TableCell>
                  </TableRow>
                );
              })
            )}
          </TableBody>
        </Table>
      </div>

      {/* Load More Trigger */}
      {hasNextPage && (
        <div className="flex justify-center py-6">
          <Button
            onClick={() => fetchNextPage()}
            disabled={isFetchingNextPage}
            variant="outline"
            className="w-full sm:w-auto min-w-[200px]"
          >
            {isFetchingNextPage ? (
              <>
                <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                Carregando mais...
              </>
            ) : (
              <span className="flex items-center gap-2">
                {`Carregar mais (Visualizando ${produtosExibidos.length} de ${totalCount})`}
                {isFuzzy && <span className="text-[10px] px-1.5 py-0.5 rounded bg-amber-100 text-amber-700 font-medium">resultado mais próximo</span>}
              </span>
            )}
          </Button>
        </div>
      )}

      <ProdutoConferenciaModal
        isOpen={isConferenciaModalOpen}
        onClose={() => {
          setIsConferenciaModalOpen(false);
          setEditingProduto(null);
        }}
        produto={editingProduto}
        onSave={async (data) => {
          try {
            if (!editingProduto?.id) return;
            await base44.entities.Produto.update(editingProduto.id, data);
            queryClient.invalidateQueries({ queryKey: ['produtos-paginated'] });
            queryClient.invalidateQueries({ queryKey: ['produtos'] });
            queryClient.invalidateQueries({ queryKey: ['produtos-atencao-count'] });
          } catch (error) {
            console.error("Erro ao salvar conferencia de estoque:", error);
            throw error;
          }
        }}
      />

      <ProdutoCadastroCompleto
        isOpen={isCadastroModalOpen}
        onClose={() => {
          setIsCadastroModalOpen(false);
          setCadastroProduto(null);
          setFocusField(null);
        }}
        produto={cadastroProduto}
        focusField={focusField}
        onSave={async (data) => {
          try {
            if (cadastroProduto) {
              await base44.entities.Produto.update(cadastroProduto.id, data);
              toast.success("Produto atualizado com sucesso");
            } else {
              await base44.entities.Produto.create(data);
              toast.success("Produto criado com sucesso");
            }
            queryClient.invalidateQueries({ queryKey: ['produtos-paginated'] });
            queryClient.invalidateQueries({ queryKey: ['produtos-atencao-count'] });
            queryClient.invalidateQueries({ queryKey: ['categorias-produtos'] }); // Update categories too
            queryClient.invalidateQueries({ queryKey: ['fabricantes-produtos'] });
            queryClient.invalidateQueries({ queryKey: ['fabricantes-produtos-v2'] });
            queryClient.invalidateQueries({ queryKey: ['fabricantes-e-map'] });
            queryClient.invalidateQueries({ queryKey: ['produtos'] });
            setIsCadastroModalOpen(false);
            setCadastroProduto(null);
            setFocusField(null);
          } catch (error) {
            console.error("Erro ao salvar produto:", error);
            toast.error("Erro ao salvar produto: " + error.message);
          }
        }}
      />

      <MovimentacaoModal
        isOpen={isMoveModalOpen}
        onClose={() => setIsMoveModalOpen(false)}
        produto={movingProduto}
      />

      <GeradorEtiquetasModal
        isOpen={isGeradorEtiquetasOpen}
        onClose={() => setIsGeradorEtiquetasOpen(false)}
        produtosPreSelecionados={produtosParaEtiqueta}
        user={user}
      />
    </div>
  );
}

import React, { forwardRef } from 'react';
import { EMPRESA } from "@/config/empresa";

// O componente de EtiquetaImpressao
// Ref é usado pelo react-to-print para capturar o nó DOM que será impresso
const LAYOUT_CONFIGS = {
    "1/4": {
        pageSize: 'A4 portrait',
        gridClass: 'grid-cols-2',
        width: '105mm',
        height: '148.5mm',
        padding: '10mm',
        logoMaxHeight: 'max-h-16',
        logoMaxWidth: 'max-w-[200px]',
        companyNameSize: 'text-lg',
        productNameSize: 'text-xl',
        detailsSize: 'text-lg',
        detailsLabelSize: 'text-base',
        priceBoxMinHeight: 'min-h-[70px]',
        priceLabelSize: 'text-xl',
        priceSize: 'text-4xl',
        priceNormalSize: 'text-lg',
        headerMargin: 'mb-6 mt-4',
        productNameMargin: 'mb-3',
        detailsMargin: 'mb-3',
    },
    "1/6": {
        pageSize: 'A4 landscape',
        gridClass: 'grid-cols-3',
        width: '85mm',
        height: '105mm',
        padding: '6mm',
        logoMaxHeight: 'max-h-11',
        logoMaxWidth: 'max-w-[150px]',
        companyNameSize: 'text-sm',
        productNameSize: 'text-base',
        detailsSize: 'text-sm',
        detailsLabelSize: 'text-xs',
        priceBoxMinHeight: 'min-h-[50px]',
        priceLabelSize: 'text-sm',
        priceSize: 'text-2xl',
        priceNormalSize: 'text-xs',
        headerMargin: 'mb-2 mt-1',
        productNameMargin: 'mb-1.5',
        detailsMargin: 'mb-1.5',
    },
    "1/2": {
        pageSize: 'A4 portrait',
        gridClass: 'grid-cols-1',
        width: '210mm',
        height: '148.5mm',
        padding: '12mm',
        logoMaxHeight: 'max-h-20',
        logoMaxWidth: 'max-w-[250px]',
        companyNameSize: 'text-xl',
        productNameSize: 'text-2xl',
        detailsSize: 'text-xl',
        detailsLabelSize: 'text-lg',
        priceBoxMinHeight: 'min-h-[80px]',
        priceLabelSize: 'text-2xl',
        priceSize: 'text-5xl',
        priceNormalSize: 'text-xl',
        headerMargin: 'mb-6 mt-4',
        productNameMargin: 'mb-4',
        detailsMargin: 'mb-4',
    },
    "inteira": {
        pageSize: 'A4 portrait',
        gridClass: 'grid-cols-1',
        width: '210mm',
        height: '297mm',
        padding: '20mm',
        logoMaxHeight: 'max-h-32',
        logoMaxWidth: 'max-w-[350px]',
        companyNameSize: 'text-3xl',
        productNameSize: 'text-4xl',
        detailsSize: 'text-2xl',
        detailsLabelSize: 'text-xl',
        priceBoxMinHeight: 'min-h-[120px]',
        priceLabelSize: 'text-3xl',
        priceSize: 'text-7xl',
        priceNormalSize: 'text-2xl',
        headerMargin: 'mb-12 mt-8',
        productNameMargin: 'mb-8',
        detailsMargin: 'mb-8',
    }
};

export const EtiquetaImpressao = forwardRef(({ empresa, produtos, logoOption = 'default', logoCustomizadaUrl = '', layout = '1/4' }, ref) => {
    // Carregar configuração de tamanho base
    const currentLayout = LAYOUT_CONFIGS[layout] || LAYOUT_CONFIGS["1/4"];

    // Determinar o logo de acordo com a opção configurada
    let logoUrl = null;
    if (logoOption === 'default') {
        logoUrl = empresa?.logo_url || EMPRESA.logo_url;
    } else if (logoOption === 'custom') {
        logoUrl = logoCustomizadaUrl;
    }

    const showFallbackBox = logoOption !== 'none' && !logoUrl;
    const nomeEmpresa = empresa?.name || EMPRESA.nome;
    const isA5 = layout === "1/2";

    return (
        <div ref={ref} className="bg-white p-4 print:p-0">
            <style type="text/css" media="print">
                {`
          @page {
            size: ${currentLayout.pageSize};
            margin: 0;
          }
          body {
            margin: 0;
            padding: 0;
            background-color: white;
          }
          .etiqueta-container {
            break-inside: avoid;
            page-break-inside: avoid;
          }
          @media print {
            .no-print {
              display: none !important;
            }
          }
        `}
            </style>

            {/* Grid container dinâmico para organizar as etiquetas na página A4 */}
            <div className={`grid ${currentLayout.gridClass} gap-x-2 gap-y-2 print:gap-x-0 print:gap-y-0 pb-10 print:pb-0 justify-items-center`}>
                {produtos.map((produto, index) => (
                    <div
                        key={`${produto.id}-${index}`}
                        className="etiqueta-container relative bg-white border border-gray-300 print:border-none overflow-hidden font-sans"
                        style={{
                            width: currentLayout.width,
                            height: currentLayout.height,
                            background: 'linear-gradient(160deg, #1f1f1f 40%, #2b2b2b 60%, #4caf50 100%)',
                            padding: currentLayout.padding,
                            display: 'flex',
                            flexDirection: 'column',
                            boxSizing: 'border-box',
                        }}
                    >
                        {/* Header com Logo e Nome da Empresa */}
                        <div className={`flex flex-col items-center justify-center ${currentLayout.headerMargin}`}>
                            {logoUrl && (
                                <img
                                    src={logoUrl}
                                    alt={nomeEmpresa}
                                    className={`${currentLayout.logoMaxHeight} ${currentLayout.logoMaxWidth} object-contain mb-2 shadow-sm`}
                                />
                            )}
                            {showFallbackBox && (
                                <div className={`${layout === 'inteira' ? 'h-24 w-24' : layout === '1/6' ? 'h-10 w-10' : 'h-16 w-16'} bg-white/20 rounded mb-2 flex items-center justify-center`}>
                                    <span className={`text-white font-bold ${layout === 'inteira' ? 'text-3xl' : layout === '1/6' ? 'text-sm' : 'text-xl'}`}>
                                        {nomeEmpresa.charAt(0)}
                                    </span>
                                </div>
                            )}
                            <h1 className={`text-white font-bold uppercase tracking-widest text-center ${currentLayout.companyNameSize}`}>
                                {nomeEmpresa}
                            </h1>
                        </div>

                        {/* Nome do Produto em Destaque Branca arredondada */}
                        <div className={`bg-white rounded-xl py-2 px-3 ${currentLayout.productNameMargin} shadow-sm w-full border border-gray-200`}>
                            <h2 className={`${currentLayout.productNameSize} font-bold text-gray-800 text-center uppercase break-words leading-tight`}>
                                {produto.nome} {produto.modelo_referencia ? ` ${produto.modelo_referencia}` : ''}
                            </h2>
                        </div>

                        {isA5 ? (
                            /* Layout especial lado a lado para 1/2 Folha */
                            <div className="flex gap-4 flex-grow min-h-0">
                                {/* Detalhes (60%) */}
                                <div className="bg-white rounded-xl py-3 px-4 shadow-sm border border-gray-200 flex-[1.5] flex flex-col justify-center min-w-0">
                                    <div className="space-y-1 overflow-hidden">
                                        {produto.sku ? (
                                            <p className={`${currentLayout.detailsSize} font-medium text-gray-700 uppercase leading-snug truncate`}>
                                                SKU: {produto.sku}
                                            </p>
                                        ) : produto.codigo_barras ? null : (
                                            <p className={`${currentLayout.detailsSize} font-medium text-gray-700 uppercase leading-snug truncate`}>
                                                COD: {produto.id?.substring(0, 8)}
                                            </p>
                                        )}
                                        {produto.codigo_barras && (
                                            <p className={`${currentLayout.detailsSize} font-medium text-gray-700 uppercase leading-snug truncate`}>
                                                EAN: {produto.codigo_barras}
                                            </p>
                                        )}
                                        <p className={`${currentLayout.detailsSize} font-medium text-gray-700 uppercase leading-snug truncate`}>
                                            COR: {produto.cor || 'A CONSULTAR'}
                                        </p>
                                        {(produto.largura || produto.altura || produto.profundidade) && (
                                            <p className={`${currentLayout.detailsLabelSize} font-medium text-gray-600 uppercase leading-snug truncate`}>
                                                MEDIDAS: {produto.largura || '?'}x{produto.altura || '?'}x{produto.profundidade || '?'} CM
                                            </p>
                                        )}
                                        <p className="text-sm font-medium text-gray-400 uppercase leading-snug text-right mt-auto">
                                            {produto.origem_nfe ? 'NFE / ' : ''}
                                        </p>
                                    </div>
                                </div>
                                {/* Preço (40%) */}
                                <div className="bg-white rounded-xl py-3 px-4 shadow-sm border border-gray-200 flex-1 flex items-center justify-center relative min-w-0">
                                    {produto.preco_promocional && produto.preco_promocional > 0 && produto.preco_promocional < produto.preco_venda ? (
                                        <div className="flex flex-col items-center w-full min-w-0">
                                            <div className="text-gray-400 font-bold text-sm line-through truncate">
                                                R$ {produto.preco_venda?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                                            </div>
                                            <div className="flex items-baseline gap-1 min-w-0">
                                                <span className="text-gray-900 font-bold text-base">R$</span>
                                                <span className="text-gray-900 font-black text-3xl tracking-tight leading-none truncate">
                                                    {produto.preco_promocional?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                                                </span>
                                            </div>
                                        </div>
                                    ) : (
                                        <div className="flex items-baseline gap-1 min-w-0">
                                            <span className="text-gray-900 font-bold text-base">R$</span>
                                            <span className="text-gray-900 font-black text-3xl tracking-tight leading-none truncate">
                                                {produto.preco_venda?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                                            </span>
                                        </div>
                                    )}
                                </div>
                            </div>
                        ) : (
                            /* Layout padrão empilhado para 1/4, 1/6, inteira */
                            <>
                                {/* Detalhes do Produto */}
                                <div className={`bg-white rounded-xl py-2 px-4 ${currentLayout.detailsMargin} shadow-sm w-full border border-gray-200 flex-grow flex flex-col justify-center min-h-0`}>
                                    <div className="space-y-1">
                                        {produto.sku ? (
                                            <p className={`${currentLayout.detailsSize} font-medium text-gray-700 uppercase leading-snug truncate`}>
                                                SKU: {produto.sku}
                                            </p>
                                        ) : produto.codigo_barras ? null : (
                                            <p className={`${currentLayout.detailsSize} font-medium text-gray-700 uppercase leading-snug truncate`}>
                                                COD: {produto.id?.substring(0, 8)}
                                            </p>
                                        )}
                                        {produto.codigo_barras && (
                                            <p className={`${currentLayout.detailsSize} font-medium text-gray-700 uppercase leading-snug truncate`}>
                                                EAN: {produto.codigo_barras}
                                            </p>
                                        )}
                                        <p className={`${currentLayout.detailsSize} font-medium text-gray-700 uppercase leading-snug truncate`}>
                                            COR: {produto.cor || 'A CONSULTAR'}
                                        </p>
                                        {(produto.largura || produto.altura || produto.profundidade) && (
                                            <p className={`${currentLayout.detailsLabelSize} font-medium text-gray-600 uppercase leading-snug truncate`}>
                                                MEDIDAS: {produto.largura || '?'}x{produto.altura || '?'}x{produto.profundidade || '?'} CM
                                            </p>
                                        )}
                                        <p className="text-xs font-medium text-gray-400 uppercase leading-snug text-right mt-auto">
                                            {produto.origem_nfe ? 'NFE / ' : ''}
                                        </p>
                                    </div>
                                </div>

                                {/* Preço */}
                                <div className={`bg-white rounded-xl py-2 px-4 shadow-sm w-full border border-gray-200 mt-auto flex items-center justify-center relative min-h-0 ${currentLayout.priceBoxMinHeight}`}>
                                    {produto.preco_promocional && produto.preco_promocional > 0 && produto.preco_promocional < produto.preco_venda ? (
                                        <div className="flex flex-col items-center w-full min-w-0">
                                            <div className={`${currentLayout.priceNormalSize} text-gray-400 font-bold line-through -mb-1 truncate`}>
                                                R$ {produto.preco_venda?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                                            </div>
                                            <div className="flex items-baseline gap-1 min-w-0">
                                                <span className={`${currentLayout.priceLabelSize} text-gray-900 font-bold`}>R$</span>
                                                <span className={`${currentLayout.priceSize} text-gray-900 font-black tracking-tight leading-none truncate`}>
                                                    {produto.preco_promocional?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                                                </span>
                                            </div>
                                        </div>
                                    ) : (
                                        <div className="flex items-baseline gap-1 min-w-0">
                                            <span className={`${currentLayout.priceLabelSize} text-gray-900 font-bold`}>R$</span>
                                            <span className={`${currentLayout.priceSize} text-gray-900 font-black tracking-tight leading-none truncate`}>
                                                {produto.preco_venda?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                                            </span>
                                        </div>
                                    )}
                                </div>
                            </>
                        )}

                    </div>
                ))}
            </div>
        </div>
    );
});

EtiquetaImpressao.displayName = 'EtiquetaImpressao';

export default EtiquetaImpressao;

import React, { useRef, useState } from "react";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription,
    DialogFooter
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { useReactToPrint } from "react-to-print";
import EtiquetaImpressao from "./EtiquetaImpressao";
import { Printer, Plus, Minus, Search, Trash2, ArrowRight, Loader2, Upload, Palette } from "lucide-react";
import { Input } from "@/components/ui/input";
import { base44 } from "@/api/base44Client";
import { toast } from "sonner";
import { ScrollArea } from "@/components/ui/scroll-area";
import { useTenant } from "@/contexts/TenantContext";
import { supabase } from "@/lib/supabase";
import { useQuery } from "@tanstack/react-query";
import BuscaProdutoAvancada from "../vendas/BuscaProdutoAvancada";

export default function GeradorEtiquetasModal({
    isOpen,
    onClose,
    produtosPreSelecionados = [],
    user
}) {
    const componentRef = useRef(null);
    const { organization, refreshTenant } = useTenant();

    // Lista de itens a serem impressos: { produto, quantidade }
    const [itensImpressao, setItensImpressao] = useState(
        produtosPreSelecionados.map(p => ({ produto: p, quantidade: 1 }))
    );

    const [layoutOption, setLayoutOption] = useState("1/4");
    const [logoOption, setLogoOption] = useState("default");
    const [logoCustomizadaUrl, setLogoCustomizadaUrl] = useState("");
    const [isSavingLogo, setIsSavingLogo] = useState(false);
    const [isUploading, setIsUploading] = useState(false);

    // Carregar configurações de logo
    React.useEffect(() => {
        if (!isOpen || !organization) return;

        const dbOption = organization.logo_etiqueta_option;
        const dbUrl = organization.logo_etiqueta_url;

        const localOption = localStorage.getItem(`etiqueta_logo_option_${organization.id}`);
        const localUrl = localStorage.getItem(`etiqueta_logo_url_${organization.id}`);

        if (dbOption) {
            setLogoOption(dbOption);
        } else if (localOption) {
            setLogoOption(localOption);
        } else {
            setLogoOption("default");
        }

        if (dbUrl) {
            setLogoCustomizadaUrl(dbUrl);
        } else if (localUrl) {
            setLogoCustomizadaUrl(localUrl);
        } else {
            setLogoCustomizadaUrl("");
        }
    }, [isOpen, organization]);

    const handleSaveLogoConfig = async (option, customUrl) => {
        if (!organization) return;
        setIsSavingLogo(true);
        try {
            const { error } = await supabase
                .from('organizations')
                .update({
                    logo_etiqueta_option: option,
                    logo_etiqueta_url: customUrl
                })
                .eq('id', organization.id);

            if (error) {
                // Fallback para localStorage
                localStorage.setItem(`etiqueta_logo_option_${organization.id}`, option);
                localStorage.setItem(`etiqueta_logo_url_${organization.id}`, customUrl);
            } else {
                if (refreshTenant) await refreshTenant();
            }
        } catch (err) {
            console.warn("Erro ao salvar no banco, usando localStorage:", err);
            localStorage.setItem(`etiqueta_logo_option_${organization.id}`, option);
            localStorage.setItem(`etiqueta_logo_url_${organization.id}`, customUrl);
        } finally {
            setIsSavingLogo(false);
        }
    };

    const handleLogoUpload = async (e) => {
        const file = e.target.files[0];
        if (!file) return;

        if (!file.type.startsWith('image/')) {
            toast.error('Selecione um arquivo de imagem válido (PNG, JPG).');
            return;
        }

        setIsUploading(true);
        try {
            const { file_url } = await base44.integrations.Core.UploadFile({ file });
            setLogoCustomizadaUrl(file_url);
            await handleSaveLogoConfig(logoOption, file_url);
            toast.success("Logo personalizada enviada com sucesso!");
        } catch (err) {
            toast.error("Erro ao enviar arquivo: " + err.message);
        } finally {
            setIsUploading(false);
        }
    };

    const handleRemoveCustomLogo = async () => {
        setLogoCustomizadaUrl("");
        await handleSaveLogoConfig(logoOption, "");
        toast.success("Logo personalizada removida.");
    };

    const { data: produtos = [] } = useQuery({
        queryKey: ['produtos'],
        queryFn: () => base44.entities.Produto.list()
    });

    const { data: fornecedores = [] } = useQuery({
        queryKey: ['fornecedores'],
        queryFn: () => base44.entities.Fornecedor.list()
    });

    // Atualizar quando a prop produtosPreSelecionados mudar e o modal abrir
    React.useEffect(() => {
        if (isOpen && produtosPreSelecionados.length > 0) {
            setItensImpressao(produtosPreSelecionados.map(p => ({ produto: p, quantidade: 1 })));
        } else if (isOpen && produtosPreSelecionados.length === 0) {
            setItensImpressao([]);
        }
    }, [isOpen, produtosPreSelecionados]);

    const adicionarProduto = (produto) => {
        setItensImpressao(prev => {
            const existe = prev.find(item => item.produto.id === produto.id);
            if (existe) {
                return prev.map(item =>
                    item.produto.id === produto.id
                        ? { ...item, quantidade: item.quantidade + 1 }
                        : item
                );
            }
            return [...prev, { produto, quantidade: 1 }];
        });
        toast.success(`${produto.nome} adicionado`);
    };

    const atualizarQuantidade = (id, delta) => {
        setItensImpressao(prev => prev.map(item => {
            if (item.produto.id === id) {
                const novaQtd = Math.max(1, item.quantidade + delta);
                return { ...item, quantidade: novaQtd };
            }
            return item;
        }));
    };

    const removerProduto = (id) => {
        setItensImpressao(prev => prev.filter(item => item.produto.id !== id));
    };

    // Gerar a array linear de produtos baseada nas quantidades
    const getProdutosParaImpressao = () => {
        const arr = [];
        itensImpressao.forEach(item => {
            for (let i = 0; i < item.quantidade; i++) {
                arr.push(item.produto);
            }
        });
        return arr;
    };

    const produtosImpressao = getProdutosParaImpressao();
    const totalEtiquetas = produtosImpressao.length;

    const handlePrint = useReactToPrint({
        contentRef: componentRef,
        documentTitle: "Etiquetas_Pedido",
        onAfterPrint: () => {
            toast.success("Impressão finalizada");
            onClose();
        }
    });

    return (
        <Dialog open={isOpen} onOpenChange={onClose}>
            <DialogContent className="max-w-4xl max-h-[90vh] flex flex-col p-0 overflow-hidden">
                <div className="p-6 pb-2 border-b">
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-2 text-xl">
                            <Printer className="w-5 h-5 text-gray-700" />
                            Gerador de Etiquetas
                        </DialogTitle>
                        <DialogDescription>
                            Adicione produtos à lista, defina o tamanho da folha e a quantidade desejada.
                        </DialogDescription>
                    </DialogHeader>
                </div>

                {/* Corpo do Modal: Split Screen (Controles vs Preview) */}
                <div className="flex-1 flex flex-col md:flex-row overflow-hidden bg-gray-50/50">

                    {/* Lado Esquerdo: Controles */}
                    <div className="w-full md:w-1/2 p-6 flex flex-col gap-6 border-r overflow-y-auto">

                        {/* Busca */}
                        <div className="space-y-3">
                            <h3 className="font-semibold text-sm text-gray-700">Adicionar Produtos</h3>
                            <BuscaProdutoAvancada
                                produtos={produtos}
                                fornecedores={fornecedores}
                                onSelectProduto={(prod) => adicionarProduto(prod)}
                            />
                        </div>

                        {/* Configuração da Logo da Etiqueta */}
                        <div className="border rounded-lg bg-white p-4 shadow-sm space-y-3">
                            <h3 className="font-semibold text-sm text-gray-700 flex items-center gap-2">
                                <Palette className="w-4 h-4 text-green-600" />
                                Logo da Etiqueta
                            </h3>
                            
                            <div className="grid grid-cols-3 gap-1 bg-gray-100 p-1 rounded-lg text-xs font-medium">
                                <button
                                    type="button"
                                    onClick={() => {
                                        setLogoOption("default");
                                        handleSaveLogoConfig("default", logoCustomizadaUrl);
                                    }}
                                    className={`py-1.5 px-2 rounded-md transition-all text-center ${
                                        logoOption === "default"
                                            ? "bg-white shadow text-gray-900"
                                            : "text-gray-500 hover:text-gray-900"
                                    }`}
                                >
                                    Loja
                                </button>
                                <button
                                    type="button"
                                    onClick={() => {
                                        setLogoOption("custom");
                                        handleSaveLogoConfig("custom", logoCustomizadaUrl);
                                    }}
                                    className={`py-1.5 px-2 rounded-md transition-all text-center ${
                                        logoOption === "custom"
                                            ? "bg-white shadow text-gray-900"
                                            : "text-gray-500 hover:text-gray-900"
                                    }`}
                                >
                                    Personalizada
                                </button>
                                <button
                                    type="button"
                                    onClick={() => {
                                        setLogoOption("none");
                                        handleSaveLogoConfig("none", logoCustomizadaUrl);
                                    }}
                                    className={`py-1.5 px-2 rounded-md transition-all text-center ${
                                        logoOption === "none"
                                            ? "bg-white shadow text-gray-900"
                                            : "text-gray-500 hover:text-gray-900"
                                    }`}
                                >
                                    Sem Logo
                                </button>
                            </div>

                            {logoOption === "custom" && (
                                <div className="space-y-2 mt-2 animate-in fade-in-50 duration-200">
                                    {logoCustomizadaUrl ? (
                                        <div className="flex items-center justify-between border rounded-lg p-2 bg-gray-50/50">
                                            <img
                                                src={logoCustomizadaUrl}
                                                alt="Logo Personalizada"
                                                className="h-10 max-w-[120px] object-contain rounded bg-white p-1 border shadow-sm"
                                            />
                                            <Button
                                                type="button"
                                                variant="ghost"
                                                size="icon"
                                                onClick={handleRemoveCustomLogo}
                                                className="h-8 w-8 text-red-500 hover:text-red-700 hover:bg-red-50 rounded-full"
                                            >
                                                <Trash2 className="w-4 h-4" />
                                            </Button>
                                        </div>
                                    ) : (
                                        <label className="block cursor-pointer">
                                            <input
                                                type="file"
                                                accept="image/png, image/jpeg, image/webp"
                                                className="hidden"
                                                onChange={handleLogoUpload}
                                                disabled={isUploading}
                                            />
                                            <div className="border border-dashed border-gray-300 rounded-lg p-4 text-center hover:bg-gray-50 transition-colors flex flex-col items-center gap-1.5">
                                                {isUploading ? (
                                                    <>
                                                        <Loader2 className="w-5 h-5 text-green-600 animate-spin" />
                                                        <span className="text-xs text-gray-500 font-medium">Enviando logo...</span>
                                                    </>
                                                ) : (
                                                    <>
                                                        <Upload className="w-5 h-5 text-gray-400" />
                                                        <span className="text-xs font-semibold text-gray-700">Enviar Imagem</span>
                                                        <span className="text-[10px] text-gray-400">PNG com fundo transparente</span>
                                                    </>
                                                )}
                                            </div>
                                        </label>
                                    )}
                                </div>
                            )}
                        </div>

                        {/* Configuração do Tamanho da Etiqueta */}
                        <div className="border rounded-lg bg-white p-4 shadow-sm space-y-3">
                            <h3 className="font-semibold text-sm text-gray-700 flex items-center gap-2">
                                <Printer className="w-4 h-4 text-green-600" />
                                Tamanho da Etiqueta
                            </h3>
                            
                            <div className="grid grid-cols-2 gap-2 bg-gray-100 p-1 rounded-lg text-xs font-medium">
                                <button
                                    type="button"
                                    onClick={() => setLayoutOption("1/4")}
                                    className={`py-2 px-3 rounded-md transition-all text-center ${
                                        layoutOption === "1/4"
                                            ? "bg-white shadow text-gray-900 font-semibold"
                                            : "text-gray-500 hover:text-gray-900"
                                    }`}
                                >
                                    1/4 da Folha (Retrato)
                                </button>
                                <button
                                    type="button"
                                    onClick={() => setLayoutOption("1/6")}
                                    className={`py-2 px-3 rounded-md transition-all text-center ${
                                        layoutOption === "1/6"
                                            ? "bg-white shadow text-gray-900 font-semibold"
                                            : "text-gray-500 hover:text-gray-900"
                                    }`}
                                >
                                    1/6 da Folha (Paisagem)
                                </button>
                                <button
                                    type="button"
                                    onClick={() => setLayoutOption("1/2")}
                                    className={`py-2 px-3 rounded-md transition-all text-center ${
                                        layoutOption === "1/2"
                                            ? "bg-white shadow text-gray-900 font-semibold"
                                            : "text-gray-500 hover:text-gray-900"
                                    }`}
                                >
                                    1/2 da Folha (Retrato)
                                </button>
                                <button
                                    type="button"
                                    onClick={() => setLayoutOption("inteira")}
                                    className={`py-2 px-3 rounded-md transition-all text-center ${
                                        layoutOption === "inteira"
                                            ? "bg-white shadow text-gray-900 font-semibold"
                                            : "text-gray-500 hover:text-gray-900"
                                    }`}
                                >
                                    Folha Inteira (Retrato)
                                </button>
                            </div>
                        </div>

                        {/* Lista de Selecionados */}
                        <div className="flex-1 flex flex-col">
                            <h3 className="font-semibold text-sm text-gray-700 mb-3 flex justify-between">
                                <span>Lista de Impressão</span>
                                <span className="bg-green-100 text-green-800 text-xs px-2 py-0.5 rounded-full">
                                    Total: {totalEtiquetas} etiqueta(s)
                                </span>
                            </h3>

                            <ScrollArea className="flex-1 h-[250px] pr-4 border rounded-md bg-white p-2">
                                {itensImpressao.length === 0 ? (
                                    <div className="h-full flex flex-col items-center justify-center text-gray-400 p-4 text-center">
                                        <Printer className="w-8 h-8 mb-2 opacity-50" />
                                        <p className="text-sm">Nenhum produto adicionado.</p>
                                    </div>
                                ) : (
                                    <div className="space-y-2">
                                        {itensImpressao.map(item => (
                                            <div key={item.produto.id} className="bg-gray-50 border p-3 rounded-lg flex items-center justify-between gap-2">
                                                <div className="flex-1 min-w-0">
                                                    <p className="font-medium text-sm text-gray-900 truncate" title={item.produto.nome}>
                                                        {item.produto.nome} {item.produto.modelo_referencia ? `(${item.produto.modelo_referencia})` : ''}
                                                    </p>
                                                </div>

                                                <div className="flex items-center gap-1 bg-white border rounded shadow-sm px-1 py-0.5 shrink-0">
                                                    <Button
                                                        variant="ghost"
                                                        size="icon"
                                                        className="h-6 w-6"
                                                        onClick={() => atualizarQuantidade(item.produto.id, -1)}
                                                    >
                                                        <Minus className="h-3 w-3" />
                                                    </Button>
                                                    <span className="text-sm font-medium w-6 text-center">
                                                        {item.quantidade}
                                                    </span>
                                                    <Button
                                                        variant="ghost"
                                                        size="icon"
                                                        className="h-6 w-6"
                                                        onClick={() => atualizarQuantidade(item.produto.id, 1)}
                                                    >
                                                        <Plus className="h-3 w-3" />
                                                    </Button>
                                                </div>

                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    className="h-7 w-7 text-red-500 hover:text-red-700 hover:bg-red-50 shrink-0"
                                                    onClick={() => removerProduto(item.produto.id)}
                                                >
                                                    <Trash2 className="h-4 w-4" />
                                                </Button>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </ScrollArea>
                        </div>

                    </div>

                    {/* Lado Direito: Preview */}
                    <div className="w-full md:w-1/2 bg-gray-200/50 p-6 flex flex-col relative">
                        <h3 className="font-semibold text-sm text-gray-700 mb-3 flex items-center gap-2">
                            Preview da Impressão
                            <span className="text-xs font-normal text-gray-500">
                                (1 página = {layoutOption === "1/6" ? 6 : layoutOption === "1/4" ? 4 : layoutOption === "1/2" ? 2 : 1} etiqueta{layoutOption === "inteira" ? "" : "s"})
                            </span>
                        </h3>

                        <ScrollArea className="flex-1 h-[450px] border border-gray-300 rounded-md bg-gray-100 shadow-inner overflow-hidden relative">
                            {produtosImpressao.length > 0 ? (
                                <div className={`${layoutOption === "1/6" ? "scale-[0.3]" : "scale-[0.4]"} origin-top-left translate-x-4 translate-y-4 ${layoutOption === "1/6" ? "w-[297mm]" : "w-[210mm]"} pointer-events-none`}>
                                    {/* Renderizamos o componente invisível que será pescado pelo react-to-print,
                        e o mesmo componente visualmente apenas para preview */}
                                    <div className="bg-white shadow">
                                        <EtiquetaImpressao 
                                            empresa={organization || user} 
                                            produtos={produtosImpressao} 
                                            logoOption={logoOption}
                                            logoCustomizadaUrl={logoCustomizadaUrl}
                                            layout={layoutOption}
                                        />
                                    </div>
                                </div>
                            ) : (
                                <div className="h-full w-full flex flex-col items-center justify-center text-gray-400">
                                    <p>Adicione itens para visualizar</p>
                                </div>
                            )}
                        </ScrollArea>

                        {/* Hidden component só pro ReactToPrint (Não afetado pelo scale do preview) */}
                        <div className="hidden">
                            <EtiquetaImpressao
                                ref={componentRef}
                                empresa={organization || user}
                                produtos={produtosImpressao}
                                logoOption={logoOption}
                                logoCustomizadaUrl={logoCustomizadaUrl}
                                layout={layoutOption}
                            />
                        </div>
                    </div>

                </div>

                <DialogFooter className="p-4 border-t bg-gray-50">
                    <Button variant="outline" onClick={onClose} className="mr-auto">Cancelar</Button>
                    <Button
                        className="bg-green-600 hover:bg-green-700 font-medium"
                        onClick={handlePrint}
                        disabled={totalEtiquetas === 0}
                    >
                        <Printer className="w-4 h-4 mr-2" />
                        Imprimir {totalEtiquetas} Etiquetas
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

import React, { useState, useEffect } from "react";
import { base44, supabase } from "@/api/base44Client";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import {
  FileText, CheckCircle, AlertTriangle, Loader2, Plus, Search,
  Barcode, Upload, Building2, Package, DollarSign, Truck,
  ChevronDown, ChevronRight, AlertCircle, CheckCircle2, Info
} from "lucide-react";
import { toast } from "sonner";
import { isValidGTIN, normalizeGTIN, generateSafeSKU } from "@/utils/gtinValidator";

export default function ImportarNFe({ user }) {
  const [activeTab, setActiveTab] = useState("chave");
  const [chaveAcesso, setChaveAcesso] = useState("");
  const [processando, setProcessando] = useState(false);
  const [consultandoAPI, setConsultandoAPI] = useState(false);
  const [dadosCompletos, setDadosCompletos] = useState(null);
  const [resultado, setResultado] = useState(null);
  const [etapaAtual, setEtapaAtual] = useState("");
  const [cnpjSelecionado, setCnpjSelecionado] = useState("49129137000130");
  const [impostoExpandido, setImpostoExpandido] = useState(false);
  const [itensExpandido, setItensExpandido] = useState(true);

  const queryClient = useQueryClient();

  // Queries para dados existentes
  const { data: fornecedores = [] } = useQuery({
    queryKey: ['fornecedores'],
    queryFn: () => base44.entities.Fornecedor.list(),
  });

  const { data: produtos = [] } = useQuery({
    queryKey: ['produtos'],
    queryFn: () => base44.entities.Produto.list(),
  });

  // ==============================================
  // SEGURANÇA: Credenciais movidas para Edge Function
  // Configurar via: supabase secrets set NUVEM_FISCAL_HOMOLOG_ID=xxx
  // ==============================================

  // Ambiente configurado localmente (apenas seleção, sem credenciais)
  const AMBIENTE = localStorage.getItem("nfe_ambiente") || "homologacao";

  const EMPRESAS = [
    { cnpj: "49129137000130", nome: "Atacadao Outlet", cnpjFormatado: "49.129.137/0001-30" },
    { cnpj: "04842257000141", nome: "Moveis Pedro II", cnpjFormatado: "04.842.257/0001-41" },
    { cnpj: "42316614000127", nome: "Massi Home Design", cnpjFormatado: "42.316.614/0001-27" },
    { cnpj: "53795479000166", nome: "Alta Performance Decoracoes", cnpjFormatado: "53.795.479/0001-66" },
  ];

  const empresaSelecionada = EMPRESAS.find(e => e.cnpj === cnpjSelecionado) || EMPRESAS[0];

  // Helper para extrair texto de tag XML
  const getTagText = (parent, tagName) => {
    if (!parent) return null;
    const el = parent.getElementsByTagName(tagName)[0];
    return el?.textContent || null;
  };

  const getTagFloat = (parent, tagName) => {
    const text = getTagText(parent, tagName);
    return text ? parseFloat(text) : 0;
  };

  // ================================================
  // NOVA IMPLEMENTAÇÃO: Usa Edge Function (seguro)
  // ================================================
  const importarViaEdgeFunction = async (chave, cnpj) => {
    const { data, error } = await supabase.functions.invoke('importar-nfe', {
      body: {
        chave_acesso: chave,
        cnpj_destinatario: cnpj,
        ambiente: AMBIENTE
      }
    });

    if (error) {
      console.error("Erro na Edge Function:", error);
      throw new Error(error.message || 'Erro ao conectar com Edge Function');
    }

    if (!data.success && data.error) {
      throw new Error(data.error);
    }

    return data;
  };

  // Parser completo do XML da NFe
  const parseXMLCompleto = (xmlContent) => {
    const parser = new DOMParser();
    const xmlDoc = parser.parseFromString(xmlContent, "text/xml");

    const infNFe = xmlDoc.getElementsByTagName("infNFe")[0];
    if (!infNFe) throw new Error("XML invalido - infNFe nao encontrado");

    const ide = xmlDoc.getElementsByTagName("ide")[0];
    const emit = xmlDoc.getElementsByTagName("emit")[0];
    const dest = xmlDoc.getElementsByTagName("dest")[0];
    const total = xmlDoc.getElementsByTagName("total")[0];
    const ICMSTot = total?.getElementsByTagName("ICMSTot")[0];
    const transp = xmlDoc.getElementsByTagName("transp")[0];
    const pag = xmlDoc.getElementsByTagName("pag")[0];
    const infAdic = xmlDoc.getElementsByTagName("infAdic")[0];
    const dets = xmlDoc.getElementsByTagName("det");

    // Dados da Nota
    const dadosNota = {
      chave_acesso: infNFe.getAttribute("Id")?.replace("NFe", "") || "",
      numero_nota: getTagText(ide, "nNF"),
      serie: getTagText(ide, "serie"),
      data_emissao: getTagText(ide, "dhEmi"),
      natureza_operacao: getTagText(ide, "natOp"),
    };

    // Emitente (Fornecedor)
    const emitEndereco = emit?.getElementsByTagName("enderEmit")[0];
    const dadosEmitente = {
      cnpj: getTagText(emit, "CNPJ"),
      razao_social: getTagText(emit, "xNome"),
      nome_fantasia: getTagText(emit, "xFant"),
      ie: getTagText(emit, "IE"),
      endereco: emitEndereco ? `${getTagText(emitEndereco, "xLgr")}, ${getTagText(emitEndereco, "nro")}` : "",
      bairro: getTagText(emitEndereco, "xBairro"),
      cidade: getTagText(emitEndereco, "xMun"),
      uf: getTagText(emitEndereco, "UF"),
      cep: getTagText(emitEndereco, "CEP"),
      telefone: getTagText(emitEndereco, "fone"),
    };

    // Destinatario
    const dadosDestinatario = {
      cnpj: getTagText(dest, "CNPJ"),
      razao_social: getTagText(dest, "xNome"),
    };

    // Totais e Impostos
    const totais = {
      valor_produtos: getTagFloat(ICMSTot, "vProd"),
      valor_frete: getTagFloat(ICMSTot, "vFrete"),
      valor_seguro: getTagFloat(ICMSTot, "vSeg"),
      valor_desconto: getTagFloat(ICMSTot, "vDesc"),
      valor_outras_despesas: getTagFloat(ICMSTot, "vOutro"),
      valor_total_nota: getTagFloat(ICMSTot, "vNF"),
      // ICMS
      base_icms: getTagFloat(ICMSTot, "vBC"),
      valor_icms: getTagFloat(ICMSTot, "vICMS"),
      base_icms_st: getTagFloat(ICMSTot, "vBCST"),
      valor_icms_st: getTagFloat(ICMSTot, "vST"),
      valor_fcp: getTagFloat(ICMSTot, "vFCP"),
      valor_fcp_st: getTagFloat(ICMSTot, "vFCPST"),
      // Outros impostos
      valor_ipi: getTagFloat(ICMSTot, "vIPI"),
      valor_ii: getTagFloat(ICMSTot, "vII"),
      valor_pis: getTagFloat(ICMSTot, "vPIS"),
      valor_cofins: getTagFloat(ICMSTot, "vCOFINS"),
      valor_aproximado_tributos: getTagFloat(ICMSTot, "vTotTrib"),
    };

    // Transporte
    const transporta = transp?.getElementsByTagName("transporta")[0];
    const veicTransp = transp?.getElementsByTagName("veicTransp")[0];
    const vol = transp?.getElementsByTagName("vol")[0];
    const dadosTransporte = {
      modalidade_frete: getTagText(transp, "modFrete"),
      transportadora_cnpj: getTagText(transporta, "CNPJ"),
      transportadora_nome: getTagText(transporta, "xNome"),
      transportadora_ie: getTagText(transporta, "IE"),
      placa_veiculo: getTagText(veicTransp, "placa"),
      uf_veiculo: getTagText(veicTransp, "UF"),
      quantidade_volumes: parseInt(getTagText(vol, "qVol")) || 0,
      especie_volumes: getTagText(vol, "esp"),
      peso_liquido: getTagFloat(vol, "pesoL"),
      peso_bruto: getTagFloat(vol, "pesoB"),
    };

    // Pagamento
    const detPag = pag?.getElementsByTagName("detPag")[0];
    const dadosPagamento = {
      forma_pagamento: getTagText(detPag, "tPag"),
      valor_pagamento: getTagFloat(detPag, "vPag"),
    };

    // Informacoes Adicionais
    const infoAdicionais = {
      informacoes_complementares: getTagText(infAdic, "infCpl"),
      informacoes_fisco: getTagText(infAdic, "infAdFisco"),
    };

    // Itens da Nota
    const itens = [];
    for (let i = 0; i < dets.length; i++) {
      const det = dets[i];
      const prod = det.getElementsByTagName("prod")[0];
      const imposto = det.getElementsByTagName("imposto")[0];

      // ICMS - pode estar em diferentes tags
      const icmsGroup = imposto?.getElementsByTagName("ICMS")[0];
      const icms = icmsGroup?.children[0]; // ICMS00, ICMS10, etc.

      // IPI
      const ipiGroup = imposto?.getElementsByTagName("IPI")[0];
      const ipiTrib = ipiGroup?.getElementsByTagName("IPITrib")[0];

      // PIS
      const pisGroup = imposto?.getElementsByTagName("PIS")[0];
      const pis = pisGroup?.children[0];

      // COFINS
      const cofinsGroup = imposto?.getElementsByTagName("COFINS")[0];
      const cofins = cofinsGroup?.children[0];

      let rawEan = getTagText(prod, "cEAN");
      let ean = (rawEan && rawEan !== "SEM GTIN" && isValidGTIN(rawEan)) ? normalizeGTIN(rawEan, true) : null;

      itens.push({
        numero_item: parseInt(det.getAttribute("nItem")) || i + 1,
        // Produto
        codigo_produto_fornecedor: getTagText(prod, "cProd"),
        codigo_barras_ean: ean,
        codigo_barras_tributavel: getTagText(prod, "cEANTrib"),
        descricao_produto: getTagText(prod, "xProd"),
        ncm: getTagText(prod, "NCM"),
        cest: getTagText(prod, "CEST"),
        cfop: getTagText(prod, "CFOP"),
        unidade_comercial: getTagText(prod, "uCom"),
        unidade_tributavel: getTagText(prod, "uTrib"),
        // Valores
        quantidade: getTagFloat(prod, "qCom"),
        quantidade_tributavel: getTagFloat(prod, "qTrib"),
        valor_unitario: getTagFloat(prod, "vUnCom"),
        valor_unitario_tributavel: getTagFloat(prod, "vUnTrib"),
        valor_total_produto: getTagFloat(prod, "vProd"),
        valor_frete_rateado: getTagFloat(prod, "vFrete"),
        valor_seguro_rateado: getTagFloat(prod, "vSeg"),
        valor_desconto: getTagFloat(prod, "vDesc"),
        valor_outras_despesas: getTagFloat(prod, "vOutro"),
        // ICMS
        origem_mercadoria: getTagText(icms, "orig"),
        cst_icms: getTagText(icms, "CST") || getTagText(icms, "CSOSN"),
        modalidade_bc_icms: getTagText(icms, "modBC"),
        base_calculo_icms: getTagFloat(icms, "vBC"),
        percentual_reducao_bc: getTagFloat(icms, "pRedBC"),
        aliquota_icms: getTagFloat(icms, "pICMS"),
        valor_icms: getTagFloat(icms, "vICMS"),
        // ICMS ST
        modalidade_bc_icms_st: getTagText(icms, "modBCST"),
        percentual_mva_st: getTagFloat(icms, "pMVAST"),
        base_calculo_icms_st: getTagFloat(icms, "vBCST"),
        aliquota_icms_st: getTagFloat(icms, "pICMSST"),
        valor_icms_st: getTagFloat(icms, "vICMSST"),
        // IPI
        cst_ipi: getTagText(ipiTrib, "CST") || getTagText(ipiGroup?.getElementsByTagName("IPINT")[0], "CST"),
        codigo_enquadramento_ipi: getTagText(ipiGroup, "cEnq"),
        base_calculo_ipi: getTagFloat(ipiTrib, "vBC"),
        aliquota_ipi: getTagFloat(ipiTrib, "pIPI"),
        valor_ipi: getTagFloat(ipiTrib, "vIPI"),
        // PIS
        cst_pis: getTagText(pis, "CST"),
        base_calculo_pis: getTagFloat(pis, "vBC"),
        aliquota_pis: getTagFloat(pis, "pPIS"),
        valor_pis: getTagFloat(pis, "vPIS"),
        // COFINS
        cst_cofins: getTagText(cofins, "CST"),
        base_calculo_cofins: getTagFloat(cofins, "vBC"),
        aliquota_cofins: getTagFloat(cofins, "pCOFINS"),
        valor_cofins: getTagFloat(cofins, "vCOFINS"),
        // Tributos aproximados
        valor_aproximado_tributos: getTagFloat(imposto, "vTotTrib"),
        // Info adicional do item
        informacoes_adicionais: getTagText(det, "infAdProd"),
      });
    }

    return {
      nota: dadosNota,
      emitente: dadosEmitente,
      destinatario: dadosDestinatario,
      totais,
      transporte: dadosTransporte,
      pagamento: dadosPagamento,
      infoAdicionais,
      itens,
      xmlOriginal: xmlContent,
    };
  };

  // Buscar nota via Edge Function (SEGURO - sem credenciais no frontend)
  const consultarNotaNaAPI = async () => {
    const chaveLimpa = chaveAcesso.replace(/\D/g, '');

    if (chaveLimpa.length !== 44) {
      setResultado({ tipo: 'erro', texto: 'A chave deve ter 44 numeros.' });
      return;
    }

    setConsultandoAPI(true);
    setResultado(null);
    setDadosCompletos(null);
    setEtapaAtual("Conectando com servidor...");

    try {
      // Verificar se a nota ja existe no banco para evitar duplicidade
      const { data: existente, error: errorCheck } = await supabase
        .from('nota_fiscal_entrada')
        .select('id, numero_nota')
        .eq('chave_acesso', chaveLimpa)
        .maybeSingle();

      if (errorCheck) console.error("Erro ao verificar duplicidade:", errorCheck);
      
      if (existente) {
        setResultado({ 
          tipo: 'erro', 
          texto: `Nota Fiscal #${existente.numero_nota} ja importada anteriormente.` 
        });
        setConsultandoAPI(false);
        setEtapaAtual("");
        return;
      }

      setEtapaAtual("Buscando nota na SEFAZ...");

      // Usar Edge Function segura
      const resposta = await importarViaEdgeFunction(chaveLimpa, cnpjSelecionado);

      if (!resposta.success) {
        if (resposta.status === 'aguardando' || resposta.status === 'processando') {
          throw new Error(resposta.error || 'Nota em processamento. Aguarde 1-2 minutos e tente novamente.');
        }
        throw new Error(resposta.error || 'Erro ao buscar nota');
      }

      if (!resposta.xml) {
        throw new Error('XML não disponível ainda. Tente novamente em alguns segundos.');
      }

      // Parse completo do XML retornado
      setEtapaAtual("Processando dados...");
      const dados = parseXMLCompleto(resposta.xml);

      setDadosCompletos(dados);
      setResultado({ tipo: 'sucesso', texto: `Nota ${dados.nota.numero_nota} carregada com sucesso!` });

    } catch (error) {
      console.error("Erro:", error);

      // Melhorar mensagem de erro para o usuário
      let mensagemErro = error.message;
      if (error.message.includes('FunctionsFetchError') || error.message.includes('Failed to fetch')) {
        mensagemErro = 'Edge Functions não deployadas. Execute: supabase functions deploy importar-nfe';
      } else if (error.message.includes('Credenciais não configuradas')) {
        mensagemErro = 'Credenciais não configuradas no servidor. Configure via supabase secrets set.';
      }

      setResultado({ tipo: 'erro', texto: mensagemErro });
    } finally {
      setConsultandoAPI(false);
      setEtapaAtual("");
    }
  };

  // Processar importacao completa
  const processarImportacao = async () => {
    if (!dadosCompletos) return;

    setProcessando(true);
    const acoes = [];

    try {
      // 1. Verificar/Criar Fornecedor
      setEtapaAtual("Verificando fornecedor...");
      let fornecedorId = null;
      const fornecedorExistente = fornecedores.find(f =>
        f.cnpj?.replace(/\D/g, '') === dadosCompletos.emitente.cnpj
      );

      if (fornecedorExistente) {
        fornecedorId = fornecedorExistente.id;
        acoes.push({ tipo: 'info', texto: `Fornecedor vinculado: ${fornecedorExistente.nome_empresa}` });
      } else {
        setEtapaAtual("Criando fornecedor...");
        const novoFornecedor = await base44.entities.Fornecedor.create({
          nome_empresa: dadosCompletos.emitente.razao_social,
          nome: dadosCompletos.emitente.nome_fantasia || dadosCompletos.emitente.razao_social,
          cnpj: dadosCompletos.emitente.cnpj,
          telefone: dadosCompletos.emitente.telefone,
          contato: dadosCompletos.emitente.nome_fantasia,
        });
        fornecedorId = novoFornecedor.id;
        acoes.push({ tipo: 'sucesso', texto: `Fornecedor criado: ${dadosCompletos.emitente.razao_social}` });
      }

      // 2. Criar registro da NFe
      setEtapaAtual("Registrando nota fiscal...");
      const nfe = await base44.entities.NotaFiscalEntrada.create({
        chave_acesso: dadosCompletos.nota.chave_acesso,
        numero_nota: dadosCompletos.nota.numero_nota,
        serie: dadosCompletos.nota.serie,
        data_emissao: dadosCompletos.nota.data_emissao,
        fornecedor_id: fornecedorId,
        fornecedor_cnpj: dadosCompletos.emitente.cnpj,
        fornecedor_razao_social: dadosCompletos.emitente.razao_social,
        fornecedor_nome_fantasia: dadosCompletos.emitente.nome_fantasia,
        fornecedor_ie: dadosCompletos.emitente.ie,
        destinatario_cnpj: dadosCompletos.destinatario.cnpj,
        destinatario_razao_social: dadosCompletos.destinatario.razao_social,
        empresa_destino: empresaSelecionada.nome,
        ...dadosCompletos.totais,
        ...dadosCompletos.transporte,
        ...dadosCompletos.pagamento,
        informacoes_complementares: dadosCompletos.infoAdicionais.informacoes_complementares,
        xml_original: dadosCompletos.xmlOriginal,
        importado_por: user?.id,
        importado_por_nome: user?.full_name || user?.email,
        status: 'Importada',
      });

      acoes.push({ tipo: 'sucesso', texto: `NFe ${dadosCompletos.nota.numero_nota} registrada` });

      // 3. Processar cada item
      setEtapaAtual("Processando itens...");
      let produtosCriados = 0;
      let produtosAtualizados = 0;
      let produtosComAtencao = 0;

      for (const item of dadosCompletos.itens) {
        let produtoId = null;
        let produtoVinculado = false;
        let produtoCriado = false;
        let requerAtencao = false;
        let motivoAtencao = null;

        // Buscar por EAN
        let produtoExistente = item.codigo_barras_ean ?
          produtos.find(p => p.codigo_barras && normalizeGTIN(p.codigo_barras, true) === item.codigo_barras_ean) : null;

        // Buscar por nome similar
        if (!produtoExistente) {
          const nomeNormalizado = item.descricao_produto.toLowerCase().trim();
          produtoExistente = produtos.find(p =>
            p.nome?.toLowerCase().trim() === nomeNormalizado
          );
          if (produtoExistente) {
            requerAtencao = true;
            motivoAtencao = "Vinculado por nome - verificar se e o produto correto";
          }
        }

        if (produtoExistente) {
          // Atualizar estoque e custo
          await base44.entities.Produto.update(produtoExistente.id, {
            quantidade_estoque: (produtoExistente.quantidade_estoque || 0) + item.quantidade,
            estoque_cd: (produtoExistente.estoque_cd || 0) + item.quantidade,
            preco_custo: item.valor_unitario,
            ncm: item.ncm || produtoExistente.ncm,
            ultima_nfe_id: nfe.id,
          });
          produtoId = produtoExistente.id;
          produtoVinculado = true;
          produtosAtualizados++;
        } else {
          // Criar novo produto com SKU seguro e EAN válido (ou null)
          const safeSku = item.codigo_produto_fornecedor
            ? generateSafeSKU(`NFE-${item.codigo_produto_fornecedor}`.substring(0, 30))
            : generateSafeSKU('NFE');

          const novoProduto = await base44.entities.Produto.create({
            nome: item.descricao_produto,
            sku: safeSku,
            codigo_barras: item.codigo_barras_ean,
            categoria: "Outros",
            preco_custo: item.valor_unitario,
            preco_venda: item.valor_unitario * (1 + (parseFloat(localStorage.getItem("nfe_margem_lucro") || "80") / 100)),
            quantidade_estoque: item.quantidade,
            estoque_cd: item.quantidade,
            estoque_minimo: 5,
            ativo: true,
            ncm: item.ncm,
            origem_nfe: true,
            requer_atencao: true,
            motivo_atencao: "Produto importado via NFe - completar cadastro",
            ultima_nfe_id: nfe.id,
            descricao: `Importado da NFe ${dadosCompletos.nota.numero_nota}`,
          });
          produtoId = novoProduto.id;
          produtoCriado = true;
          requerAtencao = true;
          motivoAtencao = "Produto novo - completar cadastro (categoria, preco venda, fotos)";
          produtosCriados++;
          produtosComAtencao++;
        }

        // Registrar item da NFe
        await base44.entities.ItemNotaFiscal.create({
          nota_fiscal_id: nfe.id,
          produto_id: produtoId,
          ...item,
          produto_vinculado: produtoVinculado,
          produto_criado: produtoCriado,
          requer_atencao: requerAtencao,
          motivo_atencao: motivoAtencao,
        });
      }

      acoes.push({
        tipo: produtosComAtencao > 0 ? 'atencao' : 'sucesso',
        texto: `${produtosAtualizados} produtos atualizados, ${produtosCriados} criados${produtosComAtencao > 0 ? ` (${produtosComAtencao} requerem atencao)` : ''}`
      });

      // 4. Criar lancamento financeiro (conta a pagar)
      setEtapaAtual("Criando lancamento financeiro...");
      const lancamento = await base44.entities.LancamentoFinanceiro.create({
        descricao: `NFe ${dadosCompletos.nota.numero_nota} - ${dadosCompletos.emitente.razao_social}`,
        valor: dadosCompletos.totais.valor_total_nota,
        tipo: "Despesa",
        data_vencimento: new Date().toISOString().split('T')[0],
        data_lancamento: new Date().toISOString().split('T')[0],
        pago: false,
        status: "Pendente",
        categoria_nome: "Compra de Mercadorias",
        forma_pagamento: dadosCompletos.pagamento.forma_pagamento === "01" ? "Dinheiro" :
          dadosCompletos.pagamento.forma_pagamento === "03" ? "Cartao Credito" :
            dadosCompletos.pagamento.forma_pagamento === "04" ? "Cartao Debito" : "Boleto",
        observacao: `Importado automaticamente da NFe ${dadosCompletos.nota.chave_acesso}`,
      });

      // Atualizar NFe com ID do lancamento
      await base44.entities.NotaFiscalEntrada.update(nfe.id, {
        lancamento_financeiro_id: lancamento.id,
        status: 'Processada',
      });

      acoes.push({ tipo: 'sucesso', texto: `Conta a pagar criada: R$ ${dadosCompletos.totais.valor_total_nota.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}` });

      // Invalidar queries
      queryClient.invalidateQueries({ queryKey: ['produtos'] });
      queryClient.invalidateQueries({ queryKey: ['fornecedores'] });
      queryClient.invalidateQueries({ queryKey: ['lancamentos-financeiros'] });
      queryClient.invalidateQueries({ queryKey: ['notas-fiscais'] });

      setResultado({
        tipo: 'completo',
        texto: 'Importacao concluida com sucesso!',
        acoes
      });

      toast.success("NFe importada e integrada com sucesso!");

    } catch (error) {
      console.error("Erro na importacao:", error);
      setResultado({ tipo: 'erro', texto: error.message });
      toast.error("Erro ao processar importacao");
    } finally {
      setProcessando(false);
      setEtapaAtual("");
    }
  };

  // Formatar valor em reais
  const formatMoney = (value) => {
    if (!value && value !== 0) return "-";
    return `R$ ${value.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`;
  };

  return (
    <div className="space-y-6">
      <Card className="border-0 shadow-lg">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-green-800">
            <FileText className="w-6 h-6" />
            Entrada de Nota Fiscal Eletronica
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Seletor de Empresa */}
          <div className="bg-gray-50 p-4 rounded-lg border">
            <div className="flex items-center gap-3">
              <Building2 className="h-5 w-5 text-gray-500" />
              <div className="flex-1">
                <label className="text-sm font-medium text-gray-700 mb-1 block">Empresa Destinataria</label>
                <Select value={cnpjSelecionado} onValueChange={setCnpjSelecionado}>
                  <SelectTrigger className="w-full bg-white">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {EMPRESAS.map(empresa => (
                      <SelectItem key={empresa.cnpj} value={empresa.cnpj}>
                        <span className="font-medium">{empresa.nome}</span>
                        <span className="text-xs text-gray-500 ml-2">{empresa.cnpjFormatado}</span>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
          </div>

          {/* Tabs de entrada */}
          <Tabs value={activeTab} onValueChange={setActiveTab}>
            <TabsList className="grid w-full grid-cols-2">
              <TabsTrigger value="chave">
                <Barcode className="w-4 h-4 mr-2" />
                Chave de Acesso
              </TabsTrigger>
              <TabsTrigger value="arquivo">
                <Upload className="w-4 h-4 mr-2" />
                Arquivo XML
              </TabsTrigger>
            </TabsList>

            <TabsContent value="chave" className="mt-4">
              <div className="flex gap-3">
                <div className="flex-1">
                  <Input
                    placeholder="Digite os 44 digitos da chave de acesso"
                    className="font-mono"
                    value={chaveAcesso}
                    onChange={(e) => setChaveAcesso(e.target.value.replace(/\D/g, ''))}
                    maxLength={44}
                  />
                  <p className="text-xs text-gray-400 mt-1">{chaveAcesso.length}/44 digitos</p>
                </div>
                <Button
                  onClick={consultarNotaNaAPI}
                  disabled={consultandoAPI || chaveAcesso.length < 44}
                  className="bg-green-700 hover:bg-green-800"
                >
                  {consultandoAPI ? <Loader2 className="w-4 h-4 animate-spin" /> : <Search className="w-4 h-4 mr-2" />}
                  Buscar
                </Button>
              </div>
            </TabsContent>

            <TabsContent value="arquivo" className="mt-4">
              <label className="cursor-pointer block">
                <input type="file" accept=".xml" className="hidden" onChange={(e) => {
                  const file = e.target.files?.[0];
                  if (!file) return;
                  const reader = new FileReader();
                  reader.onload = (ev) => {
                    try {
                      const dados = parseXMLCompleto(ev.target.result);
                      setDadosCompletos(dados);
                      setResultado({ tipo: 'sucesso', texto: `Nota ${dados.nota.numero_nota} carregada!` });
                    } catch (err) {
                      setResultado({ tipo: 'erro', texto: "Erro ao ler XML: " + err.message });
                    }
                  };
                  reader.readAsText(file);
                }} />
                <div className="flex flex-col items-center justify-center w-full h-32 border-2 border-dashed rounded-xl hover:bg-gray-50 transition-colors border-gray-300">
                  <FileText className="w-10 h-10 mb-2 text-green-700" />
                  <span className="text-sm font-medium text-gray-600">Clique para selecionar o XML</span>
                </div>
              </label>
            </TabsContent>
          </Tabs>

          {/* Status de etapa */}
          {etapaAtual && (
            <div className="flex items-center gap-2 text-sm text-gray-600">
              <Loader2 className="w-4 h-4 animate-spin" />
              {etapaAtual}
            </div>
          )}

          {/* Resultado/Erro */}
          {resultado && resultado.tipo !== 'completo' && (
            <Alert className={resultado.tipo === 'erro' ? 'border-red-200 bg-red-50' : 'border-green-200 bg-green-50'}>
              {resultado.tipo === 'erro' ? <AlertTriangle className="h-4 w-4 text-red-600" /> : <CheckCircle className="h-4 w-4 text-green-600" />}
              <AlertDescription className={resultado.tipo === 'erro' ? 'text-red-800' : 'text-green-800'}>
                {resultado.texto}
              </AlertDescription>
            </Alert>
          )}

          {/* Dados da Nota Carregada */}
          {dadosCompletos && (
            <div className="space-y-4">
              {/* Header da Nota */}
              <div className="bg-gradient-to-r from-green-50 to-emerald-50 p-4 rounded-lg border border-green-100">
                <div className="grid md:grid-cols-3 gap-4">
                  <div>
                    <p className="text-xs text-gray-500">Fornecedor</p>
                    <p className="font-bold text-green-800">{dadosCompletos.emitente.razao_social}</p>
                    <p className="text-xs text-gray-500">CNPJ: {dadosCompletos.emitente.cnpj?.replace(/(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})/, "$1.$2.$3/$4-$5")}</p>
                  </div>
                  <div className="text-center">
                    <p className="text-xs text-gray-500">Nota Fiscal</p>
                    <p className="font-bold text-2xl text-green-800">#{dadosCompletos.nota.numero_nota}</p>
                    <p className="text-xs text-gray-500">Serie {dadosCompletos.nota.serie}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-xs text-gray-500">Valor Total</p>
                    <p className="font-bold text-2xl text-green-800">{formatMoney(dadosCompletos.totais.valor_total_nota)}</p>
                    <p className="text-xs text-gray-500">{new Date(dadosCompletos.nota.data_emissao).toLocaleDateString('pt-BR')}</p>
                  </div>
                </div>
              </div>

              {/* Totais e Impostos */}
              <Collapsible open={impostoExpandido} onOpenChange={setImpostoExpandido}>
                <CollapsibleTrigger className="flex items-center justify-between w-full p-3 bg-gray-50 rounded-lg hover:bg-gray-100">
                  <div className="flex items-center gap-2">
                    <DollarSign className="w-4 h-4 text-gray-500" />
                    <span className="font-medium">Totais e Impostos</span>
                  </div>
                  {impostoExpandido ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
                </CollapsibleTrigger>
                <CollapsibleContent className="pt-3">
                  <div className="grid md:grid-cols-4 gap-4 p-4 bg-gray-50 rounded-lg">
                    <div>
                      <p className="text-xs text-gray-500">Produtos</p>
                      <p className="font-semibold">{formatMoney(dadosCompletos.totais.valor_produtos)}</p>
                    </div>
                    <div>
                      <p className="text-xs text-gray-500">Frete</p>
                      <p className="font-semibold">{formatMoney(dadosCompletos.totais.valor_frete)}</p>
                    </div>
                    <div>
                      <p className="text-xs text-gray-500">Desconto</p>
                      <p className="font-semibold text-red-600">-{formatMoney(dadosCompletos.totais.valor_desconto)}</p>
                    </div>
                    <div>
                      <p className="text-xs text-gray-500">Outras Despesas</p>
                      <p className="font-semibold">{formatMoney(dadosCompletos.totais.valor_outras_despesas)}</p>
                    </div>
                    <div className="border-t pt-2">
                      <p className="text-xs text-gray-500">ICMS</p>
                      <p className="font-semibold">{formatMoney(dadosCompletos.totais.valor_icms)}</p>
                    </div>
                    <div className="border-t pt-2">
                      <p className="text-xs text-gray-500">ICMS ST</p>
                      <p className="font-semibold">{formatMoney(dadosCompletos.totais.valor_icms_st)}</p>
                    </div>
                    <div className="border-t pt-2">
                      <p className="text-xs text-gray-500">IPI</p>
                      <p className="font-semibold">{formatMoney(dadosCompletos.totais.valor_ipi)}</p>
                    </div>
                    <div className="border-t pt-2">
                      <p className="text-xs text-gray-500">PIS + COFINS</p>
                      <p className="font-semibold">{formatMoney(dadosCompletos.totais.valor_pis + dadosCompletos.totais.valor_cofins)}</p>
                    </div>
                  </div>
                </CollapsibleContent>
              </Collapsible>

              {/* Transporte */}
              {dadosCompletos.transporte.transportadora_nome && (
                <div className="flex items-center gap-2 p-3 bg-blue-50 rounded-lg border border-blue-100">
                  <Truck className="w-4 h-4 text-blue-600" />
                  <span className="text-sm">
                    <span className="font-medium">{dadosCompletos.transporte.transportadora_nome}</span>
                    {dadosCompletos.transporte.placa_veiculo && ` - Placa: ${dadosCompletos.transporte.placa_veiculo}`}
                    {dadosCompletos.transporte.quantidade_volumes > 0 && ` - ${dadosCompletos.transporte.quantidade_volumes} volumes`}
                  </span>
                </div>
              )}

              {/* Itens */}
              <Collapsible open={itensExpandido} onOpenChange={setItensExpandido}>
                <CollapsibleTrigger className="flex items-center justify-between w-full p-3 bg-gray-50 rounded-lg hover:bg-gray-100">
                  <div className="flex items-center gap-2">
                    <Package className="w-4 h-4 text-gray-500" />
                    <span className="font-medium">Itens da Nota ({dadosCompletos.itens.length})</span>
                  </div>
                  {itensExpandido ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
                </CollapsibleTrigger>
                <CollapsibleContent className="pt-3">
                  <div className="border rounded-lg overflow-hidden">
                    <div className="max-h-96 overflow-auto">
                      <Table>
                        <TableHeader className="bg-gray-50 sticky top-0">
                          <TableRow>
                            <TableHead className="w-12">#</TableHead>
                            <TableHead>Produto</TableHead>
                            <TableHead className="text-center">NCM</TableHead>
                            <TableHead className="text-center">Qtd</TableHead>
                            <TableHead className="text-right">Unit.</TableHead>
                            <TableHead className="text-right">Total</TableHead>
                            <TableHead className="text-right">ICMS</TableHead>
                            <TableHead className="text-right">IPI</TableHead>
                          </TableRow>
                        </TableHeader>
                        <TableBody>
                          {dadosCompletos.itens.map((item, idx) => (
                            <TableRow key={idx} className="hover:bg-gray-50">
                              <TableCell className="text-gray-500">{item.numero_item}</TableCell>
                              <TableCell>
                                <div>
                                  <p className="font-medium text-sm line-clamp-1">{item.descricao_produto}</p>
                                  <div className="flex gap-2 text-xs text-gray-500">
                                    {item.codigo_barras_ean && <span>EAN: {item.codigo_barras_ean}</span>}
                                    <span>CFOP: {item.cfop}</span>
                                  </div>
                                </div>
                              </TableCell>
                              <TableCell className="text-center font-mono text-xs">{item.ncm}</TableCell>
                              <TableCell className="text-center">
                                <Badge variant="secondary">{item.quantidade} {item.unidade_comercial}</Badge>
                              </TableCell>
                              <TableCell className="text-right text-sm">{formatMoney(item.valor_unitario)}</TableCell>
                              <TableCell className="text-right font-semibold">{formatMoney(item.valor_total_produto)}</TableCell>
                              <TableCell className="text-right text-sm">
                                {item.valor_icms > 0 ? (
                                  <span className="text-orange-600">{formatMoney(item.valor_icms)}</span>
                                ) : '-'}
                              </TableCell>
                              <TableCell className="text-right text-sm">
                                {item.valor_ipi > 0 ? (
                                  <span className="text-orange-600">{formatMoney(item.valor_ipi)}</span>
                                ) : '-'}
                              </TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </div>
                  </div>
                </CollapsibleContent>
              </Collapsible>

              {/* Botao de Importar */}
              {resultado?.tipo !== 'completo' && (
                <Button
                  onClick={processarImportacao}
                  disabled={processando}
                  className="w-full h-12 text-lg bg-green-700 hover:bg-green-800"
                >
                  {processando ? (
                    <>
                      <Loader2 className="w-5 h-5 mr-2 animate-spin" />
                      {etapaAtual || "Processando..."}
                    </>
                  ) : (
                    <>
                      <Plus className="w-5 h-5 mr-2" />
                      Confirmar Entrada
                    </>
                  )}
                </Button>
              )}

              {/* Resultado Final */}
              {resultado?.tipo === 'completo' && (
                <div className="space-y-3">
                  <Alert className="border-green-200 bg-green-50">
                    <CheckCircle2 className="h-5 w-5 text-green-600" />
                    <AlertDescription className="text-green-800 font-medium">
                      {resultado.texto}
                    </AlertDescription>
                  </Alert>
                  <div className="space-y-2">
                    {resultado.acoes?.map((acao, idx) => (
                      <div key={idx} className={`flex items-center gap-2 p-2 rounded text-sm ${acao.tipo === 'sucesso' ? 'bg-green-50 text-green-800' :
                        acao.tipo === 'atencao' ? 'bg-yellow-50 text-yellow-800' :
                          'bg-blue-50 text-blue-800'
                        }`}>
                        {acao.tipo === 'sucesso' ? <CheckCircle2 className="w-4 h-4" /> :
                          acao.tipo === 'atencao' ? <AlertCircle className="w-4 h-4" /> :
                            <Info className="w-4 h-4" />}
                        {acao.texto}
                      </div>
                    ))}
                  </div>
                  <Button
                    variant="outline"
                    onClick={() => {
                      setDadosCompletos(null);
                      setChaveAcesso("");
                      setResultado(null);
                    }}
                    className="w-full"
                  >
                    Importar Nova Nota
                  </Button>
                </div>
              )}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState, useEffect, useRef, useMemo } from "react";
import { normSearch } from "@/lib/utils";
import { base44, supabase } from "@/api/base44Client";
import { useQuery } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Progress } from "@/components/ui/progress";
import {
    ArrowLeft, ScanBarcode, Search, Save, CheckCircle2,
    Filter, Package, AlertTriangle, Loader2, ChevronDown, ChevronUp
} from "lucide-react";
import { toast } from "sonner";
import { obterCampoEstoqueDaLoja } from "@/constants/productConstants";

export default function InventarioContagem({ inventarioExistente, onVoltar, onSalvar, user }) {
    // --- State ---
    const [lojaId, setLojaId] = useState(inventarioExistente?.loja_id || "");
    const [responsavel, setResponsavel] = useState(inventarioExistente?.responsavel || user?.nome || "");
    const [observacoes, setObservacoes] = useState(inventarioExistente?.observacoes || "");
    const [dataInventario] = useState(
        inventarioExistente?.data_inventario || new Date().toISOString().split('T')[0]
    );

    // contagens: { [produto_id]: number | null }
    // null = não contado, number = contagem feita
    const [contagens, setContagens] = useState({});

    const [searchTerm, setSearchTerm] = useState("");
    const [categoriaFiltro, setCategoriaFiltro] = useState("todas");
    const [filtroContagem, setFiltroContagem] = useState("todos"); // todos | nao_contados | divergentes
    const [isSaving, setIsSaving] = useState(false);
    const [isInitialized, setIsInitialized] = useState(false);

    const barcodeRef = useRef(null);
    const inputRefs = useRef({});

    // --- Queries ---
    const { data: produtos = [], isLoading: loadingProdutos } = useQuery({
        queryKey: ['produtos-inventario'],
        queryFn: () => base44.entities.Produto.list(),
    });

    const { data: lojasData = [], isLoading: loadingLojas } = useQuery({
        queryKey: ['lojas'],
        queryFn: () => base44.entities.Loja.list('nome'),
    });

    const lojasAtivas = useMemo(() => lojasData.filter(l => l.ativa), [lojasData]);

    const getLojaField = (id) => {
        const loja = lojasData.find(l => l.id === id);
        return obterCampoEstoqueDaLoja(loja || id);
    };

    const getLojaDisplayName = (id) => {
        const loja = lojasData.find(l => l.id === id);
        return loja ? loja.nome : id;
    };

    const getEstoquePorLoja = (produto, id) => {
        const field = getLojaField(id);
        return produto[field] || 0;
    };

    // --- Initialize from existing inventory ---
    useEffect(() => {
        if (inventarioExistente && !isInitialized && produtos.length > 0) {
            // Reconstruct loja from data
            if (inventarioExistente.loja_id) {
                setLojaId(inventarioExistente.loja_id);
            }
            // Reconstruct contagens from itens_contados
            if (inventarioExistente.itens_contados?.length > 0) {
                const restored = {};
                inventarioExistente.itens_contados.forEach(item => {
                    restored[item.produto_id] = item.quantidade_contada;
                });
                setContagens(restored);
            }
            setIsInitialized(true);
        }
    }, [inventarioExistente, produtos, isInitialized]);

    // --- Derived data ---
    const produtosDaLoja = useMemo(() => {
        if (!lojaId) return [];
        return produtos.filter(p => {
            const estoque = getEstoquePorLoja(p, lojaId);
            return estoque > 0 || contagens[p.id] !== undefined;
        });
    }, [produtos, lojaId, contagens]);

    const categoriasDaLoja = useMemo(() => {
        const cats = [...new Set(produtosDaLoja.map(p => p.categoria).filter(Boolean))].sort();
        return cats;
    }, [produtosDaLoja]);

    const produtosFiltrados = useMemo(() => {
        let result = produtosDaLoja;

        if (categoriaFiltro !== "todas") {
            result = result.filter(p => p.categoria === categoriaFiltro);
        }

        if (searchTerm.trim()) {
            const terms = normSearch(searchTerm).split(/\s+/).filter(Boolean);
            result = result.filter(p => {
                const searchString = [p.nome, p.codigo_barras, p.modelo_referencia].filter(Boolean).map(normSearch).join(' ');
                return terms.every(term => searchString.includes(term));
            });
        }

        if (filtroContagem === "nao_contados") {
            result = result.filter(p => contagens[p.id] === undefined || contagens[p.id] === null);
        } else if (filtroContagem === "divergentes") {
            result = result.filter(p => {
                if (contagens[p.id] === undefined || contagens[p.id] === null) return false;
                return contagens[p.id] !== getEstoquePorLoja(p, lojaId);
            });
        }

        return result;
    }, [produtosDaLoja, categoriaFiltro, searchTerm, filtroContagem, contagens, lojaId]);

    // Stats
    const totalProdutos = produtosDaLoja.length;
    const totalContados = produtosDaLoja.filter(p => contagens[p.id] !== undefined && contagens[p.id] !== null).length;
    const totalDivergentes = produtosDaLoja.filter(p => {
        if (contagens[p.id] === undefined || contagens[p.id] === null) return false;
        return contagens[p.id] !== getEstoquePorLoja(p, lojaId);
    }).length;
    const progresso = totalProdutos > 0 ? Math.round((totalContados / totalProdutos) * 100) : 0;

    // --- Handlers ---
    const handleContagemChange = (produtoId, value) => {
        const num = value === "" ? null : parseInt(value);
        setContagens(prev => ({
            ...prev,
            [produtoId]: num !== null && !isNaN(num) ? num : (value === "" ? null : prev[produtoId])
        }));
    };

    const handleBarcodeSubmit = (e) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            const code = e.target.value.trim();
            if (!code) return;

            const produto = produtos.find(p => p.codigo_barras === code);
            if (produto) {
                // Focus the counting input for this product
                const inputEl = inputRefs.current[produto.id];
                if (inputEl) {
                    inputEl.focus();
                    inputEl.select();
                    toast.success(`📦 ${produto.nome}`);
                } else {
                    // Product exists but not in current store filter
                    toast.warning(`Produto "${produto.nome}" encontrado mas sem estoque nesta loja.`);
                }
            } else {
                toast.error("Produto não encontrado com este código de barras.");
            }
            e.target.value = "";
        }
    };

    const buildItens = () => {
        return produtosDaLoja
            .filter(p => contagens[p.id] !== undefined && contagens[p.id] !== null)
            .map(p => {
                const qtdSistema = getEstoquePorLoja(p, lojaId);
                const qtdContada = contagens[p.id];
                return {
                    produto_id: p.id,
                    produto_nome: p.nome,
                    quantidade_sistema: qtdSistema,
                    quantidade_contada: qtdContada,
                    diferenca: qtdContada - qtdSistema,
                };
            });
    };

    const handleSalvar = async (finalizar = false) => {
        if (!lojaId || !responsavel) {
            toast.error("Preencha a loja e o responsável.");
            return;
        }

        const itens = buildItens();
        if (finalizar && itens.length === 0) {
            toast.error("Conte pelo menos um produto antes de finalizar.");
            return;
        }

        setIsSaving(true);
        try {
            const data = {
                numero_inventario: inventarioExistente?.numero_inventario || `INV-${Date.now()}`,
                loja: getLojaDisplayName(lojaId),
                loja_id: lojaId,
                data_inventario: dataInventario,
                responsavel,
                itens_contados: itens,
                total_itens: itens.length,
                total_divergencias: itens.filter(i => i.diferenca !== 0).length,
                status: finalizar ? "Concluído" : "Em Andamento",
                observacoes,
            };

            await onSalvar(data, inventarioExistente?.id);
            toast.success(finalizar ? "Inventário finalizado!" : "Inventário salvo. Pode continuar depois.");
        } catch (err) {
            console.error(err);
            toast.error("Erro ao salvar: " + err.message);
        } finally {
            setIsSaving(false);
        }
    };

    // --- Phase 1: Store selection ---
    if (!lojaId) {
        return (
            <div className="space-y-6">
                <div className="flex items-center gap-3">
                    <Button variant="ghost" size="icon" onClick={onVoltar}>
                        <ArrowLeft className="w-5 h-5" />
                    </Button>
                    <h2 className="text-xl font-bold" style={{ color: '#07593f' }}>
                        Novo Inventário — Selecionar Local
                    </h2>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 max-w-4xl">
                    {loadingLojas ? (
                        <div className="col-span-full text-center py-8 text-gray-500">
                            <Loader2 className="w-8 h-8 animate-spin mx-auto mb-2" />
                            Carregando lojas ativas...
                        </div>
                    ) : lojasAtivas.length === 0 ? (
                        <div className="col-span-full text-center py-8 text-gray-500 bg-white border rounded-lg">
                            <p>Nenhuma loja ativa cadastrada.</p>
                            <p className="text-sm mt-1">Acesse as Configurações para adicionar lojas antes de iniciar um inventário.</p>
                        </div>
                    ) : lojasAtivas.map(loja => {
                        const field = obterCampoEstoqueDaLoja(loja);
                        const qtdProdutos = produtos.filter(p => (p[field] || 0) > 0).length;
                        return (
                            <Card
                                key={loja.id}
                                className="border-2 cursor-pointer transition-all hover:shadow-lg hover:border-green-400 active:scale-[0.98]"
                                style={{ borderColor: '#E5E0D8' }}
                                onClick={() => setLojaId(loja.id)}
                            >
                                <CardContent className="p-6 text-center">
                                    <div
                                        className="w-14 h-14 rounded-full mx-auto mb-3 flex items-center justify-center"
                                        style={{ backgroundColor: '#DBEAFE' }}
                                    >
                                        <Package className="w-7 h-7" style={{ color: '#1E40AF' }} />
                                    </div>
                                    <h3 className="font-bold text-lg mb-1" style={{ color: '#07593f' }}>{loja.nome}</h3>
                                    <p className="text-sm" style={{ color: '#8B8B8B' }}>
                                        {loadingProdutos ? '...' : `${qtdProdutos} produtos com estoque`}
                                    </p>
                                    <Badge className="mt-2" variant="secondary">
                                        Unidade
                                    </Badge>
                                </CardContent>
                            </Card>
                        );
                    })}
                </div>
            </div>
        );
    }

    // --- Phase 2: Counting screen ---
    return (
        <div className="space-y-4">
            {/* Header */}
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
                <div className="flex items-center gap-3">
                    <Button variant="ghost" size="icon" onClick={onVoltar}>
                        <ArrowLeft className="w-5 h-5" />
                    </Button>
                    <div>
                        <h2 className="text-xl font-bold" style={{ color: '#07593f' }}>
                            Inventário — {getLojaDisplayName(lojaId)}
                        </h2>
                        <p className="text-sm" style={{ color: '#8B8B8B' }}>
                            {dataInventario} • {responsavel || 'Sem responsável'}
                        </p>
                    </div>
                </div>
                <div className="flex gap-2">
                    <Button
                        variant="outline"
                        onClick={() => handleSalvar(false)}
                        disabled={isSaving}
                    >
                        <Save className="w-4 h-4 mr-2" />
                        Salvar Parcial
                    </Button>
                    <Button
                        onClick={() => handleSalvar(true)}
                        disabled={isSaving}
                        style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
                    >
                        {isSaving ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <CheckCircle2 className="w-4 h-4 mr-2" />}
                        Finalizar Inventário
                    </Button>
                </div>
            </div>

            {/* Responsável + Obs */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                    <Label>Responsável pela Contagem *</Label>
                    <Input
                        value={responsavel}
                        onChange={(e) => setResponsavel(e.target.value)}
                        placeholder="Nome do responsável"
                    />
                </div>
                <div>
                    <Label>Observações</Label>
                    <Input
                        value={observacoes}
                        onChange={(e) => setObservacoes(e.target.value)}
                        placeholder="Notas opcionais..."
                    />
                </div>
            </div>

            {/* Progress bar */}
            <Card className="border-0 shadow-sm" style={{ backgroundColor: '#f0f9ff' }}>
                <CardContent className="p-4">
                    <div className="flex justify-between items-center mb-2">
                        <span className="text-sm font-medium" style={{ color: '#07593f' }}>
                            Progresso da Contagem
                        </span>
                        <span className="text-sm font-bold" style={{ color: '#07593f' }}>
                            {totalContados} / {totalProdutos} produtos ({progresso}%)
                        </span>
                    </div>
                    <Progress value={progresso} className="h-3" />
                    <div className="flex gap-4 mt-2 text-xs" style={{ color: '#8B8B8B' }}>
                        <span>✅ {totalContados} contados</span>
                        <span>⚠️ {totalDivergentes} divergências</span>
                        <span>📦 {totalProdutos - totalContados} pendentes</span>
                    </div>
                </CardContent>
            </Card>

            {/* Barcode + Search + Filters */}
            <div className="flex flex-col sm:flex-row gap-3">
                {/* Barcode */}
                <div className="relative flex-1 sm:max-w-xs">
                    <ScanBarcode className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4" style={{ color: '#8B8B8B' }} />
                    <Input
                        ref={barcodeRef}
                        className="pl-10"
                        placeholder="Bipar código de barras..."
                        onKeyDown={handleBarcodeSubmit}
                    />
                </div>

                {/* Search */}
                <div className="relative flex-1">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4" style={{ color: '#8B8B8B' }} />
                    <Input
                        className="pl-10"
                        placeholder="Buscar por nome, código ou referência..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                </div>

                {/* Category filter */}
                <Select value={categoriaFiltro} onValueChange={setCategoriaFiltro}>
                    <SelectTrigger className="w-full sm:w-48">
                        <Filter className="w-4 h-4 mr-2" style={{ color: '#8B8B8B' }} />
                        <SelectValue placeholder="Categoria" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="todas">Todas Categorias</SelectItem>
                        {categoriasDaLoja.map(cat => (
                            <SelectItem key={cat} value={cat}>{cat}</SelectItem>
                        ))}
                    </SelectContent>
                </Select>

                {/* Count status filter */}
                <Select value={filtroContagem} onValueChange={setFiltroContagem}>
                    <SelectTrigger className="w-full sm:w-44">
                        <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="todos">Todos</SelectItem>
                        <SelectItem value="nao_contados">Não Contados</SelectItem>
                        <SelectItem value="divergentes">Divergentes</SelectItem>
                    </SelectContent>
                </Select>
            </div>

            {/* Products Table */}
            {loadingProdutos ? (
                <div className="text-center py-16">
                    <Loader2 className="w-10 h-10 animate-spin mx-auto mb-3" style={{ color: '#07593f' }} />
                    <p style={{ color: '#8B8B8B' }}>Carregando produtos...</p>
                </div>
            ) : produtosFiltrados.length === 0 ? (
                <div className="text-center py-16">
                    <Package className="w-12 h-12 mx-auto mb-3" style={{ color: '#C0C0C0' }} />
                    <p style={{ color: '#8B8B8B' }}>
                        {totalProdutos === 0
                            ? "Nenhum produto com estoque nesta loja."
                            : "Nenhum produto corresponde aos filtros."
                        }
                    </p>
                </div>
            ) : (
                <div className="border rounded-xl overflow-hidden" style={{ borderColor: '#E5E0D8' }}>
                    {/* Table header */}
                    <div
                        className="grid grid-cols-12 gap-2 px-4 py-3 text-xs font-semibold uppercase tracking-wider"
                        style={{ backgroundColor: '#FAF8F5', color: '#8B8B8B' }}
                    >
                        <div className="col-span-5 sm:col-span-4">Produto</div>
                        <div className="col-span-2 hidden sm:block">Categoria</div>
                        <div className="col-span-2 text-center">Sistema</div>
                        <div className="col-span-3 text-center">Contagem</div>
                        <div className="col-span-2 sm:col-span-1 text-center">Dif.</div>
                    </div>

                    {/* Table body */}
                    <div className="divide-y" style={{ borderColor: '#F0EDE8' }}>
                        {produtosFiltrados.map(produto => {
                            const qtdSistema = getEstoquePorLoja(produto, lojaId);
                            const contagem = contagens[produto.id];
                            const isContado = contagem !== undefined && contagem !== null;
                            const diferenca = isContado ? contagem - qtdSistema : null;
                            const hasDivergencia = diferenca !== null && diferenca !== 0;

                            return (
                                <div
                                    key={produto.id}
                                    className="grid grid-cols-12 gap-2 px-4 py-3 items-center transition-colors"
                                    style={{
                                        backgroundColor: hasDivergencia ? '#FEF3C7' : isContado ? '#F0FDF4' : '#FFFFFF',
                                    }}
                                >
                                    {/* Product info */}
                                    <div className="col-span-5 sm:col-span-4">
                                        <p className="font-medium text-sm leading-tight" style={{ color: '#1a1a1a' }}>
                                            {produto.nome}
                                        </p>
                                        <p className="text-xs mt-0.5" style={{ color: '#8B8B8B' }}>
                                            {produto.modelo_referencia && <span>{produto.modelo_referencia} • </span>}
                                            {produto.codigo_barras && <span>COD: {produto.codigo_barras}</span>}
                                        </p>
                                    </div>

                                    {/* Category */}
                                    <div className="col-span-2 hidden sm:block">
                                        <Badge variant="secondary" className="text-xs font-normal">
                                            {produto.categoria || '-'}
                                        </Badge>
                                    </div>

                                    {/* System stock */}
                                    <div className="col-span-2 text-center">
                                        <span className="font-semibold text-sm" style={{ color: '#07593f' }}>
                                            {qtdSistema}
                                        </span>
                                    </div>

                                    {/* Count input */}
                                    <div className="col-span-3 flex justify-center">
                                        <Input
                                            ref={el => { if (el) inputRefs.current[produto.id] = el; }}
                                            type="number"
                                            min="0"
                                            className="w-20 text-center font-bold text-lg h-10"
                                            style={{
                                                borderColor: isContado ? (hasDivergencia ? '#F59E0B' : '#10B981') : '#E5E0D8',
                                                backgroundColor: isContado ? '#FFFFFF' : '#F9FAFB',
                                            }}
                                            value={contagem ?? ""}
                                            onChange={(e) => handleContagemChange(produto.id, e.target.value)}
                                            onFocus={(e) => e.target.select()}
                                            placeholder="—"
                                        />
                                    </div>

                                    {/* Difference */}
                                    <div className="col-span-2 sm:col-span-1 text-center">
                                        {isContado ? (
                                            <span
                                                className="font-bold text-sm"
                                                style={{
                                                    color: diferenca === 0 ? '#10B981' : diferenca > 0 ? '#F59E0B' : '#EF4444'
                                                }}
                                            >
                                                {diferenca === 0 ? '✓' : (diferenca > 0 ? `+${diferenca}` : diferenca)}
                                            </span>
                                        ) : (
                                            <span className="text-xs" style={{ color: '#C0C0C0' }}>—</span>
                                        )}
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* Sticky footer */}
            <div
                className="sticky bottom-0 p-4 rounded-xl shadow-lg border flex flex-col sm:flex-row items-center justify-between gap-3"
                style={{ backgroundColor: '#FFFFFF', borderColor: '#E5E0D8' }}
            >
                <div className="flex gap-6 text-sm">
                    <span>
                        <strong style={{ color: '#07593f' }}>{totalContados}</strong>
                        <span style={{ color: '#8B8B8B' }}> / {totalProdutos} contados</span>
                    </span>
                    {totalDivergentes > 0 && (
                        <span className="flex items-center gap-1">
                            <AlertTriangle className="w-4 h-4 text-orange-500" />
                            <strong className="text-orange-600">{totalDivergentes}</strong>
                            <span style={{ color: '#8B8B8B' }}> divergências</span>
                        </span>
                    )}
                </div>
                <div className="flex gap-2">
                    <Button
                        variant="outline"
                        onClick={() => handleSalvar(false)}
                        disabled={isSaving}
                    >
                        <Save className="w-4 h-4 mr-2" />
                        Salvar Parcial
                    </Button>
                    <Button
                        onClick={() => {
                            if (confirm(`Finalizar inventário?\n\n${totalContados} produtos contados, ${totalDivergentes} divergências.\n\nA contagem será enviada para aprovação.`)) {
                                handleSalvar(true);
                            }
                        }}
                        disabled={isSaving || totalContados === 0}
                        style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
                    >
                        {isSaving ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <CheckCircle2 className="w-4 h-4 mr-2" />}
                        Finalizar Inventário
                    </Button>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Loader2, Trash2, Check, ChevronsUpDown, ScanBarcode, Search } from "lucide-react";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { useLojas } from "@/hooks/useLojas";
import { obterCampoEstoqueDaLoja } from "@/constants/productConstants";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import { buildProductDisplayName } from "@/utils/productReference";

// lojas constant removed to use dynamic data from useLojas

export default function InventarioModal({ isOpen, onClose, onSave, produtos, isLoading, userLoja }) {
  const { data: lojasData = [], isLoading: loadingLojas } = useLojas();
  const lojasAtivas = lojasData; // useLojas already filters active stores

  const [formData, setFormData] = useState({
    numero_inventario: "",
    loja: userLoja || "",
    data_inventario: new Date().toISOString().split('T')[0],
    responsavel: "",
    itens: [],
    total_itens: 0,
    total_divergencias: 0,
    status: "Concluído",
    observacoes: "",
  });

  const [produtoSelecionado, setProdutoSelecionado] = useState("");
  const [quantidadeContada, setQuantidadeContada] = useState(0);
  const [barcodeInput, setBarcodeInput] = useState("");
  const [openCombobox, setOpenCombobox] = useState(false);

  useEffect(() => {
    if (isOpen) {
      const numeroInv = `INV-${Date.now()}`;
      setFormData({
        numero_inventario: numeroInv,
        loja: userLoja || "",
        data_inventario: new Date().toISOString().split('T')[0],
        responsavel: "",
        itens: [],
        total_itens: 0,
        total_divergencias: 0,
        status: "Concluído",
        observacoes: "",
      });
      setProdutoSelecionado("");
      setQuantidadeContada(0);
      setBarcodeInput("");
    }
  }, [isOpen, userLoja]);

  const handleBarcodeSubmit = (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      const code = barcodeInput.trim();
      if (!code) return;

      const produto = produtos.find(p => p.codigo_barras === code);
      if (produto) {
        if (formData.itens.some(i => i.produto_id === produto.id)) {
          toast.warning("Produto já adicionado à lista. Edite a quantidade se necessário.");
          // Optional: Highlight existing item
        } else {
          setProdutoSelecionado(produto.id);
          toast.success(`Produto encontrado: ${produto.nome}`);
          // Focus quantity input if possible, or just let user type
          document.getElementById('qtd-input')?.focus();
        }
      } else {
        toast.error("Produto não encontrado com este código de barras.");
      }
      setBarcodeInput(""); // Clear input for next scan
    }
  };

  const adicionarItem = () => {
    if (!produtoSelecionado || quantidadeContada < 0) {
      alert("Selecione um produto e informe a quantidade contada");
      return;
    }

    const produto = produtos.find(p => p.id === produtoSelecionado);
    if (!produto) return;

    // Verificar se já foi adicionado
    if (formData.itens.some(i => i.produto_id === produtoSelecionado)) {
      alert("Este produto já foi adicionado ao inventário");
      return;
    }

    const getEstoquePorLoja = (prod, lojaNome) => {
      const lojaObj = lojasAtivas.find(l => l.nome === lojaNome);
      if (!lojaObj) return prod.quantidade_estoque || 0;
      
      const campo = obterCampoEstoqueDaLoja(lojaObj);
      return prod[campo] || 0;
    };

    const qtdSistema = getEstoquePorLoja(produto, formData.loja);

    const novoItem = {
      produto_id: produto.id,
      produto_nome: buildProductDisplayName(produto.nome, produto.modelo_referencia),
      quantidade_sistema: qtdSistema,
      quantidade_contada: quantidadeContada,
      diferenca: quantidadeContada - qtdSistema,
      justificativa: ""
    };

    const novosItens = [...formData.itens, novoItem];
    const totalDivergencias = novosItens.filter(i => i.diferenca !== 0).length;

    setFormData({
      ...formData,
      itens: novosItens,
      total_itens: novosItens.length,
      total_divergencias: totalDivergencias
    });

    setProdutoSelecionado("");
    setQuantidadeContada(0);
  };

  const removerItem = (index) => {
    const novosItens = formData.itens.filter((_, i) => i !== index);
    const totalDivergencias = novosItens.filter(i => i.diferenca !== 0).length;

    setFormData({
      ...formData,
      itens: novosItens,
      total_itens: novosItens.length,
      total_divergencias: totalDivergencias
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!formData.loja || !formData.responsavel || formData.itens.length === 0) {
      alert("Preencha todos os campos e adicione pelo menos um produto");
      return;
    }

    onSave(formData);
  };

  const produtosDisponiveis = produtos.filter(
    p => !formData.itens.some(i => i.produto_id === p.id)
  );

  const selectedProductDetails = produtos.find(p => p.id === produtoSelecionado);

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle style={{ color: '#07593f' }}>
            Novo Inventário
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit}>
          <div className="space-y-4">
            <Alert style={{ backgroundColor: '#f0f9ff', borderColor: '#3b82f6' }}>
              <AlertDescription>
                Conte fisicamente o estoque e registre as quantidades. O sistema calculará as diferenças automaticamente.
              </AlertDescription>
            </Alert>

            <div className="grid md:grid-cols-3 gap-4">
              <div>
                <Label>Número do Inventário</Label>
                <Input value={formData.numero_inventario} disabled />
              </div>
              <div>
                <Label htmlFor="loja">Loja *</Label>
                <Select
                  value={formData.loja}
                  onValueChange={(value) => setFormData({ ...formData, loja: value })}
                  disabled={!!userLoja}
                  required
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {loadingLojas ? (
                      <div className="p-2 text-center text-xs text-gray-500">Carregando lojas...</div>
                    ) : (
                      lojasAtivas.map(loja => (
                        <SelectItem key={loja.id} value={loja.nome}>{loja.nome}</SelectItem>
                      ))
                    )}
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label htmlFor="data">Data *</Label>
                <Input
                  id="data"
                  type="date" lang="pt-BR"
                  value={formData.data_inventario}
                  onChange={(e) => setFormData({ ...formData, data_inventario: e.target.value })}
                  required
                />
              </div>
            </div>

            <div>
              <Label htmlFor="responsavel">Responsável pela Contagem *</Label>
              <Input
                id="responsavel"
                value={formData.responsavel}
                onChange={(e) => setFormData({ ...formData, responsavel: e.target.value })}
                placeholder="Nome do responsável"
                required
              />
            </div>

            <div className="border rounded-xl p-4" style={{ borderColor: '#E5E0D8', backgroundColor: '#f0f9ff' }}>
              <h4 className="font-semibold mb-4 flex items-center gap-2" style={{ color: '#07593f' }}>
                <ScanBarcode className="w-5 h-5" />
                Adicionar Produto
              </h4>

              {/* Barcode Input */}
              <div className="mb-4">
                <Label htmlFor="barcode">Bipar Código de Barras (Enter para buscar)</Label>
                <div className="flex gap-2">
                  <Input
                    id="barcode"
                    value={barcodeInput}
                    onChange={(e) => setBarcodeInput(e.target.value)}
                    onKeyDown={handleBarcodeSubmit}
                    placeholder="Escaneie ou digite o código..."
                    className="bg-white"
                    autoFocus
                  />
                  <Button type="button" variant="secondary" onClick={() => handleBarcodeSubmit({ key: 'Enter', preventDefault: () => { } })}>
                    <Search className="w-4 h-4" />
                  </Button>
                </div>
              </div>

              <div className="grid md:grid-cols-12 gap-3 items-end">
                <div className="md:col-span-8 flex flex-col gap-1.5">
                  <Label>Buscar Produto (Nome ou Código)</Label>
                  <Popover open={openCombobox} onOpenChange={setOpenCombobox}>
                    <PopoverTrigger asChild>
                      <Button
                        variant="outline"
                        role="combobox"
                        aria-expanded={openCombobox}
                        className="w-full justify-between bg-white"
                      >
                        {produtoSelecionado
                          ? (() => { const p = produtos.find((p) => p.id === produtoSelecionado); return p ? `${p.nome}${p.modelo_referencia ? ` (${p.modelo_referencia})` : ''}` : 'Selecione um produto...'; })()
                          : "Selecione um produto..."}
                        <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                      </Button>
                    </PopoverTrigger>
                    <PopoverContent className="w-[400px] p-0" align="start">
                      <Command>
                        <CommandInput placeholder="Buscar produto..." />
                        <CommandList>
                          <CommandEmpty>Nenhum produto encontrado.</CommandEmpty>
                          <CommandGroup>
                            {produtosDisponiveis.map((produto) => (
                              <CommandItem
                                key={produto.id}
                                value={produto.nome}
                                onSelect={() => {
                                  setProdutoSelecionado(produto.id === produtoSelecionado ? "" : produto.id);
                                  setOpenCombobox(false);
                                }}
                              >
                                <Check
                                  className={cn(
                                    "mr-2 h-4 w-4",
                                    produtoSelecionado === produto.id ? "opacity-100" : "opacity-0"
                                  )}
                                />
                                {produto.nome}{produto.modelo_referencia ? ` (${produto.modelo_referencia})` : ''}
                              </CommandItem>
                            ))}
                          </CommandGroup>
                        </CommandList>
                      </Command>
                    </PopoverContent>
                  </Popover>
                  {selectedProductDetails && (
                    <p className="text-xs text-muted-foreground mt-1">
                      Estoque Atual: <strong>{selectedProductDetails.quantidade_estoque || 0}</strong>
                    </p>
                  )}
                </div>
                <div className="md:col-span-3">
                  <Label htmlFor="qtd-input">Quantidade Contada</Label>
                  <Input
                    id="qtd-input"
                    type="number"
                    min="0"
                    value={quantidadeContada}
                    onChange={(e) => setQuantidadeContada(parseInt(e.target.value) || 0)}
                    className="bg-white"
                  />
                </div>
                <div className="md:col-span-1">
                  <Button
                    type="button"
                    onClick={adicionarItem}
                    disabled={!produtoSelecionado}
                    className="w-full"
                    style={{ background: 'linear-gradient(135deg, #f38a4c 0%, #f5a164 100%)' }}
                  >
                    +
                  </Button>
                </div>
              </div>
            </div>

            {formData.itens.length > 0 && (
              <div className="space-y-2">
                <h5 className="font-medium" style={{ color: '#07593f' }}>
                  Produtos Contados ({formData.itens.length})
                </h5>
                {formData.itens.map((item, index) => (
                  <div
                    key={index}
                    className="flex items-center justify-between p-3 rounded-lg border"
                    style={{
                      borderColor: item.diferenca !== 0 ? '#FCD34D' : '#E5E0D8',
                      backgroundColor: item.diferenca !== 0 ? '#FEF3C7' : '#FAF8F5'
                    }}
                  >
                    <div className="flex-1">
                      <p className="font-medium" style={{ color: '#07593f' }}>
                        {item.produto_nome}
                      </p>
                      <p className="text-sm" style={{ color: '#8B8B8B' }}>
                        Sistema: {item.quantidade_sistema} | Contado: {item.quantidade_contada} |
                        Diferença: <strong className={item.diferenca !== 0 ? 'text-orange-600' : ''}>
                          {item.diferenca > 0 ? '+' : ''}{item.diferenca}
                        </strong>
                      </p>
                    </div>
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={() => removerItem(index)}
                      className="text-red-600 hover:text-red-700"
                    >
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </div>
                ))}
              </div>
            )}

            <div className="p-3 rounded-lg" style={{ backgroundColor: '#D1FAE5' }}>
              <div className="flex justify-between">
                <span className="font-medium">Total de Itens:</span>
                <span className="font-bold" style={{ color: '#07593f' }}>{formData.total_itens}</span>
              </div>
              <div className="flex justify-between mt-2">
                <span className="font-medium">Divergências:</span>
                <span className="font-bold text-orange-600">{formData.total_divergencias}</span>
              </div>
            </div>

            <div>
              <Label htmlFor="observacoes">Observações</Label>
              <Textarea
                id="observacoes"
                value={formData.observacoes}
                onChange={(e) => setFormData({ ...formData, observacoes: e.target.value })}
                rows={3}
              />
            </div>
          </div>

          <DialogFooter className="mt-6">
            <Button type="button" variant="outline" onClick={onClose}>
              Cancelar
            </Button>
            <Button
              type="submit"
              disabled={isLoading || formData.itens.length === 0}
              style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
            >
              {isLoading ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Salvando...
                </>
              ) : (
                "Salvar Inventário"
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from "react";
import { useAuth } from "@/hooks/useAuth";

import { base44, supabase } from "@/api/base44Client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Plus, Check, AlertTriangle, Play, Eye } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { obterCampoEstoqueDaLoja } from "@/constants/productConstants";
import InventarioContagem from "./InventarioContagem";
import CargaInicialEstoque from "./CargaInicialEstoque";
import LancamentoManualEstoque from "./LancamentoManualEstoque";

export default function InventarioTab({ user }) {
  const [modoContagem, setModoContagem] = useState(false);
  const [modoCargaInicial, setModoCargaInicial] = useState(false);
  const [modoLancamentoManual, setModoLancamentoManual] = useState(false);
  const [inventarioEditando, setInventarioEditando] = useState(null);

  const queryClient = useQueryClient();

  const { data: inventarios = [], isLoading } = useQuery({
    queryKey: ['inventarios'],
    queryFn: () => base44.entities.Inventario.list('-created_date'),
  });

  const { data: produtos } = useQuery({
    queryKey: ['produtos'],
    queryFn: () => base44.entities.Produto.list(),
  });

  const { data: lojas = [] } = useQuery({
    queryKey: ['lojas'],
    queryFn: () => base44.entities.Loja.list(),
  });

  const aprovarMutation = useMutation({
    mutationFn: async ({ inventario }) => {
      const lojaInventario = lojas.find(l => l.id === inventario.loja_id);
      const targetField = obterCampoEstoqueDaLoja(lojaInventario || inventario.loja_id);

      for (const item of inventario.itens_contados) {
        if (item.diferenca !== 0) {
          const produto = produtos.find(p => p.id === item.produto_id);
          if (produto && targetField) {
            const currentValues = {};

            // Collect all stock fields dynamically based on active stores 
            // plus the target field if it's new
            const activeStoreFields = new Set(lojas.filter(l => l.ativa).map(l => obterCampoEstoqueDaLoja(l)));
            activeStoreFields.add(targetField); // Ensure current target is included

            activeStoreFields.forEach(field => {
              currentValues[field] = produto[field] || 0;
            });

            // Update specific store value
            currentValues[targetField] = item.quantidade_contada;

            // Recalculate total
            const newTotal = Object.values(currentValues).reduce((sum, val) => sum + val, 0);

            await base44.entities.Produto.update(produto.id, {
              [targetField]: item.quantidade_contada,
              quantidade_estoque: newTotal
            });
            try {
              await supabase.from('movimentacoes_estoque').insert({
                produto_id: produto.id,
                evento_tipo: 'inventario',
                modulo_origem: 'estoque',
                quantidade: Math.abs(item.diferenca),
                estoque_antes_local: produto[targetField] || 0,
                estoque_depois_local: item.quantidade_contada,
                estoque_antes_total: produto.quantidade_estoque || 0,
                estoque_depois_total: newTotal,
                referencia_id: inventario.id,
                referencia_numero: inventario.numero_inventario?.toString() || null,
                usuario_nome: user?.email || null,
                loja_origem: lojaInventario?.nome || null,
                organization_id: '00000000-0000-0000-0000-000000000001'
              });
            } catch (auditErr) {
              console.warn('Falha ao registrar movimentação de inventário:', auditErr);
            }
          }
        }
      }

      await base44.entities.Inventario.update(inventario.id, {
        ...inventario,
        status: 'Aprovado',
        aprovado_por: user.email,
        data_aprovacao: new Date().toISOString()
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['inventarios'] });
      queryClient.invalidateQueries({ queryKey: ['produtos'] });
      toast.success("Inventário aprovado e estoque atualizado!");
    },
  });

  const handleSalvar = async (data, existingId) => {
    if (existingId) {
      await base44.entities.Inventario.update(existingId, data);
    } else {
      await base44.entities.Inventario.create(data);
    }
    queryClient.invalidateQueries({ queryKey: ['inventarios'] });
    setModoContagem(false);
    setInventarioEditando(null);
  };

  const handleAprovar = (inventario) => {
    if (confirm(`Aprovar inventário #${inventario.numero_inventario}?\n\nOs ajustes de estoque serão aplicados.`)) {
      aprovarMutation.mutate({ inventario });
    }
  };

  const handleContinuar = (inventario) => {
    setInventarioEditando(inventario);
    setModoContagem(true);
  };

  const { can } = useAuth();
  const isAdmin = user?.cargo === 'Administrador';
  const isManager = user?.cargo === 'Gerente';
  const isWarehouse = user?.cargo === 'Estoque';
  const isGerenteGeral = user?.cargo === 'Gerente Geral';
  const canManage = isAdmin || isManager || isWarehouse || isGerenteGeral || can('manage_estoque');
  const canApprove = isAdmin || isManager || isGerenteGeral;


  const statusColors = {
    "Em Andamento": { bg: "#FEF3C7", text: "#92400E", icon: "🔄" },
    "Concluído": { bg: "#DBEAFE", text: "#1E40AF", icon: "📋" },
    "Aprovado": { bg: "#D1FAE5", text: "#065F46", icon: "✅" },
    "Cancelado": { bg: "#FEE2E2", text: "#991B1B", icon: "❌" }
  };

  // --- Carga Inicial mode ---
  if (modoCargaInicial) {
    return (
      <CargaInicialEstoque
        onVoltar={() => setModoCargaInicial(false)}
      />
    );
  }

  if (modoLancamentoManual) {
    return (
      <LancamentoManualEstoque
        onVoltar={() => setModoLancamentoManual(false)}
        user={user}
      />
    );
  }

  // --- Counting mode ---
  if (modoContagem) {
    return (
      <InventarioContagem
        inventarioExistente={inventarioEditando}
        onVoltar={() => {
          setModoContagem(false);
          setInventarioEditando(null);
        }}
        onSalvar={handleSalvar}
        user={user}
      />
    );
  }

  // --- List mode ---
  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <p style={{ color: '#8B8B8B' }}>
          {inventarios.length} inventário(s) registrado(s)
        </p>
        {canManage && (
          <div className="flex gap-2">
            <Button
              onClick={() => setModoCargaInicial(true)}
              variant="outline"
              className="shadow border-2"
              style={{ borderColor: '#07593f', color: '#07593f' }}
            >
              📦 Carga Inicial de Estoque
            </Button>
            <Button
              onClick={() => setModoLancamentoManual(true)}
              variant="outline"
              className="shadow border-2"
              style={{ borderColor: '#f38a4c', color: '#c75f1a' }}
            >
              <Plus className="w-4 h-4 mr-2" />
              Lançamento Manual
            </Button>
            <Button
              onClick={() => {
                setInventarioEditando(null);
                setModoContagem(true);
              }}
              className="shadow-lg"
              style={{ background: 'linear-gradient(135deg, #f38a4c 0%, #f5a164 100%)' }}
            >
              <Plus className="w-4 h-4 mr-2" />
              Novo Inventário
            </Button>
          </div>
        )}
      </div>

      <Alert style={{ backgroundColor: '#f0f9ff', borderColor: '#3b82f6' }}>
        <AlertDescription>
          <strong>💡 Como funciona:</strong> Selecione a loja/CD, conte os produtos fisicamente
          digitando as quantidades. O sistema calcula divergências automaticamente.
          Após finalizar, um administrador ou gerente deve aprovar para ajustar o estoque.
        </AlertDescription>
      </Alert>

      <Alert style={{ backgroundColor: '#fff7ed', borderColor: '#fdba74' }}>
        <AlertDescription>
          <strong>📝 Lançamento manual:</strong> use esta opção para ajustes rápidos em massa, sem bipagem.
          Cada linha atualiza o estoque direto e fica registrada no histórico.
        </AlertDescription>
      </Alert>

      {isLoading ? (
        <div className="text-center py-12">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 mx-auto" style={{ borderColor: '#07593f' }} />
        </div>
      ) : (
        <div className="grid grid-cols-1 gap-4">
          {inventarios.map((inventario) => (
            <Card key={inventario.id} className="border-0 shadow-md hover:shadow-lg transition-shadow">
              <CardHeader className="pb-3">
                <div className="flex items-start justify-between">
                  <div>
                    <CardTitle className="flex items-center gap-2">
                      <span style={{ color: '#07593f' }}>
                        Inventário #{inventario.numero_inventario}
                      </span>
                      <Badge
                        style={{
                          backgroundColor: statusColors[inventario.status]?.bg,
                          color: statusColors[inventario.status]?.text,
                        }}
                      >
                        {statusColors[inventario.status]?.icon} {inventario.status}
                      </Badge>
                    </CardTitle>
                    <p className="text-sm mt-1" style={{ color: '#8B8B8B' }}>
                      {inventario.loja} • {new Date(inventario.data_inventario).toLocaleDateString('pt-BR')}
                    </p>
                  </div>
                  <div className="flex gap-2">
                    {inventario.status === 'Em Andamento' && canManage && (
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => handleContinuar(inventario)}
                        style={{ borderColor: '#F59E0B', color: '#92400E' }}
                      >
                        <Play className="w-4 h-4 mr-2" />
                        Continuar
                      </Button>
                    )}
                    {inventario.status === 'Concluído' && canApprove && (
                      <Button
                        size="sm"
                        onClick={() => handleAprovar(inventario)}
                        disabled={aprovarMutation.isPending}
                        style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
                      >
                        <Check className="w-4 h-4 mr-2" />
                        Aprovar e Ajustar Estoque
                      </Button>
                    )}
                  </div>
                </div>
              </CardHeader>
              <CardContent className="pt-0">
                <div className="grid grid-cols-3 gap-6 mb-4">
                  <div>
                    <p className="text-xs font-medium mb-0.5" style={{ color: '#8B8B8B' }}>Responsável</p>
                    <p className="font-semibold text-sm" style={{ color: '#07593f' }}>
                      {inventario.responsavel}
                    </p>
                  </div>
                  <div>
                    <p className="text-xs font-medium mb-0.5" style={{ color: '#8B8B8B' }}>Total de Itens</p>
                    <p className="font-semibold text-sm" style={{ color: '#07593f' }}>
                      {inventario.total_itens || 0}
                    </p>
                  </div>
                  <div>
                    <p className="text-xs font-medium mb-0.5" style={{ color: '#8B8B8B' }}>Divergências</p>
                    <p className="font-semibold text-sm text-orange-600">
                      {inventario.total_divergencias || 0}
                    </p>
                  </div>
                </div>

                {/* Divergence details (collapsed by default for Concluído/Aprovado) */}
                {inventario.itens_contados && inventario.itens_contados.length > 0 && (
                  <ItensResumo itens={inventario.itens_contados} />
                )}

                {inventario.observacoes && (
                  <div className="mt-3 pt-3 border-t" style={{ borderColor: '#E5E0D8' }}>
                    <p className="text-sm" style={{ color: '#8B8B8B' }}>
                      <strong>Observações:</strong> {inventario.observacoes}
                    </p>
                  </div>
                )}
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {inventarios.length === 0 && !isLoading && (
        <div className="text-center py-16">
          <p className="text-xl" style={{ color: '#8B8B8B' }}>
            Nenhum inventário registrado
          </p>
          <p className="text-sm mt-2" style={{ color: '#C0C0C0' }}>
            Clique em &quot;Novo Inventário&quot; para começar a contagem
          </p>
        </div>
      )}
    </div>
  );
}

// Sub-component: collapsible divergence list
function ItensResumo({ itens }) {
  const [expandido, setExpandido] = useState(false);
  const divergentes = itens.filter(item => item.diferenca !== 0);

  if (divergentes.length === 0) {
    return (
      <div className="flex items-center gap-2 text-sm px-3 py-2 rounded-lg" style={{ backgroundColor: '#D1FAE5' }}>
        <Check className="w-4 h-4" style={{ color: '#065F46' }} />
        <span style={{ color: '#065F46' }}>Nenhuma divergência — estoque confere ✓</span>
      </div>
    );
  }

  return (
    <div className="border-t pt-3" style={{ borderColor: '#E5E0D8' }}>
      <button
        className="flex items-center gap-2 text-sm font-medium w-full text-left"
        style={{ color: '#07593f' }}
        onClick={() => setExpandido(!expandido)}
      >
        <AlertTriangle className="w-4 h-4 text-orange-500" />
        {divergentes.length} item(ns) com divergência
        {expandido ? <Eye className="w-3 h-3 ml-auto" /> : <Eye className="w-3 h-3 ml-auto opacity-50" />}
      </button>

      {expandido && (
        <div className="space-y-1.5 mt-2">
          {divergentes.map((item, index) => (
            <div
              key={index}
              className="flex items-center justify-between p-2.5 rounded-lg text-sm"
              style={{ backgroundColor: '#FEF3C7' }}
            >
              <div>
                <p className="font-medium" style={{ color: '#07593f' }}>
                  {item.produto_nome}
                </p>
                <p className="text-xs" style={{ color: '#8B8B8B' }}>
                  Sistema: {item.quantidade_sistema} → Contado: {item.quantidade_contada}
                </p>
              </div>
              <span className="font-bold text-orange-600">
                {item.diferenca > 0 ? '+' : ''}{item.diferenca}
              </span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import React, { useMemo, useRef, useState } from "react";
import { base44, supabase } from "@/api/base44Client";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { ArrowLeft, CheckCircle2, Loader2, Pencil, Plus, Search, Trash2, Warehouse } from "lucide-react";
import { toast } from "sonner";
import { normSearch } from "@/lib/utils";
import { calcularEstoqueTotal, obterCampoEstoqueDaLoja } from "@/constants/productConstants";
import { useLojas } from "@/hooks/useLojas";
import ProdutoCadastroCompleto from "@/components/produtos/ProdutoCadastroCompleto";

const LOJA_CD = { id: "__cd__", nome: "Depósito / CD", ativa: true };

export default function LancamentoManualEstoque({ onVoltar, user }) {
  const queryClient = useQueryClient();
  const [linhas, setLinhas] = useState([]);
  const [termoBusca, setTermoBusca] = useState("");
  const [tipoMovimento, setTipoMovimento] = useState("entrada");
  const [destinoId, setDestinoId] = useState("__cd__");
  const [isSaving, setIsSaving] = useState(false);
  const [isCadastrarOpen, setIsCadastrarOpen] = useState(false);
  const [produtoEmEdicao, setProdutoEmEdicao] = useState(null);
  const searchInputRef = useRef(null);
  const { data: lojas = [], isLoading: loadingLojas } = useLojas();

  const { data: produtos = [], isLoading: loadingProdutos } = useQuery({
    queryKey: ["produtos"],
    queryFn: () => base44.entities.Produto.list(),
  });

  const lojasAtivas = useMemo(() => lojas, [lojas]);
  const lojasComCd = useMemo(() => {
    const hasCd = lojasAtivas.some((loja) => obterCampoEstoqueDaLoja(loja) === "estoque_cd");
    return hasCd ? lojasAtivas : [LOJA_CD, ...lojasAtivas];
  }, [lojasAtivas]);

  const lojaOptions = useMemo(
    () => lojasComCd.map((loja) => ({
      id: loja.id,
      nome: loja.nome,
      isCd: loja.id === LOJA_CD.id,
    })),
    [lojasComCd]
  );

  const atualizarLinha = (linhaId, patch) => {
    setLinhas((current) => current.map((linha) => (linha.id === linhaId ? { ...linha, ...patch } : linha)));
  };

  const removerLinha = (linhaId) => {
    setLinhas((current) => current.filter((linha) => linha.id !== linhaId));
  };

  const montarCodigoProduto = (produto) => [
    produto?.codigo_barras,
    produto?.modelo_referencia,
    produto?.fornecedor_nome,
  ]
    .filter(Boolean)
    .join(" • ");

  const hasMeaningfulValue = (value) => {
    if (value === null || value === undefined) return false;
    const normalized = String(value).trim().toLowerCase();
    return normalized !== "" && !["n/a", "na", "-", "null", "undefined", "?"].includes(normalized);
  };

  const montarDetalhesProduto = (produto) => {
    if (!produto) return [];

    const detalhes = [];

    if (hasMeaningfulValue(produto.cor)) {
      detalhes.push({ chave: "cor", texto: `Cor: ${produto.cor}` });
    }

    if (hasMeaningfulValue(produto.tamanho)) {
      detalhes.push({ chave: "tamanho", texto: `Tam: ${produto.tamanho}` });
    }

    if (hasMeaningfulValue(produto.material)) {
      detalhes.push({ chave: "material", texto: `Material: ${produto.material}` });
    }

    const largura = hasMeaningfulValue(produto.largura) ? produto.largura : null;
    const altura = hasMeaningfulValue(produto.altura) ? produto.altura : null;
    const profundidade = hasMeaningfulValue(produto.profundidade) ? produto.profundidade : null;

    const dimensoes = [
      largura ? `L:${largura}` : null,
      altura ? `A:${altura}` : null,
      profundidade ? `P:${profundidade}` : null,
    ].filter(Boolean);

    if (dimensoes.length > 0) {
      detalhes.push({ chave: "dimensoes", texto: `${dimensoes.join(" ")} cm` });
    }

    return detalhes;
  };

  const selecionarProduto = (produto) => {
    const novaLinha = {
      id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      produtoId: produto.id,
      nomeProduto: produto.nome,
      produtoCodigo: montarCodigoProduto(produto),
      quantidade: "",
    };
    setLinhas((current) => [novaLinha, ...current]);
    setTermoBusca("");
    setTimeout(() => searchInputRef.current?.focus(), 50);
  };

  const filtrarProdutos = (termo) => {
    const searchTokens = normSearch(termo || "").split(/\s+/).filter(Boolean);
    if (searchTokens.length === 0) return [];

    const scoredProdutos = produtos
      .filter((produto) => produto.ativo !== false)
      .map((produto) => {
        const camposBusca = [
          produto.nome,
          produto.codigo_barras,
          produto.sku,
          produto.categoria,
          produto.material,
          produto.cor,
          produto.fornecedor_nome,
          produto.modelo_referencia,
          produto.descricao,
        ]
          .filter(Boolean)
          .map(normSearch)
          .join(" ");

        const matches = searchTokens.filter((token) => camposBusca.includes(token)).length;
        return { produto, score: matches };
      })
      .filter(({ score }) => score > 0)
      .sort((a, b) => b.score - a.score);

    const exactMatches = scoredProdutos.filter(({ score }) => score === searchTokens.length);
    const resultado = exactMatches.length === 0 && scoredProdutos.length > 0 ? scoredProdutos : exactMatches;
    return resultado.map((item) => item.produto).slice(0, 10);
  };

  const produtosJaAdicionados = useMemo(() => new Set(linhas.map((l) => l.produtoId)), [linhas]);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const sugestoes = useMemo(
    () => (termoBusca.trim().length >= 2 ? filtrarProdutos(termoBusca).filter((p) => !produtosJaAdicionados.has(p.id)) : []),
    [termoBusca, produtos, produtosJaAdicionados]
  );

  const obterLoja = (lojaId) => lojaOptions.find((loja) => loja.id === lojaId) || lojaOptions[0] || LOJA_CD;

  const getProdutoResumoEstoque = (produto) => {
    const itens = lojasComCd.map((loja) => {
      const campo = obterCampoEstoqueDaLoja(loja.id === LOJA_CD.id ? null : loja);
      return {
        campo,
        loja: loja.nome,
        quantidade: Number(produto[campo] || 0),
      };
    });

    return {
      total: Number(produto.quantidade_estoque || calcularEstoqueTotal(produto, lojasComCd) || 0),
      itens,
    };
  };

  const prepararResumo = () => linhas
    .map((linha, index) => ({
      index,
      linha,
      produto: produtos.find((p) => p.id === linha.produtoId),
      loja: obterLoja(destinoId),
      quantidade: parseInt(linha.quantidade, 10),
    }))
    .filter(({ linha }) => linha.produtoId && linha.quantidade !== "");

  const handleSalvar = async () => {
    const resumo = prepararResumo();

    if (resumo.length === 0) {
      toast.error("Preencha ao menos uma linha antes de salvar.");
      return;
    }

    for (const item of resumo) {
      if (!item.produto) {
        toast.error(`Selecione um produto válido na linha ${item.index + 1}.`);
        return;
      }

      if (!Number.isInteger(item.quantidade) || item.quantidade <= 0) {
        toast.error(`Informe uma quantidade válida para "${item.linha.nomeProduto}".`);
        return;
      }
    }

    const confirmacao = resumo
      .map((item) => `${item.produto.nome} • ${item.loja.nome} • ${tipoMovimento === "entrada" ? "+" : "-"}${item.quantidade}`)
      .join("\n");

    if (!confirm(`Confirmar o lançamento manual de ${resumo.length} produto(s)?\n\n${confirmacao}`)) {
      return;
    }

    setIsSaving(true);

    try {
      // Pré-validação: verificar se alguma saída ficaria negativa antes de gravar qualquer coisa
      for (const item of resumo) {
        if (tipoMovimento === "saida") {
          const campoEstoque = obterCampoEstoqueDaLoja(item.loja.isCd ? null : item.loja);
          const estoqueAtual = Number(item.produto[campoEstoque] || 0);
          if (estoqueAtual - item.quantidade < 0) {
            throw new Error(`Estoque insuficiente para ${item.produto.nome} em ${item.loja.nome}.`);
          }
        }
      }

      for (const item of resumo) {
        const campoEstoque = obterCampoEstoqueDaLoja(item.loja.isCd ? null : item.loja);
        const estoqueAntesLocal = Number(item.produto[campoEstoque] || 0);
        const estoqueAntesTotal = Number(item.produto.quantidade_estoque || 0);
        const delta = item.quantidade;
        const estoqueDepoisLocal = tipoMovimento === "entrada"
          ? estoqueAntesLocal + delta
          : estoqueAntesLocal - delta;

        const produtoAtualizado = { ...item.produto, [campoEstoque]: estoqueDepoisLocal };
        const estoqueDepoisTotal = calcularEstoqueTotal(produtoAtualizado, lojasComCd);

        await base44.entities.Produto.update(item.produto.id, {
          [campoEstoque]: estoqueDepoisLocal,
          quantidade_estoque: estoqueDepoisTotal,
        });

        try {
          const { error: auditError } = await supabase.from("movimentacoes_estoque").insert({
            produto_id: item.produto.id,
            evento_tipo: tipoMovimento === "entrada" ? "ajuste_manual_entrada" : "ajuste_manual_saida",
            modulo_origem: "estoque",
            referencia_tipo: "lancamento_manual_estoque",
            quantidade: delta,
            estoque_antes_local: estoqueAntesLocal,
            estoque_depois_local: estoqueDepoisLocal,
            estoque_antes_total: estoqueAntesTotal,
            estoque_depois_total: estoqueDepoisTotal,
            loja_origem: item.loja.nome,
            usuario_id: user?.id || null,
            usuario_nome: user?.full_name || user?.nome || user?.email || null,
            usuario_cargo: user?.cargo || null,
            observacao: item.linha.observacao || null,
            payload_json: {
              tipo: "lancamento_manual_estoque",
              loja_id: item.loja.id,
              loja_nome: item.loja.nome,
              campo_estoque: campoEstoque,
              linha_id: item.linha.id,
              operacao: tipoMovimento,
            },
            organization_id: "00000000-0000-0000-0000-000000000001",
          });

          if (auditError) {
            throw auditError;
          }
        } catch (auditErr) {
          console.warn("Falha ao registrar movimentação manual de estoque:", auditErr);
        }
      }

      queryClient.invalidateQueries({ queryKey: ["produtos"] });
      queryClient.invalidateQueries({ queryKey: ["produtos-carga-inicial"] });
      queryClient.invalidateQueries({ queryKey: ["produtos-inventario"] });
      queryClient.invalidateQueries({ queryKey: ["movimentacoes-estoque"] });

      setLinhas([]);
      setTermoBusca("");
      toast.success(`Lançamento salvo com sucesso para ${resumo.length} produto(s).`);
    } catch (error) {
      toast.error(`Erro ao salvar: ${error.message}`);
    } finally {
      setIsSaving(false);
    }
  };

  const handleSalvarEdicaoProduto = async (data) => {
    if (!produtoEmEdicao?.id) return;

    try {
      const produtoAtualizado = await base44.entities.Produto.update(produtoEmEdicao.id, data);

      setLinhas((current) => current.map((linha) => {
        if (linha.produtoId !== produtoEmEdicao.id) return linha;
        return {
          ...linha,
          nomeProduto: produtoAtualizado?.nome || data?.nome || linha.nomeProduto,
          produtoCodigo: montarCodigoProduto(produtoAtualizado || data || {}),
        };
      }));

      queryClient.invalidateQueries({ queryKey: ["produtos"] });
      queryClient.invalidateQueries({ queryKey: ["produtos-para-duplicata"] });

      setProdutoEmEdicao(null);
      toast.success("Produto atualizado com sucesso.");
    } catch (error) {
      toast.error(`Erro ao atualizar produto: ${error.message}`);
    }
  };

  const totalLinhasValidas = linhas.filter((linha) => linha.produtoId && linha.quantidade !== "").length;
  const totalQuantidades = linhas.reduce((sum, l) => sum + (parseInt(l.quantidade, 10) || 0), 0);

  return (
    <div className="space-y-6">
      <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
        <div className="flex items-center gap-3">
          <Button variant="ghost" size="icon" onClick={onVoltar}>
            <ArrowLeft className="w-5 h-5" />
          </Button>
          <div>
            <h2 className="text-xl font-bold" style={{ color: "#07593f" }}>
              Lançamento Manual de Estoque
            </h2>
            <p className="text-sm" style={{ color: "#8B8B8B" }}>
              Adicione vários produtos e quantidades em um único envio, sem bipagem.
            </p>
          </div>
        </div>

        <Button
          onClick={handleSalvar}
          disabled={isSaving || totalLinhasValidas === 0}
          style={{ background: "linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)" }}
        >
          {isSaving ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <CheckCircle2 className="w-4 h-4 mr-2" />}
          Salvar lançamento
        </Button>
      </div>

      <Alert style={{ backgroundColor: "#f0fdf4", borderColor: "#86efac" }}>
        <AlertDescription>
          <strong>Como funciona:</strong> defina o tipo e o destino, busque produtos e clique para adicioná-los à lista. Informe a quantidade de cada um e salve.
        </AlertDescription>
      </Alert>

      <Card className="border-0 shadow-sm">
        <CardContent className="pt-6">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-4">
            <div className="lg:col-span-4 space-y-2">
              <Label>Tipo de lançamento</Label>
              <Select value={tipoMovimento} onValueChange={setTipoMovimento}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="entrada">Entrada</SelectItem>
                  <SelectItem value="saida">Saída</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="lg:col-span-8 space-y-2">
              <Label>Destino</Label>
              <Select value={destinoId} onValueChange={setDestinoId}>
                <SelectTrigger><SelectValue placeholder="Selecione a unidade" /></SelectTrigger>
                <SelectContent>
                  {lojaOptions.map((loja) => (
                    <SelectItem key={loja.id} value={loja.id}>{loja.nome}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      <Card className="border-0 shadow-sm">
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between gap-3">
            <CardTitle className="flex items-center gap-2 text-lg">
              <Warehouse className="w-5 h-5 text-green-700" />
              Produtos do lançamento
            </CardTitle>
            <Badge variant="secondary" className="rounded-full px-3 py-1">
              {linhas.length} produto(s)
            </Badge>
          </div>
        </CardHeader>

        <CardContent className="space-y-4">
          {loadingProdutos || loadingLojas ? (
            <div className="py-12 text-center text-gray-500">
              <Loader2 className="w-8 h-8 animate-spin mx-auto mb-2" />
              Carregando produtos e unidades...
            </div>
          ) : (
            <>
              {/* Barra de busca única */}
              <div className="space-y-2 relative">
                <div className="flex items-center justify-between">
                  <Label>Buscar e adicionar produto</Label>
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    className="h-7 text-xs gap-1"
                    onClick={() => setIsCadastrarOpen(true)}
                  >
                    <Plus className="w-3 h-3" />
                    Cadastrar item
                  </Button>
                </div>
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                  <Input
                    ref={searchInputRef}
                    className="pl-10"
                    value={termoBusca}
                    onChange={(e) => setTermoBusca(e.target.value)}
                    placeholder="Buscar por nome, código ou referência..."
                  />
                </div>
                {sugestoes.length > 0 && (
                  <div className="absolute z-20 mt-1 w-full rounded-xl border bg-white shadow-lg overflow-hidden">
                    {sugestoes.map((produto, idx) => {
                      const resumo = getProdutoResumoEstoque(produto);
                      const detalhesProduto = montarDetalhesProduto(produto);
                      return (
                        <button
                          key={`${produto.id}-${idx}`}
                          type="button"
                          onClick={() => selecionarProduto(produto)}
                          className="flex w-full items-center justify-between gap-3 border-b border-gray-100 px-3 py-2 text-left last:border-b-0 hover:bg-green-50"
                        >
                          <div className="min-w-0">
                            <p className="truncate text-sm font-medium text-gray-900">{produto.nome}</p>
                            <p className="truncate text-xs text-gray-500">
                              {[produto.codigo_barras, produto.modelo_referencia, produto.fornecedor_nome].filter(Boolean).join(" • ") || "Sem código"}
                            </p>
                            {detalhesProduto.length > 0 && (
                              <div className="mt-1 flex flex-wrap gap-1 text-[10px] text-gray-600">
                                {detalhesProduto.map((detalhe) => (
                                  <span key={`${produto.id}-${detalhe.chave}`} className="rounded-full bg-blue-50 px-2 py-0.5 border border-blue-100 text-blue-700">
                                    {detalhe.texto}
                                  </span>
                                ))}
                              </div>
                            )}
                            <div className="mt-1 flex flex-wrap gap-1.5 text-[10px] text-gray-600">
                              <span className="rounded-full bg-gray-100 px-2 py-0.5">Estoque total: {resumo.total}</span>
                              {resumo.itens.map((item) => (
                                <span key={`${produto.id}-${item.campo}`} className="rounded-full bg-gray-50 px-2 py-0.5 border border-gray-200">
                                  {item.loja}: {item.quantidade}
                                </span>
                              ))}
                            </div>
                          </div>
                          <Badge variant="outline" className="shrink-0">Adicionar</Badge>
                        </button>
                      );
                    })}
                  </div>
                )}
              </div>

              {/* Lista de produtos adicionados (mais recente no topo) */}
              {linhas.length === 0 ? (
                <div className="py-10 text-center text-gray-400 border-2 border-dashed border-gray-200 rounded-xl">
                  <Search className="w-8 h-8 mx-auto mb-2 opacity-30" />
                  <p className="text-sm">Nenhum produto adicionado ainda.</p>
                  <p className="text-xs mt-1">Use a busca acima para adicionar produtos à lista.</p>
                </div>
              ) : (
                <div className="space-y-2">
                  {linhas.map((linha) => {
                    const produtoAtual = produtos.find((p) => p.id === linha.produtoId);
                    const resumo = produtoAtual ? getProdutoResumoEstoque(produtoAtual) : null;
                    const detalhesProduto = produtoAtual ? montarDetalhesProduto(produtoAtual) : [];
                    return (
                      <div key={linha.id} className="flex items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-3 shadow-sm">
                        <div className="min-w-0 flex-1">
                          <p className="truncate text-sm font-medium text-gray-900">{linha.nomeProduto}</p>
                          {linha.produtoCodigo && (
                            <p className="truncate text-xs text-gray-500">{linha.produtoCodigo}</p>
                          )}
                          {detalhesProduto.length > 0 && (
                            <div className="mt-1 flex flex-wrap gap-1 text-[10px] text-gray-600">
                              {detalhesProduto.map((detalhe) => (
                                <span key={`${linha.id}-${detalhe.chave}`} className="rounded-full bg-blue-50 px-2 py-0.5 border border-blue-100 text-blue-700">
                                  {detalhe.texto}
                                </span>
                              ))}
                            </div>
                          )}
                          {resumo && (
                            <div className="mt-1 flex flex-wrap gap-1 text-[10px] text-gray-500">
                              <span className="rounded-full bg-gray-100 px-2 py-0.5">Estoque: {resumo.total}</span>
                              {resumo.itens.map((item) => (
                                <span key={item.campo} className="rounded-full bg-gray-50 px-2 py-0.5 border border-gray-200">
                                  {item.loja}: {item.quantidade}
                                </span>
                              ))}
                            </div>
                          )}
                        </div>
                        <div className="flex items-center gap-2 shrink-0">
                          <Button
                            type="button"
                            variant="ghost"
                            size="icon"
                            className="text-gray-500 hover:text-gray-700 hover:bg-gray-100"
                            onClick={() => {
                              if (produtoAtual) {
                                setProdutoEmEdicao(produtoAtual);
                              } else {
                                toast.error("Produto não encontrado para edição.");
                              }
                            }}
                            title="Editar cadastro do produto"
                          >
                            <Pencil className="w-4 h-4" />
                          </Button>
                          <Input
                            type="number"
                            min="1"
                            value={linha.quantidade}
                            onChange={(e) => atualizarLinha(linha.id, { quantidade: e.target.value })}
                            onBlur={(e) => {
                              if (e.target.value && parseInt(e.target.value, 10) > 0) {
                                searchInputRef.current?.focus();
                              }
                            }}
                            placeholder="Qtd"
                            className="w-20 text-center"
                          />
                          <Button
                            variant="ghost"
                            size="icon"
                            className="text-red-400 hover:text-red-600 hover:bg-red-50"
                            onClick={() => removerLinha(linha.id)}
                          >
                            <Trash2 className="w-4 h-4" />
                          </Button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}

              {/* Rodapé com total e botão salvar */}
              {linhas.length > 0 && (
                <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between pt-3 border-t border-gray-100">
                  <div className="text-sm text-gray-600">
                    <span>Total de unidades: </span>
                    <span className="font-bold text-gray-900">{totalQuantidades}</span>
                    <span className="text-gray-400 ml-2">em {linhas.length} produto(s)</span>
                  </div>
                  <Button
                    onClick={handleSalvar}
                    disabled={isSaving || totalLinhasValidas === 0}
                    style={{ background: "linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)" }}
                  >
                    {isSaving ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <CheckCircle2 className="w-4 h-4 mr-2" />}
                    Salvar lançamento
                  </Button>
                </div>
              )}
            </>
          )}
        </CardContent>
      </Card>

      <ProdutoCadastroCompleto
        isOpen={isCadastrarOpen}
        onClose={() => setIsCadastrarOpen(false)}
        produto={null}
        onSave={async (data) => {
          const novoProduto = await base44.entities.Produto.create(data);
          queryClient.invalidateQueries({ queryKey: ["produtos"] });
          setIsCadastrarOpen(false);
          if (novoProduto?.id) {
            selecionarProduto(novoProduto);
            toast.success("Produto cadastrado e adicionado ao lançamento.");
            return;
          }

          toast.success("Produto cadastrado! Você já pode buscá-lo na lista.");
        }}
      />

      <ProdutoCadastroCompleto
        isOpen={Boolean(produtoEmEdicao)}
        onClose={() => setProdutoEmEdicao(null)}
        produto={produtoEmEdicao}
        onSave={handleSalvarEdicaoProduto}
      />
    </div>
  );
}

import React, { useState, useRef, useEffect } from "react";
import { base44 } from "@/api/base44Client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Search, ArrowUpCircle, ArrowDownCircle, Package, Loader2, ScanBarcode, Check, X } from "lucide-react";
import { toast } from "sonner";

export default function MovimentacaoEstoque({ barcodeInputRef }) {
  const [search, setSearch] = useState("");
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [quantity, setQuantity] = useState("");
  const [type, setType] = useState(null); // 'entrada' | 'saida' | null
  const inputRef = useRef(null);
  const qtyRef = useRef(null);
  
  const queryClient = useQueryClient();
  const { data: produtos = [] } = useQuery({ queryKey: ['produtos'], queryFn: () => base44.entities.Produto.list() });

  // Auto-focus search on mount and reset
  useEffect(() => { inputRef.current?.focus(); }, [selectedProduct]);
  
  // Auto-focus quantity when type selected
  useEffect(() => { if (type) qtyRef.current?.focus(); }, [type]);

  const handleSearch = (e) => {
    if (e.key === 'Enter' && search) {
      const exactMatch = produtos.find(p => p.codigo_barras === search);
      if (exactMatch) {
        selectProduct(exactMatch);
      } else {
        // Simple fuzzy search if needed, but for scanner exact is best. 
        // Let's try find by name if barcode fails
        const nameMatch = produtos.find(p => p.nome.toLowerCase().includes(search.toLowerCase()));
        if(nameMatch) selectProduct(nameMatch);
        else toast.error("Produto não encontrado");
      }
    }
  };

  const selectProduct = (prod) => {
    setSelectedProduct(prod);
    setSearch("");
    setType(null);
    setQuantity("");
  };

  const mutation = useMutation({
    mutationFn: async () => {
      const qtd = parseInt(quantity);
      if (!qtd || qtd <= 0) throw new Error("Qtd inválida");
      const novaQtd = type === 'entrada' 
        ? (selectedProduct.quantidade_estoque || 0) + qtd
        : (selectedProduct.quantidade_estoque || 0) - qtd;
      
      if (type === 'saida' && novaQtd < 0) throw new Error("Estoque insuficiente");
      
      const updates = { quantidade_estoque: novaQtd };
      const cdQtd = type === 'entrada'
        ? (selectedProduct.estoque_cd || 0) + qtd
        : Math.max(0, (selectedProduct.estoque_cd || 0) - qtd);

      if (Object.prototype.hasOwnProperty.call(selectedProduct, 'estoque_cd')) {
        updates.estoque_cd = cdQtd;
      }

      await base44.entities.Produto.update(selectedProduct.id, updates);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['produtos'] });
      toast.success("Movimentação realizada!");
      setSelectedProduct(null); // Go back to search
    },
    onError: (err) => toast.error(err.message)
  });

  return (
    <div className="max-w-2xl mx-auto">
      {!selectedProduct ? (
        <div className="bg-white dark:bg-neutral-900 p-8 rounded-2xl shadow-sm border border-gray-200 dark:border-neutral-800 text-center">
          <div className="w-16 h-16 bg-blue-50 dark:bg-blue-900/20 text-blue-600 rounded-full flex items-center justify-center mx-auto mb-6">
            <ScanBarcode className="w-8 h-8" />
          </div>
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white mb-2">Movimentação Rápida</h2>
          <p className="text-gray-500 mb-8">Escaneie o código de barras ou digite o nome do produto</p>
          
          <div className="relative max-w-md mx-auto">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
            <Input
              ref={inputRef}
              value={search}
              onChange={e => setSearch(e.target.value)}
              onKeyDown={handleSearch}
              className="pl-12 h-14 text-lg shadow-sm"
              placeholder="Código ou Nome..."
            />
          </div>
        </div>
      ) : (
        <div className="bg-white dark:bg-neutral-900 rounded-2xl shadow-sm border border-gray-200 dark:border-neutral-800 overflow-hidden">
          <div className="p-6 border-b border-gray-100 dark:border-neutral-800 bg-gray-50/50 dark:bg-neutral-900">
            <div className="flex justify-between items-start">
              <div>
                <h2 className="text-2xl font-bold text-gray-900 dark:text-white">{selectedProduct.nome}</h2>
                <p className="text-sm text-gray-500 font-mono mt-1">{selectedProduct.codigo_barras}</p>
              </div>
              <div className="text-right">
                <p className="text-xs text-gray-500 uppercase">Estoque</p>
                <p className="text-3xl font-bold text-gray-900 dark:text-white">{selectedProduct.quantidade_estoque}</p>
              </div>
            </div>
          </div>

          <div className="p-8">
            {!type ? (
              <div className="grid grid-cols-2 gap-4">
                <button 
                  onClick={() => setType('entrada')}
                  className="h-32 rounded-xl border-2 border-gray-100 dark:border-neutral-800 hover:border-green-500 hover:bg-green-50 dark:hover:bg-green-900/20 hover:text-green-700 transition-all flex flex-col items-center justify-center gap-3 group"
                >
                  <ArrowUpCircle className="w-10 h-10 text-green-500 group-hover:scale-110 transition-transform" />
                  <span className="text-lg font-bold">Entrada</span>
                </button>
                <button 
                  onClick={() => setType('saida')}
                  className="h-32 rounded-xl border-2 border-gray-100 dark:border-neutral-800 hover:border-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 hover:text-red-700 transition-all flex flex-col items-center justify-center gap-3 group"
                >
                  <ArrowDownCircle className="w-10 h-10 text-red-500 group-hover:scale-110 transition-transform" />
                  <span className="text-lg font-bold">Saída</span>
                </button>
              </div>
            ) : (
              <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4">
                <div className="text-center">
                  <Badge className={`mb-4 px-3 py-1 text-sm ${type === 'entrada' ? 'bg-green-100 text-green-800 hover:bg-green-100' : 'bg-red-100 text-red-800 hover:bg-red-100'}`}>
                    {type === 'entrada' ? 'Entrada de Estoque' : 'Saída de Estoque'}
                  </Badge>
                  <div className="flex items-center justify-center gap-4">
                    <Button variant="outline" size="icon" className="h-12 w-12 rounded-full" onClick={() => setQuantity(prev => Math.max(1, (parseInt(prev)||0)-1).toString())}>-</Button>
                    <Input 
                      ref={qtyRef}
                      type="number" 
                      className="text-center text-3xl font-bold h-16 w-32" 
                      placeholder="0"
                      value={quantity}
                      onChange={e => setQuantity(e.target.value)}
                      onKeyDown={e => e.key === 'Enter' && mutation.mutate()}
                    />
                    <Button variant="outline" size="icon" className="h-12 w-12 rounded-full" onClick={() => setQuantity(prev => ((parseInt(prev)||0)+1).toString())}>+</Button>
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <Button variant="outline" size="lg" onClick={() => setType(null)}>Voltar</Button>
                  <Button 
                    size="lg" 
                    className={type === 'entrada' ? 'bg-green-600 hover:bg-green-700' : 'bg-red-600 hover:bg-red-700'}
                    onClick={() => mutation.mutate()}
                    disabled={!quantity || mutation.isPending}
                  >
                    {mutation.isPending ? <Loader2 className="w-5 h-5 animate-spin" /> : <Check className="w-5 h-5 mr-2" />}
                    Confirmar
                  </Button>
                </div>
              </div>
            )}
          </div>
          
          <div className="bg-gray-50 dark:bg-neutral-900 p-4 border-t border-gray-100 dark:border-neutral-800 text-center">
            <Button variant="ghost" size="sm" onClick={() => setSelectedProduct(null)} className="text-gray-500">
              Cancelar e Buscar Outro
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import { base44, supabase } from '@/api/base44Client';
import { useQueryClient } from '@tanstack/react-query';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Loader2, Package, History, Warehouse, AlertTriangle, CircleDollarSign, Plus, Minus } from 'lucide-react';
import { toast } from 'sonner';
import { useLojas } from '@/hooks/useLojas';
import { useAuth } from '@/hooks/useAuth';
import { obterCampoEstoqueDaLoja, calcularEstoqueTotal } from '@/constants/productConstants';
import ProdutoHistoricoTab from '@/components/produtos/ProdutoHistoricoTab';

const LOJA_CD_FALLBACK = {
  id: 'cd-fallback',
  nome: 'Depósito / CD',
};

export default function ProdutoConferenciaModal({
  isOpen,
  onClose,
  produto,
  onSave,
}) {
  const queryClient = useQueryClient();
  const { data: lojas = [] } = useLojas();
  const { user } = useAuth();
  const [activeTab, setActiveTab] = useState('conferencia');
  const [saving, setSaving] = useState(false);
  const [manualLojaId, setManualLojaId] = useState('');
  const [manualDelta, setManualDelta] = useState('');

  const [estoquePorLoja, setEstoquePorLoja] = useState({});
  const [estoqueMinimo, setEstoqueMinimo] = useState(0);
  const [estoqueIdeal, setEstoqueIdeal] = useState(0);

  const lojasComCd = useMemo(() => {
    const base = Array.isArray(lojas) ? [...lojas] : [];
    const hasCd = base.some((loja) => obterCampoEstoqueDaLoja(loja) === 'estoque_cd');
    if (!hasCd) {
      base.unshift(LOJA_CD_FALLBACK);
    }

    return base.sort((a, b) => {
      const aIsCd = obterCampoEstoqueDaLoja(a) === 'estoque_cd';
      const bIsCd = obterCampoEstoqueDaLoja(b) === 'estoque_cd';
      if (aIsCd && !bIsCd) return -1;
      if (!aIsCd && bIsCd) return 1;
      return (a.nome || '').localeCompare(b.nome || '', 'pt-BR', { sensitivity: 'base' });
    });
  }, [lojas]);

  useEffect(() => {
    if (!produto || !isOpen) return;

    const next = {};
    lojasComCd.forEach((loja) => {
      const campo = obterCampoEstoqueDaLoja(loja);
      next[campo] = Number(produto[campo] || 0);
    });

    setEstoquePorLoja(next);
    setEstoqueMinimo(Number(produto.estoque_minimo || 0));
    setEstoqueIdeal(Number(produto.estoque_ideal || 0));
    const cdLoja = lojasComCd.find((loja) => obterCampoEstoqueDaLoja(loja) === 'estoque_cd');
    setManualLojaId(cdLoja?.id || lojasComCd[0]?.id || '');
    setManualDelta('');
    setActiveTab('conferencia');
  }, [produto, isOpen, lojasComCd]);

  const totalCalculado = useMemo(() => {
    const pseudoProduto = { ...produto, ...estoquePorLoja };
    return calcularEstoqueTotal(pseudoProduto, lojasComCd);
  }, [produto, estoquePorLoja, lojasComCd]);

  const estoqueCd = Number(estoquePorLoja.estoque_cd || 0);

  const isLowStock = totalCalculado <= estoqueMinimo;

  const atualizarLoja = (campo, valor) => {
    const qtd = Number.isNaN(Number(valor)) ? 0 : Number(valor);
    setEstoquePorLoja((prev) => ({
      ...prev,
      [campo]: Math.max(0, qtd),
    }));
  };

  const aplicarAjusteRapido = (sinal) => {
    if (!manualLojaId) {
      toast.warning('Selecione a loja para ajuste manual.');
      return;
    }

    const delta = Number(manualDelta);
    if (!delta || delta <= 0) {
      toast.warning('Informe uma quantidade valida para ajuste rapido.');
      return;
    }

    const loja = lojasComCd.find((l) => l.id === manualLojaId);
    if (!loja) return;

    const campo = obterCampoEstoqueDaLoja(loja);
    const atual = Number(estoquePorLoja[campo] || 0);
    const proximo = sinal === 'entrada' ? atual + delta : Math.max(0, atual - delta);

    setEstoquePorLoja((prev) => ({ ...prev, [campo]: proximo }));
    setManualDelta('');
  };

  const handleSalvar = async () => {
    if (!produto?.id) return;

    setSaving(true);
    try {
      const estoqueAnteriorTotal = Number(produto.quantidade_estoque || 0);
      const deltaTotal = totalCalculado - estoqueAnteriorTotal;

      const payload = {
        ...estoquePorLoja,
        quantidade_estoque: totalCalculado,
        estoque_minimo: Math.max(0, Number(estoqueMinimo || 0)),
        estoque_ideal: Math.max(0, Number(estoqueIdeal || 0)),
      };

      await onSave(payload);

      const alteracoesPorLoja = lojasComCd
        .map((loja) => {
          const campo = obterCampoEstoqueDaLoja(loja);
          const anterior = Number(produto[campo] || 0);
          const atual = Number(estoquePorLoja[campo] || 0);
          if (anterior === atual) return null;

          return {
            loja_id: loja.id,
            loja_nome: loja.nome,
            campo,
            anterior,
            atual,
            delta: atual - anterior,
          };
        })
        .filter(Boolean);

      try {
        const { error: auditError } = await supabase.from('movimentacoes_estoque').insert({
          produto_id: produto.id,
          evento_tipo: 'conferencia_estoque',
          modulo_origem: 'estoque',
          referencia_tipo: 'conferencia',
          quantidade: deltaTotal,
          estoque_antes_total: estoqueAnteriorTotal,
          estoque_depois_total: totalCalculado,
          estoque_antes_local: null,
          estoque_depois_local: null,
          usuario_id: user?.id || null,
          usuario_nome: user?.full_name || user?.nome || 'Operador de Estoque',
          usuario_cargo: user?.cargo || null,
          observacao: alteracoesPorLoja.length > 0
            ? `Conferencia com ajuste em ${alteracoesPorLoja.length} loja(s)`
            : 'Conferencia sem alteracao de quantidade',
          payload_json: {
            tipo: 'conferencia_estoque',
            alteracoes_por_loja: alteracoesPorLoja,
            estoque_cd: Number(estoquePorLoja.estoque_cd || 0),
            estoque_minimo: Math.max(0, Number(estoqueMinimo || 0)),
            estoque_ideal: Math.max(0, Number(estoqueIdeal || 0)),
          },
        });

        if (auditError) {
          throw auditError;
        }
      } catch (auditError) {
        console.warn('Falha ao registrar historico de conferencia:', auditError);
        toast.warning('Estoque salvo, mas houve falha ao registrar no historico.');
      }

      queryClient.invalidateQueries({ queryKey: ['movimentacoes-estoque', produto.id] });

      toast.success('Conferencia de estoque salva com sucesso.');
      onClose?.();
    } catch (error) {
      toast.error(`Erro ao salvar: ${error.message}`);
    } finally {
      setSaving(false);
    }
  };

  if (!produto) return null;

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-5xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Package className="w-5 h-5 text-green-700" />
            Conferencia de Mercadoria
          </DialogTitle>
        </DialogHeader>

        <Tabs value={activeTab} onValueChange={setActiveTab}>
          <TabsList>
            <TabsTrigger value="conferencia">Conferencia</TabsTrigger>
            <TabsTrigger value="historico">Historico</TabsTrigger>
          </TabsList>

          <TabsContent value="conferencia" className="space-y-4 pt-3">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <Card className="md:col-span-2">
                <CardHeader className="pb-2">
                  <CardTitle className="text-base">Dados do Produto</CardTitle>
                </CardHeader>
                <CardContent className="space-y-3">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                    <div>
                      <Label className="text-xs text-gray-500">Nome</Label>
                      <Input value={produto.nome || ''} readOnly className="bg-gray-50" />
                    </div>
                    <div>
                      <Label className="text-xs text-gray-500">Fornecedor</Label>
                      <Input value={produto.fornecedor_nome || ''} readOnly className="bg-gray-50" />
                    </div>
                    <div>
                      <Label className="text-xs text-gray-500">Categoria</Label>
                      <Input value={produto.categoria || ''} readOnly className="bg-gray-50" />
                    </div>
                    <div>
                      <Label className="text-xs text-gray-500">Codigo de Barras</Label>
                      <Input value={produto.codigo_barras || ''} readOnly className="bg-gray-50" />
                    </div>
                  </div>

                  <Alert className="border-green-200 bg-green-50">
                    <CircleDollarSign className="h-4 w-4 text-green-700" />
                    <AlertDescription className="text-green-800">
                      Preco de venda: <strong>R$ {(produto.preco_venda || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</strong>
                      {' '} (somente visualizacao para equipe de estoque)
                    </AlertDescription>
                  </Alert>
                </CardContent>
              </Card>

              <Card>
                <CardHeader className="pb-2">
                  <CardTitle className="text-base">Resumo de Estoque</CardTitle>
                </CardHeader>
                <CardContent className="space-y-3">
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-600">CD</span>
                    <Badge className="bg-blue-100 text-blue-700 hover:bg-blue-100">{estoqueCd} un.</Badge>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-600">Total atual</span>
                    <Badge variant={isLowStock ? 'destructive' : 'secondary'}>{totalCalculado} un.</Badge>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-600">Estoque minimo</span>
                    <Input
                      type="number"
                      value={estoqueMinimo}
                      onChange={(e) => setEstoqueMinimo(Math.max(0, Number(e.target.value || 0)))}
                      className="w-20 h-8"
                    />
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-600">Estoque ideal</span>
                    <Input
                      type="number"
                      value={estoqueIdeal}
                      onChange={(e) => setEstoqueIdeal(Math.max(0, Number(e.target.value || 0)))}
                      className="w-20 h-8"
                    />
                  </div>

                  {isLowStock && (
                    <Alert className="border-yellow-200 bg-yellow-50">
                      <AlertTriangle className="h-4 w-4 text-yellow-700" />
                      <AlertDescription className="text-yellow-800 text-xs">
                        Produto em nivel de atencao de estoque.
                      </AlertDescription>
                    </Alert>
                  )}
                </CardContent>
              </Card>
            </div>

            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-base flex items-center gap-2">
                  <Warehouse className="w-4 h-4 text-blue-700" />
                  Ajuste Rapido por Loja
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-[1fr_120px_auto_auto] gap-2 items-end">
                  <div>
                    <Label>Loja</Label>
                    <Select value={manualLojaId} onValueChange={setManualLojaId}>
                      <SelectTrigger>
                        <SelectValue placeholder="Selecione" />
                      </SelectTrigger>
                      <SelectContent>
                        {lojasComCd.map((loja) => (
                          <SelectItem key={loja.id} value={loja.id}>{loja.nome}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div>
                    <Label>Qtd</Label>
                    <Input
                      type="number"
                      min={1}
                      value={manualDelta}
                      onChange={(e) => setManualDelta(e.target.value)}
                    />
                  </div>
                  <Button type="button" variant="outline" onClick={() => aplicarAjusteRapido('entrada')}>
                    <Plus className="w-4 h-4 mr-1" /> Entrada
                  </Button>
                  <Button type="button" variant="outline" onClick={() => aplicarAjusteRapido('saida')}>
                    <Minus className="w-4 h-4 mr-1" /> Saida
                  </Button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                  {lojasComCd.map((loja) => {
                    const campo = obterCampoEstoqueDaLoja(loja);
                    const isCd = campo === 'estoque_cd';
                    return (
                      <div key={loja.id} className={`border rounded-lg p-3 ${isCd ? 'bg-blue-50 border-blue-200' : 'bg-gray-50'}`}>
                        <Label className="text-xs text-gray-600 flex items-center gap-1">
                          {loja.nome}
                        </Label>
                        <Input
                          type="number"
                          min={0}
                          value={estoquePorLoja[campo] ?? 0}
                          onChange={(e) => atualizarLoja(campo, e.target.value)}
                          className="mt-1"
                        />
                      </div>
                    );
                  })}
                </div>
              </CardContent>
            </Card>
          </TabsContent>

          <TabsContent value="historico" className="pt-3">
            <ProdutoHistoricoTab produtoId={produto.id} />
          </TabsContent>
        </Tabs>

        <DialogFooter>
          <Button variant="outline" onClick={onClose}>Cancelar</Button>
          <Button onClick={handleSalvar} disabled={saving} className="bg-green-700 hover:bg-green-800">
            {saving ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : null}
            Salvar Conferencia
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect } from "react";
import { base44, supabase } from "@/lib/supabase";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import {
    PackageCheck,
    Check,
    AlertCircle,
    Package,
    Truck
} from "lucide-react";
import { toast } from "sonner";
import { calcularEstoqueTotal } from "@/constants/productConstants";
import { useLojas } from "@/hooks/useLojas";

export default function RecebimentoPedido({ open, onClose, pedido }) {
    const { data: lojas = [] } = useLojas();
    const queryClient = useQueryClient();
    const [statusLocal, setStatusLocal] = useState(pedido?.status || '');
    const [originalStatus, setOriginalStatus] = useState(pedido?.status || '');

    useEffect(() => {
        let isMounted = true;

        if (open && pedido && (pedido.status === 'Confirmado')) {
            const autoIniciarConferencia = async () => {
                try {
                    await base44.entities.PedidoCompra.update(pedido.id, { status: 'Em Conferência' });
                    if (isMounted) {
                        setStatusLocal('Em Conferência');
                        queryClient.invalidateQueries({ queryKey: ['pedidos-compra'] });
            queryClient.invalidateQueries({ queryKey: ['pedidos-compra-table'] });
                        queryClient.invalidateQueries({ queryKey: ['pedidos-compra-recebimento'] });
                        queryClient.invalidateQueries({ queryKey: ['pedidos-em-conferencia-global'] });
                        toast.success('Pedido em conferência. Setor de Compras notificado.');
                    }
                } catch (err) {
                    console.error('Erro ao autodesignar Em Conferência:', err);
                }
            };
            autoIniciarConferencia();
        } else if (pedido) {
            if (isMounted) {
                setStatusLocal(pedido.status);
                setOriginalStatus(pedido.status);
            }
        }

        // Cleanup: Reverte o status se o componente for desmontado enquanto "Em Conferência" sem ter salvo
        return () => {
            isMounted = false;
        };
    }, [open, pedido?.id, pedido?.status, queryClient]);

    const handleClose = async (isConfirming = false) => {
        // If closing without confirming, and we auto-changed to 'Em Conferência', revert it
        if (!isConfirming && statusLocal === 'Em Conferência' && originalStatus !== 'Em Conferência' && pedido) {
            try {
                await base44.entities.PedidoCompra.update(pedido.id, { status: originalStatus });
                queryClient.invalidateQueries({ queryKey: ['pedidos-compra'] });
                queryClient.invalidateQueries({ queryKey: ['pedidos-compra-kanban'] });
                queryClient.invalidateQueries({ queryKey: ['pedidos-compra-recebimento'] });
                queryClient.invalidateQueries({ queryKey: ['pedidos-em-conferencia-global'] });
            } catch (err) {
                console.error('Erro ao reverter status:', err);
            }
        }
        onClose();
    };

    // Estado para quantidades recebidas
    const [quantidadesRecebidas, setQuantidadesRecebidas] = useState(() => {
        const inicial = {};
        (pedido?.itens || []).forEach((item, index) => {
            inicial[index] = 0; // Começa em 0 — o operador digita o que está recebendo AGORA
        });
        return inicial;
    });

    const [observacaoRecebimento, setObservacaoRecebimento] = useState("");

    // Mutation para atualizar pedido e estoque
    const receberPedido = useMutation({
        mutationFn: async () => {
            // 1. Coletar IDs de produtos para busca em lote
            const produtoIds = [...new Set(pedido.itens.map(i => i.produto_id).filter(Boolean))];
            let produtosMap = {};

            if (produtoIds.length > 0) {
                const { data: produtosEncontrados, error: searchError } = await supabase
                    .from('produtos')
                    .select('*')
                    .in('id', produtoIds);

                if (searchError) throw searchError;

                produtosEncontrados.forEach(p => {
                    produtosMap[p.id] = p;
                });
            }

            // 2. Preparar itens atualizados e atualizar estoque
            const itensAtualizados = (pedido.itens || []).map((item, index) => ({
                ...item,
                quantidade_rece_atual: (item.quantidade_recebida || 0) + (quantidadesRecebidas[index] || 0),
                status: verificarStatusItem(item, quantidadesRecebidas[index])
            }));

            // Sanitização final dos itens para salvar no pedido
            const itensParaSalvar = itensAtualizados.map(i => {
                const { quantidade_rece_atual, ...rest } = i;
                return { ...rest, quantidade_recebida: i.quantidade_rece_atual };
            });

            // Verificar status geral do pedido
            const todoRecebido = itensParaSalvar.every(
                item => item.quantidade_recebida >= item.quantidade_pedida
            );
            const algumRecebido = itensParaSalvar.some(
                item => item.quantidade_recebida > 0
            );

            let novoStatus = pedido.status;
            if (todoRecebido) {
                novoStatus = 'Recebido';
            } else if (algumRecebido) {
                novoStatus = 'Parcialmente Recebido';
            }

            // Atualizar pedido
            await base44.entities.PedidoCompra.update(pedido.id, {
                itens: itensParaSalvar,
                status: novoStatus,
                data_entrega_real: todoRecebido ? new Date().toISOString().split('T')[0] : null,
                observacoes: pedido.observacoes
                    ? `${pedido.observacoes}\n\n[${new Date().toLocaleString('pt-BR')}] ${observacaoRecebimento}`
                    : `[${new Date().toLocaleString('pt-BR')}] ${observacaoRecebimento}`
            });

            // Atualizar estoque de cada produto recebido
            for (const [index, qtdRecebida] of Object.entries(quantidadesRecebidas)) {
                if (qtdRecebida > 0) {
                    const item = pedido.itens[index];
                    const produto = produtosMap[item.produto_id];

                    if (produto) {
                        try {
                            const estoqueCdAtual = produto.estoque_cd || 0;
                            const pAtualizado = {
                                ...produto,
                                estoque_cd: estoqueCdAtual + qtdRecebida
                            };
                            
                            const novoTotal = calcularEstoqueTotal(pAtualizado, lojas);

                            await base44.entities.Produto.update(item.produto_id, {
                                quantidade_estoque: novoTotal,
                                estoque_cd: pAtualizado.estoque_cd
                            });

                            // Se o item estiver vinculado a uma venda (Encomenda), sinalizar na entrega
                            if (item.venda_id) {
                                try {
                                    // Buscar a entrega vinculada a esta venda
                                    const { data: entregas, error: erroEntrega } = await supabase
                                        .from('entregas')
                                        .select('id, observacoes')
                                        .eq('venda_id', item.venda_id)
                                        .limit(1);
                                    
                                    if (!erroEntrega && entregas?.length > 0) {
                                        const entrega = entregas[0];
                                        const novaObs = `[DISPONÍVEL NO CD] Item ${item.produto_nome} chegou no Centro de Distribuição em ${new Date().toLocaleDateString('pt-BR')}.`;
                                        
                                        await supabase
                                            .from('entregas')
                                            .update({
                                                observacoes: entrega.observacoes 
                                                    ? `${entrega.observacoes}\n${novaObs}`
                                                    : novaObs
                                            })
                                            .eq('id', entrega.id);
                                    }
                                } catch (eEntrega) {
                                    console.warn('Erro ao atualizar observação da entrega:', eEntrega);
                                }
                            }

                            // --- SINCRONIZAÇÃO COM ESTOQUE POR UNIDADE (estoque_loja) ---
                            if (produto.codigo_barras) {
                                try {
                                    await supabase.from('estoque_loja').insert({
                                        gtin: produto.codigo_barras,
                                        tenant_id: 'CD',
                                        quantidade: qtdRecebida
                                    });
                                } catch (syncErr) {
                                    console.warn('Erro ao sincronizar estoque por unidade:', syncErr);
                                }
                            }
                        } catch (e) {
                            console.error('Erro ao atualizar estoque do produto:', item.produto_id, e);
                        }
                    }
                }
            }

            // Criar lançamento financeiro (despesa)
            const totalRecebido = Object.entries(quantidadesRecebidas).reduce((sum, [index, qtd]) => {
                return sum + (qtd * (pedido.itens[index]?.preco_unitario || 0));
            }, 0);

            if (totalRecebido > 0) {
                await base44.entities.LancamentoFinanceiro.create({
                    descricao: `Compra de Mercadoria - Pedido ${pedido.numero_pedido} - ${pedido.fornecedor_nome}`,
                    valor: totalRecebido,
                    tipo: 'despesa',
                    categoria_nome: 'Compra de Mercadoria',
                    data_lancamento: new Date().toISOString().split('T')[0],
                    data_vencimento: new Date().toISOString().split('T')[0],
                    status: 'Pendente',
                    pago: false,
                    observacao: `Recebimento do pedido ${pedido.numero_pedido}. Fornecedor: ${pedido.fornecedor_nome}`
                });
            }

            return { todoRecebido };
        },
        onSuccess: ({ todoRecebido }) => {
            queryClient.invalidateQueries({ queryKey: ['pedidos-compra'] });
            queryClient.invalidateQueries({ queryKey: ['pedidos-compra-kanban'] });
            queryClient.invalidateQueries({ queryKey: ['pedidos-compra-recebimento'] });
            queryClient.invalidateQueries({ queryKey: ['produtos'] });
            queryClient.invalidateQueries({ queryKey: ['lancamentos'] });
            queryClient.invalidateQueries({ queryKey: ['pedidos-em-conferencia-global'] });
            toast.success(todoRecebido
                ? 'Pedido recebido completamente! Estoque atualizado.'
                : 'Recebimento parcial registrado!'
            );
            handleClose(true); // Pass true to indicate we are confirming, so we don't revert status
        },
        onError: (error) => {
            toast.error('Erro ao registrar recebimento: ' + error.message);
        }
    });

    const verificarStatusItem = (item, qtdRecebidaAgora) => {
        const totalRecebido = (item.quantidade_recebida || 0) + (qtdRecebidaAgora || 0);
        if (totalRecebido >= item.quantidade_pedida) return 'Completo';
        if (totalRecebido > 0) return 'Parcial';
        return 'Pendente';
    };

    const handleQuantidadeChange = (index, valor) => {
        const item = pedido.itens[index];
        const jaRecebido = item.quantidade_recebida || 0;
        const pendente = item.quantidade_pedida - jaRecebido;
        const novaQtd = Math.min(Math.max(0, parseInt(valor) || 0), pendente);

        setQuantidadesRecebidas({
            ...quantidadesRecebidas,
            [index]: novaQtd
        });
    };

    const receberTudo = () => {
        const novasQuantidades = {};
        (pedido?.itens || []).forEach((item, index) => {
            const jaRecebido = item.quantidade_recebida || 0;
            novasQuantidades[index] = item.quantidade_pedida - jaRecebido;
        });
        setQuantidadesRecebidas(novasQuantidades);
    };

    const totalAReceber = Object.entries(quantidadesRecebidas).reduce((sum, [index, qtd]) => {
        return sum + (qtd * (pedido?.itens[index]?.preco_unitario || 0));
    }, 0);

    const algumItemParaReceber = Object.values(quantidadesRecebidas).some(q => q > 0);

    return (
        <Dialog open={open} onOpenChange={(isOpen) => {
            if (!isOpen) {
                handleClose(false);
            }
        }}>
            <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle className="flex items-center gap-2">
                        <PackageCheck className="w-5 h-5 text-green-600" />
                        Receber Pedido {pedido?.numero_pedido}
                    </DialogTitle>
                </DialogHeader>

                <div className="space-y-6">
                    {/* Info do Fornecedor */}
                    <div className="bg-gray-50 rounded-lg p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-sm text-gray-500">Fornecedor</p>
                                <p className="font-medium">{pedido?.fornecedor_nome}</p>
                            </div>
                            <div className="flex items-center gap-3">
                                <Badge className={statusLocal === 'Em Conferência' ? 'bg-blue-500 hover:bg-blue-600 text-white outline-none border-transparent' : ''}>
                                    {statusLocal}
                                </Badge>
                            </div>
                        </div>
                    </div>

                    {/* Botão receber tudo */}
                    <div className="flex justify-end">
                        <Button variant="outline" onClick={receberTudo} size="sm">
                            <Check className="w-4 h-4 mr-2" />
                            Receber Tudo
                        </Button>
                    </div>

                    {/* Tabela de itens */}
                    <div className="border rounded-lg overflow-hidden">
                        <Table>
                            <TableHeader>
                                <TableRow>
                                    <TableHead>Produto</TableHead>
                                    <TableHead className="text-center">Pedido</TableHead>
                                    <TableHead className="text-center">Já Recebido</TableHead>
                                    <TableHead className="text-center">Receber Agora</TableHead>
                                    <TableHead className="text-right">Valor</TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {(pedido?.itens || []).map((item, index) => {
                                    const jaRecebido = item.quantidade_recebida || 0;
                                    const pendente = item.quantidade_pedida - jaRecebido;
                                    const recebendoAgora = quantidadesRecebidas[index] || 0;
                                    const completo = jaRecebido + recebendoAgora >= item.quantidade_pedida;

                                    return (
                                        <TableRow key={index} className={completo ? 'bg-green-50' : ''}>
                                            <TableCell>
                                                <div className="flex flex-col">
                                                    <div className="flex items-center gap-2">
                                                        <Package className="w-4 h-4 text-gray-400" />
                                                        <span className="font-medium">
                                                            {item.produto_nome}
                                                            {item.detalhes?.modelo && <span className="text-gray-400 font-normal ml-1">({item.detalhes.modelo})</span>}
                                                        </span>
                                                    </div>
                                                    {item.detalhes && (
                                                        <div className="flex flex-wrap gap-x-3 gap-y-1 mt-1 text-xs text-gray-500 ml-6">
                                                            {item.detalhes.cor && (
                                                                <span title="Cor">Cor: {item.detalhes.cor}</span>
                                                            )}
                                                            {item.detalhes.dimensoes && item.detalhes.dimensoes !== 'x x' && item.detalhes.dimensoes !== 'xx' && (
                                                                <span title="Dimensões">Dim: {item.detalhes.dimensoes}</span>
                                                            )}
                                                        </div>
                                                    )}
                                                    {item.produto_codigo && (
                                                        <p className="text-xs text-gray-500 ml-6">
                                                            Cód: {item.produto_codigo}
                                                        </p>
                                                    )}
                                                </div>
                                            </TableCell>
                                            <TableCell className="text-center font-bold">
                                                {item.quantidade_pedida}
                                            </TableCell>
                                            <TableCell className="text-center">
                                                {jaRecebido > 0 ? (
                                                    <Badge variant="outline" className="bg-blue-50">
                                                        {jaRecebido}
                                                    </Badge>
                                                ) : (
                                                    <span className="text-gray-400">-</span>
                                                )}
                                            </TableCell>
                                            <TableCell className="text-center">
                                                {pendente > 0 ? (
                                                    <Input
                                                        type="number"
                                                        value={recebendoAgora}
                                                        onChange={(e) => handleQuantidadeChange(index, e.target.value)}
                                                        min={0}
                                                        max={pendente}
                                                        className="w-20 text-center mx-auto"
                                                    />
                                                ) : (
                                                    <Badge className="bg-green-100 text-green-800">
                                                        <Check className="w-3 h-3 mr-1" />
                                                        Completo
                                                    </Badge>
                                                )}
                                            </TableCell>
                                            <TableCell className="text-right">
                                                R$ {(recebendoAgora * item.preco_unitario).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                                            </TableCell>
                                        </TableRow>
                                    );
                                })}
                            </TableBody>
                        </Table>
                    </div>

                    {/* Observação */}
                    <div>
                        <Label>Observação do Recebimento</Label>
                        <Textarea
                            value={observacaoRecebimento}
                            onChange={(e) => setObservacaoRecebimento(e.target.value)}
                            placeholder="Ex: Recebido por João às 14h. Sem avarias."
                            rows={2}
                        />
                    </div>

                    {/* Total e botões */}
                    <div className="flex items-center justify-between pt-4 border-t">
                        <div>
                            <p className="text-sm text-gray-500">Total a dar entrada:</p>
                            <p className="text-2xl font-bold text-green-600">
                                R$ {totalAReceber.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                            </p>
                        </div>
                        <div className="flex gap-3">
                            <Button variant="outline" onClick={() => handleClose(false)}>
                                Cancelar
                            </Button>
                            <Button
                                onClick={() => receberPedido.mutate()}
                                disabled={!algumItemParaReceber || receberPedido.isPending}
                                className="bg-green-600 hover:bg-green-700"
                            >
                                {receberPedido.isPending ? (
                                    'Processando...'
                                ) : (
                                    <>
                                        <PackageCheck className="w-4 h-4 mr-2" />
                                        Confirmar Recebimento
                                    </>
                                )}
                            </Button>
                        </div>
                    </div>

                    {/* Aviso */}
                    <div className="bg-amber-50 border border-amber-200 rounded-lg p-3 flex items-start gap-2">
                        <AlertCircle className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" />
                        <div className="text-sm text-amber-700">
                            <p className="font-medium">Atenção</p>
                            <p>Ao confirmar, o estoque dos produtos será atualizado automaticamente e um lançamento financeiro (despesa) será criado.</p>
                        </div>
                    </div>
                </div>
            </DialogContent>
        </Dialog>
    );
}

import React, { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Loader2 } from "lucide-react";
import { useLojas } from "@/hooks/useLojas";

export default function TransferenciaModal({
  open,
  onOpenChange,
  isOpen: legacyIsOpen,
  onClose: legacyOnClose,
  onSave,
  transferencia,
  produtos,
  isLoading
}) {
  const { data: lojasReal = [] } = useLojas();
  const [formData, setFormData] = useState({
    numero_transferencia: "",
    produto_id: "",
    produto_nome: "",
    loja_origem: "",
    loja_destino: "",
    quantidade: 0,
    data_solicitacao: new Date().toISOString().split('T')[0],
    status: "Solicitada",
    motivo: "",
    observacoes: "",
  });

  const isOpen = open ?? legacyIsOpen ?? false;
  const handleClose = () => {
    if (typeof onOpenChange === "function") {
      onOpenChange(false);
      return;
    }
    if (typeof legacyOnClose === "function") {
      legacyOnClose();
    }
  };

  useEffect(() => {
    if (transferencia) {
      setFormData(transferencia);
    } else {
      const numeroTransf = `TRANSF-${Date.now()}`;
      setFormData({
        numero_transferencia: numeroTransf,
        produto_id: "",
        produto_nome: "",
        loja_origem: "",
        loja_destino: "",
        quantidade: 0,
        data_solicitacao: new Date().toISOString().split('T')[0],
        status: "Solicitada",
        motivo: "",
        observacoes: "",
      });
    }
  }, [transferencia, isOpen]);

  const handleProdutoChange = (produtoId) => {
    const produto = produtos.find(p => p.id === produtoId);
    setFormData({
      ...formData,
      produto_id: produtoId,
      produto_nome: produto?.nome || ""
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!formData.produto_id || !formData.loja_origem || !formData.loja_destino || formData.quantidade <= 0) {
      alert("Preencha todos os campos obrigatórios");
      return;
    }

    if (formData.loja_origem === formData.loja_destino) {
      alert("As lojas de origem e destino devem ser diferentes");
      return;
    }

    onSave(formData);
  };

  return (
    <Dialog
      open={isOpen}
      onOpenChange={(nextOpen) => {
        if (typeof onOpenChange === "function") {
          onOpenChange(nextOpen);
          return;
        }
        if (!nextOpen) {
          legacyOnClose?.();
        }
      }}
    >
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle style={{ color: '#07593f' }}>
            {transferencia ? "Editar Transferência" : "Nova Transferência"}
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit}>
          <div className="space-y-4">
            <div>
              <Label htmlFor="numero_transferencia">Número da Transferência</Label>
              <Input
                id="numero_transferencia"
                value={formData.numero_transferencia}
                disabled
              />
            </div>

            <div>
              <Label htmlFor="produto">Produto *</Label>
              <Select
                value={formData.produto_id}
                onValueChange={handleProdutoChange}
                required
              >
                <SelectTrigger>
                  <SelectValue placeholder="Selecione um produto" />
                </SelectTrigger>
                <SelectContent>
                  {produtos.map(produto => (
                    <SelectItem key={produto.id} value={produto.id}>
                      {produto.nome} (Estoque: {produto.quantidade_estoque})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="grid md:grid-cols-3 gap-4">
              <div>
                <Label htmlFor="loja_origem">Loja Origem *</Label>
                <Select
                  value={formData.loja_origem}
                  onValueChange={(value) => setFormData({ ...formData, loja_origem: value })}
                  required
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Origem" />
                  </SelectTrigger>
                  <SelectContent>
                    {lojasReal.map(loja => (
                      <SelectItem key={loja.id} value={loja.nome}>{loja.nome}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div>
                <Label htmlFor="loja_destino">Loja Destino *</Label>
                <Select
                  value={formData.loja_destino}
                  onValueChange={(value) => setFormData({ ...formData, loja_destino: value })}
                  required
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Destino" />
                  </SelectTrigger>
                  <SelectContent>
                    {lojasReal.map(loja => (
                      <SelectItem key={loja.id} value={loja.nome}>{loja.nome}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div>
                <Label htmlFor="quantidade">Quantidade *</Label>
                <Input
                  id="quantidade"
                  type="number"
                  min="1"
                  value={formData.quantidade}
                  onChange={(e) => setFormData({ ...formData, quantidade: parseInt(e.target.value) || 0 })}
                  required
                />
              </div>
            </div>

            <div>
              <Label htmlFor="motivo">Motivo</Label>
              <Input
                id="motivo"
                value={formData.motivo}
                onChange={(e) => setFormData({ ...formData, motivo: e.target.value })}
                placeholder="Ex: Reposição de estoque, alta demanda..."
              />
            </div>

            <div>
              <Label htmlFor="observacoes">Observações</Label>
              <Textarea
                id="observacoes"
                value={formData.observacoes}
                onChange={(e) => setFormData({ ...formData, observacoes: e.target.value })}
                rows={3}
              />
            </div>
          </div>

          <DialogFooter className="mt-6">
            <Button type="button" variant="outline" onClick={handleClose}>
              Cancelar
            </Button>
            <Button
              type="submit"
              disabled={isLoading}
              style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
            >
              {isLoading ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Salvando...
                </>
              ) : (
                transferencia ? "Atualizar" : "Criar Transferência"
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect } from "react";
import { base44, supabase } from "@/api/base44Client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Plus, ArrowRight, Check } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import TransferenciaModal from "./TransferenciaModal";
import { useAuth } from "@/hooks/useAuth";


export default function TransferenciasTab({ user }) {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingTransferencia, setEditingTransferencia] = useState(null);

  const queryClient = useQueryClient();

  // Listen for header action event
  useEffect(() => {
    const handleAction = (e) => {
      if (e.detail === 'transferencias') {
        setEditingTransferencia(null);
        setIsModalOpen(true);
      }
    };
    window.addEventListener('estoque-header-action', handleAction);
    return () => window.removeEventListener('estoque-header-action', handleAction);
  }, []);

  const { data: transferencias = [], isLoading } = useQuery({
    queryKey: ['transferencias'],
    queryFn: () => base44.entities.TransferenciaEstoque.list('-created_date'),
  });

  const { data: produtos = [] } = useQuery({
    queryKey: ['produtos'],
    queryFn: () => base44.entities.Produto.list(),
  });

  const createMutation = useMutation({
    mutationFn: (data) => base44.entities.TransferenciaEstoque.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['transferencias'] });
      setIsModalOpen(false);
    },
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, data }) => base44.entities.TransferenciaEstoque.update(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['transferencias'] });
      queryClient.invalidateQueries({ queryKey: ['produtos'] });
    },
  });

  const handleSave = (data) => {
    if (editingTransferencia) {
      updateMutation.mutate({ id: editingTransferencia.id, data });
    } else {
      createMutation.mutate(data);
    }
  };

  const handleConfirmarRecebimento = async (transferencia) => {
    if (confirm(`Confirmar recebimento de ${transferencia.quantidade} unidades de ${transferencia.produto_nome}?`)) {
      try {
        const { resolveStockField } = await import("@/utils/stockUtils");

        // Find the product to update its stock
        const produto = produtos.find(p => p.id === transferencia.produto_id);
        if (produto) {
          const campoOrigem = resolveStockField(transferencia.loja_origem);
          const campoDestino = resolveStockField(transferencia.loja_destino);
          const qty = transferencia.quantidade || 0;

          const updates = {};

          // Deduct from origin store
          if (campoOrigem) {
            updates[campoOrigem] = Math.max(0, (produto[campoOrigem] || 0) - qty);
          }

          // Add to destination store
          if (campoDestino) {
            updates[campoDestino] = (produto[campoDestino] || 0) + qty;
          }

          // Total quantity_estoque stays the same (it's a transfer)
          if (Object.keys(updates).length > 0) {
            await base44.entities.Produto.update(produto.id, updates);
            try {
              const auditEntries = [];
              if (campoOrigem && qty > 0) {
                auditEntries.push({
                  produto_id: produto.id,
                  evento_tipo: 'transferencia_saida',
                  modulo_origem: 'estoque',
                  quantidade: qty,
                  estoque_antes_local: produto[campoOrigem] || 0,
                  estoque_depois_local: updates[campoOrigem] ?? null,
                  loja_origem: transferencia.loja_origem,
                  loja_destino: transferencia.loja_destino,
                  referencia_id: transferencia.id,
                  usuario_nome: user?.full_name || null,
                  organization_id: '00000000-0000-0000-0000-000000000001'
                });
              }
              if (campoDestino && qty > 0) {
                auditEntries.push({
                  produto_id: produto.id,
                  evento_tipo: 'transferencia_entrada',
                  modulo_origem: 'estoque',
                  quantidade: qty,
                  estoque_antes_local: produto[campoDestino] || 0,
                  estoque_depois_local: updates[campoDestino] ?? null,
                  loja_origem: transferencia.loja_origem,
                  loja_destino: transferencia.loja_destino,
                  referencia_id: transferencia.id,
                  usuario_nome: user?.full_name || null,
                  organization_id: '00000000-0000-0000-0000-000000000001'
                });
              }
              if (auditEntries.length > 0) {
                await supabase.from('movimentacoes_estoque').insert(auditEntries);
              }
            } catch (auditErr) {
              console.warn('Falha ao registrar movimentação de transferência:', auditErr);
            }
          }
        }

        // Update transfer status
        await updateMutation.mutateAsync({
          id: transferencia.id,
          data: {
            ...transferencia,
            status: 'Recebida',
            data_recebimento: new Date().toISOString().split('T')[0],
            responsavel_recebimento: user.full_name
          }
        });
      } catch (error) {
        console.error("Erro ao confirmar recebimento:", error);
      }
    }
  };

  const { can } = useAuth();
  const isAdmin = user?.cargo === 'Administrador';
  const isManager = user?.cargo === 'Gerente';
  const isWarehouse = user?.cargo === 'Estoque';
  const isGerenteGeral = user?.cargo === 'Gerente Geral';
  const canManage = isAdmin || isManager || isWarehouse || isGerenteGeral || can('manage_estoque');

  const statusColors = {
    "Solicitada": { bg: "#FEF3C7", text: "#92400E", border: "#FCD34D" },
    "Em Trânsito": { bg: "#DBEAFE", text: "#1E40AF", border: "#93C5FD" },
    "Recebida": { bg: "#D1FAE5", text: "#065F46", border: "#6EE7B7" },
    "Cancelada": { bg: "#FEE2E2", text: "#991B1B", border: "#FCA5A5" }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <p style={{ color: '#8B8B8B' }}>
          {transferencias.length} transferência(s) registrada(s)
        </p>
        {canManage && (
          <Button
            onClick={() => {
              setEditingTransferencia(null);
              setIsModalOpen(true);
            }}
            className="shadow-lg"
            style={{ background: 'linear-gradient(135deg, #f38a4c 0%, #f5a164 100%)' }}
          >
            <Plus className="w-4 h-4 mr-2" />
            Nova Transferência
          </Button>
        )}
      </div>

      {isLoading ? (
        <div className="text-center py-12">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 mx-auto" style={{ borderColor: '#07593f' }} />
        </div>
      ) : (
        <div className="grid grid-cols-1 gap-6">
          {transferencias.map((transferencia) => (
            <Card key={transferencia.id} className="border-0 shadow-lg">
              <CardHeader>
                <div className="flex items-start justify-between">
                  <div>
                    <CardTitle className="flex items-center gap-2">
                      <span style={{ color: '#07593f' }}>
                        Transferência #{transferencia.numero_transferencia}
                      </span>
                      <Badge
                        style={{
                          backgroundColor: statusColors[transferencia.status]?.bg,
                          color: statusColors[transferencia.status]?.text,
                          borderColor: statusColors[transferencia.status]?.border,
                        }}
                        className="border"
                      >
                        {transferencia.status}
                      </Badge>
                    </CardTitle>
                    <p className="text-sm mt-1" style={{ color: '#8B8B8B' }}>
                      Solicitada em {new Date(transferencia.data_solicitacao).toLocaleDateString('pt-BR')}
                    </p>
                  </div>
                  {transferencia.status === 'Em Trânsito' && canManage && (
                    <Button
                      size="sm"
                      onClick={() => handleConfirmarRecebimento(transferencia)}
                      style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
                    >
                      <Check className="w-4 h-4 mr-2" />
                      Confirmar Recebimento
                    </Button>
                  )}
                </div>
              </CardHeader>
              <CardContent>
                <div className="grid md:grid-cols-3 gap-6">
                  <div>
                    <p className="text-sm font-medium mb-2" style={{ color: '#8B8B8B' }}>Produto</p>
                    <p className="font-semibold" style={{ color: '#07593f' }}>
                      {transferencia.produto_nome}
                    </p>
                    <p className="text-sm" style={{ color: '#8B8B8B' }}>
                      Quantidade: {transferencia.quantidade} unidades
                    </p>
                  </div>
                  <div>
                    <p className="text-sm font-medium mb-2" style={{ color: '#8B8B8B' }}>Rota</p>
                    <div className="flex items-center gap-2">
                      <Badge variant="outline">{transferencia.loja_origem}</Badge>
                      <ArrowRight className="w-4 h-4" style={{ color: '#f38a4c' }} />
                      <Badge variant="outline">{transferencia.loja_destino}</Badge>
                    </div>
                    {transferencia.motivo && (
                      <p className="text-xs mt-2" style={{ color: '#8B8B8B' }}>
                        Motivo: {transferencia.motivo}
                      </p>
                    )}
                  </div>
                  <div>
                    <p className="text-sm font-medium mb-2" style={{ color: '#8B8B8B' }}>Datas</p>
                    {transferencia.data_envio && (
                      <p className="text-sm" style={{ color: '#8B8B8B' }}>
                        Enviado: {new Date(transferencia.data_envio).toLocaleDateString('pt-BR')}
                      </p>
                    )}
                    {transferencia.data_recebimento && (
                      <p className="text-sm" style={{ color: '#8B8B8B' }}>
                        Recebido: {new Date(transferencia.data_recebimento).toLocaleDateString('pt-BR')}
                      </p>
                    )}
                  </div>
                </div>
                {transferencia.observacoes && (
                  <div className="mt-4 pt-4 border-t" style={{ borderColor: '#E5E0D8' }}>
                    <p className="text-sm" style={{ color: '#8B8B8B' }}>
                      <strong>Observações:</strong> {transferencia.observacoes}
                    </p>
                  </div>
                )}
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {transferencias.length === 0 && !isLoading && (
        <div className="text-center py-16">
          <p className="text-xl" style={{ color: '#8B8B8B' }}>
            Nenhuma transferência registrada
          </p>
        </div>
      )}

      <TransferenciaModal
        isOpen={isModalOpen}
        onClose={() => {
          setIsModalOpen(false);
          setEditingTransferencia(null);
        }}
        onSave={handleSave}
        transferencia={editingTransferencia}
        produtos={produtos}
        isLoading={createMutation.isPending}
      />
    </div>
  );
}

import React, { useEffect, useRef, useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Search, Unlock, Clock, MapPin, Package, Loader2, AlertTriangle } from "lucide-react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/hooks/useAuth";
import { base44 } from "@/api/base44Client";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { toast } from "sonner";

export default function AguardandoLiberacao({ entregas, vendas }) {
  const { user } = useAuth();
  const [search, setSearch] = useState("");
  const [modalLiberarEntrega, setModalLiberarEntrega] = useState(null); // { entregaId, pedido }
  const queryClient = useQueryClient();
  const processingAutoReleaseRef = useRef(false);

  const formatarData = (dateString) => {
    if (!dateString) return "-";
    return new Date(`${dateString.split('T')[0]}T12:00:00`).toLocaleDateString('pt-BR');
  };

  const montarAvisoLiberacao = ({ dataRecebimento, dataLiberacao }) => {
    const recebimentoFormatado = dataRecebimento
      ? new Date(dataRecebimento).toLocaleDateString('pt-BR')
      : '-';
    const liberacaoFormatada = formatarData(dataLiberacao);
    return `Pedido recebido em ${recebimentoFormatado}, com liberação prevista para ${liberacaoFormatada}.`;
  };

  useEffect(() => {
    if (processingAutoReleaseRef.current) return;

    const hojeIso = new Date().toISOString().split('T')[0];
    const entregasAutoLiberaveis = (entregas || []).filter((entrega) =>
      entrega.status === 'Aguardando Liberação' &&
      entrega.data_liberacao &&
      entrega.data_liberacao <= hojeIso
    );

    if (!entregasAutoLiberaveis.length) return;

    processingAutoReleaseRef.current = true;

    const autoLiberar = async () => {
      try {
        await Promise.all(
          entregasAutoLiberaveis.map((entrega) => {
            const aviso = montarAvisoLiberacao({
              dataRecebimento: entrega.created_date || entrega.created_at,
              dataLiberacao: entrega.data_liberacao
            });
            const observacoesBase = entrega.observacoes ? `${entrega.observacoes}\n` : '';

            return base44.entities.Entrega.update(entrega.id, {
              status: 'Pendente',
              data_agendada: null,
              turno: null,
              observacoes: `${observacoesBase}${aviso}`
            });
          })
        );

        queryClient.invalidateQueries({ queryKey: ['entregas'] });
        toast.success(`${entregasAutoLiberaveis.length} pedido(s) foram liberados automaticamente para a Triagem.`);
      } catch (error) {
        console.error('Erro ao liberar entregas automaticamente:', error);
        toast.error('Erro ao processar liberação automática das entregas.');
      } finally {
        processingAutoReleaseRef.current = false;
      }
    };

    autoLiberar();
  }, [entregas, queryClient]);

  const liberarEntregaMutation = useMutation({
    mutationFn: ({ entregaId, dataLiberacao, dataRecebimento, observacoesAtuais }) => {
      const observacaoLiberacao = dataLiberacao
        ? montarAvisoLiberacao({ dataRecebimento, dataLiberacao })
        : "Entrega liberada pelo cliente.";

      return base44.entities.Entrega.update(entregaId, {
        status: 'Pendente', // Volta para ser um pedido "Pendente" normal
        data_agendada: null,
        turno: null,
        observacoes: observacoesAtuais ? `${observacoesAtuais}\n${observacaoLiberacao}` : observacaoLiberacao
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['entregas'] });
      toast.success("Entrega liberada! O pedido voltou para a Triagem.");
      setModalLiberarEntrega(null);
    },
    onError: () => {
      toast.error("Erro ao liberar entrega.");
    }
  });

  const confirmarLiberarEntrega = () => {
    if (!modalLiberarEntrega) return;
    liberarEntregaMutation.mutate({
      entregaId: modalLiberarEntrega.entregaId,
      dataLiberacao: modalLiberarEntrega.dataLiberacao,
      dataRecebimento: modalLiberarEntrega.dataRecebimento,
      observacoesAtuais: modalLiberarEntrega.observacoesAtuais
    });
  };

  const entregasFiltradas = entregas.filter(e => {
    const termo = search.toLowerCase();
    return (
      e.cliente_nome?.toLowerCase().includes(termo) ||
      e.numero_pedido?.toString().includes(termo) ||
      e.endereco_entrega?.toLowerCase().includes(termo)
    );
  });

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-100">
        <div className="p-3 bg-amber-100 rounded-full text-amber-700">
          <Clock className="w-6 h-6" />
        </div>
        <div className="flex-1">
          <h2 className="text-lg font-bold text-gray-800">Aguardando Liberação do Cliente</h2>
          <p className="text-sm text-gray-500">Pedidos reservados que precisam de autorização para entrega (ex: obra atrasada)</p>
        </div>
        <div className="relative w-72">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <Input
            placeholder="Buscar cliente ou pedido..."
            className="pl-9"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {entregasFiltradas.length > 0 ? (
          entregasFiltradas.map(entrega => {
            const venda = (vendas || []).find(v => v.id === entrega.venda_id);
            const itens = venda?.itens?.map(i => `${i.quantidade}x ${i.produto_nome}`).join(', ');

            // Apenas o vendedor da venda, Logística ou admin pode liberar
            const isAdmin = user?.cargo === 'Administrador';
            const isLogistica = user?.cargo === 'Logística';
            const isVendedorDaVenda = venda?.responsavel_id === user?.id;
            const isGerenteDaLoja = user?.cargo === 'Gerente' && venda?.loja === user?.loja;

            const podeLiberar = isAdmin || isLogistica || isVendedorDaVenda || isGerenteDaLoja;


            return (
              <Card key={entrega.id} className="hover:shadow-md transition-all border-l-4 border-l-amber-400">
                <CardContent className="p-4">
                  <div className="flex justify-between items-start mb-2">
                    <Badge variant="outline" className="font-mono">#{entrega.numero_pedido}</Badge>
                    <span className="text-xs text-gray-400 font-medium">
                      {entrega.created_date ? new Date(entrega.created_date).toLocaleDateString() : '-'}
                    </span>
                  </div>

                  <h3 className="font-bold text-gray-800 mb-1">{entrega.cliente_nome}</h3>

                  <div className="bg-gray-50 p-2 rounded text-xs text-gray-600 mb-3 flex gap-2">
                    <Package className="w-4 h-4 shrink-0 mt-0.5 text-gray-400" />
                    <p className="line-clamp-2">{itens || "Sem itens"}</p>
                  </div>

                  <div className="flex items-center gap-2 text-xs text-gray-500 mb-4">
                    <MapPin className="w-3 h-3" />
                    <span className="truncate">{entrega.endereco_entrega}</span>
                  </div>

                  {entrega.data_liberacao && (
                    <div className="mb-3 rounded-md border border-amber-200 bg-amber-50 px-3 py-2 text-xs text-amber-900 flex items-start gap-2">
                      <AlertTriangle className="w-3.5 h-3.5 shrink-0 mt-0.5" />
                      <span>Este pedido será liberado a partir de <strong>{formatarData(entrega.data_liberacao)}</strong>.</span>
                    </div>
                  )}

                  {podeLiberar ? (
                    <Button
                      className="w-full bg-green-600 hover:bg-green-700 gap-2"
                      onClick={() => {
                        setModalLiberarEntrega({
                          entregaId: entrega.id,
                          pedido: entrega.numero_pedido,
                          dataLiberacao: entrega.data_liberacao,
                          dataRecebimento: entrega.created_date || entrega.created_at,
                          observacoesAtuais: entrega.observacoes || ""
                        });
                      }}
                      disabled={liberarEntregaMutation.isPending}
                    >
                      <Unlock className="w-4 h-4" />
                      Entrega Liberada
                    </Button>
                  ) : (
                    <div className="text-[10px] text-gray-400 italic bg-gray-50 px-3 py-2 rounded border border-gray-100 flex items-center gap-2">
                      <Clock className="w-3.5 h-3.5" />
                      Aguardando Liberação do Vendedor/Gerente
                    </div>
                  )}
                </CardContent>
              </Card>
            )
          })
        ) : (
          <div className="col-span-full py-12 text-center text-gray-400 bg-gray-50 rounded-xl border border-dashed border-gray-200">
            <Clock className="w-12 h-12 mx-auto mb-2 opacity-20" />
            <p>Nenhum pedido aguardando liberação.</p>
          </div>
        )}
      </div>

      {/* Modal de Liberar Entrega */}
      <Dialog open={!!modalLiberarEntrega} onOpenChange={(open) => !open && setModalLiberarEntrega(null)}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-green-600">
              <Unlock className="w-5 h-5" />
              Confirmar Liberação de Entrega
            </DialogTitle>
            <DialogDescription>
              Autorizar que a logística processe esta entrega.
            </DialogDescription>
          </DialogHeader>
          <div className="py-4">
            <p className="text-sm text-gray-700 mb-4">
              <strong>Pedido:</strong> #{modalLiberarEntrega?.pedido}
            </p>
            <p className="text-sm text-gray-600">
              Após confirmar, o pedido voltará para a fila de triagem da logística e poderá ser agendado para entrega.
            </p>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setModalLiberarEntrega(null)}>
              Cancelar
            </Button>
            <Button
              onClick={confirmarLiberarEntrega}
              disabled={liberarEntregaMutation.isPending}
              className="bg-green-600 hover:bg-green-700"
            >
              {liberarEntregaMutation.isPending ? (
                <><Loader2 className="w-4 h-4 mr-2 animate-spin" />Liberando...</>
              ) : (
                <><Unlock className="w-4 h-4 mr-2" />Confirmar Liberação</>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useRef, useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Eraser, Check, RotateCcw } from "lucide-react";

export default function AssinaturaCanvas({ onSave, onCancel }) {
    const canvasRef = useRef(null);
    const [isDrawing, setIsDrawing] = useState(false);
    const [hasDrawn, setHasDrawn] = useState(false);

    useEffect(() => {
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');

        // Configurar canvas responsivo
        const resizeCanvas = () => {
            const rect = canvas.getBoundingClientRect();
            canvas.width = rect.width * window.devicePixelRatio;
            canvas.height = rect.height * window.devicePixelRatio;
            ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

            // Configurar estilo do traço
            ctx.strokeStyle = '#000';
            ctx.lineWidth = 3;
            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';

            // Fundo branco
            ctx.fillStyle = '#fff';
            ctx.fillRect(0, 0, rect.width, rect.height);

            // Linha de assinatura
            ctx.strokeStyle = '#ccc';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(20, rect.height - 40);
            ctx.lineTo(rect.width - 20, rect.height - 40);
            ctx.stroke();

            // Resetar estilo para desenho
            ctx.strokeStyle = '#000';
            ctx.lineWidth = 3;
        };

        resizeCanvas();
        window.addEventListener('resize', resizeCanvas);
        return () => window.removeEventListener('resize', resizeCanvas);
    }, []);

    const getCoords = (e) => {
        const canvas = canvasRef.current;
        const rect = canvas.getBoundingClientRect();
        
        // Fator de proporção: Tamanho interno (pixels reais) vs Tamanho na tela (CSS)
        // Isso resolve o problema de 'drift' da caneta, especialmente no celular
        const scaleX = canvas.width / rect.width;
        const scaleY = canvas.height / rect.height;

        let clientX, clientY;

        if (e.touches && e.touches.length > 0) {
            clientX = e.touches[0].clientX;
            clientY = e.touches[0].clientY;
        } else {
            clientX = e.clientX;
            clientY = e.clientY;
        }

        return {
            x: ((clientX - rect.left) * scaleX) / window.devicePixelRatio,
            y: ((clientY - rect.top) * scaleY) / window.devicePixelRatio
        };
    };

    const startDrawing = (e) => {
        e.preventDefault();
        const coords = getCoords(e);
        const ctx = canvasRef.current.getContext('2d');
        ctx.beginPath();
        ctx.moveTo(coords.x, coords.y);
        setIsDrawing(true);
        setHasDrawn(true);
    };

    const draw = (e) => {
        if (!isDrawing) return;
        e.preventDefault();
        const coords = getCoords(e);
        const ctx = canvasRef.current.getContext('2d');
        ctx.lineTo(coords.x, coords.y);
        ctx.stroke();
    };

    const stopDrawing = (e) => {
        e?.preventDefault();
        setIsDrawing(false);
    };

    const limpar = () => {
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        const rect = canvas.getBoundingClientRect();

        ctx.fillStyle = '#fff';
        ctx.fillRect(0, 0, rect.width, rect.height);

        // Redesenhar linha
        ctx.strokeStyle = '#ccc';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(20, rect.height - 40);
        ctx.lineTo(rect.width - 20, rect.height - 40);
        ctx.stroke();

        ctx.strokeStyle = '#000';
        ctx.lineWidth = 3;
        setHasDrawn(false);
    };

    const salvar = () => {
        if (!hasDrawn) {
            alert("Por favor, assine antes de confirmar.");
            return;
        }

        const canvas = canvasRef.current;
        const dataUrl = canvas.toDataURL('image/png');
        onSave(dataUrl);
    };

    return (
        <div className="flex flex-col h-full space-y-4">
            <div className="text-center">
                <p className="text-sm text-gray-500">Assine com o dedo na área abaixo</p>
            </div>

            <div className="flex-1 min-h-[50vh] border-2 border-gray-300 rounded-xl overflow-hidden bg-white touch-none">
                <canvas
                    ref={canvasRef}
                    className="w-full h-full cursor-crosshair"
                    onMouseDown={startDrawing}
                    onMouseMove={draw}
                    onMouseUp={stopDrawing}
                    onMouseLeave={stopDrawing}
                    onTouchStart={startDrawing}
                    onTouchMove={draw}
                    onTouchEnd={stopDrawing}
                />
            </div>

            <div className="flex gap-2 mt-auto">
                <Button
                    variant="outline"
                    onClick={limpar}
                    className="flex-1"
                >
                    <RotateCcw className="w-4 h-4 mr-2" />
                    Limpar
                </Button>
                <Button
                    onClick={salvar}
                    disabled={!hasDrawn}
                    className="flex-1 bg-green-600 hover:bg-green-700"
                >
                    <Check className="w-4 h-4 mr-2" />
                    Confirmar Assinatura
                </Button>
            </div>

            {onCancel && (
                <Button variant="ghost" onClick={onCancel} className="w-full">
                    Cancelar
                </Button>
            )}
        </div>
    );
}

import React from "react";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { useDraggable } from "@dnd-kit/core";
import { Map, MessageCircle, Wrench, Package, ArrowLeftRight, AlertTriangle, Settings, User } from "lucide-react";

// Cores para cada tipo de assistência (ícones e textos apenas)
const TIPO_STYLES = {
    'Devolução': { icon: Package },
    'Troca': { icon: ArrowLeftRight },
    'Peça Faltante': { icon: Settings },
    'Conserto': { icon: Wrench },
    'Visita Técnica': { icon: Map },
    'Outros': { icon: AlertTriangle }
};

// Cores de FUNDO completas baseadas na prioridade
// Urgente (Vermelho), Alta (Laranja/Amarelo - User pediu Vermelho/Amarelo/Verde, vou ajustar)
// O user disse: "Verde - Amarelo - Vermelho".
// Vamos mapear:
// Urgente -> Vermelho (bg-red-50 border-red-200)
// Alta -> Laranja (bg-orange-50 border-orange-200) - Ou Amarelo forte? User disse Amarelo
// Normal -> Amarelo (bg-yellow-50 border-yellow-200) - Ou Verde? User disse Verde-Amarelo-Vermelho.
// Baixa -> Verde (bg-green-50 border-green-200)

const PRIORITY_THEMES = {
    'Urgente': { cardBg: 'bg-red-50', border: 'border-red-200', badgeInfo: 'bg-red-200 text-red-800', textMain: 'text-red-900', textSub: 'text-red-700' },
    'Alta': { cardBg: 'bg-orange-50', border: 'border-orange-200', badgeInfo: 'bg-orange-200 text-orange-800', textMain: 'text-orange-900', textSub: 'text-orange-700' },
    'Normal': { cardBg: 'bg-yellow-50', border: 'border-yellow-200', badgeInfo: 'bg-yellow-200 text-yellow-800', textMain: 'text-yellow-900', textSub: 'text-yellow-700' },
    'Baixa': { cardBg: 'bg-green-50', border: 'border-green-200', badgeInfo: 'bg-green-200 text-green-800', textMain: 'text-green-900', textSub: 'text-green-700' },
    'default': { cardBg: 'bg-white', border: 'border-gray-200', badgeInfo: 'bg-gray-100 text-gray-800', textMain: 'text-gray-900', textSub: 'text-gray-600' }
};

export default function AssistenciaCard({ assistencia, onClick, isColumn = false }) {
    const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
        id: `at-${assistencia.id}`,
        data: { assistencia, isAssistencia: true }
    });

    const contatoManual = (e) => {
        e.stopPropagation();
        const tel = assistencia.cliente_telefone?.replace(/\D/g, '');
        if (tel) window.open(`https://wa.me/55${tel}`, '_blank');
        else alert("Telefone não cadastrado");
    };

    const tipoStyle = TIPO_STYLES[assistencia.tipo] || TIPO_STYLES['Outros'];
    const IconComponent = tipoStyle.icon;

    // Determinar tema pela prioridade
    const theme = PRIORITY_THEMES[assistencia.prioridade] || PRIORITY_THEMES['default'];

    const itensTexto = assistencia.itens_envolvidos?.map(i => i.produto_nome).join(', ') || 'Itens não especificados';

    return (
        <div
            ref={setNodeRef}
            {...listeners}
            {...attributes}
            onClick={() => onClick && onClick(assistencia)}
            className={`cursor-grab active:cursor-grabbing transition-all group mb-2 ${isDragging ? 'opacity-50 scale-95' : ''} h-full`}
        >
            <Card className={`
                relative overflow-hidden hover:shadow-lg transition-all 
                border shadow-sm ${theme.border} ${theme.cardBg}
                flex flex-col justify-start gap-1.5
                ${isColumn ? 'p-2 min-h-[90px]' : 'p-2.5 h-full'} 
            `}>

                {/* Topo: Cliente E Num Pedido/Badge */}
                <div className="flex justify-between items-start">
                    <div className="flex items-center gap-1.5 overflow-hidden flex-1 min-w-0">
                        <User className={`w-3 h-3 shrink-0 ${theme.textSub}`} />
                        <span className={`font-bold text-[10px] truncate uppercase ${theme.textMain}`} title={assistencia.cliente_nome}>
                            {assistencia.cliente_nome}
                        </span>
                    </div>

                    <div className={`flex items-center gap-1 shrink-0 px-1 py-0.5 rounded ml-1 ${theme.badgeInfo}`}>
                        <span className="font-mono text-[9px] font-bold">#{assistencia.numero_pedido}</span>
                        <Badge className="text-[8px] px-1 py-0 h-4 bg-purple-600 hover:bg-purple-700 text-white font-bold shadow-none border-0">
                            AT
                        </Badge>
                    </div>
                </div>

                {/* Tipo de Assistência (Como se fosse Endereço no card de Entrega) */}
                <div
                    className={`flex items-center gap-1 w-full rounded py-0.5 px-1 bg-white/50 border border-transparent`}
                >
                    <IconComponent className={`w-3 h-3 shrink-0 ${theme.textMain}`} />
                    <span className={`text-[10px] font-bold uppercase tracking-wider truncate ${theme.textMain}`}>
                        {assistencia.tipo}
                    </span>
                </div>

                {/* Meio: Itens (Compacto) */}
                <div className="flex-1 min-h-0 flex items-start gap-1.5 overflow-hidden">
                    <Package className={`w-3 h-3 mt-0.5 shrink-0 ${theme.textSub}`} />
                    <p className={`text-[10px] font-normal leading-3 line-clamp-3 ${theme.textSub}`} title={itensTexto}>
                        {itensTexto}
                    </p>
                </div>

                {/* Bottom: Status / WhatsApp */}
                <div className={`mt-auto pt-1 border-t border-dashed ${theme.border} flex items-center justify-between gap-1`}>
                    <Badge variant="outline" className={`text-[8px] px-1 h-4 bg-white/50 ${theme.textSub} border-0`}>
                        {assistencia.status}
                    </Badge>

                    <button
                        onClick={contatoManual}
                        className={`h-4 w-4 flex items-center justify-center rounded-full hover:bg-white/50 ${theme.textMain}`}
                        title="Chamar no WhatsApp"
                    >
                        <MessageCircle className="w-3 h-3" />
                    </button>
                </div>

            </Card>
        </div>
    );
}

import React, { useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import { Camera, RotateCcw, Check, Upload, X } from "lucide-react";

export default function CameraCapture({ onCapture, onCancel, titulo = "Tirar Foto" }) {
    const videoRef = useRef(null);
    const canvasRef = useRef(null);
    const fileInputRef = useRef(null);
    const [stream, setStream] = useState(null);
    const [foto, setFoto] = useState(null);
    const [cameraAtiva, setCameraAtiva] = useState(false);
    const [erro, setErro] = useState(null);

    const iniciarCamera = async () => {
        try {
            setErro(null);
            const mediaStream = await navigator.mediaDevices.getUserMedia({
                video: { facingMode: 'environment' }, // Câmera traseira
                audio: false
            });

            setStream(mediaStream);
            setCameraAtiva(true);

            setTimeout(() => {
                if (videoRef.current) {
                    videoRef.current.srcObject = mediaStream;
                    videoRef.current.play().catch(e => console.error("Error playing video:", e));
                }
            }, 100);
        } catch (err) {
            console.error("Erro ao acessar câmera:", err);
            setErro("Não foi possível acessar a câmera. Tente selecionar uma imagem.");
        }
    };

    const pararCamera = () => {
        if (stream) {
            stream.getTracks().forEach(track => track.stop());
            setStream(null);
        }
        setCameraAtiva(false);
    };

    const capturarFoto = () => {
        if (!videoRef.current || !canvasRef.current) return;

        const canvas = canvasRef.current;
        const video = videoRef.current;

        // Default to client dimensions or standard HD if intrinsic dimensions are not yet available
        let width = video.videoWidth || video.clientWidth || 1280;
        let height = video.videoHeight || video.clientHeight || 720;

        // Maximum dimensions to prevent canvas memory/processing errors on mobile
        const MAX_WIDTH = 1280;
        const MAX_HEIGHT = 1280;

        // Calculate aspect ratio and resize if necessary
        if (width > height) {
            if (width > MAX_WIDTH) {
                height *= MAX_WIDTH / width;
                width = MAX_WIDTH;
            }
        } else {
            if (height > MAX_HEIGHT) {
                width *= MAX_HEIGHT / height;
                height = MAX_HEIGHT;
            }
        }

        canvas.width = width;
        canvas.height = height;

        const ctx = canvas.getContext('2d');
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

        try {
            const dataUrl = canvas.toDataURL('image/jpeg', 0.8);
            if (dataUrl === "data:,") {
                console.error("toDataURL returned empty data url. Canvas dimensions:", canvas.width, 'x', canvas.height);
                setErro("Erro de memória ao processar imagem.");
                return;
            }
            setFoto(dataUrl);
            pararCamera();
        } catch (e) {
            console.error("Erro no toDataURL", e);
            setErro("Erro ao processar a foto. Tente novamente.");
        }
    };

    const selecionarArquivo = (e) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
            setFoto(event.target.result);
        };
        reader.readAsDataURL(file);
    };

    const refazer = () => {
        setFoto(null);
        setErro(null);
    };

    const confirmar = () => {
        if (foto) {
            onCapture(foto);
        }
    };

    return (
        <div className="space-y-4">
            <div className="text-center mb-2">
                <p className="font-medium text-gray-700">{titulo}</p>
            </div>

            {/* Área de preview/câmera */}
            <div className="relative bg-gray-900 rounded-xl overflow-hidden aspect-video">
                {foto ? (
                    <img
                        src={foto}
                        alt="Foto capturada"
                        className="w-full h-full object-cover"
                    />
                ) : cameraAtiva ? (
                    <video
                        ref={videoRef}
                        autoPlay
                        playsInline
                        muted
                        className="w-full h-full object-cover"
                    />
                ) : (
                    <div className="flex flex-col items-center justify-center h-full text-white/50">
                        <Camera className="w-12 h-12 mb-2" />
                        <p className="text-sm">Câmera não iniciada</p>
                    </div>
                )}

                {erro && (
                    <div className="absolute inset-0 flex items-center justify-center bg-black/70 text-white p-4 text-center">
                        <p className="text-sm">{erro}</p>
                    </div>
                )}
            </div>

            {/* Canvas oculto para captura */}
            <canvas ref={canvasRef} className="hidden" />

            {/* Controles */}
            {foto ? (
                <div className="flex gap-2">
                    <Button
                        variant="outline"
                        onClick={refazer}
                        className="flex-1"
                    >
                        <RotateCcw className="w-4 h-4 mr-2" />
                        Refazer
                    </Button>
                    <Button
                        onClick={confirmar}
                        className="flex-1 bg-green-600 hover:bg-green-700"
                    >
                        <Check className="w-4 h-4 mr-2" />
                        Usar Foto
                    </Button>
                </div>
            ) : cameraAtiva ? (
                <div className="flex gap-2">
                    <Button
                        variant="outline"
                        onClick={pararCamera}
                        className="flex-1"
                    >
                        <X className="w-4 h-4 mr-2" />
                        Cancelar
                    </Button>
                    <Button
                        onClick={capturarFoto}
                        className="flex-1 bg-blue-600 hover:bg-blue-700"
                    >
                        <Camera className="w-4 h-4 mr-2" />
                        Capturar
                    </Button>
                </div>
            ) : (
                <div className="flex gap-2">
                    <Button
                        onClick={iniciarCamera}
                        className="flex-1 bg-blue-600 hover:bg-blue-700"
                    >
                        <Camera className="w-4 h-4 mr-2" />
                        Abrir Câmera
                    </Button>
                    <Button
                        variant="outline"
                        onClick={() => fileInputRef.current?.click()}
                        className="flex-1"
                    >
                        <Upload className="w-4 h-4 mr-2" />
                        Galeria
                    </Button>
                </div>
            )}

            {/* Input de arquivo oculto */}
            <input
                ref={fileInputRef}
                type="file"
                accept="image/*"
                capture="environment"
                onChange={selecionarArquivo}
                className="hidden"
            />

            {onCancel && (
                <Button variant="ghost" onClick={onCancel} className="w-full">
                    Cancelar
                </Button>
            )}
        </div>
    );
}

import React, { useState, useEffect, useRef } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { MessageCircle, Send, X } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";

export default function ChatEquipe() {
  const [aberto, setAberto] = useState(false);
  const [mensagem, setMensagem] = useState("");
  const [usuario, setUsuario] = useState(null);
  const messagesEndRef = useRef(null);
  const queryClient = useQueryClient();

  useEffect(() => {
    base44.auth.me().then(setUsuario);
  }, []);

  const { data: mensagens = [] } = useQuery({
    queryKey: ['chat-logistica'],
    queryFn: async () => {
      const msgs = await base44.entities.MensagemChat.list('-created_date', 50);
      return msgs.reverse();
    },
    refetchInterval: 3000,
    enabled: aberto
  });

  const enviarMensagem = useMutation({
    mutationFn: async (texto) => {
      return base44.entities.MensagemChat.create({
        usuario_nome: usuario?.full_name || 'Usuário',
        usuario_email: usuario?.email,
        mensagem: texto,
        tipo: 'logistica'
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['chat-logistica'] });
      setMensagem("");
    }
  });

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    if (aberto) scrollToBottom();
  }, [mensagens, aberto]);

  const handleEnviar = (e) => {
    e.preventDefault();
    if (mensagem.trim() && usuario) {
      enviarMensagem.mutate(mensagem.trim());
    }
  };

  if (!aberto) {
    return (
      <Button
        onClick={() => setAberto(true)}
        className="fixed bottom-6 right-6 h-14 w-14 rounded-full shadow-lg bg-green-600 hover:bg-green-700 z-50"
      >
        <MessageCircle className="w-6 h-6" />
      </Button>
    );
  }

  return (
    <Card className="fixed bottom-6 right-6 w-96 h-[500px] shadow-2xl z-50 flex flex-col border-green-500">
      <CardHeader className="border-b bg-green-600 text-white p-4">
        <div className="flex items-center justify-between">
          <CardTitle className="text-base flex items-center gap-2">
            <MessageCircle className="w-5 h-5" />
            Chat da Equipe
          </CardTitle>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setAberto(false)}
            className="h-8 w-8 p-0 text-white hover:bg-green-700"
          >
            <X className="w-4 h-4" />
          </Button>
        </div>
      </CardHeader>

      <CardContent className="flex-1 overflow-y-auto p-4 space-y-3 bg-gray-50 dark:bg-neutral-900">
        {mensagens.map((msg) => {
          const ehMinha = msg.usuario_email === usuario?.email;
          return (
            <div key={msg.id} className={`flex ${ehMinha ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[75%] ${ehMinha ? 'bg-green-600 text-white' : 'bg-white dark:bg-neutral-800 text-gray-900 dark:text-white'} rounded-lg p-3 shadow-sm`}>
                <div className="text-xs font-semibold mb-1 opacity-70">
                  {msg.usuario_nome}
                </div>
                <div className="text-sm">{msg.mensagem}</div>
                <div className="text-xs mt-1 opacity-60">
                  {new Date(msg.created_date).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}
                </div>
              </div>
            </div>
          );
        })}
        <div ref={messagesEndRef} />
      </CardContent>

      <form onSubmit={handleEnviar} className="border-t p-3 bg-white dark:bg-neutral-900">
        <div className="flex gap-2">
          <Input
            value={mensagem}
            onChange={(e) => setMensagem(e.target.value)}
            placeholder="Digite sua mensagem..."
            className="flex-1"
            disabled={enviarMensagem.isPending}
          />
          <Button 
            type="submit" 
            size="sm"
            disabled={!mensagem.trim() || enviarMensagem.isPending}
            className="bg-green-600 hover:bg-green-700"
          >
            <Send className="w-4 h-4" />
          </Button>
        </div>
      </form>
    </Card>
  );
}

import React, { useState } from "react";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { useDroppable } from "@dnd-kit/core";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { Sparkles, Sun, Sunset, MessageCircle, Server, WifiOff, Loader2, Briefcase, CheckCircle, AlertTriangle, RefreshCw, RotateCcw } from "lucide-react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "@/components/ui/dialog";
import { base44 } from "@/api/base44Client";
import { ScrollArea } from "@/components/ui/scroll-area";
import { toast } from "sonner";
import { useConfirm } from "@/hooks/useConfirm";
import EntregaCard from "./EntregaCard";
import { whatsappService } from "@/services/whatsappService";
import { useTenant } from "@/contexts/TenantContext";
import { isStatusCancelado } from "@/utils/vendaStatus";

export default function ColunaKanban({ coluna, vendas, caminhoes = [], onClickEntrega, onCalcularRota, calculandoRota }) {
  const queryClient = useQueryClient();
  const confirm = useConfirm();
  const { isPaidModuleActive } = useTenant();

  const { setNodeRef: setNodeRefColuna, isOver: isOverColuna } = useDroppable({ id: coluna.id });
  const { setNodeRef: setNodeRefComercial, isOver: isOverComercial } = useDroppable({ id: `${coluna.id}-comercial` });
  const { setNodeRef: setNodeRefManha, isOver: isOverManha } = useDroppable({ id: `${coluna.id}-manha` });
  const { setNodeRef: setNodeRefTarde, isOver: isOverTarde } = useDroppable({ id: `${coluna.id}-tarde` });

  const [modalOpen, setModalOpen] = useState(false);
  const [modalReagendar, setModalReagendar] = useState(false);
  const [loading, setLoading] = useState(false);
  const [statusServidor, setStatusServidor] = useState("verificando");

  const entregas = coluna?.entregas || [];
  const entregasComercial = entregas.filter(e => !e.turno || e.turno === 'Comercial');
  const entregasManha = entregas.filter(e => e.turno === 'Manhã');
  const entregasTarde = entregas.filter(e => e.turno === 'Tarde');

  const entregasParaDisparo = entregas.filter(e => e.status !== 'Entregue' && !isStatusCancelado(e.status));

  // Verificar quais já foram notificadas para ESTA data/turno
  const jaNotificadas = entregasParaDisparo.filter(e => {
    const dataAgendada = e.data_agendada?.split('T')[0];
    const dataNotificada = e.data_notificacao;
    const turnoNotificado = e.turno_notificacao;
    return dataAgendada === dataNotificada && e.turno === turnoNotificado;
  });

  const naoNotificadas = entregasParaDisparo.filter(e => !jaNotificadas.includes(e));

  const updateEntrega = useMutation({
    mutationFn: ({ id, data }) => base44.entities.Entrega.update(id, data),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['entregas'] })
  });

  const verificarServidor = async () => {
    setStatusServidor("verificando");
    try {
      if (await whatsappService.checkStatus()) {
        setStatusServidor("online");
      } else {
        setStatusServidor("offline");
      }
    } catch (e) { setStatusServidor("offline"); }
  };

  const abrirModalRobo = () => {
    if (!isPaidModuleActive('whatsapp')) {
      toast.error("O módulo de WhatsApp não está ativo no plano da sua organização.");
      return;
    }
    setModalOpen(true);
    verificarServidor();
  };

  // Disparar apenas para os NÃO notificados
  const enviarParaRobo = async () => {
    setLoading(true);
    try {
      // Só envia os que NÃO foram notificados ainda
      const paraEnviar = naoNotificadas;

      if (paraEnviar.length === 0) {
        toast.success("✅ Todos já foram notificados para esta data!");
        setModalOpen(false);
        setLoading(false);
        return;
      }

      const payload = paraEnviar.map(entrega => {
        const venda = (vendas || []).find(v => v.id === entrega.venda_id);
        const listaProdutos = venda?.itens?.map(item => `• ${item.quantidade}x ${item.produto_nome}`).join('\n') || "Itens não informados";
        return {
          id: entrega.id,
          numero_pedido: entrega.numero_pedido,
          cliente_nome: entrega.cliente_nome,
          telefone: entrega.cliente_telefone,
          turno: entrega.turno || "comercial",
          produtos: listaProdutos,
          data_agendada: entrega.data_agendada
        };
      });

      const response = await whatsappService.sendConfirmations(payload);

      if (response.ok) {
        // Marcar como notificado com data e turno
        for (const entrega of paraEnviar) {
          try {
            await base44.entities.Entrega.update(entrega.id, {
              status_confirmacao: 'Notificada',
              whatsapp_enviado: true,
              data_notificacao: entrega.data_agendada?.split('T')[0],
              turno_notificacao: entrega.turno,
              ultima_notificacao: new Date().toISOString()
            });
          } catch (dbError) {
            console.warn('Erro ao atualizar entrega (colunas podem não existir):', dbError);
          }
        }
        toast.success(`✅ ${paraEnviar.length} cliente(s) notificado(s)!${jaNotificadas.length > 0 ? ` ⏩ ${jaNotificadas.length} já haviam sido notificados.` : ''}`);
        setModalOpen(false);
        queryClient.invalidateQueries({ queryKey: ['entregas'] });
      } else {
        const errorText = await response.text().catch(() => 'Erro desconhecido');
        toast.error(`Erro do robô: ${errorText}`);
      }
    } catch (error) {
      console.error('Erro ao enviar para robô:', error);
      toast.warning("⚠️ Não foi possível conectar ao robô. Verifique se 'npm run dev:all' está rodando.");
    } finally { setLoading(false); }
  };

  // Reagendar todas as entregas do dia
  const reagendarTodas = async () => {
    setLoading(true);
    try {
      // Enviar mensagem de reagendamento via bot
      const payload = entregasParaDisparo.map(e => ({
        telefone: e.cliente_telefone,
        nome: e.cliente_nome,
        numero_pedido: e.numero_pedido
      }));

      if (isPaidModuleActive('whatsapp')) {
        await whatsappService.rescheduleDeliveries(payload);
      }

      // Voltar todas para triagem
      for (const entrega of entregasParaDisparo) {
        await updateEntrega.mutateAsync({
          id: entrega.id,
          data: {
            data_agendada: null,
            turno: null,
            caminhao_id: null,
            status: 'Pendente',
            observacoes_entrega: `[REAGENDADO] Imprevisto em ${coluna.dataFormatada}`
          }
        });
      }

      toast.success(`✅ ${entregasParaDisparo.length} entregas reagendadas!${!isPaidModuleActive('whatsapp') ? " (WhatsApp desativado no plano)" : ""}`);
      setModalReagendar(false);
    } catch (e) {
      toast.error("Erro ao reagendar.");
    } finally {
      setLoading(false);
    }
  };

  // Reagendar uma entrega individual
  const reagendarIndividual = async (entrega) => {
    const confirmed = await confirm({
      title: "Reagendar Entrega",
      message: `Reagendar pedido #${entrega.numero_pedido} de ${entrega.cliente_nome}?`,
      confirmText: "Reagendar",
      variant: "warning"
    });
    if (!confirmed) return;

    try {
      if (isPaidModuleActive('whatsapp')) {
        await whatsappService.rescheduleDeliveries([{
          telefone: entrega.cliente_telefone,
          nome: entrega.cliente_nome,
          numero_pedido: entrega.numero_pedido
        }]);
      }

      // Voltar para triagem
      await updateEntrega.mutateAsync({
        id: entrega.id,
        data: {
          data_agendada: null,
          turno: null,
          caminhao_id: null,
          status: 'Pendente',
          observacoes_entrega: `[REAGENDADO] Individual em ${coluna.dataFormatada}`
        }
      });

      toast.success(isPaidModuleActive('whatsapp') ? "Entrega reagendada!" : "Entrega reagendada! (WhatsApp desativado no plano)");
    } catch (e) {
      toast.error("Erro ao reagendar.");
    }
  };

  // Renderizar card de entrega com indicador de notificação
  const renderEntregaCard = (entrega) => {
    const caminhao = caminhoes.find(c => c.id === entrega.caminhao_id);
    const dataAgendada = entrega.data_agendada?.split('T')[0];
    const foiNotificada = dataAgendada === entrega.data_notificacao && entrega.turno === entrega.turno_notificacao;

    return (
      <div key={entrega.id} className="relative group">
        <EntregaCard
          entrega={{
            ...entrega,
            caminhao_nome: caminhao?.placa || caminhao?.nome,
            _notificado: foiNotificada
          }}
          venda={(vendas || []).find(v => v.id === entrega.venda_id)}
          onClick={onClickEntrega}
          isColumn={true}
        />
        {/* Botão de reagendar individual */}
        <button
          onClick={(e) => { e.stopPropagation(); reagendarIndividual(entrega); }}
          className="absolute top-1 right-1 opacity-0 group-hover:opacity-100 transition-opacity p-1 rounded bg-orange-100 text-orange-600 hover:bg-orange-200"
          title="Reagendar esta entrega"
        >
          <RotateCcw className="w-3 h-3" />
        </button>
      </div>
    );
  };

  return (
    <>
      <Card
        ref={setNodeRefColuna}
        className={`flex flex-col h-full border-0 bg-gray-100/50 dark:bg-neutral-900/50 min-w-0 transition-all ${isOverColuna ? 'ring-2 ring-blue-400 bg-blue-50' : ''}`}
      >
        <div className={`p-2 rounded-t-xl border-b bg-white dark:bg-neutral-900 shadow-sm flex-shrink-0 ${coluna.isHoje ? 'border-green-500 border-t-4' : 'border-gray-200'}`}>
          <div className="flex flex-col gap-1">
            <div className="flex items-center justify-between">
              <h3 className="font-bold text-sm text-gray-800 dark:text-white truncate">
                {coluna.titulo}
              </h3>
              {coluna.isHoje && <Badge className="bg-green-500 text-[8px] px-1 h-3">HOJE</Badge>}
            </div>

            <div className="flex justify-between items-center">
              <span className="text-[10px] text-gray-500">{coluna.dataFormatada.slice(0, 5)}</span>
              <div className="flex gap-1">
                {/* Botão Reagendar Todas */}
                {entregasParaDisparo.length > 0 && (
                  <Button
                    size="icon"
                    variant="ghost"
                    className="h-5 w-5 text-orange-500 hover:bg-orange-100"
                    onClick={() => setModalReagendar(true)}
                    title="Reagendar Todas"
                  >
                    <RefreshCw className="w-3 h-3" />
                  </Button>
                )}
                {/* Botão Disparar */}
                {entregasParaDisparo.length > 0 && (
                  <Button
                    size="icon"
                    className={`h-5 w-5 shadow-sm ${!isPaidModuleActive('whatsapp')
                      ? 'bg-amber-100 text-amber-600 hover:bg-amber-200'
                      : naoNotificadas.length > 0
                        ? 'bg-green-100 hover:bg-green-200 text-green-700'
                        : 'bg-gray-100 text-gray-400'
                      }`}
                    onClick={abrirModalRobo}
                    title={
                      !isPaidModuleActive('whatsapp')
                        ? "Módulo de WhatsApp desativado no plano atual"
                        : naoNotificadas.length > 0
                          ? "Disparar Confirmações"
                          : "Todos já notificados"
                    }
                  >
                    <MessageCircle className="w-3 h-3" />
                  </Button>
                )}
              </div>
            </div>
          </div>

          <div className="flex justify-between items-center mt-1 text-[10px] text-gray-500 border-t pt-1">
            <span>Total: {entregas.length}</span>
            <div className="flex gap-1">
              {jaNotificadas.length > 0 && (
                <span className="text-green-600">✓ {jaNotificadas.length}</span>
              )}
              {naoNotificadas.length > 0 && (
                <span className="text-orange-600">⏳ {naoNotificadas.length}</span>
              )}
            </div>
          </div>
        </div>

        <ScrollArea className="flex-1 px-1">
          {/* Comercial */}
          <div ref={setNodeRefComercial} className={`mt-1 pb-1 min-h-[60px] rounded border border-dashed border-transparent transition-colors ${isOverComercial ? 'bg-blue-50 border-blue-300' : ''}`}>
            <div className="flex items-center gap-1 mb-1 px-1 pt-1">
              <Briefcase className="w-3 h-3 text-blue-500" />
              <h4 className="text-[10px] font-bold text-gray-500 uppercase">Comercial</h4>
            </div>
            {entregasComercial.map(renderEntregaCard)}
          </div>

          <div className="border-t border-gray-200 my-1"></div>

          {/* Manhã */}
          <div ref={setNodeRefManha} className={`pb-1 min-h-[60px] rounded border border-dashed border-transparent transition-colors ${isOverManha ? 'bg-amber-50 border-amber-300' : ''}`}>
            <div className="flex items-center gap-1 mb-1 px-1 pt-1">
              <Sun className="w-3 h-3 text-amber-500" />
              <h4 className="text-[10px] font-bold text-gray-500 uppercase">Manhã</h4>
            </div>
            {entregasManha.map(renderEntregaCard)}
          </div>

          <div className="border-t border-gray-200 my-1"></div>

          {/* Tarde */}
          <div ref={setNodeRefTarde} className={`pb-1 min-h-[60px] rounded border border-dashed border-transparent transition-colors ${isOverTarde ? 'bg-orange-50 border-orange-300' : ''}`}>
            <div className="flex items-center gap-1 mb-1 px-1 pt-1">
              <Sunset className="w-3 h-3 text-orange-500" />
              <h4 className="text-[10px] font-bold text-gray-500 uppercase">Tarde</h4>
            </div>
            {entregasTarde.map(renderEntregaCard)}
          </div>
        </ScrollArea>

        {entregas.length > 1 && (
          <div className="p-1 border-t bg-white">
            <Button variant="ghost" size="sm" onClick={onCalcularRota} disabled={calculandoRota} className="w-full h-6 text-[10px] text-gray-400 hover:text-blue-600">
              <Sparkles className="w-3 h-3 mr-1" /> {calculandoRota ? '...' : 'Otimizar'}
            </Button>
          </div>
        )}
      </Card>

      {/* Modal Disparar Confirmações */}
      <Dialog open={modalOpen} onOpenChange={setModalOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Confirmar Entregas - {coluna.titulo}</DialogTitle>
            <DialogDescription>
              {naoNotificadas.length > 0
                ? `Disparar WhatsApp para ${naoNotificadas.length} clientes?`
                : "Todos os clientes já foram notificados!"}
            </DialogDescription>
          </DialogHeader>
          <div className="py-4 space-y-3">
            {statusServidor === 'online'
              ? <div className="p-3 rounded bg-green-100 text-green-800 flex items-center gap-2"><Server className="w-5 h-5" /> <span>Automação Online!</span></div>
              : <div className="p-3 rounded bg-red-100 text-red-800 flex items-center gap-2"><WifiOff className="w-5 h-5" /> <span>Automação Offline.</span></div>
            }

            {/* Resumo */}
            <div className="text-sm space-y-1">
              {naoNotificadas.length > 0 && (
                <div className="flex items-center gap-2 text-orange-700">
                  <span className="w-3 h-3 rounded-full bg-orange-500"></span>
                  {naoNotificadas.length} serão notificados agora
                </div>
              )}
              {jaNotificadas.length > 0 && (
                <div className="flex items-center gap-2 text-green-700">
                  <CheckCircle className="w-4 h-4" />
                  {jaNotificadas.length} já notificados (serão ignorados)
                </div>
              )}
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setModalOpen(false)}>Cancelar</Button>
            <Button
              onClick={enviarParaRobo}
              disabled={statusServidor !== "online" || loading || naoNotificadas.length === 0}
              className="bg-green-600 hover:bg-green-700"
            >
              {loading ? <Loader2 className="animate-spin" /> : `Notificar ${naoNotificadas.length}`}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Modal Reagendar Todas */}
      <Dialog open={modalReagendar} onOpenChange={setModalReagendar}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle className="text-orange-600 flex items-center gap-2">
              <RefreshCw className="w-5 h-5" />
              Reagendar Entregas
            </DialogTitle>
            <DialogDescription>
              Isso irá notificar {entregasParaDisparo.length} cliente(s) sobre o reagendamento e voltar os pedidos para a triagem.
            </DialogDescription>
          </DialogHeader>
          <div className="py-4">
            <div className="bg-orange-50 border border-orange-200 rounded-lg p-3 text-sm text-orange-800">
              <p className="font-medium mb-1">⚠️ Ação em massa</p>
              <p>Todos os clientes receberão uma mensagem de desculpas informando que a entrega será reagendada.</p>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setModalReagendar(false)}>Cancelar</Button>
            <Button
              onClick={reagendarTodas}
              disabled={loading}
              className="bg-orange-600 hover:bg-orange-700"
            >
              {loading ? <Loader2 className="animate-spin" /> : `Reagendar ${entregasParaDisparo.length} entregas`}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

import React, { useMemo, useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { base44 } from '@/lib/supabase';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Search, PackageCheck, XCircle, RotateCcw, Truck } from 'lucide-react';
import { toast } from 'sonner';

function formatDate(value) {
  if (!value) return '—';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleDateString('pt-BR');
}

export default function ConferenciaEntregas() {
  const queryClient = useQueryClient();
  const [search, setSearch] = useState('');
  const [selectedDelivery, setSelectedDelivery] = useState(null);
  const [modalAction, setModalAction] = useState('confirm');
  const [motivo, setMotivo] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const { data: entregas = [], isLoading } = useQuery({
    queryKey: ['entregas-conferencia'],
    queryFn: () => base44.entities.Entrega.list('-created_at')
  });

  const filteredDeliveries = useMemo(() => {
    const query = search.trim().toLowerCase();
    if (!query) return entregas;
    return entregas.filter((item) => {
      const haystack = [
        item.numero_pedido,
        item.cliente_nome,
        item.cliente_telefone,
        item.endereco_entrega,
        item.observacoes,
        item.status,
        item.status_confirmacao
      ].filter(Boolean).join(' ').toLowerCase();
      return haystack.includes(query);
    });
  }, [entregas, search]);

  const confirmDeliveryMutation = useMutation({
    mutationFn: async ({ id, payload }) => base44.entities.Entrega.update(id, payload),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: ['entregas-conferencia'] });
      await queryClient.invalidateQueries({ queryKey: ['entregas'] });
      toast.success('Entrega confirmada com sucesso.');
      setSelectedDelivery(null);
      setMotivo('');
      setIsSubmitting(false);
    },
    onError: (error) => {
      console.error(error);
      toast.error('Não foi possível atualizar a entrega.');
      setIsSubmitting(false);
    }
  });

  const openResolutionModal = (delivery, action = 'confirm') => {
    setSelectedDelivery(delivery);
    setModalAction(action);
    setMotivo('');
  };

  const handleConfirmDelivered = async () => {
    if (!selectedDelivery) return;
    setIsSubmitting(true);
    await confirmDeliveryMutation.mutateAsync({
      id: selectedDelivery.id,
      payload: {
        status: 'Entregue',
        status_confirmacao: 'confirmado',
        data_realizada: new Date().toISOString(),
        observacoes: [selectedDelivery.observacoes, motivo ? `Não entregue: ${motivo}` : ''].filter(Boolean).join('\n')
      }
    });
  };

  const handleMarkNotDelivered = async () => {
    if (!selectedDelivery) return;
    setIsSubmitting(true);
    await confirmDeliveryMutation.mutateAsync({
      id: selectedDelivery.id,
      payload: {
        status: 'Reagendada',
        status_confirmacao: 'nao_entregue',
        observacoes: [selectedDelivery.observacoes, motivo ? `Não entregue: ${motivo}` : 'Motivo não informado'].filter(Boolean).join('\n')
      }
    });
  };

  return (
    <div className="space-y-4">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <PackageCheck className="h-5 w-5" />
            Conferência de Entregas
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
            <div>
              <p className="text-sm text-slate-600">
                Confirme manualmente as entregas quando o rastreamento não estiver habilitado.
              </p>
            </div>
            <div className="relative w-full md:w-80">
              <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
              <Input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Buscar por cliente, pedido ou endereço"
                className="pl-9"
              />
            </div>
          </div>

          {isLoading ? (
            <div className="rounded-lg border border-slate-200 bg-slate-50 p-6 text-sm text-slate-600">
              Carregando entregas...
            </div>
          ) : filteredDeliveries.length === 0 ? (
            <div className="rounded-lg border border-dashed border-slate-300 p-6 text-sm text-slate-600">
              Nenhuma entrega disponível para conferência no momento.
            </div>
          ) : (
            <div className="space-y-3">
              {filteredDeliveries.map((delivery) => {
                const statusLabel = delivery.status === 'Entregue' ? 'Entregue' : delivery.status_confirmacao === 'nao_entregue' ? 'Não entregue' : 'Pendente';
                return (
                  <div key={delivery.id} className="rounded-xl border border-slate-200 p-4 shadow-sm">
                    <div className="flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
                      <div className="space-y-2">
                        <div className="flex flex-wrap items-center gap-2">
                          <Badge variant={delivery.status === 'Entregue' ? 'default' : 'secondary'}>{statusLabel}</Badge>
                          <span className="text-sm font-medium text-slate-700">#{delivery.numero_pedido || delivery.id}</span>
                        </div>
                        <div className="space-y-1 text-sm text-slate-600">
                          <p className="font-semibold text-slate-900">{delivery.cliente_nome || 'Cliente sem nome'}</p>
                          <p>{delivery.endereco_entrega || 'Endereço não informado'}</p>
                          <p className="flex items-center gap-2">
                            <Truck className="h-4 w-4" />
                            {formatDate(delivery.data_agendada)}
                          </p>
                        </div>
                      </div>
                      <div className="flex flex-wrap gap-2">
                        <Button variant="outline" onClick={() => openResolutionModal(delivery, 'confirm')}>
                          <PackageCheck className="mr-2 h-4 w-4" />
                          Confirmar entrega
                        </Button>
                        <Button variant="outline" onClick={() => openResolutionModal(delivery, 'not-delivered')}>
                          <XCircle className="mr-2 h-4 w-4" />
                          Marcar como não entregue
                        </Button>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>

      <Dialog open={Boolean(selectedDelivery)} onOpenChange={(open) => {
        if (!open) {
          setSelectedDelivery(null);
          setModalAction('confirm');
          setMotivo('');
        }
      }}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Registrar confirmação</DialogTitle>
            <DialogDescription>
              Registre o resultado da visita para manter o histórico da entrega atualizado.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-2">
            <div className="rounded-lg border border-slate-200 bg-slate-50 p-3 text-sm text-slate-700">
              <p className="font-semibold text-slate-900">{selectedDelivery?.cliente_nome || 'Cliente'}</p>
              <p>{selectedDelivery?.endereco_entrega || 'Endereço não informado'}</p>
            </div>
            <div className="space-y-2">
              <Label htmlFor="motivo">Observações</Label>
              <Textarea
                id="motivo"
                value={motivo}
                onChange={(event) => setMotivo(event.target.value)}
                placeholder="Descreva o que aconteceu na visita, como ausência, endereço incorreto ou reagendamento."
              />
            </div>
          </div>

          <DialogFooter className="gap-2 sm:gap-2">
            <Button variant="outline" onClick={() => {
              setSelectedDelivery(null);
              setModalAction('confirm');
              setMotivo('');
            }} disabled={isSubmitting}>
              <RotateCcw className="mr-2 h-4 w-4" />
              Cancelar
            </Button>
            <Button variant="outline" onClick={handleMarkNotDelivered} disabled={isSubmitting}>
              Marcar como não entregue
            </Button>
            <Button onClick={handleConfirmDelivered} disabled={isSubmitting}>
              Confirmar entrega
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React from "react";
import { Card } from "@/components/ui/card";
import { BarChart, Bar, LineChart, Line, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from "recharts";
import { Package, TrendingUp, CheckCircle, Clock, Truck, Box } from "lucide-react";
import RastreadorFrota from "./RastreadorFrota";

export default function DashboardLogistica({ entregas, colunas }) {
  // KPI 1: Entregas por dia da semana
  const entregasPorDia = colunas.map(col => ({
    dia: col.titulo,
    entregas: col.entregas.length
  }));

  // KPI 2: Status de Montagem
  const comMontagem = entregas.filter(e => e.itens_montagem_interna?.length > 0);
  const montagemConcluida = comMontagem.filter(e => e.montagem_concluida).length;
  const montagemPendente = comMontagem.length - montagemConcluida;

  const dadosMontagem = [
    { name: "Concluídas", value: montagemConcluida, color: "#10b981" },
    { name: "Pendentes", value: montagemPendente, color: "#f59e0b" }
  ];

  // KPI 3: Tempo médio até data limite
  const entregasComData = entregas.filter(e => e.data_agendada && e.data_limite);
  const tempoMedio = entregasComData.length > 0
    ? entregasComData.reduce((acc, e) => {
      const agendada = new Date(e.data_agendada);
      const limite = new Date(e.data_limite);
      const diff = Math.ceil((limite - agendada) / (1000 * 60 * 60 * 24));
      return acc + diff;
    }, 0) / entregasComData.length
    : 0;

  // KPI 4: Volume total por dia (simulado - pode ser calculado com dados reais)
  const volumePorDia = colunas.map(col => ({
    dia: col.titulo,
    volume: col.entregas.reduce((acc, e) => acc + (e.volume_total_m3 || 0), 0)
  }));

  const totalEntregas = entregas.filter(e => e.data_agendada).length;
  const entregasHoje = entregas.filter(e => {
    if (!e.data_agendada) return false;
    const hojeStr = new Date().toLocaleDateString('en-CA');
    const dataAgendadaStr = e.data_agendada.split('T')[0];
    return dataAgendadaStr === hojeStr;
  }).length;

  return (
    <div className="space-y-4">
      {/* KPIs Principais */}
      <div className="grid grid-cols-4 gap-4">
        <Card className="p-4 bg-gradient-to-br from-blue-50 to-blue-100 dark:from-blue-900/20 dark:to-blue-800/20 border-blue-200">
          <div className="flex items-center justify-between mb-2">
            <Package className="w-8 h-8 text-blue-600" />
            <span className="text-3xl font-bold text-blue-700">{totalEntregas}</span>
          </div>
          <p className="text-sm font-medium text-blue-800">Total Agendadas</p>
          <p className="text-xs text-blue-600 mt-1">Semana atual</p>
        </Card>

        <Card className="p-4 bg-gradient-to-br from-green-50 to-green-100 dark:from-green-900/20 dark:to-green-800/20 border-green-200">
          <div className="flex items-center justify-between mb-2">
            <Truck className="w-8 h-8 text-green-600" />
            <span className="text-3xl font-bold text-green-700">{entregasHoje}</span>
          </div>
          <p className="text-sm font-medium text-green-800">Entregas Hoje</p>
          <p className="text-xs text-green-600 mt-1">Em andamento</p>
        </Card>

        <Card className="p-4 bg-gradient-to-br from-purple-50 to-purple-100 dark:from-purple-900/20 dark:to-purple-800/20 border-purple-200">
          <div className="flex items-center justify-between mb-2">
            <CheckCircle className="w-8 h-8 text-purple-600" />
            <span className="text-3xl font-bold text-purple-700">{montagemConcluida}</span>
          </div>
          <p className="text-sm font-medium text-purple-800">Montagens OK</p>
          <p className="text-xs text-purple-600 mt-1">{montagemPendente} pendentes</p>
        </Card>

        <Card className="p-4 bg-gradient-to-br from-orange-50 to-orange-100 dark:from-orange-900/20 dark:to-orange-800/20 border-orange-200">
          <div className="flex items-center justify-between mb-2">
            <Clock className="w-8 h-8 text-orange-600" />
            <span className="text-3xl font-bold text-orange-700">{tempoMedio.toFixed(0)}</span>
          </div>
