              </PieChart>
            </ResponsiveContainer>
          </Card>
        </div>
      </div>
    </div>
  );
}

import React from "react";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { useDraggable } from "@dnd-kit/core";
import { Map, AlertTriangle, MessageCircle, Package, Truck, User, Wrench, Store, CheckCircle, CalendarX, History, Settings, Clock } from "lucide-react";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";

export default function EntregaCard({ entrega, venda, onClick, isColumn = false }) {
  const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
    id: entrega.id,
    data: { entrega }
  });

  const abrirGoogleMaps = (e) => {
    e.stopPropagation();
    const endereco = encodeURIComponent(entrega.endereco_entrega || "");
    window.open(`https://www.google.com/maps/search/?api=1&query=${endereco}`, '_blank');
  };

  const contatoManual = (e) => {
    e.stopPropagation();
    const tel = entrega.cliente_telefone?.replace(/\D/g, '');
    if (tel) window.open(`https://wa.me/55${tel}`, '_blank');
    else alert("Telefone não cadastrado");
  };

  const isPendente = (!entrega.status_confirmacao && entrega.data_agendada);
  const isNotificado = entrega.status_confirmacao === 'Notificada';
  const isProblema = entrega.status_confirmacao === 'Requer Atenção';
  const isConfirmado = entrega.status_confirmacao === 'Confirmada';

  // Core logic for border colors
  let statusColor = "blue";
  let bgColor = "bg-white";
  let ringColor = "ring-gray-100";

  if (entrega.status === 'Aguardando Liberação') {
    statusColor = "amber";
    bgColor = "bg-amber-100";
    ringColor = "ring-amber-200";
  } else if (isConfirmado) {
    statusColor = "green";
    bgColor = "bg-emerald-100";
    ringColor = "ring-emerald-200";
  } else if (isProblema) {
    statusColor = "red";
    bgColor = "bg-red-50";
    ringColor = "ring-red-200";
  } else if (isPendente) {
    statusColor = "yellow";
    bgColor = "bg-amber-50";
    ringColor = "ring-amber-200";
  } else if (isNotificado) {
    statusColor = "emerald";
    bgColor = "bg-emerald-50";
    ringColor = "ring-emerald-200";
  }

  const borderClass = `border-l-4 border-l-${statusColor}-500`;
  // const bgClass = entrega._notificado ? 'bg-green-50' : 'bg-white'; // Old logic

  const listaItens = venda?.itens?.map(i => i.produto_nome).join(', ') || "Itens não informados";
  const temPreferencias = entrega.preferencias_entrega && (
    entrega.preferencias_entrega.dias?.length > 0 ||
    entrega.preferencias_entrega.turnos?.length > 0 ||
    entrega.preferencias_entrega.obs ||
    entrega.data_restricao
  );

  // Formatar restrição se houver
  const temRestricao = entrega.data_restricao;
  const dataRestricaoFormatada = temRestricao ? new Date(entrega.data_restricao).toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' }) : '';
  const resumoAgendamento = entrega.data_agendada
    ? `${format(new Date(`${entrega.data_agendada.split('T')[0]}T12:00:00`), 'EEE dd/MM', { locale: ptBR })} • ${entrega.turno || 'Sem turno'}`
        .replace('.', '')
        .replace(/^./, (char) => char.toUpperCase())
    : null;
  const foiLiberadaComData = entrega.status !== 'Aguardando Liberação' && Boolean(entrega.data_liberacao);
  const dataRecebimento = entrega.created_date || entrega.created_at;
  const dataRecebimentoFormatada = dataRecebimento
    ? new Date(dataRecebimento).toLocaleDateString('pt-BR')
    : '-';
  const dataLiberacaoFormatada = entrega.data_liberacao
    ? new Date(`${entrega.data_liberacao.split('T')[0]}T12:00:00`).toLocaleDateString('pt-BR')
    : '-';

  return (
    <div
      ref={setNodeRef}
      {...listeners}
      {...attributes}
      onClick={() => onClick && onClick(entrega)}
      className={`cursor-grab active:cursor-grabbing transition-all group mb-2 ${isDragging ? 'opacity-50 scale-95' : ''} ${isColumn ? '' : 'h-full min-h-[118px]'}`}
    >
      <Card className={`relative overflow-hidden hover:shadow-lg transition-all border-0 shadow-sm ring-1 ${ringColor} ${borderClass} ${bgColor} flex flex-col justify-start ${isColumn ? 'p-2 min-h-[90px]' : 'p-3 h-full min-h-[118px]'} gap-1.5`}>

        {/* Topo: Cliente E Num Pedido/Badge */}
        <div className="flex justify-between items-start gap-2">
          <div className="flex items-center gap-1.5 overflow-hidden flex-1 min-w-0">
            <User className="w-3 h-3 text-gray-400 shrink-0" />
            <span className={`font-bold text-gray-700 truncate uppercase ${isColumn ? 'text-[10px]' : 'text-[11px]'}`} title={entrega.cliente_nome}>
              {entrega.cliente_nome}
            </span>
          </div>

          <div className="flex flex-wrap items-center justify-end gap-1 shrink-0 bg-white/60 px-1.5 py-1 rounded-md ml-1 border border-gray-100 max-w-[56%]">
            <span className={`font-mono text-blue-700 font-bold ${isColumn ? 'text-[9px]' : 'text-[10px]'}`}>#{entrega.numero_pedido}</span>
            {/* Badge de Confirmação - VISÍVEL AGORA */}
            {isConfirmado && (
              <Badge className="text-[8px] px-1 py-0 h-4 bg-emerald-600 hover:bg-emerald-700 text-white font-bold shadow-none border-0 flex items-center gap-0.5" title="Entrega Confirmada">
                <CheckCircle className="w-2 h-2" />
              </Badge>
            )}

            {/* Badge de Aguardando Liberação */}
            {entrega.status === 'Aguardando Liberação' && (
              <Badge className="text-[8px] px-1 py-0 h-4 bg-amber-600 hover:bg-amber-700 text-white font-bold shadow-none border-0 flex items-center gap-0.5" title="Aguardando Liberação">
                <Clock className="w-2 h-2" />
                Aguardando
              </Badge>
            )}

            {/* Badge de Montagem */}
            {entrega.tipo_montagem === 'montado' && (
              <Badge className="text-[8px] px-1 py-0 h-4 bg-orange-600 hover:bg-orange-700 text-white font-bold shadow-none border-0" title="Entrega Montado (montagem interna)">
                <Wrench className="w-2 h-2" />
              </Badge>
            )}
            {entrega.tipo_montagem === 'montagem_cliente' && (
              <Badge className="text-[8px] px-1 py-0 h-4 bg-blue-600 hover:bg-blue-700 text-white font-bold shadow-none border-0" title="Montagem no Local (montador externo)">
                <Truck className="w-2 h-2" />
              </Badge>
            )}
            {entrega.tipo_montagem === 'retira' && (
              <Badge className="text-[8px] px-1 py-0 h-4 bg-gray-600 hover:bg-gray-700 text-white font-bold shadow-none border-0" title="Cliente Retira">
                <Store className="w-2 h-2" />
              </Badge>
            )}
            {/* Badge de Preferências de Entrega (Simplificado para evitar bugs visuais) */}
            {temPreferencias && (
              <div className="inline-block" onClick={(e) => e.stopPropagation()}>
                <Badge
                  className="text-[8px] px-1 py-0 h-4 bg-purple-100 text-purple-700 font-bold shadow-none border border-purple-200 flex items-center gap-0.5 cursor-help"
                  title={`PREFERÊNCIAS DE ENTREGA:\n${entrega.data_restricao ? `• DATA BLOQUEADA: ${new Date(entrega.data_restricao).toLocaleDateString('pt-BR')}\n` : ''}${entrega.preferencias_entrega.dias?.length ? `• DIAS PERMITIDOS: ${[...new Set(entrega.preferencias_entrega.dias)].map(d => ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'][Number(d)]).join(', ')}\n` : ''}${entrega.preferencias_entrega.turnos?.length ? `• TURNOS PERMITIDOS: ${entrega.preferencias_entrega.turnos.join(', ')}\n` : ''}${entrega.preferencias_entrega.obs ? `• OBS: ${entrega.preferencias_entrega.obs}` : ''}`}
                >
                  <Settings className="w-2 h-2" />
                  {isColumn ? 'Preferências' : 'Prefer.'}
                </Badge>
              </div>
            )}
            {/* Badge de Status da Montagem Interna */}
            {entrega.tipo_montagem === 'montado' && entrega.montagem_status === 'Concluída' && (
              <Badge className="text-[8px] px-1 py-0 h-4 bg-green-600 hover:bg-green-700 text-white font-bold shadow-none border-0 animate-pulse" title="Montagem Concluída - Pronto para Enviar">
                ✓ Pronto
              </Badge>
            )}
          </div>

        </div>

        {/* Endereço - Agora no topo */}
        <div
          className="flex items-center gap-1 text-gray-500 hover:text-blue-600 transition-colors cursor-pointer group/map w-full bg-white/60 rounded py-0.5 px-1 border border-transparent hover:border-blue-100 hover:bg-white"
          onClick={abrirGoogleMaps}
          title="Abrir no Google Maps"
        >
          <Map className="w-3 h-3 group-hover/map:animate-bounce shrink-0 text-blue-400" />
          <span className={`font-medium truncate leading-tight ${isColumn ? 'text-[10px]' : 'text-[10px]'}`}>
            {entrega.endereco_entrega || "Sem endereço"}
          </span>
        </div>

        {foiLiberadaComData && (
          <div className="w-full rounded border border-amber-200 bg-amber-50 px-1.5 py-1 text-[9px] text-amber-900 leading-tight flex items-start gap-1">
            <AlertTriangle className="w-3 h-3 shrink-0 mt-0.5" />
            <span>Pedido recebido em {dataRecebimentoFormatada}, com liberação a partir de {dataLiberacaoFormatada}.</span>
          </div>
        )}

        {/* Meio: Produtos (Compacto) */}
        <div className="flex-1 min-h-0 flex items-start gap-1.5 overflow-hidden">
          <Package className="w-3 h-3 text-gray-300 mt-0.5 shrink-0" />
          <p className={`text-[10px] font-normal text-gray-600 leading-3 ${isColumn ? 'line-clamp-3' : 'line-clamp-2'}`} title={listaItens}>
            {listaItens}
          </p>
        </div>

        {/* Bottom: Ações/Status se necessário */}
        {(resumoAgendamento || isNotificado || isProblema || (isColumn && (isPendente || entrega.data_agendada))) && (
          <div className="mt-auto pt-1 border-t border-dashed border-gray-300/50 flex items-center justify-between gap-2">
            <div className="min-w-0 flex items-center gap-1 text-[9px] text-gray-500">
              {resumoAgendamento && (
                <>
                  <Clock className="w-3 h-3 shrink-0 text-gray-400" />
                  <span className="truncate" title={resumoAgendamento}>{resumoAgendamento}</span>
                </>
              )}
            </div>

            <div className="flex items-center justify-end gap-1 shrink-0">
            {isNotificado && !isConfirmado && (
              <Badge variant="outline" className="text-[8px] px-1 h-4 border-emerald-300 bg-emerald-100/50 text-emerald-700">
                Notificada
              </Badge>
            )}
            {isProblema && (
              <Badge variant="outline" className="text-[8px] px-1 h-4 border-red-300 bg-red-100/50 text-red-700">
                Atenção
              </Badge>
            )}
            {isColumn && (
              <>
                <Button
                  size="icon"
                  variant="ghost"
                  className="h-4 w-4 hover:bg-red-50 text-red-400"
                  title="Solicitar Reagendamento (Cliente não pode receber)"
                  onClick={(e) => {
                    e.stopPropagation();
                    if (onClick) onClick(entrega, 'reagendar');
                  }}
                >
                  <CalendarX className="w-3 h-3" />
                </Button>
                <Button
                  size="icon"
                  variant="ghost"
                  className="h-4 w-4 hover:bg-green-50 text-green-600"
                  onClick={contatoManual}
                  title="Contato Manual (WhatsApp)"
                >
                  <MessageCircle className="w-3 h-3" />
                </Button>
              </>
            )}
            </div>
          </div>
        )}

      </Card >
    </div >
  );
}

import React from "react";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Package, Clock, MapPin } from "lucide-react";
import { useDraggable } from "@dnd-kit/core";

function EntregaCard({ entrega, venda, diaSugerido }) {
  const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
    id: entrega.id,
    data: { entrega, venda }
  });

  const diasRestantes = Math.ceil((new Date(entrega.data_limite) - new Date()) / (1000 * 60 * 60 * 24));
  const urgente = diasRestantes <= 3;

  return (
    <div
      ref={setNodeRef}
      {...listeners}
      {...attributes}
      className={`cursor-grab active:cursor-grabbing transition-all relative ${isDragging ? 'opacity-50' : ''}`}
      data-entrega-id={entrega.id}
    >
      <Card className={`p-3 hover:shadow-md transition-all border-l-4 w-[220px] flex-shrink-0 ${
        diaSugerido ? 'border-l-green-500 shadow-lg shadow-green-200/50' : 'border-l-orange-400'
      }`}>
        <div className="flex items-start justify-between gap-2 mb-2">
          <div className="flex-1 min-w-0">
            <p className="font-bold text-sm text-gray-900 dark:text-white truncate">
              #{entrega.numero_pedido}
            </p>
            <p className="text-xs text-gray-600 dark:text-gray-400 truncate">
              {entrega.cliente_nome}
            </p>
          </div>
          {urgente && (
            <Badge className="bg-red-500 text-white text-[10px] px-1.5 py-0">
              URGENTE
            </Badge>
          )}
        </div>

        <div className="space-y-1 text-xs text-gray-500">
          <div className="flex items-center gap-1">
            <Clock className="w-3 h-3" />
            <span>Até {new Date(entrega.data_limite).toLocaleDateString('pt-BR')}</span>
          </div>
          <div className="flex items-start gap-1">
            <MapPin className="w-3 h-3 mt-0.5 flex-shrink-0" />
            <span className="line-clamp-2">{entrega.endereco_entrega}</span>
          </div>
        </div>

        {venda?.itens?.length > 0 && (
          <div className="mt-2 pt-2 border-t border-gray-100 dark:border-neutral-800 flex items-center justify-between">
            <p className="text-xs text-gray-500">
              {venda.itens.length} {venda.itens.length === 1 ? 'item' : 'itens'}
            </p>
            {diaSugerido && (
              <span className="text-[10px] font-bold px-2 py-0.5 bg-green-100 text-green-700 rounded-full">
                → {diaSugerido}
              </span>
            )}
          </div>
        )}
      </Card>
    </div>
  );
}

export default function EntregasPendentesRota({ entregas, vendas, sugestoes }) {
  // Ordena por data limite (mais urgente primeiro)
  const entregasOrdenadas = [...entregas].sort((a, b) => 
    new Date(a.data_limite) - new Date(b.data_limite)
  );

  return (
    <div className="w-full relative">
      <div className="bg-gradient-to-r from-orange-50 to-orange-100 dark:from-orange-900/20 dark:to-orange-800/20 p-3 rounded-xl border border-orange-200 mb-3 shadow-sm">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Package className="w-5 h-5 text-orange-600" />
            <h3 className="font-bold text-orange-900 dark:text-orange-400">
              Entregas Pendentes
            </h3>
          </div>
          <Badge variant="outline" className="bg-white text-orange-700 border-orange-300">
            {entregas.length}
          </Badge>
        </div>
        <p className="text-xs text-orange-700 mt-1 flex items-center gap-1">
          <span className="inline-block w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse" />
          Arraste para o dia recomendado (em verde)
        </p>
      </div>

      <div className="overflow-x-auto pb-3">
        <div className="flex gap-3 min-w-min">
          {entregasOrdenadas.length === 0 ? (
            <div className="text-center py-8 w-full">
              <Package className="w-12 h-12 mx-auto text-gray-300 mb-2" />
              <p className="text-sm text-gray-500">Nenhuma entrega pendente</p>
            </div>
          ) : (
            entregasOrdenadas.map(entrega => {
              const venda = vendas.find(v => v.id === entrega.venda_id);
              const sugestao = sugestoes?.find(s => s.entregaId === entrega.id);
              return (
                <EntregaCard 
                  key={entrega.id} 
                  entrega={entrega} 
                  venda={venda}
                  diaSugerido={sugestao?.diaSugerido}
                />
              );
            })
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import { Camera, RotateCcw, Check, Plus, Trash2, MapPin, Upload } from "lucide-react";
import { toast } from "sonner";
import { supabase } from "@/api/base44Client";

/**
 * Componente para captura de fotos da entrega com:
 * - Múltiplas fotos (até 3)
 * - Captura de GPS
 * - Upload para Supabase Storage
 * - Preview das fotos
 */
export default function FotoEntregaCapture({
    onComplete,
    onCancel,
    entregaId,
    numeroPedido,
    minFotos = 1,
    maxFotos = 3
}) {
    const videoRef = useRef(null);
    const canvasRef = useRef(null);
    const fileInputRef = useRef(null);

    const [fotos, setFotos] = useState([]);
    const [stream, setStream] = useState(null);
    const [cameraAtiva, setCameraAtiva] = useState(false);
    const [erro, setErro] = useState(null);
    const [uploading, setUploading] = useState(false);
    const [geolocalizacao, setGeolocalizacao] = useState(null);

    // Garante limpeza do stream ao desmontar o componente ou trocar stream
    React.useEffect(() => {
        return () => {
            if (stream) {
                stream.getTracks().forEach(track => track.stop());
            }
        };
    }, [stream]);

    // Capturar GPS ao iniciar
    React.useEffect(() => {
        if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(
                (position) => {
                    setGeolocalizacao({
                        latitude: position.coords.latitude,
                        longitude: position.coords.longitude,
                        accuracy: position.coords.accuracy,
                        timestamp: new Date().toISOString()
                    });
                },
                (error) => console.warn("GPS não disponível:", error),
                { enableHighAccuracy: true, timeout: 10000 }
            );
        }
    }, []);

    const iniciarCamera = async () => {
        try {
            setErro(null);
            const mediaStream = await navigator.mediaDevices.getUserMedia({
                video: {
                    facingMode: 'environment',
                    width: { ideal: 1280 },
                    height: { ideal: 720 }
                },
                audio: false
            });

            setStream(mediaStream);
            setCameraAtiva(true);

            setTimeout(() => {
                if (videoRef.current) {
                    videoRef.current.srcObject = mediaStream;
                    videoRef.current.play().catch(e => console.error("Error playing video:", e));
                }
            }, 100);
        } catch (err) {
            console.error("Erro ao acessar câmera:", err);
            setErro("Não foi possível acessar a câmera. Tente selecionar uma imagem da galeria.");
        }
    };

    const pararCamera = () => {
        if (stream) {
            stream.getTracks().forEach(track => track.stop());
            setStream(null);
        }
        setCameraAtiva(false);
    };

    const capturarFoto = () => {
        if (!videoRef.current || !canvasRef.current) return;
        if (fotos.length >= maxFotos) {
            toast.warning(`Máximo de ${maxFotos} fotos permitidas`);
            return;
        }

        const canvas = canvasRef.current;
        const video = videoRef.current;

        // Default to client dimensions or standard HD if intrinsic dimensions are not yet available
        let width = video.videoWidth || video.clientWidth || 1280;
        let height = video.videoHeight || video.clientHeight || 720;

        // Maximum dimensions to prevent canvas memory/processing errors on mobile
        const MAX_WIDTH = 1280;
        const MAX_HEIGHT = 1280;

        // Calculate aspect ratio and resize if necessary
        if (width > height) {
            if (width > MAX_WIDTH) {
                height *= MAX_WIDTH / width;
                width = MAX_WIDTH;
            }
        } else {
            if (height > MAX_HEIGHT) {
                width *= MAX_HEIGHT / height;
                height = MAX_HEIGHT;
            }
        }

        canvas.width = width;
        canvas.height = height;

        const ctx = canvas.getContext('2d');
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

        // Adicionar marca d'água com data/hora
        const agora = new Date();
        const dataHora = agora.toLocaleString('pt-BR');
        ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
        ctx.fillRect(0, canvas.height - 30, canvas.width, 30);
        ctx.fillStyle = '#fff';
        ctx.font = '14px Arial';
        ctx.fillText(`${dataHora} - Pedido #${numeroPedido || 'N/A'}`, 10, canvas.height - 10);

        try {
            const dataUrl = canvas.toDataURL('image/jpeg', 0.8);
            if (dataUrl === "data:,") {
                console.error("toDataURL returned empty data url. Canvas dimensions:", canvas.width, 'x', canvas.height);
                toast.error("Erro ao processar imagem. Verifique permissões/memória.");
                return;
            }

            setFotos(prev => [...prev, {
                id: Date.now(),
                dataUrl,
                timestamp: agora.toISOString(),
                tipo: fotos.length === 0 ? 'principal' : 'adicional'
            }]);

            // Fecha a câmera após cada captura para mostrar preview e botão de confirmação.
            // O usuário pode tocar em "Adicionar" para tirar mais fotos.
            pararCamera();
            toast.success(`Foto ${fotos.length + 1} capturada!`);
        } catch (e) {
            console.error("Erro no toDataURL", e);
            toast.error("Erro de memória ao processar a foto. Tente novamente.");
        }
    };

    const selecionarArquivo = (e) => {
        const files = Array.from(e.target.files || []);
        if (files.length === 0) return;

        files.forEach(file => {
            if (fotos.length >= maxFotos) return;

            const reader = new FileReader();
            reader.onload = (event) => {
                setFotos(prev => {
                    if (prev.length >= maxFotos) return prev;
                    return [...prev, {
                        id: Date.now() + Math.random(),
                        dataUrl: event.target.result,
                        timestamp: new Date().toISOString(),
                        tipo: prev.length === 0 ? 'principal' : 'adicional'
                    }];
                });
            };
            reader.readAsDataURL(file);
        });
    };

    const removerFoto = (id) => {
        setFotos(prev => prev.filter(f => f.id !== id));
    };

    const uploadFotos = async () => {
        if (fotos.length < minFotos) {
            toast.error(`Tire pelo menos ${minFotos} foto(s)`);
            return;
        }

        setUploading(true);
        const fotosUploadadas = [];

        try {
            // Se já sabemos que está offline, pula o upload pesado
            if (!navigator.onLine) {
                throw new Error("Sem conexão de rede (navigator.onLine = false)");
            }

            for (let i = 0; i < fotos.length; i++) {
                const foto = fotos[i];

                // Converter base64 para blob
                const response = await fetch(foto.dataUrl);
                const blob = await response.blob();

                // Nome do arquivo
                const fileName = `entregas/${entregaId}/${Date.now()}_foto_${i + 1}.jpg`;

                // Upload para Supabase Storage
                const { data, error } = await supabase.storage
                    .from('comprovantes')
                    .upload(fileName, blob, {
                        contentType: 'image/jpeg',
                        cacheControl: '3600'
                    });

                if (error) {
                    console.error('Erro upload:', error);
                    throw error;
                }

                // Obter URL pública
                const { data: urlData } = supabase.storage
                    .from('comprovantes')
                    .getPublicUrl(fileName);

                fotosUploadadas.push({
                    url: urlData.publicUrl,
                    tipo: foto.tipo,
                    timestamp: foto.timestamp
                });
            }

            pararCamera();

            // Retornar dados com URLs públicas para o componente pai
            onComplete({
                fotos: fotosUploadadas,
                geolocalizacao,
                dataHoraEntrega: new Date().toISOString()
            });

        } catch (error) {
            console.error('Erro ao fazer upload ou detectado offline:', error);
            toast.warning('Sem conexão para envio. Salvando a foto no aparelho para sincronizar depois...');

            const fotosOffline = fotos.map(f => ({
                dataUrl: f.dataUrl,
                tipo: f.tipo,
                timestamp: f.timestamp
            }));

            pararCamera();
            onComplete({
                fotos: fotosOffline,
                isOffline: true,
                geolocalizacao,
                dataHoraEntrega: new Date().toISOString()
            });
        } finally {
            setUploading(false);
        }
    };

    return (
        <div className="space-y-4">
            {/* Header com GPS */}
            <div className="flex items-center justify-between">
                <div>
                    <h3 className="font-bold text-gray-900">Foto dos Móveis Entregues</h3>
                    <p className="text-xs text-gray-500">
                        Tire {minFotos === maxFotos ? minFotos : `${minFotos} a ${maxFotos}`} foto(s) dos móveis no local
                    </p>
                </div>
                {geolocalizacao && (
                    <div className="flex items-center gap-1 text-xs text-green-600 bg-green-50 px-2 py-1 rounded-full">
                        <MapPin className="w-3 h-3" />
                        GPS OK
                    </div>
                )}
            </div>

            {/* Preview das fotos já tiradas */}
            {fotos.length > 0 && (
                <div className="grid grid-cols-3 gap-2">
                    {fotos.map((foto, index) => (
                        <div key={foto.id} className="relative aspect-square rounded-lg overflow-hidden border-2 border-green-500">
                            <img
                                src={foto.dataUrl}
                                alt={`Foto ${index + 1}`}
                                className="w-full h-full object-cover"
                            />
                            <button
                                onClick={() => removerFoto(foto.id)}
                                className="absolute top-1 right-1 p-1 bg-red-500 text-white rounded-full"
                            >
                                <Trash2 className="w-3 h-3" />
                            </button>
                            <div className="absolute bottom-0 left-0 right-0 bg-black/50 text-white text-[10px] px-1 py-0.5 text-center">
                                {index === 0 ? 'Principal' : `Foto ${index + 1}`}
                            </div>
                        </div>
                    ))}

                    {/* Botão para adicionar mais */}
                    {fotos.length < maxFotos && (
                        <button
                            onClick={iniciarCamera}
                            className="aspect-square rounded-lg border-2 border-dashed border-gray-300 flex flex-col items-center justify-center text-gray-400 hover:border-green-500 hover:text-green-500 transition-colors"
                        >
                            <Plus className="w-6 h-6" />
                            <span className="text-xs">Adicionar</span>
                        </button>
                    )}
                </div>
            )}

            {/* Área de câmera */}
            {(fotos.length === 0 || cameraAtiva) && (
                <div className="relative bg-gray-900 rounded-xl overflow-hidden aspect-video">
                    {cameraAtiva ? (
                        <video
                            ref={videoRef}
                            autoPlay
                            playsInline
                            muted
                            className="w-full h-full object-cover"
                        />
                    ) : (
                        <div className="flex flex-col items-center justify-center h-full text-white/50">
                            <Camera className="w-12 h-12 mb-2" />
                            <p className="text-sm">Toque para abrir a câmera</p>
                        </div>
                    )}

                    {/* Guia de enquadramento */}
                    {cameraAtiva && (
                        <div className="absolute inset-4 border-2 border-white/30 rounded-lg pointer-events-none">
                            <div className="absolute top-2 left-2 w-4 h-4 border-l-2 border-t-2 border-white" />
                            <div className="absolute top-2 right-2 w-4 h-4 border-r-2 border-t-2 border-white" />
                            <div className="absolute bottom-2 left-2 w-4 h-4 border-l-2 border-b-2 border-white" />
                            <div className="absolute bottom-2 right-2 w-4 h-4 border-r-2 border-b-2 border-white" />
                        </div>
                    )}

                    {erro && (
                        <div className="absolute inset-0 flex items-center justify-center bg-black/70 text-white p-4 text-center">
                            <p className="text-sm">{erro}</p>
                        </div>
                    )}
                </div>
            )}

            {/* Canvas oculto */}
            <canvas ref={canvasRef} className="hidden" />

            {/* Controles */}
            {cameraAtiva ? (
                <div className="flex gap-2">
                    <Button
                        variant="outline"
                        onClick={pararCamera}
                        className="flex-1"
                    >
                        Cancelar
                    </Button>
                    <Button
                        onClick={capturarFoto}
                        disabled={fotos.length >= maxFotos}
                        className="flex-1 bg-green-600 hover:bg-green-700"
                    >
                        <Camera className="w-4 h-4 mr-2" />
                        Capturar
                    </Button>
                </div>
            ) : fotos.length === 0 ? (
                <div className="flex gap-2">
                    <Button
                        onClick={iniciarCamera}
                        className="flex-1 bg-blue-600 hover:bg-blue-700"
                    >
                        <Camera className="w-4 h-4 mr-2" />
                        Abrir Câmera
                    </Button>
                    <Button
                        variant="outline"
                        onClick={() => fileInputRef.current?.click()}
                        className="flex-1"
                    >
                        <Upload className="w-4 h-4 mr-2" />
                        Galeria
                    </Button>
                </div>
            ) : (
                <Button
                    onClick={uploadFotos}
                    disabled={fotos.length < minFotos || uploading}
                    className="w-full h-12 bg-green-600 hover:bg-green-700 text-lg"
                >
                    {uploading ? (
                        <>
                            <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin mr-2" />
                            Enviando...
                        </>
                    ) : (
                        <>
                            <Check className="w-5 h-5 mr-2" />
                            Confirmar {fotos.length} Foto(s)
                        </>
                    )}
                </Button>
            )}

            {/* Input de arquivo oculto */}
            <input
                ref={fileInputRef}
                type="file"
                accept="image/*"
                capture="environment"
                multiple
                onChange={selecionarArquivo}
                className="hidden"
            />

            {onCancel && (
                <Button
                    variant="ghost"
                    onClick={() => {
                        pararCamera();
                        onCancel();
                    }}
                    className="w-full"
                    disabled={uploading}
                >
                    Voltar
                </Button>
            )}
        </div>
    );
}

import React, { useState, useMemo, useEffect } from "react";
