];

// Componente de slot de turno (drop zone)
function SlotTurno({ turno, caminhaoId, dataAtual, entregas, vendas, onClickEntrega, corCaminhao, assistencias = [], activeEntrega }) {
  const dropId = `${dataAtual}-${caminhaoId}-${turno.id}`;
  const { setNodeRef, isOver } = useDroppable({
    id: dropId,
    disabled: !!activeEntrega && (function () {
      // --- LÓGICA DE RESTRIÇÃO VISUAL (MESMA DO DRAG END) ---
      if (!activeEntrega) return false;

      // 1. Data Passada
      const hojeStr = new Date().toISOString().split('T')[0];
      if (dataAtual < hojeStr) return true;

      // 2. Preferências (Dias e Turnos - WHITELIST)
      if (activeEntrega.preferencias_entrega) {
        const { dias, turnos } = activeEntrega.preferencias_entrega;

        // Check Dia da Semana - WHITELIST: Only allow if in the list
        if (dias && dias.length > 0) {
          const [y, m, d] = dataAtual.split('-').map(Number);
          const diaSemanaSlot = new Date(y, m - 1, d).getDay(); // 0=Dom

          const diasPermitidos = dias.map(d => Number(d));
          if (!diasPermitidos.includes(diaSemanaSlot)) {
            return true;
          }
        }

        // Check Turno - WHITELIST: Only allow if in the list
        if (turnos && turnos.length > 0) {
          const normalize = (str) => str.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
          const turnoSlotNorm = normalize(turno.id);

          const hasManha = turnos.some(t => normalize(t) === 'manha');
          const hasTarde = turnos.some(t => normalize(t) === 'tarde');
          const hasComercial = turnos.some(t => normalize(t) === 'comercial');

          let isAllowed = false;
          if (hasComercial) {
            isAllowed = true;
          } else {
            if (turnoSlotNorm === 'comercial') {
              isAllowed = hasManha && hasTarde;
            } else if (turnoSlotNorm === 'manha') {
              isAllowed = hasManha;
            } else if (turnoSlotNorm === 'tarde') {
              isAllowed = hasTarde;
            }
          }

          if (!isAllowed) {
            return true;
          }
        }
      }
      return false;
    })()
  });

  const entregasDoSlot = entregas.filter(e =>
    e.data_agendada?.split('T')[0] === dataAtual &&
    e.caminhao_id === caminhaoId &&
    e.turno === turno.id
  );

  const assistenciasDoSlot = assistencias.filter(a =>
    a.data_visita?.split('T')[0] === dataAtual &&
    a.caminhao_id === caminhaoId &&
    a.turno === turno.id
  );

  const totalItens = entregasDoSlot.length + assistenciasDoSlot.length;

  // --- CALCULO SE ESTÁ RESTRITO (PARA ESTILO) ---
  const isRestricted = useMemo(() => {
    if (!activeEntrega) return false;

    // 1. Data Passada (Melhorado para Local Time)
    const hoje = new Date();
    const hojeStr = new Date(hoje.getTime() - (hoje.getTimezoneOffset() * 60000)).toISOString().split('T')[0];
    if (dataAtual < hojeStr) return true;

    // 2. Preferências
    if (activeEntrega.preferencias_entrega) {
      const { dias, turnos } = activeEntrega.preferencias_entrega;

      // Check Dia (Normalized) - WHITELIST: Only allow if in the list
      if (dias && dias.length > 0) {
        const [y, m, d] = dataAtual.split('-').map(Number);
        const diaSemanaSlot = new Date(y, m - 1, d).getDay();
        const diasPermitidos = dias.map(d => Number(d));
        if (!diasPermitidos.includes(diaSemanaSlot)) return true;
      }

      // Check Turno (Normalized) - WHITELIST: Only allow if in the list
      if (turnos && turnos.length > 0) {
        const normalize = (str) => str.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
        const turnoSlotNorm = normalize(turno.id);

        const hasManha = turnos.some(t => normalize(t) === 'manha');
        const hasTarde = turnos.some(t => normalize(t) === 'tarde');
        const hasComercial = turnos.some(t => normalize(t) === 'comercial');

        let isAllowed = false;
        if (hasComercial) {
          isAllowed = true;
        } else {
          if (turnoSlotNorm === 'comercial') {
            isAllowed = hasManha && hasTarde;
          } else if (turnoSlotNorm === 'manha') {
            isAllowed = hasManha;
          } else if (turnoSlotNorm === 'tarde') {
            isAllowed = hasTarde;
          }
        }

        if (!isAllowed) {
          return true;
        }
      }
    }

    return false;
  }, [activeEntrega, dataAtual, turno.id]);


  return (
    <div
      ref={setNodeRef}
      className={`flex-1 flex flex-col border rounded-lg transition-all 
        ${isRestricted ? 'opacity-30 grayscale pointer-events-none bg-gray-100' : ''}
        ${isOver && !isRestricted
          ? `${corCaminhao.ring} ring-2 ${turno.bg} scale-[1.01]`
          : `${turno.border} ${turno.bg}/50 hover:${turno.bg}`
        }`}
    >
      {/* Header do turno */}
      <div className={`px-2 py-1 border-b ${turno.border} flex items-center gap-1`}>
        <turno.Icon className={`w-3.5 h-3.5 ${turno.iconColor}`} />
        <span className={`text-[10px] font-bold ${turno.text}`}>{turno.label}</span>
        {totalItens > 0 && (
          <Badge variant="secondary" className="ml-auto text-[9px] h-4 px-1">
            {totalItens}
          </Badge>
        )}
      </div>

      {/* Itens do slot */}
      <div className="flex-1 p-1.5 space-y-1 min-h-[60px]">
        {entregasDoSlot.map(entrega => (
          <EntregaCard
            key={entrega.id}
            entrega={entrega}
            venda={vendas.find(v => v.id === entrega.venda_id)}
            onClick={onClickEntrega}
            isColumn={true}
          />
        ))}

        {assistenciasDoSlot.map(at => (
          <AssistenciaCard
            key={at.id}
            assistencia={at}
            isColumn={true}
          />
        ))}

        {totalItens === 0 && isOver && (
          <div className={`h-full flex items-center justify-center ${turno.text}`}>
            <p className="text-[10px] font-bold">Solte aqui</p>
          </div>
        )}
      </div>
    </div>
  );
}

// Componente Visual da Aba de Data com Drop/Hover logic
function DateTabVisual({ dia, index, isSelected, onClick, activeEntrega, onHoverSwitch }) {
  const { setNodeRef, isOver } = useDroppable({
    id: `tab-date-${index}`,
    data: { type: 'date-tab', index }
  });

  // Hover timer logic
  useEffect(() => {
    if (isOver && activeEntrega) {
      const timer = setTimeout(() => {
        onHoverSwitch(index);
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [isOver, activeEntrega, index, onHoverSwitch]);

  // Restrição Visual logic
  const isRestricted = useMemo(() => {
    if (!activeEntrega) return false;

    // 1. Data Passada (Melhorado para Local Time)
    const hoje = new Date();
    const hojeStr = new Date(hoje.getTime() - (hoje.getTimezoneOffset() * 60000)).toISOString().split('T')[0];
    if (dia.id < hojeStr) return true;

    // 2. Preferências (Dia da Semana - WHITELIST)
    if (activeEntrega.preferencias_entrega?.dias?.length > 0) {
      const diasPermitidos = activeEntrega.preferencias_entrega.dias.map(d => Number(d));
      // SE NÃO ESTÁ NA LISTA -> BLOQUEADO
      if (!diasPermitidos.includes(dia.diaSemana)) return true;
    }

    return false;
  }, [activeEntrega, dia]);

  return (
    <button
      ref={setNodeRef}
      onClick={onClick}
      className={`flex-1 min-w-[80px] px-3 py-2 rounded-lg text-center transition-all relative
        ${isRestricted ? 'opacity-30 grayscale cursor-not-allowed bg-gray-100' : ''}
        ${isSelected
          ? 'bg-blue-600 text-white shadow-md'
          : dia.isHoje
            ? 'bg-blue-50 text-blue-700 hover:bg-blue-100'
            : 'bg-gray-50 text-gray-600 hover:bg-gray-100'
        }
        ${isOver && !isRestricted && !isSelected ? 'ring-2 ring-blue-400 bg-blue-50' : ''}
      `}
    >
      {/* Loading indicator if hover switching */}
      {isOver && !isRestricted && !isSelected && (
        <div className="absolute top-0 left-0 w-full h-1 bg-blue-200 overflow-hidden rounded-t-lg">
          <div className="h-full bg-blue-600 animate-[progress_1s_linear]" />
        </div>
      )}

      <p className="font-bold text-sm">{dia.label}</p>
      <p className={`text-[10px] ${isSelected ? 'text-blue-100' : 'text-gray-400'}`}>
        {dia.dataFormatada}
      </p>
      {dia.totalEntregas > 0 && (
        <Badge className={`mt-1 text-[9px] ${isSelected ? 'bg-white/20 text-white' : 'bg-gray-200 text-gray-600'}`}>
          {dia.totalEntregas}
        </Badge>
      )}
    </button>
  );
}

// Componente de coluna para cada caminhão
function ColunaCaminhao({ caminhao, cor, dataAtual, entregas, vendas, onClickEntrega, onNotificar, onOtimizar, assistencias = [], activeEntrega }) {
  const { isPaidModuleActive } = useTenant();
  const entregasDoCaminhao = entregas.filter(e =>
    e.data_agendada?.split('T')[0] === dataAtual &&
    e.caminhao_id === caminhao.id
  );

  const assistenciasDoCaminhao = assistencias.filter(a =>
    a.data_visita?.split('T')[0] === dataAtual &&
    a.caminhao_id === caminhao.id
  );

  // Verificar quais entregas já foram notificadas
  const entregasParaDisparo = entregasDoCaminhao.filter(e => e.status !== 'Entregue' && !isStatusCancelado(e.status));
  const entregasJaNotificadas = entregasParaDisparo.filter(e => {
    const dataAgendada = e.data_agendada?.split('T')[0];
    return dataAgendada === e.data_notificacao && e.turno === e.turno_notificacao;
  });
  const entregasNaoNotificadas = entregasParaDisparo.filter(e => !entregasJaNotificadas.includes(e));

  // Verificar quais assistências já foram notificadas (usando mesma lógica)
  const assistenciasParaDisparo = assistenciasDoCaminhao.filter(a => a.status !== 'Concluída' && !isStatusCancelado(a.status));
  const assistenciasJaNotificadas = assistenciasParaDisparo.filter(a => {
    const dataVisita = a.data_visita?.split('T')[0];
    return dataVisita === a.data_notificacao && a.turno === a.turno_notificacao;
  });
  const assistenciasNaoNotificadas = assistenciasParaDisparo.filter(a => !assistenciasJaNotificadas.includes(a));

  const totalParaDisparo = entregasParaDisparo.length + assistenciasParaDisparo.length;
  const totalNaoNotificadas = entregasNaoNotificadas.length + assistenciasNaoNotificadas.length;
  const totalJaNotificadas = entregasJaNotificadas.length + assistenciasJaNotificadas.length;

  return (
    <div className="flex-1 min-w-[220px] max-w-[300px] flex flex-col rounded-xl border-2 border-gray-200 bg-white">
      {/* Header do caminhão */}
      <div className={`px-3 py-2 border-b flex items-center gap-2 bg-gradient-to-r ${cor.bg} rounded-t-lg`}>
        <div className={`p-1.5 rounded-md ${cor.badge} text-white`}>
          <Truck className="w-4 h-4" />
        </div>
        <div className="flex-1 min-w-0">
          <p className={`font-bold text-sm ${cor.text} truncate`}>{caminhao.nome || caminhao.placa}</p>
          <p className="text-[10px] text-gray-500">{caminhao.placa}</p>
        </div>

        {/* Botão de Confirmar (Antigo Notificar) */}
        {totalParaDisparo > 0 && (
          <button
            onClick={() => onNotificar(caminhao, {
              entregas: entregasParaDisparo,
              entregasNaoNotificadas,
              entregasJaNotificadas,
              assistencias: assistenciasParaDisparo,
              assistenciasNaoNotificadas,
              assistenciasJaNotificadas,
              totalNaoNotificadas,
              totalJaNotificadas
            })}
            className={`flex items-center gap-1.5 px-2 py-1 rounded-md transition-all text-[10px] font-bold uppercase tracking-wide ${
              !isPaidModuleActive('whatsapp')
                ? 'bg-amber-100 text-amber-700 hover:bg-amber-200 border border-amber-200'
                : totalNaoNotificadas > 0
                  ? 'bg-green-600 hover:bg-green-700 text-white shadow-sm'
                  : 'bg-gray-200 text-gray-500'
              }`}
            title={
              !isPaidModuleActive('whatsapp')
                ? "Módulo de WhatsApp desativado no plano atual"
                : totalNaoNotificadas > 0
                  ? `Solicitar confirmação de ${totalNaoNotificadas} itens`
                  : 'Todos confirmados'
            }
          >
            <CheckCircle className="w-3.5 h-3.5" />
            {totalNaoNotificadas > 0 && <span>Confirmar</span>}
          </button>
        )}

        {/* Botão Otimizar Rota */}
        {entregasDoCaminhao.length >= 2 && (
          <button
            onClick={() => onOtimizar(entregasDoCaminhao)}
            className="p-1.5 rounded-md transition-all bg-blue-500 hover:bg-blue-600 text-white"
            title="Otimizar rota"
          >
            <Route className="w-3.5 h-3.5" />
          </button>
        )}

        <Badge className={`${cor.badge} text-white text-[10px]`}>
          {entregasDoCaminhao.length}
        </Badge>
      </div>

      {/* 3 Slots de Turno */}
      <div className="flex-1 flex flex-col gap-1.5 p-2 overflow-y-auto">
        {TURNOS.map(turno => (
          <SlotTurno
            key={turno.id}
            turno={turno}
            caminhaoId={caminhao.id}
            dataAtual={dataAtual}
            entregas={entregas}
            vendas={vendas}
            onClickEntrega={onClickEntrega}
            corCaminhao={cor}
            assistencias={assistencias}
            activeEntrega={activeEntrega}
          />
        ))}
      </div>
    </div>
  );
}


export default function KanbanRotasSemanal({ entregas, vendas, entregasPendentes, caminhoes = [], assistencias = [] }) {
  const queryClient = useQueryClient();
  const { isPaidModuleActive } = useTenant();
  const [activeId, setActiveId] = useState(null);
  const [entregaSelecionada, setEntregaSelecionada] = useState(null);
  const [searchTriagem, setSearchTriagem] = useState("");
  const [pedidoEnvioManual, setPedidoEnvioManual] = useState("");
  const [caminhaoEnvioManual, setCaminhaoEnvioManual] = useState("");
  const [turnoEnvioManual, setTurnoEnvioManual] = useState("Comercial");
  const [dataEnvioManual, setDataEnvioManual] = useState("");
  const [semanaOffset, setSemanaOffset] = useState(0);
  const [weekNavDirection, setWeekNavDirection] = useState(null);
  const [weekNavAnimationKey, setWeekNavAnimationKey] = useState(0);
  const [diaSelecionado, setDiaSelecionado] = useState(null); // null = nenhum dia selecionado

  // Estados para modais

  // Estados para disparo de notificações (por caminhão)
  const [modalDisparo, setModalDisparo] = useState(null); // { caminhao, entregas, naoNotificadas, jaNotificadas }
  const [statusServidor, setStatusServidor] = useState("verificando");
  const [loadingDisparo, setLoadingDisparo] = useState(false);

  // Estado para otimização de rotas
  const [modalOtimizacao, setModalOtimizacao] = useState(null); // Array de entregas para otimizar

  // Estados para reagendamento
  const [modalReagendamento, setModalReagendamento] = useState(null); // { entrega }
  const [motivoReagendamento, setMotivoReagendamento] = useState("");

  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 5 } }));

  const { setNodeRef: setTriagemRef, isOver: isOverTriagem } = useDroppable({ id: 'triagem' });

  const atualizarEntregaMutation = useMutation({
    mutationFn: async ({ id, data }) => {
      return await base44.entities.Entrega.update(id, data);
    },
    onError: (error) => console.error("Erro ao atualizar entrega:", error)
  });

  const diasSemana = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'];

  // Calcular início e fim da semana (Segunda a Domingo)
  const getWeekRange = (offset = 0) => {
    const hoje = new Date();
    const diaSemana = hoje.getDay(); // 0 = Domingo, 1 = Segunda, ...

    // Ajustar para Monday ser o primeiro dia (1) e Domingo o último (7)
    // Se hoje é Domingo (0), queremos voltar 6 dias para pegar a Segunda passada
    // Se hoje é Segunda (1), voltamos 0 dias
    const diffToMonday = diaSemana === 0 ? -6 : 1 - diaSemana;

    const inicioSemana = new Date(hoje);
    inicioSemana.setDate(hoje.getDate() + diffToMonday + (offset * 7));
    inicioSemana.setHours(0, 0, 0, 0);

    return inicioSemana;
  };

  const inicioSemanaAtual = getWeekRange(semanaOffset);

  const navigateSemana = (direction) => {
    setWeekNavDirection(direction);
    setSemanaOffset((s) => s + direction);
    setWeekNavAnimationKey((k) => k + 1);
  };

  // Gerar os 7 dias da semana (Segunda a Domingo)
  const diasDisponiveis = useMemo(() => {
    const dias = [];
    const hojeStr = new Date().toISOString().split('T')[0];

    for (let i = 0; i < 7; i++) {
      const dia = new Date(inicioSemanaAtual);
      dia.setDate(inicioSemanaAtual.getDate() + i);
      const dataKey = dia.toISOString().split('T')[0];

      // Contar entregas do dia
      const entregasDoDia = (entregas || []).filter(e => e.data_agendada?.split('T')[0] === dataKey);

      dias.push({
        id: dataKey,
        label: diasSemana[dia.getDay()],
        dataFormatada: `${dia.getDate().toString().padStart(2, '0')}/${(dia.getMonth() + 1).toString().padStart(2, '0')}`,
        isHoje: dataKey === hojeStr,
        totalEntregas: entregasDoDia.length,
        diaSemana: dia.getDay()
      });
    }
    return dias;
  }, [entregas, inicioSemanaAtual]);

  const dataAtual = diaSelecionado !== null ? diasDisponiveis[diaSelecionado]?.id : null;

  useEffect(() => {
    if (!dataEnvioManual && diasDisponiveis.length > 0) {
      const hojeDaSemana = diasDisponiveis.find(d => d.isHoje);
      setDataEnvioManual(hojeDaSemana?.id || diasDisponiveis[0].id);
    }
  }, [diasDisponiveis, dataEnvioManual]);

  // Filtra a triagem pela busca
  const pendentesFiltrados = (entregasPendentes || []).filter(e => {
    const termo = searchTriagem.toLowerCase();
    if (!termo) return true;
    const matchCliente = e.cliente_nome?.toLowerCase().includes(termo);
    const matchPedido = e.numero_pedido?.toString().includes(termo);
    const venda = (vendas || []).find(v => v.id === e.venda_id);
    const matchProduto = venda?.itens?.some(i => buildProductDisplayName(i.produto_nome, i.modelo_referencia).toLowerCase().includes(termo));
    return matchCliente || matchPedido || matchProduto;
  });

  const entregasConfirmadasNaoEntregues = useMemo(() => {
    return (entregas || [])
      .filter((e) =>
        e.status_confirmacao === 'Confirmada' &&
        e.data_agendada &&
        e.status !== 'Entregue' &&
        !isStatusCancelado(e.status)
      )
      .sort((a, b) => (a.data_agendada || '').localeCompare(b.data_agendada || ''));
  }, [entregas]);

  const buscaPedidoInfo = useMemo(() => {
    const termo = (searchTriagem || '').trim();
    if (!termo) return null;

    const entrega = (entregas || []).find((e) => String(e.numero_pedido) === termo);
    if (!entrega) return null;

    const dataAgendada = entrega.data_agendada?.split('T')[0] || null;
    const diaIndex = dataAgendada ? diasDisponiveis.findIndex((d) => d.id === dataAgendada) : -1;
    const caminhao = caminhoes.find((c) => String(c.id) === String(entrega.caminhao_id));

    return {
      entrega,
      caminhao,
      dataAgendada,
      diaIndex,
      localizadaEmCaminhao: Boolean(entrega.caminhao_id && dataAgendada && caminhao)
    };
  }, [searchTriagem, entregas, diasDisponiveis, caminhoes]);

  useEffect(() => {
    if (buscaPedidoInfo?.localizadaEmCaminhao && buscaPedidoInfo.diaIndex >= 0) {
      setDiaSelecionado(buscaPedidoInfo.diaIndex);
    }
  }, [buscaPedidoInfo]);

  const caminhoesFiltradosPorBusca = useMemo(() => {
    if (!buscaPedidoInfo?.localizadaEmCaminhao) return caminhoes;
    return caminhoes.filter((c) => String(c.id) === String(buscaPedidoInfo.entrega.caminhao_id));
  }, [caminhoes, buscaPedidoInfo]);


  // Assistências não agendadas (sem data_visita ou caminhao_id) - aparecem na triagem
  const assistenciasNaoAgendadas = (assistencias || []).filter(a =>
    !a.data_visita || !a.caminhao_id
  );

  // Entrega ativa (sendo arrastada)
  // Entrega ou Assistência ativa (sendo arrastada)
  const activeEntrega = useMemo(() => {
    if (!activeId) return null;
    const idStr = activeId.toString();

    // Se for assistência
    if (idStr.startsWith('at-')) {
      const cleanId = idStr.replace('at-', '');
      const assist = (assistencias || []).find(a => a.id.toString() === cleanId);
      if (assist) return { ...assist, isAssistencia: true, cliente_nome: `(AT) ${assist.cliente_nome}` };
    }

    // Se for entrega
    return (entregas || []).find(e => e.id.toString() === idStr);
  }, [activeId, entregas, assistencias]);

  // Verificar servidor do bot
  const verificarServidor = async () => {
    setStatusServidor("verificando");
    try {
      if (await whatsappService.checkStatus()) {
        setStatusServidor("online");
      } else {
        setStatusServidor("offline");
      }
    } catch (error) {
      console.error("Erro ao verificar servidor:", error);
      setStatusServidor("offline");
    }
  };


  // Abrir modal de notificação para um caminhão específico
  const handleNotificarCaminhao = (caminhao, dados) => {
    if (!isPaidModuleActive('whatsapp')) {
      toast.error("O módulo de WhatsApp não está ativo no plano da sua organização.");
      return;
    }
    setModalDisparo({ caminhao, ...dados });
    verificarServidor();
  };

  // Disparar confirmações via WhatsApp para o caminhão selecionado
  const enviarConfirmacoes = async () => {
    if (!modalDisparo) return;

    setLoadingDisparo(true);
    try {
      const {
        entregasNaoNotificadas = [],
        assistenciasNaoNotificadas = [],
        caminhao
      } = modalDisparo;

      const totalParaEnviar = entregasNaoNotificadas.length + assistenciasNaoNotificadas.length;

      if (totalParaEnviar === 0) {
        toast.success("✅ Todos já confirmados!");
        setModalDisparo(null);
        setLoadingDisparo(false);
        return;
      }

      // Payload para entregas
      const payloadEntregas = entregasNaoNotificadas.map(entrega => {
        const venda = (vendas || []).find(v => v.id === entrega.venda_id);
        const listaProdutos = venda?.itens?.map(item => `• ${item.quantidade}x ${buildProductDisplayName(item.produto_nome, item.modelo_referencia)}`).join('\n') || "Itens não informados";
        return {
          id: entrega.id,
          tipo: 'entrega',
          numero_pedido: entrega.numero_pedido,
          cliente_nome: entrega.cliente_nome,
          telefone: entrega.cliente_telefone,
          turno: entrega.turno || "Comercial",
          produtos: listaProdutos,
          data_agendada: entrega.data_agendada
        };
      });

      // Payload para assistências
      const payloadAssistencias = assistenciasNaoNotificadas.map(at => {
        const itensTexto = at.itens_envolvidos?.map(i => `• ${buildProductDisplayName(i.produto_nome, i.modelo_referencia)}`).join('\n') || at.tipo;
        return {
          id: at.id,
          tipo: 'assistencia',
          numero_pedido: at.numero_pedido,
          cliente_nome: at.cliente_nome,
          telefone: at.cliente_telefone,
          turno: at.turno || "Comercial",
          produtos: itensTexto,
          data_agendada: at.data_visita,
          tipo_assistencia: at.tipo
        };
      });

      const payloadCompleto = [...payloadEntregas, ...payloadAssistencias];

      const response = await whatsappService.sendConfirmations(payloadCompleto);

      if (response.ok) {
        // Marcar entregas como notificadas
        for (const entrega of entregasNaoNotificadas) {
          try {
            await base44.entities.Entrega.update(entrega.id, {
              status_confirmacao: 'Notificada', // Fluxo direto para Notificada
              whatsapp_enviado: true,
              data_notificacao: entrega.data_agendada?.split('T')[0],
              turno_notificacao: entrega.turno,
              ultima_notificacao: new Date().toISOString()
            });
          } catch (dbError) {
            console.warn('Erro ao atualizar entrega:', dbError);
          }
        }

        // Marcar assistências como notificadas
        for (const at of assistenciasNaoNotificadas) {
          try {
            await base44.entities.AssistenciaTecnica.update(at.id, {
              data_notificacao: at.data_visita?.split('T')[0],
              turno_notificacao: at.turno,
              ultima_notificacao: new Date().toISOString()
            });
          } catch (dbError) {
            console.warn('Erro ao atualizar assistência:', dbError);
          }
        }

        toast.success(`✅ Solicitação de confirmação enviada para ${totalParaEnviar} clientes!`);
        setModalDisparo(null);
        queryClient.invalidateQueries({ queryKey: ['entregas'] });
        queryClient.invalidateQueries({ queryKey: ['assistencias'] });
      } else {
        toast.error("Erro do robô");
      }
    } catch (error) {
      console.error('Erro ao enviar:', error);
      toast.warning("⚠️ Não foi possível conectar ao robô.");
    } finally { setLoadingDisparo(false); }
  };

  const handleDragStart = (event) => { setActiveId(event.active.id); };

  const handleDragEnd = async (event) => {
    const { active, over } = event;
    setActiveId(null);
    if (!over) return;

    const itemId = active.id;
    const overId = over.id.toString();
    const isAssistencia = itemId.toString().startsWith('at-');

    // Se for assistência, tratar separadamente
    if (isAssistencia) {
      const assistenciaId = itemId.toString().replace('at-', ''); // UUID - manter como string

      // Soltou em um slot de turno → associar data/caminhão/turno (se o sistema suportar)
      const turnoMatch = overId.match(/^(\d{4}-\d{2}-\d{2})-(\d+)-(Manhã|Tarde|Comercial)$/);
      if (turnoMatch) {
        const dataAlvo = turnoMatch[1];

        // Guardrail: Não permitir agendar para o passado
        const hojeStr = new Date().toISOString().split('T')[0];
        if (dataAlvo < hojeStr) {
          toast.error("Não é possível agendar para uma data passada!");
          return;
        }

        const caminhaoId = parseInt(turnoMatch[2]);
        const turno = turnoMatch[3];
        const caminhao = caminhoes.find(c => c.id === caminhaoId);

        try {
          await base44.entities.AssistenciaTecnica.update(assistenciaId, {
            data_visita: dataAlvo,
            caminhao_id: caminhaoId,
            turno: turno,
            status: 'Agendado' // Requer adicionar 'Agendado' ao check constraint
          });
          toast.success(`AT agendada - ${turno} - ${caminhao?.nome || caminhao?.placa}`);
          queryClient.invalidateQueries({ queryKey: ['assistencias'] });
        } catch (error) {
          console.error('Erro ao agendar assistência:', error);
          toast.error("Erro ao agendar assistência");
        }
      }
      return;
    }

    // É uma entrega normal
    const entregaId = itemId.toString();
    const entregaAtual = (entregas || []).find(e => e.id.toString() === entregaId);

    if (!entregaAtual) {
      console.error("❌ Entrega não encontrada no drop:", itemId);
      return;
    }

    // 1. Soltou na Triagem → Desagendar
    if (overId === 'triagem') {
      queryClient.setQueryData(['entregas'], (oldData) =>
        oldData.map(e => e.id === entregaId ? { ...e, data_agendada: null, turno: null, ordem_rota: null, status: 'Pendente', caminhao_id: null } : e)
      );

      try {
        await atualizarEntregaMutation.mutateAsync({
          id: entregaId,
          data: { data_agendada: null, turno: null, ordem_rota: null, status: 'Pendente', caminhao_id: null }
        });
        toast.success("Entrega desagendada");
        setTimeout(() => queryClient.invalidateQueries({ queryKey: ['entregas'] }), 500);
      } catch (error) {
        queryClient.invalidateQueries({ queryKey: ['entregas'] });
      }
      return;
    }

    // 2. Soltou em "Aguardando Liberação"
    if (overId === 'aguardando') {
      // Otimista: Mover para "Aguardando Liberação" na UI
      queryClient.setQueryData(['entregas'], (oldData) =>
        oldData.map(e => e.id === entregaId ? { ...e, status: 'Aguardando Liberação', data_agendada: null, turno: null, caminhao_id: null } : e)
      );
      try {
        await atualizarEntregaMutation.mutateAsync({
          id: entregaId,
          data: { status: 'Aguardando Liberação', data_agendada: null, turno: null, caminhao_id: null }
        });
      } catch (error) {
        queryClient.invalidateQueries({ queryKey: ['entregas'] });
      }
      return;
    }

    // 3. Soltou em um slot de turno → Agendar para data + caminhão + turno
    // Formato do ID: ${data}-${caminhaoId}-${turno}
    // Exemplo: 2025-12-28-5-Manhã
    const turnoMatch = overId.match(/^(\d{4}-\d{2}-\d{2})-(\d+)-(Manhã|Tarde|Comercial)$/);
    if (turnoMatch) {
      const dataAlvo = turnoMatch[1];

      // Guardrail: Não permitir agendar para o passado
      const hojeStr = new Date().toISOString().split('T')[0];
      if (dataAlvo < hojeStr) {
        toast.error("Não é possível agendar para uma data passada!");
        return;
      }

      const caminhaoId = parseInt(turnoMatch[2]);
      const turno = turnoMatch[3];

      // GUARDRAIL: Preferências de Entrega (WHITELIST)
      if (entregaAtual.preferencias_entrega) {
        const { dias, turnos } = entregaAtual.preferencias_entrega;

        // Verificar Dia da Semana (Whitelist)
        if (dias && dias.length > 0) {
          const [y, m, d] = dataAlvo.split('-').map(Number);
          const diaSemanaAlvo = new Date(y, m - 1, d).getDay(); // 0=Dom

          const diasPermitidos = dias.map(d => Number(d));
          if (!diasPermitidos.includes(diaSemanaAlvo)) {
            const nomesDias = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'];
            toast.error(`BLOQUEADO: Dia não permitido pelo Cliente`, {
              description: `O cliente só permite receber em: ${diasPermitidos.map(d => nomesDias[d]).join(', ')}.`,
              duration: 4000
            });
            return;
          }
        }

        // Verificar Turno (Whitelist - Normalized)
        if (turnos && turnos.length > 0) {
          const normalize = (str) => str.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
          const turnoTargetNorm = normalize(turno);

          const hasManha = turnos.some(t => normalize(t) === 'manha');
          const hasTarde = turnos.some(t => normalize(t) === 'tarde');
          const hasComercial = turnos.some(t => normalize(t) === 'comercial');

          let isAllowed = false;
          if (hasComercial) {
            isAllowed = true;
          } else {
            if (turnoTargetNorm === 'comercial') {
              isAllowed = hasManha && hasTarde;
            } else if (turnoTargetNorm === 'manha') {
              isAllowed = hasManha;
            } else if (turnoTargetNorm === 'tarde') {
              isAllowed = hasTarde;
            }
          }

          if (!isAllowed) {
            toast.error(`BLOQUEADO: Turno não permitido pelo Cliente`, {
              description: `O cliente só permite receber no turno: ${turnos.join(', ')}.`,
              duration: 4000
            });
            return;
          }
        }
      }

      const caminhao = caminhoes.find(c => c.id === caminhaoId);
      const isDateChange = entregaAtual.data_agendada?.split('T')[0] !== dataAlvo;

      const normalize = (str) => (str || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
      const isShiftChange = normalize(entregaAtual.turno) !== normalize(turno);

      const updateData = {
        data_agendada: dataAlvo,
        turno: turno,
        ordem_rota: null,
        status: 'Agendada',
        caminhao_id: caminhaoId
      };

      // Se apenas o caminhão mudou, mantém confirmação já existente.
      if (entregaAtual.status_confirmacao === 'Confirmada' && !isDateChange && !isShiftChange) {
        updateData.status_confirmacao = 'Confirmada';
      }

      console.log("🛠️ Drag Check:", {
        status: entregaAtual.status_confirmacao,
        isConfirmada: entregaAtual.status_confirmacao === 'Confirmada',
        isDateChange,
        isShiftChange,
        entTurno: entregaAtual.turno,
        newTurno: turno
      });

      // 4. Se já está CONFIRMADA e trocou de data OU turno, pedir motivo
      if (entregaAtual.status_confirmacao === 'Confirmada' && (isDateChange || isShiftChange)) {
        setModalReagendamento({
          entrega: entregaAtual,
          novoAgendamento: updateData,
          isMove: true
        });
        return; // Interrompe o drag imediato
      }

      // Atualização otimista
      queryClient.setQueryData(['entregas'], (oldData) =>
        oldData.map(e => String(e.id) === String(entregaId) ? { ...e, ...updateData } : e)
      );

      try {
        await atualizarEntregaMutation.mutateAsync({ id: entregaId, data: updateData });
        toast.success(`${turno} - ${caminhao?.nome || caminhao?.placa}`);
        setTimeout(() => queryClient.invalidateQueries({ queryKey: ['entregas'] }), 500);
      } catch (error) {
        queryClient.invalidateQueries({ queryKey: ['entregas'] });
        toast.error("Erro ao agendar");
      }
      return;
    }
  };


  const handleCardClick = (item, action) => {
    if (action === 'reagendar') {
      setModalReagendamento({ entrega: item });
      setMotivoReagendamento("");
    } else {
      setEntregaSelecionada(item);
    }
  };

  const confirmarReagendamento = async () => {
    if (!modalReagendamento || !motivoReagendamento.trim()) {
      toast.error("Informe o motivo do reagendamento");
      return;
    }

    try {
      const historicoAtual = modalReagendamento.entrega.historico_reagendamentos || [];
      const novoEvento = {
        data_anterior: modalReagendamento.entrega.data_agendada,
        data_nova: modalReagendamento.isMove ? modalReagendamento.novoAgendamento.data_agendada : null,
        motivo: motivoReagendamento,
        data_registro: new Date().toISOString(),
        usuario: 'Logistica',
        tipo: modalReagendamento.isMove ? 'ALTERACAO_DATA' : 'CANCELAMENTO'
      };

      if (modalReagendamento.isMove) {
        // CASO 1: MOVER (Trocar Data)
        await atualizarEntregaMutation.mutateAsync({
          id: modalReagendamento.entrega.id,
          data: {
            ...modalReagendamento.novoAgendamento,
            status_confirmacao: 'Notificada', // Resetar confirmação pois mudou data
            historico_reagendamentos: [...historicoAtual, novoEvento]
          }
        });

        // DISPARAR NOTIFICAÇÃO DE REAGENDAMENTO PARA O CLIENTE
        try {
          if (isPaidModuleActive('whatsapp')) {
            const venda = (vendas || []).find(v => v.id === modalReagendamento.entrega.venda_id);
            const listaProdutos = venda?.itens?.map(item => `• ${item.quantidade}x ${buildProductDisplayName(item.produto_nome, item.modelo_referencia)}`).join('\n') || "Itens não informados";

            const payload = [{
              id: modalReagendamento.entrega.id,
              tipo: 'entrega',
              numero_pedido: modalReagendamento.entrega.numero_pedido,
              cliente_nome: modalReagendamento.entrega.cliente_nome,
              telefone: modalReagendamento.entrega.cliente_telefone,
              turno: modalReagendamento.novoAgendamento.turno || "Comercial",
              produtos: listaProdutos,
              data_agendada: modalReagendamento.novoAgendamento.data_agendada,
              is_reagendamento: true // Flag para mensagem diferenciada
            }];

            await whatsappService.sendConfirmations(payload);
            toast.success("Cliente notificado via WhatsApp!");
          } else {
            console.log("Notificação de reagendamento pulada: módulo 'whatsapp' inativo.");
          }
        } catch (err) {
          console.error("Erro ao notificar reagendamento:", err);
          toast.warning("Reagendado, mas erro ao notificar WhatsApp.");
        }

        toast.success("Entrega reagendada! Status resetado para 'Notificada'.");
      } else {
        // CASO 2: CANCELAR (Voltar para Triagem)
        await atualizarEntregaMutation.mutateAsync({
          id: modalReagendamento.entrega.id,
          data: {
            status: 'Pendente',
            data_agendada: null,
            turno: null,
            caminhao_id: null,
            ordem_rota: null,
            status_confirmacao: null, // Limpar confirmação
            // Registrar restrição
            data_restricao: modalReagendamento.entrega.data_agendada,
            turno_restricao: modalReagendamento.entrega.turno,
            motivo_restricao: motivoReagendamento,
            historico_reagendamentos: [...historicoAtual, novoEvento]
          }
        });
        toast.success("Entrega retornada para triagem com restrição de data.");
      }

      queryClient.invalidateQueries({ queryKey: ['entregas'] });
    } catch (error) {
      console.error("Erro ao reagendar:", error);
      toast.error("Erro ao processar solicitação");
    }
    setModalReagendamento(null);
    setMotivoReagendamento("");
  };

  const enviarPedidoManual = async () => {
    const pedido = (pedidoEnvioManual || '').trim();
    if (!pedido || !caminhaoEnvioManual || !turnoEnvioManual || !dataEnvioManual) {
      toast.error("Preencha pedido, caminhão, data e turno para enviar.");
      return;
    }

    const entrega = (entregasPendentes || []).find((e) => String(e.numero_pedido) === pedido);
    if (!entrega) {
      toast.error("Pedido não está na triagem pendente ou não foi encontrado.");
      return;
    }

    const updateData = {
      data_agendada: dataEnvioManual,
      turno: turnoEnvioManual,
      caminhao_id: Number(caminhaoEnvioManual),
      status: 'Agendada',
      ordem_rota: null
    };

    try {
      await atualizarEntregaMutation.mutateAsync({ id: entrega.id, data: updateData });
      toast.success(`Pedido #${pedido} enviado para caminhão e turno selecionados.`);
      setPedidoEnvioManual("");
      queryClient.invalidateQueries({ queryKey: ['entregas'] });
    } catch (error) {
      toast.error("Erro ao enviar pedido para o caminhão.");
    }
  };

  return (
    <>
      <DndContext sensors={sensors} collisionDetection={rectIntersection} onDragStart={handleDragStart} onDragEnd={handleDragEnd}>
        <div className="h-full flex flex-col gap-4 p-4 rounded-2xl bg-gray-50">

          {/* --- TRIAGEM + AGUARDANDO --- */}
          <div className="flex gap-3 h-[250px] flex-shrink-0 w-full min-w-0">
            {/* Triagem */}
            <Card
              ref={setTriagemRef}
              className={`flex-1 flex flex-col border-0 transition-all shadow-sm w-full min-w-0 ${isOverTriagem ? 'bg-blue-100 ring-4 ring-blue-400' : 'bg-white/80 backdrop-blur'}`}
            >
              <div className="px-3 py-2 border-b flex justify-between items-center bg-white/50 rounded-t-xl gap-4">
                <div className="flex items-center gap-2 flex-shrink-0">
                  <div className={`p-1.5 rounded-md ${isOverTriagem ? 'bg-blue-600 text-white' : 'bg-orange-100 text-orange-600'}`}>
                    <PackageOpen className="w-4 h-4" />
                  </div>
                  <h3 className="font-bold text-sm text-gray-800">
                    {isOverTriagem ? "Solte para Desagendar" : "Triagem"}
                  </h3>
                </div>

                <div className="relative flex-1 max-w-sm">
                  <Search className="absolute left-2 top-1/2 -translate-y-1/2 w-3 h-3 text-gray-400" />
                  <Input
                    className="h-7 text-xs pl-7 bg-white border-gray-200"
                    placeholder="Buscar (cliente/produto/pedido)"
                    value={searchTriagem}
                    onChange={e => setSearchTriagem(e.target.value)}
                  />
                </div>

                <div className="flex items-center gap-1.5">
                  <Badge variant="secondary" className="text-[10px] font-mono bg-blue-100 text-blue-700">
                    {pendentesFiltrados.length} 🚚
                  </Badge>
                  {assistenciasNaoAgendadas.length > 0 && (
                    <Badge className="text-[10px] font-mono bg-purple-600 text-white">
                      {assistenciasNaoAgendadas.length} 🔧
                    </Badge>
                  )}
                </div>
              </div>

              <div className="px-3 py-2 border-b bg-slate-50/60">
                <div className="grid grid-cols-1 lg:grid-cols-[160px_1fr_1fr_1fr_auto] gap-2 items-end">
                  <div>
                    <Label className="text-[10px] text-gray-600">Pedido</Label>
                    <Input
                      className="h-8 text-xs bg-white"
                      placeholder="#12345"
                      value={pedidoEnvioManual}
                      onChange={(e) => setPedidoEnvioManual(e.target.value.replace(/\D/g, ''))}
                    />
                  </div>

                  <div>
                    <Label className="text-[10px] text-gray-600">Enviar para caminhão</Label>
                    <Select value={caminhaoEnvioManual} onValueChange={setCaminhaoEnvioManual}>
                      <SelectTrigger className="h-8 text-xs bg-white">
                        <SelectValue placeholder="Selecione" />
                      </SelectTrigger>
                      <SelectContent>
                        {caminhoes.map((c) => (
                          <SelectItem key={c.id} value={String(c.id)}>
                            {c.nome || c.placa}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  <div>
                    <Label className="text-[10px] text-gray-600">Data</Label>
                    <Select value={dataEnvioManual} onValueChange={setDataEnvioManual}>
                      <SelectTrigger className="h-8 text-xs bg-white">
                        <SelectValue placeholder="Selecione" />
                      </SelectTrigger>
                      <SelectContent>
                        {diasDisponiveis.map((d) => (
                          <SelectItem key={d.id} value={d.id}>
                            {d.label} - {d.dataFormatada}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  <div>
                    <Label className="text-[10px] text-gray-600">Horário</Label>
                    <Select value={turnoEnvioManual} onValueChange={setTurnoEnvioManual}>
                      <SelectTrigger className="h-8 text-xs bg-white">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {TURNOS.map((turno) => (
                          <SelectItem key={turno.id} value={turno.id}>
                            {turno.label}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  <Button className="h-8 text-xs" onClick={enviarPedidoManual}>
                    Enviar para rota
                  </Button>
                </div>

                {buscaPedidoInfo && (
                  <div className={`mt-2 rounded-md border px-2 py-1.5 text-xs ${buscaPedidoInfo.localizadaEmCaminhao ? 'bg-emerald-50 border-emerald-200 text-emerald-800' : 'bg-amber-50 border-amber-200 text-amber-800'}`}>
                    {buscaPedidoInfo.localizadaEmCaminhao
                      ? `Pedido #${buscaPedidoInfo.entrega.numero_pedido} está no caminhão ${buscaPedidoInfo.caminhao?.nome || buscaPedidoInfo.caminhao?.placa}, turno ${buscaPedidoInfo.entrega.turno}, dia ${new Date(`${buscaPedidoInfo.dataAgendada}T12:00:00`).toLocaleDateString('pt-BR', { timeZone: 'UTC' })}.`
                      : `Pedido #${buscaPedidoInfo.entrega.numero_pedido} localizado, mas ainda não está alocado em caminhão/data.`}
                  </div>
                )}
              </div>

              <ScrollArea className="flex-1 min-h-[128px] w-full p-2 overflow-y-hidden">
                <div className="flex gap-2 pb-2 pl-1 h-full items-start">
                  {pendentesFiltrados.map(entrega => (
                    <div key={entrega.id} className="w-[248px] flex-shrink-0 h-full">
                      <EntregaCard
                        entrega={entrega}
                        venda={(vendas || []).find(v => v.id === entrega.venda_id)}
                        onClick={handleCardClick}
                        isColumn={false}
                      />
                    </div>
                  ))}


                  {assistenciasNaoAgendadas.map(at => (
                    <div key={`at-${at.id}`} className="w-[248px] flex-shrink-0 h-full">
                      <AssistenciaCard assistencia={at} isColumn={false} />
                    </div>
                  ))}

                  {pendentesFiltrados.length === 0 && assistenciasNaoAgendadas.length === 0 && !isOverTriagem && (
                    <div className="w-full flex flex-col items-center justify-center pt-1 text-gray-300 text-[10px]">
                      <p>Tudo organizado!</p>
                    </div>
                  )}
                </div>
                <ScrollBar orientation="horizontal" />
              </ScrollArea>
            </Card>

          </div>

          <Card className="border-0 shadow-sm bg-white/90">
            <div className="px-3 py-2 border-b flex items-center justify-between">
              <h3 className="font-bold text-sm text-gray-800">Agendados e Confirmados (Pendentes de Entrega)</h3>
              <Badge className="text-[10px] bg-emerald-600">{entregasConfirmadasNaoEntregues.length}</Badge>
            </div>
            <CardContent className="p-2">
              {entregasConfirmadasNaoEntregues.length === 0 ? (
                <p className="text-xs text-gray-400 px-1 py-2">Nenhum pedido confirmado pendente de entrega.</p>
              ) : (
                <div className="flex gap-2 overflow-x-auto pb-1">
                  {entregasConfirmadasNaoEntregues.map((e) => {
                    const cam = caminhoes.find((c) => String(c.id) === String(e.caminhao_id));
                    return (
                      <button
                        key={e.id}
                        onClick={() => {
                          const dataAgendada = e.data_agendada?.split('T')[0];
                          const idx = diasDisponiveis.findIndex((d) => d.id === dataAgendada);
                          if (idx >= 0) setDiaSelecionado(idx);
                          setSearchTriagem(String(e.numero_pedido || ''));
                        }}
                        className="min-w-[260px] text-left p-2 rounded-lg border border-emerald-200 bg-emerald-50 hover:bg-emerald-100 transition-colors"
                      >
                        <div className="flex items-center justify-between gap-2">
                          <span className="font-mono text-[11px] font-bold text-emerald-700">#{e.numero_pedido}</span>
                          <Badge className="text-[9px] bg-emerald-600">Confirmada</Badge>
                        </div>
                        <p className="text-xs font-semibold text-gray-700 truncate mt-1">{e.cliente_nome}</p>
                        <p className="text-[11px] text-gray-600 mt-1">
                          {cam ? (cam.nome || cam.placa) : 'Sem caminhão'} • {e.turno || '-'} • {e.data_agendada ? new Date(e.data_agendada).toLocaleDateString('pt-BR') : '-'}
                        </p>
                      </button>
                    );
                  })}
                </div>
              )}
            </CardContent>
          </Card>

          {/* --- ABAS DE DIAS --- */}
          <div className="flex items-center gap-2 bg-white rounded-xl p-2 shadow-sm">
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8"
              onClick={() => navigateSemana(-1)}
            >
              <ChevronLeft className="w-4 h-4" />
            </Button>

            <div
              key={weekNavAnimationKey}
              className={`flex-1 flex gap-1 overflow-x-auto ${weekNavDirection === -1
                ? 'animate-week-rotate-left'
                : weekNavDirection === 1
                  ? 'animate-week-rotate-right'
                  : ''}`}
            >
              {diasDisponiveis.map((dia, index) => (
                <DateTabVisual
                  key={dia.id}
                  dia={dia}
                  index={index}
                  isSelected={diaSelecionado === index}
                  onClick={() => setDiaSelecionado(index)}
                  activeEntrega={activeEntrega}
                  onHoverSwitch={setDiaSelecionado}
                />
              ))}
            </div>

            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8"
              onClick={() => navigateSemana(1)}
            >
              <ChevronRight className="w-4 h-4" />
            </Button>
          </div>

          {/* --- COLUNAS DE CAMINHÕES --- */}
          <div className="flex-1 min-h-0">
            <div className="h-full flex gap-3 overflow-x-auto pb-2">
              {diaSelecionado === null ? (
                <div className="flex-1 flex flex-col items-center justify-center text-gray-400">
                  <Calendar className="w-16 h-16 mb-4 opacity-30" />
                  <p className="font-medium text-lg">Selecione um dia</p>
                  <p className="text-sm">Clique em um dia acima para ver as entregas</p>
                </div>
              ) : caminhoesFiltradosPorBusca.length === 0 ? (
                <div className="flex-1 flex flex-col items-center justify-center text-gray-400">
                  <Truck className="w-12 h-12 mb-3 opacity-30" />
                  <p className="font-medium">Nenhum caminhão encontrado para o filtro atual</p>
                  <p className="text-sm">Verifique a busca pelo número do pedido</p>
                </div>
              ) : (
                caminhoesFiltradosPorBusca.map((caminhao, index) => (
                  <ColunaCaminhao
                    key={caminhao.id}
                    caminhao={caminhao}
                    cor={CORES_CAMINHOES[index % CORES_CAMINHOES.length]}
                    dataAtual={dataAtual}
                    entregas={entregas || []}
                    vendas={vendas || []}
                    onClickEntrega={handleCardClick}
                    onNotificar={handleNotificarCaminhao}
                    onOtimizar={(entregasDoCaminhao) => setModalOtimizacao(entregasDoCaminhao)}
                    assistencias={assistencias || []}
                    activeEntrega={activeEntrega}
                  />
                ))
              )}
            </div>
          </div>
        </div>

        <DragOverlay>
          {activeEntrega ? (
            <Card className="p-2 bg-white shadow-2xl opacity-90 border-2 border-blue-500 w-[180px] cursor-grabbing rotate-3 z-50">
              <div className="flex items-center justify-between gap-2 mb-1">
                <Badge variant="outline" className="text-[10px] bg-white">#{activeEntrega.numero_pedido}</Badge>
              </div>
              <p className="text-xs font-bold truncate">{activeEntrega.cliente_nome}</p>
            </Card>
          ) : null}
        </DragOverlay>
      </DndContext>

      {entregaSelecionada && (
        <ModalDetalhesEntrega
          entrega={entregaSelecionada}
          venda={(vendas || []).find(v => v.id === entregaSelecionada.venda_id)}
          onClose={() => setEntregaSelecionada(null)}
        />
      )}


      {/* Modal Disparo de Confirmações - Por Caminhão */}
      <Dialog open={!!modalDisparo} onOpenChange={() => setModalDisparo(null)}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-green-600">
              <CheckCircle className="w-5 h-5" />
              Confirmar Entregas - {modalDisparo?.caminhao?.nome || modalDisparo?.caminhao?.placa}
            </DialogTitle>
            <DialogDescription>
              {(modalDisparo?.totalNaoNotificadas || 0) > 0
                ? `Enviar mensagem de confirmação para ${modalDisparo.totalNaoNotificadas} cliente(s)?`
                : "Todos os clientes já foram solicitados para confirmação!"}
            </DialogDescription>
          </DialogHeader>
          <div className="py-4 space-y-3">
            {statusServidor === 'online'
              ? <div className="p-3 rounded bg-green-100 text-green-800 flex items-center gap-2"><Server className="w-5 h-5" /> <span>Automação Online!</span></div>
              : <div className="p-3 rounded bg-red-100 text-red-800 flex items-center gap-2"><WifiOff className="w-5 h-5" /> <span>Automação Offline</span></div>
            }

            {/* Resumo de Entregas */}
            {(modalDisparo?.entregasNaoNotificadas?.length || 0) > 0 && (
              <div className="text-sm space-y-2">
                <p className="font-medium text-blue-600 flex items-center gap-1">
                  <Truck className="w-4 h-4" /> Entregas ({modalDisparo.entregasNaoNotificadas.length})
                </p>
                {['Manhã', 'Tarde', 'Comercial'].map(turno => {
                  const doTurno = modalDisparo.entregasNaoNotificadas.filter(e => e.turno === turno);
                  if (doTurno.length === 0) return null;
                  const TurnoIcon = turno === 'Manhã' ? Sun : turno === 'Tarde' ? Sunset : Clock;
                  const iconColor = turno === 'Manhã' ? 'text-amber-500' : turno === 'Tarde' ? 'text-orange-500' : 'text-blue-500';
                  return (
                    <div key={turno} className="flex items-center gap-2 text-gray-700 ml-4">
                      <TurnoIcon className={`w-3.5 h-3.5 ${iconColor}`} />
                      <span className="text-xs">{turno}: <strong>{doTurno.length}</strong></span>
                    </div>
                  );
                })}
              </div>
            )}

            {/* Resumo de Assistências */}
            {(modalDisparo?.assistenciasNaoNotificadas?.length || 0) > 0 && (
              <div className="text-sm space-y-2">
                <p className="font-medium text-purple-600 flex items-center gap-1">
                  <Wrench className="w-4 h-4" /> Assistências ({modalDisparo.assistenciasNaoNotificadas.length})
                </p>
                {['Manhã', 'Tarde', 'Comercial'].map(turno => {
                  const doTurno = modalDisparo.assistenciasNaoNotificadas.filter(a => a.turno === turno);
                  if (doTurno.length === 0) return null;
                  const TurnoIcon = turno === 'Manhã' ? Sun : turno === 'Tarde' ? Sunset : Clock;
                  const iconColor = turno === 'Manhã' ? 'text-amber-500' : turno === 'Tarde' ? 'text-orange-500' : 'text-blue-500';
                  return (
                    <div key={turno} className="flex items-center gap-2 text-gray-700 ml-4">
                      <TurnoIcon className={`w-3.5 h-3.5 ${iconColor}`} />
                      <span className="text-xs">{turno}: <strong>{doTurno.length}</strong></span>
                    </div>
                  );
                })}
              </div>
            )}

            {(modalDisparo?.totalJaNotificadas || 0) > 0 && (
              <div className="flex items-center gap-2 text-green-700 text-sm">
                <CheckCircle className="w-4 h-4" />
                {modalDisparo.totalJaNotificadas} já notificados (serão ignorados)
              </div>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setModalDisparo(null)}>Cancelar</Button>
            <Button
              onClick={enviarConfirmacoes}
              disabled={statusServidor !== "online" || loadingDisparo || !(modalDisparo?.totalNaoNotificadas)}
              className="bg-green-600 hover:bg-green-700"
            >
              {loadingDisparo ? <Loader2 className="animate-spin" /> : `Encaminhar Confirmação (${modalDisparo?.totalNaoNotificadas || 0})`}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Modal de Otimização de Rota */}
      {modalOtimizacao && (
        <RouteOptimizer
          open={!!modalOtimizacao}
          onClose={() => setModalOtimizacao(null)}
          entregas={modalOtimizacao}
          onRotaAplicada={() => queryClient.invalidateQueries({ queryKey: ['entregas'] })}
        />
      )}

      {/* Modal Solicitar Reagendamento */}
      <Dialog open={!!modalReagendamento} onOpenChange={() => setModalReagendamento(null)}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-red-600">
              <Calendar className="w-5 h-5" />
              Solicitar Reagendamento
            </DialogTitle>
            <DialogDescription>
              Por que o cliente não pode receber nesta data?
            </DialogDescription>
          </DialogHeader>
          <div className="py-4">
            {modalReagendamento?.isMove && modalReagendamento?.novoAgendamento && (
              <div className="mb-3 rounded-md border border-amber-300 bg-amber-50 p-3 text-amber-900">
                <div className="flex items-start gap-2">
                  <AlertTriangle className="w-4 h-4 mt-0.5 flex-shrink-0" />
                  <div className="text-sm">
                    <p className="font-semibold">Ao confirmar, o cliente sera notificado imediatamente sobre o ajuste de entrega.</p>
                    <p className="mt-1">
                      Nova previsao: <strong>{new Date(`${modalReagendamento.novoAgendamento.data_agendada}T12:00:00`).toLocaleDateString('pt-BR', { timeZone: 'UTC' })}</strong> no turno <strong>{modalReagendamento.novoAgendamento.turno}</strong>.
                    </p>
                  </div>
                </div>
              </div>
            )}
            <Textarea
              placeholder="Ex: Cliente estará viajando, pediu para entregar próxima semana..."
              value={motivoReagendamento}
              onChange={(e) => setMotivoReagendamento(e.target.value)}
              rows={3}
            />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setModalReagendamento(null)}>Cancelar</Button>
            <div className="flex gap-2">
              <Button
                onClick={async () => {
                  if (!motivoReagendamento.trim()) return toast.error("Informe o motivo");
                  await atualizarEntregaMutation.mutateAsync({
                    id: modalReagendamento.entrega.id,
                    data: {
                      status: 'Aguardando Liberação',
                      observacoes: motivoReagendamento,
                      data_agendada: null,
                      turno: null,
                      caminhao_id: null,
                      ordem_rota: null
                    }
                  });
                  toast.success("Entrega movida para Aguardando Liberação");
                  setModalReagendamento(null);
                  setMotivoReagendamento("");
                  queryClient.invalidateQueries({ queryKey: ['entregas'] });
                }}
                className="bg-amber-600 hover:bg-amber-700 gap-1"
              >
                <Clock className="w-4 h-4" />
                Reservar (Aguardando)
              </Button>
              <Button onClick={confirmarReagendamento} className="bg-red-600 hover:bg-red-700">
                {modalReagendamento?.isMove ? 'Confirmar e Notificar Cliente' : 'Confirmar'}
              </Button>
            </div>
          </DialogFooter>
        </DialogContent>
      </Dialog>

    </>
  );
}

import React from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Truck, Clock, MapPin, User, Navigation, ExternalLink, AlertTriangle } from "lucide-react";

export default function MapaFrota({ caminhoes = [] }) {
    const formatarHora = (isoString) => {
        if (!isoString) return '-';
        const data = new Date(isoString);
        return data.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
    };

    const tempoDesdeAtualizacao = (isoString) => {
        if (!isoString) return 'Sem dados';
        const agora = new Date();
        const ultima = new Date(isoString);
        const diffMs = agora - ultima;
        const diffMin = Math.floor(diffMs / 60000);

        if (diffMin < 1) return 'Agora mesmo';
        if (diffMin < 60) return `Há ${diffMin} min`;
        return `Há ${Math.floor(diffMin / 60)}h`;
    };

    // 🔍 Detectar dados suspeitos: motorista atribuído mas sem GPS > 12h
    const temDadosSuspeitos = (caminhao) => {
        if (!caminhao.motorista_atual_nome) return false;
        if (!caminhao.ultima_atualizacao) return true; // Motorista sem última atualização é suspeito

        const agora = new Date();
        const ultima = new Date(caminhao.ultima_atualizacao);
        const LIMITE_ATIVO_MS = 12 * 60 * 60 * 1000; // 12 horas

        return (agora - ultima) > LIMITE_ATIVO_MS;
    };

    const agora = new Date();
    const LIMITE_ATIVO_MS = 12 * 60 * 60 * 1000; // 12 horas

    const caminhoesAtivosRecentemente = caminhoes.filter(c => {
        if (!c.ultima_atualizacao) return false;
        const ultima = new Date(c.ultima_atualizacao);
        return (agora - ultima) < LIMITE_ATIVO_MS;
    });

    const caminhoesEmTransito = caminhoesAtivosRecentemente.filter(c => c.status_rota === 'Em Trânsito');
    const caminhoesParados = caminhoes.filter(c => {
        const isEmTransito = c.status_rota === 'Em Trânsito';
        const isRecente = c.ultima_atualizacao && (agora - new Date(c.ultima_atualizacao)) < LIMITE_ATIVO_MS;
        return !isEmTransito || !isRecente;
    });

    const getMapsEmbedUrl = (lat, lng) => {
        return `https://maps.google.com/maps?q=${lat},${lng}&t=m&z=15&output=embed`;
    };

    return (
        <div className="space-y-4">
            {/* Cards de Resumo */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <Card className="border-0 shadow-sm">
                    <CardContent className="p-4">
                        <div className="flex items-center gap-3">
                            <div className="p-2 rounded-full bg-blue-100 text-blue-600">
                                <Truck className="w-5 h-5" />
                            </div>
                            <div>
                                <p className="text-2xl font-bold">{caminhoes.length}</p>
                                <p className="text-xs text-gray-500">Total Frota</p>
                            </div>
                        </div>
                    </CardContent>
                </Card>

                <Card className="border-0 shadow-sm">
                    <CardContent className="p-4">
                        <div className="flex items-center gap-3">
                            <div className="p-2 rounded-full bg-green-100 text-green-600">
                                <Navigation className="w-5 h-5" />
                            </div>
                            <div>
                                <p className="text-2xl font-bold">{caminhoesEmTransito.length}</p>
                                <p className="text-xs text-gray-500">Em Trânsito</p>
                            </div>
                        </div>
                    </CardContent>
                </Card>

                <Card className="border-0 shadow-sm">
                    <CardContent className="p-4">
                        <div className="flex items-center gap-3">
                            <div className="p-2 rounded-full bg-orange-100 text-orange-600">
                                <User className="w-5 h-5" />
                            </div>
                            <div>
                                <p className="text-2xl font-bold">{caminhoes.filter(c => c.motorista_atual_nome).length}</p>
                                <p className="text-xs text-gray-500">Motoristas Ativos</p>
                            </div>
                        </div>
                    </CardContent>
                </Card>

                <Card className="border-0 shadow-sm">
                    <CardContent className="p-4">
                        <div className="flex items-center gap-3">
                            <div className="p-2 rounded-full bg-gray-100 text-gray-600">
                                <Clock className="w-5 h-5" />
                            </div>
                            <div>
                                <p className="text-2xl font-bold">{caminhoesParados.length}</p>
                                <p className="text-xs text-gray-500">Parados</p>
                            </div>
                        </div>
                    </CardContent>
                </Card>
            </div>

            {/* Caminhões em Trânsito com Mini Mapa */}
            {caminhoesEmTransito.length > 0 && (
                <Card className="border-0 shadow-sm">
                    <CardHeader className="pb-2">
                        <CardTitle className="text-sm flex items-center gap-2 text-green-700">
                            <Navigation className="w-4 h-4" />
                            Em Trânsito Agora - Localização em Tempo Real
                        </CardTitle>
                    </CardHeader>
                    <CardContent>
                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                            {caminhoesEmTransito.map(caminhao => (
                                <div
                                    key={caminhao.id}
                                    className="rounded-xl bg-gradient-to-r from-green-50 to-emerald-50 border border-green-200 overflow-hidden"
                                >
                                    {/* Header do Caminhão */}
                                    <div className="p-4 border-b border-green-200">
                                        <div className="flex items-center justify-between mb-2">
                                            <div className="flex items-center gap-2">
                                                <span className="w-3 h-3 bg-green-500 rounded-full animate-pulse" />
                                                <span className="font-bold text-lg">🚚 {caminhao.placa || caminhao.nome}</span>
                                            </div>
                                            <Badge className="bg-green-600">{caminhao.turno_atual || 'Comercial'}</Badge>
                                        </div>

                                        <div className="flex items-center justify-between text-sm">
                                            <div className="flex items-center gap-2 text-gray-600">
                                                <User className="w-4 h-4" />
                                                <span className="font-medium">{caminhao.motorista_atual_nome || 'Motorista'}</span>
                                            </div>
                                            <span className="text-xs text-gray-400">
                                                Atualizado {tempoDesdeAtualizacao(caminhao.ultima_atualizacao)}
                                            </span>
                                        </div>
                                    </div>

                                    {/* Mini Mapa */}
                                    {caminhao.latitude && caminhao.longitude ? (
                                        <div className="relative">
                                            <iframe
                                                src={getMapsEmbedUrl(caminhao.latitude, caminhao.longitude)}
                                                width="100%"
                                                height="180"
                                                style={{ border: 0 }}
                                                allowFullScreen=""
                                                loading="lazy"
                                                referrerPolicy="no-referrer-when-downgrade"
                                                className="w-full"
                                            />
                                            <a
                                                href={`https://www.google.com/maps?q=${caminhao.latitude},${caminhao.longitude}`}
                                                target="_blank"
                                                rel="noopener noreferrer"
                                                className="absolute bottom-2 right-2 flex items-center gap-1 bg-white/90 text-blue-600 text-xs px-2 py-1 rounded-full shadow hover:bg-white"
                                            >
                                                <ExternalLink className="w-3 h-3" />
                                                Abrir mapa
                                            </a>
                                        </div>
                                    ) : (
                                        <div className="h-[180px] flex items-center justify-center bg-gray-100 text-gray-400 text-sm">
                                            <MapPin className="w-5 h-5 mr-2" />
                                            Aguardando localização GPS...
                                        </div>
                                    )}
                                </div>
                            ))}
                        </div>
                    </CardContent>
                </Card>
            )}

            {/* Lista Completa da Frota */}
            <Card className="border-0 shadow-sm">
                <CardHeader className="pb-2">
                    <CardTitle className="text-sm flex items-center gap-2">
                        <Truck className="w-4 h-4" />
                        Todos os Caminhões
                    </CardTitle>
                </CardHeader>
                <CardContent>
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                        {caminhoes.map(caminhao => {
                            const emTransito = caminhao.status_rota === 'Em Trânsito';
                            const temLocalizacao = caminhao.latitude && caminhao.longitude;
                            const suspeito = temDadosSuspeitos(caminhao);

                            return (
                                <div
                                    key={caminhao.id}
                                    className={`rounded-xl border overflow-hidden ${suspeito
                                        ? 'bg-red-50 border-red-300 border-2'
                                        : emTransito
                                            ? 'bg-green-50 border-green-200'
                                            : 'bg-gray-50 border-gray-200'
                                    }`}
                                >
                                    {/* ⚠️ Aviso de dados suspeitos */}
                                    {suspeito && (
                                        <div className="bg-red-100 border-b border-red-300 px-3 py-2 flex items-center gap-2">
                                            <AlertTriangle className="w-4 h-4 text-red-600" />
                                            <span className="text-xs font-semibold text-red-700">
                                                Possível dados inconsistentes
                                            </span>
                                        </div>
                                    )}

                                    <div className="p-3">
                                        <div className="flex items-center justify-between mb-2">
                                            <div className="flex items-center gap-2">
                                                <div className={`w-3 h-3 rounded-full ${suspeito
                                                    ? 'bg-red-500 animate-pulse'
                                                    : emTransito
                                                        ? 'bg-green-500 animate-pulse'
                                                        : 'bg-gray-400'
                                                    }`} />
                                                <span className="font-bold">🚚 {caminhao.placa || caminhao.nome}</span>
                                            </div>
                                            <Badge variant={suspeito ? 'destructive' : emTransito ? 'default' : 'secondary'} className="text-xs">
                                                {suspeito ? '⚠️ Verificar' : (caminhao.status_rota || 'Parado')}
                                            </Badge>
                                        </div>

                                        <p className="text-xs text-gray-500 mb-2">
                                            {caminhao.modelo || 'Caminhão'}
                                            {caminhao.motorista_atual_nome && (
                                                <>
                                                    <br />
                                                    <span className={suspeito ? 'text-red-600 font-semibold' : ''}>
                                                        Motorista: {caminhao.motorista_atual_nome}
                                                    </span>
                                                </>
                                            )}
                                            {caminhao.ultima_atualizacao && (
                                                <>
                                                    <br />
                                                    <span className={suspeito ? 'text-red-600 font-semibold' : 'text-gray-400'}>
                                                        Último GPS: {tempoDesdeAtualizacao(caminhao.ultima_atualizacao)}
                                                    </span>
                                                </>
                                            )}
                                        </p>

                                        {temLocalizacao && (
                                            <a
                                                href={`https://www.google.com/maps?q=${caminhao.latitude},${caminhao.longitude}`}
                                                target="_blank"
                                                rel="noopener noreferrer"
                                                className="flex items-center gap-1 text-xs text-blue-600 hover:underline"
                                            >
                                                <MapPin className="w-3 h-3" />
                                                Ver localização
                                            </a>
                                        )}
                                    </div>

                                    {/* Mini mapa para caminhões parados com localização */}
                                    {!emTransito && temLocalizacao && (
                                        <div className="border-t border-gray-200">
                                            <iframe
                                                src={getMapsEmbedUrl(caminhao.latitude, caminhao.longitude)}
                                                width="100%"
                                                height="100"
                                                style={{ border: 0 }}
                                                loading="lazy"
                                                className="w-full"
                                            />
                                        </div>
                                    )}
                                </div>
                            );
                        })}

                        {caminhoes.length === 0 && (
                            <div className="col-span-full text-center py-8 text-gray-400">
                                <Truck className="w-12 h-12 mx-auto mb-2 opacity-20" />
                                <p>Nenhum caminhão cadastrado</p>
                                <p className="text-xs mt-1">Execute o SQL para criar a tabela de caminhões</p>
                            </div>
                        )}
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { base44 } from "@/lib/supabase";
import { formatarCEP, formatarEndereco } from "@/utils/formatters";
import { Package, MapPin, User, Phone, Wrench, Save, RefreshCw, Ban, Clock, Search, Loader2 } from "lucide-react";
import { toast } from "sonner";

const getEntregaAddressState = (entrega = {}) => ({
  cep: entrega.endereco_entrega_cep || "",
  rua: entrega.endereco_entrega_rua || "",
  numero: entrega.endereco_entrega_numero || "",
  complemento: entrega.endereco_entrega_complemento || "",
  ponto_referencia: entrega.endereco_entrega_ponto_referencia || "",
  bairro: entrega.endereco_entrega_bairro || "",
  cidade: entrega.endereco_entrega_cidade || "",
  estado: entrega.endereco_entrega_estado || "",
});

const getClienteDeliveryAddressState = (cliente = {}) => {
  const usarMesmoEndereco = cliente.usar_mesmo_endereco !== false;

  if (usarMesmoEndereco) {
    return {
      cep: cliente.cep || "",
      rua: cliente.endereco || "",
      numero: cliente.numero || "",
      complemento: cliente.complemento || "",
      ponto_referencia: cliente.ponto_referencia || "",
      bairro: cliente.bairro || "",
      cidade: cliente.cidade || "",
      estado: cliente.estado || "",
    };
  }

  return {
    cep: cliente.endereco_entrega_cep || "",
    rua: cliente.endereco_entrega_rua || "",
    numero: cliente.endereco_entrega_numero || "",
    complemento: cliente.endereco_entrega_complemento || "",
    ponto_referencia: cliente.endereco_entrega_ponto_referencia || "",
    bairro: cliente.endereco_entrega_bairro || "",
    cidade: cliente.endereco_entrega_cidade || "",
    estado: cliente.endereco_entrega_estado || "",
  };
};

const buildEnderecoEntregaText = (endereco = {}) => {
  if (!endereco.rua) return "";

  let enderecoTexto = `${endereco.rua}, ${endereco.numero || "s/n"}`;

  if (endereco.complemento) enderecoTexto += ` - ${endereco.complemento}`;
  if (endereco.bairro) enderecoTexto += ` - ${endereco.bairro}`;
  if (endereco.cidade) enderecoTexto += `, ${endereco.cidade}`;
  if (endereco.estado) enderecoTexto += `/${endereco.estado}`;
  if (endereco.ponto_referencia) enderecoTexto += ` (Ref: ${endereco.ponto_referencia})`;

  return enderecoTexto;
};

const hasStructuredAddressData = (endereco = {}) =>
  Object.values(endereco).some((value) => Boolean(String(value || "").trim()));

const normalizeEmptyValue = (value) => {
  if (value === null || value === undefined) return null;
  const normalized = String(value).trim();
  return normalized ? normalized : null;
};

export default function ModalDetalhesEntrega({ entrega, venda, onClose }) {
  const queryClient = useQueryClient();
  const [itensMontagem, setItensMontagem] = useState(
    entrega.itens_montagem_interna || []
  );
  const [enderecoEntrega, setEnderecoEntrega] = useState(() => getEntregaAddressState(entrega));
  const [isSyncing, setIsSyncing] = useState(false);
  const [isSearchingCep, setIsSearchingCep] = useState(false);

  useEffect(() => {
    setEnderecoEntrega(getEntregaAddressState(entrega));
  }, [entrega]);

  const enderecoPreview = buildEnderecoEntregaText(enderecoEntrega) || entrega.endereco_entrega || "";
  const isLegacyAddressOnly = !hasStructuredAddressData(enderecoEntrega) && Boolean(entrega.endereco_entrega);

  const atualizarEntregaMutation = useMutation({
    mutationFn: ({ id, data }) => base44.entities.Entrega.update(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['entregas'] });
      toast.success("Entrega atualizada com sucesso!");
      onClose();
    },
    onError: (err) => {
      console.error("Erro ao atualizar entrega:", err);
      toast.error("Erro ao salvar entrega");
    }
  });

  const fetchWithTimeout = async (resource, options = {}) => {
    const { timeout = 5000 } = options;
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeout);

    try {
      return await fetch(resource, {
        ...options,
        signal: controller.signal,
      });
    } finally {
      clearTimeout(timeoutId);
    }
  };

  const updateEnderecoField = (field, value) => {
    setEnderecoEntrega((prev) => ({ ...prev, [field]: value }));
  };

  const buscarCEP = async (cep) => {
    const cepLimpo = String(cep || "").replace(/\D/g, "");
    if (cepLimpo.length !== 8) return;

    setIsSearchingCep(true);

    const aplicarResultado = (dados) => {
      setEnderecoEntrega((prev) => ({
        ...prev,
        cep: formatarCEP(cepLimpo),
        rua: formatarEndereco(dados.logradouro || dados.street || ""),
        bairro: formatarEndereco(dados.bairro || dados.neighborhood || ""),
        cidade: formatarEndereco(dados.localidade || dados.city || ""),
        estado: (dados.uf || dados.state || "").toUpperCase(),
      }));
    };

    try {
      const responseViaCep = await fetchWithTimeout(`https://viacep.com.br/ws/${cepLimpo}/json/`, { timeout: 3000 });
      if (!responseViaCep.ok) throw new Error("ViaCEP indisponível");

      const dataViaCep = await responseViaCep.json();
      if (dataViaCep.erro) throw new Error("CEP não encontrado");

      aplicarResultado(dataViaCep);
    } catch (errorViaCep) {
      try {
        const responseBrasilApi = await fetchWithTimeout(`https://brasilapi.com.br/api/cep/v1/${cepLimpo}`, { timeout: 3000 });
        if (!responseBrasilApi.ok) throw new Error("BrasilAPI indisponível");

        const dataBrasilApi = await responseBrasilApi.json();
        aplicarResultado(dataBrasilApi);
      } catch (errorBrasilApi) {
        console.error("Erro ao buscar CEP da entrega:", errorBrasilApi);
        toast.error("Não foi possível localizar o CEP informado.");
      }
    } finally {
      setIsSearchingCep(false);
    }
  };

  const toggleItemMontagem = (itemNome) => {
    const itemExiste = (itensMontagem || []).find(i => i.produto_nome === itemNome);

    if (itemExiste) {
      setItensMontagem((itensMontagem || []).filter(i => i.produto_nome !== itemNome));
    } else {
      const itemVenda = venda?.itens?.find(i => i.produto_nome === itemNome);
      if (itemVenda) {
        setItensMontagem([...(itensMontagem || []), {
          produto_nome: itemNome,
          quantidade: itemVenda.quantidade,
          montado: false
        }]);
      }
    }
  };

  const buscarEnderecoCliente = async () => {
    setIsSyncing(true);
    try {
      let cliente = null;
      const clientes = await base44.entities.Cliente.list();

      // Tentativa 1: Pelo ID do cliente na venda
      if (venda && venda.cliente_id) {
        try {
          cliente = clientes.find(c => String(c.id) === String(venda.cliente_id));
        } catch (e) { console.warn("Erro ao buscar cliente por ID", e); }
      }

      // Tentativa 2: Pelo Nome (caso venda_id falhe ou não exista)
      if (!cliente && entrega.cliente_nome) {
        cliente = clientes.find(c => c.nome_completo === entrega.cliente_nome);
      }

      if (cliente) {
        const enderecoCliente = getClienteDeliveryAddressState(cliente);
        if (enderecoCliente.rua) {
          setEnderecoEntrega(enderecoCliente);
          toast.success("Endereço atualizado do cadastro do cliente!");
        } else {
          toast.warning("Cliente encontrado, mas endereço está incompleto.");
        }
      } else {
        toast.error("Cliente não encontrado para sincronizar.");
      }

    } catch (error) {
      console.error("Erro ao buscar cliente:", error);
      toast.error("Erro ao buscar endereço do cliente.");
    } finally {
      setIsSyncing(false);
    }
  };

  const salvarMontagem = async () => {
    const enderecoFormatado = buildEnderecoEntregaText(enderecoEntrega) || entrega.endereco_entrega || null;

    await atualizarEntregaMutation.mutateAsync({
      id: entrega.id,
      data: {
        itens_montagem_interna: itensMontagem,
        montagem_concluida: false,
        endereco_entrega: enderecoFormatado,
        endereco_entrega_cep: normalizeEmptyValue(enderecoEntrega.cep),
        endereco_entrega_rua: normalizeEmptyValue(enderecoEntrega.rua),
        endereco_entrega_numero: normalizeEmptyValue(enderecoEntrega.numero),
        endereco_entrega_complemento: normalizeEmptyValue(enderecoEntrega.complemento),
        endereco_entrega_ponto_referencia: normalizeEmptyValue(enderecoEntrega.ponto_referencia),
        endereco_entrega_bairro: normalizeEmptyValue(enderecoEntrega.bairro),
        endereco_entrega_cidade: normalizeEmptyValue(enderecoEntrega.cidade),
        endereco_entrega_estado: normalizeEmptyValue(enderecoEntrega.estado),
      }
    });
  };

  return (
    <Dialog open={true} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Package className="w-5 h-5 text-green-600" />
            Detalhes da Entrega #{entrega.numero_pedido}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          {/* Cliente */}
          <div className="bg-gray-50 dark:bg-neutral-800 p-3 rounded-lg">
            <div className="flex items-center gap-2 mb-2">
              <User className="w-4 h-4 text-gray-500" />
              <span className="font-semibold">{entrega.cliente_nome}</span>
            </div>
            <div className="flex items-center gap-2 text-sm text-gray-600">
              <Phone className="w-4 h-4" />
              <span>{entrega.cliente_telefone}</span>
            </div>
          </div>

          {/* Endereço Editável */}
          <div className="bg-blue-50 dark:bg-blue-900/20 p-3 rounded-lg space-y-2">
            <div className="flex items-center justify-between mb-1">
              <div className="flex items-center gap-2 text-blue-700 dark:text-blue-400 font-medium">
                <MapPin className="w-4 h-4" />
                <Label htmlFor="endereco_entrega_cep">Endereço de Entrega</Label>
              </div>
              <Button
                variant="ghost"
                size="sm"
                className="h-8 text-blue-600 hover:text-blue-800 hover:bg-blue-100 dark:hover:bg-blue-900/40"
                onClick={buscarEnderecoCliente}
                disabled={isSyncing}
              >
                <RefreshCw className={`w-3 h-3 mr-1 ${isSyncing ? 'animate-spin' : ''}`} />
                Sincronizar com Cliente
              </Button>
            </div>

            <div className="grid md:grid-cols-3 gap-3">
              <div>
                <Label htmlFor="endereco_entrega_cep">CEP</Label>
                <div className="flex gap-2 mt-1">
                  <Input
                    id="endereco_entrega_cep"
                    value={enderecoEntrega.cep}
                    onChange={(e) => updateEnderecoField("cep", formatarCEP(e.target.value))}
                    onBlur={() => buscarCEP(enderecoEntrega.cep)}
                    className="bg-white dark:bg-neutral-900 border-blue-200 dark:border-blue-800/50"
                    placeholder="00000-000"
                  />
                  <Button
                    type="button"
                    variant="outline"
                    size="icon"
                    onClick={() => buscarCEP(enderecoEntrega.cep)}
                    disabled={isSearchingCep}
                    className="border-blue-200 dark:border-blue-800/50"
                  >
                    {isSearchingCep ? <Loader2 className="w-4 h-4 animate-spin" /> : <Search className="w-4 h-4" />}
                  </Button>
                </div>
              </div>

              <div className="md:col-span-2">
                <Label htmlFor="endereco_entrega_rua">Rua / Logradouro</Label>
                <Input
                  id="endereco_entrega_rua"
                  value={enderecoEntrega.rua}
                  onChange={(e) => updateEnderecoField("rua", formatarEndereco(e.target.value))}
                  className="bg-white dark:bg-neutral-900 border-blue-200 dark:border-blue-800/50 mt-1"
                  placeholder="Rua, avenida, travessa..."
                />
              </div>
            </div>

            <div className="grid md:grid-cols-4 gap-3">
              <div>
                <Label htmlFor="endereco_entrega_numero">Número</Label>
                <Input
                  id="endereco_entrega_numero"
                  value={enderecoEntrega.numero}
                  onChange={(e) => updateEnderecoField("numero", e.target.value)}
                  className="bg-white dark:bg-neutral-900 border-blue-200 dark:border-blue-800/50 mt-1"
                  placeholder="123"
                />
              </div>

              <div className="md:col-span-3">
                <Label htmlFor="endereco_entrega_complemento">Complemento</Label>
                <Input
                  id="endereco_entrega_complemento"
                  value={enderecoEntrega.complemento}
                  onChange={(e) => updateEnderecoField("complemento", e.target.value)}
                  className="bg-white dark:bg-neutral-900 border-blue-200 dark:border-blue-800/50 mt-1"
                  placeholder="Casa 06, bloco A, apto 101..."
                />
              </div>
            </div>

            <div>
              <Label htmlFor="endereco_entrega_ponto_referencia">Referência</Label>
              <Input
                id="endereco_entrega_ponto_referencia"
                value={enderecoEntrega.ponto_referencia}
                onChange={(e) => updateEnderecoField("ponto_referencia", e.target.value)}
                className="bg-white dark:bg-neutral-900 border-blue-200 dark:border-blue-800/50 mt-1"
                placeholder="Próximo ao mercado, portão de grade vinho..."
              />
            </div>

            <div className="grid md:grid-cols-3 gap-3">
              <div>
                <Label htmlFor="endereco_entrega_bairro">Bairro</Label>
                <Input
                  id="endereco_entrega_bairro"
                  value={enderecoEntrega.bairro}
                  onChange={(e) => updateEnderecoField("bairro", formatarEndereco(e.target.value))}
                  className="bg-white dark:bg-neutral-900 border-blue-200 dark:border-blue-800/50 mt-1"
                />
              </div>

              <div>
                <Label htmlFor="endereco_entrega_cidade">Cidade</Label>
                <Input
                  id="endereco_entrega_cidade"
                  value={enderecoEntrega.cidade}
                  onChange={(e) => updateEnderecoField("cidade", formatarEndereco(e.target.value))}
                  className="bg-white dark:bg-neutral-900 border-blue-200 dark:border-blue-800/50 mt-1"
                />
              </div>

              <div>
                <Label htmlFor="endereco_entrega_estado">UF</Label>
                <Input
                  id="endereco_entrega_estado"
                  value={enderecoEntrega.estado}
                  onChange={(e) => updateEnderecoField("estado", e.target.value.toUpperCase().slice(0, 2))}
                  className="bg-white dark:bg-neutral-900 border-blue-200 dark:border-blue-800/50 mt-1"
                  maxLength={2}
                  placeholder="RJ"
                />
              </div>
            </div>

            {enderecoPreview && (
              <div className="rounded-md border border-blue-200 dark:border-blue-800/50 bg-white/80 dark:bg-neutral-950/40 p-2">
                <p className="text-sm text-gray-700 dark:text-gray-300">{enderecoPreview}</p>
                {isLegacyAddressOnly && (
                  <p className="text-xs text-amber-600 mt-1">
                    Endereço atual salvo no formato antigo. Ao salvar, ele passa a usar os campos separados.
                  </p>
                )}
              </div>
            )}
          </div>

          {/* Itens da Venda */}
          <div>
            <div className="flex items-center gap-2 mb-3">
              <Wrench className="w-5 h-5 text-orange-600" />
              <h3 className="font-bold">Selecionar Itens para Montagem Interna</h3>
            </div>
            <div className="space-y-2">
              {(venda?.itens || []).map((item, index) => {
                const selecionado = (itensMontagem || []).some(i => i.produto_nome === item.produto_nome);
                return (
                  <div
                    key={index}
                    className={`flex items-center gap-3 p-3 rounded-lg border-2 transition-all cursor-pointer ${selecionado
                      ? 'border-orange-400 bg-orange-50 dark:bg-orange-900/20'
                      : 'border-gray-200 dark:border-neutral-700 hover:border-gray-300'
                      }`}
                    onClick={() => toggleItemMontagem(item.produto_nome)}
                  >
                    <Checkbox
                      checked={selecionado}
                      onCheckedChange={() => toggleItemMontagem(item.produto_nome)}
                    />
                    <div className="flex-1">
                      <p className="font-medium text-sm">{item.produto_nome}</p>
                      <p className="text-xs text-gray-500">Qtd: {item.quantidade}</p>
                    </div>
                    {selecionado && (
                      <Badge className="bg-orange-500 text-white">
                        Para Montar
                      </Badge>
                    )}
                  </div>
                );
              })}
            </div>
          </div>

          {/* Resumo */}
          {itensMontagem.length > 0 && (
            <div className="bg-orange-100 dark:bg-orange-900/30 p-3 rounded-lg">
              <p className="text-sm text-orange-800 dark:text-orange-400 font-medium">
                ⚠️ {itensMontagem.length} {itensMontagem.length === 1 ? 'item será enviado' : 'itens serão enviados'} para os montadores internos
              </p>
            </div>
          )}



          {/* Histórico de Reagendamentos / Tentativas */}
          {(entrega.historico_reagendamentos?.length > 0 || entrega.motivo_restricao) && (
            <div className="bg-red-50 dark:bg-red-900/20 p-3 rounded-lg border border-red-100 dark:border-red-800/50">
              <div className="flex items-center gap-2 mb-2 text-red-700 dark:text-red-400 font-medium">
                <Package className="w-4 h-4" /> {/* Or History icon */}
                <h3>Histórico de Tentativas</h3>
              </div>

              {/* Alerta de Restrição Atual (Específica + Preferências) */}
              {(entrega.motivo_restricao || entrega.data_restricao || entrega.preferencias_entrega?.dias?.length > 0 || entrega.preferencias_entrega?.turnos?.length > 0) && (
                <div className="mb-3 p-2 bg-white dark:bg-neutral-900 rounded border border-red-200 dark:border-red-800 text-sm">
                  <div className="flex justify-between items-start mb-2">
                    <h4 className="font-bold text-red-600 flex items-center gap-1">
                      <Ban className="w-3.5 h-3.5" /> Restrições Ativas
                    </h4>
                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-6 px-2 text-red-500 hover:text-red-700 hover:bg-red-50"
                      onClick={async () => {
                        if (confirm("Isso removerá TODAS as restrições (Data específica e Preferências) desta entrega. Confirmar?")) {
                          await atualizarEntregaMutation.mutateAsync({
                            id: entrega.id,
                            data: {
                              motivo_restricao: null,
                              data_restricao: null,
                              preferencias_entrega: { dias: [], turnos: [], obs: entrega.preferencias_entrega?.obs || "" }
                            }
                          });
                          toast.success("Todas as restrições foram removidas!");
                        }
                      }}
                    >
                      Limpar Tudo
                    </Button>
                  </div>

                  <div className="space-y-1 pl-1">
                    {entrega.data_restricao && (
                      <div className="text-gray-700">
                        <span className="font-semibold">Data Bloqueada:</span> {new Date(entrega.data_restricao).toLocaleDateString('pt-BR', { timeZone: 'UTC' })}
                        {entrega.motivo_restricao && <span className="text-gray-500 italic"> - {entrega.motivo_restricao}</span>}
                      </div>
                    )}

                    {entrega.preferencias_entrega?.dias?.length > 0 && (
                      <div className="text-gray-700">
                        <span className="font-semibold">Dias Permitidos (Cliente):</span> {' '}
                        {entrega.preferencias_entrega.dias.map(d => ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'][Number(d)]).join(', ')}
                      </div>
                    )}

                    {entrega.preferencias_entrega?.turnos?.length > 0 && (
                      <div className="text-gray-700">
                        <span className="font-semibold">Turnos Permitidos:</span> {entrega.preferencias_entrega.turnos.join(', ')}
                      </div>
                    )}
                  </div>
                </div>
              )}

              {/* Lista de Histórico */}
              <div className="space-y-2 max-h-40 overflow-y-auto pr-1">
                {entrega.historico_reagendamentos?.map((hist, idx) => (
                  <div key={idx} className="text-sm bg-white dark:bg-neutral-900 p-2 rounded shadow-sm flex flex-col gap-1">
                    <div className="flex justify-between items-center border-b border-gray-100 pb-1 mb-1">
                      <span className="font-bold text-gray-700 dark:text-gray-200">
                        {hist.data ? format(new Date(hist.data), "dd/MM/yyyy", { locale: ptBR }) : 'Data N/D'}
                      </span>
                      <span className="text-xs text-gray-400 truncate max-w-[100px]" title={hist.usuario}>
                        {hist.usuario?.split('@')[0] || 'Sistema'}
                      </span>
                    </div>
                    <p className="text-gray-600 dark:text-gray-400 text-xs italic">
                      &quot;{hist.motivo || 'Sem motivo registrado'}&quot;
                    </p>
                  </div>
                ))}
                {(!entrega.historico_reagendamentos || entrega.historico_reagendamentos.length === 0) && !entrega.motivo_restricao && (
                  <p className="text-xs text-gray-500">Nenhum histórico registrado.</p>
                )}
              </div>
            </div>
          )}

          {/* Ações */}
          <div className="flex gap-2 justify-between pt-4 border-t">
            <Button
              variant="outline"
              className="text-amber-600 border-amber-200 hover:bg-amber-50 gap-2 font-bold"
              onClick={async () => {
                const motivo = prompt("Qual o motivo para aguardar liberação?");
                if (!motivo) return;

                await atualizarEntregaMutation.mutateAsync({
                  id: entrega.id,
                  data: {
                    status: 'Aguardando Liberação',
                    observacoes: motivo,
                    data_agendada: null,
                    turno: null,
                    caminhao_id: null,
                    ordem_rota: null
                  }
                });
                toast.success("Entrega movida para Aguardando Liberação");
                onClose();
              }}
              disabled={atualizarEntregaMutation.isPending}
            >
              <Clock className="w-4 h-4" />
              Mover para Aguardando
            </Button>

            <div className="flex gap-2">
              <Button variant="outline" onClick={onClose}>
                Cancelar
              </Button>
              <Button
                onClick={salvarMontagem}
                className="bg-green-600 hover:bg-green-700 gap-2"
                disabled={atualizarEntregaMutation.isPending}
              >
                <Save className="w-4 h-4" />
                {atualizarEntregaMutation.isPending ? "Salvando..." : "Salvar"}
              </Button>
            </div>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import React from "react";
import { base44 } from "@/api/base44Client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Checkbox } from "@/components/ui/checkbox";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import {
  CheckCircle, Clock, Package, User, Calendar,

  ChevronLeft, ChevronRight, Truck, PartyPopper, ArrowDown, AlertTriangle,
  UserCheck, Users, CheckSquare, Loader2, RotateCcw, MoreVertical, ArrowRightLeft, Info, LogOut
} from "lucide-react";
import { toast } from "sonner";
import { whatsappService } from "@/services/whatsappService";
import { useAuth } from "@/hooks/useAuth";
import { useTenant } from "@/contexts/TenantContext";
import { supabase } from "@/lib/supabase";
import AssistenciaTecnicaModal from "@/components/assistencia/AssistenciaTecnicaModal";

export default function MontagemInterna() {
  const queryClient = useQueryClient();
  const { user, logout } = useAuth();
  const { brandName, brandLogo } = useTenant();
  const [semanaOffset, setSemanaOffset] = React.useState(0);
  const [itemRecemConcluido, setItemRecemConcluido] = React.useState(null);

  // Determinar papel do usuário logado
  const cargoNormalizado = String(user?.cargo || '').trim().toLowerCase();
  const isAdmin =
    user?.role === 'admin' ||
    ['administrador', 'admin', 'adm'].includes(cargoNormalizado) ||
    cargoNormalizado.includes('master');
  const isMontador = user?.cargo === 'Montador';

  // Estados para modal de atribuição (apenas Admin usa)
  const [montagemSelecionada, setMontagemSelecionada] = React.useState(null);
  const [modalAtribuirOpen, setModalAtribuirOpen] = React.useState(false);
  const [montadorSelecionado, setMontadorSelecionado] = React.useState('');
  const [modalDetalhesOpen, setModalDetalhesOpen] = React.useState(false);
  const [montagemDetalhes, setMontagemDetalhes] = React.useState(null);
  const [assistenciaModalOpen, setAssistenciaModalOpen] = React.useState(false);
  const [montagemParaAssistencia, setMontagemParaAssistencia] = React.useState(null);
  const [salvandoAssistencia, setSalvandoAssistencia] = React.useState(false);
  const [selectedMontagemIds, setSelectedMontagemIds] = React.useState([]);
  const [modalAtribuirLoteOpen, setModalAtribuirLoteOpen] = React.useState(false);
  const [montadorLoteId, setMontadorLoteId] = React.useState('');
  const [mostrarConcluidas, setMostrarConcluidas] = React.useState(false);

  // Estados para PIN
  const [pinDialogOpen, setPinDialogOpen] = React.useState(false);
  const [pinCallback, setPinCallback] = React.useState(null);
  const [pinInput, setPinInput] = React.useState('');

  // Calcular início e fim da semana (Segunda a Domingo)
  const getWeekRange = (offset = 0) => {
    const hoje = new Date();
    const diaNum = hoje.getDay(); // 0 (Dom) a 6 (Sáb)

    // Tratamento para Domingo (0): se hoje é domingo, queremos a semana que TERMINA hoje.
    // getDay() retorna 0 para domingo. Queremos recuar 6 dias para chegar na segunda.
    // Se não for domingo, recuamos (diaNum - 1) dias.
    const diffParaSegunda = diaNum === 0 ? 6 : diaNum - 1;

    const inicioSemana = new Date(hoje);
    inicioSemana.setDate(hoje.getDate() - diffParaSegunda + (offset * 7));
    inicioSemana.setHours(0, 0, 0, 0);

    const fimSemana = new Date(inicioSemana);
    fimSemana.setDate(inicioSemana.getDate() + 6); // Termina no Domingo
    fimSemana.setHours(23, 59, 59, 999);

    return { inicio: inicioSemana, fim: fimSemana };
  };

  const { inicio, fim } = getWeekRange(semanaOffset);

  // Buscar todas as montagens internas
  const { data: todasMontagens = [], isLoading } = useQuery({
    queryKey: ['montagens-internas-todas'],
    queryFn: async () => {
      const todas = await base44.entities.MontagemItem.list('-created_at');
      return todas.filter(m => m.tipo_montagem === 'interna');
    },
    refetchInterval: 3000 // Atualiza a cada 3 segundos
  });

  // Buscar montadores internos (apenas cargo Montador)
  const { data: montadoresInternos = [] } = useQuery({
    queryKey: ['montadores-internos'],
    queryFn: async () => {
      const todos = await base44.entities.User.list();
      return todos
        .filter(m =>
          m.cargo === 'Montador' &&
          m.ativo !== false
        )
        .map(m => ({
          id: m.id,
          nome: m.full_name || m.email,
          nome_completo: m.full_name,
          pin_montagem: m.pin_montagem
        }));
    }
  });

  // Separar pendentes e concluídas
  const montagensInternas = React.useMemo(
    () => todasMontagens.filter(m => m.status !== 'concluida'),
    [todasMontagens]
  );
  const montagensConcluidas = React.useMemo(
    () => todasMontagens.filter(m => m.status === 'concluida').slice(0, 20),
    [todasMontagens]
  );

  // Buscar entregas para pegar a data de entrega
  const { data: entregas = [] } = useQuery({
    queryKey: ['entregas'],
    queryFn: () => base44.entities.Entrega.list('-data_agendada'),
    refetchInterval: 10000 // Atualiza a cada 10 segundos
  });

  const { data: vendas = [] } = useQuery({
    queryKey: ['vendas'],
    queryFn: () => base44.entities.Venda.list('-data_venda')
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, data }) => base44.entities.MontagemItem.update(id, data),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['montagens-internas-todas'] })
  });

  // Mapa de entregas para busca rápida por ID e Numero Pedido
  const entregasMaps = React.useMemo(() => {
    const byId = new Map();
    const byPedido = new Map();

    entregas.forEach(e => {
      byId.set(String(e.id), e);
      if (e.numero_pedido) byPedido.set(String(e.numero_pedido), e);
    });

    return { byId, byPedido };
  }, [entregas]);

  // Agrupar por dia de entrega
  const diasDaSemana = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'];

  const montagensData = React.useMemo(() => {
    const porDia = {};
    const outrasDatas = [];

    // Helper para formatar data local YYYY-MM-DD
    const getLocalDateString = (date) => {
      const year = date.getFullYear();
      const month = String(date.getMonth() + 1).padStart(2, '0');
      const day = String(date.getDate()).padStart(2, '0');
      return `${year}-${month}-${day}`;
    };

    // Gerar todos os dias da semana
    for (let i = 0; i < 7; i++) {
      const dia = new Date(inicio);
      dia.setDate(inicio.getDate() + i);
      const dataKey = getLocalDateString(dia);

      porDia[dataKey] = {
        data: dia,
        label: diasDaSemana[dia.getDay()],
        diaNumero: dia.getDate(),
        montagens: []
      };
    }

    // Distribuir montagens com base na data de entrega
    montagensInternas.forEach(montagem => {
      // Tentar encontrar a entrega (Pelo ID ou pelo Número do Pedido como fallback)
      let entrega = entregasMaps.byId.get(String(montagem.entrega_id));

      if (!entrega && montagem.numero_pedido) {
        entrega = entregasMaps.byPedido.get(String(montagem.numero_pedido));
      }

      if (entrega?.data_agendada) {
        const dataKey = entrega.data_agendada.split('T')[0];

        if (porDia[dataKey]) {
          porDia[dataKey].montagens.push({
            ...montagem,
            dataEntrega: entrega.data_agendada,
            turnoEntrega: entrega.turno
          });
        } else {
          // Agendada mas fora da semana atual
          outrasDatas.push({
            ...montagem,
            dataEntrega: entrega.data_agendada,
            turnoEntrega: entrega.turno
          });
        }
      }
    });

    return { porDia, outrasDatas };
  }, [montagensInternas, entregasMaps, inicio]);

  // Facil acesso para o render atual
  const montagensPorDia = montagensData.porDia;
  const montagensOutrasDatas = montagensData.outrasDatas;

  // Função para solicitar PIN do usuário logado
  const solicitarPin = (callback) => {
    if (!isMontador) {
      callback();
      return;
    }

    // Buscar PIN do usuário logado na lista de montadores internos
    const montadorLogado = montadoresInternos.find(m => m.id?.toString() === user?.id?.toString());
    const pinDoUsuario = montadorLogado?.pin_montagem || user?.pin_montagem;

    // Se o usuário tem PIN configurado, pedir
    if (pinDoUsuario) {
      setPinCallback(() => callback);
      setPinInput('');
      setPinDialogOpen(true);
    } else {
      toast.warning('PIN não configurado. Ação confirmada sem PIN.');
      callback();
    }
  };

  const confirmarPin = () => {
    const montadorLogado = montadoresInternos.find(m => m.id?.toString() === user?.id?.toString());
    const pinDoUsuario = montadorLogado?.pin_montagem || user?.pin_montagem;
    if (pinDoUsuario === pinInput) {
      setPinDialogOpen(false);
      if (pinCallback) pinCallback();
      // Limpar estados sensíveis
      setPinInput('');
      setPinCallback(null);
    } else {
      toast.error("PIN incorreto");
      setPinInput('');
    }
  };

  // Auto-atribuir montagem ao usuário logado (para montadores)
  const autoAtribuirMontador = async (montagem) => {
    try {
      const { data, error } = await supabase
        .from('montagens_itens')
        .update({
          montador_id: user.id?.toString(),
          montador_nome: user.full_name || user.email,
          updated_at: new Date().toISOString()
        })
        .eq('id', montagem.id)
        .is('montador_id', null)
        .neq('status', 'concluida')
        .select('id');

      if (error) throw error;

      if (!data || data.length === 0) {
        toast.warning('Esta montagem acabou de ser atribuida para outro montador.');
        queryClient.invalidateQueries({ queryKey: ['montagens-internas-todas'] });
