        } finally {
            setAplicando(false);
        }
    };

    return (
        <>
            {!modalControlado && (
                <Button
                    variant="outline"
                    size="sm"
                    onClick={handleOtimizar}
                    disabled={entregasValidas.length < 2 || loading}
