                            </div>
                        )}

                        {/* Erro */}
                        {erro && (
                            <Card className="border-red-200 bg-red-50">
                                <CardContent className="p-4 flex items-center gap-3">
                                    <AlertCircle className="w-6 h-6 text-red-500" />
                                    <div>
                                        <p className="font-medium text-red-800">Erro na otimização</p>
                                        <p className="text-sm text-red-600">{erro}</p>
                                    </div>
                                </CardContent>
                            </Card>
                        )}

                        {/* Resultado */}
                        {rotaOtimizada && !loading && (
                            <>
                                {/* Cards de resumo */}
                                <div className="grid grid-cols-3 gap-3">
                                    <Card className="bg-gradient-to-br from-blue-50 to-blue-100 border-blue-200">
                                        <CardContent className="p-4 text-center">
                                            <MapPin className="w-6 h-6 mx-auto text-blue-600 mb-2" />
                                            <p className="text-2xl font-bold text-blue-800">
                                                {rotaOtimizada.distanciaFormatada}
                                            </p>
                                            <p className="text-xs text-blue-600">Distância total</p>
                                        </CardContent>
                                    </Card>

                                    <Card className="bg-gradient-to-br from-green-50 to-green-100 border-green-200">
                                        <CardContent className="p-4 text-center">
                                            <Clock className="w-6 h-6 mx-auto text-green-600 mb-2" />
                                            <p className="text-2xl font-bold text-green-800">
                                                {rotaOtimizada.tempoFormatado}
                                            </p>
                                            <p className="text-xs text-green-600">Tempo estimado</p>
                                        </CardContent>
                                    </Card>

                                    <Card className="bg-gradient-to-br from-orange-50 to-orange-100 border-orange-200">
                                        <CardContent className="p-4 text-center">
                                            <Fuel className="w-6 h-6 mx-auto text-orange-600 mb-2" />
                                            <p className="text-2xl font-bold text-orange-800">
                                                ~{Math.round(rotaOtimizada.distanciaTotal / 10)}L
                                            </p>
                                            <p className="text-xs text-orange-600">Combustível (~10km/L)</p>
                                        </CardContent>
                                    </Card>
                                </div>

                                {/* Indicador de economia */}
                                {comparacao?.ordemMudou && (
                                    <Card className="bg-gradient-to-r from-emerald-500 to-emerald-600 text-white">
                                        <CardContent className="p-4 flex items-center justify-between">
                                            <div className="flex items-center gap-3">
                                                <TrendingDown className="w-8 h-8" />
                                                <div>
                                                    <p className="font-bold">Rota otimizada!</p>
                                                    <p className="text-sm text-emerald-100">
                                                        A ordem das entregas foi reorganizada para economia
                                                    </p>
                                                </div>
                                            </div>
                                            <Badge className="bg-white/20 text-white">
                                                ~{comparacao.economiaEstimada}km economizados
                                            </Badge>
                                        </CardContent>
                                    </Card>
                                )}

                                {!comparacao?.ordemMudou && (
                                    <Card className="bg-gray-50 border-gray-200">
                                        <CardContent className="p-4 text-center">
                                            <Check className="w-8 h-8 mx-auto text-gray-400 mb-2" />
                                            <p className="text-gray-600">
                                                A ordem atual já está otimizada!
                                            </p>
                                        </CardContent>
                                    </Card>
                                )}

                                {/* Lista de paradas otimizada */}
                                <Card>
                                    <CardHeader className="pb-2">
                                        <CardTitle className="text-sm font-medium flex items-center gap-2">
                                            <Route className="w-4 h-4" />
                                            Ordem Otimizada das Entregas
                                        </CardTitle>
                                    </CardHeader>
                                    <CardContent className="p-0">
                                        <div className="divide-y">
                                            {rotaOtimizada.ordemOtimizada.map((entrega, index) => (
                                                <div
                                                    key={entrega.id}
                                                    className="p-3 flex items-center gap-3 hover:bg-gray-50"
                                                >
                                                    <div className="w-8 h-8 rounded-full bg-blue-600 text-white flex items-center justify-center font-bold text-sm">
                                                        {index + 1}
                                                    </div>
                                                    <div className="flex-1 min-w-0">
                                                        <p className="font-medium text-sm truncate">
                                                            {entrega.cliente_nome}
                                                        </p>
                                                        <p className="text-xs text-gray-500 truncate">
                                                            {entrega.endereco_entrega}
                                                        </p>
                                                    </div>
                                                    {rotaOtimizada.legs?.[index] && (
                                                        <div className="text-right text-xs text-gray-400">
                                                            <p>{rotaOtimizada.legs[index].distancia}</p>
                                                            <p>{rotaOtimizada.legs[index].tempo}</p>
                                                        </div>
                                                    )}
                                                    {index < rotaOtimizada.ordemOtimizada.length - 1 && (
                                                        <ArrowRight className="w-4 h-4 text-gray-300 hidden sm:block" />
                                                    )}
                                                </div>
                                            ))}
                                        </div>
                                    </CardContent>
                                </Card>

                                {/* Botões de ação */}
                                <div className="flex gap-3 pt-2">
                                    <Button
                                        variant="outline"
                                        onClick={fecharModal}
                                        className="flex-1"
                                    >
                                        Cancelar
                                    </Button>
                                    <Button
                                        onClick={aplicarOrdem}
                                        disabled={aplicando || !comparacao?.ordemMudou}
                                        className="flex-1 bg-blue-600 hover:bg-blue-700"
                                    >
                                        {aplicando ? (
                                            <>
                                                <RefreshCw className="w-4 h-4 mr-2 animate-spin" />
                                                Aplicando...
                                            </>
                                        ) : (
                                            <>
                                                <Check className="w-4 h-4 mr-2" />
                                                Aplicar Nova Ordem
                                            </>
                                        )}
                                    </Button>
                                </div>
                            </>
                        )}
                    </div>
                </DialogContent>
            </Dialog>
        </>
    );
}

import React, { useEffect, useState } from "react";

export default function SugestaoRotaVisual({ sugestoes }) {
  const [linhas, setLinhas] = useState([]);

  useEffect(() => {
    const calcularLinhas = () => {
      const novasLinhas = [];
      
      sugestoes?.forEach(sugestao => {
        const entregaEl = document.querySelector(`[data-entrega-id="${sugestao.entregaId}"]`);
        const diaEl = document.querySelector(`[data-dia-id="${sugestao.diaId}"]`);
        
        if (entregaEl && diaEl) {
          const entregaRect = entregaEl.getBoundingClientRect();
          const diaRect = diaEl.getBoundingClientRect();
          
          // Ponto de origem (direita do card da entrega)
          const x1 = entregaRect.right;
          const y1 = entregaRect.top + entregaRect.height / 2;
          
          // Ponto de destino (topo do kanban do dia)
          const x2 = diaRect.left + diaRect.width / 2;
          const y2 = diaRect.top;
          
          // Pontos de controle para curva suave
          const controlX1 = x1 + (x2 - x1) * 0.3;
          const controlY1 = y1;
          const controlX2 = x2;
          const controlY2 = y2 - 30;
          
          novasLinhas.push({
            id: sugestao.entregaId,
            path: `M ${x1} ${y1} C ${controlX1} ${controlY1}, ${controlX2} ${controlY2}, ${x2} ${y2}`,
            cor: sugestao.cor || '#10b981'
          });
        }
      });
      
      setLinhas(novasLinhas);
    };

    calcularLinhas();
    window.addEventListener('resize', calcularLinhas);
    window.addEventListener('scroll', calcularLinhas);
    
    return () => {
      window.removeEventListener('resize', calcularLinhas);
      window.removeEventListener('scroll', calcularLinhas);
    };
  }, [sugestoes]);

  if (!linhas.length) return null;

  return (
    <svg
      className="absolute inset-0 pointer-events-none z-10"
      style={{ width: '100%', height: '100%' }}
    >
      <defs>
        {linhas.map(linha => (
          <marker
            key={`arrow-${linha.id}`}
            id={`arrow-${linha.id}`}
            markerWidth="10"
            markerHeight="10"
            refX="9"
            refY="3"
            orient="auto"
            markerUnits="strokeWidth"
          >
            <path d="M0,0 L0,6 L9,3 z" fill={linha.cor} />
          </marker>
        ))}
      </defs>
      
      {linhas.map(linha => (
        <g key={linha.id}>
          <path
            d={linha.path}
            stroke={linha.cor}
            strokeWidth="2"
            fill="none"
            strokeDasharray="8 4"
            strokeLinecap="round"
            opacity="0.6"
            markerEnd={`url(#arrow-${linha.id})`}
          />
          <path
            d={linha.path}
            stroke={linha.cor}
            strokeWidth="2"
            fill="none"
            strokeDasharray="8 4"
            strokeLinecap="round"
            opacity="0.3"
          >
            <animate
              attributeName="stroke-dashoffset"
              from="0"
              to="-12"
              dur="1s"
              repeatCount="indefinite"
            />
          </path>
        </g>
      ))}
    </svg>
  );
}

