export default function FidelidadeRegras() {
    const queryClient = useQueryClient();
    const [activeTab, setActiveTab] = useState("compras");
    const [savingConfig, setSavingConfig] = useState(false);
    const [isRewardModalOpen, setIsRewardModalOpen] = useState(false);
    const [isTierModalOpen, setIsTierModalOpen] = useState(false);
    const [editingTier, setEditingTier] = useState(null);
    const [isCatModalOpen, setIsCatModalOpen] = useState(false);
    const [campanhaClienteQ, setCampanhaClienteQ] = useState("");
    const [campanhaFiltroTier, setCampanhaFiltroTier] = useState("todos");
    const [campanhaQtd, setCampanhaQtd] = useState("");
    const [campanhaMotivo, setCampanhaMotivo] = useState("");
    const [campanhaLoading, setCampanhaLoading] = useState(false);

    const [config, setConfig] = useState({
        nome_pontos_singular: "Coroa",
        nome_pontos_plural: "Coroas",
        signup_bonus_ativo: true,
        purchase_value_threshold: 50, steps_per_purchase: 10, signup_bonus: 5, is_active: true,
        reward_threshold: 100, desconto_por_coroa: 0.10,
        aniversario_ativo: false, aniversario_coroas: 50,
        indicacao_ativo: false, indicacao_coroas: 30,
        avaliacao_ativo: false, avaliacao_coroas: 10,
        frequencia_ativo: false, frequencia_coroas: 20, frequencia_minima: 2,
        produto_especifico_ativo: false,
        pagamento_avista_ativo: false, pagamento_avista_coroas: 10,
        expiracao_ativo: false, expiracao_valor: 12, expiracao_unidade: "meses",
    });

    const [rewardForm, setRewardForm] = useState({
        nome: "", reward_type: "cupom_percentual", value: "",
        coroas_necessarias: "", desconta_coroas: true, expiracao_dias: 30, mensagem_cliente: ""
    });

    const [tierForm, setTierForm] = useState({ nome: "", coroas_minimas: 0, multiplicador_coroas: 1.0, ordem: 1 });
    const [catForm, setCatForm] = useState({ categoria: "", coroas_bonus: 10, multiplicador: 1.0 });

    // --- Queries ---
    const { data: configData, isLoading: loadingConfig } = useQuery({
        queryKey: ["fidelidade_config"],
        queryFn: async () => {
            const { data, error } = await supabase.from("fidelidade_config").select("*").eq("is_active", true).maybeSingle();
            if (error && error.code !== "PGRST116") throw error;
            return data;
        },
    });

    React.useEffect(() => { if (configData) setConfig(prev => ({ ...prev, ...configData })); }, [configData]);

    const { data: rewards = [], isLoading: loadingRewards } = useQuery({
        queryKey: ["fidelidade_rewards_catalog"],
        queryFn: async () => {
            const { data, error } = await supabase.from("fidelidade_recompensas")
                .select("*, fidelidade_regras (id, nome, is_active)")
                .gt("coroas_necessarias", 0).order("coroas_necessarias", { ascending: true });
            if (error) throw error;
            return data || [];
        },
    });

    const { data: tiers = [], isLoading: loadingTiers } = useQuery({
        queryKey: ["fidelidade_tiers"],
        queryFn: async () => {
            const { data, error } = await supabase.from("fidelidade_tiers")
                .select("*").order("ordem", { ascending: true });
            if (error) throw error;
            return data || [];
        },
    });

    const { data: categoriasBonus = [] } = useQuery({
        queryKey: ["fidelidade_categorias_bonus"],
        queryFn: async () => {
            const { data, error } = await supabase.from("fidelidade_categorias_bonus")
                .select("*").order("categoria");
            if (error) throw error;
            return data || [];
        },
    });

    const { data: historicoCampanha = [] } = useQuery({
        queryKey: ["fidelidade_historico_campanha"],
        queryFn: async () => {
            const { data, error } = await supabase.from("fidelidade_historico")
                .select("*, clientes (nome_completo)")
                .eq("tipo_evento", "campanha")
                .order("created_at", { ascending: false }).limit(50);
            if (error) throw error;
            return data || [];
        },
    });

    const { data: clientesCampanha = [] } = useQuery({
        queryKey: ["clientes_campanha", campanhaClienteQ, campanhaFiltroTier],
        queryFn: async () => {
            if (!campanhaClienteQ && campanhaFiltroTier === "todos") return [];
            let q = supabase.from("clientes").select("id, nome_completo, coroas, tier_id");
            if (campanhaClienteQ) q = q.ilike("nome_completo", `%${campanhaClienteQ}%`);
            if (campanhaFiltroTier !== "todos") q = q.eq("tier_id", campanhaFiltroTier);
            const { data } = await q.limit(20);
            return data || [];
        },
        enabled: !!(campanhaClienteQ || campanhaFiltroTier !== "todos"),
    });

    // --- Mutations ---
    const saveConfig = async () => {
        setSavingConfig(true);
        try {
            const { error } = await supabase.from("fidelidade_config").upsert({
                id: config.id || 1,
                nome_pontos_singular: config.nome_pontos_singular || "Coroa",
                nome_pontos_plural: config.nome_pontos_plural || "Coroas",
                signup_bonus_ativo: config.signup_bonus_ativo !== false,
                purchase_value_threshold: parseFloat(config.purchase_value_threshold) || 50,
                steps_per_purchase: parseInt(config.steps_per_purchase) || 10,
                signup_bonus: parseInt(config.signup_bonus) || 5,
                is_active: config.is_active,
                reward_threshold: parseInt(config.reward_threshold) || 100,
                desconto_por_coroa: parseFloat(config.desconto_por_coroa) || 0.10,
                aniversario_ativo: config.aniversario_ativo,
                aniversario_coroas: parseInt(config.aniversario_coroas) || 50,
                indicacao_ativo: config.indicacao_ativo,
                indicacao_coroas: parseInt(config.indicacao_coroas) || 30,
                avaliacao_ativo: config.avaliacao_ativo,
                avaliacao_coroas: parseInt(config.avaliacao_coroas) || 10,
                frequencia_ativo: config.frequencia_ativo,
                frequencia_coroas: parseInt(config.frequencia_coroas) || 20,
                frequencia_minima: parseInt(config.frequencia_minima) || 2,
                produto_especifico_ativo: config.produto_especifico_ativo,
                pagamento_avista_ativo: config.pagamento_avista_ativo,
                pagamento_avista_coroas: parseInt(config.pagamento_avista_coroas) || 10,
                expiracao_ativo: config.expiracao_ativo,
                expiracao_valor: parseInt(config.expiracao_valor) || 12,
                expiracao_unidade: config.expiracao_unidade || "meses",
            });
            if (error) throw error;
            toast.success("Configuracao salva!");
            queryClient.invalidateQueries({ queryKey: ["fidelidade_config"] });
        } catch (err) { toast.error("Erro ao salvar: " + err.message); }
        finally { setSavingConfig(false); }
    };

    const createRewardMutation = useMutation({
        mutationFn: async (data) => {
            const { data: regra, error: re } = await supabase.from("fidelidade_regras")
                .insert({ nome: data.nome, descricao: `Troque ${data.coroas_necessarias} Coroas`, trigger_type: "resgate", is_active: true, priority: 10 })
                .select().single();
            if (re) throw re;
            const { error: rwe } = await supabase.from("fidelidade_recompensas").insert({
                regra_id: regra.id, reward_type: data.reward_type, value: parseFloat(data.value) || 0,
                coroas_necessarias: parseInt(data.coroas_necessarias) || 0, desconta_coroas: data.desconta_coroas,
                expiracao_dias: parseInt(data.expiracao_dias) || 30, mensagem_cliente: data.mensagem_cliente || null
            });
            if (rwe) throw rwe;
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["fidelidade_rewards_catalog"] });
            toast.success("Recompensa criada!");
            setIsRewardModalOpen(false);
            setRewardForm({ nome: "", reward_type: "cupom_percentual", value: "", coroas_necessarias: "", desconta_coroas: true, expiracao_dias: 30, mensagem_cliente: "" });
        },
        onError: (err) => toast.error("Erro: " + err.message)
    });

    const deleteRewardMutation = useMutation({
        mutationFn: async (regraId) => {
            const { error } = await supabase.from("fidelidade_regras").delete().eq("id", regraId);
            if (error) throw error;
        },
        onSuccess: () => { queryClient.invalidateQueries({ queryKey: ["fidelidade_rewards_catalog"] }); toast.success("Recompensa excluida!"); }
    });

    const toggleRewardMutation = useMutation({
        mutationFn: async ({ regraId, is_active }) => {
            const { error } = await supabase.from("fidelidade_regras").update({ is_active }).eq("id", regraId);
            if (error) throw error;
        },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ["fidelidade_rewards_catalog"] })
    });

    const saveTierMutation = useMutation({
        mutationFn: async (data) => {
            if (data.id) {
                const { error } = await supabase.from("fidelidade_tiers").update({
                    nome: data.nome, coroas_minimas: parseInt(data.coroas_minimas),
                    multiplicador_coroas: parseFloat(data.multiplicador_coroas), ordem: parseInt(data.ordem)
                }).eq("id", data.id);
                if (error) throw error;
            } else {
                const { error } = await supabase.from("fidelidade_tiers").insert({
                    nome: data.nome, coroas_minimas: parseInt(data.coroas_minimas),
                    multiplicador_coroas: parseFloat(data.multiplicador_coroas), ordem: parseInt(data.ordem), is_active: true
                });
                if (error) throw error;
            }
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["fidelidade_tiers"] });
            toast.success("Tier salvo!");
            setIsTierModalOpen(false);
            setEditingTier(null);
            setTierForm({ nome: "", coroas_minimas: 0, multiplicador_coroas: 1.0, ordem: 1 });
        },
        onError: (err) => toast.error("Erro: " + err.message)
    });

    const deleteTierMutation = useMutation({
        mutationFn: async (id) => { const { error } = await supabase.from("fidelidade_tiers").delete().eq("id", id); if (error) throw error; },
        onSuccess: () => { queryClient.invalidateQueries({ queryKey: ["fidelidade_tiers"] }); toast.success("Tier excluido!"); }
    });

    const saveCatMutation = useMutation({
        mutationFn: async (data) => {
            const { error } = await supabase.from("fidelidade_categorias_bonus").insert({
                categoria: data.categoria, coroas_bonus: parseInt(data.coroas_bonus),
                multiplicador: parseFloat(data.multiplicador) || 1.0, is_active: true
            });
            if (error) throw error;
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ["fidelidade_categorias_bonus"] });
            toast.success("Categoria adicionada!");
            setIsCatModalOpen(false);
            setCatForm({ categoria: "", coroas_bonus: 10, multiplicador: 1.0 });
        },
        onError: (err) => toast.error("Erro: " + err.message)
    });

    const deleteCatMutation = useMutation({
        mutationFn: async (id) => { const { error } = await supabase.from("fidelidade_categorias_bonus").delete().eq("id", id); if (error) throw error; },
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ["fidelidade_categorias_bonus"] })
    });

    const handleConcederCoroas = async (clienteId, nome) => {
        if (!campanhaQtd || parseInt(campanhaQtd) === 0) { toast.error("Informe a quantidade de Coroas"); return; }
        if (!campanhaMotivo.trim()) { toast.error("Informe o motivo"); return; }
        setCampanhaLoading(true);
        const resultado = await adicionarCoroas(clienteId, parseInt(campanhaQtd), campanhaMotivo);
        setCampanhaLoading(false);
        if (resultado.sucesso) {
            toast.success(`${campanhaQtd} Coroas concedidas para ${nome}!`);
            queryClient.invalidateQueries({ queryKey: ["fidelidade_historico_campanha"] });
            queryClient.invalidateQueries({ queryKey: ["clientes"] });
        } else {
            toast.error("Erro ao conceder coroas");
        }
    };

    const openEditTier = (tier) => {
        setEditingTier(tier);
        setTierForm({ ...tier });
        setIsTierModalOpen(true);
    };

    const formatReward = (type, value) => {
        if (type === "cupom_percentual") return `${value}% de desconto`;
        if (type === "cupom_valor") return `R$ ${value} de desconto`;
        if (type === "frete_gratis") return "Frete Gratis";
        if (type === "item_gratis") return "Item Gratis";
        if (type === "cashback") return `R$ ${value} de Cashback`;
        if (type === "desconto_proximo") return `${value}% na proxima compra`;
        return `${value}`;
    };

    if (loadingConfig) {
        return <div className="flex items-center justify-center py-12"><Loader2 className="w-8 h-8 animate-spin text-amber-500" /></div>;
    }

    return (
        <div className="space-y-4">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-xl font-bold" style={{ color: "#07593f" }}>Programa de Fidelidade</h2>
                    <p className="text-sm text-gray-500">Configure como os clientes ganham e resgatam Coroas</p>
                </div>
                <div className="flex items-center gap-2">
                    <Switch checked={config.is_active} onCheckedChange={(v) => setConfig(p => ({ ...p, is_active: v }))} />
                    <span className="text-sm text-gray-600">Programa {config.is_active ? "Ativo" : "Inativo"}</span>
                </div>
            </div>

            <Tabs value={activeTab} onValueChange={setActiveTab}>
                <TabsList className="grid grid-cols-6 w-full">
                    <TabsTrigger value="compras"><ShoppingBag className="w-4 h-4 mr-1" />Compras</TabsTrigger>
                    <TabsTrigger value="relacionamento"><Users className="w-4 h-4 mr-1" />Relacionamento</TabsTrigger>
                    <TabsTrigger value="tiers"><Crown className="w-4 h-4 mr-1" />Niveis</TabsTrigger>
                    <TabsTrigger value="resgates"><Gift className="w-4 h-4 mr-1" />Resgates</TabsTrigger>
                    <TabsTrigger value="expiracao"><Clock className="w-4 h-4 mr-1" />Expiracao</TabsTrigger>
                    <TabsTrigger value="campanhas"><Megaphone className="w-4 h-4 mr-1" />Campanhas</TabsTrigger>
                </TabsList>

                {/* ============================================================ */}
                {/* TAB 1: COMPRAS & IDENTIDADE DA MOEDA                        */}
                {/* ============================================================ */}
                <TabsContent value="compras" className="space-y-4 mt-4">
                    {/* Identidade / Nomenclatura dos Pontos */}
                    <Card className="border-0 shadow border-l-4 border-l-amber-500">
                        <CardHeader className="border-b bg-amber-50/50 dark:bg-neutral-900">
                            <div className="flex items-center justify-between">
                                <div className="flex items-center gap-2">
                                    <Sparkles className="w-5 h-5 text-amber-600" />
                                    <div>
                                        <CardTitle className="text-base text-gray-900 dark:text-white">Identidade da Pontuação de Fidelidade</CardTitle>
                                        <CardDescription className="text-xs">Escolha como sua loja chama a pontuação do cliente (ex: Coroas, Pontos, Moedas, Estrelas)</CardDescription>
                                    </div>
                                </div>
                            </div>
                        </CardHeader>
                        <CardContent className="p-5 space-y-4">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div>
                                    <Label className="text-xs font-semibold">Nome no Singular</Label>
                                    <Input 
                                        className="mt-1 h-9 text-sm"
                                        placeholder="Ex: Coroa, Ponto, Moeda, Estrela"
                                        value={config.nome_pontos_singular || "Coroa"}
                                        onChange={(e) => setConfig(p => ({ ...p, nome_pontos_singular: e.target.value }))}
                                    />
                                    <p className="text-[11px] text-gray-500 mt-1">Usado quando for 1 unidade (Ex: "1 {config.nome_pontos_singular || 'Coroa'}")</p>
                                </div>

                                <div>
                                    <Label className="text-xs font-semibold">Nome no Plural</Label>
                                    <Input 
                                        className="mt-1 h-9 text-sm"
                                        placeholder="Ex: Coroas, Pontos, Moedas, Estrelas"
                                        value={config.nome_pontos_plural || "Coroas"}
                                        onChange={(e) => setConfig(p => ({ ...p, nome_pontos_plural: e.target.value }))}
                                    />
                                    <p className="text-[11px] text-gray-500 mt-1">Usado para mais de 1 unidade (Ex: "10 {config.nome_pontos_plural || 'Coroas'}")</p>
                                </div>
                            </div>

                            {/* Preset Buttons */}
                            <div className="pt-2">
                                <span className="text-xs font-medium text-gray-500 block mb-2">Modelos Rápidos (Clique para preencher em 1 clique):</span>
                                <div className="flex flex-wrap gap-2">
                                    {[
                                        { singular: "Coroa", plural: "Coroas", emoji: "👑" },
                                        { singular: "Ponto", plural: "Pontos", emoji: "⭐" },
                                        { singular: "Moeda", plural: "Moedas", emoji: "🪙" },
                                        { singular: "Estrela", plural: "Estrelas", emoji: "🌟" },
                                        { singular: "Crédito", plural: "Créditos", emoji: "💳" },
                                    ].map(item => (
                                        <button
                                            key={item.singular}
                                            type="button"
                                            onClick={() => setConfig(p => ({ ...p, nome_pontos_singular: item.singular, nome_pontos_plural: item.plural }))}
                                            className="px-2.5 py-1 text-xs rounded-lg border border-gray-200 dark:border-neutral-700 bg-white dark:bg-neutral-800 hover:bg-amber-50 dark:hover:bg-amber-950/40 text-gray-700 dark:text-gray-300 font-medium flex items-center gap-1.5 transition-colors"
                                        >
                                            <span>{item.emoji}</span> {item.plural}
                                        </button>
                                    ))}
                                </div>
                            </div>
                        </CardContent>
                    </Card>

                    <Card className="border-0 shadow">
                        <CardHeader className="border-b bg-amber-50">
                            <div className="flex items-center gap-2">
                                <Coins className="w-5 h-5 text-amber-600" />
                                <CardTitle className="text-amber-800">Acúmulo por Compra</CardTitle>
                            </div>
                        </CardHeader>
                        <CardContent className="p-6 space-y-6">
                            <div className="grid md:grid-cols-3 gap-4">
                                <div>
                                    <Label className="flex items-center gap-2 mb-2">
                                        <DollarSign className="w-4 h-4 text-green-600" />A cada R$
                                    </Label>
                                    <Input type="number" min="1" value={config.purchase_value_threshold}
                                        onChange={(e) => setConfig(p => ({ ...p, purchase_value_threshold: e.target.value }))} />
                                    <p className="text-xs text-gray-500 mt-1">Valor em reais</p>
                                </div>
                                <div>
                                    <Label className="flex items-center gap-2 mb-2">
                                        <Crown className="w-4 h-4 text-amber-500" />Ganha
                                    </Label>
                                    <Input type="number" min="1" value={config.steps_per_purchase}
                                        onChange={(e) => setConfig(p => ({ ...p, steps_per_purchase: e.target.value }))} />
                                    <p className="text-xs text-gray-500 mt-1">Coroas por unidade</p>
                                </div>
                            </div>

                            {/* Bonus Cadastro Switch & Input */}
                            <div className="border rounded-xl p-4 bg-purple-50/40 dark:bg-purple-950/20 border-purple-200 dark:border-purple-800 space-y-3">
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-2">
                                        <Sparkles className="w-5 h-5 text-purple-600 dark:text-purple-400" />
                                        <div>
                                            <span className="font-semibold text-sm text-gray-900 dark:text-white">Bônus de Boas-Vindas no Cadastro</span>
                                            <p className="text-xs text-gray-500 dark:text-gray-400">Conceder pontuação automática quando um cliente cria conta no portal</p>
                                        </div>
                                    </div>
                                    <Switch 
                                        checked={config.signup_bonus_ativo !== false}
                                        onCheckedChange={(v) => setConfig(p => ({ ...p, signup_bonus_ativo: v }))} 
                                    />
                                </div>

                                {config.signup_bonus_ativo !== false ? (
                                    <div className="flex items-center gap-3 pt-3 border-t border-purple-200/60 dark:border-purple-800/60">
                                        <Label className="text-xs font-semibold whitespace-nowrap">
                                            Quantidade de {config.nome_pontos_plural || 'Coroas'} de Bônus:
                                        </Label>
                                        <Input 
                                            type="number" 
                                            min="1" 
                                            className="w-28 h-9 text-sm" 
                                            value={config.signup_bonus}
                                            onChange={(e) => setConfig(p => ({ ...p, signup_bonus: e.target.value }))} 
                                        />
                                    </div>
                                ) : (
                                    <div className="p-2.5 bg-amber-50 dark:bg-amber-950/40 rounded-lg border border-amber-200 dark:border-amber-800 text-xs text-amber-800 dark:text-amber-300">
                                        ⚠️ <strong>Bônus Desativado:</strong> Novos clientes se cadastrarão na plataforma sem pontos iniciais.
                                    </div>
                                )}
                            </div>

                            <div className="p-4 bg-green-50 rounded-xl border border-green-200">
                                <div className="flex items-center gap-2 mb-1">
                                    <Sparkles className="w-4 h-4 text-green-600" />
                                    <span className="font-medium text-green-800">Exemplo</span>
                                </div>
                                <p className="text-sm text-green-700">
                                    Cliente compra <strong>R$ {(config.purchase_value_threshold * 2) || 100}</strong>
                                    <ArrowRight className="w-3 h-3 inline mx-2" />
                                    Ganha <strong className="text-amber-600">{(config.steps_per_purchase * 2) || 20} Coroas</strong>
                                </p>
                            </div>

                            {/* Bonus pagamento a vista */}
                            <div className="border rounded-xl p-4">
                                <div className="flex items-center justify-between mb-3">
                                    <div className="flex items-center gap-2">
                                        <Coins className="w-4 h-4 text-blue-500" />
                                        <span className="font-medium">Bonus Pagamento a Vista</span>
                                        <Badge variant="secondary" className="text-xs">Dinheiro, Pix, Debito</Badge>
                                    </div>
                                    <Switch checked={config.pagamento_avista_ativo}
                                        onCheckedChange={(v) => setConfig(p => ({ ...p, pagamento_avista_ativo: v }))} />
                                </div>
                                {config.pagamento_avista_ativo && (
                                    <div className="flex items-center gap-3">
                                        <Label className="whitespace-nowrap text-sm">Coroas extras:</Label>
                                        <Input type="number" min="1" className="w-28" value={config.pagamento_avista_coroas}
                                            onChange={(e) => setConfig(p => ({ ...p, pagamento_avista_coroas: e.target.value }))} />
                                    </div>
                                )}
                            </div>

                            {/* Categorias bonus */}
                            <div className="border rounded-xl p-4">
                                <div className="flex items-center justify-between mb-3">
                                    <div className="flex items-center gap-2">
                                        <Package className="w-4 h-4 text-orange-500" />
                                        <span className="font-medium">Categorias com Coroas Extras</span>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <Switch checked={config.produto_especifico_ativo}
                                            onCheckedChange={(v) => setConfig(p => ({ ...p, produto_especifico_ativo: v }))} />
                                        <Button size="sm" variant="outline" onClick={() => setIsCatModalOpen(true)}>
                                            <Plus className="w-3 h-3 mr-1" />Categoria
                                        </Button>
                                    </div>
                                </div>
                                {categoriasBonus.length === 0 ? (
                                    <p className="text-sm text-gray-400 text-center py-2">Nenhuma categoria configurada</p>
                                ) : (
                                    <div className="space-y-2">
                                        {categoriasBonus.map(cat => (
                                            <div key={cat.id} className="flex items-center justify-between bg-orange-50 rounded-lg px-3 py-2">
                                                <div className="flex items-center gap-2">
                                                    <Badge className="bg-orange-200 text-orange-800">{cat.categoria}</Badge>
                                                    <span className="text-sm">+{cat.coroas_bonus} Coroas</span>
                                                    {cat.multiplicador > 1 && <span className="text-xs text-gray-500">x{cat.multiplicador}</span>}
                                                </div>
                                                <Button size="sm" variant="ghost" className="text-red-400 h-6 w-6 p-0"
                                                    onClick={() => deleteCatMutation.mutate(cat.id)}>
                                                    <Trash2 className="w-3 h-3" />
                                                </Button>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        </CardContent>
                    </Card>

                    <div className="flex justify-end">
                        <Button onClick={saveConfig} disabled={savingConfig} style={{ backgroundColor: "#07593f" }}>
                            {savingConfig ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                            Salvar Configuracoes
                        </Button>
                    </div>
                </TabsContent>

                {/* ============================================================ */}
                {/* TAB 2: RELACIONAMENTO                                         */}
                {/* ============================================================ */}
                <TabsContent value="relacionamento" className="space-y-4 mt-4">
                    <Card className="border-0 shadow">
                        <CardHeader className="border-b bg-blue-50">
                            <div className="flex items-center gap-2">
                                <Users className="w-5 h-5 text-blue-600" />
                                <CardTitle className="text-blue-800">Gatilhos de Relacionamento</CardTitle>
                                <CardDescription>Configure bonus por interacoes alem das compras</CardDescription>
                            </div>
                        </CardHeader>
                        <CardContent className="p-6 space-y-4">
                            {/* Aniversario */}
                            <div className="border rounded-xl p-4">
                                <div className="flex items-center justify-between mb-2">
                                    <div className="flex items-center gap-2">
                                        <Calendar className="w-4 h-4 text-pink-500" />
                                        <span className="font-medium">Aniversario</span>
                                        <span className="text-xs text-gray-500">Uma vez por ano</span>
                                    </div>
                                    <Switch checked={config.aniversario_ativo}
                                        onCheckedChange={(v) => setConfig(p => ({ ...p, aniversario_ativo: v }))} />
                                </div>
                                {config.aniversario_ativo && (
                                    <div className="flex items-center gap-3 mt-2">
                                        <Label className="text-sm whitespace-nowrap">Coroas no mes de aniversario:</Label>
                                        <Input type="number" min="1" className="w-28" value={config.aniversario_coroas}
                                            onChange={(e) => setConfig(p => ({ ...p, aniversario_coroas: e.target.value }))} />
                                    </div>
                                )}
                            </div>

                            {/* Indicacao */}
                            <div className="border rounded-xl p-4">
                                <div className="flex items-center justify-between mb-2">
                                    <div className="flex items-center gap-2">
                                        <Users className="w-4 h-4 text-emerald-500" />
                                        <span className="font-medium">Indicacao de Amigo</span>
                                        <span className="text-xs text-gray-500">Quando o indicado faz a 1a compra</span>
                                    </div>
                                    <Switch checked={config.indicacao_ativo}
                                        onCheckedChange={(v) => setConfig(p => ({ ...p, indicacao_ativo: v }))} />
                                </div>
                                {config.indicacao_ativo && (
                                    <div className="flex items-center gap-3 mt-2">
                                        <Label className="text-sm whitespace-nowrap">Coroas para quem indicou:</Label>
                                        <Input type="number" min="1" className="w-28" value={config.indicacao_coroas}
                                            onChange={(e) => setConfig(p => ({ ...p, indicacao_coroas: e.target.value }))} />
                                    </div>
                                )}
                            </div>

                            {/* Avaliacao */}
                            <div className="border rounded-xl p-4">
                                <div className="flex items-center justify-between mb-2">
                                    <div className="flex items-center gap-2">
                                        <Star className="w-4 h-4 text-yellow-500" />
                                        <span className="font-medium">Avaliacao / Feedback</span>
                                        <span className="text-xs text-gray-500">Cooldown de 30 dias</span>
                                    </div>
                                    <Switch checked={config.avaliacao_ativo}
                                        onCheckedChange={(v) => setConfig(p => ({ ...p, avaliacao_ativo: v }))} />
                                </div>
                                {config.avaliacao_ativo && (
                                    <div className="flex items-center gap-3 mt-2">
                                        <Label className="text-sm whitespace-nowrap">Coroas por avaliacao:</Label>
                                        <Input type="number" min="1" className="w-28" value={config.avaliacao_coroas}
                                            onChange={(e) => setConfig(p => ({ ...p, avaliacao_coroas: e.target.value }))} />
                                    </div>
                                )}
                            </div>

                            {/* Frequencia */}
                            <div className="border rounded-xl p-4">
                                <div className="flex items-center justify-between mb-2">
                                    <div className="flex items-center gap-2">
                                        <Target className="w-4 h-4 text-violet-500" />
                                        <span className="font-medium">Frequencia de Compras</span>
                                        <span className="text-xs text-gray-500">Bonus ao atingir X compras no mes</span>
                                    </div>
                                    <Switch checked={config.frequencia_ativo}
                                        onCheckedChange={(v) => setConfig(p => ({ ...p, frequencia_ativo: v }))} />
                                </div>
                                {config.frequencia_ativo && (
                                    <div className="flex items-center gap-4 mt-2 flex-wrap">
                                        <div className="flex items-center gap-2">
                                            <Label className="text-sm whitespace-nowrap">Minimo de compras no mes:</Label>
                                            <Input type="number" min="2" className="w-20" value={config.frequencia_minima}
                                                onChange={(e) => setConfig(p => ({ ...p, frequencia_minima: e.target.value }))} />
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <Label className="text-sm whitespace-nowrap">Coroas de bonus:</Label>
                                            <Input type="number" min="1" className="w-24" value={config.frequencia_coroas}
                                                onChange={(e) => setConfig(p => ({ ...p, frequencia_coroas: e.target.value }))} />
                                        </div>
                                    </div>
                                )}
                            </div>
                        </CardContent>
                    </Card>
                    <div className="flex justify-end">
                        <Button onClick={saveConfig} disabled={savingConfig} style={{ backgroundColor: "#07593f" }}>
                            {savingConfig ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                            Salvar Configuracoes
                        </Button>
                    </div>
                </TabsContent>

                {/* ============================================================ */}
                {/* TAB 3: NIVEIS (TIERS)                                         */}
                {/* ============================================================ */}
                <TabsContent value="tiers" className="space-y-4 mt-4">
                    <Card className="border-0 shadow">
                        <CardHeader className="border-b flex-row items-center justify-between">
                            <div className="flex items-center gap-2">
                                <Crown className="w-5 h-5 text-amber-500" />
                                <CardTitle style={{ color: "#07593f" }}>Niveis de Clientes</CardTitle>
                            </div>
                            <Button size="sm" onClick={() => { setEditingTier(null); setTierForm({ nome: "", coroas_minimas: 0, multiplicador_coroas: 1.0, ordem: (tiers.length || 0) + 1 }); setIsTierModalOpen(true); }} style={{ backgroundColor: "#07593f" }}>
                                <Plus className="w-4 h-4 mr-1" />Novo Nivel
                            </Button>
                        </CardHeader>
                        <CardContent className="p-4">
                            {loadingTiers ? (
                                <div className="flex justify-center py-8"><Loader2 className="w-6 h-6 animate-spin" /></div>
                            ) : tiers.length === 0 ? (
                                <p className="text-center text-gray-400 py-8">Nenhum nivel cadastrado. Crie o primeiro!</p>
                            ) : (
                                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                                    {tiers.map((tier, idx) => {
                                        const cores = TIER_CORES[Math.min(idx, 3)];
                                        return (
                                            <div key={tier.id} className={`relative p-4 rounded-xl border-2 text-center ${cores.bg} ${cores.border}`}>
                                                <h4 className={`font-bold text-lg ${cores.text}`}>{tier.nome}</h4>
                                                <p className="text-xs text-gray-500 mt-1">A partir de</p>
                                                <p className={`text-2xl font-black ${cores.text}`}>{tier.coroas_minimas}</p>
                                                <p className="text-xs text-gray-500">Coroas</p>
                                                <Badge className="mt-2 bg-white border" style={{ color: "#07593f", borderColor: "#07593f" }}>
                                                    {tier.multiplicador_coroas}x multiplicador
                                                </Badge>
                                                <div className="absolute top-2 right-2 flex gap-1">
                                                    <button className="text-gray-400 hover:text-blue-500" onClick={() => openEditTier(tier)}>
                                                        <Pencil className="w-3 h-3" />
                                                    </button>
                                                    <button className="text-gray-400 hover:text-red-500" onClick={() => deleteTierMutation.mutate(tier.id)}>
                                                        <Trash2 className="w-3 h-3" />
                                                    </button>
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            )}
                            <Alert className="mt-4 bg-blue-50 border-blue-200">
                                <AlertCircle className="w-4 h-4 text-blue-600" />
                                <AlertDescription className="text-sm text-blue-700">
                                    O multiplicador e aplicado automaticamente ao total de Coroas ganhas em compras. Ex: nivel 1.5x = cliente ganha 50% mais Coroas.
                                </AlertDescription>
                            </Alert>
                        </CardContent>
                    </Card>
                </TabsContent>

                {/* ============================================================ */}
                {/* TAB 4: RESGATES                                               */}
                {/* ============================================================ */}
                <TabsContent value="resgates" className="space-y-4 mt-4">
                    {/* Resgate direto por desconto */}
                    <Card className="border-0 shadow">
                        <CardHeader className="border-b bg-green-50">
                            <div className="flex items-center gap-2">
                                <DollarSign className="w-5 h-5 text-green-600" />
                                <CardTitle className="text-green-800">Desconto por Coroas</CardTitle>
                            </div>
                        </CardHeader>
                        <CardContent className="p-6">
                            <div className="grid md:grid-cols-2 gap-4">
                                <div>
                                    <Label className="mb-2 block">Valor por Coroa (R$)</Label>
                                    <Input type="number" step="0.01" min="0.01" value={config.desconto_por_coroa}
                                        onChange={(e) => setConfig(p => ({ ...p, desconto_por_coroa: e.target.value }))} />
                                    <p className="text-xs text-gray-500 mt-1">Ex: 0.10 = cada Coroa vale R$ 0,10</p>
                                </div>
                                <div>
                                    <Label className="mb-2 block">Minimo de Coroas para Resgatar</Label>
                                    <Input type="number" min="1" value={config.reward_threshold}
                                        onChange={(e) => setConfig(p => ({ ...p, reward_threshold: e.target.value }))} />
                                    <p className="text-xs text-gray-500 mt-1">Quantidade minima para solicitar resgate</p>
                                </div>
                            </div>
                            <div className="mt-4 p-3 bg-green-50 rounded-lg border border-green-200">
                                <p className="text-sm text-green-700">
                                    Exemplo: <strong>{config.reward_threshold || 100} Coroas</strong> = <strong className="text-green-800">R$ {((config.reward_threshold || 100) * (config.desconto_por_coroa || 0.10)).toFixed(2)} de desconto</strong>
                                </p>
                            </div>
                            <div className="flex justify-end mt-4">
                                <Button onClick={saveConfig} disabled={savingConfig} style={{ backgroundColor: "#07593f" }}>
                                    {savingConfig ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                                    Salvar
                                </Button>
                            </div>
                        </CardContent>
                    </Card>

                    {/* Catalogo de recompensas */}
                    <Card className="border-0 shadow">
                        <CardHeader className="border-b flex-row items-center justify-between">
                            <div className="flex items-center gap-3">
                                <Gift className="w-5 h-5 text-purple-600" />
                                <div>
                                    <CardTitle style={{ color: "#07593f" }}>Catalogo de Recompensas</CardTitle>
                                    <CardDescription>Cupons e brindes disponiveis para troca</CardDescription>
                                </div>
                            </div>
                            <Button onClick={() => setIsRewardModalOpen(true)} style={{ backgroundColor: "#07593f" }}>
                                <Plus className="w-4 h-4 mr-2" />Nova Recompensa
                            </Button>
                        </CardHeader>
                        <CardContent className="p-0">
                            {loadingRewards ? (
                                <div className="flex justify-center py-8"><Loader2 className="w-6 h-6 animate-spin" /></div>
                            ) : rewards.length === 0 ? (
                                <div className="text-center py-10 text-gray-400">
                                    <Gift className="w-12 h-12 mx-auto mb-2 opacity-20" />
                                    <p>Nenhuma recompensa cadastrada</p>
                                </div>
                            ) : (
                                <div className="divide-y">
                                    {rewards.map((reward) => {
                                        const isActive = reward.fidelidade_regras?.is_active;
                                        return (
                                            <div key={reward.id} className={`p-4 flex items-center justify-between hover:bg-gray-50 ${!isActive ? "opacity-50" : ""}`}>
                                                <div className="flex items-center gap-3">
                                                    <div className={`w-10 h-10 rounded-lg flex items-center justify-center ${isActive ? "bg-purple-100" : "bg-gray-100"}`}>
                                                        <Gift className={`w-5 h-5 ${isActive ? "text-purple-600" : "text-gray-400"}`} />
                                                    </div>
                                                    <div>
                                                        <div className="flex items-center gap-2">
                                                            <span className="font-bold text-amber-600">{reward.coroas_necessarias} Coroas</span>
                                                            <ArrowRight className="w-3 h-3 text-gray-400" />
                                                            <span className="font-medium">{formatReward(reward.reward_type, reward.value)}</span>
                                                        </div>
                                                        <div className="flex items-center gap-2 mt-1 text-xs text-gray-500">
                                                            <span>{reward.fidelidade_regras?.nome}</span>
                                                            <span>Expira em {reward.expiracao_dias}d</span>
                                                        </div>
                                                    </div>
                                                </div>
                                                <div className="flex items-center gap-2">
                                                    <Switch checked={isActive}
                                                        onCheckedChange={(v) => toggleRewardMutation.mutate({ regraId: reward.fidelidade_regras?.id, is_active: v })} />
                                                    <Button size="sm" variant="ghost" className="text-red-400"
                                                        onClick={() => deleteRewardMutation.mutate(reward.fidelidade_regras?.id)}>
                                                        <Trash2 className="w-4 h-4" />
                                                    </Button>
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            )}
                        </CardContent>
                    </Card>
                </TabsContent>

                {/* ============================================================ */}
                {/* TAB 5: EXPIRACAO                                              */}
                {/* ============================================================ */}
                <TabsContent value="expiracao" className="space-y-4 mt-4">
                    <Card className="border-0 shadow">
                        <CardHeader className="border-b bg-orange-50">
                            <div className="flex items-center gap-2">
                                <Clock className="w-5 h-5 text-orange-600" />
                                <CardTitle className="text-orange-800">Expiracao de Coroas</CardTitle>
                            </div>
                        </CardHeader>
                        <CardContent className="p-6 space-y-4">
                            <div className="flex items-center gap-3">
                                <Switch checked={config.expiracao_ativo}
                                    onCheckedChange={(v) => setConfig(p => ({ ...p, expiracao_ativo: v }))} />
                                <span className="font-medium">Ativar expiracao de Coroas</span>
                            </div>

                            {config.expiracao_ativo && (
                                <div className="p-4 border rounded-xl space-y-4">
                                    <p className="text-sm text-gray-600">
                                        As Coroas expiram se o cliente <strong>nao realizar nenhuma compra</strong> dentro do prazo definido abaixo.
                                    </p>
                                    <div className="flex items-center gap-3">
                                        <Label className="whitespace-nowrap">Expirar apos:</Label>
                                        <Input type="number" min="1" className="w-24" value={config.expiracao_valor}
                                            onChange={(e) => setConfig(p => ({ ...p, expiracao_valor: e.target.value }))} />
                                        <Select value={config.expiracao_unidade}
                                            onValueChange={(v) => setConfig(p => ({ ...p, expiracao_unidade: v }))}>
                                            <SelectTrigger className="w-36"><SelectValue /></SelectTrigger>
                                            <SelectContent>
                                                {UNIDADES.map(u => <SelectItem key={u.value} value={u.value}>{u.label}</SelectItem>)}
                                            </SelectContent>
                                        </Select>
                                        <span className="text-sm text-gray-500">sem comprar</span>
                                    </div>
                                    <div className="p-3 bg-orange-50 rounded-lg border border-orange-200">
                                        <p className="text-sm text-orange-700">
                                            Cliente que ficar {config.expiracao_valor} {UNIDADES.find(u => u.value === config.expiracao_unidade)?.label?.toLowerCase() || "meses"} sem comprar perdera todas as Coroas acumuladas.
                                        </p>
                                    </div>
                                </div>
                            )}

                            {!config.expiracao_ativo && (
                                <div className="p-4 bg-gray-50 rounded-xl border text-sm text-gray-500">
                                    Com a expiracao desativada, as Coroas acumuladas nunca vencem.
                                </div>
                            )}
                        </CardContent>
                    </Card>
                    <div className="flex justify-end">
                        <Button onClick={saveConfig} disabled={savingConfig} style={{ backgroundColor: "#07593f" }}>
                            {savingConfig ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                            Salvar Configuracoes
                        </Button>
                    </div>
                </TabsContent>

                {/* ============================================================ */}
                {/* TAB 6: CAMPANHAS                                              */}
                {/* ============================================================ */}
                <TabsContent value="campanhas" className="space-y-4 mt-4">
                    <Card className="border-0 shadow">
                        <CardHeader className="border-b bg-violet-50">
                            <div className="flex items-center gap-2">
                                <Megaphone className="w-5 h-5 text-violet-600" />
                                <CardTitle className="text-violet-800">Conceder Coroas Manualmente</CardTitle>
                            </div>
                        </CardHeader>
                        <CardContent className="p-6 space-y-4">
                            <div className="grid md:grid-cols-2 gap-4">
                                <div>
                                    <Label className="mb-2 block">Quantidade de Coroas</Label>
                                    <Input type="number" placeholder="Ex: 50 (use negativo para deduzir)"
                                        value={campanhaQtd} onChange={(e) => setCampanhaQtd(e.target.value)} />
                                </div>
                                <div>
                                    <Label className="mb-2 block">Motivo</Label>
                                    <Input placeholder="Ex: Campanha de inauguracao"
                                        value={campanhaMotivo} onChange={(e) => setCampanhaMotivo(e.target.value)} />
                                </div>
                            </div>

                            <div className="grid md:grid-cols-2 gap-4">
                                <div>
                                    <Label className="mb-2 block">Buscar cliente por nome</Label>
                                    <div className="relative">
                                        <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                                        <Input className="pl-9" placeholder="Nome do cliente..."
                                            value={campanhaClienteQ} onChange={(e) => setCampanhaClienteQ(e.target.value)} />
                                    </div>
                                </div>
                                <div>
                                    <Label className="mb-2 block">Filtrar por nivel</Label>
                                    <Select value={campanhaFiltroTier} onValueChange={setCampanhaFiltroTier}>
                                        <SelectTrigger><SelectValue /></SelectTrigger>
                                        <SelectContent>
                                            <SelectItem value="todos">Todos os clientes</SelectItem>
                                            {tiers.map(t => <SelectItem key={t.id} value={t.id}>{t.nome}</SelectItem>)}
                                        </SelectContent>
                                    </Select>
                                </div>
                            </div>

                            {clientesCampanha.length > 0 && (
                                <div className="border rounded-xl divide-y max-h-64 overflow-y-auto">
                                    {clientesCampanha.map(c => (
                                        <div key={c.id} className="flex items-center justify-between px-4 py-3 hover:bg-gray-50">
                                            <div>
                                                <p className="font-medium text-sm">{c.nome_completo}</p>
                                                <p className="text-xs text-amber-600">{c.coroas || 0} Coroas atuais</p>
                                            </div>
                                            <Button size="sm" style={{ backgroundColor: "#07593f" }}
                                                disabled={campanhaLoading}
                                                onClick={() => handleConcederCoroas(c.id, c.nome_completo)}>
                                                {campanhaLoading ? <Loader2 className="w-3 h-3 animate-spin" /> : "Conceder"}
                                            </Button>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </CardContent>
                    </Card>

                    {/* Historico de campanhas */}
                    <Card className="border-0 shadow">
                        <CardHeader className="border-b flex-row items-center gap-2">
                            <History className="w-5 h-5 text-gray-500" />
                            <CardTitle className="text-gray-700">Historico de Campanhas</CardTitle>
                        </CardHeader>
                        <CardContent className="p-0">
                            {historicoCampanha.length === 0 ? (
                                <p className="text-center text-gray-400 py-8">Nenhuma campanha registrada</p>
                            ) : (
                                <div className="divide-y max-h-80 overflow-y-auto">
                                    {historicoCampanha.map(h => (
                                        <div key={h.id} className="flex items-center justify-between px-4 py-3">
                                            <div>
                                                <p className="font-medium text-sm">{h.clientes?.nome_completo}</p>
                                                <p className="text-xs text-gray-500">{h.descricao}</p>
                                            </div>
                                            <div className="text-right">
                                                <p className={`font-bold ${h.coroas > 0 ? "text-green-600" : "text-red-500"}`}>
                                                    {h.coroas > 0 ? "+" : ""}{h.coroas} Coroas
                                                </p>
                                                <p className="text-xs text-gray-400">
                                                    {new Date(h.created_at).toLocaleDateString("pt-BR")}
                                                </p>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </CardContent>
                    </Card>
                </TabsContent>
            </Tabs>

            {/* ============================================================ */}
            {/* MODAL: NOVA RECOMPENSA                                        */}
            {/* ============================================================ */}
            <Dialog open={isRewardModalOpen} onOpenChange={setIsRewardModalOpen}>
                <DialogContent className="max-w-lg">
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-2">
                            <Gift className="w-5 h-5 text-purple-500" />Nova Recompensa
                        </DialogTitle>
                        <DialogDescription>Defina uma recompensa do catalogo que o cliente pode resgatar</DialogDescription>
                    </DialogHeader>
                    <form onSubmit={(e) => { e.preventDefault(); if (!rewardForm.nome.trim()) return toast.error("Nome e obrigatorio"); if (!rewardForm.coroas_necessarias) return toast.error("Coroas necessarias e obrigatorio"); createRewardMutation.mutate(rewardForm); }} className="space-y-4">
                        <div>
                            <Label>Nome da Recompensa *</Label>
                            <Input value={rewardForm.nome} onChange={(e) => setRewardForm(p => ({ ...p, nome: e.target.value }))} placeholder="Ex: Cupom 10% de Desconto" />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <Label>Coroas Necessarias *</Label>
                                <Input type="number" min="1" value={rewardForm.coroas_necessarias}
                                    onChange={(e) => setRewardForm(p => ({ ...p, coroas_necessarias: e.target.value }))} placeholder="Ex: 100" />
                            </div>
                            <div>
                                <Label>Tipo</Label>
                                <Select value={rewardForm.reward_type} onValueChange={(v) => setRewardForm(p => ({ ...p, reward_type: v }))}>
                                    <SelectTrigger><SelectValue /></SelectTrigger>
                                    <SelectContent>
                                        {REWARD_TYPES.map(r => <SelectItem key={r.value} value={r.value}>{r.label}</SelectItem>)}
                                    </SelectContent>
                                </Select>
                            </div>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <Label>Valor</Label>
                                <Input type="number" value={rewardForm.value}
                                    onChange={(e) => setRewardForm(p => ({ ...p, value: e.target.value }))}
                                    disabled={["frete_gratis", "item_gratis"].includes(rewardForm.reward_type)}
                                    placeholder={rewardForm.reward_type?.includes("percentual") ? "Ex: 10" : "Ex: 50"} />
                            </div>
                            <div>
                                <Label>Expiracao (dias)</Label>
                                <Input type="number" min="1" value={rewardForm.expiracao_dias}
                                    onChange={(e) => setRewardForm(p => ({ ...p, expiracao_dias: e.target.value }))} />
                            </div>
                        </div>
                        <div className="flex items-center gap-3 p-3 bg-gray-50 rounded-lg">
                            <Checkbox id="dc" checked={rewardForm.desconta_coroas}
                                onCheckedChange={(v) => setRewardForm(p => ({ ...p, desconta_coroas: v }))} />
                            <label htmlFor="dc" className="text-sm cursor-pointer">Descontar Coroas ao resgatar</label>
                        </div>
                        <div>
                            <Label>Mensagem para o Cliente</Label>
                            <Input value={rewardForm.mensagem_cliente}
                                onChange={(e) => setRewardForm(p => ({ ...p, mensagem_cliente: e.target.value }))}
                                placeholder="Parabens! Voce ganhou..." />
                        </div>
                        <DialogFooter>
                            <Button type="button" variant="outline" onClick={() => setIsRewardModalOpen(false)}>Cancelar</Button>
                            <Button type="submit" disabled={createRewardMutation.isPending} style={{ backgroundColor: "#07593f" }}>
                                {createRewardMutation.isPending ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                                Criar Recompensa
                            </Button>
                        </DialogFooter>
                    </form>
                </DialogContent>
            </Dialog>

            {/* ============================================================ */}
            {/* MODAL: TIER                                                   */}
            {/* ============================================================ */}
            <Dialog open={isTierModalOpen} onOpenChange={setIsTierModalOpen}>
                <DialogContent className="max-w-md">
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-2">
                            <Crown className="w-5 h-5 text-amber-500" />{editingTier ? "Editar Nivel" : "Novo Nivel"}
                        </DialogTitle>
                    </DialogHeader>
                    <div className="space-y-4">
                        <div>
                            <Label>Nome do Nivel *</Label>
                            <Input value={tierForm.nome} onChange={(e) => setTierForm(p => ({ ...p, nome: e.target.value }))} placeholder="Ex: Prata ou Ouro" />
                            <div className="flex gap-2 mt-2">
                                <button
                                    type="button"
                                    onClick={() => setTierForm(p => ({ ...p, nome: "Prata", coroas_minimas: 100, multiplicador_coroas: 1.2, ordem: 1 }))}
                                    className="text-xs bg-slate-100 dark:bg-neutral-800 text-slate-700 dark:text-slate-300 px-2 py-1 rounded border border-slate-200 dark:border-neutral-700 hover:bg-slate-200"
                                >
                                    Sugestão: Prata (100 pts / 1.2x)
                                </button>
                                <button
                                    type="button"
                                    onClick={() => setTierForm(p => ({ ...p, nome: "Ouro", coroas_minimas: 500, multiplicador_coroas: 1.5, ordem: 2 }))}
                                    className="text-xs bg-amber-50 dark:bg-amber-950/40 text-amber-800 dark:text-amber-300 px-2 py-1 rounded border border-amber-200 dark:border-amber-800 hover:bg-amber-100"
                                >
                                    Sugestão: Ouro (500 pts / 1.5x)
                                </button>
                            </div>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <Label>Coroas Minimas</Label>
                                <Input type="number" min="0" value={tierForm.coroas_minimas}
                                    onChange={(e) => setTierForm(p => ({ ...p, coroas_minimas: e.target.value }))} />
                            </div>
                            <div>
                                <Label>Multiplicador de Coroas</Label>
                                <Input type="number" step="0.1" min="1.0" value={tierForm.multiplicador_coroas}
                                    onChange={(e) => setTierForm(p => ({ ...p, multiplicador_coroas: e.target.value }))} />
                                <p className="text-xs text-gray-500 mt-1">Ex: 1.5 = 50% a mais</p>
                            </div>
                        </div>
                        <div>
                            <Label>Ordem de exibicao</Label>
                            <Input type="number" min="1" value={tierForm.ordem}
                                onChange={(e) => setTierForm(p => ({ ...p, ordem: e.target.value }))} />
                        </div>
                    </div>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setIsTierModalOpen(false)}>Cancelar</Button>
                        <Button disabled={saveTierMutation.isPending} style={{ backgroundColor: "#07593f" }}
                            onClick={() => saveTierMutation.mutate({ ...tierForm, id: editingTier?.id })}>
                            {saveTierMutation.isPending ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                            Salvar Nivel
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* ============================================================ */}
            {/* MODAL: CATEGORIA BONUS                                        */}
            {/* ============================================================ */}
            <Dialog open={isCatModalOpen} onOpenChange={setIsCatModalOpen}>
                <DialogContent className="max-w-sm">
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-2">
                            <Package className="w-5 h-5 text-orange-500" />Categoria com Bonus
                        </DialogTitle>
                    </DialogHeader>
                    <div className="space-y-4">
                        <div>
                            <Label>Nome da Categoria *</Label>
                            <Input value={catForm.categoria} onChange={(e) => setCatForm(p => ({ ...p, categoria: e.target.value }))} placeholder="Ex: Sofas, Camas, Armarios" />
                            <p className="text-xs text-gray-500 mt-1">Deve corresponder a categoria dos produtos</p>
                        </div>
                        <div className="grid grid-cols-2 gap-3">
                            <div>
                                <Label>Coroas Extras</Label>
                                <Input type="number" min="1" value={catForm.coroas_bonus}
                                    onChange={(e) => setCatForm(p => ({ ...p, coroas_bonus: e.target.value }))} />
                            </div>
                            <div>
                                <Label>Multiplicador</Label>
                                <Input type="number" step="0.1" min="1.0" value={catForm.multiplicador}
                                    onChange={(e) => setCatForm(p => ({ ...p, multiplicador: e.target.value }))} />
                            </div>
                        </div>
                    </div>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setIsCatModalOpen(false)}>Cancelar</Button>
                        <Button disabled={saveCatMutation.isPending} style={{ backgroundColor: "#07593f" }}
                            onClick={() => { if (!catForm.categoria.trim()) return toast.error("Categoria obrigatoria"); saveCatMutation.mutate(catForm); }}>
                            {saveCatMutation.isPending ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
                            Adicionar
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
}

import React from "react";
import { base44 } from "@/api/base44Client";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
    Package, User, MapPin, Phone, Calendar, Clock,
    CheckCircle, AlertCircle, Wrench
} from "lucide-react";

export default function MontadorTerceirizadoTab() {
    const { data: montagens = [], isLoading } = useQuery({
        queryKey: ['montagens-terceirizadas'],
        queryFn: async () => {
            const todas = await base44.entities.MontagemItem.list('-created_at');
            return todas.filter(m => m.tipo_montagem === 'terceirizada');
        }
    });

    const { data: montadores = [] } = useQuery({
        queryKey: ['montadores'],
        queryFn: () => base44.entities.Montador.list('nome')
    });

    const getStatusBadge = (status) => {
        const config = {
            pendente: { label: 'Pendente', className: 'bg-yellow-100 text-yellow-800' },
            agendada: { label: 'Agendada', className: 'bg-blue-100 text-blue-800' },
            confirmada: { label: 'Confirmada', className: 'bg-green-100 text-green-800' },
            em_andamento: { label: 'A Caminho', className: 'bg-purple-100 text-purple-800' },
            concluida: { label: 'Concluída', className: 'bg-gray-100 text-gray-800' },
            cancelada: { label: 'Cancelada', className: 'bg-red-100 text-red-800' }
        };
        return config[status] || { label: status, className: 'bg-gray-100 text-gray-600' };
    };

    const formatarData = (dataStr) => {
        if (!dataStr) return "A definir";
        const data = new Date(dataStr);
        return data.toLocaleDateString('pt-BR', { weekday: 'short', day: '2-digit', month: '2-digit' });
    };

    const montagensPendentes = montagens.filter(m => m.status === 'pendente');
    const montagensAgendadas = montagens.filter(m => ['agendada', 'confirmada', 'em_andamento'].includes(m.status));
    const montagensConcluidas = montagens.filter(m => m.status === 'concluida');

    if (isLoading) {
        return (
            <div className="flex items-center justify-center h-64">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-green-600" />
            </div>
        );
    }

    return (
        <div className="space-y-6">
            {/* Resumo */}
            <div className="grid grid-cols-3 gap-4">
                <Card className="bg-yellow-50 border-yellow-200">
                    <CardContent className="p-4 text-center">
                        <p className="text-3xl font-bold text-yellow-600">{montagensPendentes.length}</p>
                        <p className="text-sm text-yellow-700">Pendentes</p>
                    </CardContent>
                </Card>
                <Card className="bg-blue-50 border-blue-200">
                    <CardContent className="p-4 text-center">
                        <p className="text-3xl font-bold text-blue-600">{montagensAgendadas.length}</p>
                        <p className="text-sm text-blue-700">Agendadas</p>
                    </CardContent>
                </Card>
                <Card className="bg-green-50 border-green-200">
                    <CardContent className="p-4 text-center">
                        <p className="text-3xl font-bold text-green-600">{montagensConcluidas.length}</p>
                        <p className="text-sm text-green-700">Concluídas</p>
                    </CardContent>
                </Card>
            </div>

            {/* Lista de Montagens Pendentes */}
            <div>
                <h3 className="font-bold text-lg text-gray-900 dark:text-white mb-3 flex items-center gap-2">
                    <AlertCircle className="w-5 h-5 text-yellow-500" />
                    Aguardando Montador
                </h3>

                {montagensPendentes.length === 0 ? (
                    <Card className="p-8 text-center bg-gray-50">
                        <CheckCircle className="w-12 h-12 mx-auto text-green-400 mb-3" />
                        <p className="text-gray-500">Todas as montagens foram atribuídas!</p>
                    </Card>
                ) : (
                    <div className="grid gap-3 md:grid-cols-2 lg:grid-cols-3">
                        {montagensPendentes.map(montagem => (
                            <Card key={montagem.id} className="border-l-4 border-l-yellow-500">
                                <CardContent className="p-4">
                                    <div className="flex items-start justify-between mb-3">
                                        <div>
                                            <p className="font-bold text-gray-900">#{montagem.numero_pedido}</p>
                                            <p className="text-sm text-gray-600">{montagem.produto_nome}</p>
                                            <p className="text-xs text-gray-500">Qtd: {montagem.quantidade}</p>
                                        </div>
                                        <Badge className={getStatusBadge(montagem.status).className}>
                                            {getStatusBadge(montagem.status).label}
                                        </Badge>
                                    </div>

                                    <div className="space-y-1 text-sm text-gray-600">
                                        <div className="flex items-center gap-2">
                                            <User className="w-3 h-3" />
                                            <span>{montagem.cliente_nome}</span>
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <Phone className="w-3 h-3" />
                                            <span>{montagem.cliente_telefone}</span>
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <MapPin className="w-3 h-3" />
                                            <span className="line-clamp-1">{montagem.endereco}</span>
                                        </div>
                                    </div>
                                </CardContent>
                            </Card>
                        ))}
                    </div>
                )}
            </div>

            {/* Lista de Montagens Agendadas */}
            <div>
                <h3 className="font-bold text-lg text-gray-900 dark:text-white mb-3 flex items-center gap-2">
                    <Calendar className="w-5 h-5 text-blue-500" />
                    Montagens Agendadas
                </h3>

                {montagensAgendadas.length === 0 ? (
                    <Card className="p-6 text-center bg-gray-50">
                        <p className="text-gray-500">Nenhuma montagem agendada no momento</p>
                    </Card>
                ) : (
                    <div className="grid gap-3 md:grid-cols-2 lg:grid-cols-3">
                        {montagensAgendadas.map(montagem => {
                            const montador = montadores.find(m => m.id === montagem.montador_id);
                            return (
                                <Card key={montagem.id} className="border-l-4 border-l-blue-500">
                                    <CardContent className="p-4">
                                        <div className="flex items-start justify-between mb-3">
                                            <div>
                                                <p className="font-bold text-gray-900">#{montagem.numero_pedido}</p>
                                                <p className="text-sm text-gray-600">{montagem.produto_nome}</p>
                                            </div>
                                            <Badge className={getStatusBadge(montagem.status).className}>
                                                {getStatusBadge(montagem.status).label}
                                            </Badge>
                                        </div>

                                        <div className="space-y-1 text-sm text-gray-600">
                                            <div className="flex items-center gap-2">
                                                <Calendar className="w-3 h-3" />
                                                <span className="font-medium">{formatarData(montagem.data_agendada)}</span>
                                                {montagem.horario_agendado && (
                                                    <span>às {montagem.horario_agendado}</span>
                                                )}
                                            </div>
                                            <div className="flex items-center gap-2">
                                                <Wrench className="w-3 h-3" />
                                                <span>{montador?.nome || 'Montador não identificado'}</span>
                                            </div>
                                            <div className="flex items-center gap-2">
                                                <User className="w-3 h-3" />
                                                <span>{montagem.cliente_nome}</span>
                                            </div>
                                        </div>
                                    </CardContent>
                                </Card>
                            );
                        })}
                    </div>
                )}
            </div>
        </div>
    );
}

import React, { useState } from "react";
import { base44 } from "@/api/base44Client";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Plus, MessageCircle, Calendar, User, Clock } from "lucide-react";
import MontagemModal from "./MontagemModal";

export default function MontagemAgendamentos({ montagens, valores }) {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingMontagem, setEditingMontagem] = useState(null);
  
  const queryClient = useQueryClient();

  const { data: vendas } = useQuery({
    queryKey: ['vendas'],
    queryFn: () => base44.entities.Venda.list('-created_date'),
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, data }) => base44.entities.Montagem.update(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['montagens'] });
    },
  });

  const enviarWhatsApp = (montagem) => {
    const mensagem = `Olá ${montagem.cliente_nome}! Sua montagem foi agendada para ${new Date(montagem.data_montagem).toLocaleDateString('pt-BR')}, ${montagem.horario_montagem}.

> Montador: ${montagem.montador}`;

    const telefone = montagem.cliente_telefone?.replace(/\D/g, '');
    const url = `https://wa.me/55${telefone}?text=${encodeURIComponent(mensagem)}`;
    
    window.open(url, '_blank');
    
    // Marcar como enviado
    updateMutation.mutate({
      id: montagem.id,
      data: { ...montagem, whatsapp_enviado: true }
    });
  };

  const getStatusColor = (status) => {
    const colors = {
      'Pendente': 'bg-yellow-100 text-yellow-800',
      'Agendada': 'bg-blue-100 text-blue-800',
      'Concluída': 'bg-green-100 text-green-800',
      'Cancelada': 'bg-red-100 text-red-800'
    };
    return colors[status] || '';
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold" style={{ color: '#07593f' }}>
            Agendamentos de Montagem
          </h2>
          <p style={{ color: '#8B8B8B' }}>
            {montagens.length} montagem(ns) cadastrada(s)
          </p>
        </div>
        <Button
          onClick={() => {
            setEditingMontagem(null);
            setIsModalOpen(true);
          }}
          style={{ background: 'linear-gradient(135deg, #f38a4c 0%, #f5a164 100%)' }}
        >
          <Plus className="w-4 h-4 mr-2" />
          Nova Montagem
        </Button>
      </div>

      <div className="grid gap-4">
        {montagens.map((montagem) => (
          <Card key={montagem.id} className="border-0 shadow-lg hover:shadow-xl transition-shadow">
            <CardContent className="p-6">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div className="flex-1">
                  <div className="flex items-center gap-3 mb-3">
                    <h3 className="font-bold text-lg" style={{ color: '#07593f' }}>
                      Pedido #{montagem.numero_pedido}
                    </h3>
                    <Badge className={getStatusColor(montagem.status)}>
                      {montagem.status}
                    </Badge>
                  </div>

                  <div className="grid md:grid-cols-2 gap-3 text-sm">
                    <div className="flex items-center gap-2" style={{ color: '#8B8B8B' }}>
                      <User className="w-4 h-4" />
                      <span>Cliente: <strong>{montagem.cliente_nome}</strong></span>
                    </div>
                    <div className="flex items-center gap-2" style={{ color: '#8B8B8B' }}>
                      <Calendar className="w-4 h-4" />
                      <span>Data: <strong>{new Date(montagem.data_montagem).toLocaleDateString('pt-BR')}</strong></span>
                    </div>
                    <div className="flex items-center gap-2" style={{ color: '#8B8B8B' }}>
                      <Clock className="w-4 h-4" />
                      <span>Horário: <strong>{montagem.horario_montagem}</strong></span>
                    </div>
                    <div className="flex items-center gap-2" style={{ color: '#8B8B8B' }}>
                      <User className="w-4 h-4" />
                      <span>Montador: <strong>{montagem.montador}</strong></span>
                    </div>
                  </div>

                  {montagem.itens && montagem.itens.length > 0 && (
                    <div className="mt-3 p-3 rounded-lg" style={{ backgroundColor: '#FAF8F5' }}>
                      <p className="text-sm font-semibold mb-2" style={{ color: '#07593f' }}>
                        Itens para montar:
                      </p>
                      <div className="space-y-1">
                        {montagem.itens.map((item, idx) => (
                          <p key={idx} className="text-sm" style={{ color: '#8B8B8B' }}>
                            • {item.quantidade}x {item.produto_nome} 
                            {item.montagem_externa && ' (Externa)'}
                          </p>
                        ))}
                      </div>
                    </div>
                  )}

                  {montagem.observacoes && (
                    <p className="text-sm mt-2" style={{ color: '#8B8B8B' }}>
                      <strong>Obs:</strong> {montagem.observacoes}
                    </p>
                  )}
                </div>

                <div className="flex flex-col gap-2">
                  {montagem.status === 'Agendada' && !montagem.whatsapp_enviado && (
                    <Button
                      onClick={() => enviarWhatsApp(montagem)}
                      className="w-full md:w-auto"
                      style={{ background: '#25D366' }}
                    >
                      <MessageCircle className="w-4 h-4 mr-2" />
                      Enviar WhatsApp
                    </Button>
                  )}
                  {montagem.whatsapp_enviado && (
                    <Badge variant="outline" className="text-green-600 border-green-600">
                      ✓ WhatsApp Enviado
                    </Badge>
                  )}
                  <Button
                    variant="outline"
                    onClick={() => {
                      setEditingMontagem(montagem);
                      setIsModalOpen(true);
                    }}
                  >
                    Editar
                  </Button>
                </div>
              </div>
            </CardContent>
          </Card>
        ))}

        {montagens.length === 0 && (
          <Card className="border-0 shadow-lg">
            <CardContent className="p-12 text-center">
              <Calendar className="w-16 h-16 mx-auto mb-4 opacity-20" style={{ color: '#07593f' }} />
              <p className="text-xl" style={{ color: '#8B8B8B' }}>
                Nenhuma montagem agendada
              </p>
            </CardContent>
          </Card>
        )}
      </div>

      <MontagemModal
        isOpen={isModalOpen}
        onClose={() => {
          setIsModalOpen(false);
          setEditingMontagem(null);
        }}
        montagem={editingMontagem}
        vendas={vendas}
        valores={valores}
      />
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { base44 } from "@/api/base44Client";
import { useMutation, useQueryClient, useQuery } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Checkbox } from "@/components/ui/checkbox";
import { whatsappService } from "@/services/whatsappService";
import { useTenant } from "@/contexts/TenantContext";
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

export default function MontagemModal({ isOpen, onClose, montagem, vendas, valores }) {
  const { isPaidModuleActive } = useTenant();
  const [formData, setFormData] = useState({
    venda_id: "",
    data_montagem: "",
    horario_montagem: "09:00",
    montador_id: "", // Changed from 'montador' string to ID
    status: "Agendada",
    observacoes: "",
    itens: []
  });

  const queryClient = useQueryClient();

  // Fetch assemblers dynamically
  const { data: montadores = [] } = useQuery({
    queryKey: ['montadores'],
    queryFn: () => base44.entities.Montador.list('nome'),
    staleTime: 1000 * 60 * 5 // Cache for 5 mins
  });

  // Fetch existing assemblies for the selected date to check availability
  const { data: montagensDoDia = [] } = useQuery({
    queryKey: ['montagens', formData.data_montagem, formData.montador_id],
    queryFn: async () => {
      if (!formData.data_montagem || !formData.montador_id) return [];
      return base44.entities.Montagem.filter({
        data_montagem: formData.data_montagem,
        montador_id: formData.montador_id
      });
    },
    enabled: !!formData.data_montagem && !!formData.montador_id
  });

  useEffect(() => {
    if (montagem) {
      setFormData(montagem);
    } else {
      setFormData({
        venda_id: "",
        data_montagem: "",
        horario_montagem: "09:00",
        montador_id: "",
        status: "Agendada",
        observacoes: "",
        itens: []
      });
    }
  }, [montagem, isOpen]);

  const notifyCliente = async (dadosMontagem) => {
    if (!isPaidModuleActive('whatsapp')) {
      console.log("Notificação de montagem pulada: módulo 'whatsapp' inativo.");
      return;
    }
    if (dadosMontagem.status !== 'Agendada') return;

    try {
      const venda = vendas.find(v => v.id === dadosMontagem.venda_id);
      const montador = montadores.find(m => m.id === dadosMontagem.montador_id);

      if (!venda || !montador) {
        console.warn("Venda ou Montador não encontrados para notificação");
        return;
      }

      const dadosCliente = {
        nome: venda.cliente_nome,
        telefone: venda.cliente_telefone
      };

      await whatsappService.sendAssemblyConfirmation(dadosCliente, dadosMontagem, montador);
      toast.success("Notificação enviada para o cliente via WhatsApp!");
    } catch (error) {
      console.error("Erro ao enviar notificação:", error);
    }
  };

  const createMutation = useMutation({
    mutationFn: (data) => base44.entities.Montagem.create(data),
    onSuccess: (newItem) => {
      queryClient.invalidateQueries({ queryKey: ['montagens'] });
      notifyCliente(newItem);
      onClose();
    },
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, data }) => base44.entities.Montagem.update(id, data),
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ['montagens'] });
      // Optionally notify on update too, if critical fields changed
      if (variables.data.status === 'Agendada') {
        notifyCliente({ ...variables.data, id: variables.id });
      }
      onClose();
    },
  });

  const handleVendaChange = (vendaId) => {
    const venda = vendas.find(v => v.id === vendaId);
    if (venda) {
      const itensComValores = (venda.itens || []).map(item => {
        const valorRef = valores.find(v =>
          v.modelo_movel.toLowerCase().includes(item.produto_nome.toLowerCase())
        );

        return {
          produto_nome: item.produto_nome,
          quantidade: item.quantidade,
          valor_montagem: valorRef?.valor_montagem || 0,
          montagem_externa: false
        };
      });

      setFormData({
        ...formData,
        venda_id: vendaId,
        numero_pedido: venda.numero_pedido,
        cliente_nome: venda.cliente_nome,
        cliente_telefone: venda.cliente_telefone,
        endereco_montagem: venda.endereco_montagem || "",
        itens: itensComValores
      });
    }
  };

  const handleItemChange = (index, field, value) => {
    const newItens = [...formData.itens];
    newItens[index] = { ...newItens[index], [field]: value };

    // Se mudou montagem_externa, atualizar valor
    if (field === 'montagem_externa') {
      const valorRef = valores.find(v =>
        v.modelo_movel.toLowerCase().includes(newItens[index].produto_nome.toLowerCase())
      );

      newItens[index].valor_montagem = value
        ? (valorRef?.valor_montagem_externa || 0)
        : (valorRef?.valor_montagem || 0);
    }

    setFormData({ ...formData, itens: newItens });
  };

  const calcularTotal = () => {
    return formData.itens.reduce((sum, item) =>
      sum + (item.valor_montagem * item.quantidade), 0
    );
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!formData.montador_id) {
      toast.error("Selecione um montador");
      return;
    }

    const dataToSave = {
      ...formData,
      valor_total_montagem: calcularTotal()
    };

    if (montagem) {
      updateMutation.mutate({ id: montagem.id, data: dataToSave });
    } else {
      createMutation.mutate(dataToSave);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>
            {montagem ? 'Editar Montagem' : 'Nova Montagem'}
          </DialogTitle>
          <DialogDescription>
            Configure o agendamento da montagem com o montador
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit}>
          <div className="space-y-4 py-4">
            <div className="grid md:grid-cols-2 gap-4">
              <div>
                <Label htmlFor="venda">Venda/Pedido *</Label>
                <Select
                  value={formData.venda_id}
                  onValueChange={handleVendaChange}
                  required
                  disabled={!!montagem}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Selecione um pedido" />
                  </SelectTrigger>
                  <SelectContent>
                    {vendas.map(venda => (
                      <SelectItem key={venda.id} value={venda.id}>
                        #{venda.numero_pedido} - {venda.cliente_nome}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div>
                <Label htmlFor="montador">Montador *</Label>
                <Select
                  value={formData.montador_id}
                  onValueChange={(value) => setFormData({ ...formData, montador_id: value })}
                  required
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Selecione..." />
                  </SelectTrigger>
                  <SelectContent>
                    {montadores.map(m => (
                      <SelectItem key={m.id} value={m.id}>
                        {m.nome}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="grid md:grid-cols-3 gap-4">
              <div>
                <Label htmlFor="data">Data *</Label>
                <Input
                  id="data"
                  type="date" lang="pt-BR"
                  min={new Date().toISOString().split('T')[0]}
                  value={formData.data_montagem}
                  onChange={(e) => setFormData({ ...formData, data_montagem: e.target.value })}
                  required
                />
              </div>

              <div>
                <Label htmlFor="horario">Horário *</Label>
                <Select
                  value={formData.horario_montagem}
                  onValueChange={(value) => setFormData({ ...formData, horario_montagem: value })}
                  required
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {["08:00", "09:00", "10:00", "11:00", "13:00", "14:00", "15:00", "16:00", "17:00"].map(horario => {
                      // Verificar disponibilidade
                      const isTaken = montagensDoDia?.some(m =>
                        m.montador_id === formData.montador_id &&
                        m.horario_montagem === horario &&
                        m.id !== montagem?.id // Ignora a própria montagem se estiver editando
                      );

                      return (
                        <SelectItem key={horario} value={horario} disabled={isTaken} className={isTaken ? "opacity-50 line-through" : ""}>
                          {horario} {isTaken ? '(Ocupado)' : ''}
                        </SelectItem>
                      );
                    })}
                  </SelectContent>
                </Select>
              </div>

              <div>
                <Label htmlFor="status">Status *</Label>
                <Select
                  value={formData.status}
                  onValueChange={(value) => setFormData({ ...formData, status: value })}
                  required
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="Pendente">Pendente</SelectItem>
                    <SelectItem value="Agendada">Agendada</SelectItem>
                    <SelectItem value="Concluída">Concluída</SelectItem>
                    <SelectItem value="Cancelada">Cancelada</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            {formData.itens.length > 0 && (
              <div className="border rounded-lg p-4" style={{ borderColor: '#E5E0D8' }}>
                <Label className="text-base mb-3 block">Itens para Montagem</Label>
                <div className="space-y-3">
                  {formData.itens.map((item, idx) => (
                    <div key={idx} className="flex items-center gap-3 p-3 rounded-lg" style={{ backgroundColor: '#FAF8F5' }}>
                      <div className="flex-1">
                        <p className="font-semibold" style={{ color: '#07593f' }}>
                          {item.quantidade}x {item.produto_nome}
                        </p>
                        <p className="text-sm" style={{ color: '#8B8B8B' }}>
                          R$ {item.valor_montagem?.toFixed(2)} por unidade
                        </p>
                      </div>
                      <div className="flex items-center gap-2">
                        <Checkbox
                          id={`externa-${idx}`}
                          checked={item.montagem_externa || false}
                          onCheckedChange={(checked) => handleItemChange(idx, 'montagem_externa', checked)}
                        />
                        <Label htmlFor={`externa-${idx}`} className="cursor-pointer text-sm">
                          Externa (+10%)
                        </Label>
                      </div>
                    </div>
                  ))}
                  <div className="text-right pt-2 border-t" style={{ borderColor: '#E5E0D8' }}>
                    <p className="text-lg font-bold" style={{ color: '#07593f' }}>
                      Total: R$ {calcularTotal().toFixed(2)}
                    </p>
                  </div>
                </div>
              </div>
            )}

            <div>
              <Label htmlFor="observacoes">Observações</Label>
              <Textarea
                id="observacoes"
                value={formData.observacoes}
                onChange={(e) => setFormData({ ...formData, observacoes: e.target.value })}
                rows={3}
                placeholder="Informações adicionais sobre a montagem..."
              />
            </div>
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose}>
              Cancelar
            </Button>
            <Button
              type="submit"
              disabled={createMutation.isPending || updateMutation.isPending}
              style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
            >
              {(createMutation.isPending || updateMutation.isPending) ? 'Salvando...' : 'Salvar'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useMemo } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { DollarSign, TrendingUp, Users, Calendar } from "lucide-react";

export default function RelatorioMontadores({ montagens }) {
  const [mesAno, setMesAno] = useState(new Date().toISOString().slice(0, 7));

  const dadosPorMontador = useMemo(() => {
    const montagensMes = montagens.filter(m => 
      m.data_montagem?.slice(0, 7) === mesAno &&
      m.status === 'Concluída'
    );

    const montadores = ['Carlos', 'Luis', 'Guilherme'];
    
    return montadores.map(montador => {
      const montagensMontador = montagensMes.filter(m => m.montador === montador);
      const total = montagensMontador.reduce((sum, m) => sum + (m.valor_total_montagem || 0), 0);
      
      return {
        montador,
        quantidade: montagensMontador.length,
        total,
        montagens: montagensMontador
      };
    });
  }, [montagens, mesAno]);

  const totalGeral = dadosPorMontador.reduce((sum, d) => sum + d.total, 0);
  const totalMontagens = dadosPorMontador.reduce((sum, d) => sum + d.quantidade, 0);

  return (
    <div className="space-y-6">
      <Card className="border-0 shadow-lg">
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="flex items-center gap-2">
              <DollarSign className="w-5 h-5" />
              Fechamento de Montadores
            </CardTitle>
            <div className="w-48">
              <Label htmlFor="mes">Mês/Ano</Label>
              <Input
                id="mes"
                type="month"
                value={mesAno}
                onChange={(e) => setMesAno(e.target.value)}
              />
            </div>
          </div>
        </CardHeader>
        <CardContent>
          <div className="grid md:grid-cols-3 gap-4 mb-6">
            <div className="p-4 rounded-lg text-center" style={{ backgroundColor: '#f0f9ff' }}>
              <DollarSign className="w-8 h-8 mx-auto mb-2" style={{ color: '#07593f' }} />
              <p className="text-sm mb-1" style={{ color: '#8B8B8B' }}>Total a Pagar</p>
              <p className="text-2xl font-bold" style={{ color: '#07593f' }}>
                R$ {totalGeral.toFixed(2)}
              </p>
            </div>
            <div className="p-4 rounded-lg text-center" style={{ backgroundColor: '#FEF3C7' }}>
              <Calendar className="w-8 h-8 mx-auto mb-2" style={{ color: '#f38a4c' }} />
              <p className="text-sm mb-1" style={{ color: '#8B8B8B' }}>Montagens Realizadas</p>
              <p className="text-2xl font-bold" style={{ color: '#f38a4c' }}>
                {totalMontagens}
              </p>
            </div>
            <div className="p-4 rounded-lg text-center" style={{ backgroundColor: '#D1FAE5' }}>
              <TrendingUp className="w-8 h-8 mx-auto mb-2" style={{ color: '#059669' }} />
              <p className="text-sm mb-1" style={{ color: '#8B8B8B' }}>Ticket Médio</p>
              <p className="text-2xl font-bold" style={{ color: '#059669' }}>
                R$ {totalMontagens > 0 ? (totalGeral / totalMontagens).toFixed(2) : '0.00'}
              </p>
            </div>
          </div>

          <div className="space-y-4">
            {dadosPorMontador.map((dados) => (
              <Card key={dados.montador} className="border-2" style={{ borderColor: '#E5E0D8' }}>
                <CardContent className="p-6">
                  <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-3">
                      <div 
                        className="w-12 h-12 rounded-full flex items-center justify-center"
                        style={{ backgroundColor: '#07593f', color: 'white' }}
                      >
                        <Users className="w-6 h-6" />
                      </div>
                      <div>
                        <h3 className="text-xl font-bold" style={{ color: '#07593f' }}>
                          {dados.montador}
                        </h3>
                        <p className="text-sm" style={{ color: '#8B8B8B' }}>
                          {dados.quantidade} montagem(ns) realizada(s)
                        </p>
                      </div>
                    </div>
                    <div className="text-right">
                      <p className="text-sm mb-1" style={{ color: '#8B8B8B' }}>Total a Receber</p>
                      <p className="text-2xl font-bold" style={{ color: '#07593f' }}>
                        R$ {dados.total.toFixed(2)}
                      </p>
                    </div>
                  </div>

                  {dados.montagens.length > 0 && (
                    <div className="space-y-2">
                      <p className="text-sm font-semibold mb-2" style={{ color: '#8B8B8B' }}>
                        Detalhamento:
                      </p>
                      {dados.montagens.map((m, idx) => (
                        <div 
                          key={idx} 
                          className="flex items-center justify-between p-3 rounded-lg"
                          style={{ backgroundColor: '#FAF8F5' }}
                        >
                          <div>
                            <p className="font-semibold" style={{ color: '#07593f' }}>
                              Pedido #{m.numero_pedido} - {m.cliente_nome}
                            </p>
                            <p className="text-sm" style={{ color: '#8B8B8B' }}>
                              {new Date(m.data_montagem).toLocaleDateString('pt-BR')}
                            </p>
                          </div>
                          <Badge style={{ backgroundColor: '#D1FAE5', color: '#065F46' }}>
                            R$ {m.valor_total_montagem?.toFixed(2)}
                          </Badge>
                        </div>
                      ))}
                    </div>
                  )}
                </CardContent>
              </Card>
            ))}
          </div>

          {totalMontagens === 0 && (
            <div className="text-center py-12" style={{ color: '#8B8B8B' }}>
              <Calendar className="w-16 h-16 mx-auto mb-4 opacity-20" />
              <p className="text-xl">Nenhuma montagem concluída neste período</p>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState } from "react";
import { base44 } from "@/api/base44Client";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Plus, Upload, Trash2, Edit } from "lucide-react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";

export default function ValoresMontagem({ valores }) {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingValor, setEditingValor] = useState(null);
  const [importing, setImporting] = useState(false);
  const [formData, setFormData] = useState({
    modelo_movel: "",
    valor_montagem: "",
    valor_montagem_externa: ""
  });

  const queryClient = useQueryClient();

  const createMutation = useMutation({
    mutationFn: (data) => base44.entities.ValorMontagem.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['valores-montagem'] });
      setIsModalOpen(false);
      resetForm();
    },
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, data }) => base44.entities.ValorMontagem.update(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['valores-montagem'] });
      setIsModalOpen(false);
      resetForm();
    },
  });

  const deleteMutation = useMutation({
    mutationFn: (id) => base44.entities.ValorMontagem.delete(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['valores-montagem'] });
    },
  });

  const resetForm = () => {
    setFormData({
      modelo_movel: "",
      valor_montagem: "",
      valor_montagem_externa: ""
    });
    setEditingValor(null);
  };

  const handleEdit = (valor) => {
    setEditingValor(valor);
    setFormData({
      modelo_movel: valor.modelo_movel,
      valor_montagem: valor.valor_montagem.toString(),
      valor_montagem_externa: valor.valor_montagem_externa.toString()
    });
    setIsModalOpen(true);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    
    const dataToSave = {
      modelo_movel: formData.modelo_movel,
      valor_montagem: parseFloat(formData.valor_montagem),
      valor_montagem_externa: parseFloat(formData.valor_montagem_externa),
      ativo: true
    };

    if (editingValor) {
      updateMutation.mutate({ id: editingValor.id, data: dataToSave });
    } else {
      createMutation.mutate(dataToSave);
    }
  };

  const handleImport = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setImporting(true);
    try {
      const text = await file.text();
      const lines = text.split('\n').filter(line => line.trim());
      
      // Pular cabeçalho
      const dataLines = lines.slice(1);
      
      const items = [];
      for (const line of dataLines) {
        const [modelo, valor, valorExterno] = line.split('\t');
        if (modelo && valor && valorExterno) {
          items.push({
            modelo_movel: modelo.trim(),
            valor_montagem: parseFloat(valor.replace(',', '.').replace('R$', '').trim()),
            valor_montagem_externa: parseFloat(valorExterno.replace(',', '.').replace('R$', '').trim()),
            ativo: true
          });
        }
      }

      // Criar em lote
      for (const item of items) {
        await createMutation.mutateAsync(item);
      }

      alert(`${items.length} itens importados com sucesso!`);
    } catch (error) {
      console.error('Erro ao importar:', error);
      alert('Erro ao importar arquivo. Verifique o formato.');
    } finally {
      setImporting(false);
      e.target.value = '';
    }
  };

  return (
    <div className="space-y-6">
      <Card className="border-0 shadow-lg">
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle>Tabela de Valores de Montagem</CardTitle>
            <div className="flex gap-2">
              <label>
                <input
                  type="file"
                  accept=".csv,.txt,.tsv"
                  onChange={handleImport}
                  disabled={importing}
                  className="hidden"
                />
                <Button
                  type="button"
                  variant="outline"
                  disabled={importing}
                  onClick={() => document.querySelector('input[type="file"]').click()}
                >
                  <Upload className="w-4 h-4 mr-2" />
                  {importing ? 'Importando...' : 'Importar CSV'}
                </Button>
              </label>
              <Button
                onClick={() => {
                  resetForm();
                  setIsModalOpen(true);
                }}
                style={{ background: 'linear-gradient(135deg, #f38a4c 0%, #f5a164 100%)' }}
              >
                <Plus className="w-4 h-4 mr-2" />
                Novo Valor
              </Button>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {valores.length > 0 ? (
            <div className="rounded-lg border" style={{ borderColor: '#E5E0D8' }}>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Modelo do Móvel</TableHead>
                    <TableHead className="text-right">Valor Montagem (R$)</TableHead>
                    <TableHead className="text-right">Valor Externa +10% (R$)</TableHead>
                    <TableHead className="text-right">Ações</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {valores.map((valor) => (
                    <TableRow key={valor.id}>
                      <TableCell className="font-medium">{valor.modelo_movel}</TableCell>
                      <TableCell className="text-right">
                        R$ {valor.valor_montagem?.toFixed(2)}
                      </TableCell>
                      <TableCell className="text-right">
                        R$ {valor.valor_montagem_externa?.toFixed(2)}
                      </TableCell>
                      <TableCell className="text-right">
                        <div className="flex justify-end gap-2">
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => handleEdit(valor)}
                          >
                            <Edit className="w-4 h-4" />
                          </Button>
                          <Button
                            size="sm"
                            variant="destructive"
                            onClick={() => {
                              if (confirm('Tem certeza que deseja excluir?')) {
                                deleteMutation.mutate(valor.id);
                              }
                            }}
                            disabled={deleteMutation.isPending}
                          >
                            <Trash2 className="w-4 h-4" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          ) : (
            <div className="text-center py-12" style={{ color: '#8B8B8B' }}>
              <p className="text-xl mb-2">Nenhum valor cadastrado</p>
              <p className="text-sm">Adicione valores manualmente ou importe um arquivo CSV</p>
            </div>
          )}
        </CardContent>
      </Card>

      <Dialog open={isModalOpen} onOpenChange={setIsModalOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>
              {editingValor ? 'Editar Valor' : 'Novo Valor de Montagem'}
            </DialogTitle>
            <DialogDescription>
              Configure os valores para montagem deste móvel
            </DialogDescription>
          </DialogHeader>

          <form onSubmit={handleSubmit}>
            <div className="space-y-4 py-4">
              <div>
                <Label htmlFor="modelo">Modelo do Móvel *</Label>
                <Input
                  id="modelo"
                  value={formData.modelo_movel}
                  onChange={(e) => setFormData({ ...formData, modelo_movel: e.target.value })}
                  placeholder="Ex: Sofá 3 Lugares, Cama Box Queen..."
                  required
                />
              </div>

              <div>
                <Label htmlFor="valor">Valor Montagem (R$) *</Label>
                <Input
                  id="valor"
                  type="number"
                  step="0.01"
                  min="0"
                  value={formData.valor_montagem}
                  onChange={(e) => setFormData({ ...formData, valor_montagem: e.target.value })}
                  placeholder="0.00"
                  required
                />
              </div>

              <div>
                <Label htmlFor="valor_externo">Valor Montagem Externa +10% (R$) *</Label>
                <Input
                  id="valor_externo"
                  type="number"
                  step="0.01"
                  min="0"
                  value={formData.valor_montagem_externa}
                  onChange={(e) => setFormData({ ...formData, valor_montagem_externa: e.target.value })}
                  placeholder="0.00"
                  required
                />
              </div>
            </div>

            <DialogFooter>
              <Button type="button" variant="outline" onClick={() => {
                setIsModalOpen(false);
                resetForm();
              }}>
                Cancelar
              </Button>
              <Button
                type="submit"
                disabled={createMutation.isPending || updateMutation.isPending}
                style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
              >
                {(createMutation.isPending || updateMutation.isPending) ? 'Salvando...' : 'Salvar'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useEffect, useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { base44 } from "@/api/base44Client";
import { Bell, Check, X, AlertCircle, Truck, Package } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { AMBIENTES } from "@/constants/productConstants";

const CATEGORIAS_NOTIFICACAO_PRODUTO = [
  'Sofá',
  'Cama',
  'Mesa',
  'Cadeira',
  'Armário',
  'Estante',
  'Rack',
  'Poltrona',
  'Escrivaninha',
  'Criado-mudo',
  'Buffet',
  'Aparador',
  'Banco',
  'Colchão',
  'Guarda-roupa',
  'Cômoda',
  'Painel',
  'Sapateira',
  'Cristaleira',
  'Balcão',
  'Cabeceira',
  'Box',
  'Penteadeira',
  'Travesseiro',
  'Almofada',
  'Decorações',
  'Utensílios',
  'Outros',
];

const CATEGORIAS_NOTIFICACAO_KEY = 'notificacoes_categorias_ativas';
const AMBIENTES_NOTIFICACAO_KEY = 'notificacoes_ambientes_ativos';

const AMBIENTES_NOTIFICACAO_PRODUTO = Array.from(new Set([
  ...(Array.isArray(AMBIENTES) ? AMBIENTES : []),
  'Área Externa',
]));

const normalizeKey = (value = '') => String(value)
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .trim();

const resolveConfiguredValue = (rawValue, options) => {
  const normalizedRaw = normalizeKey(rawValue);
  if (!normalizedRaw) return '';
  return options.find((option) => normalizeKey(option) === normalizedRaw) || '';
};

const getCategoriaFromNotification = (n) => {
  if (!n) return '';
  return (
    n.categoria_produto ||
    n.categoria ||
    n?.metadata?.categoria ||
    n?.detalhes?.categoria ||
    ''
  );
};

const getAmbienteFromNotification = (n) => {
  if (!n) return '';
  return (
    n.ambiente_produto ||
    n.ambiente ||
    n?.metadata?.ambiente ||
    n?.detalhes?.ambiente ||
    ''
  );
};

const createDefaultCategoriasState = () => {
  const defaults = {};
  CATEGORIAS_NOTIFICACAO_PRODUTO.forEach((categoria) => {
    defaults[categoria] = true;
  });
  return defaults;
};

const createDefaultAmbientesState = () => {
  const defaults = {};
  AMBIENTES_NOTIFICACAO_PRODUTO.forEach((ambiente) => {
    defaults[ambiente] = true;
  });
  return defaults;
};

export default function NotificacoesPanel({ user }) {
  const [open, setOpen] = useState(false);
  const [showCategoriaManager, setShowCategoriaManager] = useState(false);
  const [categoriasAtivas, setCategoriasAtivas] = useState(() => {
    try {
      const raw = localStorage.getItem(CATEGORIAS_NOTIFICACAO_KEY);
      if (!raw) return createDefaultCategoriasState();
      const parsed = JSON.parse(raw);
      return {
        ...createDefaultCategoriasState(),
        ...(parsed || {}),
      };
    } catch {
      return createDefaultCategoriasState();
    }
  });
  const [ambientesAtivos, setAmbientesAtivos] = useState(() => {
    try {
      const raw = localStorage.getItem(AMBIENTES_NOTIFICACAO_KEY);
      if (!raw) return createDefaultAmbientesState();
      const parsed = JSON.parse(raw);
      return {
        ...createDefaultAmbientesState(),
        ...(parsed || {}),
      };
    } catch {
      return createDefaultAmbientesState();
    }
  });
  const queryClient = useQueryClient();

  useEffect(() => {
    localStorage.setItem(CATEGORIAS_NOTIFICACAO_KEY, JSON.stringify(categoriasAtivas));
  }, [categoriasAtivas]);

  useEffect(() => {
    localStorage.setItem(AMBIENTES_NOTIFICACAO_KEY, JSON.stringify(ambientesAtivos));
  }, [ambientesAtivos]);

  const { data: notificacoes = [] } = useQuery({
    queryKey: ['notificacoes', user?.email],
    queryFn: async () => {
      const todas = await base44.entities.Notificacao.list('-created_date');
      return todas.filter(n => 
        n.destinatario_email === user?.email || 
        n.destinatario_cargo === user?.cargo
      );
    },
    refetchInterval: 5000,
    enabled: !!user
  });

  const marcarLidaMutation = useMutation({
    mutationFn: (id) => base44.entities.Notificacao.update(id, {
      lida: true,
      data_leitura: new Date().toISOString()
    }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['notificacoes'] })
  });

  const deletarMutation = useMutation({
    mutationFn: (id) => base44.entities.Notificacao.delete(id),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['notificacoes'] })
  });

  const notificacoesFiltradas = notificacoes.filter((n) => {
    const categoria = resolveConfiguredValue(getCategoriaFromNotification(n), CATEGORIAS_NOTIFICACAO_PRODUTO);
    const ambiente = resolveConfiguredValue(getAmbienteFromNotification(n), AMBIENTES_NOTIFICACAO_PRODUTO);

    const categoriaAtiva = !categoria || categoriasAtivas[categoria] !== false;
    const ambienteAtivo = !ambiente || ambientesAtivos[ambiente] !== false;

    return categoriaAtiva && ambienteAtivo;
  });

  const naoLidas = notificacoesFiltradas.filter(n => !n.lida);

  const toggleCategoria = (categoria) => {
    setCategoriasAtivas((prev) => ({
      ...prev,
      [categoria]: prev[categoria] === false,
    }));
  };

  const toggleAmbiente = (ambiente) => {
    setAmbientesAtivos((prev) => ({
      ...prev,
      [ambiente]: prev[ambiente] === false,
    }));
  };

  const getIcon = (tipo) => {
    switch(tipo) {
      case 'nova_entrega': return <Truck className="w-4 h-4 text-blue-600" />;
      case 'entrega_concluida': return <Check className="w-4 h-4 text-green-600" />;
      case 'problema_entrega': return <AlertCircle className="w-4 h-4 text-red-600" />;
      case 'alteracao_rota': return <Package className="w-4 h-4 text-orange-600" />;
      case 'atraso': return <AlertCircle className="w-4 h-4 text-yellow-600" />;
      default: return <Bell className="w-4 h-4 text-gray-600" />;
    }
  };

  const getPrioridadeCor = (prioridade) => {
    switch(prioridade) {
      case 'urgente': return 'bg-red-100 border-red-300';
      case 'alta': return 'bg-orange-100 border-orange-300';
      case 'media': return 'bg-blue-100 border-blue-300';
      default: return 'bg-gray-100 border-gray-300';
    }
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button variant="ghost" size="icon" className="relative">
          <Bell className="w-5 h-5" />
          {naoLidas.length > 0 && (
            <Badge className="absolute -top-1 -right-1 h-5 w-5 flex items-center justify-center p-0 bg-red-500 text-white text-[10px]">
              {naoLidas.length}
            </Badge>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-96 p-0" align="end">
        <div className="flex items-center justify-between p-4 border-b">
          <h3 className="font-bold text-sm">Notificações</h3>
          <div className="flex items-center gap-2">
            <Button
              type="button"
              variant="outline"
              size="sm"
              className="h-7 text-[11px]"
              onClick={() => setShowCategoriaManager((prev) => !prev)}
            >
              Categorias
            </Button>
            {naoLidas.length > 0 && (
              <Badge variant="outline">{naoLidas.length} novas</Badge>
            )}
          </div>
        </div>
        {showCategoriaManager && (
          <div className="border-b px-4 py-3">
            <p className="text-[11px] text-gray-500 mb-2">Gerenciar categorias de produto nas notificações</p>
            <div className="flex flex-wrap gap-2">
