  useEffect(() => {
    if (!isOpen) return;
    setFornecedorFilter(String(fornecedorSelecionado || "all"));
  }, [fornecedorSelecionado, isOpen]);

  useEffect(() => {
    if (!isOpen) return;
    if (orcamento) {
      setFormData({
        ...orcamento,
        vendedor_id: orcamento.vendedor_id || user?.id || null,
      });
      // Initialize search with client name if editing an existing quote
      if (orcamento.cliente_nome) {
        setSearchCliente(orcamento.cliente_nome);
      } else if (orcamento.cliente_id && clientes) {
        const cliente = clientes.find(c => c.id === orcamento.cliente_id);
        if (cliente) setSearchCliente(formatarNome(cliente.nome_completo));
      }
    } else {
      const numeroOrcamento = `ORC-${Math.floor(10000 + Math.random() * 90000)}`; // Fixed random number generation
      setFormData({
        numero_orcamento: numeroOrcamento,
        data_orcamento: obterDataLocalString(),
        validade: (() => {
          const d = new Date();
          d.setDate(d.getDate() + 30);
          return obterDataLocalString(d);
        })(),
        loja: getUserLoja() || user?.loja || "Centro",
        cliente_id: "",
        cliente_nome: "",
        cliente_telefone: "",
        itens: [],
        pagamentos: [],
        valor_total: 0,
        desconto: 0,
        status: "Pendente",
        observacoes: "",
        cidade: "",
        bairro: "",
        endereco: "",
        vendedor_id: user?.id || null,
      });
      setSearchCliente("");
    }
  }, [orcamento, isOpen]);

  useEffect(() => {
    calcularTotal();
  }, [formData.itens, formData.desconto]);

  // No productSearchRef setup needed anymore as BuscaProdutoAvancada handles it internally

  const handleClienteChange = (clienteId) => {
    const cliente = clientes.find(c => c.id === clienteId);
    setFormData({
      ...formData,
      cliente_id: clienteId,
      cliente_nome: cliente?.nome_completo || "",
      cliente_telefone: cliente?.telefone || ""
    });
    setSearchCliente(cliente?.nome_completo || "");
    setIsClienteDropdownOpen(false);
  };

  const clientesFiltrados = clientes.filter(c =>
    c.nome_completo?.toLowerCase().includes(searchCliente.toLowerCase()) ||
    c.cpf?.includes(searchCliente) ||
    c.telefone?.includes(searchCliente)
  );

  const podeCriarCliente = searchCliente.trim().length >= 3 && clientesFiltrados.length === 0;

  const getItemCaracteristicas = (item) => {
    if (item.caracteristicas) return item.caracteristicas;

    const caracteristicas = [];
    const tamanho = String(item.tamanho || '').trim();
    const material = String(item.material || '').trim();
    const cor = String(item.cor || '').trim();
    const tamanhoValido = tamanho && !['n/a', 'na', '-', 'null', 'undefined'].includes(tamanho.toLowerCase());

    const dimensoesFormatadas = formatDimensions(item.largura, item.altura, item.profundidade);
    const dimensoesValidas = dimensoesFormatadas !== '-';
    const dimensoesCompactas = [item.largura, item.altura, item.profundidade].filter(Boolean).join('x');
    const tamanhoDuplicaDimensoes = tamanhoValido && dimensoesCompactas && tamanho.replace(/\s+/g, '').toLowerCase() === dimensoesCompactas.toLowerCase();

    if (tamanhoValido && !tamanhoDuplicaDimensoes) caracteristicas.push(`Tamanho: ${tamanho}`);
    if (material && !['n/a', 'na', '-', 'null', 'undefined'].includes(material.toLowerCase())) caracteristicas.push(`Material: ${material}`);
    if (cor && !['n/a', 'na', '-', 'null', 'undefined'].includes(cor.toLowerCase())) caracteristicas.push(`Cor: ${cor}`);
    if (dimensoesValidas) caracteristicas.push(`Medidas: ${dimensoesFormatadas}`);

    return caracteristicas.join(" | ");
  };

  const getItemFabricante = (item) => {
    return String(item.fornecedor_nome || fornecedoresById[String(item.fornecedor_id)] || '').trim();
  };

  const handleSelectProduto = (produto) => {
    if (!produto) return;

    const qty = quantidade || 1;
    const subtotal = produto.preco_venda * qty;
    
    const novoItem = {
      produto_id: produto.id,
      produto_nome: buildProductDisplayName(produto.nome, produto.modelo_referencia),
      fornecedor_id: produto.fornecedor_id || null,
      fornecedor_nome: fornecedoresById[String(produto.fornecedor_id)] || produto.fornecedor_nome || '',
      quantidade: qty,
      preco_unitario: produto.preco_venda,
      subtotal: subtotal,
      caracteristicas: getItemCaracteristicas(produto),
      cor: produto.cor,
      material: produto.material,
      tamanho: produto.tamanho,
      largura: produto.largura,
      altura: produto.altura,
      profundidade: produto.profundidade
    };

    setFormData(prev => ({
      ...prev,
      itens: [...prev.itens, novoItem]
    }));

    setQuantidade(1);
    toast.success(`${produto.nome} adicionado ao orçamento!`);
  };

  const removerProduto = (index) => {
    setFormData({
      ...formData,
      itens: formData.itens.filter((_, i) => i !== index)
    });
  };

  const alterarQuantidade = (index, novaQtd) => {
    const qty = Math.max(1, novaQtd);
    setFormData(prev => {
      const novosItens = [...prev.itens];
      const item = novosItens[index];
      const subtotal = item.preco_unitario * qty;
      novosItens[index] = {
        ...item,
        quantidade: qty,
        subtotal: subtotal
      };
      return {
        ...prev,
        itens: novosItens
      };
    });
  };

  const calcularTotal = () => {
    const subtotal = formData.itens.reduce((sum, item) => sum + item.subtotal, 0);
    const total = subtotal - (formData.desconto || 0);
    setFormData(prev => ({ ...prev, valor_total: total }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!formData.cliente_id || formData.itens.length === 0) {
      alert("Selecione um cliente e adicione pelo menos um produto");
      return;
    }
    onSave(formData);
  };

  // Mapear fornecedores por ID para resolver o nome
  const fornecedoresById = (fornecedores || []).reduce((acc, f) => {
    acc[String(f.id)] = f.nome_empresa;
    return acc;
  }, {});

  const produtosFiltradosPorFornecedor = useMemo(() => {
    if (fornecedorFilter === "all") return produtos;
    return (produtos || []).filter(p => String(p.fornecedor_id || "") === fornecedorFilter);
  }, [produtos, fornecedorFilter]);

  return (
    <>
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle style={{ color: '#07593f' }}>
            {orcamento ? "Editar Orçamento" : "Novo Orçamento"}
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit}>
          <div className="space-y-6">
            <div className="grid md:grid-cols-3 gap-4">
              <div>
                <Label>Número do Orçamento</Label>
                <Input value={formData.numero_orcamento} disabled />
              </div>
              <div>
                <Label htmlFor="data_orcamento">Data *</Label>
                <Input
                  id="data_orcamento"
                  type="date" lang="pt-BR"
                  value={formData.data_orcamento}
                  onChange={(e) => setFormData({ ...formData, data_orcamento: e.target.value })}
                  required
                />
              </div>
              <div>
                <Label htmlFor="validade">Válido até *</Label>
                <Input
                  id="validade"
                  type="date" lang="pt-BR"
                  value={formData.validade}
                  onChange={(e) => setFormData({ ...formData, validade: e.target.value })}
                  required
                />
                <div className="flex gap-1 mt-1 items-center flex-wrap">
                  {[7, 15, 30, 60].map(dias => (
                    <button
                      key={dias}
                      type="button"
                      onClick={() => {
                        const d = new Date();
                        d.setDate(d.getDate() + dias);
                        setFormData({ ...formData, validade: obterDataLocalString(d) });
                      }}
                      className="px-2 py-0.5 text-[10px] rounded-full border border-gray-200 hover:bg-gray-100 text-gray-600"
                    >
                      {dias}d
                    </button>
                  ))}
                  <div className="flex items-center gap-0.5 ml-1">
                    <input
                      type="number"
                      min="1"
                      placeholder="0"
                      className="w-12 h-5 text-[10px] text-center border border-gray-200 rounded-l-full px-1 focus:outline-none focus:border-green-500"
                      id="validade_custom_num"
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') {
                          e.preventDefault();
                          const num = parseInt(e.target.value);
                          const unidade = document.getElementById('validade_custom_unidade')?.value || 'd';
                          if (!num || num < 1) return;
                          const mult = unidade === 's' ? 7 : unidade === 'm' ? 30 : 1;
                          const d = new Date();
                          d.setDate(d.getDate() + num * mult);
                          setFormData({ ...formData, validade: obterDataLocalString(d) });
                        }
                      }}
                      onBlur={(e) => {
                        const num = parseInt(e.target.value);
                        const unidade = document.getElementById('validade_custom_unidade')?.value || 'd';
                        if (!num || num < 1) return;
                        const mult = unidade === 's' ? 7 : unidade === 'm' ? 30 : 1;
                        const d = new Date();
                        d.setDate(d.getDate() + num * mult);
                        setFormData({ ...formData, validade: obterDataLocalString(d) });
                      }}
                    />
                    <select
                      id="validade_custom_unidade"
                      className="h-5 text-[10px] border border-l-0 border-gray-200 rounded-r-full px-1 focus:outline-none focus:border-green-500 bg-white text-gray-600"
                    >
                      <option value="d">dias</option>
                      <option value="s">sem</option>
                      <option value="m">mês</option>
                    </select>
                  </div>
                </div>
              </div>
            </div>

            <div className="grid md:grid-cols-3 gap-4">
              <div className="relative">
                <div className="flex items-center justify-between">
                  <Label htmlFor="cliente">Cliente *</Label>
                  <Button 
                    type="button" 
                    variant="link" 
                    className="h-auto p-0 text-green-700 text-xs"
                    onClick={() => {
                      setIsCriandoCliente(true);
                      setIsClienteDropdownOpen(false);
                    }}
                  >
                    <UserPlus className="w-3 h-3 mr-1" />
                    Novo Cliente
                  </Button>
                </div>
                <div className="relative mt-2">
                  <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-400" />
                  <Input
                    placeholder="Buscar por nome, CPF ou telefone..."
                    value={searchCliente || formData.cliente_nome}
                    onChange={(e) => {
                      setSearchCliente(e.target.value);
                      setIsClienteDropdownOpen(true);
                      if (formData.cliente_id) {
                        setFormData({ ...formData, cliente_id: "", cliente_nome: "", cliente_telefone: "" });
                      }
                    }}
                    onFocus={() => setIsClienteDropdownOpen(true)}
                    className="pl-9"
                    required={!formData.cliente_id}
                  />
                </div>
                {isClienteDropdownOpen && searchCliente && (
                  <div className="absolute z-50 w-full mt-1 bg-white border rounded-lg shadow-lg max-h-60 overflow-y-auto">
                    {clientesFiltrados.length > 0 ? (
                      clientesFiltrados.map(cliente => (
                        <div key={cliente.id} className="flex items-center hover:bg-gray-50 group">
                          <button
                            type="button"
                            onClick={() => handleClienteChange(cliente.id)}
                            className="flex-1 text-left px-4 py-3 flex flex-col"
                          >
                            <span className="font-medium text-green-900">{formatarNome(cliente.nome_completo)}</span>
                            <span className="text-xs text-gray-500">{cliente.cpf || 'CPF n/d'} • {formatarTelefone(cliente.telefone)}</span>
                          </button>
                          <button
                            type="button"
                            title="Editar cadastro"
                            onClick={(e) => { e.stopPropagation(); setEditandoCliente(cliente); setIsClienteDropdownOpen(false); }}
                            className="pr-3 pl-1 py-3 text-gray-400 hover:text-green-700 opacity-0 group-hover:opacity-100 transition-opacity"
                          >
                            <Pencil className="w-3.5 h-3.5" />
                          </button>
                        </div>
                      ))
                    ) : (
                      <div className="px-4 py-3 text-sm text-gray-500 space-y-2">
                        {!showNovoClienteForm ? (
                          <>
                            <div>Nenhum cliente encontrado</div>
                            {podeCriarCliente && (
                              <Button
                                type="button"
                                variant="link"
                                className="h-auto p-0 text-green-700"
                                onClick={handleAbrirNovoClienteForm}
                              >
                                {`Criar novo cliente com o nome "${formatarNome(searchCliente)}"`}
                              </Button>
                            )}
                          </>
                        ) : (
                          <form onSubmit={handleSubmitNovoCliente} className="space-y-3 pt-1">
                            <div className="font-medium text-gray-700 text-sm">Novo cliente</div>
                            <div>
                              <Label className="text-xs">Nome *</Label>
                              <Input
                                value={novoClienteData.nome_completo}
                                onChange={e => setNovoClienteData(prev => ({ ...prev, nome_completo: e.target.value }))}
                                placeholder="Nome completo"
                                className="h-8 text-sm mt-1"
                                required
                              />
                            </div>
                            <div>
                              <Label className="text-xs">Telefone / WhatsApp {!novoClienteData.sem_whatsapp && <span className="text-red-500">*</span>}</Label>
                              <Input
                                value={novoClienteData.telefone}
                                onChange={e => setNovoClienteData(prev => ({ ...prev, telefone: formatarTelefone(e.target.value) }))}
                                placeholder="(00) 00000-0000"
                                className="h-8 text-sm mt-1"
                                disabled={novoClienteData.sem_whatsapp}
                              />
                            </div>
                            <div className="flex items-center gap-2">
                              <input
                                type="checkbox"
                                id="sem_whatsapp_check"
                                checked={novoClienteData.sem_whatsapp}
                                onChange={e => setNovoClienteData(prev => ({ ...prev, sem_whatsapp: e.target.checked, telefone: e.target.checked ? "" : prev.telefone }))}
                                className="h-4 w-4 accent-green-700"
                              />
                              <label htmlFor="sem_whatsapp_check" className="text-xs text-gray-600 cursor-pointer">Cliente não possui WhatsApp</label>
                            </div>
                            <div className="flex gap-2 pt-1">
                              <Button type="submit" size="sm" className="bg-green-700 hover:bg-green-800 text-white" disabled={criarClienteMutation.isPending}>
                                {criarClienteMutation.isPending ? "Salvando..." : "Salvar"}
                              </Button>
                              <Button type="button" size="sm" variant="outline" onClick={() => setShowNovoClienteForm(false)}>
                                Cancelar
                              </Button>
                            </div>
                          </form>
                        )}
                      </div>
                    )}
                  </div>
                )}
              </div>
              <div>
                <Label htmlFor="loja">Loja *</Label>
                <div className="mt-2">
                  <Select
                    value={formData.loja}
                    onValueChange={(value) => setFormData({ ...formData, loja: value })}
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {lojas.length === 0 ? (
                        <SelectItem value="Centro" disabled>Carregando...</SelectItem>
                      ) : (
                        lojas.map(loja => (
                          <SelectItem key={loja.id} value={loja.nome}>{loja.nome}</SelectItem>
                        ))
                      )}
                    </SelectContent>
                  </Select>
                </div>
              </div>
              <div>
                <Label htmlFor="vendedor">Vendedor *</Label>
                <div className="mt-2">
                  {hasMasterAccess ? (
                    <Select
                      value={formData.vendedor_id || user?.id || ''}
                      onValueChange={(value) => setFormData({ ...formData, vendedor_id: value })}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Selecione o vendedor" />
                      </SelectTrigger>
                      <SelectContent>
                        {vendedoresDisponiveis.map((u) => (
                          <SelectItem key={u.id} value={u.id}>
                            {u.full_name || u.email}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  ) : (
                    <Input
                      value={(() => {
                        const selId = formData.vendedor_id || user?.id;
                        const u = users.find(x => x.id === selId);
                        return u ? (u.full_name || u.email) : (user?.full_name || user?.email || "");
                      })()}
                      disabled
                    />
                  )}
                </div>
              </div>
            </div>

            <div className="border rounded-xl p-4" style={{ borderColor: '#E5E0D8' }}>
              <h4 className="font-semibold mb-4" style={{ color: '#07593f' }}>Produtos</h4>

              <div className="mb-4">
                <Label>Filtrar por Fornecedor</Label>
                <Select value={fornecedorFilter} onValueChange={(value) => setFornecedorFilter(String(value))}>
                  <SelectTrigger className="mt-2">
                    <SelectValue placeholder="Selecione um fornecedor" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">Todos os Fornecedores</SelectItem>
                    {(fornecedores || []).map(f => (
                      <SelectItem key={f.id} value={String(f.id)}>{f.nome_empresa}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="grid md:grid-cols-12 gap-3 mb-4">
                <div className="md:col-span-9">
                  <Label>Buscar Produto</Label>
                  <div className="mt-2">
                    <BuscaProdutoAvancada
                      produtos={produtosFiltradosPorFornecedor}
                      fornecedores={fornecedores}
                      onSelectProduto={handleSelectProduto}
                      user={user}
                    />
                  </div>
                </div>
                <div className="md:col-span-3">
                  <Label htmlFor="quantidade_input">Qtd. a Adicionar</Label>
                  <Input
                    id="quantidade_input"
                    type="number"
                    min="1"
                    value={quantidade}
                    onChange={(e) => setQuantidade(parseInt(e.target.value) || 1)}
                    className="mt-2 h-11"
                  />
                </div>
              </div>

              {formData.itens.length > 0 && (
                <div className="space-y-2">
                  {formData.itens.map((item, index) => (
                    <div key={index} className="p-3 rounded-lg border">
                      <div className="flex items-start justify-between mb-2">
                        <div className="flex-1">
                          <p className="font-medium" style={{ color: '#07593f' }}>{item.produto_nome}</p>
                          {getItemFabricante(item) && (
                            <p className="text-xs mt-1 font-medium" style={{ color: '#8B8B8B' }}>
                              Fabricante: {getItemFabricante(item)}
                            </p>
                          )}
                          <p className="text-sm" style={{ color: '#8B8B8B' }}>
                            {item.quantidade} x R$ {item.preco_unitario?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                          </p>
                          {getItemCaracteristicas(item) && (
                            <p className="text-xs mt-2 p-2 bg-gray-50 rounded" style={{ color: '#666' }}>
                              {getItemCaracteristicas(item)}
                            </p>
                          )}
                        </div>
                        <div className="flex flex-col items-end gap-2 ml-4 shrink-0">
                          <div className="flex items-center gap-3">
                            <p className="font-bold text-lg" style={{ color: '#07593f' }}>
                              R$ {item.subtotal?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                            </p>
                            <Button
                              type="button"
                              variant="ghost"
                              size="sm"
                              onClick={() => removerProduto(index)}
                              className="text-red-600 hover:bg-red-50 h-8 w-8 p-0"
                            >
                              <Trash2 className="w-4 h-4" />
                            </Button>
                          </div>
                          
                          <div className="flex items-center gap-1 border border-gray-200 dark:border-neutral-800 rounded-lg p-0.5 bg-gray-50 dark:bg-neutral-900">
                            <button
                              type="button"
                              onClick={() => alterarQuantidade(index, item.quantidade - 1)}
                              disabled={item.quantidade <= 1}
                              className="w-7 h-7 rounded flex items-center justify-center text-gray-500 hover:bg-gray-200 dark:hover:bg-neutral-800 disabled:opacity-40 transition-colors"
                            >
                              -
                            </button>
                            <input
                              type="number"
                              min="1"
                              value={item.quantidade}
                              onChange={(e) => alterarQuantidade(index, parseInt(e.target.value) || 1)}
                              className="w-12 text-center bg-transparent border-0 font-semibold text-sm focus:outline-none focus:ring-0 [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
                            />
                            <button
                              type="button"
                              onClick={() => alterarQuantidade(index, item.quantidade + 1)}
                              className="w-7 h-7 rounded flex items-center justify-center text-gray-500 hover:bg-gray-200 dark:hover:bg-neutral-800 transition-colors"
                            >
                              +
                            </button>
                          </div>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <div className="grid md:grid-cols-2 gap-4">
              <div>
                <Label htmlFor="desconto">Desconto (R$)</Label>
                <Input
                  id="desconto"
                  type="number"
                  step="0.01"
                  min="0"
                  value={formData.desconto}
                  onChange={(e) => setFormData({ ...formData, desconto: parseFloat(e.target.value) || 0 })}
                />
              </div>
            </div>

            {formData.cliente_id && (
              <div className="p-3 bg-gray-50 border rounded-lg">
                <Label className="text-gray-600 mb-1 block">Endereço do Cliente</Label>
                <div className="text-sm">
                  {(() => {
                    const cliente = clientes.find(c => c.id === formData.cliente_id);
                    if (!cliente) return "Endereço não encontrado";
                    const enderecoCompleto = [cliente.endereco, cliente.numero].filter(Boolean).join(", ");
                    const localidade = [cliente.bairro, cliente.cidade, cliente.estado].filter(Boolean).join(" - ");
                    const full = [enderecoCompleto, localidade].filter(Boolean).join(" | ");
                    return full || "Nenhum endereço cadastrado para este cliente.";
                  })()}
                </div>
              </div>
            )}

            <div className="flex items-end">
              <div className="w-full p-4 rounded-lg" style={{ backgroundColor: '#07593f', color: 'white' }}>
                <p className="text-sm mb-1">Valor Total</p>
                <p className="text-2xl font-bold">
                  R$ {formData.valor_total?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                </p>
              </div>
            </div>
          </div>

          <div>
            <Label htmlFor="observacoes">Observações</Label>
            <Textarea
              id="observacoes"
              value={formData.observacoes}
              onChange={(e) => setFormData({ ...formData, observacoes: e.target.value })}
              rows={3}
            />
          </div>

          <DialogFooter className="mt-6">
            <Button type="button" variant="outline" onClick={onClose}>
              Cancelar
            </Button>
            <Button
              type="submit"
              disabled={isLoading || !formData.cliente_id || formData.itens.length === 0}
              style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
            >
              {isLoading ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Salvando...
                </>
              ) : (
                orcamento ? "Atualizar" : "Criar Orçamento"
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>

    {(editandoCliente || isCriandoCliente) && (
      <ClienteModal
        isOpen={!!editandoCliente || isCriandoCliente}
        onClose={() => { setEditandoCliente(null); setIsCriandoCliente(false); }}
        cliente={editandoCliente}
        isLoading={isEditClienteLoading}
        clientes={clientes}
        onSave={async (dadosAtualizados) => {
          setIsEditClienteLoading(true);
          try {
            if (editandoCliente) {
              await base44.entities.Cliente.update(editandoCliente.id, dadosAtualizados);
              queryClient.invalidateQueries({ queryKey: ['clientes'] });
              if (formData.cliente_id === editandoCliente.id) {
                const telefoneWhatsApp = dadosAtualizados.telefone || "";
                setFormData(prev => ({
                  ...prev,
                  cliente_nome: dadosAtualizados.nome_completo || prev.cliente_nome,
                  cliente_telefone: telefoneWhatsApp,
                }));
                setSearchCliente(formatarNome(dadosAtualizados.nome_completo || ""));
              }
              toast.success("Cliente atualizado com sucesso!");
              setEditandoCliente(null);
            } else {
              const novoCliente = await base44.entities.Cliente.create(dadosAtualizados);
              queryClient.setQueryData(['clientes'], (old) => {
                if (old) return [...old, novoCliente];
                return [novoCliente];
              });
              queryClient.invalidateQueries({ queryKey: ['clientes'] });
              setFormData(prev => ({
                ...prev,
                cliente_id: novoCliente.id,
                cliente_nome: novoCliente.nome_completo || "",
                cliente_telefone: novoCliente.telefone || ""
              }));
              setSearchCliente(formatarNome(novoCliente.nome_completo || ""));
              setIsClienteDropdownOpen(false);
              toast.success("Cliente criado com sucesso!");
              setIsCriandoCliente(false);
            }
          } catch (err) {
            toast.error(err?.message || "Erro ao salvar cliente");
          } finally {
            setIsEditClienteLoading(false);
          }
        }}
      />
    )}
    </>
  );
}

import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import {
    QrCode,
    Copy,
    Check,
    X,
    RefreshCw,
    MessageCircle,
    Clock,
    CheckCircle,
    AlertCircle,
    ExternalLink
} from "lucide-react";
import { toast } from "sonner";
import { supabase } from "@/api/base44Client";
import { usePixCobrancaStatus } from "@/hooks/usePaymentStatus";
import { useTenant } from "@/contexts/TenantContext";

/**
 * Modal para exibir QR Code PIX Stone com:
 * - QR Code visual
 * - Código Pix Copia-Cola
 * - Timer de expiração
 * - Status em tempo real
 * - Envio via WhatsApp
 */
export default function PixQRCodeModal({
    open,
    onClose,
    valor,
    vendaId,
    entregaId,
    numeroPedido,
    clienteNome,
    clienteTelefone,
    clienteDocumento,
    descricao,
    onPaymentConfirmed
}) {
    const { brandName } = useTenant();
    const [loading, setLoading] = useState(false);
    const [pixData, setPixData] = useState(null);
    const [copiado, setCopiado] = useState(false);
    const [tempoRestante, setTempoRestante] = useState(null);
    const [status, setStatus] = useState('gerando'); // gerando | ativo | pago | expirado
    const [numeroAlternativo, setNumeroAlternativo] = useState("");

    const { status: realtimeStatus } = usePixCobrancaStatus(
        pixData?.cobranca_id,
        {
            showToast: false,
            onPaid: () => {
                setStatus('pago');
                toast.success('Pagamento PIX confirmado!');
                onPaymentConfirmed?.();
            },
            onExpired: () => {
                setStatus('expirado');
            }
        }
    );

    // Gerar PIX ao abrir modal
    useEffect(() => {
        if (open && valor > 0) {
            gerarPix();
        }
    }, [open]);

    // Timer de expiração
    useEffect(() => {
        if (!pixData?.expiracao) return;

        const interval = setInterval(() => {
            const agora = new Date().getTime();
            const expiracao = new Date(pixData.expiracao).getTime();
            const diff = expiracao - agora;

            if (diff <= 0) {
                setTempoRestante(null);
                setStatus('expirado');
                clearInterval(interval);
            } else {
                const horas = Math.floor(diff / (1000 * 60 * 60));
                const minutos = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
                const segundos = Math.floor((diff % (1000 * 60)) / 1000);
                setTempoRestante(`${horas.toString().padStart(2, '0')}:${minutos.toString().padStart(2, '0')}:${segundos.toString().padStart(2, '0')}`);
            }
        }, 1000);

        return () => clearInterval(interval);
    }, [pixData?.expiracao]);

    // Atualizacao em tempo real via Realtime + webhook
    useEffect(() => {
        if (!realtimeStatus) return;

        if (realtimeStatus === 'CONCLUIDA') {
            setStatus('pago');
            return;
        }

        if (realtimeStatus === 'EXPIRADA') {
            setStatus('expirado');
            return;
        }

        if (status !== 'gerando' && status !== 'erro') {
            setStatus('ativo');
        }
    }, [realtimeStatus, status]);

    const gerarPix = async () => {
        setLoading(true);
        setStatus('gerando');

        try {
            const { data, error } = await supabase.functions.invoke('stone-pix-create', {
                body: {
                    valor,
                    venda_id: vendaId,
                    entrega_id: entregaId,
                    numero_pedido: numeroPedido,
                    cliente_nome: clienteNome,
                    cliente_documento: clienteDocumento,
                    descricao: descricao || `Pedido #${numeroPedido || 'N/A'} - ${brandName || 'StoreHub'}`
                }
            });

            if (error) throw new Error(error.message);
            if (data.error) throw new Error(data.error);

            setPixData(data);
            setStatus('ativo');
            toast.success('QR Code PIX gerado!');

        } catch (error) {
            console.error('Erro ao gerar PIX:', error);
            toast.error(error.message || 'Erro ao gerar QR Code PIX');
            setStatus('erro');
        } finally {
            setLoading(false);
        }
    };

    const copiarCodigo = async () => {
        if (!pixData?.pix_copia_cola) return;

        try {
            await navigator.clipboard.writeText(pixData.pix_copia_cola);
            setCopiado(true);
            toast.success('Código PIX copiado!');
            setTimeout(() => setCopiado(false), 3000);
        } catch (e) {
            toast.error('Erro ao copiar');
        }
    };

    const enviarWhatsApp = (telefone) => {
        if (!pixData?.pix_copia_cola || !telefone) return;

        const tel = telefone.replace(/\D/g, '');
        const telFormatado = tel.startsWith('55') ? tel : `55${tel}`;

        const mensagem = encodeURIComponent(
            `Olá ${clienteNome?.split(' ')[0] || 'Cliente'}! 👋\n\n` +
            `Segue o PIX para pagamento do seu pedido:\n\n` +
            `📦 Pedido: #${numeroPedido || 'N/A'}\n` +
            `💰 Valor: R$ ${valor?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}\n\n` +
            `📱 *PIX Copia e Cola:*\n${pixData.pix_copia_cola}\n\n` +
            `⏰ Válido por 24 horas\n\n` +
            `${brandName || 'StoreHub'} 🧡💚`
        );

        window.open(`https://wa.me/${telFormatado}?text=${mensagem}`, '_blank');
    };

    const getStatusBadge = () => {
        switch (status) {
            case 'gerando':
                return <Badge className="bg-blue-100 text-blue-800"><RefreshCw className="w-3 h-3 mr-1 animate-spin" /> Gerando...</Badge>;
            case 'ativo':
                return <Badge className="bg-orange-100 text-orange-800"><Clock className="w-3 h-3 mr-1" /> Aguardando Pagamento</Badge>;
            case 'pago':
                return <Badge className="bg-green-100 text-green-800"><CheckCircle className="w-3 h-3 mr-1" /> Pago ✅</Badge>;
            case 'expirado':
                return <Badge className="bg-red-100 text-red-800"><AlertCircle className="w-3 h-3 mr-1" /> Expirado</Badge>;
            case 'erro':
                return <Badge className="bg-red-100 text-red-800"><X className="w-3 h-3 mr-1" /> Erro</Badge>;
            default:
                return null;
        }
    };

    return (
        <Dialog open={open} onOpenChange={(o) => !o && onClose?.()}>
            <DialogContent className="max-w-md mx-4">
                <DialogHeader>
                    <DialogTitle className="flex items-center justify-between">
                        <span className="flex items-center gap-2">
                            <QrCode className="w-5 h-5 text-green-600" />
                            PIX Stone
                        </span>
                        {getStatusBadge()}
                    </DialogTitle>
                </DialogHeader>

                <div className="space-y-4">
                    {/* Valor */}
                    <div className="bg-gradient-to-r from-green-500 to-green-600 rounded-xl p-4 text-white text-center">
                        <p className="text-sm opacity-90">Valor a Pagar</p>
                        <p className="text-3xl font-bold">
                            R$ {valor?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                        </p>
                        {numeroPedido && (
                            <p className="text-sm opacity-80 mt-1">Pedido #{numeroPedido}</p>
                        )}
                    </div>

                    {/* Loading */}
                    {loading && (
                        <div className="flex flex-col items-center justify-center py-8">
                            <div className="w-16 h-16 border-4 border-green-200 border-t-green-600 rounded-full animate-spin mb-4" />
                            <p className="text-gray-500">Gerando QR Code PIX...</p>
                        </div>
                    )}

                    {/* QR Code */}
                    {pixData && status !== 'pago' && (
                        <>
                            <div className="flex justify-center">
                                <div className="bg-white p-4 rounded-xl border-2 border-gray-200 shadow-sm">
                                    <img
                                        src={pixData.qr_code_image}
                                        alt="QR Code PIX"
                                        className="w-48 h-48"
                                    />
                                </div>
                            </div>

                            {/* Timer */}
                            {tempoRestante && status === 'ativo' && (
                                <div className="flex items-center justify-center gap-2 text-orange-600">
                                    <Clock className="w-4 h-4" />
                                    <span className="font-mono font-bold">{tempoRestante}</span>
                                    <span className="text-sm">restantes</span>
                                </div>
                            )}

                            {/* Código Copia-Cola */}
                            <div className="bg-gray-50 rounded-lg p-3 border">
                                <p className="text-xs text-gray-500 mb-2 font-medium">PIX Copia e Cola</p>
                                <div className="flex items-center gap-2">
                                    <input
                                        type="text"
                                        value={pixData.pix_copia_cola}
                                        readOnly
                                        className="flex-1 bg-white border rounded px-2 py-1.5 text-xs font-mono text-gray-600 truncate"
                                    />
                                    <Button
                                        size="sm"
                                        variant={copiado ? "default" : "outline"}
                                        onClick={copiarCodigo}
                                        className={copiado ? "bg-green-600 hover:bg-green-700" : ""}
                                    >
                                        {copiado ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                                    </Button>
                                </div>
                            </div>

                            {/* WhatsApp */}
                            <div className="bg-green-50 rounded-lg p-4 border border-green-200 space-y-3">
                                <p className="text-sm font-semibold text-green-800 flex items-center gap-1">
                                    <MessageCircle className="w-4 h-4" />
                                    Enviar via WhatsApp
                                </p>

                                {clienteTelefone && (
                                    <Button
                                        size="sm"
                                        onClick={() => enviarWhatsApp(clienteTelefone)}
                                        className="w-full bg-green-600 hover:bg-green-700 justify-start gap-2"
                                    >
                                        <MessageCircle className="w-4 h-4" />
                                        Enviar para {clienteNome?.split(' ')[0] || 'Cliente'}
                                    </Button>
                                )}

                                <div className="flex gap-2">
                                    <div className="flex-1 relative">
                                        <Input
                                            type="tel"
                                            placeholder="Outro número"
                                            value={numeroAlternativo}
                                            onChange={(e) => setNumeroAlternativo(e.target.value.replace(/\D/g, ''))}
                                            className="h-9 text-sm pl-10"
                                        />
                                        <span className="absolute left-3 top-1/2 -translate-y-1/2 text-xs text-gray-400">+55</span>
                                    </div>
                                    <Button
                                        size="sm"
                                        variant="outline"
                                        disabled={numeroAlternativo.length < 10}
                                        onClick={() => enviarWhatsApp(numeroAlternativo)}
                                        className="shrink-0"
                                    >
                                        <ExternalLink className="w-4 h-4" />
                                    </Button>
                                </div>
                            </div>
                        </>
                    )}

                    {/* Status Pago */}
                    {status === 'pago' && (
                        <div className="flex flex-col items-center justify-center py-8 text-center">
                            <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mb-4">
                                <CheckCircle className="w-12 h-12 text-green-600" />
                            </div>
                            <h3 className="text-xl font-bold text-green-700">Pagamento Confirmado!</h3>
                            <p className="text-gray-500 mt-2">O PIX foi recebido com sucesso.</p>
                            <Button
                                onClick={onClose}
                                className="mt-6 bg-green-600 hover:bg-green-700"
                            >
                                Fechar
                            </Button>
                        </div>
                    )}

                    {/* Status Expirado */}
                    {status === 'expirado' && (
                        <div className="flex flex-col items-center justify-center py-4 text-center">
                            <AlertCircle className="w-12 h-12 text-red-500 mb-3" />
                            <p className="text-gray-600">QR Code expirado</p>
                            <Button
                                onClick={gerarPix}
                                variant="outline"
                                className="mt-4"
                            >
                                <RefreshCw className="w-4 h-4 mr-2" />
                                Gerar Novo
                            </Button>
                        </div>
                    )}

                    {/* Status Erro */}
                    {status === 'erro' && !loading && (
                        <div className="flex flex-col items-center justify-center py-4 text-center">
                            <X className="w-12 h-12 text-red-500 mb-3" />
                            <p className="text-gray-600">Erro ao gerar PIX</p>
                            <Button
                                onClick={gerarPix}
                                variant="outline"
                                className="mt-4"
                            >
                                <RefreshCw className="w-4 h-4 mr-2" />
                                Tentar Novamente
                            </Button>
                        </div>
                    )}
                </div>
            </DialogContent>
        </Dialog>
    );
}

import React, { useState } from "react";
import { Button } from "@/components/ui/button";
import { Trash2, Package, Wrench, Truck, Store, AlertTriangle, Ban, ImageIcon, ImagePlus, Upload, Loader2, Check, Edit2, Tag, X } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { toast } from "sonner";
import { base44 } from "@/api/base44Client";
import { generateSafeSKU } from "@/utils/gtinValidator";

export default function CarrinhoVenda({ itens = [], onRemoveItem, onToggleEntrega, onToggleMontagem, onVincularImagem, onEditProduto, onAtualizarEstoque, onAtualizarQuantidade, onAtualizarProdutoId, onAtualizarItem }) {
  // Estado para o dialog de atualizar estoque
  const [atualizarEstoqueOpen, setAtualizarEstoqueOpen] = useState(false);
  const [itemParaEstoque, setItemParaEstoque] = useState(null);
  const [novaQuantidadeEstoque, setNovaQuantidadeEstoque] = useState("");
  const [atualizandoEstoque, setAtualizandoEstoque] = useState(false);

  // Edição de quantidade no carrinho
  const [editingQuantidadeIndex, setEditingQuantidadeIndex] = useState(null);
  const [editingQuantidadeValue, setEditingQuantidadeValue] = useState("");

  // Vincular Imagem State
  const [vincularImagemOpen, setVincularImagemOpen] = useState(false);
  const [itemParaImagem, setItemParaImagem] = useState(null);
  const [fotoUrl, setFotoUrl] = useState("");
  const [uploading, setUploading] = useState(false);
  const [savingImage, setSavingImage] = useState(false);

  const handleOpenAtualizarEstoque = (index, item) => {
    setItemParaEstoque({ index, ...item });
    setNovaQuantidadeEstoque("");
    setAtualizarEstoqueOpen(true);
  };

  const handleAtualizarEstoque = async () => {
    const novaQtd = parseInt(novaQuantidadeEstoque);
    if (isNaN(novaQtd) || novaQtd < 0) {
      toast.error("Informe uma quantidade válida");
      return;
    }

    setAtualizandoEstoque(true);
    try {
      // Calcular o estoque após a venda
      const qtdVenda = itemParaEstoque.quantidade;
      const estoqueAposVenda = novaQtd - qtdVenda;

      if (onAtualizarEstoque) {
        await onAtualizarEstoque(itemParaEstoque.index, novaQtd);
      }

      toast.success(`Estoque atualizado! Após a venda: ${estoqueAposVenda} un.`);
      setAtualizarEstoqueOpen(false);
      setNovaQuantidadeEstoque("");
    } catch (error) {
      console.error("Erro ao atualizar estoque:", error);
      toast.error("Erro ao atualizar estoque");
    } finally {
      setAtualizandoEstoque(false);
    }
  };

  const handleOpenVincularImagem = (index, item) => {
    setItemParaImagem({ index, ...item });
    setFotoUrl("");
    setVincularImagemOpen(true);
  };

  const handleImageUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setUploading(true);
    try {
      const { file_url } = await base44.integrations.Core.UploadFile({ file });
      setFotoUrl(file_url);
      toast.success("Imagem enviada com sucesso!");
    } catch (error) {
      console.error('Erro no upload:', error);
      toast.error('Erro ao enviar imagem');
    } finally {
      setUploading(false);
    }
  };

  const salvarImagem = async () => {
    if (!fotoUrl.trim()) {
      toast.error("Insira uma imagem ou link válido.");
      return;
    }

    setSavingImage(true);
    try {
      await onVincularImagem(itemParaImagem.index, fotoUrl.trim());
      toast.success("Imagem vinculada com sucesso!");
      setVincularImagemOpen(false);
    } catch (error) {
      toast.error("Erro ao vincular imagem.");
    } finally {
      setSavingImage(false);
    }
  };

  const aplicarQuantidade = (index, quantidade) => {
    if (!Number.isFinite(quantidade) || quantidade < 1) {
      toast.error("Informe uma quantidade válida (mínimo 1)");
      return;
    }

    if (typeof onAtualizarQuantidade === 'function') {
      onAtualizarQuantidade(index, quantidade);
    }
  };

  const iniciarEdicaoQuantidade = (index, quantidadeAtual) => {
    setEditingQuantidadeIndex(index);
    setEditingQuantidadeValue(String(quantidadeAtual || 1));
  };

  const confirmarEdicaoQuantidade = (index) => {
    const parsed = parseInt(editingQuantidadeValue, 10);
    aplicarQuantidade(index, parsed);
    setEditingQuantidadeIndex(null);
    setEditingQuantidadeValue("");
  };

  const cancelarEdicaoQuantidade = () => {
    setEditingQuantidadeIndex(null);
    setEditingQuantidadeValue("");
  };

  const isValidProdutoId = (id) => {
    if (!id || typeof id !== 'string') return false;
    if (id.startsWith('SOL-')) return false;
    // UUID v4: 36 chars, 4 hífens
    return id.length === 36 && id.split('-').length === 5;
  };

  // Se o item tem ID provisório (SOL-...), cria um Produto real no banco e atualiza o carrinho
  const resolverProdutoId = async (index, item) => {
    if (isValidProdutoId(item.produto_id)) return item.produto_id;
    const novoProduto = await base44.entities.Produto.create({
      sku: generateSafeSKU('PDV'),
      codigo_barras: null,
      nome: item.produto_nome || 'Produto sem nome',
      preco_venda: item.preco_unitario || 0,
      requer_atencao: true,
      quantidade_estoque: 0,
    });
    if (onAtualizarProdutoId) onAtualizarProdutoId(index, novoProduto.id);
    return novoProduto.id;
  };

  if (itens.length === 0) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center text-gray-400 border-2 border-dashed border-gray-200 dark:border-neutral-800 rounded-xl p-8 h-full min-h-[300px]">
        <div className="w-16 h-16 bg-gray-100 dark:bg-neutral-800 rounded-full flex items-center justify-center mb-4">
          <Trash2 className="w-8 h-8 text-gray-300" />
        </div>
        <p className="font-medium">O carrinho está vazio</p>
        <p className="text-sm text-gray-400">Adicione produtos para começar a venda</p>
      </div>
    );
  }

  const requerMontagem = (item) => item.tipo_entrega_padrao !== 'nao_requer_montagem';
  const toNumber = (value) => {
    const n = Number(value);
    return Number.isFinite(n) ? n : null;
  };

  return (
    <div className="flex-1 overflow-y-auto pr-2 space-y-2">
      {itens.map((item, index) => {
        const selecaoIncompleta = !item.tipo_entrega ||
          (item.tipo_entrega === 'entrega' && requerMontagem(item) && !item.tipo_montagem);
        const bloqueadoEstoque = item.bloqueado_estoque === true;
        const estoqueZerado = item.estoque_loja_atual !== null && item.estoque_loja_atual !== undefined && Number(item.estoque_loja_atual) <= 0;
        const quantidadeVenda = Math.max(1, Number(item.quantidade) || 1);
        const origemSelecionada = Array.isArray(item.origens_estoque_disponiveis)
          ? item.origens_estoque_disponiveis.find((origem) => origem.campo === item.origem_estoque_campo)
          : null;
        const estoqueAtual = toNumber(
          origemSelecionada?.quantidade
          ?? item.estoque_loja_atual
          ?? item.quantidade_estoque
        );
        const estoqueAposVenda = estoqueAtual !== null
          ? estoqueAtual - quantidadeVenda
          : null;
        const semEstoqueProjetado = estoqueAposVenda !== null && estoqueAposVenda < 0;

        return (
          <div
            key={index}
            className={`group p-3 bg-white dark:bg-neutral-900 rounded-lg border hover:shadow-sm transition-all ${(selecaoIncompleta || bloqueadoEstoque)
              ? 'border-red-300 dark:border-red-900 bg-red-50/10'
              : 'border-gray-100 dark:border-neutral-800 hover:border-green-200 dark:hover:border-green-900'
              }`}
          >
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4 flex-1">
                {/* Imagem do Produto */}
                <div className="w-16 h-16 shrink-0 relative flex-col items-center justify-center border rounded-md overflow-hidden bg-gray-50 flex">
                  {item.fotos?.[0] ? (
                    <img
                      src={item.fotos[0]}
                      alt={item.produto_nome}
                      className="w-full h-full object-cover"
                    />
                  ) : (
                    <>
                      <ImageIcon className="w-6 h-6 text-gray-300 mb-1" />
                      {onVincularImagem && (
                        <Button
                          variant="ghost"
                          size="sm"
                          className="h-5 px-1 absolute bottom-0 w-full text-[11px] bg-white/80 hover:bg-white text-green-700 font-bold border-t"
                          onClick={(e) => {
                            e.stopPropagation();
                            handleOpenVincularImagem(index, item);
                          }}
                        >
                          <ImagePlus className="w-3 h-3 mr-1" />
                          Vincular
                        </Button>
                      )}
                    </>
                  )}
                </div>

                <div className="flex flex-col items-center gap-0.5">
                  <span className="text-[11px] uppercase font-bold text-gray-400 leading-none">Qtd</span>
                  <button
                    type="button"
                    className="w-7 h-7 rounded-full border border-gray-200 dark:border-neutral-700 text-gray-600 dark:text-gray-300 hover:border-green-300 hover:text-green-700 dark:hover:border-green-700 dark:hover:text-green-400 flex items-center justify-center transition-colors"
                    onClick={() => aplicarQuantidade(index, (item.quantidade || 1) + 1)}
                    title="Aumentar quantidade"
                  >
                    +
                  </button>
                  {editingQuantidadeIndex === index ? (
                    <Input
                      type="number"
                      min="1"
                      value={editingQuantidadeValue}
                      onChange={(e) => setEditingQuantidadeValue(e.target.value)}
                      onBlur={() => confirmarEdicaoQuantidade(index)}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') {
                          e.preventDefault();
                          confirmarEdicaoQuantidade(index);
                        }
                        if (e.key === 'Escape') {
                          e.preventDefault();
                          cancelarEdicaoQuantidade();
                        }
                      }}
                      className="h-8 w-14 text-center px-1 font-bold text-sm"
                      autoFocus
                    />
                  ) : (
                    <button
                      type="button"
                      className="w-10 h-8 bg-green-50 dark:bg-green-900/20 rounded-md flex items-center justify-center text-green-700 dark:text-green-400 font-bold text-sm border border-green-100 dark:border-green-900/40"
                      onClick={() => iniciarEdicaoQuantidade(index, item.quantidade)}
                      title="Clique para editar a quantidade"
                    >
                      {item.quantidade}
                    </button>
                  )}
                  <button
                    type="button"
                    className="w-7 h-7 rounded-full border border-gray-200 dark:border-neutral-700 text-gray-600 dark:text-gray-300 hover:border-red-300 hover:text-red-600 dark:hover:border-red-700 dark:hover:text-red-400 disabled:opacity-40 disabled:cursor-not-allowed flex items-center justify-center transition-colors"
                    onClick={() => aplicarQuantidade(index, (item.quantidade || 1) - 1)}
                    disabled={(item.quantidade || 1) <= 1}
                    title="Diminuir quantidade"
                  >
                    -
                  </button>
                  {item.estoque_atualizado_em && (
                    <div className="mt-2 text-[10px] bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-300 px-2 py-1 rounded border border-blue-200 dark:border-blue-800 whitespace-nowrap">
                      <p className="font-semibold">Estoque definido</p>
                      <p>{item.estoque_atualizado_por}</p>
                      <p>{new Date(item.estoque_atualizado_em).toLocaleString('pt-BR')}</p>
                    </div>
                  )}
                </div>
                <div>
                  <div className="flex items-center gap-2">
                    <p className="font-medium text-gray-800 dark:text-gray-200">{item.produto_nome}</p>
                    {item.is_solicitacao && (
                      <Badge variant="outline" className="text-xs px-1 py-0 h-4 bg-amber-50 text-amber-600 border-amber-200 dark:bg-amber-900/20 dark:text-amber-400 dark:border-amber-800">
                        Novo
                      </Badge>
                    )}
                  </div>
                  <div className="flex items-center gap-2 text-xs text-gray-500">
                    {(!item.preco_unitario || item.preco_unitario <= 0) ? (
                      <span className="text-red-500 font-bold flex items-center gap-1">
                        <AlertTriangle className="w-3 h-3" /> Preço não definido - Use editar
                      </span>
                    ) : (
                      <div className="flex items-center gap-2">
                        <span>Unit: R$ {item.preco_unitario?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>

                        {item.status_solicitacao_preco === 'pendente' && (
                          <Badge variant="outline" className="text-xs bg-amber-50 text-amber-600 border-amber-200 animate-pulse">
                            R$ {item.preco_sugerido?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })} solicitado. Aguardando análise.
                          </Badge>
                        )}
                        {item.status_solicitacao_preco === 'aprovado' && (
                          <Badge variant="outline" className="text-xs bg-green-50 text-green-600 border-green-200">
                            Preço Aprovado
                          </Badge>
                        )}
                      </div>
                    )}
                  </div>

                  {estoqueAtual !== null && (
                    <div className="mt-1 flex items-center gap-2 text-[11px]">
                      <span className="text-gray-500 dark:text-gray-400">
                        Estoque atual: <strong className="text-gray-700 dark:text-gray-200">{estoqueAtual} un</strong>
                      </span>
                      <span className="text-gray-300">|</span>
                      <span className={semEstoqueProjetado ? 'text-red-600 dark:text-red-400 font-semibold' : 'text-emerald-700 dark:text-emerald-400'}>
                        Após venda: {estoqueAposVenda} un
                      </span>
                    </div>
                  )}

                  {Array.isArray(item.origens_estoque_disponiveis) && item.origens_estoque_disponiveis.length > 0 && (
                    <div className="mt-1 flex items-center gap-2">
                      <span className="text-[11px] text-gray-500 dark:text-gray-400">Retirada do estoque</span>
                      <Select
                        value={item.origem_estoque_campo || ''}
                        onValueChange={(novoCampo) => {
                          const origemSelecionada = item.origens_estoque_disponiveis.find((origem) => origem.campo === novoCampo);
                          if (!origemSelecionada || origemSelecionada.quantidade <= 0) return;

                          if (onAtualizarItem) {
                            onAtualizarItem(index, {
                              origem_estoque_campo: origemSelecionada.campo,
                              origem_estoque_nome: origemSelecionada.nome,
                              is_encomenda: false
                            });
                          }
                        }}
                      >
                        <SelectTrigger className="h-6 w-[170px] px-2 text-xs bg-white dark:bg-neutral-900 border-gray-200 dark:border-neutral-700">
                          <SelectValue placeholder="Selecionar local" />
                        </SelectTrigger>
                        <SelectContent>
                          {item.origens_estoque_disponiveis.map((origem) => (
                            <SelectItem
                              key={origem.campo}
                              value={origem.campo}
                              disabled={origem.quantidade <= 0 && origem.campo !== item.origem_estoque_campo}
                            >
                              {origem.nome} ({origem.quantidade} un)
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                  )}
                  {estoqueZerado && (
                    <div className="mt-2 flex items-center gap-2">
                      <Checkbox
                        id={`encomenda-item-${index}`}
                        checked={item.is_encomenda === true}
                        onCheckedChange={(checked) => onAtualizarItem && onAtualizarItem(index, { is_encomenda: checked === true })}
                      />
                      <label
                        htmlFor={`encomenda-item-${index}`}
                        className="text-xs font-medium text-amber-700 dark:text-amber-400 cursor-pointer select-none"
                      >
                        Encomenda
                      </label>
                      {!item.is_encomenda && (
                        <span className="text-[11px] text-red-500">
                          Marque para liberar o avanço
                        </span>
                      )}
                    </div>
                  )}
                </div>
              </div>
            </div>

            {/* Preço + Ações */}
            <div className="flex items-center gap-2 mt-2 justify-end">
              <p className="font-bold text-gray-800 dark:text-gray-200 w-28 text-right">
                R$ {item.subtotal?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
              </p>

              {onEditProduto && (
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-8 w-8 text-gray-400 hover:text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20"
                  onClick={() => onEditProduto(item)}
                  title="Editar Produto"
                >
                  <Edit2 className="w-4 h-4" />
                </Button>
              )}

              <Button
                variant="ghost"
                size="icon"
                className="h-8 w-8 text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20"
                onClick={() => onRemoveItem(index)}
              >
                <Trash2 className="w-4 h-4" />
              </Button>
            </div>

            {/* === SELETOR DE ENTREGA (Linha 1) === */}
            {onToggleEntrega && (
              <div className="mt-2 pt-2 border-t border-gray-100 dark:border-neutral-800">
                <div className="flex flex-col gap-1">
                  <span className="text-xs text-gray-500 mb-1">Tipo de Entrega:</span>
                  <div className="flex gap-1 flex-wrap">
                    <div className="flex items-center gap-1">
                      <button
                      type="button"
                      onClick={() => onToggleEntrega(index, 'entrega')}
                      className={`flex items-center gap-1 px-2 py-1 rounded-md text-xs font-medium transition-all ${item.tipo_entrega === 'entrega'
                        ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400 border border-green-300'
                        : 'bg-gray-50 text-gray-500 dark:bg-neutral-800 dark:text-gray-400 hover:bg-green-50'
                        }`}
                      title="Produto será entregue no endereço do cliente"
                      >
                        <Truck className="w-3 h-3" />
                        Entrega
                        {item.tipo_entrega === 'entrega' && item.tipo_entrega !== item.tipo_entrega_padrao && (
                          <span
                            className="ml-2 px-2 py-0.5 text-xs font-medium text-emerald-700 bg-emerald-50 border border-emerald-400 rounded"
                            onClick={async (e) => {
                              e.stopPropagation();
                              try {
                                const produtoId = await resolverProdutoId(index, item);
                                await base44.entities.Produto.update(produtoId, {
                                  tipo_entrega_padrao: item.tipo_entrega,
                                });
                                if (onAtualizarItem) onAtualizarItem(index, { tipo_entrega_padrao: item.tipo_entrega });
                                toast.success("Tipo de entrega salvo como padrão!");
                              } catch (err) {
                                toast.error("Erro ao salvar padrão: " + (err.message || err));
                              }
                            }}
                          >
                            Padrão
                          </span>
                        )}
                      </button>
                    </div>
                    <div className="flex items-center gap-1">
                      <button
                      type="button"
                      onClick={() => onToggleEntrega(index, 'retira')}
                      className={`flex items-center gap-1 px-2 py-1 rounded-md text-xs font-medium transition-all ${item.tipo_entrega === 'retira'
                        ? 'bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400 border border-orange-300'
                        : 'bg-gray-50 text-gray-500 dark:bg-neutral-800 dark:text-gray-400 hover:bg-orange-50'
                        }`}
                      title="Cliente retira na loja (sem entrega ou montagem)"
                      >
                        <Store className="w-3 h-3" />
                        Cliente Retira
                        {item.tipo_entrega === 'retira' && item.tipo_entrega !== item.tipo_entrega_padrao && (
                          <span
                            className="ml-2 px-2 py-0.5 text-xs font-medium text-emerald-700 bg-emerald-50 border border-emerald-400 rounded"
                            onClick={async (e) => {
                              e.stopPropagation();
                              try {
                                const produtoId = await resolverProdutoId(index, item);
                                await base44.entities.Produto.update(produtoId, {
                                  tipo_entrega_padrao: item.tipo_entrega,
                                });
                                if (onAtualizarItem) onAtualizarItem(index, { tipo_entrega_padrao: item.tipo_entrega });
                                toast.success("Tipo de entrega salvo como padrão!");
                              } catch (err) {
                                toast.error("Erro ao salvar padrão: " + (err.message || err));
                              }
                            }}
                          >
                            Padrão
                          </span>
                        )}
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* === SELETOR DE MONTAGEM (Linha 2) - Só aparece se Entrega + Requer Montagem === */}
            {onToggleMontagem && item.tipo_entrega === 'entrega' && requerMontagem(item) && (
              <div className="mt-2 pt-2 border-t border-gray-100 dark:border-neutral-800">
                <div className="flex flex-col gap-1">
                  <span className="text-xs text-gray-500 mb-1">Tipo de Montagem:</span>
                  <div className="flex gap-1 flex-wrap">
                    <div className="flex items-center gap-1">
                      <button
                      type="button"
                      onClick={() => onToggleMontagem(index, 'montado')}
                      className={`flex items-center gap-1 px-2 py-1 rounded-md text-xs font-medium transition-all ${item.tipo_montagem === 'montado'
                        ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400 border border-green-300'
                        : 'bg-gray-50 text-gray-500 dark:bg-neutral-800 dark:text-gray-400 hover:bg-green-50'
                        }`}
                      title="Produto vai montado (montagem interna, entrega com produto já montado)"
                      >
                        <Package className="w-3 h-3" />
                        Entrega Montado
                        {item.tipo_montagem === 'montado' && item.tipo_montagem !== item.tipo_montagem_padrao && (
                          <span
                            className="ml-2 px-2 py-0.5 text-xs font-medium text-emerald-700 bg-emerald-50 border border-emerald-400 rounded"
                            onClick={async (e) => {
                              e.stopPropagation();
                              try {
                                const produtoId = await resolverProdutoId(index, item);
                                await base44.entities.Produto.update(produtoId, {
                                  tipo_montagem_padrao: item.tipo_montagem,
                                });
                                if (onAtualizarItem) onAtualizarItem(index, { tipo_montagem_padrao: item.tipo_montagem });
                                toast.success("Tipo de montagem salvo como padrão!");
                              } catch (err) {
                                toast.error("Erro ao salvar padrão: " + (err.message || err));
                              }
                            }}
                          >
                            Padrão
                          </span>
                        )}
                      </button>
                    </div>
                    <div className="flex items-center gap-1">
                      <button
                      type="button"
                      onClick={() => onToggleMontagem(index, 'montagem_cliente')}
                      className={`flex items-center gap-1 px-2 py-1 rounded-md text-xs font-medium transition-all ${item.tipo_montagem === 'montagem_cliente'
                        ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400 border border-blue-300'
                        : 'bg-gray-50 text-gray-500 dark:bg-neutral-800 dark:text-gray-400 hover:bg-blue-50'
                        }`}
                      title="Produto vai na caixa, montador externo monta no endereço do cliente"
                      >
                        <Wrench className="w-3 h-3" />
                        Montagem no Local
                        {item.tipo_montagem === 'montagem_cliente' && item.tipo_montagem !== item.tipo_montagem_padrao && (
                          <span
                            className="ml-2 px-2 py-0.5 text-xs font-medium text-emerald-700 bg-emerald-50 border border-emerald-400 rounded"
                            onClick={async (e) => {
                              e.stopPropagation();
                              try {
                                const produtoId = await resolverProdutoId(index, item);
                                await base44.entities.Produto.update(produtoId, {
                                  tipo_montagem_padrao: item.tipo_montagem,
                                });
                                if (onAtualizarItem) onAtualizarItem(index, { tipo_montagem_padrao: item.tipo_montagem });
                                toast.success("Tipo de montagem salvo como padrão!");
                              } catch (err) {
                                toast.error("Erro ao salvar padrão: " + (err.message || err));
                              }
                            }}
                          >
                            Padrão
                          </span>
                        )}
                      </button>
                    </div>
                    <div className="flex items-center gap-1">
                      <button
                      type="button"
                      onClick={() => onToggleMontagem(index, 'sem_montagem')}
                      className={`flex items-center gap-1 px-2 py-1 rounded-md text-xs font-medium transition-all ${item.tipo_montagem === 'sem_montagem'
                        ? 'bg-rose-100 text-rose-700 dark:bg-rose-900/30 dark:text-rose-400 border border-rose-300'
                        : 'bg-gray-50 text-gray-500 dark:bg-neutral-800 dark:text-gray-400 hover:bg-rose-50'
                        }`}
                      title="Produto será entregue mas NÃO será montado pela empresa (vai na caixa)"
                      >
                        <Ban className="w-3 h-3" />
                        Não requer montagem
                        {item.tipo_montagem === 'sem_montagem' && item.tipo_montagem !== item.tipo_montagem_padrao && (
                          <span
                            className="ml-2 px-2 py-0.5 text-xs font-medium text-emerald-700 bg-emerald-50 border border-emerald-400 rounded"
                            onClick={async (e) => {
                              e.stopPropagation();
                              try {
                                const produtoId = await resolverProdutoId(index, item);
                                await base44.entities.Produto.update(produtoId, {
                                  tipo_montagem_padrao: item.tipo_montagem,
                                });
                                if (onAtualizarItem) onAtualizarItem(index, { tipo_montagem_padrao: item.tipo_montagem });
                                toast.success("Tipo de montagem salvo como padrão!");
                              } catch (err) {
                                toast.error("Erro ao salvar padrão: " + (err.message || err));
                              }
                            }}
                          >
                            Padrão
                          </span>
                        )}
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* === Info para produtos que NÃO requerem montagem e já tem entrega selecionada === */}
            {item.tipo_entrega === 'entrega' && !requerMontagem(item) && (
              <div className="mt-1 flex items-center gap-1">
                <Badge variant="outline" className="text-xs px-1 py-0 h-4 bg-blue-50 text-blue-600 border-blue-200 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-800">
                  Não requer montagem
                </Badge>
              </div>
            )}
          </div>
        );
      })}

      {/* Modal Vincular Imagem */}
      <Dialog open={vincularImagemOpen} onOpenChange={setVincularImagemOpen}>
        <DialogContent className="sm:max-w-[425px]">
          <DialogHeader>
            <DialogTitle>Vincular Imagem</DialogTitle>
            <DialogDescription>
              Adicione uma imagem para o produto <strong>{itemParaImagem?.produto_nome}</strong>.
            </DialogDescription>
          </DialogHeader>

          <div className="py-4 space-y-4">
            <div className="relative border-2 border-dashed rounded-lg h-32 flex items-center justify-center bg-gray-50 hover:bg-gray-100 transition-colors">
              <input
                type="file"
                accept="image/*"
                onChange={handleImageUpload}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                disabled={uploading || savingImage}
              />
              <div className="text-center">
                {uploading ? (
                  <Loader2 className="w-8 h-8 mx-auto animate-spin text-green-600" />
                ) : (
                  <>
                    <Upload className="w-6 h-6 mx-auto text-green-600 mb-2" />
                    <p className="text-xs font-medium text-gray-900">Clique ou arraste a imagem</p>
                  </>
                )}
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="imagem_url" className="text-xs text-gray-500 uppercase font-bold">Ou Link da Imagem</Label>
              <Input
                id="imagem_url"
                value={fotoUrl}
                onChange={(e) => setFotoUrl(e.target.value)}
                placeholder="https://..."
                disabled={savingImage || uploading}
              />
            </div>

            {fotoUrl && (
              <div className="relative border rounded-lg bg-gray-100 flex items-center justify-center overflow-hidden aspect-video mt-4">
                <img
                  src={fotoUrl}
                  alt="Preview"
                  className="w-full h-full object-cover"
                  onError={(e) => {
                    e.target.onerror = null;
                    toast.error("Link de imagem inválido!");
                  }}
                />
              </div>
            )}
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setVincularImagemOpen(false)} disabled={savingImage}>Cancelar</Button>
            <Button
              className="bg-green-600 hover:bg-green-700 text-white"
              onClick={salvarImagem}
              disabled={savingImage || !fotoUrl.trim()}
            >
              {savingImage ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Check className="w-4 h-4 mr-2" />}
              Salvar Imagem
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Dialog Atualizar Estoque */}
      <Dialog open={atualizarEstoqueOpen} onOpenChange={setAtualizarEstoqueOpen}>
        <DialogContent className="sm:max-w-[425px]">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-green-600">
              <Package className="w-5 h-5" />
              Atualizar Estoque
            </DialogTitle>
            <DialogDescription className="text-gray-600 pt-2">
              Produto: <strong>{itemParaEstoque?.produto_nome}</strong>
            </DialogDescription>
          </DialogHeader>

          <div className="py-4 space-y-4">
            <div className="space-y-2">
              <Label htmlFor="nova-qtd-estoque" className="text-sm font-medium">
                Quantidade em Estoque
              </Label>
              <Input
                id="nova-qtd-estoque"
                type="number"
                placeholder="0"
                value={novaQuantidadeEstoque}
                onChange={(e) => setNovaQuantidadeEstoque(e.target.value)}
                className="text-lg font-bold"
                autoFocus
                min="0"
              />
            </div>

            {novaQuantidadeEstoque && !isNaN(parseInt(novaQuantidadeEstoque)) && (
              <div className="p-3 bg-blue-50 dark:bg-blue-900/10 border border-blue-200 dark:border-blue-800 rounded-lg space-y-2">
                <p className="text-xs text-gray-600 dark:text-gray-300">
                  <strong>Quantidade inserida:</strong> {parseInt(novaQuantidadeEstoque)} un.
                </p>
                <p className="text-xs text-gray-600 dark:text-gray-300">
                  <strong>Quantidade de venda:</strong> {itemParaEstoque?.quantidade} un.
                </p>
                <p className="text-sm font-bold text-green-600 dark:text-green-400 border-t pt-2">
                  Estoque após a venda: {parseInt(novaQuantidadeEstoque) - (itemParaEstoque?.quantidade || 0)} un.
                </p>
              </div>
            )}

            <div className="p-3 bg-amber-50 dark:bg-amber-900/10 border border-amber-200 dark:border-amber-800 rounded-lg">
              <p className="text-xs text-amber-800 dark:text-amber-300">
                <strong>Informação:</strong> Insira a quantidade real de unidades em estoque. O sistema subtrairá automaticamente a quantidade que está sendo vendida e atualizará o cadastro.
              </p>
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setAtualizarEstoqueOpen(false)} disabled={atualizandoEstoque}>
              Cancelar
            </Button>
            <Button
              className="bg-green-600 hover:bg-green-700 text-white"
              onClick={handleAtualizarEstoque}
              disabled={!novaQuantidadeEstoque || isNaN(parseInt(novaQuantidadeEstoque)) || atualizandoEstoque}
            >
              {atualizandoEstoque ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Check className="w-4 h-4 mr-2" />}
              Confirmar Atualização
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useState, useEffect, useRef, useMemo } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Slider } from "@/components/ui/slider";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "@/components/ui/dialog";
import { Receipt, CreditCard, Wallet, DollarSign, Plus, X, Loader2, Clock, Tag, Check, Percent, Truck, User, Package, Key, Ban, TrendingUp, RefreshCw, Search, ShoppingBag, ChevronDown, ChevronRight } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { base44, supabase } from "@/api/base44Client";
import { useQuery } from "@tanstack/react-query";
import { toast } from "sonner";
import {
  PAYMENT_METHOD_OPTIONS,
  PAYMENT_METHOD_OPTIONS_DELIVERY,
  LINK_PAYMENT_SUBTYPES,
  isInstallmentPaymentMethod,
  isLinkPaymentMethod,
  normalizePaymentMethod,
  normalizePaymentItem,
} from "@/services/paymentOrchestrator";

// Formas base + subtypes do Link — não devem aparecer como opções extras
const BASE_OPTIONS_SET = new Set([...PAYMENT_METHOD_OPTIONS, ...LINK_PAYMENT_SUBTYPES]);

export default function PainelPagamento({
  valores,
  pagamentos = [],
  onAddPagamento,
  onRemovePagamento,
  onFinalizar,
  onOrcamento,
  loading,
  savingOrcamento,
  desconto,
  setDesconto,
  observacoes,
  setObservacoes,
  pagamentoEntrega,
  setPagamentoEntrega,
  disabled,
  cupomAplicado,
  setCupomAplicado,
  cliente,
  itensCount,
  prazo,
  tokenGerencial,
  setTokenGerencial,
  margemNegociavel = 0,
  onDescontoMargemChange,
  hideActions = false,
  vendas = [],
  itens = [],
  onAtualizarItem,
  descontoMaxProduto = 0,
  isProdutoComDesconto
}) {
  const [novoPagamento, setNovoPagamento] = useState({ forma: "", valor: "", parcelas: 1, linkSubtipo: "" });
  const [cupomCodigo, setCupomCodigo] = useState("");
  const [aplicandoCupom, setAplicandoCupom] = useState(false);
  const [erroCupom, setErroCupom] = useState("");

  // Estado para Modal de Troca
  const [modalTrocaOpen, setModalTrocaOpen] = useState(false);
  const [buscaPedido, setBuscaPedido] = useState("");
  const [pedidoSelecionado, setPedidoSelecionado] = useState(null);
  const [itensTrocaChecked, setItensTrocaChecked] = useState({});

  const isTrocaPayment = (forma) => String(forma || "").toLowerCase() === "troca";

  const [modalOrcamentoOpen, setModalOrcamentoOpen] = useState(false);
  const [validadeOrcamentoDias, setValidadeOrcamentoDias] = useState(30);

  // Estado para Token Gerencial
  const [tokenCodigo, setTokenCodigo] = useState("");
  const [aplicandoToken, setAplicandoToken] = useState(false);
  const [erroToken, setErroToken] = useState("");
  const [descontoPercent, setDescontoPercent] = useState(0);
  const [descontoValorDisplay, setDescontoValorDisplay] = useState("");

  // Estado para Margem Negociável
  const [descontoMargemPercent, setDescontoMargemPercent] = useState(0);
  const [descontoMargemValorDisplay, setDescontoMargemValorDisplay] = useState("");

  // Formatador de moeda: "1171" → "11,71"
  const formatCurrencyMask = (raw) => {
    const digits = String(raw || "").replace(/\D/g, "");
    if (!digits) return "";
    const padded = digits.padStart(3, "0");
    const cents = padded.slice(-2);
    const intPart = padded.slice(0, -2).replace(/^0+(?=\d)/, "") || "0";
    const intFormatted = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
    return `${intFormatted},${cents}`;
  };

  const parseCurrencyToNumber = (formattedValue) => {
    if (!formattedValue) return 0;
    const normalized = String(formattedValue)
      .replace(/\./g, "")
      .replace(/,/g, ".")
      .replace(/[^\d.-]/g, "");
    return parseFloat(normalized) || 0;
  };


  // Buscar configurações de taxa/acréscimo
  const { data: configTaxas = [] } = useQuery({
    queryKey: ['configuracao_taxas'],
    queryFn: () => base44.entities.ConfiguracaoTaxa.list()
  });

  // Formas customizadas criadas pela loja (não presentes na lista base do PDV)
  const customPaymentOptions = useMemo(() =>
    configTaxas
      .filter(t => t.ativa && !BASE_OPTIONS_SET.has(t.forma_pagamento))
      .map(t => t.forma_pagamento)
      .sort((a, b) => a.localeCompare(b, 'pt-BR')),
    [configTaxas]
  );

  const allPaymentOptions = useMemo(() =>
    [...PAYMENT_METHOD_OPTIONS, ...customPaymentOptions],
    [customPaymentOptions]
  );

  const normalizeKey = (value = "") =>
    String(value)
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .trim()
      .toLowerCase();

  // Mapa de acréscimos por forma de pagamento — match canônico exato
  const getAcrescimo = (forma) => {
    const formaKey = normalizeKey(normalizePaymentMethod(forma));
    const taxa = configTaxas.find(
      (t) => normalizeKey(normalizePaymentMethod(t.forma_pagamento || "")) === formaKey
    );
    if (!taxa || Number(taxa.acrescimo) === 0) return null;
    return { valor: Number(taxa.acrescimo), tipo: taxa.acrescimo_tipo || 'porcentagem' };
  };

  // Calcular valor do acréscimo
  const calcularAcrescimo = (forma, valorBase) => {
    const acrescimo = getAcrescimo(forma);
    if (!acrescimo) return 0;
    if (acrescimo.tipo === 'porcentagem') {
      return (valorBase * acrescimo.valor) / 100;
    }
    return acrescimo.valor;
  };

  // Resolve a forma canônica final considerando sub-tipo (Link) e parcelamento (Crédito)
  const resolverForma = (forma, parcelas) => {
    if (isLinkPaymentMethod(forma)) return novoPagamento.linkSubtipo;
    if (forma === "Crédito") return parcelas > 1 ? "Crédito Parcelado" : "Crédito 1x";
    return forma;
  };

  const handleAdd = async () => {
    if (!novoPagamento.valor) return;
    if (isTrocaPayment(novoPagamento.forma)) {
      setModalTrocaOpen(true);
      return;
    }

    const formaResolvida = resolverForma(novoPagamento.forma, novoPagamento.parcelas);

    const valorBase = parseFloat(novoPagamento.valor);
    const valorAcrescimo = calcularAcrescimo(formaResolvida, valorBase);
    const valorTotal = valorBase + valorAcrescimo;

    onAddPagamento(normalizePaymentItem({
      forma_pagamento: formaResolvida,
      valor: valorTotal,
      valor_base: valorBase,
      acrescimo: valorAcrescimo,
      parcelas: novoPagamento.parcelas
    }));
    setNovoPagamento({ forma: "", valor: "", parcelas: 1, linkSubtipo: "" });
  };

  const handleConfirmarTroca = () => {
    if (!pedidoSelecionado) return;
    const itensPedido = pedidoSelecionado.itens || [];
    const itensSelecionados = itensPedido.filter((_, idx) => itensTrocaChecked[idx]);
    if (itensSelecionados.length === 0) {
      toast.warning("Selecione pelo menos um item para trocar.");
      return;
    }
    itensSelecionados.forEach((item) => {
      const valorItem = Number(item.preco_unitario || 0) * Number(item.quantidade || 1);
      onAddPagamento(normalizePaymentItem({
        forma_pagamento: "Troca",
        valor: valorItem,
        parcelas: 1,
        troca_pedido_numero: pedidoSelecionado.numero_pedido,
        troca_pedido_id: pedidoSelecionado.id,
        troca_produto_nome: item.produto_nome || item.nome,
        troca_produto_id: item.produto_id,
        troca_quantidade: item.quantidade,
      }));
    });
    toast.success(`${itensSelecionados.length} item(ns) de troca adicionados!`);
    setModalTrocaOpen(false);
    setPedidoSelecionado(null);
    setBuscaPedido("");
    setItensTrocaChecked({});
    setNovoPagamento({ forma: "", valor: "", parcelas: 1, linkSubtipo: "" });
  };


  const handleAplicarCupom = async () => {
    if (!cupomCodigo.trim()) return;

    setAplicandoCupom(true);
    setErroCupom("");

    try {
      const cupons = await base44.entities.Cupom.list();
      const cupom = cupons.find(c => c.codigo === cupomCodigo.toUpperCase());

      if (!cupom) {
        setErroCupom("Cupom não encontrado");
        setAplicandoCupom(false);
        return;
      }

      if (!cupom.ativo) {
        setErroCupom("Cupom inativo");
        setAplicandoCupom(false);
        return;
      }

      const hojeIso = new Date().toLocaleDateString('en-CA');
      if (cupom.validade && cupom.validade.split('T')[0] < hojeIso) {
        setErroCupom("Cupom expirado");
        setAplicandoCupom(false);
        return;
      }

      if (cupom.quantidade_disponivel && (cupom.quantidade_usada || 0) >= cupom.quantidade_disponivel) {
        setErroCupom("Cupom esgotado");
        setAplicandoCupom(false);
        return;
      }

      // Calcular desconto
      let valorDesconto = 0;
      if (cupom.tipo === "porcentagem") {
        valorDesconto = (valores.subtotal * cupom.valor) / 100;
      } else {
        valorDesconto = Math.min(cupom.valor, valores.subtotal); // Não pode exceder o subtotal
      }

      setDesconto(valorDesconto);
      setCupomAplicado(cupom);
      setCupomCodigo("");
      // Limpa desconto de margem (mutuamente exclusivos)
      setDescontoMargemPercent(0);
      setDescontoMargemValorDisplay("");
      if (onDescontoMargemChange) onDescontoMargemChange(0);

    } catch (error) {
      console.error("Erro ao validar cupom:", error);
      setErroCupom("Erro ao validar cupom");
    } finally {
      setAplicandoCupom(false);
    }
  };

  const handleRemoverCupom = () => {
    setCupomAplicado(null);
    setDesconto(0);
    setCupomCodigo("");
    setErroCupom("");
  };

  // Aplicar token gerencial
  const handleAplicarToken = async () => {
    if (!tokenCodigo.trim()) return;

    setAplicandoToken(true);
    setErroToken("");

    try {
      const tokens = await base44.entities.TokenGerencial.list();
      const token = tokens.find(t => t.codigo.toUpperCase() === tokenCodigo.toUpperCase());

      if (!token) {
        setErroToken("Token não encontrado");
        setAplicandoToken(false);
        return;
      }

      if (!token.ativo) {
        setErroToken("Token revogado");
        setAplicandoToken(false);
        return;
      }

      const hojeIso = new Date().toLocaleDateString('en-CA');
      if (token.expira_em && token.expira_em.split('T')[0] < hojeIso) {
        setErroToken("Token expirado");
        setAplicandoToken(false);
        return;
      }

      if (token.max_usos && token.usos_realizados >= token.max_usos) {
        setErroToken("Token já foi utilizado o máximo de vezes");
        setAplicandoToken(false);
        return;
      }

      setTokenGerencial(token);
      setTokenCodigo("");
      setDescontoPercent(0); // Inicia em 0, gerente ajusta
      setDescontoValorDisplay("");
      // Limpa desconto de margem (mutuamente exclusivos)
      setDescontoMargemPercent(0);
      setDescontoMargemValorDisplay("");
      if (onDescontoMargemChange) onDescontoMargemChange(0);
      toast.success("Token autorizado! Ajuste o desconto desejado.");

    } catch (error) {
      console.error("Erro ao validar token:", error);
      setErroToken("Erro ao validar token");
    } finally {
      setAplicandoToken(false);
    }
  };

  const handleRemoverToken = () => {
    setTokenGerencial(null);
    setDescontoPercent(0);
    setDesconto(0);
    setDescontoValorDisplay("");
    setTokenCodigo("");
    setErroToken("");
  };

  // ---- Margem Negociável ----
  const handleAplicarDescontoMargem = (percent, valorR) => {
    if (percent > margemNegociavel) {
      toast.error(`Limite de ${margemNegociavel}% atingido.`);
      return;
    }
    setDesconto(valorR);
    if (onDescontoMargemChange) onDescontoMargemChange(percent);
    if (cupomAplicado) handleRemoverCupom();
    if (tokenGerencial) handleRemoverToken();
  };

  const handleRemoverDescontoMargem = () => {
    setDescontoMargemPercent(0);
    setDescontoMargemValorDisplay("");
    setDesconto(0);
    if (onDescontoMargemChange) onDescontoMargemChange(0);
  };

  // ---- Desconto por item ----
  const handleDescontoItem = (index, item, percentStr) => {
    let percent = parseFloat(percentStr);
    if (isNaN(percent) || percent < 0) percent = 0;
    if (percent > descontoMaxProduto) {
      toast.error(`Limite de ${descontoMaxProduto}% atingido.`);
      percent = descontoMaxProduto;
    }
    const precoOriginal = item.preco_original ?? item.preco_unitario;
    const novoPrecoUnit = precoOriginal * (1 - percent / 100);
    const novoSubtotal = novoPrecoUnit * (item.quantidade || 1);
    if (onAtualizarItem) {
      onAtualizarItem(index, {
        desconto_item_percent: percent,
        desconto_item_valor: precoOriginal * (percent / 100) * (item.quantidade || 1),
        preco_original: precoOriginal,
        preco_unitario: novoPrecoUnit,
        subtotal: novoSubtotal
      });
    }
  };

  const handleRemoverDescontoItem = (index, item) => {
    const precoOriginal = item.preco_original ?? item.preco_unitario;
    if (onAtualizarItem) {
      onAtualizarItem(index, {
        desconto_item_percent: 0,
        desconto_item_valor: 0,
        preco_unitario: precoOriginal,
        subtotal: precoOriginal * (item.quantidade || 1)
      });
    }
  };

  // Sincronizar desconto de margem quando o subtotal muda
  useEffect(() => {
    if (descontoMargemPercent > 0 && !cupomAplicado && !tokenGerencial) {
      const valorDesconto = (valores.subtotal * descontoMargemPercent) / 100;
      setDesconto(valorDesconto);
      setDescontoMargemValorDisplay(formatCurrencyMask(String(Math.round(valorDesconto * 100))));
    }
  }, [valores.subtotal, descontoMargemPercent]);

  // Atualizar desconto quando slider muda
  useEffect(() => {
    if (tokenGerencial && descontoPercent > 0) {
      const valorDesconto = (valores.subtotal * descontoPercent) / 100;
      setDesconto(valorDesconto);
      setDescontoValorDisplay(formatCurrencyMask(String(Math.round(valorDesconto * 100))));
    } else if (tokenGerencial && descontoPercent === 0) {
      setDesconto(0);
      setDescontoValorDisplay("");
    }
  }, [descontoPercent, valores.subtotal, tokenGerencial]);

  // Arredondamento logica
  const isDescontoMargem = !cupomAplicado && !tokenGerencial && desconto > 0 && descontoMargemPercent > 0;
  const isArredondamento = !cupomAplicado && !tokenGerencial && !isDescontoMargem && desconto !== 0;

  const handleArredondar = () => {
    if (valores.subtotal <= 0) return;

    if (isArredondamento) {
      setDesconto(0);
      toast.info("Arredondamento removido");
    } else {
      const arredondado = Math.round(valores.subtotal / 10) * 10;
      const diff = valores.subtotal - arredondado;
      if (diff === 0) {
        toast.info("O valor já está arredondado!");
        return;
      }
      setDesconto(diff);
      if (cupomAplicado) handleRemoverCupom();
      if (tokenGerencial) handleRemoverToken();
      if (descontoMargemPercent > 0) handleRemoverDescontoMargem();
      toast.success(`Total ajustado para R$ ${arredondado.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`);
    }
  };

  // [CORREÇÃO] Atualizar valor do 'Receber na Entrega' sempre que o restante mudar
  // E garantir que a forma de pagamento tenha um padrão se estiver vazio
  useEffect(() => {
    if (pagamentoEntrega.ativo) {
      setPagamentoEntrega(prev => ({
        ...prev,
        valor: valores.restante,
        forma: prev.forma || "Dinheiro" // Garante padrão caso venha vazio do storage
      }));
    }
  }, [valores.restante, pagamentoEntrega.ativo]);

  const creditoDisponivel = Number(cliente?.saldo_credito || 0);
  const creditoJaAplicado = pagamentos.some((p) => p.forma_pagamento === 'Crédito de Loja');
  const valorCreditoAplicavel = Math.min(creditoDisponivel, Math.max(0, valores.restante));

  const handleAplicarCredito = () => {
    if (creditoJaAplicado || valorCreditoAplicavel <= 0) return;
    onAddPagamento(normalizePaymentItem({
      forma_pagamento: 'Crédito de Loja',
      valor: valorCreditoAplicavel,
      parcelas: 1,
    }));
  };

  const handleFinalizarComCredito = async () => {
    const pagamentoCredito = pagamentos.find((p) => p.forma_pagamento === 'Crédito de Loja');
    if (pagamentoCredito && cliente?.id && pagamentoCredito.valor > 0) {
      try {
        const saldoAtual = Number(cliente.saldo_credito || 0);
        const novoSaldo = Math.max(0, saldoAtual - pagamentoCredito.valor);
        await base44.entities.Cliente.update(cliente.id, { saldo_credito: novoSaldo });
      } catch (err) {
        console.warn('Erro ao debitar crédito do cliente:', err);
      }
    }
    onFinalizar();
  };

  return (
    <div className="bg-white dark:bg-neutral-900 rounded-xl shadow-sm border border-gray-200 dark:border-neutral-800 p-4 h-full">
      <div className="grid grid-cols-1 md:grid-cols-12 gap-6 h-full">

        {/* COLUNA ESQUERDA - RESUMO FINANCEIRO (md:col-span-4) */}
        <div className="md:col-span-5 lg:col-span-4 flex flex-col gap-4 border-b md:border-b-0 md:border-r border-gray-100 dark:border-neutral-800 pb-4 md:pb-0 md:pr-4">

          {/* Resumo do Pedido (Novo) */}
          <div className="bg-green-50 dark:bg-neutral-800/50 rounded-xl p-4 border border-green-100 dark:border-neutral-700/50">
            <div className="flex items-start gap-3">
              <div className="w-10 h-10 rounded-full bg-green-100 dark:bg-green-900/40 flex items-center justify-center text-green-700 dark:text-green-400 font-bold">
                {cliente?.nome_completo?.charAt(0).toUpperCase() || <User className="w-5 h-5" />}
              </div>
              <div>
                <p className="font-bold text-sm text-gray-900 dark:text-gray-100 line-clamp-1">{cliente?.nome_completo}</p>
                <div className="flex flex-wrap gap-2 text-xs text-gray-500 mt-1">
                  <span className="flex items-center gap-1"><Package className="w-3 h-3" /> {itensCount} itens</span>
                  <span>•</span>
                  <span className="flex items-center gap-1"><Truck className="w-3 h-3" /> {prazo}</span>
                </div>
              </div>
            </div>
          </div>

          {/* Lista de Itens com Desconto por Produto */}
          {itens.length > 0 && (
            <div className="bg-gray-50 dark:bg-neutral-800/30 rounded-xl p-3 border border-gray-100 dark:border-neutral-700/50 max-h-[180px] overflow-y-auto">
              <h4 className="text-xs font-bold text-gray-500 uppercase mb-2">Itens do Pedido</h4>
              <div className="space-y-2">
                {itens.map((item, index) => {
                  const eligible = isProdutoComDesconto && isProdutoComDesconto(item);
                  return (
                    <div key={index} className="flex flex-col gap-1 p-2 bg-white dark:bg-neutral-900 rounded border border-gray-100 dark:border-neutral-800">
                      <div className="flex items-start justify-between gap-2">
                        <p className="text-xs font-medium text-gray-800 dark:text-gray-200 line-clamp-2 leading-tight flex-1">
                          {item.quantidade}x {item.produto_nome}
                        </p>
                        <div className="text-right whitespace-nowrap">
                          {(item.desconto_item_percent || 0) > 0 && item.preco_original ? (
                            <div className="flex flex-col">
                              <span className="text-[10px] text-gray-400 line-through">
                                R$ {(item.preco_original * (item.quantidade || 1)).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                              </span>
                              <span className="text-xs font-bold text-emerald-600 dark:text-emerald-400">
                                R$ {item.subtotal?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                              </span>
                            </div>
                          ) : (
                            <span className="text-xs font-bold text-gray-800 dark:text-gray-200">
                              R$ {item.subtotal?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                            </span>
                          )}
                        </div>
                      </div>

                      {/* Desconto do Item */}
                      {eligible && (
                        <div className="flex items-center justify-between mt-1 pt-1 border-t border-dashed border-gray-100 dark:border-neutral-800">
                          <span className="text-[10px] text-emerald-600 flex items-center gap-1">
                            <Tag className="w-3 h-3" />
                            Desconto (máx {descontoMaxProduto}%)
                          </span>
                          <div className="flex items-center gap-1">
                            <div className="relative">
                              <Input
                                type="number"
                                min={0}
                                max={descontoMaxProduto}
                                step={0.5}
                                value={item.desconto_item_percent || 0}
                                onChange={(e) => handleDescontoItem(index, item, e.target.value)}
                                className="h-6 w-16 text-[11px] pr-5 border-emerald-200 focus-visible:ring-emerald-500"
                              />
                              <span className="absolute right-1.5 top-1/2 -translate-y-1/2 text-gray-400 text-[10px]">%</span>
                            </div>
                            {(item.desconto_item_percent || 0) > 0 && (
                              <button
                                type="button"
                                onClick={() => handleRemoverDescontoItem(index, item)}
                                className="p-1 rounded text-gray-400 hover:text-red-500 hover:bg-red-50"
                                title="Remover desconto"
                              >
                                <X className="w-3 h-3" />
                              </button>
                            )}
                          </div>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          <h3 className="font-semibold text-sm uppercase text-gray-500 dark:text-gray-400 flex items-center justify-between mt-2 mb-2">
            <div className="flex items-center gap-2">
              <DollarSign className="w-4 h-4" /> Resumo Financeiro
            </div>
            <Button
              variant={isArredondamento ? "default" : "outline"}
              size="sm"
              className={`h-6 text-xs px-2 transition-colors ${isArredondamento
                ? "bg-green-500 text-white hover:bg-green-600 dark:bg-green-600 dark:hover:bg-green-700 border-transparent shadow-sm"
                : "border-gray-200 dark:border-neutral-700 hover:bg-gray-100 dark:hover:bg-neutral-800"
                }`}
              onClick={handleArredondar}
              disabled={valores.subtotal <= 0 || loading || savingOrcamento}
              title={isArredondamento ? "Remover arredondamento" : "Arredondar para a dezena mais próxima"}
            >
              {isArredondamento ? "Arredondado" : "Arredondar"}
            </Button>
          </h3>

          <div className="flex-1 flex flex-col justify-center gap-6">
            {/* Start Jackpot Area */}
            <div className={`p-6 rounded-2xl text-center border-2 transition-all duration-500 ${valores.pago > 0
              ? 'bg-orange-50 dark:bg-orange-900/10 border-orange-100 dark:border-orange-800/30'
              : 'bg-white dark:bg-transparent border-gray-100 dark:border-neutral-800 shadow-sm'
              }`}>
              <AnimatePresence mode="wait">
                <motion.p
                  key={valores.pago > 0 ? 'restante' : 'total'}
                  initial={{ opacity: 0, y: -10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: 10 }}
                  className={`text-sm font-bold uppercase mb-2 ${valores.pago > 0
                    ? 'text-orange-800 dark:text-orange-400'
                    : 'text-green-800 dark:text-green-400'
                    }`}
                >
                  {valores.pago > 0 ? 'Valor Restante' : 'Total a Pagar'}
                </motion.p>
              </AnimatePresence>
              <JackpotNumber
                value={valores.pago > 0 ? valores.restante : valores.total}
                className={`text-4xl md:text-5xl ${valores.pago > 0 ? 'text-orange-600 dark:text-orange-400' : 'text-green-700 dark:text-green-400'}`}
              />
            </div>

            <div className="space-y-3 px-2">
              <div className="flex justify-between items-center text-sm">
                <span className="text-gray-500">Subtotal</span>
                <span className="font-medium">R$ {valores.subtotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
              </div>

              {desconto !== 0 && (
                <div className={`flex justify-between items-center text-sm ${desconto > 0 ? 'text-purple-600 dark:text-purple-400' : 'text-blue-600 dark:text-blue-400'}`}>
                  <span className="flex items-center gap-1">
                    <Tag className="w-3 h-3" />
                    {desconto > 0 ? `Desconto ${cupomAplicado ? `(${cupomAplicado.codigo})` : ''}` : 'Arredondamento'}
                  </span>
                  <span className="font-bold">
                    {desconto > 0 ? '- ' : '+ '}
                    R$ {Math.abs(desconto).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                  </span>
                </div>
              )}

              {/* Linha de Acréscimos */}
              {pagamentos.reduce((acc, p) => acc + (p.acrescimo || 0), 0) > 0 && (
                <div className="flex justify-between items-center text-sm text-blue-600 dark:text-blue-400">
                  <span className="flex items-center gap-1"><TrendingUp className="w-3 h-3" /> Acréscimos</span>
                  <span className="font-bold">+ R$ {pagamentos.reduce((acc, p) => acc + (p.acrescimo || 0), 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
                </div>
              )}

              <div className="flex justify-between items-center text-sm">
                <span className="text-gray-500">Pago</span>
                <span className="font-medium text-green-600">R$ {valores.pago.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
              </div>

              <div className="h-px bg-gray-100 dark:bg-neutral-800 my-2" />

              {pagamentoEntrega.ativo && (
                <div className="flex justify-between items-center text-xs text-orange-600">
                  <span>Receber na Entrega ({pagamentoEntrega.forma})</span>
                  <span className="font-bold">R$ {pagamentoEntrega.valor.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
                </div>
              )}
            </div>

            {/* Cupom Section Compacta */}
            <div className="bg-purple-50 dark:bg-purple-900/20 p-3 rounded-lg border border-purple-100 dark:border-purple-800 mt-auto">
              {cupomAplicado ? (
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <div className="bg-purple-100 dark:bg-purple-800 p-1.5 rounded text-purple-600 dark:text-purple-300">
                      <Tag className="w-4 h-4" />
                    </div>
                    <div>
                      <p className="text-xs text-purple-500 dark:text-purple-400 font-medium">Cupom Aplicado</p>
                      <p className="text-sm font-bold text-purple-700 dark:text-purple-300">{cupomAplicado.codigo}</p>
                    </div>
                  </div>
                  <button
                    onClick={handleRemoverCupom}
                    className="p-1 hover:bg-purple-200 dark:hover:bg-purple-800 rounded text-purple-600 transition-colors"
                    title="Remover cupom"
                  >
                    <X className="w-4 h-4" />
                  </button>
                </div>
              ) : (
                <div className="flex gap-2">
                  <div className="relative flex-1">
                    <Tag className="w-3 h-3 absolute left-2 top-1/2 -translate-y-1/2 text-purple-500" />
                    <Input
                      placeholder="CÓDIGO DO CUPOM"
                      value={cupomCodigo}
                      onChange={(e) => {
                        setCupomCodigo(e.target.value.toUpperCase());
                        setErroCupom("");
                      }}
                      className="h-9 text-xs pl-7 uppercase font-mono bg-white dark:bg-neutral-800 border-purple-200 dark:border-purple-700 focus-visible:ring-purple-500"
                      onKeyDown={(e) => e.key === 'Enter' && handleAplicarCupom()}
                    />
                  </div>
                  <Button
                    size="sm"
                    className="h-9 bg-purple-600 hover:bg-purple-700 text-white shadow-sm"
                    onClick={handleAplicarCupom}
                    disabled={aplicandoCupom || !cupomCodigo.trim()}
                  >
                    {aplicandoCupom ? <Loader2 className="w-3 h-3 animate-spin" /> : "Aplicar"}
                  </Button>
                </div>
              )}
              {erroCupom && <p className="text-xs text-red-500 mt-1 pl-1">{erroCupom}</p>}
            </div>

            {/* Token Gerencial Section */}
            <div className="bg-amber-50 dark:bg-amber-900/20 p-3 rounded-lg border border-amber-100 dark:border-amber-800">
              {tokenGerencial ? (
                <div className="space-y-3">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <div className={`p-1.5 rounded ${tokenGerencial.tipo_token === 'SUPERVISOR_MODE' ? 'bg-purple-100 dark:bg-purple-900/40' : 'bg-blue-100 dark:bg-blue-900/40'}`}>
                        <span className="text-lg">{tokenGerencial.tipo_token === 'SUPERVISOR_MODE' ? '👑' : '🎫'}</span>
                      </div>
                      <div>
                        <p className="text-xs text-amber-500 dark:text-amber-400 font-medium flex items-center gap-1">
                          {tokenGerencial.tipo_token === 'SUPERVISOR_MODE' ? 'Modo Supervisor' : 'Token Único'}
                          <span className="text-xs px-1.5 py-0.5 rounded bg-amber-200 dark:bg-amber-800 text-amber-800 dark:text-amber-200">
                            {tokenGerencial.permissao}
                          </span>
                        </p>
                        <p className="text-sm font-bold font-mono text-amber-700 dark:text-amber-300">{tokenGerencial.codigo}</p>
                      </div>
                    </div>
                    <button
                      onClick={handleRemoverToken}
                      className="p-1 hover:bg-amber-200 dark:hover:bg-amber-800 rounded text-amber-600 transition-colors"
                      title="Remover token"
                    >
                      <X className="w-4 h-4" />
                    </button>
                  </div>

                  {/* Slider de desconto - só mostra se permissão é DESCONTO ou ALTERACAO_PRECO */}
                  {/* Slider de desconto - só mostra se permissão é DESCONTO ou ALTERACAO_PRECO */}
                  {(tokenGerencial.permissao === 'DESCONTO' || tokenGerencial.permissao === 'ALTERACAO_PRECO') && (
                    <div className="space-y-3">
                      <div className="flex items-center justify-between text-xs">
                        <span className="text-amber-700 dark:text-amber-400 font-medium">Desconto Autorizado</span>
                        <span className="text-xs bg-amber-100 text-amber-800 px-1.5 py-0.5 rounded">
                          Máx: {tokenGerencial.valor_limite || 30}%
                        </span>
                      </div>

                      <div className="flex gap-2 items-center">
                        {/* Input Porcentagem */}
                        <div className="relative flex-1">
                          <Input
                            type="number"
                            value={descontoPercent}
                            onChange={(e) => {
                              let val = parseFloat(e.target.value);
                              if (isNaN(val)) val = 0;
                              const max = tokenGerencial.valor_limite || 30;
                              if (val > max) val = max;
                              if (val < 0) val = 0;
                              setDescontoPercent(val);
                            }}
                            className="h-8 text-xs pr-6"
                            placeholder="0"
                          />
                          <span className="absolute right-2 top-1/2 -translate-y-1/2 text-gray-500 text-xs">%</span>
                        </div>

                        {/* Input Valor (R$) */}
                        <div className="relative flex-[1.5]">
                          <span className="absolute left-2 top-1/2 -translate-y-1/2 text-gray-500 text-xs">R$</span>
                          <Input
                            type="text"
                            inputMode="numeric"
                            value={descontoValorDisplay}
                            onChange={(e) => {
                              const formatted = formatCurrencyMask(e.target.value);
                              setDescontoValorDisplay(formatted);

                              let valR = parseCurrencyToNumber(formatted);
                              if (isNaN(valR) || valR < 0) {
                                setDesconto(0);
                                setDescontoPercent(0);
                                return;
                              }

                              // Calcula a porcentagem equivalente
                              let newPercent = (valR / valores.subtotal) * 100;
                              const maxPercent = tokenGerencial.valor_limite || 30;

                              if (newPercent > maxPercent) {
                                // Se passar do limite, trava no limite
                                newPercent = maxPercent;
                                valR = (valores.subtotal * maxPercent) / 100;
                                toast.error(`Limite de ${maxPercent}% atingido.`);
                                setDescontoValorDisplay(formatCurrencyMask(String(Math.round(valR * 100))));
                              }

                              setDescontoPercent(newPercent);
                              setDesconto(valR);
                            }}
                            className="h-8 text-xs pl-6"
                            placeholder="0,00"
                          />
                        </div>
                      </div>

                      <Slider
                        value={[descontoPercent]}
                        onValueChange={([v]) => setDescontoPercent(v)}
                        max={tokenGerencial.valor_limite || 30}
                        step={0.1} // Permitir frações para ajustes finos de valor
                        className="w-full"
                      />

                      <div className="text-center">
                        <p className="text-xs font-bold text-amber-800 dark:text-amber-300">
                          Total Desconto: R$ {desconto.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                        </p>
                      </div>
                    </div>
                  )}

                  {/* Info adicional para SUPER_CAIXA */}
                  {tokenGerencial.permissao === 'SUPER_CAIXA' && (
                    <p className="text-xs text-purple-600 flex items-center gap-1">
                      <Check className="w-3 h-3" /> Modo Super Caixa - Todas permissões liberadas
                    </p>
                  )}
                </div>
              ) : (
                <div className="space-y-2">
                  <p className="text-xs font-medium text-amber-700 dark:text-amber-400 flex items-center gap-1">
                    <Key className="w-3 h-3" /> Token do Gerente
                  </p>
                  <div className="flex gap-2">
                    <div className="relative flex-1">
                      <Key className="w-3 h-3 absolute left-2 top-1/2 -translate-y-1/2 text-amber-500" />
                      <Input
                        placeholder="G-XXXX"
                        value={tokenCodigo}
                        onChange={(e) => {
                          setTokenCodigo(e.target.value.toUpperCase());
                          setErroToken("");
                        }}
                        className="h-9 text-xs pl-7 uppercase font-mono bg-white dark:bg-neutral-800 border-amber-200 dark:border-amber-700 focus-visible:ring-amber-500"
                        onKeyDown={(e) => e.key === 'Enter' && handleAplicarToken()}
                      />
                    </div>
                    <Button
                      size="sm"
                      className="h-9 bg-amber-600 hover:bg-amber-700 text-white shadow-sm"
                      onClick={handleAplicarToken}
                      disabled={aplicandoToken || !tokenCodigo.trim()}
                    >
                      {aplicandoToken ? <Loader2 className="w-3 h-3 animate-spin" /> : "Usar"}
                    </Button>
                  </div>
                  {erroToken && <p className="text-xs text-red-500">{erroToken}</p>}
                </div>
              )}
            </div>

            {/* Margem Negociável — só aparece se a loja tiver margem configurada */}
            {margemNegociavel > 0 && (
              <div className={`p-3 rounded-lg border transition-all ${isDescontoMargem
                ? 'bg-green-50 dark:bg-green-900/20 border-green-200 dark:border-green-800'
                : 'bg-green-50/60 dark:bg-green-950/20 border-green-100 dark:border-green-900/40'}`}>
                <div className="flex items-center justify-between mb-2">
                  <p className="text-xs font-medium text-green-700 dark:text-green-400 flex items-center gap-1">
                    <Percent className="w-3 h-3" /> Desconto Negociável
                    <span className="ml-1 px-1.5 py-0.5 rounded bg-green-100 dark:bg-green-900/40 text-green-700 dark:text-green-400">
                      máx {margemNegociavel}%
                    </span>
                  </p>
                  {isDescontoMargem && (
                    <button
                      onClick={handleRemoverDescontoMargem}
                      className="p-1 hover:bg-green-200 dark:hover:bg-green-800 rounded text-green-600 transition-colors"
                      title="Remover desconto"
                    >
                      <X className="w-3 h-3" />
                    </button>
                  )}
                </div>

                <div className="space-y-2">
                  <div className="grid grid-cols-2 gap-2">
                    <div className="relative">
                      <Input
                        type="number"
                        value={descontoMargemPercent}
                        onChange={(e) => {
                          let val = parseFloat(e.target.value);
                          if (isNaN(val) || val < 0) val = 0;
                          if (val > margemNegociavel) val = margemNegociavel;
                          const valorR = (valores.subtotal * val) / 100;
                          setDescontoMargemPercent(val);
                          setDescontoMargemValorDisplay(formatCurrencyMask(String(Math.round(valorR * 100))));
                          handleAplicarDescontoMargem(val, valorR);
                        }}
                        className="h-8 text-xs pr-6 border-green-200 dark:border-green-700"
                        placeholder="0"
                        min={0}
                        max={margemNegociavel}
                        step={0.1}
                      />
                      <span className="absolute right-2 top-1/2 -translate-y-1/2 text-gray-400 text-xs">%</span>
                    </div>

                    <div className="relative">
                      <span className="absolute left-2 top-1/2 -translate-y-1/2 text-gray-500 text-xs">R$</span>
                      <Input
                        type="text"
                        inputMode="numeric"
                        value={descontoMargemValorDisplay}
                        onChange={(e) => {
                          const formatted = formatCurrencyMask(e.target.value);
                          setDescontoMargemValorDisplay(formatted);
                          let valR = parseCurrencyToNumber(formatted);
                          if (isNaN(valR) || valR < 0) valR = 0;
                          let percent = valores.subtotal > 0 ? (valR / valores.subtotal) * 100 : 0;
                          if (percent > margemNegociavel) {
                            percent = margemNegociavel;
                            valR = (valores.subtotal * margemNegociavel) / 100;
                            toast.error(`Limite de ${margemNegociavel}% atingido.`);
                            setDescontoMargemValorDisplay(formatCurrencyMask(String(Math.round(valR * 100))));
                          }
                          setDescontoMargemPercent(percent);
                          handleAplicarDescontoMargem(percent, valR);
                        }}
                        className="h-8 text-xs pl-7 border-green-200 dark:border-green-700"
                        placeholder="0,00"
                      />
                    </div>
                  </div>

                  <Slider
                    value={[descontoMargemPercent]}
                    onValueChange={([v]) => {
                      setDescontoMargemPercent(v);
                      const valorR = (valores.subtotal * v) / 100;
                      setDescontoMargemValorDisplay(formatCurrencyMask(String(Math.round(valorR * 100))));
                      handleAplicarDescontoMargem(v, valorR);
                    }}
                    max={margemNegociavel}
                    step={0.1}
                    className="w-full"
                  />
                </div>
              </div>
            )}

          </div>
        </div>

        {/* COLUNA DIREITA - AÇÕES (md:col-span-8) */}
        <div className="md:col-span-7 lg:col-span-8 flex flex-col gap-4 h-full">
          <div className="flex-1 flex flex-col gap-4">

            {/* Modal de Troca de Mercadoria */}
            <Dialog open={modalTrocaOpen} onOpenChange={(open) => {
              setModalTrocaOpen(open);
              if (!open) {
                setPedidoSelecionado(null);
                setBuscaPedido("");
                setItensTrocaChecked({});
                setNovoPagamento(prev => ({ ...prev, forma: "" }));
              }
            }}>
              <DialogContent className="sm:max-w-[620px] max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                  <DialogTitle className="flex items-center gap-2">
                    <RefreshCw className="w-5 h-5 text-teal-600" />
                    Troca de Mercadoria
                  </DialogTitle>
                  <DialogDescription>
                    Busque um pedido anterior e selecione os itens que serão aceitos como crédito na venda atual.
                  </DialogDescription>
                </DialogHeader>

                {/* Busca de Pedido */}
                {!pedidoSelecionado && (
                  <div className="space-y-3">
                    <div className="relative">
                      <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                      <Input
                        placeholder="Digite o número do pedido (ex: 10001)"
                        value={buscaPedido}
                        onChange={(e) => setBuscaPedido(e.target.value)}
                        className="pl-9 h-10"
                        autoFocus
                      />
                    </div>

                    {/* Resultados da Busca */}
                    {buscaPedido.trim().length >= 1 && (() => {
                      const termo = buscaPedido.trim().toLowerCase();
                      const encontrados = vendas.filter(v =>
                        String(v.numero_pedido || "").toLowerCase().includes(termo) ||
                        String(v.cliente_nome || "").toLowerCase().includes(termo)
                      ).slice(0, 8);
                      return (
                        <div className="space-y-2 max-h-72 overflow-y-auto pr-1">
                          {encontrados.length === 0 ? (
                            <p className="text-sm text-gray-400 text-center py-4">Nenhum pedido encontrado</p>
                          ) : (
                            encontrados.map((venda) => (
                              <button
                                key={venda.id}
                                type="button"
                                onClick={() => {
                                  setPedidoSelecionado(venda);
                                  const initialChecked = {};
                                  (venda.itens || []).forEach((_, idx) => { initialChecked[idx] = false; });
                                  setItensTrocaChecked(initialChecked);
                                }}
                                className="w-full text-left p-3 rounded-lg border border-gray-200 dark:border-neutral-700 bg-white dark:bg-neutral-800 hover:border-teal-400 hover:bg-teal-50 dark:hover:bg-teal-900/20 transition-all"
                              >
                                <div className="flex items-center justify-between">
                                  <div>
                                    <p className="font-bold text-sm text-gray-800 dark:text-gray-200">Pedido #{venda.numero_pedido}</p>
                                    <p className="text-xs text-gray-500 mt-0.5">{venda.cliente_nome}</p>
                                  </div>
                                  <div className="text-right">
                                    <p className="text-sm font-semibold text-teal-700 dark:text-teal-400">
                                      R$ {Number(venda.valor_total || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                                    </p>
                                    <p className="text-xs text-gray-400">
                                      {venda.data_venda ? new Date(venda.data_venda + 'T00:00:00').toLocaleDateString('pt-BR') : ''}
                                      {venda.status && ` · ${venda.status}`}
                                    </p>
                                  </div>
                                </div>
                                {(venda.itens || []).length > 0 && (
                                  <p className="text-xs text-gray-400 mt-1">{venda.itens.length} item(ns)</p>
                                )}
                              </button>
                            ))
                          )}
                        </div>
                      );
                    })()}

                    {buscaPedido.trim().length === 0 && (
                      <p className="text-sm text-gray-400 text-center py-4 flex items-center justify-center gap-2">
                        <Search className="w-4 h-4" /> Digite para buscar pedidos
                      </p>
                    )}
                  </div>
                )}

                {/* Itens do Pedido Selecionado */}
                {pedidoSelecionado && (
                  <div className="space-y-3">
                    <div className="flex items-center justify-between">
                      <div>
                        <p className="font-bold text-teal-700 dark:text-teal-400">Pedido #{pedidoSelecionado.numero_pedido}</p>
                        <p className="text-sm text-gray-500">{pedidoSelecionado.cliente_nome}</p>
                      </div>
                      <button
                        type="button"
                        onClick={() => {
                          setPedidoSelecionado(null);
                          setBuscaPedido("");
                          setItensTrocaChecked({});
                        }}
                        className="text-xs text-teal-600 hover:underline flex items-center gap-1"
                      >
                        <Search className="w-3 h-3" /> Buscar outro pedido
                      </button>
                    </div>

                    <div className="bg-teal-50 dark:bg-teal-900/10 rounded-lg p-2 border border-teal-100 dark:border-teal-800">
                      <div className="flex items-center justify-between mb-2 px-1">
                        <p className="text-xs font-semibold uppercase text-teal-600 dark:text-teal-400">Itens do Pedido</p>
                        <button
                          type="button"
                          className="text-xs text-teal-600 hover:underline"
                          onClick={() => {
                            const allChecked = (pedidoSelecionado.itens || []).every((_, i) => itensTrocaChecked[i]);
                            const newState = {};
                            (pedidoSelecionado.itens || []).forEach((_, i) => { newState[i] = !allChecked; });
                            setItensTrocaChecked(newState);
                          }}
                        >
                          {(pedidoSelecionado.itens || []).every((_, i) => itensTrocaChecked[i]) ? 'Desmarcar todos' : 'Selecionar todos'}
                        </button>
                      </div>
                      <div className="space-y-2 max-h-64 overflow-y-auto">
                        {(pedidoSelecionado.itens || []).map((item, idx) => {
                          const valorItem = Number(item.preco_unitario || 0) * Number(item.quantidade || 1);
                          const isChecked = !!itensTrocaChecked[idx];
                          return (
                            <button
                              key={idx}
                              type="button"
                              onClick={() => setItensTrocaChecked(prev => ({ ...prev, [idx]: !prev[idx] }))}
                              className={`w-full text-left p-3 rounded-lg border transition-all flex items-start gap-3 ${isChecked
                                ? 'bg-teal-100 dark:bg-teal-900/30 border-teal-400 dark:border-teal-600'
                                : 'bg-white dark:bg-neutral-800 border-gray-200 dark:border-neutral-700 hover:border-teal-300'
                                }`}
                            >
                              <div className={`w-5 h-5 rounded flex items-center justify-center border shrink-0 mt-0.5 transition-colors ${isChecked
                                ? 'bg-teal-600 border-teal-600 text-white'
                                : 'bg-white dark:bg-neutral-700 border-gray-300 dark:border-neutral-500'
                                }`}>
                                {isChecked && <Check className="w-3 h-3" />}
                              </div>
                              <div className="flex-1 min-w-0">
                                <p className="font-medium text-sm text-gray-800 dark:text-gray-200 truncate">
                                  {item.produto_nome || item.nome || 'Produto'}
                                </p>
                                <p className="text-xs text-gray-500 mt-0.5">
                                  Qtd: {item.quantidade || 1} · R$ {Number(item.preco_unitario || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })} cada
                                </p>
                              </div>
                              <div className="text-right shrink-0">
                                <p className={`font-bold text-sm ${isChecked ? 'text-teal-700 dark:text-teal-400' : 'text-gray-700 dark:text-gray-300'}`}>
                                  R$ {valorItem.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                                </p>
                              </div>
                            </button>
                          );
                        })}
                      </div>
                    </div>

                    {/* Resumo da seleção */}
                    {(() => {
                      const selecionados = (pedidoSelecionado.itens || []).filter((_, i) => itensTrocaChecked[i]);
                      const totalTroca = selecionados.reduce((acc, item) => acc + Number(item.preco_unitario || 0) * Number(item.quantidade || 1), 0);
                      return selecionados.length > 0 ? (
                        <div className="bg-teal-600 text-white rounded-lg p-3 flex items-center justify-between">
                          <div>
                            <p className="text-sm font-semibold">{selecionados.length} item(ns) selecionado(s)</p>
                            <p className="text-xs opacity-80">Crédito total de troca</p>
                          </div>
                          <p className="text-xl font-bold">R$ {totalTroca.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                        </div>
                      ) : (
                        <p className="text-sm text-gray-400 text-center py-2">Selecione ao menos um item para prosseguir</p>
                      );
                    })()}
                  </div>
                )}

                <DialogFooter className="mt-2">
                  <Button variant="outline" onClick={() => {
                    setModalTrocaOpen(false);
                    setPedidoSelecionado(null);
                    setBuscaPedido("");
                    setItensTrocaChecked({});
                    setNovoPagamento(prev => ({ ...prev, forma: "" }));
                  }}>Cancelar</Button>
                  <Button
                    className="bg-teal-600 hover:bg-teal-700 text-white"
                    disabled={!pedidoSelecionado || !(pedidoSelecionado.itens || []).some((_, i) => itensTrocaChecked[i])}
                    onClick={handleConfirmarTroca}
                  >
                    <RefreshCw className="w-4 h-4 mr-2" /> Confirmar Troca
                  </Button>
                </DialogFooter>
              </DialogContent>
            </Dialog>

            {/* Adicionar Pagamento */}
            <div className="bg-gray-50 dark:bg-neutral-800/50 p-4 rounded-xl border border-gray-100 dark:border-neutral-800">
              <Label className="text-xs font-semibold uppercase text-gray-500 mb-3 block">Adicionar Pagamento</Label>
              <div className="flex flex-col sm:flex-row gap-3 items-end flex-wrap">
                <div className="flex-1 w-full sm:w-auto">
                  <Label className="text-xs mb-1.5 block">Forma de Pagamento</Label>
                  <Select value={novoPagamento.forma} onValueChange={v => {
                    setNovoPagamento({ forma: v, valor: "", parcelas: 1, linkSubtipo: "" });
                    if (v === "Troca") {
                      setModalTrocaOpen(true);
                    }
                  }}>
                    <SelectTrigger className="h-10 bg-white dark:bg-neutral-800">
                      <SelectValue placeholder="Selecione" />
                    </SelectTrigger>
                    <SelectContent>
                      {allPaymentOptions.map(f => {
                        const acr = getAcrescimo(f);
                        return (
                          <SelectItem key={f} value={f}>
                            <span className="flex items-center gap-2">
                              {f}
                              {acr && (
                                <span className="text-xs px-1.5 py-0.5 rounded bg-blue-100 text-blue-700 font-medium">
                                  +{acr.tipo === 'porcentagem' ? `${acr.valor}%` : `R$${acr.valor}`}
                                </span>
                              )}
                            </span>
                          </SelectItem>
                        );
                      })}
                    </SelectContent>
                  </Select>
                </div>

                {/* Sub-select para Link de Pagamento */}
                {isLinkPaymentMethod(novoPagamento.forma) && (
                  <div className="w-full sm:w-36">
                    <Label className="text-xs mb-1.5 block">Tipo do Link</Label>
                    <Select value={novoPagamento.linkSubtipo} onValueChange={v => setNovoPagamento({ ...novoPagamento, linkSubtipo: v, parcelas: 1 })}>
                      <SelectTrigger className="h-10 bg-white dark:bg-neutral-800">
                        <SelectValue placeholder="Selecione" />
                      </SelectTrigger>
                      <SelectContent>
                        {LINK_PAYMENT_SUBTYPES.map(sub => (
                          <SelectItem key={sub} value={sub}>{sub.replace('Link - ', '')}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                )}

                {isInstallmentPaymentMethod(
                  isLinkPaymentMethod(novoPagamento.forma) ? novoPagamento.linkSubtipo : novoPagamento.forma
                ) && (
                    <div className="w-full sm:w-24">
                      <Label className="text-xs mb-1.5 block">Parcelas</Label>
                      <Select value={String(novoPagamento.parcelas)} onValueChange={v => setNovoPagamento({ ...novoPagamento, parcelas: Number(v) })}>
                        <SelectTrigger className="h-10 bg-white dark:bg-neutral-800"><SelectValue /></SelectTrigger>
                        <SelectContent>
                          {Array.from({ length: 12 }).map((_, i) => (
                            <SelectItem key={i + 1} value={String(i + 1)}>{i + 1}x</SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                  )}

                {/* Campo de Valor — oculto para Troca */}
                {!isTrocaPayment(novoPagamento.forma) && (
                  <div className="flex-1 w-full sm:w-auto">
                    <Label className="text-xs mb-1.5 block">Valor (R$)</Label>
                    <div className="relative">
                      <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 text-sm">R$</span>
                      <Input
                        type="number"
                        className="h-10 pl-9 text-lg font-bold bg-white dark:bg-neutral-800"
                        placeholder="0,00"
                        value={novoPagamento.valor}
                        onChange={e => setNovoPagamento({ ...novoPagamento, valor: e.target.value })}
                        onKeyDown={e => e.key === 'Enter' && handleAdd()}
                      />
                    </div>
                    {/* Preview do acréscimo */}
                    {(() => {
                      const formaPreview = resolverForma(novoPagamento.forma, novoPagamento.parcelas);
