const parseFlexibleCharge = (rawValue, baseAmount) => {
    const rawText = String(rawValue ?? '').trim();
    if (!rawText) {
        return {
            rawText,
            isPercent: false,
            value: 0,
            percent: 0,
            amount: 0,
            isValid: true,
        };
    }

    const normalized = rawText
        .replace(/\s+/g, '')
        .replace('R$', '')
        .replace(',', '.');

    const isPercent = normalized.includes('%');
    const numericText = normalized.replace('%', '');
    const value = parseFloat(numericText);

    if (!Number.isFinite(value) || value < 0) {
        return {
            rawText,
            isPercent,
            value: 0,
            percent: 0,
            amount: 0,
            isValid: false,
        };
    }

    if (isPercent) {
        return {
            rawText,
            isPercent: true,
            value,
            percent: value,
            amount: baseAmount > 0 ? (baseAmount * value) / 100 : 0,
            isValid: true,
        };
    }

    return {
        rawText,
        isPercent: false,
        value,
        percent: baseAmount > 0 ? (value / baseAmount) * 100 : 0,
        amount: value,
        isValid: true,
    };
};

