import React, { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { base44 } from "@/api/base44Client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { Slider } from "@/components/ui/slider";
import {
    Award, Plus, Star, TrendingUp, Users, Eye,
    Edit, Calendar, Target, MessageSquare
} from "lucide-react";
import { toast } from "sonner";

const TIPOS_AVALIACAO = ["90 Dias", "Anual", "360°", "Promocional", "Feedback"];
const STATUS_AVALIACAO = ["Rascunho", "Concluída", "Revisão"];

const COMPETENCIAS_PADRAO = [
    { nome: "Produtividade", peso: 1 },
    { nome: "Qualidade do Trabalho", peso: 1 },
    { nome: "Trabalho em Equipe", peso: 1 },
    { nome: "Comunicação", peso: 1 },
    { nome: "Iniciativa", peso: 1 },
    { nome: "Pontualidade", peso: 1 },
    { nome: "Comprometimento", peso: 1 },
    { nome: "Conhecimento Técnico", peso: 1 },
];

export default function AvaliacoesTab() {
    const queryClient = useQueryClient();
    const [modalNova, setModalNova] = useState(false);
    const [modalDetalhes, setModalDetalhes] = useState(false);
    const [avaliacaoSelecionada, setAvaliacaoSelecionada] = useState(null);
    const [filtroColaborador, setFiltroColaborador] = useState("todos");

    const { data: colaboradores = [] } = useQuery({
        queryKey: ['colaboradores'],
        queryFn: () => base44.entities.Colaborador.list(),
    });

    const { data: avaliacoes = [], isLoading } = useQuery({
        queryKey: ['avaliacoes_desempenho'],
        queryFn: () => base44.entities.AvaliacaoDesempenho.list('-created_at'),
    });

    const colaboradoresAtivos = colaboradores.filter(c => c.status !== 'Desligado');

    // Metrics
    const avaliacoesConcluidas = avaliacoes.filter(a => a.status === 'Concluída');
    const mediaGeral = avaliacoesConcluidas.length > 0
        ? avaliacoesConcluidas.reduce((sum, a) => sum + (Number(a.pontuacao_media) || 0), 0) / avaliacoesConcluidas.length
        : 0;
    const avaliacoesRecentes = avaliacoes.filter(a => {
        const data = new Date(a.data_avaliacao);
        const hoje = new Date();
        const diff = (hoje - data) / (1000 * 60 * 60 * 24);
        return diff <= 30;
    });

    const avaliacoesFiltradas = avaliacoes.filter(a =>
        filtroColaborador === "todos" || a.colaborador_id === filtroColaborador
    );

    const getStatusBadgeStyle = (status) => {
        switch (status) {
            case 'Concluída':
                return { backgroundColor: '#D1FAE5', color: '#065F46' };
            case 'Rascunho':
                return { backgroundColor: '#FEF3C7', color: '#92400E' };
            case 'Revisão':
                return { backgroundColor: '#DBEAFE', color: '#1E40AF' };
            default:
                return { backgroundColor: '#E5E7EB', color: '#374151' };
        }
    };

    const getNotaColor = (nota) => {
        if (nota >= 4) return '#065F46';
        if (nota >= 3) return '#1E40AF';
        if (nota >= 2) return '#92400E';
        return '#991B1B';
    };

    return (
        <div className="space-y-6">
            {/* Metrics */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <Card className="border-0 shadow-lg">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs text-gray-500">Total de Avaliações</p>
                                <p className="text-2xl font-bold" style={{ color: '#07593f' }}>{avaliacoes.length}</p>
                            </div>
                            <Award className="w-8 h-8 opacity-50" style={{ color: '#07593f' }} />
                        </div>
                    </CardContent>
                </Card>
                <Card className="border-0 shadow-lg">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs text-gray-500">Média Geral</p>
                                <p className="text-2xl font-bold text-blue-600">{mediaGeral.toFixed(1)}/5</p>
                            </div>
                            <Star className="w-8 h-8 text-blue-600 opacity-50" />
                        </div>
                    </CardContent>
                </Card>
                <Card className="border-0 shadow-lg">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs text-gray-500">Últimos 30 dias</p>
                                <p className="text-2xl font-bold text-orange-600">{avaliacoesRecentes.length}</p>
                            </div>
                            <Calendar className="w-8 h-8 text-orange-600 opacity-50" />
                        </div>
                    </CardContent>
                </Card>
                <Card className="border-0 shadow-lg">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs text-gray-500">Concluídas</p>
                                <p className="text-2xl font-bold text-green-600">{avaliacoesConcluidas.length}</p>
                            </div>
                            <TrendingUp className="w-8 h-8 text-green-600 opacity-50" />
                        </div>
                    </CardContent>
                </Card>
            </div>

            {/* Actions */}
            <Card className="border-0 shadow-lg">
                <CardContent className="p-4">
                    <div className="flex flex-wrap items-end gap-4">
                        <div className="flex-1 min-w-[200px]">
                            <Label>Filtrar por Colaborador</Label>
                            <Select value={filtroColaborador} onValueChange={setFiltroColaborador}>
                                <SelectTrigger>
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="todos">Todos os Colaboradores</SelectItem>
                                    {colaboradoresAtivos.filter(c => c?.id).map(c => (
                                        <SelectItem key={c.id} value={c.id}>{c.nome_completo}</SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                        <Button
                            onClick={() => { setAvaliacaoSelecionada(null); setModalNova(true); }}
                            style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
                        >
                            <Plus className="w-4 h-4 mr-2" />
                            Nova Avaliação
                        </Button>
                    </div>
                </CardContent>
            </Card>

            {/* Evaluations List */}
            <Card className="border-0 shadow-lg">
                <CardHeader>
                    <CardTitle className="flex items-center gap-2" style={{ color: '#07593f' }}>
                        <Award className="w-5 h-5" />
                        Avaliações de Desempenho
                    </CardTitle>
                </CardHeader>
                <CardContent>
                    {isLoading ? (
                        <div className="flex justify-center py-8">
                            <div className="animate-spin rounded-full h-8 w-8 border-b-2" style={{ borderColor: '#07593f' }} />
                        </div>
                    ) : avaliacoesFiltradas.length === 0 ? (
                        <div className="text-center py-12">
                            <Award className="w-16 h-16 mx-auto mb-4 text-gray-300" />
                            <p className="text-gray-500 mb-4">Nenhuma avaliação encontrada</p>
                            <Button
                                onClick={() => setModalNova(true)}
                                style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
                            >
                                <Plus className="w-4 h-4 mr-2" />
                                Criar Primeira Avaliação
                            </Button>
                        </div>
                    ) : (
                        <div className="space-y-4">
                            {avaliacoesFiltradas.map(avaliacao => (
                                <div
                                    key={avaliacao.id}
                                    className="p-4 rounded-xl border hover:shadow-md transition-all cursor-pointer"
                                    style={{ borderColor: '#E5E0D8' }}
                                    onClick={() => { setAvaliacaoSelecionada(avaliacao); setModalDetalhes(true); }}
                                >
                                    <div className="flex items-start justify-between">
                                        <div>
                                            <p className="font-semibold text-lg" style={{ color: '#07593f' }}>
                                                {avaliacao.colaborador_nome}
                                            </p>
                                            <div className="flex items-center gap-2 text-sm text-gray-500 mt-1">
                                                <Badge variant="outline">{avaliacao.tipo}</Badge>
                                                <span>•</span>
                                                <span>{avaliacao.data_avaliacao && new Date(avaliacao.data_avaliacao).toLocaleDateString('pt-BR')}</span>
                                                {avaliacao.avaliador_nome && (
                                                    <>
                                                        <span>•</span>
                                                        <span>por {avaliacao.avaliador_nome}</span>
                                                    </>
                                                )}
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-3">
                                            {avaliacao.pontuacao_media && (
                                                <div className="text-center">
                                                    <p className="text-2xl font-bold" style={{ color: getNotaColor(avaliacao.pontuacao_media) }}>
                                                        {Number(avaliacao.pontuacao_media).toFixed(1)}
                                                    </p>
                                                    <p className="text-xs text-gray-500">de 5</p>
                                                </div>
                                            )}
                                            <Badge style={getStatusBadgeStyle(avaliacao.status)}>
                                                {avaliacao.status}
                                            </Badge>
                                        </div>
                                    </div>

                                    {/* Star Rating Display */}
                                    {avaliacao.pontuacao_media && (
                                        <div className="flex items-center gap-1 mt-3">
                                            {[1, 2, 3, 4, 5].map(star => (
                                                <Star
                                                    key={star}
                                                    className={`w-5 h-5 ${star <= Math.round(avaliacao.pontuacao_media) ? 'text-yellow-400 fill-yellow-400' : 'text-gray-300'}`}
                                                />
                                            ))}
                                        </div>
                                    )}
                                </div>
                            ))}
                        </div>
                    )}
                </CardContent>
            </Card>

            {/* Modals */}
            {modalNova && (
                <AvaliacaoFormModal
                    avaliacao={avaliacaoSelecionada}
                    colaboradores={colaboradoresAtivos}
                    onClose={() => { setModalNova(false); setAvaliacaoSelecionada(null); }}
                />
            )}

            {modalDetalhes && avaliacaoSelecionada && (
                <AvaliacaoDetalhesModal
                    avaliacao={avaliacaoSelecionada}
                    onClose={() => { setModalDetalhes(false); setAvaliacaoSelecionada(null); }}
                    onEdit={() => {
                        setModalDetalhes(false);
                        setModalNova(true);
                    }}
                />
            )}
        </div>
    );
}

// Evaluation Form Modal
function AvaliacaoFormModal({ avaliacao, colaboradores, onClose }) {
    const queryClient = useQueryClient();
    const isEditing = !!avaliacao;

    const [formData, setFormData] = useState({
        colaborador_id: avaliacao?.colaborador_id || "",
        colaborador_nome: avaliacao?.colaborador_nome || "",
        tipo: avaliacao?.tipo || "Anual",
        data_avaliacao: avaliacao?.data_avaliacao || new Date().toISOString().slice(0, 10),
        status: avaliacao?.status || "Rascunho",
        pontos_fortes: avaliacao?.pontos_fortes || "",
        pontos_melhorar: avaliacao?.pontos_melhorar || "",
        metas_definidas: avaliacao?.metas_definidas || "",
        comentarios_gerais: avaliacao?.comentarios_gerais || "",
    });

    const [competencias, setCompetencias] = useState(() => {
        if (avaliacao?.competencias) {
            return typeof avaliacao.competencias === 'string'
                ? JSON.parse(avaliacao.competencias)
                : avaliacao.competencias;
        }
        return COMPETENCIAS_PADRAO.map(c => ({ ...c, nota: 3 }));
    });

    const [saving, setSaving] = useState(false);

    const handleColaboradorChange = (id) => {
        const colab = colaboradores.find(c => c.id === id);
        setFormData(prev => ({
            ...prev,
            colaborador_id: id,
            colaborador_nome: colab?.nome_completo || "",
        }));
    };

    const handleNotaChange = (index, nota) => {
        setCompetencias(prev => {
            const updated = [...prev];
            updated[index] = { ...updated[index], nota };
            return updated;
        });
    };

    const calcularMedia = () => {
        const totalPeso = competencias.reduce((sum, c) => sum + (c.peso || 1), 0);
        const totalNota = competencias.reduce((sum, c) => sum + ((c.nota || 0) * (c.peso || 1)), 0);
        return totalPeso > 0 ? totalNota / totalPeso : 0;
    };

    const handleSubmit = async () => {
        if (!formData.colaborador_id) {
            toast.error("Selecione um colaborador");
            return;
        }

        setSaving(true);
        try {
            const dataToSave = {
                ...formData,
                competencias: JSON.stringify(competencias),
                pontuacao_media: calcularMedia(),
            };

            if (isEditing) {
                await base44.entities.AvaliacaoDesempenho.update(avaliacao.id, dataToSave);
                toast.success("Avaliação atualizada!");
            } else {
                await base44.entities.AvaliacaoDesempenho.create(dataToSave);
                toast.success("Avaliação criada!");
            }
            queryClient.invalidateQueries(['avaliacoes_desempenho']);
            onClose();
        } catch (error) {
            toast.error("Erro: " + error.message);
        } finally {
            setSaving(false);
        }
    };

    const media = calcularMedia();

    return (
        <Dialog open onOpenChange={onClose}>
            <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle className="flex items-center gap-2" style={{ color: '#07593f' }}>
                        <Award className="w-5 h-5" />
                        {isEditing ? "Editar Avaliação" : "Nova Avaliação de Desempenho"}
                    </DialogTitle>
                </DialogHeader>

                <div className="space-y-6 mt-4">
                    {/* Basic Info */}
                    <div className="grid grid-cols-2 gap-4">
                        <div className="col-span-2">
                            <Label>Colaborador *</Label>
                            <Select value={formData.colaborador_id} onValueChange={handleColaboradorChange}>
                                <SelectTrigger>
                                    <SelectValue placeholder="Selecione o colaborador" />
                                </SelectTrigger>
                                <SelectContent>
                                    {colaboradores.filter(c => c?.id).map(c => (
                                        <SelectItem key={c.id} value={c.id}>{c.nome_completo}</SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                        <div>
                            <Label>Tipo de Avaliação</Label>
                            <Select value={formData.tipo} onValueChange={(v) => setFormData(prev => ({ ...prev, tipo: v }))}>
                                <SelectTrigger>
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    {TIPOS_AVALIACAO.map(t => (
                                        <SelectItem key={t} value={t}>{t}</SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                        <div>
                            <Label>Data da Avaliação</Label>
                            <Input
                                type="date" lang="pt-BR"
                                value={formData.data_avaliacao}
                                onChange={(e) => setFormData(prev => ({ ...prev, data_avaliacao: e.target.value }))}
                            />
                        </div>
                    </div>

                    {/* Competencies */}
                    <div>
                        <Label className="mb-3 block">Avaliação por Competências</Label>
                        <div className="space-y-4 p-4 rounded-lg border" style={{ borderColor: '#E5E0D8' }}>
                            {competencias.map((comp, index) => (
                                <div key={index} className="space-y-2">
                                    <div className="flex items-center justify-between">
                                        <span className="text-sm font-medium">{comp.nome}</span>
                                        <span className="text-lg font-bold" style={{ color: '#07593f' }}>{comp.nota}/5</span>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        {[1, 2, 3, 4, 5].map(nota => (
                                            <button
                                                key={nota}
                                                type="button"
                                                onClick={() => handleNotaChange(index, nota)}
                                                className="p-1"
                                            >
                                                <Star
                                                    className={`w-6 h-6 transition-colors ${nota <= comp.nota ? 'text-yellow-400 fill-yellow-400' : 'text-gray-300 hover:text-yellow-300'}`}
                                                />
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            ))}
                        </div>

                        {/* Average Display */}
                        <div className="mt-4 p-4 rounded-lg text-center" style={{ backgroundColor: '#f0f9ff' }}>
                            <p className="text-sm text-gray-600">Média Geral</p>
                            <p className="text-3xl font-bold" style={{ color: '#07593f' }}>{media.toFixed(1)}/5</p>
                            <div className="flex justify-center gap-1 mt-2">
                                {[1, 2, 3, 4, 5].map(star => (
                                    <Star
                                        key={star}
                                        className={`w-6 h-6 ${star <= Math.round(media) ? 'text-yellow-400 fill-yellow-400' : 'text-gray-300'}`}
                                    />
                                ))}
                            </div>
                        </div>
                    </div>

                    {/* Comments */}
                    <div className="space-y-4">
                        <div>
                            <Label className="flex items-center gap-2">
                                <TrendingUp className="w-4 h-4 text-green-600" />
                                Pontos Fortes
                            </Label>
                            <Textarea
                                value={formData.pontos_fortes}
                                onChange={(e) => setFormData(prev => ({ ...prev, pontos_fortes: e.target.value }))}
                                placeholder="Destaque os pontos positivos do colaborador..."
                                rows={2}
                            />
                        </div>
                        <div>
                            <Label className="flex items-center gap-2">
                                <Target className="w-4 h-4 text-orange-600" />
                                Pontos a Melhorar
                            </Label>
                            <Textarea
                                value={formData.pontos_melhorar}
                                onChange={(e) => setFormData(prev => ({ ...prev, pontos_melhorar: e.target.value }))}
                                placeholder="Identifique áreas de melhoria..."
                                rows={2}
                            />
                        </div>
                        <div>
                            <Label className="flex items-center gap-2">
                                <Target className="w-4 h-4 text-blue-600" />
                                Metas para o Próximo Período
                            </Label>
                            <Textarea
                                value={formData.metas_definidas}
                                onChange={(e) => setFormData(prev => ({ ...prev, metas_definidas: e.target.value }))}
                                placeholder="Defina metas claras e mensuráveis..."
                                rows={2}
                            />
                        </div>
                        <div>
                            <Label className="flex items-center gap-2">
                                <MessageSquare className="w-4 h-4 text-gray-600" />
                                Comentários Gerais
                            </Label>
                            <Textarea
                                value={formData.comentarios_gerais}
                                onChange={(e) => setFormData(prev => ({ ...prev, comentarios_gerais: e.target.value }))}
                                placeholder="Observações adicionais..."
                                rows={2}
                            />
                        </div>
                    </div>

                    {/* Status */}
                    <div>
                        <Label>Status da Avaliação</Label>
                        <Select value={formData.status} onValueChange={(v) => setFormData(prev => ({ ...prev, status: v }))}>
                            <SelectTrigger>
                                <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
                                {STATUS_AVALIACAO.map(s => (
                                    <SelectItem key={s} value={s}>{s}</SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </div>
                </div>

                <div className="flex justify-end gap-3 mt-6">
                    <Button variant="outline" onClick={onClose}>Cancelar</Button>
                    <Button
                        onClick={handleSubmit}
                        disabled={saving}
                        style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
                    >
                        {saving ? "Salvando..." : isEditing ? "Salvar Alterações" : "Criar Avaliação"}
                    </Button>
                </div>
            </DialogContent>
        </Dialog>
    );
}

// Evaluation Details Modal
function AvaliacaoDetalhesModal({ avaliacao, onClose, onEdit }) {
    const competencias = avaliacao.competencias
        ? (typeof avaliacao.competencias === 'string' ? JSON.parse(avaliacao.competencias) : avaliacao.competencias)
        : [];

    const getNotaColor = (nota) => {
        if (nota >= 4) return '#065F46';
        if (nota >= 3) return '#1E40AF';
        if (nota >= 2) return '#92400E';
        return '#991B1B';
    };

    return (
        <Dialog open onOpenChange={onClose}>
            <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle className="flex items-center gap-2" style={{ color: '#07593f' }}>
                        <Award className="w-5 h-5" />
                        Detalhes da Avaliação
                    </DialogTitle>
                </DialogHeader>

                <div className="space-y-6 mt-4">
                    {/* Header */}
                    <div className="p-4 rounded-lg" style={{ backgroundColor: '#f0f9ff' }}>
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="font-bold text-xl" style={{ color: '#07593f' }}>{avaliacao.colaborador_nome}</p>
                                <p className="text-sm text-gray-500">
                                    {avaliacao.tipo} • {avaliacao.data_avaliacao && new Date(avaliacao.data_avaliacao).toLocaleDateString('pt-BR')}
                                </p>
                            </div>
                            <div className="text-center">
                                <p className="text-3xl font-bold" style={{ color: getNotaColor(avaliacao.pontuacao_media) }}>
                                    {Number(avaliacao.pontuacao_media || 0).toFixed(1)}
                                </p>
                                <p className="text-sm text-gray-500">de 5</p>
                            </div>
                        </div>
                    </div>

                    {/* Competencies */}
                    {competencias.length > 0 && (
                        <div>
                            <Label className="mb-3 block">Competências Avaliadas</Label>
                            <div className="space-y-3">
                                {competencias.map((comp, index) => (
                                    <div key={index} className="flex items-center justify-between p-3 rounded-lg border" style={{ borderColor: '#E5E0D8' }}>
                                        <span className="font-medium">{comp.nome}</span>
                                        <div className="flex items-center gap-2">
                                            <div className="flex gap-0.5">
                                                {[1, 2, 3, 4, 5].map(star => (
                                                    <Star
                                                        key={star}
                                                        className={`w-4 h-4 ${star <= comp.nota ? 'text-yellow-400 fill-yellow-400' : 'text-gray-300'}`}
                                                    />
                                                ))}
                                            </div>
                                            <span className="font-bold ml-2" style={{ color: getNotaColor(comp.nota) }}>
                                                {comp.nota}/5
                                            </span>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Comments */}
                    {avaliacao.pontos_fortes && (
                        <div>
                            <Label className="flex items-center gap-2 mb-2">
                                <TrendingUp className="w-4 h-4 text-green-600" />
                                Pontos Fortes
                            </Label>
                            <p className="p-3 rounded-lg bg-green-50 text-green-800">{avaliacao.pontos_fortes}</p>
                        </div>
                    )}

                    {avaliacao.pontos_melhorar && (
                        <div>
                            <Label className="flex items-center gap-2 mb-2">
                                <Target className="w-4 h-4 text-orange-600" />
                                Pontos a Melhorar
                            </Label>
                            <p className="p-3 rounded-lg bg-orange-50 text-orange-800">{avaliacao.pontos_melhorar}</p>
                        </div>
                    )}

                    {avaliacao.metas_definidas && (
                        <div>
                            <Label className="flex items-center gap-2 mb-2">
                                <Target className="w-4 h-4 text-blue-600" />
                                Metas Definidas
                            </Label>
                            <p className="p-3 rounded-lg bg-blue-50 text-blue-800">{avaliacao.metas_definidas}</p>
                        </div>
                    )}

                    {avaliacao.comentarios_gerais && (
                        <div>
                            <Label className="flex items-center gap-2 mb-2">
                                <MessageSquare className="w-4 h-4 text-gray-600" />
                                Comentários Gerais
                            </Label>
                            <p className="p-3 rounded-lg border text-gray-700" style={{ borderColor: '#E5E0D8' }}>
                                {avaliacao.comentarios_gerais}
                            </p>
                        </div>
                    )}
                </div>

                <div className="flex justify-end gap-3 mt-6">
                    <Button variant="outline" onClick={onClose}>Fechar</Button>
                    <Button
                        onClick={onEdit}
                        style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
                    >
                        <Edit className="w-4 h-4 mr-2" />
                        Editar Avaliação
                    </Button>
                </div>
            </DialogContent>
        </Dialog>
    );
}

import React from "react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {
    User, Phone, Mail, MapPin, Calendar, DollarSign,
    Briefcase, Building, CreditCard, Edit, FileText,
    Clock, UserCheck, KeyRound, ShieldAlert, Moon, Zap
} from "lucide-react";

export default function ColaboradorDetalhesModal({ colaborador, onClose, onEdit, canEdit = false }) {
    if (!colaborador) return null;

    const getStatusBadgeStyle = (status) => {
        switch (status) {
            case 'Ativo':
                return { backgroundColor: '#D1FAE5', color: '#065F46' };
            case 'Férias':
                return { backgroundColor: '#DBEAFE', color: '#1E40AF' };
            case 'Licença':
                return { backgroundColor: '#FEF3C7', color: '#92400E' };
            case 'Afastado':
                return { backgroundColor: '#FED7AA', color: '#C2410C' };
            case 'Desligado':
                return { backgroundColor: '#FEE2E2', color: '#991B1B' };
            default:
                return { backgroundColor: '#E5E7EB', color: '#374151' };
        }
    };

    const calcularTempoEmpresa = () => {
        if (!colaborador.data_admissao) return null;
        const inicio = new Date(colaborador.data_admissao);
        const fim = colaborador.data_demissao ? new Date(colaborador.data_demissao) : new Date();
        const diffTime = Math.abs(fim - inicio);
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
        const years = Math.floor(diffDays / 365);
        const months = Math.floor((diffDays % 365) / 30);
        if (years > 0) {
            return `${years} ano${years > 1 ? 's' : ''} e ${months} mês${months !== 1 ? 'es' : ''}`;
        }
        return `${months} mês${months !== 1 ? 'es' : ''}`;
    };

    const InfoItem = ({ icon: Icon, label, value, className = "" }) => (
        value ? (
            <div className={`flex items-start gap-3 ${className}`}>
                <Icon className="w-4 h-4 mt-0.5 text-gray-400 flex-shrink-0" />
                <div>
                    <p className="text-xs text-gray-500">{label}</p>
                    <p className="font-medium" style={{ color: '#07593f' }}>{value}</p>
                </div>
            </div>
        ) : null
    );

    return (
        <Dialog open onOpenChange={onClose}>
            <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                    <div className="flex items-center justify-between">
                        <DialogTitle className="flex items-center gap-3">
                            <div
                                className="w-14 h-14 rounded-full flex items-center justify-center text-2xl font-bold text-white"
                                style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
                            >
                                {colaborador.nome_completo?.charAt(0).toUpperCase() || '?'}
                            </div>
                            <div>
                                <h2 className="text-xl font-bold" style={{ color: '#07593f' }}>
                                    {colaborador.nome_completo}
                                </h2>
                                <p className="text-sm text-gray-500">
                                    {colaborador.descricao_cargo || 'Sem cargo'}
                                </p>
                            </div>
                        </DialogTitle>
                        <div className="flex items-center gap-2">
                            <Badge style={getStatusBadgeStyle(colaborador.status)}>
                                {colaborador.status || 'Indefinido'}
                            </Badge>
                            {colaborador.tipo_contrato && (
                                <Badge variant="outline">{colaborador.tipo_contrato}</Badge>
                            )}
                        </div>
                    </div>
                </DialogHeader>

                <div className="mt-6 space-y-6">
                    {/* Resumo Rápido */}
                    <div className="grid grid-cols-3 gap-4">
                        {colaborador.salario_base && (
                            <div className="p-4 rounded-xl" style={{ backgroundColor: '#f0f9ff' }}>
                                <div className="flex items-center gap-2 mb-1">
                                    <DollarSign className="w-4 h-4" style={{ color: '#07593f' }} />
                                    <span className="text-xs text-gray-500">Salário Base</span>
                                </div>
                                <p className="text-xl font-bold" style={{ color: '#07593f' }}>
                                    R$ {Number(colaborador.salario_base).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                                </p>
                            </div>
                        )}
                        {colaborador.data_admissao && (
                            <div className="p-4 rounded-xl" style={{ backgroundColor: '#f0f9ff' }}>
                                <div className="flex items-center gap-2 mb-1">
                                    <Clock className="w-4 h-4" style={{ color: '#07593f' }} />
                                    <span className="text-xs text-gray-500">Tempo de Empresa</span>
                                </div>
                                <p className="text-xl font-bold" style={{ color: '#07593f' }}>
                                    {calcularTempoEmpresa()}
                                </p>
                            </div>
                        )}
                        {colaborador.carga_horaria && (
                            <div className="p-4 rounded-xl" style={{ backgroundColor: '#f0f9ff' }}>
                                <div className="flex items-center gap-2 mb-1">
                                    <Briefcase className="w-4 h-4" style={{ color: '#07593f' }} />
                                    <span className="text-xs text-gray-500">Carga Horária</span>
                                </div>
                                <p className="text-xl font-bold" style={{ color: '#07593f' }}>
                                    {colaborador.carga_horaria}h/semana
                                </p>
                            </div>
                        )}
                    </div>

                    {/* Dados Pessoais */}
                    <div>
                        <h3 className="font-semibold mb-3 flex items-center gap-2" style={{ color: '#07593f' }}>
                            <User className="w-4 h-4" />
                            Dados Pessoais
                        </h3>
                        <div className="grid grid-cols-2 md:grid-cols-3 gap-4 p-4 rounded-xl border" style={{ borderColor: '#E5E0D8' }}>
                            <InfoItem icon={FileText} label="CPF" value={colaborador.cpf} />
                            <InfoItem icon={FileText} label="RG" value={colaborador.rg} />
                            <InfoItem icon={Calendar} label="Data de Nascimento" value={colaborador.data_nascimento ? new Date(colaborador.data_nascimento).toLocaleDateString('pt-BR') : null} />
                            <InfoItem icon={Phone} label="Telefone" value={colaborador.telefone} />
                            <InfoItem icon={Mail} label="Email" value={colaborador.email} className="col-span-2" />
                        </div>
                    </div>

                    {/* Dados Profissionais */}
                    <div>
                        <h3 className="font-semibold mb-3 flex items-center gap-2" style={{ color: '#07593f' }}>
                            <Briefcase className="w-4 h-4" />
                            Dados Profissionais
                        </h3>
                        <div className="grid grid-cols-2 md:grid-cols-3 gap-4 p-4 rounded-xl border" style={{ borderColor: '#E5E0D8' }}>
                            <InfoItem icon={Building} label="Cargo" value={colaborador.descricao_cargo} />
                            <InfoItem icon={KeyRound} label="Matrícula" value={colaborador.matricula} />

                            <InfoItem icon={FileText} label="Tipo de Contrato" value={colaborador.tipo_contrato} />
                            <InfoItem icon={Calendar} label="Data de Admissão" value={colaborador.data_admissao ? new Date(colaborador.data_admissao).toLocaleDateString('pt-BR') : null} />
                            <InfoItem icon={DollarSign} label="Salário Base" value={colaborador.salario_base ? `R$ ${Number(colaborador.salario_base).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}` : null} />
                            <InfoItem icon={Clock} label="Carga Horária" value={colaborador.carga_horaria ? `${colaborador.carga_horaria}h/semana` : null} />
                            {colaborador.status === 'Desligado' && (
                                <>
                                    <InfoItem icon={Calendar} label="Data de Demissão" value={colaborador.data_demissao ? new Date(colaborador.data_demissao).toLocaleDateString('pt-BR') : null} />
                                    <InfoItem icon={FileText} label="Motivo da Demissão" value={colaborador.motivo_demissao} className="col-span-2" />
                                </>
                            )}
                        </div>
                    </div>

                    {/* Endereço */}
                    {(colaborador.endereco || colaborador.cidade) && (
                        <div>
                            <h3 className="font-semibold mb-3 flex items-center gap-2" style={{ color: '#07593f' }}>
                                <MapPin className="w-4 h-4" />
                                Endereço
                            </h3>
                            <div className="p-4 rounded-xl border" style={{ borderColor: '#E5E0D8' }}>
                                <p className="font-medium" style={{ color: '#07593f' }}>
                                    {[
                                        colaborador.endereco,
                                        colaborador.numero,
                                        colaborador.complemento
                                    ].filter(Boolean).join(', ')}
                                </p>
                                <p className="text-sm text-gray-500">
                                    {[
                                        colaborador.bairro,
                                        colaborador.cidade,
                                        colaborador.estado,
                                        colaborador.cep
                                    ].filter(Boolean).join(' - ')}
                                </p>
                            </div>
                        </div>
                    )}

                    {/* Benefícios */}
                    {(colaborador.recebe_vale !== undefined || colaborador.dia_vale || colaborador.vale_transporte || colaborador.vale_alimentacao || colaborador.vale_refeicao || colaborador.plano_saude || colaborador.plano_odontologico || colaborador.bonus_mensal || colaborador.outros_beneficios || colaborador.pensao_alimenticia || colaborador.adicional_noturno || colaborador.periculosidade || colaborador.insalubridade_grau) && (
                        <div>
                            <h3 className="font-semibold mb-3 flex items-center gap-2" style={{ color: '#07593f' }}>
                                <DollarSign className="w-4 h-4" />
                                Benefícios e Adicionais
                            </h3>
                            <div className="grid grid-cols-2 md:grid-cols-3 gap-4 p-4 rounded-xl border" style={{ borderColor: '#E5E0D8' }}>
                                <InfoItem icon={Calendar} label="Recebe Vale" value={colaborador.recebe_vale ? 'Sim' : 'Não'} />
                                {colaborador.recebe_vale && (
                                    <InfoItem icon={Calendar} label="Dia do Vale" value={colaborador.dia_vale ? `Todo dia ${colaborador.dia_vale}` : null} />
                                )}
                                {colaborador.recebe_vale && (Number(colaborador.valor_dia_pagamento) > 0 || Number(colaborador.valor_dia_vale) > 0) && (
                                    <>
                                        <InfoItem icon={DollarSign} label={`Valor no Dia ${colaborador.dia_pagamento || 5}`} value={Number(colaborador.valor_dia_pagamento) > 0 ? `R$ ${Number(colaborador.valor_dia_pagamento).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}` : null} />
                                        <InfoItem icon={DollarSign} label={`Valor no Dia ${colaborador.dia_vale || 20} (Vale)`} value={Number(colaborador.valor_dia_vale) > 0 ? `R$ ${Number(colaborador.valor_dia_vale).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}` : null} />
                                    </>
                                )}
                                <InfoItem icon={DollarSign} label="Vale Transporte" value={colaborador.vale_transporte ? `R$ ${Number(colaborador.vale_transporte).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}` : null} />
                                <InfoItem icon={DollarSign} label="Vale Alimentação" value={colaborador.vale_alimentacao ? `R$ ${Number(colaborador.vale_alimentacao).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}` : null} />
                                <InfoItem icon={DollarSign} label="Vale Refeição" value={colaborador.vale_refeicao ? `R$ ${Number(colaborador.vale_refeicao).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}` : null} />
                                <InfoItem icon={DollarSign} label="Plano de Saúde" value={colaborador.plano_saude ? `R$ ${Number(colaborador.plano_saude).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}` : null} />
                                <InfoItem icon={DollarSign} label="Plano Odontológico" value={colaborador.plano_odontologico ? `R$ ${Number(colaborador.plano_odontologico).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}` : null} />
                                <InfoItem icon={DollarSign} label="Bônus Mensal" value={colaborador.bonus_mensal ? `R$ ${Number(colaborador.bonus_mensal).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}` : null} />
                                {colaborador.outros_beneficios && <InfoItem icon={DollarSign} label={colaborador.descricao_outros_beneficios || "Outros Benefícios"} value={`R$ ${Number(colaborador.outros_beneficios).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`} />}
                                <InfoItem icon={DollarSign} label="Pensão Alimentícia" value={colaborador.pensao_alimenticia ? `R$ ${Number(colaborador.pensao_alimenticia).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}` : null} />
                                {colaborador.adicional_noturno && <InfoItem icon={Moon} label="Adicional Noturno" value="+20%" />}
                                {colaborador.periculosidade && <InfoItem icon={Zap} label="Periculosidade" value="+30%" />}
                                <InfoItem icon={ShieldAlert} label="Insalubridade" value={colaborador.insalubridade_grau ? { minimo: 'Grau Mínimo (10%)', medio: 'Grau Médio (20%)', maximo: 'Grau Máximo (40%)' }[colaborador.insalubridade_grau] : null} />
                            </div>
                        </div>
                    )}

                    {/* Dados Bancários */}
                    {(colaborador.banco || colaborador.pix) && (
                        <div>
                            <h3 className="font-semibold mb-3 flex items-center gap-2" style={{ color: '#07593f' }}>
                                <CreditCard className="w-4 h-4" />
                                Dados Bancários
                            </h3>
                            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 p-4 rounded-xl border" style={{ borderColor: '#E5E0D8' }}>
                                <InfoItem icon={CreditCard} label="Banco" value={colaborador.banco} />
                                <InfoItem icon={CreditCard} label="Agência" value={colaborador.agencia} />
                                <InfoItem icon={CreditCard} label="Conta" value={colaborador.conta} />
                                <InfoItem icon={CreditCard} label="Chave PIX" value={colaborador.pix} />
                            </div>
                        </div>
                    )}

                    {/* Vínculo Sistema */}
                    {colaborador.user_id && (
                        <div>
                            <h3 className="font-semibold mb-3 flex items-center gap-2" style={{ color: '#07593f' }}>
                                <UserCheck className="w-4 h-4" />
                                Vínculo com Sistema
                            </h3>
                            <div className="p-4 rounded-xl" style={{ backgroundColor: '#D1FAE5' }}>
                                <p className="text-sm text-green-800">
                                    Este colaborador está vinculado a um usuário do sistema e possui acesso à plataforma.
                                </p>
                            </div>
                        </div>
                    )}

                    {/* Observações */}
                    {colaborador.observacoes && (
                        <div>
                            <h3 className="font-semibold mb-3 flex items-center gap-2" style={{ color: '#07593f' }}>
                                <FileText className="w-4 h-4" />
                                Observações
                            </h3>
                            <div className="p-4 rounded-xl border" style={{ borderColor: '#E5E0D8' }}>
                                <p className="text-gray-600 whitespace-pre-wrap">{colaborador.observacoes}</p>
                            </div>
                        </div>
                    )}
                </div>

                <div className="flex justify-end gap-3 mt-6 pt-4 border-t">
                    <Button variant="outline" onClick={onClose}>
                        Fechar
                    </Button>
                    {canEdit && (
                        <Button
                            onClick={onEdit}
                            style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
                        >
                            <Edit className="w-4 h-4 mr-2" />
                            Editar Colaborador
                        </Button>
                    )}
                </div>
            </DialogContent>
        </Dialog>
    );
}

import React, { useMemo, useState, useEffect } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useNavigate } from "react-router-dom";
import { base44 } from "@/api/base44Client";
import { useAuth } from "@/hooks/useAuth";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Alert, AlertDescription } from "@/components/ui/alert";
import {
    User,
    Briefcase,
    Save,
    Loader2,
    DollarSign,
    Calendar,
    KeyRound,
    CheckCircle2,
    UserX,
    UserCheck,
    ExternalLink,
    Info,
    Users,
    MapPin,
    CreditCard,
    Shield,
    AlertTriangle,
    X,
} from "lucide-react";
import { toast } from "sonner";
import { formatarCEP, formatarCPF, formatarTelefone } from "@/utils/formatters";
import { gerarResumoEstimado } from "@/utils/calculosTrabalhistas";

const STATUS_OPTIONS = ["Ativo", "Férias", "Licença", "Afastado", "Desligado"];
const CONTRATO_OPTIONS = ["CLT", "PJ", "Estagiário", "Temporário"];
const ESTADOS = [
    "AC", "AL", "AP", "AM", "BA", "CE", "DF", "ES", "GO", "MA", "MT", "MS",
    "MG", "PA", "PB", "PR", "PE", "PI", "RJ", "RN", "RS", "RO", "RR", "SC",
    "SP", "SE", "TO",
];
const TIPO_PAGAMENTO = ["Mensal", "Quinzenal", "Semanal"];
const RECEBE_VALE_OPCOES = [
    { value: "sim", label: "Sim" },
    { value: "nao", label: "Não" },
];
const DIAS_PAGAMENTO = Array.from({ length: 31 }, (_, i) => i + 1);
const INSALUBRIDADE_OPCOES = [
    { value: "nao_aplicavel", label: "Não aplicável" },
    { value: "minimo", label: "Grau Mínimo (10%)" },
    { value: "medio", label: "Grau Médio (20%)" },
    { value: "maximo", label: "Grau Máximo (40%)" },
];

const formatCurrency = (value) => {
    const num = Number(value) || 0;
    return num.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
};

function SectionTitle({ children }) {
    return (
        <p className="text-xs font-semibold uppercase tracking-widest text-gray-400 mb-3 mt-1">
            {children}
        </p>
    );
}

export default function ColaboradorModal({
    colaborador,
    usuarios = [],
    onClose,
    onSuccess,
    initialTab = "pessoal",
}) {
    const queryClient = useQueryClient();
    const navigate = useNavigate();
    const { can } = useAuth();
    const canManageAccess = can("manage_user_access");
    const isEditing = !!colaborador && !colaborador.isAcessoRapido;

    const [formData, setFormData] = useState({
        nome_completo: colaborador?.nome_completo || "",
        cpf: colaborador?.cpf || "",
        rg: colaborador?.rg || "",
        data_nascimento: colaborador?.data_nascimento || "",
        telefone: colaborador?.telefone || "",
        email: colaborador?.email || "",
        // Endereço — merged into pessoal tab
        cep: colaborador?.cep || "",
        endereco: colaborador?.endereco || "",
        numero: colaborador?.numero || "",
        complemento: colaborador?.complemento || "",
        bairro: colaborador?.bairro || "",
        cidade: colaborador?.cidade || "",
        estado: colaborador?.estado || "",
        // Profissional
        descricao_cargo: colaborador?.descricao_cargo || "",
        status: colaborador?.status || "Ativo",
        tipo_contrato: colaborador?.tipo_contrato || "CLT",
        data_admissao: colaborador?.data_admissao || "",
        carga_horaria: colaborador?.carga_horaria || 44,
        data_demissao: colaborador?.data_demissao || "",
        motivo_demissao: colaborador?.motivo_demissao || "",
        adicional_noturno: colaborador?.adicional_noturno || false,
        insalubridade_grau: colaborador?.insalubridade_grau || "",
        periculosidade: colaborador?.periculosidade || false,
        pin_montagem: colaborador?.pin_montagem || "",
        observacoes: colaborador?.observacoes || "",
        // Remuneração
        salario_base: colaborador?.salario_base || "",
        numero_dependentes: colaborador?.numero_dependentes || 0,
        dia_pagamento: colaborador?.dia_pagamento || 5,
        tipo_dia_pagamento: colaborador?.tipo_dia_pagamento || "util",
        tipo_pagamento: colaborador?.tipo_pagamento || "Mensal",
        recebe_vale: typeof colaborador?.recebe_vale === "boolean"
            ? colaborador.recebe_vale
            : !!(
                Number(colaborador?.vale_transporte) ||
                Number(colaborador?.vale_alimentacao) ||
                Number(colaborador?.vale_refeicao)
            ),
        dia_vale: colaborador?.dia_vale || 20,
        tipo_dia_vale: colaborador?.tipo_dia_vale || "fixo",
        valor_dia_pagamento: colaborador?.valor_dia_pagamento || "",
        valor_dia_vale: colaborador?.valor_dia_vale || "",
        vale_transporte: colaborador?.vale_transporte || "",
        vale_alimentacao: colaborador?.vale_alimentacao || "",
        vale_refeicao: colaborador?.vale_refeicao || "",
        plano_saude: colaborador?.plano_saude || "",
        plano_odontologico: colaborador?.plano_odontologico || "",
        bonus_mensal: colaborador?.bonus_mensal || "",
        outros_beneficios: colaborador?.outros_beneficios || "",
        descricao_outros_beneficios: colaborador?.descricao_outros_beneficios || "",
        pensao_alimenticia: Number(colaborador?.pensao_alimenticia) || 0,
        // Descontos
        desconto_vale_transporte: colaborador?.desconto_vale_transporte || "",
        desconto_plano_saude: colaborador?.desconto_plano_saude || "",
        desconto_adiantamento: colaborador?.desconto_adiantamento || "",
        outros_descontos: colaborador?.outros_descontos || "",
        descricao_outros_descontos: colaborador?.descricao_outros_descontos || "",
        // Tributos Manuais
        tipo_inss: colaborador?.tipo_inss || "automatico",
        valor_inss: colaborador?.valor_inss || "",
        tipo_irrf: colaborador?.tipo_irrf || "automatico",
        valor_irrf: colaborador?.valor_irrf || "",
        tipo_fgts: colaborador?.tipo_fgts || "automatico",
        valor_fgts: colaborador?.valor_fgts || "",
        // Dados bancários
        banco: colaborador?.banco || "",
        agencia: colaborador?.agencia || "",
        conta: colaborador?.conta || "",
        pix: colaborador?.pix || "",
        // Sistema
        user_id: colaborador?.user_id || "",
    });

    const [saving, setSaving] = useState(false);

    // Estado local para lista dinâmica de descontos
    const [listaDescontos, setListaDescontos] = useState(() => {
        try {
            const parsed = JSON.parse(colaborador?.descricao_outros_descontos || "[]");
            if (Array.isArray(parsed) && parsed.length > 0) return parsed;
        } catch {
            // Se não for JSON (sistema antigo), tenta usar o valor existente
            if (colaborador?.outros_descontos > 0) {
                return [{ descricao: colaborador?.descricao_outros_descontos || "Outros", valor: Number(colaborador?.outros_descontos) || 0 }];
            }
        }
        return [];
    });

    // Atualiza formData sempre que a lista de descontos muda
    useEffect(() => {
        const total = listaDescontos.reduce((acc, curr) => acc + (Number(curr.valor) || 0), 0);
        const descricaoJson = JSON.stringify(listaDescontos);
        
        // Atualiza apenas se mudou para evitar loop
        if (total !== formData.outros_descontos || descricaoJson !== formData.descricao_outros_descontos) {
            handleChange("outros_descontos", total);
            handleChange("descricao_outros_descontos", descricaoJson);
        }
    }, [listaDescontos, formData.outros_descontos, formData.descricao_outros_descontos]);

    const usaPinMontagem =
        !!formData.pin_montagem ||
        formData.descricao_cargo?.toLowerCase().includes("montador");

    const totals = useMemo(() => gerarResumoEstimado(formData), [formData]);

    const createMutation = useMutation({
        mutationFn: async (data) => {
            const colaboradorData = { ...data };
            colaboradorData.pin_montagem = data.pin_montagem || null;
            return base44.entities.Colaborador.create(colaboradorData);
        },
        onSuccess: (createdData) => {
            queryClient.invalidateQueries(["colaboradores"]);
            queryClient.invalidateQueries(["users"]);
            toast.success("Colaborador cadastrado com sucesso!");
            if (onSuccess) {
                onSuccess({ ...formData, ...createdData, id: createdData.id });
            } else {
                onClose();
            }
        },
        onError: (error) => {
            toast.error("Erro ao cadastrar colaborador: " + error.message);
        },
    });

    const updateMutation = useMutation({
        mutationFn: async ({ id, data }) => {
            const colaboradorData = { ...data };
            colaboradorData.pin_montagem = data.pin_montagem || null;
            return base44.entities.Colaborador.update(id, colaboradorData);
        },
        onSuccess: () => {
            queryClient.invalidateQueries(["colaboradores"]);
            queryClient.invalidateQueries(["users"]);
            toast.success("Colaborador atualizado com sucesso!");
            onClose();
        },
        onError: (error) => {
            toast.error("Erro ao atualizar colaborador: " + error.message);
        },
    });

    const linkedUser = useMemo(
        () => usuarios.find((u) => u.id === formData.user_id),
        [formData.user_id, usuarios]
    );

    const handleChange = (field, value) => {
        setFormData((prev) => ({ ...prev, [field]: value }));
    };

    const buscarCep = async () => {
        const cep = formData.cep?.replace(/\D/g, "");
        if (cep?.length === 8) {
            try {
                const response = await fetch(`https://viacep.com.br/ws/${cep}/json/`);
                const data = await response.json();
                if (!data.erro) {
                    setFormData((prev) => ({
                        ...prev,
                        endereco: data.logradouro,
                        bairro: data.bairro,
                        cidade: data.localidade,
                        estado: data.uf,
                    }));
                }
            } catch (error) {
                console.error("Erro ao buscar CEP:", error);
            }
        }
    };

    const handleSubmit = async (e) => {
        if (e) e.preventDefault();
        setSaving(true);
        try {
            // Limpa campos numéricos vazios para evitar erro do Supabase
            const cleanPayload = { ...formData };
            const numericFields = [
                'salario_base', 'numero_dependentes', 'dia_pagamento', 'dia_vale',
                'valor_dia_pagamento', 'valor_dia_vale', 'vale_transporte', 'vale_alimentacao',
                'vale_refeicao', 'plano_saude', 'plano_odontologico', 'bonus_mensal',
                'outros_beneficios', 'pensao_alimenticia', 'desconto_vale_transporte',
                'desconto_plano_saude', 'desconto_adiantamento', 'outros_descontos',
                'valor_inss', 'valor_irrf', 'valor_fgts'
            ];

            for (const field of numericFields) {
                if (cleanPayload[field] === "") {
                    cleanPayload[field] = null;
                } else if (cleanPayload[field] !== null && cleanPayload[field] !== undefined) {
                    cleanPayload[field] = Number(cleanPayload[field]);
                }
            }

            // Limpa campos de data vazios
            const dateFields = ['data_nascimento', 'data_admissao', 'data_demissao'];
            for (const field of dateFields) {
                if (cleanPayload[field] === "") {
                    cleanPayload[field] = null;
                }
            }

            const payload = {
                ...cleanPayload,
                user_id: colaborador?.user_id || formData.user_id || null,
            };
            
            // Remove user_id nulo para não violar foreign key se não tiver uuid
            if (!payload.user_id) {
                delete payload.user_id;
            }

            if (isEditing) {
                await updateMutation.mutateAsync({ id: colaborador.id, data: payload });
            } else {
                await createMutation.mutateAsync(payload);
            }
        } catch (error) {
            console.error("Erro ao salvar:", error);
        } finally {
            setSaving(false);
        }
    };

    return (
        <Dialog open onOpenChange={onClose}>
            <DialogContent 
                className="max-w-4xl max-h-[90vh] overflow-y-auto"
                onInteractOutside={(e) => e.preventDefault()}
            >
                <DialogHeader>
                    <DialogTitle
                        className="flex items-center gap-2 text-xl font-bold"
                        style={{ color: "#07593f" }}
                    >
                        {isEditing ? (
                            <UserCheck className="w-5 h-5" />
                        ) : (
                            <User className="w-5 h-5" />
                        )}
                        {isEditing ? "Editar Colaborador" : "Novo Colaborador"}
                    </DialogTitle>
                </DialogHeader>

                <Tabs defaultValue={initialTab} className="mt-2">
                    <TabsList className="grid grid-cols-4 h-auto p-1 bg-gray-100 rounded-xl">
                        <TabsTrigger value="pessoal" className="rounded-lg py-2 text-xs sm:text-sm">
                            <User className="w-4 h-4 mr-1.5 hidden sm:inline" />
                            Pessoal
                        </TabsTrigger>
                        <TabsTrigger value="profissional" className="rounded-lg py-2 text-xs sm:text-sm">
                            <Briefcase className="w-4 h-4 mr-1.5 hidden sm:inline" />
                            Profissional
                        </TabsTrigger>
                        <TabsTrigger value="remuneracao" className="rounded-lg py-2 text-xs sm:text-sm">
                            <DollarSign className="w-4 h-4 mr-1.5 hidden sm:inline" />
                            Remuneração
                        </TabsTrigger>
                        <TabsTrigger value="sistema" className="rounded-lg py-2 text-xs sm:text-sm">
                            <KeyRound className="w-4 h-4 mr-1.5 hidden sm:inline" />
                            Sistema
                        </TabsTrigger>
                    </TabsList>

                    {/* ── Pessoal ── */}
                    <TabsContent value="pessoal" className="space-y-5 mt-4">
                        <SectionTitle>Dados de Identificação</SectionTitle>
                        <div className="grid grid-cols-3 gap-4">
                            <div className="col-span-2">
                                <Label>Nome Completo</Label>
                                <Input
                                    value={formData.nome_completo}
                                    onChange={(e) =>
                                        handleChange("nome_completo", e.target.value)
                                    }
                                    placeholder="Nome completo do colaborador"
                                />
                            </div>
                            <div>
                                <Label>Data de Nascimento</Label>
                                <Input
                                    type="date" lang="pt-BR"
                                    value={formData.data_nascimento}
                                    onChange={(e) =>
                                        handleChange("data_nascimento", e.target.value)
                                    }
                                />
                            </div>
                            <div>
                                <Label>CPF</Label>
                                <Input
                                    value={formData.cpf}
                                    onChange={(e) =>
                                        handleChange("cpf", formatarCPF(e.target.value))
                                    }
                                    maxLength={14}
                                    placeholder="000.000.000-00"
                                />
                            </div>
                            <div>
                                <Label>RG</Label>
                                <Input
                                    value={formData.rg}
                                    onChange={(e) => handleChange("rg", e.target.value)}
                                    placeholder="Número do RG"
                                />
                            </div>
                            <div>
                                <Label>Telefone</Label>
                                <Input
                                    value={formData.telefone}
                                    onChange={(e) =>
                                        handleChange(
                                            "telefone",
                                            formatarTelefone(e.target.value)
                                        )
                                    }
                                    placeholder="(00) 00000-0000"
                                />
                            </div>
                            <div className="col-span-3">
                                <Label>Email</Label>
                                <Input
                                    type="email"
                                    value={formData.email}
                                    onChange={(e) => handleChange("email", e.target.value)}
                                    placeholder="email@empresa.com.br"
                                />
                            </div>
                        </div>

                        <div className="border-t pt-4" style={{ borderColor: "#E5E0D8" }}>
                            <SectionTitle>Endereço</SectionTitle>
                            <div className="grid grid-cols-3 gap-4">
                                <div>
                                    <Label>CEP</Label>
                                    <Input
                                        value={formData.cep}
                                        onChange={(e) =>
                                            handleChange("cep", formatarCEP(e.target.value))
                                        }
                                        onBlur={buscarCep}
                                        maxLength={9}
                                        placeholder="00000-000"
                                    />
                                </div>
                                <div className="col-span-2">
                                    <Label>Logradouro</Label>
                                    <Input
                                        value={formData.endereco}
                                        onChange={(e) =>
                                            handleChange("endereco", e.target.value)
                                        }
                                        placeholder="Rua, Avenida..."
                                    />
                                </div>
                                <div>
                                    <Label>Número</Label>
                                    <Input
                                        value={formData.numero}
                                        onChange={(e) =>
                                            handleChange("numero", e.target.value)
                                        }
                                    />
                                </div>
                                <div>
                                    <Label>Complemento</Label>
                                    <Input
                                        value={formData.complemento}
                                        onChange={(e) =>
                                            handleChange("complemento", e.target.value)
                                        }
                                    />
                                </div>
                                <div>
                                    <Label>Bairro</Label>
                                    <Input
                                        value={formData.bairro}
                                        onChange={(e) =>
                                            handleChange("bairro", e.target.value)
                                        }
                                    />
                                </div>
                                <div className="col-span-2">
                                    <Label>Cidade</Label>
                                    <Input
                                        value={formData.cidade}
                                        onChange={(e) =>
                                            handleChange("cidade", e.target.value)
                                        }
                                    />
                                </div>
                                <div>
                                    <Label>Estado</Label>
                                    <Select
                                        value={formData.estado}
                                        onValueChange={(v) => handleChange("estado", v)}
                                    >
                                        <SelectTrigger>
                                            <SelectValue placeholder="UF" />
                                        </SelectTrigger>
                                        <SelectContent>
                                            {ESTADOS.map((uf) => (
                                                <SelectItem key={uf} value={uf}>
                                                    {uf}
                                                </SelectItem>
                                            ))}
                                        </SelectContent>
                                    </Select>
                                </div>
                            </div>
                        </div>
                    </TabsContent>

                    {/* ── Profissional ── */}
                    <TabsContent value="profissional" className="space-y-5 mt-4">
                        <SectionTitle>Cargo (Descrição da Função)</SectionTitle>
                        <div>
                            <Label>Descrição do Cargo</Label>
                            <p className="text-xs text-gray-500 mb-1">Descreva a função do colaborador (ex: Gerente de Loja, Vendedor, Auxiliar Administrativo)</p>
                            <Input
                                value={formData.descricao_cargo}
                                onChange={(e) => handleChange("descricao_cargo", e.target.value)}
                                placeholder="Ex: Vendedor, Montador..."
                            />
                        </div>

                        <div className="grid grid-cols-2 gap-4 mt-5">
                            <div>
                                <Label>Status</Label>
                                <Select
                                    value={formData.status}
                                    onValueChange={(v) => handleChange("status", v)}
                                >
                                    <SelectTrigger>
                                        <SelectValue />
                                    </SelectTrigger>
                                    <SelectContent>
                                        {STATUS_OPTIONS.map((s) => (
                                            <SelectItem key={s} value={s}>
                                                {s}
                                            </SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                            </div>

                            <div>
                                <Label>Tipo de Contrato</Label>
                                <Select
                                    value={formData.tipo_contrato}
                                    onValueChange={(v) => handleChange("tipo_contrato", v)}
                                >
                                    <SelectTrigger>
                                        <SelectValue />
                                    </SelectTrigger>
                                    <SelectContent>
                                        {CONTRATO_OPTIONS.map((c) => (
                                            <SelectItem key={c} value={c}>
                                                {c}
                                            </SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                            </div>

                            <div>
                                <Label>Data de Admissão</Label>
                                <Input
                                    type="date" lang="pt-BR"
                                    value={formData.data_admissao}
                                    onChange={(e) =>
                                        handleChange("data_admissao", e.target.value)
                                    }
                                />
                            </div>

                            <div>
                                <Label>Carga Horária (h/semana)</Label>
                                <Input
                                    type="number"
                                    value={formData.carga_horaria}
                                    onChange={(e) =>
                                        handleChange(
                                            "carga_horaria",
                                            Number(e.target.value)
                                        )
                                    }
                                />
                            </div>

                            {formData.status === "Desligado" && (
                                <>
                                    <div>
                                        <Label>Data de Demissão</Label>
                                        <Input
                                            type="date" lang="pt-BR"
                                            value={formData.data_demissao}
                                            onChange={(e) =>
                                                handleChange(
                                                    "data_demissao",
                                                    e.target.value
                                                )
                                            }
                                        />
                                    </div>
                                    <div>
                                        <Label>Motivo da Demissão</Label>
                                        <Input
                                            value={formData.motivo_demissao}
                                            onChange={(e) =>
                                                handleChange(
                                                    "motivo_demissao",
                                                    e.target.value
                                                )
                                            }
                                        />
                                    </div>
                                </>
                            )}
                        </div>

                        <div className="border-t pt-4" style={{ borderColor: "#E5E0D8" }}>
                            <SectionTitle>Adicionais Trabalhistas</SectionTitle>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <Label>Insalubridade</Label>
                                    <Select
                                        value={formData.insalubridade_grau || "nao_aplicavel"}
                                        onValueChange={(v) =>
                                            handleChange("insalubridade_grau", v === "nao_aplicavel" ? "" : v)
                                        }
                                    >
                                        <SelectTrigger>
                                            <SelectValue placeholder="Selecione o grau" />
                                        </SelectTrigger>
                                        <SelectContent>
                                            {INSALUBRIDADE_OPCOES.map((opt) => (
                                                <SelectItem key={opt.value} value={opt.value}>
                                                    {opt.label}
                                                </SelectItem>
                                            ))}
                                        </SelectContent>
                                    </Select>
                                </div>
                                {usaPinMontagem && (
                                    <div>
                                        <Label>PIN de Montagem</Label>
                                        <Input
                                            value={formData.pin_montagem}
                                            onChange={(e) =>
                                                handleChange("pin_montagem", e.target.value.replace(/\D/g, "").slice(0, 4))
                                            }
                                            placeholder="PIN numérico"
                                            maxLength={4}
                                        />
                                    </div>
                                )}
                                <div className="flex items-center gap-3 pt-2">
                                    <Checkbox
                                        id="adicional_noturno"
                                        checked={!!formData.adicional_noturno}
                                        onCheckedChange={(v) =>
                                            handleChange("adicional_noturno", v)
                                        }
                                    />
                                    <Label htmlFor="adicional_noturno" className="cursor-pointer">
                                        Adicional Noturno (+20%)
                                    </Label>
                                </div>
                                <div className="flex items-center gap-3 pt-2">
                                    <Checkbox
                                        id="periculosidade"
                                        checked={!!formData.periculosidade}
                                        onCheckedChange={(v) =>
                                            handleChange("periculosidade", v)
                                        }
                                    />
                                    <Label htmlFor="periculosidade" className="cursor-pointer">
                                        Periculosidade (+30%)
                                    </Label>
                                </div>
                            </div>
                        </div>

                        <div className="border-t pt-4" style={{ borderColor: "#E5E0D8" }}>
                            <SectionTitle>Observações</SectionTitle>
                            <Textarea
                                value={formData.observacoes}
                                onChange={(e) =>
                                    handleChange("observacoes", e.target.value)
                                }
                                className="min-h-[100px]"
                                placeholder="Observações internas sobre o colaborador..."
                            />
                        </div>
                    </TabsContent>

                    {/* ── Remuneração ── */}
                    <TabsContent value="remuneracao" className="space-y-5 mt-4">
                        <SectionTitle>Salário e Pagamento</SectionTitle>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <Label>Salário Base (R$)</Label>
                                <Input
                                    type="number"
                                    value={formData.salario_base}
                                    onChange={(e) =>
                                        handleChange("salario_base", Number(e.target.value))
                                    }
                                    placeholder="0,00"
                                />
                            </div>
                            <div>
                                <Label>Nº de Dependentes</Label>
                                <Input
                                    type="number"
                                    min="0"
                                    max="20"
                                    value={formData.numero_dependentes}
                                    onChange={(e) =>
                                        handleChange(
                                            "numero_dependentes",
                                            Number(e.target.value) || 0
                                        )
                                    }
                                />
                            </div>
                            <div>
                                <Label>Tipo de Pagamento</Label>
                                <Select
                                    value={formData.tipo_pagamento}
                                    onValueChange={(v) =>
                                        handleChange("tipo_pagamento", v)
                                    }
                                >
                                    <SelectTrigger>
                                        <SelectValue />
                                    </SelectTrigger>
                                    <SelectContent>
                                        {TIPO_PAGAMENTO.map((t) => (
                                            <SelectItem key={t} value={t}>
                                                {t}
                                            </SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                            </div>
                            <div>
                                <Label>Dia do Pagamento</Label>
                                <div className="flex gap-2">
                                    <Select
                                        value={formData.tipo_dia_pagamento}
                                        onValueChange={(v) => handleChange("tipo_dia_pagamento", v)}
                                    >
                                        <SelectTrigger className="w-1/2">
                                            <SelectValue />
                                        </SelectTrigger>
                                        <SelectContent>
                                            <SelectItem value="util">Dia Útil</SelectItem>
                                            <SelectItem value="fixo">Dia Fixo</SelectItem>
                                        </SelectContent>
                                    </Select>
                                    <Select
                                        value={String(formData.dia_pagamento)}
                                        onValueChange={(v) =>
                                            handleChange("dia_pagamento", Number(v))
                                        }
                                    >
                                        <SelectTrigger className="w-1/2">
                                            <SelectValue placeholder="Dia" />
                                        </SelectTrigger>
                                        <SelectContent>
                                            {DIAS_PAGAMENTO.map((d) => (
                                                <SelectItem key={d} value={String(d)}>
                                                    {formData.tipo_dia_pagamento === "util" ? `${d}º Dia Útil` : `Dia ${d}`}
                                                </SelectItem>
                                            ))}
                                        </SelectContent>
                                    </Select>
                                </div>
                            </div>
                            <div>
                                <Label>Recebe Vale</Label>
                                <Select
                                    value={formData.recebe_vale ? "sim" : "nao"}
                                    onValueChange={(v) =>
                                        handleChange("recebe_vale", v === "sim")
                                    }
                                >
                                    <SelectTrigger>
                                        <SelectValue />
                                    </SelectTrigger>
                                    <SelectContent>
                                        {RECEBE_VALE_OPCOES.map((opt) => (
                                            <SelectItem key={opt.value} value={opt.value}>
                                                {opt.label}
                                            </SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                            </div>
                            {formData.recebe_vale && (
                                <div>
                                    <Label>Dia do Vale</Label>
                                    <div className="flex gap-2">
                                        <Select
                                            value={formData.tipo_dia_vale}
                                            onValueChange={(v) => handleChange("tipo_dia_vale", v)}
                                        >
                                            <SelectTrigger className="w-1/2">
                                                <SelectValue />
                                            </SelectTrigger>
                                            <SelectContent>
                                                <SelectItem value="util">Dia Útil</SelectItem>
                                                <SelectItem value="fixo">Dia Fixo</SelectItem>
                                            </SelectContent>
                                        </Select>
                                        <Select
                                            value={String(formData.dia_vale || 20)}
                                            onValueChange={(v) =>
                                                handleChange("dia_vale", Number(v))
                                            }
                                        >
                                            <SelectTrigger className="w-1/2">
                                                <SelectValue placeholder="Dia" />
                                            </SelectTrigger>
                                            <SelectContent>
                                                {DIAS_PAGAMENTO.map((d) => (
                                                    <SelectItem key={d} value={String(d)}>
                                                        {formData.tipo_dia_vale === "util" ? `${d}º Dia Útil` : `Dia ${d}`}
                                                    </SelectItem>
                                                ))}
                                            </SelectContent>
                                        </Select>
                                    </div>
                                </div>
                            )}
                        </div>

                        {formData.recebe_vale && (
                            <div className="border-t pt-4" style={{ borderColor: "#E5E0D8" }}>
                                <SectionTitle>Distribuição do Salário</SectionTitle>
                                <p className="text-xs text-gray-500 mb-3">
                                    Defina quanto será pago em cada data. Os valores devem somar o salário líquido.
                                </p>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <Label>Valor no Dia {formData.dia_pagamento || 5} (R$)</Label>
                                        <Input
                                            type="number"
                                            value={formData.valor_dia_pagamento}
                                            onChange={(e) =>
                                                handleChange("valor_dia_pagamento", Number(e.target.value))
                                            }
                                            placeholder="0,00"
                                        />
                                    </div>
                                    <div>
                                        <Label>Valor no Dia {formData.dia_vale || 20} — Vale (R$)</Label>
                                        <Input
                                            type="number"
                                            value={formData.valor_dia_vale}
                                            onChange={(e) =>
                                                handleChange("valor_dia_vale", Number(e.target.value))
                                            }
                                            placeholder="0,00"
                                        />
                                    </div>
                                </div>
                                {(() => {
                                    const somaDistribuicao =
                                        (Number(formData.valor_dia_pagamento) || 0) +
                                        (Number(formData.valor_dia_vale) || 0);
                                    const liquido = totals.salario_liquido || 0;
                                    const temValores = somaDistribuicao > 0;
                                    const diferenca = Math.abs(somaDistribuicao - liquido);
                                    if (temValores && diferenca > 0.01) {
                                        return (
                                            <div className="mt-3 p-3 rounded-lg bg-amber-50 border border-amber-200 flex items-start gap-2">
                                                <AlertTriangle className="w-4 h-4 text-amber-600 mt-0.5 flex-shrink-0" />
                                                <div className="text-sm text-amber-800">
                                                    <p className="font-medium">Atenção: a soma dos valores ({formatCurrency(somaDistribuicao)}) é diferente do salário líquido estimado ({formatCurrency(liquido)}).</p>
                                                    <p className="text-xs text-amber-600 mt-1">Diferença: {formatCurrency(diferenca)}</p>
                                                </div>
                                            </div>
                                        );
                                    }
                                    return null;
                                })()}
                            </div>
                        )}

                        <div className="border-t pt-4" style={{ borderColor: "#E5E0D8" }}>
                            <SectionTitle>Benefícios</SectionTitle>
                            <div className="grid grid-cols-3 gap-4">
                                <div>
                                    <Label>Vale Transporte (R$)</Label>
                                    <Input
                                        type="number"
                                        value={formData.vale_transporte}
                                        onChange={(e) =>
                                            handleChange(
                                                "vale_transporte",
                                                Number(e.target.value)
                                            )
                                        }
                                        placeholder="0,00"
                                    />
                                </div>
                                <div>
                                    <Label>Vale Alimentação (R$)</Label>
                                    <Input
                                        type="number"
                                        value={formData.vale_alimentacao}
                                        onChange={(e) =>
                                            handleChange(
                                                "vale_alimentacao",
                                                Number(e.target.value)
                                            )
                                        }
                                        placeholder="0,00"
                                    />
                                </div>
                                <div>
                                    <Label>Vale Refeição (R$)</Label>
                                    <Input
                                        type="number"
                                        value={formData.vale_refeicao}
                                        onChange={(e) =>
                                            handleChange(
                                                "vale_refeicao",
                                                Number(e.target.value)
                                            )
                                        }
                                        placeholder="0,00"
                                    />
                                </div>
                                <div>
                                    <Label>Plano de Saúde (R$)</Label>
                                    <Input
                                        type="number"
                                        value={formData.plano_saude}
                                        onChange={(e) =>
                                            handleChange(
                                                "plano_saude",
                                                Number(e.target.value)
                                            )
                                        }
                                        placeholder="0,00"
                                    />
                                </div>
                                <div>
                                    <Label>Plano Odontológico (R$)</Label>
                                    <Input
                                        type="number"
                                        value={formData.plano_odontologico}
                                        onChange={(e) =>
                                            handleChange(
                                                "plano_odontologico",
                                                Number(e.target.value)
                                            )
                                        }
                                        placeholder="0,00"
                                    />
                                </div>
                                <div>
                                    <Label>Bônus Mensal (R$)</Label>
                                    <Input
                                        type="number"
                                        value={formData.bonus_mensal}
                                        onChange={(e) =>
                                            handleChange(
                                                "bonus_mensal",
                                                Number(e.target.value)
                                            )
                                        }
                                        placeholder="0,00"
                                    />
                                </div>
                                <div>
                                    <Label>Outros Benefícios (R$)</Label>
                                    <Input
                                        type="number"
                                        value={formData.outros_beneficios}
                                        onChange={(e) =>
                                            handleChange(
                                                "outros_beneficios",
                                                Number(e.target.value)
                                            )
                                        }
                                        placeholder="0,00"
                                    />
                                </div>
                                <div className="col-span-2">
                                    <Label>Descrição dos Outros Benefícios</Label>
                                    <Input
                                        value={formData.descricao_outros_beneficios}
                                        onChange={(e) =>
                                            handleChange(
                                                "descricao_outros_beneficios",
                                                e.target.value
                                            )
                                        }
                                        placeholder="Ex: Combustível, estacionamento..."
                                    />
                                </div>
                            </div>
                        </div>

                        <div className="border-t pt-4" style={{ borderColor: "#E5E0D8" }}>
                            <SectionTitle>Descontos (Além dos Tributários)</SectionTitle>
                            <p className="text-xs text-gray-500 mb-3">
                                Valores que serão descontados do salário líquido mensalmente. Deixe em branco no Vale Transporte para usar o cálculo padrão de 6%.
                            </p>
                            <div className="grid grid-cols-3 gap-4">
                                <div>
                                    <Label>Vale Transporte (R$)</Label>
                                    <Input
                                        type="number"
                                        value={formData.desconto_vale_transporte}
                                        onChange={(e) =>
                                            handleChange(
                                                "desconto_vale_transporte",
                                                e.target.value
                                            )
                                        }
                                        placeholder="Cálculo auto (6%)"
                                    />
                                </div>
                                <div>
                                    <Label>Plano de Saúde (R$)</Label>
                                    <Input
                                        type="number"
                                        value={formData.desconto_plano_saude}
                                        onChange={(e) =>
                                            handleChange(
                                                "desconto_plano_saude",
                                                e.target.value
                                            )
                                        }
                                        placeholder="0,00"
                                    />
                                </div>
                                <div>
                                    <Label>Adiantamento (R$)</Label>
                                    <Input
                                        type="number"
                                        value={formData.desconto_adiantamento}
                                        onChange={(e) =>
                                            handleChange(
                                                "desconto_adiantamento",
                                                e.target.value
                                            )
                                        }
                                        placeholder="0,00"
                                    />
                                </div>
                                <div className="col-span-3 border p-3 rounded-lg bg-gray-50 mt-2">
                                    <div className="flex justify-between items-center mb-3">
                                        <Label className="text-sm">Outros Descontos Adicionais</Label>
                                        <Button
                                            type="button"
                                            variant="outline"
                                            size="sm"
                                            onClick={() => setListaDescontos([...listaDescontos, { descricao: "", valor: 0 }])}
                                        >
                                            + Adicionar
                                        </Button>
                                    </div>
                                    
                                    {listaDescontos.length === 0 ? (
                                        <p className="text-xs text-gray-500 italic">Nenhum desconto adicional cadastrado.</p>
                                    ) : (
                                        <div className="space-y-3">
                                            {listaDescontos.map((desc, idx) => (
                                                <div key={idx} className="flex gap-2 items-start">
                                                    <div className="flex-1">
                                                        <Input
                                                            value={desc.descricao}
                                                            onChange={(e) => {
                                                                const newLista = [...listaDescontos];
                                                                newLista[idx].descricao = e.target.value;
                                                                setListaDescontos(newLista);
                                                            }}
                                                            placeholder="Descrição (Ex: Farmácia, Quebra de Caixa)"
                                                            className="text-xs h-8"
                                                        />
                                                    </div>
                                                    <div className="w-32">
                                                        <Input
                                                            type="number"
                                                            value={desc.valor || ""}
                                                            onChange={(e) => {
                                                                const newLista = [...listaDescontos];
                                                                newLista[idx].valor = Number(e.target.value);
                                                                setListaDescontos(newLista);
                                                            }}
                                                            placeholder="R$ 0,00"
                                                            className="text-xs h-8"
                                                        />
                                                    </div>
                                                    <Button
                                                        type="button"
                                                        variant="ghost"
                                                        size="sm"
                                                        className="text-red-500 h-8 w-8 p-0"
                                                        onClick={() => {
                                                            const newLista = listaDescontos.filter((_, i) => i !== idx);
                                                            setListaDescontos(newLista);
                                                        }}
                                                    >
                                                        <X className="w-4 h-4" />
                                                    </Button>
                                                </div>
                                            ))}
                                            <div className="text-right border-t pt-2 mt-2">
                                                <span className="text-xs text-gray-600 mr-2">Total Adicional:</span>
                                                <span className="font-bold text-red-600">
                                                    - R$ {listaDescontos.reduce((acc, curr) => acc + (Number(curr.valor) || 0), 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                                                </span>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>

                        <div className="border-t pt-4" style={{ borderColor: "#E5E0D8" }}>
                            <SectionTitle>Tributário</SectionTitle>
                            <div className="grid grid-cols-3 gap-4 mb-4">
                                <div>
                                    <Label>Pensão Alimenticia (R$)</Label>
                                    <Input
                                        type="number"
                                        value={formData.pensao_alimenticia}
                                        onChange={(e) =>
                                            handleChange(
                                                "pensao_alimenticia",
                                                Number(e.target.value)
                                            )
                                        }
                                        placeholder="0,00"
                                    />
                                </div>
                            </div>

                            <p className="text-xs text-gray-500 mb-3 mt-2">Configurações Manuais (INSS, FGTS, IRRF)</p>
                            <div className="grid grid-cols-3 gap-4 mb-4 bg-gray-50 p-3 rounded-lg border border-gray-200">
                                {/* INSS */}
                                <div className="space-y-2">
                                    <Label className="text-xs">Cálculo INSS</Label>
                                    <Select value={formData.tipo_inss} onValueChange={(v) => handleChange("tipo_inss", v)}>
                                        <SelectTrigger className="h-8 text-xs">
                                            <SelectValue />
                                        </SelectTrigger>
                                        <SelectContent>
                                            <SelectItem value="automatico">Automático (Tabela)</SelectItem>
                                            <SelectItem value="valor">Valor Fixo (R$)</SelectItem>
                                            <SelectItem value="porcentagem">Porcentagem (%)</SelectItem>
                                            <SelectItem value="isento">Isento / Não Tem</SelectItem>
                                        </SelectContent>
                                    </Select>
                                    {(formData.tipo_inss === "valor" || formData.tipo_inss === "porcentagem") && (
                                        <Input
                                            type="number"
                                            className="h-8 text-xs mt-2"
                                            placeholder={formData.tipo_inss === "valor" ? "0,00" : "0"}
                                            value={formData.valor_inss}
                                            onChange={(e) => handleChange("valor_inss", e.target.value)}
                                        />
                                    )}
                                </div>
                                {/* FGTS */}
                                <div className="space-y-2">
                                    <Label className="text-xs">Cálculo FGTS</Label>
                                    <Select value={formData.tipo_fgts} onValueChange={(v) => handleChange("tipo_fgts", v)}>
                                        <SelectTrigger className="h-8 text-xs">
                                            <SelectValue />
                                        </SelectTrigger>
                                        <SelectContent>
                                            <SelectItem value="automatico">Automático (8%)</SelectItem>
                                            <SelectItem value="valor">Valor Fixo (R$)</SelectItem>
                                            <SelectItem value="porcentagem">Porcentagem (%)</SelectItem>
                                            <SelectItem value="isento">Isento / Não Tem</SelectItem>
                                        </SelectContent>
                                    </Select>
                                    {(formData.tipo_fgts === "valor" || formData.tipo_fgts === "porcentagem") && (
                                        <Input
                                            type="number"
                                            className="h-8 text-xs mt-2"
                                            placeholder={formData.tipo_fgts === "valor" ? "0,00" : "0"}
                                            value={formData.valor_fgts}
                                            onChange={(e) => handleChange("valor_fgts", e.target.value)}
                                        />
                                    )}
                                </div>
                                {/* IRRF */}
                                <div className="space-y-2">
                                    <Label className="text-xs">Cálculo IRRF</Label>
                                    <Select value={formData.tipo_irrf} onValueChange={(v) => handleChange("tipo_irrf", v)}>
                                        <SelectTrigger className="h-8 text-xs">
                                            <SelectValue />
                                        </SelectTrigger>
                                        <SelectContent>
                                            <SelectItem value="automatico">Automático (Tabela)</SelectItem>
                                            <SelectItem value="valor">Valor Fixo (R$)</SelectItem>
                                            <SelectItem value="porcentagem">Porcentagem (%)</SelectItem>
                                            <SelectItem value="isento">Isento / Não Tem</SelectItem>
                                        </SelectContent>
                                    </Select>
                                    {(formData.tipo_irrf === "valor" || formData.tipo_irrf === "porcentagem") && (
                                        <Input
                                            type="number"
                                            className="h-8 text-xs mt-2"
                                            placeholder={formData.tipo_irrf === "valor" ? "0,00" : "0"}
                                            value={formData.valor_irrf}
                                            onChange={(e) => handleChange("valor_irrf", e.target.value)}
                                        />
                                    )}
                                </div>
                            </div>

                            <div className="grid grid-cols-3 gap-3 text-sm">
                                <div className="bg-red-50 rounded-lg p-3">
                                    <p className="text-xs text-red-600">INSS (Desconto)</p>
                                    <p className="font-bold text-red-700 mt-0.5">
                                        {formatCurrency(totals.inss)}
                                    </p>
                                    <p className="text-xs text-gray-500 mt-1">{totals.inss_faixa}</p>
                                </div>
                                <div className="bg-yellow-50 rounded-lg p-3">
                                    <p className="text-xs text-yellow-700">FGTS (Empresa)</p>
                                    <p className="font-bold text-yellow-800 mt-0.5">
                                        {formatCurrency(totals.fgts)}
                                    </p>
                                </div>
                                <div className="bg-purple-50 rounded-lg p-3">
                                    <p className="text-xs text-purple-600">IRRF (Desconto)</p>
                                    <p className="font-bold text-purple-700 mt-0.5">
                                        {formatCurrency(totals.irrf)}
                                    </p>
                                    <p className="text-xs text-gray-500 mt-1">{totals.irrf_faixa}</p>
                                </div>
                            </div>
                        </div>

                        <div className="border-t pt-4" style={{ borderColor: "#E5E0D8" }}>
                            <SectionTitle>Dados Bancários</SectionTitle>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <Label>Banco</Label>
                                    <Input
                                        value={formData.banco}
                                        onChange={(e) =>
                                            handleChange("banco", e.target.value)
                                        }
                                        placeholder="Nome do banco"
                                    />
                                </div>
                                <div>
                                    <Label>Chave PIX</Label>
                                    <Input
                                        value={formData.pix}
                                        onChange={(e) =>
                                            handleChange("pix", e.target.value)
                                        }
                                        placeholder="CPF, email, telefone ou chave aleatória"
                                    />
                                </div>
                                <div>
                                    <Label>Agência</Label>
                                    <Input
                                        value={formData.agencia}
                                        onChange={(e) =>
                                            handleChange("agencia", e.target.value)
                                        }
                                        placeholder="0000"
                                    />
                                </div>
                                <div>
                                    <Label>Conta</Label>
                                    <Input
                                        value={formData.conta}
                                        onChange={(e) =>
                                            handleChange("conta", e.target.value)
                                        }
                                        placeholder="00000-0"
                                    />
                                </div>
                            </div>
                        </div>

                        {/* Salary summary */}
                        <Card className="border-2" style={{ borderColor: "#07593f" }}>
                            <CardContent className="pt-4 pb-4">
                                <h3
                                    className="font-semibold mb-3 text-sm"
                                    style={{ color: "#07593f" }}
                                >
                                    Resumo Mensal Estimado
                                </h3>
                                <div className="grid grid-cols-3 gap-3 text-sm">
                                    <div className="bg-gray-50 rounded-lg p-3">
                                        <p className="text-xs text-gray-500">Salário Bruto</p>
                                        <p className="font-bold mt-0.5">
                                            {formatCurrency(totals.salario_base)}
                                        </p>
                                    </div>
                                    <div
                                        className="rounded-lg p-3"
                                        style={{ backgroundColor: "#D1FAE5" }}
                                    >
                                        <p
                                            className="text-xs"
                                            style={{ color: "#065F46" }}
                                        >
                                            Líquido Estimado
                                        </p>
                                        <p
                                            className="font-bold mt-0.5"
                                            style={{ color: "#07593f" }}
                                        >
                                            {formatCurrency(totals.salario_liquido)}
                                        </p>
                                    </div>
                                    <div className="bg-orange-50 rounded-lg p-3">
                                        <p className="text-xs text-orange-600">
                                            Custo Total Empresa
                                        </p>
                                        <p className="font-bold text-orange-700 mt-0.5">
                                            {formatCurrency(totals.custo_total_empresa)}
                                        </p>
                                    </div>
                                </div>
                            </CardContent>
                        </Card>
                    </TabsContent>

                    {/* ── Sistema ── */}
                    <TabsContent value="sistema" className="space-y-4 mt-4">
                        {!formData.user_id ? (
                            <div className="space-y-5">
                                <Alert className="bg-blue-50 border-blue-200">
                                    <KeyRound className="w-4 h-4 text-blue-600" />
                                    <AlertDescription className="text-blue-800">
                                        Este colaborador ainda não possui vínculo com uma
                                        conta do sistema. Criação de credenciais e reset de
                                        senha são feitos na área Admin de Usuários.
                                    </AlertDescription>
                                </Alert>

                                <Card>
                                    <CardContent className="pt-5">
                                        <div className="space-y-4">
                                            <h3 className="font-semibold flex items-center gap-2 text-sm">
                                                <Info className="w-4 h-4 text-gray-500" />
                                                Vínculo de Usuário
                                            </h3>
                                            <p className="text-sm text-gray-500">
                                                O RH realiza somente o cadastro do funcionário.
                                                O vínculo com conta de acesso e a geração de
                                                credenciais são realizados pelo Administrador na
                                                área de Gestão de Acessos.
                                            </p>

                                            <Button
                                                variant="outline"
                                                className="gap-2"
                                                onClick={() =>
                                                    navigate("/admin/GerenciamentoUsuarios")
                                                }
                                            >
                                                <ExternalLink className="w-4 h-4" />
                                                Abrir Gestão de Acessos (Admin)
                                            </Button>
                                        </div>
                                    </CardContent>
                                </Card>
                            </div>
                        ) : (
                            <div className="space-y-5">
                                <Alert className="bg-green-50 border-green-200">
                                    <UserCheck className="w-4 h-4 text-green-600" />
                                    <AlertDescription className="text-green-800">
                                        Este colaborador possui vínculo com usuário do sistema.
                                    </AlertDescription>
                                </Alert>

                                <Card>
                                    <CardContent className="pt-5">
                                        <div className="space-y-4">
                                            <h3 className="font-semibold text-sm">
                                                Resumo de Vínculo
                                            </h3>
                                            <div className="grid grid-cols-2 gap-3">
                                                <div className="bg-gray-50 p-3 rounded-lg">
                                                    <span className="text-xs text-gray-500">
                                                        Usuário
                                                    </span>
                                                    <div className="font-medium text-sm mt-0.5">
                                                        {linkedUser?.full_name || "..."}
                                                    </div>
                                                    <div className="text-xs text-gray-400">
                                                        {linkedUser?.email}
                                                    </div>
                                                </div>
                                                <div className="bg-gray-50 p-3 rounded-lg">
                                                    <span className="text-xs text-gray-500">
                                                        Matrícula
                                                    </span>
                                                    <div className="text-xl font-mono font-bold tracking-wider mt-0.5">
                                                        {linkedUser?.matricula || "---"}
                                                    </div>
                                                </div>
                                                <div className="bg-gray-50 p-3 rounded-lg">
                                                    <span className="text-xs text-gray-500">
                                                        Status
                                                    </span>
                                                    <div className="mt-0.5">
                                                        {linkedUser?.ativo === false ? (
                                                            <span className="text-red-600 flex items-center gap-1 font-semibold text-sm">
                                                                <UserX className="w-3 h-3" />
                                                                Desativado
                                                            </span>
                                                        ) : (
                                                            <span className="text-green-600 flex items-center gap-1 font-semibold text-sm">
                                                                <CheckCircle2 className="w-3 h-3" />
                                                                Ativo
                                                            </span>
                                                        )}
                                                    </div>
                                                </div>
                                                <div className="bg-gray-50 p-3 rounded-lg">
                                                    <span className="text-xs text-gray-500">
                                                        Último Login
                                                    </span>
                                                    <div className="text-sm mt-0.5">
                                                        {linkedUser?.ultimo_login
                                                            ? new Date(
                                                                  linkedUser.ultimo_login
                                                              ).toLocaleDateString("pt-BR")
                                                            : "Nunca"}
                                                    </div>
                                                </div>
                                            </div>

                                            <Button
                                                variant="outline"
                                                className="gap-2"
                                                onClick={() =>
                                                    navigate("/admin/GerenciamentoUsuarios")
                                                }
                                            >
                                                <ExternalLink className="w-4 h-4" />
                                                Gerenciar Credenciais no Admin
                                            </Button>

                                            {canManageAccess && (
                                                <div className="pt-3 border-t">
                                                    <Button
                                                        variant="ghost"
                                                        className="w-full text-red-500 hover:text-red-700 hover:bg-red-50"
                                                        onClick={() =>
                                                            handleChange("user_id", "")
                                                        }
                                                    >
                                                        Desvincular Usuário (apenas remove link)
                                                    </Button>
                                                </div>
                                            )}
                                        </div>
                                    </CardContent>
                                </Card>
                            </div>
                        )}
                    </TabsContent>
                </Tabs>

                <div className="flex justify-end gap-3 mt-4 pt-4 border-t">
                    <Button variant="outline" onClick={onClose}>
                        Cancelar
                    </Button>
                    <Button
                        onClick={handleSubmit}
                        disabled={saving}
                        style={{
                            background:
                                "linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)",
                        }}
                    >
                        {saving ? (
                            <>
                                <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                                Salvando...
                            </>
                        ) : (
                            <>
                                <Save className="w-4 h-4 mr-2" />
                                {isEditing ? "Salvar Alterações" : "Cadastrar Colaborador"}
                            </>
                        )}
                    </Button>
                </div>
            </DialogContent>
        </Dialog>
    );
}

import React, { useMemo, useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useNavigate } from "react-router-dom";
import { base44 } from "@/api/base44Client";
import { useAuth } from "@/hooks/useAuth";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Alert, AlertDescription } from "@/components/ui/alert";
import {
    Users,
    Search,
    Plus,
    Edit,
    Trash2,
    Eye,
    UserCheck,
    UserX,
    Calendar,
    Download,
    MoreVertical,
    FileText,
    Shield,
    ExternalLink,
    KeyRound,
    Building,
} from "lucide-react";
import { formatarNome } from "@/utils/formatters";
import ColaboradorModal from "./ColaboradorModal";
import ColaboradorDetalhesModal from "./ColaboradorDetalhesModal";
import ContratacaoResumoModal from "./ContratacaoResumoModal";

const STATUS_OPTIONS = [
    { value: "todos", label: "Todos" },
    { value: "Ativo", label: "Ativo" },
    { value: "Férias", label: "Férias" },
    { value: "Licença", label: "Licença" },
    { value: "Afastado", label: "Afastado" },
    { value: "Desligado", label: "Desligado" },
];

const CONTRATO_OPTIONS = [
    { value: "todos", label: "Todos" },
    { value: "CLT", label: "CLT" },
    { value: "PJ", label: "PJ" },
    { value: "Estagiário", label: "Estagiário" },
    { value: "Temporário", label: "Temporário" },
];

const STAT_CARDS = [
    {
        key: "Ativo",
        label: "Ativos",
        icon: UserCheck,
        bg: "#D1FAE5",
        fg: "#065F46",
        activeFg: "#fff",
        activeBg: "#065F46",
        border: "#6EE7B7",
    },
    {
        key: "Férias",
        label: "Em Férias",
        icon: Calendar,
        bg: "#DBEAFE",
        fg: "#1E40AF",
        activeFg: "#fff",
        activeBg: "#1E40AF",
        border: "#93C5FD",
    },
    {
        key: "Licença",
        label: "Em Licença",
        icon: UserX,
        bg: "#FEF3C7",
        fg: "#92400E",
        activeFg: "#fff",
        activeBg: "#92400E",
        border: "#FCD34D",
    },
    {
        key: "total",
        label: "Total",
        icon: Users,
        bg: "#F0FDF4",
        fg: "#07593f",
        activeFg: "#fff",
        activeBg: "#07593f",
        border: "#86EFAC",
    },
];

function getStatusStyle(status) {
    const map = {
        Ativo: { bg: "#D1FAE5", color: "#065F46" },
        Férias: { bg: "#DBEAFE", color: "#1E40AF" },
        Licença: { bg: "#FEF3C7", color: "#92400E" },
        Afastado: { bg: "#FED7AA", color: "#C2410C" },
        Desligado: { bg: "#FEE2E2", color: "#991B1B" },
    };
    return map[status] || { bg: "#E5E7EB", color: "#374151" };
}

function getAvatarGradient(status) {
    const map = {
        Ativo: "linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)",
        Férias: "linear-gradient(135deg, #1E40AF 0%, #2563EB 100%)",
        Licença: "linear-gradient(135deg, #92400E 0%, #B45309 100%)",
        Afastado: "linear-gradient(135deg, #C2410C 0%, #EA580C 100%)",
        Desligado: "linear-gradient(135deg, #6B7280 0%, #9CA3AF 100%)",
    };
    return map[status] || "linear-gradient(135deg, #6B7280 0%, #9CA3AF 100%)";
}

export default function ColaboradoresTab() {
    const queryClient = useQueryClient();
    const navigate = useNavigate();
    const { can } = useAuth();
    const canManageRH = can("manage_rh");
    const canManageAccess = can("manage_user_access");

    const [busca, setBusca] = useState("");
    const [filtroStatus, setFiltroStatus] = useState("todos");
    const [filtroContrato, setFiltroContrato] = useState("todos");
    const [modalAberto, setModalAberto] = useState(false);
    const [modalDetalhes, setModalDetalhes] = useState(false);
    const [modalResumo, setModalResumo] = useState(false);
    const [colaboradorSelecionado, setColaboradorSelecionado] = useState(null);
    const [novoColaborador, setNovoColaborador] = useState(null);
    const [confirmDelete, setConfirmDelete] = useState(null);
    const [initialTab, setInitialTab] = useState("pessoal");

    const { data: colaboradores = [], isLoading } = useQuery({
        queryKey: ["colaboradores"],
        queryFn: () => base44.entities.Colaborador.list("-created_at"),
    });

    const { data: usuarios = [] } = useQuery({
        queryKey: ["usuarios"],
        queryFn: () => base44.entities.User.list(),
    });

    const deleteMutation = useMutation({
        mutationFn: (id) => base44.entities.Colaborador.delete(id),
        onSuccess: () => {
            queryClient.invalidateQueries(["colaboradores"]);
            setConfirmDelete(null);
        },
    });

    const usuariosById = useMemo(
        () => new Map(usuarios.map((u) => [u.id, u])),
        [usuarios]
    );

    const colaboradoresEnriquecidos = useMemo(
        () =>
            colaboradores.map((c) => {
                const usuarioVinculado = c.user_id ? usuariosById.get(c.user_id) : null;
                return { ...c, matricula: usuarioVinculado?.matricula || null };
            }),
        [colaboradores, usuariosById]
    );

    const contasAguardandoVinculo = useMemo(
        () =>
            usuarios.filter((u) => {
                const isEmployee = u.cargo && u.matricula?.startsWith("MP-");
                const isNotLinked = !colaboradores.some((c) => c.user_id === u.id);
                return isEmployee && isNotLinked;
            }).length,
        [usuarios, colaboradores]
    );

    const colaboradoresFiltrados = useMemo(
        () =>
            colaboradoresEnriquecidos.filter((c) => {
                const termo = busca.toLowerCase();
                const matchBusca =
                    !busca ||
                    c.nome_completo?.toLowerCase().includes(termo) ||
                    c.cpf?.includes(busca) ||
                    c.email?.toLowerCase().includes(termo) ||
                    c.matricula?.toLowerCase().includes(termo);
                const matchStatus = filtroStatus === "todos" || c.status === filtroStatus;
                const matchContrato =
                    filtroContrato === "todos" || c.tipo_contrato === filtroContrato;
                return matchBusca && matchStatus && matchContrato;
            }),
        [colaboradoresEnriquecidos, busca, filtroStatus, filtroContrato]
    );

    const counts = useMemo(
        () => ({
            Ativo: colaboradoresEnriquecidos.filter((c) => c.status === "Ativo").length,
            Férias: colaboradoresEnriquecidos.filter((c) => c.status === "Férias").length,
            Licença: colaboradoresEnriquecidos.filter((c) => c.status === "Licença").length,
            total: colaboradoresEnriquecidos.length,
        }),
        [colaboradoresEnriquecidos]
    );

    const abrirModal = (colaborador = null, tab = "pessoal") => {
        setColaboradorSelecionado(colaborador);
        setInitialTab(tab);
        setModalAberto(true);
    };

    const abrirDetalhes = (colaborador) => {
        setColaboradorSelecionado(colaborador);
        setModalDetalhes(true);
    };

    const handleNovoColaboradorSuccess = (colaborador) => {
        setModalAberto(false);
        setColaboradorSelecionado(null);
        setNovoColaborador(colaborador);
        setModalResumo(true);
    };

    const handleStatClick = (key) => {
        if (key === "total") {
            setFiltroStatus("todos");
        } else {
            setFiltroStatus((prev) => (prev === key ? "todos" : key));
        }
    };

    const exportarCSV = () => {
        let csv =
            "Nome,Matrícula,CPF,Cargo,Status,Tipo Contrato,Salário Base,Data Admissão,Telefone,Email\n";
        colaboradoresFiltrados.forEach((c) => {
            csv += `"${c.nome_completo || ""}","${c.matricula || ""}","${c.cpf || ""}","${c.descricao_cargo || ""}","${c.status || ""}","${c.tipo_contrato || ""}","${c.salario_base || ""}","${c.data_admissao || ""}","${c.telefone || ""}","${c.email || ""}"\n`;
        });
        const blob = new Blob([csv], { type: "text/csv" });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = `colaboradores_${new Date().toISOString().slice(0, 10)}.csv`;
        a.click();
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center py-16">
                <div
                    className="animate-spin rounded-full h-8 w-8 border-b-2"
                    style={{ borderColor: "#07593f" }}
                />
            </div>
        );
    }

    return (
        <div className="space-y-4">
            {/* Stat cards — also act as filter shortcuts */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                {STAT_CARDS.map(({ key, label, icon: Icon, bg, fg, activeBg, border }) => {
                    const count = counts[key] ?? 0;
                    const isActive = filtroStatus === key || (key === "total" && filtroStatus === "todos" && busca === "");
                    return (
                        <button
                            key={key}
                            onClick={() => handleStatClick(key)}
                            className="rounded-xl p-4 flex items-center justify-between transition-all hover:scale-[1.02] active:scale-[0.99] text-left focus:outline-none focus-visible:ring-2"
                            style={{
                                backgroundColor: isActive ? activeBg : bg,
                                border: `2px solid ${isActive ? activeBg : border}`,
                                color: isActive ? "#fff" : fg,
                            }}
                        >
                            <div>
                                <p className="text-xs font-medium opacity-80">{label}</p>
                                <p className="text-2xl font-bold mt-0.5">{count}</p>
                            </div>
                            <Icon className="w-8 h-8 opacity-30" />
                        </button>
                    );
                })}
            </div>

            {/* Unlinked accounts alert */}
            {contasAguardandoVinculo > 0 && (
                <Alert className="bg-blue-50 border-blue-200">
                    <KeyRound className="h-4 w-4 text-blue-600" />
                    <AlertDescription className="text-blue-800 flex items-center justify-between gap-4 w-full">
                        <span>
                            <strong>{contasAguardandoVinculo}</strong> conta
                            {contasAguardandoVinculo > 1 ? "s" : ""} de acesso sem vínculo com
                            colaborador de RH.
                        </span>
                        <Button
                            variant="outline"
                            size="sm"
                            className="border-blue-300 text-blue-800 shrink-0"
                            disabled={!canManageAccess}
                            onClick={() => navigate("/admin/GerenciamentoUsuarios")}
                        >
                            <ExternalLink className="w-4 h-4 mr-1.5" />
                            {canManageAccess ? "Gerenciar" : "Somente Admin"}
                        </Button>
                    </AlertDescription>
                </Alert>
            )}

            {/* Filter + action bar */}
            <div className="flex flex-col sm:flex-row gap-2">
                <div className="flex-1 relative">
                    <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                    <Input
                        placeholder="Buscar por nome, matrícula, CPF ou email..."
                        value={busca}
                        onChange={(e) => setBusca(e.target.value)}
                        className="pl-9"
                    />
                </div>
                <Select value={filtroStatus} onValueChange={setFiltroStatus}>
                    <SelectTrigger className="w-full sm:w-36">
                        <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                        {STATUS_OPTIONS.map((opt) => (
                            <SelectItem key={opt.value} value={opt.value}>
                                {opt.label}
                            </SelectItem>
                        ))}
                    </SelectContent>
                </Select>
                <Select value={filtroContrato} onValueChange={setFiltroContrato}>
                    <SelectTrigger className="w-full sm:w-36">
                        <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                        {CONTRATO_OPTIONS.map((opt) => (
                            <SelectItem key={opt.value} value={opt.value}>
                                {opt.label}
                            </SelectItem>
                        ))}
                    </SelectContent>
                </Select>
                <div className="flex gap-2">
                    <Button
                        onClick={exportarCSV}
                        variant="outline"
                        size="icon"
                        title="Exportar CSV"
                    >
                        <Download className="w-4 h-4" />
                    </Button>
                    <Button
                        variant="outline"
                        size="icon"
                        title={canManageAccess ? "Gerenciar Contas de Acesso" : "Apenas administrador pode vincular acesso"}
                        disabled={!canManageAccess}
                        onClick={() => navigate("/admin/GerenciamentoUsuarios")}
                    >
                        <Shield className="w-4 h-4" />
                    </Button>
                    {canManageRH && (
                        <Button
                            onClick={() => abrirModal()}
                            className="gap-2 whitespace-nowrap"
                            style={{
                                background: "linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)",
                            }}
                        >
                            <Plus className="w-4 h-4" />
                            Novo Colaborador
                        </Button>
                    )}
                </div>
            </div>

            {/* Collaborator table */}
            <div
                className="rounded-xl border overflow-hidden bg-white"
                style={{ borderColor: "#E5E0D8" }}
            >
                <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                        <thead>
                            <tr
                                className="border-b text-xs text-gray-500 uppercase tracking-wide"
                                style={{ backgroundColor: "#F9F6F2", borderColor: "#E5E0D8" }}
                            >
                                <th className="text-left px-4 py-3 font-semibold">Colaborador</th>
                                <th className="text-left px-4 py-3 font-semibold hidden md:table-cell">
                                    Cargo
                                </th>
                                <th className="text-left px-4 py-3 font-semibold hidden lg:table-cell">
                                    Contrato
                                </th>
                                <th className="text-left px-4 py-3 font-semibold hidden lg:table-cell">
                                    Salário Base
                                </th>
                                <th className="text-left px-4 py-3 font-semibold hidden lg:table-cell">
                                    Admissão
                                </th>
                                <th className="text-left px-4 py-3 font-semibold hidden xl:table-cell">
                                    Matrícula
                                </th>
                                <th className="text-center px-4 py-3 font-semibold">Status</th>
                                <th className="text-right px-4 py-3 font-semibold">Ações</th>
                            </tr>
                        </thead>
                        <tbody>
                            {colaboradoresFiltrados.length === 0 ? (
                                <tr>
                                    <td colSpan={8} className="text-center py-14">
                                        <Users className="w-12 h-12 mx-auto mb-3 text-gray-200" />
                                        <p className="text-gray-400 mb-3">
                                            Nenhum colaborador encontrado
                                        </p>
                                        {canManageRH && (
                                            <Button
                                                onClick={() => abrirModal()}
                                                size="sm"
                                                style={{
                                                    background:
                                                        "linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)",
                                                }}
                                            >
                                                <Plus className="w-4 h-4 mr-2" />
                                                Cadastrar Colaborador
                                            </Button>
                                        )}
                                    </td>
                                </tr>
                            ) : (
                                colaboradoresFiltrados.map((colaborador) => {
                                    const statusStyle = getStatusStyle(colaborador.status);
                                    const admissao = colaborador.data_admissao
                                        ? new Date(
                                              colaborador.data_admissao + "T00:00:00"
                                          ).toLocaleDateString("pt-BR")
                                        : null;
                                    return (
                                        <tr
                                            key={colaborador.id}
                                            className="border-b last:border-0 hover:bg-gray-50/70 transition-colors"
                                            style={{ borderColor: "#F0EBE3" }}
                                        >
                                            {/* Colaborador name + email */}
                                            <td className="px-4 py-3">
                                                <div className="flex items-center gap-3">
                                                    <div
                                                        className="w-9 h-9 rounded-full flex items-center justify-center text-sm font-bold text-white flex-shrink-0"
                                                        style={{
                                                            background: getAvatarGradient(
                                                                colaborador.status
                                                            ),
                                                        }}
                                                    >
                                                        {colaborador.nome_completo
                                                            ?.charAt(0)
                                                            .toUpperCase() || "?"}
                                                    </div>
                                                    <div className="min-w-0">
                                                        <p
                                                            className="font-semibold truncate"
                                                            style={{ color: "#07593f" }}
                                                        >
                                                            {formatarNome(colaborador.nome_completo) ||
                                                                "Sem nome"}
                                                        </p>
                                                        {colaborador.email && (
                                                            <p className="text-xs text-gray-400 truncate hidden sm:block">
                                                                {colaborador.email}
                                                            </p>
                                                        )}
                                                        {/* On mobile, show cargo below name */}
                                                        <p className="text-xs text-gray-500 md:hidden mt-0.5">
                                                            {colaborador.descricao_cargo || "Sem cargo"}
                                                        </p>
                                                    </div>
                                                </div>
                                            </td>

                                            {/* Cargo */}
                                            <td className="px-4 py-3 hidden md:table-cell">
                                                <span className="flex items-center gap-1.5 text-gray-700">
                                                    <Building className="w-3 h-3 text-gray-400 shrink-0" />
                                                    {colaborador.descricao_cargo || (
                                                        <span className="text-gray-300 italic">
                                                            Sem cargo
                                                        </span>
                                                    )}
                                                </span>
                                            </td>

                                            {/* Contrato */}
                                            <td className="px-4 py-3 hidden lg:table-cell">
                                                {colaborador.tipo_contrato ? (
                                                    <Badge
                                                        variant="outline"
                                                        className="text-xs font-normal"
                                                    >
                                                        {colaborador.tipo_contrato}
                                                    </Badge>
                                                ) : (
                                                    <span className="text-gray-300">—</span>
                                                )}
                                            </td>
                                            <td className="px-4 py-3 hidden lg:table-cell">
                                              {colaborador.salario_base ? colaborador.salario_base.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }) : "—"}
                                            </td>
                                            {/* Admissão */}
                                            <td className="px-4 py-3 hidden lg:table-cell text-gray-600">
                                                {admissao || (
                                                    <span className="text-gray-300">—</span>
                                                )}
                                            </td>

                                            {/* Matrícula */}
                                            <td className="px-4 py-3 hidden xl:table-cell">
                                                {colaborador.matricula ? (
                                                    <code className="text-xs bg-gray-100 px-2 py-0.5 rounded font-mono text-gray-700">
                                                        {colaborador.matricula}
                                                    </code>
                                                ) : (
                                                    <span className="text-gray-300">—</span>
                                                )}
                                            </td>

                                            {/* Status badge */}
                                            <td className="px-4 py-3 text-center">
                                                <Badge
                                                    className="text-xs"
                                                    style={{
                                                        backgroundColor: statusStyle.bg,
                                                        color: statusStyle.color,
                                                        border: "none",
                                                    }}
                                                >
                                                    {colaborador.status || "Indefinido"}
                                                </Badge>
                                            </td>

                                            {/* Actions */}
                                            <td className="px-4 py-3">
                                                <div className="flex items-center justify-end gap-1">
                                                    <Button
                                                        variant="ghost"
                                                        size="icon"
                                                        className="h-8 w-8 text-gray-500 hover:text-gray-800"
                                                        title="Ver detalhes"
                                                        onClick={() =>
                                                            abrirDetalhes(colaborador)
                                                        }
                                                    >
                                                        <Eye className="w-3.5 h-3.5" />
                                                    </Button>
                                                    {canManageRH && (
                                                        <Button
                                                            variant="ghost"
                                                            size="icon"
                                                            className="h-8 w-8 text-gray-500 hover:text-gray-800"
                                                            title="Editar"
                                                            onClick={() =>
                                                                abrirModal(colaborador)
                                                            }
                                                        >
                                                            <Edit className="w-3.5 h-3.5" />
                                                        </Button>
                                                    )}
                                                    <DropdownMenu>
                                                        <DropdownMenuTrigger asChild>
                                                            <Button
                                                                variant="ghost"
                                                                size="icon"
                                                                className="h-8 w-8 text-gray-500 hover:text-gray-800"
                                                            >
                                                                <MoreVertical className="w-3.5 h-3.5" />
                                                            </Button>
                                                        </DropdownMenuTrigger>
                                                        <DropdownMenuContent align="end">
                                                            <DropdownMenuItem
                                                                onClick={() => {
                                                                    setNovoColaborador(
                                                                        colaborador
                                                                    );
                                                                    setModalResumo(true);
                                                                }}
                                                            >
                                                                <FileText className="w-4 h-4 mr-2" />
                                                                Resumo de Contratação
                                                            </DropdownMenuItem>
                                                            {canManageRH && (
                                                                <>
                                                                    <DropdownMenuSeparator />
                                                                    <DropdownMenuItem
                                                                        onClick={() =>
                                                                            abrirModal(
                                                                                colaborador,
                                                                                "profissional"
                                                                            )
                                                                        }
                                                                    >
                                                                        <Shield className="w-4 h-4 mr-2" />
                                                                        Alterar Cargo
                                                                    </DropdownMenuItem>
                                                                    <DropdownMenuItem
                                                                        className="text-red-600 focus:text-red-600"
                                                                        onClick={() =>
                                                                            setConfirmDelete(
                                                                                colaborador
                                                                            )
                                                                        }
                                                                    >
                                                                        <Trash2 className="w-4 h-4 mr-2" />
                                                                        Excluir
                                                                    </DropdownMenuItem>
                                                                </>
                                                            )}
                                                        </DropdownMenuContent>
                                                    </DropdownMenu>
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })
                            )}
                        </tbody>
                    </table>
                </div>

                {/* Table footer */}
                {colaboradoresFiltrados.length > 0 && (
                    <div
                        className="px-4 py-2 border-t text-xs text-gray-400 flex items-center justify-between"
                        style={{
                            borderColor: "#E5E0D8",
                            backgroundColor: "#F9F6F2",
                        }}
                    >
                        <span>
                            {colaboradoresFiltrados.length} de{" "}
                            {colaboradoresEnriquecidos.length} colaboradores
                        </span>
                        {(filtroStatus !== "todos" || filtroContrato !== "todos" || busca) && (
                            <button
                                className="text-blue-600 hover:underline"
                                onClick={() => {
                                    setFiltroStatus("todos");
                                    setFiltroContrato("todos");
                                    setBusca("");
                                }}
                            >
                                Limpar filtros
                            </button>
                        )}
                    </div>
                )}
            </div>

            {/* Modals */}
            {modalAberto && (
                <ColaboradorModal
                    colaborador={colaboradorSelecionado}
                    usuarios={usuarios}
                    initialTab={initialTab}
                    onClose={() => {
                        setModalAberto(false);
                        setColaboradorSelecionado(null);
                    }}
                    onSuccess={
                        !colaboradorSelecionado ? handleNovoColaboradorSuccess : undefined
                    }
                />
            )}

            {modalDetalhes && colaboradorSelecionado && (
                <ColaboradorDetalhesModal
                    colaborador={colaboradorSelecionado}
                    canEdit={canManageRH}
                    onClose={() => {
                        setModalDetalhes(false);
                        setColaboradorSelecionado(null);
                    }}
                    onEdit={() => {
                        setModalDetalhes(false);
                        abrirModal(colaboradorSelecionado);
                    }}
                />
            )}

            {modalResumo && novoColaborador && (
                <ContratacaoResumoModal
                    colaborador={novoColaborador}
                    onClose={() => {
                        setModalResumo(false);
                        setNovoColaborador(null);
                    }}
                />
            )}

            <AlertDialog
                open={!!confirmDelete}
                onOpenChange={() => setConfirmDelete(null)}
            >
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>Confirmar Exclusão</AlertDialogTitle>
                        <AlertDialogDescription>
                            Tem certeza que deseja excluir{" "}
                            <strong>{confirmDelete?.nome_completo}</strong>? Esta ação não
                            pode ser desfeita.
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel>Cancelar</AlertDialogCancel>
                        <AlertDialogAction
                            onClick={() => deleteMutation.mutate(confirmDelete.id)}
                            className="bg-red-600 hover:bg-red-700"
                        >
                            Excluir
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </div>
    );
}

import React from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import { Separator } from "@/components/ui/separator";
import {
    User, Briefcase, DollarSign, Gift, Calendar, CreditCard,
    Phone, Mail, MapPin, CheckCircle2, Printer, X, KeyRound
} from "lucide-react";
import { gerarResumoEstimado } from "@/utils/calculosTrabalhistas";
import html2pdf from "html2pdf.js";

// Utility function to format currency
const formatCurrency = (value) => {
    const num = Number(value) || 0;
    return num.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
};

// Section Header Component
function SectionHeader({ icon: Icon, title, color }) {
    return (
        <div className="flex items-center gap-2 mb-2">
            <div
                className="w-8 h-8 rounded-lg flex items-center justify-center shrink-0"
                style={{ backgroundColor: `${color}15` }}
            >
                <Icon className="w-4 h-4" style={{ color }} />
            </div>
            <h3 className="font-semibold text-gray-900 leading-none">{title}</h3>
        </div>
    );
}

// Data Row Component
function DataRow({ label, value, highlight = false }) {
    return (
        <div className="flex justify-between items-center py-1">
            <span className="text-[11px] text-gray-600">{label}</span>
            <span className={`text-[11px] ${highlight ? 'font-bold text-green-600' : 'font-medium text-gray-900'}`}>
                {value}
            </span>
        </div>
    );
}

// Benefit Badge Component
function BenefitBadge({ label, value, active = true }) {
    if (!active || Number(value) <= 0) return null;

    return (
        <div className="flex items-center justify-between p-2 bg-blue-50 rounded-lg border border-blue-100">
            <span className="text-sm text-blue-800">{label}</span>
            <span className="text-sm font-semibold text-blue-900">{formatCurrency(value)}</span>
        </div>
    );
}

export default function ContratacaoResumoModal({ colaborador, onClose, onGenerateAccess }) {
    if (!colaborador) return null;

    // Calculate totals using the centralized CLT engine
    const resumo = gerarResumoEstimado(colaborador);

    const salarioBase = resumo.salario_base;
    const totalBeneficios = resumo.beneficios_empresa;
    const totalBruto = salarioBase + totalBeneficios;
    const totalLiquido = resumo.salario_liquido;
    const valeTransporte = Number(colaborador.vale_transporte) || 0;
    const valeAlimentacao = Number(colaborador.vale_alimentacao) || 0;
    const valeRefeicao = Number(colaborador.vale_refeicao) || 0;
    const planoSaude = Number(colaborador.plano_saude) || 0;
    const planoOdontologico = Number(colaborador.plano_odontologico) || 0;
    const bonusMensal = Number(colaborador.bonus_mensal) || 0;
    const outrosBeneficios = Number(colaborador.outros_beneficios) || 0;

    const diaPagamento = colaborador.dia_pagamento || 5;
    const tipoPagamento = colaborador.tipo_pagamento || 'Mensal';
    const recebeVale = typeof colaborador.recebe_vale === 'boolean'
        ? colaborador.recebe_vale
        : !!(valeTransporte || valeAlimentacao || valeRefeicao);
    const diaVale = colaborador.dia_vale || 20;

    const descontoPlanoSaude = Number(colaborador.desconto_plano_saude) || 0;
    const descontoAdiantamento = Number(colaborador.desconto_adiantamento) || 0;

    let descontosAdicionaisList = [];
    try {
        const parsed = JSON.parse(colaborador.descricao_outros_descontos || "[]");
        if (Array.isArray(parsed)) {
            descontosAdicionaisList = parsed;
        } else if (colaborador.outros_descontos > 0) {
            descontosAdicionaisList = [{ descricao: colaborador.descricao_outros_descontos || 'Outros Descontos', valor: colaborador.outros_descontos }];
        }
    } catch {
        if (colaborador.outros_descontos > 0) {
            descontosAdicionaisList = [{ descricao: colaborador.descricao_outros_descontos || 'Outros Descontos', valor: colaborador.outros_descontos }];
        }
    }

    const handlePrint = () => {
        const element = document.getElementById("resumo-contratacao-content");
        if (!element) return;

        const nomeArquivo = `Ficha_Contratacao_${colaborador.nome_completo?.replace(/\s+/g, '_') || 'Colaborador'}.pdf`;

        const opt = {
            margin: 10,
            filename: nomeArquivo,
            image: { type: 'jpeg', quality: 0.98 },
            html2canvas: { scale: 2, useCORS: true },
            jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
        };

        html2pdf().set(opt).from(element).save();
    };

    return (
        <Dialog open onOpenChange={onClose}>
            <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
                <div id="resumo-contratacao-content" className="p-2">
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-2">
                            <div className="w-10 h-10 rounded-xl flex items-center justify-center shrink-0" style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}>
                                <CheckCircle2 className="w-5 h-5 text-white" />
                            </div>
                            <div className="flex flex-col justify-center">
                                <span className="text-xl leading-none mb-1.5" style={{ color: '#07593f' }}>Resumo de Contratação</span>
                                <p className="text-xs font-normal text-gray-500 leading-none">Funcionário cadastrado com sucesso!</p>
                            </div>
                        </DialogTitle>
                    </DialogHeader>

                    <div className="space-y-3 mt-3">
                    {/* Dados Pessoais */}
                    <Card className="border-0 shadow-sm bg-gray-50">
                        <CardContent className="pt-4">
                            <SectionHeader icon={User} title="Dados do Funcionário" color="#07593f" />
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <DataRow label="Nome Completo" value={colaborador.nome_completo || '-'} />
                                    <DataRow label="CPF" value={colaborador.cpf || '-'} />
                                    <DataRow label="Telefone" value={colaborador.telefone || '-'} />
                                    <DataRow label="Email" value={colaborador.email || '-'} />
                                </div>
                                <div>
                                    <DataRow label="Cargo" value={colaborador.descricao_cargo || '-'} />

                                    <DataRow label="Tipo Contrato" value={colaborador.tipo_contrato || 'CLT'} />
                                    <DataRow label="Data Admissão" value={colaborador.data_admissao ? new Date(colaborador.data_admissao).toLocaleDateString('pt-BR') : '-'} />
                                </div>
                            </div>
                        </CardContent>
                    </Card>

                    {/* Linha 1: Remuneração e Dados Bancários */}
                    <div className="grid grid-cols-2 gap-3">
                            {/* Remuneração e Pagamento */}
                            <Card className="border-0 shadow-sm bg-green-50 h-fit">
                                <CardContent className="pt-3 pb-3">
                                    <SectionHeader icon={DollarSign} title="Remuneração e Pagamento" color="#22c55e" />
                                    <div className="space-y-0.5 mb-2">
                                        <DataRow label="Salário Base" value={formatCurrency(salarioBase)} highlight />
                                        <DataRow label="Carga Horária" value={`${colaborador.carga_horaria || 44}h semanais`} />
                                    </div>
                                    <div className="pt-2 border-t border-green-200">
                                        <div className="flex items-center justify-between mb-1">
                                            <p className="text-[10px] text-gray-600">Dia de Pagamento</p>
                                            <p className="text-[11px] font-bold text-green-800">
                                                {resumo.tipo_dia_pagamento === "util" ? `${diaPagamento}º Dia Útil` : `Todo dia ${diaPagamento}`}
                                            </p>
                                        </div>
                                        <div className="flex items-center justify-between">
                                            <p className="text-[10px] text-gray-600">Recebe Vale</p>
                                            <p className="text-[11px] font-semibold text-green-800">
                                                {recebeVale 
                                                    ? `Sim, ${resumo.tipo_dia_vale === "util" ? `${diaVale}º Dia Útil` : `dia ${diaVale}`}`
                                                    : 'Não'}
                                            </p>
                                        </div>
                                        
                                        {recebeVale && (Number(colaborador.valor_dia_pagamento) > 0 || Number(colaborador.valor_dia_vale) > 0) && (
                                            <div className="mt-2 pt-2 border-t border-green-200">
                                                <p className="text-[10px] text-gray-600 mb-1">Distribuição do Salário</p>
                                                <div className="grid grid-cols-2 gap-2">
                                                    {Number(colaborador.valor_dia_pagamento) > 0 && (
                                                        <div className="p-1 bg-green-100/50 rounded text-center">
                                                            <p className="text-[9px] text-green-700">
                                                                {resumo.tipo_dia_pagamento === "util" ? `${diaPagamento}º Dia Útil` : `Dia ${diaPagamento}`}
                                                            </p>
                                                            <p className="text-[10px] font-bold text-green-900">{formatCurrency(colaborador.valor_dia_pagamento)}</p>
                                                        </div>
                                                    )}
                                                    {Number(colaborador.valor_dia_vale) > 0 && (
                                                        <div className="p-1 bg-green-100/50 rounded text-center">
                                                            <p className="text-[9px] text-green-700">
                                                                {resumo.tipo_dia_vale === "util" ? `${diaVale}º Dia Útil (Vale)` : `Dia ${diaVale} (Vale)`}
                                                            </p>
                                                            <p className="text-[10px] font-bold text-green-900">{formatCurrency(colaborador.valor_dia_vale)}</p>
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                        )}
                                    </div>
                                </CardContent>
                            </Card>

                        {/* Dados Bancários */}
                        {colaborador.banco ? (
                            <Card className="border-0 shadow-sm h-fit">
                                <CardContent className="pt-3 pb-3">
                                    <SectionHeader icon={CreditCard} title="Dados Bancários" color="#8b5cf6" />
                                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-4 gap-y-1">
                                        <DataRow label="Banco" value={colaborador.banco} />
                                        <DataRow label="Agência" value={colaborador.agencia || '-'} />
                                        <DataRow label="Conta" value={colaborador.conta || '-'} />
                                        <DataRow label="PIX" value={colaborador.pix || '-'} />
                                    </div>
                                </CardContent>
                            </Card>
                        ) : (
                            <Card className="border-0 shadow-sm opacity-50 h-fit">
                                <CardContent className="pt-3 pb-3 flex items-center justify-center h-full">
                                    <span className="text-[11px] text-gray-400">Dados bancários não informados</span>
                                </CardContent>
                            </Card>
                        )}
                    </div>

                    {/* Benefícios */}
                    {totalBeneficios > 0 && (
                        <Card className="border-0 shadow-sm bg-blue-50/50">
                            <CardContent className="pt-4">
                                <SectionHeader icon={Gift} title="Benefícios" color="#3b82f6" />
                                <div className="grid grid-cols-2 gap-2">
                                    <BenefitBadge label="Vale Transporte" value={valeTransporte} />
                                    <BenefitBadge label="Vale Alimentação" value={valeAlimentacao} />
                                    <BenefitBadge label="Vale Refeição" value={valeRefeicao} />
                                    <BenefitBadge label="Plano de Saúde" value={planoSaude} />
                                    <BenefitBadge label="Plano Odontológico" value={planoOdontologico} />
                                    <BenefitBadge label="Bônus Mensal" value={bonusMensal} />
                                    {outrosBeneficios > 0 && (
                                        <div className="col-span-2">
                                            <BenefitBadge
                                                label={`Outros: ${colaborador.descricao_outros_beneficios || 'Benefícios adicionais'}`}
                                                value={outrosBeneficios}
                                            />
                                        </div>
                                    )}
                                </div>
                                <Separator className="my-3" />
                                <DataRow label="Total em Benefícios" value={formatCurrency(totalBeneficios)} highlight />
                            </CardContent>
                        </Card>
                    )}

                    {/* Resumo Financeiro */}
                    <Card className="border-2" style={{ borderColor: '#07593f' }}>
                        <CardContent className="pt-3 pb-3">
                            <SectionHeader icon={CreditCard} title="Resumo Financeiro Mensal" color="#07593f" />

                            <div className="space-y-1 mb-2">
                                <DataRow label="Salário Base" value={formatCurrency(salarioBase)} />
                                {totalBeneficios > 0 && (
                                    <DataRow label="(+) Benefícios" value={formatCurrency(totalBeneficios)} />
                                )}
                                <div className="border-t pt-1">
                                    <DataRow label="Total Bruto" value={formatCurrency(totalBruto)} highlight />
                                </div>
                            </div>

                            <div className="p-2 bg-gray-100 rounded-lg mb-2">
                                <p className="text-[10px] text-gray-600 mb-1">Descontos e Encargos (CLT 2025):</p>
                                <DataRow label={`INSS (${resumo.inss_faixa})`} value={`- ${formatCurrency(resumo.inss)}`} />
                                {resumo.irrf > 0 && (
                                    <DataRow label={`IRRF (${resumo.irrf_faixa})`} value={`- ${formatCurrency(resumo.irrf)}`} />
                                )}
                                {resumo.pensao_alimenticia > 0 && (
                                    <DataRow label="Pensão Alimentícia" value={`- ${formatCurrency(resumo.pensao_alimenticia)}`} />
                                )}
                                {resumo.vale_transporte > 0 && (
                                    <DataRow label="Desc. VT (6% CLT)" value={`- ${formatCurrency(resumo.vale_transporte)}`} />
                                )}
                                {resumo.adicional_noturno > 0 && (
                                    <DataRow label="(+) Adic. Noturno" value={`+ ${formatCurrency(resumo.adicional_noturno)}`} />
                                )}
                                {descontoPlanoSaude > 0 && (
                                    <DataRow label="Desc. Plano Saúde" value={`- ${formatCurrency(descontoPlanoSaude)}`} />
                                )}
                                {descontoAdiantamento > 0 && (
                                    <DataRow label="Adiantamento" value={`- ${formatCurrency(descontoAdiantamento)}`} />
                                )}
                                {descontosAdicionaisList.map((desc, idx) => {
                                    if (!desc.valor) return null;
                                    return (
                                        <DataRow key={`desc-${idx}`} label={desc.descricao || 'Outros Descontos'} value={`- ${formatCurrency(desc.valor)}`} />
                                    );
                                })}
                                {resumo.insalubridade > 0 && (
                                    <DataRow label="(+) Insalubridade" value={`+ ${formatCurrency(resumo.insalubridade)}`} />
                                )}
                                {resumo.periculosidade > 0 && (
                                    <DataRow label="(+) Periculosidade" value={`+ ${formatCurrency(resumo.periculosidade)}`} />
                                )}
                                {resumo.salario_familia > 0 && (
                                    <DataRow label="(+) Salário Família" value={`+ ${formatCurrency(resumo.salario_familia)}`} />
                                )}
                                <DataRow label="FGTS (8%)" value={formatCurrency(resumo.fgts)} />
                            </div>

                            <div className="p-2 rounded-lg" style={{ backgroundColor: '#07593f10' }}>
                                <div className="flex justify-between items-center">
                                    <div>
                                        <p className="text-xs text-gray-600">Valor Líquido Estimado</p>
                                        <p className="text-[10px] text-gray-500">(após descontos obrigatórios)</p>
                                    </div>
                                    <span className="text-xl font-bold" style={{ color: '#07593f' }}>
                                        {formatCurrency(totalLiquido)}
                                    </span>
                                </div>
                            </div>
                        </CardContent>
                    </Card>
                </div>
            </div>

            {/* Footer Actions */}
                <div className="flex justify-between gap-3 mt-6 pt-4 border-t">
                    <Button variant="outline" onClick={handlePrint} className="flex items-center gap-2">
                        <Printer className="w-4 h-4" />
                        Imprimir
                    </Button>
                    <div className="flex gap-2">
                        {onGenerateAccess && (
                            <Button
                                onClick={onGenerateAccess}
                                className="bg-amber-600 hover:bg-amber-700 text-white gap-2"
                            >
                                <KeyRound className="w-4 h-4" />
                                Gerar Acesso ao Sistema
                            </Button>
                        )}
                        <Button
                            onClick={onClose}
                            style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
                        >
                            Concluir
                        </Button>
                    </div>
                </div>
            </DialogContent>
        </Dialog>
    );
}

import React, { useState, useRef } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { base44, supabase } from "@/api/base44Client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
    FileText, Plus, Upload, Eye, Download, Trash2,
    Search, Folder, File, Calendar, User
} from "lucide-react";
import { toast } from "sonner";

const TIPOS_DOCUMENTO = ["Contrato", "Atestado", "Certificado", "Advertência", "Carteira de Trabalho", "Comprovante", "Outros"];

export default function DocumentosTab() {
    const queryClient = useQueryClient();
    const [modalUpload, setModalUpload] = useState(false);
    const [documentoSelecionado, setDocumentoSelecionado] = useState(null);
    const [confirmDelete, setConfirmDelete] = useState(null);
    const [busca, setBusca] = useState("");
    const [filtroTipo, setFiltroTipo] = useState("todos");
    const [filtroColaborador, setFiltroColaborador] = useState("todos");

    const { data: colaboradores = [] } = useQuery({
        queryKey: ['colaboradores'],
        queryFn: () => base44.entities.Colaborador.list(),
    });

    const { data: documentos = [], isLoading } = useQuery({
        queryKey: ['documentos_rh'],
        queryFn: () => base44.entities.DocumentoRH.list('-created_at'),
    });

    const deleteMutation = useMutation({
        mutationFn: (id) => base44.entities.DocumentoRH.delete(id),
        onSuccess: () => {
            queryClient.invalidateQueries(['documentos_rh']);
            toast.success("Documento excluído!");
            setConfirmDelete(null);
        },
    });

    const colaboradoresAtivos = colaboradores.filter(c => c.status !== 'Desligado');

    // Metrics
    const documentosPorTipo = TIPOS_DOCUMENTO.map(tipo => ({
        tipo,
        quantidade: documentos.filter(d => d.tipo === tipo).length,
    }));

    const documentosFiltrados = documentos.filter(d => {
        const matchBusca = !busca ||
            d.titulo?.toLowerCase().includes(busca.toLowerCase()) ||
            d.colaborador_nome?.toLowerCase().includes(busca.toLowerCase());
        const matchTipo = filtroTipo === "todos" || d.tipo === filtroTipo;
        const matchColaborador = filtroColaborador === "todos" || d.colaborador_id === filtroColaborador;
        return matchBusca && matchTipo && matchColaborador;
    });

    const getTipoBadgeStyle = (tipo) => {
        switch (tipo) {
            case 'Contrato':
                return { backgroundColor: '#D1FAE5', color: '#065F46' };
            case 'Atestado':
                return { backgroundColor: '#FEE2E2', color: '#991B1B' };
            case 'Certificado':
                return { backgroundColor: '#DBEAFE', color: '#1E40AF' };
            case 'Advertência':
                return { backgroundColor: '#FEF3C7', color: '#92400E' };
            case 'Carteira de Trabalho':
                return { backgroundColor: '#E0E7FF', color: '#3730A3' };
            default:
                return { backgroundColor: '#E5E7EB', color: '#374151' };
        }
    };

    const abrirDocumento = (url) => {
        if (url) {
            window.open(url, '_blank');
        } else {
            toast.error("URL do documento não disponível");
        }
    };

    return (
        <div className="space-y-6">
            {/* Metrics */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <Card className="border-0 shadow-lg">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs text-gray-500">Total de Documentos</p>
                                <p className="text-2xl font-bold" style={{ color: '#07593f' }}>{documentos.length}</p>
                            </div>
                            <Folder className="w-8 h-8 opacity-50" style={{ color: '#07593f' }} />
                        </div>
                    </CardContent>
                </Card>
                {documentosPorTipo.slice(0, 3).map(item => (
                    <Card key={item.tipo} className="border-0 shadow-lg">
                        <CardContent className="p-4">
                            <div className="flex items-center justify-between">
                                <div>
                                    <p className="text-xs text-gray-500">{item.tipo}</p>
                                    <p className="text-2xl font-bold text-blue-600">{item.quantidade}</p>
                                </div>
                                <File className="w-8 h-8 text-blue-600 opacity-50" />
                            </div>
                        </CardContent>
                    </Card>
                ))}
            </div>

            {/* Filters */}
            <Card className="border-0 shadow-lg">
                <CardContent className="p-4">
                    <div className="flex flex-wrap gap-4">
                        <div className="flex-1 min-w-[200px] relative">
                            <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                            <Input
                                placeholder="Buscar documentos..."
                                value={busca}
                                onChange={(e) => setBusca(e.target.value)}
                                className="pl-9"
                            />
                        </div>
                        <Select value={filtroTipo} onValueChange={setFiltroTipo}>
                            <SelectTrigger className="w-40">
                                <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="todos">Todos os Tipos</SelectItem>
                                {TIPOS_DOCUMENTO.map(t => (
                                    <SelectItem key={t} value={t}>{t}</SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                        <Select value={filtroColaborador} onValueChange={setFiltroColaborador}>
                            <SelectTrigger className="w-48">
                                <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="todos">Todos os Colaboradores</SelectItem>
                                {colaboradoresAtivos.filter(c => c?.id).map(c => (
                                    <SelectItem key={c.id} value={c.id}>{c.nome_completo}</SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                        <Button
                            onClick={() => { setDocumentoSelecionado(null); setModalUpload(true); }}
                            style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
                        >
                            <Upload className="w-4 h-4 mr-2" />
                            Enviar Documento
                        </Button>
                    </div>
                </CardContent>
            </Card>

            {/* Documents List */}
            <Card className="border-0 shadow-lg">
                <CardHeader>
                    <CardTitle className="flex items-center gap-2" style={{ color: '#07593f' }}>
                        <FileText className="w-5 h-5" />
                        Documentos ({documentosFiltrados.length})
                    </CardTitle>
                </CardHeader>
                <CardContent>
                    {isLoading ? (
                        <div className="flex justify-center py-8">
                            <div className="animate-spin rounded-full h-8 w-8 border-b-2" style={{ borderColor: '#07593f' }} />
                        </div>
                    ) : documentosFiltrados.length === 0 ? (
                        <div className="text-center py-12">
                            <Folder className="w-16 h-16 mx-auto mb-4 text-gray-300" />
                            <p className="text-gray-500 mb-4">Nenhum documento encontrado</p>
                            <Button
                                onClick={() => setModalUpload(true)}
                                style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
                            >
                                <Upload className="w-4 h-4 mr-2" />
                                Enviar Primeiro Documento
                            </Button>
                        </div>
                    ) : (
                        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-4">
                            {documentosFiltrados.map(doc => (
                                <div
                                    key={doc.id}
                                    className="p-4 rounded-xl border hover:shadow-md transition-all"
                                    style={{ borderColor: '#E5E0D8' }}
                                >
                                    <div className="flex items-start justify-between mb-3">
                                        <div className="flex items-start gap-3">
                                            <div
                                                className="w-10 h-10 rounded-lg flex items-center justify-center"
                                                style={{ backgroundColor: '#f0f9ff' }}
                                            >
                                                <FileText className="w-5 h-5" style={{ color: '#07593f' }} />
                                            </div>
                                            <div className="flex-1 min-w-0">
                                                <p className="font-semibold truncate" style={{ color: '#07593f' }}>
                                                    {doc.titulo}
                                                </p>
                                                <p className="text-sm text-gray-500 truncate">{doc.colaborador_nome}</p>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="flex items-center gap-2 mb-3">
                                        <Badge style={getTipoBadgeStyle(doc.tipo)}>{doc.tipo}</Badge>
                                        {doc.data_documento && (
                                            <span className="text-xs text-gray-500 flex items-center gap-1">
                                                <Calendar className="w-3 h-3" />
                                                {new Date(doc.data_documento).toLocaleDateString('pt-BR')}
                                            </span>
                                        )}
                                    </div>

                                    {doc.descricao && (
                                        <p className="text-sm text-gray-600 mb-3 line-clamp-2">{doc.descricao}</p>
                                    )}

                                    <div className="flex items-center justify-end gap-1">
                                        {doc.arquivo_url && (
                                            <>
                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    className="h-8 w-8"
                                                    onClick={() => abrirDocumento(doc.arquivo_url)}
                                                >
                                                    <Eye className="w-4 h-4" />
                                                </Button>
                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    className="h-8 w-8"
                                                    onClick={() => {
                                                        const a = document.createElement('a');
                                                        a.href = doc.arquivo_url;
                                                        a.download = doc.titulo || 'documento';
                                                        a.click();
                                                    }}
                                                >
                                                    <Download className="w-4 h-4" />
                                                </Button>
                                            </>
                                        )}
                                        <Button
                                            variant="ghost"
                                            size="icon"
                                            className="h-8 w-8 text-red-600"
                                            onClick={() => setConfirmDelete(doc)}
                                        >
                                            <Trash2 className="w-4 h-4" />
                                        </Button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </CardContent>
            </Card>

            {/* Upload Modal */}
            {modalUpload && (
                <DocumentoUploadModal
                    colaboradores={colaboradoresAtivos}
                    onClose={() => { setModalUpload(false); setDocumentoSelecionado(null); }}
                />
            )}

            {/* Delete Confirmation */}
            <AlertDialog open={!!confirmDelete} onOpenChange={() => setConfirmDelete(null)}>
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>Confirmar Exclusão</AlertDialogTitle>
                        <AlertDialogDescription>
                            Tem certeza que deseja excluir o documento &quot;{confirmDelete?.titulo}&quot;?
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel>Cancelar</AlertDialogCancel>
                        <AlertDialogAction
                            onClick={() => deleteMutation.mutate(confirmDelete.id)}
                            className="bg-red-600 hover:bg-red-700"
                        >
                            Excluir
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </div>
    );
}

// Document Upload Modal
function DocumentoUploadModal({ colaboradores, onClose }) {
    const queryClient = useQueryClient();
    const fileInputRef = useRef(null);

    const [formData, setFormData] = useState({
        colaborador_id: "",
        colaborador_nome: "",
        tipo: "Contrato",
        titulo: "",
        descricao: "",
        data_documento: "",
        arquivo_url: "",
    });

    const [arquivo, setArquivo] = useState(null);
    const [uploading, setUploading] = useState(false);
    const [saving, setSaving] = useState(false);

    const handleColaboradorChange = (id) => {
        const colab = colaboradores.find(c => c.id === id);
        setFormData(prev => ({
            ...prev,
            colaborador_id: id,
            colaborador_nome: colab?.nome_completo || "",
        }));
    };

    const handleFileChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            setArquivo(file);
            if (!formData.titulo) {
                setFormData(prev => ({ ...prev, titulo: file.name.replace(/\.[^/.]+$/, "") }));
            }
        }
    };

    const uploadFile = async () => {
        if (!arquivo) return null;

        const fileExt = arquivo.name.split('.').pop();
        const fileName = `${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`;
        const filePath = `documentos-rh/${fileName}`;

        const { data, error } = await supabase.storage
            .from('documentos')
            .upload(filePath, arquivo);

        if (error) {
            throw new Error("Erro ao fazer upload do arquivo: " + error.message);
        }

        const { data: urlData } = supabase.storage
            .from('documentos')
            .getPublicUrl(filePath);

        return urlData.publicUrl;
    };

    const handleSubmit = async () => {
        if (!formData.colaborador_id || !formData.titulo) {
            toast.error("Colaborador e título são obrigatórios");
            return;
        }

        setSaving(true);
        try {
            let arquivoUrl = formData.arquivo_url;

            if (arquivo) {
                setUploading(true);
                arquivoUrl = await uploadFile();
                setUploading(false);
            }

            await base44.entities.DocumentoRH.create({
                ...formData,
                arquivo_url: arquivoUrl,
            });

            queryClient.invalidateQueries(['documentos_rh']);
            toast.success("Documento enviado com sucesso!");
            onClose();
        } catch (error) {
            toast.error("Erro: " + error.message);
        } finally {
            setSaving(false);
            setUploading(false);
        }
    };

    return (
        <Dialog open onOpenChange={onClose}>
            <DialogContent className="max-w-lg">
                <DialogHeader>
                    <DialogTitle className="flex items-center gap-2" style={{ color: '#07593f' }}>
                        <Upload className="w-5 h-5" />
                        Enviar Documento
                    </DialogTitle>
                </DialogHeader>

                <div className="space-y-4 mt-4">
                    <div>
                        <Label>Colaborador *</Label>
                        <Select value={formData.colaborador_id} onValueChange={handleColaboradorChange}>
                            <SelectTrigger>
                                <SelectValue placeholder="Selecione o colaborador" />
                            </SelectTrigger>
                            <SelectContent>
                                {colaboradores.filter(c => c?.id).map(c => (
                                    <SelectItem key={c.id} value={c.id}>{c.nome_completo}</SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <Label>Tipo de Documento</Label>
                            <Select value={formData.tipo} onValueChange={(v) => setFormData(prev => ({ ...prev, tipo: v }))}>
                                <SelectTrigger>
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    {TIPOS_DOCUMENTO.map(t => (
                                        <SelectItem key={t} value={t}>{t}</SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                        <div>
                            <Label>Data do Documento</Label>
                            <Input
                                type="date" lang="pt-BR"
                                value={formData.data_documento}
                                onChange={(e) => setFormData(prev => ({ ...prev, data_documento: e.target.value }))}
                            />
                        </div>
                    </div>

                    <div>
                        <Label>Título *</Label>
                        <Input
                            value={formData.titulo}
                            onChange={(e) => setFormData(prev => ({ ...prev, titulo: e.target.value }))}
                            placeholder="Nome do documento"
                        />
                    </div>

                    <div>
                        <Label>Descrição</Label>
                        <Textarea
                            value={formData.descricao}
                            onChange={(e) => setFormData(prev => ({ ...prev, descricao: e.target.value }))}
                            placeholder="Breve descrição do documento..."
                            rows={2}
                        />
                    </div>

                    {/* File Upload */}
                    <div>
                        <Label>Arquivo</Label>
                        <div
                            className="border-2 border-dashed rounded-lg p-6 text-center cursor-pointer hover:border-gray-400 transition-colors"
                            style={{ borderColor: '#E5E0D8' }}
                            onClick={() => fileInputRef.current?.click()}
                        >
                            <input
                                ref={fileInputRef}
                                type="file"
                                className="hidden"
                                onChange={handleFileChange}
                                accept=".pdf,.doc,.docx,.jpg,.jpeg,.png"
                            />
                            {arquivo ? (
                                <div className="flex items-center justify-center gap-2">
                                    <FileText className="w-8 h-8" style={{ color: '#07593f' }} />
                                    <div className="text-left">
                                        <p className="font-medium">{arquivo.name}</p>
                                        <p className="text-sm text-gray-500">
                                            {(arquivo.size / 1024 / 1024).toFixed(2)} MB
                                        </p>
                                    </div>
                                </div>
                            ) : (
                                <>
                                    <Upload className="w-10 h-10 mx-auto mb-2 text-gray-400" />
                                    <p className="text-gray-600">Clique para selecionar um arquivo</p>
                                    <p className="text-xs text-gray-400 mt-1">PDF, DOC, DOCX, JPG, PNG (max 10MB)</p>
                                </>
                            )}
                        </div>
                    </div>

                    <div>
                        <Label>Ou cole uma URL</Label>
                        <Input
                            value={formData.arquivo_url}
                            onChange={(e) => setFormData(prev => ({ ...prev, arquivo_url: e.target.value }))}
                            placeholder="https://..."
                            disabled={!!arquivo}
                        />
                    </div>
                </div>

                <div className="flex justify-end gap-3 mt-6">
                    <Button variant="outline" onClick={onClose}>Cancelar</Button>
                    <Button
                        onClick={handleSubmit}
                        disabled={saving || uploading}
                        style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
                    >
                        {uploading ? "Enviando arquivo..." : saving ? "Salvando..." : "Enviar Documento"}
                    </Button>
                </div>
            </DialogContent>
        </Dialog>
    );
}

import React, { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { base44 } from "@/api/base44Client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
    Calendar, Plus, Check, X, Clock, Umbrella,
    FileText, Edit, Trash2, Filter, CalendarDays
} from "lucide-react";
import { toast } from "sonner";

const STATUS_FERIAS = ["Solicitada", "Aprovada", "Rejeitada", "Em Gozo", "Concluída", "Cancelada"];
const STATUS_LICENCA = ["Solicitada", "Aprovada", "Rejeitada", "Em Andamento", "Concluída"];
const TIPOS_LICENCA = ["Médica", "Maternidade", "Paternidade", "Casamento", "Falecimento", "Outros"];

export default function FeriasLicencasTab() {
    const queryClient = useQueryClient();
    const [modalFerias, setModalFerias] = useState(false);
    const [modalLicenca, setModalLicenca] = useState(false);
    const [itemSelecionado, setItemSelecionado] = useState(null);
    const [confirmDelete, setConfirmDelete] = useState(null);
    const [tipoDelete, setTipoDelete] = useState(null);
    const [filtroStatus, setFiltroStatus] = useState("todos");

    const { data: colaboradores = [] } = useQuery({
        queryKey: ['colaboradores'],
        queryFn: () => base44.entities.Colaborador.list(),
    });

    const { data: ferias = [], isLoading: loadingFerias } = useQuery({
        queryKey: ['ferias'],
        queryFn: () => base44.entities.Ferias.list('-data_inicio'),
    });

    const { data: licencas = [], isLoading: loadingLicencas } = useQuery({
        queryKey: ['licencas'],
        queryFn: () => base44.entities.Licenca.list('-data_inicio'),
    });

    const colaboradoresAtivos = colaboradores.filter(c => c.status !== 'Desligado');

    // Metrics
    const feriasProximas = ferias.filter(f => {
        if (f.status !== 'Aprovada') return false;
        const dataInicio = new Date(f.data_inicio);
        const hoje = new Date();
        const proximos30Dias = new Date(hoje.getTime() + 30 * 24 * 60 * 60 * 1000);
        return dataInicio >= hoje && dataInicio <= proximos30Dias;
    });

    const feriasEmGozo = ferias.filter(f => f.status === 'Em Gozo');
    const licencasAtivas = licencas.filter(l => l.status === 'Em Andamento');
    const pendentesAprovacao = [...ferias.filter(f => f.status === 'Solicitada'), ...licencas.filter(l => l.status === 'Solicitada')];

    const getStatusBadgeStyle = (status) => {
        switch (status) {
            case 'Aprovada':
            case 'Aprovado':
                return { backgroundColor: '#D1FAE5', color: '#065F46' };
            case 'Em Gozo':
            case 'Em Andamento':
                return { backgroundColor: '#DBEAFE', color: '#1E40AF' };
            case 'Solicitada':
            case 'Solicitado':
                return { backgroundColor: '#FEF3C7', color: '#92400E' };
            case 'Rejeitada':
            case 'Rejeitado':
                return { backgroundColor: '#FEE2E2', color: '#991B1B' };
            case 'Concluída':
            case 'Concluído':
                return { backgroundColor: '#E5E7EB', color: '#374151' };
            case 'Cancelada':
            case 'Cancelado':
                return { backgroundColor: '#FED7AA', color: '#C2410C' };
            default:
                return { backgroundColor: '#E5E7EB', color: '#374151' };
        }
    };

    return (
        <div className="space-y-6">
            {/* Metrics */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <Card className="border-0 shadow-lg">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs text-gray-500">Férias Próximas (30 dias)</p>
                                <p className="text-2xl font-bold text-blue-600">{feriasProximas.length}</p>
                            </div>
                            <CalendarDays className="w-8 h-8 text-blue-600 opacity-50" />
                        </div>
                    </CardContent>
                </Card>
                <Card className="border-0 shadow-lg">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs text-gray-500">Em Férias</p>
                                <p className="text-2xl font-bold" style={{ color: '#07593f' }}>{feriasEmGozo.length}</p>
                            </div>
                            <Umbrella className="w-8 h-8 opacity-50" style={{ color: '#07593f' }} />
                        </div>
                    </CardContent>
                </Card>
                <Card className="border-0 shadow-lg">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs text-gray-500">Licenças Ativas</p>
                                <p className="text-2xl font-bold text-orange-600">{licencasAtivas.length}</p>
                            </div>
                            <FileText className="w-8 h-8 text-orange-600 opacity-50" />
                        </div>
                    </CardContent>
                </Card>
                <Card className="border-0 shadow-lg">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-xs text-gray-500">Aguardando Aprovação</p>
                                <p className="text-2xl font-bold text-amber-600">{pendentesAprovacao.length}</p>
                            </div>
                            <Clock className="w-8 h-8 text-amber-600 opacity-50" />
                        </div>
                    </CardContent>
                </Card>
            </div>

            {/* Actions */}
            <div className="flex flex-wrap gap-3">
                <Button
                    onClick={() => { setItemSelecionado(null); setModalFerias(true); }}
                    style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
                >
                    <Plus className="w-4 h-4 mr-2" />
                    Nova Solicitação de Férias
                </Button>
                <Button
                    onClick={() => { setItemSelecionado(null); setModalLicenca(true); }}
                    variant="outline"
                    className="border-orange-300 text-orange-600 hover:bg-orange-50"
                >
                    <Plus className="w-4 h-4 mr-2" />
                    Nova Licença
                </Button>
            </div>

            {/* Pending Approvals */}
            {pendentesAprovacao.length > 0 && (
                <Card className="border-0 shadow-lg border-l-4" style={{ borderLeftColor: '#f38a4c' }}>
                    <CardHeader>
                        <CardTitle className="flex items-center gap-2 text-amber-700">
                            <Clock className="w-5 h-5" />
                            Aguardando Aprovação ({pendentesAprovacao.length})
                        </CardTitle>
                    </CardHeader>
                    <CardContent>
                        <div className="space-y-3">
                            {pendentesAprovacao.map((item, index) => {
                                const isFerias = 'quantidade_dias' in item && !('tipo' in item);
                                return (
                                    <PendingApprovalCard
                                        key={item.id}
                                        item={item}
                                        isFerias={isFerias}
                                        onApprove={() => {
                                            // Handle approval
                                            const entity = isFerias ? base44.entities.Ferias : base44.entities.Licenca;
                                            entity.update(item.id, { status: isFerias ? 'Aprovada' : 'Aprovada' })
                                                .then(() => {
                                                    queryClient.invalidateQueries(['ferias']);
                                                    queryClient.invalidateQueries(['licencas']);
                                                    toast.success(`${isFerias ? 'Férias' : 'Licença'} aprovada com sucesso!`);
                                                })
                                                .catch(err => toast.error("Erro ao aprovar: " + err.message));
                                        }}
                                        onReject={() => {
                                            const entity = isFerias ? base44.entities.Ferias : base44.entities.Licenca;
                                            entity.update(item.id, { status: 'Rejeitada' })
                                                .then(() => {
                                                    queryClient.invalidateQueries(['ferias']);
                                                    queryClient.invalidateQueries(['licencas']);
                                                    toast.success(`${isFerias ? 'Férias' : 'Licença'} rejeitada.`);
                                                })
                                                .catch(err => toast.error("Erro ao rejeitar: " + err.message));
                                        }}
                                    />
                                );
                            })}
                        </div>
                    </CardContent>
                </Card>
            )}

            {/* Main Content */}
            <div className="grid md:grid-cols-2 gap-6">
                {/* Férias */}
                <Card className="border-0 shadow-lg">
                    <CardHeader>
                        <CardTitle className="flex items-center gap-2" style={{ color: '#07593f' }}>
                            <Umbrella className="w-5 h-5" />
                            Férias
                        </CardTitle>
                    </CardHeader>
                    <CardContent>
                        {loadingFerias ? (
                            <div className="flex justify-center py-8">
                                <div className="animate-spin rounded-full h-8 w-8 border-b-2" style={{ borderColor: '#07593f' }} />
                            </div>
                        ) : ferias.length === 0 ? (
                            <p className="text-center py-8 text-gray-500">Nenhuma férias registrada</p>
                        ) : (
                            <div className="space-y-3 max-h-[500px] overflow-y-auto">
                                {ferias.slice(0, 20).map(f => (
                                    <div key={f.id} className="p-3 rounded-lg border" style={{ borderColor: '#E5E0D8' }}>
                                        <div className="flex items-start justify-between mb-2">
                                            <div>
                                                <p className="font-semibold" style={{ color: '#07593f' }}>{f.colaborador_nome}</p>
                                                <p className="text-sm text-gray-500">
                                                    {f.data_inicio && new Date(f.data_inicio).toLocaleDateString('pt-BR')}
                                                    {f.data_fim && ` até ${new Date(f.data_fim).toLocaleDateString('pt-BR')}`}
                                                </p>
                                            </div>
                                            <Badge style={getStatusBadgeStyle(f.status)}>{f.status}</Badge>
                                        </div>
                                        <div className="flex items-center justify-between">
                                            <Badge variant="outline">{f.quantidade_dias || 0} dias</Badge>
                                            <div className="flex gap-1">
                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    className="h-7 w-7"
                                                    onClick={() => { setItemSelecionado(f); setModalFerias(true); }}
                                                >
                                                    <Edit className="w-3 h-3" />
                                                </Button>
                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    className="h-7 w-7 text-red-600"
                                                    onClick={() => { setConfirmDelete(f); setTipoDelete('ferias'); }}
                                                >
                                                    <Trash2 className="w-3 h-3" />
                                                </Button>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </CardContent>
                </Card>

                {/* Licenças */}
                <Card className="border-0 shadow-lg">
                    <CardHeader>
                        <CardTitle className="flex items-center gap-2 text-orange-600">
                            <FileText className="w-5 h-5" />
                            Licenças
                        </CardTitle>
                    </CardHeader>
                    <CardContent>
                        {loadingLicencas ? (
                            <div className="flex justify-center py-8">
                                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-orange-600" />
                            </div>
                        ) : licencas.length === 0 ? (
                            <p className="text-center py-8 text-gray-500">Nenhuma licença registrada</p>
                        ) : (
                            <div className="space-y-3 max-h-[500px] overflow-y-auto">
                                {licencas.slice(0, 20).map(l => (
                                    <div key={l.id} className="p-3 rounded-lg border" style={{ borderColor: '#E5E0D8' }}>
                                        <div className="flex items-start justify-between mb-2">
                                            <div>
                                                <p className="font-semibold text-orange-600">{l.colaborador_nome}</p>
                                                <p className="text-sm text-gray-500">{l.tipo}</p>
                                                <p className="text-xs text-gray-400">
                                                    {l.data_inicio && new Date(l.data_inicio).toLocaleDateString('pt-BR')}
                                                    {l.data_fim && ` até ${new Date(l.data_fim).toLocaleDateString('pt-BR')}`}
                                                </p>
                                            </div>
                                            <Badge style={getStatusBadgeStyle(l.status)}>{l.status}</Badge>
                                        </div>
                                        <div className="flex items-center justify-between">
                                            {l.quantidade_dias && <Badge variant="outline">{l.quantidade_dias} dias</Badge>}
                                            <div className="flex gap-1">
                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    className="h-7 w-7"
                                                    onClick={() => { setItemSelecionado(l); setModalLicenca(true); }}
                                                >
                                                    <Edit className="w-3 h-3" />
                                                </Button>
                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    className="h-7 w-7 text-red-600"
                                                    onClick={() => { setConfirmDelete(l); setTipoDelete('licenca'); }}
                                                >
                                                    <Trash2 className="w-3 h-3" />
                                                </Button>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </CardContent>
                </Card>
            </div>

            {/* Modals */}
            {modalFerias && (
                <FeriasModal
                    ferias={itemSelecionado}
                    colaboradores={colaboradoresAtivos}
                    onClose={() => { setModalFerias(false); setItemSelecionado(null); }}
                />
            )}

            {modalLicenca && (
                <LicencaModal
                    licenca={itemSelecionado}
                    colaboradores={colaboradoresAtivos}
                    onClose={() => { setModalLicenca(false); setItemSelecionado(null); }}
                />
            )}

            {/* Delete Confirmation */}
            <AlertDialog open={!!confirmDelete} onOpenChange={() => setConfirmDelete(null)}>
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>Confirmar Exclusão</AlertDialogTitle>
                        <AlertDialogDescription>
                            Tem certeza que deseja excluir este registro de {tipoDelete === 'ferias' ? 'férias' : 'licença'}?
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel>Cancelar</AlertDialogCancel>
                        <AlertDialogAction
                            onClick={() => {
                                const entity = tipoDelete === 'ferias' ? base44.entities.Ferias : base44.entities.Licenca;
                                entity.delete(confirmDelete.id)
                                    .then(() => {
                                        queryClient.invalidateQueries([tipoDelete === 'ferias' ? 'ferias' : 'licencas']);
                                        toast.success("Registro excluído com sucesso!");
                                        setConfirmDelete(null);
                                    })
                                    .catch(err => toast.error("Erro ao excluir: " + err.message));
                            }}
                            className="bg-red-600 hover:bg-red-700"
                        >
                            Excluir
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </div>
    );
}

// Pending Approval Card Component
function PendingApprovalCard({ item, isFerias, onApprove, onReject }) {
    return (
        <div className="flex items-center justify-between p-3 rounded-lg bg-amber-50 border border-amber-200">
            <div>
                <p className="font-semibold" style={{ color: '#07593f' }}>{item.colaborador_nome}</p>
                <p className="text-sm text-gray-600">
                    {isFerias ? 'Férias' : `Licença: ${item.tipo}`} • {item.quantidade_dias || 0} dias
                </p>
                <p className="text-xs text-gray-500">
                    {item.data_inicio && new Date(item.data_inicio).toLocaleDateString('pt-BR')}
                    {item.data_fim && ` até ${new Date(item.data_fim).toLocaleDateString('pt-BR')}`}
                </p>
            </div>
            <div className="flex gap-2">
                <Button
                    size="sm"
                    onClick={onApprove}
                    className="bg-green-600 hover:bg-green-700"
                >
                    <Check className="w-4 h-4 mr-1" />
                    Aprovar
                </Button>
                <Button
                    size="sm"
                    variant="outline"
                    onClick={onReject}
                    className="border-red-300 text-red-600 hover:bg-red-50"
                >
                    <X className="w-4 h-4 mr-1" />
                    Rejeitar
                </Button>
            </div>
        </div>
    );
}

// Férias Modal Component
function FeriasModal({ ferias, colaboradores, onClose }) {
    const queryClient = useQueryClient();
    const isEditing = !!ferias;

    const [formData, setFormData] = useState({
        colaborador_id: ferias?.colaborador_id || "",
        colaborador_nome: ferias?.colaborador_nome || "",
        data_inicio: ferias?.data_inicio || "",
        data_fim: ferias?.data_fim || "",
        quantidade_dias: ferias?.quantidade_dias || 30,
        status: ferias?.status || "Solicitada",
        tipo: ferias?.tipo || "Normal",
        observacoes: ferias?.observacoes || "",
    });

    const [saving, setSaving] = useState(false);

    const handleColaboradorChange = (id) => {
        const colab = colaboradores.find(c => c.id === id);
        setFormData(prev => ({
            ...prev,
            colaborador_id: id,
            colaborador_nome: colab?.nome_completo || "",
        }));
    };

    const calcularDias = () => {
        if (formData.data_inicio && formData.data_fim) {
            const inicio = new Date(formData.data_inicio);
            const fim = new Date(formData.data_fim);
            const diff = Math.ceil((fim - inicio) / (1000 * 60 * 60 * 24)) + 1;
            setFormData(prev => ({ ...prev, quantidade_dias: diff > 0 ? diff : 0 }));
        }
    };

    const handleSubmit = async () => {
        if (!formData.colaborador_id || !formData.data_inicio) {
            toast.error("Colaborador e data de início são obrigatórios");
            return;
        }

        setSaving(true);
        try {
            if (isEditing) {
                await base44.entities.Ferias.update(ferias.id, formData);
                toast.success("Férias atualizada com sucesso!");
            } else {
                await base44.entities.Ferias.create(formData);
                toast.success("Férias registrada com sucesso!");
            }
            queryClient.invalidateQueries(['ferias']);
            onClose();
        } catch (error) {
            toast.error("Erro: " + error.message);
        } finally {
            setSaving(false);
        }
    };

    return (
        <Dialog open onOpenChange={onClose}>
            <DialogContent>
                <DialogHeader>
                    <DialogTitle className="flex items-center gap-2" style={{ color: '#07593f' }}>
                        <Umbrella className="w-5 h-5" />
                        {isEditing ? "Editar Férias" : "Nova Solicitação de Férias"}
                    </DialogTitle>
                </DialogHeader>

                <div className="space-y-4 mt-4">
                    <div>
                        <Label>Colaborador *</Label>
                        <Select value={formData.colaborador_id} onValueChange={handleColaboradorChange}>
                            <SelectTrigger>
                                <SelectValue placeholder="Selecione o colaborador" />
                            </SelectTrigger>
                            <SelectContent>
                                {colaboradores.filter(c => c?.id).map(c => (
                                    <SelectItem key={c.id} value={c.id}>{c.nome_completo}</SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <Label>Data Início *</Label>
                            <Input
                                type="date" lang="pt-BR"
                                value={formData.data_inicio}
                                onChange={(e) => setFormData(prev => ({ ...prev, data_inicio: e.target.value }))}
                                onBlur={calcularDias}
                            />
                        </div>
                        <div>
                            <Label>Data Fim</Label>
                            <Input
                                type="date" lang="pt-BR"
                                value={formData.data_fim}
                                onChange={(e) => setFormData(prev => ({ ...prev, data_fim: e.target.value }))}
                                onBlur={calcularDias}
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <Label>Quantidade de Dias</Label>
                            <Input
                                type="number"
                                value={formData.quantidade_dias}
                                onChange={(e) => setFormData(prev => ({ ...prev, quantidade_dias: Number(e.target.value) }))}
                            />
                        </div>
                        <div>
                            <Label>Status</Label>
                            <Select value={formData.status} onValueChange={(v) => setFormData(prev => ({ ...prev, status: v }))}>
                                <SelectTrigger>
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    {STATUS_FERIAS.map(s => (
                                        <SelectItem key={s} value={s}>{s}</SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                    </div>

                    <div>
                        <Label>Observações</Label>
                        <Textarea
                            value={formData.observacoes}
                            onChange={(e) => setFormData(prev => ({ ...prev, observacoes: e.target.value }))}
                            placeholder="Observações adicionais..."
                        />
                    </div>
                </div>

                <div className="flex justify-end gap-3 mt-6">
                    <Button variant="outline" onClick={onClose}>Cancelar</Button>
                    <Button
                        onClick={handleSubmit}
                        disabled={saving}
                        style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
                    >
                        {saving ? "Salvando..." : isEditing ? "Salvar Alterações" : "Registrar Férias"}
                    </Button>
                </div>
            </DialogContent>
        </Dialog>
    );
}

// Licença Modal Component
