                          </p>
                        )}
                        
                        {/* Show changes for UPDATE actions */}
                        {log.action === 'UPDATE' && log.changes && (
                          <div className="mt-3 p-3 rounded-lg" style={{ backgroundColor: '#f0f9ff' }}>
                            <p className="text-xs font-semibold mb-2" style={{ color: '#07593f' }}>
                              Alterações:
                            </p>
                            <div className="space-y-1">
                              {Object.entries(log.changes).map(([field, change]) => (
                                <div key={field} className="text-xs">
                                  <span className="font-semibold">{field}:</span>
                                  {' '}
                                  <span className="line-through text-red-600">
                                    {typeof change.before === 'object' 
                                      ? JSON.stringify(change.before) 
                                      : change.before || '(vazio)'}
                                  </span>
                                  {' → '}
                                  <span className="text-green-600 font-semibold">
                                    {typeof change.after === 'object' 
                                      ? JSON.stringify(change.after) 
                                      : change.after || '(vazio)'}
                                  </span>
                                </div>
                              ))}
                            </div>
                          </div>
                        )}
                      </div>

                      <div className="flex items-center gap-2 text-xs flex-shrink-0" style={{ color: '#8B8B8B' }}>
                        <Clock className="w-3 h-3" />
                        {formatTimestamp(log.timestamp)}
                      </div>
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      <Card className="border-0 shadow-lg">
        <CardHeader>
          <CardTitle className="text-sm">Estatísticas do Log</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid md:grid-cols-4 gap-4 text-center">
            <div>
              <p className="text-2xl font-bold" style={{ color: '#07593f' }}>
                {logs.length}
              </p>
              <p className="text-xs" style={{ color: '#8B8B8B' }}>Total de Ações</p>
            </div>
            <div>
              <p className="text-2xl font-bold text-green-600">
                {logs.filter(l => l.action === 'CREATE').length}
              </p>
              <p className="text-xs" style={{ color: '#8B8B8B' }}>Criações</p>
            </div>
            <div>
              <p className="text-2xl font-bold text-blue-600">
                {logs.filter(l => l.action === 'UPDATE').length}
              </p>
              <p className="text-xs" style={{ color: '#8B8B8B' }}>Atualizações</p>
            </div>
            <div>
              <p className="text-2xl font-bold text-red-600">
                {logs.filter(l => l.action === 'DELETE').length}
              </p>
              <p className="text-xs" style={{ color: '#8B8B8B' }}>Exclusões</p>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState, useMemo } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Loader2, Shield, Search, ChevronDown, ChevronRight, Check, X, Plus, Minus } from "lucide-react";
import { ROLE_RULES, PERMISSION_CATALOG, PERMISSION_CATEGORIES, getUserRoles } from "@/config/permissions";

/**
 * Editor visual de permissões por usuário (sobrepõe o cargo).
 * Suporta múltiplos cargos: calcula base como union de ROLE_RULES dos cargos do usuário.
 * Mantém a API onSave({ inherit, allowed, denied }) inalterada.
 */
export default function PermissionEditorModal({ user, onSave, onClose, isSaving = false }) {
    // Multi-cargo support: getUserRoles retorna array de cargos do usuário
    const roles       = getUserRoles(user);
    const primaryRole = roles[0] || 'Vendedor';

    // Estado inicial das custom_permissions
    const initialCustom = user?.custom_permissions || { inherit: true, allowed: [], denied: [] };

    const [inherit, setInherit] = useState(initialCustom.inherit !== false);
    const [allowed, setAllowed] = useState(initialCustom.allowed || []);
    const [denied,  setDenied]  = useState(initialCustom.denied  || []);
    const [search,             setSearch]             = useState('');
    const [expandedCategories, setExpandedCategories] = useState({});

    // Union of base permissions from all user roles
    const roleBasePerms = useMemo(() => {
        const perms = new Set();
        roles.forEach(role => {
            const rule = ROLE_RULES[role];
            if (!rule) return;
            if (rule.can.includes('*')) {
                PERMISSION_CATALOG.forEach(({ code }) => perms.add(code));
            } else {
                rule.can.forEach(p => perms.add(p));
            }
        });
        return perms;
    }, [roles]);

    // Compute display state for every catalog permission
    const permState = useMemo(() => {
        const states = {};
        PERMISSION_CATALOG.forEach(({ code }) => {
            const fromRole  = roleBasePerms.has(code);
            const inAllowed = allowed.includes(code);
            const inDenied  = denied.includes(code);

            let active = false;
            let source = 'none';

            if (!inherit) {
                active = inAllowed;
                source = inAllowed ? 'custom_allowed' : 'none';
            } else if (inDenied) {
                active = false;
                source = 'custom_denied';
            } else if (inAllowed) {
                active = true;
                source = 'custom_allowed';
            } else if (fromRole) {
                active = true;
                source = 'role';
            }

            states[code] = { active, source, fromRole };
        });
        return states;
    }, [roleBasePerms, inherit, allowed, denied]);

    const togglePerm = (code) => {
        const state = permState[code];
        if (!state) return;

        if (inherit) {
            if (state.fromRole) {
                if (state.source === 'custom_denied') {
                    setDenied(prev => prev.filter(p => p !== code));
                } else {
                    setDenied(prev  => [...prev, code]);
                    setAllowed(prev => prev.filter(p => p !== code));
                }
            } else {
                if (state.source === 'custom_allowed') {
                    setAllowed(prev => prev.filter(p => p !== code));
                } else {
                    setAllowed(prev => [...prev, code]);
                    setDenied(prev  => prev.filter(p => p !== code));
                }
            }
        } else {
            if (allowed.includes(code)) {
                setAllowed(prev => prev.filter(p => p !== code));
            } else {
                setAllowed(prev => [...prev, code]);
            }
        }
    };

    const handleSave = () => {
        onSave({
            inherit,
            allowed: allowed.filter(Boolean),
            denied:  inherit ? denied.filter(Boolean) : [],
        });
    };

    // Group catalog by category with search filter
    const catalogByCategory = useMemo(() => {
        const q = search.toLowerCase().trim();
        const result = {};
        PERMISSION_CATALOG.forEach(item => {
            if (
                q &&
                !item.label.toLowerCase().includes(q) &&
                !item.code.toLowerCase().includes(q) &&
                !item.description.toLowerCase().includes(q)
            ) return;
            if (!result[item.category]) result[item.category] = [];
            result[item.category].push(item);
        });
        return result;
    }, [search]);

    const toggleCategory = (cat) =>
        setExpandedCategories(prev => ({ ...prev, [cat]: !prev[cat] }));

    const isCategoryExpanded = (cat) => expandedCategories[cat] !== false;

    const getPermStyle = (code) => {
        const s = permState[code];
        if (!s || s.source === 'none')   return { bg: 'bg-gray-50', border: 'border-gray-200', opacity: 'opacity-50' };
        if (s.source === 'custom_denied') return { bg: 'bg-red-50',  border: 'border-red-300',  opacity: '' };
        if (s.source === 'custom_allowed') return { bg: 'bg-blue-50', border: 'border-blue-300', opacity: '' };
        if (s.active)                      return { bg: 'bg-green-50', border: 'border-green-300', opacity: '' };
        return { bg: 'bg-gray-50', border: 'border-gray-200', opacity: 'opacity-50' };
    };

    const activeCount = Object.values(permState).filter(s => s.active).length;
    const customCount = allowed.length + denied.length;

    if (!user) return null;

    return (
        <Dialog open onOpenChange={onClose}>
            <DialogContent className="max-w-3xl max-h-[92vh] flex flex-col gap-3">
                <DialogHeader className="flex-shrink-0">
                    <DialogTitle className="flex items-center gap-2">
                        <Shield className="w-5 h-5" style={{ color: '#07593f' }} />
                        Permissões de {user.full_name}
                    </DialogTitle>
                    <DialogDescription>
                        Cargo(s): <strong>{roles.join(', ') || 'Nenhum'}</strong>.
                        Clique nas permissões para personalizar o acesso individual.
                    </DialogDescription>
                </DialogHeader>

                <div className="flex-shrink-0 space-y-3">
                    {/* Legend */}
                    <div className="flex gap-3 text-xs text-gray-600 flex-wrap">
                        <span className="flex items-center gap-1">
                            <span className="w-3 h-3 rounded bg-green-100 border border-green-400 inline-block" />
                            Do cargo
                        </span>
                        <span className="flex items-center gap-1">
                            <span className="w-3 h-3 rounded bg-blue-100 border border-blue-400 inline-block" />
                            Adicionado
                        </span>
                        <span className="flex items-center gap-1">
                            <span className="w-3 h-3 rounded bg-red-100 border border-red-400 inline-block" />
                            Removido
                        </span>
                        <span className="flex items-center gap-1">
                            <span className="w-3 h-3 rounded bg-gray-100 border border-gray-300 inline-block opacity-50" />
                            Sem acesso
                        </span>
                    </div>

                    {/* Inherit toggle */}
                    <div
                        className="flex items-center gap-3 p-3 rounded-lg border"
                        style={{ backgroundColor: inherit ? '#f0fdf4' : '#fef3c7' }}
                    >
                        <Checkbox checked={inherit} onCheckedChange={setInherit} id="inherit-user" />
                        <div>
                            <Label htmlFor="inherit-user" className="cursor-pointer font-medium">
                                Herdar permissões do cargo ({primaryRole})
                            </Label>
                            <p className="text-xs text-gray-500">
                                {inherit
                                    ? 'Customizações adicionam ou removem permissões do cargo base'
                                    : 'Usuário terá APENAS as permissões marcadas manualmente'}
                            </p>
                        </div>
                    </div>

                    {!inherit && (
                        <div className="text-xs text-amber-700 bg-amber-50 border border-amber-200 rounded p-2">
                            Modo manual: apenas permissões marcadas abaixo serão concedidas.
                        </div>
                    )}

                    {/* Search */}
                    <div className="flex items-center gap-3">
                        <div className="flex-1 relative">
                            <Search className="absolute left-2 top-1/2 -translate-y-1/2 w-3 h-3 text-gray-400" />
                            <Input
                                value={search}
                                onChange={e => setSearch(e.target.value)}
                                placeholder="Filtrar permissões..."
                                className="pl-7 h-8 text-sm"
                            />
                        </div>
                        <span className="text-xs text-gray-500 whitespace-nowrap">
                            {activeCount} ativa(s){customCount > 0 ? ` · ${customCount} customiz.` : ''}
                        </span>
                    </div>
                </div>

                {/* Permissions by category */}
                <ScrollArea className="flex-1 min-h-0">
                    <div className="space-y-3 pr-2">
                        {Object.entries(catalogByCategory).map(([category, items]) => {
                            const catConfig   = PERMISSION_CATEGORIES.find(c => c.key === category);
                            const expanded    = isCategoryExpanded(category);
                            const activeInCat = items.filter(i => permState[i.code]?.active).length;

                            return (
                                <div key={category} className="border rounded-lg overflow-hidden">
                                    <button
                                        type="button"
                                        className="w-full flex items-center justify-between p-3 bg-gray-50 hover:bg-gray-100 transition-colors"
                                        onClick={() => toggleCategory(category)}
                                    >
                                        <div className="flex items-center gap-2">
                                            {expanded
                                                ? <ChevronDown  className="w-4 h-4 text-gray-500" />
                                                : <ChevronRight className="w-4 h-4 text-gray-500" />
                                            }
                                            <span
                                                className="font-medium text-sm"
                                                style={{ color: catConfig?.color || '#374151' }}
                                            >
                                                {catConfig?.label || category}
                                            </span>
                                        </div>
                                        <Badge
                                            className="text-xs"
                                            style={{
                                                backgroundColor: `${catConfig?.color || '#6b7280'}20`,
                                                color:           catConfig?.color || '#6b7280',
                                            }}
                                        >
                                            {activeInCat}/{items.length}
                                        </Badge>
                                    </button>

                                    {expanded && (
                                        <div className="p-2 grid sm:grid-cols-2 gap-1">
                                            {items.map(item => {
                                                const style = getPermStyle(item.code);
                                                const state = permState[item.code];
                                                return (
                                                    <button
                                                        key={item.code}
                                                        type="button"
                                                        onClick={() => togglePerm(item.code)}
                                                        className={`w-full text-left p-2 rounded-lg border transition-all hover:scale-[1.01] ${style.bg} ${style.border} ${style.opacity}`}
                                                    >
                                                        <div className="flex items-start gap-2">
                                                            <div className={`w-4 h-4 rounded flex items-center justify-center flex-shrink-0 mt-0.5 ${
                                                                state?.source === 'custom_denied'  ? 'bg-red-200'   :
                                                                state?.active                      ? 'bg-green-200' :
                                                                'bg-gray-200'
                                                            }`}>
                                                                {state?.source === 'custom_denied'              && <X     className="w-3 h-3 text-red-600"   />}
                                                                {state?.active && state?.source !== 'custom_denied' && <Check className="w-3 h-3 text-green-600" />}
                                                            </div>
                                                            <div className="min-w-0 flex-1">
                                                                <p className="text-xs font-medium leading-tight">{item.label}</p>
                                                                <p className="text-xs text-gray-500 leading-tight">{item.description}</p>
                                                            </div>
                                                            {state?.source === 'custom_allowed' && (
                                                                <Badge className="bg-blue-100 text-blue-700 text-xs px-1 flex-shrink-0">
                                                                    <Plus className="w-2 h-2" />
                                                                </Badge>
                                                            )}
                                                            {state?.source === 'custom_denied' && (
                                                                <Badge className="bg-red-100 text-red-700 text-xs px-1 flex-shrink-0">
                                                                    <Minus className="w-2 h-2" />
                                                                </Badge>
                                                            )}
                                                        </div>
                                                    </button>
                                                );
                                            })}
                                        </div>
                                    )}
                                </div>
                            );
                        })}
                        {Object.keys(catalogByCategory).length === 0 && (
                            <p className="text-center text-gray-400 py-8 text-sm">
                                Nenhuma permissão encontrada para este filtro.
                            </p>
                        )}
                    </div>
                </ScrollArea>

                <DialogFooter className="flex-shrink-0">
                    <Button variant="outline" onClick={onClose}>Cancelar</Button>
                    <Button
                        onClick={handleSave}
                        disabled={isSaving}
                        style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
                    >
                        {isSaving && <Loader2 className="w-4 h-4 animate-spin mr-2" />}
                        Salvar Permissões
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

import React, { useState, createElement } from "react";
import { base44 } from "@/api/base44Client";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Users, UserX, Shield, Search, CheckCircle2, Clock,
  Store, Edit, Eye, TrendingUp, Trash2, UserCircle, Loader2, Key
} from "lucide-react";
import {
  Dialog, DialogContent, DialogDescription, DialogFooter,
  DialogHeader, DialogTitle,
} from "@/components/ui/dialog";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import { toast } from "sonner";
import { CARGOS, getCargoConfig } from "@/config/cargos";
import { useLojas } from "@/hooks/useLojas";
import PermissionEditorModal from "./PermissionEditorModal";

export default function UserManagementTab({ users = [], isLoading, currentUser }) {
  const [searchTerm, setSearchTerm] = useState("");
  const [filterRole, setFilterRole] = useState("all");
  const [selectedUser, setSelectedUser] = useState(null);
  const [editModalOpen, setEditModalOpen] = useState(false);
  const [viewingUser, setViewingUser] = useState(null);
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [permissionUser, setPermissionUser] = useState(null);
  const [isPermissionModalOpen, setIsPermissionModalOpen] = useState(false);

  const queryClient = useQueryClient();
  const { data: lojasReal = [] } = useLojas();

  const updateUserMutation = useMutation({
    mutationFn: async ({ userId, updates, telefone, currentData }) => {
      await base44.entities.User.update(userId, updates);

      // Se o cargo é "Montador Externo", criar registro em montadores
      if (updates.cargo === 'Montador Externo') {
        try {
          const montadores = await base44.entities.Montador.list();
          const existe = montadores.find(m => m.usuario_id === userId);
          if (!existe) {
            await base44.entities.Montador.create({
              usuario_id: userId,
              nome: updates.full_name || currentData?.full_name || 'Montador',
              telefone: telefone || '',
              status: 'ativo',
              tipo: 'externo'
            });
          } else if (telefone && telefone !== existe.telefone) {
            await base44.entities.Montador.update(existe.id, { telefone });
          }
        } catch (err) {
          console.error('Erro ao criar/atualizar montador:', err);
        }
      }

      // Log de auditoria
      const changes = {};
      Object.keys(updates).forEach(key => {
        if (updates[key] !== currentData?.[key]) {
          changes[key] = { before: currentData?.[key], after: updates[key] };
        }
      });
      if (Object.keys(changes).length > 0) {
        try {
          await base44.entities.AuditLog.create({
            user_email: currentUser.email,
            user_name: currentUser.full_name,
            user_cargo: currentUser.cargo,
            action: 'UPDATE',
            entity_type: 'User',
            entity_id: userId,
            entity_description: `Usuário ${currentData?.full_name || updates?.full_name || ''}`,
            changes,
            timestamp: new Date().toISOString()
          });
        } catch (e) { void e; }
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['usuarios'] });
      queryClient.invalidateQueries({ queryKey: ['montadores'] });
      setEditModalOpen(false);
      setSelectedUser(null);
      toast.success("Usuário atualizado!");
    },
    onError: (e) => toast.error("Erro: " + e.message)
  });

  const deleteUserMutation = useMutation({
    mutationFn: async (userId) => {
      try {
        const montadores = await base44.entities.Montador.list();
        const montador = montadores.find(m => m.usuario_id === userId);
        if (montador) await base44.entities.Montador.delete(montador.id);
      } catch (e) { void e; }
      await base44.entities.User.delete(userId);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['usuarios'] });
      toast.success("Usuário deletado");
    },
    onError: () => toast.error("Erro ao deletar usuário")
  });

  const updatePermissionsMutation = useMutation({
    mutationFn: async ({ userId, customPermissions }) => {
      await base44.entities.User.update(userId, { custom_permissions: customPermissions });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['usuarios'] });
      setIsPermissionModalOpen(false);
      setPermissionUser(null);
      toast.success("Permissoes atualizadas!");
    },
    onError: (e) => toast.error("Erro: " + e.message)
  });

  const handleEditUser = (user) => {
    setSelectedUser({ ...user, is_vendedor: user.is_vendedor || false, meta_mensal: user.meta_mensal || 0 });
    setEditModalOpen(true);
  };

  const handleApprove = async (user) => {
    await updateUserMutation.mutateAsync({
      userId: user.id,
      updates: {
        cargo: user.cargo || 'Vendedor',
        loja: user.loja || 'Centro',
        status_aprovacao: 'Aprovado',
        data_aprovacao: new Date().toISOString()
      },
      currentData: user
    });
    toast.success(`${user.full_name} aprovado!`);
  };

  const handleReject = (user) => {
    if (confirm(`Rejeitar ${user.full_name}?`)) {
      updateUserMutation.mutate({
        userId: user.id,
        updates: { status_aprovacao: 'Rejeitado' },
        currentData: user
      });
    }
  };

  const handleDeleteUser = (user) => {
    if (user.id === currentUser?.id) {
      toast.error("Você não pode deletar sua própria conta");
      return;
    }
    if (confirm(`⚠️ DELETAR "${user.full_name}" permanentemente?\n\nEsta ação não pode ser desfeita!`)) {
      deleteUserMutation.mutate(user.id);
    }
  };

  const handleSaveEdit = () => {
    if (!selectedUser) return;
    const cargoConfig = getCargoConfig(selectedUser.cargo);
    const updates = {
      full_name: selectedUser.full_name,
      cargo: selectedUser.cargo,
      loja: cargoConfig?.requiresStore ? selectedUser.loja : null,
      status_aprovacao: selectedUser.status_aprovacao,
      is_vendedor: selectedUser.is_vendedor,
      meta_mensal: selectedUser.is_vendedor ? parseFloat(selectedUser.meta_mensal) || 0 : 0
    };
    updateUserMutation.mutate({
      userId: selectedUser.id,
      updates,
      telefone: selectedUser.telefone,
      currentData: users.find(u => u.id === selectedUser.id)
    });
  };

  const filteredUsers = users.filter(user => {
    const matchesSearch = user.full_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      user.email?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesRole = filterRole === "all" || user.cargo === filterRole;
    return matchesSearch && matchesRole;
  });

  const getStatusBadge = (status) => {
    const styles = {
      'Aprovado': { bg: 'bg-green-100', text: 'text-green-800', icon: CheckCircle2 },
      'Pendente': { bg: 'bg-yellow-100', text: 'text-yellow-800', icon: Clock },
      'Rejeitado': { bg: 'bg-red-100', text: 'text-red-800', icon: UserX }
    };
    const s = styles[status] || styles['Pendente'];
    return (
      <Badge className={`${s.bg} ${s.text} hover:${s.bg}`}>
        {createElement(s.icon, { className: "w-3 h-3 mr-1" })}
        {status || 'Pendente'}
      </Badge>
    );
  };

  const getRoleBadge = (cargo) => {
    const config = getCargoConfig(cargo);
    if (!config) return <Badge variant="outline">{cargo || 'Não definido'}</Badge>;
    return (
      <Badge style={{ backgroundColor: `${config.color}15`, color: config.color, border: `1px solid ${config.color}40` }}>
        {createElement(config.icon, { className: "w-3 h-3 mr-1" })}
        {config.label}
      </Badge>
    );
  };

  const selectedCargoConfig = selectedUser ? getCargoConfig(selectedUser.cargo) : null;

  return (
    <div className="space-y-6">
      {/* Stats */}
      <div className="grid grid-cols-3 gap-4">
        <Card className="border-0 shadow-sm">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-500">Total</p>
                <p className="text-2xl font-bold" style={{ color: '#07593f' }}>{users.length}</p>
              </div>
              <Users className="w-8 h-8 text-gray-200" />
            </div>
          </CardContent>
        </Card>
        <Card className="border-0 shadow-sm">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-500">Por Cargo</p>
                <p className="text-2xl font-bold text-blue-600">{new Set(users.map(u => u.cargo)).size}</p>
              </div>
              <Shield className="w-8 h-8 text-blue-100" />
            </div>
          </CardContent>
        </Card>
        <Card className="border-0 shadow-sm">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-500">Vendedores</p>
                <p className="text-2xl font-bold text-green-600">{users.filter(u => u.is_vendedor).length}</p>
              </div>
              <TrendingUp className="w-8 h-8 text-green-100" />
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <Card className="border-0 shadow-lg">
        <CardContent className="p-4">
          <div className="flex gap-4">
            <div className="flex-1 relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
              <Input
                placeholder="Buscar por nome ou email..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-10"
              />
            </div>
            <Select value={filterRole} onValueChange={setFilterRole}>
              <SelectTrigger className="w-40">
                <SelectValue placeholder="Cargo" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Todos Cargos</SelectItem>
                {CARGOS.map(c => (
                  <SelectItem key={c.value} value={c.value}>{c.label}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </CardContent>
      </Card>

      {/* Table */}
      {isLoading ? (
        <div className="flex justify-center py-12">
          <Loader2 className="w-8 h-8 animate-spin text-green-700" />
        </div>
      ) : (
        <Card className="border-0 shadow-lg">
          <CardHeader className="pb-0">
            <CardTitle className="text-lg">Usuários ({filteredUsers.length})</CardTitle>
          </CardHeader>
          <CardContent>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Usuario</TableHead>
                  <TableHead>Cargo</TableHead>
                  <TableHead>Loja</TableHead>
                  <TableHead>Permissoes</TableHead>
                  <TableHead className="text-right">Acoes</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredUsers.map((user) => {
                  const config = getCargoConfig(user.cargo);
                  return (
                    <TableRow key={user.id}>
                      <TableCell>
                        <div className="flex items-center gap-3">
                          <div
                            className="w-10 h-10 rounded-full flex items-center justify-center"
                            style={{ backgroundColor: config?.bgColor || '#f3f4f6' }}
                          >
                            {createElement(config?.icon || UserCircle, {
                              className: "w-5 h-5",
                              style: { color: config?.color || '#6b7280' }
                            })}
                          </div>
                          <div>
                            <p className="font-semibold text-sm">{user.full_name || 'Sem nome'}</p>
                            <p className="text-xs text-gray-500">{user.email}</p>
                          </div>
                        </div>
                      </TableCell>
                      <TableCell>{getRoleBadge(user.cargo)}</TableCell>
                      <TableCell>
                        {user.loja && (
                          <div className="flex items-center gap-1 text-sm text-gray-600">
                            <Store className="w-4 h-4" />
                            {user.loja}
                          </div>
                        )}
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center gap-2">
                          {user.custom_permissions &&
                            (user.custom_permissions.allowed?.length > 0 || user.custom_permissions.denied?.length > 0) ? (
                            <Badge variant="outline" className="bg-blue-50 text-blue-700 text-xs">
                              <Key className="w-3 h-3 mr-1" />
                              Customizadas
                            </Badge>
                          ) : (
                            <Badge variant="outline" className="text-gray-500 text-xs">
                              Do cargo
                            </Badge>
                          )}
                        </div>
                      </TableCell>
                      <TableCell>
                        <div className="flex justify-end gap-1">
                          <Button size="sm" variant="outline" className="h-8" onClick={() => { setViewingUser(user); setIsViewModalOpen(true); }}>
                            <Eye className="w-4 h-4" />
                          </Button>
                          <Button size="sm" variant="outline" className="h-8" onClick={() => handleEditUser(user)}>
                            <Edit className="w-4 h-4" />
                          </Button>
                          <Button
                            size="sm"
                            variant="outline"
                            className="h-8"
                            onClick={() => { setPermissionUser(user); setIsPermissionModalOpen(true); }}
                            title="Editar Permissoes"
                          >
                            <Key className="w-4 h-4" />
                          </Button>
                          {currentUser?.cargo === 'Administrador' && user.id !== currentUser?.id && (
                            <Button size="sm" variant="destructive" className="h-8" onClick={() => handleDeleteUser(user)}>
                              <Trash2 className="w-4 h-4" />
                            </Button>
                          )}
                        </div>
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
            {filteredUsers.length === 0 && (
              <div className="text-center py-12 text-gray-500">
                <Users className="w-12 h-12 mx-auto mb-3 opacity-20" />
                <p>Nenhum usuário encontrado</p>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {/* Edit Modal */}
      <Dialog open={editModalOpen} onOpenChange={setEditModalOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Editar Usuário</DialogTitle>
            <DialogDescription>Altere as informações do usuário</DialogDescription>
          </DialogHeader>

          {selectedUser && (
            <div className="space-y-4 py-4">
              <div>
                <Label>Nome Completo</Label>
                <Input
                  value={selectedUser.full_name || ''}
                  onChange={(e) => setSelectedUser({ ...selectedUser, full_name: e.target.value })}
                />
              </div>

              <div>
                <Label>E-mail</Label>
                <Input value={selectedUser.email || ''} disabled className="bg-gray-50" />
              </div>

              {selectedUser.cargo === 'Montador Externo' && (
                <div>
                  <Label>Telefone</Label>
                  <Input
                    value={selectedUser.telefone || ''}
                    onChange={(e) => setSelectedUser({ ...selectedUser, telefone: e.target.value })}
                    placeholder="(27) 99999-9999"
                  />
                </div>
              )}

              <div>
                <Label>Status</Label>
                <Select
                  value={selectedUser.status_aprovacao}
                  onValueChange={(v) => setSelectedUser({ ...selectedUser, status_aprovacao: v })}
                >
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="Pendente">Pendente</SelectItem>
                    <SelectItem value="Aprovado">Aprovado</SelectItem>
                    <SelectItem value="Rejeitado">Rejeitado</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div>
                <Label>Cargo</Label>
                <Select
                  value={selectedUser.cargo || ''}
                  onValueChange={(v) => setSelectedUser({
                    ...selectedUser,
                    cargo: v,
                    is_vendedor: v === 'Vendedor' ? true : selectedUser.is_vendedor
                  })}
                >
                  <SelectTrigger><SelectValue placeholder="Selecione" /></SelectTrigger>
                  <SelectContent>
                    {CARGOS.map(c => (
                      <SelectItem key={c.value} value={c.value}>{c.label}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              {selectedCargoConfig?.requiresStore && (
                <div className={`${selectedUser.cargo === 'Gerente' ? 'p-3 bg-orange-50 rounded-lg border border-orange-200' : ''}`}>
                  <Label className={selectedUser.cargo === 'Gerente' ? 'text-orange-700 font-semibold' : ''}>
                    {selectedUser.cargo === 'Gerente' ? '⚠️ Loja que o Gerente irá gerenciar' : 'Loja'}
                  </Label>
                  {selectedUser.cargo === 'Gerente' && (
                    <p className="text-xs text-orange-600 mb-2">
                      Este gerente só verá dados da loja selecionada abaixo.
                    </p>
                  )}
                  <Select
                    value={selectedUser.loja || ''}
                    onValueChange={(v) => setSelectedUser({ ...selectedUser, loja: v })}
                  >
                    <SelectTrigger><SelectValue placeholder="Selecione a loja" /></SelectTrigger>
                    <SelectContent>
                      {lojasReal.map(l => (
                        <SelectItem key={l.id} value={l.nome}>{l.nome}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              )}

              {selectedUser.cargo === 'Gerente Geral' && (
                <div className="p-3 bg-green-50 rounded-lg border border-green-200">
                  <p className="text-sm text-green-700 font-medium">
                    ✓ Gerente Geral tem acesso a todas as lojas
                  </p>
                </div>
              )}

              <div className="p-4 rounded-xl bg-blue-50 border-2 border-blue-200">
                <div className="flex items-start gap-3">
                  <Checkbox
                    checked={selectedUser.is_vendedor}
                    onCheckedChange={(v) => setSelectedUser({ ...selectedUser, is_vendedor: v })}
                  />
                  <div>
                    <Label className="cursor-pointer font-semibold text-blue-700">Atua como Vendedor</Label>
                    <p className="text-xs text-gray-500 mt-1">Incluído no cálculo de comissões</p>
                  </div>
                </div>
                {selectedUser.is_vendedor && (
                  <div className="mt-3">
                    <Label>Meta Mensal (R$)</Label>
                    <Input
                      type="number"
                      value={selectedUser.meta_mensal || 0}
                      onChange={(e) => setSelectedUser({ ...selectedUser, meta_mensal: parseFloat(e.target.value) || 0 })}
                    />
                  </div>
                )}
              </div>

              {selectedCargoConfig && (
                <Alert style={{ backgroundColor: selectedCargoConfig.bgColor }}>
                  <Shield className="h-4 w-4" style={{ color: selectedCargoConfig.color }} />
                  <AlertDescription>
                    <strong>Permissões: </strong>
                    {selectedCargoConfig.permissions.join(', ')}
                  </AlertDescription>
                </Alert>
              )}
            </div>
          )}

          <DialogFooter>
            <Button variant="outline" onClick={() => setEditModalOpen(false)}>Cancelar</Button>
            <Button onClick={handleSaveEdit} disabled={updateUserMutation.isPending} className="bg-green-700 hover:bg-green-800">
              {updateUserMutation.isPending ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : null}
              Salvar
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* View Modal */}
      <Dialog open={isViewModalOpen} onOpenChange={setIsViewModalOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Detalhes do Usuário</DialogTitle>
          </DialogHeader>
          {viewingUser && (
            <div className="space-y-4 py-4">
              <div className="flex items-center gap-4">
                <div
                  className="w-16 h-16 rounded-full flex items-center justify-center text-2xl font-bold"
                  style={{ backgroundColor: getCargoConfig(viewingUser.cargo)?.bgColor || '#f3f4f6', color: getCargoConfig(viewingUser.cargo)?.color || '#6b7280' }}
                >
                  {viewingUser.full_name?.charAt(0).toUpperCase() || 'U'}
                </div>
                <div>
                  <h3 className="text-xl font-bold">{viewingUser.full_name}</h3>
                  <p className="text-gray-500">{viewingUser.email}</p>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div><Label>Status</Label><div className="mt-1">{getStatusBadge(viewingUser.status_aprovacao)}</div></div>
                <div><Label>Cargo</Label><div className="mt-1">{getRoleBadge(viewingUser.cargo)}</div></div>
                {viewingUser.loja && <div><Label>Loja</Label><div className="mt-1 flex items-center gap-1"><Store className="w-4 h-4" />{viewingUser.loja}</div></div>}
                <div><Label>Cadastrado em</Label><div className="mt-1 text-sm text-gray-600">{new Date(viewingUser.created_at).toLocaleDateString('pt-BR')}</div></div>
              </div>
              {viewingUser.is_vendedor && (
                <Alert className="bg-blue-50 border-blue-200">
                  <TrendingUp className="w-4 h-4 text-blue-600" />
                  <AlertDescription className="text-blue-800">
                    <strong>Vendedor Ativo</strong> - Meta: R$ {(viewingUser.meta_mensal || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                  </AlertDescription>
                </Alert>
              )}
            </div>
          )}
          <DialogFooter>
            <Button onClick={() => setIsViewModalOpen(false)}>Fechar</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Permission Editor Modal */}
      {isPermissionModalOpen && permissionUser && (
        <PermissionEditorModal
          user={permissionUser}
          onClose={() => {
            setIsPermissionModalOpen(false);
            setPermissionUser(null);
          }}
          onSave={(customPermissions) => {
            updatePermissionsMutation.mutate({
              userId: permissionUser.id,
              customPermissions
            });
          }}
          isSaving={updatePermissionsMutation.isPending}
        />
      )}
    </div>
  );
}

import React from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Edit, Trash2, Users, DollarSign, Truck, Shield, Download } from "lucide-react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { base44 } from "@/api/base44Client";

const CARGO_CATEGORY_BY_NAME = {
  "Administrador": "Admin",
  "Gerente": "Gestão",
  "Gerente Geral": "Gestão",
  "Vendedor": "Vendas",
  "Estoque": "Operacional",
  "Logística": "Operacional",
  "Financeiro": "Gestão",
  "RH": "Gestão",
  "Entregador": "Operacional",
  "Montador": "Operacional",
  "Montador Externo": "Operacional",
};

function inferCategoria(cargo) {
  if (cargo?.categoria) return cargo.categoria;
  return CARGO_CATEGORY_BY_NAME[cargo?.nome] || "Sem Categoria";
}

function getPermissoesList(cargo) {
  if (Array.isArray(cargo?.permissoes)) return cargo.permissoes;
  if (cargo?.permissoes && Array.isArray(cargo.permissoes.can)) return cargo.permissoes.can;
  return [];
}

export default function GerenciamentoCargos({ cargos, onEditar, onImportarPadrao, importandoPadrao = false }) {
  const queryClient = useQueryClient();

  const deletarCargoMutation = useMutation({
    mutationFn: (id) => base44.entities.Cargo.delete(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['cargos'] });
      alert('Cargo removido com sucesso!');
    }
  });

  const confirmarRemocao = (cargo) => {
    if (confirm(`Tem certeza que deseja remover o cargo "${cargo.nome}"?`)) {
      deletarCargoMutation.mutate(cargo.id);
    }
  };

  const cargosComCategoria = cargos.map((cargo) => ({
    ...cargo,
    categoria_render: inferCategoria(cargo),
    permissoes_render: getPermissoesList(cargo),
  }));

  const cargosPorCategoria = {
    'Principal': cargosComCategoria.filter(c => c.categoria_render === 'Principal'),
    'Vendas': cargosComCategoria.filter(c => c.categoria_render === 'Vendas'),
    'Operacional': cargosComCategoria.filter(c => c.categoria_render === 'Operacional'),
    'Gestão': cargosComCategoria.filter(c => c.categoria_render === 'Gestão'),
    'Admin': cargosComCategoria.filter(c => c.categoria_render === 'Admin'),
    'Sem Categoria': cargosComCategoria.filter(c => c.categoria_render === 'Sem Categoria')
  };

  if (cargos.length === 0) {
    return (
      <Card className="p-8 text-center">
        <Shield className="w-16 h-16 mx-auto mb-4 text-gray-400" />
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-2">
          Nenhum cargo criado ainda
        </h3>
        <p className="text-gray-500 dark:text-gray-400">
          Você pode carregar os cargos padrão do sistema ou criar cargos personalizados para sua equipe
        </p>
        <div className="mt-5 flex items-center justify-center gap-2">
          <Button variant="outline" onClick={onImportarPadrao} disabled={importandoPadrao || !onImportarPadrao}>
            <Download className="w-4 h-4 mr-2" />
            {importandoPadrao ? 'Importando...' : 'Inserir Cargos Padrão'}
          </Button>
        </div>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      {Object.entries(cargosPorCategoria).map(([categoria, cargosCategoria]) => (
        cargosCategoria.length > 0 && (
          <div key={categoria}>
            <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-3 flex items-center gap-2">
              {categoria}
              <Badge variant="secondary">{cargosCategoria.length}</Badge>
            </h3>
            <div className="grid gap-3">
              {cargosCategoria.map(cargo => (
                <Card key={cargo.id} className="p-4">
                  <div className="flex items-center gap-4">
                    <div
                      className="w-12 h-12 rounded-lg flex items-center justify-center text-white font-bold text-xl"
                      style={{ backgroundColor: cargo.cor }}
                    >
                      {cargo.nome.charAt(0)}
                    </div>

                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-1">
                        <h4 className="font-bold text-gray-900 dark:text-white">
                          {cargo.nome}
                        </h4>
                        <Badge variant="outline">
                          Nível {cargo.hierarquia ?? 0}
                        </Badge>
                        {cargo.e_vendedor && (
                          <Badge className="bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200">
                            <DollarSign className="w-3 h-3 mr-1" />
                            Comissões
                          </Badge>
                        )}
                        {cargo.e_master_caminhao && (
                          <Badge className="bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200">
                            <Truck className="w-3 h-3 mr-1" />
                            Master
                          </Badge>
                        )}
                      </div>
                      
                      {cargo.descricao && (
                        <p className="text-sm text-gray-600 dark:text-gray-400 mb-2">
                          {cargo.descricao}
                        </p>
                      )}

                      <div className="flex flex-wrap gap-1">
                        {cargo.permissoes_render.slice(0, 5).map((perm, i) => (
                          <Badge key={i} variant="outline" className="text-xs">
                            {perm}
                          </Badge>
                        ))}
                        {cargo.permissoes_render.length > 5 && (
                          <Badge variant="outline" className="text-xs">
                            +{cargo.permissoes_render.length - 5} mais
                          </Badge>
                        )}
                      </div>
                    </div>

                    <div className="flex gap-2">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => onEditar(cargo)}
                      >
                        <Edit className="w-4 h-4" />
                      </Button>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => confirmarRemocao(cargo)}
                        className="text-red-600 hover:text-red-700"
                      >
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </div>
                  </div>
                </Card>
              ))}
            </div>
          </div>
        )
      ))}
    </div>
  );
}

import React from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Edit, Trash2, Crown, Truck } from "lucide-react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { base44 } from "@/lib/supabase";
import { formatarNome } from "@/utils/formatters";

export default function ListaUsuarios({ usuarios, cargos, caminhoes, onEditar }) {
  const queryClient = useQueryClient();

  const deletarUsuarioMutation = useMutation({
    mutationFn: (id) => base44.entities.User.delete(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['usuarios'] });
      alert('Usuário removido com sucesso!');
    },
    onError: (error) => {
      console.error('Erro ao remover usuário:', error);
      alert('Erro ao remover usuário: ' + (error.message || 'Erro desconhecido'));
    }
  });

  const confirmarRemocao = (usuario) => {
    if (confirm(`Tem certeza que deseja remover ${usuario.full_name}?`)) {
      deletarUsuarioMutation.mutate(usuario.id);
    }
  };

  const getCargo = (cargoId) => cargos.find(c => c.id === cargoId);

  return (
    <div className="grid gap-3">
      {usuarios.map(usuario => {
        const cargosUsuario = usuario.cargos?.map(getCargo).filter(Boolean) || [];

        return (
          <Card key={usuario.id} className="p-4 hover:shadow-lg transition-shadow">
            <div className="flex items-center gap-4">
              <Avatar className="w-12 h-12">
                <AvatarImage src={usuario.avatar_url} />
                <AvatarFallback className="bg-gradient-to-br from-green-600 to-green-700 text-white font-bold">
                  {usuario.full_name?.charAt(0).toUpperCase()}
                </AvatarFallback>
              </Avatar>

              <div className="flex-1">
                <div className="flex items-center gap-2 mb-1">
                  <h3 className="font-bold text-gray-900 dark:text-white">
                    {formatarNome(usuario.full_name)}
                  </h3>
                  {usuario.role === 'admin' && (
                    <Crown className="w-4 h-4 text-yellow-500" />
                  )}
                </div>

                <p className="text-sm text-gray-600 dark:text-gray-400 mb-2">
                  {usuario.email}
                </p>

                <div className="flex flex-wrap gap-2">
                  {cargosUsuario.map(cargo => (
                    <Badge
                      key={cargo.id}
                      style={{
                        backgroundColor: cargo.cor + '20',
                        color: cargo.cor,
                        borderColor: cargo.cor
                      }}
                      className="border"
                    >
                      {cargo.nome}
                    </Badge>
                  ))}
                  {usuario.matricula && (
                    <Badge variant="secondary" className="font-mono">
                      🆔 {usuario.matricula}
                    </Badge>
                  )}
                  {usuario.loja && (
                    <Badge variant="outline">
                      🏪 {usuario.loja}
                    </Badge>
                  )}
                  {!usuario.ativo && (
                    <Badge variant="destructive">Inativo</Badge>
                  )}
                </div>
              </div>

              <div className="flex gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => onEditar(usuario)}
                >
                  <Edit className="w-4 h-4" />
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => confirmarRemocao(usuario)}
                  className="text-red-600 hover:text-red-700"
                >
                  <Trash2 className="w-4 h-4" />
                </Button>
              </div>
            </div>
          </Card>
        );
      })}
    </div>
  );
}

import React, { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
