                      }}
                      className={`w-full text-left px-4 py-2.5 flex flex-col gap-1 border-b border-gray-100 dark:border-neutral-800 transition-colors ${isSelected ? 'bg-green-50 dark:bg-green-900/30' : 'hover:bg-gray-50 dark:hover:bg-neutral-800'
                        }`}
                    >
                      {/* Linha principal: Imagem + Nome + Modelo + PreÃ§o */}
                      <div className="flex items-center justify-between w-full gap-3">
                        {/* Imagem do Produto Produto (Cascata) */}
                        <div className="w-10 h-10 shrink-0 border rounded overflow-hidden bg-gray-50 flex items-center justify-center">
                          {produto.fotos?.[0] ? (
                            <img src={produto.fotos[0]} alt={produto.nome} className="w-full h-full object-cover" />
                          ) : (
                            <ImageIcon className="w-5 h-5 text-gray-300" />
                          )}
                        </div>

                        <span
                          className="flex-1 text-sm font-medium text-gray-800 dark:text-white truncate"
                          title={`${produto.nome}${produto.modelo_referencia ? ` - ${produto.modelo_referencia}` : ''}`}
                        >
                          <span className="text-xs text-gray-400 mr-2">#{produto.id}</span>
                          {produto.nome}{produto.modelo_referencia ? ` - ${produto.modelo_referencia}` : ''}
                        </span>
                        <span className="text-sm font-bold text-green-700 dark:text-green-400 ml-2">
                          R$ {produto.preco_venda?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                        </span>
                      </div>

                      {/* Linha de detalhes */}
                      <div className="flex items-start justify-between w-full gap-2">
                        <div className="min-w-0 flex-1">
                          {dimensoes && (
                            <p className="text-[12px] font-semibold text-emerald-800 dark:text-emerald-300 leading-tight truncate">
                              <span className="inline-block mr-1.5 px-1.5 py-0.5 rounded bg-emerald-100 dark:bg-emerald-900/40 text-[10px] font-bold uppercase tracking-wide">
                                Medidas
                              </span>
                              <span className="tracking-wide">{dimensoes}</span>
                            </p>
                          )}
                          <p className="text-[11px] text-gray-500 dark:text-gray-400 leading-none truncate mt-0.5">
                            {detalhesTecnicos}
                          </p>
                        </div>
                        <div className="flex flex-col items-end shrink-0">
                          <div className="flex items-center gap-1">
                            <span className="text-[10px] font-semibold">
                              {bloqueado ? (
                                <span className="text-red-500">Sem estoque</span>
                              ) : semEstoque ? (
                                <span className="text-amber-500">Sob encomenda</span>
                              ) : (
                                <span className={qtd <= 5 ? 'text-orange-500' : 'text-green-600'}>Total: {qtd}un</span>
                              )}
                            </span>
                            {onEditProduto && (
                              <div onClick={(e) => e.stopPropagation()}>
                                <Button
                                  variant="ghost"
                                  size="icon"
                                  className="h-6 w-6 rounded-full hover:bg-blue-100 text-blue-600"
                                  title="Editar Produto"
                                  onClick={() => onEditProduto(produto)}
                                >
                                  <Edit2 className="w-3 h-3" />
                                </Button>
                              </div>
                            )}
                          </div>
                          {renderEstoqueBages(produto)}
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
              {/* Footer with Request Button */}
              <div className="p-2 border-t border-gray-100 dark:border-neutral-800 bg-gray-50 dark:bg-neutral-900">
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => {
                    setIsModalOpen(true);
                  }}
                  className="w-full text-xs text-gray-500 hover:text-green-700 h-8 font-normal"
                >
                  <Plus className="w-3 h-3 mr-2" /> NÃ£o encontrou? Cadastrar item
                </Button>
              </div>
            </>
          )}
        </div>
      )}

      {/* === SELETOR DE VARIANTES (Tecido â†’ Cor) === */}
      {variantesProduto && showResults && (
        <div className="absolute top-full left-0 right-0 z-50 mt-1 bg-white dark:bg-neutral-900 border-2 border-green-600 rounded-lg shadow-2xl overflow-hidden">
          {/* Header do seletor */}
          <div className="bg-green-50 dark:bg-green-900/20 px-4 py-3 border-b border-green-200 dark:border-green-800">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Palette className="w-4 h-4 text-green-700 dark:text-green-400" />
                <span className="text-sm font-semibold text-green-800 dark:text-green-300">
                  {variantesProduto.produto.nome}
                </span>
              </div>
              <Button
                variant="ghost"
                size="sm"
                className="h-6 px-2 text-xs text-gray-500 hover:text-gray-700"
                onClick={resetVarianteSelector}
              >
                âœ• Cancelar
              </Button>
            </div>
            <p className="text-xs text-green-600 dark:text-green-400 mt-1">
              {variantesProduto.variantes.length} variante(s) disponÃ­vel(is) â€” selecione a combinaÃ§Ã£o desejada
            </p>
          </div>

          {loadingVariantes && (
            <div className="p-6 text-center">
              <Loader2 className="w-6 h-6 mx-auto animate-spin text-green-600 mb-2" />
              <p className="text-sm text-gray-500">Carregando variantes...</p>
            </div>
          )}

          {/* Seletor de Tecido */}
          {(mostrarTecidos) && (
            <div className="p-3">
              <p className="text-xs font-semibold text-gray-500 uppercase mb-2">Selecione o Tecido</p>
              <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto">
                {tecidosDisponiveis.map(tecido => (
                  <button
                    key={tecido.id}
                    type="button"
                    onClick={() => handleSelecionarTecido(tecido.id)}
                    className="text-left px-3 py-2 rounded-md border border-gray-200 dark:border-neutral-700 hover:border-green-400 hover:bg-green-50 dark:hover:bg-green-900/20 transition-colors flex items-center justify-between gap-2"
                  >
                    <span className="text-sm font-medium text-gray-700 dark:text-gray-300 truncate">{tecido.nome}</span>
                    <ChevronRight className="w-3 h-3 text-gray-400 shrink-0" />
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Seletor de Cor (apÃ³s selecionar tecido OU se nÃ£o hÃ¡ tecidos) */}
          {(mostrarCores || mostrarApenasCores) && (
            <div className="p-3">
              {tecidoSelecionado && (
                <div className="flex items-center gap-2 mb-2">
                  <Badge variant="secondary" className="text-xs">
                    Tecido: {tecidosDisponiveis.find(t => t.id === tecidoSelecionado)?.nome}
                  </Badge>
                  <button
                    type="button"
                    className="text-xs text-blue-600 hover:underline"
                    onClick={() => { setTecidoSelecionado(null); setCorSelecionada(null); }}
                  >
                    alterar
                  </button>
                </div>
              )}
              <p className="text-xs font-semibold text-gray-500 uppercase mb-2">Selecione a Cor</p>
              <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto">
                {coresDisponiveis.map(cor => (
                  <button
                    key={cor.id}
                    type="button"
                    onClick={() => handleSelecionarCor(cor.id)}
                    className="text-left px-3 py-2 rounded-md border border-gray-200 dark:border-neutral-700 hover:border-green-400 hover:bg-green-50 dark:hover:bg-green-900/20 transition-colors flex items-center gap-2"
                  >
                    {cor.hex && (
                      <div
                        className="w-4 h-4 rounded-full border border-gray-300 shrink-0"
                        style={{ backgroundColor: cor.hex }}
                      />
                    )}
                    <span className="text-sm font-medium text-gray-700 dark:text-gray-300 truncate">{cor.nome}</span>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      <ProdutoCadastroCompleto
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        produto={null}
        isLoading={isSavingProduto}
        onSave={async (data) => {
          if (isSavingProduto) return;

          setIsSavingProduto(true);
          try {
            const novoProduto = await base44.entities.Produto.create({
              ...data,
              requer_atencao: true,
              motivo_atencao: data?.motivo_atencao || "Cadastro iniciado no PDV por vendedor",
            });
            await queryClient.invalidateQueries({ queryKey: ['produtos'] });
            setIsModalOpen(false);

            if (novoProduto?.id) {
              handleSelectProduto(novoProduto);
              toast.success("Produto cadastrado e adicionado ao carrinho.");
              return;
            }

            toast.success("Produto cadastrado! Voce ja pode busca-lo na lista.");
          } catch (error) {
            toast.error(`Erro ao cadastrar produto: ${error.message}`);
          } finally {
            setIsSavingProduto(false);
          }
        }}
      />
    </div>
  );
}

import React, { useState, useMemo, useEffect } from 'react';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import {
    Loader2, AlertTriangle, FileCheck, Download,
    ShieldCheck, ShieldAlert, CheckCircle2, XCircle,
    RefreshCw, FileDown, ArrowRight, Settings, Package, User
} from 'lucide-react';
import { toast } from 'sonner';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/hooks/useAuth';
import { useNavigate } from 'react-router-dom';
import { validarNFe } from '@/services/NfeValidator';
import { NfeGenerator } from '@/services/NfeGenerator';

// Roles that can emit NF-e directly without a token
const ROLES_EMISSAO_DIRETA = ['Administrador', 'Gerente', 'Gerente Geral'];

// Empresas base (same as before for Sebrae XML export)
const EMPRESAS_BASE = [
    { cnpj: "49129137000130", nome: "Atacadao Outlet", cnpjFormatado: "49.129.137/0001-30" },
    { cnpj: "04842257000141", nome: "Moveis Pedro II", cnpjFormatado: "04.842.257/0001-41" },
    { cnpj: "42316614000127", nome: "Massi Home Design", cnpjFormatado: "42.316.614/0001-27" },
    { cnpj: "53795479000166", nome: "Alta Performance Decoracoes", cnpjFormatado: "53.795.479/0001-66" },
];

export default function EmitirNFeModal({ isOpen, onClose, venda, cliente }) {
    const { user, can } = useAuth();
    const navigate = useNavigate();
    const [loading, setLoading] = useState(false);
    const [ambiente, setAmbiente] = useState('homologacao');
    const [tokenGerencial, setTokenGerencial] = useState('');
    const [nfeStatus, setNfeStatus] = useState(null); // { status, ref, message }
    const [validationErrors, setValidationErrors] = useState(null);
    const [showValidationDetails, setShowValidationDetails] = useState(false);
    const [consultando, setConsultando] = useState(false);

    // Reset state when modal opens/closes
    useEffect(() => {
        if (isOpen) {
            setTokenGerencial('');
            setNfeStatus(null);
            setValidationErrors(null);
            setShowValidationDetails(false);
            setItensAtualizados(venda?.itens || []);

            // If sale already has NF-e, load its status
            if (venda?.nfe_ref && venda?.nfe_status) {
                setNfeStatus({
                    status: venda.nfe_status,
                    ref: venda.nfe_ref,
                    message: venda.nfe_mensagem || ''
                });
            }
        }
    }, [isOpen, venda]);

    const [itensAtualizados, setItensAtualizados] = useState([]);
    const [clienteAtualizado, setClienteAtualizado] = useState(null);

    // Fetch fresh product data when modal opens
    useEffect(() => {
        const fetchFreshProductData = async () => {
            if (!isOpen || !venda?.itens?.length) return;

            try {
                const produtoIds = venda.itens.map(i => i.produto_id).filter(Boolean);
                if (produtoIds.length === 0) return;

                const { data: produtos, error } = await supabase
                    .from('produtos')
                    .select('id, nome, ncm, cfop, cest, origem_mercadoria, preco_venda, unidade, estoque_minimo, estoque_ideal')
                    .in('id', produtoIds);

                if (error) throw error;

                if (produtos) {
                    const mappedItens = venda.itens.map(item => {
                        const prod = produtos.find(p => p.id === item.produto_id);
                        if (prod) {
                            // Prioritize product catalog data over stale sale snapshot
                            return {
                                ...item,
                                nome: prod.nome || item.nome, // Update description if changed
                                produto_nome: prod.nome || item.produto_nome,
                                ncm: prod.ncm || item.ncm,
                                cfop: prod.cfop || item.cfop,
                                cest: prod.cest || item.cest,
                                origem_mercadoria: prod.origem_mercadoria ?? item.origem_mercadoria,
                                preco: prod.preco_venda || item.preco, // Update price
                                preco_venda: prod.preco_venda || item.preco_venda,
                                valor_unitario: prod.preco_venda || item.valor_unitario,
                                unidade: prod.unidade || item.unidade || 'UN',
                                // Keep quantity as is from the sale
                            };
                        }
                        return item;
                    });
                    setItensAtualizados(mappedItens);
                }
            } catch (err) {
                toast.error("Erro ao atualizar dados dos produtos para a NF-e. Alguns campos podem estar desatualizados.");
            }
        };

        fetchFreshProductData();
    }, [isOpen, venda]);

    // Fetch fresh client data when modal opens
    useEffect(() => {
        const fetchFreshClientData = async () => {
            if (!isOpen || !venda?.cliente_id) return;

            try {
                const { data: freshCliente, error } = await supabase
                    .from('clientes')
                    .select('*')
                    .eq('id', venda.cliente_id)
                    .single();

                if (error) throw error;
                if (freshCliente) {
                    setClienteAtualizado(freshCliente);
                }
            } catch (err) {
                toast.error("Erro ao carregar dados atualizados do cliente.");
            }
        };

        fetchFreshClientData();
    }, [isOpen, venda?.cliente_id]);

    // Update clienteAtualizado when prop changes as a fallback
    useEffect(() => {
        if (cliente) setClienteAtualizado(cliente);
    }, [cliente]);

    // Auto-trigger validation when data changes
    useEffect(() => {
        if (isOpen && (clienteAtualizado || cliente) && itensAtualizados.length > 0) {
            runValidation();
        }
    }, [isOpen, clienteAtualizado, cliente, itensAtualizados]);

    if (!venda || !cliente) return null;

    const cargo = user?.cargo || '';
    const podeEmitirDireto = ROLES_EMISSAO_DIRETA.includes(cargo) || cargo === 'Administrador';
    const precisaToken = !podeEmitirDireto;
    const jaEmitida = venda.nfe_emitida && venda.nfe_status === 'autorizado';

    // ─── Pre-flight Validation ───────────────────────────────────────────────
    const runValidation = () => {
        const emitente = getDadosEmitente();
        const result = validarNFe({
            emitente,
            cliente: clienteAtualizado || cliente,
            itens: itensAtualizados
        });
        setValidationErrors(result.valid ? null : result);
        return result.valid;
    };

    const getDadosEmitente = () => {
        const cnpjPadrao = localStorage.getItem("nfe_empresa_padrao");
        const dadosFiscaisRaw = localStorage.getItem("nfe_empresas_fiscais");
        const serie = localStorage.getItem("nfe_serie") || "1";
        const dadosFiscais = dadosFiscaisRaw ? JSON.parse(dadosFiscaisRaw) : {};

        const empresaBase = EMPRESAS_BASE.find(e => e.cnpj === cnpjPadrao) || EMPRESAS_BASE[0];
        const dadosComplementares = dadosFiscais[empresaBase.cnpj] || {};

        return {
            nome: empresaBase.nome,
            razao_social: empresaBase.nome,
            cnpj: empresaBase.cnpj,
            inscricao_estadual: dadosComplementares.ie || "",
            ie: dadosComplementares.ie || "",
            crt: dadosComplementares.regimeTributario || 1,
            regime_tributario: dadosComplementares.regimeTributario || 1,
            regimeTributario: dadosComplementares.regimeTributario || 1,
            logradouro: dadosComplementares.logradouro,
            numero: dadosComplementares.numero,
            bairro: dadosComplementares.bairro,
            cidade: dadosComplementares.municipio,
            municipio: dadosComplementares.municipio,
            uf: dadosComplementares.uf,
            cep: dadosComplementares.cep,
            serie: serie,
            endereco_fiscal: {
                logradouro: dadosComplementares.logradouro,
                numero: dadosComplementares.numero,
                bairro: dadosComplementares.bairro,
                municipio_codigo: dadosComplementares.codigoMunicipio || '3550308',
                municipio_nome: dadosComplementares.municipio,
                uf: dadosComplementares.uf,
                cep: dadosComplementares.cep
            },
            codigoMunicipio: dadosComplementares.codigoMunicipio
        };
    };

    // ─── Sebrae XML Download ─────────────────────────────────────────────────
    const handleBaixarXmlSebrae = () => {
        try {
            setLoading(true);
            if (!runValidation()) {
                setShowValidationDetails(true);
                setLoading(false);
                toast.error('Corrija os erros de validação antes de gerar o XML.');
                return;
            }

            const emitente = getDadosEmitente();
            const xml = NfeGenerator.generateXML(
                { ...venda, itens: itensAtualizados },
                emitente,
                cliente
            );

            const blob = new Blob([xml], { type: "application/xml" });
            const url = URL.createObjectURL(blob);
            const a = document.createElement("a");
            a.href = url;
            a.download = `NFe_${venda.numero_pedido}_${emitente.razao_social.replace(/\s+/g, '_')}.xml`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);

            toast.success("XML gerado! Importe no emissor do Sebrae.");
            onClose();
        } catch (error) {
            console.error(error);
            toast.error("Erro ao gerar XML: " + error.message);
        } finally {
            setLoading(false);
        }
    };

    // ─── API Emission (Nuvem Fiscal) ────────────────────────────────────────────
    const handleEmitirAPI = async () => {
        try {
            setLoading(true);
            setValidationErrors(null);

            // Pre-flight validation
            if (!runValidation()) {
                setShowValidationDetails(true);
                setLoading(false);
                return;
            }

            // Check token requirement
            if (precisaToken && !tokenGerencial.trim()) {
                toast.error('Você precisa de um token gerencial para emitir NF-e. Solicite ao seu gerente.');
                setLoading(false);
                return;
            }

            // Fetch issuer data using the unified helper
            const emitenteDados = getDadosEmitente();

            // Critical check: If we don't even have a CNPJ, we can't emit
            if (!emitenteDados.cnpj || !emitenteDados.ie) {
                toast.error('Dados da empresa incompletos. Por favor, configure a empresa em Configurações > NF-e.');
                setLoading(false);
                return;
            }

            const { data, error } = await supabase.functions.invoke('emitir-nfe', {
                body: {
                    venda_id: venda.id,
                    ambiente,
                    user_id: user.id,
                    token_gerencial: precisaToken ? tokenGerencial.trim() : undefined,
                    itens_atualizados: itensAtualizados,
                    emitente_dados: emitenteDados
                }
            });

            if (error) {
                // Try to extract from context body
                let msg = error.message || 'Erro de conexão';
                if (error.context && typeof error.context.json === 'function') {
                    try {
                        const body = await error.context.json();
                        if (body?.error) msg = body.error;
                        if (body?.code === 'VALIDATION_ERROR' && body?.camposFaltantes) {
                            setValidationErrors({
                                valid: false,
                                errors: body.camposFaltantes,
                                errorsBySection: body.porSecao,
                                totalErrors: body.totalErros
                            });
                            setShowValidationDetails(true);
                            toast.error(`Validação falhou: ${body.totalErros} campo(s) faltante(s)`);
                            return;
                        }
                        if (body?.code === 'ROLE_BLOCKED') {
                            toast.error(msg);
                            return;
                        }
                        if (body?.code === 'INVALID_TOKEN' || body?.code === 'TOKEN_EXPIRED' || body?.code === 'TOKEN_EXHAUSTED') {
                            toast.error(msg);
                            setTokenGerencial('');
                            return;
                        }
                    } catch (e) { /* ignore JSON parse error */ }
                }
                throw new Error(msg);
            }

            if (!data?.success) {
                if (data?.code === 'VALIDATION_ERROR' && data?.camposFaltantes) {
                    setValidationErrors({
                        valid: false,
                        errors: data.camposFaltantes,
                        errorsBySection: data.porSecao,
                        totalErrors: data.totalErros
                    });
                    setShowValidationDetails(true);
                    toast.error(`Validação falhou: ${data.totalErros} campo(s) faltante(s)`);
                    return;
                }
                throw new Error(data?.error || 'Erro desconhecido ao emitir NFe');
            }

            setNfeStatus({
                status: data.status,
                ref: data.ref,
                message: 'NF-e enviada para processamento!'
            });
            toast.success(`NF-e enviada! Status: ${data.status}`);

        } catch (error) {
            console.error('Erro ao emitir NFe:', error);
            toast.error('Falha ao emitir NFe: ' + error.message);
        } finally {
            setLoading(false);
        }
    };

    // ─── Consultar Status ────────────────────────────────────────────────────
    const handleConsultarStatus = async () => {
        const ref = nfeStatus?.ref || venda.nfe_ref;
        if (!ref) return;

        try {
            setConsultando(true);
            const { data, error } = await supabase.functions.invoke('consultar-nfe', {
                body: {
                    nfe_ref: ref,
                    ambiente,
                    organization_id: venda.organization_id
                }
            });

            if (error) throw error;
            if (!data?.success) throw new Error(data?.error || 'Erro ao consultar');

            setNfeStatus({
                status: data.status,
                ref,
                message: data.motivo_status || data.status,
                chave: data.chave,
                numero: data.numero,
                danfeUrl: data.caminho_danfe,
                xmlUrl: data.caminho_xml,
                protocolo: data.protocolo
            });
            toast.success(`Status: ${data.status}`);
        } catch (error) {
            console.error('Erro ao consultar:', error);
            toast.error('Erro ao consultar status: ' + error.message);
        } finally {
            setConsultando(false);
        }
    };

    // ─── Status Badge ────────────────────────────────────────────────────────
    const getStatusBadge = (status) => {
        const s = (status || '').toLowerCase();
        if (s === 'autorizado' || s === 'autorizada') return <Badge className="bg-green-600 text-white"><CheckCircle2 className="w-3 h-3 mr-1" /> Autorizada</Badge>;
        if (s === 'processando_autorizacao' || s === 'processando') return <Badge className="bg-yellow-500 text-white"><Loader2 className="w-3 h-3 mr-1 animate-spin" /> Processando</Badge>;
        if (s === 'cancelado' || s === 'cancelada') return <Badge className="bg-red-600 text-white"><XCircle className="w-3 h-3 mr-1" /> Cancelada</Badge>;
        if (s === 'erro_autorizacao' || s === 'rejeitada') return <Badge className="bg-red-500 text-white"><XCircle className="w-3 h-3 mr-1" /> Rejeitada</Badge>;
        return <Badge variant="outline">{status}</Badge>;
    };

    return (
        <Dialog open={isOpen} onOpenChange={onClose}>
            <DialogContent className="sm:max-w-lg max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle className="flex items-center gap-2">
                        <FileCheck className="w-5 h-5 text-green-600" />
                        Emitir Nota Fiscal (NF-e)
                    </DialogTitle>
                    <DialogDescription>
                        Pedido #{venda.numero_pedido} - {cliente.nome_completo || cliente.nome || cliente.razao_social}
                    </DialogDescription>
                </DialogHeader>

                <div className="grid gap-4 py-2">

                    {/* ─── Already Emitted Status ─────────────────────────────── */}
                    {nfeStatus && (
                        <div className="bg-gray-50 border rounded-lg p-4 space-y-3">
                            <div className="flex items-center justify-between">
                                <span className="text-sm font-semibold text-gray-700">Status da NF-e</span>
                                {getStatusBadge(nfeStatus.status)}
                            </div>

                            {nfeStatus.chave && (
                                <div className="text-xs">
                                    <span className="text-gray-500">Chave:</span>
                                    <span className="ml-1 font-mono text-gray-700 break-all">{nfeStatus.chave}</span>
                                </div>
                            )}
                            {nfeStatus.numero && (
                                <div className="text-xs">
                                    <span className="text-gray-500">Número:</span>
                                    <span className="ml-1 font-semibold">{nfeStatus.numero}</span>
                                </div>
                            )}
                            {nfeStatus.protocolo && (
                                <div className="text-xs">
                                    <span className="text-gray-500">Protocolo:</span>
                                    <span className="ml-1 font-mono">{nfeStatus.protocolo}</span>
                                </div>
                            )}

                            <div className="flex gap-2">
                                <Button size="sm" variant="outline" onClick={handleConsultarStatus} disabled={consultando}>
                                    <RefreshCw className={`w-3 h-3 mr-1 ${consultando ? 'animate-spin' : ''}`} />
                                    Atualizar
                                </Button>
                                {nfeStatus.danfeUrl && (
                                    <Button size="sm" variant="outline" asChild>
                                        <a href={nfeStatus.danfeUrl} target="_blank" rel="noopener noreferrer">
                                            <FileDown className="w-3 h-3 mr-1" /> DANFE (PDF)
                                        </a>
                                    </Button>
                                )}
                                {nfeStatus.xmlUrl && (
                                    <Button size="sm" variant="outline" asChild>
                                        <a href={nfeStatus.xmlUrl} target="_blank" rel="noopener noreferrer">
                                            <Download className="w-3 h-3 mr-1" /> XML
                                        </a>
                                    </Button>
                                )}
                            </div>
                        </div>
                    )}

                    {/* ─── Role Gate ──────────────────────────────────────────── */}
                    {precisaToken && !jaEmitida && (
                        <div className="bg-amber-50 border border-amber-200 rounded-lg p-4 space-y-3">
                            <div className="flex items-start gap-3">
                                <ShieldAlert className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" />
                                <div className="text-sm">
                                    <p className="font-semibold text-amber-800">Token Gerencial Necessário</p>
                                    <p className="text-amber-700 mt-1">
                                        Vendedores precisam de autorização do gerente para emitir NF-e.
                                        Solicite um token ao seu gerente.
                                    </p>
                                </div>
                            </div>
                            <div className="flex gap-2">
                                <Input
                                    type="text"
                                    value={tokenGerencial}
                                    onChange={(e) => setTokenGerencial(e.target.value.toUpperCase())}
                                    placeholder="Código do token (ex: A3B2C1)"
                                    maxLength={10}
                                    className="font-mono tracking-wider uppercase text-center"
                                />
                            </div>
                        </div>
                    )}

                    {podeEmitirDireto && !jaEmitida && (
                        <div className="bg-green-50 border border-green-200 rounded-lg p-3 flex items-center gap-3 text-sm text-green-800">
                            <ShieldCheck className="w-5 h-5 text-green-600 shrink-0" />
                            <div>
                                <p className="font-semibold">Emissão autorizada</p>
                                <p className="text-green-700 text-xs">Cargo: {cargo}</p>
                            </div>
                        </div>
                    )}

                    {/* ─── Validation Errors ──────────────────────────────────── */}
                    {validationErrors && (
                        <div className="bg-red-50 border border-red-200 rounded-xl p-4 space-y-3">
                            <div className="flex items-center gap-2">
                                <AlertTriangle className="w-4 h-4 text-red-600 shrink-0" />
                                <span className="text-sm font-semibold text-red-800">
                                    {validationErrors.totalErrors} campo(s) precisam ser preenchidos
                                </span>
                            </div>

                            {validationErrors.errorsBySection && Object.entries(validationErrors.errorsBySection).map(([secao, erros]) => (
                                <div key={secao} className="bg-white rounded-lg border border-red-200 overflow-hidden">
                                    {/* Section header */}
                                    <div className="flex items-center justify-between px-3 py-2 bg-red-100">
                                        <div className="flex items-center gap-2">
                                            {secao === 'Emitente' ? (
                                                <Settings className="w-3.5 h-3.5 text-red-700" />
                                            ) : secao === 'Cliente' ? (
                                                <User className="w-3.5 h-3.5 text-red-700" />
                                            ) : (
                                                <Package className="w-3.5 h-3.5 text-red-700" />
                                            )}
                                            <span className="text-xs font-bold text-red-800 uppercase tracking-wide">{secao}</span>
                                        </div>
                                        {secao === 'Emitente' && (
                                            <button
                                                onClick={() => {
                                                    localStorage.setItem('nfe_highlight_emitente', '1');
                                                    onClose();
                                                    navigate('/admin/Configuracoes?tab=nfe');
                                                }}
                                                className="flex items-center gap-1 text-xs font-semibold text-red-700 hover:text-red-900 underline"
                                            >
                                                Corrigir nas Configurações <ArrowRight className="w-3 h-3" />
                                            </button>
                                        )}
                                    </div>
                                    {/* Error list */}
                                    <ul className="divide-y divide-red-100">
                                        {erros.map((erro, i) => {
                                            // Extract product_id from item errors if available
                                            // Tenta extrair o índice do item (suporta itens[0] ou itens.0)
                                            const itemMatch = erro.campo?.match(/itens(?:\[|\.)(\d+)(?:\]|\.)?/);
                                            const itemIndex = itemMatch ? parseInt(itemMatch[1]) : null;
                                            const itemObj = (itemIndex !== null && venda?.itens) ? venda.itens[itemIndex] : null;
                                            const produtoId = itemObj?.produto_id; // Sempre usar produto_id para o catálogo

                                            return (
                                                <li key={i} className="flex items-center justify-between px-3 py-2 gap-2">
                                                    <div className="flex items-start gap-1.5">
                                                        <XCircle className="w-3.5 h-3.5 text-red-500 shrink-0 mt-0.5" />
                                                        <span className="text-xs text-red-700">{erro.mensagem}</span>
                                                    </div>
                                                    {produtoId && (
                                                        <button
                                                            onClick={() => {
                                                                // Extrair nome do campo para foco (ex: "ncm", "cest")
                                                                const fieldMatch = erro.campo?.split('.').pop();
                                                                const focusParam = fieldMatch ? `&focus=${fieldMatch}` : '';

                                                                // URL de retorno para reabrir este modal
                                                                const returnUrl = encodeURIComponent(`/admin/Vendas?emitirNfe=${venda.id}`);

                                                                onClose();
                                                                navigate(`/admin/Produtos?highlight=${produtoId}${focusParam}&returnUrl=${returnUrl}`);
                                                            }}
                                                            className="flex items-center gap-1 text-xs font-semibold text-red-700 hover:text-red-900 underline whitespace-nowrap shrink-0"
                                                        >
                                                            Editar <ArrowRight className="w-3 h-3" />
                                                        </button>
                                                    )}
                                                    {secao === 'Cliente' && venda?.cliente_id && (
                                                        <button
                                                            onClick={() => {
                                                                const returnUrl = encodeURIComponent(`/admin/Vendas?emitirNfe=${venda.id}`);
                                                                onClose();
                                                                navigate(`/admin/Clientes?highlight=${venda.cliente_id}&returnUrl=${returnUrl}`);
                                                            }}
                                                            className="flex items-center gap-1 text-xs font-semibold text-red-700 hover:text-red-900 underline whitespace-nowrap shrink-0"
                                                        >
                                                            Editar <ArrowRight className="w-3 h-3" />
                                                        </button>
                                                    )}
                                                </li>
                                            );
                                        })}
                                    </ul>
                                </div>
                            ))}
                        </div>
                    )}

                    {/* ─── Emission Options ───────────────────────────────────── */}
                    {!jaEmitida && !nfeStatus && (
                        <>
                            <div className="space-y-2">
                                <Label>Opções de Emissão</Label>
                                <div className="grid grid-cols-2 gap-3">
                                    <Button
                                        variant="outline"
                                        className="h-auto py-4 flex flex-col gap-2 items-center hover:bg-blue-50 border-dashed border-2"
                                        onClick={handleBaixarXmlSebrae}
                                        disabled={loading}
                                    >
                                        <Download className="w-6 h-6 text-blue-600" />
                                        <span className="font-semibold text-blue-700">Baixar XML</span>
                                        <span className="text-xs text-center text-gray-500 font-normal">Para Emissor Sebrae</span>
                                    </Button>

                                    <Button
                                        variant="outline"
                                        className="h-auto py-4 flex flex-col gap-2 items-center hover:bg-green-50 border-dashed border-2"
                                        onClick={handleEmitirAPI}
                                        disabled={loading || (precisaToken && !tokenGerencial.trim())}
                                    >
                                        {loading ? (
                                            <Loader2 className="w-6 h-6 text-green-600 animate-spin" />
                                        ) : (
                                            <FileCheck className="w-6 h-6 text-green-600" />
                                        )}
                                        <span className="font-semibold text-green-700">Via API (Auto)</span>
                                        <span className="text-xs text-center text-gray-500 font-normal">Nuvem Fiscal</span>
                                    </Button>
                                </div>
                            </div>

                            <div className="space-y-2 pt-2 border-t mt-2">
                                <Label className="text-xs text-gray-500">Ambiente (Apenas API)</Label>
                                <Select value={ambiente} onValueChange={setAmbiente}>
                                    <SelectTrigger className="h-8 text-xs">
                                        <SelectValue />
                                    </SelectTrigger>
                                    <SelectContent>
                                        <SelectItem value="homologacao">Homologação (Teste)</SelectItem>
                                        <SelectItem value="producao">Produção (Validade Jurídica)</SelectItem>
                                    </SelectContent>
                                </Select>
                            </div>
                        </>
                    )}

                    {/* ─── Re-emit or Consult for already emitted ─────────────── */}
                    {jaEmitida && (
                        <div className="text-center text-sm text-gray-500 py-4">
                            Esta venda já possui uma NF-e autorizada.
                        </div>
                    )}
                </div>

                <DialogFooter>
                    <Button variant="ghost" onClick={onClose} disabled={loading}>
                        Fechar
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

import { useEffect, useMemo, useState } from 'react';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { AlertTriangle, CheckCircle2, Loader2, ShieldCheck, ShieldX } from 'lucide-react';
import { toast } from 'sonner';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/hooks/useAuth';

const TIPOS_EVENTO = {
  cancelamento: 'Cancelamento',
  carta_correcao: 'Carta de Correcao (CC-e)',
  inutilizacao: 'Inutilizacao de Numeracao',
};

function statusBadge(status) {
  const normalized = (status || '').toLowerCase();
  if (normalized === 'pendente_aprovacao') return <Badge className="bg-yellow-500 text-white">Pendente aprovacao</Badge>;
  if (normalized === 'aprovado') return <Badge className="bg-blue-600 text-white">Aprovado</Badge>;
  if (normalized === 'reprovado') return <Badge className="bg-red-600 text-white">Reprovado</Badge>;
  if (normalized === 'executando') return <Badge className="bg-orange-500 text-white">Executando</Badge>;
  if (normalized === 'executado') return <Badge className="bg-green-600 text-white">Executado</Badge>;
  if (normalized === 'erro_execucao') return <Badge className="bg-red-700 text-white">Erro execucao</Badge>;
  return <Badge variant="outline">{status || 'Sem status'}</Badge>;
}

export default function NfeEventosModal({ isOpen, onClose, venda, nfeRef, ambiente = 'homologacao', onUpdated }) {
  const { user, can } = useAuth();
  const [loading, setLoading] = useState(false);
  const [solicitacoes, setSolicitacoes] = useState([]);
  const [tipoEvento, setTipoEvento] = useState('cancelamento');
  const [justificativa, setJustificativa] = useState('');
  const [descricaoCorrecao, setDescricaoCorrecao] = useState('');
  const [motivoReprovacao, setMotivoReprovacao] = useState('');
  const [inutilizacao, setInutilizacao] = useState({
    cnpj: '',
    ano: new Date().getFullYear() % 100,
    serie: 1,
    numero_inicial: '',
    numero_final: '',
    justificativa: '',
  });
  const [diasDesdeAutorizacao, setDiasDesdeAutorizacao] = useState(null);

  const permsByTipo = {
    cancelamento: {
      solicitar: can('solicitar_cancelamento_nfe') || can('solicitar_nfe'),
      aprovar: can('aprovar_cancelamento_nfe') || can('aprovar_nfe') || can('cancelar_nfe'),
    },
    carta_correcao: {
      solicitar: can('solicitar_cce_nfe') || can('solicitar_nfe'),
      aprovar: can('aprovar_cce_nfe') || can('aprovar_nfe') || can('corrigir_nfe'),
    },
    inutilizacao: {
      solicitar: can('solicitar_inutilizacao_nfe') || can('solicitar_nfe'),
      aprovar: can('aprovar_inutilizacao_nfe') || can('aprovar_nfe'),
    },
  };

  const podeSolicitar = permsByTipo[tipoEvento]?.solicitar;
  const podeAprovar = permsByTipo[tipoEvento]?.aprovar;

  const solicitacaoPendente = useMemo(() => {
    return solicitacoes.find((s) => s.status_solicitacao === 'pendente_aprovacao');
  }, [solicitacoes]);

  const carregarSolicitacoes = async () => {
    if (!isOpen) return;
    setLoading(true);
    try {
      let query = supabase
        .from('nfe_eventos_solicitacoes')
        .select('*')
        .order('created_at', { ascending: false })
        .limit(30);

      if (nfeRef) {
        query = query.eq('nfe_ref', nfeRef);
      } else if (venda?.id) {
        query = query.eq('venda_id', venda.id);
      }

      const { data, error } = await query;
      if (error) throw error;
      setSolicitacoes(data || []);
    } catch (err) {
      toast.error(`Erro ao carregar solicitacoes: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const carregarPrazoAviso = async () => {
    if (!isOpen || !nfeRef) {
      setDiasDesdeAutorizacao(null);
      return;
    }

    const { data } = await supabase
      .from('notas_fiscais_emitidas')
      .select('data_autorizacao')
      .eq('nuvem_fiscal_id', nfeRef)
      .maybeSingle();

    if (!data?.data_autorizacao) {
      setDiasDesdeAutorizacao(null);
      return;
    }

    const diffMs = Date.now() - new Date(data.data_autorizacao).getTime();
    setDiasDesdeAutorizacao(Math.floor(diffMs / (1000 * 60 * 60 * 24)));
  };

  useEffect(() => {
    if (!isOpen) return;
    carregarSolicitacoes();
    carregarPrazoAviso();
  }, [isOpen, nfeRef, venda?.id]);

  const acionarWorkflow = async (body) => {
    const { data, error } = await supabase.functions.invoke('gerir-evento-nfe', { body });
    if (error || !data?.success) throw new Error(data?.error || error?.message || 'Erro desconhecido');
    return data;
  };

  const handleSolicitar = async () => {
    if (!podeSolicitar) return;

    try {
      setLoading(true);

      const body = {
        acao: 'solicitar',
        tipo_evento: tipoEvento,
        venda_id: venda?.id,
        nfe_ref: nfeRef || venda?.nfe_ref || null,
        organization_id: venda?.organization_id,
        user_id: user?.id,
        ambiente,
        justificativa: tipoEvento === 'cancelamento' ? justificativa : undefined,
        descricao_correcao: tipoEvento === 'carta_correcao' ? descricaoCorrecao : undefined,
        inutilizacao: tipoEvento === 'inutilizacao' ? inutilizacao : undefined,
      };

      await acionarWorkflow(body);
      toast.success('Solicitacao registrada para aprovacao.');
      setJustificativa('');
      setDescricaoCorrecao('');
      setMotivoReprovacao('');
      await carregarSolicitacoes();
      onUpdated?.();
    } catch (err) {
      toast.error(`Falha ao solicitar: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleAprovar = async (solicitacaoId) => {
    try {
      setLoading(true);
      await acionarWorkflow({
        acao: 'aprovar',
        tipo_evento: tipoEvento,
        solicitacao_id: solicitacaoId,
        user_id: user?.id,
      });
      toast.success('Solicitacao aprovada.');
      await carregarSolicitacoes();
      onUpdated?.();
    } catch (err) {
      toast.error(`Falha ao aprovar: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleReprovar = async (solicitacaoId) => {
    try {
      setLoading(true);
      await acionarWorkflow({
        acao: 'reprovar',
        tipo_evento: tipoEvento,
        solicitacao_id: solicitacaoId,
        user_id: user?.id,
        motivo_reprovacao: motivoReprovacao,
      });
      toast.success('Solicitacao reprovada.');
      setMotivoReprovacao('');
      await carregarSolicitacoes();
      onUpdated?.();
    } catch (err) {
      toast.error(`Falha ao reprovar: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleExecutar = async (solicitacao) => {
    try {
      setLoading(true);
      await acionarWorkflow({
        acao: 'executar',
        tipo_evento: solicitacao.tipo_evento,
        solicitacao_id: solicitacao.id,
        user_id: user?.id,
      });
      toast.success('Evento executado com sucesso.');
      await carregarSolicitacoes();
      onUpdated?.();
    } catch (err) {
      toast.error(`Falha na execucao: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const solicitacoesFiltradas = solicitacoes.filter((s) => s.tipo_evento === tipoEvento);

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-3xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Gestao de Eventos NF-e</DialogTitle>
          <DialogDescription>
            Solicite, aprove e execute eventos fiscais (cancelamento, CC-e e inutilizacao) em fluxo controlado.
          </DialogDescription>
        </DialogHeader>

        {diasDesdeAutorizacao != null && (
          <div className="rounded-md border border-amber-300 bg-amber-50 p-3 text-xs text-amber-900 flex items-start gap-2">
            <AlertTriangle className="w-4 h-4 mt-0.5" />
            <div>
              Esta NF-e foi autorizada ha {diasDesdeAutorizacao} dia(s). Prazo legal de 30 dias para cancelamento/CC-e pode se aplicar.
            </div>
          </div>
        )}

        <div className="grid gap-4">
          <div className="space-y-2">
            <Label>Tipo de Evento</Label>
            <Select value={tipoEvento} onValueChange={setTipoEvento}>
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="cancelamento">Cancelamento</SelectItem>
                <SelectItem value="carta_correcao">Carta de Correcao (CC-e)</SelectItem>
                <SelectItem value="inutilizacao">Inutilizacao de Numeracao</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {tipoEvento === 'cancelamento' && (
            <div className="space-y-2">
              <Label>Justificativa do Cancelamento</Label>
              <Textarea
                value={justificativa}
                onChange={(e) => setJustificativa(e.target.value)}
                rows={3}
                placeholder="Minimo de 15 caracteres"
              />
            </div>
          )}

          {tipoEvento === 'carta_correcao' && (
            <div className="space-y-2">
              <Label>Descricao da Correcao (CC-e)</Label>
              <Textarea
                value={descricaoCorrecao}
                onChange={(e) => setDescricaoCorrecao(e.target.value)}
                rows={3}
                placeholder="Minimo de 15 caracteres"
              />
            </div>
          )}

          {tipoEvento === 'inutilizacao' && (
            <div className="grid md:grid-cols-2 gap-3">
              <div>
                <Label>CNPJ</Label>
                <Input value={inutilizacao.cnpj} onChange={(e) => setInutilizacao((p) => ({ ...p, cnpj: e.target.value }))} />
              </div>
              <div>
                <Label>Ano (2 digitos)</Label>
                <Input value={inutilizacao.ano} onChange={(e) => setInutilizacao((p) => ({ ...p, ano: e.target.value }))} />
              </div>
              <div>
                <Label>Serie</Label>
                <Input value={inutilizacao.serie} onChange={(e) => setInutilizacao((p) => ({ ...p, serie: e.target.value }))} />
              </div>
              <div>
                <Label>Numero inicial</Label>
                <Input value={inutilizacao.numero_inicial} onChange={(e) => setInutilizacao((p) => ({ ...p, numero_inicial: e.target.value }))} />
              </div>
              <div>
                <Label>Numero final</Label>
                <Input value={inutilizacao.numero_final} onChange={(e) => setInutilizacao((p) => ({ ...p, numero_final: e.target.value }))} />
              </div>
              <div className="md:col-span-2">
                <Label>Justificativa</Label>
                <Textarea
                  value={inutilizacao.justificativa}
                  onChange={(e) => setInutilizacao((p) => ({ ...p, justificativa: e.target.value }))}
                  rows={2}
                />
              </div>
            </div>
          )}

          <div className="flex items-center gap-2">
            <Button
              onClick={handleSolicitar}
              disabled={loading || !podeSolicitar || (tipoEvento !== 'inutilizacao' && !nfeRef)}
            >
              {loading ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : null}
              Solicitar {TIPOS_EVENTO[tipoEvento]}
            </Button>
            {!podeSolicitar && <span className="text-xs text-red-600">Seu perfil nao pode solicitar eventos fiscais.</span>}
            {tipoEvento !== 'inutilizacao' && !nfeRef && <span className="text-xs text-red-600">NF-e sem referencia (nfe_ref).</span>}
          </div>

          <div className="border rounded-lg p-3 space-y-3">
            <div className="flex items-center justify-between">
              <h4 className="text-sm font-semibold">Historico ({TIPOS_EVENTO[tipoEvento]})</h4>
              {solicitacaoPendente && <Badge className="bg-yellow-500 text-white">Ha solicitacao pendente</Badge>}
            </div>

            {solicitacoesFiltradas.length === 0 && (
              <p className="text-xs text-gray-500">Nenhuma solicitacao registrada para este tipo.</p>
            )}

            <div className="space-y-2 max-h-72 overflow-y-auto">
              {solicitacoesFiltradas.map((s) => (
                <div key={s.id} className="border rounded-md p-2 text-xs space-y-2">
                  <div className="flex items-center justify-between gap-2">
                    <div className="font-medium">{new Date(s.created_at).toLocaleString('pt-BR')}</div>
                    <div>{statusBadge(s.status_solicitacao)}</div>
                  </div>

                  <div className="text-gray-600">Solicitante: {s.solicitante_nome || '-'}</div>
                  {s.aprovador_nome && <div className="text-gray-600">Aprovador: {s.aprovador_nome}</div>}
                  {s.reprovado_motivo && <div className="text-red-700">Motivo: {s.reprovado_motivo}</div>}
                  {s.mensagem_status && <div className="text-gray-700">{s.mensagem_status}</div>}

                  <div className="flex gap-2 flex-wrap">
                    {podeAprovar && s.status_solicitacao === 'pendente_aprovacao' && (
                      <>
                        <Button size="sm" variant="outline" onClick={() => handleAprovar(s.id)} disabled={loading}>
                          <ShieldCheck className="w-3 h-3 mr-1" /> Aprovar
                        </Button>
                        <Button size="sm" variant="outline" onClick={() => handleReprovar(s.id)} disabled={loading || motivoReprovacao.trim().length < 5}>
                          <ShieldX className="w-3 h-3 mr-1" /> Reprovar
                        </Button>
                      </>
                    )}

                    {podeAprovar && s.status_solicitacao === 'aprovado' && (
                      <Button size="sm" onClick={() => handleExecutar(s)} disabled={loading}>
                        {loading ? <Loader2 className="w-3 h-3 mr-1 animate-spin" /> : <CheckCircle2 className="w-3 h-3 mr-1" />}
                        Executar
                      </Button>
                    )}
                  </div>
                </div>
              ))}
            </div>

            {podeAprovar && (
              <div className="space-y-1">
                <Label>Motivo da Reprovacao (min 5)</Label>
                <Input
                  value={motivoReprovacao}
                  onChange={(e) => setMotivoReprovacao(e.target.value)}
                  placeholder="Informe o motivo"
                />
              </div>
            )}
          </div>
        </div>

        <DialogFooter>
          <Button variant="ghost" onClick={onClose}>Fechar</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Loader2 } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { toast } from "sonner";
import { useQuery } from "@tanstack/react-query";
import { CATEGORIAS, AMBIENTES, MATERIAIS } from "@/constants/productConstants";
import FurnitureColorPicker from "@/components/produtos/FurnitureColorPicker";
import { detectProductKeywordSuggestion } from "@/lib/productKeywordDetector";
import { generateSafeSKU } from "@/utils/gtinValidator";

export default function SolicitacaoCadastroModal({ isOpen, onClose, onProdutoSolicitado, user, initialParentProduct = null }) {
    const [loading, setLoading] = useState(false);
    const [dismissedSuggestionName, setDismissedSuggestionName] = useState('');

    // Effect to update internal state if prop changes
    React.useEffect(() => {
        setFormData(prev => ({
            ...prev,
            nome_produto: '',
            categoria: '',
            ambiente: '',
            fornecedor_id: '',
            material: '',
            preco_sugerido: ''
        }));
        setDismissedSuggestionName('');
    }, [isOpen]);

    const [formData, setFormData] = useState({
        nome_produto: '',
        categoria: '',
        ambiente: '',
        fornecedor_id: '',
        cor: '',
        cor_hex: '',
        tecido: '',
        material: '',
        altura: '',
        largura: '',
        profundidade: '',
        preco_sugerido: '',
        observacoes: ''
    });

    // Busca fornecedores
    const { data: fornecedores = [] } = useQuery({
        queryKey: ['fornecedores'],
        queryFn: () => base44.entities.Fornecedor.list(),
        enabled: isOpen
    });

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData({ ...formData, [name]: value });

        if (name === 'nome_produto') {
            setDismissedSuggestionName('');
        }
    };

    const handleSelectChange = (name, value) => {
        setFormData({ ...formData, [name]: value });
    }

    const keywordSuggestion = React.useMemo(
        () => detectProductKeywordSuggestion(formData.nome_produto, {
            returnDefault: true,
            defaultCategoria: 'Outros',
        }),
        [formData.nome_produto]
    );

    const normalizedSuggestionName = React.useMemo(
        () => (formData.nome_produto || '').trim().toLowerCase(),
        [formData.nome_produto]
    );

    const suggestedCategoria = keywordSuggestion.categoriaSuggestion;
    const suggestedAmbiente = AMBIENTES.includes(keywordSuggestion.ambienteSuggestion)
        ? keywordSuggestion.ambienteSuggestion
        : null;

    const canApplyCategoriaSuggestion = suggestedCategoria &&
        CATEGORIAS.includes(suggestedCategoria) &&
        suggestedCategoria !== formData.categoria;

    const canApplyAmbienteSuggestion = suggestedAmbiente &&
        suggestedAmbiente !== formData.ambiente;

    const shouldShowSuggestion = normalizedSuggestionName &&
        dismissedSuggestionName !== normalizedSuggestionName &&
        (canApplyCategoriaSuggestion || canApplyAmbienteSuggestion);

    const shouldShowCategoriaSuggestion = shouldShowSuggestion && canApplyCategoriaSuggestion;
    const shouldShowAmbienteSuggestion = shouldShowSuggestion && canApplyAmbienteSuggestion;

    const applyCategoriaSuggestion = () => {
        if (!canApplyCategoriaSuggestion) return;
        setFormData(prev => ({ ...prev, categoria: suggestedCategoria }));
    };

    const applyAmbienteSuggestion = () => {
        if (!canApplyAmbienteSuggestion) return;
        setFormData(prev => ({ ...prev, ambiente: suggestedAmbiente }));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!formData.nome_produto || !formData.preco_sugerido || !formData.categoria) {
            toast.warning("Nome, Categoria e Preço são obrigatórios");
            return;
        }

        setLoading(true);
        try {
            // 1. Formatar preco e dimensoes
            const preco = parseFloat(String(formData.preco_sugerido).replace(',', '.'));
            const medidasFormatted = [
                formData.altura ? `A:${formData.altura}cm` : '',
                formData.largura ? `L:${formData.largura}cm` : '',
                formData.profundidade ? `P:${formData.profundidade}cm` : ''
            ].filter(Boolean).join(' x ');

            // 2. Criar produto real na base (pendente revisao pelo gerente)
            const novoProduto = await base44.entities.Produto.create({
                sku: generateSafeSKU('SOL'),
                codigo_barras: null,
                nome: formData.nome_produto,
                categoria: formData.categoria,
                ambiente: formData.ambiente || null,
                material: formData.material || null,
                cor: formData.cor || null,
                cor_hex: formData.cor_hex || null,
                altura: formData.altura ? parseFloat(formData.altura) : null,
                largura: formData.largura ? parseFloat(formData.largura) : null,
                profundidade: formData.profundidade ? parseFloat(formData.profundidade) : null,
                preco_venda: preco,
                preco_custo: 0,
                fornecedor_id: formData.fornecedor_id ? parseInt(formData.fornecedor_id) : null,
                quantidade_estoque: 1,
                ativo: true,
                requer_atencao: true,
                tipo_entrega_padrao: 'desmontado',
                variacoes: [],
                fotos: [],
                is_parent: false,
                parent_id: null,
            });

            // 3. Criar solicitacao para revisao dos gerentes (informacoes fiscais e cadastro completo)
            await base44.entities.SolicitacaoCadastro.create({
                vendedor_id: user?.id,
                produto_gerado_id: novoProduto.id,
                nome_produto: formData.nome_produto,
                cor: formData.cor || null,
                tecido: formData.tecido || null,
                medidas: medidasFormatted,
                preco_sugerido: preco,
                observacoes: formData.observacoes || null,
                status: 'pendente',
                categoria: formData.categoria,
                ambiente: formData.ambiente || null,
                material: formData.material || null,
                fornecedor_id: formData.fornecedor_id ? parseInt(formData.fornecedor_id) : null,
                altura: formData.altura ? parseFloat(formData.altura) : null,
                largura: formData.largura ? parseFloat(formData.largura) : null,
                profundidade: formData.profundidade ? parseFloat(formData.profundidade) : null,
            });

            // 4. Enviar produto real ao carrinho (marcado para revisao)
            const produtoParaCarrinho = {
                ...novoProduto,
                preco_venda: preco,
                is_solicitacao: true,
                detalhes_solicitacao: {
                    cor: formData.cor,
                    tecido: formData.tecido,
                    altura: formData.altura,
                    largura: formData.largura,
                    profundidade: formData.profundidade,
                    medidas: medidasFormatted,
                    categoria: formData.categoria,
                    ambiente: formData.ambiente,
                    material: formData.material,
                    fornecedor_id: formData.fornecedor_id,
                    nome_original: formData.nome_produto,
                },
            };

            toast.success("Produto cadastrado e enviado para revisao dos gerentes.");
            onProdutoSolicitado(produtoParaCarrinho);
            onClose();
            setFormData({
                nome_produto: '', categoria: '', ambiente: '', fornecedor_id: '',
                cor: '', cor_hex: '', tecido: '', material: '',
                altura: '', largura: '', profundidade: '',
                preco_sugerido: '', observacoes: ''
            });

        } catch (err) {
            console.error(err);
            toast.error("Erro ao solicitar cadastro: " + err.message);
        } finally {
            setLoading(false);
        }
    };

    return (
        <Dialog open={isOpen} onOpenChange={onClose}>
            <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle>
                        Solicitar Cadastro de Produto
                    </DialogTitle>
                    <DialogDescription>
                        Preencha todos os dados técnicos para agilizar o cadastro.
                    </DialogDescription>
                </DialogHeader>

                <form onSubmit={handleSubmit} className="space-y-4">
                    {/* Linha 1: Nome e Categoria */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <Label>Nome do Produto *</Label>
                            <Input
                                name="nome_produto"
                                value={formData.nome_produto}
                                onChange={handleChange}
                                placeholder="Ex: Mesa Jantar 4 lugares"
                                required
                            />
                        </div>
                        <div className="space-y-2">
                            <Label>Categoria *</Label>
                            {shouldShowCategoriaSuggestion && (
                                <div className="rounded-md border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs text-emerald-900 flex items-center justify-between gap-2">
                                    <span>Categoria sugerida: <strong>{suggestedCategoria}</strong></span>
                                    <div className="flex items-center gap-2">
                                        <button
                                            type="button"
                                            onClick={applyCategoriaSuggestion}
                                            className="h-7 rounded border border-emerald-300 bg-white px-2 text-[11px] font-medium text-emerald-800 hover:bg-emerald-100"
                                        >
                                            Aplicar
                                        </button>
                                        <button
                                            type="button"
                                            onClick={() => setDismissedSuggestionName(normalizedSuggestionName)}
                                            className="text-[11px] text-emerald-700 underline underline-offset-2 hover:text-emerald-600"
                                        >
                                            Ignorar
                                        </button>
                                    </div>
                                </div>
                            )}
                            <Select
                                onValueChange={(v) => handleSelectChange('categoria', v)}
                                value={formData.categoria}
                            >
                                <SelectTrigger>
                                    <SelectValue placeholder="Selecione" />
                                </SelectTrigger>
                                <SelectContent>
                                    {CATEGORIAS.map(c => (
                                        <SelectItem key={c} value={c}>{c}</SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                    </div>

                    {/* Linha 2: Ambiente e Fornecedor */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <Label>Ambiente</Label>
                            {shouldShowAmbienteSuggestion && (
                                <div className="rounded-md border border-sky-200 bg-sky-50 px-3 py-2 text-xs text-sky-900 flex items-center justify-between gap-2">
                                    <span>Ambiente sugerido: <strong>{suggestedAmbiente}</strong></span>
                                    <div className="flex items-center gap-2">
                                        <button
                                            type="button"
                                            onClick={applyAmbienteSuggestion}
                                            className="h-7 rounded border border-sky-300 bg-white px-2 text-[11px] font-medium text-sky-800 hover:bg-sky-100"
                                        >
                                            Aplicar
                                        </button>
                                        <button
                                            type="button"
                                            onClick={() => setDismissedSuggestionName(normalizedSuggestionName)}
                                            className="text-[11px] text-sky-700 underline underline-offset-2 hover:text-sky-600"
                                        >
                                            Ignorar
                                        </button>
                                    </div>
                                </div>
                            )}
                            <Select onValueChange={(v) => handleSelectChange('ambiente', v)} value={formData.ambiente}>
                                <SelectTrigger>
                                    <SelectValue placeholder="Selecione" />
                                </SelectTrigger>
                                <SelectContent>
                                    {AMBIENTES.map(a => (
                                        <SelectItem key={a} value={a}>{a}</SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                        <div className="space-y-2">
                            <Label>Fornecedor (Opcional)</Label>
                            <Select onValueChange={(v) => handleSelectChange('fornecedor_id', v)} value={formData.fornecedor_id}>
                                <SelectTrigger>
                                    <SelectValue placeholder="Selecione" />
                                </SelectTrigger>
                                <SelectContent>
                                    {fornecedores.map(f => (
                                        <SelectItem key={f.id} value={String(f.id)}>{f.nome_empresa || f.nome_contato}</SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                    </div>

                    {/* Linha 3: Dimensões (Split) */}
                    <div className="space-y-2">
                        <Label>Dimensões (cm)</Label>
                        <div className="grid grid-cols-3 gap-2">
                            <div className="relative">
                                <span className="absolute left-2 top-1/2 -translate-y-1/2 text-gray-400 text-xs">Alt.</span>
                                <Input
                                    name="altura"
                                    type="number"
                                    value={formData.altura}
                                    onChange={handleChange}
                                    placeholder="0"
                                    className="pl-8"
                                />
                            </div>
                            <div className="relative">
                                <span className="absolute left-2 top-1/2 -translate-y-1/2 text-gray-400 text-xs">Larg.</span>
                                <Input
                                    name="largura"
                                    type="number"
                                    value={formData.largura}
                                    onChange={handleChange}
                                    placeholder="0"
                                    className="pl-9"
                                />
                            </div>
                            <div className="relative">
                                <span className="absolute left-2 top-1/2 -translate-y-1/2 text-gray-400 text-xs">Prof.</span>
                                <Input
                                    name="profundidade"
                                    type="number"
                                    value={formData.profundidade}
                                    onChange={handleChange}
                                    placeholder="0"
                                    className="pl-9"
                                />
                            </div>
                        </div>
                    </div>

                    {/* Linha 4: Acabamento (Cor, Tecido, Material) */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                        <div className="space-y-2">
                            <Label>Cor</Label>
                            <FurnitureColorPicker
                                value={formData.cor}
                                hexValue={formData.cor_hex}
                                onChange={(val) => setFormData(prev => ({ ...prev, cor: val }))}
                                onHexChange={(hex) => setFormData(prev => ({ ...prev, cor_hex: hex }))}
                                placeholder="Selecione a cor por nomenclatura"
                            />
                        </div>
                        <div className="space-y-2">
                            <Label>Tecido</Label>
                            <Input
                                name="tecido"
                                value={formData.tecido}
                                onChange={handleChange}
                                placeholder="Ex: Linho"
                            />
                        </div>
                        <div className="space-y-2">
                            <Label>Material</Label>
                            <Select onValueChange={(v) => handleSelectChange('material', v)} value={formData.material}>
                                <SelectTrigger>
                                    <SelectValue placeholder="Selecione" />
                                </SelectTrigger>
                                <SelectContent>
                                    {MATERIAIS.map(m => (
                                        <SelectItem key={m} value={m}>{m}</SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                    </div>

                    <div className="space-y-2">
                        <Label>Preço de Venda (R$)*</Label>
                        <div className="relative">
                            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500 font-bold">R$</span>
                            <Input
                                name="preco_sugerido"
                                type="number"
                                step="0.01"
                                value={formData.preco_sugerido}
                                onChange={handleChange}
                                placeholder="0.00"
                                className="pl-9 text-lg font-bold text-green-700"
                                required
                            />
                        </div>
                    </div>

                    <div className="space-y-2">
                        <Label>Observações Adicionais</Label>
                        <Textarea
                            name="observacoes"
                            value={formData.observacoes}
                            onChange={handleChange}
                            placeholder="Detalhes adicionais..."
                        />
                    </div>

                    <DialogFooter>
                        <Button type="button" variant="outline" onClick={onClose}>Cancelar</Button>
                        <Button type="submit" className="bg-amber-600 hover:bg-amber-700 text-white w-full md:w-auto" disabled={loading}>
                            {loading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : "Solicitar Cadastro"}
                        </Button>
                    </DialogFooter>
                </form>
            </DialogContent>
        </Dialog>
    );
}

import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { ArrowRightLeft, UserCheck, Loader2, AlertTriangle } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";

export default function TransferirMontagemModal({ isOpen, onClose, venda, user }) {
    const [selectedItems, setSelectedItems] = useState([]);
    const queryClient = useQueryClient();

    // Buscar itens de montagem INTERNA e NÃO CONCLUÍDOS para esta venda
    const { data: itensMontagem = [], isLoading } = useQuery({
        queryKey: ['montagens-internas-venda', venda?.id],
        queryFn: async () => {
            if (!venda?.id) return [];
            const todas = await base44.entities.MontagemItem.list();
            return todas.filter(m =>
                m.venda_id === venda.id &&
                m.tipo_montagem === 'interna' &&
                m.status !== 'concluida'
            );
        },
        enabled: !!venda?.id && isOpen,
    });

    // Mutation para atualizar
    const updateMutation = useMutation({
        mutationFn: ({ id, data }) => base44.entities.MontagemItem.update(id, data),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['montagens-internas-venda'] });
            queryClient.invalidateQueries({ queryKey: ['montagens'] }); // Atualizar listas globais
        }
    });

    // Selecionar todos os itens
    const handleSelectAll = (checked) => {
        if (checked) {
            // Só seleciona os que não estão atribuídos (ou todos, mas com aviso)
            // A regra é: se já tem montador, não pode transferir (salvo se limparmos)
            // Mas o usuario pediu "não permita status mudar caso já tenha sido atribuido"
            // Entao só selecionamos os elegiveis
            const elegiveis = itensMontagem.filter(m => !m.montador_id).map(m => m.id);
            setSelectedItems(elegiveis);
            if (elegiveis.length < itensMontagem.length) {
                toast.info("Alguns itens já estão atribuídos e não foram selecionados.");
            }
        } else {
            setSelectedItems([]);
        }
    };

    const handleToggleItem = (id, montadorId) => {
        if (montadorId) {
            toast.warning("Este item já está atribuído a um montador interno. Remova a atribuição primeiro.");
            return;
        }

        setSelectedItems(prev =>
            prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
        );
    };

    const handleTransferir = async () => {
        if (selectedItems.length === 0) return;

        const confirmacao = window.confirm(`Deseja transferir ${selectedItems.length} itens para Montagem Externa?`);
        if (!confirmacao) return;

        try {
            const promises = selectedItems.map(id =>
                updateMutation.mutateAsync({
                    id,
                    data: {
                        tipo_montagem: 'terceirizada',
                        montador_id: null,
                        montador_nome: null,
                        status: 'pendente',
                        updated_at: new Date().toISOString()
                    }
                })
            );

            await Promise.all(promises);
            toast.success(`${selectedItems.length} itens transferidos com sucesso!`);
            onClose();
            setSelectedItems([]);
        } catch (error) {
            console.error(error);
            toast.error("Erro ao transferir itens.");
        }
    };

    const isAllSelected = itensMontagem.length > 0 && itensMontagem.filter(m => !m.montador_id).every(m => selectedItems.includes(m.id)) && selectedItems.length > 0;

    if (!isOpen) return null;

    return (
        <Dialog open={isOpen} onOpenChange={onClose}>
            <DialogContent className="sm:max-w-lg">
                <DialogHeader>
                    <DialogTitle className="flex items-center gap-2">
                        <ArrowRightLeft className="w-5 h-5 text-orange-600" />
                        Transferir para Montagem Externa
                    </DialogTitle>
                    <DialogDescription>
                        Selecione os itens que devem ser montados no local do cliente (Montador Externo).
                    </DialogDescription>
                </DialogHeader>

                <div className="py-4">
                    {isLoading ? (
                        <div className="flex justify-center p-4"><Loader2 className="animate-spin" /></div>
                    ) : itensMontagem.length === 0 ? (
                        <div className="text-center p-4 text-gray-500 bg-gray-50 rounded-lg border border-dashed">
                            Nenhum item de montagem interna pendente encontrado para este pedido.
                        </div>
                    ) : (
                        <div className="space-y-3">
                            <div className="flex items-center space-x-2 pb-2 border-b">
                                <Checkbox
                                    id="select-all"
                                    checked={isAllSelected}
                                    onCheckedChange={handleSelectAll}
                                />
                                <Label htmlFor="select-all" className="font-bold cursor-pointer">
                                    Selecionar Todos (Elegíveis)
                                </Label>
                            </div>

                            <div className="max-h-[300px] overflow-y-auto space-y-2 pr-1">
                                {itensMontagem.map(item => {
                                    const isAssigned = !!item.montador_id;
                                    return (
                                        <div
                                            key={item.id}
                                            className={`flex items-start space-x-3 p-2 rounded-lg border transition-colors ${isAssigned ? 'bg-gray-50 border-gray-200 opacity-70' :
                                                    selectedItems.includes(item.id) ? 'bg-orange-50 border-orange-200' : 'bg-white hover:bg-gray-50'
                                                }`}
                                        >
                                            <Checkbox
                                                id={`item-${item.id}`}
                                                checked={selectedItems.includes(item.id)}
                                                onCheckedChange={() => handleToggleItem(item.id, item.montador_id)}
                                                disabled={isAssigned}
                                            />
                                            <div className="flex-1">
                                                <Label
                                                    htmlFor={`item-${item.id}`}
                                                    className={`font-medium cursor-pointer ${isAssigned ? 'cursor-not-allowed text-gray-500' : ''}`}
                                                >
                                                    {item.produto_nome}
                                                </Label>
                                                <div className="flex items-center gap-2 text-xs text-gray-500 mt-1">
                                                    <span className="bg-gray-100 px-1 rounded">Qtd: {item.quantidade}</span>
                                                    {isAssigned && (
                                                        <span className="flex items-center gap-1 text-blue-600 bg-blue-50 px-1 rounded">
                                                            <UserCheck className="w-3 h-3" />
                                                            {item.montador_nome}
                                                        </span>
                                                    )}
                                                </div>
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>

                            <div className="bg-yellow-50 p-3 rounded-md text-xs text-yellow-800 flex items-start gap-2">
                                <AlertTriangle className="w-4 h-4 mt-0.5 flex-shrink-0" />
                                <p>
                                    Itens já atribuídos a um montador interno não podem ser transferidos diretamente.
                                    Vá para &quot;Montagem Interna&quot; e remova a atribuição primeiro.
                                </p>
                            </div>
                        </div>
                    )}
                </div>

                <DialogFooter>
                    <Button variant="outline" onClick={onClose}>Cancelar</Button>
                    <Button
                        onClick={handleTransferir}
                        disabled={selectedItems.length === 0 || updateMutation.isPending}
                        className="bg-orange-600 hover:bg-orange-700 text-white"
                    >
                        {updateMutation.isPending ? <Loader2 className="animate-spin mr-2" /> : null}
                        Transferir {selectedItems.length} Item(ns)
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

import React, { useState } from "react";
import { base44, supabase } from "@/api/base44Client";
import { useAuth } from "@/hooks/useAuth";
import { EMPRESA } from "@/config/empresa";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Pencil, Trash2, User, Calendar, CreditCard, Package, FileDown, MapPin, XCircle } from "lucide-react";
import { format } from "date-fns";
import { formatarDataExibicao } from "@/utils/dateUtils";
import { stripInternalProductPrefixes } from "@/utils/productReference";
import { isStatusCancelado } from "@/utils/vendaStatus";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";

const statusColors = {
  "Pagamento Pendente": { bg: "#FEF3C7", text: "#92400E", border: "#FCD34D" },
  "Pago": { bg: "#DBEAFE", text: "#1E40AF", border: "#93C5FD" },
  "Pago & Retirado": { bg: "#D1FAE5", text: "#065F46", border: "#6EE7B7" }
};

export default function VendaCard({ venda, onEdit, onDelete, onLiberarEstoque, showValues = true, showLiberarEstoque = false }) {
  const [baixando, setBaixando] = useState(false);
  const [showCancelDialog, setShowCancelDialog] = useState(false);
  const queryClient = useQueryClient();
  const { user } = useAuth();

  // Only managers and admins can cancel sales
  const canCancel = user?.cargo === 'Administrador' || user?.cargo === 'Gerente' || user?.cargo === 'Gerente Geral';

  const cancelarVendaMutation = useMutation({
    mutationFn: async () => {
      const { resolveStockField } = await import("@/utils/stockUtils");
      const campoLoja = resolveStockField(venda.loja);

      // 1. Atualizar status da venda para Cancelado
      await base44.entities.Venda.update(venda.id, { status: 'Cancelado' });

      // 2. Cancelar lançamentos financeiros vinculados
      try {
        const lancamentos = await base44.entities.LancamentoFinanceiro.list();
        const lancamentosVenda = lancamentos.filter(l =>
          l.venda_id === venda.id || l.numero_pedido === venda.numero_pedido
        );
        for (const lanc of lancamentosVenda) {
          await base44.entities.LancamentoFinanceiro.update(lanc.id, {
            status: 'Cancelado',
            observacao: (lanc.observacao || '') + ' [VENDA CANCELADA]'
          });
        }
      } catch (err) {
        console.error('Erro ao cancelar lançamentos:', err);
      }

      // 3. Cancelar entregas vinculadas
      try {
        const entregas = await base44.entities.Entrega.list();
        const entregasVenda = entregas.filter(e =>
          e.venda_id === venda.id || e.numero_pedido === venda.numero_pedido
        );
        for (const entrega of entregasVenda) {
          if (!isStatusCancelado(entrega.status)) {
            await base44.entities.Entrega.update(entrega.id, {
              status: 'Cancelado',
              observacoes: (entrega.observacoes || '') + ' [VENDA CANCELADA]'
            });
          }
        }
      } catch (err) {
        console.error('Erro ao cancelar entregas:', err);
      }

      // 4. Cancelar montagens vinculadas (internas e externas)
      try {
        const montagens = await base44.entities.MontagemItem.list();
        const montagensVenda = montagens.filter(m => m.venda_id === venda.id);
        for (const montagem of montagensVenda) {
          if (!isStatusCancelado(montagem.status)) {
            await base44.entities.MontagemItem.update(montagem.id, {
              status: 'cancelada',
              observacoes: (montagem.observacoes || '') + ' [VENDA CANCELADA]'
            });
          }
        }
      } catch (err) {
        console.error('Erro ao cancelar montagens:', err);
      }

      // 5. Cancelar assistências técnicas vinculadas
      try {
        const assistencias = await base44.entities.AssistenciaTecnica.list();
        const assistenciasVenda = assistencias.filter(a => a.venda_id === venda.id);
        for (const assistencia of assistenciasVenda) {
          if (!isStatusCancelado(assistencia.status)) {
            await base44.entities.AssistenciaTecnica.update(assistencia.id, {
              status: 'Cancelada',
              observacoes: (assistencia.observacoes || '') + ' [VENDA CANCELADA]'
            });
          }
        }
      } catch (err) {
        console.error('Erro ao cancelar assistências:', err);
      }

      // 6. Devolver produtos ao estoque
      for (const item of venda.itens) {
        const produtos = await base44.entities.Produto.list();
        const produto = produtos.find(p => p.id === item.produto_id);

        if (produto) {
          const updates = {
            quantidade_estoque: (produto.quantidade_estoque || 0) + item.quantidade,
            quantidade_reservada: Math.max(0, (produto.quantidade_reservada || 0) - item.quantidade)
          };

          // Also restore the per-store stock field
          if (campoLoja) {
            updates[campoLoja] = (produto[campoLoja] || 0) + item.quantidade;
          }

          const estoqueAntesCancelamento = produto.quantidade_estoque || 0;
          await base44.entities.Produto.update(produto.id, updates);
          try {
            await supabase.from('movimentacoes_estoque').insert({
              produto_id: produto.id,
              evento_tipo: 'cancelamento_devolucao',
              modulo_origem: 'vendas',
              quantidade: item.quantidade,
              estoque_antes_total: estoqueAntesCancelamento,
              estoque_depois_total: estoqueAntesCancelamento + item.quantidade,
              usuario_id: user?.id || null,
              usuario_nome: user?.nome || null,
              usuario_cargo: user?.cargo || null,
              cliente_nome: venda.cliente_nome || null,
              cliente_contato: venda.cliente_telefone || null,
              referencia_id: venda.id,
              referencia_numero: venda.numero_pedido || null,
              loja_origem: venda.loja || null,
              organization_id: '00000000-0000-0000-0000-000000000001'
            });
          } catch (auditErr) {
            console.warn('Falha ao registrar movimentação de cancelamento:', auditErr);
          }
        }
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['vendas'] });
      queryClient.invalidateQueries({ queryKey: ['produtos'] });
      queryClient.invalidateQueries({ queryKey: ['entregas'] });
      queryClient.invalidateQueries({ queryKey: ['montagens'] });
      queryClient.invalidateQueries({ queryKey: ['assistencias'] });
      queryClient.invalidateQueries({ queryKey: ['lancamentos-financeiros'] });
      setShowCancelDialog(false);
    },
  });

  const baixarPDF = (e) => {
    if (e) e.stopPropagation();
    setBaixando(true);

    // Função para limpar nome do produto (remove prefixos internos)
    const limparNomeProduto = (nome) => stripInternalProductPrefixes(nome) || '-';

    let itensHTML = '';
    venda.itens?.forEach(item => {
      itensHTML += `
        <tr>
          <td style="padding: 12px; border-bottom: 1px solid #E5E0D8;">${limparNomeProduto(item.produto_nome)}</td>
          <td style="padding: 12px; border-bottom: 1px solid #E5E0D8; text-align: center;">${item.quantidade}</td>
          <td style="padding: 12px; border-bottom: 1px solid #E5E0D8; text-align: right;">R$ ${item.preco_unitario.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</td>
          <td style="padding: 12px; border-bottom: 1px solid #E5E0D8; text-align: right; font-weight: bold;">R$ ${item.subtotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</td>
        </tr>
      `;
    });

    const htmlContent = `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <style>
          body {
            font-family: Arial, sans-serif;
            padding: 40px;
            color: #2C2C2C;
          }
          .header {
            text-align: center;
            margin-bottom: 40px;
            border-bottom: 3px solid #07593f;
            padding-bottom: 20px;
          }
          .header img {
            width: 80px;
            height: auto;
            margin: 0 auto 15px;
          }
          .header h1 {
            color: #07593f;
            margin: 0;
            font-size: 32px;
          }
          .header p {
            color: #8B8B8B;
            margin: 5px 0;
          }
          .info-section {
            margin-bottom: 30px;
          }
          .info-row {
            margin-bottom: 10px;
          }
          .info-label {
            font-weight: bold;
            color: #2C2C2C;
          }
          .info-value {
            color: #8B8B8B;
          }
          table {
            width: 100%;
            border-collapse: collapse;
            margin: 30px 0;
          }
          th {
            background-color: #07593f;
            color: white;
            padding: 15px;
            text-align: left;
          }
          .totals {
            margin-top: 20px;
            text-align: right;
          }
          .totals div {
            margin-bottom: 10px;
            font-size: 16px;
          }
          .total-final {
            font-size: 24px;
            font-weight: bold;
            color: #07593f;
            margin-top: 15px;
            padding-top: 15px;
            border-top: 2px solid #07593f;
          }
          .payment-info {
            background: #f0f9ff;
            padding: 15px;
            border-radius: 8px;
            margin-top: 20px;
          }
          .footer {
            margin-top: 50px;
            text-align: center;
            color: #8B8B8B;
            font-size: 12px;
          }
        </style>
      </head>
      <body>
        <div class="header">
          <img src="${EMPRESA.logo_url}" alt="Logo" />
          <h1>${EMPRESA.nome}</h1>
          <p>Loja ${venda.loja}</p>
        </div>

        <div class="info-section">
          <h2 style="color: #07593f; margin-bottom: 20px;">Comprovante de Venda</h2>
          <div class="info-row">
            <span class="info-label">Pedido Nº:</span>
            <span class="info-value">${venda.numero_pedido}</span>
          </div>
          <div class="info-row">
            <span class="info-label">Data:</span>
            <span class="info-value">${formatarDataExibicao(venda.data_venda)}</span>
          </div>
          <div class="info-row">
            <span class="info-label">Status:</span>
            <span class="info-value">${venda.status}</span>
          </div>
        </div>

        <div class="info-section">
          <h3 style="color: #2C2C2C; margin-bottom: 15px;">Dados do Cliente</h3>
          <div class="info-row">
            <span class="info-label">Nome:</span>
            <span class="info-value">${venda.cliente_nome}</span>
          </div>
        </div>

        <table>
          <thead>
            <tr>
              <th>Produto</th>
              <th style="text-align: center;">Qtd</th>
              <th style="text-align: right;">Preço Unit.</th>
              <th style="text-align: right;">Subtotal</th>
            </tr>
          </thead>
          <tbody>
            ${itensHTML}
          </tbody>
        </table>

        <div class="totals">
          ${venda.desconto > 0 ? `
          <div>
            <span class="info-label">Desconto:</span>
            <span style="color: #f38a4c;">-R$ ${venda.desconto.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
          </div>` : ''}
          <div class="total-final">
            Total: R$ ${venda.valor_total.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
          </div>
        </div>

        ${venda.valor_entrada > 0 || venda.valor_restante > 0 ? `
        <div class="payment-info">
          <h3 style="color: #07593f; margin-bottom: 10px;">Informações de Pagamento</h3>
          ${venda.valor_entrada > 0 ? `
          <div class="info-row">
            <span class="info-label">Entrada Paga:</span>
            <span class="info-value">R$ ${venda.valor_entrada.toLocaleString('pt-BR', { minimumFractionDigits: 2 })} via ${venda.forma_pagamento_entrada}
            ${venda.forma_pagamento_entrada === 'Crédito' && venda.parcelas_cartao > 1 ? ` (${venda.parcelas_cartao}x)` : ''}</span>
          </div>` : ''}
          ${venda.valor_restante > 0 ? `
          <div class="info-row">
            <span class="info-label">Restante:</span>
            <span class="info-value">R$ ${venda.valor_restante.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
            ${venda.pagamento_restante_entrega ? ` (A pagar na entrega via ${venda.forma_pagamento_entrega})` : ''}</span>
          </div>` : ''}
        </div>` : ''}

        ${venda.observacoes ? `
        <div class="info-section" style="margin-top: 30px;">
          <h3 style="color: #2C2C2C; margin-bottom: 10px;">Observações</h3>
          <p style="color: #8B8B8B;">${venda.observacoes}</p>
        </div>` : ''}

        <div class="footer">
          <p>Obrigado pela preferência!</p>
          <p>${EMPRESA.nome} - Loja ${venda.loja}</p>
        </div>
      </body>
      </html>
    `;

    const printWindow = window.open('', '', 'height=600,width=800');
    printWindow.document.write(htmlContent);
    printWindow.document.close();

    setTimeout(() => {
      printWindow.print();
      setBaixando(false);
    }, 250);
  };

  return (
    <>
      <Card className="hover:shadow-xl transition-all duration-300 border-0">
        <CardHeader className="pb-4">
          <div className="flex items-start justify-between">
            <div>
              <div className="flex items-center gap-2 mb-2">
                <h3 className="font-bold text-xl" style={{ color: '#07593f' }}>
                  Pedido #{venda.numero_pedido}
                </h3>
                <Badge
                  style={{
                    backgroundColor: statusColors[venda.status]?.bg,
                    color: statusColors[venda.status]?.text,
                    borderColor: statusColors[venda.status]?.border,
                  }}
                  className="border"
                >
                  {venda.status}
                </Badge>
              </div>
              <div className="flex items-center gap-4 text-sm" style={{ color: '#8B8B8B' }}>
                <div className="flex items-center gap-2">
                  <Calendar className="w-4 h-4" />
                  {formatarDataExibicao(venda.data_venda)}
                </div>
                {venda.loja && (
                  <div className="flex items-center gap-2">
                    <MapPin className="w-4 h-4" />
                    {venda.loja}
                  </div>
                )}
              </div>
            </div>
            {showValues && (
              <div className="text-right">
                <p className="text-sm mb-1" style={{ color: '#8B8B8B' }}>Valor Total</p>
                <p className="text-2xl font-bold" style={{ color: '#07593f' }}>
                  R$ {venda.valor_total?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                </p>
              </div>
            )}
          </div>
        </CardHeader>

        <CardContent className="space-y-4">
          {showLiberarEstoque && venda.valor_restante > 0 && (
            <div className="p-3 rounded-lg border-2" style={{ borderColor: '#FCD34D', backgroundColor: '#FEF3C7' }}>
              <p className="text-xs font-semibold mb-1" style={{ color: '#92400E' }}>
                🔒 Estoque Reservado
              </p>
              <p className="text-xs mb-2" style={{ color: '#92400E' }}>
                Cliente: <strong>{venda.cliente_nome}</strong>
                <br />
                Restante a pagar: <strong>R$ {venda.valor_restante?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</strong>
              </p>
              <Button
                size="sm"
                variant="outline"
                onClick={(e) => {
                  e.stopPropagation();
                  onLiberarEstoque(venda);
                }}
                className="w-full text-orange-600 hover:text-orange-700 hover:bg-orange-50 border-orange-300"
              >
                <XCircle className="w-4 h-4 mr-2" />
                Cliente Desistiu - Liberar Estoque
              </Button>
            </div>
          )}

          <div className="space-y-2">
            <div className="flex items-center gap-2">
              <User className="w-4 h-4" style={{ color: '#07593f' }} />
              <span className="font-medium" style={{ color: '#07593f' }}>
                {venda.cliente_nome}
              </span>
            </div>

            {showValues && venda.valor_entrada > 0 && (
              <div className="text-sm p-2 rounded" style={{ backgroundColor: '#f0f9ff' }}>
                <p style={{ color: '#07593f' }}>
                  <strong>Entrada:</strong> R$ {venda.valor_entrada?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                  {' '}via {venda.forma_pagamento_entrada}
                  {venda.forma_pagamento_entrada === 'Crédito' && venda.parcelas_cartao > 1 && ` (${venda.parcelas_cartao}x)`}
                </p>
              </div>
            )}

            {showValues && venda.valor_restante > 0 && (
              <div className="text-sm p-2 rounded" style={{ backgroundColor: '#fef3c7' }}>
                <p style={{ color: '#92400E' }}>
                  <strong>Restante:</strong> R$ {venda.valor_restante?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                  {venda.pagamento_restante_entrega && ` (na entrega)`}
                </p>
              </div>
            )}

            {venda.itens && venda.itens.length > 0 && (
              <div className="pt-2 border-t" style={{ borderColor: '#E5E0D8' }}>
                <div className="flex items-center gap-2 mb-2">
                  <Package className="w-4 h-4" style={{ color: '#f38a4c' }} />
                  <span className="text-sm font-medium" style={{ color: '#07593f' }}>
                    Itens da venda:
                  </span>
                </div>
                <div className="space-y-1">
                  {venda.itens.map((item, index) => (
                    <div key={index} className="text-sm flex justify-between" style={{ color: '#8B8B8B' }}>
                      <span>{item.quantidade}x {item.produto_nome}</span>
                      {showValues && (
                        <span>R$ {item.subtotal?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            )}

            {venda.desconto > 0 && showValues && (
              <div className="text-sm" style={{ color: '#8B8B8B' }}>
                Desconto: R$ {venda.desconto?.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
              </div>
            )}
          </div>

          {venda.observacoes && (
            <div className="pt-2 border-t" style={{ borderColor: '#E5E0D8' }}>
              <p className="text-sm" style={{ color: '#8B8B8B' }}>
                <span className="font-medium">Obs:</span> {venda.observacoes}
              </p>
            </div>
          )}

          <div className="flex gap-2 pt-2 flex-wrap">
            <Button
              variant="outline"
              size="sm"
              onClick={baixarPDF}
              disabled={baixando}
              className="flex-1"
              style={{ borderColor: '#07593f', color: '#07593f' }}
            >
              <FileDown className="w-4 h-4 mr-1" />
              {baixando ? "Gerando..." : "PDF"}
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={(e) => {
                e.stopPropagation();
                onEdit(venda);
              }}
              className="flex-1"
            >
              <Pencil className="w-4 h-4 mr-1" />
              Editar
            </Button>
            {canCancel && (
            <Button
              variant="outline"
              size="sm"
              onClick={(e) => {
                e.stopPropagation();
                setShowCancelDialog(true);
              }}
              className="flex-1 text-orange-600 hover:text-orange-700 hover:border-orange-600"
            >
              <XCircle className="w-4 h-4 mr-1" />
              Cancelar
            </Button>
            )}
            <Button
              variant="outline"
              size="sm"
              onClick={(e) => {
                e.stopPropagation();
                onDelete(venda.id);
              }}
              className="text-red-600 hover:text-red-700 hover:border-red-600"
            >
              <Trash2 className="w-4 h-4" />
            </Button>
          </div>
        </CardContent>
      </Card>

      <AlertDialog open={showCancelDialog} onOpenChange={setShowCancelDialog}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle style={{ color: '#07593f' }}>
              Cancelar Venda #{venda.numero_pedido}
            </AlertDialogTitle>
            <AlertDialogDescription>
              Ao cancelar esta venda:
              <ul className="list-disc list-inside mt-2 space-y-1">
                <li>Os produtos serão devolvidos ao estoque</li>
                <li>As reservas serão liberadas</li>
                <li>Entregas vinculadas serão canceladas</li>
                <li>Montagens (internas e externas) serão canceladas</li>
                <li>Assistências técnicas serão canceladas</li>
                <li>Lançamentos financeiros serão cancelados</li>
                <li>Esta ação não pode ser desfeita</li>
              </ul>
              <p className="mt-3 font-semibold" style={{ color: '#f38a4c' }}>
                Tem certeza que deseja cancelar esta venda?
              </p>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Não, manter venda</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => cancelarVendaMutation.mutate()}
              disabled={cancelarVendaMutation.isPending}
              className="bg-orange-600 hover:bg-orange-700"
            >
              {cancelarVendaMutation.isPending ? 'Cancelando...' : 'Sim, cancelar venda'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
    Package,
    User,
    Calendar,
    MapPin,
    CreditCard,
    MessageSquare,
    Truck,
    Wrench,
    Store,
    FileText,
    AlertTriangle,
    ShieldCheck
} from 'lucide-react';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { buildProductDisplayName } from '@/utils/productReference';
import { getEntregaFotos, getVendaFinanceiro, getVendaResumoLogistico } from '@/utils/vendaStatus';

const TONE_CLASSES = {
    purple: 'bg-purple-100 text-purple-700 border-purple-200',
    blue: 'bg-blue-100 text-blue-700 border-blue-200',
    orange: 'bg-orange-100 text-orange-700 border-orange-200',
    cyan: 'bg-cyan-100 text-cyan-700 border-cyan-200',
    green: 'bg-green-100 text-green-700 border-green-200'
};

export function VendaDetalhesModal({ venda, isOpen, onClose, entregas = [], montagens = [], lancamentos = [] }) {
    if (!venda) return null;

    const formatCurrency = (value) => {
        return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value || 0);
    };

    const financeiro = getVendaFinanceiro(venda, { entregas, lancamentos });
    const resumoLogistico = getVendaResumoLogistico(venda, { entregas, montagens });
    const entregaAtual = resumoLogistico.entregaPrincipal;
    const fotosEntrega = getEntregaFotos(entregaAtual);

    const totalDescontosItens = (venda.itens || []).reduce((acc, item) => acc + Number(item.desconto_item_valor || 0), 0);
    const subtotalBruto = (venda.itens || []).reduce((acc, item) => {
        const price = Number(item.preco_original || item.preco_unitario || item.valor_unitario || 0);
        return acc + (price * Number(item.quantidade || 1));
    }, 0);
    const descontoGlobal = Number(venda.desconto || venda.valor_desconto || 0);

    const getStatusBadge = (status) => {
        const statusMap = {
            'pago': { color: 'bg-emerald-500', label: 'Pago' },
            'pagamento pendente': { color: 'bg-amber-500', label: 'Pagamento Pendente' },
            'cancelado': { color: 'bg-destructive', label: 'Cancelado' },
            'concluida': { color: 'bg-blue-500', label: 'Concluída' },
        };
        const config = statusMap[status?.toLowerCase()] || { color: 'bg-slate-500', label: status || 'Desconhecido' };
        return <Badge className={`${config.color} text-white`}>{config.label}</Badge>;
    };

    return (
        <Dialog open={isOpen} onOpenChange={onClose}>
            <DialogContent className="max-w-4xl max-h-[90vh] flex flex-col p-6 overflow-hidden">
                <DialogHeader className="border-b pb-4 mb-4">
                    <div className="flex items-center justify-between">
                        <div className="flex flex-col">
                            <DialogTitle className="text-2xl font-bold flex items-center gap-2">
                                <FileText className="h-6 w-6 text-primary" />
                                Venda #{venda.numero_pedido || venda.id.slice(0, 8)}
                            </DialogTitle>
                            <div className="flex items-center gap-4 mt-2 text-sm text-muted-foreground">
                                <span className="flex items-center gap-1">
                                    <Calendar className="h-4 w-4" />
                                    {format(new Date(venda.data_venda || venda.created_at), "dd/MM/yyyy HH:mm", { locale: ptBR })}
                                </span>
                                {(venda.loja_nome || venda.loja) && (
                                    <span className="flex items-center gap-1">
                                        <Store className="h-4 w-4" />
                                        {venda.loja_nome || venda.loja}
                                    </span>
                                )}
                            </div>
                        </div>
                        <div className="flex flex-col items-end gap-2">
                            {getStatusBadge(financeiro.displayStatus)}
                            {venda.conferencia_caixa_status === 'aguardando' && (
                                <Badge className="bg-amber-100 text-amber-700 border-amber-200 border text-[10px] flex items-center gap-1 font-semibold uppercase tracking-wider">
                                    <ShieldCheck className="h-3 w-3" /> Aguardando Caixa
                                </Badge>
                            )}
                            {venda.conferencia_caixa_status === 'devolvido' && (
                                <Badge className="bg-orange-100 text-orange-700 border-orange-200 border text-[10px] flex items-center gap-1 font-semibold uppercase tracking-wider">
                                    <AlertTriangle className="h-3 w-3" /> Devolvido
                                </Badge>
                            )}
                            {venda.conferencia_caixa_status === 'aprovado' && (
                                <Badge className="bg-green-100 text-green-700 border-green-200 border text-[10px] flex items-center gap-1 font-semibold uppercase tracking-wider">
                                    <ShieldCheck className="h-3 w-3" /> Conferido
                                </Badge>
                            )}
                            {(venda.vendedor_nome || venda.responsavel_nome) && (
                                <span className="text-xs font-medium text-muted-foreground">
                                    Vendedor: {venda.vendedor_nome || venda.responsavel_nome}
                                </span>
                            )}
                        </div>
                    </div>
                </DialogHeader>

                <ScrollArea className="flex-1 pr-4">
                    <div className="space-y-8">
                        {/* Informações do Cliente */}
                        <section>
                            <h3 className="text-lg font-semibold flex items-center gap-2 mb-4 text-primary">
                                <User className="h-5 w-5" />
                                Informações do Cliente
                            </h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-muted/30 p-4 rounded-xl border">
                                <div>
                                    <p className="text-sm font-semibold">{venda.cliente_nome}</p>
                                    {venda.cliente_cpf_cnpj && (
                                        <p className="text-xs text-muted-foreground mt-1">
                                            CPF/CNPJ: {venda.cliente_cpf_cnpj}
                                        </p>
                                    )}
                                    {venda.cliente_telefone && (
                                        <p className="text-xs text-muted-foreground">{venda.cliente_telefone}</p>
                                    )}
                                </div>
                                <div className="flex flex-col gap-1">
                                    {(entregaAtual?.endereco_entrega || venda.endereco_entrega) && (
                                        <div className="flex items-start gap-2 text-xs">
                                            <MapPin className="h-3 w-3 mt-0.5 shrink-0 text-muted-foreground" />
                                            <span>{entregaAtual?.endereco_entrega || venda.endereco_entrega}</span>
                                        </div>
                                    )}
                                    {venda.ponto_referencia && (
                                        <p className="text-[10px] text-amber-600 font-medium ml-5">
                                            Ref: {venda.ponto_referencia}
                                        </p>
                                    )}
                                </div>
                            </div>
                        </section>

                        {/* Itens do Pedido */}
                        <section>
                            <h3 className="text-lg font-semibold flex items-center gap-2 mb-4 text-primary">
                                <Package className="h-5 w-5" />
                                Itens do Pedido
                            </h3>
                            <div className="border rounded-xl overflow-hidden">
                                <Table>
                                    <TableHeader className="bg-muted/50">
                                        <TableRow>
                                            <TableHead>Produto</TableHead>
                                            <TableHead>Entrega</TableHead>
                                            <TableHead>Montagem</TableHead>
                                            <TableHead className="text-center">Qtd</TableHead>
                                            <TableHead className="text-right">Unitário</TableHead>
                                            <TableHead className="text-right">Total</TableHead>
                                        </TableRow>
                                    </TableHeader>
                                    <TableBody>
                                        {resumoLogistico.itensDetalhados.map((item, idx) => {
                                            const temDescontoItem = (item.desconto_item_percent || 0) > 0 || (item.desconto_item_valor || 0) > 0;
                                            const unitPrice = Number(item.valor_unitario || item.preco_unitario || 0);
                                            const originalPrice = item.preco_original || (unitPrice + Number(item.desconto_item_valor || 0) / Number(item.quantidade || 1));
                                            const subtotalOriginal = originalPrice * Number(item.quantidade || 1);
                                            const subtotalComDesconto = Number(item.quantidade || 0) * unitPrice;
                                            
                                            return (
                                                <TableRow key={idx}>
                                                    <TableCell className="font-medium text-sm">
                                                        {buildProductDisplayName(item.produto_nome, item.modelo_referencia)}
                                                        {item.variacao_nome && (
                                                            <span className="text-xs text-muted-foreground block font-normal">
                                                                {item.variacao_nome}
                                                            </span>
                                                        )}
                                                        {temDescontoItem && (
                                                            <span className="text-xs text-emerald-600 font-semibold block mt-0.5">
                                                                ✂ {item.desconto_item_percent ? `Desconto ${item.desconto_item_percent}%` : 'Desconto'}: -{formatCurrency(item.desconto_item_valor)}
                                                            </span>
                                                        )}
                                                    </TableCell>
                                                    <TableCell className="text-xs text-muted-foreground">{item.entregaLabel || '-'}</TableCell>
                                                    <TableCell className="text-xs text-muted-foreground">{item.montagemLabel || '-'}</TableCell>
                                                    <TableCell className="text-center">{item.quantidade}</TableCell>
                                                    <TableCell className="text-right text-xs">
                                                        {temDescontoItem && originalPrice > unitPrice && (
                                                            <span className="text-[10px] text-muted-foreground line-through block">
                                                                {formatCurrency(originalPrice)}
                                                            </span>
                                                        )}
                                                        <span className="font-medium">{formatCurrency(unitPrice)}</span>
                                                    </TableCell>
                                                    <TableCell className="text-right font-semibold">
                                                        {temDescontoItem && subtotalOriginal > subtotalComDesconto && (
                                                            <span className="text-xs text-muted-foreground line-through block font-normal">
                                                                {formatCurrency(subtotalOriginal)}
                                                            </span>
                                                        )}
                                                        <span className={temDescontoItem ? "text-emerald-700" : ""}>
                                                            {formatCurrency(item.subtotal || subtotalComDesconto)}
                                                        </span>
                                                    </TableCell>
                                                </TableRow>
                                            );
                                        })}
                                    </TableBody>
                                </Table>
                            </div>
                        </section>

                        {/* Resumo Financeiro e Logística */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                            {/* Financeiro */}
                            <section>
                                <h3 className="text-lg font-semibold flex items-center gap-2 mb-4 text-primary">
                                    <CreditCard className="h-5 w-5" />
                                    Financeiro
                                </h3>
                                <div className="space-y-3 bg-muted/20 p-4 rounded-xl border">
                                     {/* Subtotal bruto se houver qualquer desconto */}
                                     {(totalDescontosItens > 0 || descontoGlobal > 0) ? (
                                         <div className="flex justify-between text-sm">
                                             <span className="text-muted-foreground">Subtotal bruto</span>
                                             <span>{formatCurrency(subtotalBruto)}</span>
                                         </div>
                                     ) : (
                                         <div className="flex justify-between text-sm">
                                             <span className="text-muted-foreground">Subtotal</span>
                                             <span>{formatCurrency(venda.valor_subtotal || subtotalBruto)}</span>
                                         </div>
                                     )}
                                     
                                     {totalDescontosItens > 0 && (
                                         <div className="flex justify-between text-sm text-emerald-600 font-medium">
                                             <span>Descontos em produtos</span>
                                             <span>-{formatCurrency(totalDescontosItens)}</span>
                                         </div>
                                     )}
                                     
                                     {descontoGlobal > 0 && (
                                         <div className="flex justify-between text-sm text-emerald-600 font-medium">
                                             <span>Desconto negociável</span>
                                             <span>-{formatCurrency(descontoGlobal)}</span>
                                         </div>
                                     )}
                                     
                                     {venda.valor_frete > 0 && (
                                         <div className="flex justify-between text-sm">
                                             <span>Frete</span>
                                             <span>{formatCurrency(venda.valor_frete)}</span>
                                         </div>
                                     )}
                                     <div className="flex justify-between pt-2 border-t font-bold text-lg text-primary">
                                         <span>Total</span>
                                         <span>{formatCurrency(venda.valor_total)}</span>
                                     </div>
                                    <div className="flex justify-between text-sm pt-2 border-t mt-2">
                                        <span className="text-muted-foreground">Status</span>
                                        <span className={financeiro.isPaid ? 'text-emerald-700 font-semibold' : 'text-amber-700 font-semibold'}>
                                            {financeiro.displayStatus}
                                        </span>
                                    </div>
                                    <div className="flex justify-between text-sm">
                                        <span className="text-muted-foreground">Total pago</span>
                                        <span>{formatCurrency(financeiro.valorPago)}</span>
                                    </div>
                                    <div className="flex justify-between text-sm">
                                        <span className="text-muted-foreground">Saldo restante</span>
                                        <span className={financeiro.valorRestante > 0 ? 'text-amber-700 font-semibold' : 'text-emerald-700 font-semibold'}>
                                            {financeiro.valorRestante > 0 ? formatCurrency(financeiro.valorRestante) : '-'}
                                        </span>
                                    </div>

                                    {/* Pagamentos */}
                                    {Array.isArray(venda.pagamentos) && venda.pagamentos.length > 0 && (
                                        <div className="mt-4 pt-4 border-t space-y-2">
                                            <p className="text-xs font-semibold text-muted-foreground uppercase text-center mb-2">Formas de Pagamento</p>
                                            {venda.pagamentos.map((pag, idx) => (
                                                <div key={idx} className="flex justify-between items-center bg-background p-2 rounded-lg border text-sm">
                                                    <span className="font-medium">{pag.forma_pagamento || pag.forma || '-'}</span>
                                                    <span className="font-semibold text-primary">{formatCurrency(pag.valor)}</span>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            </section>

                            {/* Logística e Observações */}
                            <div className="space-y-6">
                                <section>
                                    <h3 className="text-lg font-semibold flex items-center gap-2 mb-4 text-primary">
                                        <Truck className="h-5 w-5" />
                                        Logística
                                    </h3>
                                    <div className="space-y-3 bg-muted/10 p-4 rounded-xl border">
                                        <div className="flex flex-wrap gap-2">
                                            {resumoLogistico.composicao.length > 0 ? resumoLogistico.composicao.map((grupo) => (
                                                <Badge key={grupo.key} variant="outline" className={TONE_CLASSES[grupo.tone] || TONE_CLASSES.blue}>
                                                    {grupo.count} {grupo.label}
                                                </Badge>
                                            )) : (
                                                <span className="text-xs text-muted-foreground italic">Sem composição logística informada</span>
                                            )}
                                        </div>
                                        <div className="grid grid-cols-1 gap-3 text-sm md:grid-cols-2">
                                            <div className="rounded-lg border bg-background p-3">
                                                <p className="text-[10px] font-bold uppercase text-muted-foreground">Composição</p>
                                                <div className="mt-2 flex items-center gap-2 font-medium">
                                                    <Truck className="h-4 w-4 text-blue-500" />
                                                    {resumoLogistico.headline}
                                                </div>
                                                {resumoLogistico.isMisto && (
                                                    <p className="mt-2 text-xs text-muted-foreground">
                                                        Este pedido combina itens para entrega e retirada no mesmo número.
                                                    </p>
                                                )}
                                            </div>
                                            <div className="rounded-lg border bg-background p-3">
                                                <p className="text-[10px] font-bold uppercase text-muted-foreground">Status operacional</p>
                                                {entregaAtual ? (
                                                    <div className="mt-2 space-y-1 text-sm">
                                                        <div className="font-medium">{entregaAtual.status || '-'}</div>
                                                        <div className="text-xs text-muted-foreground">
                                                            {entregaAtual.data_realizada
                                                                ? `Concluído em ${format(new Date(entregaAtual.data_realizada), "dd/MM/yyyy HH:mm", { locale: ptBR })}`
                                                                : entregaAtual.data_agendada
                                                                    ? `Agendado para ${format(new Date(entregaAtual.data_agendada), "dd/MM/yyyy", { locale: ptBR })}`
                                                                    : 'Sem data operacional'}
                                                        </div>
                                                        <div className="text-xs text-muted-foreground">
                                                            {entregaAtual.endereco_entrega || 'Retirada na loja'}
                                                        </div>
                                                    </div>
                                                ) : (
                                                    <span className="mt-2 block text-xs text-muted-foreground italic">Sem entrega vinculada</span>
                                                )}
                                                {(resumoLogistico.contagens.montagemInterna > 0 || resumoLogistico.contagens.montagemExterna > 0) && (
                                                    <div className="mt-3 flex items-center gap-2 text-xs">
                                                        <Wrench className="h-3.5 w-3.5 text-orange-500" />
                                                        <span>{resumoLogistico.montagensConcluidas ? 'Montagens concluídas' : 'Montagens pendentes'}</span>
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                        {resumoLogistico.gruposDetalhados.length > 0 && (
                                            <div className="grid grid-cols-1 gap-3 lg:grid-cols-2">
                                                {resumoLogistico.gruposDetalhados.map((grupo) => (
                                                    <div key={grupo.key} className="rounded-lg border bg-background p-3">
                                                        <p className={`text-xs font-bold uppercase ${TONE_CLASSES[grupo.tone] || TONE_CLASSES.blue}`}>
                                                            {grupo.label}
                                                        </p>
                                                        <div className="mt-2 space-y-1.5 text-sm text-muted-foreground">
                                                            {grupo.items.map((item, index) => (
                                                                <p key={`${grupo.key}-${index}`}>{item.resumoItem}</p>
                                                            ))}
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </section>

                                {fotosEntrega.length > 0 && (
                                    <section>
                                        <h3 className="text-lg font-semibold flex items-center gap-2 mb-4 text-primary">
                                            <Package className="h-5 w-5" />
                                            Fotos da Entrega
                                        </h3>
                                        <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                                            {fotosEntrega.map((foto, index) => (
                                                <div key={`${foto.url}-${index}`} className="overflow-hidden rounded-xl border bg-muted/20 p-2">
                                                    <img
                                                        src={foto.url}
                                                        alt={foto.tipo || `Foto da entrega ${index + 1}`}
                                                        className="h-48 w-full rounded-lg object-cover"
                                                    />
                                                    <p className="mt-2 text-xs font-medium text-muted-foreground">
                                                        {foto.tipo || `Foto ${index + 1}`}
                                                    </p>
                                                </div>
                                            ))}
                                        </div>
                                    </section>
                                )}

                                {venda.observacoes && (
                                    <section>
                                        <h3 className="text-lg font-semibold flex items-center gap-2 mb-4 text-primary">
                                            <MessageSquare className="h-5 w-5" />
                                            Observações
                                        </h3>
                                        <div className="bg-amber-50/50 p-4 rounded-xl border border-amber-100 text-sm text-amber-900 italic">
                                            {venda.observacoes}
                                        </div>
                                    </section>
                                )}

                                {venda.conferencia_caixa_status === 'devolvido' && venda.conferencia_caixa_observacao && (
                                    <section>
                                        <h3 className="text-lg font-semibold flex items-center gap-2 mb-4 text-orange-700">
                                            <AlertTriangle className="h-5 w-5" />
                                            Devolvido pelo Caixa
                                        </h3>
                                        <div className="bg-orange-50 p-4 rounded-xl border border-orange-100 text-sm text-orange-950">
                                            <p className="font-semibold text-xs text-orange-800 uppercase tracking-wider mb-1">Motivo da Devolução</p>
                                            <p className="italic">"{venda.conferencia_caixa_observacao}"</p>
                                            {venda.conferencia_caixa_por && (
                                                <p className="text-[10px] text-orange-500 mt-2 font-medium">
                                                    Por: {venda.conferencia_caixa_por} {venda.conferencia_caixa_at ? `em ${format(new Date(venda.conferencia_caixa_at), "dd/MM/yyyy HH:mm", { locale: ptBR })}` : ''}
                                                </p>
                                            )}
                                        </div>
                                    </section>
                                )}

                                {venda.conferencia_caixa_status === 'aprovado' && (
                                    <section>
                                        <h3 className="text-lg font-semibold flex items-center gap-2 mb-4 text-green-700">
                                            <ShieldCheck className="h-5 w-5" />
                                            Conferência de Caixa Realizada
                                        </h3>
                                        <div className="bg-green-50 p-4 rounded-xl border border-green-100 text-sm text-green-950">
                                            <p className="font-semibold text-xs text-green-800 uppercase tracking-wider mb-1">Status</p>
                                            <p>O pagamento deste pedido foi conferido e aprovado pelo caixa.</p>
                                            {venda.conferencia_caixa_observacao && (
                                                <p className="mt-2 text-xs italic text-green-800">
                                                    Observação: "{venda.conferencia_caixa_observacao}"
                                                </p>
                                            )}
                                            {venda.conferencia_caixa_por && (
                                                <p className="text-[10px] text-green-600 mt-2 font-medium">
                                                    Por: {venda.conferencia_caixa_por} {venda.conferencia_caixa_at ? `em ${format(new Date(venda.conferencia_caixa_at), "dd/MM/yyyy HH:mm", { locale: ptBR })}` : ''}
                                                </p>
                                            )}
                                        </div>
                                    </section>
                                )}
                            </div>
                        </div>
                    </div>
                </ScrollArea>
            </DialogContent>
        </Dialog>
    );
}

