    responsavel_nome: "",
    cliente_id: "",
    cliente_nome: "",
    cliente_telefone: "",
    itens: [],
    valor_total: 0,
    pagamentos: [], // Array de múltiplos pagamentos
    valor_pago: 0,
    valor_restante: 0,
    comissao_calculada: 0,
    porcentagem_comissao: 0,
    prazo_entrega: "15 dias úteis",
    status: "Pagamento Pendente",
    desconto: 0,
    observacoes: "",
