/**
 * Calcula as permissoes efetivas de um usuario
 * Combina ROLE_RULES do cargo com custom_permissions do usuario
 * 
 * @param {Object} user - Usuario com cargo e custom_permissions
 * @returns {Object} { permissions: string[], scope: string }
 */
export function getUserEffectivePermissions(user) {
  if (!user) return { permissions: [], scope: SCOPES.OWN };

  const roles = getUserRoles(user);
  const roleRulesList = roles.map((role) => ROLE_RULES[role]).filter(Boolean);
  const fallbackRules = ROLE_RULES['Vendedor'];
  const effectiveRoleRules = roleRulesList.length > 0 ? roleRulesList : [fallbackRules];

  // Administrador tem acesso total
  if (effectiveRoleRules.some((rules) => rules.can.includes('*'))) {
    return {
      permissions: ['*'],
      scope: SCOPES.ALL
    };
  }

  // Pega permissoes base da uniao de cargos
  let basePermissions = Array.from(new Set(effectiveRoleRules.flatMap((rules) => rules.can)));

  // Aplica custom_permissions se existir
  const custom = user.custom_permissions;
  if (custom && typeof custom === 'object') {
    // Se nao herda do cargo, comeca do zero
    if (custom.inherit === false) {
      basePermissions = [];
    }

    // Adiciona permissoes allowed
    if (Array.isArray(custom.allowed)) {
      custom.allowed.forEach(p => {
        if (!basePermissions.includes(p)) {
          basePermissions.push(p);
        }
      });
    }

    // Remove permissoes denied
    if (Array.isArray(custom.denied)) {
      basePermissions = basePermissions.filter(p => !custom.denied.includes(p));
    }
  }

  return {
    permissions: basePermissions,
    scope: getHighestScope(effectiveRoleRules.map((rules) => rules.scope))
  };
}

/**
 * Verifica se usuario tem uma permissao especifica
 * @param {Object} user - Usuario
 * @param {string} permission - Permissao a verificar
 * @returns {boolean}
 */
export function userCan(user, permission) {
  if (Array.isArray(permission)) {
    return permission.some((item) => userCan(user, item));
  }

  const { permissions } = getUserEffectivePermissions(user);

  // Wildcard tem acesso total
  if (permissions.includes('*')) return true;

  // Permissao especifica
  return permissions.includes(permission);
}

/** Verifica se o registro pertence ao usuario (created_by, vendedor_id, etc.) */
export function isRecordOwner(user, record, fields = ['created_by']) {
  if (!user || !record) return false;

  return fields.some((field) => {
    const value = record[field];
    if (!value) return false;
    return value === user.id || value === user.email;
  });
}

/** Gerentes editam todos; vendedores apenas clientes que criaram */
export function canEditCliente(user, cliente, canFn) {
  if (!user || !cliente || typeof canFn !== 'function') return false;
  if (canFn('manage_clientes')) return true;
  if (!canFn('create_clientes')) return false;
  return isRecordOwner(user, cliente);
}

/**
 * Retorna os itens de menu visiveis para um usuario
 * @param {Object} user - Usuario
 * @returns {Array} Menu items filtrados
 */
export function getVisibleMenuItems(user) {
  const { permissions } = getUserEffectivePermissions(user);

  return MENU_ITEMS.filter(item => {
    const itemPermissions = Array.isArray(item.permission) ? item.permission : [item.permission];

    // Itens com * sao visiveis para todos
    if (itemPermissions.includes('*')) return true;

    // Admin only items
    if (itemPermissions.includes('admin_only')) {
      return permissions.includes('*');
    }

    // Verifica permissao
    if (permissions.includes('*')) return true;
    return itemPermissions.some((permission) => permissions.includes(permission));
  });
}

/**
 * Retorna todas as permissoes unicas do sistema
 * @returns {Array} Lista de permissoes
 */
export function getAllPermissions() {
  const permSet = new Set();

  MENU_ITEMS.forEach(item => {
    const itemPermissions = Array.isArray(item.permission) ? item.permission : [item.permission];
    itemPermissions.forEach((permission) => {
      if (permission && permission !== '*' && permission !== 'admin_only') {
        permSet.add(permission);
      }
    });
  });

  // Adiciona permissoes extras que nao estao no menu
  Object.values(ROLE_RULES).forEach(rule => {
    rule.can.forEach(p => {
      if (p !== '*') permSet.add(p);
    });
  });

  return Array.from(permSet).sort();
}

/**
 * Retorna o estado de cada permissao para um usuario
 * @param {Object} user - Usuario
 * @returns {Object} { permission: { active: boolean, source: 'role'|'custom_allowed'|'custom_denied' } }
 */
export function getPermissionStates(user) {
  if (!user) return {};

  const roles = getUserRoles(user);
  const roleRulesList = roles.map((role) => ROLE_RULES[role]).filter(Boolean);
  const effectiveRoleRules = roleRulesList.length > 0 ? roleRulesList : [ROLE_RULES['Vendedor']];
  const custom = user.custom_permissions || { inherit: true, allowed: [], denied: [] };
  const allPerms = getAllPermissions();

  const states = {};

  allPerms.forEach(perm => {
    const fromRole = effectiveRoleRules.some((rules) => rules.can.includes('*') || rules.can.includes(perm));
    const inAllowed = Array.isArray(custom.allowed) && custom.allowed.includes(perm);
    const inDenied = Array.isArray(custom.denied) && custom.denied.includes(perm);

    let active = false;
    let source = 'role';

    if (custom.inherit === false) {
      // Nao herda - apenas allowed conta
      active = inAllowed;
      source = inAllowed ? 'custom_allowed' : 'none';
    } else {
      // Herda do cargo
      if (inDenied) {
        active = false;
        source = 'custom_denied';
      } else if (inAllowed) {
        active = true;
        source = 'custom_allowed';
      } else {
        active = fromRole;
        source = 'role';
      }
    }

    states[perm] = { active, source, fromRole };
  });

  return states;
}

import React, { createContext, useContext, useState, useEffect } from 'react';
import { supabase } from '@/lib/supabase';

// Contexto para dados do tenant (organização)
const TenantContext = createContext(null);

// Configurações padrão (fallback)
const DEFAULT_ORGANIZATION = {
    id: '00000000-0000-0000-0000-000000000001',
    name: 'Sistema ERP',
    slug: 'default',
    logo_url: null,
    primary_color: '#07593f',
    secondary_color: '#f38a4c',
};

const DEFAULT_SETTINGS = {
    prazo_entrega_padrao: 7,
    prazo_montagem_padrao: 3,
    taxa_juros_parcelamento: {
        "2x": 0, "3x": 0, "4x": 2.5, "5x": 3, "6x": 3.5,
        "7x": 4, "8x": 4.5, "9x": 5, "10x": 5.5, "11x": 6, "12x": 6.5
    },
    comissao_base_percentual: 3.00,
    comissao_sobre: 'bruto',
    comissao_prioridade_estrategia: 'mais_especifica',
    comissao_recalculo_politica: 'nao_recalcular',
    comissao_modelo_calculo: 'regra_venda',
    comissao_faixa_referencia: 'vendedor',
    comissao_meta_minima_loja_percentual: 0,
    compras_aprovacao_automatica: ['a_vista'],
    conferencia_caixa_enabled: false,
    modulos_ativos: {
        montagem: true,
        assistencia_tecnica: true,
        nfe: true,
        marketing: true,
        rh: true,
        bi_dashboard: true,
        catalogo_whatsapp: true,
        rastreio: true,
        frota: true,
        fotos_entrega: true,
        comissoes: true,
        conferencia_caixa: true,
        markup_automatico: true,
        aprovacao_vendas: true,
        whatsapp: true
    }
};

export function TenantProvider({ children, organizationId, slug: slugProp }) {
    const [organization, setOrganization] = useState(null);
    const [settings, setSettings] = useState(null);
    const [plano, setPlano] = useState(null);
    const [lojas, setLojas] = useState([]);
    const [loading, setLoading] = useState(true);

    const [error, setError] = useState(null);
    const [resolvedOrgId, setResolvedOrgId] = useState(organizationId || null);
    const [isDomainResolved, setIsDomainResolved] = useState(false);

    // Detectar o organization_id: prioridade hostname/domain > slug > organizationId > sessão do usuário > fallback
    useEffect(() => {
        const detectOrganization = async () => {
            // A. Detectar por hostname (domínio customizado ou subdomínio)
            const hostname = window.location.hostname;
            const mainDomains = ['localhost', 'moveis-pedro-ii-hub.vercel.app', 'gesthub.com', 'GestApp.com.br']; // domínios principais do SaaS

            const isMainDomain = mainDomains.includes(hostname) || hostname.endsWith('.vercel.app');

            if (!isMainDomain) {
                try {
                    // 1. Verificar se é um subdomínio (ex: moveis-pedro-ii.gesthub.com)
                    const parts = hostname.split('.');
                    if (parts.length > 2) {
                        const subdomain = parts[0];
                        const { data: orgBySlug } = await supabase
                            .from('organizations')
                            .select('id')
                            .eq('slug', subdomain)
                            .maybeSingle();

                        if (orgBySlug?.id) {
                            setResolvedOrgId(orgBySlug.id);
                            setIsDomainResolved(true);
                            return;
                        }
                    }

                    // 2. Verificar se é um domínio customizado completo (ex: portal.moveispedroii.com.br)
                    const { data: orgByDomain } = await supabase
                        .from('organizations')
                        .select('id')
                        .eq('custom_domain', hostname)
                        .maybeSingle();

                    if (orgByDomain?.id) {
                        setResolvedOrgId(orgByDomain.id);
                        setIsDomainResolved(true);
                        return;
                    }
                } catch (err) {
                    console.warn('[Tenant] Erro ao resolver tenant por hostname:', hostname, err);
                }
            }

            // B. Se um slug foi passado (rota pública/path-based), resolver por slug
            if (slugProp) {
                try {
                    const { data: orgBySlug } = await supabase
                        .from('organizations')
                        .select('id')
                        .eq('slug', slugProp)
                        .maybeSingle();

                    if (orgBySlug?.id) {
                        setResolvedOrgId(orgBySlug.id);
                        setIsDomainResolved(false);
                        return;
                    }
                } catch (err) {
                    console.warn('[Tenant] Erro ao resolver slug:', slugProp, err);
                }
                // Slug inválido — cai no fallback abaixo
            }

            // C. Se um organizationId foi passado explicitamente, usar ele
            if (organizationId) {
                setResolvedOrgId(organizationId);
                return;
            }

            // D. Tentar detectar via sessão do usuário logado
            try {
                const { data: { session } } = await supabase.auth.getSession();
                if (session?.user) {
                    const { data: profile } = await supabase
                        .from('public_users')
                        .select('organization_id')
                        .eq('id', session.user.id)
                        .maybeSingle();

                    if (profile?.organization_id) {
                        setResolvedOrgId(profile.organization_id);
                        return;
                    }
                }
            } catch (err) {
                console.warn('[Tenant] Erro ao detectar organização do usuário:', err);
            }

            // E. Fallback: ID padrão (retrocompatibilidade)
            setResolvedOrgId('00000000-0000-0000-0000-000000000001');
        };

        detectOrganization();

        // Reagir a mudanças de autenticação (login/logout) — apenas se não tem slug fixo ou domínio resolvido
        if (!slugProp && !isDomainResolved) {
            const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
                if (!session) {
                    // Logout — voltar ao padrão
                    setResolvedOrgId('00000000-0000-0000-0000-000000000001');
                } else {
                    // Novo login — detectar novamente
                    detectOrganization();
                }
            });

            return () => subscription?.unsubscribe();
        }
    }, [organizationId, slugProp, isDomainResolved]);

    useEffect(() => {
        if (resolvedOrgId) {
            loadTenantData();
        }
    }, [resolvedOrgId]);

    useEffect(() => {
        if (organization) {
            // Se estiver na rota de operador, ignorar títulos e favicons do tenant
            if (window.location.pathname.startsWith('/operador')) {
                return;
            }

            const orgName = organization.name || '';
            const isDefaultOrg = orgName.toLowerCase().includes('pedro ii');
            
            document.title = orgName && !isDefaultOrg
                ? `${orgName} - GestApp` 
                : 'GestApp';

            // Remove favicons antigos se existirem para evitar duplicidade
            const existingLinks = document.querySelectorAll("link[rel~='icon']");
            existingLinks.forEach(link => link.remove());

            // Cria o novo favicon do tenant (se for org padrão, usa o favicon.svg do GestApp)
            if (!isDefaultOrg && organization.logo_url && !organization.logo_url.includes('mp2logo.png')) {
                const logoUrl = `${organization.logo_url}?v=${new Date().getTime()}`;
                const link = document.createElement('link');
                link.rel = 'icon';
                link.type = 'image/png';
                link.href = logoUrl;
                document.getElementsByTagName('head')[0].appendChild(link);
            } else {
                const link = document.createElement('link');
                link.rel = 'icon';
                link.type = 'image/svg+xml';
                link.href = '/favicon.svg?v=2';
                document.getElementsByTagName('head')[0].appendChild(link);
            }
        }
    }, [organization]);

    const loadTenantData = async () => {
        try {
            setLoading(true);
            setError(null);

            const orgId = resolvedOrgId || '00000000-0000-0000-0000-000000000001';

            // Carregar organização
            const { data: orgData, error: orgError } = await supabase
                .from('organizations')
                .select('*')
                .eq('id', orgId)
                .single();

            if (orgError) {
                console.warn('Erro ao carregar organização, usando padrão:', orgError);
                setOrganization(DEFAULT_ORGANIZATION);
                setPlano(null);
                try { localStorage.setItem('current_organization_id', DEFAULT_ORGANIZATION.id); } catch (_) {}
            } else {
                setOrganization(orgData);
                try { localStorage.setItem('current_organization_id', orgData.id); } catch (_) {}
                if (orgData?.plano_id) {
                    const { data: pData } = await supabase
                        .from('planos')
                        .select('*')
                        .eq('id', orgData.plano_id)
                        .maybeSingle();
                    setPlano(pData || null);
                } else {
                    setPlano(null);
                }
            }


            // Carregar configurações
            const { data: settingsData, error: settingsError } = await supabase
                .from('organization_settings')
                .select('*')
                .eq('organization_id', orgId)
                .single();

            if (settingsError) {
                console.warn('Erro ao carregar settings, usando padrão:', settingsError);
                setSettings(DEFAULT_SETTINGS);
            } else {
                setSettings(settingsData);
            }

            // Carregar lojas
            const { data: lojasData, error: lojasError } = await supabase
                .from('lojas')
                .select('*')
                .eq('organization_id', orgId)
                .eq('is_active', true)
                .order('nome');

            if (lojasError) {
                console.warn('Erro ao carregar lojas:', lojasError);
                setLojas([]);
            } else {
                setLojas(lojasData || []);
            }

        } catch (err) {
            console.error('Erro ao carregar dados do tenant:', err);
            setError(err);
            // Usar valores padrão em caso de erro
            setOrganization(DEFAULT_ORGANIZATION);
            setSettings(DEFAULT_SETTINGS);
        } finally {
            setLoading(false);
        }
    };

    // Verificar se um módulo é permitido pelo plano de assinatura da empresa
    const isModuleAllowedByPlan = (moduleName) => {
        if (!plano || !plano.recursos) return true; // sem plano específico ou recursos = liberado
        if (Object.prototype.hasOwnProperty.call(plano.recursos, moduleName)) {
            return plano.recursos[moduleName] !== false;
        }
        return true;
    };

    // Verificar se um módulo está ativo (considerando trava do plano E opção da empresa)
    const isModuleActive = (moduleName) => {
        if (!isModuleAllowedByPlan(moduleName)) return false;
        if (!settings?.modulos_ativos) return true;
        return settings.modulos_ativos[moduleName] !== false;
    };


    // Verificar se um módulo PAGO está ativo (padrão: DESATIVADO se ausente)
    // Usar esta função para módulos que geram custo real: 'whatsapp', 'fotos_entrega'
    // Diferença do isModuleActive: chave ausente = bloqueado (fail-safe)
    const isPaidModuleActive = (moduleName) => {
        if (!settings?.modulos_ativos) return false; // sem settings = desativado
        return settings.modulos_ativos[moduleName] === true;
    };

    // Obter taxa de juros para parcelas
    const getJurosParcela = (parcelas) => {
        if (!settings?.taxa_juros_parcelamento) return 0;
        return settings.taxa_juros_parcelamento[`${parcelas}x`] || 0;
    };

    const value = {
        organization,
        settings,
        plano,
        lojas,
        loading,
        error,
        isModuleActive,
        isModuleAllowedByPlan,
        isPaidModuleActive,
        getJurosParcela,
        isDomainResolved,
        refreshTenant: loadTenantData,

        // Flag de Conferência de Caixa
        conferenciaCaixaEnabled: settings?.conferencia_caixa_enabled === true,
        // Helpers para branding
        brandName: organization?.name || DEFAULT_ORGANIZATION.name,
        brandLogo: organization?.logo_url || DEFAULT_ORGANIZATION.logo_url,
        primaryColor: organization?.primary_color || DEFAULT_ORGANIZATION.primary_color,
        secondaryColor: organization?.secondary_color || DEFAULT_ORGANIZATION.secondary_color,
    };

    return (
        <TenantContext.Provider value={value}>
            {children}
        </TenantContext.Provider>
    );
}

// Hook para usar o contexto do tenant
export function useTenant() {
    const context = useContext(TenantContext);
    if (!context) {
        console.warn('useTenant deve ser usado dentro de um TenantProvider');
        // Retornar valores padrão para evitar quebrar o app
        return {
            organization: DEFAULT_ORGANIZATION,
            settings: DEFAULT_SETTINGS,
            lojas: [],
            loading: false,
            error: null,
            isModuleActive: () => true,
            isPaidModuleActive: () => false, // Fail-safe: sem contexto = desativado
            getJurosParcela: () => 0,
            refreshTenant: () => { },
            conferenciaCaixaEnabled: false,
            brandName: DEFAULT_ORGANIZATION.name,
            brandLogo: DEFAULT_ORGANIZATION.logo_url,
