import { useEffect, useRef } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';
import { supabase } from '@/lib/supabase';
import { base44 } from '@/api/base44Client';

/**
 * Hook para monitorar estoque mínimo e criar encomendas automaticamente
 * Roda em background verificando a cada 5 minutos
 * 
 * @param {string} lojaId - ID da loja para filtrar alertas (opcional)
 * @param {boolean} enabled - Se deve ativar o monitoramento
 * @returns {Object} { alertasAtivos, isChecking, ultimaVerificacao }
 */
export function useAlertasEstoque(lojaId = null, enabled = true) {
  const queryClient = useQueryClient();
  const intervalRef = useRef(null);
  const ultimaVerificacaoRef = useRef(null);

  // Query: Alertas de Recompra
  const { data: alertas = [] } = useQuery({
    queryKey: ['alertas_recompra'],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('alertas_recompra')
        .select('*')
        .eq('habilitado', true);

      if (error) {
        console.error('[useAlertasEstoque] Erro ao buscar alertas:', error);
        return [];
      }
      return data || [];
    },
    enabled,
    staleTime: 10 * 60 * 1000, // 10 minutos
  });

  // Query: Estoque por Loja
  const { data: estoqueLojas = [] } = useQuery({
    queryKey: ['estoque_loja'],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('estoque_loja')
        .select('*');

      if (error) {
        console.error('[useAlertasEstoque] Erro ao buscar estoque:', error);
        return [];
      }
      return data || [];
    },
    enabled,
    staleTime: 5 * 60 * 1000, // 5 minutos
  });

  // Mutation: Criar SolicitacaoEncomenda
  const criarEncomendaMutation = useMutation({
    mutationFn: async (dados) => {
      const { produto_id, produto_nome, fornecedor_id, quantidade_sugerida } = dados;

      // Buscar ou criar SolicitacaoEncomenda
      const { data: existente } = await supabase
        .from('solicitacoes_encomenda')
        .select('*')
        .eq('produto_id', produto_id)
        .in('status', ['pendente', 'Pendente', 'aguardando_compra', 'em_compra'])
        .limit(1)
        .single();

      if (existente) {
        console.log(`[useAlertasEstoque] SolicitacaoEncomenda já existe para produto ${produto_id}`);
        return existente;
      }

      return await base44.entities.SolicitacaoEncomenda.create({
        produto_id,
        produto_nome,
        fornecedor_id,
        quantidade: quantidade_sugerida,
        status: 'pendente',
        data_criacao: new Date().toISOString(),
        motivo: 'Alerta automático - estoque mínimo atingido',
      });
    },
    onSuccess: (data, variables) => {
      toast.success(`Encomenda criada automaticamente para ${variables.produto_nome}`);
      queryClient.invalidateQueries({ queryKey: ['solicitacoes_encomenda'] });
    },
    onError: (error) => {
      console.error('[useAlertasEstoque] Erro ao criar encomenda:', error);
      toast.error('Erro ao criar encomenda automática');
    },
  });

  // Função para verificar alertas e criar encomendas
  const verificarAlertas = async () => {
    try {
      const agora = new Date();
      ultimaVerificacaoRef.current = agora;

      console.log('[useAlertasEstoque] Verificando alertas de estoque mínimo...');

      for (const alerta of alertas) {
        // Filtrar por loja se especificado
        const estoqueLoja = estoqueLojas.find(
          e => e.produto_id === alerta.produto_id && 
               (!lojaId || e.loja_id === lojaId)
        );

        if (!estoqueLoja) {
          // Produto não tem registro de estoque em nenhuma loja
          console.warn(`[useAlertasEstoque] Produto ${alerta.produto_id} não tem estoque registrado`);
          continue;
        }

        const quantidadeAtual = estoqueLoja.quantidade || 0;
        const estoque_minimo = alerta.estoque_minimo || 0;

        if (quantidadeAtual < estoque_minimo) {
          console.log(
            `[useAlertasEstoque] ALERTA: Produto ${alerta.produto_id} abaixo do mínimo (${quantidadeAtual} < ${estoque_minimo})`
          );

          // Calcular quantidade sugerida (mínimo * 2 como padrão)
          const quantidade_sugerida = estoque_minimo * 2;

          // Criar encomenda
          criarEncomendaMutation.mutate({
            produto_id: alerta.produto_id,
            produto_nome: alerta.produto_nome,
            fornecedor_id: alerta.fornecedor_id,
            quantidade_sugerida,
          });
        }
      }
    } catch (error) {
      console.error('[useAlertasEstoque] Erro durante verificação:', error);
    }
  };

  // Efeito: Verificar alertas a cada 5 minutos
  useEffect(() => {
    if (!enabled || alertas.length === 0) {
      return;
    }

    // Verificar imediatamente
    verificarAlertas();

    // Agendar verificações periódicas (5 minutos)
    intervalRef.current = setInterval(() => {
      verificarAlertas();
    }, 5 * 60 * 1000);

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, [enabled, alertas, estoqueLojas]);

  // Encontrar alertas ativos (produtos com estoque < mínimo)
  const alertasAtivos = alertas.filter(alerta => {
    const estoque = estoqueLojas.find(
      e => e.produto_id === alerta.produto_id && (!lojaId || e.loja_id === lojaId)
    );
    return estoque && estoque.quantidade < alerta.estoque_minimo;
  });

  return {
    alertasAtivos,
    totalAlertas: alertasAtivos.length,
    isChecking: criarEncomendaMutation.isPending,
    ultimaVerificacao: ultimaVerificacaoRef.current,
    verificarAgora: verificarAlertas,
  };
}

import { useState, useEffect, createContext, useContext } from "react";
import { base44, supabase } from "@/api/base44Client";
import { getActiveAuthMode, setActiveAuthMode, clearActiveAuthMode, AUTH_MODES } from "@/lib/supabase";
import { ROLE_RULES, SCOPES, userCan, getUserRoles, getHighestScope, hasRole, getUserEffectivePermissions } from "@/config/permissions";
import { canAccessLojaId, filterDataByLoja } from "@/lib/utils";

const AuthContext = createContext(null);

function normalizeUserRoles(user) {
  const roles = getUserRoles(user);
  return {
    ...user,
    cargos: roles,
    // Preserva cargo legado; não sobrescreve com default de roles para não
    // dar cargo a clientes sem cargo atribuído.
    cargo: user?.cargo || null
  };
}

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [cargoPermissoes, setCargoPermissoes] = useState(null);
  const [authType, setAuthType] = useState(null); // 'employee' | 'supabase' | null
  const [authError, setAuthError] = useState(null);
  const [authAttempt, setAuthAttempt] = useState(0);

  // Admin Store Selection State
  const [selectedStore, setSelectedStoreState] = useState(() => {
    return localStorage.getItem('admin_selected_store') || null;
  });

  const setSelectedStore = (store) => {
    setSelectedStoreState(store);
    if (store) {
      localStorage.setItem('admin_selected_store', store);
    } else {
      localStorage.removeItem('admin_selected_store');
    }
  };

  const getMergedRolePermissions = (roles = [], rawRolePermissions = []) => {
    const allPermissions = new Set();
    for (const role of roles) {
      const dbRow = rawRolePermissions.find(r => r.cargo === role);
      // Base: hardcoded ROLE_RULES (fallback when no DB row exists)
      (ROLE_RULES[role]?.can || []).forEach(p => allPermissions.add(p));
      if (dbRow) {
        // Explicitly added permissions (extras beyond ROLE_RULES)
        (dbRow.permissions || []).forEach(p => allPermissions.add(p));
        // Explicitly denied permissions (removed from ROLE_RULES)
        (dbRow.denied_permissions || []).forEach(p => allPermissions.delete(p));
      }
    }
    return Array.from(allPermissions);
  };

  useEffect(() => {
    let mounted = true;

    const isTimeoutError = (error) => {
      return error?.message?.includes('Timeout em');
    };

    const startLoadingFailsafe = () => {
      return setTimeout(() => {
        if (mounted) {
          console.warn('[Auth] Failsafe acionado: finalizando loading para evitar tela travada.');
          setLoading(false);
        }
      }, 10000);
    };

    const withTimeout = async (promise, ms, label) => {
      let timeoutId;
      const timeoutPromise = new Promise((_, reject) => {
        timeoutId = setTimeout(() => reject(new Error(`Timeout em ${label}`)), ms);
      });

      try {
        return await Promise.race([promise, timeoutPromise]);
      } finally {
        clearTimeout(timeoutId);
      }
    };

    // Flag interna: se o usuário já foi autenticado, timeouts subsequentes
    // (ex.: permissões, base44.auth.me em Strict Mode) NÃO devem gerar authError.
    let userAlreadyResolved = false;

    const loadPermissionsForUser = async (targetUser) => {
      try {
        const rolePermissions = await withTimeout(
          base44.entities.RolePermission.list(),
          10000,
          'RolePermission.list'
        );
        const roles = getUserRoles(targetUser);
        // Filter DB rows matching the user's roles
        const userRoleRows = rolePermissions.filter(c => roles.includes(c.cargo));
        const permissions = getMergedRolePermissions(roles, userRoleRows);

        if (permissions.length > 0 && mounted) {
          // Scope: prefer DB scope (supports custom cargos), fallback to ROLE_RULES
          const scopePerRole = roles.map(role => {
            const dbRow = userRoleRows.find(r => r.cargo === role);
            return dbRow?.scope || ROLE_RULES[role]?.scope || SCOPES.OWN;
          });
          setCargoPermissoes({
            can: permissions,
            scope: getHighestScope(scopePerRole)
          });
        }
      } catch (e) {
        // Permissões são não-críticas: fallback hardcoded já cobre.
        // NÃO setar authError aqui — o usuário já foi autenticado com sucesso.
        console.warn('[Auth] Usando permissões hardcoded (fallback)', e);
      }
    };

    // Função auxiliar para carregar o perfil completo (Supabase)
    const loadSupabaseProfile = async (sessionUser) => {
      try {
        if (!sessionUser) {
          return null;
        }

        const { data: u, error: profileError } = await supabase
          .from('public_users')
          .select('*')
          .eq('id', sessionUser.id)
          .maybeSingle();

        if (profileError && profileError.code !== 'PGRST116') {
          console.error('Erro ao buscar perfil:', profileError);
        }

        // Mescla dados da sessão com dados do perfil e normaliza cargos
        const fullUser = u ? { ...sessionUser, ...u } : sessionUser;
        return normalizeUserRoles(fullUser);
      } catch (err) {
        console.error('Erro ao carregar perfil Supabase:', err);
        return sessionUser;
      }
    };

    // Função para verificar autenticação de funcionário (agora via Supabase direto)
    const checkEmployeeAuth = async () => {
      // Verifica se há dados de usuário em localStorage (cache do login)
      const cachedUser = localStorage.getItem('employee_user');
      if (!cachedUser) return null;

      try {
        // Valida que o cache é JSON v\u00e1lido antes de prosseguir (cache corrompido = limpar e sair)
        JSON.parse(cachedUser);

        const parsedCachedUser = normalizeUserRoles(JSON.parse(cachedUser));

        // Verificar se ainda tem sessão Supabase ativa (com timeout)
        const { data: { session } } = await withTimeout(
          supabase.auth.getSession(),
          8000,
          'supabase.auth.getSession'
        );

        if (!session) {
          // Sessão expirada, limpar cache
          localStorage.removeItem('employee_user');
          return null;
        }

        // Buscar perfil atualizado do banco para garantir dados recentes
        let userProfile = null;
        let error = null;
        try {
          const profileResponse = await withTimeout(
            supabase
              .from('public_users')
              .select('*')
              .eq('id', session.user.id)
              .maybeSingle(),
            15000,
            'public_users.profile'
          );
          userProfile = profileResponse?.data || null;
          error = profileResponse?.error || null;
        } catch (profileTimeoutError) {
          console.warn('[Auth] Timeout ao buscar perfil, usando cache local.', profileTimeoutError);
          return normalizeUserRoles({
            ...session.user,
            ...parsedCachedUser,
            full_name: parsedCachedUser.full_name || parsedCachedUser.matricula || session.user.email
          });
        }

        if (error || !userProfile) {
          console.warn('[Auth] Perfil não encontrado no banco');
          return normalizeUserRoles({
            ...session.user,
            ...parsedCachedUser,
            full_name: parsedCachedUser.full_name || parsedCachedUser.matricula || session.user.email
          });
        }

        if (!userProfile.ativo) {
          console.warn('[Auth] Usuário inativo');
          localStorage.removeItem('employee_user');
          await supabase.auth.signOut();
          return null;
        }

        // Atualizar cache com dados atualizados
        localStorage.setItem('employee_user', JSON.stringify(userProfile));

        return normalizeUserRoles({
          ...session.user,
          ...userProfile,
          full_name: userProfile.full_name || userProfile.matricula
        });
      } catch (e) {
        console.error("Erro ao verificar auth de funcionário:", e);
        try {
          const parsedCachedUser = JSON.parse(cachedUser);
          if (isTimeoutError(e)) {
            console.warn('[Auth] Timeout ao validar sessão remota, mantendo cache local temporariamente.');
          } else {
            console.warn('[Auth] Falha na validação remota, mantendo cache local temporariamente.');
          }
          return normalizeUserRoles(parsedCachedUser);
        } catch {
          localStorage.removeItem('employee_user');
          return null;
        }
      }
    };

    // Carrega estado inicial
    const initAuth = async () => {
      console.log('[Auth] Iniciando verificação de autenticação...');

      try {
        if (mounted) {
          setAuthError(null);
        }

        // Limpar token legado do backend (não mais utilizado)
        if (localStorage.getItem('employee_token')) {
          console.log('[Auth] Removendo token legado do backend...');
          localStorage.removeItem('employee_token');
        }

        // ISOLAMENTO: Se o modo ativo é 'operator', não carregar perfil de tenant
        const currentMode = getActiveAuthMode();
        if (currentMode === AUTH_MODES.OPERATOR) {
          console.log('[Auth] Modo operador ativo. Ignorando sessão de tenant.');
          if (mounted) {
            setUser(null);
            setLoading(false);
          }
          return;
        }

        // 1. Primeiro verifica se há cache de funcionário
        const hasCachedUser = localStorage.getItem('employee_user');

        if (hasCachedUser) {
          console.log('[Auth] Cache de funcionário encontrado, verificando...');
          const employeeUser = await checkEmployeeAuth();

          if (employeeUser && mounted) {
            console.log('[Auth] ✅ Funcionário autenticado:', employeeUser.full_name, '- Cargos:', employeeUser.cargos?.join(', ') || employeeUser.cargo);
            userAlreadyResolved = true;
            setAuthType('employee');
            setUser(employeeUser);
            setLoading(false);

            // Carrega permissões sem bloquear navegação inicial
            void loadPermissionsForUser(employeeUser);

            return;
          } else {
            console.log('[Auth] ⚠️ Cache inválido ou sessão expirada');
          }
        }

        // 2. Se não tem funcionário logado, verifica Supabase Auth (para clientes)
        console.log('[Auth] Verificando autenticação Supabase...');
        const supabaseUser = await withTimeout(
          base44.auth.me(),
          15000,
          'base44.auth.me'
        );

        if (supabaseUser && mounted) {
          const fullProfile = await loadSupabaseProfile(supabaseUser);

          if (fullProfile) {
            console.log('[Auth] Supabase user encontrado:', fullProfile.email, '- Cargos:', fullProfile.cargos?.join(', ') || fullProfile.cargo || 'Nenhum');
            setAuthType('supabase');
            setUser(fullProfile);

            // Buscar permissões dos cargos se existir
            if (fullProfile.cargos?.length || fullProfile.cargo) {
              void loadPermissionsForUser(fullProfile);
            }
          }
        }
      } catch (error) {
        console.error('[Auth] Erro durante initAuth:', error);
        // Só exibe tela de erro se o usuário ainda não foi resolvido com sucesso.
        // Em React Strict Mode, o useEffect pode rodar duas vezes; a segunda
        // invocação pode dar timeout enquanto a primeira já autenticou o user.
        if (isTimeoutError(error) && mounted && !userAlreadyResolved) {
          setUser(null);
          setCargoPermissoes(null);
          setAuthType(null);
          setAuthError({
            code: 'auth-timeout',
            source: error?.message?.replace('Timeout em ', '') || 'auth',
            message: 'Nao foi possivel validar sua sessao dentro do tempo esperado. Tente novamente em instantes.'
          });
        }
      } finally {
        if (mounted) {
          setLoading(false);
        }
      }
    };

    const failsafeId = startLoadingFailsafe();
    initAuth().finally(() => clearTimeout(failsafeId));

    // Inscreve para mudanças no Supabase Auth
    const { data: { subscription } } = base44.auth.onAuthStateChange?.((event, session) => {
      if (event === 'SIGNED_OUT' && authType === 'supabase') {
        setUser(null);
        setCargoPermissoes(null);
        setAuthType(null);
        setLoading(false);
        localStorage.removeItem('admin_selected_store'); // Limpa seleção ao sair
      } else if ((event === 'SIGNED_IN' || event === 'TOKEN_REFRESHED') && !localStorage.getItem('employee_user')) {
        // Só atualiza se não estiver logado como funcionário E se não estiver em modo operador
        if (getActiveAuthMode() === AUTH_MODES.OPERATOR) return;
        loadSupabaseProfile(session?.user).then(profile => {
          if (mounted && profile) {
            setAuthType('supabase');
            setUser(profile);
          }
        });
      }
    }) || { data: { subscription: null } };

    return () => {
      mounted = false;
      subscription?.unsubscribe();
    };
  }, [authAttempt]);

  // Sync effect: If user has fixed store, force selectedStore to match
  useEffect(() => {
    if (user?.loja) {
      if (selectedStore !== user.loja) {
        setSelectedStoreState(user.loja);
        localStorage.setItem('admin_selected_store', user.loja);
      }
    }
  }, [user?.loja]);

  // Função de logout que funciona para ambos os tipos
  const logout = async () => {
    // Limpar cache de funcionário
    localStorage.removeItem('employee_user');
    // Limpar modo de autenticação
    clearActiveAuthMode();
    // Sempre tenta deslogar do Supabase também
    await base44.auth.logout();
    setUser(null);
    setAuthType(null);
    setCargoPermissoes(null);
    setAuthError(null);
    setSelectedStore(null); // Limpa seleção
    window.location.href = '/login';
  };

  const retryAuth = () => {
    setLoading(true);
    setAuthError(null);
    setAuthAttempt(prev => prev + 1);
  };

  // Verifica permissão - primeiro tenta banco, depois fallback hardcoded
  const can = (permission) => {
    if (!user) return false;

    const roles = getUserRoles(user);
    if (!roles.length) return false;

    // Se cargo é Administrador no banco OU tem permissão especial '*'
    if (hasRole(user, 'Administrador')) return true;

    // Tenta usar permissões do banco primeiro
    if (cargoPermissoes?.can) {
      if (cargoPermissoes.can.includes('*')) return true;
      return cargoPermissoes.can.includes(permission);
    }

    // Fallback para regras hardcoded multi-cargo
    return userCan(user, permission);
  };

  // Pega o escopo (all, store, own)
  const getScope = () => {
    if (!user) return SCOPES.OWN;

    // Tenta banco primeiro
    if (cargoPermissoes?.scope) {
      return cargoPermissoes.scope;
    }

    // Fallback
    return getUserEffectivePermissions(user).scope;
  };

  // Verifica se usuario e Gerente
  const isGerente = () => {
    return hasRole(user, 'Gerente');
  };

  // Pega a loja do usuario (Prioridade: Loja fixa do user -> Loja selecionada pelo Admin)
  const getUserLoja = () => {
    return user?.loja || selectedStore || null;
  };

  const getUserLojas = () => {
    const lojas = [user?.loja, selectedStore].filter(Boolean);
    return Array.from(new Set(lojas));
  };

  const canAccessLoja = (lojaId) => {
    return canAccessLojaId(lojaId, getUserLojas());
  };

  // Verifica se deve filtrar por loja (Gerente)
  const shouldFilterByStore = () => {
    return getUserLojas().length > 0;
  };

  // Filtra dados automaticamente por escopo
  const filterData = (data, options = {}) => {
    if (!data || !user) return [];
    if (!Array.isArray(data)) return [];

    const normalizedOptions = typeof options === 'string'
      ? { scopeOverride: options }
      : (options || {});

    const userLojas = getUserLojas();
    const dataWithinUserStores = userLojas.length > 0
      ? filterDataByLoja(data, userLojas, { lojaField: normalizedOptions.lojaField })
      : data;

    const scope = normalizedOptions.scopeOverride || getScope();

    // Mesmo admins do tenant continuam limitados a suas lojas atribuídas.
    if (scope === SCOPES.ALL || scope === 'all') return dataWithinUserStores;

    // Gerente ve apenas da sua loja
    if (scope === SCOPES.STORE || scope === 'store') {
      if (!userLojas.length) {
        console.warn('[useAuth] Gerente sem loja definida, filtrando tudo');
        return [];
      }

      return dataWithinUserStores;
    }

    // Vendedor ve apenas o proprio
    if (scope === SCOPES.OWN || scope === 'own') {
      const userIdField = normalizedOptions.userField || 'responsavel_id';
      const userIdFields = [userIdField, 'vendedor_id', 'created_by', 'user_id'];

      return dataWithinUserStores.filter(item => {
        for (const field of userIdFields) {
          if (item[field] === user.id || item[field] === user.email) {
            return true;
          }
        }
        return false;
      });
    }

    return [];
  };

  const value = {
    user,
    loading,
    authError,
    logout,
    retryAuth,
    authType,
    can,
    getScope,
    filterData,
    isGerente,
    getUserLoja,
    getUserLojas,
    canAccessLoja,
    shouldFilterByStore,
    SCOPES,
    selectedStore,
    setSelectedStore
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined || context === null) {
    console.error('[useAuth] Context is missing! AuthContext:', AuthContext);
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

import React, { useState, createContext, useContext, useCallback } from "react";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog";

const ConfirmContext = createContext(null);

export function ConfirmProvider({ children }) {
    const [state, setState] = useState({
        isOpen: false,
        title: "Confirmar",
        message: "",
        confirmText: "Confirmar",
        cancelText: "Cancelar",
        variant: "default", // "default" | "destructive"
        onConfirm: null,
        onCancel: null,
    });

    const confirm = useCallback(({
        title = "Confirmar",
        message,
        confirmText = "Confirmar",
        cancelText = "Cancelar",
        variant = "default"
    }) => {
        return new Promise((resolve) => {
            setState({
                isOpen: true,
                title,
                message,
                confirmText,
                cancelText,
                variant,
                onConfirm: () => {
                    setState(prev => ({ ...prev, isOpen: false }));
                    resolve(true);
                },
                onCancel: () => {
                    setState(prev => ({ ...prev, isOpen: false }));
                    resolve(false);
                },
            });
        });
    }, []);

    return (
        <ConfirmContext.Provider value={confirm}>
            {children}
            <AlertDialog open={state.isOpen} onOpenChange={(open) => {
                if (!open) state.onCancel?.();
            }}>
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>{state.title}</AlertDialogTitle>
                        <AlertDialogDescription className="whitespace-pre-line">
                            {state.message}
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel onClick={state.onCancel}>
                            {state.cancelText}
                        </AlertDialogCancel>
                        <AlertDialogAction
                            onClick={state.onConfirm}
                            className={state.variant === "destructive" ? "bg-red-600 hover:bg-red-700" : ""}
                            style={state.variant !== "destructive" ? { background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' } : {}}
                        >
                            {state.confirmText}
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </ConfirmContext.Provider>
    );
}

export function useConfirm() {
    const context = useContext(ConfirmContext);
    if (!context) {
        throw new Error("useConfirm must be used within a ConfirmProvider");
    }
    return context;
}

import { useState, useEffect, useRef, useCallback } from 'react';
import { whatsappService } from '@/services/whatsappService';
import { getOfflineQueue, removeOfflineQueueItem } from '@/utils/offlineQueue';
import { toast } from "sonner";

const WHATSAPP_STATUS_CACHE_KEY = 'whatsapp_connection_status';

export function useConnectionStatus(enabled = false) {
    function readCachedStatus() {
        try {
            const cached = localStorage.getItem(WHATSAPP_STATUS_CACHE_KEY);
            if (cached === null) return false;
            return cached === 'true';
        } catch {
            return false;
        }
    }

    function writeCachedStatus(status) {
        try {
            localStorage.setItem(WHATSAPP_STATUS_CACHE_KEY, status ? 'true' : 'false');
        } catch {
            // Ignora falhas de storage para não impactar o layout.
        }
    }

    const prevWhatsAppConnected = useRef(true);
    const [isWhatsAppConnected, setIsWhatsAppConnected] = useState(readCachedStatus());
    const [isSystemOnline, setIsSystemOnline] = useState(navigator.onLine);

    // Função de sincronização da fila offline (compartilhada entre triggers)
    const syncOfflineQueue = useCallback(async () => {
        const whatsappOnline = await whatsappService.checkStatus();
        if (!whatsappOnline) return;

        const queue = await getOfflineQueue();
        if (queue.length === 0) return;

        toast.info(`Sincronizando ${queue.length} ação(ões) offline do WhatsApp...`);
        let sucesso = 0;

        for (const item of queue) {
            try {
                if (typeof whatsappService[item.action] !== 'function') {
                    console.warn(`Ação inválida encontrada na fila e removida: ${item.action}`);
                    await removeOfflineQueueItem(item.id);
                    continue;
                }
                const replayOk = await whatsappService[item.action](...item.payload);
                if (replayOk === true || replayOk?.status === 'sent') {
                    await removeOfflineQueueItem(item.id);
                    sucesso++;
                }
                // replayOk com status 'queued' mantém o item para nova tentativa futura.
            } catch (error) {
                console.error(`Erro ao sincronizar item offline ${item.id}:`, error);
            }
        }

        if (sucesso > 0) {
            toast.success(`${sucesso} ação(ões) do Zap enviadas com sucesso!`);
        }
    }, []);

    // Monitor System Online/Offline status
    useEffect(() => {
        const handleOnline = () => {
            setIsSystemOnline(true);
            syncOfflineQueue();
        };

        const handleOffline = () => setIsSystemOnline(false);

        window.addEventListener('online', handleOnline);
        window.addEventListener('offline', handleOffline);

        return () => {
            window.removeEventListener('online', handleOnline);
            window.removeEventListener('offline', handleOffline);
        };
    }, [enabled, syncOfflineQueue]);

    // Monitor WhatsApp Bot status
    useEffect(() => {
        if (!enabled) {
            return undefined;
        }

        const checkWhatsAppStatus = async () => {
            const status = await whatsappService.checkStatus();

            // Se o WhatsApp reconectou, o modal de confirmação na tela de Configuração
            // permite ao usuário decidir se envia ou descarta as pendências.
            if (status && !prevWhatsAppConnected.current) {
                console.log('🔄 WhatsApp conectado.');
            }

            prevWhatsAppConnected.current = status;
            setIsWhatsAppConnected(status);
            writeCachedStatus(status);
        };

        // Check immediately on mount
        checkWhatsAppStatus();

        // Then check every 30 seconds
        const interval = setInterval(checkWhatsAppStatus, 30000);

        return () => clearInterval(interval);
    }, [syncOfflineQueue]);

    return {
        isSystemOnline,
        isWhatsAppConnected
    };
}

import { useState, useEffect, useCallback } from "react";
import { SCOPES, getUserRoles, hasRole, userCan, getUserEffectivePermissions } from "@/config/permissions";

// API URL baseada no ambiente
const API_URL = import.meta.env.VITE_ZAP_API_URL || '';

/**
 * Hook de autenticação para funcionários (Matrícula + Senha)
 * Separado do Supabase Auth usado para clientes
 */
export function useEmployeeAuth() {
    const [user, setUser] = useState(null);
    const [loading, setLoading] = useState(true);
    const [cargoPermissoes, setCargoPermissoes] = useState(null);

    // Carregar usuário do localStorage
    useEffect(() => {
        const loadUser = async () => {
            try {
                const token = localStorage.getItem('employee_token');
                const storedUser = localStorage.getItem('employee_user');

                if (!token || !storedUser) {
                    setUser(null);
                    setLoading(false);
                    return;
                }

                // Verificar se token ainda é válido
                const response = await fetch(`${API_URL}/api/auth/employee/me`, {
                    headers: { 'Authorization': `Bearer ${token}` }
                });

                if (!response.ok) {
                    // Token inválido ou expirado
                    localStorage.removeItem('employee_token');
                    localStorage.removeItem('employee_user');
                    setUser(null);
                    setLoading(false);
                    return;
                }

                const data = await response.json();

                if (data.success && data.user) {
                    const roles = getUserRoles(data.user);
                    setUser({
                        ...data.user,
                        cargos: roles,
                        cargo: data.user.cargo || roles[0] || null,
                        full_name: data.user.full_name || data.user.matricula
                    });
                } else {
                    setUser(null);
                }

            } catch (error) {
                console.error("Erro ao carregar usuário:", error);
                setUser(null);
            } finally {
                setLoading(false);
            }
        };

        loadUser();
    }, []);

    // Logout
    const logout = useCallback(() => {
        localStorage.removeItem('employee_token');
        localStorage.removeItem('employee_user');
        setUser(null);
        window.location.href = '/login';
    }, []);

    // Obter token
    const getToken = useCallback(() => {
        return localStorage.getItem('employee_token');
    }, []);

    // Verificar permissão
    const can = useCallback((permission) => {
        if (!user) return false;
        const roles = getUserRoles(user);
        if (!roles.length) return false;

        // Administrador pode tudo
        if (hasRole(user, 'Administrador')) return true;

        // Usar permissões do cargo se disponíveis
        if (cargoPermissoes?.can) {
            if (cargoPermissoes.can.includes('*')) return true;
            return cargoPermissoes.can.includes(permission);
        }

        // Fallback para regras hardcoded multi-cargo
        return userCan(user, permission);
    }, [user, cargoPermissoes]);

    // Pegar o escopo (all, store, own)
    const getScope = useCallback(() => {
        if (!user) return SCOPES.OWN;

        if (cargoPermissoes?.scope) {
            return cargoPermissoes.scope;
        }

        return getUserEffectivePermissions(user).scope;
    }, [user, cargoPermissoes]);

    // Verificar se é Gerente
    const isGerente = useCallback(() => {
        return hasRole(user, 'Gerente');
    }, [user]);

    // Pegar a loja do usuário
    const getUserLoja = useCallback(() => {
        return user?.loja || null;
    }, [user]);

    // Verificar se deve filtrar por loja
    const shouldFilterByStore = useCallback(() => {
        const scope = getScope();
        return scope === SCOPES.STORE || scope === 'store';
    }, [getScope]);

    // Filtrar dados por escopo
    const filterData = useCallback((data, options = {}) => {
        if (!data || !user) return [];
        if (!Array.isArray(data)) return [];

        const scope = getScope();

        // Admin vê tudo
        if (scope === SCOPES.ALL || scope === 'all') return data;

        // Gerente vê apenas da sua loja
        if (scope === SCOPES.STORE || scope === 'store') {
            const userLoja = user.loja;
            if (!userLoja) return [];

            const lojaFields = options.lojaField
                ? [options.lojaField]
                : ['loja', 'loja_id', 'loja_nome', 'loja_venda', 'store'];

            return data.filter(item => {
                for (const field of lojaFields) {
                    if (item[field] && item[field] === userLoja) {
                        return true;
                    }
                }
                return false;
            });
        }

        // Vendedor vê apenas o próprio
        if (scope === SCOPES.OWN || scope === 'own') {
            const userIdField = options.userField || 'responsavel_id';
            const userIdFields = [userIdField, 'vendedor_id', 'created_by', 'user_id'];

            return data.filter(item => {
                for (const field of userIdFields) {
                    if (item[field] === user.id || item[field] === user.email) {
                        return true;
                    }
                }
                return false;
            });
        }

        return [];
    }, [user, getScope]);

    // Fazer requisição autenticada
    const fetchWithAuth = useCallback(async (url, options = {}) => {
        const token = getToken();

        if (!token) {
            throw new Error('Não autenticado');
        }

        const headers = {
            ...options.headers,
            'Authorization': `Bearer ${token}`
        };

        return fetch(url, { ...options, headers });
    }, [getToken]);

    return {
        user,
        loading,
        logout,
        getToken,
        fetchWithAuth,
        can,
        getScope,
        filterData,
        isGerente,
        getUserLoja,
        shouldFilterByStore,
        SCOPES
    };
}

import { useEffect, useState, useCallback } from 'react';
import { supabase } from '@/api/base44Client';
import { toast } from 'sonner';

/**
 * Hook para monitorar status de um link de pagamento
 * Usa Supabase Realtime para receber notificações instantâneas quando o pagamento é confirmado
 * 
 * @param {string} paymentLinkId - ID do payment_link a monitorar
 * @param {Object} options - Opções do hook
 * @param {boolean} options.showToast - Se deve mostrar toast ao confirmar (default: true)
 * @param {function} options.onPaid - Callback quando pagamento for confirmado
 * @param {function} options.onExpired - Callback quando link expirar
 * @param {function} options.onStatusChange - Callback para qualquer mudança de status
 */
export function usePaymentStatus(paymentLinkId, options = {}) {
    const {
        showToast = true,
        onPaid,
        onExpired,
        onStatusChange
    } = options;

    const [status, setStatus] = useState('pending');
    const [loading, setLoading] = useState(true);
    const [paymentLink, setPaymentLink] = useState(null);

    // Buscar status inicial
    const fetchStatus = useCallback(async () => {
        if (!paymentLinkId) {
            setLoading(false);
            return;
        }

        try {
            const { data, error } = await supabase
                .from('payment_links')
                .select('*')
                .eq('id', paymentLinkId)
                .single();

            if (error) throw error;

            setPaymentLink(data);
            setStatus(data.status);
        } catch (error) {
            console.error('Erro ao buscar status do pagamento:', error);
        } finally {
            setLoading(false);
        }
    }, [paymentLinkId]);

    useEffect(() => {
        fetchStatus();
    }, [fetchStatus]);

    // Configurar listener Realtime
    useEffect(() => {
        if (!paymentLinkId) return;

        const channel = supabase
            .channel(`payment_link_${paymentLinkId}`)
            .on(
                'postgres_changes',
                {
                    event: 'UPDATE',
                    schema: 'public',
                    table: 'payment_links',
                    filter: `id=eq.${paymentLinkId}`
                },
                (payload) => {
                    const newData = payload.new;
                    const oldStatus = status;
                    const newStatus = newData.status;

                    setPaymentLink(newData);
                    setStatus(newStatus);

                    // Callback genérico
                    onStatusChange?.(newStatus, oldStatus, newData);

                    // Status específicos
                    if (newStatus === 'paid' && oldStatus !== 'paid') {
                        if (showToast) {
                            toast.success('💰 Pagamento confirmado!', {
                                description: `Valor: R$ ${(newData.amount / 100).toFixed(2)}`,
                                duration: 5000
                            });
                        }
                        onPaid?.(newData);
                    }

                    if (newStatus === 'expired' && oldStatus !== 'expired') {
                        if (showToast) {
                            toast.warning('Link de pagamento expirado', {
                                description: 'O link de pagamento expirou sem ser pago'
                            });
                        }
                        onExpired?.(newData);
                    }
                }
            )
            .subscribe();

        return () => {
            supabase.removeChannel(channel);
        };
    }, [paymentLinkId, status, showToast, onPaid, onExpired, onStatusChange]);

    return {
        status,
        loading,
        paymentLink,
        isPaid: status === 'paid',
        isPending: status === 'pending',
        isExpired: status === 'expired',
        refetch: fetchStatus
    };
}

/**
 * Hook simplificado para monitorar qualquer pagamento pendente da venda
 * Monitora a tabela payment_links filtrada por venda_id
 */
export function useVendaPaymentStatus(vendaId, options = {}) {
    const [paymentLinkId, setPaymentLinkId] = useState(null);
    const [loading, setLoading] = useState(true);

    // Buscar payment_link da venda
    useEffect(() => {
        if (!vendaId) {
            setLoading(false);
            return;
        }

        const fetchPaymentLink = async () => {
            try {
                const { data } = await supabase
                    .from('payment_links')
                    .select('id')
                    .eq('venda_id', vendaId)
                    .order('created_at', { ascending: false })
                    .limit(1)
                    .single();

                if (data) {
                    setPaymentLinkId(data.id);
                }
            } catch (error) {
                // Venda pode não ter link de pagamento
            } finally {
                setLoading(false);
            }
        };

        fetchPaymentLink();
    }, [vendaId]);

    const paymentStatus = usePaymentStatus(paymentLinkId, options);

    return {
        ...paymentStatus,
        loading: loading || paymentStatus.loading,
        hasPaymentLink: !!paymentLinkId
    };
}

/**
 * Hook para monitorar uma cobranca PIX especifica via Realtime.
 */
export function usePixCobrancaStatus(cobrancaId, options = {}) {
    const {
        showToast = true,
        onPaid,
        onExpired,
        onStatusChange
    } = options;

    const [status, setStatus] = useState('PENDENTE');
    const [loading, setLoading] = useState(true);
    const [cobranca, setCobranca] = useState(null);

    const fetchStatus = useCallback(async () => {
        if (!cobrancaId) {
            setLoading(false);
            return;
        }

        try {
            const { data, error } = await supabase
                .from('cobrancas_pix')
                .select('*')
                .eq('id', cobrancaId)
                .single();

            if (error) throw error;

            setCobranca(data);
            setStatus(data.status || 'PENDENTE');
        } catch (error) {
            console.error('Erro ao buscar status da cobranca PIX:', error);
        } finally {
            setLoading(false);
        }
    }, [cobrancaId]);

    useEffect(() => {
        fetchStatus();
    }, [fetchStatus]);

    useEffect(() => {
        if (!cobrancaId) return;

        const channel = supabase
            .channel(`pix_cobranca_${cobrancaId}`)
            .on(
                'postgres_changes',
                {
                    event: 'UPDATE',
                    schema: 'public',
                    table: 'cobrancas_pix',
                    filter: `id=eq.${cobrancaId}`
                },
                (payload) => {
                    const newData = payload.new;
                    const oldStatus = status;
                    const newStatus = newData.status || 'PENDENTE';

                    setCobranca(newData);
                    setStatus(newStatus);

                    onStatusChange?.(newStatus, oldStatus, newData);

                    if (newStatus === 'CONCLUIDA' && oldStatus !== 'CONCLUIDA') {
                        if (showToast) {
                            toast.success('Pagamento PIX confirmado!', { duration: 5000 });
                        }
                        onPaid?.(newData);
                    }

                    if (newStatus === 'EXPIRADA' && oldStatus !== 'EXPIRADA') {
                        if (showToast) {
                            toast.warning('Cobranca PIX expirada');
                        }
                        onExpired?.(newData);
                    }
                }
            )
            .subscribe();

        return () => {
            supabase.removeChannel(channel);
        };
    }, [cobrancaId, status, showToast, onPaid, onExpired, onStatusChange]);

    return {
        status,
        loading,
        cobranca,
        isPaid: status === 'CONCLUIDA',
        isPending: status === 'PENDENTE' || status === 'ATIVA',
        isExpired: status === 'EXPIRADA',
        refetch: fetchStatus,
    };
}

export default usePaymentStatus;

import { useState, useEffect, useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/api/base44Client';

/**
 * Hook para gerenciar filtros padrão de produto
 * Reutilizável entre Produtos.jsx e EstoqueTab.jsx
 * 
 * @returns {Object} Contém states dos filtros, queries de categorias/fabricantes, e utilities
 */
export function useProdutoFilters() {
  const [searchTerm, setSearchTerm] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [selectedCategoria, setSelectedCategoria] = useState('todas');
  const [selectedFabricante, setSelectedFabricante] = useState('todos');
  const [selectedOrdenacao, setSelectedOrdenacao] = useState('alfabetica');
  const [selectedDirecao, setSelectedDirecao] = useState('asc');
  const [filtroAtencao, setFiltroAtencao] = useState(false);

  // Debounce search
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(searchTerm);
    }, 500);
    return () => clearTimeout(timer);
  }, [searchTerm]);

  // Fetch categorias únicas
  const { data: categorias = [] } = useQuery({
    queryKey: ['categorias-produtos'],
    queryFn: async () => {
      const { data, error } = await supabase.from('produtos').select('categoria').not('categoria', 'is', null);
      if (error) throw error;
      const cats = [...new Set(data?.map(p => p.categoria))].filter(Boolean).sort();
      return cats;
    },
    staleTime: 1000 * 60 * 5
  });

  // Fetch count de produtos com atenção
  const { data: produtosComAtencao = 0 } = useQuery({
    queryKey: ['produtos-atencao-count'],
    queryFn: async () => {
      const { count, error } = await supabase
        .from('produtos')
        .select('*', { count: 'exact', head: true })
        .eq('requer_atencao', true);
      if (error) throw error;
      return count || 0;
    }
  });

  // Função para aplicar sorting (client-side) em um array de produtos.
  // O filtro de fabricante NÃO é aplicado aqui — já foi aplicado no queryFn de quem chamou.
  const aplicarOrdenacao = (produtos) => {
    let sorted = [...produtos];

    switch (selectedOrdenacao) {
      case 'quantidade':
        sorted.sort((a, b) => {
          const aQtd = a.quantidade_estoque || 0;
          const bQtd = b.quantidade_estoque || 0;
          return selectedDirecao === 'asc' ? aQtd - bQtd : bQtd - aQtd;
        });
        break;
      case 'preco':
        sorted.sort((a, b) => {
          const aPreco = a.preco_venda || 0;
          const bPreco = b.preco_venda || 0;
          return selectedDirecao === 'asc' ? aPreco - bPreco : bPreco - aPreco;
        });
        break;
      case 'alfabetica':
      default:
        sorted.sort((a, b) => {
          const comparacao = (a.nome || '').localeCompare((b.nome || ''), 'pt-BR', { sensitivity: 'base' });
          return selectedDirecao === 'asc' ? comparacao : comparacao * -1;
        });
        break;
    }

    return sorted;
  };

  // Função para resetar todos os filtros
  const resetFilters = () => {
    setSearchTerm('');
    setDebouncedSearch('');
    setSelectedCategoria('todas');
    setSelectedFabricante('todos');
    setSelectedOrdenacao('alfabetica');
    setSelectedDirecao('asc');
    setFiltroAtencao(false);
  };

  return {
    // Estados
    searchTerm,
    setSearchTerm,
    debouncedSearch,
    selectedCategoria,
    setSelectedCategoria,
    selectedFabricante,
    setSelectedFabricante,
    selectedOrdenacao,
    setSelectedOrdenacao,
    selectedDirecao,
    setSelectedDirecao,
    filtroAtencao,
    setFiltroAtencao,

    // Dados carregados
    categorias,
    produtosComAtencao,

    // Utilities
    aplicarOrdenacao,
    resetFilters
  };
}

import { createClient } from '@supabase/supabase-js';

// Configuração do Supabase
export const supabaseUrl = import.meta.env.VITE_SUPABASE_URL || import.meta.env.SUPABASE_URL;
export const supabaseKey = import.meta.env.VITE_SUPABASE_ANON_KEY || import.meta.env.SUPABASE_ANON_KEY;

if (!supabaseUrl || !supabaseKey) {
    const missingVars = [];
    if (!supabaseUrl) missingVars.push('VITE_SUPABASE_URL/SUPABASE_URL');
    if (!supabaseKey) missingVars.push('VITE_SUPABASE_ANON_KEY/SUPABASE_ANON_KEY');
    throw new Error(`Configuração do Supabase ausente: ${missingVars.join(', ')}.`);
}

// Criar cliente com configurações que garantem persistência de autenticação
// Singleton para garantir que só exista uma instância do cliente Supabase no browser
if (!window.__supabase_instance) {
    window.__supabase_instance = createClient(supabaseUrl, supabaseKey, {
        auth: {
            persistSession: true, // Persiste a sessão no localStorage
            autoRefreshToken: true, // Atualiza automaticamente o token
            detectSessionInUrl: true, // Detecta sessão na URL (útil para email confirmations)
            storage: window.localStorage, // Usa localStorage explicitamente
            storageKey: 'moveis-pedro-ii-auth-token', // Chave única para evitar conflitos
        },
        global: {
            headers: {
                'x-client-info': 'moveis-pedro-ii-web',
            },
        },
    });
}

export const supabase = window.__supabase_instance;

// ============================================================================
// AUTH MODE ISOLATION - Separar sessão Operador SaaS vs Funcionário GestApp
// ============================================================================
const AUTH_MODE_KEY = 'active_auth_mode';
export const AUTH_MODES = Object.freeze({
    OPERATOR: 'operator',
    TENANT: 'tenant',
});

export function getActiveAuthMode() {
    try {
        return localStorage.getItem(AUTH_MODE_KEY) || null;
    } catch {
        return null;
    }
}

export function setActiveAuthMode(mode) {
    try {
        if (mode && Object.values(AUTH_MODES).includes(mode)) {
            localStorage.setItem(AUTH_MODE_KEY, mode);
        }
    } catch {
        // Ignora falhas de storage
    }
}

export function clearActiveAuthMode() {
    try {
        localStorage.removeItem(AUTH_MODE_KEY);
    } catch {
        // Ignora falhas de storage
    }
}

// Listener para refresh automático de sessão quando estiver prestes a expirar
