              Aprovação de Encomendas
              {countPendentes > 0 && (
                <span className="ml-2 text-sm bg-amber-500 text-white px-2 py-0.5 rounded-full">
                  {countPendentes} pendente{countPendentes > 1 ? "s" : ""}
                </span>
              )}
            </h1>
            <p className="text-sm text-gray-500">Vendas sem estoque aguardando autorização gerencial</p>
          </div>
        </div>
      </div>

      {/* Filtros */}
      <div className="flex flex-wrap gap-3 items-center">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <Input
            placeholder="Buscar produto, cliente, pedido..."
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="pl-9 h-9 w-72"
          />
        </div>
        <div className="flex gap-1">
          {[
            { key: "aguardando_aprovacao", label: "Pendentes" },
            { key: "aprovado", label: "Aprovados" },
            { key: "rejeitado", label: "Rejeitados" },
            { key: "todos", label: "Todos" },
          ].map(({ key, label }) => (
            <button
              key={key}
              onClick={() => setFiltroStatus(key)}
              className={`text-xs px-3 py-1.5 rounded-full transition-colors ${
                filtroStatus === key
                  ? "bg-green-700 text-white"
                  : "bg-gray-100 text-gray-600 hover:bg-gray-200"
              }`}
            >
              {label}
            </button>
          ))}
        </div>
      </div>

      {/* Tabela */}
      <Card>
        <CardContent className="p-0">
          {/* Cabeçalho da tabela */}
          <div className="grid grid-cols-[1.5fr_2fr_0.8fr_1fr_1fr_auto] gap-3 px-4 py-2.5 bg-gray-50 border-b text-xs font-medium text-gray-500">
            <span>Produto / Fornecedor</span>
            <span>Cliente / Pedido</span>
            <span>Qtd</span>
            <span>Motivo</span>
            <span>Status</span>
            <span>Ações</span>
          </div>

          {isLoading ? (
            <div className="flex justify-center py-10">
              <Loader2 className="animate-spin text-gray-400" />
            </div>
          ) : filtradas.length === 0 ? (
            <div className="text-center py-12 text-sm text-gray-400">
              Nenhuma solicitação encontrada para o filtro selecionado.
            </div>
          ) : (
            filtradas.map(s => (
              <div
                key={s.id}
                className="grid grid-cols-[1.5fr_2fr_0.8fr_1fr_1fr_auto] gap-3 px-4 py-3 border-b border-gray-100 hover:bg-gray-50/50 items-center"
              >
                <div>
                  <p className="text-sm font-medium text-gray-800 truncate">{s.produto_nome}</p>
                  <p className="text-xs text-gray-400">{s.fornecedor_nome}</p>
                </div>
                <div>
                  <p className="text-sm text-gray-700">{s.cliente_nome}</p>
                  <p className="text-xs text-gray-400">Pedido #{s.numero_pedido} · {s.loja}</p>
                </div>
                <span className="text-sm font-medium">{s.quantidade}</span>
                <span className="text-xs text-gray-600">
                  {MOTIVO_LABELS[s.motivo_encomenda] || s.motivo_encomenda || "—"}
                </span>
                <StatusBadge status={s.status} />
                <div className="flex gap-1">
                  {s.status === "aguardando_aprovacao" && (
                    <>
                      <Button
                        size="sm"
                        variant="outline"
                        className="h-7 px-2 text-xs text-green-700 border-green-200 hover:bg-green-50"
                        onClick={() => { setModalItem({ solicitacao: s, acao: "aprovar" }); setObs(""); }}
                      >
                        <CheckCircle className="w-3.5 h-3.5 mr-1" /> Aprovar
                      </Button>
                      <Button
                        size="sm"
                        variant="outline"
                        className="h-7 px-2 text-xs text-red-600 border-red-200 hover:bg-red-50"
                        onClick={() => { setModalItem({ solicitacao: s, acao: "rejeitar" }); setObs(""); }}
                      >
                        <XCircle className="w-3.5 h-3.5 mr-1" /> Rejeitar
                      </Button>
                    </>
                  )}
                  {s.status === "aprovado" && (
                    <div className="text-xs text-gray-400">
                      por {s.aprovado_por_nome || "—"}<br />
                      {s.data_aprovacao ? new Date(s.data_aprovacao).toLocaleDateString("pt-BR") : ""}
                    </div>
                  )}
                  {s.observacoes_gerencial && (
                    <span className="text-xs text-gray-400 italic truncate max-w-32" title={s.observacoes_gerencial}>
                      &quot;{s.observacoes_gerencial}&quot;
                    </span>
                  )}
                </div>
              </div>
            ))
          )}
        </CardContent>
      </Card>

      {/* Modal Aprovar / Rejeitar */}
      <Dialog open={!!modalItem} onOpenChange={() => setModalItem(null)}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle className={modalItem?.acao === "aprovar" ? "text-green-700" : "text-red-600"}>
              {modalItem?.acao === "aprovar" ? "Aprovar Encomenda" : "Rejeitar Encomenda"}
            </DialogTitle>
          </DialogHeader>
          {modalItem && (
            <div className="space-y-4 py-2">
              <div className="bg-gray-50 rounded-lg p-3 text-sm space-y-1">
                <p><span className="font-medium">Produto:</span> {modalItem.solicitacao.produto_nome}</p>
                <p><span className="font-medium">Cliente:</span> {modalItem.solicitacao.cliente_nome}</p>
                <p><span className="font-medium">Pedido:</span> #{modalItem.solicitacao.numero_pedido}</p>
                <p><span className="font-medium">Qtd:</span> {modalItem.solicitacao.quantidade}</p>
              </div>
              <div className="space-y-1">
                <label className="text-sm font-medium text-gray-700">
                  Observações {modalItem.acao === "rejeitar" ? "(obrigatório indicar motivo)" : "(opcional)"}
                </label>
                <Textarea
                  rows={3}
                  placeholder={
                    modalItem.acao === "aprovar"
                      ? "Ex: Mercadoria em trânsito, prazo 10 dias..."
                      : "Ex: Produto descontinuado, aguardar nova coleção..."
                  }
                  value={obs}
                  onChange={e => setObs(e.target.value)}
                />
              </div>
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setModalItem(null)}>Cancelar</Button>
            {modalItem?.acao === "aprovar" ? (
              <Button
                disabled={processando}
                className="bg-green-700 hover:bg-green-800 text-white"
                onClick={handleAprovar}
              >
                {processando ? <><Loader2 className="w-4 h-4 mr-2 animate-spin" />Aprovando...</> : "Confirmar Aprovação"}
              </Button>
            ) : (
              <Button
                disabled={processando || !obs.trim()}
                variant="destructive"
                onClick={handleRejeitar}
              >
                {processando ? <><Loader2 className="w-4 h-4 mr-2 animate-spin" />Rejeitando...</> : "Confirmar Rejeição"}
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useState, useMemo } from "react";
import { base44, supabase } from "@/api/base44Client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/hooks/useAuth";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Card, CardContent } from "@/components/ui/card";
import {
    Plus, Search, Trash2, Edit, Loader2, Wrench,
    AlertCircle, Clock, CheckCircle, Package, Filter, Link as LinkIcon, FileText
} from "lucide-react";
import AssistenciaTecnicaModal from "../components/assistencia/AssistenciaTecnicaModal";
import SelecionarLojaReposicaoModal from "../components/assistencia/SelecionarLojaReposicaoModal";
import { abrirAssistenciaTecnicaPDF } from "../components/assistencia/AssistenciaTecnicaPDF";
import { useTenant } from "@/contexts/TenantContext";
import { toast } from "sonner";
import DevolucaoModal from "../components/devolucoes/DevolucaoModal";

const DEFAULT_TENANT_ID = '00000000-0000-0000-0000-000000000001';
const TIPOS_COM_REPOSICAO = ['Troca', 'Peça Faltante'];

const TIPOS_ASSISTENCIA = [
    { value: "Devolução", label: "Devolução", color: "bg-red-100 text-red-800 border-red-200" },
    { value: "Troca", label: "Troca", color: "bg-orange-100 text-orange-800 border-orange-200" },
    { value: "Peça Faltante", label: "Peça Faltante", color: "bg-yellow-100 text-yellow-800 border-yellow-200" },
    { value: "Conserto", label: "Conserto", color: "bg-blue-100 text-blue-800 border-blue-200" },
    { value: "Visita Técnica", label: "Visita Técnica", color: "bg-purple-100 text-purple-800 border-purple-200" },
    { value: "Outros", label: "Outros", color: "bg-gray-100 text-gray-800 border-gray-200" }
];

const STATUS_OPTIONS = [
    { value: "Aberta", label: "Aberta", color: "bg-blue-100 text-blue-800 border-blue-200" },
    { value: "Em Andamento", label: "Em Andamento", color: "bg-yellow-100 text-yellow-800 border-yellow-200" },
    { value: "Aguardando Peça", label: "Aguardando Peça", color: "bg-orange-100 text-orange-800 border-orange-200" },
    { value: "Aguardando Cliente", label: "Aguardando Cliente", color: "bg-purple-100 text-purple-800 border-purple-200" },
    { value: "Concluída", label: "Concluída", color: "bg-green-100 text-green-800 border-green-200" },
    { value: "Cancelada", label: "Cancelada", color: "bg-red-100 text-red-800 border-red-200" }
];

const PRIORIDADE_OPTIONS = [
    { value: "Baixa", label: "Baixa", color: "bg-gray-100 text-gray-600 border-gray-200" },
    { value: "Normal", label: "Normal", color: "bg-blue-100 text-blue-700 border-blue-200" },
    { value: "Alta", label: "Alta", color: "bg-orange-100 text-orange-700 border-orange-200" },
    { value: "Urgente", label: "Urgente", color: "bg-red-100 text-red-700 border-red-200" }
];

export default function AssistenciaTecnica() {
    const [searchTerm, setSearchTerm] = useState("");
    const [filterTipo, setFilterTipo] = useState("todos");
    const [filterStatus, setFilterStatus] = useState("todos");
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingAssistencia, setEditingAssistencia] = useState(null);
    const [saving, setSaving] = useState(false);
    const [reposicaoPendente, setReposicaoPendente] = useState(null);
    const [isReposicaoModalOpen, setIsReposicaoModalOpen] = useState(false);
    const { user } = useAuth();
    const { brandName } = useTenant();
    const queryClient = useQueryClient();

    // Queries
    // Devolution module states
    const [isDevolucaoModalOpen, setIsDevolucaoModalOpen] = useState(false);
    const [editingDevolucao, setEditingDevolucao] = useState(null);
    const [savingDevolucao, setSavingDevolucao] = useState(false);

    // Queries
    const { data: assistencias = [], isLoading: isLoadingAssistencias } = useQuery({
        queryKey: ['assistencias'],
        queryFn: () => base44.entities.AssistenciaTecnica.list('-created_at')
    });

    const { data: devolucoes = [], isLoading: isLoadingDevolucoes } = useQuery({
        queryKey: ['devolucoes'],
        queryFn: () => base44.entities.Devolucao.list('-created_date')
    });

    const { data: vendas = [] } = useQuery({
        queryKey: ['vendas'],
        queryFn: () => base44.entities.Venda.list('-data_venda')
    });

    const { data: lojas = [] } = useQuery({
        queryKey: ['lojas'],
        queryFn: () => base44.entities.Loja.list('nome')
    });

    const { data: clientes = [] } = useQuery({
        queryKey: ['clientes'],
        queryFn: () => base44.entities.Cliente.list()
    });

    const { data: fornecedores = [] } = useQuery({
        queryKey: ['fornecedores'],
        queryFn: () => base44.entities.Fornecedor.list()
    });

    const { data: produtos = [] } = useQuery({
        queryKey: ['produtos'],
        queryFn: () => base44.entities.Produto.list('nome'),
        enabled: isModalOpen
    });

    const isLoading = isLoadingAssistencias || isLoadingDevolucoes;

    // ==============================================
    // FUNÇÃO PRINCIPAL DE SAVE COM INTEGRAÇÕES
    // ==============================================
    const handleSave = async (formData) => {
        const isEditing = !!editingAssistencia;
        const statusAnterior = editingAssistencia?.status;
        const mudouParaConcluida = formData.status === 'Concluída' && statusAnterior !== 'Concluída';
        const exigeReposicao =
            mudouParaConcluida &&
            TIPOS_COM_REPOSICAO.includes(formData.tipo) &&
            (formData.itens_envolvidos?.length ?? 0) > 0;

        // Se exige reposição, interceptar e abrir modal de seleção de loja antes de salvar
        if (exigeReposicao) {
            setReposicaoPendente({ formData, isEditing, statusAnterior, mudouParaConcluida });
            setIsReposicaoModalOpen(true);
            return;
        }

        await _executarSave({ formData, isEditing, statusAnterior, mudouParaConcluida, selecaoLojas: null });
    };

    // Chamado pelo SelecionarLojaReposicaoModal ao confirmar seleção de lojas
    const handleConfirmarReposicao = async (selecaoLojas) => {
        setIsReposicaoModalOpen(false);
        if (!reposicaoPendente) return;
        const { formData, isEditing, statusAnterior, mudouParaConcluida } = reposicaoPendente;
        setReposicaoPendente(null);
        await _executarSave({ formData, isEditing, statusAnterior, mudouParaConcluida, selecaoLojas });
    };

    const handleCancelarReposicao = () => {
        setIsReposicaoModalOpen(false);
        setReposicaoPendente(null);
    };

    const _executarSave = async ({ formData, isEditing, statusAnterior, mudouParaConcluida, selecaoLojas }) => {
        setSaving(true);
        const hoje = new Date().toISOString().split('T')[0];

        try {
            // 1. Adicionar histórico de mudança de status
            const novoHistorico = formData.historico || [];
            if (isEditing && formData.status !== statusAnterior) {
                novoHistorico.push({
                    status_anterior: statusAnterior,
                    status_novo: formData.status,
                    data: new Date().toISOString(),
                    usuario: user?.full_name || user?.email || 'Sistema'
                });
            }
            formData.historico = novoHistorico;

            // 2. Se concluiu, preencher data_resolucao automaticamente
            if (mudouParaConcluida && !formData.data_resolucao) {
                formData.data_resolucao = hoje;
            }

            // 3. Salvar a assistência
            if (isEditing) {
                await base44.entities.AssistenciaTecnica.update(editingAssistencia.id, formData);
            } else {
                // Ao criar, já adicionar o primeiro registro no histórico
                formData.historico = [{
                    status_anterior: null,
                    status_novo: formData.status,
                    data: new Date().toISOString(),
                    usuario: user?.full_name || user?.email || 'Sistema'
                }];
                await base44.entities.AssistenciaTecnica.create(formData);
            }

            // 4. INTEGRAÇÃO FINANCEIRA - Executar quando concluída com valores
            if (mudouParaConcluida) {
                // Se houver valor devolvido, criar lançamento de saída
                if (formData.valor_devolvido > 0) {
                    try {
                        await base44.entities.LancamentoFinanceiro.create({
                            descricao: `Devolução #${formData.numero_pedido} - ${formData.cliente_nome} (${formData.tipo})`,
                            valor: -formData.valor_devolvido,
                            tipo: 'despesa',
                            data_vencimento: hoje,
                            data_lancamento: hoje,
                            pago: true,
                            categoria_nome: 'Devoluções/Assistência',
                            status: 'Pago',
                            observacao: `Assistência técnica: ${formData.descricao_problema?.substring(0, 100)}...`
                        });
                        console.log('✅ Lançamento de devolução criado:', formData.valor_devolvido);
                    } catch (err) {
                        console.error('Erro ao criar lançamento de devolução:', err);
                    }
                }

                // Se houver valor cobrado, criar lançamento de entrada
                if (formData.valor_cobrado > 0) {
                    try {
                        await base44.entities.LancamentoFinanceiro.create({
                            descricao: `Serviço AT #${formData.numero_pedido} - ${formData.cliente_nome} (${formData.tipo})`,
                            valor: formData.valor_cobrado,
                            tipo: 'receita',
                            data_vencimento: hoje,
                            data_lancamento: hoje,
                            pago: true,
                            categoria_nome: 'Serviços/Assistência',
                            status: 'Pago',
                            observacao: `Assistência técnica: ${formData.solucao_aplicada?.substring(0, 100) || 'N/A'}`
                        });
                        console.log('✅ Lançamento de serviço criado:', formData.valor_cobrado);
                    } catch (err) {
                        console.error('Erro ao criar lançamento de serviço:', err);
                    }
                }

                // 5. INTEGRAÇÃO ESTOQUE - Devolver itens ao estoque quando for Devolução
                if (formData.tipo === 'Devolução' && formData.itens_envolvidos?.length > 0) {
                    for (const item of formData.itens_envolvidos) {
                        try {
                            const { data: produto, error } = await supabase
                                .from('produtos')
                                .select('*')
                                .eq('id', item.produto_id)
                                .single();

                            if (error) throw error;

                            if (produto) {
                                // Sincronização Global (PDV)
                                await base44.entities.Produto.update(produto.id, {
                                    quantidade_estoque: (produto.quantidade_estoque || 0) + item.quantidade,
                                    quantidade_reservada: Math.max(0, (produto.quantidade_reservada || 0) - item.quantidade)
                                });

                                // Sincronização Local (Scanner/Estoque Loja)
                                const tenantId = user?.loja || 'CD';
                                await supabase.from('estoque_loja').insert({
                                    gtin: produto.gtin,
                                    tenant_id: tenantId,
                                    quantidade: item.quantidade,
                                    volumes_recebidos: Array.from({ length: produto.volumes || 1 }, (_, i) => i + 1)
                                });

                                console.log('✅ Estoque sincronizado (Global + Local):', item.produto_nome, '+', item.quantidade);
                            }
                        } catch (err) {
                            console.error('Erro ao atualizar estoque sincronizado:', err);
                        }
                    }
                }

                // 6. INTEGRAÇÃO REPOSIÇÃO - Descontar estoque e criar solicitação de reposição para Troca / Peça Faltante
                if (selecaoLojas && TIPOS_COM_REPOSICAO.includes(formData.tipo) && formData.itens_envolvidos?.length > 0) {
                    const assistenciaSalva = await base44.entities.AssistenciaTecnica.list(
                        '-created_at'
                    ).then(list => list.find(a => a.numero_pedido === formData.numero_pedido));

                    for (const item of formData.itens_envolvidos) {
                        const prodSaiId = item.produto_sai_id || item.produto_id;
                        const prodSaiNome = item.produto_sai_nome || item.produto_nome;
                        const prodSaiQtd = item.produto_sai_quantidade || item.quantidade;

                        const lojaInfo = selecaoLojas[prodSaiId] || selecaoLojas[item.produto_id];
                        if (!lojaInfo) continue;

                        try {
                            // a) Buscar estoque atual da loja selecionada
                            const { data: estoqueRows } = await supabase
                                .from('estoque_loja')
                                .select('id, quantidade')
                                .eq('produto_id', prodSaiId)
                                .eq('loja_id', lojaInfo.loja_id)
                                .maybeSingle();

                            const qtdAtual = estoqueRows?.quantidade ?? 0;
                            const qtdNova = Math.max(0, qtdAtual - prodSaiQtd);

                            if (estoqueRows?.id) {
                                // b) Decrementar estoque_loja
                                await supabase
                                    .from('estoque_loja')
                                    .update({ quantidade: qtdNova, updated_at: new Date().toISOString() })
                                    .eq('id', estoqueRows.id);
                            }

                            // c) Recalcular produtos.quantidade_estoque (soma de todas as lojas)
                            const { data: todasLojas } = await supabase
                                .from('estoque_loja')
                                .select('quantidade')
                                .eq('produto_id', prodSaiId);

                            const totalEstoque = (todasLojas || []).reduce(
                                (sum, row) => sum + (row.quantidade || 0), 0
                            );

                            await supabase
                                .from('produtos')
                                .update({ quantidade_estoque: totalEstoque })
                                .eq('id', prodSaiId);

                            // d) Registrar movimentação de auditoria
                            await supabase.from('movimentacoes_estoque').insert({
                                produto_id: prodSaiId,
                                evento_tipo: 'assistencia_troca',
                                modulo_origem: 'assistencia',
                                quantidade: prodSaiQtd,
                                estoque_antes_total: qtdAtual,
                                estoque_depois_total: qtdNova,
                                loja_origem: lojaInfo.loja_nome,
                                referencia_numero: formData.numero_pedido,
                                usuario_id: user?.id,
                                usuario_nome: user?.full_name || user?.email || 'Sistema',
                                organization_id: DEFAULT_TENANT_ID
                            });

                            // e) Criar solicitação de reposição para o setor de compras
                            await base44.entities.SolicitacaoReposicao.create({
                                assistencia_id: assistenciaSalva?.id || null,
                                numero_assistencia: formData.numero_pedido,
                                produto_id: prodSaiId,
                                produto_nome: prodSaiNome,
                                quantidade: prodSaiQtd,
                                loja_id: lojaInfo.loja_id,
                                loja_nome: lojaInfo.loja_nome,
                                status: 'Pendente',
                                observacoes: `Gerado ao concluir assistência #${formData.numero_pedido} - ${formData.tipo} - ${formData.cliente_nome}`,
                                tenant_id: DEFAULT_TENANT_ID
                            });

                            console.log('✅ Reposição criada e estoque decrementado:', prodSaiNome, 'loja:', lojaInfo.loja_nome);
                        } catch (err) {
                            console.error('Erro ao processar reposição para item:', prodSaiNome, err);
                        }
                    }

                    queryClient.invalidateQueries({ queryKey: ['solicitacoes-reposicao'] });
                }
            }

            // Invalidar queries para atualizar a lista
            queryClient.invalidateQueries({ queryKey: ['assistencias'] });
            queryClient.invalidateQueries({ queryKey: ['produtos'] });
            queryClient.invalidateQueries({ queryKey: ['lancamentos'] });

            setIsModalOpen(false);
            setEditingAssistencia(null);
            toast.success(isEditing ? "Assistência atualizada!" : "Assistência criada!");

        } catch (error) {
            console.error('Erro ao salvar assistência:', error);
            toast.error("Erro ao salvar assistência");
        } finally {
            setSaving(false);
        }
    };

    // Delete mutation
    const deleteMutation = useMutation({
        mutationFn: (id) => base44.entities.AssistenciaTecnica.delete(id),
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['assistencias'] })
    });

    // Devolution mutations
    const createDevolucaoMutation = useMutation({
        mutationFn: (data) => base44.entities.Devolucao.create(data),
        onSuccess: async () => {
            await invalidateRelatedData();
            setIsModalOpen(false);
            setEditingAssistencia(null);
            toast.success("Devolução/Troca criada com sucesso!");
        }
    });

    const updateDevolucaoMutation = useMutation({
        mutationFn: ({ id, data }) => base44.entities.Devolucao.update(id, data),
        onSuccess: async () => {
            await invalidateRelatedData();
            setIsModalOpen(false);
            setEditingAssistencia(null);
            toast.success("Devolução/Troca atualizada com sucesso!");
        }
    });

    const deleteDevolucaoMutation = useMutation({
        mutationFn: (id) => base44.entities.Devolucao.delete(id),
        onSuccess: async () => {
            await invalidateRelatedData();
            toast.success("Devolução/Troca excluída com sucesso!");
        }
    });

    const invalidateRelatedData = async () => {
        await Promise.all([
            queryClient.invalidateQueries({ queryKey: ['devolucoes'] }),
            queryClient.invalidateQueries({ queryKey: ['produtos'] }),
            queryClient.invalidateQueries({ queryKey: ['vendas'] }),
            queryClient.invalidateQueries({ queryKey: ['lancamentos-financeiros'] }),
            queryClient.invalidateQueries({ queryKey: ['movimentacoes-estoque'] }),
            queryClient.invalidateQueries({ queryKey: ['assistencias'] })
        ]);
    };

    const handleSaveDevolucao = async (data) => {
        setSavingDevolucao(true);
        const performSave = async (payload) => {
            if (editingAssistencia && editingAssistencia.id) {
                return updateDevolucaoMutation.mutateAsync({ id: editingAssistencia.id, data: payload });
            }
            return createDevolucaoMutation.mutateAsync(payload);
        };

        try {
            await performSave(data);
        } catch (error) {
            const msg = String(error?.message || '').toLowerCase();
            if (!msg.includes('column') || !msg.includes('does not exist')) {
                toast.error("Erro ao salvar devolução");
                throw error;
            }

            const payloadCompat = { ...data };
            delete payloadCompat.financeiro_tipo;
            delete payloadCompat.justificativa_financeira;
            delete payloadCompat.destino_estoque;
            delete payloadCompat.cliente_nome;
            delete payloadCompat.financeiro_lancamento_id;
            delete payloadCompat.financeiro_lancamentos_ids;
            delete payloadCompat.processado_por;
            delete payloadCompat.data_processamento;
            delete payloadCompat.organization_id;

            await performSave(payloadCompat);
        } finally {
            setSavingDevolucao(false);
        }
    };

    const handleDeleteDevolucao = (id) => {
        if (window.confirm("Tem certeza que deseja excluir esta devolução/troca? Esta ação não pode ser desfeita.")) {
            deleteDevolucaoMutation.mutate(id);
        }
    };

    // Combine lists into a unifiedList
    const unifiedList = useMemo(() => {
        const mappedAssistencias = assistencias.map(a => ({
            ...a,
            itemType: 'assistencia',
            dateForSort: new Date(a.data_abertura || a.created_at)
        }));

        const mappedDevolucoes = devolucoes.map(d => ({
            ...d,
            itemType: 'devolucao',
            descricao_problema: d.observacoes || `Itens: ${(d.itens_devolvidos || []).map(i => i.produto_nome).join(', ')}`,
            prioridade: 'Normal',
            data_abertura: d.data_devolucao,
            dateForSort: new Date(d.data_devolucao || d.created_at)
        }));

        return [...mappedAssistencias, ...mappedDevolucoes].sort((a, b) => b.dateForSort - a.dateForSort);
    }, [assistencias, devolucoes]);

    // Filtering
    const filtered = useMemo(() => {
        return unifiedList.filter(item => {
            const matchesSearch =
                item.numero_pedido?.toLowerCase().includes(searchTerm.toLowerCase()) ||
                item.cliente_nome?.toLowerCase().includes(searchTerm.toLowerCase()) ||
                item.descricao_problema?.toLowerCase().includes(searchTerm.toLowerCase());

            const matchesTipo = filterTipo === "todos" || item.tipo === filterTipo;
            const matchesStatus = filterStatus === "todos" || item.status === filterStatus;

            return matchesSearch && matchesTipo && matchesStatus;
        });
    }, [unifiedList, searchTerm, filterTipo, filterStatus]);

    // Statistics
    const stats = {
        abertas: assistencias.filter(a => a.status === 'Aberta').length,
        emAndamento: assistencias.filter(a => a.status === 'Em Andamento').length,
        aguardando: assistencias.filter(a => a.status === 'Aguardando Peça' || a.status === 'Aguardando Cliente').length,
        concluidas: assistencias.filter(a => a.status === 'Concluída').length,
        urgentes: assistencias.filter(a => a.prioridade === 'Urgente' && a.status !== 'Concluída' && a.status !== 'Cancelada').length
    };

    const handleDelete = async (id) => {
        const ok = window.confirm("Tem certeza que deseja excluir este registro? Esta ação não pode ser desfeita.");
        if (ok) {
            deleteMutation.mutate(id);
        }
    };

    const getTipoBadge = (tipo, itemType) => {
        if (itemType === 'devolucao') {
            const color = tipo === 'Troca' ? 'bg-orange-100 text-orange-800 border-orange-200' : 'bg-red-100 text-red-800 border-red-200';
            return <Badge className={`${color} border px-2 py-0.5 text-[10px] uppercase tracking-wider`}>{tipo}</Badge>;
        }
        const config = TIPOS_ASSISTENCIA.find(t => t.value === tipo) || TIPOS_ASSISTENCIA[5];
        return <Badge className={`${config.color} border px-2 py-0.5 text-[10px] uppercase tracking-wider`}>{tipo}</Badge>;
    };

    const getStatusBadge = (status, itemType) => {
        if (itemType === 'devolucao') {
            const styles = {
                "Aprovada": "bg-green-100 text-green-800 border-green-200",
                "Pendente": "bg-yellow-100 text-yellow-800 border-yellow-200",
                "Rejeitada": "bg-red-100 text-red-800 border-red-200",
                "Processada": "bg-blue-100 text-blue-800 border-blue-200"
            };
            return <Badge className={`${styles[status] || "bg-gray-100 text-gray-800"} border px-2 py-0.5 text-[10px] uppercase tracking-wider`}>{status}</Badge>;
        }
        const config = STATUS_OPTIONS.find(s => s.value === status) || STATUS_OPTIONS[0];
        return <Badge className={`${config.color} border px-2 py-0.5 text-[10px] uppercase tracking-wider`}>{status}</Badge>;
    };

    const getPrioridadeBadge = (prioridade) => {
        const config = PRIORIDADE_OPTIONS.find(p => p.value === prioridade) || PRIORIDADE_OPTIONS[1];
        return <Badge className={`${config.color} border px-2 py-0.5 text-[10px] uppercase tracking-wider`}>{prioridade}</Badge>;
    };

    const handleImprimir = async (assistencia) => {
        const venda = vendas.find(v => String(v.id) === String(assistencia.venda_id)) || null;
        const clienteCompleto = venda
            ? (clientes.find(c => c.id === venda.cliente_id) || {
                nome_completo: assistencia.cliente_nome,
                telefone: assistencia.cliente_telefone
            })
            : {
                nome_completo: assistencia.cliente_nome,
                telefone: assistencia.cliente_telefone
            };
        const lojaInfo = venda
            ? lojas.find(l => String(l.nome).trim().toLowerCase() === String(venda.loja || '').trim().toLowerCase()) || null
            : null;

        // Fetch only the specific products involved in this assistance request
        const productIds = [
            ...new Set(
                (assistencia.itens_envolvidos || []).flatMap(i => [i.produto_id, i.produto_sai_id].filter(Boolean))
            )
        ];

        let involvedProducts = [];
        if (productIds.length > 0) {
            try {
                const { data } = await supabase
                    .from('produtos')
                    .select('*')
                    .in('id', productIds);
                involvedProducts = data || [];
            } catch (err) {
                console.error("Erro ao carregar produtos envolvidos para o PDF:", err);
            }
        }

        abrirAssistenciaTecnicaPDF(assistencia, venda, clienteCompleto, lojaInfo ? { ...lojaInfo, empresa_nome: brandName } : null, involvedProducts);
    };

    return (
        <div className="max-w-7xl mx-auto space-y-6">

            {/* Header */}
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
                        <Wrench className="w-6 h-6 text-green-700" />
                        Assistência Técnica
                    </h1>
                    <p className="text-sm text-gray-500">Gestão de devoluções, trocas, consertos e suporte pós-venda</p>
                </div>
                <div className="flex gap-2">
                    <Button
                        variant="outline"
                        onClick={() => {
                            const origin = window.location.hostname === 'localhost' ? 'https://moveispedro2.com.br' : window.location.origin;
                            const link = `${origin}/assistencia/auto`;
                            navigator.clipboard.writeText(link);
                            toast.success("Link copiado para a área de transferência!");
                        }}
                    >
                        <LinkIcon className="w-4 h-4 mr-2" />
                        Link Autoatendimento
                    </Button>
                    <Button
                        onClick={() => { setEditingAssistencia(null); setIsModalOpen(true); }}
                        className="bg-green-700 hover:bg-green-800 text-white"
                    >
                        <Plus className="w-4 h-4 mr-2" /> Nova Assistência
                    </Button>
                </div>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                <Card className="border-l-4 border-l-blue-500">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-2xl font-bold text-blue-600">{stats.abertas}</p>
                                <p className="text-xs text-gray-500">Abertas</p>
                            </div>
                            <AlertCircle className="w-8 h-8 text-blue-200" />
                        </div>
                    </CardContent>
                </Card>
                <Card className="border-l-4 border-l-yellow-500">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-2xl font-bold text-yellow-600">{stats.emAndamento}</p>
                                <p className="text-xs text-gray-500">Em Andamento</p>
                            </div>
                            <Clock className="w-8 h-8 text-yellow-200" />
                        </div>
                    </CardContent>
                </Card>
                <Card className="border-l-4 border-l-orange-500">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-2xl font-bold text-orange-600">{stats.aguardando}</p>
                                <p className="text-xs text-gray-500">Aguardando</p>
                            </div>
                            <Package className="w-8 h-8 text-orange-200" />
                        </div>
                    </CardContent>
                </Card>
                <Card className="border-l-4 border-l-green-500">
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-2xl font-bold text-green-600">{stats.concluidas}</p>
                                <p className="text-xs text-gray-500">Concluídas</p>
                            </div>
                            <CheckCircle className="w-8 h-8 text-green-200" />
                        </div>
                    </CardContent>
                </Card>
                <Card className={`border-l-4 ${stats.urgentes > 0 ? 'border-l-red-500 bg-red-50' : 'border-l-gray-300'}`}>
                    <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                            <div>
                                <p className={`text-2xl font-bold ${stats.urgentes > 0 ? 'text-red-600' : 'text-gray-400'}`}>
                                    {stats.urgentes}
                                </p>
                                <p className="text-xs text-gray-500">Urgentes</p>
                            </div>
                            <AlertCircle className={`w-8 h-8 ${stats.urgentes > 0 ? 'text-red-300' : 'text-gray-200'}`} />
                        </div>
                    </CardContent>
                </Card>
            </div>

            {/* Filters */}
            <div className="bg-white dark:bg-neutral-900 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-neutral-800">
                <div className="flex flex-wrap gap-4 items-center">
                    <div className="relative flex-1 min-w-[200px]">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                        <Input
                            placeholder="Buscar por pedido, cliente ou descrição..."
                            className="pl-9 border-gray-200 dark:border-neutral-700"
                            value={searchTerm}
                            onChange={e => setSearchTerm(e.target.value)}
                        />
                    </div>
                    <div className="flex items-center gap-2">
                        <Filter className="w-4 h-4 text-gray-400" />
                        <Select value={filterTipo} onValueChange={setFilterTipo}>
                            <SelectTrigger className="w-[150px]">
                                <SelectValue placeholder="Tipo" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="todos">Todos os Tipos</SelectItem>
                                {TIPOS_ASSISTENCIA.map(t => (
                                    <SelectItem key={t.value} value={t.value}>{t.label}</SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                        <Select value={filterStatus} onValueChange={setFilterStatus}>
                            <SelectTrigger className="w-[180px]">
                                <SelectValue placeholder="Status" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="todos">Todos os Status</SelectItem>
                                {STATUS_OPTIONS.map(s => (
                                    <SelectItem key={s.value} value={s.value}>{s.label}</SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </div>
                </div>
            </div>

            {/* Table */}
            <div className="bg-white dark:bg-neutral-900 rounded-xl shadow-sm border border-gray-100 dark:border-neutral-800 overflow-hidden">
                <Table>
                    <TableHeader className="bg-gray-50 dark:bg-neutral-950">
                        <TableRow>
                            <TableHead>Pedido</TableHead>
                            <TableHead>Cliente</TableHead>
                            <TableHead>Tipo</TableHead>
                            <TableHead>Problema</TableHead>
                            <TableHead>Prioridade</TableHead>
                            <TableHead>Status</TableHead>
                            <TableHead>Data</TableHead>
                            <TableHead className="text-right">Ações</TableHead>
                        </TableRow>
                    </TableHeader>
                    <TableBody>
                        {isLoading ? (
                            <TableRow>
                                <TableCell colSpan={8} className="text-center py-8">
                                    <Loader2 className="w-6 h-6 animate-spin mx-auto" />
                                </TableCell>
                            </TableRow>
                        ) : filtered.length === 0 ? (
                            <TableRow>
                                <TableCell colSpan={8} className="text-center py-8 text-gray-500">
                                    Nenhuma assistência encontrada.
                                </TableCell>
                            </TableRow>
                        ) : (
                            filtered.map(a => (
                                <TableRow key={`${a.itemType}-${a.id}`} className={a.prioridade === 'Urgente' && a.status !== 'Concluída' ? 'bg-red-50' : ''}>
                                    <TableCell className="font-medium">#{a.numero_pedido}</TableCell>
                                    <TableCell>{a.cliente_nome}</TableCell>
                                    <TableCell>{getTipoBadge(a.tipo, a.itemType)}</TableCell>
                                    <TableCell className="max-w-[200px] truncate text-sm text-gray-600">
                                        {a.descricao_problema}
                                    </TableCell>
                                    <TableCell>{a.itemType === 'devolucao' ? '-' : getPrioridadeBadge(a.prioridade)}</TableCell>
                                    <TableCell>{getStatusBadge(a.status, a.itemType)}</TableCell>
                                    <TableCell className="text-sm text-gray-500">
                                        {new Date(a.itemType === 'devolucao' ? a.data_devolucao : a.data_abertura).toLocaleDateString('pt-BR')}
                                    </TableCell>
                                    <TableCell className="text-right">
                                        <div className="flex justify-end gap-2">
                                            {a.itemType === 'assistencia' ? (
                                                <>
                                                    <Button
                                                        variant="ghost"
                                                        size="icon"
                                                        onClick={() => handleImprimir(a)}
                                                        title="Imprimir assistência"
                                                    >
                                                        <FileText className="w-4 h-4 text-green-700" />
                                                    </Button>
                                                    <Button
                                                        variant="ghost"
                                                        size="icon"
                                                        onClick={() => { setEditingAssistencia(a); setIsModalOpen(true); }}
                                                    >
                                                        <Edit className="w-4 h-4 text-blue-600" />
                                                    </Button>
                                                    <Button
                                                        variant="ghost"
                                                        size="icon"
                                                        onClick={() => handleDelete(a.id)}
                                                    >
                                                        <Trash2 className="w-4 h-4 text-red-600" />
                                                    </Button>
                                                </>
                                            ) : (
                                                <>
                                                    <Button
                                                        variant="ghost"
                                                        size="icon"
                                                        onClick={() => { setEditingAssistencia(a); setIsModalOpen(true); }}
                                                    >
                                                        <Edit className="w-4 h-4 text-blue-600" />
                                                    </Button>
                                                    <Button
                                                        variant="ghost"
                                                        size="icon"
                                                        disabled={a.status === 'Aprovada'}
                                                        onClick={() => handleDeleteDevolucao(a.id)}
                                                    >
                                                        <Trash2 className="w-4 h-4 text-red-600" />
                                                    </Button>
                                                </>
                                            )}
                                        </div>
                                    </TableCell>
                                </TableRow>
                            ))
                        )}
                    </TableBody>
                </Table>
            </div>

            {/* Modal principal */}
            <AssistenciaTecnicaModal
                isOpen={isModalOpen}
                onClose={() => { setIsModalOpen(false); setEditingAssistencia(null); }}
                onSave={handleSave}
                assistencia={editingAssistencia}
                vendas={vendas}
                produtos={produtos}
                fornecedores={fornecedores}
                devolucoes={devolucoes}
                onSaveDevolucao={handleSaveDevolucao}
                savingDevolucao={savingDevolucao}
                isLoading={saving}
            />

            {/* Modal de seleção de loja para reposição */}
            <SelecionarLojaReposicaoModal
                isOpen={isReposicaoModalOpen}
                onClose={handleCancelarReposicao}
                onConfirm={handleConfirmarReposicao}
                itens={(reposicaoPendente?.formData?.itens_envolvidos || []).map(item => ({
                    produto_id: item.produto_sai_id || item.produto_id,
                    produto_nome: item.produto_sai_nome || item.produto_nome,
                    quantidade: item.produto_sai_quantidade || item.quantidade
                }))}
                lojas={lojas}
            />
        </div>
    );
}

import React, { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { base44 } from "@/api/base44Client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import {
  ShieldCheck, Search, User, Calendar, Edit, Trash2,
  CheckCircle, XCircle, UserPlus, LogIn, LogOut
} from "lucide-react";
import { format } from "date-fns";

const actionIcons = {
  CREATE: UserPlus,
  UPDATE: Edit,
  DELETE: Trash2,
  APPROVE: CheckCircle,
  REJECT: XCircle,
  CANCEL: XCircle,
  LOGIN: LogIn,
  LOGOUT: LogOut
};

const actionColors = {
  CREATE: 'bg-green-100 text-green-700 border-green-300',
  UPDATE: 'bg-blue-100 text-blue-700 border-blue-300',
  DELETE: 'bg-red-100 text-red-700 border-red-300',
  APPROVE: 'bg-green-100 text-green-700 border-green-300',
  REJECT: 'bg-red-100 text-red-700 border-red-300',
  CANCEL: 'bg-orange-100 text-orange-700 border-orange-300',
  LOGIN: 'bg-purple-100 text-purple-700 border-purple-300',
  LOGOUT: 'bg-gray-100 text-gray-700 border-gray-300'
};

export default function AuditLogPage() {
  const [searchTerm, setSearchTerm] = useState("");
  const [filterAction, setFilterAction] = useState("all");
  const [filterEntity, setFilterEntity] = useState("all");

  const { data: rawLogs = [], isLoading, isError } = useQuery({
    queryKey: ['audit-logs'],
    queryFn: () => base44.entities.AuditLog.list('-created_at'),
    refetchInterval: 10000,
      staleTime: 30000,
      retry: false,
  });

  const inferChanges = (log) => {
    const directChanges = log.detalhes?.changes || log.changes;
    if (directChanges && typeof directChanges === 'object' && !Array.isArray(directChanges)) {
      return directChanges;
    }

    const oldData = log.old_data && typeof log.old_data === 'object' ? log.old_data : {};
    const newData = log.new_data && typeof log.new_data === 'object' ? log.new_data : {};
    const keys = new Set([...Object.keys(oldData), ...Object.keys(newData)]);

    const normalized = {};
    keys.forEach((key) => {
      const before = oldData[key];
      const after = newData[key];
      if (JSON.stringify(before) !== JSON.stringify(after)) {
        normalized[key] = { before, after };
      }
    });

    return normalized;
  };

  // Map database columns to expected format
  const logs = rawLogs.map(log => ({
    ...log,
    action: log.acao || log.action || 'UPDATE',
    user_name: log.usuario || log.user_name || log.user_email || 'Unknown',
    user_email: log.user_email || '',
    user_cargo: log.user_cargo || '',
    entity_type: log.tabela || log.entity_type || log.table_name || '',
    entity_description: log.detalhes?.description || log.entity_description || (log.table_name ? `Registro em ${log.table_name}` : ''),
    changes: inferChanges(log),
    timestamp: log.created_at || log.timestamp,
    ip_address: log.ip_address || ''
  }));

  const filteredLogs = logs.filter(log => {
    const matchesSearch =
      log.user_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      log.user_email?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      log.entity_description?.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesAction = filterAction === "all" || log.action === filterAction;
    const matchesEntity = filterEntity === "all" || log.entity_type === filterEntity;

    return matchesSearch && matchesAction && matchesEntity;
  });

  const entityTypes = [...new Set(logs.map(l => l.entity_type))].filter(Boolean);

  return (
    <div className="max-w-7xl mx-auto space-y-6">
      <div>
        <h1 className="text-3xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
          <ShieldCheck className="w-8 h-8 text-green-700" />
          Registro de Auditoria
        </h1>
        <p className="text-sm text-gray-500 mt-1">
          Histórico completo de todas as ações realizadas no sistema
        </p>
      </div>

      <Card className="border-0 shadow-lg">
        <CardHeader>
          <CardTitle>Filtros</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid md:grid-cols-3 gap-4">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
              <Input
                placeholder="Buscar usuário ou ação..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-10"
              />
            </div>

            <Select value={filterAction} onValueChange={setFilterAction}>
              <SelectTrigger>
                <SelectValue placeholder="Tipo de Ação" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Todas as Ações</SelectItem>
                <SelectItem value="CREATE">Criar</SelectItem>
                <SelectItem value="UPDATE">Editar</SelectItem>
                <SelectItem value="DELETE">Deletar</SelectItem>
                <SelectItem value="APPROVE">Aprovar</SelectItem>
                <SelectItem value="REJECT">Rejeitar</SelectItem>
                <SelectItem value="CANCEL">Cancelar</SelectItem>
                <SelectItem value="LOGIN">Login</SelectItem>
                <SelectItem value="LOGOUT">Logout</SelectItem>
              </SelectContent>
            </Select>

            <Select value={filterEntity} onValueChange={setFilterEntity}>
              <SelectTrigger>
                <SelectValue placeholder="Tipo de Entidade" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Todas as Entidades</SelectItem>
                {entityTypes.map(type => (
                  <SelectItem key={type} value={type}>{type}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </CardContent>
      </Card>

      {isLoading ? (
        <div className="flex justify-center items-center py-12">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-600" />
        </div>
      ) : isError ? (
        <Card className="border-0 shadow-lg">
          <CardContent className="py-12 text-center">
            <ShieldCheck className="w-16 h-16 mx-auto mb-4 opacity-20 text-red-400" />
            <p className="text-gray-500">Não foi possível carregar os logs de auditoria.</p>
            <p className="text-sm text-gray-400 mt-1">A tabela pode não estar configurada ainda.</p>
          </CardContent>
        </Card>
      ) : (
        <Card className="border-0 shadow-lg">
          <CardContent className="p-0">
            <div className="divide-y divide-gray-200 dark:divide-neutral-800">
              {filteredLogs.length === 0 ? (
                <div className="text-center py-12 text-gray-500">
                  <ShieldCheck className="w-16 h-16 mx-auto mb-4 opacity-20" />
                  <p>Nenhum registro encontrado</p>
                </div>
              ) : (
                filteredLogs.map(log => {
                  const ActionIcon = actionIcons[log.action] || Edit;

                  return (
                    <div key={log.id} className="p-4 hover:bg-gray-50 dark:hover:bg-neutral-800 transition-colors">
                      <div className="flex items-start gap-4">
                        <div className={`w-10 h-10 rounded-full flex items-center justify-center flex-shrink-0 ${actionColors[log.action] || 'bg-gray-100'}`}>
                          <ActionIcon className="w-5 h-5" />
                        </div>

                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 mb-1 flex-wrap">
                            <span className="font-semibold text-gray-900 dark:text-white">
                              {log.user_name || 'Usuário Desconhecido'}
                            </span>
                            <Badge variant="outline" className="text-xs">
                              {log.user_cargo || 'Sem cargo'}
                            </Badge>
                            <Badge className={`text-xs ${actionColors[log.action]}`}>
                              {log.action}
                            </Badge>
                          </div>

                          <p className="text-sm text-gray-600 dark:text-gray-400 mb-2">
                            {log.entity_type && (
                              <span className="font-medium">{log.entity_type}</span>
                            )}
                            {log.entity_description && (
                              <span> - {log.entity_description}</span>
                            )}
                          </p>

                          {log.changes && Object.keys(log.changes).length > 0 && (
                            <div className="bg-gray-50 dark:bg-neutral-900 rounded p-2 text-xs mt-2">
                              <p className="font-semibold mb-1 text-gray-700 dark:text-gray-300">Alterações:</p>
                              {Object.entries(log.changes).map(([key, value]) => (
                                <div key={key} className="text-gray-600 dark:text-gray-400 mb-1">
                                  <span className="font-medium">{key}:</span>{' '}
                                  {value.before !== undefined && (
                                    <>
                                      <span className="line-through text-red-600">
                                        {JSON.stringify(value.before)}
                                      </span>
                                      {' → '}
                                    </>
                                  )}
                                  <span className="text-green-600">
                                    {JSON.stringify(value.after)}
                                  </span>
                                </div>
                              ))}
                            </div>
                          )}

                          <div className="flex items-center gap-4 mt-2 text-xs text-gray-500">
                            <div className="flex items-center gap-1">
                              <User className="w-3 h-3" />
                              {log.user_email}
                            </div>
                            <div className="flex items-center gap-1">
                              <Calendar className="w-3 h-3" />
                              {log.timestamp && format(new Date(log.timestamp), 'dd/MM/yyyy HH:mm')}
                            </div>
                            {log.ip_address && (
                              <div className="text-gray-400">
                                IP: {log.ip_address}
                              </div>
                            )}
                          </div>
                        </div>
                      </div>
                    </div>
                  );
                })
              )}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import React, { useState, useRef, useEffect } from 'react';
import { supabase, base44 } from "@/api/base44Client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Camera, Search, ArrowRight, CheckCircle, RefreshCcw, Loader2, Trash2, AlertTriangle, Image as ImageIcon, Clock } from "lucide-react";
import { toast } from "sonner";
import { useTenant } from "@/contexts/TenantContext";


const TIPOS_ASSISTENCIA = [
    { value: "Devolução", label: "Devolução" },
    { value: "Troca", label: "Troca" },
    { value: "Peça Faltante", label: "Peça Faltante" },
    { value: "Conserto", label: "Conserto" },
    { value: "Outros", label: "Outros" }
];

export default function AutoAtendimento() {
    const { brandName, brandLogo, organization } = useTenant();
    const [step, setStep] = useState(0);
    const [loading, setLoading] = useState(false);


    // Identification
    const [searchTerm, setSearchTerm] = useState("");
    const [pedido, setPedido] = useState(null);
    const [pedidosRelacionados, setPedidosRelacionados] = useState([]);
    const [errorMsg, setErrorMsg] = useState("");
    const [orderStatus, setOrderStatus] = useState(null); // Para mostrar status se não entregue

    // Details
    const [tipo, setTipo] = useState("Conserto");
    const [descricao, setDescricao] = useState("");

    // Camera
    const videoRef = useRef(null);
    const canvasRef = useRef(null);
    const [stream, setStream] = useState(null);
    const [cameraActive, setCameraActive] = useState(false);
    const [photos, setPhotos] = useState([]);

    // Cleanup stream on unmount
    useEffect(() => {
        return () => {
            if (stream) {
                stream.getTracks().forEach(track => track.stop());
            }
        };
    }, [stream]);

    // Step 1: Find Order
    const handleSearch = async (forcedPedido = null) => {
        setErrorMsg("");
        if (!searchTerm.trim()) {
            const msg = "Digite o número do pedido ou CPF";
            setErrorMsg(msg);
            toast.error(msg);
            return;
        }

        setLoading(true);
        try {
            const cleanSearch = searchTerm.replace(/\D/g, ''); // Remove non-digits for CPF

            // First try by numero_pedido
            let { data, error } = await supabase
                .from('vendas')
                .select('*')
                .eq('numero_pedido', searchTerm)
                .limit(1)
                .maybeSingle();

            // If not found by pedido, try by CPF/CNPJ or telefone via clientes table
            if (!data) {
                const searchParam = cleanSearch || searchTerm.trim();

                // Try to find client by CPF, CNPJ or telefone
                const { data: matchedClients, error: clientError } = await supabase
                    .from('clientes')
                    .select('id')
                    .or(`cpf.ilike.%${searchParam}%,cnpj.ilike.%${searchParam}%,cpf_cnpj.ilike.%${searchParam}%,telefone.ilike.%${searchParam}%`)
                    .limit(1);

                if (clientError) console.error('Erro ao buscar cliente:', clientError);

                if (matchedClients && matchedClients.length > 0) {
                    const cliente = matchedClients[0];
                    const { data: vendaByCliente, error: vendaError } = await supabase
                        .from('vendas')
                        .select('*')
                        .eq('cliente_id', cliente.id)
                        .order('data_venda', { ascending: false })
                        .limit(1)
                        .maybeSingle();

                    if (vendaError) console.error('Erro ao buscar venda por cliente:', vendaError);
                    data = vendaByCliente;
                }

                // Fallback: search directly in vendas by cliente_telefone or cliente_nome
                if (!data) {
                    const { data: vendaFallback, error: fallbackError } = await supabase
                        .from('vendas')
                        .select('*')
                        .or(`cliente_telefone.ilike.%${searchParam}%,cliente_nome.ilike.%${searchTerm.trim()}%`)
                        .order('data_venda', { ascending: false })
                        .limit(1)
                        .maybeSingle();

                    if (fallbackError) console.error('Erro ao buscar venda fallback:', fallbackError);
                    data = vendaFallback;
                }
            }

            if (error) throw error;

            if (data) {
                // Verificar se o pedido foi entregue
                const { data: entregas, error: entregaError } = await supabase
                    .from('entregas')
                    .select('id')
                    .eq('venda_id', data.id)
                    .eq('status', 'Entregue');

                if (entregaError) throw entregaError;

                if (!entregas || entregas.length === 0) {
                    const msg = "Solicitações de troca ou defeito só podem ser feitas após a entrega do pedido.";
                    setErrorMsg(msg);
                    toast.error(msg);
                    return;
                }

                setPedido(data);
                toast.success("Pedido encontrado!");
                setStep(1);
            } else {
                const msg = "Pedido não encontrado. Verifique os dados.";
                setErrorMsg(msg);
                toast.error(msg);
            }
        } catch (err) {
            console.error(err);
            const msg = "Erro ao buscar pedido. Tente novamente.";
            setErrorMsg(msg);
            toast.error(msg);
        } finally {
            setLoading(false);
        }
    };

    // Camera Logic
    const startCamera = async () => {
        try {
            const mediaStream = await navigator.mediaDevices.getUserMedia({
                video: { facingMode: "environment" },
                audio: false
            });
            setStream(mediaStream);
            setCameraActive(true);

            // Allow React to render the <video> element before attaching the stream
            setTimeout(() => {
                if (videoRef.current) {
                    videoRef.current.srcObject = mediaStream;
                    videoRef.current.play().catch(e => console.error("Error playing video:", e));
                }
            }, 100);

        } catch (err) {
            console.error("Erro ao acessar câmera:", err);
            toast.error("Não foi possível acessar a câmera. Verifique as permissões.");
        }
    };

    const stopCamera = () => {
        if (stream) {
            stream.getTracks().forEach(track => track.stop());
            setStream(null);
        }
        setCameraActive(false);
    };

    const takePhoto = () => {
        if (!videoRef.current || !canvasRef.current || !pedido) return;

        const video = videoRef.current;
        const canvas = canvasRef.current;
        const context = canvas.getContext('2d');

        // Default to client dimensions or standard HD if intrinsic dimensions are not yet available
        let width = video.videoWidth || video.clientWidth || 1280;
        let height = video.videoHeight || video.clientHeight || 720;

        // Maximum dimensions to prevent canvas memory/processing errors on mobile
        const MAX_WIDTH = 1280;
        const MAX_HEIGHT = 1280;

        // Calculate aspect ratio and resize if necessary
        if (width > height) {
            if (width > MAX_WIDTH) {
                height *= MAX_WIDTH / width;
                width = MAX_WIDTH;
            }
        } else {
            if (height > MAX_HEIGHT) {
                width *= MAX_HEIGHT / height;
                height = MAX_HEIGHT;
            }
        }

        // Set canvas dimensions
        canvas.width = width;
        canvas.height = height;

        // Draw video frame
        context.drawImage(video, 0, 0, canvas.width, canvas.height);

        // Add Watermark
        const date = new Date().toLocaleString('pt-BR');
        const text = `PEDIDO #${pedido.numero_pedido} - ${date} - ${brandName.toUpperCase()}`;


        context.font = 'bold 24px Arial';
        context.fillStyle = 'rgba(255, 255, 255, 0.8)';
        context.shadowColor = 'black';
        context.shadowBlur = 4;
        context.fillText(text, 20, canvas.height - 30);

        try {
            const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
            if (dataUrl === "data:,") {
                console.error("toDataURL returned empty data url.");
                toast.error("Erro ao processar imagem da câmera.");
                return;
            }
            // Convert dataUrl to blob object for the photos array (to match the expected structure)
            fetch(dataUrl)
                .then(res => res.blob())
                .then(blob => {
                    const url = URL.createObjectURL(blob);
                    setPhotos(prev => [...prev, { blob, url, name: `foto_${Date.now()}.jpg` }]);
                    toast.success("Foto capturada!");
                    stopCamera();
                })
                .catch(err => {
                    console.error("Failed to convert dataURL to blob", err);
                    toast.error("Erro interno ao processar a memória da imagem.");
                });
        } catch (e) {
            console.error("toDataURL Error:", e);
            toast.error("Erro na captura. O dispositivo pode estar sem memória para imagens grandes.");
        }
    };

    const removePhoto = (index) => {
        setPhotos(prev => prev.filter((_, i) => i !== index));
    };

    // Final Submission
    const handleSubmit = async () => {
        if (photos.length === 0) {
            toast.error("Por favor, tire pelo menos uma foto do problema.");
            return;
        }
        if (!descricao.trim()) {
            toast.error("Por favor, descreva o problema.");
            return;
        }

        setLoading(true);
        try {
            // Upload Photos
            const uploadedFiles = [];
            for (const photo of photos) {
                const file = new File([photo.blob], photo.name, { type: 'image/jpeg' });
                const result = await base44.integrations.Core.UploadFile({ file });
                uploadedFiles.push({
                    nome: photo.name,
                    url: result.file_url,
                    tipo: 'image/jpeg',
                    data: new Date().toISOString()
                });
            }

            // Create Assistance Record
            const { error } = await supabase.from('assistencias_tecnicas').insert({
                organization_id: pedido?.organization_id || organization?.id || null,
                venda_id: pedido.id,
                numero_pedido: pedido.numero_pedido,
                cliente_nome: pedido.cliente_nome,
                cliente_telefone: pedido.cliente_telefone,
                tipo: tipo,
                descricao_problema: descricao,
                status: 'Aberta',
                prioridade: 'Normal',
                data_abertura: new Date().toISOString(),
                arquivos: uploadedFiles,
                observacoes: 'Solicitação via Autoatendimento'
            });


            if (error) throw error;

            setStep(3); // Success Step
            toast.success("Solicitação enviada com sucesso!");

        } catch (err) {
            console.error(err);
            toast.error("Erro ao enviar solicitação.");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4">
            <div className="max-w-md w-full">

                {/* Header Logo */}
                <div className="text-center mb-6">
                    {brandLogo && <img src={brandLogo} alt={brandName} className="h-16 mx-auto mb-2 object-contain" />}
                    <h1 className="text-2xl font-bold text-green-800">{brandName}</h1>
                    <p className="text-gray-500">Autoatendimento Assistência Técnica</p>
                </div>


                {/* STEPS */}
                {step === 0 && (
                    <Card>
                        <CardHeader>
                            <CardTitle>Identificação</CardTitle>
                        </CardHeader>
                        <CardContent className="space-y-4">
                            <p className="text-sm text-gray-600">
                                Para iniciar, digite o número do seu pedido ou seu CPF (apenas números).
                            </p>
                            <div className="space-y-2">
                                <Label>Número do Pedido ou CPF</Label>
                                <Input
                                    placeholder="Ex: 12345 ou CPF"
                                    value={searchTerm}
                                    onChange={e => {
                                        setSearchTerm(e.target.value);
                                        setErrorMsg("");
                                    }}
                                    onKeyDown={e => e.key === 'Enter' && handleSearch()}
                                    className={errorMsg ? "border-red-500" : ""}
                                />
                                {errorMsg && (
                                    <p className="text-sm text-red-600 flex items-center mt-1">
                                        <AlertTriangle className="w-4 h-4 mr-1" />
                                        {errorMsg}
                                    </p>
                                )}
                            </div>
                            <Button className="w-full bg-green-700 hover:bg-green-800 text-white" onClick={() => handleSearch()} disabled={loading}>
                                {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : "Buscar Pedido"}
                            </Button>

                            {/* Seleção de Pedidos se houver múltiplos */}
                            {pedidosRelacionados.length > 0 && (
                                <div className="mt-6 pt-6 border-t">
                                    <h3 className="font-semibold text-sm mb-3">Encontramos mais de um pedido. Selecione um:</h3>
                                    <div className="space-y-2">
                                        {pedidosRelacionados.map((p) => (
                                            <button
                                                key={p.id}
                                                onClick={() => handleSearch(p)}
                                                className="w-full text-left p-3 rounded-lg border hover:border-green-500 hover:bg-green-50 transition-colors flex justify-between items-center group"
                                            >
                                                <div>
                                                    <p className="font-medium text-sm">Pedido #{p.numero_pedido}</p>
                                                    <p className="text-xs text-gray-500">
                                                        {new Date(p.data_venda).toLocaleDateString('pt-BR')} - {p.loja}
                                                    </p>
                                                </div>
                                                <ArrowRight className="w-4 h-4 text-gray-300 group-hover:text-green-600" />
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            )}
                        </CardContent>
                    </Card>
                )}

                {step === 1 && (
                    <Card>
                        <CardHeader>
                            <CardTitle>Detalhes do Problema</CardTitle>
                        </CardHeader>
                        <CardContent className="space-y-4">
                            <div className="bg-green-50 p-3 rounded-lg border border-green-100 text-sm mb-2">
                                <p><strong>Pedido:</strong> #{pedido?.numero_pedido}</p>
                                <p><strong>Cliente:</strong> {pedido?.cliente_nome}</p>
                            </div>

                            {/* Request Type hidden or defaulted since customer doesn't decide */}
                            <div className="bg-amber-50 p-3 rounded-lg border border-amber-100 text-sm mb-4">
                                <p className="text-amber-800 font-medium flex items-center gap-2">
                                    <AlertTriangle className="w-4 h-4" />
                                    Sua solicitação será analisada
                                </p>
                                <p className="text-amber-700 mt-1">
                                    Nossa equipe técnica avaliará o problema relatado e as fotos para determinar se será necessário troca, conserto ou envio de peças.
                                </p>
                            </div>

                            <div className="space-y-2">
                                <Label>Descrição do Problema</Label>
                                <Textarea
                                    placeholder="Descreva o que aconteceu..."
                                    value={descricao}
                                    onChange={e => setDescricao(e.target.value)}
                                    rows={3}
                                />
                            </div>

                            <Button className="w-full" onClick={() => setStep(2)}>
                                Próximo: Fotos <ArrowRight className="w-4 h-4 ml-2" />
                            </Button>
                        </CardContent>
                    </Card>
                )}

                {step === 2 && (
                    <Card>
                        <CardHeader>
                            <CardTitle className="flex justify-between items-center">
                                Fotos do Problema
                                <span className="text-sm font-normal text-gray-500">{photos.length} fotos</span>
                            </CardTitle>
                        </CardHeader>
                        <CardContent className="space-y-4">
                            <AlertTriangle className="w-8 h-8 text-amber-500 mx-auto" />
                            <p className="text-center text-sm text-gray-600">
                                Tire fotos claras do defeito. A câmera será ativada e a data será registrada automaticamente na foto.
                            </p>

                            {/* Camera View */}
                            {cameraActive ? (
                                <div className="space-y-4">
                                    <div className="aspect-[3/4] bg-black rounded-lg overflow-hidden relative">
                                        <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover"></video>
                                        <canvas ref={canvasRef} className="hidden"></canvas>
                                    </div>
                                    <div className="grid grid-cols-2 gap-2">
                                        <Button variant="outline" onClick={stopCamera} className="w-full">
                                            Cancelar
                                        </Button>
                                        <Button onClick={takePhoto} className="w-full bg-green-600 hover:bg-green-700 text-white">
                                            <Camera className="w-4 h-4 mr-2" /> Capturar
                                        </Button>
                                    </div>
                                </div>
                            ) : (
                                <Button className="w-full py-8 text-lg bg-blue-600 hover:bg-blue-700 text-white" onClick={startCamera}>
                                    <Camera className="w-6 h-6 mr-2" /> Abrir Câmera
                                </Button>
                            )}

                            {/* Gallery of captured photos */}
                            {photos.length > 0 && !cameraActive && (
                                <div className="grid grid-cols-3 gap-2 mt-4">
                                    {photos.map((photo, idx) => (
                                        <div key={idx} className="relative aspect-square rounded-lg overflow-hidden border">
                                            <img src={photo.url} alt="Evidencia" className="w-full h-full object-cover" />
                                            <button
                                                onClick={() => removePhoto(idx)}
                                                className="absolute top-1 right-1 bg-red-500 text-white p-1 rounded-full shadow-md"
                                            >
                                                <Trash2 className="w-3 h-3" />
                                            </button>
                                        </div>
                                    ))}
                                </div>
                            )}

                            {!cameraActive && (
                                <div className="flex gap-2 pt-4">
                                    <Button variant="outline" onClick={() => setStep(1)} className="flex-1">
                                        Voltar
                                    </Button>
                                    <Button
                                        className="flex-1 bg-green-700 hover:bg-green-800 text-white"
                                        onClick={handleSubmit}
                                        disabled={loading || photos.length === 0}
                                    >
                                        {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : "Enviar Solicitação"}
                                    </Button>
                                </div>
                            )}
                        </CardContent>
                    </Card>
                )}

                {step === 4 && (
                    <Card className="border-t-4 border-t-amber-500">
                        <CardHeader>
                            <CardTitle className="flex items-center gap-2">
                                <Clock className="w-5 h-5 text-amber-500" />
                                Status do Pedido
                            </CardTitle>
                        </CardHeader>
                        <CardContent className="space-y-6">
                            <div className="bg-gray-50 p-4 rounded-lg space-y-3">
                                <div className="flex justify-between items-center">
                                    <span className="text-sm text-gray-500">Número do Pedido:</span>
                                    <span className="font-semibold">#{pedido?.numero_pedido}</span>
                                </div>
                                <div className="flex justify-between items-center">
                                    <span className="text-sm text-gray-500">Status Geral:</span>
                                    <span className={`px-2 py-1 rounded-full text-xs font-medium ${pedido?.status === 'Entregue' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'
                                        }`}>
                                        {pedido?.status}
                                    </span>
                                </div>
                                <div className="flex justify-between items-center border-t pt-2 mt-2">
                                    <span className="text-sm text-gray-500">Status da Entrega:</span>
                                    <span className="font-medium text-amber-700">{orderStatus?.entrega}</span>
                                </div>
                            </div>

                            <p className="text-sm text-gray-600 text-center">
                                Solicitações de assistência técnica, troca ou devolução só podem ser realizadas após a entrega ser confirmada pelo sistema.
                            </p>

                            <Button onClick={() => setStep(0)} variant="outline" className="w-full">
                                Nova Consulta
                            </Button>
                        </CardContent>
                    </Card>
                )}

                {step === 3 && (
                    <Card className="border-t-4 border-t-green-600 text-center p-6">
                        <CardContent className="space-y-4">
                            <CheckCircle className="w-16 h-16 text-green-600 mx-auto" />
                            <h2 className="text-2xl font-bold text-gray-900">Solicitação Enviada!</h2>
                            <p className="text-gray-600">
                                Recebemos seu pedido de assistência. Nossa equipe analisará as fotos e entrará em contato em breve.
                            </p>
                            <p className="text-sm text-gray-500">
                                Protocolo gerado para o pedido #{pedido?.numero_pedido}
                            </p>
                            <Button onClick={() => window.location.reload()} variant="outline" className="mt-4">
                                Voltar ao Início
                            </Button>
                        </CardContent>
                    </Card>
                )}
            </div>
        </div>
    );
}

import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import { supabase } from "@/api/base44Client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
