            if (pendingReturnUrl) {
              navigate(pendingReturnUrl);
              setPendingReturnUrl(null);
            }
          }}
        />
      )}

      {isCRMModalOpen && (
        <ClienteCRMModal
          cliente={selectedCRMCliente}
          isOpen={isCRMModalOpen}
          onClose={() => {
            setIsCRMModalOpen(false);
            setSelectedCRMCliente(null);
          }}
        />
      )}

      {/* Dialog Preview do Portal do Cliente */}
      <Dialog open={previewModalOpen} onOpenChange={setPreviewModalOpen}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto bg-neutral-950 text-white border border-neutral-800">
          <DialogHeader className="border-b border-neutral-800 pb-3">
            <DialogTitle className="text-base font-bold flex items-center justify-between text-white">
              <span className="flex items-center gap-2">
                <Eye className="w-4 h-4 text-green-400" /> Prévia do Portal: {previewCliente?.nome_completo}
              </span>
              <Badge className="bg-amber-500/20 text-amber-300 border-amber-500/30">
                Tema: {getPortalTheme(selectedPortalTheme).name}
              </Badge>
            </DialogTitle>
          </DialogHeader>

          {previewCliente ? (
            <div className="py-2 space-y-4">
              {/* Selector de Abas da Prévia */}
              <div className="flex items-center justify-between gap-2 border-b border-neutral-800 pb-2">
                <div className="flex gap-2">
                  <button
                    onClick={() => setPreviewTab('login')}
                    className={`px-3 py-1.5 rounded-lg text-xs font-semibold transition-all ${previewTab === 'login' ? 'bg-green-600 text-white' : 'bg-neutral-800 text-neutral-400 hover:text-white'
                      }`}
                  >
                    1. Tela de Login
                  </button>
                  <button
                    onClick={() => setPreviewTab('cadastro')}
                    className={`px-3 py-1.5 rounded-lg text-xs font-semibold transition-all ${previewTab === 'cadastro' ? 'bg-green-600 text-white' : 'bg-neutral-800 text-neutral-400 hover:text-white'
                      }`}
                  >
                    2. Tela de Cadastro
                  </button>
                  <button
                    onClick={() => setPreviewTab('painel')}
                    className={`px-3 py-1.5 rounded-lg text-xs font-semibold transition-all ${previewTab === 'painel' ? 'bg-green-600 text-white' : 'bg-neutral-800 text-neutral-400 hover:text-white'
                      }`}
                  >
                    3. Painel do Cliente
                  </button>
                </div>
              </div>

              {/* Viewport Frame */}
              <div className="rounded-2xl border border-neutral-800 overflow-hidden shadow-2xl p-4 sm:p-6 transition-all duration-300 bg-stone-900">
                {(() => {
                  const theme = getPortalTheme(selectedPortalTheme);
                  const isAuthTab = previewTab === 'login' || previewTab === 'cadastro';
                  const styles = isAuthTab ? theme.auth : theme.dashboard;

                  if (previewTab === 'login') {
                    return (
                      <div className={`p-6 sm:p-8 rounded-2xl ${styles.bg} transition-all`}>
                        <div className="max-w-md mx-auto space-y-6">
                          <div className="text-center space-y-2">
                            <h3 className={`text-2xl font-bold ${styles.textHeading}`}>{selectedOrgObj.name}</h3>
                            <p className={`text-xs ${styles.textMuted}`}>Acesse sua Área Exclusiva do Cliente</p>
                          </div>

                          <div className={`p-6 rounded-2xl ${styles.card} space-y-4`}>
                            <div className="space-y-1">
                              <label className={`text-xs font-semibold ${styles.textMuted}`}>E-mail ou CPF</label>
                              <input disabled type="text" value={previewCliente.email || previewCliente.cpf || ""} className={`w-full px-3 py-2 text-xs rounded-xl ${styles.input}`} />
                            </div>
                            <div className="space-y-1">
                              <label className={`text-xs font-semibold ${styles.textMuted}`}>Senha</label>
                              <input disabled type="password" value="••••••••" className={`w-full px-3 py-2 text-xs rounded-xl ${styles.input}`} />
                            </div>
                            <button className={`w-full py-2.5 text-xs rounded-xl ${styles.primaryButton}`}>
                              Entrar no Painel
                            </button>
                          </div>
                        </div>
                      </div>
                    );
                  }

                  if (previewTab === 'cadastro') {
                    return (
                      <div className={`p-6 sm:p-8 rounded-2xl ${styles.bg} transition-all`}>
                        <div className="max-w-md mx-auto space-y-6">
                          <div className="text-center space-y-2">
                            <h3 className={`text-2xl font-bold ${styles.textHeading}`}>Criar Minha Conta</h3>
                            <p className={`text-xs ${styles.textMuted}`}>Cadastre-se na loja {selectedOrgObj.name}</p>
                          </div>

                          <div className={`p-6 rounded-2xl ${styles.card} space-y-4`}>
                            <div className="space-y-1">
                              <label className={`text-xs font-semibold ${styles.textMuted}`}>Nome Completo</label>
                              <input disabled type="text" value={previewCliente.nome_completo || ""} className={`w-full px-3 py-2 text-xs rounded-xl ${styles.input}`} />
                            </div>
                            <div className="grid grid-cols-2 gap-2">
                              <div className="space-y-1">
                                <label className={`text-xs font-semibold ${styles.textMuted}`}>Telefone / WhatsApp</label>
                                <input disabled type="text" value={previewCliente.telefone || "(38) 99999-0000"} className={`w-full px-3 py-2 text-xs rounded-xl ${styles.input}`} />
                              </div>
                              <div className="space-y-1">
                                <label className={`text-xs font-semibold ${styles.textMuted}`}>CPF</label>
                                <input disabled type="text" value={previewCliente.cpf || "000.000.000-00"} className={`w-full px-3 py-2 text-xs rounded-xl ${styles.input}`} />
                              </div>
                            </div>
                            <button className={`w-full py-2.5 text-xs rounded-xl ${styles.primaryButton}`}>
                              Cadastrar e Acessar
                            </button>
                          </div>
                        </div>
                      </div>
                    );
                  }

                  return (
                    <div className={`p-6 rounded-2xl ${styles.bg} space-y-6 transition-all`}>
                      {/* Top Bar */}
                      <div className={`p-4 rounded-xl ${styles.headerBg} flex items-center justify-between`}>
                        <div>
                          <h3 className={`text-lg font-bold ${styles.textHeading}`}>Olá, {previewCliente.nome_completo?.split(' ')[0]}</h3>
                          <p className={`text-xs ${styles.textMuted}`}>Portal {selectedOrgObj.name}</p>
                        </div>
                        <span className={`px-3 py-1 rounded-full text-xs font-bold ${styles.badge}`}>
                          Nível {getTierBadge(previewCliente).nome}
                        </span>
                      </div>

                      {/* Loyalty Banner */}
                      <div className={`p-5 rounded-2xl ${styles.loyaltyBg} space-y-3`}>
                        <div className="flex justify-between items-center">
                          <div>
                            <p className="text-[10px] font-bold uppercase tracking-wider text-amber-400">Programa Coroas & Fidelidade</p>
                            <h4 className="text-xl font-bold text-white">{previewCliente.coroas || 120} Coroas Acumuladas</h4>
                          </div>
                          <Award className="w-8 h-8 text-amber-400" />
                        </div>
                      </div>

                      {/* Modules Grid */}
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                        <div className={`p-4 rounded-xl ${styles.card}`}>
                          <p className={`font-bold text-xs ${styles.textHeading} mb-1`}>Meus Pedidos</p>
                          <p className={`text-[11px] ${styles.textMuted}`}>3 pedidos registrados</p>
                        </div>
                        <div className={`p-4 rounded-xl ${styles.card}`}>
                          <p className={`font-bold text-xs ${styles.textHeading} mb-1`}>Assistência Técnica</p>
                          <p className={`text-[11px] ${styles.textMuted}`}>Nenhum chamado aberto</p>
                        </div>
                      </div>
                    </div>
                  );
                })()}
              </div>
            </div>
          ) : (
            <p className="text-center py-6 text-neutral-500 text-xs">Selecione um cliente para simular a prévia.</p>
          )}

          <DialogFooter>
            <Button variant="outline" size="sm" onClick={() => setPreviewModalOpen(false)} className="h-8 text-xs text-white border-neutral-700 bg-neutral-800 hover:bg-neutral-700">
              Fechar
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { supabase } from "@/lib/supabase";
import { toast } from "sonner";
import {
  Building2, User, CreditCard, QrCode, FileText, Check, ChevronRight,
  ChevronLeft, Loader2, Sparkles, Info, Eye, EyeOff, ArrowLeft
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import PlanModulesDisplay from "@/components/planos/PlanModulesDisplay";


const STEPS = [
  { id: 1, title: "Escolha o Plano", icon: Sparkles },
  { id: 2, title: "Dados da Empresa", icon: Building2 },
  { id: 3, title: "Ativação", icon: Check },
];

export default function CadastroEmpresa() {
  const navigate = useNavigate();
  const [step, setStep] = useState(1);
  const [planos, setPlanos] = useState([]);
  const [loadingPlanos, setLoadingPlanos] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  // Step 1 — Plan selection
  const [selectedPlan, setSelectedPlan] = useState(null);

  // Step 2 — Company data
  const [nomeEmpresa, setNomeEmpresa] = useState("");
  const [cnpj, setCnpj] = useState("");
  const [emailEmpresa, setEmailEmpresa] = useState("");
  const [whatsappEmpresa, setWhatsappEmpresa] = useState("");
  const [nomeAdmin, setNomeAdmin] = useState("");
  const [emailAdmin, setEmailAdmin] = useState("");
  const [senhaAdmin, setSenhaAdmin] = useState("");
  const [logoUrl, setLogoUrl] = useState("");
  const [uploadingLogo, setUploadingLogo] = useState(false);

  const handleLogoUpload = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      setUploadingLogo(true);
      const fileName = `${Date.now()}_${file.name.replace(/[^a-zA-Z0-9.]/g, '_')}`;
      const { error } = await supabase.storage.from('publico').upload(fileName, file);
      if (error) throw error;

      const { data: { publicUrl } } = supabase.storage.from('publico').getPublicUrl(fileName);
      setLogoUrl(publicUrl);
      toast.success("Logo enviada com sucesso!");
    } catch (err) {
      console.error("Erro ao enviar logo:", err);
      toast.error("Erro ao enviar a logo.");
    } finally {
      setUploadingLogo(false);
    }
  };

  // Step 3 — Payment / Trial
  const [paymentMethod, setPaymentMethod] = useState("PIX");

  // Result
  const [result, setResult] = useState(null);

  useEffect(() => {
    loadPlanos();
  }, []);

  async function loadPlanos() {
    try {
      setLoadingPlanos(true);
      const { data, error } = await supabase
        .from("planos")
        .select("*")
        .eq("ativo", true)
        .order("preco_mensal", { ascending: true });

      if (error) throw error;
      setPlanos(data || []);
    } catch (err) {
      console.error("Erro ao carregar planos:", err);
      toast.error("Erro ao carregar os planos.");
    } finally {
      setLoadingPlanos(false);
    }
  }

  const formatCurrency = (val) =>
    new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(val);

  const formatCnpj = (value) => {
    const nums = value.replace(/\D/g, "").substring(0, 14);
    return nums
      .replace(/^(\d{2})(\d)/, "$1.$2")
      .replace(/^(\d{2})\.(\d{3})(\d)/, "$1.$2.$3")
      .replace(/\.(\d{3})(\d)/, ".$1/$2")
      .replace(/(\d{4})(\d)/, "$1-$2");
  };

  const formatPhone = (value) => {
    const nums = value.replace(/\D/g, "").substring(0, 11);
    if (nums.length <= 10) {
      return nums.replace(/^(\d{2})(\d{4})(\d{0,4})/, "($1) $2-$3");
    }
    return nums.replace(/^(\d{2})(\d{5})(\d{0,4})/, "($1) $2-$3");
  };

  const validateStep2 = () => {
    if (!nomeEmpresa.trim()) { toast.error("Nome da empresa é obrigatório."); return false; }
    if (cnpj.replace(/\D/g, "").length < 11) { toast.error("CNPJ/CPF inválido."); return false; }
    if (!emailEmpresa.includes("@")) { toast.error("Email da empresa inválido."); return false; }
    if (!nomeAdmin.trim()) { toast.error("Nome do responsável é obrigatório."); return false; }
    if (!emailAdmin.includes("@")) { toast.error("Email do administrador inválido."); return false; }
    if (senhaAdmin.length < 6) { toast.error("A senha deve ter pelo menos 6 caracteres."); return false; }
    return true;
  };

  const handleSubmit = async () => {

    try {
      setSubmitting(true);

      const payload = {
        nomeEmpresa: nomeEmpresa.trim(),
        cnpj: cnpj.replace(/\D/g, ""),
        emailEmpresa: emailEmpresa.trim(),
        whatsappEmpresa: whatsappEmpresa ? whatsappEmpresa.replace(/\D/g, "") : null,
        logoUrl: logoUrl || null,
        nomeAdmin: nomeAdmin.trim(),
        emailAdmin: emailAdmin.trim(),
        senhaAdmin,
        planoId: selectedPlan.id,
        paymentMethod: "PIX",
        cardDetails: null
      };

      const { data, error } = await supabase.functions.invoke("criar-organizacao", {
        body: payload
      });

      if (error) {
        let msg = error.message || 'Erro ao processar o cadastro.';
        if (error.context && typeof error.context.json === 'function') {
          try {
            const body = await error.context.json();
            if (body?.error) msg = body.error;
          } catch (_) { }
        }
        throw new Error(msg);
      }

      if (data?.success) {
        setResult(data);
        setStep(4); // Success screen
        toast.success("Cadastro realizado com sucesso!");
      } else if (data?.error) {
        throw new Error(data.error);
      }
    } catch (err) {
      console.error("Erro no cadastro:", err);
      toast.error(err.message || "Erro ao processar o cadastro.");
    } finally {
      setSubmitting(false);
    }
  };

  const handleLoginRedirect = async () => {
    // Auto-login com as credenciais recém-criadas
    try {
      const { error } = await supabase.auth.signInWithPassword({
        email: emailAdmin,
        password: senhaAdmin
      });
      if (error) throw error;
      navigate("/admin", { replace: true });
    } catch {
      navigate("/login", { replace: true });
    }
  };

  // ========== STEPPER VISUAL ==========
  const renderStepper = () => (
    <div className="flex items-center justify-center gap-0 mb-8">
      {STEPS.map((s, i) => {
        const Icon = s.icon;
        const isActive = step === s.id;
        const isDone = step > s.id;
        return (
          <React.Fragment key={s.id}>
            {i > 0 && (
              <div className={`w-12 h-0.5 mx-1 transition-colors ${isDone ? "bg-green-600" : "bg-gray-200"}`} />
            )}
            <div className="flex flex-col items-center gap-1.5">
              <div className={`w-10 h-10 rounded-full flex items-center justify-center text-sm font-bold transition-all ${isActive ? "bg-green-700 text-white shadow-lg ring-4 ring-green-100" :
                isDone ? "bg-green-600 text-white" :
                  "bg-gray-100 text-gray-400"
                }`}>
                {isDone ? <Check className="w-5 h-5" /> : <Icon className="w-4 h-4" />}
              </div>
              <span className={`text-xs font-medium whitespace-nowrap ${isActive ? "text-green-800" : isDone ? "text-green-600" : "text-gray-400"
                }`}>{s.title}</span>
            </div>
          </React.Fragment>
        );
      })}
    </div>
  );

  // ========== STEP 1: PLANOS ==========
  const renderStepPlanos = () => (
    <div key="step-1" className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
      <div className="text-center">
        <h2 className="text-2xl font-bold text-gray-900">Escolha o plano ideal para sua empresa</h2>
        <p className="text-gray-500 mt-2">Todos os planos incluem o sistema ERP completo. A diferença está nos módulos extras.</p>
      </div>

      {loadingPlanos ? (
        <div className="flex justify-center py-12">
          <Loader2 className="w-8 h-8 animate-spin text-green-700" />
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 max-w-3xl mx-auto">
          {planos.map((plano) => {
            const isSelected = selectedPlan?.id === plano.id;
            return (
              <Card
                key={plano.id}
                className={`cursor-pointer transition-all relative ${isSelected
                  ? "border-2 border-green-700 shadow-lg ring-2 ring-green-100"
                  : "border-gray-200 hover:shadow-md hover:border-green-300"
                  }`}
                onClick={() => setSelectedPlan(plano)}
              >
                {plano.slug === "completo" && (
                  <div className="absolute top-0 right-1/2 translate-x-1/2 -translate-y-1/2 bg-green-700 text-white text-xs font-bold px-3 py-1 rounded-full uppercase tracking-wider shadow">
                    Recomendado
                  </div>
                )}
                <CardHeader className="text-center pb-4">
                  <CardTitle className="text-xl text-gray-800">{plano.nome}</CardTitle>
                  <CardDescription className="text-xs">Recorrência mensal automática</CardDescription>
                  <div className="mt-4">
                    <span className="text-3xl font-extrabold text-gray-900">{formatCurrency(plano.preco_mensal)}</span>
                    <span className="text-sm text-gray-400"> / mês</span>
                  </div>
                </CardHeader>
                <CardContent className="pt-2">
                  <div className="space-y-3">
                    <div className="flex items-center gap-2 text-sm font-semibold text-gray-700 border-b pb-2">
                      <Sparkles className="w-4 h-4 text-green-700" /> Módulos Inclusos:
                    </div>
                    <PlanModulesDisplay recursos={plano.recursos} variant="card" />

                    <div className="flex items-start gap-2 text-xs text-gray-500 pt-2 border-t">
                      <Info className="w-3.5 h-3.5 text-gray-400 shrink-0 mt-0.5" />
                      <span>Inclui suporte técnico e atualizações do MPII Hub.</span>
                    </div>
                  </div>
                </CardContent>
                <CardFooter>
                  {isSelected ? (
                    <Button className="w-full bg-green-700 hover:bg-green-800" disabled>
                      <Check className="w-4 h-4 mr-2" /> Selecionado
                    </Button>
                  ) : (
                    <Button variant="outline" className="w-full border-green-200 text-green-800 hover:bg-green-50">
                      Selecionar
                    </Button>
                  )}
                </CardFooter>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );

  // ========== STEP 2: DADOS DA EMPRESA ==========
  const renderStepDadosEmpresa = () => (
    <div key="step-2" className="space-y-6 max-w-xl mx-auto animate-in fade-in slide-in-from-right-4 duration-300">
      <div className="text-center">
        <h2 className="text-2xl font-bold text-gray-900">Dados da sua empresa</h2>
        <p className="text-gray-500 mt-2">Informe os dados cadastrais e crie sua conta de administrador.</p>
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <Building2 className="w-5 h-5 text-green-700" /> Empresa
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div>
            <Label htmlFor="nome-empresa">Nome da Empresa / Razão Social *</Label>
            <Input id="nome-empresa" placeholder="Ex: Minha Empresa Ltda" value={nomeEmpresa}
              onChange={(e) => setNomeEmpresa(e.target.value)} className="mt-1" required />
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <Label htmlFor="cnpj">CNPJ ou CPF *</Label>
              <Input id="cnpj" placeholder="00.000.000/0001-00" value={cnpj}
                onChange={(e) => setCnpj(formatCnpj(e.target.value))} className="mt-1" required />
            </div>
            <div>
              <Label htmlFor="whatsapp-empresa">WhatsApp</Label>
              <Input id="whatsapp-empresa" placeholder="(24) 99999-0000" value={whatsappEmpresa}
                onChange={(e) => setWhatsappEmpresa(formatPhone(e.target.value))} className="mt-1" />
            </div>
          </div>
          <div>
            <Label htmlFor="email-empresa">Email da Empresa *</Label>
            <Input id="email-empresa" type="email" placeholder="contato@suaempresa.com.br" value={emailEmpresa}
              onChange={(e) => setEmailEmpresa(e.target.value)} className="mt-1" required />
          </div>
          <div>
            <Label>Logo da Empresa</Label>
            <div className="mt-2 flex items-center gap-4">
              {logoUrl ? (
                <div className="w-16 h-16 border rounded-lg bg-gray-50 flex items-center justify-center overflow-hidden">
                  <img src={logoUrl} alt="Logo" className="w-full h-full object-contain" />
                </div>
              ) : (
                <div className="w-16 h-16 border border-dashed rounded-lg flex items-center justify-center text-gray-400 text-xs text-center p-2">
                  Sem Logo
                </div>
              )}
              <div className="flex-1">
                <input
                  type="file"
                  id="logo"
                  accept="image/*"
                  onChange={handleLogoUpload}
                  className="hidden"
                />
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => document.getElementById("logo").click()}
                  disabled={uploadingLogo}
                  className="border-green-200 text-green-800 hover:bg-green-50"
                >
                  {uploadingLogo ? (
                    <><Loader2 className="w-4 h-4 animate-spin mr-1.5" /> Enviando...</>
                  ) : (
                    <>Escolher Imagem</>
                  )}
                </Button>
                {logoUrl && (
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={() => setLogoUrl("")}
                    className="ml-2 text-red-600 hover:text-red-700 hover:bg-red-50"
                  >
                    Remover
                  </Button>
                )}
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <User className="w-5 h-5 text-green-700" /> Conta do Administrador
          </CardTitle>
          <CardDescription>Essa será sua conta pessoal para acessar o sistema.</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div>
            <Label htmlFor="nome-admin">Nome Completo *</Label>
            <Input id="nome-admin" placeholder="Seu nome completo" value={nomeAdmin}
              onChange={(e) => setNomeAdmin(e.target.value)} className="mt-1" required />
          </div>
          <div>
            <Label htmlFor="email-admin">Email de Login *</Label>
            <Input id="email-admin" type="email" placeholder="seu.email@provedor.com" value={emailAdmin}
              onChange={(e) => setEmailAdmin(e.target.value)} className="mt-1" required />
          </div>
          <div>
            <Label htmlFor="senha-admin">Senha *</Label>
            <div className="relative mt-1">
              <Input id="senha-admin" type={showPassword ? "text" : "password"} placeholder="Mínimo 6 caracteres"
                value={senhaAdmin} onChange={(e) => setSenhaAdmin(e.target.value)} className="pr-10" required />
              <button type="button" onClick={() => setShowPassword(!showPassword)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600">
                {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
              </button>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );

  // ========== STEP 3: ATIVAÇÃO (TRIAL) ==========
  const renderStepPagamento = () => (
    <div key="step-3" className="space-y-6 max-w-xl mx-auto animate-in fade-in slide-in-from-right-4 duration-300">
      <div className="text-center">
        <h2 className="text-2xl font-bold text-gray-900">15 Dias de Teste Grátis</h2>
        <p className="text-gray-500 mt-2">
          Assinatura de <strong>{selectedPlan?.nome}</strong> — {formatCurrency(selectedPlan?.preco_mensal || 0)}/mês após o período de teste.
        </p>
      </div>

      <Card>
        <CardContent className="pt-8 pb-8 text-center space-y-4">
          <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto text-green-700">
            <Sparkles className="w-8 h-8" />
          </div>
          <h3 className="text-xl font-bold text-gray-800">Seu acesso será liberado imediatamente!</h3>
          <p className="text-sm text-gray-600 max-w-sm mx-auto">
            Nenhuma cobrança será gerada agora. Aproveite todos os recursos do sistema sem compromisso durante os primeiros 15 dias. A forma de pagamento da sua assinatura poderá ser configurada posteriormente.
          </p>
        </CardContent>
      </Card>

      <div className="bg-green-50 border border-green-200 rounded-lg p-4">
        <h4 className="text-sm font-bold text-green-800 mb-2">Resumo do Cadastro</h4>
        <div className="text-sm text-green-700 space-y-1">
          <p><strong>Empresa:</strong> {nomeEmpresa}</p>
          <p><strong>Plano:</strong> {selectedPlan?.nome} — {formatCurrency(selectedPlan?.preco_mensal || 0)}/mês</p>
          <p><strong>Admin:</strong> {nomeAdmin} ({emailAdmin})</p>
        </div>
      </div>
    </div>
  );

  // ========== STEP 4: SUCESSO ==========
  const renderStepSucesso = () => (
    <div className="max-w-lg mx-auto text-center space-y-6 animate-in fade-in zoom-in-95 duration-500">
      <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto">
        <Check className="w-10 h-10 text-green-700" />
      </div>
      <h2 className="text-2xl font-bold text-gray-900">Cadastro Realizado! 🎉</h2>
      <p className="text-gray-500">
        Sua empresa <strong>{nomeEmpresa}</strong> foi criada com sucesso no MPII Hub.
      </p>

      {result?.matricula && (
        <Card className="text-left">
          <CardContent className="pt-6 space-y-3">
            <div className="flex justify-between text-sm">
              <span className="text-gray-500">Matrícula do Admin:</span>
              <span className="font-mono font-bold text-green-800">{result.matricula}</span>
            </div>
            <div className="flex justify-between text-sm">
              <span className="text-gray-500">Email de Login:</span>
              <span className="font-medium">{emailAdmin}</span>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Removido QRCode ou Boleto imediato pois a assinatura tem carência de 15 dias */}

      <Button onClick={handleLoginRedirect} className="w-full bg-green-700 hover:bg-green-800 h-12 text-base">
        Acessar o Sistema <ChevronRight className="w-5 h-5 ml-2" />
      </Button>
    </div>
  );

  // ========== RENDER ==========
  return (
    <div className="min-h-screen bg-gradient-to-b from-green-50 via-white to-gray-50">
      {/* Header */}
      <header className="border-b bg-white/80 backdrop-blur-sm sticky top-0 z-10">
        <div className="max-w-4xl mx-auto px-4 py-4 flex items-center justify-between">
          <button onClick={() => navigate("/")} className="flex items-center gap-2 text-gray-500 hover:text-gray-800 text-sm transition-colors">
            <ArrowLeft className="w-4 h-4" /> Voltar ao site
          </button>
          <h1 className="text-lg font-bold" style={{ color: "#07593f" }}>GestApp — Cadastro</h1>
          <div />
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-4 py-8">
        {step <= 3 && renderStepper()}

        {step === 1 && renderStepPlanos()}
        {step === 2 && renderStepDadosEmpresa()}
        {step === 3 && renderStepPagamento()}
        {step === 4 && renderStepSucesso()}

        {/* Navigation Buttons */}
        {step <= 3 && (
          <div className="flex justify-between mt-8 max-w-xl mx-auto">
            {step > 1 ? (
              <Button variant="outline" onClick={() => setStep(step - 1)} disabled={submitting}>
                <ChevronLeft className="w-4 h-4 mr-2" /> Voltar
              </Button>
            ) : <div />}

            {step < 3 ? (
              <Button
                className="bg-green-700 hover:bg-green-800"
                disabled={step === 1 && !selectedPlan}
                onClick={() => {
                  if (step === 2 && !validateStep2()) return;
                  setStep(step + 1);
                }}
              >
                Continuar <ChevronRight className="w-4 h-4 ml-2" />
              </Button>
            ) : (
              <Button
                className="bg-green-700 hover:bg-green-800"
                disabled={submitting}
                onClick={handleSubmit}
              >
                {submitting ? (
                  <><Loader2 className="w-4 h-4 animate-spin mr-2" /> Processando...</>
                ) : (
                  <>Finalizar Cadastro <ChevronRight className="w-4 h-4 ml-2" /></>
                )}
              </Button>
            )}
          </div>
        )}
      </main>
    </div>
  );
}

import React, { useState } from "react";
import { base44 } from "@/api/base44Client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
    Truck, Wrench, User, Phone, Mail, Lock,
    CheckCircle, AlertCircle, ArrowLeft
} from "lucide-react";
import { toast } from "sonner";
import { Link } from "react-router-dom";

export default function CadastroMobile() {
    const [step, setStep] = useState(1);
    const [tipoUsuario, setTipoUsuario] = useState(null);
    const [loading, setLoading] = useState(false);
    const [cadastroEnviado, setCadastroEnviado] = useState(false);
    const [formData, setFormData] = useState({
        nome: "",
        telefone: "",
        email: "",
        senha: "",
        confirmarSenha: ""
    });

    const handleChange = (field, value) => {
        setFormData(prev => ({ ...prev, [field]: value }));
    };

    const handleSubmit = async () => {
        // Validações
        if (!formData.nome || !formData.telefone || !formData.email || !formData.senha) {
            toast.error("Preencha todos os campos");
            return;
        }

        if (formData.senha !== formData.confirmarSenha) {
            toast.error("As senhas não coincidem");
            return;
        }

        if (formData.senha.length < 6) {
            toast.error("A senha deve ter pelo menos 6 caracteres");
            return;
        }

        setLoading(true);

        try {
            // Criar usuário no Supabase Auth
            const { user, error: authError } = await base44.auth.signUp(
                formData.email,
                formData.senha
            );

            if (authError) {
                throw authError;
            }

            // Criar registro na tabela public_users
            const cargo = tipoUsuario === 'entregador' ? 'Entregador' : 'Montador Externo';

            await base44.entities.User.create({
                id: user.id,
                email: formData.email,
                full_name: formData.nome,
                telefone: formData.telefone,
                cargo: cargo,
                aprovado: false,
                status_cadastro: 'pendente'
            });

            // Se for montador, criar registro na tabela montadores
            if (tipoUsuario === 'montador') {
                await base44.entities.Montador.create({
                    nome: formData.nome,
                    telefone: formData.telefone,
                    email: formData.email,
                    tipo: 'terceirizado',
                    ativo: false, // Aguardando aprovação
                    usuario_id: user.id
                });
            }

            setCadastroEnviado(true);
            toast.success("Cadastro enviado para aprovação!");

        } catch (error) {
            console.error("Erro no cadastro:", error);
            toast.error(error.message || "Erro ao realizar cadastro");
        } finally {
            setLoading(false);
        }
    };

    // Tela de sucesso
    if (cadastroEnviado) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-green-600 to-green-800 flex items-center justify-center p-4">
                <Card className="w-full max-w-md">
                    <CardContent className="p-8 text-center">
                        <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
                            <CheckCircle className="w-10 h-10 text-green-600" />
                        </div>
                        <h2 className="text-2xl font-bold text-gray-900 mb-4">
                            Cadastro Enviado!
                        </h2>
                        <p className="text-gray-600 mb-6">
                            Seu cadastro foi enviado para análise.
                            Você receberá uma notificação quando for aprovado.
                        </p>
                        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4 text-left">
                            <p className="text-sm text-yellow-800">
                                <strong>⏳ Aguardando Aprovação</strong><br />
                                A administração irá revisar seu cadastro em breve.
                            </p>
                        </div>
                        <Link to="/">
                            <Button className="mt-6 w-full" variant="outline">
                                Voltar para o início
                            </Button>
                        </Link>
                    </CardContent>
                </Card>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gradient-to-br from-green-600 to-green-800 flex items-center justify-center p-4">
            <Card className="w-full max-w-md">
                <CardHeader className="text-center pb-2">
                    <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4">
                        <User className="w-8 h-8 text-green-600" />
                    </div>
                    <CardTitle className="text-xl">
                        {step === 1 ? "Cadastro de Colaborador" : `Cadastro de ${tipoUsuario === 'entregador' ? 'Entregador' : 'Montador'}`}
                    </CardTitle>
                    <p className="text-sm text-gray-500 mt-1">
                        Sistema de Gestão
                    </p>
                </CardHeader>

                <CardContent className="p-6">
                    {/* Step 1: Escolher Tipo */}
                    {step === 1 && (
                        <div className="space-y-4">
                            <p className="text-center text-gray-600 mb-6">
                                Selecione o tipo de cadastro:
                            </p>

                            <button
                                onClick={() => { setTipoUsuario('entregador'); setStep(2); }}
                                className="w-full p-4 rounded-xl border-2 hover:border-green-500 hover:bg-green-50 transition-all flex items-center gap-4"
                            >
                                <div className="w-12 h-12 bg-blue-100 rounded-xl flex items-center justify-center">
                                    <Truck className="w-6 h-6 text-blue-600" />
                                </div>
                                <div className="text-left">
                                    <p className="font-bold text-gray-900">Entregador</p>
                                    <p className="text-sm text-gray-500">Faço entregas para a loja</p>
                                </div>
                            </button>

                            <button
                                onClick={() => { setTipoUsuario('montador'); setStep(2); }}
                                className="w-full p-4 rounded-xl border-2 hover:border-orange-500 hover:bg-orange-50 transition-all flex items-center gap-4"
                            >
                                <div className="w-12 h-12 bg-orange-100 rounded-xl flex items-center justify-center">
                                    <Wrench className="w-6 h-6 text-orange-600" />
                                </div>
                                <div className="text-left">
                                    <p className="font-bold text-gray-900">Montador</p>
                                    <p className="text-sm text-gray-500">Monto móveis na casa dos clientes</p>
                                </div>
                            </button>

                            <div className="text-center pt-4">
                                <Link to="/" className="text-sm text-gray-500 hover:text-green-600">
                                    ← Voltar para login
                                </Link>
                            </div>
                        </div>
                    )}

                    {/* Step 2: Formulário */}
                    {step === 2 && (
                        <div className="space-y-4">
                            <button
                                onClick={() => setStep(1)}
                                className="flex items-center gap-2 text-gray-500 hover:text-gray-700 mb-4"
                            >
                                <ArrowLeft className="w-4 h-4" />
                                <span className="text-sm">Voltar</span>
                            </button>

                            <div>
                                <Label>Nome Completo</Label>
                                <div className="relative">
                                    <User className="absolute left-3 top-3 w-4 h-4 text-gray-400" />
                                    <Input
                                        value={formData.nome}
                                        onChange={(e) => handleChange('nome', e.target.value)}
                                        className="pl-10"
                                        placeholder="Seu nome completo"
                                    />
                                </div>
                            </div>

                            <div>
                                <Label>Telefone de Trabalho (WhatsApp)</Label>
                                <p className="text-xs text-gray-500 mb-1">Este número será passado aos clientes para contato direto</p>
                                <div className="relative">
                                    <Phone className="absolute left-3 top-3 w-4 h-4 text-gray-400" />
                                    <Input
                                        value={formData.telefone}
                                        onChange={(e) => handleChange('telefone', e.target.value)}
                                        className="pl-10"
                                        placeholder="(11) 99999-9999"
                                    />
                                </div>
                            </div>

                            <div>
                                <Label>E-mail</Label>
                                <div className="relative">
                                    <Mail className="absolute left-3 top-3 w-4 h-4 text-gray-400" />
                                    <Input
                                        type="email"
                                        value={formData.email}
                                        onChange={(e) => handleChange('email', e.target.value)}
                                        className="pl-10"
                                        placeholder="seu@email.com"
                                    />
                                </div>
                            </div>

                            <div>
                                <Label>Senha</Label>
                                <div className="relative">
                                    <Lock className="absolute left-3 top-3 w-4 h-4 text-gray-400" />
                                    <Input
                                        type="password"
                                        value={formData.senha}
                                        onChange={(e) => handleChange('senha', e.target.value)}
                                        className="pl-10"
                                        placeholder="Mínimo 6 caracteres"
                                    />
                                </div>
                            </div>

                            <div>
                                <Label>Confirmar Senha</Label>
                                <div className="relative">
                                    <Lock className="absolute left-3 top-3 w-4 h-4 text-gray-400" />
                                    <Input
                                        type="password"
                                        value={formData.confirmarSenha}
                                        onChange={(e) => handleChange('confirmarSenha', e.target.value)}
                                        className="pl-10"
                                        placeholder="Repita a senha"
                                    />
                                </div>
                            </div>

                            <Button
                                onClick={handleSubmit}
                                disabled={loading}
                                className={`w-full h-12 mt-4 ${tipoUsuario === 'entregador'
                                    ? 'bg-blue-600 hover:bg-blue-700'
                                    : 'bg-orange-500 hover:bg-orange-600'
                                    }`}
                            >
                                {loading ? 'Enviando...' : 'Enviar Cadastro'}
                            </Button>

                            <p className="text-xs text-center text-gray-500 mt-4">
                                Ao se cadastrar, você concorda com os termos de uso.
                                Seu acesso será liberado após aprovação.
                            </p>
                        </div>
                    )}
                </CardContent>
            </Card>
        </div>
    );
}

import React, { useState, useEffect } from "react";
import { base44 } from "@/api/base44Client";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useLojas } from "@/hooks/useLojas";
import { calcularEstoqueTotal } from "@/constants/productConstants";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { MessageCircle, Download, Eye, Share2, Filter, Search, ImageIcon, ImagePlus, Upload, Loader2, Check, X } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { useTenant } from "@/contexts/TenantContext";

import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";

export default function CatalogoWhatsApp() {
  const { brandName } = useTenant();
  const [user, setUser] = useState(null);

  const [filtroCategoria, setFiltroCategoria] = useState("all");
  const [filtroAmbiente, setFiltroAmbiente] = useState("all");
  const [filtroDisponibilidade, setFiltroDisponibilidade] = useState("all");
  const [busca, setBusca] = useState("");
  const [produtosSelecionados, setProdutosSelecionados] = useState([]);
  const [visualizacao, setVisualizacao] = useState(false);
  const [paginaExibicao, setPaginaExibicao] = useState(1);
  const [vincularImagemOpen, setVincularImagemOpen] = useState(false);
  const [uploadingFor, setUploadingFor] = useState(null); // ID do produto sendo enviado
  const [fotosIndividuais, setFotosIndividuais] = useState({}); // { [id]: 'url' }
  const [savingImage, setSavingImage] = useState(false);
  const itensPorPagina = 50;
  const queryClient = useQueryClient();

  // Reset pagination when filters change
  useEffect(() => {
    setPaginaExibicao(1);
  }, [filtroCategoria, filtroAmbiente, filtroDisponibilidade, busca]);

  const { data: lojasAtivas = [] } = useLojas();

  const getEstoqueTotal = (p) => {
    return calcularEstoqueTotal(p, lojasAtivas);
  };

  useEffect(() => {
    let mounted = true;
    const loadUser = async () => {
      try {
        const currentUser = await base44.auth.me();
        if (mounted) setUser(currentUser);
      } catch (error) {
        console.error("Erro:", error);
      }
    };
    loadUser();
    return () => { mounted = false; };
  }, []);

  const { data: produtos } = useQuery({
    queryKey: ['produtos'],
    queryFn: () => base44.entities.Produto.list(),
    enabled: !!user,
  });

  if (!user) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2" style={{ borderColor: '#07593f' }} />
      </div>
    );
  }

  const produtosAtivos = (produtos || []).filter(p => p.ativo !== false);

  const categorias = [...new Set(produtosAtivos.map(p => p.categoria))].filter(Boolean).sort();
  const ambientes = [...new Set(produtosAtivos.map(p => p.ambiente))].filter(Boolean).sort();


  const produtosFiltrados = produtosAtivos.filter(p => {
    const estoqueTotal = getEstoqueTotal(p);
    const matchCategoria = filtroCategoria === "all" || p.categoria === filtroCategoria;
    const matchAmbiente = filtroAmbiente === "all" || p.ambiente === filtroAmbiente;
    const matchDisponibilidade = filtroDisponibilidade === "all" ||
      (filtroDisponibilidade === "pronta" && estoqueTotal > 0) ||
      (filtroDisponibilidade === "encomenda" && estoqueTotal <= 0);
    const matchBusca = !busca ||
      p.nome?.toLowerCase().includes(busca.toLowerCase()) ||
      p.modelo_referencia?.toLowerCase().includes(busca.toLowerCase());

    return matchCategoria && matchAmbiente && matchDisponibilidade && matchBusca;
  });


  const produtosPaginados = produtosFiltrados.slice(0, paginaExibicao * itensPorPagina);

  const selecionarTodosFiltrados = () => {
    const novosIds = new Set(produtosSelecionados.map(p => p.id));
    const novosSelecionados = [...produtosSelecionados];

    produtosFiltrados.forEach(p => {
      if (!novosIds.has(p.id)) {
        novosSelecionados.push(p);
        novosIds.add(p.id);
      }
    });

    setProdutosSelecionados(novosSelecionados);
  };

  const toggleProduto = (produto) => {
    if (produtosSelecionados.find(p => p.id === produto.id)) {
      setProdutosSelecionados(produtosSelecionados.filter(p => p.id !== produto.id));
    } else {
      setProdutosSelecionados([...produtosSelecionados, produto]);
    }
  };

  const gerarTextoWhatsApp = () => {
    let texto = `🛋️ *CATÁLOGO ${brandName.toUpperCase()}* 🛋️\n\n`;

    texto += `📱 Entre em contato pelo WhatsApp para mais informações!\n\n`;
    texto += `━━━━━━━━━━━━━━━━━━━━━━\n\n`;

    const produtosPorCategoria = {};
    produtosSelecionados.forEach(p => {
      const cat = p.categoria || "Outros";
      if (!produtosPorCategoria[cat]) {
        produtosPorCategoria[cat] = [];
      }
      produtosPorCategoria[cat].push(p);
    });

    Object.keys(produtosPorCategoria).forEach(categoria => {
      texto += `📍 *${categoria.toUpperCase()}*\n\n`;
      produtosPorCategoria[categoria].forEach(p => {
        texto += `✨ *${p.nome} ${p.modelo_referencia || ''}*\n`;
        if (p.descricao) texto += `   ${p.descricao}\n`;
        if (p.material) texto += `   🧵 Material: ${p.material}\n`;
        if (p.cor) texto += `   🎨 Cor: ${p.cor}\n`;
        if (p.largura || p.altura || p.profundidade) {
          const dims = [];
          if (p.largura) dims.push(`Largura: ${p.largura}cm`);
          if (p.altura) dims.push(`Altura: ${p.altura}cm`);
          if (p.profundidade) dims.push(`Profundidade: ${p.profundidade}cm`);
          texto += `   📏 ${dims.join(', ')}\n`;
        }
        texto += `   💰 *R$ ${p.preco_venda?.toFixed(2) || 'Sob consulta'}*\n`;
        texto += `   📦 ${getEstoqueTotal(p) > 0 ? 'Pronta-entrega' : 'Disponível por encomenda'}\n\n`;
      });
      texto += `━━━━━━━━━━━━━━━━━━━━━━\n\n`;
    });

    texto += `📍 *Nossas Lojas:*\n`;
    lojasAtivas.forEach(loja => {
      texto += `   • ${loja.nome}\n`;
    });
    texto += `\n`;
    texto += `💬 *Faça seu pedido pelo WhatsApp!*\n`;
    texto += `🚚 *Entregamos na sua casa!*\n`;

    return texto;
  };

  const gerarTextoProdutoIndividual = (p) => {
    let texto = `✨ *${p.nome} ${p.modelo_referencia || ''}*\n`;
    if (p.descricao) texto += `${p.descricao}\n`;
    if (p.material) texto += `🧵 Material: ${p.material}\n`;
    if (p.cor) texto += `🎨 Cor: ${p.cor}\n`;
    if (p.largura || p.altura || p.profundidade) {
      const dims = [];
      if (p.largura) dims.push(`Largura: ${p.largura}cm`);
      if (p.altura) dims.push(`Altura: ${p.altura}cm`);
      if (p.profundidade) dims.push(`Profundidade: ${p.profundidade}cm`);
      texto += `📏 ${dims.join(', ')}\n`;
    }
    texto += `💰 *R$ ${p.preco_venda?.toFixed(2) || 'Sob consulta'}*\n`;
    texto += `📦 ${getEstoqueTotal(p) > 0 ? 'Pronta-entrega' : 'Disponível por encomenda'}\n`;

    return texto;
  };

  const abrirWhatsApp = () => {
    if (produtosSelecionados.length === 0) {
      toast.error("Selecione pelo menos um produto!");
      return;
    }

    const texto = gerarTextoWhatsApp();
    const url = `https://wa.me/?text=${encodeURIComponent(texto)}`;
    window.open(url, "_blank");
  };

  const handleImageUploadIndiv = async (e, produtoId) => {
    const file = e.target.files[0];
    if (!file) return;

    setUploadingFor(produtoId);
    try {
      const { file_url } = await base44.integrations.Core.UploadFile({ file });
      setFotosIndividuais(prev => ({ ...prev, [produtoId]: file_url }));
      toast.success("Imagem enviada com sucesso!");
    } catch (error) {
      console.error('Erro no upload:', error);
      toast.error('Erro ao enviar imagem');
    } finally {
      setUploadingFor(null);
    }
  };

  const salvarImagensIndividuais = async () => {
    const idsComFoto = Object.keys(fotosIndividuais).filter(id => fotosIndividuais[id]?.trim());

    if (idsComFoto.length === 0) {
      toast.error("Insira pelo menos uma imagem para algum produto.");
      return;
    }

    setSavingImage(true);
    try {
      const promises = idsComFoto.map(id =>
        base44.entities.Produto.update(id, {
          fotos: [fotosIndividuais[id].trim()]
        })
      );

      await Promise.all(promises);

      toast.success(`${promises.length} produto(s) atualizado(s) com sucesso!`);
      fecharModalVincular();

      queryClient.invalidateQueries(['produtos']);

      setProdutosSelecionados(prev => prev.map(p =>
        fotosIndividuais[p.id] ? { ...p, fotos: [fotosIndividuais[p.id].trim()] } : p
      ));

    } catch (error) {
      console.error("Erro ao salvar imagens:", error);
      toast.error("Erro ao vincular imagens");
    } finally {
      setSavingImage(false);
    }
  };

  const fecharModalVincular = () => {
    setVincularImagemOpen(false);
    setFotosIndividuais({});
    setUploadingFor(null);
  };

  const copiarTexto = () => {
    const texto = gerarTextoWhatsApp();
    navigator.clipboard.writeText(texto);
    toast.success("Texto copiado! Cole no WhatsApp.");
  };

  return (
    <div className="p-4 md:p-8">
      <div className="max-w-7xl mx-auto">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-8">
          <div>
            <div className="flex items-center gap-3 mb-2">
              <MessageCircle className="w-8 h-8" style={{ color: '#25D366' }} />
              <h1 className="text-3xl md:text-4xl font-bold" style={{ color: '#07593f' }}>
                Catálogo para WhatsApp
              </h1>
            </div>
            <p style={{ color: '#8B8B8B' }}>
              Gere catálogos profissionais para enviar aos seus clientes
            </p>
          </div>
          <Badge className="text-lg px-4 py-2" style={{ backgroundColor: '#25D366', color: 'white' }}>
            {produtosSelecionados.length} selecionados
          </Badge>
        </div>

        <div className="grid lg:grid-cols-3 gap-6">
          {/* Seleção de Produtos */}
          <div className="lg:col-span-2 space-y-4">
            <Card className="border-0 shadow-xl">
              <CardHeader>
                <CardTitle>Selecione os Produtos</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="flex flex-wrap gap-2">
                  <div className="relative flex-1 min-w-[200px]">
                    <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4" style={{ color: '#8B8B8B' }} />
                    <Input
                      placeholder="Buscar por nome ou referência..."
                      value={busca}
                      onChange={(e) => setBusca(e.target.value)}
                      className="pl-9 h-10"
                    />
                  </div>

                  <select
                    value={filtroCategoria}
                    onChange={(e) => setFiltroCategoria(e.target.value)}
                    className="h-10 px-3 rounded border border-input bg-background text-sm"
                  >
                    <option value="all">Todas Categorias</option>
                    {categorias.map(cat => (
                      <option key={cat} value={cat}>{cat}</option>
                    ))}
                  </select>

                  <select
                    value={filtroAmbiente}
                    onChange={(e) => setFiltroAmbiente(e.target.value)}
                    className="h-10 px-3 rounded border border-input bg-background text-sm"
                  >
                    <option value="all">Todos os Cômodos</option>
                    {ambientes.map(amb => (
                      <option key={amb} value={amb}>{amb}</option>
                    ))}
                  </select>

                  <select
                    value={filtroDisponibilidade}
                    onChange={(e) => setFiltroDisponibilidade(e.target.value)}
                    className="h-10 px-3 rounded border border-input bg-background text-sm"
                  >
                    <option value="all">Disponibilidade (Ver todos)</option>
                    <option value="pronta">Pronta-entrega</option>
                    <option value="encomenda">Por Encomenda</option>
                  </select>
                </div>

                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    className="text-xs h-8"
                    onClick={selecionarTodosFiltrados}
                    disabled={produtosFiltrados.length === 0}
                  >
                    Selecionar Todos ({produtosFiltrados.length})
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="text-xs h-8 text-red-500 hover:text-red-700"
                    onClick={() => setProdutosSelecionados([])}
                    disabled={produtosSelecionados.length === 0}
                  >
                    Limpar Seleção
                  </Button>
                </div>

                <div className="grid md:grid-cols-2 gap-3 max-h-[600px] overflow-y-auto pr-2">
                  {produtosPaginados.map(produto => {
                    const selecionado = produtosSelecionados.find(p => p.id === produto.id);
                    return (
                      <Card
                        key={produto.id}
                        className={`cursor-pointer transition-all ${selecionado ? 'border-[#25D366] border-2 bg-green-50' : 'border-2 hover:border-[#07593f]'
                          }`}
                        onClick={() => toggleProduto(produto)}
                      >
                        <CardContent className="p-4">
                          <div className="relative">
                            {produto.fotos && produto.fotos[0] ? (
                              <img
                                src={produto.fotos[0]}
                                alt={produto.nome}
                                className="w-full h-32 object-cover rounded mb-2"
                              />
                            ) : (
                              <div className="w-full h-32 bg-gray-100 rounded mb-2 flex flex-col items-center justify-center border-2 border-dashed border-gray-200">
                                <ImageIcon className="w-8 h-8 text-gray-300 mb-1" />
                                <Button
                                  variant="ghost"
                                  size="sm"
                                  className="h-7 text-[10px] text-green-700 hover:bg-green-50"
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    setProdutosSelecionados([produto]);
                                    setVincularImagemOpen(true);
                                  }}
                                >
                                  <ImagePlus className="w-3 h-3 mr-1" />
                                  Vincular Imagem
                                </Button>
                              </div>
                            )}

                            {produto.fotos?.length > 0 && (
                              <Badge className="absolute top-1 right-1 bg-[#07593f]/80 text-white text-[9px] h-4 px-1 hover:bg-[#07593f] border-0">
                                {produto.fotos.length} {produto.fotos.length === 1 ? 'foto' : 'fotos'}
                              </Badge>
                            )}
                          </div>
                          <h3 className="font-bold text-sm leading-tight mb-1" style={{ color: '#07593f' }}>
                            {produto.nome}{produto.modelo_referencia ? ` - ${produto.modelo_referencia}` : ''}
                          </h3>
                          <div className="flex flex-wrap gap-1 mb-2">
                            <Badge variant="secondary" className="text-[10px] h-4 py-0">{produto.categoria}</Badge>
                            {produto.ambiente && <Badge variant="outline" className="text-[10px] h-4 py-0 border-blue-200 text-blue-700">{produto.ambiente}</Badge>}
                            <Badge variant="outline" className={`text-[10px] h-4 py-0 ${getEstoqueTotal(produto) > 0 ? 'border-green-200 text-green-700' : 'border-orange-200 text-orange-700'}`}>
                              {getEstoqueTotal(produto) > 0 ? 'Pronta' : 'Encomenda'}
                            </Badge>
                          </div>
                          <p className="text-xl font-bold" style={{ color: '#f38a4c' }}>
                            {produto.preco_venda ? `R$ ${produto.preco_venda.toFixed(2)}` : 'Consultar'}
                          </p>
                        </CardContent>
                      </Card>
                    );
                  })}

                  {produtosFiltrados.length > produtosPaginados.length && (
                    <div className="md:col-span-2 py-4 text-center">
                      <Button
                        variant="ghost"
                        onClick={() => setPaginaExibicao(p => p + 1)}
                        className="text-green-700 hover:bg-green-50"
                      >
                        Ver Mais ({produtosFiltrados.length - produtosPaginados.length} restantes)
                      </Button>
                    </div>
                  )}
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Preview e Ações */}
          <div className="space-y-4">
            <Card className="border-0 shadow-xl">
              <CardHeader>
                <CardTitle>Ações</CardTitle>
              </CardHeader>
              <CardContent className="space-y-3">
                <Button
                  onClick={abrirWhatsApp}
                  disabled={produtosSelecionados.length === 0}
                  className="w-full h-12 text-lg"
                  style={{ backgroundColor: '#25D366', color: 'white' }}
                >
                  <MessageCircle className="w-5 h-5 mr-2" />
                  Enviar pelo WhatsApp
                </Button>

                <Button
                  onClick={copiarTexto}
                  disabled={produtosSelecionados.length === 0}
                  variant="outline"
                  className="w-full h-12"
                >
                  <Share2 className="w-5 h-5 mr-2" />
                  Copiar Texto
                </Button>

                <Button
                  onClick={() => setVisualizacao(!visualizacao)}
                  disabled={produtosSelecionados.length === 0}
                  variant="outline"
                  className="w-full h-12"
                >
                  <Eye className="w-5 h-5 mr-2" />
                  {visualizacao ? 'Ocultar' : 'Visualizar'} Preview
                </Button>

                <Button
                  onClick={() => setProdutosSelecionados([])}
                  disabled={produtosSelecionados.length === 0}
                  variant="outline"
                  className="w-full"
                >
                  Limpar Seleção
                </Button>

                <Button
                  onClick={() => setVincularImagemOpen(true)}
                  disabled={produtosSelecionados.length === 0}
                  variant="secondary"
                  className="w-full h-12 border-2 border-dashed border-green-300 bg-green-50 hover:bg-green-100 text-green-700 font-semibold"
                >
                  <ImagePlus className="w-5 h-5 mr-2" />
                  Vincular Imagem ({produtosSelecionados.length})
                </Button>
              </CardContent>
            </Card>

            {/* Modal de Vincular Imagem Individual em Lote */}
            <Dialog open={vincularImagemOpen} onOpenChange={(open) => !open && fecharModalVincular()}>
              <DialogContent className="max-w-2xl max-h-[85vh] flex flex-col p-0 overflow-hidden">
                <DialogHeader className="px-6 pt-6 pb-4 border-b">
                  <DialogTitle>Vincular Imagens aos Produtos</DialogTitle>
                </DialogHeader>

                <div className="flex-1 overflow-y-auto px-6 py-4 space-y-6">
                  {produtosSelecionados.map((p, idx) => (
                    <div key={p.id} className="p-4 rounded-xl border-2 border-gray-100 bg-white shadow-sm space-y-4">
                      <div className="flex justify-between items-start gap-3">
                        <div className="flex-1 min-w-0">
                          <h4 className="font-bold text-[#07593f] truncate">
                            {p.nome}{p.modelo_referencia ? ` (${p.modelo_referencia})` : ''}
                          </h4>
                        </div>
                        <Badge variant="outline" className="text-[10px] bg-green-50 text-green-700 h-5 px-1.5 shrink-0">
                          {idx + 1}/{produtosSelecionados.length}
                        </Badge>
                      </div>

                      <div className="grid md:grid-cols-2 gap-4">
                        <div className="space-y-3">
                          <div className="relative border-2 border-dashed rounded-lg h-24 flex items-center justify-center bg-gray-50 hover:bg-gray-100 transition-colors">
                            <input
                              type="file"
                              accept="image/*"
                              onChange={(e) => handleImageUploadIndiv(e, p.id)}
                              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                              disabled={uploadingFor === p.id || savingImage}
                            />
                            <div className="text-center">
                              {uploadingFor === p.id ? (
                                <Loader2 className="w-6 h-6 mx-auto animate-spin text-green-600" />
                              ) : (
                                <>
                                  <Upload className="w-5 h-5 mx-auto text-green-600 mb-1" />
                                  <p className="text-[10px] font-medium text-gray-900">Upload de Arquivo</p>
                                </>
                              )}
                            </div>
                          </div>

                          <div className="space-y-1">
                            <Label className="text-[10px] text-gray-500 uppercase font-bold">Ou Link da Imagem</Label>
                            <Input
                              value={fotosIndividuais[p.id] || ''}
                              onChange={(e) => setFotosIndividuais(prev => ({ ...prev, [p.id]: e.target.value }))}
                              placeholder="https://..."
                              disabled={savingImage || uploadingFor === p.id}
                              className="h-8 text-[11px]"
                            />
                          </div>
                        </div>

                        <div className="relative border rounded-lg bg-gray-100 flex items-center justify-center overflow-hidden aspect-video">
                          {fotosIndividuais[p.id] ? (
                            <img
                              src={fotosIndividuais[p.id]}
                              alt="Preview"
                              className="w-full h-full object-cover"
                              onError={(e) => {
                                e.target.onerror = null;
                                toast.error("Link inválido!");
                              }}
                            />
                          ) : (
                            p.fotos?.[0] ? (
                              <div className="relative w-full h-full group">
                                <img src={p.fotos[0]} className="w-full h-full object-cover opacity-60" alt="" />
                                <div className="absolute inset-0 flex items-center justify-center">
                                  <Badge className="bg-white/90 text-gray-700 text-[10px] shadow-sm">Foto atual</Badge>
                                </div>
                              </div>
                            ) : (
                              <div className="text-center">
                                <ImageIcon className="w-8 h-8 text-gray-300 mx-auto" />
                                <p className="text-[10px] text-gray-400">Nenhuma foto</p>
                              </div>
                            )
                          )}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>

                <DialogFooter className="px-6 py-4 border-t bg-gray-50 flex items-center justify-between sm:justify-between w-full">
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={fecharModalVincular}
                    disabled={savingImage}
                  >
                    Descartar Alterações
                  </Button>
                  <Button
                    size="sm"
                    onClick={salvarImagensIndividuais}
                    disabled={savingImage || Object.keys(fotosIndividuais).length === 0}
                    className="bg-green-600 hover:bg-green-700 min-w-[140px] shadow-md transition-all hover:scale-105"
                  >
                    {savingImage ? (
                      <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                    ) : (
                      <Check className="w-4 h-4 mr-2" />
                    )}
                    Salvar Tudo ({Object.keys(fotosIndividuais).length})
                  </Button>
                </DialogFooter>
              </DialogContent>
            </Dialog>

            {visualizacao && produtosSelecionados.length > 0 && (
              <Card className="border-0 shadow-xl">
                <CardHeader>
                  <CardTitle>Preview</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="bg-gray-100 p-4 rounded text-sm whitespace-pre-wrap max-h-96 overflow-y-auto">
                    {gerarTextoWhatsApp()}
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState, useMemo, useEffect } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  Plus,
  Search,
  Filter,
  Download,
  Copy,
  TrendingUp,
  Package,
  AlertTriangle,
  HelpCircle,
  ShoppingCart,
  Truck,
  CheckCircle,
  DollarSign,
  Wrench,
} from 'lucide-react';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { toast } from 'sonner';
import { useAuth } from '@/hooks/useAuth';
import { useConfirm } from '@/hooks/useConfirm';
import { useTenant } from '@/contexts/TenantContext';
import { comprasService } from '@/services/comprasService';
import OcTable from '@/components/compras/OcTable';
import CriarLancamentoFromOcModal from '@/components/compras/CriarLancamentoFromOcModal';
import OcModal from '@/components/compras/OcModal';
import SolicitacoesReposicaoTab from '@/components/compras/SolicitacoesReposicaoTab';
import RecebimentoModal from '@/components/compras/RecebimentoModal';
import EnviarOcModal from '@/components/compras/EnviarOcModal';
import PaymentApprovalModal from '@/components/compras/PaymentApprovalModal';
import AjustePrecoModal from '@/components/configuracoes/AjustePrecoModal';
import { VendaDetalhesModal } from '@/components/vendas/VendaDetalhesModal';
import { base44 } from '@/api/base44Client';
import { supabase } from '@/lib/supabase';
import { useAlertasEstoque } from '@/hooks/useAlertasEstoque';

function getEncomendaVendor(encomenda, vendaRelacionada) {
  return (
    encomenda.vendedor_nome ||
    vendaRelacionada?.responsavel_nome ||
    vendaRelacionada?.vendedor_nome ||
    encomenda.usuario_criacao ||
    'Vendedor Desconhecido'
  );
}

function isItemEncomenda(item) {
  if (!item || typeof item !== 'object') return false;
  if (item.is_encomenda === true) return true;
  if (item.is_encomenda === 'true') return true;
  const origem = (item.origem || '').toString().toLowerCase();
  return origem === 'encomenda';
}

function normalizeProductName(nome) {
  return (nome || '').toString().toLowerCase().trim();
}

/**
 * Página principal de Compras - VERSÃO 2
 * Hub centralizado com Dashboard + Tabela de OCs + Encomendas + Análise por Fornecedor
 */
export default function Compras() {
  const queryClient = useQueryClient();
  const confirm = useConfirm();
  const { user, can, filterData } = useAuth();
  const { settings } = useTenant();

  // Categorias financeiras para o modal de lançamento
  const { data: categorias = [] } = useQuery({
    queryKey: ['categorias-financeiras'],
    queryFn: async () => await base44.entities.CategoriaFinanceira.list('nome') || [],
  });

  // Estado do modal de lançamento financeiro
  const [modalLancamentoOpen, setModalLancamentoOpen] = useState(false);
  const [ocParaLancamento, setOcParaLancamento] = useState(null);

  // Handler para abrir modal de lançamento financeiro
  const handleCriarLancamentoFinanceiro = (oc) => {
    setOcParaLancamento(oc);
    setModalLancamentoOpen(true);
  };

  // Verificar permissões
  const temPermissaoVisualizacao = can('view_compras') || can('manage_compras');
  const temPermissaoCriacao = can('create_oc') || can('manage_compras');
  const temPermissaoEnvio = can('send_oc') || can('manage_compras');
  const temPermissaoRecebimento = can('receive_oc') || can('manage_compras');
  const temPermissaoAprovacaoPagamento = can('approve_payment_oc');
  const temPermissaoReajusteGlobal = can('manage_bulk_price_adjustment');
  const formasAutoAprovadas = Array.isArray(settings?.compras_aprovacao_automatica)
    ? settings.compras_aprovacao_automatica
    : ['a_vista'];

  // Hook: Monitoramento de alertas de estoque (background job a cada 5 min)
  const { alertasAtivos, totalAlertas } = useAlertasEstoque(
    user?.loja_id || null,
    temPermissaoVisualizacao || can('view_produtos')
  );

  // Estado
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [vendedorFilter, setVendedorFilter] = useState('all');
  const [fornecedorFilter, setFornecedorFilter] = useState('all');
  const [ocModalOpen, setOcModalOpen] = useState(false);
  const [ocParaEditar, setOcParaEditar] = useState(null);
  const [envioModalOpen, setEnvioModalOpen] = useState(false);
  const [ocParaEnvio, setOcParaEnvio] = useState(null);
  const [recebimentoModalOpen, setRecebimentoModalOpen] = useState(false);
  const [ocParaReceber, setOcParaReceber] = useState(null);
  const [ocModalModo, setOcModalModo] = useState('novo');
  const [alertasModalOpen, setAlertasModalOpen] = useState(false);
  const [mostrarTutorial, setMostrarTutorial] = useState(false);
  const [abaAtiva, setAbaAtiva] = useState('ordens');
  const [isVendaDetalhesOpen, setIsVendaDetalhesOpen] = useState(false);
  const [vendaSelecionada, setVendaSelecionada] = useState(null);
  const [paymentApprovalOpen, setPaymentApprovalOpen] = useState(false);
  const [ocParaAprovacaoPagamento, setOcParaAprovacaoPagamento] = useState(null);
  const [filtroAprovacaoPagamento, setFiltroAprovacaoPagamento] = useState('pendente_aprovacao');
  const [aprovacaoUltimaContagem, setAprovacaoUltimaContagem] = useState(0);
  const [ajustePrecoModalOpen, setAjustePrecoModalOpen] = useState(false);

  // Estados para Análise de Preços
  const [searchProduto, setSearchProduto] = useState('');
  const [searchFornecedorAnalise, setSearchFornecedorAnalise] = useState('');
  const [ordenacaoAnalise, setOrdenacaoAnalise] = useState('data_desc');
  const [paginaAnalisePrecos, setPaginaAnalisePrecos] = useState(1);
  const [dataInicioAnalise] = useState(
    new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]
  );
  const itensPorPaginaAnalise = 10;

  // Query: OCs (Ordens de Compra)
  const { data: ocsRaw = [], isLoading: ocIsLoading } = useQuery({
    queryKey: ['compras'],
    queryFn: () => comprasService.listOcs('-created_at'),
    enabled: temPermissaoVisualizacao,
  });

