  // Filtrar OCs por permissões multi-loja
  const ocs = useMemo(() => {
    if (!ocsRaw) return [];
    return filterData(ocsRaw, user?.scope).map((oc) => {
      const centro = centrosCusto.find(cc => String(cc.id) === String(oc.centro_custo_id));
      return {
