      case "prazos": return <ConfiguracaoPrazos />;
      case "compras-pagamento": return <ConfiguracaoComprasPagamento />;
      case "rastreio": return <ConfiguracaoModulosOperacionais />;
      case "assinatura": return <ConfiguracaoAssinatura />;

