        <div className="flex gap-6">
          {/* Sidebar Esquerda */}
          <div className="w-64 flex-shrink-0">
            <div className="bg-white rounded-xl shadow-sm border overflow-hidden sticky top-28">
              <div className="p-4 border-b bg-gray-50">
