import React, { useState } from "react";
import { base44 } from "@/lib/supabase";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Plus, Search, Trash2, Edit, Loader2 } from "lucide-react";
import DevolucaoModal from "../components/devolucoes/DevolucaoModal";
import { useAuth } from "@/hooks/useAuth";

export default function Devolucoes() {
  const [searchTerm, setSearchTerm] = useState("");
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingDevolucao, setEditingDevolucao] = useState(null);
  const queryClient = useQueryClient();
    const { can } = useAuth();

    const canViewDevolucoes = can('view_devolucoes') || can('approve_devolucoes') || can('view_vendas') || can('manage_vendas');
    const canManageDevolucoes = can('approve_devolucoes') || can('manage_vendas');

    const { data: devolucoes = [], isLoading } = useQuery({
        queryKey: ['devolucoes'],
        queryFn: () => base44.entities.Devolucao.list('-created_date'),
        enabled: canViewDevolucoes,
    });
    const { data: vendas = [] } = useQuery({
        queryKey: ['vendas'],
        queryFn: () => base44.entities.Venda.list(),
        enabled: canViewDevolucoes,
    });
    const { data: produtos = [] } = useQuery({
        queryKey: ['produtos'],
        queryFn: () => base44.entities.Produto.list('nome'),
        enabled: canViewDevolucoes,
    });
    const { data: fornecedores = [] } = useQuery({
        queryKey: ['fornecedores'],
        queryFn: () => base44.entities.Fornecedor.list(),
        enabled: canViewDevolucoes,
    });

    const invalidateRelatedData = async () => {
        await Promise.all([
            queryClient.invalidateQueries({ queryKey: ['devolucoes'] }),
            queryClient.invalidateQueries({ queryKey: ['produtos'] }),
            queryClient.invalidateQueries({ queryKey: ['vendas'] }),
            queryClient.invalidateQueries({ queryKey: ['lancamentos-financeiros'] }),
            queryClient.invalidateQueries({ queryKey: ['movimentacoes-estoque'] })
        ]);
    };

    const createMutation = useMutation({
        mutationFn: (data) => base44.entities.Devolucao.create(data),
        onSuccess: async () => {
            await invalidateRelatedData();
            setIsModalOpen(false);
            setEditingDevolucao(null);
        }
    });

    const updateMutation = useMutation({
        mutationFn: ({ id, data }) => base44.entities.Devolucao.update(id, data),
        onSuccess: async () => {
            await invalidateRelatedData();
            setIsModalOpen(false);
            setEditingDevolucao(null);
        }
    });

    const deleteMutation = useMutation({
        mutationFn: (id) => base44.entities.Devolucao.delete(id),
        onSuccess: async () => {
            await invalidateRelatedData();
        }
    });

    const handleSave = async (data) => {
        const performSave = async (payload) => {
            if (editingDevolucao) {
                return updateMutation.mutateAsync({ id: editingDevolucao.id, data: payload });
            }
            return createMutation.mutateAsync(payload);
        };

        try {
            return await performSave(data);
        } catch (error) {
            const msg = String(error?.message || '').toLowerCase();
            if (!msg.includes('column') || !msg.includes('does not exist')) {
                throw error;
            }

            const payloadCompat = {
                ...data,
            };

            delete payloadCompat.financeiro_tipo;
            delete payloadCompat.justificativa_financeira;
            delete payloadCompat.destino_estoque;
            delete payloadCompat.cliente_nome;
            delete payloadCompat.financeiro_lancamento_id;
            delete payloadCompat.financeiro_lancamentos_ids;
            delete payloadCompat.processado_por;
            delete payloadCompat.data_processamento;
            delete payloadCompat.organization_id;

            return await performSave(payloadCompat);
        }
    };

  const filtered = devolucoes.filter(dev =>
    dev.numero_pedido?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    dev.cliente_nome?.toLowerCase().includes(searchTerm.toLowerCase())
  );

    if (!canViewDevolucoes) {
        return (
            <div className="max-w-3xl mx-auto py-10">
                <div className="bg-white dark:bg-neutral-900 rounded-xl border border-gray-100 dark:border-neutral-800 p-6">
                    <h1 className="text-xl font-semibold text-gray-900 dark:text-white">Devoluções e Trocas</h1>
                    <p className="mt-2 text-sm text-gray-500">Você não possui permissão para visualizar este módulo.</p>
                </div>
            </div>
        );
    }

    return (
    <div className="max-w-7xl mx-auto space-y-6">
      <div className="flex justify-between items-center">
        <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Devoluções e Trocas</h1>
            <p className="text-sm text-gray-500">Gestão de devoluções de mercadoria</p>
        </div>
                <Button
                    onClick={() => { setEditingDevolucao(null); setIsModalOpen(true); }}
                    className="bg-green-700 hover:bg-green-800 text-white"
                    disabled={!canManageDevolucoes}
                >
            <Plus className="w-4 h-4 mr-2" /> Nova Devolução
        </Button>
      </div>

      <div className="bg-white dark:bg-neutral-900 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-neutral-800">
        <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <Input 
                placeholder="Buscar por pedido ou cliente..." 
                className="pl-9 border-gray-200 dark:border-neutral-700"
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
            />
        </div>
      </div>

      <div className="bg-white dark:bg-neutral-900 rounded-xl shadow-sm border border-gray-100 dark:border-neutral-800 overflow-hidden">
        <Table>
            <TableHeader className="bg-gray-50 dark:bg-neutral-950">
                <TableRow>
                    <TableHead>Pedido</TableHead>
                    <TableHead>Cliente</TableHead>
                    <TableHead>Data</TableHead>
                    <TableHead>Tipo</TableHead>
                    <TableHead>Valor</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="text-right">Ações</TableHead>
                </TableRow>
            </TableHeader>
            <TableBody>
                {isLoading ? (
                    <TableRow><TableCell colSpan={7} className="text-center py-8"><Loader2 className="w-6 h-6 animate-spin mx-auto" /></TableCell></TableRow>
                ) : filtered.length === 0 ? (
                    <TableRow><TableCell colSpan={7} className="text-center py-8 text-gray-500">Nenhuma devolução encontrada.</TableCell></TableRow>
                ) : (
                    filtered.map(dev => (
                        <TableRow key={dev.id}>
                            <TableCell className="font-medium">#{dev.numero_pedido}</TableCell>
                            <TableCell>{dev.cliente_nome}</TableCell>
                            <TableCell className="text-sm text-gray-500">{new Date(dev.data_devolucao).toLocaleDateString('pt-BR')}</TableCell>
                            <TableCell><Badge variant="outline">{dev.tipo}</Badge></TableCell>
                            <TableCell className="font-bold">R$ {(dev.valor_devolvido || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</TableCell>
                            <TableCell><StatusBadge status={dev.status} /></TableCell>
                            <TableCell className="text-right">
                                <div className="flex justify-end gap-2">
                                    <Button variant="ghost" size="icon" onClick={() => { setEditingDevolucao(dev); setIsModalOpen(true); }}>
                                        <Edit className="w-4 h-4 text-blue-600" />
                                    </Button>
                                                                        <Button
                                                                            variant="ghost"
                                                                            size="icon"
                                                                            disabled={!canManageDevolucoes || dev.status === 'Aprovada'}
                                                                            onClick={() => {
                                                                                if (confirm('Excluir registro?')) deleteMutation.mutate(dev.id)
                                                                            }}
                                                                        >
                                        <Trash2 className="w-4 h-4 text-red-600" />
                                    </Button>
                                </div>
                            </TableCell>
                        </TableRow>
                    ))
                )}
            </TableBody>
        </Table>
      </div>

      <DevolucaoModal
        isOpen={isModalOpen}
        onClose={() => { setIsModalOpen(false); setEditingDevolucao(null); }}
        onSave={handleSave}
        devolucao={editingDevolucao}
        devolucoes={devolucoes}
        vendas={vendas}
        produtos={produtos}
                fornecedores={fornecedores}
        isLoading={createMutation.isPending || updateMutation.isPending}
      />
    </div>
  );
}

function StatusBadge({ status }) {
    const styles = {
        "Aprovada": "bg-green-100 text-green-800 border-green-200",
        "Pendente": "bg-yellow-100 text-yellow-800 border-yellow-200",
        "Rejeitada": "bg-red-100 text-red-800 border-red-200",
        "Processada": "bg-blue-100 text-blue-800 border-blue-200"
    };
    return <Badge className={`${styles[status] || "bg-gray-100 text-gray-800"} border px-2 py-0.5 text-[10px] uppercase tracking-wider`}>{status}</Badge>;
}

import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '@/hooks/useAuth';
import { useScanListener } from '@/hooks/useScanListener';
import { productService } from '@/services/productService';
import { supabase } from '@/lib/supabase';
import { Card, CardContent } from "@/components/ui/card";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Package, CheckCircle, AlertTriangle, CloudOff } from 'lucide-react';
import { toast } from "sonner";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";

// Audio Context for feedback
const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
const playSound = (type) => {
    if (audioCtx.state === 'suspended') audioCtx.resume();
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.connect(gain);
    gain.connect(audioCtx.destination);

    if (type === 'success') {
        osc.frequency.setValueAtTime(660, audioCtx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(880, audioCtx.currentTime + 0.1);
        gain.gain.setValueAtTime(0.1, audioCtx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.1);
        osc.start();
        osc.stop(audioCtx.currentTime + 0.1);
    } else if (type === 'error') {
        osc.frequency.setValueAtTime(220, audioCtx.currentTime);
        osc.type = 'sawtooth';
        gain.gain.setValueAtTime(0.2, audioCtx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.3);
        osc.start();
        osc.stop(audioCtx.currentTime + 0.3);
    } else if (type === 'wait') {
        osc.frequency.setValueAtTime(440, audioCtx.currentTime);
        gain.gain.setValueAtTime(0.05, audioCtx.currentTime);
        osc.start();
        osc.stop(audioCtx.currentTime + 0.1);
    }
};

export default function EntradaEstoque() {
    const { user, loading: authLoading } = useAuth();
    const [scannedItems, setScannedItems] = useState([]);
    const [lastScanTime, setLastScanTime] = useState({}); // Map of GTIN -> timestamp
    const [scanBuffer, setScanBuffer] = useState({}); // Map of GTIN -> current volume count
    const [loading, setLoading] = useState(false);
    const [currentCard, setCurrentCard] = useState(null); // The card currently being processed/displayed

    // Animation state
    const [shake, setShake] = useState(false);

    const triggerShake = () => {
        setShake(true);
        setTimeout(() => setShake(false), 500);
    };

    const handleScan = async (gtin) => {
        if (!gtin || !gtin.trim()) return; // Validação extra
        if (loading) return;
        setLoading(true);

        try {
            // 1. Check local DB (produtos_mestre)
            let { data: product, error } = await supabase
                .from('produtos_mestre')
                .select('*')
                .eq('gtin', gtin)
                .single();

            // 2. Fallback to API Proxy (Cosmos)
            let isNewProduct = false;
            if (!product) {
                const apiData = await productService.fetchProductByGtin(gtin);
                if (apiData) {
                    // Prepare skeleton product
                    const skeleton = {
                        gtin: apiData.gtin,
                        nome: apiData.nome || 'PRODUTO NOVO (Completar)',
                        marca: apiData.marca,
                        ncm: apiData.ncm,
                        foto_url: apiData.foto_url,
                        volumes_esperados: apiData.volumes || 1, // API usually doesn't return volumes, so default 1. Logic can be improved if we have specific volume data.
                        status: (!apiData.ncm || !apiData.nome) ? 'REVISAO_PENDENTE' : 'COMPLETO'
                    };

                    // 1. Tenta salvar o produto mestre
                    const { data: newProd, error: insertError } = await supabase
                        .from('produtos_mestre')
                        .upsert(skeleton, { onConflict: 'gtin' })
                        .select()
                        .maybeSingle(); // Use maybeSingle para evitar erros se vier vazio

                    // 2. Tratamento de Erro REAL
                    if (insertError) {
                        console.error('🚨 ERRO AO SALVAR:', insertError);
                        playSound('error');
                        alert(`Erro no Banco: ${insertError.message}`);
                        return;
                    }

                    // 3. A CORREÇÃO DE OURO:
                    const referenciaProduto = newProd?.gtin || skeleton.gtin;
                    console.log('✅ Produto garantido. Usando referência:', referenciaProduto);

                    // Garante que o objeto product exista para os próximos passos
                    product = newProd || skeleton;
                    isNewProduct = true;
                } else {
                    // Unknown product
                    playSound('error');
                    triggerShake();
                    setCurrentCard({ status: 'error', message: `Produto desconhecido: ${gtin}` });
                    setLoading(false);
                    return;
                }
            }

            // 3. Kit Logic
            const now = Date.now();
            const lastTime = lastScanTime[gtin] || 0;
            const currentVolume = scanBuffer[gtin] || 0;
            const expectedVolumes = product.volumes_esperados || 1;

            if (expectedVolumes > 1) {
                if (now - lastTime < 2000 && currentVolume < expectedVolumes && currentVolume > 0) {
                    // Cooldown active
                    playSound('wait');
                    setCurrentCard({ status: 'warning', message: 'Aguarde 2s para o próximo volume...', product });
                    setLoading(false);
                    return;
                }

                // Advance volume
                const nextVolume = currentVolume + 1;
                setScanBuffer(prev => ({ ...prev, [gtin]: nextVolume }));
                setLastScanTime(prev => ({ ...prev, [gtin]: now }));

                if (nextVolume < expectedVolumes) {
                    playSound('success'); // Soft success
                    setCurrentCard({ status: 'info', message: `Volume ${nextVolume}/${expectedVolumes} detectado`, product });
                    setLoading(false);
                    return;
                }
                // If reached here, we have all volumes
                // Clear buffer
                setScanBuffer(prev => {
                    const newState = { ...prev };
                    delete newState[gtin];
                    return newState;
                });
            }

            // 4. Register Stock Entry
            // Get user's store (tenant) - defaulting to first store found for now or hardcoded logic
            // Ideally should come from auth context.
            // Using a dummy insert for now as we need to fetch user context
            // Using getSession instead of getUser for better resilience (checks local cache first)
            // 4. Register Stock Entry
            if (authLoading) {
                throw new Error("Carregando autenticação...");
            }
            if (!user) {
                throw new Error("Usuário não autenticado");
            }

            // Se não tiver loja vinculada, assume que está no CD
            const tenantId = user.loja || 'CD';

            if (!tenantId) {
                // Should not happen if we default to CD, but keeping safe check or removing
                throw new Error("Erro interno: Local de estoque não definido.");
            }

            // Insert into estoque_loja
            const { error: stockError } = await supabase.from('estoque_loja').insert({
                gtin: product.gtin,
                tenant_id: tenantId,
                quantidade: 1, // Adding 1 unit (kit or item)
                volumes_recebidos: Array.from({ length: expectedVolumes }, (_, i) => i + 1) // [1, 2, ...]
            });

            if (stockError) throw stockError;

            // --- SINCRONIZAÇÃO COM ESTOQUE GLOBAL (PDV) ---
            // Além de registrar na unidade (estoque_loja), atualizamos o total no Produto Mestre/Variação
            // para que o PDV reflita a disponibilidade imediata.
            try {
                const { data: mainProds, error: findError } = await supabase
                    .from('produtos')
                    .select('id, quantidade_estoque')
                    .eq('codigo_barras', product.gtin);

                if (!findError && mainProds && mainProds.length > 0) {
                    for (const p of mainProds) {
                        await supabase
                            .from('produtos')
                            .update({ quantidade_estoque: (p.quantidade_estoque || 0) + 1 })
                            .eq('id', p.id);
                    }
