                            <div className="w-8 h-8 rounded-full bg-slate-50 border-2 border-white flex items-center justify-center text-[10px] text-slate-500 font-bold shadow-sm">
                                +99
                            </div>
                        </div>
                    </div>

                </div>

                {/* Footer */}
                <div className="text-center mt-8">
                    <p className="text-slate-400 text-xs font-body">
                        © 2026 {EMPRESA.nome}. Todos os direitos reservados.
                    </p>
                </div>

            </div>
        </div>
    );
}

import React, { useState, useEffect } from "react";
import { useLocation, useNavigate, Link } from "react-router-dom";
import { base44 } from "@/api/base44Client";
import { useQuery } from "@tanstack/react-query";
import { useTenant } from "@/contexts/TenantContext";
import {
  LayoutDashboard, Warehouse, Users, ShoppingCart, Truck, Building2,
  FileText, Menu, Settings, DollarSign, LogOut, RotateCcw, Plus,
  UserCog, BarChart3, Presentation, Receipt, MessageCircle, CreditCard,
  Moon, Sun, ChevronLeft, ChevronRight, Search, Bell, HelpCircle, Store, ChevronDown
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import NotificacoesPanel from "@/components/notificacoes/NotificacoesPanel";
import BuscaGlobal from "@/components/busca/BuscaGlobal";
import NovoUsuarioModal from "@/components/usuarios/NovoUsuarioModal";
import {
  Sidebar, SidebarContent, SidebarGroup, SidebarGroupContent, SidebarGroupLabel,
  SidebarMenu, SidebarMenuButton, SidebarMenuItem, SidebarHeader, SidebarFooter,
  SidebarProvider, SidebarTrigger,
} from "@/components/ui/sidebar";
import StoreSelectorModal from "@/components/common/StoreSelectorModal";
import { MENU_ITEMS } from "@/config/permissions";
import { useAuth } from "@/hooks/useAuth";
import { useLojas } from "@/hooks/useLojas";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

import { supabase } from "@/lib/supabase";
import { differenceInHours } from "date-fns";
import { useConnectionStatus } from "@/hooks/useConnectionStatus";
import { Activity, Wifi, WifiOff, MessageCircleOff } from "lucide-react";
import { hasAnyRole } from "@/config/permissions";

export default function Layout({ children, currentPageName }) {
  const location = useLocation();
  const navigate = useNavigate();
  const { user, loading, can, logout, selectedStore, setSelectedStore } = useAuth();
  const { data: lojas = [] } = useLojas();

  // Buscar alertas/pendências para o badge do menu
  const { data: menuBadges } = useQuery({
    queryKey: ['menu-badges-compras'],
    queryFn: async () => {
      if (!user) return null;

      let count = 0;
      if (hasAnyRole(user, ['Financeiro', 'Administrador'])) {
        const { count: pendingApps } = await supabase
          .from('compras_aprovacoes')
          .select('*', { count: 'exact', head: true })
          .eq('status', 'pendente');
        count += (pendingApps || 0);
      }

      if (hasAnyRole(user, ['Estoque', 'Gerente Geral', 'Administrador'])) {
        // Não faturados ou sem resposta > 24h
        const { data: ordens } = await supabase
          .from('compras_ordens')
          .select('status, updated_at, created_at, devolutiva')
          .or('status.eq.Aguardando Envio,status.eq.Pedido Enviado')
          .is('deleted_at', null);

        const criticos = (ordens || []).filter(o => {
          if (o.status === 'Aguardando Envio') return true;
          if (o.status === 'Pedido Enviado' && !o.devolutiva) {
            const horas = differenceInHours(new Date(), new Date(o.updated_at || o.created_at));
            return horas > 24;
          }
          return false;
        });
        count += criticos.length;
      }
      return count;
    },
    enabled: !!user,
    refetchInterval: 30000 // A cada 30 segundos
  });

  // Buscar assistências pendentes para o badge do menu
  const { data: assistenciaBadges = 0 } = useQuery({
    queryKey: ['menu-badges-assistencia'],
    queryFn: async () => {
      if (!user) return 0;
      const { count, error } = await supabase
        .from('assistencias_tecnicas')
        .select('*', { count: 'exact', head: true })
        .not('status', 'in', '("Concluída", "Cancelada")');

      if (error) {
        console.error('Erro ao buscar badges de assistência:', error);
        return 0;
      }
      return count || 0;
    },
    enabled: !!user && can('view_assistencia'),
    refetchInterval: 30000
  });
  const { brandName, brandLogo, isModuleActive } = useTenant();
  const [darkMode, setDarkMode] = useState(() => localStorage.getItem('darkMode') === 'true');
  const [buscaAberta, setBuscaAberta] = useState(false);
  const [novoUsuarioModalOpen, setNovoUsuarioModalOpen] = useState(false);
  const shouldMonitorWhatsApp = location.pathname === '/admin/Configuracoes' || location.pathname === '/admin/CatalogoWhatsApp';
  const { isSystemOnline, isWhatsAppConnected } = useConnectionStatus(shouldMonitorWhatsApp);

  useEffect(() => {
    localStorage.setItem('darkMode', darkMode);
    if (darkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [darkMode]);

  // Atalho Ctrl+K para abrir busca
  useEffect(() => {
    const handleKeyDown = (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
        e.preventDefault();
        setBuscaAberta(true);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  const { data: alertasAtivos = [] } = useQuery({
    queryKey: ['alertas-ativos-menu'],
    queryFn: async () => {
      const alertas = await base44.entities.AlertaRecompra.list();
      return alertas.filter(a => a.status === 'Ativo');
    },
    refetchInterval: 60000,
    enabled: !!user && can('view_estoque')
  });

  if (location.pathname === "/admin/BoasVindas" || location.pathname === "/admin/ModoReuniao" || location.pathname === "/admin/Entregador" || location.pathname === "/admin/MontadorExterno") {
    return children;
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-gray-50 dark:bg-neutral-950">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-green-600" />
      </div>
    );
  }

  // Filtra menu baseado em permissões E módulos ativos do tenant
  const menuFiltrado = MENU_ITEMS.filter(item => {
    // Verifica permissão do usuário
    if (!can(item.permission)) return false;
    // Se o item tem um módulo associado, verifica se está ativo no tenant
    if (item.module && !isModuleActive(item.module)) return false;
    return true;
  });
  const sections = [...new Set(menuFiltrado.map(i => i.section))];
  const currentMenuItem = menuFiltrado.find((item) => item.url.toLowerCase() === location.pathname.toLowerCase());
  const isPedidosPage = ['/admin/pedidos', '/admin/vendas'].includes(location.pathname.toLowerCase());
  const currentPageTitle = isPedidosPage ? 'Pedidos' : (currentMenuItem?.title || brandName || 'Dashboard');
  const currentPageSubtitle = currentPageTitle === 'Dashboard'
    ? 'Visão geral da sua empresa'
    : isPedidosPage
      ? 'Gerencie e acompanhe todos os pedidos da sua empresa'
      : 'Gerencie as informações do seu módulo';

  return (
    <SidebarProvider>
      <div className="min-h-screen flex w-full bg-gray-50 dark:bg-neutral-950">
        <Sidebar collapsible="icon" className="border-r border-gray-200 dark:border-neutral-800 bg-white dark:bg-neutral-950 text-slate-800 dark:text-slate-200">
          <SidebarHeader className="p-3 border-b border-gray-100 dark:border-neutral-800 flex flex-col items-center bg-white dark:bg-neutral-950">
            {/* Toggle Button - always visible at top when collapsed */}
            <div className="hidden group-data-[collapsible=icon]:flex w-full justify-center mb-2">
              <SidebarTrigger className="text-slate-500 hover:text-slate-900 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-neutral-800" />
            </div>

            {/* Logo and Title Row */}
            <div className="flex items-center w-full gap-2.5 p-1 group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:p-0">
              {brandLogo ? (
                <div className="w-9 h-9 rounded-xl border border-gray-200 dark:border-neutral-800 bg-white dark:bg-neutral-900 flex items-center justify-center overflow-hidden flex-shrink-0 p-1 shadow-sm">
                  <img src={brandLogo} alt="Logo" className="w-full h-full object-contain" />
                </div>
              ) : (
                <div className="w-9 h-9 rounded-xl bg-emerald-500 flex items-center justify-center text-white font-black text-xl flex-shrink-0 shadow-md">
                  G
                </div>
              )}
              <div className="flex-1 min-w-0 group-data-[collapsible=icon]:hidden">
                <h2 className="font-extrabold text-[15px] tracking-tight text-slate-900 dark:text-white truncate flex items-center gap-1">
                  <span>{brandName || 'GestApp'}</span>
                </h2>

                <div className="flex flex-col">
                  <p className="text-[11px] text-slate-500 dark:text-slate-400 truncate font-medium">
                    {user?.loja ? `Loja ${user.loja}` : (selectedStore ? `Loja ${selectedStore}` : 'Todas as Lojas')}
                  </p>

                  {/* Status Indicators */}
                  <div className="flex items-center gap-2 mt-1">
                    <div
                      className="flex items-center gap-1"
                      title={isSystemOnline ? "Sistema Online" : "Sistema Offline (Sem internet)"}
                    >
                      <div className={`w-1.5 h-1.5 rounded-full ${isSystemOnline ? 'bg-emerald-500 animate-pulse' : 'bg-red-500'}`} />
                      <span className="text-[10px] text-slate-500 dark:text-slate-400 font-medium">
                        {isSystemOnline ? 'Online' : 'Offline'}
                      </span>
                    </div>
                    <div
                      className="flex items-center gap-1"
                      title={isWhatsAppConnected ? "WhatsApp Conectado" : "WhatsApp Desconectado"}
                    >
                      <div className={`w-1.5 h-1.5 rounded-full ${isWhatsAppConnected ? 'bg-orange-500' : 'bg-amber-500'}`} />
                      <span className="text-[10px] text-slate-500 dark:text-slate-400 font-medium">
                        WhatsApp
                      </span>
                    </div>
                  </div>

                  {!user?.loja && selectedStore && (
                    <button
                      onClick={() => setSelectedStore(null)}
                      className="text-[10px] text-emerald-600 hover:text-emerald-700 dark:text-emerald-400 dark:hover:text-emerald-300 hover:underline text-left cursor-pointer mt-1 font-medium"
                    >
                      Trocar Loja
                    </button>
                  )}
                </div>
              </div>
              <SidebarTrigger className="hidden md:flex flex-shrink-0 text-slate-400 hover:text-slate-900 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-neutral-800 group-data-[collapsible=icon]:hidden" />
            </div>

            {/* Search Button - full when expanded, icon-only when collapsed */}
            <div className="w-full mt-3 group-data-[collapsible=icon]:flex group-data-[collapsible=icon]:justify-center">
              <Button
                variant="outline"
                className="w-full justify-start text-left font-normal bg-white dark:bg-neutral-900 border-gray-200 dark:border-neutral-800 text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-neutral-800 group-data-[collapsible=icon]:!w-8 group-data-[collapsible=icon]:!h-8 group-data-[collapsible=icon]:!p-0 group-data-[collapsible=icon]:justify-center h-9 text-[13px] rounded-md shadow-sm"
                onClick={() => setBuscaAberta(true)}
              >
                <Search className="w-4 h-4 group-data-[collapsible=icon]:mr-0 mr-2 text-slate-400 flex-shrink-0" />
                <span className="group-data-[collapsible=icon]:hidden">Buscar...</span>
                <kbd className="ml-auto pointer-events-none inline-flex h-5 select-none items-center gap-1 rounded border border-gray-200 dark:border-neutral-700 bg-gray-50 dark:bg-neutral-800 px-1.5 font-mono text-[10px] font-medium text-slate-500 dark:text-slate-400 opacity-100 group-data-[collapsible=icon]:hidden">
                  <span className="text-[10px]">⌘K</span>
                </kbd>
              </Button>
            </div>
          </SidebarHeader>

          <SidebarContent className="p-2 overflow-y-auto group-data-[collapsible=icon]:!p-0 group-data-[collapsible=icon]:!px-1 custom-scrollbar bg-white dark:bg-neutral-950">
            {sections.map(section => (
              <SidebarGroup key={section}>
                <SidebarGroupLabel className="text-[11px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider px-2 mb-2 mt-4">
                  {section}
                </SidebarGroupLabel>
                <SidebarGroupContent>
                  <SidebarMenu>
                    {menuFiltrado.filter(i => i.section === section).map(item => (
                      <SidebarMenuItem key={item.title}>
                        <SidebarMenuButton
                          asChild
                          isActive={location.pathname === item.url}
                          tooltip={item.title}
                          className={`w-full h-10 text-[13px] transition-all rounded-lg mb-0.5 group-data-[collapsible=icon]:!w-8 group-data-[collapsible=icon]:!p-0 group-data-[collapsible=icon]:mx-auto ${location.pathname === item.url
                            ? "bg-slate-50 dark:bg-neutral-900 text-slate-900 dark:text-white font-semibold"
                            : "text-slate-600 dark:text-slate-400 hover:bg-slate-50/80 dark:hover:bg-neutral-900 hover:text-slate-900 dark:hover:text-white"
                            }`}
                        >
                          <Link to={item.url} className="flex items-center gap-3 px-3 group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:!px-0">
                            <item.icon className={`w-4 h-4 flex-shrink-0 ${location.pathname === item.url ? "text-emerald-600 dark:text-emerald-500" : "text-slate-400 dark:text-slate-500"}`} />
                            <span className="flex-1 group-data-[collapsible=icon]:hidden truncate">{item.title}</span>
                            {item.title === 'Estoque' && alertasAtivos.length > 0 && (
                              <Badge className="h-4 min-w-4 flex items-center justify-center p-0 px-1 bg-red-500 hover:bg-red-600 text-white text-[9px] rounded-full group-data-[collapsible=icon]:absolute group-data-[collapsible=icon]:-top-1 group-data-[collapsible=icon]:-right-1">
                                {alertasAtivos.length}
                              </Badge>
                            )}
                            {item.title === 'Setor de Compras' && menuBadges > 0 && (
                              <Badge className="h-4 min-w-4 flex items-center justify-center p-0 px-1 bg-red-500 hover:bg-red-600 text-white text-[9px] rounded-full group-data-[collapsible=icon]:absolute group-data-[collapsible=icon]:-top-1 group-data-[collapsible=icon]:-right-1">
                                {menuBadges > 99 ? '99+' : menuBadges}
                              </Badge>
                            )}
                            {item.title === 'Assistência Técnica' && assistenciaBadges > 0 && (
                              <Badge className="h-4 min-w-4 flex items-center justify-center p-0 px-1 bg-red-500 hover:bg-red-600 text-white text-[9px] rounded-full group-data-[collapsible=icon]:absolute group-data-[collapsible=icon]:-top-1 group-data-[collapsible=icon]:-right-1">
                                {assistenciaBadges > 99 ? '99+' : assistenciaBadges}
                              </Badge>
                            )}
                          </Link>
                        </SidebarMenuButton>
                      </SidebarMenuItem>
                    ))}
                  </SidebarMenu>
                </SidebarGroupContent>
              </SidebarGroup>
            ))}
          </SidebarContent>

          <SidebarFooter className="border-t border-gray-100 dark:border-neutral-800 p-3 bg-white dark:bg-neutral-950">
            {/* User Info - hidden when collapsed */}
            <div className="flex items-center gap-3 p-1 mb-3 group-data-[collapsible=icon]:justify-center">
              <div className="w-9 h-9 rounded-full bg-slate-50 dark:bg-neutral-800 text-slate-600 dark:text-slate-300 font-bold text-[13px] flex items-center justify-center flex-shrink-0">
                {user?.full_name?.charAt(0).toUpperCase() || 'U'}
              </div>
              <div className="flex-1 min-w-0 group-data-[collapsible=icon]:hidden">
                <p className="text-[13px] font-semibold text-slate-900 dark:text-white truncate">{user?.full_name || 'Usuário'}</p>
                <p className="text-[11px] text-slate-500 dark:text-slate-400 truncate">{user?.email || user?.cargo || 'Colaborador'}</p>
              </div>
            </div>

            {/* New User Button - hidden when collapsed */}
            {can('manage_user_access') && (
              <Button
                size="sm"
                onClick={() => setNovoUsuarioModalOpen(true)}
                className="w-full bg-[#189851] hover:bg-[#158043] text-white h-9 text-[13px] font-medium shadow-sm mb-3 group-data-[collapsible=icon]:hidden rounded-md"
              >
                <Plus className="w-4 h-4 mr-1.5" />
                Novo Usuário
              </Button>
            )}

            {/* Action Buttons */}
            <div className="flex gap-2 group-data-[collapsible=icon]:flex-col">
              <Button
                variant="outline"
                size="sm"
                onClick={() => setDarkMode(!darkMode)}
                className="flex-1 h-9 text-[13px] font-medium text-slate-700 dark:text-slate-300 border-gray-200 dark:border-neutral-800 hover:bg-slate-50 dark:hover:bg-neutral-900 group-data-[collapsible=icon]:w-8 group-data-[collapsible=icon]:p-0 group-data-[collapsible=icon]:flex-none rounded-md"
              >
                {darkMode ? <Sun className="w-4 h-4" /> : <Moon className="w-4 h-4" />}
                <span className="group-data-[collapsible=icon]:hidden ml-1.5">Tema</span>
              </Button>
              <Button
                variant="ghost"
                size="sm"
                onClick={logout}
                className="flex-1 h-9 text-[13px] font-medium text-red-600 hover:text-red-700 hover:bg-red-50 dark:hover:bg-red-950/30 group-data-[collapsible=icon]:w-8 group-data-[collapsible=icon]:p-0 group-data-[collapsible=icon]:flex-none rounded-md"
              >
                <LogOut className="w-4 h-4" />
                <span className="group-data-[collapsible=icon]:hidden ml-1.5">Sair</span>
              </Button>
            </div>
          </SidebarFooter>
        </Sidebar>

        <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
          <header className="h-14 sm:h-16 bg-slate-50 dark:bg-neutral-950 flex items-center justify-between px-4 sm:px-6 w-full flex-shrink-0 gap-4">
            <div className="flex items-center gap-3 sm:gap-4 shrink-0">
              <div className="hidden sm:block">
                <h1 className="text-base sm:text-lg font-bold tracking-tight text-slate-900 dark:text-white">
                  {currentPageTitle}
                </h1>
                <p className="text-[11px] sm:text-xs text-slate-500 dark:text-slate-400 mt-0.5">
                  {currentPageSubtitle}
                </p>
              </div>
            </div>

            <div className="relative hidden md:flex flex-1 max-w-md mx-auto justify-center">
              <div className="relative w-full">
                <Search className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                <Button 
                  variant="outline" 
                  onClick={() => setBuscaAberta(true)}
                  className="w-full justify-start pl-8 text-[13px] h-9 bg-white dark:bg-neutral-900 border-gray-200 dark:border-neutral-800 text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-neutral-800 rounded-lg shadow-sm"
                >
                  Pesquisar (Ctrl + K)
                </Button>
              </div>
            </div>

            <div className="flex items-center gap-1 sm:gap-2 shrink-0">
              <button
                className="relative p-2 rounded-lg text-slate-500 hover:text-slate-900 dark:text-slate-400 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-neutral-800 transition-colors"
                title="Notificações"
              >
                <Bell className="w-4 h-4 sm:w-5 sm:h-5" />
                {menuBadges > 0 && (
                  <span className="absolute top-1 right-1 sm:top-1.5 sm:right-1.5 w-2 h-2 bg-emerald-500 rounded-full border-2 border-white dark:border-neutral-950" />
                )}
              </button>
              <button
                className="p-2 rounded-lg text-slate-500 hover:text-slate-900 dark:text-slate-400 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-neutral-800 transition-colors hidden sm:block"
                title="Ajuda"
              >
                <HelpCircle className="w-4 h-4 sm:w-5 sm:h-5" />
              </button>

              {user?.loja ? (
                <div className="hidden md:flex items-center gap-2 h-9 px-3 ml-2 rounded-lg bg-white dark:bg-neutral-900 border border-gray-200 dark:border-neutral-800 text-[13px] font-medium text-slate-700 dark:text-slate-200 shadow-sm">
                  <Store className="w-4 h-4 text-emerald-600 dark:text-emerald-500" />
                  <span className="max-w-[120px] truncate">Loja {user.loja}</span>
                </div>
              ) : (
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <div className="hidden md:flex items-center gap-2 h-9 px-3 ml-2 rounded-lg bg-white dark:bg-neutral-900 border border-gray-200 dark:border-neutral-800 text-[13px] font-medium text-slate-700 dark:text-slate-200 cursor-pointer hover:bg-slate-50 dark:hover:bg-neutral-800 shadow-sm transition-colors">
                      <Store className="w-4 h-4 text-emerald-600 dark:text-emerald-500" />
                      <span className="max-w-[120px] truncate">
                        {selectedStore && selectedStore !== 'todas' ? (selectedStore.toLowerCase().startsWith('loja') ? selectedStore : `Loja ${selectedStore}`) : 'Todas Lojas'}
                      </span>
                      <ChevronDown className="w-3.5 h-3.5 text-slate-400" />
                    </div>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end" className="w-48">
                    <DropdownMenuItem 
                      onClick={() => setSelectedStore('todas')}
                      className={(!selectedStore || selectedStore === 'todas') ? "font-semibold text-emerald-600 dark:text-emerald-400 bg-emerald-50/50 dark:bg-emerald-950/20" : ""}
                    >
                      Todas Lojas
                    </DropdownMenuItem>
                    {lojas.map((loja) => {
                      const isSelected = selectedStore === loja.nome;
                      return (
                        <DropdownMenuItem
                          key={loja.id || loja.nome}
                          onClick={() => setSelectedStore(loja.nome)}
                          className={isSelected ? "font-semibold text-emerald-600 dark:text-emerald-400 bg-emerald-50/50 dark:bg-emerald-950/20" : ""}
                        >
                          Loja {loja.nome}
                        </DropdownMenuItem>
                      );
                    })}
                  </DropdownMenuContent>
                </DropdownMenu>
              )}
            </div>
          </header>
          <div className="flex-1 overflow-auto p-4 sm:p-6 bg-slate-50 dark:bg-neutral-950">
            {children}
          </div>
        </main>
      </div>

      <BuscaGlobal open={buscaAberta} onClose={() => setBuscaAberta(false)} />
      <NovoUsuarioModal
        isOpen={novoUsuarioModalOpen}
        onClose={() => setNovoUsuarioModalOpen(false)}
      />

      <StoreSelectorModal />
    </SidebarProvider>
  );
}

import React, { useState, useEffect } from "react";
import { base44 } from "@/api/base44Client";
import { useTenant } from "@/contexts/TenantContext";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Eye, EyeOff, Lock, Mail, Store } from "lucide-react";

export default function Login() {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [showPassword, setShowPassword] = useState(false);

  // Campos do formulario
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  // Verificar se ja esta logado
  useEffect(() => {
    base44.auth.me().then(user => {
      if (user) {
        redirectByRole(user.cargo);
      }
    }).catch(() => { });
  }, []);

  const redirectByRole = (userCargo) => {
    if (userCargo === 'Montador Externo') {
      window.location.href = '/montador-externo';
    } else if (userCargo === 'Entregador') {
      window.location.href = '/entregador';
    } else {
      window.location.reload();
    }
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError("");

    try {
      const { data, error } = await base44.auth.login(email, password);
      if (error) throw error;

      const user = await base44.auth.me();

      // Verificar se é funcionário (tem cargo válido)
      if (!user || !user.cargo) {
        setError("Acesso restrito a funcionários. Clientes devem usar a Área do Cliente.");
        await base44.auth.logout();
        setLoading(false);
        return;
      }

      redirectByRole(user.cargo);
    } catch (err) {
      console.error("Login error:", err);
      setError("Email ou senha incorretos. Tente novamente.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-green-50 to-blue-50 dark:from-gray-900 dark:to-gray-800 p-4">
      <Card className="w-full max-w-md shadow-xl">
        <CardHeader className="text-center">
          <div className="flex justify-center mb-4">
            <div className="w-16 h-16 bg-green-100 dark:bg-green-900 rounded-full flex items-center justify-center">
              <Store className="w-8 h-8 text-green-600 dark:text-green-400" />
            </div>
          </div>
          <CardTitle className="text-2xl font-bold text-gray-900 dark:text-white">
            GestApp
          </CardTitle>
          <CardDescription className="text-gray-600 dark:text-gray-400">
            Entre com suas credenciais para acessar
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleLogin} className="space-y-4">
            {error && (
              <Alert variant="destructive">
                <AlertDescription>{error}</AlertDescription>
              </Alert>
            )}

            <div className="space-y-2">
              <Label htmlFor="email">Email</Label>
              <div className="relative">
                <Mail className="absolute left-3 top-3 h-4 w-4 text-gray-400" />
                <Input
                  id="email"
                  type="email"
                  placeholder="seu@email.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="pl-10"
                  required
                  disabled={loading}
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="password">Senha</Label>
              <div className="relative">
                <Lock className="absolute left-3 top-3 h-4 w-4 text-gray-400" />
                <Input
                  id="password"
                  type={showPassword ? "text" : "password"}
                  placeholder="Digite sua senha"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="pl-10 pr-10"
                  required
                  disabled={loading}
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-3 text-gray-400 hover:text-gray-600"
                  disabled={loading}
                >
                  {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                </button>
              </div>
            </div>

            <Button
              type="submit"
              className="w-full bg-green-600 hover:bg-green-700 text-white"
              disabled={loading}
            >
              {loading ? "Entrando..." : "Entrar"}
            </Button>
          </form>

          <div className="mt-6 text-center text-xs text-gray-400">
            Por Natan R.
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { useTenant } from "@/contexts/TenantContext";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Eye, EyeOff, Lock, IdCard, Loader2, Store } from "lucide-react";
import { supabase } from "@/api/base44Client";
import { setActiveAuthMode, AUTH_MODES } from "@/lib/supabase";
import { useNavigate } from "react-router-dom";

export default function LoginFuncionario() {
    const navigate = useNavigate();
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState("");
    const [showPassword, setShowPassword] = useState(false);

    // Estados do formulário
    const [identificacao, setIdentificacao] = useState("");
    const [senha, setSenha] = useState("");

    // Estado de primeiro acesso
    const [primeiroAcesso, setPrimeiroAcesso] = useState(false);
    const [tokenTemp, setTokenTemp] = useState("");
    const [novaSenha, setNovaSenha] = useState("");
    const [confirmarSenha, setConfirmarSenha] = useState("");



    const redirectByRole = (cargo, profile = null) => {
        // Verificar parametro de redirecionamento na URL
        const params = new URLSearchParams(window.location.search);
        const redirect = params.get('redirect');
        if (redirect) {
            navigate(redirect, { replace: true });
            return;
        }

        const effectiveCargo = cargo || (Array.isArray(profile?.cargos) && profile.cargos[0]) || 'Administrador';

        if (effectiveCargo === 'Montador Externo') {
            navigate('/admin/MontadorExterno', { replace: true });
        } else if (effectiveCargo === 'Entregador') {
            navigate('/admin/Entregador', { replace: true });
        } else if (effectiveCargo === 'Montador') {
            navigate('/admin/Montagem', { replace: true });
        } else {
            navigate('/admin', { replace: true });
        }
    };

    // Verificação de sessão removida para evitar loop de redirecionamento.
    // O controle de redirecionamento se já estiver logado é feito no App.jsx (PagesContent) usando o hook useAuth.

    // [FIX] Mas se o usuário JÁ estiver logado e cair aqui (porque o App.jsx permitiu por ser primeiro acesso),
    // precisamos ativar o modo de troca de senha imediatamente.
    useEffect(() => {
        const checkSession = async () => {
            const { data: { session } } = await supabase.auth.getSession();
            if (session?.user) {
                // Verificar perfil
                const { data: profile } = await supabase.from('public_users').select('*').eq('id', session.user.id).maybeSingle();
                if (profile?.primeiro_acesso) {
                    console.log("Sessão ativa detectada com primeiro_acesso=true. Ativando wizard.");
                    setPrimeiroAcesso(true);
                    setTokenTemp(session.access_token);
                }
            }
        };
        checkSession();
    }, []);

    const handleLogin = async (e) => {
        e.preventDefault();
        setLoading(true);
        setError("");

        const cleanIdentificacao = (identificacao || "").trim();
        const isEmailInput = cleanIdentificacao.includes("@");

        if (!cleanIdentificacao) {
            setError("Por favor, informe sua matrícula ou e-mail.");
            setLoading(false);
            return;
        }

        try {
            // 1. Resolver matrícula/email para o email de login via RPC (bypass RLS)
            let resolvedEmail = null;
            try {
                const { data: rpcEmail, error: rpcError } = await supabase
                    .rpc('resolve_login_email', { p_identificacao: cleanIdentificacao });

                if (rpcError) {
                    console.warn("Aviso na RPC resolve_login_email:", rpcError);
                } else if (rpcEmail) {
                    resolvedEmail = rpcEmail;
                }
            } catch (rpcEx) {
                console.warn("Exceção na RPC resolve_login_email:", rpcEx);
            }

            // Se o usuário digitou um email diretamente, podemos usar o próprio email mesmo se a RPC falhar
            const targetEmail = resolvedEmail || (isEmailInput ? cleanIdentificacao.toLowerCase() : null);

            if (!targetEmail) {
                throw new Error("Matrícula não encontrada ou usuário inativo. Verifique os dados digitados ou contate o administrador.");
            }

            // 2. Autenticar via Supabase Auth com o email resolvido
            const { data: authData, error: authError } = await supabase.auth.signInWithPassword({
                email: targetEmail,
                password: senha
            });

            if (authError) {
                console.error("Erro na autenticação:", authError);
                if (authError.message?.toLowerCase().includes("invalid login credentials") || authError.status === 400) {
                    throw new Error("Credenciais inválidas. Verifique seu e-mail/matrícula e senha.");
                }
                if (authError.message?.toLowerCase().includes("email not confirmed")) {
                    throw new Error("E-mail ainda não confirmado no sistema.");
                }
                throw new Error(authError.message || "Erro ao realizar login. Verifique sua senha.");
            }

            if (!authData?.session?.user) {
                throw new Error("Falha ao iniciar sessão. Tente novamente.");
            }

            // 3. Buscar perfil AUTENTICADO (agora o RLS permite via organization_id)
            const { data: userProfile, error: profileError } = await supabase
                .from('public_users')
                .select('*')
                .eq('id', authData.session.user.id)
                .maybeSingle();

            if (profileError) {
                console.warn("Aviso ao buscar perfil autenticado:", profileError);
            }

            // Se perfil existir e estiver expressamente inativo
            if (userProfile && userProfile.ativo === false) {
                await supabase.auth.signOut();
                throw new Error("Este usuário está inativo no sistema. Contate o administrador.");
            }

            // Perfil efetivo (com fallback resiliente se o registro ainda não existir em public_users)
            let effectiveProfile = userProfile;
            if (!effectiveProfile) {
                const userMeta = authData.session.user.user_metadata || {};
                const fallbackCargo = userMeta.cargo || (userMeta.role === 'admin_org' ? 'Administrador' : 'Colaborador');
                effectiveProfile = {
                    id: authData.session.user.id,
                    email: authData.session.user.email,
                    full_name: userMeta.full_name || authData.session.user.email?.split('@')[0] || 'Usuário',
                    cargo: fallbackCargo,
                    ativo: true,
                    primeiro_acesso: false
                };

                // Tentar inserir em background para regularizar perfil
                supabase.from('public_users').insert(effectiveProfile).then(({ error: insertErr }) => {
                    if (insertErr) console.warn("Aviso ao auto-criar perfil em public_users:", insertErr);
                });
            }

            // Verificar primeiro acesso
            if (effectiveProfile.primeiro_acesso) {
                setPrimeiroAcesso(true);
                setTokenTemp(authData.session?.access_token || '');
                setError("");
                return;
            }

            // Atualizar último login
            if (effectiveProfile.id) {
                supabase.from('public_users')
                    .update({ ultimo_login: new Date().toISOString() })
                    .eq('id', effectiveProfile.id)
                    .then(({ error: loginTimeErr }) => {
                        if (loginTimeErr) console.warn("Aviso ao atualizar ultimo_login:", loginTimeErr);
                    });
            }

            // ISOLAMENTO: Marcar sessão como tenant e limpar cache de operador
            setActiveAuthMode(AUTH_MODES.TENANT);
            try { localStorage.removeItem('operator_auth_cache'); } catch { /* ignore */ }

            // Salvar dados do usuário no localStorage para compatibilidade
            localStorage.setItem('employee_user', JSON.stringify(effectiveProfile));

            // Redirecionar por cargo
            redirectByRole(effectiveProfile.cargo, effectiveProfile);

        } catch (err) {
            console.error("Erro no login:", err);
            setError(err.message || "Erro ao fazer login");
        } finally {
            setLoading(false);
        }
    };

    const handleTrocarSenha = async (e) => {
        e.preventDefault();

        if (novaSenha !== confirmarSenha) {
            setError("As senhas não coincidem");
            return;
        }

        // Validar complexidade da senha
        if (novaSenha.length < 6) {
            setError("A senha deve ter pelo menos 6 caracteres");
            return;
        }
        if (!/[A-Z]/.test(novaSenha)) {
            setError("A senha deve conter pelo menos uma letra maiúscula");
            return;
        }
        if (!/[0-9]/.test(novaSenha)) {
            setError("A senha deve conter pelo menos um número");
            return;
        }

        setLoading(true);
        setError("");

        try {
            // Atualizar senha via Supabase Auth (usuário já está logado via tokenTemp/session)
            const { error: updateError } = await supabase.auth.updateUser({
                password: novaSenha
            });

            if (updateError) {
                throw new Error(updateError.message);
            }

            // Marcar primeiro_acesso como false no banco
            const { data: sessionData } = await supabase.auth.getSession();
            if (sessionData?.session?.user?.id) {
                await supabase
                    .from('public_users')
                    .update({ primeiro_acesso: false })
                    .eq('id', sessionData.session.user.id);
            }

            // Buscar perfil do usuário
            const { data: userProfile } = await supabase
                .from('public_users')
                .select('*')
                .eq('id', sessionData.session.user.id)
                .maybeSingle();

            if (userProfile) {
                localStorage.setItem('employee_user', JSON.stringify(userProfile));
            }

            alert("Senha alterada com sucesso! Você será redirecionado.");
            redirectByRole(userProfile?.cargo, userProfile);

        } catch (err) {
            console.error("Erro ao trocar senha:", err);
            alert(`Erro ao trocar senha: ${err.message || "Erro desconhecido"}`);
            setError(err.message || "Erro ao trocar senha");
        } finally {
            setLoading(false);
        }
    };

    // Formulário de troca de senha (primeiro acesso)
    if (primeiroAcesso) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-green-50 to-blue-50 dark:from-gray-900 dark:to-gray-800 p-4">
                <Card className="w-full max-w-md shadow-xl">
                    <CardHeader className="text-center">
                        <div className="flex justify-center mb-4">
                            <div className="w-16 h-16 bg-green-100 dark:bg-green-900 rounded-full flex items-center justify-center">
                                <Store className="w-8 h-8 text-green-600 dark:text-green-400" />
                            </div>
                        </div>
                        <CardTitle className="text-2xl font-bold text-gray-900 dark:text-white">
                            Primeiro Acesso
                        </CardTitle>
                        <CardDescription className="text-gray-600 dark:text-gray-400">
                            Defina uma nova senha para continuar
                        </CardDescription>
                    </CardHeader>
                    <CardContent>
                        <form onSubmit={handleTrocarSenha} className="space-y-4">
                            {error && (
                                <Alert variant="destructive">
                                    <AlertDescription>{error}</AlertDescription>
                                </Alert>
                            )}

                            <div className="space-y-2">
                                <Label htmlFor="novaSenha">Nova Senha</Label>
                                <div className="relative">
                                    <Lock className="absolute left-3 top-3 h-4 w-4 text-gray-400" />
                                    <Input
                                        id="novaSenha"
                                        type={showPassword ? "text" : "password"}
                                        placeholder="Mín 6 chars, 1 maiúscula, 1 número"
                                        value={novaSenha}
                                        onChange={(e) => setNovaSenha(e.target.value)}
                                        className="pl-10 pr-10"
                                        required
                                        disabled={loading}
                                        minLength={6}
                                    />
                                    <button
                                        type="button"
                                        onClick={() => setShowPassword(!showPassword)}
                                        className="absolute right-3 top-3 text-gray-400 hover:text-gray-600"
                                    >
                                        {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                                    </button>
                                </div>
                            </div>

                            <div className="space-y-2">
                                <Label htmlFor="confirmarSenha">Confirmar Senha</Label>
                                <div className="relative">
                                    <Lock className="absolute left-3 top-3 h-4 w-4 text-gray-400" />
                                    <Input
                                        id="confirmarSenha"
                                        type={showPassword ? "text" : "password"}
                                        placeholder="Repita a senha"
                                        value={confirmarSenha}
                                        onChange={(e) => setConfirmarSenha(e.target.value)}
                                        className="pl-10"
                                        required
                                        disabled={loading}
                                    />
                                </div>
                            </div>

                            <Button
                                type="submit"
                                className="w-full bg-green-600 hover:bg-green-700 text-white"
                                disabled={loading}
                            >
                                {loading ? (
                                    <>
                                        <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                                        Salvando...
                                    </>
                                ) : (
                                    "Definir Nova Senha"
                                )}
                            </Button>
                        </form>
                    </CardContent>
                </Card>
            </div>
        );
    }

    // Formulário de login normal
    return (
        <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-green-50 to-blue-50 dark:from-gray-900 dark:to-gray-800 p-4">
            <Card className="w-full max-w-md shadow-xl">
                <CardHeader className="text-center">
                    <div className="flex justify-center mb-4">
                        <div className="w-16 h-16 bg-green-100 dark:bg-green-900 rounded-full flex items-center justify-center">
                            <Store className="w-8 h-8 text-green-600 dark:text-green-400" />
                        </div>
                    </div>
                    <CardTitle className="text-2xl font-bold text-gray-900 dark:text-white">
                        GestApp
                    </CardTitle>
                    <CardDescription className="text-gray-600 dark:text-gray-400">
                        Acesso para funcionários
                    </CardDescription>
                </CardHeader>
                <CardContent>
                    <form onSubmit={handleLogin} className="space-y-4">
                        {error && (
                            <Alert variant="destructive">
                                <AlertDescription>{error}</AlertDescription>
                            </Alert>
                        )}

                        <div className="space-y-2">
                            <Label htmlFor="identificacao">Matrícula ou Email</Label>
                            <div className="relative">
                                <IdCard className="absolute left-3 top-3 h-4 w-4 text-gray-400" />
                                <Input
                                    id="identificacao"
                                    type="text"
                                    placeholder="MP-VE0001 ou email@exemplo.com"
                                    value={identificacao}
                                    onChange={(e) => setIdentificacao(e.target.value)}
                                    className="pl-10"
                                    required
                                    disabled={loading}
                                />
                            </div>
                        </div>

                        <div className="space-y-2">
                            <Label htmlFor="senha">Senha</Label>
                            <div className="relative">
                                <Lock className="absolute left-3 top-3 h-4 w-4 text-gray-400" />
                                <Input
                                    id="senha"
                                    type={showPassword ? "text" : "password"}
                                    placeholder="Digite sua senha"
                                    value={senha}
                                    onChange={(e) => setSenha(e.target.value)}
                                    className="pl-10 pr-10"
                                    required
                                    disabled={loading}
                                />
                                <button
                                    type="button"
                                    onClick={() => setShowPassword(!showPassword)}
                                    className="absolute right-3 top-3 text-gray-400 hover:text-gray-600"
                                    disabled={loading}
                                >
                                    {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                                </button>
                            </div>
                        </div>

                        <Button
                            type="submit"
                            className="w-full bg-green-600 hover:bg-green-700 text-white"
                            disabled={loading}
                        >
                            {loading ? (
                                <>
                                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                                    Entrando...
                                </>
                            ) : (
                                "Entrar"
                            )}
                        </Button>
                    </form>

                    <div className="mt-4 flex flex-col items-center gap-1 border-t pt-4">
                        <Button
                            variant="outline"
                            className="w-full border-green-200 text-green-800 hover:bg-green-50"
                            onClick={() => navigate("/cadastro")}
                        >
                            Cadastre sua Empresa (15 Dias Grátis)
                        </Button>
                    </div>

                    <div className="mt-4 text-center text-xs text-gray-400">
                        Por Natan R.
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

import React, { useState } from "react";
import { base44 } from "@/api/base44Client";
import { useQuery } from "@tanstack/react-query";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Calendar, MapPin, Package, Clock, Truck, Wrench } from "lucide-react";
import DashboardLogistica from "@/components/logistica/DashboardLogistica";
import KanbanRotasSemanal from "@/components/logistica/KanbanRotasSemanal";
import MontagemInterna from "@/components/logistica/MontagemInterna";
import AguardandoLiberacao from "@/components/logistica/AguardandoLiberacao";
import MapaFrota from "@/components/logistica/MapaFrota";
import RoteirosFreota from "@/components/logistica/RoteirosFreota";
import ChatEquipe from "@/components/logistica/ChatEquipe";
import ConferenciaEntregas from "@/components/logistica/ConferenciaEntregas";
import { useTenant } from "@/contexts/TenantContext";
import { isRastreioEnabled } from "@/utils/deliveryConference";
import { isStatusCancelado } from "@/utils/vendaStatus";

export default function LogisticaSemanal() {
  const [tabAtiva, setTabAtiva] = useState("planejamento");
  const [subTabFrota, setSubTabFrota] = useState("roteiros");
  const { settings } = useTenant();
  const rastreioHabilitado = isRastreioEnabled(settings);

  const { data: entregas = [], isLoading } = useQuery({
    queryKey: ['entregas'],
    queryFn: () => base44.entities.Entrega.list(),
    refetchInterval: 5000
  });

  const { data: vendas = [] } = useQuery({
    queryKey: ['vendas'],
    queryFn: () => base44.entities.Venda.list(),
  });

  const { data: clientes = [] } = useQuery({
    queryKey: ['clientes'],
    queryFn: () => base44.entities.Cliente.list(),
    refetchInterval: 60000
  });

  // Query para caminhões com refresh a cada 5 segundos
  const { data: caminhoes = [] } = useQuery({
    queryKey: ['caminhoes-rastreamento'],
    queryFn: () => base44.entities.Caminhao.list(),
    refetchInterval: 5000 // Atualiza a cada 5 segundos
  });

  // Query para assistências técnicas que precisam de entrega
  const { data: assistencias = [] } = useQuery({
    queryKey: ['assistencias'],
    queryFn: () => base44.entities.AssistenciaTecnica.list('-created_at')
  });

  // Query para itens de montagem interna (para o badge)
  const { data: todasMontagens = [] } = useQuery({
    queryKey: ['montagens-internas-badge'],
    queryFn: () => base44.entities.MontagemItem.list()
  });

  // Filtrar assistências que precisam de entrega/visita (não concluídas/canceladas)
  const assistenciasPendentes = assistencias.filter(a =>
    a.status !== 'Concluída' &&
    !isStatusCancelado(a.status) &&
    (a.tipo === 'Devolução' || a.tipo === 'Troca' || a.tipo === 'Peça Faltante' || a.tipo === 'Visita Técnica' || a.tipo === 'Conserto')
  );

  const caminhoesAtivos = caminhoes.filter(c => c.status_rota === 'Em Trânsito');

  const hoje = new Date();
  const fimSemana = new Date(hoje);
  fimSemana.setDate(hoje.getDate() + 6);

  // 1. Pendentes (Triagem)
  const entregasPendentes = entregas.filter(e =>
    (e.status === 'Pendente' || !e.status) && !e.data_agendada
  );

  // 2. Aguardando Liberação (NOVA LISTA)
  const entregasAguardando = entregas.filter(e =>
    e.status === 'Aguardando Liberação'
  );

  // 3. Montagem (Filtrar itens pendentes de montagem interna)
  const montagensPendentes = todasMontagens.filter(m =>
    m.tipo_montagem === 'interna' && m.status !== 'concluida'
  );

  // 4. Semanal (Colunas)
  const colunasSemana = [];
  const diasSemana = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'];

  for (let i = 0; i < 7; i++) {
    const data = new Date();
    data.setDate(hoje.getDate() + i);
    const dataStr = data.toISOString().split('T')[0];
    const diaSemana = diasSemana[data.getDay()];

    colunasSemana.push({
      id: dataStr,
      titulo: i === 0 ? 'Hoje' : i === 1 ? 'Amanhã' : `${diaSemana} (${data.getDate()}/${data.getMonth() + 1})`,
      data: dataStr,
      // Usa startsWith para comparar datas (ignora timezone)
      entregas: (entregas || []).filter(e => e.data_agendada?.startsWith(dataStr) && e.status !== 'Entregue' && !isStatusCancelado(e.status) && e.status !== 'Aguardando Liberação'),
      isHoje: i === 0,
      dataFormatada: data.toLocaleDateString('pt-BR')
    });
  }

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-green-600" />
      </div>
    );
  }

  if (!rastreioHabilitado) {
    return (
      <div className="space-y-6">
        <div className="rounded-2xl border border-amber-200 bg-amber-50 p-5">
          <h1 className="text-2xl font-semibold text-slate-900">Conferência de Entregas</h1>
          <p className="mt-2 text-sm text-slate-600">
            O rastreamento está desabilitado para esta organização. Use esta tela para registrar entregas manualmente.
          </p>
        </div>
        <ConferenciaEntregas />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">Logística Semanal</h1>
          <p className="text-gray-600 dark:text-gray-400 mt-1">
            Planejamento e rastreamento de entregas
          </p>
        </div>
      </div>

      <Tabs value={tabAtiva} onValueChange={setTabAtiva} className="w-full">
        <TabsList className="grid w-full max-w-3xl grid-cols-5">
          <TabsTrigger value="planejamento" className="gap-2">
            <MapPin className="w-4 h-4" />
            Planejamento
          </TabsTrigger>
          <TabsTrigger value="frota" className="gap-2">
            <Truck className="w-4 h-4" />
            Frota ({caminhoesAtivos.length})
          </TabsTrigger>
          <TabsTrigger value="montagem" className="gap-2">
            <Calendar className="w-4 h-4" />
            Montagem ({montagensPendentes.length})
          </TabsTrigger>
          <TabsTrigger value="aguardando" className="gap-2">
            <Clock className="w-4 h-4" />
            Aguardando ({entregasAguardando.length})
          </TabsTrigger>
          <TabsTrigger value="dashboard" className="gap-2">
            <Package className="w-4 h-4" />
            Dashboard
          </TabsTrigger>
        </TabsList>

        <TabsContent value="planejamento" className="space-y-4 mt-6">
          <KanbanRotasSemanal
            entregas={entregas}
            vendas={vendas}
            entregasPendentes={entregasPendentes}
            colunasSemana={colunasSemana}
            caminhoes={caminhoes}
            assistencias={assistenciasPendentes}
          />
        </TabsContent>

        <TabsContent value="frota" className="mt-6">
          <div className="space-y-4">
            <Tabs value={subTabFrota} onValueChange={setSubTabFrota}>
              <TabsList className="grid w-full max-w-xs grid-cols-2">
                <TabsTrigger value="roteiros" className="gap-2">
                  <Truck className="w-4 h-4" />
                  Roteiros
                </TabsTrigger>
                <TabsTrigger value="mapa" className="gap-2">
                  <MapPin className="w-4 h-4" />
                  Mapa
                </TabsTrigger>
              </TabsList>
              <TabsContent value="roteiros" className="mt-4">
                <RoteirosFreota
                  entregas={entregas}
                  vendas={vendas}
                  caminhoes={caminhoes}
                  clientes={clientes}
                />
              </TabsContent>
              <TabsContent value="mapa" className="mt-4">
                <MapaFrota caminhoes={caminhoes} />
              </TabsContent>
            </Tabs>
          </div>
        </TabsContent>

        <TabsContent value="montagem" className="mt-6">
          <MontagemInterna />
        </TabsContent>

        <TabsContent value="aguardando" className="mt-6">
          <AguardandoLiberacao entregas={entregasAguardando} vendas={vendas} />
        </TabsContent>

        <TabsContent value="dashboard" className="space-y-4 mt-6">
          <DashboardLogistica entregas={entregas} colunas={colunasSemana} />
        </TabsContent>
      </Tabs>

      <ChatEquipe />
    </div>
  );
}

import React, { useState, useRef } from "react";
import { useNavigate } from "react-router-dom";
import FidelidadeRegras from "@/components/marketing/FidelidadeRegras";
