                  }}>
              <CardContent className="p-6 md:p-8 space-y-6">
                <div className="text-center mb-8 pb-6 border-b border-zinc-800">
                  <div className="w-16 h-16 mx-auto mb-4 rounded-full flex items-center justify-center"
                       style={{ 
