// Chaves para persistência
const PDV_STATE_KEY = 'pdv_state';
const OFFLINE_SALES_KEY = 'pending_sales_offline';

// --- FUNÇÕES AUXILIARES DE OFFLINE ---
const saveOfflineSale = (vendaData) => {
  try {
    const pending = JSON.parse(localStorage.getItem(OFFLINE_SALES_KEY) || '[]');
    const vendaOffline = { ...vendaData, offlineId: Date.now(), timestamp: new Date().toISOString() };
    pending.push(vendaOffline);
    localStorage.setItem(OFFLINE_SALES_KEY, JSON.stringify(pending));
    return true;
  } catch (e) {
    console.error("Erro ao salvar offline:", e);
    return false;
  }
};

const getOfflineSales = () => {
  try {
    return JSON.parse(localStorage.getItem(OFFLINE_SALES_KEY) || '[]');
  } catch (e) { return []; }
};

const removeOfflineSale = (offlineId) => {
  const pending = getOfflineSales().filter(s => s.offlineId !== offlineId);
  localStorage.setItem(OFFLINE_SALES_KEY, JSON.stringify(pending));
};

// --- FUNÇÃO PARA CONSTRUIR ENDEREÇO COMPLETO DE ENTREGA ---
const construirEnderecoEntrega = (cliente) => {
  if (!cliente) return "Endereço a definir";

  // Determinar qual endereço usar
  const usarMesmo = cliente.usar_mesmo_endereco !== false;

  const end = usarMesmo ? {
    rua: cliente.endereco,
    numero: cliente.numero,
    complemento: cliente.complemento,
    ponto_referencia: cliente.ponto_referencia,
    bairro: cliente.bairro,
    cidade: cliente.cidade,
    estado: cliente.estado
  } : {
    rua: cliente.endereco_entrega_rua,
    numero: cliente.endereco_entrega_numero,
    complemento: cliente.endereco_entrega_complemento,
    ponto_referencia: cliente.endereco_entrega_ponto_referencia,
    bairro: cliente.endereco_entrega_bairro,
    cidade: cliente.endereco_entrega_cidade,
    estado: cliente.endereco_entrega_estado
  };

  if (!end.rua) return "Endereço a definir";

  let endereco = `${formatarEndereco(end.rua)}, ${end.numero || 's/n'}`;
  if (end.complemento) endereco += ` - ${formatarEndereco(end.complemento)}`;
  if (end.bairro) endereco += ` - ${formatarEndereco(end.bairro)}`;
  if (end.cidade) endereco += `, ${formatarEndereco(end.cidade)}`;
  if (end.estado) endereco += `/${end.estado}`;
  if (end.ponto_referencia) endereco += ` (Ref: ${formatarEndereco(end.ponto_referencia)})`;

  return endereco;
};

const normalizarTexto = (valor = "") =>
  valor
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase();

const formatarPrazoEntrega = (prazo) => {
  if (!prazo) return "";
  return `${prazo.quantidade_dias} dias ${prazo.tipo_dias === 'uteis' ? 'úteis' : 'corridos'}`;
};

const encontrarPrazoConfigurado = (prazos, valorSelecionado) => {
  if (!valorSelecionado) return null;

  const valorNormalizado = normalizarTexto(valorSelecionado);

  return prazos.find((prazo) => {
    const label = formatarPrazoEntrega(prazo);
    return [prazo.identificador, prazo.titulo, label]
      .filter(Boolean)
      .some((valor) => normalizarTexto(valor) === valorNormalizado);
  }) || null;
};

const obterPrazoEncomenda = (prazos) => {
  if (!Array.isArray(prazos) || prazos.length === 0) return null;

  return prazos.find((prazo) => normalizarTexto(prazo.identificador) === 'encomenda')
    || prazos.find((prazo) => normalizarTexto(prazo.titulo).includes('encomenda'))
    || [...prazos].sort((a, b) => (b.quantidade_dias || 0) - (a.quantidade_dias || 0))[0]
    || null;
};

// --- FUNÇÃO PARA CRIAR LANÇAMENTOS FINANCEIROS AUTOMÁTICOS ---
const criarLancamentosVenda = async (vendaData, taxas, vendaId) => {
  try {
    const hoje = obterDataLocalString();

    // 1. Receita Bruta da Venda
    await base44.entities.LancamentoFinanceiro.create({
      descricao: `Venda #${vendaData.numero_pedido} - ${formatarNome(vendaData.cliente_nome)}`,
      valor: vendaData.valor_total + (vendaData.desconto || 0),
      tipo: 'receita',
      data_vencimento: hoje,
      data_lancamento: hoje,
      pago: vendaData.status === 'Pago',
      categoria_nome: 'Vendas',
      forma_pagamento: vendaData.pagamentos?.[0]?.forma_pagamento || 'Diversos',
      status: vendaData.status === 'Pago' ? 'Pago' : 'Pendente',
      observacao: `Pedido ${vendaData.numero_pedido}`,
      venda_id: vendaId, // Vinculado à venda
      numero_pedido: vendaData.numero_pedido
    });

    // 2. Lançamento de Desconto (se houver)
    if (vendaData.desconto > 0) {
      await base44.entities.LancamentoFinanceiro.create({
        descricao: `Desconto Venda #${vendaData.numero_pedido}${vendaData.cupom_codigo ? ` (Cupom: ${vendaData.cupom_codigo})` : ''}`,
        valor: -vendaData.desconto,
        tipo: 'despesa',
        data_vencimento: hoje,
        data_lancamento: hoje,
        pago: true,
        categoria_nome: 'Descontos Concedidos',
        status: 'Pago',
        observacao: vendaData.cupom_codigo ? `Cupom: ${vendaData.cupom_codigo}` : 'Desconto manual',
        venda_id: vendaId,
        numero_pedido: vendaData.numero_pedido
      });
    }

    // 2.b Lançamento de Acréscimo/Arredondamento (se desconto for negativo)
    if (vendaData.desconto < 0) {
      await base44.entities.LancamentoFinanceiro.create({
        descricao: `Arredondamento Venda #${vendaData.numero_pedido}`,
        valor: Math.abs(vendaData.desconto),
        tipo: 'receita',
        data_vencimento: hoje,
        data_lancamento: hoje,
        pago: vendaData.status === 'Pago',
        categoria_nome: 'Vendas',
        forma_pagamento: vendaData.pagamentos?.[0]?.forma_pagamento || 'Diversos',
        status: vendaData.status === 'Pago' ? 'Pago' : 'Pendente',
        observacao: 'Acréscimo de arredondamento no PDV',
        venda_id: vendaId,
        numero_pedido: vendaData.numero_pedido
      });
    }

    // 3. Lançamentos de Taxas de Cartão (para cada pagamento)
    for (const pagamento of vendaData.pagamentos || []) {
      const taxa = taxas.find(t => {
        if (pagamento.forma_pagamento === 'Crédito' && pagamento.parcelas > 1) {
          return t.forma_pagamento === 'Crédito Parcelado';
        }
        return t.forma_pagamento === pagamento.forma_pagamento ||
          t.forma_pagamento === pagamento.forma_pagamento.replace(' 1x', '');
      });

      if (taxa && taxa.valor > 0) {
        let valorTaxa = 0;
        if (taxa.tipo_taxa === 'porcentagem') {
          valorTaxa = (pagamento.valor * taxa.valor) / 100;
        } else {
          valorTaxa = taxa.valor;
        }

        if (valorTaxa > 0) {
          await base44.entities.LancamentoFinanceiro.create({
            descricao: `Taxa ${pagamento.forma_pagamento} - Venda #${vendaData.numero_pedido}`,
            valor: -valorTaxa,
            tipo: 'despesa',
            data_vencimento: hoje,
            data_lancamento: hoje,
            pago: true,
            categoria_nome: 'Taxas de Cartão',
            forma_pagamento: pagamento.forma_pagamento,
            status: 'Pago',
            observacao: `${taxa.valor}${taxa.tipo_taxa === 'porcentagem' ? '%' : ' R$'} sobre R$ ${pagamento.valor.toFixed(2)}`,
            venda_id: vendaId,
            numero_pedido: vendaData.numero_pedido
          });
        }
      }
    }

    console.log('✅ Lançamentos financeiros criados para venda', vendaData.numero_pedido);
  } catch (error) {
    console.error('❌ Erro ao criar lançamentos financeiros:', error);
  }
};

const medirDuracaoEtapa = async (nomeEtapa, operacao) => {
  const inicio = typeof performance !== 'undefined' ? performance.now() : Date.now();

  try {
    return await operacao();
  } finally {
    const fim = typeof performance !== 'undefined' ? performance.now() : Date.now();
    console.log(`[PDV] ${nomeEtapa} concluido em ${Math.round(fim - inicio)}ms`);
  }
};

const executarEmSegundoPlano = (nomeEtapa, operacao) => {
  Promise.resolve()
    .then(() => medirDuracaoEtapa(nomeEtapa, operacao))
    .catch((erro) => {
      console.error(`[PDV] Erro em ${nomeEtapa}:`, erro);
    });
};

const resolverFornecedorDoItem = (item, produtos = [], fornecedores = []) => {
  if (!item) return { fornecedor_id: null, fornecedor_nome: '' };

  const produtoCadastro = produtos.find((produto) => produto.id === item.produto_id);
  const fornecedorId = item.fornecedor_id || produtoCadastro?.fornecedor_id || null;

  let fornecedorNome = item.fornecedor_nome || produtoCadastro?.fornecedor_nome || '';

  if (!fornecedorNome && fornecedorId) {
    fornecedorNome = fornecedores.find((fornecedor) => fornecedor.id === fornecedorId)?.nome_empresa || '';
  }

  return {
    fornecedor_id: fornecedorId,
    fornecedor_nome: fornecedorNome
  };
};

const enriquecerItensEncomendaComFornecedor = (itens = [], produtos = [], fornecedores = []) =>
  itens.map((item) => {
    if (!item?.is_encomenda) return item;

    const fornecedorResolvido = resolverFornecedorDoItem(item, produtos, fornecedores);
    return {
      ...item,
      ...fornecedorResolvido
    };
  });

// RestricaoCheckbox imported from components/ui/restricao-checkbox

export default function PDV() {
  const { user } = useAuth();
  const { brandName, conferenciaCaixaEnabled, isPaidModuleActive } = useTenant();
  const queryClient = useQueryClient();
  const confirm = useConfirm();
  const { state: sidebarState, isMobile } = useSidebar();

  // Ref para prevenir duplo-clique (mutex)
  const isProcessingRef = useRef(false);

  // --- ESTADO ONLINE/OFFLINE ---
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [vendasPendentes, setVendasPendentes] = useState([]);
  const [syncing, setSyncing] = useState(false);
  const [prazosConfig, setPrazosConfig] = useState([]);


  useEffect(() => {
    carregarVendasPendentes();
    carregarPrazos();
  }, []);

  // --- Realtime para Solicitação de Preços ---
  useEffect(() => {
    if (!user) return;

    const channel = supabase
      .channel('pdv-solicitacoes-preco')
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'solicitacoes_preco',
          filter: `vendedor_id=eq.${user.id}`
        },
        (payload) => {
          const { new: novaSolicitacao } = payload;

          if (novaSolicitacao.status === 'aprovado' || novaSolicitacao.status === 'rejeitado') {
            setItens(prevItens => {
              const newItens = [...prevItens];
              const index = newItens.findIndex(item => item.solicitacao_preco_id === novaSolicitacao.id);

              if (index !== -1) {
                if (novaSolicitacao.status === 'aprovado') {
                  newItens[index].preco_unitario = Number(novaSolicitacao.preco_sugerido);
                  newItens[index].subtotal = Number(novaSolicitacao.preco_sugerido) * (newItens[index].quantidade || 1);
                  toast.success(`Preço aprovado para ${newItens[index].produto_nome}!`);
                } else if (novaSolicitacao.status === 'rejeitado') {
                  toast.error(`Preço sugerido para ${newItens[index].produto_nome} foi rejeitado.`);
                }
                newItens[index].status_solicitacao_preco = novaSolicitacao.status;
              }
              return newItens;
            });
          }
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [user]);

  useEffect(() => {
    const handleStatusChange = () => {
      const online = navigator.onLine;
      setIsOnline(online);
      if (online) carregarVendasPendentes();
    };

    window.addEventListener('online', handleStatusChange);
    window.addEventListener('offline', handleStatusChange);

    return () => {
      window.removeEventListener('online', handleStatusChange);
      window.removeEventListener('offline', handleStatusChange);
    };
  }, []);

  const carregarVendasPendentes = () => {
    const pendentes = getOfflineSales();
    setVendasPendentes(pendentes);
  };

  const carregarPrazos = async () => {
    try {
      const { data, error } = await supabase.from('prazos_entrega').select('*');
      if (error) throw error;
      setPrazosConfig(data || []);
    } catch (err) {
      console.error('Erro ao carregar prazos:', err);
    }
  };


  // Carregar estado inicial
  const getInitialState = () => {
    try {
      // 1. Tentar pegar estado de conversão de orçamento
      const orcamentoSaved = sessionStorage.getItem('moveispedroii_pdv_state');
      if (orcamentoSaved) {
        const parsed = JSON.parse(orcamentoSaved);
        // NÃO remover aqui — o componente pode re-montar (auth re-check)
        // A remoção será feita no useEffect após montagem estável

        return {
          etapa: 1, // Começa na primeira etapa para conferir itens
          clienteSelecionado: null, // Será buscado pelo ID logo em seguida através do useEffect
          itens: parsed.itens || [],
          pagamentos: parsed.pagamentos || [],
          configVenda: {
            data: obterDataLocalString(),
            loja: parsed.loja || "Centro",
            prazo: ""
          },
          desconto: parseFloat(parsed.desconto) || 0,
          observacoes: parsed.observacoes || "",
          pagamentoEntrega: {
            ativo: (parseFloat(parsed.valor_frete) > 0),
            valor: parseFloat(parsed.valor_frete) || 0,
            forma: ""
          },
          cidade: parsed.cidade || "",
          bairro: parsed.bairro || "",
          endereco: parsed.endereco || "",
          aguardandoLiberacao: false,
          _cliente_id_pendente: parsed.cliente_id, // Guardar para buscar o objeto cliente completo
          _orcamento_id: parsed.orcamento_id || null // Guardar para verificar duplicata
        };
      }

      // 2. Tentar pegar estado normal do PDV abandonado
      const saved = sessionStorage.getItem(PDV_STATE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        return {
          etapa: parsed.etapa || 1,
          clienteSelecionado: parsed.clienteSelecionado || null,
          itens: parsed.itens || [],
          pagamentos: parsed.pagamentos || [],
          configVenda: parsed.configVenda || {
            data: obterDataLocalString(),
            loja: "Centro",
            prazo: ""
          },
          desconto: parsed.desconto || 0,
          observacoes: parsed.observacoes || "",
          pagamentoEntrega: parsed.pagamentoEntrega || { ativo: false, valor: 0, forma: "" },
          selectedVendedorId: parsed.selectedVendedorId || null,
          aguardandoLiberacao: parsed.aguardandoLiberacao || false,
          dataLiberacao: parsed.dataLiberacao || "",
          cupomAplicado: parsed.cupomAplicado || null,
          tokenGerencial: parsed.tokenGerencial || null
        };
      }
    } catch (e) {
      console.error("Erro ao ler state", e);
    }
    return null;
  };

  const initialState = getInitialState();

  // --- ESTADOS DO PDV ---
  const [etapa, setEtapa] = useState((() => {
    // Força etapa 1 se vier de orçamento
    if (initialState?._cliente_id_pendente) return 1;
    return initialState?.etapa || 1;
  })());
  const [clienteSelecionado, setClienteSelecionado] = useState(initialState?.clienteSelecionado || null);
  const [itens, setItens] = useState(initialState?.itens || []);
  const [pagamentos, setPagamentos] = useState(initialState?.pagamentos || []);
  const [configVenda, setConfigVenda] = useState(initialState?.configVenda || {
    data: obterDataLocalString(),
    loja: "Centro",
    prazo: ""
  });
  const [desconto, setDesconto] = useState(initialState?.desconto || 0);
  const [observacoes, setObservacoes] = useState(initialState?.observacoes || "");
  const [pagamentoEntrega, setPagamentoEntrega] = useState(initialState?.pagamentoEntrega || { ativo: false, valor: 0, forma: "" });
  const [preferenciasEntrega, setPreferenciasEntrega] = useState(initialState?.preferenciasEntrega || { dias: [0, 1, 2, 3, 4, 5, 6], turnos: ['Manhã', 'Tarde', 'Comercial'], obs: "" });
  const [aguardandoLiberacao, setAguardandoLiberacao] = useState(initialState?.aguardandoLiberacao || false);
  const [dataLiberacao, setDataLiberacao] = useState(initialState?.dataLiberacao || "");
  const [selectedVendedorId, setSelectedVendedorId] = useState(initialState?.selectedVendedorId || user?.id || null);
  const [orcamentoOrigemId, setOrcamentoOrigemId] = useState(initialState?._orcamento_id || null);
  const [modalPreferenciasOpen, setModalPreferenciasOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [savingOrcamento, setSavingOrcamento] = useState(false);
  const [cupomAplicado, setCupomAplicado] = useState(initialState?.cupomAplicado || null);
  const [tokenGerencial, setTokenGerencial] = useState(initialState?.tokenGerencial || null);
  const [descontoMargemPercent, setDescontoMargemPercent] = useState(initialState?.descontoMargemPercent || 0);
  const [editingProdutoPDV, setEditingProdutoPDV] = useState(null);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [origemRetiradaModalOpen, setOrigemRetiradaModalOpen] = useState(false);
  const [produtoPendenteOrigem, setProdutoPendenteOrigem] = useState(null);
  const [opcoesOrigemPendente, setOpcoesOrigemPendente] = useState([]);
  const [origemSelecionadaCampo, setOrigemSelecionadaCampo] = useState("");

  // Flag para bloquear o auto-save enquanto dados do orçamento estão sendo carregados
  const isLoadingOrcamentoRef = useRef(false);
  const prevTodosItensSemEstoqueRef = useRef(false);

  // === DETECÇÃO DE ORÇAMENTO NO SESSIONSTORAGE ===
  // Este useEffect resolve o problema de SPA: quando o PDV já está montado
  // e o usuário navega de Orçamentos->PDV, o getInitialState não re-executa.
  // Por isso verificamos o sessionStorage a cada vez que o componente ganha foco.
  const carregarOrcamentoDoSessionStorage = async () => {
    const orcamentoSaved = sessionStorage.getItem('moveispedroii_pdv_state');
    if (!orcamentoSaved) return;

    // Bloquear auto-save para não sobrescrever com estado vazio
    isLoadingOrcamentoRef.current = true;

    try {
      const parsed = JSON.parse(orcamentoSaved);
      sessionStorage.removeItem('moveispedroii_pdv_state');

      console.log("📦 Carregando orçamento no PDV:", parsed);

      // Definir todos os estados de uma vez
      setItens(parsed.itens || []);
      setPagamentos(parsed.pagamentos || []);
      setDesconto(parseFloat(parsed.desconto) || 0);
      setObservacoes(parsed.observacoes || "");
      setEtapa(1);
      if (parsed.loja) {
        setConfigVenda(prev => ({ ...prev, loja: parsed.loja }));
      }
      setPagamentoEntrega({
        ativo: (parseFloat(parsed.valor_frete) > 0),
        valor: parseFloat(parsed.valor_frete) || 0,
        forma: ""
      });
      setAguardandoLiberacao(false);
      setDataLiberacao("");
      setCupomAplicado(null);
      setTokenGerencial(null);
      setOrcamentoOrigemId(parsed.orcamento_id || null);

      // Buscar o cliente completo pelo ID
      if (parsed.cliente_id) {
        try {
          const clienteList = await base44.entities.Cliente.list();
          const clienteObj = clienteList.find(c => c.id === parsed.cliente_id);
          if (clienteObj) {
            const clienteFinal = {
              ...clienteObj,
              cidade: parsed.cidade || clienteObj.cidade,
              bairro: parsed.bairro || clienteObj.bairro,
              endereco: parsed.endereco || clienteObj.endereco
            };
            setClienteSelecionado(clienteFinal);
          }
        } catch (e) {
          console.error("Erro ao carregar cliente do orçamento:", e);
        }
      }

      toast.success("Orçamento carregado no PDV!");
    } catch (e) {
      console.error("Erro ao parsear orçamento do sessionStorage:", e);
    } finally {
      // Liberar auto-save após um tick para os estados terem sido aplicados
      setTimeout(() => { isLoadingOrcamentoRef.current = false; }, 500);
    }
  };

  // Roda na montagem E quando o componente recebe sinal de orçamento
  useEffect(() => {
    // Limpar o sessionStorage de orçamento após montagem estável
    // (evita que o double-mount do auth consuma e perca os dados)
    const cleanupTimer = setTimeout(() => {
      sessionStorage.removeItem('moveispedroii_pdv_state');
    }, 1000);

    carregarOrcamentoDoSessionStorage();

    const handleFocus = () => carregarOrcamentoDoSessionStorage();
    window.addEventListener('focus', handleFocus);

    // Evento customizado disparado por Orcamentos.jsx/OrcamentoCard.jsx
    const handleOrcamentoEvent = () => {
      // Pequeno delay para garantir que o sessionStorage já foi escrito
      setTimeout(() => carregarOrcamentoDoSessionStorage(), 100);
    };
    window.addEventListener('orcamento-para-pdv', handleOrcamentoEvent);

    // Também verifica quando a aba/visibilidade muda
    const handleVisibility = () => {
      if (!document.hidden) carregarOrcamentoDoSessionStorage();
    };
    document.addEventListener('visibilitychange', handleVisibility);

    return () => {
      clearTimeout(cleanupTimer);
      window.removeEventListener('focus', handleFocus);
      window.removeEventListener('orcamento-para-pdv', handleOrcamentoEvent);
      document.removeEventListener('visibilitychange', handleVisibility);
    };
  }, []);

  // Busca o cliente completo caso tenha vindo apenas o ID do orçamento (montagem inicial)
  useEffect(() => {
    if (initialState?._cliente_id_pendente) {
      const carregarClienteOrcamento = async () => {
        try {
          const clienteList = await base44.entities.Cliente.list();
          const clienteObj = clienteList.find(c => c.id === initialState._cliente_id_pendente);
          if (clienteObj) {
            setClienteSelecionado(clienteObj);
          }
        } catch (e) {
          console.error("Erro ao carregar cliente do orçamento: ", e);
        }
      };
      carregarClienteOrcamento();
    }
  }, []);

  useEffect(() => {
    // Não salvar se estamos no meio do carregamento de um orçamento (race condition)
    if (isLoadingOrcamentoRef.current) return;
    const state = { etapa, clienteSelecionado, itens, pagamentos, configVenda, desconto, observacoes, pagamentoEntrega, preferenciasEntrega, aguardandoLiberacao, dataLiberacao, selectedVendedorId, cupomAplicado, tokenGerencial, descontoMargemPercent };
    sessionStorage.setItem(PDV_STATE_KEY, JSON.stringify(state));
  }, [etapa, clienteSelecionado, itens, pagamentos, configVenda, desconto, observacoes, pagamentoEntrega, preferenciasEntrega, aguardandoLiberacao, dataLiberacao, selectedVendedorId, cupomAplicado, tokenGerencial, descontoMargemPercent]);

  useEffect(() => {
    if (user && !initialState) {
      // Tenta setar a loja do usuário como padrão. 
      // O texto "Centro" é apenas o último fallback caso o usuário não tenha loja definida.
      const defaultLoja = user.loja || "Centro";
      setConfigVenda(prev => ({ ...prev, loja: defaultLoja }));
    }
  }, [user]);

  useEffect(() => {
    if (user?.id && !selectedVendedorId) {
      setSelectedVendedorId(user.id);
    }
  }, [user, selectedVendedorId]);

  // --- REALTIME UPDATES: PRODUTOS ---
  useEffect(() => {
    // Só conecta se estiver online
    if (!isOnline) return;

    console.log("🔌 Conectando ao Realtime de Produtos...");

    const channel = supabase
      .channel('pdv-produtos-changes')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'produtos' },
        (payload) => {
          const newProduto = payload.new;

          if (payload.eventType === 'DELETE') {
            queryClient.invalidateQueries({ queryKey: ['produtos'] });
            return;
          }

          console.log("Produto atualizado em realtime:", newProduto?.nome || payload.eventType);

          // 1. Atualiza o cache da lista de produtos (para a busca encontrar o preço novo)
          queryClient.invalidateQueries({ queryKey: ['produtos'] });

          // 2. Atualiza os itens que já estão no carrinho
          setItens(prevItens => {
            const hasItem = prevItens.some(i => i.produto_id == newProduto.id); // Loose equality for ID
            if (!hasItem) return prevItens;

            return prevItens.map(item => {
              if (item.produto_id == newProduto.id) {
                const novoPreco = parseFloat(newProduto.preco_venda);
                const precoOriginalBase = item.preco_original ?? item.preco_unitario;

                // Só notifica/atualiza se o preço no banco realmente mudou
                if (precoOriginalBase !== novoPreco) {
                  toast.info(`Preço atualizado: ${newProduto.nome} agora é R$ ${novoPreco.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`);

                  const percent = item.desconto_item_percent || 0;
                  const novoPrecoUnit = percent > 0 ? novoPreco * (1 - percent / 100) : novoPreco;
                  const novoDescontoValor = percent > 0 ? novoPreco * (percent / 100) * (item.quantidade || 1) : 0;

                  return {
                    ...item,
                    preco_original: percent > 0 ? novoPreco : undefined,
                    preco_unitario: novoPrecoUnit,
                    desconto_item_valor: novoDescontoValor,
                    subtotal: (item.quantidade || 1) * novoPrecoUnit
                  };
                }
              }
              return item;
            });
          });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [isOnline, queryClient]);

  const { data: produtos = [] } = useQuery({
    queryKey: ['produtos'],
    queryFn: () => base44.entities.Produto.list()
  });

  const { data: lojas = [] } = useQuery({
    queryKey: ['lojas'],
    queryFn: () => base44.entities.Loja.list()
  });

  const { data: descontoExcecoes = [] } = useQuery({
    queryKey: ['desconto_produto_excecoes'],
    queryFn: () => base44.entities.DescontoProdutoExcecao.list(),
    enabled: isOnline
  });

  const { data: clientes = [] } = useQuery({
    queryKey: ['clientes'],
    queryFn: () => base44.entities.Cliente.list()
  });

  const { data: vendas = [] } = useQuery({
    queryKey: ['vendas'],
    queryFn: () => base44.entities.Venda.list('-data_venda', 500),
    enabled: isOnline
  });

  const { data: taxasFinanceiras = [] } = useQuery({
    queryKey: ['configuracao_taxas'],
    queryFn: () => base44.entities.ConfiguracaoTaxa.list(),
    enabled: isOnline
  });

  // Buscar fornecedores (para validação de encomendas)
  const { data: fornecedores = [] } = useQuery({
    queryKey: ['fornecedores'],
    queryFn: () => base44.entities.Fornecedor.list(),
    enabled: isOnline
  });

  const { data: users = [] } = useQuery({
    queryKey: ['users_list'],
    queryFn: () => base44.entities.User.list(),
    enabled: isOnline
  });

  const hasMasterAccess = String(user?.cargo || '').toLowerCase().includes('admin') || String(user?.cargo || '').toLowerCase().includes('master');
  const vendedoresDisponiveis = (users || []).filter((u) => !!u?.id);
  const vendedorSelecionado = vendedoresDisponiveis.find((u) => u.id === selectedVendedorId) || null;
  const vendedorFinal = {
    id: hasMasterAccess ? (vendedorSelecionado?.id || user?.id) : user?.id,
    nome: hasMasterAccess
      ? (vendedorSelecionado?.full_name || vendedorSelecionado?.email || user?.full_name || user?.email)
      : (user?.full_name || user?.email)
  };

  const montarAtualizacaoEstoqueProduto = (produto, quantidadeLocalAtualizada, lojaNome) => {
    const campoLoja = resolveStockField(lojaNome);

    if (!campoLoja) {
      throw new Error('Nao foi possivel determinar a unidade de estoque do PDV.');
    }

    const produtoAtualizado = {
      ...produto,
      [campoLoja]: Number(quantidadeLocalAtualizada || 0)
    };

    return {
      [campoLoja]: produtoAtualizado[campoLoja],
      quantidade_estoque: getProductTotalStock(produtoAtualizado)
    };
  };

  const montarAtualizacaoEstoqueProdutoPorCampo = (produto, quantidadeLocalAtualizada, campoEstoque) => {
    if (!campoEstoque) {
      throw new Error('Nao foi possivel determinar a origem de estoque do item.');
    }

    const produtoAtualizado = {
      ...produto,
      [campoEstoque]: Number(quantidadeLocalAtualizada || 0)
    };

    return {
      [campoEstoque]: produtoAtualizado[campoEstoque],
      quantidade_estoque: getProductTotalStock(produtoAtualizado)
    };
  };

  const getOrigensDisponiveisProduto = (produto, options = {}) => {
    const includeZero = options?.includeZero === true;
    if (!produto) return [];

    const opcoesPorCampo = new Map();

    for (const loja of (lojas || [])) {
      if (!loja?.nome) continue;
      const campoLoja = resolveStockField(loja.nome);
      if (!campoLoja) continue;
      if (!opcoesPorCampo.has(campoLoja)) {
        opcoesPorCampo.set(campoLoja, loja.nome);
      }
    }

    if (!opcoesPorCampo.has('estoque_cd')) {
      opcoesPorCampo.set('estoque_cd', 'CD');
    }

    return Array.from(opcoesPorCampo.entries())
      .map(([campo, nome]) => ({
        campo,
        nome,
        quantidade: Number(produto?.[campo] || 0)
      }))
      .filter((opcao) => includeZero || opcao.quantidade > 0)
      .sort((a, b) => {
        if (a.campo === 'estoque_cd' && b.campo !== 'estoque_cd') return -1;
        if (b.campo === 'estoque_cd' && a.campo !== 'estoque_cd') return 1;
        return a.nome.localeCompare(b.nome, 'pt-BR');
      });
  };

  const criarVendaMutation = useMutation({
    mutationFn: (data) => base44.entities.Venda.create(data)
  });

  // Margem negociável da loja ativa
  const margemNegociavel = useMemo(() => {
    const lojaObj = (lojas || []).find(l => l.nome === configVenda.loja);
    return parseFloat(lojaObj?.margem_negociavel || 0);
  }, [lojas, configVenda.loja]);

  // Configurações de desconto por produto da loja ativa
  const lojaAtivaPDV = useMemo(() => (lojas || []).find(l => l.nome && configVenda.loja && String(l.nome).trim().toLowerCase() === String(configVenda.loja).trim().toLowerCase()), [lojas, configVenda.loja]);
  const descontoProdutoAtivo = lojaAtivaPDV?.desconto_produto_ativo === true || String(lojaAtivaPDV?.desconto_produto_ativo) === 'true';
  const descontoMaxProduto = parseFloat(lojaAtivaPDV?.desconto_produto_max_percent || 0);

  // Exceções da loja ativa (produto_id ou categoria bloqueados)
  const excecoesDaLoja = useMemo(() => {
    if (!lojaAtivaPDV?.id) return [];
    return (descontoExcecoes || []).filter(e => e.loja_id === lojaAtivaPDV.id);
  }, [descontoExcecoes, lojaAtivaPDV?.id]);

  // Retorna true se o produto pode receber desconto individual no carrinho
  const isProdutoComDesconto = useMemo(() => {
    return (item) => {
      if (!descontoProdutoAtivo || descontoMaxProduto <= 0) return false;
      const excecoes = excecoesDaLoja;
      const bloqueadoPorProduto = excecoes.some(e => e.produto_id && e.produto_id === item.produto_id);
      const bloqueadoPorCategoria = excecoes.some(e => {
        if (!e.categoria) return false;
        const prod = produtos.find(p => p.id === item.produto_id);
        const itemCat = item.categoria || prod?.categoria;
        return itemCat && String(e.categoria).toLowerCase() === String(itemCat).toLowerCase();
      });
      return !bloqueadoPorProduto && !bloqueadoPorCategoria;
    };
  }, [descontoProdutoAtivo, descontoMaxProduto, excecoesDaLoja, produtos]);

  const criarOrcamentoMutation = useMutation({
    mutationFn: (data) => base44.entities.Orcamento.create(data),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['orcamentos'] })
  });

  const sincronizarVendas = async () => {
    if (!isOnline || vendasPendentes.length === 0) return;

    const confirmed = await confirm({
      title: "Sincronizar Vendas",
      message: `Existem ${vendasPendentes.length} vendas salvas offline. Deseja sincronizar agora?`,
      confirmText: "Sincronizar"
    });
    if (!confirmed) return;

    setSyncing(true);
    let sucessos = 0;

    for (const vendaOffline of vendasPendentes) {
      try {
        const { offlineId, ...dadosVenda } = vendaOffline;
        delete dadosVenda.timestamp; // campo de metadado offline, não é campo da entidade Venda
        const vendaCriada = await criarVendaMutation.mutateAsync(dadosVenda);

        const itensVenda = dadosVenda.itens || [];
        for (const item of itensVenda) {
          if (!item.produto_id) continue;

          const produtoAtual = await base44.entities.Produto.getById(item.produto_id);
          if (!produtoAtual) continue;

          const campoOrigem = item?.origem_estoque_campo || resolveStockField(dadosVenda.loja);
          const estoqueLocalAposVenda = (produtoAtual[campoOrigem] || 0) - (item.quantidade || 0);
          const updates = montarAtualizacaoEstoqueProdutoPorCampo(produtoAtual, estoqueLocalAposVenda, campoOrigem);

          await base44.entities.Produto.update(item.produto_id, updates);
        }

        const itensEncomendaComFornecedor = enriquecerItensEncomendaComFornecedor(itensVenda, produtos, fornecedores);
        const itensEncomenda = itensEncomendaComFornecedor.filter(i => i.is_encomenda);
        const itensEncomendaInvalidos = itensEncomenda.filter(i => !i.fornecedor_id);
        const itensEncomendaValidos = itensEncomenda.filter(i => i.fornecedor_id);

        if (itensEncomendaInvalidos.length > 0) {
          console.warn('[PDV] Encomendas offline sem fornecedor foram ignoradas na sincronizacao', itensEncomendaInvalidos);
          toast.warning(`⚠️ ${itensEncomendaInvalidos.length} encomenda(s) sem fornecedor nao foram enviadas ao Compras. Conclua o cadastro dos produtos com fornecedor.`);
        }

        for (const item of itensEncomendaValidos) {
          await base44.entities.SolicitacaoEncomenda.create({
            venda_id: vendaCriada.id,
            produto_id: item.produto_id,
            produto_nome: item.produto_nome,
            fornecedor_id: item.fornecedor_id || null,
            fornecedor_nome: item.fornecedor_nome || '',
            quantidade: item.quantidade,
            cliente_nome: dadosVenda.cliente_nome,
            numero_pedido: dadosVenda.numero_pedido,
            loja: dadosVenda.loja,
            loja_id: dadosVenda.loja_id || null,
            vendedor_id: dadosVenda.responsavel_id || user?.id || null,
            vendedor_nome: dadosVenda.responsavel_nome || user?.full_name || user?.email || null,
            status: 'pendente'
          });
        }

        // Tenta enviar mensagem do robô também na sincronização
        if (dadosVenda.cliente_telefone) {
          fetch(`${ZAP_API_URL}/mensagem-pos-venda`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', ...(_BOT_API_KEY ? { 'x-bot-api-key': _BOT_API_KEY } : {}) },
            body: JSON.stringify({
              telefone: dadosVenda.cliente_telefone,
              nome: dadosVenda.cliente_nome,
              pedido: dadosVenda.numero_pedido,
              prazo: dadosVenda.prazo_entrega
            })
          }).catch(e => console.log("Robô offline na sincronização"));
        }

        removeOfflineSale(offlineId);
        sucessos++;
      } catch (erro) {
        console.error("Erro ao sincronizar venda:", erro);
      }
    }

    setSyncing(false);
    carregarVendasPendentes();
    if (sucessos > 0) toast.success(`${sucessos} vendas sincronizadas com sucesso!`);
  };

  const adicionarProdutoAoCarrinho = (produto, origemEstoque = null) => {
    const fornecedorResolvido = resolverFornecedorDoItem({
      produto_id: produto.id,
      fornecedor_id: produto.fornecedor_id,
      fornecedor_nome: produto.fornecedor_nome
    }, produtos, fornecedores);

    setItens(prev => {
      const exists = prev.findIndex(i => i.produto_id === produto.id);

      if (exists >= 0) {
        const newItens = [...prev];
        newItens[exists].quantidade += 1;
        newItens[exists].subtotal = newItens[exists].quantidade * newItens[exists].preco_unitario;
        newItens[exists].fornecedor_id = newItens[exists].fornecedor_id || fornecedorResolvido.fornecedor_id;
        newItens[exists].fornecedor_nome = newItens[exists].fornecedor_nome || fornecedorResolvido.fornecedor_nome;
        newItens[exists].cor = newItens[exists].cor || produto.cor || '';
        newItens[exists].tecido = newItens[exists].tecido || produto.tecido || produto.material || '';
        newItens[exists].tamanho = newItens[exists].tamanho || produto.tamanho || '';
        newItens[exists].fabricante = newItens[exists].fabricante || produto.fabricante || produto.marca || fornecedorResolvido.fornecedor_nome || '';
        if (origemEstoque?.campo && !newItens[exists].origem_estoque_campo) {
          newItens[exists].origem_estoque_campo = origemEstoque.campo;
          newItens[exists].origem_estoque_nome = origemEstoque.nome;
        }
        return newItens;
      }

      return [...prev, {
        produto_id: produto.id,
        produto_nome: buildProductDisplayName(produto.nome, produto.modelo_referencia),
        quantidade: 1,
        preco_unitario: produto.preco_venda,
        subtotal: produto.preco_venda,
        fotos: produto.fotos || [], // Add fotos
        tipo_entrega: null, // null | 'entrega' | 'retira'
        tipo_montagem: null, // null | 'montado' | 'montagem_cliente'
        tipo_entrega_padrao: produto.tipo_entrega_padrao, // Salvar para usar no carrinho
        tipo_montagem_padrao: produto.tipo_montagem_padrao || null,
        tipo_montagem_padrao_por: produto.tipo_montagem_padrao_por || null,
        tipo_montagem_padrao_em: produto.tipo_montagem_padrao_em || null,
        tipo_montagem_padrao_via: produto.tipo_montagem_padrao_via || null,
        origem: produto.origem, // Store origin used for delivery flagging
        // Preserve metadata for provisional products
        is_solicitacao: produto.is_solicitacao,
        solicitacao_id: produto.solicitacao_id,
        detalhes_solicitacao: produto.detalhes_solicitacao,
        // Encomenda flag
        is_encomenda: produto.is_encomenda || false,
        origem_estoque_campo: origemEstoque?.campo || null,
        origem_estoque_nome: origemEstoque?.nome || null,
        fornecedor_id: fornecedorResolvido.fornecedor_id,
        fornecedor_nome: fornecedorResolvido.fornecedor_nome,
        cor: produto.cor || '',
        tecido: produto.tecido || produto.material || '',
        tamanho: produto.tamanho || '',
        fabricante: produto.fabricante || produto.marca || fornecedorResolvido.fornecedor_nome || '',
        // Variante (novo padrão Base + Variantes)
        variante_id: produto.variante_id || null,
        variante_sku: produto.variante_sku || null
      }];
    });
  };

  // MODIFIED: Accepts ID (string) OR Full Product Object (provisional)
  const handleSelectProduto = (produtoOrId) => {
    let produto = null;

    if (typeof produtoOrId === 'string' || typeof produtoOrId === 'number') {
      produto = produtos.find(p => p.id === produtoOrId);
    } else if (typeof produtoOrId === 'object') {
      produto = produtoOrId; // Provisional product passed directly
    }

    if (!produto) return;

    const itemExistente = itens.find((item) => item.produto_id === produto.id);
    if (itemExistente?.origem_estoque_campo) {
      adicionarProdutoAoCarrinho(produto, {
        campo: itemExistente.origem_estoque_campo,
        nome: itemExistente.origem_estoque_nome || configVenda.loja
      });
      return;
    }

    const opcoesOrigem = getOrigensDisponiveisProduto(produto);
    const opcaoCd = opcoesOrigem.find((opcao) => opcao.campo === 'estoque_cd');

    if (opcoesOrigem.length > 1) {
      setProdutoPendenteOrigem(produto);
      setOpcoesOrigemPendente(opcoesOrigem);
      setOrigemSelecionadaCampo(opcaoCd?.campo || opcoesOrigem[0]?.campo || "");
      setOrigemRetiradaModalOpen(true);
      return;
    }

    const origemAutomatica = opcoesOrigem[0] || null;
    adicionarProdutoAoCarrinho(produto, origemAutomatica);
  };

  const confirmarOrigemRetiradaItem = () => {
    if (!produtoPendenteOrigem) return;

    const origemSelecionada = opcoesOrigemPendente.find((opcao) => opcao.campo === origemSelecionadaCampo) || null;
    adicionarProdutoAoCarrinho(produtoPendenteOrigem, origemSelecionada);

    setOrigemRetiradaModalOpen(false);
    setProdutoPendenteOrigem(null);
    setOpcoesOrigemPendente([]);
    setOrigemSelecionadaCampo("");
  };

  const cancelarOrigemRetiradaItem = () => {
    setOrigemRetiradaModalOpen(false);
    setProdutoPendenteOrigem(null);
    setOpcoesOrigemPendente([]);
    setOrigemSelecionadaCampo("");
  };

  const handleVincularImagem = async (index, imageUrl) => {
    try {
      const item = itens[index];
      const produtoId = item.produto_id || item.id;

      // Update in database
      await base44.entities.Produto.update(produtoId, {
        fotos: [imageUrl]
      });

      // Update in cart immediately
      setItens(prev => {
        const newItens = [...prev];
        newItens[index].fotos = [imageUrl];
        return newItens;
      });

      // Update react query cache for the product search
      queryClient.invalidateQueries(['produtos']);

      return true;
    } catch (error) {
      console.error('Erro ao vincular imagem:', error);
      throw error;
    }
  };

  const handleEditProdutoPDV = (item) => {
    // Buscar o produto real da lista para ter todos os metadados (categoria, dimensões, etc)
    const produtoCompleto = produtos.find(p => p.id === item.produto_id);
    if (!produtoCompleto) {
      toast.error("Não foi possível encontrar os dados completos do produto.");
      return;
    }
    setEditingProdutoPDV(produtoCompleto);
    setIsEditModalOpen(true);
  };

  const handleSaveEditProdutoPDV = async (updatedData) => {
    try {
      // 1. Determine what changed for the Audit Log (before applying the update)
      const changes = {};
      Object.keys(updatedData).forEach(key => {
        // Ignorar o array "variacoes" se for muito complexo ou faça stringify
        if (JSON.stringify(updatedData[key]) !== JSON.stringify(editingProdutoPDV[key])) {
          changes[key] = {
            before: editingProdutoPDV[key],
            after: updatedData[key]
          };
        }
      });

      // 2. Update the product in the database
      await base44.entities.Produto.update(editingProdutoPDV.id, updatedData);

      // 3. Register Audit Log if there were changes
      if (Object.keys(changes).length > 0 && user) {
        try {
          await base44.entities.AuditLog.create({
            user_email: user.email,
            user_name: user.full_name || user.nome,
            user_cargo: user.cargo,
            action: 'UPDATE',
            entity_type: 'Produto',
            entity_id: editingProdutoPDV.id,
            entity_description: `Produto Atualizado via PDV (ID: ${editingProdutoPDV.id}) - ${updatedData.nome || editingProdutoPDV.nome}`,
            detalhes: {
              changes,
              source: 'PDV',
            },
            timestamp: new Date().toISOString()
          });
        } catch (logErr) {
          console.error("Failed to write audit log:", logErr);
        }
      }

      // 4. Update cart items if the edited product is already in the cart
      setItens(prevItens =>
        prevItens.map(item => {
          if (item.produto_id === editingProdutoPDV.id) {
            const precoEditado = Number(updatedData.preco_venda);
            const precoUnitarioAtualizado = Number.isFinite(precoEditado)
              ? precoEditado
              : Number(item.preco_unitario || 0);
            const quantidadeItem = Number(item.quantidade || 0);

            return {
              ...item,
              produto_nome: buildProductDisplayName(updatedData.nome || item.produto_nome, updatedData.modelo_referencia),
              preco_unitario: precoUnitarioAtualizado,
              subtotal: quantidadeItem * precoUnitarioAtualizado
            };
          }
          return item;
        })
      );

      // 5. Invalidate queries and close modal
      queryClient.invalidateQueries({ queryKey: ['produtos'] });
      setIsEditModalOpen(false);
      setEditingProdutoPDV(null);
      toast.success("Produto atualizado com sucesso!");
    } catch (error) {
      console.error("Error saving product from PDV:", error);
      const errorMessage = error?.message
        ? error.message
        : typeof error === 'string'
          ? error
          : JSON.stringify(error);
      toast.error("Erro ao atualizar o produto: " + errorMessage);
    }
  };

  const handleAtualizarItem = (index, updates) => {
    setItens(prev => prev.map((item, i) => i === index ? { ...item, ...updates } : item));
  };

  const handleAtualizarProdutoId = (index, newProdutoId) => {
    setItens(prev => prev.map((item, i) => i === index ? { ...item, produto_id: newProdutoId } : item));
  };

  const handleAtualizarEstoque = async (index, novaQuantidade) => {
    try {
      const item = itens[index];
      const produtoId = item.produto_id || item.id;
      const produtoAtual = produtos.find(produto => produto.id === produtoId);

      if (!produtoAtual) {
        throw new Error('Produto nao encontrado para atualizar o estoque.');
      }

      const campoOrigem = item?.origem_estoque_campo || resolveStockField(configVenda.loja);
      const updates = montarAtualizacaoEstoqueProdutoPorCampo(produtoAtual, novaQuantidade, campoOrigem);

      await base44.entities.Produto.update(produtoId, updates);

      // Atualizar o item do carrinho com informações de quem e quando atualizou
      setItens(prev => {
        const newItens = [...prev];
        newItens[index].estoque_atualizado_por = user?.full_name || user?.nome || 'Desconhecido';
        newItens[index].estoque_atualizado_em = new Date().toISOString();
        return newItens;
      });

      // Atualizar imediatamente os dados de produtos para desbloquear o PDV sem recarregar a pagina.
      await queryClient.invalidateQueries({ queryKey: ['produtos'], refetchType: 'active' });

      return true;
    } catch (error) {
      console.error('Erro ao atualizar estoque:', error);
      throw error;
    }
  };

  const handleToggleEntrega = (index, tipo) => {
    setItens(prev => {
      const newItens = [...prev];
      newItens[index].tipo_entrega = tipo;
      // Se mudar para 'retira', limpa a seleção de montagem
      if (tipo === 'retira') {
        newItens[index].tipo_montagem = null;
      }
      // Se mudar para 'entrega'
      if (tipo === 'entrega') {
        if (newItens[index].tipo_entrega_padrao === 'nao_requer_montagem') {
          newItens[index].tipo_montagem = null; // não precisa de montagem
        } else if (newItens[index].tipo_montagem_padrao) {
          // Preenche com o padrão se existir
          newItens[index].tipo_montagem = newItens[index].tipo_montagem_padrao;
        }
      }
      return newItens;
    });
  };

  const handleToggleMontagem = (index, tipo) => {
    setItens(prev => {
      const newItens = [...prev];
      newItens[index].tipo_montagem = tipo;
      return newItens;
    });
  };

  const handleRemoveItem = (index) => {
    setItens(prev => prev.filter((_, i) => i !== index));
  };

  const handleAtualizarQuantidadeItem = (index, novaQuantidade) => {
    const quantidadeSegura = parseInt(novaQuantidade, 10);
    if (!Number.isFinite(quantidadeSegura) || quantidadeSegura < 1) return;

    setItens(prev => {
      const newItens = [...prev];
      const itemAtual = newItens[index];
      if (!itemAtual) return prev;

      newItens[index] = {
        ...itemAtual,
        quantidade: quantidadeSegura,
        subtotal: quantidadeSegura * (itemAtual.preco_unitario || 0)
      };

      return newItens;
    });
  };

  const handleSetMontagemPadrao = async (index, produtoId, tipoMontagem) => {
    try {
      const now = new Date().toISOString();
      const payload = {
        tipo_montagem_padrao: tipoMontagem,
        tipo_montagem_padrao_por: user?.full_name || 'Usuário Desconhecido',
        tipo_montagem_padrao_em: now,
        tipo_montagem_padrao_via: 'PDV'
      };

      // 1. Atualizar no banco de dados
      const { error } = await supabase
        .from('produtos')
        .update(payload)
        .eq('id', produtoId);

      if (error) throw error;

      // 2. Atualizar o item no carrinho atual para que o botão desapareça
      setItens(prev => {
        const newItens = [...prev];
        newItens[index].tipo_montagem_padrao = tipoMontagem;
        newItens[index].tipo_montagem_padrao_por = payload.tipo_montagem_padrao_por;
        newItens[index].tipo_montagem_padrao_em = payload.tipo_montagem_padrao_em;
        newItens[index].tipo_montagem_padrao_via = payload.tipo_montagem_padrao_via;
        return newItens;
      });

      // 3. Atualizar o cache de produtos para próximas adições
      queryClient.setQueryData(['produtos'], (oldData) => {
        if (!oldData) return oldData;
        return oldData.map(p =>
          p.id === produtoId ? { ...p, ...payload } : p
        );
      });

      toast.success(`Definido como padrão com sucesso!`);
    } catch (err) {
      console.error('Erro ao salvar padrão de montagem:', err);
      toast.error('Erro ao salvar preferência. Tente novamente.');
    }
  };

  const subtotal = itens.reduce((acc, item) => acc + item.subtotal, 0);
  const total = Math.max(0, subtotal - desconto);
  const totalPago = pagamentos.reduce((acc, p) => acc + p.valor, 0);
  const restante = Math.max(0, total - totalPago);

  // Verdadeiro quando TODOS os itens são retirada na loja
  // Usado para esconder campos irrelevantes (prazo, preferências, aguardar liberação)
  const todosRetiram = itens.length > 0 && itens.every(i => i.tipo_entrega === 'retira');
  const temEncomenda = itens.some(i => i.is_encomenda);
  const todosItensSemEstoque = itens.length > 0 && itens.every(i => i.is_encomenda);
  const conclusaoAutomatica = todosRetiram && !temEncomenda;
  const prazoEncomendaConfigurado = obterPrazoEncomenda(prazosConfig);
  const prazoEncomendaAutomatico = formatarPrazoEntrega(prazoEncomendaConfigurado);

  useEffect(() => {
    const entrouEmCarrinhoSemEstoque = todosItensSemEstoque && !prevTodosItensSemEstoqueRef.current;
    prevTodosItensSemEstoqueRef.current = todosItensSemEstoque;

    if (todosRetiram || !prazoEncomendaAutomatico || !todosItensSemEstoque) return;
    if (!entrouEmCarrinhoSemEstoque && configVenda.prazo) return;

    setConfigVenda((prev) => {
      if (prev.prazo === prazoEncomendaAutomatico) return prev;
      return { ...prev, prazo: prazoEncomendaAutomatico };
    });
  }, [todosItensSemEstoque, todosRetiram, prazoEncomendaAutomatico, configVenda.prazo]);

  // Helper: obter o tipo_montagem final para uso downstream
  const getTipoMontagemFinal = (item) => {
    if (item.tipo_entrega === 'retira') return 'retira';
    if (item.tipo_entrega === 'entrega') {
      if (item.tipo_entrega_padrao === 'nao_requer_montagem') return 'sem_montagem';
      return item.tipo_montagem; // 'montado' | 'montagem_cliente' | 'sem_montagem'
    }
    return null;
  };

  const getProdutoDoItemCarrinho = (item) => {
    if (!item?.produto_id) return null;
    return produtos.find((produto) => produto.id === item.produto_id) || null;
  };

  const getEstoqueOrigemItem = (produto, item) => {
    if (!produto) return null;

    const campoOrigem = item?.origem_estoque_campo;
    if (campoOrigem) {
      return Number(produto?.[campoOrigem] || 0);
    }

    const total = Number(getProductTotalStock(produto));
    const reservado = Number(produto?.quantidade_reservada || 0);
    if (!Number.isFinite(total)) return null;
    return total - reservado;
  };

  const itemBloqueadoPorEstoque = (item) => {
    if (!item || item.is_encomenda || item.is_solicitacao) return false;

    const produtoAtual = getProdutoDoItemCarrinho(item);
    if (!produtoAtual) return false;

    const estoqueOrigemAtual = getEstoqueOrigemItem(produtoAtual, item);
    if (estoqueOrigemAtual === null) return false;

    return estoqueOrigemAtual <= 0;
  };

  const itensBloqueadosPorEstoque = itens.filter(itemBloqueadoPorEstoque);

  const getResumoItensBloqueadosPorEstoque = (limite = 3) => {
    if (itensBloqueadosPorEstoque.length === 0) return '';

    const nomesUnicos = Array.from(new Set(
      itensBloqueadosPorEstoque.map((item) => item?.produto_nome).filter(Boolean)
    ));

    const nomesVisiveis = nomesUnicos.slice(0, limite).join(', ');
    const restantes = nomesUnicos.length - limite;

    if (restantes > 0) {
      return `${nomesVisiveis} e mais ${restantes}`;
    }

    return nomesVisiveis;
  };

  const podeAvancar = () => {
    return getMotivoBloqueioBotao() === null;
  };
  const getMotivoBloqueioBotao = () => {
    if (etapa === 1) {
      if (itens.length === 0) return 'Adicione produtos ao carrinho';
      const semEntrega = itens.filter(i => !i.tipo_entrega);
      if (semEntrega.length > 0) return `${semEntrega.length} item(ns) sem tipo de entrega`;
      const semPreco = itens.filter(i => !i.preco_unitario || i.preco_unitario <= 0);
      if (semPreco.length > 0) return `${semPreco.length} item(ns) com preço inválido`;
      const precoPendente = itens.filter(i => i.status_solicitacao_preco === 'pendente');
      if (precoPendente.length > 0) return `${precoPendente.length} item(ns) com preço pendente`;
      const semMontagem = itens.filter(i =>
        i.tipo_entrega === 'entrega' &&
        i.tipo_entrega_padrao !== 'nao_requer_montagem' &&
        !i.tipo_montagem
      );
      if (semMontagem.length > 0) return `${semMontagem.length} item(ns) sem tipo de montagem`;
      if (itensBloqueadosPorEstoque.length > 0) {
        const resumoItens = getResumoItensBloqueadosPorEstoque();
        return `${itensBloqueadosPorEstoque.length} item(ns) com estoque zerado (${resumoItens}). Ajuste no Estoque e atualize o PDV.`;
      }
    }
    if (etapa === 2) {
      if (!clienteSelecionado) return 'Selecione um cliente';
      if (!todosRetiram && !configVenda.prazo) return 'Defina o prazo de entrega';
      if (!todosRetiram && aguardandoLiberacao && !dataLiberacao) return 'Defina a data "Liberar a partir de"';
    }
    return null;
  };

  const avancarEtapa = () => {
    if (etapa === 1) {
      if (itens.length === 0) return toast.warning("Adicione pelo menos um produto");

      const itensSemEntrega = itens.filter(i => !i.tipo_entrega);
      if (itensSemEntrega.length > 0) {
        return toast.warning("Escolha o tipo de entrega para todos os itens");
      }

      const itensSemMontagem = itens.filter(i =>
        i.tipo_entrega === 'entrega' &&
        i.tipo_entrega_padrao !== 'nao_requer_montagem' &&
        !i.tipo_montagem
      );
      if (itensSemMontagem.length > 0) {
        return toast.warning("Escolha o tipo de montagem para os itens com entrega");
      }

      const itensSemPreco = itens.filter(i => !i.preco_unitario || i.preco_unitario <= 0);
      if (itensSemPreco.length > 0) {
        return toast.error(`Existem ${itensSemPreco.length} produto(s) com preço inválido (R$ 0 ou indefinido). Solicite a revisão do preço a um supervisor .`);
      }

      const itensComSolicitacaoPendente = itens.filter(i => i.status_solicitacao_preco === 'pendente');
      if (itensComSolicitacaoPendente.length > 0) {
        return toast.error(`Existem ${itensComSolicitacaoPendente.length} produto(s) com solicitação de preço pendente. Aguarde a aprovação ou ajuste o preço.`);
      }

      if (itensBloqueadosPorEstoque.length > 0) {
        const resumoItens = getResumoItensBloqueadosPorEstoque();
        return toast.error(`Venda bloqueada: ${itensBloqueadosPorEstoque.length} item(ns) com estoque zerado (${resumoItens}). Gerente deve ajustar no Estoque para continuar.`);
      }
    }
    if (etapa === 2) {
      if (!clienteSelecionado) return toast.warning("Selecione um cliente");
      if (!todosRetiram && !configVenda.prazo) return toast.warning("Selecione o prazo de entrega");
      if (!todosRetiram && aguardandoLiberacao && !dataLiberacao) return toast.warning("Selecione a data de liberação da entrega");
    }
    if (etapa < 3) setEtapa(etapa + 1);
  };

  const voltarEtapa = () => {
    if (etapa > 1) setEtapa(etapa - 1);
  };

  const handleFinalizar = async () => {
    // 🛡️ Proteção contra duplo-clique (mutex imediato)
    if (isProcessingRef.current || loading) {
      console.log('⚠️ Venda já em processamento, ignorando clique duplicado');
      return;
    }
    isProcessingRef.current = true;
    setLoading(true);

    // 🛡️ Proteção contra venda duplicada originada de orçamento
    if (orcamentoOrigemId) {
      const vendaExistente = (vendas || []).find(v => v.orcamento_origem_id === orcamentoOrigemId);
      if (vendaExistente) {
        toast.error(`Este orçamento já foi convertido na venda #${vendaExistente.numero_pedido}. Não é possível criar uma segunda venda a partir do mesmo orçamento.`);
        isProcessingRef.current = false;
        setLoading(false);
        return;
      }
    }

    // Validações
    if (!clienteSelecionado) {
      isProcessingRef.current = false;
      setLoading(false);
      return toast.warning("Selecione um cliente");
    }
    if (itens.length === 0) {
      isProcessingRef.current = false;
      setLoading(false);
      return toast.warning("Adicione produtos");
    }

    const itensSemPrecoFinal = itens.filter(i => !i.preco_unitario || i.preco_unitario <= 0);
    if (itensSemPrecoFinal.length > 0) {
      isProcessingRef.current = false;
      setLoading(false);
      return toast.error("A venda contém itens com preço inválido (R$ 0 ou indefinido). Solicite a revisão do preço a um supervisor .");
    }
    if (!todosRetiram && !configVenda.prazo) {
      isProcessingRef.current = false;
      setLoading(false);
      return toast.warning("Selecione o prazo de entrega");
    }
    if (!todosRetiram && aguardandoLiberacao && !dataLiberacao) {
      isProcessingRef.current = false;
      setLoading(false);
      return toast.warning("Selecione a data de liberação da entrega");
    }

    if (itensBloqueadosPorEstoque.length > 0) {
      isProcessingRef.current = false;
      setLoading(false);
      const resumoItens = getResumoItensBloqueadosPorEstoque();
      return toast.error(`Venda bloqueada: ${itensBloqueadosPorEstoque.length} item(ns) com estoque zerado (${resumoItens}). Ajuste no Estoque e atualize o PDV.`);
    }

    if (restante > 0 && !pagamentoEntrega.ativo) {
      const confirmed = await confirm({
        title: "Saldo Pendente",
        message: "Há um saldo restante pendente. Confirmar venda assim mesmo?",
        confirmText: "Confirmar Venda"
      });
      if (!confirmed) {
        isProcessingRef.current = false;
        setLoading(false);
        return;
      }
    }

    // --- VALIDAÇÃO DE ENDEREÇO OBRIGATÓRIO ---
    // Se algum item requer entrega, o cliente precisa ter endereço
    const temEntrega = itens.some(i => i.tipo_entrega === 'entrega');
    if (temEntrega) {
      const enderecoCompleto = construirEnderecoEntrega(clienteSelecionado);
      if (!enderecoCompleto || enderecoCompleto === "Endereço a definir") {
        isProcessingRef.current = false;
        setLoading(false);
        return toast.error("Endereço obrigatório para entrega. Cadastre o endereço do cliente.");
      }
    }


    // 🖨️ ABRIR JANELA DE IMPRESSÃO AGORA (antes de qualquer operação async)
    // O navegador só permite window.open() direto no evento de clique.
    // Se movermos para depois das operações do banco, o popup é bloqueado.
    const printWindow = prepararNotaPedidoPDF();
    const atualizarProgressoPedido = (step, progress, label = 'Finalizando pedido...') => {
      atualizarStatusNotaPedidoPDF(printWindow, { label, step, progress });
    };

    // Gerar número do pedido com fallback para evitar NaN
    // Gerar número do pedido sequencial (pula OFF e O-)
    let lastNum = 0;
    if (vendas.length > 0 && isOnline) {
      // Encontrar o maior número de pedido VÁLIDO e SEQUENCIAL (ignorando offline)
      const numerosvalidos = vendas
        .map(v => v.numero_pedido)
        .filter(n => n && !n.startsWith('OFF') && !n.startsWith('O-') && !n.includes('NaN'))
        .map(n => parseInt(n))
        .filter(n => !isNaN(n));

      if (numerosvalidos.length > 0) {
        lastNum = Math.max(...numerosvalidos);
      }
    }

    // Garantir que pedidos online comecem a partir de 10000
    if (isOnline && lastNum < 10000) {
      lastNum = 9999; // Assim o próximo (lastNum + 1) será 10000
    }

    let novoNumero = isOnline
      ? String(lastNum + 1).padStart(5, '0')
      : `O-${Math.floor(Date.now() / 1000).toString().slice(-4)}`;

    const formaPagamentoEntregaStr = pagamentoEntrega.ativo
      ? (pagamentoEntrega.forma === "Cartão de Crédito" || pagamentoEntrega.forma?.includes("Crédito")
        ? `${pagamentoEntrega.forma} (${pagamentoEntrega.parcelas || 1}x)`
        : pagamentoEntrega.forma || "")
      : "";

    // --- MAPEAMENTO DE LOJA_ID ---
    // Buscamos o ID da loja com base no nome selecionado em configVenda.loja
    const lojaObj = (lojas || []).find(l => l.nome === configVenda.loja);
    const lojaId = lojaObj?.id || user?.loja_id || null;

    const itensComFornecedorResolvido = enriquecerItensEncomendaComFornecedor(itens, produtos, fornecedores);
    const itensEncomenda = itensComFornecedorResolvido.filter(i => i.is_encomenda);
    const itensEncomendaInvalidos = itensEncomenda.filter(i => !i.fornecedor_id);

    if (itensEncomendaInvalidos.length > 0) {
      const nomes = itensEncomendaInvalidos
        .map(i => i.produto_nome)
        .filter(Boolean)
        .join(', ');

      if (printWindow && !printWindow.closed) {
        printWindow.close();
      }

      toast.error(`Fornecedor obrigatorio para encomenda. Conclua o cadastro do produto e informe o fornecedor para: ${nomes}`);
      setLoading(false);
      isProcessingRef.current = false;
      return;
    }

    const vendaData = {
      numero_pedido: novoNumero,
      data_venda: configVenda.data,
      loja: configVenda.loja,
      loja_id: lojaId, // Adicionado campo vital para relatórios
      responsavel_id: vendedorFinal.id,
      responsavel_nome: vendedorFinal.nome,
      cliente_id: clienteSelecionado.id,
      cliente_nome: clienteSelecionado.nome_completo,
      cliente_telefone: clienteSelecionado.telefone,
      itens: itensComFornecedorResolvido,
      valor_total: total,
      desconto,
      pagamentos,
      valor_pago: totalPago,
      valor_restante: restante,
      pagamento_na_entrega: pagamentoEntrega.ativo,
      valor_pagamento_entrega: pagamentoEntrega.ativo ? pagamentoEntrega.valor : 0,
      forma_pagamento_entrega: formaPagamentoEntregaStr,
      prazo_entrega: todosRetiram ? "Retirado na loja" : configVenda.prazo,
      status: restante <= 0 ? (todosRetiram ? "Pago & Retirado" : "Pago") : "Pagamento Pendente",
      observacoes: observacoes,
      cupom_codigo: cupomAplicado?.codigo || null,
      cupom_desconto: cupomAplicado ? desconto : 0,
      desconto_percentual: desconto > 0 && subtotal > 0
        ? parseFloat(((desconto / subtotal) * 100).toFixed(2))
        : null,
      desconto_origem: cupomAplicado
        ? 'cupom'
        : tokenGerencial
          ? 'token'
          : desconto > 0 && descontoMargemPercent > 0
            ? 'margem_negociavel'
            : desconto !== 0
              ? 'arredondamento'
              : null,
      triagem_realizada: todosRetiram,
      data_triagem: todosRetiram ? new Date().toISOString() : null,
      orcamento_origem_id: orcamentoOrigemId || null
    };

    if
      (!isOnline) {
      const salvou = saveOfflineSale(vendaData);
      if (salvou) {
        toast.warning("⚠️ Sem internet: Venda salva no dispositivo! Será sincronizada quando a conexão voltar.");
        abrirNotaPedidoPDF({ ...vendaData }, clienteSelecionado, vendedorFinal.nome || user.full_name, lojaAtivaPDV ? { ...lojaAtivaPDV, empresa_nome: brandName } : null);
        resetForm();
        carregarVendasPendentes();
      } else {
        toast.error("Erro crítico ao salvar venda offline. Tire foto da tela.");
      }
      setLoading(false);
      isProcessingRef.current = false;
      return;
    }

    try {
      atualizarProgressoPedido('Salvando venda...', 18);
      const vendaCriada = await medirDuracaoEtapa('criar venda', () =>
        criarVendaMutation.mutateAsync({
          ...vendaData,
          // Marcar como aguardando conferência se o módulo estiver ativo
          // (exceto se for "pagar na entrega", que não precisa de conferência)
          ...(conferenciaCaixaEnabled && !pagamentoEntrega.ativo
            ? { conferencia_caixa_status: 'aguardando' }
            : {})
        })
      );

      // ─── SE MÓDULO DE CONFERÊNCIA ATIVO: parar aqui ───
      // Entrega, montagens e lançamentos financeiros só são criados APÓS a conferência
      // Função de atualização de estoque declarada aqui para uso nos dois fluxos
      const atualizarEstoqueVenda = async () => {
        const itensComProduto = itens.filter(item => !!item.produto_id);
        return medirDuracaoEtapa('atualizar estoque', () =>
          Promise.all(itensComProduto.map(async (item) => {
            if (item.variante_id && lojaId) {
              const estoqueAtual = await getVarianteEstoque(supabase, item.variante_id, lojaId);
              const novaQtd = estoqueAtual - Number(item.quantidade || 0);
              const resultado = await atualizarEstoqueVariante(supabase, item.variante_id, lojaId, novaQtd);
              if (!resultado.success) console.warn('[PDV] Erro ao atualizar estoque da variante:', resultado.error);
              return resultado;
            }
            const prod = await base44.entities.Produto.getById(item.produto_id);
            if (!prod) return null;
            const campoOrigem = item?.origem_estoque_campo || resolveStockField(configVenda.loja);
            const estoqueOrigemAtual = Number(prod?.[campoOrigem] || 0);
            const estoqueLocalAposVenda = estoqueOrigemAtual - Number(item.quantidade || 0);
            const updates = montarAtualizacaoEstoqueProdutoPorCampo(prod, estoqueLocalAposVenda, campoOrigem);
            return base44.entities.Produto.update(prod.id, updates);
          }))
        );
      };

      if (conferenciaCaixaEnabled && !pagamentoEntrega.ativo) {
        // Ainda atualizamos estoque (já comprometido)
        atualizarProgressoPedido('Atualizando estoque...', 80);
        await atualizarEstoqueVenda();

        atualizarProgressoPedido('Atualizando paineis...', 90);
        await Promise.all([
          queryClient.invalidateQueries({ queryKey: ['vendas'] }),
          queryClient.invalidateQueries({ queryKey: ['produtos'] }),
        ]);

        atualizarProgressoPedido('Preparando impressao...', 96);
        preencherEImprimirPDF(printWindow, { ...vendaData }, clienteSelecionado, vendedorFinal.nome || user.full_name, lojaAtivaPDV ? { ...lojaAtivaPDV, empresa_nome: brandName } : null);

        toast.success("Venda criada! Aguardando conferência de caixa para liberar entrega e lançamentos.");
        resetForm();
        return;
      }

      // ─── FLUXO NORMAL (sem conferência de caixa) ───
      // atualizarEstoqueVenda já declarada acima (compartilhada com o bloco de conferência)

      // Calcular prazo de entrega com base na configuração
      const prazoSelecionado = encontrarPrazoConfigurado(prazosConfig, configVenda.prazo);
      const dias = prazoSelecionado ? prazoSelecionado.quantidade_dias : 15;
      const tipoDias = prazoSelecionado ? prazoSelecionado.tipo_dias : 'uteis';
      const basePrazoData = aguardandoLiberacao && dataLiberacao ? dataLiberacao : configVenda.data;
      const limite = adicionarDias(basePrazoData, dias, tipoDias);

      const enderecoCompleto = temEntrega ? construirEnderecoEntrega(clienteSelecionado) : `Retirado na loja: ${configVenda.loja}`;
      const todosRetiram = itens.every(i => i.tipo_entrega === 'retira');

      const itensParaMontagemInterna = itens
        .filter(i => getTipoMontagemFinal(i) === 'montado')
        .map(i => ({
          produto_nome: i.produto_nome,
          quantidade: i.quantidade,
          montado: false
        }));

      atualizarProgressoPedido('Criando entrega...', 56);
      const entregaCriada = await medirDuracaoEtapa('criar entrega', () =>
        base44.entities.Entrega.create({
          venda_id: vendaCriada.id,
          numero_pedido: novoNumero,
          cliente_nome: clienteSelecionado.nome_completo,
          cliente_telefone: clienteSelecionado.telefone,
          endereco_entrega: enderecoCompleto,
          data_limite: todosRetiram ? obterDataLocalString() : obterDataLocalString(limite),
          prazo_entrega: configVenda.prazo,
          data_liberacao: aguardandoLiberacao ? (dataLiberacao || null) : null,
          status: todosRetiram
            ? (conclusaoAutomatica && restante <= 0 ? 'Entregue' : 'Retirado')
            : (aguardandoLiberacao ? 'Aguardando Liberação' : 'Pendente'),
          tipo_montagem: itens.length === 1 ? getTipoMontagemFinal(itens[0]) : 'Múltiplos Itens',
          montagem_status: (itens.some(i => {
            const tf = getTipoMontagemFinal(i);
            return tf === 'montado' || tf === 'montagem_cliente';
          })) ? 'Pendente' : null,
          itens_montagem_interna: itensParaMontagemInterna,
          pagamento_na_entrega: pagamentoEntrega.ativo,
          valor_a_receber: pagamentoEntrega.ativo ? pagamentoEntrega.valor : 0,
          forma_pagamento_entrega: pagamentoEntrega.ativo ? formaPagamentoEntregaStr : null,
          preferencias_entrega: preferenciasEntrega,
          loja_id: lojaId,
          vendedor_id: vendedorFinal.id
        })
      );

      const montagensParaCriar = itens
        .map((item) => {
          const tipoFinal = getTipoMontagemFinal(item);

          if (tipoFinal === 'montagem_cliente') {
            return {
              entrega_id: entregaCriada.id,
              venda_id: vendaCriada.id,
              produto_id: item.produto_id,
              produto_nome: item.produto_nome,
              quantidade: item.quantidade,
              tipo_montagem: 'terceirizada',
              status: 'pendente',
              cliente_nome: clienteSelecionado.nome_completo,
              cliente_telefone: clienteSelecionado.telefone,
              endereco: enderecoCompleto,
              numero_pedido: novoNumero
            };
          }

          if (tipoFinal === 'montado') {
            return {
              entrega_id: entregaCriada.id,
              venda_id: vendaCriada.id,
              produto_id: item.produto_id,
              produto_nome: item.produto_nome,
              quantidade: item.quantidade,
              tipo_montagem: 'interna',
              status: 'pendente',
              cliente_nome: clienteSelecionado.nome_completo,
              cliente_telefone: clienteSelecionado.telefone,
              endereco: enderecoCompleto,
              numero_pedido: novoNumero
            };
          }

          return null;
        })
        .filter(Boolean);

      atualizarProgressoPedido('Registrando itens de montagem...', 72);
      const criarMontagensPromise = montagensParaCriar.length > 0
        ? medirDuracaoEtapa('criar montagens', () =>
          Promise.all(montagensParaCriar.map((payload) => base44.entities.MontagemItem.create(payload)))
        )
        : Promise.resolve([]);

      await criarMontagensPromise;

      atualizarProgressoPedido('Atualizando estoque...', 80);
      await atualizarEstoqueVenda();

      // Invalidar queries após TODAS as operações serem concluídas
      atualizarProgressoPedido('Atualizando paineis...', 88);
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: ['vendas'] }),
        queryClient.invalidateQueries({ queryKey: ['produtos'] }),
        queryClient.invalidateQueries({ queryKey: ['entregas'] }),
        queryClient.invalidateQueries({ queryKey: ['montagens'] }),
        queryClient.invalidateQueries({ queryKey: ['clientes'] }),
        queryClient.invalidateQueries({ queryKey: ['lojas'] })
      ]);

      // 4. IMPRESSÃO
      atualizarProgressoPedido('Preparando impressao...', 96);
      preencherEImprimirPDF(printWindow, { ...vendaData }, clienteSelecionado, vendedorFinal.nome || user.full_name, lojaAtivaPDV ? { ...lojaAtivaPDV, empresa_nome: brandName } : null);

      toast.success("Venda finalizada com sucesso!");

      if (itensEncomenda.length > 0) {
        executarEmSegundoPlano('criar solicitações de encomenda', async () => {
          const resultados = await Promise.allSettled(itensEncomenda.map((item) =>
            base44.entities.SolicitacaoEncomenda.create({
              venda_id: vendaCriada.id,
              produto_id: item.produto_id,
              produto_nome: item.produto_nome,
              fornecedor_id: item.fornecedor_id || null,
              fornecedor_nome: item.fornecedor_nome || '',
              quantidade: item.quantidade,
              cliente_nome: clienteSelecionado.nome_completo,
              numero_pedido: novoNumero,
              loja: configVenda.loja,
              loja_id: lojaId,
              vendedor_id: vendedorFinal.id || null,
              vendedor_nome: vendedorFinal.nome || null,
              status: 'pendente'
            })
          ));

          const falhas = resultados.filter((resultado) => resultado.status === 'rejected');
          if (falhas.length > 0) {
            console.error('Erro ao criar solicitações de encomenda:', falhas);
            toast.warning(`Venda concluida, mas ${falhas.length} encomenda(s) precisarao de revisao no Compras.`);
          } else {
            toast.info(`📦 ${itensEncomenda.length} item(ns) enviado(s) como encomenda ao Setor de Compras`);
          }

          await queryClient.invalidateQueries({ queryKey: ['solicitacoes_encomenda'] });
        });
      }

      if (cupomAplicado) {
        executarEmSegundoPlano('atualizar uso de cupom', async () => {
          await base44.entities.Cupom.update(cupomAplicado.id, {
            quantidade_usada: (cupomAplicado.quantidade_usada || 0) + 1
          });
        });
      }

      if (tokenGerencial) {
        executarEmSegundoPlano('registrar uso de token gerencial', async () => {
          await base44.entities.TokenGerencial.update(tokenGerencial.id, {
            usos_realizados: (tokenGerencial.usos_realizados || 0) + 1
          });

          await base44.entities.LogUsoToken.create({
            token_id: tokenGerencial.id,
            venda_id: vendaCriada.id,
            vendedor_id: user?.id,
            vendedor_nome: user?.full_name || user?.email,
            acao_realizada: 'desconto_gerencial',
            detalhes: {
              desconto_aplicado: desconto,
              desconto_percent: (desconto / subtotal * 100).toFixed(1),
              subtotal_venda: subtotal,
              numero_pedido: novoNumero
            }
          });
        });
      }

      executarEmSegundoPlano('criar lançamentos financeiros', async () => {
        await criarLancamentosVenda(vendaData, taxasFinanceiras, vendaCriada.id);
        await queryClient.invalidateQueries({ queryKey: ['lancamentos-financeiros'] });
      });

      executarEmSegundoPlano('processar fidelidade', async () => {
        const formaPagamentoPrincipal = vendaData.pagamentos?.[0]?.forma_pagamento || '';
        const itensFidelidade = (itens || []).map(i => ({ categoria: i.categoria || '' }));

        const resultadoFidelidade = await processarFidelidadeCompra(
          clienteSelecionado,
          total,
          vendaData.numero_pedido,
          vendaCriada.id,
          formaPagamentoPrincipal,
          itensFidelidade
        );

        if (resultadoFidelidade?.coroasGanhas > 0) {
          console.log(`👑 Cliente ganhou ${resultadoFidelidade.coroasGanhas} Coroas!`);
        }

        await queryClient.invalidateQueries({ queryKey: ['clientes'] });
      });

      // Captura variáveis para o closure do timeout antes do resetForm
      const zapTelefone = clienteSelecionado.telefone;
      const zapNome = clienteSelecionado.nome_completo;
      const zapPedido = novoNumero;
      const zapPrazo = configVenda.prazo;
      const zapItens = [...itens]; // Copia array

      // Limpa o PDV para próxima venda
      resetForm();

      // 5. ENVIO WHATSAPP EM "BACKGROUND" (Delay para não competir com renderização do print)
      if (zapTelefone) {
        if (isPaidModuleActive('whatsapp')) {
          toast.info("Emissão concluída. Tentando enviar comprovante pelo WhatsApp...");

          setTimeout(async () => {
            try {
              // Formata lista de produtos
              const listaProdutos = zapItens.map(item => `• ${item.quantidade}x ${stripInternalProductPrefixes(item.produto_nome) || '-'}`).join('\n');

              console.log("📄 Gerando PDF para WhatsApp em background...");
              let pdfBase64 = null;
              try {
                // Nota: vendaData ainda está acessível no closure
                pdfBase64 = await gerarNotaPedidoBase64(vendaData, { ...clienteSelecionado }, vendedorFinal.nome || user.full_name, lojaAtivaPDV ? { ...lojaAtivaPDV, empresa_nome: brandName } : null);

                if (pdfBase64) {
                  console.log(`📄 PDF gerado com sucesso (${pdfBase64.length} bytes)`);
                } else {
                  console.warn('⚠️ Falha ao gerar PDF base64 (retornou null)');
                }
              } catch (pdfErr) {
                console.error('Erro na geração do PDF background:', pdfErr);
              }

              // Envia para o Bot (com fallback offline automático)
              await whatsappService.sendSaleConfirmation({
                telefone: zapTelefone,
                nome: zapNome,
                pedido: zapPedido,
                prazo: zapPrazo,
                produtos: listaProdutos,
                pdf_base64: pdfBase64
              });

            } catch (bgErr) {
              console.error("Erro fatal no processo de background:", bgErr);
            }
          }, 1500); // 1.5s delay para garantir que o print dialog já abriu
        } else {
          console.log("🚫 Envio automático de WhatsApp pulado: módulo 'whatsapp' desativado no plano.");
        }
      }

    } catch (err) {
      // Extrair mensagem útil do erro (Supabase devolve detalhes em err.message ou err.details)
      const errMsg = err?.message || err?.details || err?.hint || (typeof err === 'string' ? err : null);
      const errDetail = err?.details ? ` (${err.details})` : '';
      const displayMsg = errMsg
        ? `Erro: ${errMsg}${errDetail}`
        : 'A venda nao foi concluida. Verifique a conexao e tente novamente.';
      sinalizarErroNotaPedidoPDF(printWindow, displayMsg);
      console.error('[PDV] Erro ao finalizar venda:', err);
      toast.error(errMsg ? `Erro ao finalizar venda: ${errMsg}` : "Erro ao finalizar venda. Verifique sua conexão.");
    } finally {
      setLoading(false);
      isProcessingRef.current = false;
    }
  };

  const handleOrcamento = async (diasValidade = 30) => {
    if (!clienteSelecionado) return toast.warning("Selecione um cliente");
    if (!isOnline) return toast.warning("Orçamentos só podem ser salvos online.");

    setSavingOrcamento(true);
    try {
      const numero = String(Date.now()).slice(-5);
      await criarOrcamentoMutation.mutateAsync({
        numero_orcamento: numero,
        data_orcamento: configVenda.data,
        validade: new Date(Date.now() + diasValidade * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
        loja: configVenda.loja,
        cliente_id: clienteSelecionado.id,
        cliente_nome: clienteSelecionado.nome_completo,
        cliente_telefone: clienteSelecionado.telefone,
        itens,
        valor_total: total,
        desconto,
        pagamentos,
        cidade: clienteSelecionado.cidade || "",
        bairro: clienteSelecionado.bairro || "",
        endereco: clienteSelecionado.endereco || "",
        valor_frete: pagamentoEntrega.ativo ? pagamentoEntrega.valor : 0,
        status: "Pendente",
        observacoes,
        vendedor_id: vendedorFinal.id || user?.id || null
      });
      toast.success("Orçamento salvo!");
      resetForm();
    } catch (err) {
      console.error(err);
      toast.error("Erro ao salvar orçamento");
    } finally {
      setSavingOrcamento(false);
    }
  };

  const resetForm = () => {
    setClienteSelecionado(null);
    setItens([]);
    setPagamentos([]);
    setDesconto(0);
    setObservacoes("");
    setPagamentoEntrega({ ativo: false, valor: 0, forma: "" });
    setConfigVenda(prev => ({ ...prev, data: obterDataLocalString(), prazo: "" }));
    setPreferenciasEntrega({ dias: [0, 1, 2, 3, 4, 5, 6], turnos: ['Manhã', 'Tarde', 'Comercial'], obs: "" });
    setAguardandoLiberacao(false);
    setDataLiberacao("");
    setSelectedVendedorId(user?.id || null);
    setCupomAplicado(null);
    setOrcamentoOrigemId(null);
    setDescontoMargemPercent(0);
    setEtapa(1);
    sessionStorage.removeItem(PDV_STATE_KEY);
  };

  if (!user) return <div className="flex h-screen items-center justify-center"><div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-800" /></div>;

  const etapas = [
    { num: 1, titulo: "Produtos", icon: Package },
    { num: 2, titulo: "Cliente & Entrega", icon: User },
    { num: 3, titulo: "Pagamento", icon: CreditCard },
  ];

  return (
    <div
      className="fixed inset-y-0 right-0 flex flex-col bg-gray-50 dark:bg-black text-gray-900 dark:text-gray-100 transition-[left] duration-200 ease-linear"
      style={{ left: isMobile ? '0px' : (sidebarState === 'expanded' ? '16rem' : '3rem') }}
    >

      {!isOnline && (
        <div className="bg-red-600 text-white text-xs font-bold text-center py-1 flex items-center justify-center gap-2">
          <WifiOff className="w-3 h-3" />
          MODO OFFLINE ATIVADO - As vendas serão salvas neste dispositivo
        </div>
      )}
      {isOnline && vendasPendentes.length > 0 && (
        <div className="bg-orange-500 text-white text-xs font-bold text-center py-1 flex items-center justify-center gap-2 cursor-pointer hover:bg-orange-600" onClick={sincronizarVendas}>
          <RefreshCw className={`w-3 h-3 ${syncing ? 'animate-spin' : ''}`} />
          {syncing ? "Sincronizando..." : `VOCÊ ESTÁ ONLINE! Clique aqui para enviar ${vendasPendentes.length} vendas salvas offline.`}
        </div>
      )}

      <header className="h-12 bg-white dark:bg-neutral-900 border-b border-gray-200 dark:border-neutral-800 flex items-center justify-between px-4 flex-shrink-0">
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2 text-green-800 dark:text-green-500 font-bold text-lg">
            <Store className="w-5 h-5" />
            PDV
          </div>
          <div className="h-5 w-px bg-gray-200 dark:bg-neutral-800" />
          <div className="flex gap-2 text-xs">
            <div className="flex items-center gap-1.5 bg-gray-100 dark:bg-neutral-800 px-2 py-1 rounded">
              <Store className="w-3 h-3 text-gray-400" />
              <span className="font-medium">{configVenda.loja}</span>
            </div>
            {isOnline ? (
              <Badge variant="outline" className="text-green-600 border-green-200 bg-green-50"><Wifi className="w-3 h-3 mr-1" /> Online</Badge>
            ) : (
              <Badge variant="outline" className="text-red-600 border-red-200 bg-red-50"><WifiOff className="w-3 h-3 mr-1" /> Offline</Badge>
            )}
          </div>
        </div>
        <div className="flex items-center gap-2">
          {/* Usa o email se o nome não carregar */}
          <span className="text-xs text-gray-500 hidden sm:inline">
            {user.full_name || user.email}
          </span>
          <div className="w-7 h-7 bg-green-100 dark:bg-green-900 rounded-full flex items-center justify-center text-green-800 dark:text-green-400 font-bold text-xs">
            {/* Pega a 1ª letra do nome OU do email, ou usa 'U' se tudo falhar */}
            {(user.full_name || user.email || 'U').charAt(0).toUpperCase()}
          </div>
        </div>
      </header>

      <div className="bg-white dark:bg-neutral-900 border-b border-gray-200 dark:border-neutral-800 px-4 py-2 flex-shrink-0">
        <div className="max-w-3xl mx-auto flex items-center justify-between">
          {etapas.map((e, idx) => (
            <React.Fragment key={e.num}>
              <div
                className={`flex items-center gap-2 cursor-pointer transition-all ${etapa === e.num ? 'opacity-100' : etapa > e.num ? 'opacity-70' : 'opacity-40'
                  }`}
                onClick={() => etapa > e.num && setEtapa(e.num)}
              >
                <div className={`w-7 h-7 rounded-full flex items-center justify-center font-bold text-xs ${etapa === e.num
                  ? 'bg-green-600 text-white'
                  : etapa > e.num
                    ? 'bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-400'
                    : 'bg-gray-100 text-gray-400 dark:bg-neutral-800'
                  }`}>
                  {etapa > e.num ? <Check className="w-3 h-3" /> : e.num}
                </div>
                <span className={`text-xs font-medium hidden sm:inline ${etapa === e.num ? 'text-green-700 dark:text-green-400' : 'text-gray-500'}`}>
                  {e.titulo}
                </span>
              </div>
              {idx < etapas.length - 1 && (
                <div className={`flex-1 h-0.5 mx-2 rounded-full ${etapa > e.num ? 'bg-green-500' : 'bg-gray-200 dark:bg-neutral-700'}`} />
              )}
            </React.Fragment>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4">
        <div className={`mx-auto transition-all duration-300 ${etapa === 3 ? 'max-w-[95%] xl:max-w-7xl' : 'max-w-3xl'}`}>
          {etapa === 1 && (
            <div className="space-y-4">
              <div className="bg-white dark:bg-neutral-900 rounded-xl p-4 shadow-sm border border-gray-100 dark:border-neutral-800">
                <h2 className="text-sm font-bold mb-3 flex items-center gap-2">
                  <ShoppingCart className="w-4 h-4 text-green-600" />
                  Adicionar Produtos
                </h2>
                <BuscaProdutoAvancada produtos={produtos} fornecedores={fornecedores} onSelectProduto={(p) => handleSelectProduto(p.is_solicitacao || p.is_encomenda ? p : p.id)} onEditProduto={handleEditProdutoPDV} user={user} />
              </div>
              <div className="bg-white dark:bg-neutral-900 rounded-xl p-4 shadow-sm border border-gray-100 dark:border-neutral-800">
                <div className="flex items-center justify-between mb-3">
                  <h3 className="font-semibold text-sm">Carrinho ({itens.length})</h3>
                  <div className="text-right">
                    <p className="text-xs text-gray-500">Subtotal</p>
                    <p className="text-lg font-bold text-green-700">R$ {subtotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                  </div>
                </div>
                <CarrinhoVenda
                  itens={itens.map((item) => {
                    const produtoAtual = getProdutoDoItemCarrinho(item);
                    const estoqueOrigemAtual = getEstoqueOrigemItem(produtoAtual, item);
                    const opcoesOrigemItem = getOrigensDisponiveisProduto(produtoAtual, { includeZero: true });
                    if (item?.origem_estoque_campo && !opcoesOrigemItem.some((origem) => origem.campo === item.origem_estoque_campo)) {
                      opcoesOrigemItem.push({
                        campo: item.origem_estoque_campo,
                        nome: item.origem_estoque_nome || item.origem_estoque_campo,
                        quantidade: Number(produtoAtual?.[item.origem_estoque_campo] || 0)
                      });
                    }
                    return {
                      ...item,
                      estoque_loja_atual: estoqueOrigemAtual,
                      origens_estoque_disponiveis: opcoesOrigemItem,
                      bloqueado_estoque: itemBloqueadoPorEstoque(item)
                    };
                  })}
                  onRemoveItem={handleRemoveItem}
                  onAtualizarQuantidade={handleAtualizarQuantidadeItem}
                  onToggleEntrega={handleToggleEntrega}
                  onToggleMontagem={handleToggleMontagem}
                  onSetMontagemPadrao={handleSetMontagemPadrao}
                  onVincularImagem={handleVincularImagem}
                  onEditProduto={handleEditProdutoPDV}
                  onAtualizarEstoque={handleAtualizarEstoque}
                  onAtualizarProdutoId={handleAtualizarProdutoId}
                  onAtualizarItem={handleAtualizarItem}
                />
              </div>
            </div>
          )}

          {etapa === 2 && (
            <div className="space-y-4">
              <div className="bg-white dark:bg-neutral-900 rounded-xl p-4 shadow-sm border border-gray-100 dark:border-neutral-800">
                <h2 className="text-sm font-bold mb-3 flex items-center gap-2">
                  <User className="w-4 h-4 text-green-600" />
                  Selecionar Cliente
                </h2>
                {!isOnline && clientes.length === 0 && (
                  <Alert className="mb-2 bg-yellow-50 border-yellow-200">
                    <AlertDescription className="text-yellow-800 text-xs">
                      Modo Offline: Somente clientes já carregados anteriormente podem ser buscados.
                    </AlertDescription>
                  </Alert>
                )}
                <SeletorCliente
                  clienteSelecionado={clienteSelecionado}
                  setClienteSelecionado={setClienteSelecionado}
                  clientes={clientes}
                />
              </div>
              <div className="bg-white dark:bg-neutral-900 rounded-xl p-4 shadow-sm border border-gray-100 dark:border-neutral-800">
                <h2 className="text-sm font-bold mb-3 flex items-center gap-2">
                  <Truck className="w-4 h-4 text-green-600" />
                  Configuração de Entrega
                </h2>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <Label className="text-xs mb-1.5 block font-medium">Data da Venda</Label>
                    <input
                      type="date" lang="pt-BR"
                      className="w-full h-10 text-sm border rounded-lg px-3 bg-white dark:bg-neutral-800 border-gray-200 dark:border-neutral-700"
                      value={configVenda.data}
                      onChange={e => setConfigVenda({ ...configVenda, data: e.target.value })}
                    />
                  </div>
                  {/* Prazo só aparece se houver pelo menos um item com entrega */}
                  {!todosRetiram && (
                    <div>
                      <Label className="text-xs mb-1.5 block font-medium">
                        Prazo de Entrega <span className="text-red-500">*</span>
                      </Label>
                      <Select
                        value={configVenda.prazo}
                        onValueChange={v => setConfigVenda({ ...configVenda, prazo: v })}
                      >
                        <SelectTrigger className={`h-10 text-sm ${!configVenda.prazo ? 'border-orange-400 bg-orange-50 dark:bg-orange-900/20' : ''}`}>
                          <SelectValue placeholder="Selecione..." />
                        </SelectTrigger>
                        <SelectContent>
                          {prazosConfig.map(p => {
                            const label = formatarPrazoEntrega(p);
                            return (
                              <SelectItem key={p.id} value={label}>
                                {label}
                              </SelectItem>
                            );
                          })}
                        </SelectContent>
                      </Select>
                    </div>
                  )}
                </div>

                {hasMasterAccess && isOnline && (
                  <div className="mt-4">
                    <Label className="text-xs mb-1.5 block font-medium">Vendedor da Venda</Label>
                    <Select
                      value={selectedVendedorId || user?.id || ''}
                      onValueChange={setSelectedVendedorId}
                    >
                      <SelectTrigger className="h-10 text-sm">
                        <SelectValue placeholder="Selecione o vendedor" />
                      </SelectTrigger>
                      <SelectContent>
                        {vendedoresDisponiveis.map((u) => (
                          <SelectItem key={u.id} value={u.id}>
                            {u.full_name || u.email}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                )}

                {/* Badge informativo quando todos os itens são retirada */}
                {todosRetiram && (
                  <div className="mt-3 p-3 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 rounded-lg flex items-center gap-2 text-green-800 dark:text-green-300 text-sm">
                    <Store className="w-4 h-4 shrink-0" />
                    <span><strong>Retirada na loja</strong> — nenhuma configuração de entrega necessária.</span>
                  </div>
                )}

                {/* Opção Aguardando Liberação — só para pedidos com entrega */}
                {!todosRetiram && (
                  <div className="mt-4 p-3 bg-blue-50 dark:bg-blue-900/10 border border-blue-100 dark:border-blue-800 rounded-lg flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <Checkbox
                        id="aguardar-liberacao"
                        checked={aguardandoLiberacao}
                        onCheckedChange={(checked) => {
                          const ativo = checked === true;
                          setAguardandoLiberacao(ativo);
                          if (!ativo) setDataLiberacao("");
                        }}
                      />
                      <Label htmlFor="aguardar-liberacao" className="text-sm cursor-pointer text-blue-800 dark:text-blue-300">
                        <strong>Aguardar Liberação</strong>
                        <p className="text-xs opacity-70">Marque se o cliente pediu para segurar a entrega (ex: obra)</p>
                      </Label>
                    </div>
                    {aguardandoLiberacao && <Badge className="bg-blue-500">Ativado</Badge>}
                  </div>
                )}

                {!todosRetiram && aguardandoLiberacao && (
                  <div className="mt-3 p-3 bg-blue-50/80 dark:bg-blue-900/10 border border-blue-100 dark:border-blue-800 rounded-lg space-y-2">
                    <Label htmlFor="data-liberacao" className="text-sm text-blue-900 dark:text-blue-300">Liberar a partir de:</Label>
                    <input
                      id="data-liberacao"
                      type="date"
                      value={dataLiberacao}
                      min={configVenda.data || obterDataLocalString()}
                      onChange={(e) => setDataLiberacao(e.target.value)}
                      className="w-full h-10 rounded-md border border-blue-200 bg-white px-3 text-sm text-gray-700 shadow-sm focus:border-blue-400 focus:outline-none focus:ring-2 focus:ring-blue-200"
                    />
                    <p className="text-xs text-blue-800 dark:text-blue-300">
                      O prazo selecionado (normalmente 10 ou 40 dias úteis) será contado a partir da data de liberação.
                    </p>
                  </div>
                )}

                {/* Botão de Restrições de Entrega — só para pedidos com entrega */}
                {!todosRetiram && (
                  <div className="mt-4 pt-4 border-t border-gray-100 dark:border-neutral-800">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => setModalPreferenciasOpen(true)}
                      className={`w-full justify-between ${(preferenciasEntrega.dias.length > 0 || preferenciasEntrega.turnos.length > 0 || preferenciasEntrega.obs) ? 'border-amber-400 bg-amber-50 text-amber-700 hover:bg-amber-100 hover:text-amber-800' : ''}`}
                    >
                      <span className="flex items-center gap-2">
                        <Calendar className="w-4 h-4" />
                        Preferências de Entrega / Restrições
                      </span>
                      {(preferenciasEntrega.dias.length > 0 || preferenciasEntrega.turnos.length > 0 || preferenciasEntrega.obs) && (
                        <Badge variant="secondary" className="bg-amber-200 text-amber-800 border-amber-300 hover:bg-amber-200">
                          Definido
                        </Badge>
                      )}
                    </Button>
                  </div>
                )}

                {/* Modal de Preferências */}
                <Dialog open={modalPreferenciasOpen} onOpenChange={setModalPreferenciasOpen}>
                  <DialogContent className="sm:max-w-[425px]">
                    <DialogHeader>
                      <DialogTitle>Restrições de Entrega</DialogTitle>
                      <DialogDescription>
                        Informe quando o cliente <strong>PODE</strong> receber.
                      </DialogDescription>
                    </DialogHeader>
                    <div className="grid gap-4 py-4">
                      <div className="space-y-3">
                        <Label>Dias da Semana Permitidos</Label>
                        <div className="grid grid-cols-4 gap-2">
                          {['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'].map((dia, idx) => (
                            <RestricaoCheckbox
                              key={idx}
                              label={dia}
                              checked={preferenciasEntrega.dias.includes(idx)} // 0=Dom, 1=Seg, ..., 6=Sab

                              onCheckedChange={(checked) => {
                                setPreferenciasEntrega(prev => ({
                                  ...prev,
                                  dias: checked
                                    ? [...prev.dias, idx]
                                    : prev.dias.filter(d => d !== idx)
                                }));

                              }}
                            />
                          ))}
                        </div>
                      </div>

                      <div className="space-y-3">
                        <Label>Turnos Permitidos</Label>
                        <div className="grid grid-cols-2 gap-2">
                          {['Manhã', 'Tarde'].map((turno) => (
                            <RestricaoCheckbox
                              key={turno}
                              label={turno}
                              checked={preferenciasEntrega.turnos.includes(turno)}
                              onCheckedChange={(checked) => {
                                setPreferenciasEntrega(prev => {
                                  let newTurnos = checked
                                    ? [...prev.turnos, turno]
                                    : prev.turnos.filter(t => t !== turno);
                                  if (newTurnos.includes('Manhã') && newTurnos.includes('Tarde')) {
                                    if (!newTurnos.includes('Comercial')) {
                                      newTurnos.push('Comercial');
                                    }
                                  } else {
                                    newTurnos = newTurnos.filter(t => t !== 'Comercial');
                                  }
                                  return {
                                    ...prev,
                                    turnos: newTurnos
                                  };
                                });
                              }}
                            />
                          ))}
                        </div>
                      </div>

                      <div className="space-y-2">
                        <Label>Observação da Restrição</Label>
                        <Textarea
                          placeholder="Ex: Porteiro recebe, ou ligar antes..."
                          value={preferenciasEntrega.obs}
                          onChange={(e) => setPreferenciasEntrega(prev => ({ ...prev, obs: e.target.value }))}
                        />
                      </div>
                    </div>
                    <DialogFooter>
                      <Button onClick={() => setModalPreferenciasOpen(false)}>Confirmar</Button>
                    </DialogFooter>
                  </DialogContent>
                </Dialog>
              </div>
              <div className="bg-gray-100 dark:bg-neutral-800/50 rounded-xl p-3">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-xs text-gray-500">{itens.length} itens no carrinho</p>
                  </div>
                  <p className="text-lg font-bold text-green-700">R$ {subtotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                </div>
              </div>
            </div>
          )}

          {etapa === 3 && (
            <div className={`space-y-4 h-full ${etapa === 3 ? 'flex flex-col' : ''}`}>
              <PainelPagamento
                valores={{ subtotal, total, pago: totalPago, restante }}
                pagamentos={pagamentos}
                onAddPagamento={p => setPagamentos([...pagamentos, p])}
                onRemovePagamento={i => setPagamentos(pagamentos.filter((_, idx) => idx !== i))}
                onFinalizar={handleFinalizar}
                onOrcamento={handleOrcamento}
                loading={loading}
                savingOrcamento={savingOrcamento}
                desconto={desconto}
                setDesconto={setDesconto}
                observacoes={observacoes}
                setObservacoes={setObservacoes}
                pagamentoEntrega={pagamentoEntrega}
                setPagamentoEntrega={setPagamentoEntrega}
                disabled={!clienteSelecionado || itens.length === 0 || (!todosRetiram && !configVenda.prazo)}
                cupomAplicado={cupomAplicado}
                setCupomAplicado={setCupomAplicado}
                cliente={clienteSelecionado}
                itensCount={itens.length}
                prazo={configVenda.prazo}
                tokenGerencial={tokenGerencial}
                setTokenGerencial={setTokenGerencial}
                margemNegociavel={margemNegociavel}
                onDescontoMargemChange={(percent) => setDescontoMargemPercent(percent)}
                vendas={vendas}
                itens={itens}
                onAtualizarItem={handleAtualizarItem}
                descontoMaxProduto={descontoMaxProduto}
                isProdutoComDesconto={isProdutoComDesconto}
              />
            </div>
          )}
        </div>
      </div>

      <footer className="h-16 bg-white dark:bg-neutral-900 border-t border-gray-200 dark:border-neutral-800 px-4 flex-shrink-0 flex items-center justify-between">
        {etapa > 1 ? (
          <Button variant="outline" size="sm" onClick={voltarEtapa} className="gap-1.5 h-10">
            <ArrowLeft className="w-4 h-4" />
            Voltar
          </Button>
        ) : (
          <div />
        )}
        <div className="flex items-center gap-3">
          <div className="text-right">
            <p className="text-xs text-gray-500">{itens.length} itens</p>
            <p className="font-bold text-base text-green-700">R$ {subtotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
          </div>
          {etapa < 3 && (
            <div className="flex flex-col items-end gap-1">
              <Button
                onClick={avancarEtapa}
                disabled={!podeAvancar()}
                className="gap-1.5 bg-green-600 hover:bg-green-700 h-10 px-6"
              >
                Avançar
                <ArrowRight className="w-4 h-4" />
              </Button>
              {!podeAvancar() && getMotivoBloqueioBotao() && (
                <span className="text-sm text-red-500 font-medium animate-pulse">
                  {getMotivoBloqueioBotao()}
                </span>
              )}
            </div>
          )}
        </div>
      </footer>

      {/* Modal de Edição Rápida */}
      {isEditModalOpen && editingProdutoPDV && (
        <ProdutoQuickEditModal
          isOpen={isEditModalOpen}
          onClose={() => setIsEditModalOpen(false)}
          produto={editingProdutoPDV}
          onSave={handleSaveEditProdutoPDV}
        />
      )}

      <Dialog
        open={origemRetiradaModalOpen}
        onOpenChange={(open) => {
          if (!open) {
            cancelarOrigemRetiradaItem();
            return;
          }
          setOrigemRetiradaModalOpen(true);
        }}
      >
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Origem da retirada</DialogTitle>
            <DialogDescription>
              Este produto possui estoque em mais de um local. Selecione de onde sera retirado.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-2">
            <Label htmlFor="origem-retirada-item">Origem do estoque</Label>
            <Select value={origemSelecionadaCampo} onValueChange={setOrigemSelecionadaCampo}>
              <SelectTrigger id="origem-retirada-item">
                <SelectValue placeholder="Selecione a origem" />
              </SelectTrigger>
              <SelectContent>
                {opcoesOrigemPendente.map((opcao) => (
                  <SelectItem key={opcao.campo} value={opcao.campo}>
                    {opcao.nome} ({opcao.quantidade} un)
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={cancelarOrigemRetiradaItem}>Cancelar</Button>
            <Button onClick={confirmarOrigemRetiradaItem} disabled={!origemSelecionadaCampo}>Confirmar</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { ShieldAlert, Trash2, Search, Building2, Activity, Users, MoreVertical, XCircle, FileText, Key, Lock, Unlock, Mail, Footprints, Sliders, CheckCircle2 } from "lucide-react";
import { supabase } from "@/lib/supabase";
import { toast } from "sonner";
import { SYSTEM_MODULES, MODULE_CATEGORIES } from "@/config/modules";
import { Switch } from "@/components/ui/switch";

import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

export default function PainelSaaSOperadorEmpresas() {
  const [organizations, setOrganizations] = useState([]);
  const [planos, setPlanos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [usageData, setUsageData] = useState({});

  // States for Modals
  const [selectedOrg, setSelectedOrg] = useState(null);
  const [isOverrideModalOpen, setIsOverrideModalOpen] = useState(false);
  const [isDetailsModalOpen, setIsDetailsModalOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [isAccessModalOpen, setIsAccessModalOpen] = useState(false);
  
  // Access Modal States
  const [selectedOrgUsers, setSelectedOrgUsers] = useState([]);
  const [loadingUsers, setLoadingUsers] = useState(false);
  const [userSearchTerm, setUserSearchTerm] = useState("");

  // Footsteps Modal States
  const [activeFootstepsUser, setActiveFootstepsUser] = useState(null);
  const [isFootstepsModalOpen, setIsFootstepsModalOpen] = useState(false);

  // Org Footsteps Feed States
  const [isOrgFootstepsModalOpen, setIsOrgFootstepsModalOpen] = useState(false);
  const [orgFootsteps, setOrgFootsteps] = useState([]);
  const [loadingOrgFootsteps, setLoadingOrgFootsteps] = useState(false);

  // Override Form
  const [overridePlanId, setOverridePlanId] = useState("");
  const [overrideReason, setOverrideReason] = useState("");
  const [isOverriding, setIsOverriding] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  // Modules Modal States
  const [isModulesModalOpen, setIsModulesModalOpen] = useState(false);
  const [modulesState, setModulesState] = useState({});
  const [savingModules, setSavingModules] = useState(false);


  const fetchData = async () => {
    setLoading(true);
    try {
      const [orgsRes, planosRes, usageRes] = await Promise.all([
        supabase.from("organizations").select(`
          id, name, plano_id, status_assinatura, asaas_customer_id, asaas_subscription_id, created_at, deleted_at,
          organization_settings ( modulos_ativos )
        `).order("created_at", { ascending: false }),
        supabase.from("planos").select("*").order("preco_mensal", { ascending: true }),
        supabase.from("saas_tenant_daily_usage").select("organization_id, active_users, total_events")
      ]);

      if (orgsRes.error) throw orgsRes.error;
      if (planosRes.error) throw planosRes.error;
      
      // Aggregate usage data by organization
      const usageMap = {};
      if (usageRes.data) {
        usageRes.data.forEach(row => {
          if (!usageMap[row.organization_id]) {
            usageMap[row.organization_id] = { active_users: 0, total_events: 0 };
          }
          usageMap[row.organization_id].active_users += row.active_users || 0;
          usageMap[row.organization_id].total_events += row.total_events || 0;
        });
      }

      setOrganizations(orgsRes.data || []);
      setPlanos(planosRes.data || []);
      setUsageData(usageMap);
    } catch (error) {
      console.error("Erro ao carregar dados:", error);
      toast.error("Falha ao carregar empresas.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const openOverrideModal = (org) => {
    setSelectedOrg(org);
    setOverridePlanId(org.plano_id || "");
    setOverrideReason("");
    setIsOverrideModalOpen(true);
  };

  const openDetailsModal = (org) => {
    setSelectedOrg(org);
    setIsDetailsModalOpen(true);
  };

  const openDeleteModal = (org) => {
    setSelectedOrg(org);
    setIsDeleteModalOpen(true);
  };

  const openAccessModal = async (org) => {
    setSelectedOrg(org);
    setUserSearchTerm("");
    setIsAccessModalOpen(true);
    setLoadingUsers(true);
    try {
      const { data, error } = await supabase.rpc('operator_get_organization_users', {
        p_org_id: org.id
      });
      if (error) throw error;
      setSelectedOrgUsers(data || []);
    } catch (err) {
      toast.error("Erro ao carregar usuários.");
      console.error(err);
    } finally {
      setLoadingUsers(false);
    }
  };

  const openOrgFootstepsModal = async (org) => {
    setSelectedOrg(org);
    setIsOrgFootstepsModalOpen(true);
    setLoadingOrgFootsteps(true);
    try {
      const { data, error } = await supabase.rpc('operator_get_organization_users', {
        p_org_id: org.id
      });
      if (error) throw error;
      
      let allFootsteps = [];
      if (data) {
        data.forEach(user => {
          if (user.last_footsteps && Array.isArray(user.last_footsteps)) {
            user.last_footsteps.forEach(step => {
              allFootsteps.push({
                ...step,
                userName: user.nome,
                userEmail: user.email
              });
            });
          }
        });
      }
      
      // Sort by timestamp descending (newest first)
      allFootsteps.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));
      setOrgFootsteps(allFootsteps);
    } catch (err) {
      toast.error("Erro ao carregar atividades.");
      console.error(err);
    } finally {
      setLoadingOrgFootsteps(false);
    }
  };

  const openModulesModal = (org) => {
    setSelectedOrg(org);
    const modulosNoBanco = org?.organization_settings?.[0]?.modulos_ativos || {};
    const initialMap = {};

    SYSTEM_MODULES.forEach(mod => {
      if (Object.prototype.hasOwnProperty.call(modulosNoBanco, mod.key)) {
        initialMap[mod.key] = modulosNoBanco[mod.key] !== false;
      } else {
        initialMap[mod.key] = mod.defaultActive;
      }
    });

    setModulesState(initialMap);
    setIsModulesModalOpen(true);
  };

  const handleSaveModules = async () => {
    try {
      setSavingModules(true);
      const { error } = await supabase
        .from('organization_settings')
        .upsert(
          {
            organization_id: selectedOrg.id,
            modulos_ativos: modulesState,
            updated_at: new Date().toISOString()
          },
          { onConflict: 'organization_id' }
        );

      if (error) throw error;

      toast.success(`Módulos da empresa ${selectedOrg.name} atualizados com sucesso!`);
      setIsModulesModalOpen(false);
      fetchData();
    } catch (err) {
      console.error("Erro ao salvar módulos do tenant:", err);
      toast.error("Falha ao salvar módulos: " + (err.message || err));
    } finally {
      setSavingModules(false);
    }
  };


  const handleOverrideSubmit = async (e) => {
    e.preventDefault();
    if (!overrideReason) {
      toast.error("O motivo é obrigatório para auditoria.");
      return;
    }

    setIsOverriding(true);
    try {
      const { data: authData } = await supabase.auth.getUser();
      
      const { data, error } = await supabase.rpc('operator_override_subscription', {
        p_organization_id: selectedOrg.id,
        p_new_plano_id: overridePlanId || null,
        p_reason: overrideReason,
        p_operator_id: authData?.user?.id
      });

      if (error) throw error;

      toast.success("Assinatura alterada com sucesso!");
      setIsOverrideModalOpen(false);
      fetchData();
    } catch (err) {
      console.error(err);
      toast.error(err.message || "Erro ao realizar override.");
    } finally {
      setIsOverriding(false);
    }
  };

  const handleCancelPlan = async (org) => {
    if (!confirm(`Tem certeza que deseja FINALIZAR o plano da empresa ${org.name}? Eles perderão acesso premium.`)) return;
    
    try {
      const { error } = await supabase
        .from('organizations')
        .update({ status_assinatura: 'cancelada' })
        .eq('id', org.id);
        
      if (error) throw error;
      toast.success("Plano finalizado.");
      fetchData();
    } catch (err) {
      toast.error("Erro ao finalizar plano.");
    }
  };

  const handleDeleteCompany = async () => {
    setIsDeleting(true);
    try {
      // Agenda a exclusão (Soft Delete temporário de 90 dias)
      const { error } = await supabase.rpc('schedule_organization_deletion', {
        p_org_id: selectedOrg.id
      });

      if (error) throw error;
      toast.success("Empresa agendada para exclusão (90 dias).");
      setIsDeleteModalOpen(false);
      fetchData();
    } catch (err) {
      console.error(err);
      toast.error(err.message || "Erro ao agendar exclusão.");
    } finally {
      setIsDeleting(false);
    }
  };

  const handleRestoreCompany = async (org) => {
    try {
      const { error } = await supabase.rpc('restore_organization', {
        p_org_id: org.id
      });

      if (error) throw error;
      toast.success("Empresa restaurada com sucesso!");
      fetchData();
    } catch (err) {
      console.error(err);
      toast.error("Erro ao restaurar empresa.");
    }
  };

  const handleToggleUserStatus = async (userId, currentStatus) => {
    try {
      const newStatus = !currentStatus;
      const { error } = await supabase.rpc('operator_toggle_user_status', {
        p_user_id: userId,
        p_ativo: newStatus
      });
      
      if (error) throw error;
      toast.success(newStatus ? "Usuário desbloqueado." : "Usuário bloqueado com sucesso.");
      
      // Update local state
      setSelectedOrgUsers(prev => prev.map(u => u.id === userId ? { ...u, ativo: newStatus } : u));
    } catch (err) {
      toast.error("Erro ao alterar status do usuário.");
      console.error(err);
    }
  };

  const handleResetPassword = async (email) => {
    if(!email) return toast.error("Usuário sem e-mail cadastrado.");
    if(!confirm(`Enviar link de redefinição de senha para ${email}?`)) return;

    try {
      const { error } = await supabase.auth.resetPasswordForEmail(email, {
        redirectTo: window.location.origin + '/nova-senha',
      });
      if (error) throw error;
      toast.success("E-mail de recuperação enviado!");
    } catch (err) {
      toast.error("Erro ao enviar e-mail de recuperação.");
      console.error(err);
    }
  };

  const filteredUsers = selectedOrgUsers.filter(user => {
    const term = userSearchTerm.toLowerCase();
    return (
      (user.nome?.toLowerCase().includes(term)) ||
      (user.email?.toLowerCase().includes(term)) ||
      (user.cargo?.toLowerCase().includes(term)) ||
      (user.matricula?.toLowerCase().includes(term))
    );
  });

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-slate-900">Gestão de Empresas (Tenants)</h1>
        <p className="text-slate-600 mt-1">Visualize telemetria e controle o acesso de todas as empresas clientes.</p>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        {loading ? (
          <div className="p-8 text-center text-slate-500">Carregando empresas...</div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
              <thead className="bg-slate-50 border-b border-slate-200 text-xs uppercase font-semibold text-slate-600">
                <tr>
                  <th className="px-4 py-3">Organização</th>
                  <th className="px-4 py-3">Plano Atual</th>
                  <th className="px-4 py-3">Status</th>
                  <th className="px-4 py-3 text-right">Usuários Ativos</th>
                  <th className="px-4 py-3 text-right">Tráfego (Eventos)</th>
                  <th className="px-4 py-3 text-right">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {organizations.map(org => {
                  const plano = planos.find(p => p.id === org.plano_id);
                  const usage = usageData[org.id] || { active_users: 0, total_events: 0 };
                  
                  return (
                    <tr key={org.id} className="hover:bg-slate-50/50">
                      <td className="px-4 py-3 font-medium text-slate-900 flex items-center gap-2">
                        <Building2 className="w-4 h-4 text-slate-400" />
                        {org.name}
                      </td>
                      <td className="px-4 py-3">
                        {plano ? plano.nome : <span className="text-slate-400">Sem Plano</span>}
                      </td>
                      <td className="px-4 py-3">
                        {org.deleted_at ? (
                          <span className="inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium bg-red-100 text-red-800">
                            Exclusão Agendada
                          </span>
                        ) : (
                          <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${
                            org.status_assinatura === 'ativa' ? 'bg-emerald-100 text-emerald-800' :
                            org.status_assinatura === 'cancelada' ? 'bg-red-100 text-red-800' :
                            'bg-amber-100 text-amber-800'
                          }`}>
                            {org.status_assinatura || 'inativa'}
                          </span>
                        )}
                      </td>
                      <td className="px-4 py-3 text-right text-slate-600 font-mono">
                        {usage.active_users}
                      </td>
                      <td className="px-4 py-3 text-right text-slate-600 font-mono">
                        {usage.total_events}
                      </td>
                      <td className="px-4 py-3 text-right">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <button className="p-1.5 hover:bg-slate-100 rounded-md text-slate-500 transition-colors">
                              <MoreVertical className="w-4 h-4" />
                            </button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end" className="w-48">
                            <DropdownMenuLabel>Ações da Empresa</DropdownMenuLabel>
                            <DropdownMenuItem onClick={() => openDetailsModal(org)}>
                              <FileText className="w-4 h-4 mr-2" /> Ficha Completa
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => openModulesModal(org)}>
                              <Sliders className="w-4 h-4 mr-2 text-purple-600" /> Módulos & Recursos
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => openOrgFootstepsModal(org)}>
                              <Activity className="w-4 h-4 mr-2 text-blue-600" /> Feed de Atividades
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => openAccessModal(org)}>
                              <Key className="w-4 h-4 mr-2 text-indigo-600" /> Gerenciar Acessos
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => openOverrideModal(org)}>
                              <ShieldAlert className="w-4 h-4 mr-2 text-amber-600" /> Override de Plano
                            </DropdownMenuItem>
                            <DropdownMenuSeparator />
                            {org.deleted_at ? (
                              <DropdownMenuItem onClick={() => handleRestoreCompany(org)} className="text-emerald-600 focus:text-emerald-600 focus:bg-emerald-50">
                                <Activity className="w-4 h-4 mr-2" /> Restaurar Empresa
                              </DropdownMenuItem>
                            ) : (
                              <>
                                <DropdownMenuItem onClick={() => handleCancelPlan(org)}>
                                  <XCircle className="w-4 h-4 mr-2 text-orange-600" /> Finalizar Plano
                                </DropdownMenuItem>
                                <DropdownMenuItem onClick={() => openDeleteModal(org)} className="text-red-600 focus:text-red-600 focus:bg-red-50">
                                  <Trash2 className="w-4 h-4 mr-2" /> Excluir Empresa
                                </DropdownMenuItem>
                              </>
                            )}
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </td>
                    </tr>
                  );
                })}
                {organizations.length === 0 && (
                  <tr>
                    <td colSpan="6" className="px-4 py-8 text-center text-slate-500">Nenhuma empresa encontrada.</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Override Modal */}
      <Dialog open={isOverrideModalOpen} onOpenChange={setIsOverrideModalOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-amber-800">
              <ShieldAlert className="w-5 h-5" /> Override de Assinatura
            </DialogTitle>
            <DialogDescription>
              Alterar forçadamente a assinatura de <strong>{selectedOrg?.name}</strong>.
            </DialogDescription>
          </DialogHeader>

          <form onSubmit={handleOverrideSubmit} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Novo Plano</label>
              <select
                className="w-full border-slate-300 rounded-lg shadow-sm focus:border-amber-500 focus:ring-amber-500"
                value={overridePlanId}
                onChange={(e) => setOverridePlanId(e.target.value)}
              >
                <option value="">-- Remover Plano --</option>
                {planos.map(p => (
                  <option key={p.id} value={p.id}>{p.nome}</option>
                ))}
              </select>
            </div>
            
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Motivo (Obrigatório para Auditoria)</label>
              <textarea
                required
                className="w-full border-slate-300 rounded-lg shadow-sm focus:border-amber-500 focus:ring-amber-500"
                rows="3"
                value={overrideReason}
                onChange={(e) => setOverrideReason(e.target.value)}
                placeholder="Ex: Concessão especial, correção de cobrança, etc."
              />
            </div>

            <DialogFooter>
              <button type="button" className="px-4 py-2 text-sm font-medium text-slate-700 hover:bg-slate-100 rounded-lg" onClick={() => setIsOverrideModalOpen(false)}>
                Cancelar
              </button>
              <button type="submit" disabled={isOverriding} className="px-4 py-2 text-sm font-medium text-white bg-amber-600 hover:bg-amber-700 rounded-lg disabled:opacity-50">
                {isOverriding ? "Aplicando..." : "Confirmar Override"}
              </button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* Delete Modal */}
      <Dialog open={isDeleteModalOpen} onOpenChange={setIsDeleteModalOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-red-600">
              <Trash2 className="w-5 h-5" /> Excluir Empresa
            </DialogTitle>
            <DialogDescription>
              Você está prestes a excluir a empresa <strong>{selectedOrg?.name}</strong>.
              A empresa entrará na Lixeira (Agendada para Exclusão) e perderá o acesso imediato ao sistema.
              Após 90 dias, todos os dados serão apagados permanentemente de forma automática.
            </DialogDescription>
          </DialogHeader>

          <DialogFooter>
            <button type="button" className="px-4 py-2 text-sm font-medium text-slate-700 hover:bg-slate-100 rounded-lg" onClick={() => setIsDeleteModalOpen(false)}>
              Cancelar
            </button>
            <button type="button" onClick={handleDeleteCompany} disabled={isDeleting} className="px-4 py-2 text-sm font-medium text-white bg-red-600 hover:bg-red-700 rounded-lg disabled:opacity-50">
              {isDeleting ? "Agendando..." : "Mover para Lixeira (90 dias)"}
            </button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Details Modal */}
      <Dialog open={isDetailsModalOpen} onOpenChange={setIsDetailsModalOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Building2 className="w-5 h-5 text-slate-500" /> Ficha da Empresa: {selectedOrg?.name}
            </DialogTitle>
          </DialogHeader>
          
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="bg-slate-50 p-4 rounded-lg border border-slate-100">
                <p className="text-xs text-slate-500 uppercase font-semibold">ID do Tenant</p>
                <p className="text-sm font-mono text-slate-900 mt-1">{selectedOrg?.id}</p>
              </div>
              <div className="bg-slate-50 p-4 rounded-lg border border-slate-100">
                <p className="text-xs text-slate-500 uppercase font-semibold">Data de Criação</p>
                <p className="text-sm text-slate-900 mt-1">{new Date(selectedOrg?.created_at).toLocaleDateString()}</p>
              </div>
              <div className="bg-slate-50 p-4 rounded-lg border border-slate-100">
                <p className="text-xs text-slate-500 uppercase font-semibold">Cliente Asaas ID</p>
                <p className="text-sm font-mono text-slate-900 mt-1">{selectedOrg?.asaas_customer_id || 'Não vinculado'}</p>
              </div>
              <div className="bg-slate-50 p-4 rounded-lg border border-slate-100">
                <p className="text-xs text-slate-500 uppercase font-semibold">Assinatura Asaas ID</p>
                <p className="text-sm font-mono text-slate-900 mt-1">{selectedOrg?.asaas_subscription_id || 'Não vinculado'}</p>
              </div>
            </div>

            <div className="bg-slate-50 p-4 rounded-lg border border-slate-100">
              <p className="text-xs text-slate-500 uppercase font-semibold mb-2">Módulos Ativos (Configurações)</p>
              <pre className="text-xs bg-white p-2 rounded border border-slate-200 overflow-x-auto">
                {JSON.stringify(selectedOrg?.organization_settings?.[0]?.modulos_ativos || {}, null, 2)}
              </pre>
            </div>
            
            <div className="grid grid-cols-2 gap-4">
              <div className="bg-blue-50 p-4 rounded-lg border border-blue-100 flex items-center gap-3">
                <div className="p-2 bg-blue-100 text-blue-600 rounded-lg"><Users className="w-5 h-5" /></div>
                <div>
                  <p className="text-xs text-blue-600 uppercase font-semibold">Usuários Ativos</p>
                  <p className="text-xl font-bold text-blue-900">{usageData[selectedOrg?.id]?.active_users || 0}</p>
                </div>
              </div>
              <div className="bg-emerald-50 p-4 rounded-lg border border-emerald-100 flex items-center gap-3">
                <div className="p-2 bg-emerald-100 text-emerald-600 rounded-lg"><Activity className="w-5 h-5" /></div>
                <div>
                  <p className="text-xs text-emerald-600 uppercase font-semibold">Tráfego (Eventos)</p>
                  <p className="text-xl font-bold text-emerald-900">{usageData[selectedOrg?.id]?.total_events || 0}</p>
                </div>
              </div>
            </div>
          </div>

          <DialogFooter>
            <button type="button" className="px-4 py-2 text-sm font-medium text-slate-700 bg-slate-100 hover:bg-slate-200 rounded-lg" onClick={() => setIsDetailsModalOpen(false)}>
              Fechar
            </button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Modal Gerenciar Acessos */}
      <Dialog open={isAccessModalOpen} onOpenChange={setIsAccessModalOpen}>
        <DialogContent className="max-w-4xl">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Key className="w-5 h-5 text-indigo-500" /> Gerenciar Acessos: {selectedOrg?.name}
            </DialogTitle>
            <DialogDescription>
              Visualize, bloqueie ou envie redefinição de senhas para todos os usuários que têm acesso a este painel.
            </DialogDescription>
          </DialogHeader>

          <div className="relative mt-4">
            <Search className="absolute left-3 top-2.5 h-4 w-4 text-slate-400" />
            <input
              type="text"
              placeholder="Buscar por nome, email ou cargo..."
              value={userSearchTerm}
              onChange={(e) => setUserSearchTerm(e.target.value)}
              className="pl-9 w-full border-slate-200 rounded-lg shadow-sm focus:border-indigo-500 focus:ring-indigo-500 text-sm py-2"
            />
          </div>

          <div className="bg-white rounded-lg border border-slate-200 mt-4 overflow-x-auto overflow-y-auto max-h-[60vh]">
            {loadingUsers ? (
              <div className="p-8 text-center text-slate-500">Carregando acessos...</div>
            ) : (
              <table className="w-full text-sm text-left">
                <thead className="bg-slate-50 border-b text-xs uppercase text-slate-600">
                  <tr>
                    <th className="px-4 py-3">Nome / Cargo</th>
                    <th className="px-4 py-3">Matrícula</th>
                    <th className="px-4 py-3">Email</th>
                    <th className="px-4 py-3">Status</th>
                    <th className="px-4 py-3 text-right">Último Login</th>
                    <th className="px-4 py-3 text-right">Ações</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {filteredUsers.map(user => (
                    <tr key={user.id} className="hover:bg-slate-50">
                      <td className="px-4 py-3">
                        <div className="font-medium text-slate-900">{user.nome}</div>
                        <div className="text-xs text-slate-500">{user.cargo || 'Sem cargo'}</div>
                      </td>
                      <td className="px-4 py-3 font-mono text-xs text-slate-600">
                        {user.matricula || '-'}
                      </td>
                      <td className="px-4 py-3 text-slate-600">{user.email}</td>
                      <td className="px-4 py-3">
                        {user.ativo ? (
                          <span className="inline-flex px-2 py-0.5 rounded-full text-xs font-medium bg-emerald-100 text-emerald-800">Ativo</span>
                        ) : (
                          <span className="inline-flex px-2 py-0.5 rounded-full text-xs font-medium bg-red-100 text-red-800">Bloqueado</span>
                        )}
                      </td>
                      <td className="px-4 py-3 text-right text-slate-500 text-xs">
                        {user.ultimo_login ? new Date(user.ultimo_login).toLocaleString() : 'Nunca acessou'}
                      </td>
                      <td className="px-4 py-3 text-right">
                        <div className="flex justify-end gap-2">
                          <button 
                            onClick={() => {
                              setActiveFootstepsUser(user);
                              setIsFootstepsModalOpen(true);
                            }}
                            className="p-1.5 hover:bg-slate-200 rounded text-emerald-600" 
                            title="Ver Pegadas (Footsteps)"
                          >
                            <Footprints className="w-4 h-4" />
                          </button>
                          <button 
                            onClick={() => handleResetPassword(user.email)}
                            className="p-1.5 hover:bg-slate-200 rounded text-slate-600 tooltip-trigger" 
                            title="Enviar E-mail de Recuperação de Senha"
                          >
                            <Mail className="w-4 h-4" />
                          </button>
                          <button 
                            onClick={() => handleToggleUserStatus(user.id, user.ativo)}
                            className={`p-1.5 rounded transition-colors ${user.ativo ? 'hover:bg-red-100 text-red-600' : 'hover:bg-emerald-100 text-emerald-600'}`}
                            title={user.ativo ? "Bloquear Acesso" : "Desbloquear Acesso"}
                          >
                            {user.ativo ? <Lock className="w-4 h-4" /> : <Unlock className="w-4 h-4" />}
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                  {filteredUsers.length === 0 && (
                    <tr>
                      <td colSpan="6" className="px-4 py-8 text-center text-slate-500">Nenhum usuário encontrado.</td>
                    </tr>
                  )}
                </tbody>
              </table>
            )}
          </div>

          <DialogFooter className="mt-4">
            <button type="button" className="px-4 py-2 text-sm font-medium text-slate-700 bg-slate-100 hover:bg-slate-200 rounded-lg" onClick={() => setIsAccessModalOpen(false)}>
              Fechar
            </button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Modal de Pegadas (Telemetria) */}
      <Dialog open={isFootstepsModalOpen} onOpenChange={setIsFootstepsModalOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Footprints className="w-5 h-5 text-emerald-600" />
              Pegadas de: {activeFootstepsUser?.nome}
            </DialogTitle>
            <DialogDescription>
              Últimos passos e cliques deste usuário no sistema em tempo real.
            </DialogDescription>
          </DialogHeader>

          <div className="mt-4 space-y-4 max-h-[350px] overflow-y-auto pr-1">
            {!activeFootstepsUser?.last_footsteps || activeFootstepsUser.last_footsteps.length === 0 ? (
              <p className="text-sm text-slate-500 text-center py-6">Nenhuma atividade registrada recentemente.</p>
            ) : (
              <div className="relative border-l border-slate-200 ml-3 pl-4 space-y-4">
                {activeFootstepsUser.last_footsteps.map((step, idx) => (
                  <div key={idx} className="relative">
                    <span className="absolute -left-[21px] top-1.5 flex h-2.5 w-2.5 items-center justify-center rounded-full bg-emerald-500 ring-4 ring-white" />
                    <div className="flex flex-col">
                      <p className="text-sm font-medium text-slate-900">{step.action}</p>
                      <span className="text-xs text-slate-400 font-mono mt-0.5">{step.path}</span>
                      <span className="text-[10px] text-slate-500 mt-1">
                        {new Date(step.timestamp).toLocaleDateString()} às {new Date(step.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          <DialogFooter className="mt-4">
            <button 
              type="button" 
              className="px-4 py-2 text-sm font-medium text-slate-700 bg-slate-100 hover:bg-slate-200 rounded-lg" 
              onClick={() => setIsFootstepsModalOpen(false)}
            >
              Fechar
            </button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Modal Feed de Atividades da Organização */}
      <Dialog open={isOrgFootstepsModalOpen} onOpenChange={setIsOrgFootstepsModalOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Activity className="w-5 h-5 text-blue-600" />
              Feed de Atividades: {selectedOrg?.name}
            </DialogTitle>
            <DialogDescription>
              Linha do tempo consolidada com as últimas ações de todos os usuários desta empresa.
            </DialogDescription>
          </DialogHeader>

          <div className="mt-4 space-y-4 max-h-[500px] overflow-y-auto pr-2">
            {loadingOrgFootsteps ? (
              <div className="p-8 text-center text-slate-500">Carregando feed de atividades...</div>
            ) : orgFootsteps.length === 0 ? (
              <div className="p-8 text-center text-slate-500">Nenhuma atividade recente registrada nesta empresa.</div>
            ) : (
              <div className="relative border-l-2 border-slate-200 ml-4 pl-6 space-y-6">
                {orgFootsteps.map((step, idx) => (
                  <div key={idx} className="relative bg-slate-50 p-3 rounded-lg border border-slate-100 shadow-sm">
                    <span className="absolute -left-[31px] top-4 flex h-3 w-3 items-center justify-center rounded-full bg-blue-500 ring-4 ring-white" />
                    <div className="flex flex-col">
                      <div className="flex items-center justify-between">
                        <p className="text-sm font-semibold text-slate-900">{step.action}</p>
                        <span className="text-xs text-slate-500">
                          {new Date(step.timestamp).toLocaleDateString()} às {new Date(step.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        </span>
                      </div>
                      <span className="text-xs text-slate-400 font-mono mt-1">{step.path}</span>
                      <div className="mt-2 flex items-center gap-2 border-t border-slate-200 pt-2">
                        <div className="w-5 h-5 rounded-full bg-slate-200 flex items-center justify-center text-[10px] font-bold text-slate-600">
                          {step.userName ? step.userName.charAt(0).toUpperCase() : '?'}
                        </div>
                        <span className="text-xs font-medium text-slate-700">{step.userName || 'Usuário Desconhecido'}</span>
                        <span className="text-xs text-slate-400">({step.userEmail || 'Sem email'})</span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          <DialogFooter className="mt-4">
            <button 
              type="button" 
              className="px-4 py-2 text-sm font-medium text-slate-700 bg-slate-100 hover:bg-slate-200 rounded-lg" 
              onClick={() => setIsOrgFootstepsModalOpen(false)}
            >
              Fechar
            </button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Modal Operador SaaS: Gerenciador de Módulos */}
      <Dialog open={isModulesModalOpen} onOpenChange={setIsModulesModalOpen}>
        <DialogContent className="max-w-2xl max-h-[85vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-purple-900">
              <Sliders className="w-5 h-5 text-purple-600" />
              Módulos & Recursos: {selectedOrg?.name}
            </DialogTitle>
            <DialogDescription>
              Ative ou desative o acesso da empresa aos módulos do sistema. Alterações feitas pelo operador entram em vigor imediatamente.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-6 py-2">
            {MODULE_CATEGORIES.map(cat => {
              const modulesInCategory = SYSTEM_MODULES.filter(m => m.category === cat.key);
              return (
                <div key={cat.key} className="space-y-3">
                  <h4 className="text-xs uppercase font-bold tracking-wider text-slate-500 border-b pb-1">
                    {cat.label}
                  </h4>
                  <div className="space-y-2">
                    {modulesInCategory.map(mod => {
                      const isChecked = modulesState[mod.key] !== false;
                      return (
                        <div key={mod.key} className="flex items-center justify-between p-3 rounded-lg border border-slate-100 bg-slate-50/50 hover:bg-slate-50">
                          <div className="pr-4">
                            <p className="text-sm font-semibold text-slate-900">{mod.label}</p>
                            <p className="text-xs text-slate-500">{mod.description}</p>
                          </div>
                          <Switch
                            checked={isChecked}
                            onCheckedChange={(val) => setModulesState(prev => ({ ...prev, [mod.key]: val }))}
                          />
                        </div>
                      );
                    })}
                  </div>
                </div>
              );
            })}
          </div>

          <DialogFooter className="gap-2">
            <button
              type="button"
              className="px-4 py-2 text-sm font-medium text-slate-700 bg-slate-100 hover:bg-slate-200 rounded-lg"
              onClick={() => setIsModulesModalOpen(false)}
            >
              Cancelar
            </button>
            <button
              type="button"
              disabled={savingModules}
              onClick={handleSaveModules}
              className="px-4 py-2 text-sm font-medium text-white bg-purple-600 hover:bg-purple-700 rounded-lg disabled:opacity-50"
            >
              {savingModules ? "Salvando Módulos..." : "Salvar Módulos"}
            </button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { supabase } from "@/lib/supabase";
import { toast } from "sonner";
import { 
  Loader2, 
  Edit, 
  Plus, 
  Trash2, 
  LayoutGrid, 
  Table, 
  Sparkles, 
  Check, 
  Layers, 
  HelpCircle,
  ExternalLink,
  MessageCircle,
  Eye,
  CheckCircle2,
  X
} from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { SYSTEM_MODULES, MODULE_CATEGORIES } from "@/config/modules";
import PlanModulesDisplay from "@/components/planos/PlanModulesDisplay";

export default function PainelSaaSOperadorPlanos() {
  const [loading, setLoading] = useState(true);
  const [planos, setPlanos] = useState([]);
  const [submitting, setSubmitting] = useState(false);
  const [activeViewTab, setActiveViewTab] = useState("cards"); // 'cards' | 'table'

  // Edit/Create Plan State
  const [showPlanModal, setShowPlanModal] = useState(false);
  const [modalTab, setModalTab] = useState("design"); // 'design' | 'modules' | 'sync'
  const [isEditing, setIsEditing] = useState(false);

  const [planForm, setPlanForm] = useState({
    id: null,
    nome: "",
    preco_mensal: "",
    sem_valor: false,
    descricao: "",
    destaque: false,
    badge: "",
    botao_texto: "Comece Agora",
    botao_link: "",
    beneficios: [
      "Acesso via web em qualquer dispositivo",
      "Suporte especializado via WhatsApp",
      "Backups automáticos diários",
      "Módulos de PDV, Estoque e Logística"
    ],
    ativo: true,
    recursos: {},
    updateExisting: false,
    updateExistingModules: false
  });

  // Delete State
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [planToDelete, setPlanToDelete] = useState(null);

  useEffect(() => {
    fetchData();
  }, []);

  async function fetchData() {
    try {
      setLoading(true);

      const { data: planosData, error: planosError } = await supabase
        .from("planos")
        .select("*")
        .order("preco_mensal", { ascending: true });

      if (planosError) throw planosError;
      setPlanos(planosData || []);
    } catch (error) {
      console.error("Erro ao carregar dados:", error);
      toast.error("Falha ao carregar planos do sistema.");
    } finally {
      setLoading(false);
    }
  }

  // Módulos iniciais
  const getInitialPlanModules = (planoRecursos = {}) => {
    const map = {};
    SYSTEM_MODULES.forEach(mod => {
      if (Object.prototype.hasOwnProperty.call(planoRecursos, mod.key)) {
        map[mod.key] = planoRecursos[mod.key] !== false;
      } else {
        map[mod.key] = true;
      }
    });
    return map;
  };

  const handleOpenCreatePlan = () => {
    setIsEditing(false);
    setModalTab("design");
    setPlanForm({
      id: null,
      nome: "",
      preco_mensal: "",
      sem_valor: false,
      descricao: "",
      destaque: false,
      badge: "",
      botao_texto: "Comece Agora",
      botao_link: "",
      beneficios: [
        "Acesso via web em qualquer dispositivo",
        "Suporte especializado via WhatsApp",
        "Backups automáticos diários",
        "Módulos de PDV, Estoque e Logística"
      ],
      ativo: true,
      recursos: getInitialPlanModules({}),
      updateExisting: false,
      updateExistingModules: false
    });
    setShowPlanModal(true);
  };

  const handleOpenEditPlan = (plano) => {
    setIsEditing(true);
    setModalTab("design");
    const isCustom = !plano.preco_mensal || Number(plano.preco_mensal) === 0 || plano.recursos?.customizado || plano.recursos?.sob_consulta;

    const existingBeneficios = Array.isArray(plano.recursos?.beneficios) && plano.recursos.beneficios.length > 0
      ? plano.recursos.beneficios
      : (isCustom ? [
          "Módulos e recursos sob demanda",
          "Suporte prioritário e especializado",
          "Backups automáticos diários",
          "Implantação e onboarding dedicado"
        ] : [
          "Acesso via web em qualquer dispositivo",
          "Suporte especializado via WhatsApp",
          "Backups automáticos diários",
          "Módulos de PDV, Estoque e Logística"
        ]);

    setPlanForm({
      id: plano.id,
      nome: plano.nome || "",
      preco_mensal: isCustom ? "" : (plano.preco_mensal ?? "").toString(),
      sem_valor: !!isCustom,
      ordem: plano.recursos?.ordem ?? "",
      descricao: plano.recursos?.descricao || plano.descricao || (isCustom ? "Solução sob medida para o tamanho e fluxo da sua operação." : "Acesso completo aos módulos e recursos do GestApp."),
      destaque: !!plano.recursos?.destaque,
      badge: plano.recursos?.badge || plano.nome || "",
      botao_texto: plano.recursos?.botao_texto || (isCustom ? "Contate-nos" : "Comece Agora"),
      botao_link: plano.recursos?.botao_link || "",
      beneficios: existingBeneficios,
      ativo: plano.ativo ?? true,
      recursos: getInitialPlanModules(plano.recursos || {}),
      updateExisting: false,
      updateExistingModules: false
    });
    setShowPlanModal(true);
  };

  const handleToggleAtivo = async (plano) => {
    try {
      const novoStatus = !plano.ativo;
      const body = {
        action: 'update',
        planId: plano.id,
        nome: plano.nome,
        preco_mensal: plano.preco_mensal,
        ativo: novoStatus,
        recursos: plano.recursos || {}
      };

      const { data, error } = await supabase.functions.invoke('operator-update-plan', { body });
      if (error) throw error;
      if (data?.error) throw new Error(data.error);

      toast.success(novoStatus ? `Plano "${plano.nome}" agora está VISÍVEL na Landing Page!` : `Plano "${plano.nome}" foi OCULTADO da Landing Page.`);
      fetchData();
    } catch (err) {
      console.error("Erro ao alterar visibilidade:", err);
      toast.error(err.message || "Erro ao alterar visibilidade do plano.");
    }
  };

  const togglePlanModule = (moduleKey) => {
    setPlanForm(prev => ({
      ...prev,
      recursos: {
        ...prev.recursos,
        [moduleKey]: !prev.recursos?.[moduleKey]
      }
    }));
  };

  // Funções de edição de Benefícios (Checklist)
  const handleAddBeneficio = () => {
    setPlanForm(prev => ({
      ...prev,
      beneficios: [...prev.beneficios, ""]
    }));
  };

  const handleUpdateBeneficio = (index, value) => {
    setPlanForm(prev => {
      const updated = [...prev.beneficios];
      updated[index] = value;
      return { ...prev, beneficios: updated };
    });
  };

  const handleRemoveBeneficio = (index) => {
    setPlanForm(prev => ({
      ...prev,
      beneficios: prev.beneficios.filter((_, i) => i !== index)
    }));
  };

  const handlePlanSubmit = async (e) => {
    e.preventDefault();
    try {
      setSubmitting(true);

      const isCustom = !!planForm.sem_valor;
      let parsedPrice = 0;

      if (!isCustom) {
        parsedPrice = parseFloat(planForm.preco_mensal.toString().replace(',', '.'));
        if (isNaN(parsedPrice) || parsedPrice < 0) {
          throw new Error("Por favor, informe um preço mensal válido.");
        }
      }

      const filteredBeneficios = (planForm.beneficios || []).filter(b => typeof b === 'string' && b.trim().length > 0);

      const updatedRecursos = {
        ...planForm.recursos,
        descricao: planForm.descricao,
        destaque: !!planForm.destaque,
        badge: planForm.badge || planForm.nome,
        ordem: planForm.ordem !== "" ? Number(planForm.ordem) : undefined,
        botao_texto: planForm.botao_texto || (isCustom ? "Contate-nos" : "Comece Agora"),
        botao_link: planForm.botao_link,
        beneficios: filteredBeneficios,
        customizado: isCustom,
        sob_consulta: isCustom
      };

      const body = {
        action: isEditing ? 'update' : 'create',
        nome: planForm.nome,
        preco_mensal: parsedPrice,
        ativo: planForm.ativo,
        recursos: updatedRecursos
      };

      if (isEditing) {
        body.planId = planForm.id;
        body.update_existing = isCustom ? false : planForm.updateExisting;
        body.update_existing_modules = planForm.updateExistingModules;
      }

      const { data, error } = await supabase.functions.invoke('operator-update-plan', { body });

      if (error) throw error;
      if (data?.error) throw new Error(data.error);

      toast.success(data?.message || "Plano e Card salvos com sucesso!");
      if (data?.asaas_stats?.success > 0 || data?.asaas_stats?.errors > 0) {
         toast.info(`Atualizações no Asaas: ${data.asaas_stats?.success} sucessos, ${data.asaas_stats?.errors} erros.`);
      }

      setShowPlanModal(false);
      fetchData();
    } catch (error) {
      console.error("Erro ao salvar plano:", error);
      toast.error(error.message || "Erro ao salvar plano.");
    } finally {
      setSubmitting(false);
    }
  };

  const handleDeletePlan = async () => {
    if (!planToDelete) return;
    try {
      setSubmitting(true);
      const { data, error } = await supabase.functions.invoke('operator-update-plan', {
        body: { action: 'delete', planId: planToDelete.id }
      });

      if (error) throw error;
      if (data?.error) throw new Error(data.error);

      toast.success(data?.message || "Plano excluído com sucesso.");
      setShowDeleteModal(false);
      fetchData();
    } catch (error) {
      console.error("Erro ao excluir:", error);
      toast.error(error.message || "Falha ao excluir plano.");
    } finally {
      setSubmitting(false);
    }
  };

  const formatCurrency = (val) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val || 0);
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <Loader2 className="w-8 h-8 animate-spin text-emerald-700" />
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500 max-w-7xl mx-auto pb-12">
      {/* Header Superior */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-white p-6 rounded-2xl border border-slate-200/80 shadow-xs">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-slate-900 flex items-center gap-2">
            Gestão de Planos & Cards da Landing Page
          </h1>
          <p className="text-slate-500 text-sm mt-1">
            Edite em tempo real os títulos, preços, descrições, botões e benefícios exibidos nos cards do site.
          </p>
        </div>
        <div className="flex items-center gap-3">
          <Button onClick={handleOpenCreatePlan} className="bg-emerald-700 hover:bg-emerald-800 text-white font-medium shadow-sm cursor-pointer">
            <Plus className="w-4 h-4 mr-1.5" /> Novo Plano / Card
          </Button>
        </div>
      </div>

      {/* Seletor de Modo de Visualização */}
      <div className="flex items-center justify-between">
        <div className="flex items-center bg-slate-100 p-1 rounded-xl border border-slate-200">
          <button
            onClick={() => setActiveViewTab("cards")}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-semibold transition-all cursor-pointer ${
              activeViewTab === "cards"
                ? "bg-white text-slate-900 shadow-xs"
                : "text-slate-600 hover:text-slate-900"
            }`}
          >
            <LayoutGrid className="w-4 h-4 text-emerald-600" />
            Visualização dos Cards (Landing Page)
          </button>
          <button
            onClick={() => setActiveViewTab("table")}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-semibold transition-all cursor-pointer ${
              activeViewTab === "table"
                ? "bg-white text-slate-900 shadow-xs"
                : "text-slate-600 hover:text-slate-900"
            }`}
          >
            <Table className="w-4 h-4 text-slate-600" />
            Tabela Técnica & Módulos
          </button>
        </div>

        <span className="text-xs text-slate-400 font-medium">
          {planos.length} plano(s) configurado(s)
        </span>
      </div>

      {/* ABA 1: VISUALIZAÇÃO DOS CARDS (COMO APARECEM NA LANDING PAGE) */}
      {activeViewTab === "cards" && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {planos.map((plano, index) => {
              const isCustom = !plano.preco_mensal || Number(plano.preco_mensal) === 0 || plano.recursos?.customizado || plano.recursos?.sob_consulta;
              const isPopular = plano.recursos?.destaque !== undefined ? !!plano.recursos.destaque : (index === 1);
              const descricao = plano.recursos?.descricao || plano.descricao || (isCustom ? "Solução sob medida para o tamanho e fluxo da sua operação." : "Acesso completo aos módulos e recursos do GestApp.");
              const botaoTexto = plano.recursos?.botao_texto || (isCustom ? "Contate-nos" : "Comece Agora");

              const defaultBeneficios = isCustom ? [
                "Módulos e recursos sob demanda",
                "Suporte prioritário e especializado",
                "Backups automáticos diários",
                "Implantação e onboarding dedicado"
              ] : [
                "Acesso via web em qualquer dispositivo",
                "Suporte especializado via WhatsApp",
                "Backups automáticos diários",
                "Módulos de PDV, Estoque e Logística"
              ];

              const beneficios = Array.isArray(plano.recursos?.beneficios) && plano.recursos.beneficios.length > 0
                ? plano.recursos.beneficios
                : defaultBeneficios;

              return (
                <div 
                  key={plano.id} 
                  className={`bg-white rounded-[2rem] p-5 border transition-all duration-300 flex flex-col justify-between relative group ${
                    isPopular 
                      ? "border-emerald-300 shadow-[0_15px_45px_rgba(45,122,77,0.08)] ring-2 ring-emerald-500/10" 
                      : "border-slate-200/80 shadow-[0_10px_30px_rgba(0,0,0,0.03)] hover:shadow-md"
                  }`}
                >
                  <div className="space-y-5">
                    {/* Header do Card */}
                    <div className={`rounded-2xl p-5 transition-colors ${
                      isPopular 
                        ? "bg-[#e7f4ed] border border-[#ccebd5]" 
                        : "bg-slate-100/70 border border-slate-200/50"
                    }`}>
                      <div className="flex items-center justify-between gap-2">
                        <span className="inline-block px-3 py-1 bg-white text-slate-800 text-[11px] font-bold rounded-full tracking-wider uppercase shadow-2xs">
                          {plano.recursos?.badge || plano.nome}
                        </span>

                        <div className="flex items-center gap-1.5">
                          {isPopular && (
                            <span className="text-[10px] font-bold text-[#2d7a4d] uppercase tracking-wider mr-1">
                              Mais Escolhido
                            </span>
                          )}

                          {/* Botão de 1 Clique para Exibir / Ocultar da Landing Page */}
                          <button
                            type="button"
                            onClick={(e) => {
                              e.stopPropagation();
                              handleToggleAtivo(plano);
                            }}
                            className={`px-2.5 py-1 text-[10px] font-bold rounded-full transition-all cursor-pointer flex items-center gap-1 shadow-2xs ${
                              plano.ativo
                                ? "bg-emerald-600 hover:bg-red-600 text-white"
                                : "bg-gray-200 hover:bg-emerald-600 text-gray-700 hover:text-white"
                            }`}
                            title={plano.ativo ? "Atualmente VISÍVEL no site. Clique para Ocultar." : "Atualmente OCULTO do site. Clique para Exibir."}
                          >
                            {plano.ativo ? (
                              <>
                                <Eye className="w-3 h-3" />
                                Visível no Site
                              </>
                            ) : (
                              <>
                                <X className="w-3 h-3" />
                                Oculto do Site
                              </>
                            )}
                          </button>
                        </div>
                      </div>

                      {/* Preço */}
                      <div className="mt-5 flex items-baseline gap-1">
                        {isCustom ? (
                          <>
                            <span className="text-2xl sm:text-3xl font-extrabold text-slate-900 tracking-tight">
                              Sob Consulta
                            </span>
                            <span className="text-xs font-semibold text-slate-500">/personalizado</span>
                          </>
                        ) : (
                          <>
                            <span className="text-3xl sm:text-4xl font-extrabold text-slate-900 tracking-tight">
                              {formatCurrency(plano.preco_mensal)}
                            </span>
                            <span className="text-xs font-semibold text-slate-500">/mês</span>
                          </>
                        )}
                      </div>
                    </div>

                    {/* Descrição */}
                    <p className="text-xs sm:text-sm font-medium text-slate-700 px-1 min-h-[36px] leading-relaxed">
                      {descricao}
                    </p>

                    {/* Botão de Demonstração */}
                    <div className="px-1">
                      <button className="w-full py-3 bg-[#1b2a23] text-white text-xs font-semibold rounded-full shadow-xs opacity-95">
                        {botaoTexto}
                      </button>
                    </div>

                    {/* Checklist de Benefícios */}
                    <div className="pt-2 px-1 space-y-2.5 text-xs text-slate-600 border-t border-slate-100">
                      {beneficios.map((item, bIdx) => (
                        <div key={bIdx} className="flex items-center gap-2.5">
                          <Check className="w-3.5 h-3.5 text-emerald-600 flex-shrink-0" />
                          <span className="leading-tight">{item}</span>
                        </div>
                      ))}
                    </div>
                  </div>

                  {/* Barra de Ações Rápidas no Rodapé do Card */}
                  <div className="mt-6 pt-4 border-t border-slate-100 flex items-center justify-between gap-2">
                    <Button 
                      size="sm" 
                      onClick={() => handleOpenEditPlan(plano)} 
                      className="flex-1 bg-slate-900 hover:bg-slate-800 text-white text-xs font-semibold rounded-xl cursor-pointer"
                    >
                      <Edit className="w-3.5 h-3.5 mr-1.5" /> Editar Conteúdo do Card
                    </Button>
                    <Button 
                      size="sm" 
                      variant="outline" 
                      className="text-red-600 hover:bg-red-50 border-slate-200 rounded-xl px-3 cursor-pointer"
                      onClick={() => {
                        setPlanToDelete(plano);
                        setShowDeleteModal(true);
                      }}
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </Button>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* ABA 2: VISUALIZAÇÃO EM TABELA TÉCNICA */}
      {activeViewTab === "table" && (
        <Card className="border-slate-200/80 shadow-xs">
          <CardHeader>
            <CardTitle className="text-lg">Planos do Sistema & Módulos Inclusos</CardTitle>
            <CardDescription>Visão tabular de preços, permissões de módulos e assinaturas.</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="overflow-x-auto">
              <table className="w-full text-sm text-left">
                <thead className="text-xs text-slate-500 bg-slate-50 border-b uppercase">
                  <tr>
                    <th className="px-4 py-3">Plano</th>
                    <th className="px-4 py-3">Preço Mensal</th>
                    <th className="px-4 py-3">Status</th>
                    <th className="px-4 py-3">Destaque Site</th>
                    <th className="px-4 py-3">Módulos Inclusos</th>
                    <th className="px-4 py-3 text-right">Ações</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {planos.map(plano => {
                    const isCustom = !plano.preco_mensal || Number(plano.preco_mensal) === 0 || plano.recursos?.customizado || plano.recursos?.sob_consulta;
                    return (
                      <tr key={plano.id} className="hover:bg-slate-50/50">
                        <td className="px-4 py-3 font-semibold text-slate-900">{plano.nome}</td>
                        <td className="px-4 py-3">
                          {isCustom ? (
                            <span className="inline-flex items-center px-2.5 py-0.5 rounded text-xs font-semibold bg-blue-50 text-blue-700 border border-blue-200">
                              Sob Consulta
                            </span>
                          ) : (
                            <span className="font-semibold text-slate-900">
                              {formatCurrency(plano.preco_mensal)}
                            </span>
                          )}
                        </td>
                        <td className="px-4 py-3">
                          {plano.ativo ? (
                            <span className="px-2 py-0.5 text-xs font-semibold bg-emerald-100 text-emerald-800 rounded-md">Ativo</span>
                          ) : (
                            <span className="px-2 py-0.5 text-xs font-semibold bg-gray-100 text-gray-700 rounded-md">Inativo</span>
                          )}
                        </td>
                        <td className="px-4 py-3">
                          {plano.recursos?.destaque ? (
                            <span className="text-xs font-bold text-emerald-700 bg-emerald-50 px-2 py-0.5 rounded-md border border-emerald-200">
                              ★ Mais Escolhido
                            </span>
                          ) : (
                            <span className="text-xs text-slate-400">Padrão</span>
                          )}
                        </td>
                        <td className="px-4 py-3">
                          <PlanModulesDisplay recursos={plano.recursos} variant="compact" showDisabled={false} />
                        </td>

                        <td className="px-4 py-3 text-right">
                          <Button size="sm" variant="ghost" className="text-slate-600 hover:text-slate-900" onClick={() => handleOpenEditPlan(plano)}>
                            <Edit className="w-4 h-4" />
                          </Button>
                          <Button size="sm" variant="ghost" className="text-red-500 hover:text-red-700" onClick={() => {
                            setPlanToDelete(plano);
                            setShowDeleteModal(true);
                          }}>
                            <Trash2 className="w-4 h-4" />
                          </Button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </CardContent>
        </Card>
      )}

      {/* ========================================================================= */}
      {/* MODAL INTUITIVO DE EDIÇÃO / CRIAÇÃO DO CARD E PLANO */}
      {/* ========================================================================= */}
      <Dialog open={showPlanModal} onOpenChange={setShowPlanModal}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <form onSubmit={handlePlanSubmit}>
            <DialogHeader>
              <DialogTitle className="flex items-center gap-2 text-slate-900 text-lg">
                {isEditing ? <Edit className="w-5 h-5 text-emerald-700" /> : <Plus className="w-5 h-5 text-emerald-700" />}
                {isEditing ? `Editar Plano & Card: ${planForm.nome || "Novo"}` : "Criar Novo Plano / Card"}
              </DialogTitle>
              <DialogDescription>
                Personalize os dados de apresentação do card na Landing Page e configure os módulos do sistema.
              </DialogDescription>
            </DialogHeader>

            {/* Abas Internas do Modal */}
            <Tabs value={modalTab} onValueChange={setModalTab} className="mt-4">
              <TabsList className="grid grid-cols-3 w-full bg-slate-100 p-1 rounded-xl">
                <TabsTrigger value="design" className="text-xs font-semibold">
                  🎨 Conteúdo do Card
                </TabsTrigger>
                <TabsTrigger value="modules" className="text-xs font-semibold">
                  ⚙️ Módulos ERP
                </TabsTrigger>
                <TabsTrigger value="sync" className="text-xs font-semibold">
                  🔄 Propagação
                </TabsTrigger>
              </TabsList>

              {/* ABA 1: CONTEÚDO DO CARD NA LANDING PAGE */}
              <TabsContent value="design" className="space-y-4 pt-4">
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                  <div className="space-y-1.5 sm:col-span-1">
                    <Label htmlFor="planName" className="text-xs font-bold text-slate-700">Nome do Plano</Label>
                    <Input
                      id="planName"
                      value={planForm.nome}
                      onChange={(e) => setPlanForm({...planForm, nome: e.target.value})}
                      placeholder="Ex: Starter, Enterprise..."
                      required
                    />
                  </div>

                  <div className="space-y-1.5 sm:col-span-1">
                    <Label htmlFor="planBadge" className="text-xs font-bold text-slate-700">Tag / Badge do Topo</Label>
                    <Input
                      id="planBadge"
                      value={planForm.badge}
                      onChange={(e) => setPlanForm({...planForm, badge: e.target.value})}
                      placeholder="Ex: STARTER, POPULAR..."
                    />
                  </div>

                  <div className="space-y-1.5 sm:col-span-1">
                    <Label htmlFor="planOrdem" className="text-xs font-bold text-slate-700">Posição no Site (1, 2, 3)</Label>
                    <Input
                      id="planOrdem"
                      type="number"
                      min="1"
                      value={planForm.ordem}
                      onChange={(e) => setPlanForm({...planForm, ordem: e.target.value})}
                      placeholder="Ex: 1 para 1º card"
                    />
                  </div>
                </div>

                {/* Box de Preço & Customizado */}
                <div className="p-4 bg-slate-50 rounded-xl border border-slate-200/80 space-y-3">
                  <div className="flex items-center space-x-2">
                    <Checkbox 
                      id="planSemValor" 
                      checked={planForm.sem_valor}
                      onCheckedChange={(c) => setPlanForm({
                        ...planForm, 
                        sem_valor: !!c, 
                        preco_mensal: !!c ? "" : planForm.preco_mensal,
                        botao_texto: !!c ? "Contate-nos" : (planForm.botao_texto === "Contate-nos" ? "Comece Agora" : planForm.botao_texto)
                      })}
                    />
                    <label htmlFor="planSemValor" className="text-sm font-semibold text-slate-800 cursor-pointer">
                      Plano Customizado (Sob Consulta / Sem valor fixo)
                    </label>
                  </div>

                  {planForm.sem_valor ? (
                    <div className="bg-blue-50 border border-blue-200 rounded-lg p-3 text-xs text-blue-900 leading-relaxed">
                      <p className="font-semibold">✓ Modo Sob Consulta ativado:</p>
                      <p className="text-blue-700 mt-0.5">
                        O card exibirá <strong>"Sob Consulta / personalizado"</strong> e o botão <strong>"Contate-nos"</strong> direcionará o cliente para atendimento comercial.
                      </p>
                    </div>
                  ) : (
                    <div className="space-y-1.5 pt-1">
                      <Label htmlFor="planPrice" className="text-xs font-bold text-slate-700">Preço Mensal (R$)</Label>
                      <Input
                        id="planPrice"
                        type="number"
                        step="0.01"
                        min="0"
                        value={planForm.preco_mensal}
                        onChange={(e) => setPlanForm({...planForm, preco_mensal: e.target.value})}
                        placeholder="Ex: 299.90"
                        required={!planForm.sem_valor}
                      />
                    </div>
                  )}
                </div>

                {/* Descrição Curta */}
                <div className="space-y-1.5">
                  <Label htmlFor="planDesc" className="text-xs font-bold text-slate-700">Descrição Curta do Card</Label>
                  <Input
                    id="planDesc"
                    value={planForm.descricao}
                    onChange={(e) => setPlanForm({...planForm, descricao: e.target.value})}
                    placeholder="Ex: Ideal para pequenos comércios e lojas em fase de crescimento."
                  />
                </div>

                {/* Destaque e Botão */}
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 pt-1">
                  <div className="space-y-1.5">
                    <Label htmlFor="btnTexto" className="text-xs font-bold text-slate-700">Texto do Botão</Label>
                    <Input
                      id="btnTexto"
                      value={planForm.botao_texto}
                      onChange={(e) => setPlanForm({...planForm, botao_texto: e.target.value})}
                      placeholder="Ex: Comece Agora ou Contate-nos"
                    />
                  </div>

                  <div className="space-y-1.5">
                    <Label htmlFor="btnLink" className="text-xs font-bold text-slate-700">Link Personalizado (Opcional)</Label>
                    <Input
                      id="btnLink"
                      value={planForm.botao_link}
                      onChange={(e) => setPlanForm({...planForm, botao_link: e.target.value})}
                      placeholder="Ex: https://wa.me/55... ou /cadastro"
                    />
                  </div>
                </div>

                <div className="flex flex-col sm:flex-row gap-4 pt-2">
                  <div className="flex items-center space-x-2">
                    <Checkbox 
                      id="planDestaque" 
                      checked={planForm.destaque}
                      onCheckedChange={(c) => setPlanForm({...planForm, destaque: !!c})}
                    />
                    <label htmlFor="planDestaque" className="text-xs font-semibold text-slate-800 cursor-pointer">
                      Destacar este Plano (Fundo verde com tag "Mais Escolhido")
                    </label>
                  </div>

                  <div className="flex items-center space-x-2">
                    <Checkbox 
                      id="planActive" 
                      checked={planForm.ativo}
                      onCheckedChange={(c) => setPlanForm({...planForm, ativo: !!c})}
                    />
                    <label htmlFor="planActive" className="text-xs font-semibold text-slate-800 cursor-pointer">
                      Plano Ativo no Site
                    </label>
                  </div>
                </div>

                {/* EDITOR DE BENEFÍCIOS (CHECKLIST) */}
                <div className="space-y-2 pt-3 border-t border-slate-200">
                  <div className="flex items-center justify-between">
                    <Label className="text-xs font-bold text-slate-800 flex items-center gap-1.5">
                      <CheckCircle2 className="w-4 h-4 text-emerald-600" />
                      Linhas de Benefícios exibidas no Card (Checklist)
                    </Label>
                    <Button
                      type="button"
                      size="sm"
                      variant="outline"
                      onClick={handleAddBeneficio}
                      className="text-xs text-emerald-700 hover:bg-emerald-50 border-emerald-300 h-7"
                    >
                      <Plus className="w-3.5 h-3.5 mr-1" /> Adicionar Linha
                    </Button>
                  </div>

                  <div className="space-y-2">
                    {planForm.beneficios.map((beneficio, bIndex) => (
                      <div key={bIndex} className="flex items-center gap-2">
                        <Input
                          value={beneficio}
                          onChange={(e) => handleUpdateBeneficio(bIndex, e.target.value)}
                          placeholder={`Benefício #${bIndex + 1}`}
                          className="text-xs h-8"
                        />
                        <Button
                          type="button"
                          size="sm"
                          variant="ghost"
                          onClick={() => handleRemoveBeneficio(bIndex)}
                          className="text-red-500 hover:text-red-700 h-8 w-8 p-0 shrink-0"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </Button>
                      </div>
                    ))}
                  </div>
                </div>
              </TabsContent>

              {/* ABA 2: MÓDULOS DO SISTEMA ERP */}
              <TabsContent value="modules" className="space-y-4 pt-4">
                <div className="bg-slate-50 p-3 rounded-lg border border-slate-200 text-xs text-slate-600">
                  Selecione quais módulos do GestApp ficam desbloqueados para as empresas que assinarem este plano.
                </div>

                <div className="space-y-3 max-h-72 overflow-y-auto pr-1">
                  {MODULE_CATEGORIES.map(cat => {
                    const categoryModules = SYSTEM_MODULES.filter(m => m.category === cat.key);
                    return (
                      <div key={cat.key} className="space-y-2 bg-slate-50 p-3 rounded-xl border border-slate-200/80">
                        <p className="text-[11px] uppercase font-bold text-slate-600 tracking-wider">{cat.label}</p>
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                          {categoryModules.map(mod => {
                            const isChecked = planForm.recursos?.[mod.key] !== false;
                            return (
                              <div key={mod.key} className="flex items-center space-x-2 bg-white p-2 rounded-lg border border-slate-100">
                                <Checkbox
                                  id={`plan_mod_${mod.key}`}
                                  checked={isChecked}
                                  onCheckedChange={() => togglePlanModule(mod.key)}
                                />
                                <label htmlFor={`plan_mod_${mod.key}`} className="text-xs font-medium cursor-pointer text-slate-700">
                                  {mod.label}
                                </label>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </TabsContent>

              {/* ABA 3: SINCRONIZAÇÃO E PROPAGAÇÃO */}
              <TabsContent value="sync" className="space-y-4 pt-4">
                {isEditing ? (
                  <div className="flex flex-col gap-3 bg-blue-50 p-4 rounded-xl border border-blue-200">
                    <p className="text-xs font-bold text-blue-950 uppercase tracking-wider">
                      Propagação para Empresas Ativas
                    </p>
                    <div className="flex items-start space-x-2 pt-1">
                      <Checkbox 
                        id="updateExistingPrice" 
                        className="mt-1"
                        checked={planForm.updateExisting}
                        disabled={planForm.sem_valor}
                        onCheckedChange={(c) => setPlanForm({...planForm, updateExisting: !!c})}
                      />
                      <label htmlFor="updateExistingPrice" className="text-xs font-medium text-blue-900 cursor-pointer leading-relaxed">
                        Propagar NOVO PREÇO para a próxima fatura do Asaas das empresas ativas neste plano
                      </label>
                    </div>
                    <div className="flex items-start space-x-2">
                      <Checkbox 
                        id="updateExistingModules" 
                        className="mt-1"
                        checked={planForm.updateExistingModules}
                        onCheckedChange={(c) => setPlanForm({...planForm, updateExistingModules: !!c})}
                      />
                      <label htmlFor="updateExistingModules" className="text-xs font-medium text-blue-900 cursor-pointer leading-relaxed">
                        Propagar NOVOS MÓDULOS para as empresas ativas neste plano
                      </label>
                    </div>
                  </div>
                ) : (
                  <div className="bg-slate-50 p-4 rounded-xl text-xs text-slate-500">
                    Ao criar um novo plano, novas empresas cadastradas receberão as configurações definidas.
                  </div>
                )}
              </TabsContent>
            </Tabs>

            <DialogFooter className="mt-6 pt-4 border-t border-slate-100 flex items-center justify-between">
              <Button type="button" variant="outline" onClick={() => setShowPlanModal(false)} className="rounded-xl">
                Cancelar
              </Button>
              <Button type="submit" disabled={submitting} className="bg-emerald-700 hover:bg-emerald-800 text-white rounded-xl font-semibold cursor-pointer">
                {submitting && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
                Salvar Card & Plano
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* MODAL DE CONFIRMAÇÃO DE EXCLUSÃO */}
      <Dialog open={showDeleteModal} onOpenChange={setShowDeleteModal}>
        <DialogContent className="max-w-sm">
          <DialogHeader>
            <DialogTitle className="text-red-600">Excluir Plano</DialogTitle>
            <DialogDescription>
              Tem certeza que deseja excluir o plano <strong>{planToDelete?.nome}</strong>?
            </DialogDescription>
          </DialogHeader>
          <div className="py-2 text-xs text-slate-600 leading-relaxed">
            A exclusão só será permitida se nenhuma organização estiver vinculada a este plano.
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowDeleteModal(false)}>Cancelar</Button>
            <Button variant="destructive" onClick={handleDeletePlan} disabled={submitting}>
              {submitting ? <Loader2 className="w-4 h-4 animate-spin" /> : "Excluir"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useState } from "react";
import { base44 } from "@/api/base44Client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { toast } from "sonner";
import { Search, Settings, Package, Loader2, Save } from "lucide-react";

const TIPO_LABELS = {
  pronta_entrega:  { label: "Pronta Entrega", desc: "Bloqueia venda se sem estoque", color: "bg-red-100 text-red-700" },
  sob_encomenda:   { label: "Sob-Encomenda",  desc: "Sempre gera ordem de compra",  color: "bg-blue-100 text-blue-700" },
  flexivel:        { label: "Flexível",        desc: "Vende normal, sem estoque pede aprovação", color: "bg-green-100 text-green-700" },
  herdado:         { label: "Herdar fornecedor", desc: "Usa configuração do fornecedor", color: "bg-gray-100 text-gray-600" },
};

// ─── Linha editável de fornecedor ────────────────────────────────────────────
function FornecedorRow({ fornecedor, onSave, saving }) {
  const [draft, setDraft] = useState({
    tipo_estoque_padrao: fornecedor.tipo_estoque_padrao || "flexivel",
    aprovacao_obrigatoria: fornecedor.aprovacao_obrigatoria !== false,
    prazo_entrega_dias_padrao: fornecedor.prazo_entrega_dias_padrao ?? 15,
  });
  const dirty =
    draft.tipo_estoque_padrao !== (fornecedor.tipo_estoque_padrao || "flexivel") ||
    draft.aprovacao_obrigatoria !== (fornecedor.aprovacao_obrigatoria !== false) ||
    draft.prazo_entrega_dias_padrao !== (fornecedor.prazo_entrega_dias_padrao ?? 15);

  return (
    <div className="grid grid-cols-[2fr_1.5fr_1fr_auto_auto] gap-3 items-center py-3 px-4 border-b border-gray-100 hover:bg-gray-50/50">
      <div>
        <p className="text-sm font-medium text-gray-800">{fornecedor.nome_empresa}</p>
        <p className="text-xs text-gray-400">{fornecedor.cidade || "—"}</p>
      </div>

      <Select value={draft.tipo_estoque_padrao} onValueChange={v => setDraft(d => ({ ...d, tipo_estoque_padrao: v }))}>
        <SelectTrigger className="h-8 text-xs">
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {Object.entries(TIPO_LABELS)
            .filter(([k]) => k !== "herdado")
            .map(([value, { label }]) => (
              <SelectItem key={value} value={value} className="text-xs">{label}</SelectItem>
            ))}
        </SelectContent>
      </Select>

      <div className="flex items-center gap-2">
        <input
          type="number"
          min={1}
          max={120}
          className="w-16 border rounded px-2 py-1 text-xs"
          value={draft.prazo_entrega_dias_padrao}
          onChange={e => setDraft(d => ({ ...d, prazo_entrega_dias_padrao: Number(e.target.value) }))}
        />
        <span className="text-xs text-gray-400">dias</span>
      </div>

      <label className="flex items-center gap-1.5 cursor-pointer select-none">
        <input
          type="checkbox"
          checked={draft.aprovacao_obrigatoria}
          onChange={e => setDraft(d => ({ ...d, aprovacao_obrigatoria: e.target.checked }))}
          className="rounded"
        />
        <span className="text-xs text-gray-600 whitespace-nowrap">Exigir aprovação</span>
      </label>

      <Button
        size="sm"
        variant={dirty ? "default" : "ghost"}
        disabled={!dirty || saving}
        className="h-7 px-3 text-xs"
        onClick={() => onSave(fornecedor.id, draft)}
      >
        {saving ? <Loader2 className="w-3 h-3 animate-spin" /> : <Save className="w-3 h-3" />}
      </Button>
    </div>
  );
}

// ─── Linha editável de produto (override) ───────────────────────────────────
function ProdutoRow({ produto, onSave, saving }) {
  const [draft, setDraft] = useState({
    tipo_estoque: produto.tipo_estoque || "herdado",
    prazo_entrega_dias: produto.prazo_entrega_dias ?? "",
    requires_approval: produto.requires_approval,
  });
  const dirty =
    draft.tipo_estoque !== (produto.tipo_estoque || "herdado") ||
    draft.prazo_entrega_dias !== (produto.prazo_entrega_dias ?? "") ||
    draft.requires_approval !== produto.requires_approval;

  const tipoInfo = TIPO_LABELS[draft.tipo_estoque];

  return (
    <div className="grid grid-cols-[2.5fr_1.5fr_0.8fr_auto_auto] gap-3 items-center py-2.5 px-4 border-b border-gray-100 hover:bg-gray-50/50">
      <div>
        <p className="text-xs font-medium text-gray-800 truncate">{produto.nome}</p>
        <p className="text-xs text-gray-400">{produto.fornecedor_nome} · #{produto.id}</p>
      </div>

      <Select value={draft.tipo_estoque} onValueChange={v => setDraft(d => ({ ...d, tipo_estoque: v }))}>
        <SelectTrigger className="h-7 text-xs">
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {Object.entries(TIPO_LABELS).map(([value, { label }]) => (
            <SelectItem key={value} value={value} className="text-xs">{label}</SelectItem>
          ))}
        </SelectContent>
      </Select>

      <div className="flex items-center gap-1">
        <input
          type="number"
          min={1}
          max={365}
          placeholder="padrão"
          className="w-16 border rounded px-2 py-1 text-xs"
          value={draft.prazo_entrega_dias}
          onChange={e => setDraft(d => ({ ...d, prazo_entrega_dias: e.target.value ? Number(e.target.value) : "" }))}
        />
      </div>

      <label className="flex items-center gap-1 cursor-pointer">
        <input
          type="checkbox"
          checked={draft.requires_approval === true}
          onChange={e => setDraft(d => ({
            ...d,
            requires_approval: e.target.checked ? true : null
          }))}
          className="rounded"
        />
        <span className="text-xs text-gray-500 whitespace-nowrap">Override<br/>aprovação</span>
      </label>

      <Button
        size="sm"
        variant={dirty ? "default" : "ghost"}
        disabled={!dirty || saving}
        className="h-7 px-3 text-xs"
        onClick={() => onSave(produto.id, {
          tipo_estoque: draft.tipo_estoque,
          prazo_entrega_dias: draft.prazo_entrega_dias !== "" ? draft.prazo_entrega_dias : null,
          requires_approval: draft.requires_approval,
        })}
      >
        {saving ? <Loader2 className="w-3 h-3 animate-spin" /> : <Save className="w-3 h-3" />}
      </Button>
    </div>
  );
}

// ─── Página Principal ────────────────────────────────────────────────────────
export default function PoliticasEstoque() {
  const [searchForn, setSearchForn] = useState("");
  const [searchProd, setSearchProd] = useState("");
  const [savingId, setSavingId] = useState(null);
  const queryClient = useQueryClient();

  const { data: fornecedores = [], isLoading: loadingForn } = useQuery({
    queryKey: ["fornecedores"],
    queryFn: () => base44.entities.Fornecedor.list("nome_empresa"),
  });

  const { data: produtos = [], isLoading: loadingProd } = useQuery({
    queryKey: ["produtos-politicas"],
    queryFn: () => base44.entities.Produto.list("nome"),
    select: d => d.filter(p => p.ativo && p.tipo_estoque && p.tipo_estoque !== "herdado"),
    staleTime: 60000,
  });

  const saveFornMutation = useMutation({
    mutationFn: ({ id, data }) => base44.entities.Fornecedor.update(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["fornecedores"] });
      toast.success("Fornecedor atualizado");
      setSavingId(null);
    },
    onError: () => {
      toast.error("Erro ao salvar");
      setSavingId(null);
    },
  });

  const saveProdMutation = useMutation({
    mutationFn: ({ id, data }) => base44.entities.Produto.update(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["produtos-politicas"] });
      toast.success("Produto atualizado");
      setSavingId(null);
    },
    onError: () => {
      toast.error("Erro ao salvar");
      setSavingId(null);
    },
  });

  const fornsFiltrados = fornecedores.filter(f =>
    f.nome_empresa?.toLowerCase().includes(searchForn.toLowerCase())
  );

  const prodsFiltrados = produtos.filter(p =>
    p.nome?.toLowerCase().includes(searchProd.toLowerCase()) ||
    p.fornecedor_nome?.toLowerCase().includes(searchProd.toLowerCase())
  );

  return (
    <div className="p-6 max-w-6xl mx-auto space-y-6">
      <div className="flex items-center gap-3">
        <div className="p-2 rounded-lg bg-green-100">
          <Settings className="w-5 h-5 text-green-700" />
        </div>
        <div>
          <h1 className="text-xl font-bold text-gray-800">Políticas de Estoque</h1>
          <p className="text-sm text-gray-500">Configure como cada fornecedor/produto se comporta quando sem estoque</p>
        </div>
      </div>

      {/* Legenda */}
      <Card className="border-0 bg-gray-50">
        <CardContent className="py-3 px-4 flex flex-wrap gap-3">
          {Object.entries(TIPO_LABELS).map(([, { label, desc, color }]) => (
            <div key={label} className="flex items-center gap-2">
              <span className={`text-xs px-2 py-0.5 rounded font-medium ${color}`}>{label}</span>
              <span className="text-xs text-gray-500">{desc}</span>
            </div>
          ))}
        </CardContent>
      </Card>

      <Tabs defaultValue="fornecedores">
        <TabsList>
          <TabsTrigger value="fornecedores">Por Fornecedor (padrão)</TabsTrigger>
          <TabsTrigger value="produtos">Overrides por Produto</TabsTrigger>
        </TabsList>

        {/* ─── ABA FORNECEDORES ─── */}
        <TabsContent value="fornecedores" className="mt-4">
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base">Configuração por Fornecedor</CardTitle>
              <CardDescription className="text-xs">
                Define o comportamento padrão para todos os produtos do fornecedor. Produtos com override individual ignoram esta configuração.
              </CardDescription>
              <div className="relative mt-2">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <Input
                  placeholder="Buscar fornecedor..."
                  value={searchForn}
                  onChange={e => setSearchForn(e.target.value)}
                  className="pl-9 h-8 text-sm"
                />
              </div>
            </CardHeader>
            <CardContent className="p-0">
              {/* Cabeçalho */}
              <div className="grid grid-cols-[2fr_1.5fr_1fr_auto_auto] gap-3 px-4 py-2 bg-gray-100 text-xs text-gray-500 font-medium">
                <span>Fornecedor</span>
                <span>Política de estoque</span>
                <span>Prazo padrão</span>
                <span>Aprovação</span>
                <span></span>
              </div>
              {loadingForn ? (
                <div className="flex justify-center py-8"><Loader2 className="animate-spin text-gray-400" /></div>
              ) : (
                fornsFiltrados.map(f => (
                  <FornecedorRow
                    key={f.id}
                    fornecedor={f}
                    saving={savingId === f.id}
                    onSave={(id, data) => {
                      setSavingId(id);
                      saveFornMutation.mutate({ id, data });
                    }}
                  />
                ))
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* ─── ABA PRODUTOS ─── */}
        <TabsContent value="produtos" className="mt-4">
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base flex items-center gap-2">
                <Package className="w-4 h-4" /> Overrides por Produto
              </CardTitle>
              <CardDescription className="text-xs">
                Apenas produtos com configuração individual diferente de "herdado" aparecem aqui. Para configurar um produto, acesse o cadastro do produto e altere o campo "Política de Estoque".
              </CardDescription>
              <div className="relative mt-2">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <Input
                  placeholder="Buscar produto ou fornecedor..."
                  value={searchProd}
                  onChange={e => setSearchProd(e.target.value)}
                  className="pl-9 h-8 text-sm"
                />
              </div>
            </CardHeader>
            <CardContent className="p-0">
              <div className="grid grid-cols-[2.5fr_1.5fr_0.8fr_auto_auto] gap-3 px-4 py-2 bg-gray-100 text-xs text-gray-500 font-medium">
                <span>Produto</span>
                <span>Política individual</span>
                <span>Prazo (dias)</span>
                <span>Aprovação</span>
                <span></span>
              </div>
              {loadingProd ? (
                <div className="flex justify-center py-8"><Loader2 className="animate-spin text-gray-400" /></div>
              ) : prodsFiltrados.length === 0 ? (
                <div className="text-center py-10 text-sm text-gray-400">
                  Nenhum produto com configuração individual. Configure um produto editando o campo "Política de Estoque" no cadastro do produto.
                </div>
              ) : (
                prodsFiltrados.map(p => (
                  <ProdutoRow
                    key={p.id}
                    produto={p}
                    saving={savingId === p.id}
                    onSave={(id, data) => {
                      setSavingId(id);
                      saveProdMutation.mutate({ id, data });
                    }}
                  />
                ))
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

import React, { useState, useMemo, useEffect, useRef } from "react";
import { normSearch } from "@/lib/utils";
import { useSearchParams, useNavigate } from "react-router-dom";
import { base44 } from "@/api/base44Client";
import { useAuth } from "@/hooks/useAuth";
import { useTenant } from "@/contexts/TenantContext";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger, DropdownMenuSeparator } from "@/components/ui/dropdown-menu";
import {
  Search,
  Plus,
  MoreHorizontal,
  Edit,
  Trash2,
  Package,
  Filter,
  Grid3X3,
  List,
  Eye,
  Palette,
  Tag,
  AlertTriangle,
  CheckCircle,
  XCircle,
  Copy,
  Image as ImageIcon,
  Loader2,
  Upload,
  ChevronDown,
  ChevronUp,
  Ruler,
  ChevronLeft,
  ChevronRight,
  Layers
} from "lucide-react";
import { toast } from "sonner";
import { useConfirm } from "@/hooks/useConfirm";
import ProdutoCadastroCompleto from "@/components/produtos/ProdutoCadastroCompleto";
import ImportProdutosModal from "@/components/produtos/ImportProdutosModal";
import { formatDimensions, formatPrice } from "@/utils/productFormatters";
import { getColorHex } from "@/components/produtos/FurnitureColorPicker";
import { CATEGORIAS } from "@/constants/productConstants";
import ProductIncompleteIndicator from "@/components/produtos/ProductIncompleteIndicator";
import { getProductStockFields } from "@/utils/stockUtils";
import GeradorEtiquetasModal from "@/components/legacy_estoque/GeradorEtiquetasModal";
import { Printer } from "lucide-react";
import { useProdutoFilters } from "@/hooks/useProdutoFilters";

export default function Produtos() {
  const {
    searchTerm,
    setSearchTerm,
    debouncedSearch,
    selectedCategoria,
    setSelectedCategoria,
    selectedFabricante,
    setSelectedFabricante,
    selectedOrdenacao,
    setSelectedOrdenacao,
    selectedDirecao,
    setSelectedDirecao,
    filtroAtencao,
    setFiltroAtencao,
    categorias,
    produtosComAtencao,
    aplicarOrdenacao
  } = useProdutoFilters();
  // fabricantes é derivado localmente dos produtos resolvidos (ver useMemo abaixo)
  const [viewMode, setViewMode] = useState("grid"); // grid ou list
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 100;
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [editingProduto, setEditingProduto] = useState(null);
  const [modalMode, setModalMode] = useState('edit');
  const [savingProduto, setSavingProduto] = useState(false);
  const [pendingReturnUrl, setPendingReturnUrl] = useState(null);
  const [focusField, setFocusField] = useState(null);
  const [isGeradorEtiquetasOpen, setIsGeradorEtiquetasOpen] = useState(false);
  const [produtosParaEtiqueta, setProdutosParaEtiqueta] = useState([]);
  const handledHighlightRef = useRef('');
  const saveInFlightRef = useRef(false);
  const { user, loading, can } = useAuth();
  const { organization } = useTenant();

  const queryClient = useQueryClient();
  const confirm = useConfirm();

  const hasMeaningfulValue = (value) => {
    const normalized = String(value || '').trim().toLowerCase();
    return normalized && !['n/a', 'na', '-', 'null', 'undefined', '?'].includes(normalized);
  };

  const getDisplayDimensions = (produto) => {
    const dimensions = formatDimensions(produto.largura, produto.altura, produto.profundidade);
    return dimensions === '-' ? null : dimensions;
  };

  const shouldShowSize = (produto) => {
    if (!hasMeaningfulValue(produto.tamanho)) return false;
    const dimensoesCompactas = [produto.largura, produto.altura, produto.profundidade].filter(Boolean).join('x').toLowerCase();
    const tamanhoCompacto = String(produto.tamanho).replace(/\s+/g, '').toLowerCase();
    return !dimensoesCompactas || tamanhoCompacto !== dimensoesCompactas;
  };

  // Query 1: todos os produtos (sem filtro de fabricante — feito via useMemo abaixo)
  const { data: rawProdutos = [], isLoading } = useQuery({
    queryKey: ['produtos'],
    queryFn: async () => {
      const allProdutos = await base44.entities.Produto.list('nome');
      return allProdutos || [];
    },
  });

  // Query 2: fornecedores — mesma chave usada pelo OcModal, beneficia do cache compartilhado
  const { data: fornecedoresList = [] } = useQuery({
    queryKey: ['fornecedores'],
    queryFn: () => base44.entities.Fornecedor.list('nome_empresa'),
    staleTime: 1000 * 60 * 5,
  });

  // Mapa UUID → nome_empresa (fonte única de verdade)
  const fornecedoresById = useMemo(() => {
    return (fornecedoresList || []).reduce((acc, f) => {
      const id = String(f.id || '');
      const nome = String(f.nome_empresa || '').trim();
      if (id && nome) acc[id] = nome;
      return acc;
    }, {});
  }, [fornecedoresList]);

  // Produtos com nome do fornecedor resolvido (ID-first) e filtros de busca/categoria/atenção
  const { produtos, isFuzzy } = useMemo(() => {
    const mapped = (rawProdutos || []).map((p) => ({
      ...p,
      fornecedor_nome: String(fornecedoresById[String(p.fornecedor_id)] || p.fornecedor_nome || '').trim(),
    })).filter((p) => {
      if (selectedCategoria !== 'todas' && p.categoria !== selectedCategoria) return false;
      if (filtroAtencao && !p.requer_atencao) return false;
      return true;
    });

    if (!debouncedSearch) return { produtos: mapped, isFuzzy: false };

    const termos = normSearch(debouncedSearch).split(/\s+/).filter(Boolean);
    if (termos.length === 0) return { produtos: mapped, isFuzzy: false };

    const scored = mapped
      .map(p => {
        const texto = [
          p.id,
          p.nome,
          p.modelo_referencia,
          p.categoria,
          p.ambiente,
          p.codigo_barras,
          p.sku,
          p.fornecedor_nome,
          p.cor,
          p.material,
          p.tamanho,
          p.descricao,
          p.descricao_completa,
          p.observacoes,
          p.ncm,
          p.gtin,
          p.ean,
          p.marca,
          p.largura,
          p.altura,
          p.profundidade,
        ]
          .filter(Boolean).map(normSearch).join(' ');
        const matches = termos.filter(t => texto.includes(t)).length;
        return { p, score: matches };
      })
      .filter(({ score }) => score > 0)
      .sort((a, b) => b.score - a.score);

    const exact = scored.filter(({ score }) => score === termos.length);
    const fuzzy = exact.length === 0 && scored.length > 0;
    return {
      produtos: (fuzzy ? scored : exact).map(({ p }) => p),
      isFuzzy: fuzzy,
    };
  }, [rawProdutos, fornecedoresById, debouncedSearch, selectedCategoria, filtroAtencao]);

  // Lista de fabricantes para o dropdown — derivada dos mesmos produtos resolvidos
  const fabricantes = useMemo(() => {
    return [...new Set((produtos || []).map(p => p.fornecedor_nome).filter(Boolean))]
      .sort((a, b) => a.localeCompare(b, 'pt-BR', { sensitivity: 'base' }));
  }, [produtos]);

  const [searchParams, setSearchParams] = useSearchParams();
  const navigate = useNavigate();

  // Check for highlight param to auto-open edit modal
  useEffect(() => {
    const highlightId = searchParams.get('highlight');
    const returnUrl = searchParams.get('returnUrl');
    const focus = searchParams.get('focus');

    if (!highlightId) {
      handledHighlightRef.current = '';
      return;
    }

    const highlightKey = `${highlightId}|${focus || ''}|${returnUrl || ''}`;
    if (handledHighlightRef.current === highlightKey) {
      return;
    }

    if (highlightId && produtos?.length > 0 && !isLoading) {
      const productToEdit = produtos.find(p => String(p.id) === String(highlightId));
      if (productToEdit) {
        handledHighlightRef.current = highlightKey;
        setPendingReturnUrl(returnUrl ? decodeURIComponent(returnUrl) : null);
        openEditModal(productToEdit, focus);

        // Remove params to avoid reopening on refresh
        setSearchParams(params => {
          const newParams = new URLSearchParams(params);
          newParams.delete('highlight');
          newParams.delete('returnUrl');
          newParams.delete('focus');
          return newParams;
        }, { replace: true });
      }
    }
  }, [produtos, isLoading, searchParams, setSearchParams]);

  const deleteMutation = useMutation({
    mutationFn: (id) => base44.entities.Produto.delete(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['produtos'] });
      toast.success("Produto excluído com sucesso");
    },
    onError: (error) => {
      toast.error("Erro ao excluir: " + error.message);
    }
  });

  // Verificações de permissão
  const isAdmin = user?.cargo === 'Administrador';
  const canEdit = can('manage_produtos');
  const canDelete = isAdmin || can('manage_produtos');

  // Helper para calcular estoque total consolidado
  const getEstoqueTotal = (p) => {
    return p?.quantidade_estoque || p?.estoque_cd || 0;
  };

  const renderEstoqueBages = (produto, isListView = false) => {
    const stockFields = getProductStockFields(produto);
    const nonZeroFields = stockFields.filter(f => (produto[f] || 0) > 0);
    
    if (nonZeroFields.length === 0) {
      return (
        <Badge variant="secondary" className={`font-mono ${isListView ? 'text-xs' : 'text-[10px]'} bg-gray-50 text-gray-400 px-1.5 ${isListView ? '' : 'h-5'}`} title="Sem estoque">
          Est: 0
        </Badge>
      );
    }

    return (
      <div className={`flex flex-wrap justify-end gap-1 ${isListView ? 'max-w-[200px]' : 'max-w-[150px]'}`}>
        {nonZeroFields.map(field => {
          const val = produto[field];
          let name = field === 'estoque_cd' ? 'CD' :
                     field === 'estoque_mostruario_mega_store' ? 'Mega' :
                     field === 'estoque_mostruario_centro' ? 'Centro' :
                     field === 'estoque_mostruario_ponte_branca' ? 'P.Branca' :
                     field === 'estoque_mostruario_futura' ? 'Futura' :
                     field.replace('estoque_mostruario_', '').replace('estoque_', '').substring(0,8);
                     
          return (
            <Badge key={field} variant="outline" className={`font-mono ${isListView ? 'text-xs' : 'text-[9px]'} border-gray-200 text-gray-600 px-1.5 ${isListView ? 'py-0.5' : 'h-4'} flex items-center`} title={field}>
              {name}: <strong className="ml-1 text-gray-800">{val}</strong>
            </Badge>
          );
        })}
      </div>
    );
  };

  // Apply ordering to products
  const produtosOrdenados = useMemo(() => {
    // Aplica filtro de fabricante client-side (mesma resolu\u00e7\u00e3o que o dropdown)
    const filtrados = selectedFabricante === 'todos'
      ? (produtos || [])
      : (produtos || []).filter(p => p.fornecedor_nome === selectedFabricante);
    return aplicarOrdenacao(filtrados);
  }, [produtos, selectedFabricante, selectedOrdenacao, selectedDirecao, aplicarOrdenacao]);

  // Estatísticas
  const stats = useMemo(() => {
    const items = produtos || [];
    return {
      total: items.length,
      ativos: items.filter(p => p.ativo !== false).length,
      inativos: items.filter(p => p.ativo === false).length,
      semFoto: items.filter(p => !p.fotos?.length).length,
      semPreco: items.filter(p => !p.preco_venda).length,
      comAtencao: produtosComAtencao?.length || 0
    };
  }, [produtos, produtosComAtencao]);

  // Resetar página quando filtros mudarem
  React.useEffect(() => {
    setCurrentPage(1);
  }, [debouncedSearch, selectedCategoria, selectedFabricante, filtroAtencao, selectedOrdenacao, selectedDirecao]);

  // Paginação
  const paginatedProdutos = useMemo(() => {
    const startIndex = (currentPage - 1) * itemsPerPage;
    return produtosOrdenados.slice(startIndex, startIndex + itemsPerPage);
  }, [produtosOrdenados, currentPage]);

  const totalPages = Math.ceil(produtosOrdenados.length / itemsPerPage);

  const openEditModal = (produto, nextFocusField = null) => {
    setModalMode('edit');
    setFocusField(nextFocusField);
    setEditingProduto({ ...produto, nomeDisplay: produto.nome });
    setIsModalOpen(true);
  };

  const openViewModal = (produto) => {
    setModalMode('view');
    setFocusField(null);
    setEditingProduto({ ...produto, nomeDisplay: produto.nome });
    setIsModalOpen(true);
  };

  const handleEdit = (produto) => {
    openEditModal(produto, null);
  };

  const handleNew = () => {
    setModalMode('edit');
    setEditingProduto(null);
    setFocusField(null);
    setIsModalOpen(true);
  };

  const handleDuplicate = (produto) => {
    // Cria uma cópia do produto para edição
    const copy = {
      ...produto,
      id: undefined,
      nome: `${produto.nome} (Cópia)`,
      sku: '',
      codigo_barras: null,
    };
    setModalMode('edit');
    setEditingProduto(copy);
    setFocusField(null);
    setIsModalOpen(true);
  };

  const handleDelete = async (produto) => {
    const confirmed = await confirm({
      title: "Excluir Produto",
      message: `Tem certeza que deseja excluir "${produto.nome}"? Esta ação não pode ser desfeita.`,
      confirmText: "Excluir",
      variant: "destructive"
    });
    if (confirmed) {
      deleteMutation.mutate(produto.id);
    }
  };

  const handleSave = async (data) => {
    if (saveInFlightRef.current) {
      return;
    }

    saveInFlightRef.current = true;
    setSavingProduto(true);
    try {
      let savedProduct;
      const precoNovo = parseFloat(data.preco_venda) || 0;
      const precoAntigo = editingProduto?.preco_venda || 0;

      if (editingProduto?.id) {
        savedProduct = await base44.entities.Produto.update(editingProduto.id, data);
        toast.success("Produto atualizado com sucesso");
      } else {
        savedProduct = await base44.entities.Produto.create(data);
        toast.success("Produto cadastrado com sucesso");
      }

      // --- REGISTRAR HISTÓRICO DE PREÇOS ---
      try {
        if (savedProduct && savedProduct.id && precoNovo !== precoAntigo) {
          await base44.entities.HistoricoPrecos?.create?.({
            organization_id: organization?.id || '00000000-0000-0000-0000-000000000001',
            produto_id: savedProduct.id,
            preco_antigo: precoAntigo,
            preco_novo: precoNovo,
            tipo: 'venda',
            motivo: editingProduto?.id ? 'Atualização Manual' : 'Cadastro Inicial',
            usuario_nome: user?.nome || 'Sistema'
          });
        }
      } catch (histErr) {
        console.warn('Não foi possível registrar histórico de preços:', histErr);
      }

      queryClient.invalidateQueries({ queryKey: ['produtos'] });
      setIsModalOpen(false);
      setEditingProduto(null);
      setModalMode('edit');

      // Smart return flow
      if (pendingReturnUrl) {
        navigate(pendingReturnUrl);
        setPendingReturnUrl(null);
      }
    } catch (error) {
      console.error("Erro ao salvar:", error);
      toast.error("Erro ao salvar produto: " + error.message);
    } finally {
      saveInFlightRef.current = false;
      setSavingProduto(false);
    }
  };

  if (!user) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2" style={{ borderColor: '#07593f' }} />
      </div>
    );
  }

  return (
    <div className="p-4 md:p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
          <div>
            <h1 className="text-2xl md:text-3xl font-bold" style={{ color: '#07593f' }}>
              Catálogo de Produtos
            </h1>
            <p className="text-gray-500">
              Gerencie seu catálogo de produtos, categorias e variações
            </p>
          </div>
          {canEdit && (
            <div className="flex gap-2">
              <Button
                onClick={() => setIsImportModalOpen(true)}
                variant="outline"
                size="lg"
                className="gap-2"
              >
                <Upload className="w-5 h-5" />
                Importar CSV
              </Button>
              <Button
                onClick={() => { setProdutosParaEtiqueta([]); setIsGeradorEtiquetasOpen(true); }}
                variant="outline"
                size="lg"
                className="gap-2 border-green-200 text-green-700 hover:bg-green-50"
              >
                <Printer className="w-5 h-5" />
                Gerar Etiquetas
              </Button>
              <Button
                onClick={handleNew}
                size="lg"
                className="gap-2"
                style={{ background: 'linear-gradient(135deg, #07593f 0%, #0a6b4d 100%)' }}
              >
                <Plus className="w-5 h-5" />
                Novo Produto
              </Button>
            </div>
          )}
        </div>

        {/* Stats Cards */}
        <div className="grid grid-cols-2 md:grid-cols-6 gap-3 mb-6">
          <Card className="hover:shadow-md transition-all">
            <CardContent className="p-4 text-center">
              <Package className="w-6 h-6 mx-auto mb-1 text-gray-500" />
              <p className="text-2xl font-bold" style={{ color: '#07593f' }}>
                {stats.total}
              </p>
              <p className="text-xs text-gray-500">Total</p>
            </CardContent>
          </Card>

          <Card className="hover:shadow-md transition-all">
            <CardContent className="p-4 text-center">
              <CheckCircle className="w-6 h-6 mx-auto mb-1 text-green-500" />
              <p className="text-2xl font-bold text-green-600">{stats.ativos}</p>
              <p className="text-xs text-gray-500">Ativos</p>
            </CardContent>
          </Card>

          <Card className="hover:shadow-md transition-all">
            <CardContent className="p-4 text-center">
              <XCircle className="w-6 h-6 mx-auto mb-1 text-red-400" />
              <p className="text-2xl font-bold text-red-500">{stats.inativos}</p>
              <p className="text-xs text-gray-500">Inativos</p>
            </CardContent>
          </Card>

          <Card className="hover:shadow-md transition-all">
            <CardContent className="p-4 text-center">
              <ImageIcon className="w-6 h-6 mx-auto mb-1 text-yellow-500" />
              <p className="text-2xl font-bold text-yellow-600">{stats.semFoto}</p>
              <p className="text-xs text-gray-500">Sem Foto</p>
            </CardContent>
          </Card>

          <Card className="hover:shadow-md transition-all">
            <CardContent className="p-4 text-center">
              <AlertTriangle className="w-6 h-6 mx-auto mb-1 text-orange-500" />
              <p className="text-2xl font-bold text-orange-600">{stats.semPreco}</p>
              <p className="text-xs text-gray-500">Sem Preço</p>
            </CardContent>
          </Card>

          <Card
            className={`cursor-pointer transition-all ${filtroAtencao ? 'ring-2 ring-green-500' : 'hover:shadow-md'}`}
            onClick={() => setFiltroAtencao(!filtroAtencao)}
          >
            <CardContent className="p-4 text-center">
              <AlertTriangle className="w-6 h-6 mx-auto mb-1 text-red-500" />
              <p className="text-2xl font-bold text-red-600">{stats.comAtencao}</p>
              <p className="text-xs text-gray-500">Requer Atenção</p>
            </CardContent>
          </Card>
        </div>

        {/* Filters */}
        <Card className="mb-6">
          <CardContent className="p-4">
            <div className="space-y-4">
              {/* Search Row */}
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <Input
                  placeholder="Buscar por nome, código, SKU ou fornecedor..."
                  value={searchTerm}
                  onChange={e => setSearchTerm(e.target.value)}
                  className="pl-10"
                />
              </div>

              {/* Filters Row */}
              <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
                {/* Category Filter */}
                <Select value={selectedCategoria} onValueChange={setSelectedCategoria}>
                  <SelectTrigger>
                    <SelectValue placeholder="Categoria" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="todas">Todas Categorias</SelectItem>
                    {categorias?.map(cat => (
                      <SelectItem key={cat} value={cat}>{cat}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>

                {/* Manufacturer Filter */}
                <Select value={selectedFabricante} onValueChange={setSelectedFabricante}>
                  <SelectTrigger>
                    <SelectValue placeholder="Fabricante" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="todos">Todos Fabricantes</SelectItem>
                    {fabricantes?.map(fab => (
                      <SelectItem key={fab} value={fab}>{fab}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>

                {/* Ordenacao */}
                <Select value={selectedOrdenacao} onValueChange={setSelectedOrdenacao}>
                  <SelectTrigger>
                    <SelectValue placeholder="Ordenar por" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="alfabetica">Alfabética</SelectItem>
                    <SelectItem value="preco">Preço</SelectItem>
                    <SelectItem value="estoque">Estoque</SelectItem>
                  </SelectContent>
                </Select>

                {/* Direction */}
                <Select value={selectedDirecao} onValueChange={setSelectedDirecao}>
                  <SelectTrigger>
                    <SelectValue placeholder="Direção" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="asc">Crescente</SelectItem>
                    <SelectItem value="desc">Decrescente</SelectItem>
                  </SelectContent>
                </Select>

                {/* Attention Filter Button */}
                <Button
                  variant={filtroAtencao ? "default" : "outline"}
                  className="w-full"
                  onClick={() => setFiltroAtencao(!filtroAtencao)}
                >
                  <AlertTriangle className="w-4 h-4 mr-2" />
                  {filtroAtencao ? "Com Atenção" : "Todas"}
                </Button>
              </div>

              {/* View Mode Toggle */}
              <div className="flex gap-1 bg-gray-100 p-1 rounded-lg w-fit">
                <Button
                  variant={viewMode === 'grid' ? 'default' : 'ghost'}
                  size="sm"
                  onClick={() => setViewMode('grid')}
                  className="px-3"
                >
                  <Grid3X3 className="w-4 h-4" />
                </Button>
                <Button
                  variant={viewMode === 'list' ? 'default' : 'ghost'}
                  size="sm"
                  onClick={() => setViewMode('list')}
                  className="px-3"
                >
                  <List className="w-4 h-4" />
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Loading State */}
        {isLoading && (
          <div className="flex items-center justify-center py-20">
            <Loader2 className="w-8 h-8 animate-spin text-green-600" />
          </div>
        )}

        {/* Empty State */}
        {!isLoading && produtosOrdenados.length === 0 && (
          <Card className="py-16 text-center">
            <CardContent>
              <Package className="w-16 h-16 mx-auto mb-4 text-gray-300" />
              <h3 className="text-xl font-semibold text-gray-700 mb-2">
                {debouncedSearch || selectedCategoria !== 'todas' || selectedFabricante !== 'todos' || filtroAtencao
                  ? 'Nenhum produto encontrado'
                  : 'Nenhum produto cadastrado'}
              </h3>
              <p className="text-gray-500 mb-6">
                {debouncedSearch || selectedCategoria !== 'todas' || selectedFabricante !== 'todos' || filtroAtencao
                  ? 'Tente ajustar os filtros de busca'
                  : 'Comece cadastrando seu primeiro produto'}
              </p>
              {canEdit && !debouncedSearch && selectedCategoria === 'todas' && selectedFabricante === 'todos' && !filtroAtencao && (
                <Button onClick={handleNew} className="gap-2" style={{ backgroundColor: '#07593f' }}>
                  <Plus className="w-4 h-4" />
                  Cadastrar Primeiro Produto
                </Button>
              )}
            </CardContent>
          </Card>
        )}

        {/* Grid View */}
        {!isLoading && produtosOrdenados.length > 0 && viewMode === 'grid' && (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
            {paginatedProdutos.map(produto => (
              <Card
                key={produto.id}
                className={`group flex relative overflow-hidden cursor-pointer bg-white transition-all hover:shadow-lg hover:ring-1 hover:ring-green-500/20 ${produto.ativo === false ? 'opacity-75' : ''}`}
                onClick={() => {
                  openViewModal(produto);
                }}
              >
                {/* Image Section (Left) */}
                <div className="w-1/3 min-w-[120px] bg-gray-50 relative overflow-hidden border-r border-gray-100">
                  {produto.fotos?.[0] ? (
                    <img
                      src={produto.fotos[0]}
                      alt={produto.nome}
                      className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
                    />
                  ) : (
                    <div className="w-full h-full flex flex-col items-center justify-center text-gray-300">
                      <Package className="w-8 h-8 mb-1" />
                      <span className="text-[10px]">Sem foto</span>
                    </div>
                  )}

                  {/* ID Badge (Top Left) */}
                  <div className="absolute top-1.5 left-1.5 z-10">
                    <Badge variant="outline" className="h-5 px-1.5 text-[10px] bg-white/90 backdrop-blur shadow-sm border-gray-200 text-gray-500">
                      #{produto.id}
                    </Badge>
                  </div>

                  {/* Badges Overlay */}
                  {produto.ativo === false && (
                    <Badge variant="destructive" className="absolute bottom-1.5 left-1.5 h-5 px-1.5 text-[10px] shadow-sm z-10">Inativo</Badge>
                  )}
                  {(produto.requer_atencao || !produto.preco_venda) && (
                    <Badge className="absolute bottom-1.5 right-1.5 bg-orange-500 text-[10px] h-5 px-1.5 shadow-sm z-10">
                      {!produto.preco_venda ? 'S/ Preço' : 'Atenção'}
                    </Badge>
                  )}
                </div>

                {/* Quick Edit Button (Overlay) */}
                {canEdit && (
                  <div className="absolute top-1.5 right-1.5 opacity-0 group-hover:opacity-100 transition-opacity z-20 flex gap-1">
                    <Button size="icon" variant="secondary" className="h-7 w-7 shadow-sm bg-white/90 backdrop-blur" onClick={(e) => { e.stopPropagation(); setProdutosParaEtiqueta([produto]); setIsGeradorEtiquetasOpen(true); }} title="Imprimir Etiqueta">
                      <Printer className="w-3.5 h-3.5 text-green-700" />
                    </Button>
                    <Button size="icon" variant="secondary" className="h-7 w-7 shadow-sm bg-white/90 backdrop-blur" onClick={(e) => { e.stopPropagation(); openEditModal(produto); }} title="Editar">
                      <Edit className="w-3.5 h-3.5 text-gray-700" />
                    </Button>
                  </div>
                )}

                {/* Content Section (Right) */}
                <div className="flex-1 p-3 flex flex-col justify-between min-w-0">

                  <div className="space-y-1">
                    <div className="flex justify-between items-start gap-2">
                      <p className="text-[10px] font-bold text-green-700 uppercase tracking-wider">{produto.categoria}</p>
                    </div>

                    <div className="flex items-start gap-2">
                      <h3 className="text-sm font-bold text-gray-900 leading-snug line-clamp-2" title={`${produto.nome} ${produto.modelo_referencia || ''}`}>
                        {produto.nome} <span className="text-gray-500 font-normal">{produto.modelo_referencia}</span>
                      </h3>
                      <ProductIncompleteIndicator
                        produto={produto}
                        canEdit={canEdit}
                        onSelectMissing={(missingItem) => openEditModal(produto, missingItem.focusField)}
                      />
                    </div>

                    {produto.fornecedor_nome && (
                      <p className="text-[11px] text-gray-400 truncate clamp-1">{produto.fornecedor_nome}</p>
                    )}

                    {/* Dimensoes e Material */}
                    <div className="flex flex-wrap gap-1 mt-1">
                      {getDisplayDimensions(produto) && (
                        <span className="text-[10px] px-1.5 py-0.5 rounded bg-amber-50 text-amber-700 border border-amber-100 flex items-center" title="Dimensões (LxAxP)">
                          <Ruler className="w-3 h-3 mr-1 opacity-50" />
                          {getDisplayDimensions(produto)}
                        </span>
                      )}
                      {hasMeaningfulValue(produto.material) && (
                        <span className="text-[10px] px-1.5 py-0.5 rounded bg-blue-50 text-blue-700 border border-blue-100 flex items-center" title="Material">
                          <Layers className="w-3 h-3 mr-1 opacity-50" /> {produto.material}
                        </span>
                      )}
                    </div>

                    {/* Atributos da Variação (Cor/Tamanho) */}
                    <div className="flex flex-wrap gap-1 mt-1">
                      {hasMeaningfulValue(produto.cor) && (
                        <Badge variant="secondary" className="text-[10px] px-1.5 h-5 flex items-center gap-1 bg-gray-50 border border-gray-100" title="Cor">
                          <>
                            <div
                              className="w-2 h-2 rounded-full border border-gray-300"
                              style={{ background: getColorHex(produto.cor) }}
                            />
                            {produto.cor}
                          </>
                        </Badge>
                      )}
                      {shouldShowSize(produto) && (
                        <Badge variant="secondary" className="text-[10px] px-1.5 h-5 bg-gray-50 border border-gray-100" title="Tamanho">
                          <Ruler className="w-3 h-3 mr-1 text-gray-400" />
                          {produto.tamanho}
                        </Badge>
                      )}
                    </div>
                  </div>

                  {/* Footer: Price & Stock */}
                  <div className="pt-2 mt-1 border-t border-gray-50 flex items-end justify-between gap-1">
                    <div className="flex flex-col">
                      {produto.preco_venda ? (
                        <span className="text-base font-bold text-green-800 leading-none">{formatPrice(produto.preco_venda)}</span>
                      ) : (
                        <span className="text-xs italic text-gray-400">Sob consulta</span>
                      )}
                    </div>

                    <div className="text-right">
                      {renderEstoqueBages(produto, false)}
                    </div>
                  </div>

                </div>
              </Card>
            ))}
          </div>
        )}

        {/* List View */}
        {
          !isLoading && produtosOrdenados.length > 0 && viewMode === 'list' && (
            <Card>
              <div className="divide-y">
                {paginatedProdutos.map((produto) => (
                  <div
                    key={produto.id}
                    className={`p-4 flex items-center gap-4 hover:bg-gray-50 transition-colors ${produto.ativo === false ? 'opacity-75' : ''}`}
                  >
                    {/* Thumb */}
                    <div className="w-16 h-16 rounded-lg bg-gray-100 overflow-hidden flex-shrink-0 relative">
                      {produto.fotos?.[0] ? (
                        <img
                          src={produto.fotos[0]}
                          alt={produto.nome}
                          className="w-full h-full object-cover"
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center">
                          <Package className="w-6 h-6 text-gray-300" />
                        </div>
                      )}
                    </div>

                    {/* Info */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 flex-wrap">
                        <h3 className="font-semibold text-gray-900">
                          {produto.nome}{produto.modelo_referencia ? ` ${produto.modelo_referencia}` : ''}
                        </h3>
                        {produto.ativo === false && (
                          <Badge variant="destructive" className="h-5 px-1.5 text-[10px]">Inativo</Badge>
                        )}
                        <ProductIncompleteIndicator
                          produto={produto}
                          canEdit={canEdit}
                          onSelectMissing={(missingItem) => openEditModal(produto, missingItem.focusField)}
                        />
                      </div>
                      <p className="text-sm text-gray-500 mb-2">
                        {produto.categoria}
                        {produto.fornecedor_nome && ` • ${produto.fornecedor_nome}`}
                        {produto.largura && produto.altura && ` • ${produto.largura}×${produto.altura}${produto.profundidade ? `×${produto.profundidade}` : ''} cm`}
                      </p>

                      {/* Atributos */}
                      {(produto.cor || produto.tamanho) && (
                        <div className="flex gap-2">
                          {produto.cor && (
                            <span className="text-xs text-gray-600 flex items-center gap-1">
                              <div className="w-2 h-2 rounded-full border" style={{ background: getColorHex(produto.cor) }} />
                              {produto.cor}
                            </span>
                          )}
                          {produto.tamanho && (
                            <span className="text-xs text-gray-600 flex items-center gap-1">
                              <Ruler className="w-3 h-3" />
                              {produto.tamanho}
                            </span>
                          )}
                        </div>
                      )}
                    </div>

                    {/* Price and Stock */}
                    <div className="text-right flex flex-col items-end gap-1">
                      <div>
                        {produto.preco_venda ? (
                          <span className="text-base font-bold text-green-800">{formatPrice(produto.preco_venda)}</span>
                        ) : (
                          <span className="text-xs italic text-gray-400">Consulte</span>
                        )}
                      </div>
                      {renderEstoqueBages(produto, true)}
                    </div>

                    {/* Actions */}
                    {canEdit && (
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button variant="ghost" size="icon" className="h-8 w-8">
                            <MoreHorizontal className="w-4 h-4" />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                          <DropdownMenuItem onClick={() => handleEdit(produto)}>
                            <Edit className="w-4 h-4 mr-2" />
                            Editar
                          </DropdownMenuItem>
                          <DropdownMenuItem onClick={() => { setProdutosParaEtiqueta([produto]); setIsGeradorEtiquetasOpen(true); }}>
                            <Printer className="w-4 h-4 mr-2" />
                            Imprimir Etiqueta
                          </DropdownMenuItem>
                          <DropdownMenuItem onClick={() => handleDuplicate(produto)}>
                            <Copy className="w-4 h-4 mr-2" />
                            Duplicar
                          </DropdownMenuItem>
                          {canDelete && (
                            <>
                              <DropdownMenuSeparator />
                              <DropdownMenuItem
                                onClick={() => handleDelete(produto)}
                                className="text-red-600"
                              >
                                <Trash2 className="w-4 h-4 mr-2" />
                                Excluir
                              </DropdownMenuItem>
                            </>
                          )}
                        </DropdownMenuContent>
                      </DropdownMenu>
                    )}
                  </div>
                ))}
              </div>
            </Card>
          )
        }

        {/* Pagination Controls */}
        {!isLoading && produtosOrdenados.length > 0 && (
          <div className="flex flex-col md:flex-row justify-between items-center mt-6 gap-4">
            <p className="text-sm text-gray-500 flex items-center gap-2">
              Exibindo {Math.min((currentPage - 1) * itemsPerPage + 1, produtosOrdenados.length)} - {Math.min(currentPage * itemsPerPage, produtosOrdenados.length)} de {produtosOrdenados.length >= 100000 ? '+100k' : produtosOrdenados.length} produtos
              {isFuzzy && <span className="text-[10px] px-1.5 py-0.5 rounded bg-amber-100 text-amber-700 font-medium">resultado mais próximo</span>}
            </p>

            <div className="flex gap-2 items-center">
              <span className="text-sm text-gray-400 mr-2">Página {currentPage} de {totalPages}</span>
              <Button
                variant="outline"
                size="sm"
                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                disabled={currentPage === 1}
              >
                <ChevronLeft className="w-4 h-4 mr-2" /> Anterior
              </Button>
              <Button
                variant="outline"
                size="sm"
                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                disabled={currentPage === totalPages}
              >
                Próximo <ChevronRight className="w-4 h-4 ml-2" />
              </Button>
            </div>
          </div>
        )}
      </div>

      {/* Modal de Cadastro */}
      <ProdutoCadastroCompleto
        isOpen={isModalOpen}
        onClose={() => {
          setIsModalOpen(false);
          setEditingProduto(null);
          setFocusField(null);
          setModalMode('edit');
        }}
        onSave={modalMode === 'edit' ? handleSave : undefined}
        produto={editingProduto}
        focusField={focusField}
        isLoading={savingProduto}
        readOnly={modalMode === 'view'}
      />

      <GeradorEtiquetasModal
        isOpen={isGeradorEtiquetasOpen}
        onClose={() => setIsGeradorEtiquetasOpen(false)}
        produtosPreSelecionados={produtosParaEtiqueta}
        user={user}
      />

      {/* Modal de Importação */}
      <ImportProdutosModal
        isOpen={isImportModalOpen}
        onClose={() => setIsImportModalOpen(false)}
        onSuccess={() => queryClient.invalidateQueries({ queryKey: ['produtos'] })}
      />
    </div>
  );
}

import React, { useState, useEffect, useRef } from "react";
import { useTenant } from "@/contexts/TenantContext";
import { Slider } from "@/components/ui/slider";
import { Volume2, VolumeX, Cast, Loader2, Play, Pause, Radio } from "lucide-react";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";

const STREAM_URL = "https://sv15.hdradios.net:6858/stream";
const METADATA_ENDPOINTS = [
  "https://sv15.hdradios.net:6858/status-json.xsl",
  "https://sv15.hdradios.net:6858/stats?json=1",
];

export default function RadioLoja() {
  const { brandName, brandLogo } = useTenant();
  const [isPlaying, setIsPlaying] = useState(false);
  const [volume, setVolume] = useState([100]);
  const [isMuted, setIsMuted] = useState(false);
  const [songName, setSongName] = useState("Procurando informações...");
  const [isLoading, setIsLoading] = useState(true);
  const [isCasting, setIsCasting] = useState(false);
  const [showCastGuide, setShowCastGuide] = useState(false);
  const audioRef = useRef(null);
  const [castAvailable, setCastAvailable] = useState(false);

  // Cast Initialization
  useEffect(() => {
    const initializeCastApi = () => {
      const cast = window.cast;
      const chrome = window.chrome;
      if (!cast || !cast.framework || !chrome?.cast) return;

      const context = cast.framework.CastContext.getInstance();
      context.setOptions({
        receiverApplicationId: chrome.cast.media.DEFAULT_MEDIA_RECEIVER_APP_ID,
        autoJoinPolicy: chrome.cast.AutoJoinPolicy.ORIGIN_SCOPED,
      });

      // Listener: quando uma sessão Cast é estabelecida, enviar a mídia automaticamente
      context.addEventListener(
        cast.framework.CastContextEventType.SESSION_STATE_CHANGED,
        (event) => {
          const { SessionState } = cast.framework;
          if (
            event.sessionState === SessionState.SESSION_STARTED ||
            event.sessionState === SessionState.SESSION_RESUMED
          ) {
            setIsCasting(true);
            sendMediaToCast();
          } else if (event.sessionState === SessionState.SESSION_ENDED) {
            setIsCasting(false);
            toast.info("Transmissão encerrada.");
          }
        }
      );

      setCastAvailable(true);
    };

    // A API do Google Cast chama esta função quando está pronta
    window['__onGCastApiAvailable'] = (isAvailable) => {
      if (isAvailable) initializeCastApi();
    };

    if (!document.getElementById('cast-sdk')) {
      const script = document.createElement('script');
      script.id = 'cast-sdk';
      script.src = 'https://www.gstatic.com/cv/js/sender/v1/cast_sender.js?loadCastFramework=1';
      document.body.appendChild(script);
    } else if (window.cast?.framework) {
      initializeCastApi();
    }
  }, []); // roda apenas uma vez

  /**
   * Envia a stream de áudio para o Chromecast.
   * Deve ser chamado DEPOIS que a sessão já foi criada.
   */
  const sendMediaToCast = () => {
    try {
      const chromeCast = window.chrome?.cast;
      if (!chromeCast) return;

      const castSession = window.cast.framework.CastContext.getInstance().getCurrentSession();
      if (!castSession) {
        toast.error('Nenhuma sessão Cast ativa.');
        return;
      }

      const mediaInfo = new chromeCast.media.MediaInfo(STREAM_URL, 'audio/mpeg');
      mediaInfo.streamType = chromeCast.media.StreamType.LIVE;
      mediaInfo.metadata = new chromeCast.media.MusicTrackMediaMetadata();
      mediaInfo.metadata.title = songName !== 'Procurando informações...' ? songName : 'Rádio Samambaia';
      mediaInfo.metadata.artist = brandName || 'Loja';
      if (brandLogo) {
        mediaInfo.metadata.images = [new chromeCast.Image(brandLogo)];
      }

      const request = new chromeCast.media.LoadRequest(mediaInfo);
      request.autoplay = true;

      castSession.loadMedia(request).then(
        () => toast.success('Tocando na TV! 📺'),
        (err) => {
          console.error('Erro ao carregar mídia no Cast:', err);
          toast.error('Não foi possível enviar o áudio para a TV.');
        }
      );
    } catch (e) {
      console.error('Erro inesperado no Cast:', e);
      toast.error('Erro ao iniciar transmissão.');
    }
  };

  /**
   * Botão de Cast: abre o seletor de dispositivos (se não conectado)
   * ou envia mídia (se já conectado).
   */
  const handleCast = () => {
    if (!castAvailable) {
      toast.error('Chromecast não detectado. Certifique-se de estar no mesmo Wi-Fi.');
      return;
    }

    const context = window.cast.framework.CastContext.getInstance();
    const currentSession = context.getCurrentSession();

    if (currentSession) {
      // Já conectado: apenas reenvia a mídia
      sendMediaToCast();
    } else {
      // Abre o seletor nativo de Chromecasts
      context.requestSession().then(
        () => { /* O listener de SESSION_STARTED cuida do resto */ },
        (err) => {
          if (err?.code !== 'cancel') {
            toast.error('Erro ao conectar no Chromecast.');
            console.error(err);
          }
        }
      );
    }
  };

  // Áudio Local e Autoplay
  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = isMuted ? 0 : volume[0] / 100;
      
      const playAudio = async () => {
        try {
          setIsLoading(true);
          await audioRef.current.play();
          setIsPlaying(true);
        } catch (err) {
          console.log("Autoplay bloqueado pelo navegador.", err);
          setIsPlaying(false);
          toast.info("Clique no play para iniciar a rádio.");
        } finally {
          setIsLoading(false);
        }
      };

      playAudio();
    }
  }, []);

  const togglePlay = () => {
    if (!audioRef.current) return;
    if (isPlaying) {
      audioRef.current.pause();
      setIsPlaying(false);
    } else {
      setIsLoading(true);
      audioRef.current.play()
        .then(() => setIsPlaying(true))
        .catch(() => toast.error("Não foi possível iniciar o áudio."))
        .finally(() => setIsLoading(false));
    }
  };

  const handleVolumeChange = (value) => {
    const vol = value[0];
    setVolume([vol]);
    setIsMuted(vol === 0);
    if (audioRef.current) {
      audioRef.current.volume = vol / 100;
    }
  };

  // Buscando Metadados (Polling)
  useEffect(() => {
    let intervalId;

    const fetchSongData = async () => {
      // Tentativa simples via JSON para Shoutcast/Icecast
      for (const endpoint of METADATA_ENDPOINTS) {
        try {
          const response = await fetch(endpoint, { cache: "no-store", mode: 'cors' });
          if (!response.ok) continue;
          
          const text = await response.text();
          try {
            const data = JSON.parse(text);
            
            // Lógica comum para Shoutcast v2 / Icecast v2
            if (data?.icestats?.source) {
              const source = Array.isArray(data.icestats.source) ? data.icestats.source[0] : data.icestats.source;
              if (source?.title) {
                setSongName(source.title);
                return;
              }
            } else if (data?.title) {
              setSongName(data.title);
              return;
            } else if (data?.streamtitle) {
                setSongName(data.streamtitle);
                return;
            }
          } catch (e) {
            // Pode ser ICY text plain, algumas rádios retornam text/html
          }
        } catch (err) {
          console.warn("Erro ao buscar metadados", endpoint);
        }
      }
      // Fallback
      if (songName === "Procurando informações...") {
        setSongName("Rádio Samambaia ao Vivo");
      }
    };

    fetchSongData();
    intervalId = setInterval(fetchSongData, 15000); // Atualiza a cada 15 segundos

    return () => clearInterval(intervalId);
  }, []);


  return (
    <div className="min-h-screen flex flex-col justify-between overflow-hidden relative font-sans text-white bg-green-950">
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,600;0,700;1,400&family=Lato:wght@300;400;700&display=swap');
        .font-serif { fontFamily: 'Playfair Display', serif; }
        .font-body { fontFamily: 'Lato', sans-serif; }
        @keyframes eq {
          0%, 100% { height: 10px; }
          50% { height: 35px; }
        }
        .animate-eq { animation: eq 1s ease-in-out infinite; }
      `}</style>
      
      {/* Background Image Immersive */}
      <div className="absolute inset-0 z-0">
        <div 
            className="absolute inset-0 bg-cover bg-center transform scale-105"
            style={{ backgroundImage: `url('https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?q=80&w=2000&auto=format&fit=crop')` }}
        ></div>
        {/* Overlay degradê escuro sofisticado */}
        <div className="absolute inset-0 bg-gradient-to-r from-green-950/95 via-green-950/80 to-transparent"></div>
        <div className="absolute inset-0 bg-black/40"></div>
        
        {/* Elemento de animação suave se tocando */}
        {isPlaying && (
          <div className="absolute top-1/2 left-1/3 -translate-y-1/2 w-[600px] h-[600px] bg-amber-500/20 rounded-full blur-[150px] animate-pulse pointer-events-none"></div>
        )}
      </div>

      {/* Áudio Oculto */}
      <audio ref={audioRef} src={STREAM_URL} preload="auto" />

      {/* Cabeçalho - Logo e Nome (Esqueda Superior) */}
      <div className="z-10 p-12 flex flex-col items-start space-y-4 animate-in fade-in slide-in-from-left-10 duration-1000">
        <div className="flex items-center gap-8">
          {brandLogo ? (
            <div className="w-32 h-32 rounded-2xl bg-white/5 backdrop-blur-md border border-white/20 flex items-center justify-center p-4 shadow-2xl">
              <img src={brandLogo} alt="Logo da Loja" className="w-full h-full object-contain drop-shadow-lg" />
            </div>
          ) : (
             <div className="w-32 h-32 rounded-2xl bg-green-900/80 backdrop-blur-md border border-amber-500/30 flex items-center justify-center text-4xl shadow-2xl shadow-green-900/50">
               <Radio className="w-12 h-12 text-amber-400" />
             </div>
          )}
          
          <div>
            <h1 className="text-6xl md:text-7xl font-serif font-bold tracking-tight text-white drop-shadow-2xl">
              {brandName || 'Sua Loja'}
            </h1>
            <p className="text-2xl mt-4 font-body text-amber-200/80 font-light tracking-[0.2em] uppercase">
              Tocando Rádio Samambaia
            </p>
          </div>
        </div>
      </div>

      {/* Centro - Nome da Música */}
      <div className="z-10 flex-1 flex flex-col items-start justify-center p-12 max-w-5xl">
        <div className="animate-in fade-in slide-in-from-bottom-10 duration-1000 delay-300">
           {songName !== "Procurando informações..." && songName !== "Rádio Samambaia ao Vivo" && (
             <>
               {/* Equalizador animado minimalista */}
               <div className={`flex items-end gap-1.5 mb-8 h-12 ${isPlaying ? 'opacity-100' : 'opacity-0'} transition-opacity duration-700`}>
                 {[1,2,3,4,5].map(i => (
                    <div key={i} className="w-1.5 bg-amber-400 rounded-full animate-eq" style={{ animationDelay: `${i*0.15}s` }}></div>
                 ))}
               </div>

               <h2 className="text-5xl md:text-8xl font-serif font-bold text-transparent bg-clip-text bg-gradient-to-r from-white via-stone-100 to-stone-400 leading-tight drop-shadow-2xl">
                 {songName}
               </h2>
             </>
           )}
        </div>
      </div>

      {/* Rodapé - Controles (Slider, Play, Cast) */}
      <div className="z-10 w-full pb-8 pt-12 px-6 bg-gradient-to-t from-green-950/90 to-transparent">
        <div className="max-w-2xl mx-auto backdrop-blur-xl bg-white/5 border border-white/10 p-3 pl-4 pr-6 rounded-full flex items-center gap-6 shadow-2xl">
          
          {/* Botão Play/Pause */}
          <Button 
            onClick={togglePlay}
            size="icon"
            className="w-14 h-14 rounded-full bg-gradient-to-br from-amber-400 to-amber-600 hover:from-amber-300 hover:to-amber-500 text-green-950 shrink-0 transition-transform hover:scale-105 active:scale-95 border-none shadow-[0_0_30px_rgba(251,191,36,0.3)]"
          >
            {isLoading ? (
              <Loader2 className="w-6 h-6 animate-spin text-green-950" />
            ) : isPlaying ? (
              <Pause className="w-5 h-5 fill-current" />
            ) : (
              <Play className="w-5 h-5 fill-current ml-1" />
            )}
          </Button>

          {/* Volume Slider */}
          <div className="flex-1 flex items-center gap-4">
            <button onClick={() => handleVolumeChange([isMuted ? 50 : 0])} className="text-stone-400 hover:text-white transition-colors">
              {isMuted || volume[0] === 0 ? <VolumeX className="w-5 h-5" /> : <Volume2 className="w-5 h-5" />}
            </button>
            <Slider
              defaultValue={[100]}
              max={100}
              step={1}
              value={volume}
              onValueChange={handleVolumeChange}
              className="w-full cursor-grab active:cursor-grabbing [&_.bg-primary]:bg-gradient-to-r [&_.bg-primary]:from-amber-500 [&_.bg-primary]:to-amber-300 [&_[role=slider]]:bg-white [&_[role=slider]]:border-white [&_[role=slider]]:shadow-[0_0_10px_rgba(251,191,36,0.5)] [&_[role=slider]]:w-5 [&_[role=slider]]:h-5"
            />
          </div>

           {/* Cast Button */}
          <div className="shrink-0 flex items-center gap-3 pr-2">
             <google-cast-launcher style={{ '--connected-color': '#fcd34d', '--disconnected-color': 'rgba(255,255,255,0.5)', width: '28px', height: '28px' }}></google-cast-launcher>

             <Button 
               variant="outline" 
               className="bg-white/5 border-white/20 text-white hover:bg-white/20 hover:text-amber-300 font-body transition-all rounded-full px-5 h-10 uppercase tracking-widest text-[10px]"
               onClick={() => setShowCastGuide(true)}
             >
               <Cast className="w-3 h-3 mr-2" />
               Espelhar TV
             </Button>
          </div>
        </div>
      </div>

      {/* Modal de Guia: Como Espelhar para a TV */}
      {showCastGuide && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/70 backdrop-blur-md"
          onClick={() => setShowCastGuide(false)}
        >
          <div
            className="max-w-lg w-full bg-green-950/95 border border-white/10 rounded-3xl p-8 shadow-2xl"
            onClick={e => e.stopPropagation()}
          >
            <div className="flex items-center justify-between mb-6">
              <h3 className="font-serif text-2xl font-bold text-white">Como exibir na TV</h3>
              <button
                onClick={() => setShowCastGuide(false)}
                className="text-white/40 hover:text-white transition-colors text-2xl leading-none"
              >
                &times;
              </button>
            </div>

            <p className="text-stone-300 font-body text-sm mb-6 leading-relaxed">
              Para que a TV exiba <strong className="text-amber-300">exatamente esta tela</strong> — com logo, nome da música e controles — utilize o espelhamento de guia nativo do Chrome:
            </p>

            <ol className="space-y-4 mb-8">
              {[
                { step: '1', text: <>Clique no ícone de <strong className="text-amber-300">três pontos</strong> (⋮) no canto superior direito do Chrome</> },
                { step: '2', text: <>Clique em <strong className="text-amber-300">&quot;Transmitir...&quot;</strong> no menu</> },
                { step: '3', text: <>Em <em className="text-stone-300">&quot;Transmitir para&quot;</em>, selecione <strong className="text-amber-300">&quot;Transmitir guia&quot;</strong> (não "Transmitir arquivo")</> },
                { step: '4', text: <>Escolha seu Chromecast na lista e pronto — a TV mostrará exatamente esta tela!</> },
              ].map(({ step, text }) => (
                <li key={step} className="flex items-start gap-4">
                  <span className="w-8 h-8 rounded-full bg-amber-500 text-green-950 font-bold text-sm flex items-center justify-center shrink-0 mt-0.5">{step}</span>
                  <span className="text-stone-200 font-body text-sm leading-relaxed">{text}</span>
                </li>
              ))}
            </ol>

            <div className="bg-white/5 border border-white/10 rounded-2xl p-4 flex items-start gap-3">
              <Cast className="w-5 h-5 text-amber-400 shrink-0 mt-0.5" />
              <p className="text-stone-400 font-body text-xs leading-relaxed">
                O som tocará nos <strong className="text-stone-200">alto-falantes da TV</strong> e a imagem será idêntica ao PC. A música não para no computador enquanto transmite.
              </p>
            </div>

            <Button
              className="w-full mt-6 bg-gradient-to-r from-amber-400 to-amber-600 text-green-950 font-bold rounded-full h-12 hover:from-amber-300 hover:to-amber-500"
              onClick={() => setShowCastGuide(false)}
            >
              Entendido!
            </Button>
          </div>
        </div>
      )}

    </div>
  );
}

import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { supabase } from "@/lib/supabase";
import { getZapApiUrl } from "@/utils/zapApiUrl";
import MapaRota from "@/components/entregador/MapaRota";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Truck, MapPin, Package, AlertCircle, Clock, Smartphone, Hash } from "lucide-react";

export default function RastreioPublico({ idProp, slugProp }) {
    const params = useParams();
    const idUrlOriginal = idProp || params.id || (window.location.pathname.split('/').pop() !== 'rastreio' ? window.location.pathname.split('/').pop() : null);
    const tokenUrl = typeof window !== 'undefined' ? new URLSearchParams(window.location.search).get('token') : null;

    const [termoBusca, setTermoBusca] = useState("");
    const [confirmacaoTelefone, setConfirmacaoTelefone] = useState("");
    const [etapa, setEtapa] = useState("busca"); // "busca", "confirmacao", "detalhes"
    const [entrega, setEntrega] = useState(null);
    const [loading, setLoading] = useState(false);
    const [pesquisando, setPesquisando] = useState(false);
    const [erro, setErro] = useState(null);
    const [localizacaoMotorista, setLocalizacaoMotorista] = useState(null);
    const [paradasNaFrente, setParadasNaFrente] = useState(null);
    const [rastreioDesativado, setRastreioDesativado] = useState(false);
    const [organizacao, setOrganizacao] = useState({
        name: "Empresa",
        logo_url: null,
        primary_color: "#16a34a", // green-600
        secondary_color: "#f38a4c",
        cnpj: null
    });

    // Busca dados da organização de forma dinâmica baseada no pedido, slug ou CNPJ
    useEffect(() => {
        async function fetchBranding() {
            try {
                let targetOrgId = null;

                // 1. Tentar identificar a organização através do pedido/entrega
                if (idUrlOriginal && idUrlOriginal !== 'rastreio') {
                    const { data: entregaInfo } = await supabase
                        .from("entregas")
                        .select("organization_id")
                        .or(`id.eq.${idUrlOriginal},numero_pedido.eq.${idUrlOriginal}`)
                        .maybeSingle();

                    if (entregaInfo?.organization_id) {
                        targetOrgId = entregaInfo.organization_id;
                    }
                }

                // 2. Se não encontrou pelo pedido, tentar por slug ou param da URL (ex: /slug/rastreio ou ?org=slug)
                if (!targetOrgId) {
                    const urlParams = typeof window !== 'undefined' ? new URLSearchParams(window.location.search) : new URLSearchParams();
                    const pathParts = typeof window !== 'undefined' ? window.location.pathname.split('/').filter(Boolean) : [];
                    const pathCandidate = pathParts.length >= 2 && pathParts[1] === 'rastreio' ? pathParts[0] : null;
                    const identifier = slugProp || urlParams.get('org') || urlParams.get('tenant') || urlParams.get('cnpj') || pathCandidate;

                    if (identifier && identifier !== 'rastreio') {
                        const { data: orgByIdentifier } = await supabase
                            .from("organizations")
                            .select("id")
                            .or(`slug.eq.${identifier},cnpj.eq.${identifier},id.eq.${identifier}`)
                            .maybeSingle();

                        if (orgByIdentifier?.id) {
                            targetOrgId = orgByIdentifier.id;
                        }
                    }
                }

                // 3. Buscar os dados da organização (com fallback para a primeira caso nenhuma seja especificada)
                let query = supabase.from("organizations").select("id, name, logo_url, primary_color, secondary_color, cnpj");
                if (targetOrgId) {
                    query = query.eq("id", targetOrgId);
                } else {
                    query = query.limit(1);
                }

                const { data: orgData } = await query.maybeSingle();

                if (orgData) {
                    setOrganizacao({
                        name: orgData.name || "Empresa",
                        logo_url: orgData.logo_url,
                        primary_color: orgData.primary_color || "#16a34a",
                        secondary_color: orgData.secondary_color || "#f38a4c",
                        cnpj: orgData.cnpj
                    });

                    if (orgData.id) {
                        const { data: settingsData } = await supabase
                            .from("organization_settings")
                            .select("modulos_ativos")
                            .eq("organization_id", orgData.id)
                            .maybeSingle();

                        if (settingsData?.modulos_ativos?.rastreio === false) {
                            setRastreioDesativado(true);
                        }
                    }
                }
            } catch (err) {
                console.error("Erro ao carregar branding do tenant:", err);
            }
        }
        fetchBranding();
    }, [idUrlOriginal, slugProp]);


    // Formatação de telefone em tempo real
    function formatarTelefone(valor) {
        const v = valor.replace(/\D/g, '');
        if (v.length <= 10) {
            return v.replace(/(\d{2})(\d{4})(\d{0,4})/, "($1) $2-$3");
        }
        return v.replace(/(\d{2})(\d{5})(\d{0,4})/, "($1) $2-$3");
    }

    const normalizarStatus = (status) => (status || "")
        .toString()
        .trim()
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '');

    const escolherEntregaMaisRelevante = (entregas = []) => {
        if (!Array.isArray(entregas) || entregas.length === 0) return null;

        const pesoStatus = (statusNorm, caminhaoId) => {
            if (["proxima parada", "em rota", "a caminho", "proximo"].includes(statusNorm)) return 5;
            if (["agendada", "agendado", "pendente"].includes(statusNorm) && caminhaoId) return 4;
            if (["agendada", "agendado", "pendente"].includes(statusNorm)) return 3;
            if (["entregue", "finalizada"].includes(statusNorm)) return 2;
            if (["cancelada", "cancelado"].includes(statusNorm)) return 1;
            return 0;
        };

        return [...entregas].sort((a, b) => {
            const statusA = normalizarStatus(a.status);
            const statusB = normalizarStatus(b.status);
            const pesoA = pesoStatus(statusA, a.caminhao_id);
            const pesoB = pesoStatus(statusB, b.caminhao_id);
            if (pesoA !== pesoB) return pesoB - pesoA;

            const dataA = a.data_agendada ? new Date(a.data_agendada).getTime() : 0;
            const dataB = b.data_agendada ? new Date(b.data_agendada).getTime() : 0;
            if (dataA !== dataB) return dataB - dataA;

            const idA = Number(a.id) || 0;
            const idB = Number(b.id) || 0;
            return idB - idA;
        })[0];
    };

    // Busca inicial pelo número do pedido ou ID
    async function handleBuscarPedido(e, searchId = null) {
        if (e) e.preventDefault();
        
        const searchValue = searchId || termoBusca.trim();
        if (!searchValue) return;

        setErro(null);
        setPesquisando(true);

        try {
            let entregaEncontrada = null;

            if (searchId) {
                const { data, error } = await supabase
                    .from("entregas")
                    .select("*")
                    .eq("id", searchValue)
                    .single();

                if (error || !data) {
                    setErro("Pedido não encontrado. Verifique o número digitado.");
                    return;
                }

                entregaEncontrada = data;
            } else {
                const { data, error } = await supabase
                    .from("entregas")
                    .select("*")
                    .eq("numero_pedido", searchValue)
                    .order('data_agendada', { ascending: false, nullsFirst: false })
                    .order('id', { ascending: false })
                    .limit(50);

                if (error || !data || data.length === 0) {
                    setErro("Pedido não encontrado. Verifique o número digitado.");
                    return;
                }

                entregaEncontrada = escolherEntregaMaisRelevante(data);
            }

            if (!entregaEncontrada) {
                setErro("Pedido não encontrado. Verifique o número digitado.");
                return;
            }

            setEntrega(entregaEncontrada);
            setEtapa("confirmacao");
        } catch (err) {
            console.error("Erro na busca:", err);
            setErro("Erro ao realizar a busca. Tente novamente.");
        } finally {
            setPesquisando(false);
        }
    }

    async function validarTokenRastreio(token) {
        setErro(null);
        setLoading(true);

        try {
            const apiUrl = getZapApiUrl();
            const response = await fetch(`${apiUrl}/api/tracking/validate?token=${encodeURIComponent(token)}`);
            const data = await response.json().catch(() => ({}));

            if (!response.ok || !data?.ok || !data?.entrega) {
                throw new Error(data?.error || 'Link de rastreio inválido ou expirado');
            }

            setEntrega(data.entrega);
            setParadasNaFrente(typeof data.paradasNaFrente === 'number' ? data.paradasNaFrente : 0);

            if (data.localizacaoMotorista?.lat && data.localizacaoMotorista?.lng) {
                setLocalizacaoMotorista({
                    lat: data.localizacaoMotorista.lat,
                    lng: data.localizacaoMotorista.lng
                });
            }

            setEtapa('detalhes');
        } catch (err) {
            console.error('Erro ao validar token de rastreio:', err);
            setErro(err.message || 'Link de rastreio inválido ou expirado.');
            setEtapa('busca');
        } finally {
            setLoading(false);
        }
    }

    // Efeito para auto-preencher se houver ID na URL
    useEffect(() => {
        if (etapa !== "busca" || entrega) return;

        if (tokenUrl) {
            validarTokenRastreio(tokenUrl);
            return;
        }

        if (idUrlOriginal) {
            handleBuscarPedido(null, idUrlOriginal);
        }
    }, [idUrlOriginal, tokenUrl, etapa, entrega]);

    // Verificação do telefone
    async function handleConfirmarTelefone(e) {
        if (e) e.preventDefault();
        const telLimpoDigitado = confirmacaoTelefone.replace(/\D/g, '');
        const telLimpoBanco = (entrega.cliente_telefone || "").replace(/\D/g, '');

        // Comparação robusta: compara os últimos 8 dígitos (o "corpo" do número)
        // Isso resolve o problema de ter ou não o dígito 9 extra, código de país ou DDD.
        const matches = (telLimpoDigitado.length >= 8 && telLimpoBanco.length >= 8) &&
            (telLimpoDigitado.slice(-8) === telLimpoBanco.slice(-8));

        if (!matches) {
            setErro("Telefone incorreto. Verifique o número e tente novamente.");
            return;
        }

        setErro(null);
        setLoading(true);
        await processarEntregaEncontrada(entrega);
        setEtapa("detalhes");
        setLoading(false);
    }

    async function processarEntregaEncontrada(dadosEntrega) {
        const statusNormalizado = (dadosEntrega.status || "").trim().toLowerCase();
        const statusComRota = ["a caminho", "em rota", "próxima parada", "proxima parada", "próximo", "proximo", "pendente", "agendada", "agendado"];

        if (["entregue", "cancelada", "cancelado", "finalizada"].includes(statusNormalizado)) {
            return;
        }

        if (!statusComRota.includes(statusNormalizado) && !dadosEntrega.caminhao_id) {
            return;
        }

        if (dadosEntrega.caminhao_id) {
            try {
                const dataBase = dadosEntrega.data_agendada ? dadosEntrega.data_agendada.split('T')[0] : null;

                let query = supabase
                    .from("entregas")
                    .select("id, status, ordem_rota, dt_agendada:data_agendada, turnoTr:turno")
                    .eq("caminhao_id", dadosEntrega.caminhao_id)
                    .not("status", "in", '("Entregue","Cancelada","Cancelado","Finalizada")');

                if (dataBase) {
                    query = query.gte("data_agendada", `${dataBase}T00:00:00`)
                        .lte("data_agendada", `${dataBase}T23:59:59`);
                }

                if (dadosEntrega.turno) {
                    query = query.eq("turno", dadosEntrega.turno);
                }

                const { data: routeDeliveries, error: routeError } = await query;

                if (!routeError && routeDeliveries) {
                    const sortedDeliveries = [...routeDeliveries].sort((a, b) => (a.ordem_rota || 99) - (b.ordem_rota || 99));
                    const minhaPosicaoIdx = sortedDeliveries.findIndex(d => d.id === dadosEntrega.id);

                    if (minhaPosicaoIdx > 0) {
                        setParadasNaFrente(minhaPosicaoIdx);
                    } else if (minhaPosicaoIdx === 0) {
                        setParadasNaFrente(0);
                        if (!["próxima parada", "em rota", "a caminho"].includes(dadosEntrega.status?.toLowerCase())) {
                            dadosEntrega.status = 'Próxima parada';
                        }
                        setEntrega({ ...dadosEntrega });
                        await buscarLocalizacaoAtual(dadosEntrega.caminhao_id);
                    }
                } else {
                    if (["próxima parada", "a caminho", "em rota"].includes(dadosEntrega.status?.toLowerCase())) {
                        setParadasNaFrente(0);
                        await buscarLocalizacaoAtual(dadosEntrega.caminhao_id);
                    }
                }
            } catch (filaErr) {
                console.error("Erro ao calcular fila:", filaErr);
            }
        }
    }

    async function buscarLocalizacaoAtual(caminhaoId) {
        const { data: veiculo } = await supabase
            .from("caminhoes")
            .select("latitude, longitude, ultima_atualizacao")
            .eq("id", caminhaoId)
            .single();

        if (veiculo) {
            setLocalizacaoMotorista({
                lat: veiculo.latitude,
                lng: veiculo.longitude
            });
        }
    }

    useEffect(() => {
        let interval;
        if (entrega && paradasNaFrente === 0 && entrega.caminhao_id) {
            interval = setInterval(() => {
                buscarLocalizacaoAtual(entrega.caminhao_id);
            }, 30000);
        }
        return () => { if (interval) clearInterval(interval); };
    }, [entrega, paradasNaFrente]);

    // Máscara para o telefone no DB (exibe apenas os últimos 4 dígitos)
    const renderMascaraTelefone = (tel) => {
        if (!tel) return "";
        const limpo = tel.replace(/\D/g, '');
        const ultimos = limpo.slice(-4);
        return `(XX) *****-${ultimos}`;
    };

    if (loading) return (
        <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4">
            <div className="animate-pulse flex flex-col items-center">
                {organizacao.logo_url ? (
                    <img src={organizacao.logo_url} alt="Logo" className="w-20 h-20 object-contain mb-4" />
                ) : (
                    <Truck className="w-12 h-12 mb-4" style={{ color: organizacao.primary_color }} />
                )}
                <p className="text-gray-500">Localizando informações...</p>
            </div>
        </div>
    );

    return (
        <div
            className="min-h-screen bg-gray-50 p-4 md:p-8"
            style={{
                "--primary": organizacao.primary_color,
                "--secondary": organizacao.secondary_color
            }}
        >
            <div className="max-w-2xl mx-auto space-y-4">
                <div className="flex items-center justify-center flex-col gap-3 mb-8 mt-4 text-center">
                    {organizacao.logo_url ? (
                        <div className="relative">
                            <img
                                src={organizacao.logo_url}
                                alt={organizacao.name}
                                className="h-20 md:h-24 w-auto object-contain drop-shadow-md"
                            />
                        </div>
                    ) : (
                        <div className="p-3 rounded-full shadow-lg" style={{ backgroundColor: organizacao.primary_color }}>
                            <Truck className="w-8 h-8 text-white" />
                        </div>
                    )}
                    <div>
                        <h1 className="text-2xl font-bold text-gray-900">{organizacao.name}</h1>
                        <p className="text-sm text-gray-500 mt-1">Rastreamento de Entregas</p>
                    </div>
                </div>

                {rastreioDesativado ? (
                    <Card className="shadow-lg border-amber-200 bg-amber-50/60">
                        <CardContent className="p-6 md:p-8 text-center space-y-4">
                            <div className="mx-auto w-14 h-14 rounded-full bg-amber-100 flex items-center justify-center text-amber-700">
                                <AlertCircle className="w-7 h-7 text-amber-600" />
                            </div>
                            <div className="space-y-2">
                                <h3 className="text-xl font-bold text-gray-900">Rastreamento Online Indisponível</h3>
                                <p className="text-sm text-gray-600 max-w-md mx-auto leading-relaxed">
                                    O acompanhamento de entregas em tempo real via mapa não está ativado para esta empresa.
                                </p>
                                <p className="text-xs text-gray-500 max-w-sm mx-auto">
                                    Para verificar o agendamento ou status da entrega do seu pedido, por favor entre em contato diretamente com o atendimento da loja.
                                </p>
                            </div>
                        </CardContent>
                    </Card>
                ) : (
                    <>
                        {etapa === "busca" && (

                    <Card className="shadow-lg border-green-100">
                        <CardHeader className="text-center pb-2">
                            <CardTitle className="text-xl">Encontre seu pedido</CardTitle>
                        </CardHeader>
                        <CardContent className="space-y-4">
                            <form onSubmit={handleBuscarPedido} className="space-y-4">
                                <div className="space-y-2">
                                    <label className="text-sm font-medium text-gray-700 block flex items-center gap-2">
                                        <Hash className="w-4 h-4" style={{ color: organizacao.primary_color }} /> Número do Pedido
                                    </label>
                                    <input
                                        type="text"
                                        value={termoBusca}
                                        onChange={(e) => setTermoBusca(e.target.value)}
                                        placeholder="Ex: 10001"
                                        className="w-full text-center p-3 border rounded-lg transition-all outline-none font-bold text-lg focus:ring-2"
                                        style={{ "--tw-ring-color": organizacao.primary_color, borderColor: "var(--tw-ring-color)" }}
                                        required
                                    />
                                </div>
                                <button
                                    type="submit"
                                    disabled={pesquisando || !termoBusca.trim()}
                                    className="w-full text-white font-bold py-3 rounded-lg transition-colors disabled:opacity-50 flex justify-center items-center gap-2 shadow-md hover:brightness-110"
                                    style={{ backgroundColor: organizacao.primary_color }}
                                >
                                    {pesquisando ? (
                                        <><div className="animate-spin w-5 h-5 border-2 border-white border-t-transparent rounded-full" /> Buscando pedido...</>
                                    ) : (
