                )}

                {etapa === "confirmacao" && (
                    <Card className="shadow-lg border-green-100 animate-in slide-in-from-right-4">
                        <CardHeader className="text-center pb-2">
                            <CardTitle className="text-xl">Confirme sua Identidade</CardTitle>
