export default function RecursosHumanos() {
  const { user, loading, can } = useAuth();
  const [activeTab, setActiveTab] = useState("colaboradores");
  const canViewRH = can('view_rh') || can('manage_rh');

  // Fetch all HR data
  const { data: colaboradores = [], refetch: refetchColaboradores } = useQuery({
    queryKey: ['colaboradores'],
    queryFn: () => base44.entities.Colaborador.list(),
    enabled: !!user && canViewRH,
  });

  const { data: ferias = [], refetch: refetchFerias } = useQuery({
    queryKey: ['ferias'],
    queryFn: () => base44.entities.Ferias.list('-data_inicio'),
    enabled: !!user && canViewRH,
  });

  const { data: licencas = [] } = useQuery({
    queryKey: ['licencas'],
    queryFn: () => base44.entities.Licenca.list('-data_inicio'),
    enabled: !!user && canViewRH,
  });

  const { data: vagas = [] } = useQuery({
    queryKey: ['vagas'],
    queryFn: () => base44.entities.Vaga.list(),
    enabled: !!user && canViewRH,
  });

  const { data: folhas = [] } = useQuery({
    queryKey: ['folhas_pagamento'],
    queryFn: () => base44.entities.FolhaPagamento.list(),
    enabled: !!user && canViewRH,
  });

  const { data: avaliacoes = [] } = useQuery({
    queryKey: ['avaliacoes_desempenho'],
    queryFn: () => base44.entities.AvaliacaoDesempenho.list(),
    enabled: !!user && canViewRH,
  });

  // Calculate metrics and alerts
  const metrics = useMemo(() => {
    const hoje = new Date();
    const proximos30Dias = new Date(hoje.getTime() + 30 * 24 * 60 * 60 * 1000);
    const currentMonth = hoje.getMonth() + 1;
    const currentYear = hoje.getFullYear();

    // Colaboradores
    const colaboradoresAtivos = colaboradores.filter(c => c.status === 'Ativo').length;
    const colaboradoresFerias = colaboradores.filter(c => c.status === 'Férias').length;
    const colaboradoresAfastados = colaboradores.filter(c => c.status === 'Afastado' || c.status === 'Licença').length;

    // Férias pendentes de aprovação
    const feriasPendentes = ferias.filter(f => f.status === 'Solicitada').length;
    const licencasPendentes = licencas.filter(l => l.status === 'Solicitada').length;

    // Férias próximas (próximos 30 dias)
    const feriasProximas = ferias.filter(f => {
      if (f.status !== 'Aprovada' && f.status !== 'Em Gozo') return false;
      const dataInicio = new Date(f.data_inicio);
      return dataInicio >= hoje && dataInicio <= proximos30Dias;
    }).length;

    // Vagas abertas
    const vagasAbertas = vagas.filter(v => v.status === 'Aberta').length;
    const candidatosPendentes = vagas.reduce((sum, v) =>
      sum + (v.candidatos?.filter(c => c.status === 'Em Análise')?.length || 0), 0
    );

    // Folha do mês
    const folhasMesAtual = folhas.filter(f =>
      f.mes_referencia === currentMonth && f.ano_referencia === currentYear
    );

    const isFolhaPendente = (f) => {
      if (f.status === 'Pago' || f.status === 'Cancelado') return false;

      // Se for de meses/anos anteriores, qualquer coisa não paga está pendente
      const isPastMonth = f.ano_referencia < currentYear || (f.ano_referencia === currentYear && f.mes_referencia < currentMonth);
      if (isPastMonth) return true;

      // Se for de meses futuros, nada está pendente ainda
      const isFutureMonth = f.ano_referencia > currentYear || (f.ano_referencia === currentYear && f.mes_referencia > currentMonth);
      if (isFutureMonth) return false;

      // Mês atual: verificar por datas
      const colab = colaboradores.find(c => c.id === f.colaborador_id || c.nome_completo === f.colaborador_nome);
      const diaHoje = hoje.getDate();

      const recebeVale = colab?.recebe_vale === true;
      const valorDiaPagamento = Number(colab?.valor_dia_pagamento) || 0;
      const valorDiaVale = Number(colab?.valor_dia_vale) || 0;
      const temDistribuicao = recebeVale && (valorDiaPagamento + valorDiaVale) > 0;

      if (temDistribuicao) {
        const diaPgto = Number(colab.dia_pagamento) || 5;
        const diaV = Number(colab.dia_vale) || 20;

        const salPendente = f.salario_pago !== true && diaHoje >= diaPgto;
        const valePendente = f.vale_pago !== true && diaHoje >= diaV;

        return salPendente || valePendente;
      } else {
        const diaPgto = Number(colab?.dia_pagamento) || 5;
        return f.salario_pago !== true && diaHoje >= diaPgto;
      }
    };

    const totalFolhaMes = folhasMesAtual.reduce((sum, f) => sum + (Number(f.salario_liquido) || 0), 0);
    const folhasPendentes = folhasMesAtual.filter(isFolhaPendente).length;

    // Avaliações
    const avaliacoesPendentes = avaliacoes.filter(a => a.status === 'Rascunho').length;
    const avaliacoesTotal = avaliacoes.length;

    // Contratos a vencer (próximos 60 dias)
    const contratosVencer = colaboradores.filter(c => {
      if (!c.data_fim_contrato || c.status !== 'Ativo') return false;
      const dataFim = new Date(c.data_fim_contrato);
      const proximos60Dias = new Date(hoje.getTime() + 60 * 24 * 60 * 60 * 1000);
      return dataFim >= hoje && dataFim <= proximos60Dias;
    }).length;

    return {
      colaboradoresAtivos,
      colaboradoresFerias,
      colaboradoresAfastados,
      feriasPendentes,
      licencasPendentes,
      feriasProximas,
      vagasAbertas,
      candidatosPendentes,
      totalFolhaMes,
      folhasPendentes,
      avaliacoesPendentes,
      avaliacoesTotal,
      contratosVencer,
      totalPendencias: feriasPendentes + licencasPendentes + folhasPendentes + avaliacoesPendentes
    };
  }, [colaboradores, ferias, licencas, vagas, folhas, avaliacoes]);

  const handleRefreshData = () => {
    refetchColaboradores();
    refetchFerias();
  };

  if (loading || !user) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2" style={{ borderColor: '#07593f' }} />
      </div>
    );
  }

  if (!canViewRH) {
    return (
      <div className="p-4 md:p-8">
        <div className="max-w-7xl mx-auto">
          <Card className="border-2 border-red-200 bg-red-50">
            <CardContent className="p-8 text-center">
              <AlertCircle className="w-16 h-16 mx-auto mb-4 text-red-600" />
              <h2 className="text-2xl font-bold mb-2 text-red-800">
                Acesso Restrito
              </h2>
              <p className="text-red-600">
                Você não tem permissão para acessar o módulo de Recursos Humanos.
              </p>
            </CardContent>
          </Card>
        </div>
      </div>
    );
  }

  return (
    <div className="p-4 md:p-6 lg:p-8 bg-gray-50/50 min-h-screen">
      <div className="max-w-7xl mx-auto space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <h1 className="text-xl font-bold text-gray-900">
              Recursos Humanos
            </h1>
            {metrics.totalPendencias > 0 && (
              <Badge className="bg-red-500 text-white">
                {metrics.totalPendencias} pendente{metrics.totalPendencias > 1 ? 's' : ''}
              </Badge>
            )}
          </div>
          <Button
            variant="outline"
            size="sm"
            onClick={handleRefreshData}
            className="flex items-center gap-2"
          >
            <RefreshCw className="w-4 h-4" />
            Atualizar
          </Button>
        </div>

        {/* Alerts Section */}
        {(metrics.feriasPendentes > 0 || metrics.licencasPendentes > 0 || metrics.contratosVencer > 0 || metrics.avaliacoesPendentes > 0) && (
          <Card className="border-0 shadow-lg bg-gradient-to-r from-amber-50 to-orange-50">
            <CardHeader className="pb-2">
              <CardTitle className="flex items-center gap-2 text-lg">
                <Bell className="w-5 h-5 text-amber-600" />
                Ações Pendentes
              </CardTitle>
            </CardHeader>
            <CardContent className="pt-2">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                {metrics.feriasPendentes > 0 && (
                  <AlertCard
                    icon={Calendar}
                    title="Férias Aguardando"
                    count={metrics.feriasPendentes}
                    description="Solicitações de férias para aprovar"
                    color="#f59e0b"
                    onClick={() => setActiveTab("ferias")}
                  />
                )}
                {metrics.licencasPendentes > 0 && (
                  <AlertCard
                    icon={FileWarning}
                    title="Licenças Aguardando"
                    count={metrics.licencasPendentes}
                    description="Solicitações de licença para aprovar"
                    color="#ef4444"
                    onClick={() => setActiveTab("ferias")}
                  />
                )}
                {metrics.contratosVencer > 0 && (
                  <AlertCard
                    icon={AlertTriangle}
                    title="Contratos Vencendo"
                    count={metrics.contratosVencer}
                    description="Contratos vencem nos próximos 60 dias"
                    color="#8b5cf6"
                    onClick={() => setActiveTab("colaboradores")}
                  />
                )}
                {metrics.avaliacoesPendentes > 0 && (
                  <AlertCard
                    icon={ClipboardCheck}
                    title="Avaliações Pendentes"
                    count={metrics.avaliacoesPendentes}
                    description="Avaliações em rascunho para finalizar"
                    color="#3b82f6"
                    onClick={() => setActiveTab("avaliacoes")}
                  />
                )}
              </div>
            </CardContent>
          </Card>
        )}

        {/* Main Metrics Dashboard */}
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-2">
          <MetricCard
            icon={UserCheck}
            value={metrics.colaboradoresAtivos}
            label="Colaboradores Ativos"
            color="#07593f"
            onClick={() => setActiveTab("colaboradores")}
          />
          <MetricCard
            icon={Calendar}
            value={metrics.feriasProximas}
            label="Férias Próximas"
            color="#3b82f6"
            badge={metrics.feriasPendentes}
            onClick={() => setActiveTab("ferias")}
          />
          <MetricCard
            icon={Briefcase}
            value={metrics.vagasAbertas}
            label="Vagas Abertas"
            color="#f38a4c"
            badge={metrics.candidatosPendentes}
            onClick={() => setActiveTab("recrutamento")}
          />
          <MetricCard
            icon={DollarSign}
            value={metrics.totalFolhaMes > 0 ? `R$ ${(metrics.totalFolhaMes / 1000).toFixed(0)}k` : 'R$ 0'}
            label="Folha do Mês"
            color="#22c55e"
            badge={metrics.folhasPendentes}
            onClick={() => setActiveTab("folha")}
          />
          <MetricCard
            icon={Award}
            value={metrics.avaliacoesTotal}
            label="Avaliações"
            color="#8b5cf6"
            badge={metrics.avaliacoesPendentes}
            onClick={() => setActiveTab("avaliacoes")}
          />
          <MetricCard
            icon={CalendarClock}
            value={metrics.colaboradoresFerias + metrics.colaboradoresAfastados}
            label="Em Férias/Licença"
            color="#64748b"
            onClick={() => setActiveTab("ferias")}
          />
        </div>

        {/* Main Tabs */}
        <Tabs value={activeTab} onValueChange={setActiveTab} className="space-y-4">
          <Card className="border-0 shadow-lg">
            <CardContent className="p-2">
              <TabsList className="flex flex-wrap h-auto p-1 gap-1 bg-gray-100/50 w-full">
                <TabsTrigger value="colaboradores" className="flex-1 min-w-[120px] py-2.5 px-3 text-xs md:text-sm data-[state=active]:bg-white data-[state=active]:shadow-sm">
                  <Users className="w-4 h-4 mr-1.5" />
                  <span className="hidden sm:inline">Colaboradores</span>
                  <span className="sm:hidden">Colab.</span>
                </TabsTrigger>
                <TabsTrigger value="ferias" className="flex-1 min-w-[100px] py-2.5 px-3 text-xs md:text-sm data-[state=active]:bg-white data-[state=active]:shadow-sm relative">
                  <Calendar className="w-4 h-4 mr-1.5" />
                  <span className="hidden sm:inline">Férias</span>
                  <span className="sm:hidden">Fér.</span>
                  {(metrics.feriasPendentes + metrics.licencasPendentes) > 0 && (
                    <Badge className="absolute -top-1 -right-1 w-5 h-5 p-0 flex items-center justify-center text-xs bg-red-500">{metrics.feriasPendentes + metrics.licencasPendentes}</Badge>
                  )}
                </TabsTrigger>
                <TabsTrigger value="recrutamento" className="flex-1 min-w-[120px] py-2.5 px-3 text-xs md:text-sm data-[state=active]:bg-white data-[state=active]:shadow-sm">
                  <Briefcase className="w-4 h-4 mr-1.5" />
                  <span className="hidden sm:inline">Recrutamento</span>
                  <span className="sm:hidden">Recr.</span>
                </TabsTrigger>
                <TabsTrigger value="folha" className="flex-1 min-w-[100px] py-2.5 px-3 text-xs md:text-sm data-[state=active]:bg-white data-[state=active]:shadow-sm relative">
                  <DollarSign className="w-4 h-4 mr-1.5" />
                  <span className="hidden sm:inline">Folha</span>
                  <span className="sm:hidden">$</span>
                  {metrics.folhasPendentes > 0 && (
                    <Badge className="absolute -top-1 -right-1 w-5 h-5 p-0 flex items-center justify-center text-xs bg-amber-500">{metrics.folhasPendentes}</Badge>
                  )}
                </TabsTrigger>
                <TabsTrigger value="avaliacoes" className="flex-1 min-w-[100px] py-2.5 px-3 text-xs md:text-sm data-[state=active]:bg-white data-[state=active]:shadow-sm relative">
                  <Award className="w-4 h-4 mr-1.5" />
                  <span className="hidden sm:inline">Avaliações</span>
                  <span className="sm:hidden">Aval.</span>
                  {metrics.avaliacoesPendentes > 0 && (
                    <Badge className="absolute -top-1 -right-1 w-5 h-5 p-0 flex items-center justify-center text-xs bg-blue-500">{metrics.avaliacoesPendentes}</Badge>
                  )}
                </TabsTrigger>

                <TabsTrigger value="documentos" className="flex-1 min-w-[120px] py-2.5 px-3 text-xs md:text-sm data-[state=active]:bg-white data-[state=active]:shadow-sm">
                  <FolderOpen className="w-4 h-4 mr-1.5" />
                  <span className="hidden sm:inline">Documentos</span>
                  <span className="sm:hidden">Docs</span>
                </TabsTrigger>
              </TabsList>
            </CardContent>
          </Card>

          {/* Tab Contents */}
          <TabsContent value="colaboradores" className="mt-0">
            <ColaboradoresTab />
          </TabsContent>

          <TabsContent value="ferias" className="mt-0">
            <FeriasLicencasTab />
          </TabsContent>

          <TabsContent value="recrutamento" className="mt-0">
            <RecrutamentoTab />
          </TabsContent>

          <TabsContent value="folha" className="mt-0">
            <FolhaPagamentoTab />
          </TabsContent>

          <TabsContent value="avaliacoes" className="mt-0">
            <AvaliacoesTab />
          </TabsContent>



          <TabsContent value="documentos" className="mt-0">
            <DocumentosTab />
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { supabase } from "@/api/base44Client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import {
    Users, Activity, Clock, BarChart2, Search, RefreshCw, ChevronDown, ChevronUp
} from "lucide-react";

// ─── helpers ──────────────────────────────────────────────────────────────────

const CATEGORY_LABEL = {
    auth:        "Autenticação",
    navigation:  "Navegação",
    profile:     "Perfil",
    orders:      "Pedidos",
    loyalty:     "Fidelidade",
    support:     "Suporte",
};

const EVENT_LABEL = {
    login_success:                    "Login",
    logout:                           "Logout",
    dashboard_view:                   "Painel aberto",
    profile_edit_opened:              "Edição de perfil aberta",
    profile_saved:                    "Perfil salvo",
    orders_tab_opened:                "Aba de pedidos aberta",
    loyalty_tab_opened:               "Aba de fidelidade aberta",
    support_auto_atendimento_opened:  "Autoatendimento aberto",
};

function fmt(dateStr) {
    if (!dateStr) return "—";
    const d = new Date(dateStr);
    return d.toLocaleString("pt-BR", {
        day: "2-digit", month: "2-digit", year: "numeric",
        hour: "2-digit", minute: "2-digit",
    });
}

function fmtDate(dateStr) {
    if (!dateStr) return "—";
    const d = new Date(dateStr);
    return d.toLocaleDateString("pt-BR");
}

// ─── sub-componente: linha da tabela individual ────────────────────────────────

function ClienteRow({ row }) {
    const [open, setOpen] = useState(false);
    const categorias = row.eventos_por_categoria || {};
    const categoriaKeys = Object.keys(categorias);

    return (
        <>
            <tr
                className="border-b hover:bg-muted/30 cursor-pointer transition-colors"
                onClick={() => setOpen(v => !v)}
            >
                <td className="py-3 px-4 font-medium text-sm">
                    {row.nome_completo || row.email || row.auth_user_id?.slice(0, 8) + "…"}
                </td>
                <td className="py-3 px-4 text-sm text-center">{row.total_sessoes}</td>
                <td className="py-3 px-4 text-sm text-center">{row.total_eventos}</td>
                <td className="py-3 px-4 text-sm">{fmt(row.ultimo_acesso)}</td>
                <td className="py-3 px-4 text-sm">{fmt(row.primeiro_acesso)}</td>
                <td className="py-3 px-4 text-sm text-center">
                    <div className="flex flex-wrap gap-1 justify-center">
                        {categoriaKeys.slice(0, 3).map(cat => (
                            <Badge key={cat} variant="outline" className="text-xs capitalize">
                                {CATEGORY_LABEL[cat] || cat}
                            </Badge>
                        ))}
                        {categoriaKeys.length > 3 && (
                            <Badge variant="secondary" className="text-xs">+{categoriaKeys.length - 3}</Badge>
                        )}
                    </div>
                </td>
                <td className="py-3 px-4 text-center">
                    {open ? <ChevronUp className="w-4 h-4 mx-auto text-muted-foreground" />
                           : <ChevronDown className="w-4 h-4 mx-auto text-muted-foreground" />}
                </td>
            </tr>
            {open && (
                <tr className="bg-muted/20">
                    <td colSpan={7} className="px-6 py-3">
                        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-2 text-xs">
                            {categoriaKeys.map(cat => (
                                <div key={cat} className="bg-white border rounded px-3 py-2 flex justify-between">
                                    <span className="text-muted-foreground capitalize">
                                        {CATEGORY_LABEL[cat] || cat}
                                    </span>
                                    <span className="font-semibold">{categorias[cat]} eventos</span>
                                </div>
                            ))}
                            {categoriaKeys.length === 0 && (
                                <span className="text-muted-foreground col-span-4">Sem detalhes de categoria.</span>
                            )}
                        </div>
                    </td>
                </tr>
            )}
        </>
    );
}

// ─── componente principal ──────────────────────────────────────────────────────

export default function RelatorioAcessosClientes() {
    const today = new Date().toISOString().split("T")[0];
    const thirtyDaysAgo = new Date(Date.now() - 30 * 86400000).toISOString().split("T")[0];

    const [dateFrom, setDateFrom] = useState(thirtyDaysAgo);
    const [dateTo,   setDateTo]   = useState(today);
    const [search,   setSearch]   = useState("");

    const [kpis,       setKpis]       = useState(null);
    const [funnel,     setFunnel]     = useState([]);
    const [individual, setIndividual] = useState([]);
    const [loading,    setLoading]    = useState(false);
    const [error,      setError]      = useState(null);

    async function fetchAll() {
        setLoading(true);
        setError(null);
        try {
            const fromTs = dateFrom + "T00:00:00Z";
            const toTs   = dateTo   + "T23:59:59Z";

            // ── KPIs agregados no período ──
            const { data: kpiRows, error: kpiErr } = await supabase
                .from("vw_cliente_acesso_indice_geral_diario")
                .select("*")
                .gte("dia", dateFrom)
                .lte("dia", dateTo);
            if (kpiErr) throw kpiErr;

            const kpiAgg = (kpiRows || []).reduce(
                (acc, row) => {
                    acc.totalEventos   += Number(row.total_eventos   || 0);
                    acc.totalSessoes   += Number(row.total_sessoes   || 0);
                    acc.clientesUnicos  = Math.max(acc.clientesUnicos, Number(row.clientes_unicos || 0));
                    if (!acc.ultimoEvento || row.ultimo_evento > acc.ultimoEvento)
                        acc.ultimoEvento = row.ultimo_evento;
                    return acc;
                },
                { totalEventos: 0, totalSessoes: 0, clientesUnicos: 0, ultimoEvento: null }
            );

            // Clientes únicos reais no período (distinct)
            const { count: uniqueCount } = await supabase
                .from("cliente_sessoes_portal")
                .select("auth_user_id", { count: "exact", head: true })
                .gte("session_started_at", fromTs)
                .lte("session_started_at", toTs);

            setKpis({ ...kpiAgg, clientesUnicos: uniqueCount ?? kpiAgg.clientesUnicos });

            // ── Funil: eventos por categoria + nome ──
            const { data: funnelRows, error: funnelErr } = await supabase
                .from("cliente_acesso_eventos")
                .select("event_category, event_name")
                .gte("event_at", fromTs)
                .lte("event_at", toTs);
            if (funnelErr) throw funnelErr;

            const funnelMap = {};
            for (const row of funnelRows || []) {
                const key = `${row.event_category}||${row.event_name}`;
                funnelMap[key] = (funnelMap[key] || 0) + 1;
            }
            const funnelSorted = Object.entries(funnelMap)
                .map(([key, count]) => {
                    const [cat, evt] = key.split("||");
                    return { category: cat, event: evt, count };
                })
                .sort((a, b) => b.count - a.count);
            setFunnel(funnelSorted);

            // ── Índice individual ──
            const { data: indRows, error: indErr } = await supabase
                .from("vw_cliente_acesso_indice_individual")
                .select("*")
                .gte("ultimo_acesso", fromTs)
                .order("ultimo_acesso", { ascending: false });
            if (indErr) throw indErr;
            setIndividual(indRows || []);
        } catch (err) {
            setError(err.message || "Erro ao carregar dados.");
        } finally {
            setLoading(false);
        }
    }

    useEffect(() => { fetchAll(); }, []); // eslint-disable-line react-hooks/exhaustive-deps

    const filteredIndividual = individual.filter(row => {
        if (!search) return true;
        const s = search.toLowerCase();
        return (
            (row.nome_completo || "").toLowerCase().includes(s) ||
            (row.email || "").toLowerCase().includes(s)
        );
    });

    return (
        <div className="p-6 space-y-6">
            {/* Cabeçalho */}
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-foreground">Acessos do Portal do Cliente</h1>
                    <p className="text-sm text-muted-foreground mt-1">
                        Índice geral e individual de uso do portal pelos clientes.
                    </p>
                </div>
                {/* Filtros */}
                <div className="flex flex-wrap items-center gap-2">
                    <div className="flex items-center gap-1 text-sm">
                        <span className="text-muted-foreground">De</span>
                        <Input
                            type="date" lang="pt-BR" value={dateFrom}
                            onChange={e => setDateFrom(e.target.value)}
                            className="h-8 w-36 text-sm"
                        />
                    </div>
                    <div className="flex items-center gap-1 text-sm">
                        <span className="text-muted-foreground">até</span>
                        <Input
                            type="date" lang="pt-BR" value={dateTo}
                            onChange={e => setDateTo(e.target.value)}
                            className="h-8 w-36 text-sm"
                        />
                    </div>
                    <Button size="sm" onClick={fetchAll} disabled={loading} className="gap-1">
                        <RefreshCw className={`w-4 h-4 ${loading ? "animate-spin" : ""}`} />
                        Atualizar
                    </Button>
                </div>
            </div>

            {error && (
                <div className="bg-red-50 border border-red-200 text-red-700 text-sm rounded-lg p-4">
                    {error}
                </div>
            )}

            {/* KPIs */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <Card>
                    <CardContent className="pt-5 pb-4">
                        <div className="flex items-start justify-between">
                            <div>
                                <p className="text-xs text-muted-foreground uppercase tracking-wide">Clientes únicos</p>
                                <p className="text-3xl font-bold mt-1">{kpis?.clientesUnicos ?? "—"}</p>
                            </div>
                            <div className="w-9 h-9 rounded-full bg-green-100 flex items-center justify-center">
                                <Users className="w-5 h-5 text-green-700" />
                            </div>
                        </div>
                    </CardContent>
                </Card>
                <Card>
                    <CardContent className="pt-5 pb-4">
                        <div className="flex items-start justify-between">
                            <div>
                                <p className="text-xs text-muted-foreground uppercase tracking-wide">Total de sessões</p>
                                <p className="text-3xl font-bold mt-1">{kpis?.totalSessoes ?? "—"}</p>
                            </div>
                            <div className="w-9 h-9 rounded-full bg-blue-100 flex items-center justify-center">
                                <Activity className="w-5 h-5 text-blue-700" />
                            </div>
                        </div>
                    </CardContent>
                </Card>
                <Card>
                    <CardContent className="pt-5 pb-4">
                        <div className="flex items-start justify-between">
                            <div>
                                <p className="text-xs text-muted-foreground uppercase tracking-wide">Total de eventos</p>
                                <p className="text-3xl font-bold mt-1">{kpis?.totalEventos ?? "—"}</p>
                            </div>
                            <div className="w-9 h-9 rounded-full bg-purple-100 flex items-center justify-center">
                                <BarChart2 className="w-5 h-5 text-purple-700" />
                            </div>
                        </div>
                    </CardContent>
                </Card>
                <Card>
                    <CardContent className="pt-5 pb-4">
                        <div className="flex items-start justify-between">
                            <div>
                                <p className="text-xs text-muted-foreground uppercase tracking-wide">Último acesso</p>
                                <p className="text-sm font-semibold mt-2 leading-tight">{fmt(kpis?.ultimoEvento)}</p>
                            </div>
                            <div className="w-9 h-9 rounded-full bg-amber-100 flex items-center justify-center">
                                <Clock className="w-5 h-5 text-amber-700" />
                            </div>
                        </div>
                    </CardContent>
                </Card>
            </div>

            {/* Funil de eventos */}
            <Card>
                <CardHeader className="pb-2">
                    <CardTitle className="text-base">Funil de objetivos — o que os clientes fazem no portal</CardTitle>
                </CardHeader>
                <CardContent>
                    {funnel.length === 0 && !loading && (
                        <p className="text-sm text-muted-foreground text-center py-6">
                            Nenhum evento registrado no período.
                        </p>
                    )}
                    {funnel.length > 0 && (
                        <div className="space-y-2">
                            {funnel.map((item, i) => {
                                const maxCount = funnel[0]?.count || 1;
                                const pct = Math.round((item.count / maxCount) * 100);
                                return (
                                    <div key={i} className="flex items-center gap-3">
                                        <div className="w-40 shrink-0 text-right">
                                            <span className="text-xs font-medium text-foreground">
                                                {EVENT_LABEL[item.event] || item.event}
                                            </span>
                                            <br />
                                            <span className="text-xs text-muted-foreground capitalize">
                                                {CATEGORY_LABEL[item.category] || item.category}
                                            </span>
                                        </div>
                                        <div className="flex-1 h-5 bg-muted rounded-full overflow-hidden">
                                            <div
                                                className="h-full bg-green-600 rounded-full transition-all"
                                                style={{ width: `${pct}%` }}
                                            />
                                        </div>
                                        <span className="w-12 text-right text-sm font-semibold text-foreground shrink-0">
                                            {item.count}
                                        </span>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </CardContent>
            </Card>

            {/* Tabela individual */}
            <Card>
                <CardHeader className="pb-3">
                    <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
                        <CardTitle className="text-base">Índice individual de clientes</CardTitle>
                        <div className="relative w-full sm:w-64">
                            <Search className="absolute left-2.5 top-2.5 w-4 h-4 text-muted-foreground" />
                            <Input
                                placeholder="Buscar cliente..."
                                value={search}
                                onChange={e => setSearch(e.target.value)}
                                className="pl-8 h-8 text-sm"
                            />
                        </div>
                    </div>
                </CardHeader>
                <CardContent className="p-0">
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm">
                            <thead>
                                <tr className="border-b bg-muted/40 text-muted-foreground text-xs uppercase tracking-wide">
                                    <th className="py-2 px-4 text-left">Cliente</th>
                                    <th className="py-2 px-4 text-center">Sessões</th>
                                    <th className="py-2 px-4 text-center">Eventos</th>
                                    <th className="py-2 px-4 text-left">Último acesso</th>
                                    <th className="py-2 px-4 text-left">Primeiro acesso</th>
                                    <th className="py-2 px-4 text-center">Objetivos</th>
                                    <th className="py-2 px-4 text-center w-8"></th>
                                </tr>
                            </thead>
                            <tbody>
                                {loading && (
                                    <tr>
                                        <td colSpan={7} className="text-center py-10 text-muted-foreground text-sm">
                                            Carregando...
                                        </td>
                                    </tr>
                                )}
                                {!loading && filteredIndividual.length === 0 && (
                                    <tr>
                                        <td colSpan={7} className="text-center py-10 text-muted-foreground text-sm">
                                            {search ? "Nenhum cliente encontrado para esta busca." : "Nenhum acesso registrado no período."}
                                        </td>
                                    </tr>
                                )}
                                {!loading && filteredIndividual.map((row, i) => (
                                    <ClienteRow key={row.auth_user_id || i} row={row} />
                                ))}
                            </tbody>
                        </table>
                    </div>
                    {filteredIndividual.length > 0 && (
                        <p className="text-xs text-muted-foreground text-right px-4 py-2">
                            {filteredIndividual.length} cliente{filteredIndividual.length !== 1 ? "s" : ""} com acesso no período
                        </p>
                    )}
                </CardContent>
            </Card>
        </div>
    );
}

import React, { useState, useEffect } from "react";
import { base44, supabase } from "@/lib/supabase";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { DollarSign, TrendingUp, Users, FileDown, AlertCircle, Calendar, Banknote, RefreshCcw, Lock, CheckCircle2, Target, BarChart3 } from "lucide-react";
import { ModalNiveisComissao } from "@/components/comissoes/ModalNiveisComissao";
import { calcularVendasLiquidas, calcularComissaoTiered } from "@/services/comissaoTiersService";
import { Badge } from "@/components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { toast } from "sonner";
import { useTenant } from "@/contexts/TenantContext";

export default function RelatorioComissoes() {
  const { organization, settings } = useTenant();
  const [user, setUser] = useState(null);
  const [vendedorFiltro, setVendedorFiltro] = useState("todos");
  const [mesInicio, setMesInicio] = useState(new Date().toISOString().slice(0, 7));
  const [mesFim, setMesFim] = useState(new Date().toISOString().slice(0, 7));

  // States for payment modal
  const [modalPagamento, setModalPagamento] = useState(false);
  const [pagamentoSelecionado, setPagamentoSelecionado] = useState(null);
  const [dataPagamento, setDataPagamento] = useState(new Date().toISOString().slice(0, 10));
  const [processandoPagamento, setProcessandoPagamento] = useState(false);
  const [observacaoPagamento, setObservacaoPagamento] = useState("");
  const [processandoFechamento, setProcessandoFechamento] = useState(false);
  const [modalNiveisVendedor, setModalNiveisVendedor] = useState(null);
  const queryClient = useQueryClient();

  const tenantId = organization?.id || "00000000-0000-0000-0000-000000000001";

  useEffect(() => {
    const loadUser = async () => {
      const currentUser = await base44.auth.me();
      setUser(currentUser);
    };
    loadUser();
  }, []);

  const { data: vendas = [], isLoading } = useQuery({
    queryKey: ['vendas'],
    queryFn: () => base44.entities.Venda.list('-data_venda'),
  });

  const { data: vendedores = [] } = useQuery({
    queryKey: ['vendedores'],
    queryFn: () => base44.entities.Vendedor.list(),
  });

  const { data: assistencias = [] } = useQuery({
    queryKey: ['assistencias-comissoes'],
    queryFn: () => base44.entities.AssistenciaTecnica.list(),
  });

  const { data: fechamentos = [] } = useQuery({
    queryKey: ['comissoes-fechamento', mesInicio, mesFim, tenantId],
    queryFn: () => base44.entities.ComissaoFechamentoMensal.list('-created_at'),
  });

  const { data: configTaxas = [] } = useQuery({
    queryKey: ['configuracao_taxas'],
    queryFn: () => base44.entities.ConfiguracaoTaxa.list(),
  });

  const { data: niveisComissao = [] } = useQuery({
    queryKey: ['niveis-comissao'],
    queryFn: () => base44.entities.NivelComissao.list(),
  });

  const { data: niveisComissaoFaixas = [] } = useQuery({
    queryKey: ['niveis-comissao-faixas'],
    queryFn: () => base44.entities.NivelComissaoFaixa.list(),
  });

  if (!user) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2" style={{ borderColor: '#07593f' }} />
      </div>
    );
  }

  // Sistema simplificado - usa APENAS cargo
  const isAdmin = user.cargo === 'Administrador';

  if (!isAdmin) {
    return (
      <div className="p-4 md:p-8">
        <div className="max-w-7xl mx-auto">
          <Card className="border-2 border-red-200 bg-red-50">
            <CardContent className="p-8 text-center">
              <AlertCircle className="w-16 h-16 mx-auto mb-4 text-red-600" />
              <h2 className="text-2xl font-bold mb-2 text-red-800">
                Acesso Restrito
              </h2>
              <p className="text-red-600">
                Apenas administradores podem acessar o relatório de comissões.
              </p>
            </CardContent>
          </Card>
        </div>
      </div>
    );
  }

  // Filtrar vendas por período e vendedor
  const getVendedorRef = (venda) => venda.vendedor_id || venda.responsavel_id || venda.responsavel_nome || "sem-vendedor";

  const vendasFiltradas = vendas.filter(v => {
    const dataVenda = v.data_venda?.slice(0, 7); // YYYY-MM
    const dentroPeríodo = dataVenda >= mesInicio && dataVenda <= mesFim;
    const vendedorMatch = vendedorFiltro === "todos" || getVendedorRef(v) === vendedorFiltro;
    return dentroPeríodo && vendedorMatch && v.comissao_calculada > 0;
  });

  // Calcular breakdown por forma de pagamento para todas as vendas filtradas
  const calcularBreakdownPorFormaPagamento = (vendasArr) => {
    const breakdown = {};

    vendasArr.forEach(venda => {
      if (venda.pagamentos && Array.isArray(venda.pagamentos)) {
        venda.pagamentos.forEach(pag => {
          const forma = pag.forma_pagamento;
          if (!breakdown[forma]) {
            breakdown[forma] = { valor: 0, quantidade: 0 };
          }
          breakdown[forma].valor += pag.valor || 0;
          breakdown[forma].quantidade += 1;
        });
      }
    });

    return breakdown;
  };



  // Agrupar por vendedor (com fallback para responsavel_id em vendas antigas)
  const gruposPorVendedor = vendasFiltradas.reduce((acc, venda) => {
    const ref = getVendedorRef(venda);
    if (!acc[ref]) {
      const vendedorCadastrado = vendedores.find((ven) => ven.id === ref);
      acc[ref] = {
        vendedor: vendedorCadastrado || {
          id: ref,
          nome: venda.responsavel_nome || "Sem vendedor",
          loja: venda.loja || "-",
          meta_mensal: 0,
        },
        vendas: [],
      };
    }

    acc[ref].vendas.push(venda);
    return acc;
  }, {});

  const faturamentosLoja = {};
  Object.values(gruposPorVendedor).forEach((grupo) => {
    const loja = grupo.vendedor.loja || "-";
    const vendasVendedor = grupo.vendas;
    const totalVendasVendedor = vendasVendedor.reduce((sum, v) => {
      const assistencia = assistencias.find(a => a.numero_pedido === v.numero_pedido && a.status === 'Concluída');
      return sum + ((v.valor_total || 0) - (assistencia?.valor_devolvido || 0));
    }, 0);
    faturamentosLoja[loja] = (faturamentosLoja[loja] || 0) + totalVendasVendedor;
  });

  const comissoesPorVendedor = Object.values(gruposPorVendedor).map((grupo) => {
    const vendasVendedor = grupo.vendas;

    // Calcular comissão subtraindo devoluções
    const totalComissao = vendasVendedor.reduce((sum, v) => {
      const assistencia = assistencias.find(a =>
        a.numero_pedido === v.numero_pedido &&
        a.status === 'Concluída' &&
        (a.tipo === 'Devolução' || a.tipo === 'Troca')
      );

      const valorBaseComissao = Math.max(0, (v.valor_total || 0) - (assistencia?.valor_devolvido || 0));
      const porcentagem = v.comissao_calculada / (v.valor_total || 1);
      const comissaoAjustada = valorBaseComissao * porcentagem;

      return sum + comissaoAjustada;
    }, 0);

    const totalVendas = vendasVendedor.reduce((sum, v) => {
      const assistencia = assistencias.find(a => a.numero_pedido === v.numero_pedido && a.status === 'Concluída');
      return sum + ((v.valor_total || 0) - (assistencia?.valor_devolvido || 0));
    }, 0);

    const quantidadeVendas = vendasVendedor.length;
    const breakdownPagamentos = calcularBreakdownPorFormaPagamento(vendasVendedor);
    const vendasLiquidas = calcularVendasLiquidas(vendasVendedor, configTaxas);
    
    const nivelConfig = niveisComissao.find((n) => n.vendedor_id === grupo.vendedor.id && n.ativo !== false);
    const faixasNivel = nivelConfig ? niveisComissaoFaixas.filter((f) => f.nivel_comissao_id === nivelConfig.id) : [];
    const metaVendedor = nivelConfig?.meta_mensal || grupo.vendedor.meta_mensal || 0;

    // Configurações do modelo
    const faixaRef = settings?.comissao_faixa_referencia || 'vendedor';
    const pisoLoja = Number(settings?.comissao_meta_minima_loja_percentual || 0);

    const lojaVendedor = grupo.vendedor.loja || "-";
    const faturamentoLoja = faturamentosLoja[lojaVendedor] || 0;

    // Buscar meta da loja
    const metaLojaObj = metas.find(m => m.mes === `${mesInicio}-01` && m.loja === lojaVendedor && !m.vendedor_id);
    const metaLoja = metaLojaObj?.meta_valor || 0;

    const percentualMetaVendedor = metaVendedor > 0 ? (totalVendas / metaVendedor) * 100 : 0;
    const percentualMetaLoja = metaLoja > 0 ? (faturamentoLoja / metaLoja) * 100 : 0;

    let overridePercentual = undefined;
    let pisoLojaAtingido = true;

    if (faixaRef === 'loja') {
      overridePercentual = percentualMetaLoja;
    } else if (faixaRef === 'ambos') {
      overridePercentual = percentualMetaVendedor;
      if (percentualMetaLoja < pisoLoja) {
        pisoLojaAtingido = false;
      }
    }

    const comissaoTiered = nivelConfig && faixasNivel.length > 0 && (faixaRef !== 'ambos' || pisoLojaAtingido)
      ? calcularComissaoTiered({
          vendasBrutas: totalVendas,
          vendasLiquidas,
          meta: metaVendedor,
          faixas: faixasNivel,
          percentualMetaOverride: overridePercentual
        })
      : null;

    return {
      vendedor: grupo.vendedor,
      totalComissao,
      totalVendas,
      quantidadeVendas,
      breakdownPagamentos,
      vendasLiquidas,
      comissaoTiered,
      meta: metaVendedor,
      metaLoja,
      faturamentoLoja,
      percentualMetaLoja,
      pisoLojaAtingido,
      pisoLoja,
      faixaRef,
      vendas: vendasVendedor
    };
  }).filter(item => item.quantidadeVendas > 0);

  const getPeriodoInicioDate = () => new Date(`${mesInicio}-01T00:00:00`);

  const getPeriodoFimDate = () => {
    const [ano, mes] = mesFim.split('-').map(Number);
    return new Date(ano, mes, 0, 23, 59, 59, 999);
  };

  const periodoInicioDate = getPeriodoInicioDate();
  const periodoFimDate = getPeriodoFimDate();
  const periodoInicioIso = periodoInicioDate.toISOString().slice(0, 10);
  const periodoFimIso = periodoFimDate.toISOString().slice(0, 10);

  const fechamentosPeriodo = (fechamentos || []).filter((f) => {
    const inicio = (f.periodo_inicio || '').slice(0, 10);
    const fim = (f.periodo_fim || '').slice(0, 10);
    const vendedorMatch = vendedorFiltro === 'todos' || f.vendedor_id === vendedorFiltro;
    return (
      f.organization_id === tenantId &&
      inicio === periodoInicioIso &&
      fim === periodoFimIso &&
      vendedorMatch
    );
  });

  const mapFechamentoPorVendedor = new Map(
    fechamentosPeriodo.map((f) => [f.vendedor_id || `sem-vendedor-${f.id}`, f])
  );

  const comissoesConsolidadas = comissoesPorVendedor.map((item) => {
    const fechamento = mapFechamentoPorVendedor.get(item.vendedor.id);
    const modelo = settings?.comissao_modelo_calculo || 'regra_venda';

    let totalComissaoFinal = item.totalComissao;
    if (modelo === 'faixas_meta') {
      if (item.comissaoTiered && item.comissaoTiered.valorComissao > 0) {
        totalComissaoFinal = item.comissaoTiered.valorComissao;
      } else if (item.comissaoTiered && !item.pisoLojaAtingido) {
        totalComissaoFinal = item.totalComissao; // fallback se piso não atingido
      } else {
        totalComissaoFinal = 0; // se atingiu o piso mas faturamento abaixo do primeiro tier
      }
    }

    if (!fechamento) {
      return {
        ...item,
        fechamento_id: null,
        status_fechamento: 'Nao Fechado',
        totalFinal: totalComissaoFinal,
      };
    }

    return {
      ...item,
      fechamento_id: fechamento.id,
      status_fechamento: fechamento.status || 'Pendente',
      totalFinal: Number(fechamento.total_final || fechamento.total_comissao || totalComissaoFinal),
      fechamento,
    };
  });

  const totalGeralComissoes = comissoesConsolidadas.reduce((sum, item) => sum + item.totalFinal, 0);
  const totalGeralVendas = comissoesConsolidadas.reduce((sum, item) => sum + item.totalVendas, 0);

  const totalPendente = comissoesConsolidadas
    .filter((item) => item.status_fechamento !== 'Pago')
    .reduce((sum, item) => sum + Number(item.totalFinal || 0), 0);

  const aplicarPoliticaFechamento = (existente, politica) => {
    if (!existente) {
      return 'criar';
    }

    if (politica === 'recalcular_tudo') {
      return 'recriar';
    }

    if (politica === 'recalcular_periodo_aberto') {
      return existente.status === 'Pago' ? 'manter' : 'recriar';
    }

    return 'manter';
  };

  const gerarFechamentoPeriodo = async () => {
    setProcessandoFechamento(true);
    const politica = settings?.comissao_recalculo_politica || 'nao_recalcular';
    const modelo = settings?.comissao_modelo_calculo || 'regra_venda';

    try {
      const existentesPorVendedor = new Map(
        fechamentosPeriodo.map((item) => [item.vendedor_id || `sem-vendedor-${item.id}`, item])
      );

      let criados = 0;
      let atualizados = 0;
      let mantidos = 0;

      for (const item of comissoesPorVendedor) {
        const existente = existentesPorVendedor.get(item.vendedor.id);
        const acao = aplicarPoliticaFechamento(existente, politica);

        if (acao === 'manter') {
          mantidos += 1;
          continue;
        }

        let totalComissaoFinal = item.totalComissao;
        if (modelo === 'faixas_meta') {
          if (item.comissaoTiered && item.comissaoTiered.valorComissao > 0) {
            totalComissaoFinal = item.comissaoTiered.valorComissao;
          } else if (item.comissaoTiered && !item.pisoLojaAtingido) {
            totalComissaoFinal = item.totalComissao; // fallback
          } else {
            totalComissaoFinal = 0;
          }
        }

        if (acao === 'recriar' && existente) {
          await base44.entities.ComissaoFechamentoMensal.update(existente.id, {
            quantidade_vendas: item.quantidadeVendas,
            valor_total_vendas: Number(item.totalVendas.toFixed(2)),
            total_comissao: Number(totalComissaoFinal.toFixed(2)),
            total_final: Number(totalComissaoFinal.toFixed(2)),
            total_ajustes: Number(existente.total_ajustes || 0),
            valor_vendas_liquidas: Number(item.vendasLiquidas.toFixed(2)),
            percentual_meta_atingido: item.comissaoTiered ? Number(item.comissaoTiered.percentualMeta.toFixed(1)) : null,
            faixa_comissao_aplicada: item.comissaoTiered?.faixaAplicada ? `>=${item.comissaoTiered.faixaAplicada.percentual_meta_min}%` : null,
            percentual_comissao_aplicado: item.comissaoTiered?.percentualComissao ?? null,
            breakdown_pagamentos: item.breakdownPagamentos,
            status: existente.status || 'Pendente',
            observacoes: existente.observacoes || `Fechamento atualizado automaticamente (${politica})`,
            updated_at: new Date().toISOString(),
          });
          atualizados += 1;
          continue;
        }

        await base44.entities.ComissaoFechamentoMensal.create({
          organization_id: tenantId,
          periodo_inicio: periodoInicioIso,
          periodo_fim: periodoFimIso,
          vendedor_id: item.vendedor.id,
          loja: item.vendedor.loja || null,
          quantidade_vendas: item.quantidadeVendas,
          valor_total_vendas: Number(item.totalVendas.toFixed(2)),
          total_comissao: Number(totalComissaoFinal.toFixed(2)),
          total_ajustes: 0,
          total_final: Number(totalComissaoFinal.toFixed(2)),
          valor_vendas_liquidas: Number(item.vendasLiquidas.toFixed(2)),
          percentual_meta_atingido: item.comissaoTiered ? Number(item.comissaoTiered.percentualMeta.toFixed(1)) : null,
          faixa_comissao_aplicada: item.comissaoTiered?.faixaAplicada ? `>=${item.comissaoTiered.faixaAplicada.percentual_meta_min}%` : null,
          percentual_comissao_aplicado: item.comissaoTiered?.percentualComissao ?? null,
          status: 'Pendente',
          breakdown_pagamentos: item.breakdownPagamentos,
          observacoes: `Fechamento gerado automaticamente em ${new Date().toLocaleDateString('pt-BR')}`,
        });
        criados += 1;
      }

      queryClient.invalidateQueries(['comissoes-fechamento']);
      toast.success(`Fechamento concluído: ${criados} criado(s), ${atualizados} atualizado(s), ${mantidos} mantido(s).`);
    } catch (error) {
      toast.error(`Erro ao gerar fechamento: ${error.message}`);
    } finally {
      setProcessandoFechamento(false);
    }
  };

  const exportarCSV = () => {
    let csv = "Vendedor,Loja,Quantidade de Vendas,Total em Vendas,Total Comissões\n";

    comissoesPorVendedor.forEach(item => {
      csv += `${item.vendedor.nome},${item.vendedor.loja},${item.quantidadeVendas},R$ ${item.totalVendas.toFixed(2)},R$ ${item.totalComissao.toFixed(2)}\n`;
    });

    csv += `\nTOTAL GERAL,,${comissoesPorVendedor.reduce((sum, i) => sum + i.quantidadeVendas, 0)},R$ ${totalGeralVendas.toFixed(2)},R$ ${totalGeralComissoes.toFixed(2)}`;

    const blob = new Blob(["\ufeff" + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `comissoes_${mesInicio}_${mesFim}.csv`;
    a.style.display = 'none';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const abrirModalPagamento = (item) => {
    if (!item.fechamento_id) {
      toast.error('Feche o período antes de registrar pagamento.');
      return;
    }

    if (item.status_fechamento === 'Pago') {
      toast.info('Esta comissão já está marcada como paga.');
      return;
    }

    setPagamentoSelecionado(item);
    setDataPagamento(new Date().toISOString().slice(0, 10));
    setObservacaoPagamento("");
    setModalPagamento(true);
  };

  const confirmarPagamentoComissao = async () => {
    if (!pagamentoSelecionado) return;

    setProcessandoPagamento(true);
    try {
      await base44.entities.LancamentoFinanceiro.create({
        descricao: `Comissão - ${pagamentoSelecionado.vendedor.nome} - Ref: ${mesInicio === mesFim ? mesInicio : `${mesInicio} a ${mesFim}`}`,
        valor: -Number(pagamentoSelecionado.totalFinal.toFixed(2)),
        tipo: 'despesa',
        categoria_nome: 'Comissões',
        data_lancamento: dataPagamento,
        forma_pagamento: 'Transferência',
        status: 'Pago',
        observacao: `Pgto ref. ${pagamentoSelecionado.quantidadeVendas} vendas. ${observacaoPagamento}`,
      });

      if (pagamentoSelecionado.fechamento_id) {
        await base44.entities.ComissaoFechamentoMensal.update(pagamentoSelecionado.fechamento_id, {
          status: 'Pago',
          data_pagamento: `${dataPagamento}T12:00:00.000Z`,
          observacoes: observacaoPagamento || pagamentoSelecionado.fechamento?.observacoes || null,
          updated_at: new Date().toISOString(),
        });

        const dataInicioHistorico = `${periodoInicioIso}T00:00:00.000Z`;
        const dataFimHistorico = `${periodoFimIso}T23:59:59.999Z`;
        await supabase
          .from('comissoes_historico')
          .update({
            status: 'Pago',
            data_pagamento: `${dataPagamento}T12:00:00.000Z`,
          })
          .eq('organization_id', tenantId)
          .eq('vendedor_id', pagamentoSelecionado.vendedor.id)
          .gte('data_calculo', dataInicioHistorico)
          .lte('data_calculo', dataFimHistorico)
          .neq('status', 'Pago');
      }

      toast.success(`Pagamento registrado para ${pagamentoSelecionado.vendedor.nome}!`);
      setModalPagamento(false);
      setPagamentoSelecionado(null);
      queryClient.invalidateQueries(['comissoes-fechamento']);
      queryClient.invalidateQueries(['lancamentos']);

    } catch (error) {
      toast.error("Erro ao registrar pagamento: " + error.message);
    } finally {
      setProcessandoPagamento(false);
    }
  };

  return (
    <div className="p-4 md:p-8">
      <div className="max-w-7xl mx-auto">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-8">
          <div>
            <h1 className="text-3xl md:text-4xl font-bold mb-2" style={{ color: '#07593f' }}>
              Relatório de Comissões
            </h1>
            <p style={{ color: '#8B8B8B' }}>
              Análise detalhada por vendedor e período
            </p>
          </div>
          <div className="flex items-center gap-2">
            <Button
              onClick={gerarFechamentoPeriodo}
              variant="outline"
              disabled={processandoFechamento || comissoesPorVendedor.length === 0}
            >
              <RefreshCcw className="w-4 h-4 mr-2" />
              {processandoFechamento ? 'Processando...' : 'Gerar Fechamento'}
            </Button>
            <Button
              onClick={exportarCSV}
              className="shadow-lg"
              style={{ background: 'linear-gradient(135deg, #f38a4c 0%, #f5a164 100%)' }}
            >
              <FileDown className="w-4 h-4 mr-2" />
              Exportar CSV
            </Button>
          </div>
        </div>

        <Card className="border-0 shadow-lg mb-6">
          <CardContent className="p-4 md:p-5">
            <div className="grid md:grid-cols-4 gap-3">
              <div className="p-3 rounded-lg border" style={{ borderColor: '#E5E0D8' }}>
                <p className="text-xs text-gray-500">Período de fechamento</p>
                <p className="font-semibold" style={{ color: '#07593f' }}>{periodoInicioIso} a {periodoFimIso}</p>
              </div>
              <div className="p-3 rounded-lg border" style={{ borderColor: '#E5E0D8' }}>
                <p className="text-xs text-gray-500">Fechamentos encontrados</p>
                <p className="font-semibold" style={{ color: '#07593f' }}>{fechamentosPeriodo.length}</p>
              </div>
              <div className="p-3 rounded-lg border" style={{ borderColor: '#E5E0D8' }}>
                <p className="text-xs text-gray-500">Pendente para pagamento</p>
                <p className="font-semibold text-amber-600">
                  R$ {totalPendente.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                </p>
              </div>
              <div className="p-3 rounded-lg border" style={{ borderColor: '#E5E0D8' }}>
                <p className="text-xs text-gray-500">Política de recálculo</p>
                <p className="font-semibold" style={{ color: '#07593f' }}>
                  {settings?.comissao_recalculo_politica || 'nao_recalcular'}
                </p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className="border-0 shadow-lg mb-6">
          <CardContent className="p-6">
            <div className="grid md:grid-cols-4 gap-4">
              <div>
                <Label htmlFor="mesInicio">Período Inicial</Label>
                <Input
                  id="mesInicio"
                  type="month"
                  value={mesInicio}
                  onChange={(e) => setMesInicio(e.target.value)}
                />
              </div>
              <div>
                <Label htmlFor="mesFim">Período Final</Label>
                <Input
                  id="mesFim"
                  type="month"
                  value={mesFim}
                  onChange={(e) => setMesFim(e.target.value)}
                />
              </div>
              <div className="md:col-span-2">
                <Label htmlFor="vendedor">Vendedor</Label>
                <Select value={vendedorFiltro} onValueChange={setVendedorFiltro}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="todos">Todos os Vendedores</SelectItem>
                    {vendedores.map(v => (
                      <SelectItem key={v.id} value={v.id}>
                        {v.nome} - {v.loja}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
          </CardContent>
        </Card>

        <div className="grid md:grid-cols-3 gap-6 mb-8">
          <Card className="border-0 shadow-lg">
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium" style={{ color: '#8B8B8B' }}>
                Total em Comissões
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex items-center gap-2">
                <DollarSign className="w-8 h-8" style={{ color: '#f38a4c' }} />
                <p className="text-2xl font-bold" style={{ color: '#f38a4c' }}>
                  R$ {totalGeralComissoes.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                </p>
              </div>
            </CardContent>
          </Card>

          <Card className="border-0 shadow-lg">
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium" style={{ color: '#8B8B8B' }}>
                Total em Vendas
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex items-center gap-2">
                <TrendingUp className="w-8 h-8" style={{ color: '#07593f' }} />
                <p className="text-2xl font-bold" style={{ color: '#07593f' }}>
                  R$ {totalGeralVendas.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                </p>
              </div>
            </CardContent>
          </Card>

          <Card className="border-0 shadow-lg">
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium" style={{ color: '#8B8B8B' }}>
                Vendedores Ativos
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex items-center gap-2">
                <Users className="w-8 h-8" style={{ color: '#3b82f6' }} />
                <p className="text-2xl font-bold" style={{ color: '#3b82f6' }}>
                  {comissoesPorVendedor.length}
                </p>
              </div>
            </CardContent>
          </Card>
        </div>

        {isLoading ? (
          <div className="text-center py-12">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 mx-auto" style={{ borderColor: '#07593f' }} />
          </div>
        ) : comissoesConsolidadas.length === 0 ? (
          <Card className="border-0 shadow-lg">
            <CardContent className="p-12 text-center">
              <Calendar className="w-16 h-16 mx-auto mb-4 opacity-20" style={{ color: '#07593f' }} />
              <p className="text-xl" style={{ color: '#8B8B8B' }}>
                Nenhuma comissão encontrada no período selecionado
              </p>
            </CardContent>
          </Card>
        ) : (
          <div className="space-y-4">
            {comissoesConsolidadas.map((item) => (
              <Card key={item.vendedor.id} className="border-0 shadow-lg">
                <CardHeader style={{ backgroundColor: '#f0f9ff' }}>
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <div
                        className="w-12 h-12 rounded-full flex items-center justify-center text-xl"
                        style={{ backgroundColor: '#07593f', color: 'white' }}
                      >
                        {item.vendedor.nome.charAt(0).toUpperCase()}
                      </div>
                      <div>
                        <div className="flex items-center gap-2">
                          <CardTitle style={{ color: '#07593f' }}>
                            {item.vendedor.nome}
                          </CardTitle>
                          <button
                            onClick={() => setModalNiveisVendedor(item.vendedor)}
                            className="text-gray-400 hover:text-green-600 transition-colors"
                            title="Configurar Níveis de Comissão"
                          >
                            <Target className="w-4 h-4" />
                          </button>
                        </div>
                        <p className="text-sm" style={{ color: '#8B8B8B' }}>
                          Loja {item.vendedor.loja}
                        </p>
                      </div>
                    </div>
                    <div className="text-right">
                      <div className="flex items-center justify-end gap-2 mb-1">
                        <Badge
                          className={item.status_fechamento === 'Pago' ? 'bg-green-100 text-green-700' : item.status_fechamento === 'Pendente' ? 'bg-amber-100 text-amber-700' : 'bg-gray-100 text-gray-700'}
                        >
                          {item.status_fechamento === 'Pago' ? <CheckCircle2 className="w-3 h-3 mr-1" /> : <Lock className="w-3 h-3 mr-1" />}
                          {item.status_fechamento}
                        </Badge>
                      </div>
                      <p className="text-sm mb-1" style={{ color: '#8B8B8B' }}>Total Comissão</p>
                      <p className="text-2xl font-bold" style={{ color: '#f38a4c' }}>
                        R$ {item.totalFinal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                      </p>
                      <Button
                        size="sm"
                        variant="outline"
                        className="mt-2 h-8 text-green-700 border-green-200 hover:bg-green-50"
                        disabled={!item.fechamento_id || item.status_fechamento === 'Pago'}
                        onClick={() => abrirModalPagamento(item)}
                      >
                        <Banknote className="w-4 h-4 mr-1" />
                        {!item.fechamento_id ? 'Fechar Período Primeiro' : item.status_fechamento === 'Pago' ? 'Já Pago' : 'Registrar Pagamento'}
                      </Button>
                    </div>
                  </div>
                </CardHeader>
                <CardContent className="p-6">
                  <div className="grid md:grid-cols-4 gap-4 mb-4">
                    <div className="text-center p-3 rounded-lg" style={{ backgroundColor: '#FAF8F5' }}>
                      <p className="text-sm mb-1" style={{ color: '#8B8B8B' }}>Quantidade de Vendas</p>
                      <p className="text-xl font-bold" style={{ color: '#07593f' }}>
                        {item.quantidadeVendas}
                      </p>
                    </div>
                    <div className="text-center p-3 rounded-lg" style={{ backgroundColor: '#FAF8F5' }}>
                      <p className="text-sm mb-1" style={{ color: '#8B8B8B' }}>Total em Vendas</p>
                      <p className="text-xl font-bold" style={{ color: '#07593f' }}>
                        R$ {item.totalVendas.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                      </p>
                    </div>
                    <div className="text-center p-3 rounded-lg" style={{ backgroundColor: '#FFF7ED' }}>
                      <p className="text-sm mb-1" style={{ color: '#8B8B8B' }}>Vendas Líquidas</p>
                      <p className="text-xl font-bold text-orange-600">
                        R$ {item.vendasLiquidas.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                      </p>
                    </div>
                    <div className="text-center p-3 rounded-lg" style={{ backgroundColor: '#FAF8F5' }}>
                      <p className="text-sm mb-1" style={{ color: '#8B8B8B' }}>Ticket Médio</p>
                      <p className="text-xl font-bold" style={{ color: '#07593f' }}>
                        R$ {(item.totalVendas / item.quantidadeVendas).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                      </p>
                    </div>
                  </div>

                  {/* Comissão por Faixas */}
                  {settings?.comissao_modelo_calculo === 'faixas_meta' && (
                    <>
                      {/* Caso 1: Piso da loja não atingido */}
                      {!item.pisoLojaAtingido && (
                        <div className="mb-4 p-4 rounded-lg border-2 border-red-200 bg-red-50/50">
                          <div className="flex items-center justify-between flex-wrap gap-2">
                            <div className="flex items-center gap-2">
                              <AlertCircle className="w-4 h-4 text-red-600" />
                              <p className="text-sm font-semibold text-red-800">Piso da Loja Não Atingido</p>
                            </div>
                            <div className="flex items-center gap-3 flex-wrap">
                              <Badge className="bg-red-100 text-red-700">
                                Loja: {item.percentualMetaLoja.toFixed(1)}% (Piso Mínimo: {item.pisoLoja}%)
                              </Badge>
                              <span className="text-xs text-red-600 font-medium">
                                Revertido para Comissão Simples (Por Venda)
                              </span>
                            </div>
                          </div>
                        </div>
                      )}

                      {/* Caso 2: Piso atingido e possui faixa ativa */}
                      {item.pisoLojaAtingido && item.comissaoTiered && item.comissaoTiered.faixaAplicada && (
                        <div className="mb-4 p-4 rounded-lg border-2" style={{ borderColor: '#f38a4c', backgroundColor: '#fff7ed' }}>
                          <div className="flex items-center justify-between flex-wrap gap-2">
                            <div className="flex items-center gap-2">
                              <BarChart3 className="w-4 h-4 text-orange-600" />
                              <p className="text-sm font-semibold text-orange-800">Comissão por Faixas (Meta Atingida)</p>
                            </div>
                            <div className="flex items-center gap-3 flex-wrap">
                              <Badge className="bg-orange-100 text-orange-700">
                                {item.comissaoTiered.percentualMeta.toFixed(1)}% da meta
                              </Badge>
                              <Badge className="bg-green-100 text-green-700">
                                {`Faixa ≥${item.comissaoTiered.faixaAplicada.percentual_meta_min}% → ${item.comissaoTiered.percentualComissao}% ${item.comissaoTiered.faixaAplicada.base_calculo === 'bruto' ? 'bruto' : 'líquido'}`}
                              </Badge>
                              <span className="text-lg font-bold text-orange-700">
                                R$ {item.comissaoTiered.valorComissao.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                              </span>
                            </div>
                          </div>
                        </div>
                      )}

                      {/* Caso 3: Piso atingido mas faturamento abaixo do primeiro tier */}
                      {item.pisoLojaAtingido && item.comissaoTiered && !item.comissaoTiered.faixaAplicada && (
                        <div className="mb-4 p-4 rounded-lg border border-dashed border-gray-300 bg-gray-50 flex items-center justify-between flex-wrap gap-2">
                          <div className="flex items-center gap-2">
                            <AlertCircle className="w-4 h-4 text-gray-500" />
                            <span className="text-xs text-gray-500 font-medium">Faturamento individual abaixo do percentual mínimo para receber comissão.</span>
                          </div>
                          <Badge className="bg-gray-200 text-gray-700">0% de comissão</Badge>
                        </div>
                      )}
                    </>
                  )}

                  {/* Breakdown por Forma de Pagamento */}
                  {Object.keys(item.breakdownPagamentos).length > 0 && (
                    <div className="mt-4 p-4 rounded-lg border" style={{ borderColor: '#E5E0D8' }}>
                      <p className="text-sm font-semibold mb-3" style={{ color: '#07593f' }}>
                        Recebimentos por Forma de Pagamento
                      </p>
                      <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
                        {Object.entries(item.breakdownPagamentos).map(([forma, dados]) => (
                          <div key={forma} className="flex items-center justify-between p-2 rounded bg-gray-50">
                            <span className="text-sm text-gray-600">{forma}</span>
                            <span className="text-sm font-semibold" style={{ color: '#07593f' }}>
                              R$ {dados.valor.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                            </span>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}

                  {item.meta > 0 && (
                    <div className="mt-4 p-4 rounded-lg" style={{ backgroundColor: '#f0f9ff' }}>
                      <div className="flex items-center justify-between mb-2">
                        <p className="text-sm font-medium" style={{ color: '#07593f' }}>
                          Meta Individual: R$ {item.meta.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                        </p>
                        <Badge
                          style={{
                            backgroundColor: item.totalVendas >= item.meta ? '#D1FAE5' : '#FEF3C7',
                            color: item.totalVendas >= item.meta ? '#065F46' : '#92400E'
                          }}
                        >
                          {((item.totalVendas / item.meta) * 100).toFixed(0)}% atingido
                        </Badge>
                      </div>
                      <div className="w-full bg-gray-200 rounded-full h-2">
                        <div
                          className="h-2 rounded-full transition-all"
                          style={{
                            width: `${Math.min((item.totalVendas / item.meta) * 100, 100)}%`,
                            backgroundColor: item.totalVendas >= item.meta ? '#07593f' : '#f38a4c'
                          }}
                        />
                      </div>
                    </div>
                  )}

                  {/* Meta da Loja (se configurado como referência) */}
                  {settings?.comissao_modelo_calculo === 'faixas_meta' && item.faixaRef !== 'vendedor' && item.metaLoja > 0 && (
                    <div className="mt-3 p-4 rounded-lg" style={{ backgroundColor: '#FAF8F5' }}>
                      <div className="flex items-center justify-between mb-2">
                        <p className="text-sm font-medium text-gray-700">
                          Meta da Filial (Loja {item.vendedor.loja}): R$ {item.metaLoja.toLocaleString('pt-BR', { minimumFractionDigits: 2 })} (Faturamento: R$ {item.faturamentoLoja.toLocaleString('pt-BR', { minimumFractionDigits: 2 })})
                        </p>
                        <Badge
                          className={item.percentualMetaLoja >= 100 ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}
                        >
                          {item.percentualMetaLoja.toFixed(0)}% atingido
                        </Badge>
                      </div>
                      <div className="w-full bg-gray-200 rounded-full h-2">
                        <div
                          className="h-2 rounded-full transition-all"
                          style={{
                            width: `${Math.min(item.percentualMetaLoja, 100)}%`,
                            backgroundColor: item.percentualMetaLoja >= 100 ? '#07593f' : '#f38a4c'
                          }}
                        />
                      </div>
                    </div>
                  )}
                </CardContent>
              </Card>
            ))}
          </div>
        )}


        {modalNiveisVendedor && (
          <ModalNiveisComissao
            vendedor={modalNiveisVendedor}
            organizationId={tenantId}
            niveisComissao={niveisComissao}
            niveisComissaoFaixas={niveisComissaoFaixas}
            onClose={() => setModalNiveisVendedor(null)}
            onSaved={() => {
              queryClient.invalidateQueries({ queryKey: ['niveis-comissao'] });
              queryClient.invalidateQueries({ queryKey: ['niveis-comissao-faixas'] });
            }}
          />
        )}

        {/* Modal de Pagamento */}
        <Dialog open={modalPagamento} onOpenChange={setModalPagamento}>
          <DialogContent>
            <DialogHeader>
              <DialogTitle className="flex items-center gap-2">
                <Banknote className="w-5 h-5 text-green-600" />
                Registrar Pagamento de Comissão
              </DialogTitle>
              <DialogDescription>
                Confirmar pagamento para <strong>{pagamentoSelecionado?.vendedor.nome}</strong>
              </DialogDescription>
            </DialogHeader>

            <div className="space-y-4 py-4">
              <div className="p-4 bg-green-50 rounded-lg border border-green-100 text-center">
                <p className="text-sm text-gray-500 mb-1">Valor a Pagar</p>
                <p className="text-3xl font-bold text-green-700">
                  R$ {pagamentoSelecionado?.totalFinal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                </p>
              </div>

              <div className="grid gap-2">
                <Label htmlFor="dataPagamento">Data do Pagamento</Label>
                <Input
                  id="dataPagamento"
                  type="date" lang="pt-BR"
                  value={dataPagamento}
                  onChange={(e) => setDataPagamento(e.target.value)}
                />
              </div>

              <div className="grid gap-2">
                <Label htmlFor="obsPagamento">Observações (Opcional)</Label>
                <Input
                  id="obsPagamento"
                  placeholder="Ex: Pix, Transferência, etc."
                  value={observacaoPagamento}
                  onChange={(e) => setObservacaoPagamento(e.target.value)}
                />
              </div>
            </div>

            <DialogFooter>
              <Button variant="outline" onClick={() => setModalPagamento(false)}>Cancelar</Button>
              <Button
                onClick={confirmarPagamentoComissao}
                disabled={processandoPagamento}
                className="bg-green-600 hover:bg-green-700"
              >
                {processandoPagamento ? "Processando..." : "Confirmar Pagamento"}
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </div>
    </div >
  );
}

import React, { useState, useMemo } from "react";
import { base44 } from "@/api/base44Client";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { DollarSign, Percent, Users, TrendingDown, Tag, Key, Store, Calendar, ChevronDown, ChevronRight } from "lucide-react";
import { useAuth } from "@/hooks/useAuth";
import { isVendaCancelada } from "@/utils/vendaStatus";

const ORIGEM_LABELS = {
  margem_negociavel: { label: "Margem Livre", color: "bg-green-100 text-green-700" },
  token: { label: "Token Gerencial", color: "bg-amber-100 text-amber-700" },
  cupom: { label: "Cupom", color: "bg-purple-100 text-purple-700" },
  arredondamento: { label: "Arredondamento", color: "bg-blue-100 text-blue-700" },
  desconto_produto: { label: "Desc. por Produto", color: "bg-emerald-100 text-emerald-700" },
};

export default function RelatorioDescontos() {
  const { user, can, filterData } = useAuth();

  const [dataInicio, setDataInicio] = useState(() => {
    const d = new Date();
    d.setDate(1);
    return d.toISOString().slice(0, 10);
  });
  const [dataFim, setDataFim] = useState(() => new Date().toISOString().slice(0, 10));
  const [filtroVendedor, setFiltroVendedor] = useState("todos");
  const [filtroLoja, setFiltroLoja] = useState("todas");
  const [filtroOrigem, setFiltroOrigem] = useState("todas");
  const [linhasExpandidas, setLinhasExpandidas] = useState({});

  const { data: todasVendas = [], isLoading } = useQuery({
    queryKey: ["vendas"],
    queryFn: () => base44.entities.Venda.list("-data_venda"),
  });

  const { data: lojasData = [] } = useQuery({
    queryKey: ["lojas-ativas"],
    queryFn: () => base44.entities.Loja.list("nome"),
  });

  // Aplica filtro de escopo (RBAC)
  const vendasEscopo = useMemo(() => filterData(todasVendas, "store"), [todasVendas, filterData]);

  // Filtra vendas com desconto > 0, não canceladas, no período
  const vendasComDesconto = useMemo(() => {
    return vendasEscopo.filter(v => {
      if (isVendaCancelada(v)) return false;
      if ((v.desconto || 0) <= 0) return false;
      if (v.data_venda < dataInicio || v.data_venda > dataFim) return false;
      if (filtroVendedor !== "todos" && v.responsavel_id !== filtroVendedor) return false;
      if (filtroLoja !== "todas" && v.loja !== filtroLoja) return false;
      if (filtroOrigem !== "todas" && v.desconto_origem !== filtroOrigem) return false;
      return true;
    });
  }, [vendasEscopo, dataInicio, dataFim, filtroVendedor, filtroLoja, filtroOrigem]);

  // KPIs
  const kpis = useMemo(() => {
    const totalDescontos = vendasComDesconto.reduce((acc, v) => acc + (v.desconto || 0), 0);
    const percentMedio = vendasComDesconto.length > 0
      ? vendasComDesconto.reduce((acc, v) => acc + (v.desconto_percentual || 0), 0) / vendasComDesconto.length
      : 0;
    const totalVendas = vendasComDesconto.length;
    const valorMedio = totalVendas > 0 ? totalDescontos / totalVendas : 0;
    return { totalDescontos, percentMedio, totalVendas, valorMedio };
  }, [vendasComDesconto]);

  // Agrupamento por vendedor
  const porVendedor = useMemo(() => {
    const map = {};
    for (const v of vendasComDesconto) {
      const key = v.responsavel_id || "desconhecido";
      if (!map[key]) {
        map[key] = {
          id: key,
          nome: v.responsavel_nome || "Desconhecido",
          vendas: [],
        };
      }
      map[key].vendas.push(v);
    }
    return Object.values(map)
      .map(entry => {
        const totalDesconto = entry.vendas.reduce((acc, v) => acc + (v.desconto || 0), 0);
        const percentMedio = entry.vendas.length > 0
          ? entry.vendas.reduce((acc, v) => acc + (v.desconto_percentual || 0), 0) / entry.vendas.length
          : 0;
        const valorMedio = entry.vendas.length > 0 ? totalDesconto / entry.vendas.length : 0;
        return { ...entry, totalDesconto, percentMedio, valorMedio };
      })
      .sort((a, b) => b.totalDesconto - a.totalDesconto);
  }, [vendasComDesconto]);

  // Vendedores únicos para filtro
  const vendedoresUnicos = useMemo(() => {
    const map = {};
    vendasEscopo.forEach(v => {
