                        <TableCell className="text-right">
                          {v.desconto_origem ? (
                            <Badge className={`text-[10px] px-1.5 py-0 ${ORIGEM_LABELS[v.desconto_origem]?.color || 'bg-gray-100 text-gray-700'}`}>
                              {ORIGEM_LABELS[v.desconto_origem]?.label || v.desconto_origem}
