            );
            const podeLiberar = user?.cargo === 'Administrador' || user?.cargo === 'Gerente Geral' || venda.responsavel_id === user?.id;
            return Boolean(entregaAguardando && podeLiberar);
        });

        if (!elegiveis.length) {
