    );
}


const PAGES = {
    Dashboard, Produtos, Clientes, Vendas, Pedidos: Vendas, Devolucoes, Orcamentos, AssistenciaTecnica,
    Configuracoes, SelecaoVendedor,
    BoasVindas, GerenciamentoUsuarios, Financeiro, Montagem, Fornecedores, Compras,
