        log(`Novo cliente ${cliente.nome_completo}: +${bonus} Coroas`);
        return { sucesso: true, coroasGanhas: bonus, novoSaldo };
    } catch (error) {
        logError('Erro no bonus de cadastro:', error);
        return { sucesso: false, coroasGanhas: 0 };
    }
}

