import { isValidGTIN, normalizeGTIN, normalizeSKU } from './gtinValidator';

/**
 * Normaliza SKU para comparação case-insensitive ignorando apenas espaços externos.
 * Preserva caracteres especiais como /, ., _, - e não remove pontuações.
 *
 * @param {any} sku
 * @returns {string}
 */
export const normalizeSkuForComparison = (sku) => {
  return String(sku || '').trim().toLowerCase();
};

/**
 * Normaliza SKU para persistência no banco.
 * Apenas trim de espaços externos.
 *
 * @param {any} sku
 * @returns {string}
 */
export const normalizeSkuForStorage = (sku) => {
  return normalizeSKU(sku);
};

/**
 * Validador completo da planilha de importação de produtos.
 * Executa pré-validação de todas as linhas antes de qualquer escrita no banco.
 *
 * @param {object} params
 * @param {Array<object>} params.rows Linhas parsed do CSV
 * @param {Array<object>} [params.produtosExistentes=[]] Produtos já cadastrados no tenant
 * @param {string} params.organizationId ID da organização atual
 * @returns {object} Resultado detalhado da validação
 */
export const validateImportPlanilha = ({ rows = [], produtosExistentes = [], organizationId }) => {
  const errors = [];
  const skuToRows = new Map(); // normalizedSku -> array de { linha, row }
  const eanToRows = new Map(); // ean -> array de { linha, sku, row }

  if (!organizationId) {
    errors.push({
      linha: 0,
      campo: 'organization_id',
      tipo: 'TENANT_AUSENTE',
      mensagem: 'Organização não identificada. A importação foi bloqueada por segurança.',
    });
    return {
      isValid: false,
      errors,
      novos: [],
      atualizacoes: [],
      skuDuplicates: [],
      eanDuplicates: [],
    };
  }

  // Índice de produtos existentes no banco pelo SKU normalizado e pelo ID
  const existingBySku = new Map();
  const existingById = new Map();
  const existingByEan = new Map();

  for (const prod of produtosExistentes) {
    if (prod.sku) {
      existingBySku.set(normalizeSkuForComparison(prod.sku), prod);
    }
    if (prod.id) {
      existingById.set(String(prod.id), prod);
    }
    if (prod.codigo_barras) {
      existingByEan.set(String(prod.codigo_barras).trim(), prod);
    }
  }

  // 1ª Passagem: Validação individual de cada linha
  rows.forEach((row, index) => {
    const linhaNum = row.linha || index + 1;
    const rawSku = row.sku ?? row.codigo ?? row.codigo_interno ?? '';
    const cleanSku = normalizeSkuForStorage(rawSku);
    const normSku = normalizeSkuForComparison(cleanSku);

    // Validação obrigatória de SKU
    if (!cleanSku) {
      errors.push({
        linha: linhaNum,
        campo: 'sku',
        tipo: 'SKU_OBRIGATORIO',
        mensagem: `Linha ${linhaNum}: SKU/Código interno é obrigatório e não foi informado.`,
      });
    } else {
      if (!skuToRows.has(normSku)) {
        skuToRows.set(normSku, []);
      }
      skuToRows.get(normSku).push({ linha: linhaNum, row });
    }

    // Validação de divergência entre ID e SKU (se ID fornecido)
    const rawId = row.id ?? row.id_produto ?? null;
    if (rawId) {
      const prodExistingId = existingById.get(String(rawId));
      if (prodExistingId && cleanSku) {
        const existingProdNormSku = normalizeSkuForComparison(prodExistingId.sku);
        if (existingProdNormSku && existingProdNormSku !== normSku) {
          errors.push({
            linha: linhaNum,
            campo: 'id',
            tipo: 'CONFLITO_ID_SKU',
            mensagem: `Linha ${linhaNum}: ID "${rawId}" aponta para SKU "${prodExistingId.sku}", mas a linha contém SKU "${cleanSku}".`,
          });
        }
      }
    }

    // Validação do Código de Barras (EAN/GTIN)
    const rawEan = row.codigo_barras ?? row.ean ?? row.gtin ?? '';
    const trimmedEan = String(rawEan || '').trim();

    if (trimmedEan && !/^SEM\s*GTIN$/i.test(trimmedEan)) {
      if (!isValidGTIN(trimmedEan)) {
        errors.push({
          linha: linhaNum,
          campo: 'codigo_barras',
          tipo: 'EAN_INVALIDO',
          mensagem: `Linha ${linhaNum}: Código de barras "${trimmedEan}" inválido. Deve ser um GTIN válido (8, 12, 13 ou 14 dígitos com dígito verificador).`,
        });
      } else {
        // Validação de EAN duplicado entre SKUs diferentes na mesma planilha
        if (!eanToRows.has(trimmedEan)) {
          eanToRows.set(trimmedEan, []);
        }
        eanToRows.get(trimmedEan).push({ linha: linhaNum, sku: cleanSku, normSku });

        // Validação se o mesmo EAN já pertence a outro produto existente com SKU diferente
        const prodExistingEan = existingByEan.get(trimmedEan);
        if (prodExistingEan && cleanSku) {
          const existingEanNormSku = normalizeSkuForComparison(prodExistingEan.sku);
          if (existingEanNormSku && existingEanNormSku !== normSku) {
            errors.push({
              linha: linhaNum,
              campo: 'codigo_barras',
              tipo: 'EAN_JA_CADASTRADO_OUTRO_SKU',
              mensagem: `Linha ${linhaNum}: Código de barras "${trimmedEan}" já está associado a outro produto (SKU "${prodExistingEan.sku}"). O mesmo EAN não pode pertencer a SKUs distintos na mesma organização.`,
            });
          }
        }
      }
    }

    // Validação de variações com EAN ambíguo
    // Se a linha tiver múltiplas cores ou múltiplos tecidos separados por vírgula
    // e trouxer apenas 1 EAN, não podemos atribuir o mesmo EAN a vários produtos físicos.
    const corRaw = String(row.cor || row.variacao_de_cores || '').trim();
    const tecidoRaw = String(row.modelos_tecidos || row.tecidos || '').trim();
    const numCores = corRaw ? corRaw.split(',').map(c => c.trim()).filter(Boolean).length : 0;
    const numTecidos = tecidoRaw ? tecidoRaw.split(',').map(t => t.trim()).filter(Boolean).length : 0;
    const totalVariacoes = (numCores > 1 ? numCores : 1) * (numTecidos > 1 ? numTecidos : 1);

    if (totalVariacoes > 1 && trimmedEan && !/^SEM\s*GTIN$/i.test(trimmedEan)) {
      errors.push({
        linha: linhaNum,
        campo: 'codigo_barras',
        tipo: 'EAN_AMBIGUO_VARIACOES',
        mensagem: `Linha ${linhaNum}: Esta linha declara múltiplas variações (${totalVariacoes}) com um único EAN ("${trimmedEan}"). Cada item físico precisa de seu próprio EAN ou código de barras vazio.`,
      });
    }
  });

  // 2ª Passagem: Checar duplicidade de SKU dentro do próprio CSV
  const skuDuplicates = [];
  skuToRows.forEach((entries, normSku) => {
    if (entries.length > 1) {
      const linhas = entries.map(e => e.linha);
      const skuOriginal = entries[0].row.sku || normSku;
      skuDuplicates.push({ sku: skuOriginal, linhas });
      errors.push({
        linha: linhas[0],
        campo: 'sku',
        tipo: 'SKU_DUPLICADO_CSV',
        mensagem: `SKU "${skuOriginal}" aparece duplicado no CSV nas linhas: ${linhas.join(', ')}. Cada SKU deve aparecer apenas uma vez na planilha.`,
      });
    }
  });

  // 3ª Passagem: Checar duplicidade de EAN entre SKUs distintos dentro do próprio CSV
  const eanDuplicates = [];
  eanToRows.forEach((entries, ean) => {
    const distinctNormSkus = new Set(entries.map(e => e.normSku).filter(Boolean));
    if (distinctNormSkus.size > 1) {
      const conflito = entries.map(e => `linha ${e.linha} (SKU ${e.sku})`).join(', ');
      eanDuplicates.push({ ean, conflito });
      errors.push({
        linha: entries[0].linha,
        campo: 'codigo_barras',
        tipo: 'EAN_DUPLICADO_ENTRE_SKUS',
        mensagem: `Código de barras "${ean}" foi atribuído a SKUs diferentes no mesmo arquivo: ${conflito}.`,
      });
    }
  });

  // Classificação em novos vs atualizações
  const novos = [];
  const atualizacoes = [];

  rows.forEach((row, index) => {
    const cleanSku = normalizeSkuForStorage(row.sku ?? row.codigo ?? row.codigo_interno ?? '');
    const normSku = normalizeSkuForComparison(cleanSku);
    if (!normSku) return;

    const existingProduct = existingBySku.get(normSku);
    if (existingProduct) {
      atualizacoes.push({
        ...row,
        sku: cleanSku,
        codigo_barras: normalizeGTIN(row.codigo_barras ?? row.ean ?? row.gtin),
        id_existente: existingProduct.id,
        produto_existente: existingProduct,
      });
    } else {
      novos.push({
        ...row,
        sku: cleanSku,
        codigo_barras: normalizeGTIN(row.codigo_barras ?? row.ean ?? row.gtin),
      });
    }
  });

  return {
    isValid: errors.length === 0,
    errors,
    novos,
    atualizacoes,
    skuDuplicates,
    eanDuplicates,
  };
};

/**
 * Constrói payload seguro para inserção de um novo produto vindo da importação.
 * Aplica defaults necessários e nunca inventa ID nem sufixo.
 */
export const buildInsertProductPayload = (item, organizationId, extraFields = {}) => {
  if (!organizationId) {
    throw new Error('organization_id é obrigatório para cadastrar produtos.');
  }

  const cleanSku = normalizeSkuForStorage(item.sku);
  if (!cleanSku) {
    throw new Error('SKU é obrigatório para cadastrar produtos.');
  }

  const cleanEan = normalizeGTIN(item.codigo_barras);

  return {
    organization_id: organizationId,
    sku: cleanSku,
    codigo_barras: cleanEan,
    nome: String(item.nome || '').trim(),
    modelo_referencia: item.modelo_referencia !== undefined ? String(item.modelo_referencia || '').trim() : null,
    categoria: item.categoria || 'Outros',
    ambiente: item.ambiente || null,
    fornecedor_id: item.fornecedor_id || null,
    fornecedor_nome: item.fornecedor_nome || '',
    preco_custo: Number(item.preco_custo) || 0,
    preco_venda: Number(item.preco_venda) || 0,
    quantidade_estoque: 0, // Regra do sistema: estoque CSV é ignorado na importação inicial
    estoque_minimo: Number(item.estoque_minimo) || 0,
    largura: item.largura !== undefined && item.largura !== '' ? Number(item.largura) : null,
    altura: item.altura !== undefined && item.altura !== '' ? Number(item.altura) : null,
    profundidade: item.profundidade !== undefined && item.profundidade !== '' ? Number(item.profundidade) : null,
    material: item.material || '',
    cor: item.cor || '',
    cor_hex: item.cor_hex || null,
    variacoes: [],
    fotos: [],
    ativo: true,
    is_parent: false,
    parent_id: null,
    ...extraFields,
  };
};

/**
 * Constrói payload cirúrgico para atualização (reimportação) de um produto existente.
 * Atualiza APENAS campos presentes no CSV.
 * NUNCA envia arrays vazios de fotos ou variações para não sobrescrever dados existentes.
 * NUNCA sobrescreve estoque, ativo, fotos ou variações ausentes.
 */
export const buildUpdateProductPayload = (item, extraFields = {}) => {
  const payload = {};

  if (item.nome !== undefined && String(item.nome).trim()) {
    payload.nome = String(item.nome).trim();
  }

  if (item.modelo_referencia !== undefined) {
    payload.modelo_referencia = String(item.modelo_referencia || '').trim() || null;
  }

  if (item.categoria !== undefined && item.categoria) {
    payload.categoria = item.categoria;
  }

  if (item.ambiente !== undefined) {
    payload.ambiente = item.ambiente || null;
  }

  if (item.fornecedor_id !== undefined && item.fornecedor_id) {
    payload.fornecedor_id = item.fornecedor_id;
  }

  if (item.fornecedor_nome !== undefined) {
    payload.fornecedor_nome = item.fornecedor_nome || '';
  }

  if (item.preco_custo !== undefined && item.preco_custo !== '') {
    payload.preco_custo = Number(item.preco_custo);
  }

  if (item.preco_venda !== undefined && item.preco_venda !== '') {
    payload.preco_venda = Number(item.preco_venda);
  }

  if (item.largura !== undefined && item.largura !== '') {
    payload.largura = Number(item.largura);
  }

  if (item.altura !== undefined && item.altura !== '') {
    payload.altura = Number(item.altura);
  }

  if (item.profundidade !== undefined && item.profundidade !== '') {
    payload.profundidade = Number(item.profundidade);
  }

  if (item.material !== undefined) {
    payload.material = item.material || '';
  }

  if (item.cor !== undefined) {
    payload.cor = item.cor || '';
  }

  if (item.cor_hex !== undefined) {
    payload.cor_hex = item.cor_hex || null;
  }

  // Código de barras: se informado no CSV, normaliza e atualiza
  if (item.codigo_barras !== undefined) {
    payload.codigo_barras = normalizeGTIN(item.codigo_barras);
  }

  // Incorpora extras explícitos sanitizados
  Object.assign(payload, extraFields);

  return payload;
};

import { describe, it, expect } from 'vitest';
import {
  normalizeSkuForComparison,
  normalizeSkuForStorage,
  validateImportPlanilha,
  buildInsertProductPayload,
  buildUpdateProductPayload,
} from './importProdutosUtils';

describe('importProdutosUtils', () => {
  const orgIdA = '00000000-0000-0000-0000-000000000001';
  const orgIdB = '00000000-0000-0000-0000-000000000002';

  describe('normalizeSkuForComparison & normalizeSkuForStorage', () => {
    it('normalizes comparison case-insensitively and trims whitespace', () => {
      expect(normalizeSkuForComparison('  ABC-123.4/XY  ')).toBe('abc-123.4/xy');
    });

    it('preserves significant punctuation like /, ., _, - in storage', () => {
      expect(normalizeSkuForStorage('  ALT-001/BRANCO_1.2  ')).toBe('ALT-001/BRANCO_1.2');
    });

    it('does not append line numbers or suffixes to SKU', () => {
      expect(normalizeSkuForStorage('ABC123')).toBe('ABC123');
    });
  });

  describe('validateImportPlanilha', () => {
    it('identifies new products vs re-imports updating the same ID', () => {
      const produtosExistentes = [
        { id: 'uuid-1', sku: 'ABC-100', nome: 'Produto Existente', organization_id: orgIdA },
      ];

      const rows = [
        { linha: 1, sku: 'ABC-100', nome: 'Produto Atualizado' },
        { linha: 2, sku: 'XYZ-200', nome: 'Produto Novo' },
      ];

      const result = validateImportPlanilha({
        rows,
        produtosExistentes,
        organizationId: orgIdA,
      });

      expect(result.isValid).toBe(true);
      expect(result.novos).toHaveLength(1);
      expect(result.novos[0].sku).toBe('XYZ-200');

      expect(result.atualizacoes).toHaveLength(1);
      expect(result.atualizacoes[0].sku).toBe('ABC-100');
      expect(result.atualizacoes[0].id_existente).toBe('uuid-1');
    });

    it('blocks import when SKU is missing and reports the line numbers', () => {
      const rows = [
        { linha: 1, sku: 'SKU-OK', nome: 'Item 1' },
        { linha: 2, sku: '', nome: 'Item 2 Sem SKU' },
        { linha: 3, sku: null, nome: 'Item 3 Nulo' },
      ];

      const result = validateImportPlanilha({
        rows,
        produtosExistentes: [],
        organizationId: orgIdA,
      });

      expect(result.isValid).toBe(false);
      const skuErrors = result.errors.filter(e => e.tipo === 'SKU_OBRIGATORIO');
      expect(skuErrors).toHaveLength(2);
      expect(skuErrors.map(e => e.linha)).toEqual([2, 3]);
    });

    it('blocks import when same SKU appears multiple times in CSV and lists all conflicting lines', () => {
      const rows = [
        { linha: 1, sku: 'PROD-A', nome: 'Item Linha 1' },
        { linha: 5, sku: 'PROD-B', nome: 'Item Linha 5' },
        { linha: 12, sku: 'prod-a', nome: 'Item Linha 12 (Duplicado case-insensitive)' },
      ];

      const result = validateImportPlanilha({
        rows,
        produtosExistentes: [],
        organizationId: orgIdA,
      });

      expect(result.isValid).toBe(false);
      expect(result.skuDuplicates).toHaveLength(1);
      expect(result.skuDuplicates[0].linhas).toEqual([1, 12]);
    });

    it('permits same SKU in different organizations without conflict', () => {
      // Existente na Org B
      const produtosExistentesOrgB = [
        { id: 'uuid-b', sku: 'ABC-100', organization_id: orgIdB },
      ];

      // Importando na Org A (produtos existentes da Org A é vazio)
      const rows = [
        { linha: 1, sku: 'ABC-100', nome: 'Produto na Org A' },
      ];

      const result = validateImportPlanilha({
        rows,
        produtosExistentes: [], // Apenas produtos da Org A
        organizationId: orgIdA,
      });

      expect(result.isValid).toBe(true);
      expect(result.novos).toHaveLength(1);
      expect(result.novos[0].sku).toBe('ABC-100');
    });

    it('rejects invalid GTIN with clear error and preserves zeros when valid', () => {
      const rows = [
        { linha: 1, sku: 'SKU-1', codigo_barras: 'INVALID_EAN', nome: 'Item' },
        { linha: 2, sku: 'SKU-2', codigo_barras: '012000052309', nome: 'Item 2' }, // GTIN-12 com zero
      ];

      const result = validateImportPlanilha({
        rows,
        produtosExistentes: [],
        organizationId: orgIdA,
      });

      expect(result.isValid).toBe(false);
      const eanErrors = result.errors.filter(e => e.tipo === 'EAN_INVALIDO');
      expect(eanErrors).toHaveLength(1);
      expect(eanErrors[0].linha).toBe(1);

      // Linha 2 foi normalizada com zero preservado
      const item2 = result.novos.find(n => n.sku === 'SKU-2');
      expect(item2.codigo_barras).toBe('012000052309');
    });

    it('blocks import if the same EAN belongs to different SKUs in the same sheet', () => {
      const validEan = '7891000315507';
      const rows = [
        { linha: 1, sku: 'SKU-AAA', codigo_barras: validEan },
        { linha: 2, sku: 'SKU-BBB', codigo_barras: validEan },
      ];

      const result = validateImportPlanilha({
        rows,
        produtosExistentes: [],
        organizationId: orgIdA,
      });

      expect(result.isValid).toBe(false);
      const err = result.errors.find(e => e.tipo === 'EAN_DUPLICADO_ENTRE_SKUS');
      expect(err).toBeDefined();
    });

    it('blocks import if an EAN in CSV is already used by a different SKU in DB', () => {
      const validEan = '7891000315507';
      const produtosExistentes = [
        { id: 'id-1', sku: 'SKU-EXISTING', codigo_barras: validEan, organization_id: orgIdA },
      ];

      const rows = [
        { linha: 3, sku: 'SKU-NEW', codigo_barras: validEan },
      ];

      const result = validateImportPlanilha({
        rows,
        produtosExistentes,
        organizationId: orgIdA,
      });

      expect(result.isValid).toBe(false);
      const err = result.errors.find(e => e.tipo === 'EAN_JA_CADASTRADO_OUTRO_SKU');
      expect(err).toBeDefined();
      expect(err.linha).toBe(3);
    });

    it('blocks import when ID and SKU point to divergent products', () => {
      const produtosExistentes = [
        { id: 'uuid-real', sku: 'SKU-ORIGINAL', organization_id: orgIdA },
      ];

      const rows = [
        { linha: 4, id: 'uuid-real', sku: 'SKU-DIVERGENTE', nome: 'Divergente' },
      ];

      const result = validateImportPlanilha({
        rows,
        produtosExistentes,
        organizationId: orgIdA,
      });

      expect(result.isValid).toBe(false);
      const err = result.errors.find(e => e.tipo === 'CONFLITO_ID_SKU');
      expect(err).toBeDefined();
      expect(err.linha).toBe(4);
    });

    it('allows products without EAN (null barcode)', () => {
      const rows = [
        { linha: 1, sku: 'SKU-NO-EAN', codigo_barras: '', nome: 'Produto Sem EAN' },
        { linha: 2, sku: 'SKU-SEM-GTIN', codigo_barras: 'SEM GTIN', nome: 'Sem GTIN' },
      ];

      const result = validateImportPlanilha({
        rows,
        produtosExistentes: [],
        organizationId: orgIdA,
      });

      expect(result.isValid).toBe(true);
      expect(result.novos[0].codigo_barras).toBeNull();
      expect(result.novos[1].codigo_barras).toBeNull();
    });

    it('allows multiple variations without EAN', () => {
      const rows = [
        {
          linha: 1,
          sku: 'SOFA-MODULAR',
          cor: 'Cinza, Azul, Bege',
          modelos_tecidos: 'Suede, Linho',
          codigo_barras: '',
        },
      ];

      const result = validateImportPlanilha({
        rows,
        produtosExistentes: [],
        organizationId: orgIdA,
      });

      expect(result.isValid).toBe(true);
    });

    it('blocks a line with multiple variations having only one single EAN (ambiguity)', () => {
      const validEan = '7891000315507';
      const rows = [
        {
          linha: 7,
          sku: 'SOFA-VAR',
          cor: 'Preto, Branco',
          codigo_barras: validEan,
        },
      ];

      const result = validateImportPlanilha({
        rows,
        produtosExistentes: [],
        organizationId: orgIdA,
      });

      expect(result.isValid).toBe(false);
      const err = result.errors.find(e => e.tipo === 'EAN_AMBIGUO_VARIACOES');
      expect(err).toBeDefined();
      expect(err.linha).toBe(7);
    });

    it('never changes identity based on line number or order', () => {
      const rowA = { linha: 99, sku: 'SKU-STABLE', codigo_barras: '7891000315507' };
      const rowB = { linha: 1, sku: 'SKU-STABLE', codigo_barras: '7891000315507' };

      const resA = validateImportPlanilha({ rows: [rowA], organizationId: orgIdA });
      const resB = validateImportPlanilha({ rows: [rowB], organizationId: orgIdA });

      expect(resA.novos[0].sku).toBe(resB.novos[0].sku);
      expect(resA.novos[0].codigo_barras).toBe(resB.novos[0].codigo_barras);
    });
  });

  describe('buildInsertProductPayload and buildUpdateProductPayload', () => {
    it('creates full insert payload with safe defaults', () => {
      const row = {
        sku: 'ALT-100',
        codigo_barras: '7891000315507',
        nome: 'Mesa de Jantar',
        modelo_referencia: 'MJ-01',
        preco_custo: 200,
        preco_venda: 450,
      };

      const payload = buildInsertProductPayload(row, orgIdA);

      expect(payload.sku).toBe('ALT-100');
      expect(payload.codigo_barras).toBe('7891000315507');
      expect(payload.organization_id).toBe(orgIdA);
      expect(payload.ativo).toBe(true);
      expect(payload.quantidade_estoque).toBe(0);
      expect(payload.modelo_referencia).toBe('MJ-01'); // Without line suffix!
    });

    it('creates partial update payload preserving photos, variations and stock', () => {
      const row = {
        sku: 'ALT-100',
        nome: 'Mesa Atualizada',
        preco_venda: 499.90,
      };

      const payload = buildUpdateProductPayload(row);

      expect(payload.nome).toBe('Mesa Atualizada');
      expect(payload.preco_venda).toBe(499.90);
      // Ensure missing fields are not sent as empty arrays or reset
      expect(payload).not.toHaveProperty('fotos');
      expect(payload).not.toHaveProperty('variacoes');
      expect(payload).not.toHaveProperty('ativo');
      expect(payload).not.toHaveProperty('quantidade_estoque');
      expect(payload).not.toHaveProperty('parent_id');
    });
  });
});

// src/utils/markupCalculator.js

/**
 * Default margin targets per category (percentage as decimal).
 */
export function getMarginTarget(category) {
    const defaults = {
        Sofa: 0.30,
        Cama: 0.25,
        Mesa: 0.28,
        Cadeira: 0.27,
        Armario: 0.32,
        Estante: 0.30,
        Rack: 0.30,
        Poltrona: 0.30,
        Escrivaninha: 0.28,
        "Criado-mudo": 0.25,
        Buffet: 0.27,
        Aparador: 0.26,
        Banco: 0.24,
        Colchao: 0.30,
        "Guarda-roupa": 0.33,
        Comoda: 0.28,
        Painel: 0.30,
        Travesseiro: 0.25,
        Almofada: 0.25,
        Decoracao: 0.25,
        Utensilios: 0.25,
        Outros: 0.25,
    };
    return defaults[category] ?? 0.25;
}

/**
 * Supplier reliability factor. Placeholder logic: even IDs are trusted.
 */
export function getSupplierFactor(supplierId) {
    if (!supplierId) return 1.0;
    return supplierId % 2 === 0 ? 0.95 : 1.05;
}

/**
 * Adjusts margin based on stock levels (Scarcity vs Excess).
 */
export function getStockAdjustment(product) {
    const { quantidade_estoque = 0, estoque_minimo = 0 } = product;

    // If no minimum stock defined, assume neutral
    if (!estoque_minimo) return 1.0;

    const estoque = parseInt(quantidade_estoque);
    const min = parseInt(estoque_minimo);

    // Scarcity: Stock below minimum -> Increase price to slow sales/maximize profit
    if (estoque < min) {
        // Linear increase up to 10% when stock is near 0
        const shortageRatio = (min - estoque) / min; // 0 to 1
        return 1.0 + Math.min(shortageRatio * 0.10, 0.10);
    }

    // Excess: Stock way above minimum (> 3x) -> Decrease price to clear inventory
    if (estoque > min * 3) {
        // Small discount of 5% to encourage sales
        return 0.95;
    }

    // Normal stock levels
    return 1.0;
}

/**
 * Simplified tax rate (e.g., ICMS 18%).
 */
export function getTaxRate(_product) {
    return 0.18;
}

/**
 * Main function to calculate suggested selling price.
 */
export function calculateSuggestedMarkup(product) {
    const custo = parseFloat(product.preco_custo || 0);
    if (custo <= 0) return 0;

    const multiplierFromProduct = parseFloat(product.markup_multiplicador || 0);
    if (multiplierFromProduct > 0) {
        return Math.round(custo * multiplierFromProduct * 100) / 100;
    }

    const percentFromProduct = parseFloat(product.markup_percentual || 0);
    if (percentFromProduct > 0) {
        return Math.round(custo * (1 + (percentFromProduct / 100)) * 100) / 100;
    }

    const categoria = product.categoria;

    // 1. Base margin target
    const margemAlvo = getMarginTarget(categoria);
    let markup = custo * (1 + margemAlvo);

    // 2. Stock/Market Adjustment
    // Replaced "DemandFactor" with more specific StockAdjustment
    markup *= getStockAdjustment(product);

    // 3. Tax
    markup *= 1 + getTaxRate(product);

    // 4. Round to two decimals
    return Math.round(markup * 100) / 100;
}

/**
 * Returns detailed breakdown of markup calculation for transparency.
 */
export function calculateMarkupDetails(product) {
    const custo = parseFloat(product.preco_custo || 0);
    if (custo <= 0) {
        return null;
    }

    const multiplierFromProduct = parseFloat(product.markup_multiplicador || 0);
    if (multiplierFromProduct > 0) {
        const precoFinalMultiplicador = custo * multiplierFromProduct;
        return {
            custo,
            categoria: product.categoria || 'Outros',
            steps: [
                {
                    label: 'Markup Definido',
                    factor: `${multiplierFromProduct.toFixed(2)}x`,
                    value: Math.round(precoFinalMultiplicador * 100) / 100,
                    description: `R$ ${custo.toFixed(2)} × ${multiplierFromProduct.toFixed(2)}`
                }
            ],
            precoFinal: Math.round(precoFinalMultiplicador * 100) / 100
        };
    }

    const percentFromProduct = parseFloat(product.markup_percentual || 0);
    if (percentFromProduct > 0) {
        const multiplier = 1 + (percentFromProduct / 100);
        const precoFinalPercentual = custo * multiplier;
        return {
            custo,
            categoria: product.categoria || 'Outros',
            steps: [
                {
                    label: 'Markup Definido',
                    factor: `+${percentFromProduct.toFixed(2)}%`,
                    value: Math.round(precoFinalPercentual * 100) / 100,
                    description: `R$ ${custo.toFixed(2)} × ${multiplier.toFixed(4)}`
                }
            ],
            precoFinal: Math.round(precoFinalPercentual * 100) / 100
        };
    }

    const categoria = product.categoria || 'Outros';

    // Step 1: Base margin
    const margemAlvo = getMarginTarget(categoria);
    const margemPercent = Math.round(margemAlvo * 100);
    const precoComMargem = custo * (1 + margemAlvo);

    // Step 2: Stock Adjustment
    const stockFactor = getStockAdjustment(product);
    let stockLabel = 'Estoque Normal';
    let stockFactorLabel = '0%';

    if (stockFactor > 1) {
        stockLabel = 'Escassez (Baixo Estoque)';
        stockFactorLabel = `+${Math.round((stockFactor - 1) * 100)}%`;
    } else if (stockFactor < 1) {
        stockLabel = 'Excesso de Estoque';
        stockFactorLabel = `${Math.round((stockFactor - 1) * 100)}%`;
    }

    const precoComEstoque = precoComMargem * stockFactor;

    // Step 3: Tax
    const taxRate = getTaxRate(product);
    const taxPercent = Math.round(taxRate * 100);
    const precoFinal = precoComEstoque * (1 + taxRate);

    return {
        custo,
        categoria,
        steps: [
            {
                label: `Margem ${categoria}`,
                factor: `+${margemPercent}%`,
                value: Math.round(precoComMargem * 100) / 100,
                description: `R$ ${custo.toFixed(2)} × ${(1 + margemAlvo).toFixed(2)}`
            },
            {
                label: stockLabel,
                factor: stockFactorLabel,
                value: Math.round(precoComEstoque * 100) / 100,
                description: stockFactor === 1 ? 'Sem ajuste' : (stockFactor > 1 ? 'Aumento por escassez' : 'Desconto por excesso')
            },
            {
                label: `Impostos (Estimado)`,
                factor: `+${taxPercent}%`,
                value: Math.round(precoFinal * 100) / 100,
                description: `ICMS ~${taxPercent}%`
            }
        ],
        precoFinal: Math.round(precoFinal * 100) / 100
    };
}

/**
 * Normaliza um valor percentual para fração decimal.
 * - Se contém "%" no texto original, o parseFloat já ignora, mas o valor inteiro (ex: 10) precisa ser dividido por 100.
 * - Valores > 1 são tratados como percentuais inteiros (ex: 10 → 0.10, 12 → 0.12).
 * - Valores <= 1 são tratados como já em fração decimal (ex: 0.10 → 0.10).
 */
function normalizePercent(val) {
    const num = parseFloat(val || 0);
    if (isNaN(num)) return 0;
    return num > 1 ? num / 100 : num;
}

export function toPercentFromMultiplier(multiplier) {
    const numericMultiplier = parseFloat(multiplier || 0);
    if (!numericMultiplier || numericMultiplier <= 0) return 0;
    return Math.round((numericMultiplier - 1) * 10000) / 100;
}

export function toMultiplierFromPercent(percent) {
    const numericPercent = parseFloat(percent || 0);
    if (isNaN(numericPercent)) return 1;
    return Math.round((1 + (numericPercent / 100)) * 10000) / 10000;
}

export function calculateFinalPriceFromMarkup(custo, markupMultiplicador, markupPercentual) {
    const custoNumerico = parseFloat(custo || 0);
    if (custoNumerico <= 0) return 0;

    const multiplicador = parseFloat(markupMultiplicador || 0);
    if (multiplicador > 0) {
        return Math.round(custoNumerico * multiplicador * 100) / 100;
    }

    const percentual = parseFloat(markupPercentual || 0);
    if (percentual > 0) {
        return Math.round(custoNumerico * (1 + (percentual / 100)) * 100) / 100;
    }

    return 0;
}

/**
 * Calcula o preço final de venda usando a fórmula da planilha:
 * =ARREDONDAR.PARA.CIMA(custo × (1+frete%) × (1+IPI%) × (1+grupo%) × markup, 0)
 *
 * - Frete, IPI e Grupo são percentuais (10,00% = 0.10)
 * - Markup é multiplicador direto (ex: 2.70)
 *
 * @param {Object} produto - Dados do produto com campos de custeio
 * @returns {number} Preço final arredondado para cima (inteiro)
 */
export function calcularPrecoFinalImportacao(produto) {
    const custo = parseFloat(produto.preco_custo || 0);
    if (custo <= 0) return 0;

    const frete = normalizePercent(produto.frete_custo);
    const ipi = normalizePercent(produto.ipi_percentual);

    // Usa o grupo de markup ativo (prioridade: grupo preenchido)
    const grupoVal = produto.markup_grupo2_montagem ||
        produto.markup_grupo1_prontos ||
        produto.markup_grupo3_lustre || 0;
    const grupo = normalizePercent(grupoVal);

    // Markup é multiplicador direto (ex: 2.70)
    const markup = parseFloat(produto.markup_aplicado || 0);
    if (markup <= 0) return 0;

    const resultado = custo * (1 + frete) * (1 + ipi) * (1 + grupo) * markup;
    return Math.ceil(resultado); // ARREDONDAR.PARA.CIMA(..., 0)
}

import { format } from "date-fns";
import { buildProductDisplayName, formatProductItemName } from "@/utils/productReference";

/**
 * Monta a linha de exibição de um item da OC no texto operacional.
 * Usa nome_completo_produto (que já vem consolidado com Ref, Medidas e Material).
 * Inclui cor específica do item (cor_item) para precisão máxima.
 * Garante que o fornecedor saiba EXATAMENTE qual item é.
 * @param {Object} item
 * @param {number} index
 * @returns {string}
 */
export function formatarLinhaItemOc(item, index) {
  const nome = formatProductItemName(item);
  const cor = item.cor_item || item.cor || null;
  const qtd = Number(item.quantidade_pedida || 0);
  const qtdFormatada = new Intl.NumberFormat('pt-BR', {
    minimumFractionDigits: Number.isInteger(qtd) ? 0 : 2,
    maximumFractionDigits: 2,
  }).format(qtd);

  const partes = [nome];
  if (cor) partes.push(cor);

  const precoCusto = Number(item.preco_custo_item || 0);

  return `${index + 1}. ${partes.join(' - ')},  Qtd: ${qtdFormatada}, Custo: R$ ${precoCusto.toFixed(2)}`;
}

/**
 * Monta o bloco de informações de assistência de um item, quando aplicável.
 * @param {Object} item
 * @returns {string|null} Bloco formatado ou null quando tipo for ordem comum.
 */
export function formatarBlocoAssistenciaItem(item) {
  if (!item.tipo_item_oc || item.tipo_item_oc === 'ORDEM_COMUM_ENCOMENDA') return null;

  const linhas = [];
  linhas.push(`Assistência do Ped. ${item.pedido_origem_numero || 'N/I'}`);
  linhas.push(`É reposição pela fábrica? ${item.reposicao_fabrica ? 'SIM' : 'NÃO'}`);
  if (item.motivo_assistencia) {
    linhas.push(`Motivo da assistência: ${item.motivo_assistencia}`);
  }
  linhas.push(`Imagens e Vídeos? ${item.possui_imagens_videos ? 'Sim' : 'Não'}`);
  if (item.anexos_item && item.anexos_item.length > 0) {
    const nomes = item.anexos_item.map(a => a.nome || a.url || 'anexo').join(', ');
    linhas.push(`Anexo: ${nomes}`);
  }
  return linhas.join('\n');
}

/**
 * Gera o texto operacional do pedido para cópia/envio ao fornecedor.
 * Formato profissional com saudação, dados completos da OC e assinatura.
 * @param {Object} oc  - Objeto OC com fornecedor_nome, numero_pedido, created_at/data_pedido, metadata
 * @param {Array}  itens - Array de itens da OC
 * @param {Object} user - Usuário logado { nome, nome_usuario, id, ... }
 * @param {string} lojaName - Nome da loja/empresa (vem das configurações, nunca deixar vazio)
 * @returns {string}
 */
export function gerarTextoPedidoOperacional(oc, itens = [], user = {}, lojaName = '') {
  const rawDate = oc.created_at || oc.data_pedido;
  const dataFormatada = rawDate
    ? new Date(rawDate.includes('T') ? rawDate : rawDate + 'T12:00:00').toLocaleDateString('pt-BR')
    : new Date().toLocaleDateString('pt-BR');

  const metadata = oc.metadata || {};
  const vendedorNome = metadata.vendedor_nome || user.nome || user.nome_usuario || 'Não informado';
  const ocNumero = oc.numero_pedido || 'Sem número';
  const refPedido = metadata.pedido_origem_numero || metadata.origem || '';
  const marca = metadata.marca || 'N/I';

  const linhas = [];

  // Cabeçalho com nome da loja (sempre validado pelas chamadas de componentes)
  const nomeEmpresa = lojaName || 'Empresa';
  linhas.push(`Segue encomenda da loja *${nomeEmpresa}*:\n`);

  // Linha do pedido OC com referências
  let linhaOc = `Pedido OC-${ocNumero}`;
  if (refPedido) {
    linhaOc += `, (ref. ao pedido ${refPedido})`;
  }
  linhaOc += `, vend. ${vendedorNome} - ${marca}`;
  linhas.push(linhaOc);
  linhas.push('');

  // Produtos
  linhas.push('Produto:');
  linhas.push('');

  if (itens.length > 0) {
    itens.forEach((item, index) => {
      linhas.push(`- ${formatarLinhaItemOc(item, index)}`);
    });
  } else {
    linhas.push('(Sem itens cadastrados)');
  }

  linhas.push('');
  linhas.push('POR GENTILEZA, ENVIAR CÓPIA DO PEDIDO');
  linhas.push('');
  linhas.push('ATENCIOSAMENTE,');
  linhas.push('');
  linhas.push(vendedorNome);
  linhas.push('Departamento de Compras');
  linhas.push(nomeEmpresa);

  return linhas.join('\n');
}

/**
 * Generates a formatted, WhatsApp-ready text block for a purchase order.
 * @param {Object} pedidoData  - The order object, must include: numero_pedido, data_pedido,
 *                               fornecedor_id, fornecedor_nome, itens[], valor_total,
 *                               data_previsao_entrega, condicoes_pagamento, observacoes,
 *                               tipo_preco, promocao_observacao, economia_total, valor_frete, valor_desconto
 * @param {Array}  fornecedores - The full list of supplier objects for phone/email lookup.
 * @returns {string}
 */
export function gerarTextoPedido(pedidoData, fornecedores = []) {
    const fornecedor = fornecedores.find(f => f.id === pedidoData.fornecedor_id);
    const parseDateSafe = (d) => {
        if (!d) return null;
        if (typeof d === 'string') {
            return new Date(d.includes('T') ? d : d + 'T12:00:00');
        }
        return new Date(d);
    };
    const dataFormatada = pedidoData.data_pedido
        ? format(parseDateSafe(pedidoData.data_pedido), 'dd/MM/yyyy')
        : 'Não informada';
    const previsaoFormatada = pedidoData.data_previsao_entrega
        ? format(parseDateSafe(pedidoData.data_previsao_entrega), 'dd/MM/yyyy')
        : 'A combinar';

    let texto = `*PEDIDO DE COMPRA*\n`;
    texto += `Nº: ${pedidoData.numero_pedido || 'Novo'}\n`;
    texto += `Data: ${dataFormatada}\n\n`;

    texto += `*FORNECEDOR:*\n`;
    texto += `${pedidoData.fornecedor_nome || fornecedor?.nome_empresa || 'Desconhecido'}\n`;
    if (fornecedor?.telefone) texto += `Tel: ${fornecedor.telefone}\n`;
    if (fornecedor?.email) texto += `Email: ${fornecedor.email}\n`;
    texto += `\n`;

    texto += `*ITENS DO PEDIDO:*\n`;
    texto += `━━━━━━━━━━━━━━━━━━━━━━\n`;

    (pedidoData.itens || []).forEach((item, index) => {
        const total = (item.quantidade_pedida || 0) * (item.preco_unitario || 0);
      texto += `${index + 1}. ${buildProductDisplayName(item.produto_nome, item.modelo_referencia)}\n`;
        texto += `   Qtd: ${item.quantidade_pedida} | R$ ${(item.preco_unitario || 0).toFixed(2)} = R$ ${total.toFixed(2)}\n`;
    });

    texto += `━━━━━━━━━━━━━━━━━━━━━━\n`;

    if (pedidoData.valor_frete > 0) {
        texto += `Frete: R$ ${pedidoData.valor_frete.toFixed(2)}\n`;
    }
    if (pedidoData.valor_desconto > 0) {
        texto += `Desconto: R$ ${pedidoData.valor_desconto.toFixed(2)}\n`;
    }

    texto += `*TOTAL: R$ ${(pedidoData.valor_total || 0).toFixed(2)}*\n\n`;

    if (pedidoData.tipo_preco === 'promocional') {
        texto += `🏷️ *Preço Promocional*\n`;
        if (pedidoData.promocao_observacao) texto += `   ${pedidoData.promocao_observacao}\n`;
        texto += `   Economia: R$ ${(pedidoData.economia_total || 0).toFixed(2)}\n\n`;
    }

    texto += `*Previsão de Entrega:* ${previsaoFormatada}\n`;
    if (pedidoData.condicoes_pagamento) {
        texto += `*Pagamento:* ${pedidoData.condicoes_pagamento}\n`;
    }

    if (pedidoData.observacoes) {
        texto += `\n*Observações:*\n${pedidoData.observacoes}\n`;
    }

    texto += `\n---\n_Gestão de Compras_`;

    return texto;
}

/**
 * Calculates the completeness score of a product registration.
 * Returns a score (0-100), a level ('low', 'medium', 'high'), and missing fields.
 * 
 * Criteria:
 * - Green (High - 100%): Nome, EAN, Cor (if variation), Dims (H/W/D), NCM, Stock.
 * - Yellow (Medium - 50-80%): Basic info present, but missing Dims, Weight, or NCM.
 * - Red (Low - <50%): Only Name/Barcode present.
 */
export const calculateProductScore = (produto) => {
    if (!produto) return { score: 0, level: 'low', missing: [] };

    let score = 0;
    const missing = [];
    const totalWeights = {
        identity: 30, // Name, EAN, SKU
        specs: 30,    // Dimensions, Color, Material
        fiscal: 20,   // NCM, Origin
        logistic: 20  // Weight, Volumes, Stock
    };

    // 1. Identity Check
    if (produto.nome?.length > 3) score += 10;
    else missing.push('Nome');

    if (produto.codigo_barras?.length > 0) score += 10;
    else missing.push('EAN (Código de Barras)');

    // SKU is often auto-generated, checking if it exists
    if (produto.codigo_barras || produto.sku) score += 10;

    // 2. Specs Check
    const hasDims = produto.altura > 0 && produto.largura > 0 && produto.profundidade > 0;
    if (hasDims) score += 15;
    else missing.push('Dimensões (A/L/P)');

    // Color check: If it's a variation (parent_id) or has variations, color is crucial.
    // For standalone, it's good to have but maybe not mandatory if it's "Única".
    // We'll enforce it for score quality.
    if (produto.cor && produto.cor !== 'PADRAO') score += 10;
    else missing.push('Cor');

    if (produto.material) score += 5;

    // 3. Fiscal Check
    if (produto.ncm?.length >= 8) score += 15;
    else missing.push('NCM');

    if (produto.origem_mercadoria) score += 5;

    // 4. Logistic Check
    if (parseFloat(produto.peso_bruto) > 0) score += 10;
    else missing.push('Peso Bruto');

    if (parseInt(produto.volumes) > 0) score += 5;
    else missing.push('Volumes');

    // Stock check (not strict for registration quality, but good for "Active" status)
    if (produto.quantidade_estoque >= 0) score += 5;

    // Determine Level
    let level = 'low';
    if (score >= 90) level = 'high';
    else if (score >= 50) level = 'medium';

    return { score, level, missing };
};

export const getColorForScore = (level) => {
    switch (level) {
        case 'high': return 'bg-green-100 text-green-800 border-green-200';
        case 'medium': return 'bg-yellow-100 text-yellow-800 border-yellow-200';
        case 'low': return 'bg-red-100 text-red-800 border-red-200';
        default: return 'bg-gray-100 text-gray-800';
    }
};
